INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin varmı?', 'haberin-varmi-erhan-saka-d4ztj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana soruyorum geçen yılları, 

Aşkımız nerede haberin varmı, 

Yeşilken kuruttun sen umutları, 

Mutluluk aradım haberin varmı.

Artık kendim için yaşayacağım, 

Sahte sevgililere kanmayacağım, 

Her şeye yeniden başlayacağım, 

Hayata küsmüşüm haberin varmı.

Bir daha karşıma çıkma yeterki, 

Senden başkasını severim belki, 

Olmuyor seninle, gitmen gerekli, 

Yatağa düşmüşüm haberin varmı.', 'Sana soruyorum geçen yılları,  Aşkımız nerede haberin varmı,  Yeşilken kuruttun sen umutları,  Mutluluk aradım haberin varmı. Artık kendim i...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haberin-varmi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep seveceğim', 'hep-sevecegim-erhan-saka-qz26w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akmasın gözünden yaşlar kıyamam, 

Ayrılsak seninle mutlu olamam, 

Madem gideceksin suçlu aramam, 

Ben seni uzaktan hep seveceğim.

Sevmeye doymadım sevgilim seni, 

Bilirim gidersen dönmezsin geri, 

Yüzünü görmesem olurum deli, 

Ben seni uzaktan hep seveceğim.

Mutluluk süslesin güzel yüzünü, 

Göklerde ararım mavi gözünü, 

Tutmaya mecburum sana sözümü, 

Ben seni uzaktan hep seveceğim.', 'Akmasın gözünden yaşlar kıyamam,  Ayrılsak seninle mutlu olamam,  Madem gideceksin suçlu aramam,  Ben seni uzaktan hep seveceğim. Sevmeye do...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hep-sevecegim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm yetmiyor', 'omrum-yetmiyor-erhan-saka-80fps', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç bahar sensiz geçti saymadım, 

Aşkın bu bedende hala yaşıyor.

Senden sonra inan ki ben sevemedim, 

Seni unutmaya ömrüm yetmiyor.

Unuturum diyerek yaktım mektupları, 

Aklıma gelir diye anılarını, 

Yakamadım sokak lambalarını, 

 Seni unutmaya ömrüm yetmiyor

Terkettim beraber gittiğimiz yerleri, 

Şimdi çok yalnızım içim yanıyor.

Oysa ki yırtmıştım o resimleri, 

Seni unutmaya ömrüm yetmiyor', 'Kaç bahar sensiz geçti saymadım,  Aşkın bu bedende hala yaşıyor. Senden sonra inan ki ben sevemedim,  Seni unutmaya ömrüm yetmiyor. Unuturum...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/omrum-yetmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilemezsin', 'sen-bilemezsin-erhan-saka-3xixz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sağanaklar beni sarar götürür, 

Sarar benliğimi sen bilemezsin.

Yokluğun içime ateş düşürür

Yanar tutuşurum söndüremezsin.

Sahilde sulara adını yazdım, 

Bakmaya doyamam sen göremezsin.

Aşkını kalbime sevginle kazdım, 

Yaşlı gözlerimi sen silemezsin.

Her akşam kadehe seni sorarım, 

Yanımda değilsin sen göremezsin.

Kendimi kaybeder seni ararım, 

Tanınmaz haldeyim sen bilemezsin.', 'Sağanaklar beni sarar götürür,  Sarar benliğimi sen bilemezsin. Yokluğun içime ateş düşürür Yanar tutuşurum söndüremezsin. Sahilde sulara ad...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-bilemezsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Arzu', 'bir-arzu-garip-teymur-o4y8o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Didinsem

Uyumasam hiçbir zaman 

Yorgun akşamlarda 

Senin için şiir yazsam

Gözlerinin içine dalsam

Uyumasam

Hep seninle kalsam

Keşke

Hep yanında olsam...', 'Didinsem Uyumasam hiçbir zaman  Yorgun akşamlarda  Senin için şiir yazsam Gözlerinin içine dalsam Uyumasam Hep seninle kalsam Keşke Hep yanı...', ARRAY['Türk Edebiyatı','Şiir','Garip Teymur']::text[], 8.5, '{"poet":"Garip Teymur","poet_slug":"garip-teymur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-arzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erdal-ı Erda', 'erdal-i-erda-refik-recep-pelit-juuay', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erdal-ı Erda       

Ey ıraklara meyl eden dost-u maşukum, 

Biz kuru lafza değil suret-i asla bakarız

Beygare sözü bırak, meylet bir gönlümüze, 

Cümle-i sahtevekar''a değil samim söze aşığız.

Boşuna temayül etme beyhude serzenişlere, 

Kalb-i cemalinin, secere-i bidayetini tanırız, 

Sır ile terki diyar eyleyen, ey yaren-i cevherim

Biz ezelden beridir muhabbete iştiyak ile bağlıyız.

Fikri amiyanına bir kez dönüp''te baksaydın, 

Dost muhabbetinde meclis-i efruz olurdun, 

Ainesi iştir kişinin malum, laflarına nazar edilmez 

Ey erdal-ı erda, beyhude sözleri biz evvelden tanırız.

Not: 

bazı kelimelerin anlamları 

Erdal: Yeşermiş Dal 

Erda: ağaç kurdu

Maşuk: Sevilen, sevgili

Beygare:azarlama, serzeniş

Sahtevekar:yapmacık tavırlar takınan, kendini satmaya çalışan

Bidayet:Evveliyat, ilk 

İştiyak: Fazla arzu ve şevk. Tahassür. Hasret çekmek

Amiyane:Bayağıca. Cahillere yakışır surette.

Meclis-i efruz: Topluluğu aydınlatan, ışık saçan', 'Erdal-ı Erda        Ey ıraklara meyl eden dost-u maşukum,  Biz kuru lafza değil suret-i asla bakarız Beygare sözü bırak, meylet bir gönlümüz...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/erdal-i-erda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Bir daha Asla', 'bizi-bir-daha-asla-sevgi-karadeniz-ssfwz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz birbirimizi bulduğumuzda

Kurumuş çatlamıştı topraklarımız

Sanki bir daha hiç bir tohumu

Yeşertemiyecek kadar kısırlaşmıştk

Hatırlıyorum

Onca uzun yollardan belimiz bükülerek

Ne sular taşıdık 

Avuçlarımızı kanata kanata

Ne gübreler döşedik toprağmıza

Yorgunluğun getirdiği ağrılar ile

Ne geceleri sabahladık uykusuz

En zoruda

Dışarıdan gelen haşerelerdi

Kaç böcek yarasının acılarında inledik

Kaç kez ilaç zehirlenmelerinde

Ölümden döndük

Ama sonunda

Öyle filizlendik ki

Bir ömür boyu suyumuzu kesseler

Bir yaprağmızı bile sarartamazlar

Umulmaz korkunçlukta

Kasırgalar estirselerde 

Bizi bir daha asla sarsamazlar bile', 'Biz birbirimizi bulduğumuzda Kurumuş çatlamıştı topraklarımız Sanki bir daha hiç bir tohumu Yeşertemiyecek kadar kısırlaşmıştk Hatırlıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Sevgi Karadeniz']::text[], 8.5, '{"poet":"Sevgi Karadeniz","poet_slug":"sevgi-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bizi-bir-daha-asla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcağım', 'sicagim-cemal-karsavran-apcqh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'güle yeşermez toprak 

gül yeterki toprağa 

emek ver 

kazma ol kürek ol 

bahar ol yağmurlarla 

yelken ol yürek ol 

sende gel umutlarla sevdama 

gülen yüzün gözlerinle 

o tatlı dillerinle 

zeytin gözlerini 

çiğdem moru dudaklarını 

dalga dalga saçlarını rüzgarla 

seni özlerim 

silme yüreğinden 

döner yüreğim yüreğine 

gölgem gölgene 

umudumda umutlara 

dilden akan bala değil 

dudaktan dökülen kelimeyle 

gel de gayrı gel 

gelemezsem yollar uzak bilesin

düşlerimde taşırım 

kordan bir tuzak 

güne dönen geceye 

yüreğimin sustuğu her akşam 

güller naz edende 

sevdamın dönüşü ah edende 

sen benim gönlümdesin yüreğimde 

düşürmem sevdanı dilimden 

akdenizlim  seninim

sıcağım', 'güle yeşermez toprak  gül yeterki toprağa  emek ver  kazma ol kürek ol  bahar ol yağmurlarla  yelken ol yürek ol  sende gel umutlarla sevdam...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sicagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatsız Güvercinim Şimdi', 'kanatsiz-guvercinim-simdi-cemal-karsavran-9rr5q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerim dalar bakışlarımda kaybolurum 

bir gemi gecer okyanustur cok zaman 

cennetten yeni dünya senden bana kalan 

hatıralar sararmadan dur gitme dayanamam 

yangın yeri gözlerim boşalır kara bulutlardan özlemin ağlar

yalnızlığı reva sanma kendine ve bana 

katlanamam hasretine duman olurum 

henüz yeni sayılır kaç gün dayanırım 

mavidir suların ılık meltemdir eser başımda 

kaybolurum bulduğum yer gelir aklıma 

debelenip durduğum dört duvar arasında 

tam kurtuldum derken gene aldı yanına 

sığınmam sığınamam senden başka birine 

verselerde cennetten bir köşe hurileriyle 

sana ait olanı veremem vermem başkasına 

kırılsada kanadım yenilenirim seninle 

sanma rahatım batar yaradır ayrılık

umutluyum döneceksin sende sevdin 

tutacağız bu engelli yollarda ellerimizden 

ben özür diledim yaradan adına senden

çok sevdim kıskandım varlığımdan ötürü 

deli oldum sevda dedikleri dipsiz kuyuda 

aşkım sevgilim yüreğimdeki çocuğum 

kırdım kırıldım kanatsız güvercinim şimdi', 'gözlerim dalar bakışlarımda kaybolurum  bir gemi gecer okyanustur cok zaman  cennetten yeni dünya senden bana kalan  hatıralar sararmadan du...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kanatsiz-guvercinim-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemiyorum*', 'sevemiyorum-guven-aktas-xcydg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık bu saatten sonra, 

Sana bir şey diyemiyorum, 

Ne sevgilim, nede bir başka cümleyi, 

Senin için kuramıyorum..

Yansada deli gibi yüreğim, 

Sana sevgilim diyemiyorum..

Göremiyorum rüyalarımda artık seni, 

Senden başkasını sevemiyorum…

Günlerim zindan olmuş, ben mahkum, 

Sana sevgilim diyemiyorum…

Yıkılmış ümitlerim, tükenmiş çarelerim, 

Seni bir  başkasıyla düşünemiyorum….

Ölümüne bağlanmışım senin aşkına, 

Hasrete yol almış kervanler gibi, 

Yürüyorum susuz çöllerdeyim, 

Artık sana sevgilim diyemiyorum….

Bilmiyorum nasıl yıllarım sensiz gececek, 

Senden sonra hiç kimseyi sevemiyorum, 

Yarınlarım kaybolmuş, içlerinde bende varım, 

Sensiz yaşayacağımı sanmıyorum….', 'Artık bu saatten sonra,  Sana bir şey diyemiyorum,  Ne sevgilim, nede bir başka cümleyi,  Senin için kuramıyorum.. Yansada deli gibi yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevemiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtuluşum için söküp atın yüreğimi*', 'kurtulusum-icin-sokup-atin-yuregimi-guven-aktas-vlcac', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kanadından yara almış bir martı gibi, 

Tünemişim pencerene, ölümü bekliyorum, 

Acıp pencereni alma sakın içeri beni, 

Ellerinde can vermek istemiyorum, 

Alıp basımı uzaklara gideceğim, 

Kimsenin görmediği bir  yere çökeceğim, 

Cebimden cıkarıp son sigaramdan, 

Hayalinle karışık derin bir nefes çekeceğim.

Bu benim sizlerden son  isteğim, 

Ne bir teselli ne de acınmak isterim, 

Böyle olmasını bende istemedim, 

Caresizce ölümü bekleyecegim, 

Doktor getirmeyin bilmez derdimi, 

Yaram dısarda degil ki, 

En iyi cerrah bile çözemez içimi, 

Kurtulmam için söküp atmalılar yüreğimi,', 'Kanadından yara almış bir martı gibi,  Tünemişim pencerene, ölümü bekliyorum,  Acıp pencereni alma sakın içeri beni,  Ellerinde can vermek i...', ARRAY['Türk Edebiyatı','Şiir','Güven Aktaş']::text[], 8.5, '{"poet":"Güven Aktaş","poet_slug":"guven-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kurtulusum-icin-sokup-atin-yuregimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta Dedi Ki', 'usta-dedi-ki-cemal-karsavran-kjsgp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'toprak susuz 

toprak kıraç 

toprak taş 

ekmek arpa 

ekmek çavdar 

ekmek mısır 

yatak dam(ahır)

bir göz oda 

ve koyun koyuna 

bir köşede bağlı inek buzağısıyla 

anadoluda bir kasaba 

kışlar kış 

ayaz, yaz kadar yakıcı 

yazlar sıcak 

iki yanı keskin bıçak 

çatlayan toprak 

çavdar tarlası 

sancılı bir bahar 

patika yol 

ve sancılı bir doğum 

usta dedi ki 

allah rızkını verir 

höllük bez 

ısıt ısıt koy 

e bebeğim e 

tahta beşik 

salla yavrum ağlamasın 

umuda yolculuk 

yağmura dua 

bir hafta 

kırk gün 

güneş kavur kavur kavururken toprağı 

gölgede bebek 

temmuzun onbeşinde 

kara sinekler gözlerde 

oğul verir. 

nasırlı eller 

altın sarısı çavdarda 

çatlamış dudaklar suya hasret 

usta dedi ki 

bu yılda bitiğiz 

umut gelecek yıla 

baba çoban 

anne ırgat 

otlaklar taş 

tarlalar kocabaş 

eller kan içinde 

yalın ayak yarı çıplak 

ho der babam 

o köy senin bu köy benim 

bir sığır çobanı 

bir koyun çobanı 

yarı hak verilir yarı verilmez 

yollar yokuş 

üç yıl 

beş yıl 

karın tokluğuna 

çocuklar amele 

çocuklar okulsuz 

okuyupta muallimmi olacaklar 

usta dedi ki 

okursalar.. 

kim güder sığırları 

ırgata kim gider 

yıllar yıllar içinde 

birbirini aratır 

anne yorgun 

baba bitkin 

göze gurbet görünür 

ama nasıl 

evden bir kuş uçar 

kanadı kınalı 

gelin ederler telli duvaklı 

birde yiğitleri var deli dolu 

erkek olacak ya 

aklı bir karış havada 

ne gaz dayanır ne fitil 

ders çalışır geceler boyunca 

az kaldı ilk mektebin sonuna 

biter bitmez 

şehir alır onuda 

okuyacak büyük adam olacak 

kurtaracak anne babasınıda 

şehir renkli dünya 

şehir umut 

kurtlar sofrasında 

ekmek aramaktır 

yatağı mekanı belli değildir 

düşer yollara 

usta dedi ki 

bitmez bu sevda 

ağa düşmüş balık 

sarılır yengeclere 

sahipsiz ve kimsesiz 

her uzanan ele 

simsarlar kol gezer 

şehir varoşlarında 

o hala ayakta 

köprü altı, parklar 

sıcak sokuluşlarla 

kaybolur gecenin karanlığında 

her doğan gün 

sancılı bir umuttur 

hasrete, özleme 

kahve köşesinde boyacı 

çığrış bağrış ara sokaklarda satıcı 

balonlar renk renk 

uçuşur gökyüzünde 

teyyareler selam götürür sılaya 

dur durak bilmez 

ayak işlerinde 

çırpınır kanadı kırık serçe 

zaman zaman 

tutunacak dal arar 

ideali var ya... 

usta dedi ki 

düşte kalır okumak 

adam olmak 

bu gidişle... 

meslek gelir akla 

işe başlanır 

hoş geldin hayat eri 

yer süpürme 

ayak işleri, ufak tefek işler 

yeni bir hayat. 

iş tarifi yapılır 

şunu şöyle yap 

bunu böyle yap.. 

söylediklerime kulak ver 

elini kullan; dikkat et; seri ol.. 

kafa; parmak dirsekleriyle 

eller; çekiç sapıyla 

ayaklar; tek ayak üzerine dikelmekle 

eğitilir.. 

güven sağlar 

anahtar verilir 

günün ilk ışıklarıyla koşar 

fedakar eleman kimliği ile 

her şeyde o her işte o 

gün onunla başlar onunla biter 

ekmeğini sever 

emeğimi sever. 

usta dedi ki 

aferim.. 

sende gelecek var 

sırt sıvazlar 

bir hafta 

bir ay 

bir yıl 

karşılığı istenir emeğin 

orası olmamış burası olmamış 

dikkat etmelisin 

sabretmelisin 

azmetmelisin 

daha cok öğreneceklerin var 

çok çalışmalısın çok.. 

dikkat ettim 

çok koştum 

çok çalıştım 

bakınmadım sağıma soluma 

gün nasıl başladı nasıl bitti 

anlayamadım 

düşlerime taşıdım 

emeğimi işimi.. 

yorgun bitkin düştüm gecelere 

usta dedim... 

işi öğrendim. 

emeğimin karşılığı.. 

yoruldum. 

tatil; istirahat 

usta dedi ki 

olur..düşünürüz. 

işler yoluna girmiş 

zaman zaman dank eder 

okuma arzusu 

ekmek su gibi 

ikinci eğitimi düşler düşünde 

balıklama dalar 

bir akşam üstü 

bir elinde kitabı 

bir elinde işi 

akşama ders, aş, bulaşık 

günler su gibi akıp geçmekte 

artık hem işçi hem öğrenci 

baharın ılık ılık esintisi 

güneşin yaza göz kırptığı 

bir bahar sabahıydı 

bir mayıs bin dokuz yüz yetmiş yedi 

ellerinde bayraklar 

sokaklar bayram yeri 

istanbul türküler çığırır 

işçi öğrenci köylü 

her yönden yürüyüş kolu 

ve taksim meydanı 

yumruklar çekiç iner haksızlığa 

ve otuz yedi can 

taksim meydanı mezar 

usta dedi ki 

yıldırmasın seni bunlar 

baba yoksul 

köy yoksul 

toprak alınır bir kaç parça 

gurbetlik görünür diğer çocuklara da 

birer birer uçuşurlar 

kimi okumak 

kimi iş sevdasına 

gidenler dönmez geri 

anadolu 

ilgisiz, bakımsız, eğitimsiz 

devlet toplu katliyamda 

ekonomik politikalarıyla 

hayvancılık, tarımda 

şehir her gecen gün 

yeni çalkantılara gebe 

işçisi emekçisiyle 

işsizlik cığ gibi büyümekte 

kapanan fabrikalar 

sıkıldıkça sıkılan kemerler 

patladı patlayacaklar 

sokaklar yığınla eğitimsiz gençler 

sevdalar duman duman 

usta dedi ki 

herkes ekmek peşinde 

yıllar su gibi akmakta 

yaş yarıya yaklaşmakta 

dümen almış gemi 

çıkılan uzun yolculukta 

güneş vurmuşken kana 

sevmek aşık olmak yada 

saplanır sancıdır kalbe 

sevda ve umut yaşanılanlarla 

hakkıydı onunda bu 

yüreğindeki boşlukta 

sevdi aşık olduda 

sonbahara yenildi 

umut sevda dedi ya 

bitti bitecek derken 

filiz verdi yeniden 

umuda yolculukta 

usta dedi ki 

yaşam bitmedikçe 

sevda bitmez ki', 'toprak susuz  toprak kıraç  toprak taş  ekmek arpa  ekmek çavdar  ekmek mısır  yatak dam(ahır) bir göz oda  ve koyun koyuna  bir köşede bağl...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":242,"source_url":"https://www.antoloji.com/usta-dedi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan De', 'yalan-de-cemal-karsavran-gzonq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gün özler yollar bekler 

ıslak bir öpücük kuşluk vakti 

dudaktan kalbe kayıp yürekler 

hasret çeken gündüzlere 

yalan de 

saatler geçmek bilmez ki 

beklenilen köşe başında 

dalıp giden bakınılan yollarda 

gelişinle öpüşmeler 

yalan de 

ele ele kol kola yürünülen 

bir şeyler anlatıp gülüşülen 

kırılıp düşecekmiş gibi tutulan 

kulaktan kulağa fısıltılara 

yalan de 

zaman nede çabuk geçiyor senle 

buluşmuştuk oysa az önce 

gün bitmiş sevgilerle 

yürüdüğümüz yollara 

yalan de 

ayrılık saati gelir çatar da 

gözlerden akan yaş sızım sızım 

damla damla mutluluktur 

yalnızlığa yol alan sevgilere 

yalan de 

aranır bakınırsın her anında 

canlanırsın gözlerde 

dokunmak istersin uzanıpta 

yürekteki sensizliğe 

yalan de 

güne sığmaz geceye taşınır 

sayıklanır düşe girer 

döne döne uykusuzluklarda 

sensiz geçen gecelere 

yalan de', 'gün özler yollar bekler  ıslak bir öpücük kuşluk vakti  dudaktan kalbe kayıp yürekler  hasret çeken gündüzlere  yalan de  saatler geçmek bil...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yalan-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümsemelisin', 'gulumsemelisin-cemal-karsavran-q85xd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dünkü bıraktığım yerdemisin 

sokak lambasının altında 

sırtımı yasladığın dostum 

sırrımı paylaştığım sırdaşım 

gece ışıkları düşlerinmi hala 

yalan yanlış sevgilerden kalan 

bir damla gözyaşımı toprağa akan 

aşksa sevgi ise değer gözyaşlarına 

kıymet bilen insanadır akan yaş 

yalan aşklar iflah etmez öldürür 

seven sevdiğini sarmalı bence 

düşmeli düşlerine, ateş olmalı sevene sevgisi 

doğmalı her yeni güne fısıldamalı 

duman duman açlığın olmalı 

her dumanda solumalısın yüreğini 

bekleyişlerin olmalı umutlarında 

güneş olmalısın gündüzüne sevgilinin 

sabah serinliğinde tenini ısıtmalısın 

boğmalısın onun karanlıklarını yüreğinde 

sevginle onun yalnızlığını atmalısın 

güneşe göz kırpmalısın 

gülümsemelisin..', 'dünkü bıraktığım yerdemisin  sokak lambasının altında  sırtımı yasladığın dostum  sırrımı paylaştığım sırdaşım  gece ışıkları düşlerinmi hal...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gulumsemelisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarıma', 'dostlarima-cemal-karsavran-qxb90', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dostlarım hep yüreğimde saklıdır 

sevgileri zulamdadır 

sevildikçe sevilir paylaştıkca coşarım 

sanmayın gözlerim buluttur 

içten tebessüm vede umuttur 

kekeme dil konuşmasa bile 

latifede beceremez çok zaman 

kahkahalar çınlar kulaklarda 

başımın üstündedir yerleri 

açarım yüreğimi canlarıma 

uzak bakışlar akar geceye 

kaşlar oktur karanlıklara 

içten tebessümüm vardır heran 

koca bir yürek ağlayan gözlerde 

susuz bir ovadır tatlı bir sözle 

saçlar dolaşır parmak uçlarında 

bir sigara bir sigara daha 

duman duman olur 

sıkıntılarımda parmak uçlarımda 

zoraki değil gülüşlerm içten gönülden 

dostlarıma...', 'dostlarım hep yüreğimde saklıdır  sevgileri zulamdadır  sevildikçe sevilir paylaştıkca coşarım  sanmayın gözlerim buluttur  içten tebessüm v...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dostlarima-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Güler Sen Bende', 'gunes-guler-sen-bende-cemal-karsavran-7lv3j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şimdi aşk zamanıdır 

özlenen beklenen sen olduğunda 

ruhumda yanan yangın sevdandır 

denizler okyanuslar taşsa 

su damlası damladıkça yanar 

yandıkça alevler sarar 

yüreğinde yangın yanana 

sevdaya tutulan anlar 

hasret çekeni muştu güldürür 

yüreğim yüreğine sevdalı bülbül 

sevdan her zaman açan bir güldür 

seninle coşan çocuk ruhumda 

kulağımda çınlar tatlı sesin 

koşarım gelirim ayak sesine 

keklik olup seke seke 

kırılmazsa kanadım kolum 

kahramanı yaşatan umuttur 

yaşarım düşde hayalde olsan 

gözlerimin ışığı olursun günle 

güneş güler sen bende', 'şimdi aşk zamanıdır  özlenen beklenen sen olduğunda  ruhumda yanan yangın sevdandır  denizler okyanuslar taşsa  su damlası damladıkça yanar ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunes-guler-sen-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Güzel Akdenizli Seninle', 'yasamak-guzel-akdenizli-seninle-cemal-karsavran-0jcpl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yalnız kaldığım gecelerde 

tattım sevdayı buselerle 

kollarımda yüreğimde buldum özlemi 

öpüşen dudaklarım ıslaktı geceden 

özlenmezmi akdenizli yürekten 

uzak diyarlar ses verir 

düşlerime düşersin ak güvercin olupta 

umut olup yarına şafakla 

umutlarla özlemler karışık 

bir ömürdür akdenizli sevgiden 

gün geçtikçe yükselir haykırış 

unutulur acılar sararsan sımsıcak 

dilim söylemez dolanır birbirine 

yüreğimdir feryat eden sensizliğe 

isyanımdır akdenizli hasrete 

dalar gözlerim arar sevdayı aşkı 

sıcak nefestir dudağıma konan 

melektir dönen başucunda sabaha dek 

uyurken bir tebessüm dudaklarımda 

yaşamak güzel akdenizli seninle', 'yalnız kaldığım gecelerde  tattım sevdayı buselerle  kollarımda yüreğimde buldum özlemi  öpüşen dudaklarım ıslaktı geceden  özlenmezmi akden...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasamak-guzel-akdenizli-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevi''yim', 'sevi-yim-cemal-karsavran-leagh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'cenin''im 

yeni dünyaya gebe 

evrim''im 

ateş topuyum 

ekonomik çalkantılara 

devrim''im 

savaş''ım 

dargınlık ve küskünlüklere 

barış''ım 

emeğim 

şafakla yollarda 

aç''lara 

fakirim 

ekmeğim umut 

çingene''yim 

ekmeğim çöp''üm 

yağmur''um 

susamış topraklara 

köylü''yüm 

köle''yim 

hece''yim dilsizlere 

öğretmen''im 

umudum 

unutsuzluklara 

yeni günüm 

ruh''um 

sancıyım yüreklerde 

sevi''yim', 'cenin''im  yeni dünyaya gebe  evrim''im  ateş topuyum  ekonomik çalkantılara  devrim''im  savaş''ım  dargınlık ve küskünlüklere  barış''ım  emeği...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevi-yim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kadar', 'ne-kadar-cemal-karsavran-nupy2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hep sevgi derim ya 

hep zamansızımdır 

ne kadar sevdim 

kızımı 

oğlumu 

eşimi 

aşkımı 

ne kadar muhtaçım sevgiye 

onlar ne kadar 

ne zaman aşarız organik yaşamı 

kızım oğlum eşim 

kapıma dikildiğinde 

paramı.... 

sevgimi.... 

ne kadarı mutluluk 

ne kadar zaman ayırabiliyoruz 

cocuklara 

eşe 

dosta 

sevgilimize 

ne kadar sosyaliteyiz 

ne kadar sevgi 

ölçüsü varmıdır sevgilerin 

varsa 

ne kadar..', 'hep sevgi derim ya  hep zamansızımdır  ne kadar sevdim  kızımı  oğlumu  eşimi  aşkımı  ne kadar muhtaçım sevgiye  onlar ne kadar  ne zaman a...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ne-kadar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelken Ol Yüreğime', 'yelken-ol-yuregime-cemal-karsavran-5cqiq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kır zincirlerinde gel bana sığınağım ol 

gec kalmış sayılmayız boştur marina 

odak değil nokta olalım bakışlara 

kader çizgisidir uzanan yollara 

deli eden sevdalar yangın yeri 

bayram olsun gönüllere 

kışa dönen sonbaharda 

havada o kadar soğuk ki 

sarmak istiyorum kar yağarken 

uçuşurken tane tane başımda 

sokulmalıyız birbirimize 

sıcak sımsıcak her damla kar la 

gelirsen güneşli günlerde gel 

sahilleri paylaşalım üşürüm 

gözlerini kapama öpüşürken 

canlılığa hasretim kış mevsiminde 

uzun bekletme alışık değilim sürprizlere 

ölüdür şehir akşam saatlerinde 

istersen yağmurlarla gel 

çisi çisi başlasın kiprikler ıslandığında 

sen bana yağ ben sana 

dolu dolu bulutlar patlasın 

sel olsun sığmayalım yatağımıza 

fırtınaya kürek çekelim 

yelken ol yüreğime', 'kır zincirlerinde gel bana sığınağım ol  gec kalmış sayılmayız boştur marina  odak değil nokta olalım bakışlara  kader çizgisidir uzanan yol...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yelken-ol-yuregime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küstüm...', 'kustum-haci-ozturk-hhb09', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yazı   yazılmış  benim  alnıma, 

     Adı gurbetmiş  yazana   küstüm.

     Ağustosta karlar   yağar başıma, 

     Yüreğim  soğutmaz  yakana  küstüm.

     Eller gibi  bir gün olsun gülmedim, 

     Her zaman ağladım gözyaşım  silmedim, 

     Bu zalim gurbete isteyerek gelmedim, 

     Yolumu  şaşırtıp  ardımdan bakana  küstüm.

    Yağmur yağsa, rüzdar esse  sesleri gelir, 

    Hasreti,  özlemi  yüreği  yananlar  bilir, 

    Yeter  artık  yarap  yeter   ayrılığı  bitir, 

    Sensiz  olamam  diyen  o  cana  küstüm.



    Kıymeti  bilinmez mi   uzakta  olanın, 

    Halıda  sorulmaz mı gurbette    kalanın, 

    Can  dediğin  candan  gelmesze  selamın

    Hacım, , saçlarını  ağartan  o yara  küstüm.

             

                                         

 Hacı   Öztürk                               16/08/2003

                                                       LİBYA

KAYDEDEN                                 Hacı  Öztürk', 'Bir yazı   yazılmış  benim  alnıma,       Adı gurbetmiş  yazana   küstüm.      Ağustosta karlar   yağar başıma,       Yüreğim  soğutmaz  yak...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kustum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilsem...', 'bir-bilsem-haci-ozturk-fk8zz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaç  gündür  dosttan  haber gelmiyor

Başı  dardamıdır  bir  bilebilsem..

Hal  hatır  sorup, selam  vermiyor, 

Günü  zordamıdır  bir  bilebilsem.

Gidersen  seni  unutmam  derdi, 

Unutanı da asla  affetmem   derdi, 

Uzakta  olsa  aramız, yakınız  derdi, 

Bir  hatamı  ettim  bir  bilebilsem.

Dostların arasında olmaz dargınlık, 

Feryadım sahrada  hep çığlık, çığlık, 

Zorla   elbette  olmaz  güzellik, 

Ne dedimde küstü bir  bilebilsem.

Değer  veririm hep seven   insana, 

Arar  derdim  başı  düşürse  dara

O aramadı  bari  “hacım   sen  ara, 

Düşüncemde   yanlışmıyım  bir bilebilsem..

Hacı  Öztürk                        18/08/2003

                                              LİBYA

KAYDEDEN                       Hacı  Öztürk', 'Kaç  gündür  dosttan  haber gelmiyor Başı  dardamıdır  bir  bilebilsem.. Hal  hatır  sorup, selam  vermiyor,  Günü  zordamıdır  bir  bilebil...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-bilsem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak İsterken', 'yasamak-i-sterken-rasim-eksi-9xbfy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O ağacı iyi tanırım

Yaprağını ilkyazda döküşünden

Doğada eşitlik olmadığı belli

Ağacın kendini öldürüşünden

O ağacı iyi tanırım.

İyi tanırım kuşları

Avcıların izinden

Doğada eşitlik olmadığı belli

Neden öldüklerini bilmeden ölen

Kuşları iyi tanırım.

Bir insan var iyi tanırım

Sevgiye olan özleminden

Doğada eşitlik olmadığı belli

İnsanın insanı düşünüşünden

Bir insan var iyi tanırım.', 'O ağacı iyi tanırım Yaprağını ilkyazda döküşünden Doğada eşitlik olmadığı belli Ağacın kendini öldürüşünden O ağacı iyi tanırım. İyi tanırım...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasamak-isterken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Micheline''m', 'micheline-m-rasim-eksi-ujgmi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '- I -

Çağdaş müziği severim diyorsun

Verdi''den Çaykovski''den söz açıyorsun

Daha yirmisindesin - on yıllık vurgun

Daha yaşadığın ne ki korkuyorsun.

Sana beni anlatmak istemem

Emelimden Dileğimden söz açmak istemem

Salt şunu söylersem anlarsın Micheline''m

Bir yerden vurmazsa evlenemem.

         

                      - II -

Var mıydı böylesine ince telden çalmak

Neyimize yetmezdi uzun bir esinti

Neyimize yetmezdi Dünyalı olmak.

Acı badem çekirdeğinde seni duyuyorum

İlle ki umudediyorum da ne ola

Ben demedim mi nokta koya koya

Salt bizim  kızları seviyorum.', '- I - Çağdaş müziği severim diyorsun Verdi''den Çaykovski''den söz açıyorsun Daha yirmisindesin - on yıllık vurgun Daha yaşadığın ne ki korkuy...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/micheline-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-erhan-saka-xmeys', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Solmasın ümitlerin, hep yeşil kalsın, 

Yıkılmasın hayallerin, birer gerçek olsun, 

Süslesin mutluluk, o güzel gözlerini

Ben seni seviyorum, o günden beri.

Bahtın açık olsun, yaz günü kadar, 

Güzellikler senindir, sabahlar ve akşamlar, 

Sevgiler sarmalasın, o narin yüreğini, 

Ben seni seviyorum, o günden beri

Acılar çıkmasın, hayatında yoluna, 

Ümitsizlik düşmesin, gönül baharına, 

Anlatsın sağanaklar, sana olan sevgimi, 

Ben seni seviyorum o günden beri.

Aşkımı haykırsın, pencerede güvercin, 

Kalbimde senin aşkın, dudaklarımda ismin, 

Benim olsun tertemiz, yüreğin ve sevgin, 

Ben seni seviyorum o günden beri.', 'Solmasın ümitlerin, hep yeşil kalsın,  Yıkılmasın hayallerin, birer gerçek olsun,  Süslesin mutluluk, o güzel gözlerini Ben seni seviyorum, ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-gun-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Söylemesi', 'benden-soylemesi-rasim-eksi-8z5ts', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir yazıyordu sevgilin

Coşkuluydu

Tutkularla doluydu içi

Sözcüklerin en güzelini

Seni düşünerek seçti.

O tüm varlığını sana adamış

Seni sevgisiyle büyütür gibi

Sanki evrendeki elemler onun

Güzellikler sana vergi.

Sakın o beni sevmedi deme

Defalarca okur yazdıklarını

Seni bulmak için anılarında

Yeter artık onu anla

Kalma uzaklarda.', 'Şiir yazıyordu sevgilin Coşkuluydu Tutkularla doluydu içi Sözcüklerin en güzelini Seni düşünerek seçti. O tüm varlığını sana adamış Seni sev...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/benden-soylemesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Bu Kentteyken', 'sen-de-bu-kentteyken-rasim-eksi-7r537', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bunca aramadan sonra

Bu kentin sana varmayan yollarını

Bozmak geliyor içimden

Seni bilmeyen insanlarını

Kırmak.

Bu kent büyük kent

Çıkmaz sokakları var 

İnce uzun

Ben oralarda dolaşan serseri

Seni aramaktan yorgun düşmüş

Sırılsıklam deli.

Bilir misin bu kentte seninle yaşadığımı

Uykularını böldüğün beni

Bilir misin?', 'Bunca aramadan sonra Bu kentin sana varmayan yollarını Bozmak geliyor içimden Seni bilmeyen insanlarını Kırmak. Bu kent büyük kent Çıkmaz so...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-de-bu-kentteyken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul', 'istanbul-fatime-gokcen-adex2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ibrahim güllerinin yanık kokusuyla körükler yürek ateşimi uzakların ılık esintisi..

yeşil gözlerindeki serinliğe takılır, kavruk çöllerdeki serapların hayali..

alevlerin kızıllığı boyar, günbatımı keşmekeşliği...

VE AŞK......

permeperişan, kül kül, hücre hücre, yalın ayak bağrına düştüğüm andır sevdiğim..

uzakların gemilerine inadına gönüllü yazıldım limanına demir atmak için..

sevmenin yedi dağına çıktım seninle..yüreğimde yüreğinle..

yanlızlığın zemheresinde gül büyüttüm sevdiğim, ellerimde aşkla...

kara sevdayı akladım gözlerimdeki yaşlarla..

usul usul aheste aheste boyandım sevdiğim aşkının boyasıyla...

yaktı beni ateşin..

ateşin iklimleri en zirveleri ve aşkın ta kendisini yaktı sevdiğim..

seni buldum damarlarımda..

seni hücrelerimde, seni soluduğum havada, seni benden derinlerdeki bende buldum...

güllere sarı yakışır, ateşe kızıl, dağlara lale..gönlüme AŞK yaraşır sevdiğim yanlızca seninle...

ISTANBUL..', 'ibrahim güllerinin yanık kokusuyla körükler yürek ateşimi uzakların ılık esintisi.. yeşil gözlerindeki serinliğe takılır, kavruk çöllerdeki ...', ARRAY['Türk Edebiyatı','Şiir','Fatime Gökçen']::text[], 8.5, '{"poet":"Fatime Gökçen","poet_slug":"fatime-gokcen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çift Odalar', 'cift-odalar-i-brahim-tolga-ozsoy-6znmb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çift odalar, 

Bir açılır, bir kapanır kapılar.

Ses getirirler

Beni götürürler

Tenine değdikçe dudaklarım, 

Tutunamaz yanar gider.

Hasretin dalga, dalga büyür.

Seni getirdikçe beni götürür.

Beni götürdükçe ses getirir

Sesler sarar odamı

Her ses bir kelimeye denk gelir.

Çift odalar boyu, 

Bir ona bir buna

Dolaşıp oda oda

Seni toplar koynuna girerim

Tenime değdikçe dudakların 

Yanar giderim.', 'Çift odalar,  Bir açılır, bir kapanır kapılar. Ses getirirler Beni götürürler Tenine değdikçe dudaklarım,  Tutunamaz yanar gider. Hasretin d...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tolga Özsoy']::text[], 8.5, '{"poet":"İbrahim Tolga Özsoy","poet_slug":"i-brahim-tolga-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cift-odalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burgaz Kaldırımları', 'burgaz-kaldirimlari-yusuf-ziyaeddin-sivaslioglu-adf72', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu akşam gene yalnızım, 

Bir ben, bir de, 

Burgaz kaldırımlarındaki

Ayak seslerim

Bir ses, 

Tak! tak! diye, 

Yalnızlığın şarkısını söyler

Bir gönül, 

Ah! ah! diye, 

Yalnızlığınla inler

Sus artık, 

Sen de sus, 

Burgaz kaldırımları.

Sadece bir ben olayım, 

Bırak beni, 

Yalnız kalayım. 

(Lüleburgaz,12 Ekim 1972)', 'Bu akşam gene yalnızım,  Bir ben, bir de,  Burgaz kaldırımlarındaki Ayak seslerim Bir ses,  Tak! tak! diye,  Yalnızlığın şarkısını söyler Bi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/burgaz-kaldirimlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-yusuf-ziyaeddin-sivaslioglu-7cyxr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herşey gönlünce olsun

Her arzu gerçek

Ne tadı olurdu dünyanın

Kavgasız yaşamın

Kim ezecek, kim ezilecek

Belki Tanrı böyle istedi

Belki inandığımız cennet

Belki bu dünyada gerçekleşecek

(Lüleburgaz,8 Ocak 1972)', 'Herşey gönlünce olsun Her arzu gerçek Ne tadı olurdu dünyanın Kavgasız yaşamın Kim ezecek, kim ezilecek Belki Tanrı böyle istedi Belki inand...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gercek-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çingeneler Tutuyor Yasını', 'cingeneler-tutuyor-yasini-i-brahim-tolga-ozsoy-xjfb1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Esiyor bir ezgi varoşların arasından süzülüp.

Siyah beyaz bir film oynuyor gözyaşlarımda.

Bir keman çalıyor ağlarcasına.

Ürperiyor rüzgar, iç gıcıklıyor her nota.

Kapımın arkasında topuk sesleri

Gelip gelip gidiyor maziden

Vurulup düştüğün sokak kar beyazı topluyor, 

Kanından karanfiller açmış.

Gözlerin siyah beyaz oluyor anılarımda

Çingeneler tutuyor yasını, kemanlar çalınıyor ardına

Yatağıma uyku girmiyor imansız gecelerde.

Sarmıyor kolların, çalmıyor çigan

Soğuk toprağa sığınıyorum her gecenin ardından

Çingeneler tutuyor yasını, tefler şıkırdıyor

Sığamıyorum taşıyorum her notadan.

Topladıkça seni her yatsı vakti gökten, 

Bir bir birikiyor; çığlık çığlık oluyor yaşam

Ateşler yanıyor, her kıvılcım adın senin

Dualarımız oluyor ceylan gözlerin

Türkülere yazdın adını şimdiden, 

Şarkılara yazdın çingene gecelerinde.

O kanlı sokağa yazdın adını karanfillerle.

Güvercinler yükseldikçe göklere özgürlüğü yazacaksın.

Kemanlar çalınıyor ardından, 

Ve giriyorsun her gece vakti yatağıma

Sevişiyorsun uykularımla.

Bir kadeh şarap oluyorsun bazen, 

Bir çingene şarkısı, bir keman sesi

Bırakıp gidiyorsun her sabah vakti

Çingeneler tutuyor yasımızı.

Fidan''a

1993 İstanbul', 'Esiyor bir ezgi varoşların arasından süzülüp. Siyah beyaz bir film oynuyor gözyaşlarımda. Bir keman çalıyor ağlarcasına. Ürperiyor rüzgar, i...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tolga Özsoy']::text[], 8.5, '{"poet":"İbrahim Tolga Özsoy","poet_slug":"i-brahim-tolga-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cingeneler-tutuyor-yasini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Sofrasında', 'karanlik-sofrasinda-ugur-oguz-sahin-ku7uh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çöker geceye sessizlik

Oturur yüreğime sensizlik

Hep ıstırap hep ıstırap

Boynumda yafta bu talihsizlik

Gözümde göz yaşları

Ta derinde gönül yangınları

Yaşadım sahte aşkları

Yağdı hep feryat yağmurları

Sevdim sevilmedim

Mutluluk nasıl şey göremedim

Rüyalarda battığım

Karanlık gecelerdeydim

Şimdi sormayın neredeyim

Bazen bir bulut kucağında

Ya da bir yıldız kapısında

Durmadan dert kustuğum

Karanlık sofrasında', 'Çöker geceye sessizlik Oturur yüreğime sensizlik Hep ıstırap hep ıstırap Boynumda yafta bu talihsizlik Gözümde göz yaşları Ta derinde gönül ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karanlik-sofrasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Eri', 'gonul-eri-serdar-uzunoner-conl4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dövülmüş bir demirdir gönlüm

Aşkına şekillenmiş

Tutsak olmuş

Kalbine kilitlenmiş

Sevdan gözlerimi dağladı

Bağladı beni saçlarının teliyle

Ruhumun varlığı sen

Varlığımın ruhu sevgin oldu

Güzelliğinin fermanı gözlerime kesilmiş

Yazgısı birleştimiş ikimizi

Sultanım can özüm

Ben gönlünün eriyim

Saksıda büyüttüğün çiçeğim

Ve sen istemezsen solmaz sevgim

Solmaz sevdiceğim', 'Dövülmüş bir demirdir gönlüm Aşkına şekillenmiş Tutsak olmuş Kalbine kilitlenmiş Sevdan gözlerimi dağladı Bağladı beni saçlarının teliyle Ru...', ARRAY['Türk Edebiyatı','Şiir','Serdar Uzunöner']::text[], 8.5, '{"poet":"Serdar Uzunöner","poet_slug":"serdar-uzunoner","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gonul-eri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebepsiz Gidiş', 'sebepsiz-gidis-serdar-uzunoner-u1mth', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karaya vurmuştu ölü balıklar

Denize atıldıktan kısa bir süre sonra

Kimyasal atıklar

Koparılmıştı hayattan

Koparılmıştı canları

Kendi dünyalarına ait olmayan bir ölümdü

Bu yok oluşun nedenini anlayamayacak 

Kavrayamayacak kadar masum

Ve suçsuzlardı oysa ki

Bende anlayamadım

Şah damarımı kesen

Bıçak gibi sözleri sarf edip gidişini', 'Karaya vurmuştu ölü balıklar Denize atıldıktan kısa bir süre sonra Kimyasal atıklar Koparılmıştı hayattan Koparılmıştı canları Kendi dünyala...', ARRAY['Türk Edebiyatı','Şiir','Serdar Uzunöner']::text[], 8.5, '{"poet":"Serdar Uzunöner","poet_slug":"serdar-uzunoner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sebepsiz-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Rüyaya Dalar Gibi', 'bir-ruyaya-dalar-gibi-bekir-mutlu-gokcesu-x4nb0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgimizi

Parmak uçlarımızdaki

Dokunuşlara taşırdık

Dokunuşlarımızda

Özlem fırtınaları eserdi

Fırtınalarımızda

Sakin limanlar olurdu

Sığınabileceğimiz

Sakin limanlarımızda

Çılgınca sevişirdik kimi

Ve gözlerimizi kapardık

Bir rüyaya dalar gibi', 'Sevgimizi Parmak uçlarımızdaki Dokunuşlara taşırdık Dokunuşlarımızda Özlem fırtınaları eserdi Fırtınalarımızda Sakin limanlar olurdu Sığınab...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-ruyaya-dalar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yeni Günle', 'her-yeni-gunle-cemal-karsavran-trdj8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ayaz yüzümü oksarken

pamuk bir eldi...

gökyüzü surat asmis 

geceye..

sessizligi bölen 

ayak seslerimdi..

püfür püfür lodos

yüzümü yalarken

sen geldin nefes alislarimda 

aklımı aldın

gece dalgali deniz karaya vuran

ben sehrin içinde kayip bir liman

bir elimde kagit bir elimde kalem

tasi topragi altin Istanbul...

varim iste 

sehir uyur..

sessiz sokaklarda 

ayak seslerimle....

yolcuyum umuda

her yeni günle.', 'ayaz yüzümü oksarken pamuk bir eldi... gökyüzü surat asmis  geceye.. sessizligi bölen  ayak seslerimdi.. püfür püfür lodos yüzümü yalarken s...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/her-yeni-gunle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Bakislarimla', 'umutsuz-bakislarimla-cemal-karsavran-19si6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'resimlerle avuttugum

yalan dostluklar

yalanci baharlar

firtinalar kopsun varsin

alip basimi gideyim

deli desinler.

biliyorum ki..

gün be gün yükümü tasiyamiyorum

yetti dedigim her seferde

umutlarim düssede tel tel

genede tutunuyorum hayata

bir seyler var

kirik dökük içimde

uzak diyarlar tüter gözlerimde

kar çiçekleri 

ak güvercin olur

konar gözlerime

kelebekler uçusur basimda

döne döne

mustudur uzak özlemlere

yalan..

bitmedim

gitmedim

varim

oldugum yerdeyim

çember çember

sigaramin dumani

seyrine doyamadigim

umutsuz bakislarimla', 'resimlerle avuttugum yalan dostluklar yalanci baharlar firtinalar kopsun varsin alip basimi gideyim deli desinler. biliyorum ki.. gün be gün...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/umutsuz-bakislarimla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüşvetin Belgesi', 'rusvetin-belgesi-umut-gul-a5is0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'olmaz elbette rüşvetin belgesi 

çıkmıyorsa eğer vicdanın sesi 

garibin kokarken açlıktan nefesi 

şiştikçe şişer beylerin ensesi 

veren gönüllü alan dünden razı 

eksik etmez dilinden hamd-ı niyazı 

öylesine pişkin ki canım kardeşim 

rüşveti yerken kılar şükür namazı 

doğrudan çoktur onun yalanı 

deniz sanır hergele devlet malını 

bir gün gelir dizilir boğazına 

boğulur elbet yerken yetim hakkını 

hem kel hemde foduldur vesselam 

ağzından çıkar zorla bir kaç kelam 

öylesine işlemişki ciğerine deyyusun

rüşvet değildir diye almaz selam 

rüşveti yutarken hamudu ile 

sanır ki gömülecek tabutu ile 

oysa ki dünyayı titreten sultanlar bile 

ahirete gitti üç arşın çaputu ile', 'olmaz elbette rüşvetin belgesi  çıkmıyorsa eğer vicdanın sesi  garibin kokarken açlıktan nefesi  şiştikçe şişer beylerin ensesi  veren gönül...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/rusvetin-belgesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimsiz Ülkelerin Yağmuru Gibi Yüzün', 'mevsimsiz-ulkelerin-yagmuru-gibi-yuzun-engin-kahraman-bvyg6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her adımın ince bir sızı yüreğimde

öyle yumuşak öyle uçar gibi endamın

suya dokunuyor sanki ayakları

gün ağarırken ürkek bir ceylanın

-duyarmısın bir gün bu çığlığı

kimbilir tanısan diyorum belki beni severdin-

rüzgarla sevişen taze fidanlar gibisin

kayboluşun gözlerimde kızıl bir hüzün

sararmadan düşüyor sana meyleden hevesim

mevsimsiz ülkelerin yağmuru gibi yüzün

-sende üşürdün belki yağamayan kar gibi

belki de burun kıvırıp gülerdin-

gözlerimden geçiyorsun uzak bahçelerden

dağların içinden akan ırmaklar gibisin

biliyorum dokunsam sana öleceğim

uğultuyla sarsıyor gecemi nefesin', 'her adımın ince bir sızı yüreğimde öyle yumuşak öyle uçar gibi endamın suya dokunuyor sanki ayakları gün ağarırken ürkek bir ceylanın -duyar...', ARRAY['Türk Edebiyatı','Şiir','Engin Kahraman']::text[], 8.5, '{"poet":"Engin Kahraman","poet_slug":"engin-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mevsimsiz-ulkelerin-yagmuru-gibi-yuzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Puxa Vida', 'puxa-vida-yalcin-ergun-brdsx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hummalı bir serüvenin tam ortasıdır aslında aşk! 

Yani, göz açıp kapayıncaya kadar bir solukta okunan…

Boş lakırdılara bile kulak kabartmaktır işin özü

Trenin çarpacağını bile bile koşmaktır tünelin sonuna

Anlık bir hiddet ve küfür ile telefonu duvara fırlatmak

Ve ardından, ya ararda bulamazsa diye oturup kaygılanmaktır biraz da…

Yalanların yaralarını bilmektir aslında aşk! 

Her sözün başına-sonuna istemeden eklenen…

Heyecanını gizleyememek, ansızın kıpkırmızı olmak

Olsun da, nasıl olursa olsun mantığıyla hareket etmektir

Şirin görünmek uğruna bin türlü şaklabanlık yapmak, 

Yaranabilmek için türlü yaraları kabullenebilmektir sanki…

Küfür tadında bir yaşamaktır aslında aşk! 

Hatta Can Yücel’in mısralarında hamak kurup uyumak…

Kavga kadar gereksiz ama “gerekirse kaçmam” edasında

Yalancı pehlivanlık kadar kaygılı ve havalı olmak

Ve Jerry Drake edasıyla bir “Puxa Vida” savurmaktır 

Zillere basıp dörtnala kaçarken, hınzır bir “nanik” sallamaktır kimi zaman…

30.08.2003', 'Hummalı bir serüvenin tam ortasıdır aslında aşk!  Yani, göz açıp kapayıncaya kadar bir solukta okunan… Boş lakırdılara bile kulak kabartmakt...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/puxa-vida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönenle Sohbet', 'donenle-sohbet-oguzkan-bolukbasi-wtz1i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzun yoldan gelmişsin

Yorgun fakat anlatacak çok şeyler var gibi

Çay koydum ocağa demlenmek üzere

İçer misin

Bir duş al önce kendine gel

Tozunu al sadece,  anıların suya akıp gitmesin

Küçük odayı sana ayırdım

Çocukluğunla birlikte kalacaksın

Çekmecelerde kısa eteklerin var

Gençliğinden bir şey bırakmadan gitmiştin

Bak bu kırmızı kurdeleyi de sakladım

Bayram günleri takardın

Bakma bana öyle

Seni sakladığım gibi içimde

Senden kalanları da sakladım

Mevsimler değişirken seni her bekleyişimde

Dilek tutar gibi tuttum sarıldım senden kalanlara

O delikler eteğindeki ve kurdelendeki güvedendir

Çok zaman oldu ilk günkü gibi koruyamadım

Yaşadıklarım da siliniyordu yavaştan 

Beynimin güveleri de anıları delik deşik etti

İyi ki geldin 

Çayına kaç şeker isterdin

Yıllar önce de böyle gülümserdin

Aklından geçenler nedir söyle

 Bahçemdeki çiçeklere bakıyorsun

Çeşit çeşit rengarenk

Sen yoksun diye olmazdı sevmemek

Olmazdı yaşamamak

O çiçekler hayatın renkleri

Bir gelincikteki benekleri

Bir güldeki dikenleri

Bir yürekteki sevenleri yoketmek kolay değil

Gel sarıl bana döndüğüne sevindim

Çay ısıtacak seni

Okuyorsa hala gözlerin

Bak bunlar da senin şiirlerin', 'Uzun yoldan gelmişsin Yorgun fakat anlatacak çok şeyler var gibi Çay koydum ocağa demlenmek üzere İçer misin Bir duş al önce kendine gel Toz...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/donenle-sohbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''nun Haricinde', 'o-nun-haricinde-cemal-karsavran-6gxje', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'taptim ona 

birbaskaydi o

es kostum sevgime 

yoklugu bir parçam benden kopan 

çocugum esim annem canimdi.

melekti.

sigdiramadim yüregime

yasantimla her seyde

hep benim olsun istedim.

öyle mutluydum.

kalp atislarim cogalirdi her görüsümde

bir sicak nefesti kulaklarimda sesiyle

parmaklarimda, dilimde titreyen hece.

her kelimeyle.

canimdi sevgilim askimdi

ruhumda yanan. 

sönmedi sönmeyecek

denizler okyanuslar tassa...

sevda atesi bu

sevda söndürür

olmaz hiç bir sey çare

o''nun haricinde..', 'taptim ona  birbaskaydi o es kostum sevgime  yoklugu bir parçam benden kopan  çocugum esim annem canimdi. melekti. sigdiramadim yüregime yas...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/o-nun-haricinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizim Sizim', 'sizim-sizim-cemal-karsavran-850lp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sabirsizim

tezcanli

düsüncesiz belkide

kirdigim potlar üstüste

dara koyar sevdami

ayaz vurur

dalima yapragima

yesermege baslamisken

çiçegim.

cemre düser

yüregime.

zemheride

kar yagar basima

poyraz kirar

dalim budagim

sizim sizim sizlar

fakir sevdam.

akar gözümden yas

sizim sizim

kayboldum

varmiyim yokmuyum

kendi elimle

vurgun yedim

kirildim

yikildim bir kez daha

simdi vururum 

tastan tasa

akilsiz basim

is isten geçtikten sonra

sebep yok

kendim ettim kendim buldum

içim sizlar

sizim sizim

çile 

sizim sizim

sizlar yaralarim

sizim sizim

ask

sizim sizim

sevi

sizim sizim

sevgiler

sizim sizim

sancilarim

sizim sizim

ruhsuzum

ruhum..

sizim sizim', 'sabirsizim tezcanli düsüncesiz belkide kirdigim potlar üstüste dara koyar sevdami ayaz vurur dalima yapragima yesermege baslamisken çiçegim....', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/sizim-sizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Nefeste Adin Aklimda', 'her-nefeste-adin-aklimda-cemal-karsavran-znv4u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'unutmak mi dedin

gölge olur dostlar

biraktigin yürege

kimse tutamaz senin yerini

ben hala seninleyim

ve biraktigin yerde

bana bir alem verdin

dünüm yoktu

bu günüm

yarinimsin

bana beni verdin

hiç kimse sen olamaz

beni sen dogurdun

sancilarimiz oldu

olacakta..

seven yürek katlanir acilara

sen beni kirmadinmi

senin verdigini veremez kimse bana

sana yazdim seni yazdim

her nefeste adin aklimda', 'unutmak mi dedin gölge olur dostlar biraktigin yürege kimse tutamaz senin yerini ben hala seninleyim ve biraktigin yerde bana bir alem verdi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/her-nefeste-adin-aklimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatiralarda Mutluluklar Yasasin', 'hatiralarda-mutluluklar-yasasin-cemal-karsavran-14zvv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'umrunda degil sevmek sevilmek

sorunlari paylasmak dostane

özlemlerin üzüntülerin olsada

zarar görmesin yüregin ve sen

hayat senin

karamsarlik yakismiyor sana

kim yasayabiliyor hayati diledigince

dostlar zor günde

omuz omuza vermedikten sonra

ne anlami olabilir 

doldurmaz biliyorum yerini

bir sevgi bir sevginin 

bilki seni seveninde

sana sevgisi vardir

tanriçasiydin belki 

toz kondurulmaz sevgilerle

dostluklarin özlemlerinde yasasin

unutmalisin sana aci veriyorsa

uykusuzluklarinda geceler boyu

düs olan sizilarin

anlami yok artik

hatiralarda buruk sevgiler

basini döndürsede

dindiremez gözyasini

gecelere sigdiramadigin

acilari yastik yaparken basina

senin sancilarini çekmiyordur belkide

gül hade gün''e

anlik olsun üzüntülerinde

acilarin kadini degilsin

gül olmalisin

gülmelisin güne

baharin adi sen

mutlulugun tebessümü

sana hüzün yakismiyor

yasanmislar yasandiklariyla kalmali

yeniden dogmalisin

iste sana kirmizi bir karanfil

dost yürekten dost yürege

hatiralarda mutluluklar yasasin', 'umrunda degil sevmek sevilmek sorunlari paylasmak dostane özlemlerin üzüntülerin olsada zarar görmesin yüregin ve sen hayat senin karamsarli...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hatiralarda-mutluluklar-yasasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paramparça''yim', 'paramparca-yim-cemal-karsavran-3eqql', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dügüm dügüm

dügümleniyorum...

yüregim

dügüm dügüm.. 

kelimeler

dügüm dügüm..

dilim

dügüm dügüm..

gözlerimde yas

yüregimde yara

kaniyor, 

kan..

aci yok, 

duyumsayamiyorum..

duymuyorum..

kan kizil

yüregim kizil

kaniyor..

kolum kanadim kirik

derman yok dizlerimde

açligimi unuttum, 

yaniyor

yaniyorum..

dumanim

duman duman

savruluyorum..

her dumanda; sevda; ask

sevdigim..

ben.....

gözlerimde yas

ince bir sizi

damla damla

yüregim kaniyor

sevdam agliyor

bittim

bitiyorum

parça parca

paramparca

paramparça''yim....', 'dügüm dügüm dügümleniyorum... yüregim dügüm dügüm..  kelimeler dügüm dügüm.. dilim dügüm dügüm.. gözlerimde yas yüregimde yara kaniyor,  kan...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/paramparca-yim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Var Ya Sen', 'sen-var-ya-sen-cemal-karsavran-zvuuj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen var ya sen

sen olmasaydin

ellerim ayaklarim yüzüm 

kis ayazindaydi

feri kaçmis gözlerimde can oldun

somurtan dudagimda tebessüm

sen var ya sen

dalip dalip bakakaldigim durakta

son gelen yolcusun

zamani sana ayarladim

ayak sesinle ürpertim oldun

öne egik basimi kaldirdigimda

topraga düsen bir damla gözyasiydin

sen var ya sen

bekleyislerime özlemdin

akdeniz lodosu ilik ilik eserken

her nefeste aldigim

derin derin cigerlerimde bayramdin

sen var ya sen

iste o sen olmasaydin

ben oldugum yerde kalacaktim

kendi kendime

parmaklarim delerken avuç içlerimi

kan içinde.

sen var ya sen

gideceksin simdi biliyorum

bir demet gül sakli 

biraktigin mendilde

dikenleri isirgan otu olsada

kokladikça seni anacagim', 'sen var ya sen sen olmasaydin ellerim ayaklarim yüzüm  kis ayazindaydi feri kaçmis gözlerimde can oldun somurtan dudagimda tebessüm sen var ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-var-ya-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlukla Sevgiyle', 'dostlukla-sevgiyle-cemal-karsavran-ttw9d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sekerden bir sevgili 

buzdan saray degil 

yagan yagmurla yeseren

sarayda süslenen bahar

çikolata tadinda dudaklarla

yeni dünya yaratir

tebessüm eder

gülerim güne 

aynanin göbeginde

saçlari kizil kestane

günes kizil alev

sizarken perde araliginda

kralice olur gecelere 

güne dogar tebessümle

küçük bir çocuga melek

oyuncaklar kadar mutluluk verir

özgürlügü yaratir

hayat olur can olur

umulmadik yerde

dosta kosan yüregimle

basarilar yaratir

mutlulugu kucaklarim

dostlukla sevgiyle', 'sekerden bir sevgili  buzdan saray degil  yagan yagmurla yeseren sarayda süslenen bahar çikolata tadinda dudaklarla yeni dünya yaratir tebes...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dostlukla-sevgiyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuz Dokuzuncu Merdiven', 'otuz-dokuzuncu-merdiven-cemal-karsavran-iq278', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'serin soguk bir hava

umudun adi olmasa

anlami olurmuydu

yasanmis ve yasanacaklarin

ben ki dogdugumu bilmem

anam bile bilmiyor ki

çocuk olmadim vede

dogum günüm olmadi ki

hiç dogmadim bilmiyorum

annem tarla yolunda der

dedim ya oda bilmiyor

duhulumde mart on diyor

bende bilmiyorum

acaba diyorum

yoksa yasamiyormuyum

çalis çalis yas otuz dokuz

daha küçücük yasta

koyun kuzu otlatirdim

alfabeyi bile ögrendim sekizimde

ve gurbetlik onbirimde

mart on otuz dokuz yil

yarim asir 

ne çabukta geçmis yillar sakalimda kir

yasanmadan geçen onca yil

dün yada yarin degil bu günü yasamak

hep ertelesekte

göz kapaklarimda büyüyor

yasananlar var olmasa düsünmesem

otuz dokuz yil

bu gün benim dogum günüm

gelmis geçmis dile kolay

kimse bilmediki ben asla.

sararmis bir kitabin sayfalari

çevirdikçe hüzün yapraklariyla

kirilip dökülen

umutlardi parça parça

otuz dokuz yil

kaç yil yasadim

kaç ay, gün, saat

bir yaprak daha kiriliyor çitir çitir

yarina ertelenen

bir umut daha

her günkü günlerden bir gün

merhaba otuz dokuz yasim

yasam devam ediyor 

ertelemek degil yasamak hayati

yakinacak çok seyin içinden 

mutlu olmak sevinecek çok az seyi görmekle

bu yil ilkdefa aklima gelen

geçmis degil bu gün için

alnimdaki çizgilerde gizli

otuz dokuzuncu merdiven', 'serin soguk bir hava umudun adi olmasa anlami olurmuydu yasanmis ve yasanacaklarin ben ki dogdugumu bilmem anam bile bilmiyor ki çocuk olmad...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/otuz-dokuzuncu-merdiven-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Dostlara', 'tum-dostlara-cemal-karsavran-bpvqa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir günaydin yetti kusluk''la

olmasaydin sikintili günümde

yasamaya dair umudum yoktu

silkelendim artik bak yasiyorum

her nefeste dostlarim var diye

yeniden baslarim güne

sevinçlerim ve hüzünlerimle

bakma sen benim sitemime

gelip geçicidir çok zaman

hüzün dogurur mutluluklari

bir tatli söz dosttan dosta

gebedir buruk tebessümlere

varsin ya sundugun 

yesil zeytin dali sicak ellerinle

barisigim simdi günle kendimle

yalan degil sevgilerimde bende

minnettarim alakana ilgine

su serptin yalniz yüregime

tebessümüm oldun dostlugunla

daim olsun mutluluk ve sevinçler 

tüm dostlara', 'bir günaydin yetti kusluk''la olmasaydin sikintili günümde yasamaya dair umudum yoktu silkelendim artik bak yasiyorum her nefeste dostlarim v...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tum-dostlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erteleme', 'erteleme-cemal-karsavran-jqp0i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu yürege can veren sendin

bir bahar sabahi 

günesle dogan.

yeni bir askin filizini, 

seninle attim

yagmurlar yagdirdim

gözyasimdan

ince ince

damla damla

seninle filiz verdi

basak verdi

yüregimde 

olgunlasmis bir yara artik 

ne olur

erteleme bir sonraki bahara', 'bu yürege can veren sendin bir bahar sabahi  günesle dogan. yeni bir askin filizini,  seninle attim yagmurlar yagdirdim gözyasimdan ince inc...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/erteleme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Bürümüs Gözleri', 'kan-burumus-gozleri-cemal-karsavran-gepbk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çakallar is basinda

kuzgun kosuyor lese

bitik ekonomiler 

kisisel hirslariyla

olan mazluma olur 

kirilir kanadi kolu 

talanciya gün dogar

hedef belli Türkiye

tarihe damga vuran

savasçi yigit cesur

kazma görmemis toprak

eski kita ülkesi

dünyanin gözü türkte 

devletinde...

dört mevsim yasanilan iklimiyle

bir ana haykiriyor

kucaginda bebesi

dogacak bebelerin

umudu ipotekte

açlik sefalet ölüm

savaslarin çikmazi

ülkelerin bitimi 

yagma talan karmasa

sistemin istedigi 

çakallar basarirlar

kan bürümüs gözleri', 'çakallar is basinda kuzgun kosuyor lese bitik ekonomiler  kisisel hirslariyla olan mazluma olur  kirilir kanadi kolu  talanciya gün dogar he...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kan-burumus-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçsuz Bucaksiz Mavi', 'ucsuz-bucaksiz-mavi-cemal-karsavran-dqzeu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'zaman acilarin ilacidir

el ele tutusurken günes geceyle

su yanar

gizemli dünyadir 

yaralar uzun ince kanar

yaralar yürekleri sizim sizim

bazen maziyi bazen gelecegi anariz

gözlerimizi kapar

gelecek güzel günler hayallerde

garip bir tebessüm dudaklarda

tadini animsarsin

ayni noktaya takili kalir

biran gelir uykulardan uyanirsin

islak bir öpücükle

meltemler tatli tatli oksar

tenin tene degdiginde hissedilen gizemle

ince bir haz titresimle

yada ürkek dalginligindan siyrilir

bal rengi bakislar

tatli bir hayal geride kalirken

gerçek yasam birlesir 

ne korku ne hicran kalir

ne pir pir uçan kelebek

ne uçsuz bucaksiz mavi', 'zaman acilarin ilacidir el ele tutusurken günes geceyle su yanar gizemli dünyadir  yaralar uzun ince kanar yaralar yürekleri sizim sizim baz...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ucsuz-bucaksiz-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filiz', 'filiz-cemal-karsavran-qjhul', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çalkantilar baglar bizi yasama

hani çiçekler vardir ya

sanirsin ki..

hep tomurcuk kalacaklar

uzun sürmüstür gelismeleri

serpilip olgunlasmalari

sürek vermeleri

oysa gün gelir inanmadigin hizla

piril piril açiverirler

öylesine birden bire

yasamin anlami

ve bir hayat güler

tomurcuklanan filizlerde

mahmur gözler gibi

alinca günesi

rengi mutluluk rengine dönüsür

kiskandiran aydinlik

basaklar boy boy

o zaman kaybetsende kendini

umdugun..

buldugun yerdesindir

mutluluklar içinde

toprakta bereket yagmurlarla

basak olur 

hayat verir dogaya

ana olur 

filiz olur

umut olursun yarinlara', 'çalkantilar baglar bizi yasama hani çiçekler vardir ya sanirsin ki.. hep tomurcuk kalacaklar uzun sürmüstür gelismeleri serpilip olgunlasmal...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/filiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarim Kalan Özlemlerde', 'yarim-kalan-ozlemlerde-cemal-karsavran-xnrba', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yillar vardi gözbebeklerinde

her gün biraz daha büyüyen hayat

sigmiyorki yillara

geçiyor yaralar iz birakarak

yasamak 

insan olarak

özlemleri olur yapmaktir

küçük mutluluklarla

yasamak yasamanin

farkina varmaktir

paylasmaktir

yillar içinde

her gün yeni bir umut

sen eksik kalma mutluluklar içinde

kendini var say

hayat merdivenlerinde

yalniz degilsin

koy elini yalnizligi hisseden yüregine 

bul kendini kendinden öte

yillar alip götürsede yillari

daha yasanacaklar var 

yarim kalan özlemlerde', 'yillar vardi gözbebeklerinde her gün biraz daha büyüyen hayat sigmiyorki yillara geçiyor yaralar iz birakarak yasamak  insan olarak özlemler...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yarim-kalan-ozlemlerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hayatimsin', 'sen-hayatimsin-cemal-karsavran-quh6p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözlerimde tütersin aksam olunca

sigaramin alevinde görürüm

duman duman gecersin 

sesin gelir kulagima ninni

uyumak isterim dizlerin hani

bakinirim bir bosluktur her yanim

uzanir kollarim tutmak isterim

parmaklarim titrek mum alevidir

geceler yanar ben yanarim

ayak seslerimde durur ararim 

mechul rüzgarlarla kokun gelir

ilik ilik damarlarimda dolasirsin

kelimeler dügümlenir dilimde

ruhum titrer avuç içim terler

dalar gider gözlerim sensizlige

ucan bir sevdasin basimda

yelken olur dal olursun 

denizleri kıtaları asip geçersin

kucak kucak akarsin yüregime

sen mutlulugum sen hayatimsin', 'gözlerimde tütersin aksam olunca sigaramin alevinde görürüm duman duman gecersin  sesin gelir kulagima ninni uyumak isterim dizlerin hani ba...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-hayatimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlulugumsun Her Zaman', 'mutlulugumsun-her-zaman-cemal-karsavran-w99cz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'beyaz bir mutluluk senden bana 

yasadik birlikte hos bir seda

açtirmistin güllerimi ilkyazda

mevsim sonbahar hüzünmüdür yoksa

kistir hüzünle karisik mutluluk

bahari yasamistik biz allisi morlusuyla

iki kişilik doyasiya bu sevda

hayatin hediyesi yillardan sonra

hissettim biliyormusun senle ben

engin denizsin gözlerimde rüzgarla 

kalbin muhtesem bir sevgi hazinesi

tanrının armağanıydın 

bir güldürüp bir aglatan

bir öldürüp bir yasatan

gülde diken dikende gül

mutlulugumsun her zaman', 'beyaz bir mutluluk senden bana  yasadik birlikte hos bir seda açtirmistin güllerimi ilkyazda mevsim sonbahar hüzünmüdür yoksa kistir hüzünle...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutlulugumsun-her-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçmu Yoksa', 'sucmu-yoksa-cemal-karsavran-88orc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'zamansiz zamanlarda

benimle benden içeri

yasarsin derinliklerimde

çölde susamis toprak

geçit vermez daglar

basimda uçuk mavi

hayalin ak kefen

siyah beyaz resim

zeytin gözlerin; 

onyedi yasinin gizemi 

yüzün dolunay

gençlik yillarim; 

kare kare film seridi

seneler içinde sarabim 

duman duman tüten

sesin çinlar aranirim

vurgun yerim aklimda

krizlerim kis ayazi

nefes versen ferahlasa

kor kor yanan yüregim

hasret; özlemlerime

seni duymak, sevmek 

suçmu yoksa', 'zamansiz zamanlarda benimle benden içeri yasarsin derinliklerimde çölde susamis toprak geçit vermez daglar basimda uçuk mavi hayalin ak kefe...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sucmu-yoksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Geceye', 'gun-geceye-cemal-karsavran-0cnmv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ask sana hasret 

günes güne 

ben sana

içim gecer her hatirlandiginda

özlemler bugulanir gözlerimde

yagan yagmurla camlarda

gri bulutlar geceyi sarar

yangin yeridir yüregim

duman duman geçersin gözlerimden

bazen tren katari 

bazen okyanus

bazen kizil alevlerle 

yada süslenmis bayram yeridir

uçusan balonlarla

sen varsan ruhumda

akdeniz''den ilik ilik lodos rüzgarı eser

çinlar kulagimda sesin

mutlulugun tebessümü dudaklarimda

gün geceye göz kirparken', 'ask sana hasret  günes güne  ben sana içim gecer her hatirlandiginda özlemler bugulanir gözlerimde yagan yagmurla camlarda gri bulutlar gece...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gun-geceye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nede Ayak Izlerim', 'nede-ayak-izlerim-cemal-karsavran-6qqzn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her gün ayri baharsin

düslerime tasidigim

ayaz gecelerimde

parmaklarim buz keserken

avuç içlerimde

sicakligin vurur akdenizlim 

geceye

sen gelirsin sessiz sinsice

azar azar çogalirsin

damla damla 

cama vuran yagmurlarla

düsersin yüregime

ellerini ellerimde hissederim

avuç içlerim isinir

parmaklarimla

kagidim kalemim

dile gelir 

geceyi yazarim 

sensizligi

yoksun

düslerimde büyüttügüm sevdam

aynalar görebiliyormusunuz

gece dalgali

akdeniz yaliyor kiyilari

itiliyorum

o dalga senin bu dalga benim

kumlarda ayak izlerim

ne sen varsin

ne gece

ne akdeniz

nede ayak izlerim', 'her gün ayri baharsin düslerime tasidigim ayaz gecelerimde parmaklarim buz keserken avuç içlerimde sicakligin vurur akdenizlim  geceye sen g...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/nede-ayak-izlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Maviliklerde', 'sonsuz-maviliklerde-cemal-karsavran-k6sma', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir sen olmaliydin bende

bahar mevsimi gibi

dogan yüregime

kapi araligindan süzülen günes

dolasirken damarlarimda

toprak suya hasret bense sevgiye

ilik eser akdenizin lodosu

hasret özlem buram buram kokusu

güne dogdum güne bakanlarla

dilimde bir sarki nakaratiyla

çizik plaktir dönen basimda

avuç içim tatli tatli ezilir

mutlulugun mustusudur belkide

belli belirsiz tebessümlerim gizlenir

deli gözler kurumus dudagimda

düsünüyorum

beyaz güvercin uçar basimda

kanatlari çigris çigris vurur yürege

alip benide koltuk altina uçar

sonsuz maviliklerde', 'bir sen olmaliydin bende bahar mevsimi gibi dogan yüregime kapi araligindan süzülen günes dolasirken damarlarimda toprak suya hasret bense s...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sonsuz-maviliklerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Bil Tani Ustani Sevdam', 'sende-bil-tani-ustani-sevdam-cemal-karsavran-hn8lp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hey umutlarimin gökyüzü bakisli yalan sevdam

gözlerimde uçan uçuk maviler

ne sürüklenirsiniz lodosla 

nokta nokta çember çember gözlerimde

bekleyenin varmi düsünsene

çirpini çirpini kanatsiz kusum

geceler sessiz ölüm desene

günden güne biten ümitlerime.

aglayarak ciktigim bu yollarda

boynum egik gözlerim düser topraga

ben giderim yol bitmez bittigimde

dalga dalga karadeniz seni yarattigimda

gözümden canimdan çok baktim

kol kanat gerdim yoklugun yoklugumdu

egenin serin sularina verdim çagil çagil

attim yüregime kara iklimleriyle anadolum

hep seni düsledim hece hece

okyanus oldun zaman içinde

simdi coskun nehirsin kar sulariyla

baharlarla cosan sigmayan ele avuca 

delice bir çocuksun karadenizden

kiyilari yalayip geldigin liman sehrinde

toprak ana yesil dalmi birakti

doga baba günden güne verir erezyona

tasi topragi altin marmara

siginaklarim vardi koylarinda

yaradani yaratanda bilirim

sende bil tani ustani sevdam', 'hey umutlarimin gökyüzü bakisli yalan sevdam gözlerimde uçan uçuk maviler ne sürüklenirsiniz lodosla  nokta nokta çember çember gözlerimde b...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sende-bil-tani-ustani-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doyumsuz Sevdalarimla', 'doyumsuz-sevdalarimla-cemal-karsavran-xgbit', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bugün sahile inecegim.

yazdan kalma

ayak izlerimi bulmak için

islak kumlarda.

sevdalarimla.

denize yakindan bakacagim

ellerimi uzatacagim 

tenim akdenize dokunacak

dalgalarin serpintileriyle

uzanacagim.. 

deniz avuçlarimda

damla damla pul pul

lodos saçlarimi oksarken

sürü sürü geçecek 

sigda yüzen baliklar 

her biri birer yildiz 

uçusan gözlerimde

yosunlara gizlenen sevgiler

kayip giderken dalgalarla 

kiyilar yikanacak

islak tene düsen damla 

yeni dünya ve hayat

tuzlu suyun tadiyla dudagimda

ürpertisi denizin 

toros arslani

büyüyen uzakliklar

tedirginlikle

ürkek korkak sevdamin

maviler uçsuz bucaksiz

gözlerimde büyürken

akdeniz olacak

seyrine doyamadigim 

ilik ilik akan damarlarimda

sen olacaksin

güz gülleri açan yüregimde

doyumsuz.sevdalarimda..', 'bugün sahile inecegim. yazdan kalma ayak izlerimi bulmak için islak kumlarda. sevdalarimla. denize yakindan bakacagim ellerimi uzatacagim  t...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/doyumsuz-sevdalarimla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Öleli Çok Olmuş', 'ben-oleli-cok-olmus-orcun-oruc-aykac-nbnps', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben Öleli Çok Olmuş

Gölgemi çaktım yere, 

Işığı alnının ortasına

Parmak uçlarımı yaktım

Geride iz bırakmadım yaşadığıma dair.

Gözlerimi açtım mezar taşına

Silik bir yazı...

Öldüğümü düşünmüştüm

Oysa ben öleli çok olmuş.

26.12.2002', 'Ben Öleli Çok Olmuş Gölgemi çaktım yere,  Işığı alnının ortasına Parmak uçlarımı yaktım Geride iz bırakmadım yaşadığıma dair. Gözlerimi açtı...', ARRAY['Türk Edebiyatı','Şiir','Orçun Oruç Aykaç']::text[], 8.5, '{"poet":"Orçun Oruç Aykaç","poet_slug":"orcun-oruc-aykac","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ben-oleli-cok-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlik Sokaklar', 'karanlik-sokaklar-cemal-karsavran-urhhk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir kosusturmadir

gün geceye döndügünde

dolmabahce sirtlarindan

seyret istanbulu

seke seke kosar 

sehir umuda...

umutsuzluklara.....

vapur düdükleri 

çiglik çigliga

deler karanligi

yildiz olur isiklar

bogaziçi, kiz kulesi 

ve anadolu

uzaklarda yanar sehir

yanarim yalnizligimda

askin sessiz ayak sesleri

fisilti ve kosusturmalarla

çaliliklarin arasinda 

el ele yürüyen sevgililer

kaçamak öpüsler

bakislarda.

beynimi yirtar

vapur düdükleri

özlem, hasret, bekleyislere

her sefer''de

kaldigim yerde kalirim

bakislarim kalir geceye

ayni noktada

zaman gelir gecer

anliktir..

irkildigim ayak sesiyle

geceyi birakirim

oldugum yerde

gözlerimi

ruhumu

uyusmus bacaklarimi

oturdugum yerde

hain bicak olup keser 

umutlarimi..

sessizlik yalnizlik

karanlik sokaklar', 'bir kosusturmadir gün geceye döndügünde dolmabahce sirtlarindan seyret istanbulu seke seke kosar  sehir umuda... umutsuzluklara..... vapur d...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/karanlik-sokaklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakır Sahan', 'bakir-sahan-engin-kahraman-fevdo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Trablusgarp da mı kaldın Yemen de mi 

Çanakkale de mi yatıyorsun

gidişin kalmış bize son hatıran

bir de işlemeli bakır sahan;                  

şehirden alıp, ağlayarak köylülere verdiğin

''babam'' deyip bağrına bassın diye

kırk günlük oğlun hilmiye gönderdiğin', 'Trablusgarp da mı kaldın Yemen de mi  Çanakkale de mi yatıyorsun gidişin kalmış bize son hatıran bir de işlemeli bakır sahan;               ...', ARRAY['Türk Edebiyatı','Şiir','Engin Kahraman']::text[], 8.5, '{"poet":"Engin Kahraman","poet_slug":"engin-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bakir-sahan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Ama Soluğumsun', 'aci-ama-solugumsun-derin-oger-x30xt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılma kalbimden

Dökülüp giden yıllar olsun

Geceydi kadehlere doldurup içtiğim

Ben siyahı sevdim beyazlar senin olsun..

Olsun sönmesin bu ateş

Issız ışıksız kalan yollar olsun

Bir tek taşına bile dokunma sevdamın

Yel vurdukça solan menekşeler olsun..

Acı ama soluğumsun

Dudağımda adın suskunluk olsun

İster es gönlüme ister savur ömrümü

Göğsüme demir atmış fırtınan olsun..

Bana geceden bir yıldız getir

Işığından gözlerim körelmiş olsun

Ağla....Gözyaşın tutmasın elimden

Hüznüm rüzgarıyla giden bulutlar olsun.....', 'Ayrılma kalbimden Dökülüp giden yıllar olsun Geceydi kadehlere doldurup içtiğim Ben siyahı sevdim beyazlar senin olsun.. Olsun sönmesin bu a...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aci-ama-solugumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kirilan Sevdama Isik', 'ne-kirilan-sevdama-isik-cemal-karsavran-fm3im', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gökte gri bulutlar kizila çalar

sehir yorgun sokaklar suskun

uzaklarda teyyare isiklari yanar 

özlem, hasret yüklü yolcular

sokak isiklari yarar karanligi

geceye mahkumdur hüzünler

bir el aranir tutunmak ister

çirpini çirpinidir yürekler

durup durup bakinilan köse baslari

umutsuz ve çaresiz bekleyislerde

ne dal kipirdar ne ayak sesi

gece yalniz ben yalniz kendi kendime

dalgin bakislarimdan geçer 

katar katar trenler sevda yüklü

ay yok yildizlar küskün

sen yoksun isigim sönük

poyraz geceyi döver

üfür üfür kükreyen aslan

gece soguk mum alevi titrer

üsür ayaklarim ellerim yüregim üsür

sancili gece basim dumanli 

uyur uyanirim gökte kizil bulut

ne umuda yolculuk gelengün

ne kirilan sevdama isik', 'gökte gri bulutlar kizila çalar sehir yorgun sokaklar suskun uzaklarda teyyare isiklari yanar  özlem, hasret yüklü yolcular sokak isiklari y...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-kirilan-sevdama-isik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasamak Umuduyla', 'yasamak-umuduyla-cemal-karsavran-1qbm7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'günes oglak dönencesinde 

kan damitiyor

papatya görücüye çikmis

nevruz sunuyor

hava sirkülasyonu 

ölümün çirpinisi

kiliç kalkan oynuyor

sah damar vuruluyor

sevda yagli urgan

asilirken bogaza

kelimeler dügümlenir 

alamaz yutkunu

bogulur bogum bogum

gözden akan yaslarla

yapisir girtlaga bir söz

adi ölüm

sevda kanli biçak

belliki ok gelmistir yürege..

bilmezmisin hey be dost

yürek dayanmaz buna

rüzgar otu gibidir

sürüklenir bir anda

bir mustuydu ince tiz

dostun merhabasiyla

geceye küsen günebakan

güne dogdu aniden

islak gözlerini silerken 

yasamak umuduyla', 'günes oglak dönencesinde  kan damitiyor papatya görücüye çikmis nevruz sunuyor hava sirkülasyonu  ölümün çirpinisi kiliç kalkan oynuyor sah ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yasamak-umuduyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Bahar Yaşadın', 'kac-bahar-yasadin-cemal-karsavran-vkwm5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'otururdu dört duvar arasinda 

cama yakin

saçlari kumral

gözleri kestane

parmaklari sirça

kaslari dolgun

yanaklari al

uyur uyanirdi

oldugu yerde

dertlerini örük yapardi saçlarina

suskundu

dili yoktu agzinin içinde

düsmanini dost bilip

kosardi yardima

düsmanida yoktu ya

sakinmazdi sözünü dogru bildiginden

sevmekti suçu 

götürlürken daragacina

hep bakardi

yola bakan tek pervazli pencereden

kaç tren geldi geçti

yolculari neredeydi kimlerdi

hangi ayak sesiyle irkilirdi bilinmez

ama hep bakardi

derin bir uçurumdu

bakislarinda kaybolan

dalip dalip giderken

camin göbeginde

yillardan sonra

aynalari ters cevirir

aynalarda yalan sevdalari

onyedi yasinin umudu canlanir

kaçak asklari yagmurlarla

evlilik mutlulukmuydu

ayriliga uyumsuzluga ayak mi

lodosla çalkalanan dalga dalga

sevmek yasam felsefen olsada

güvenmi kaldi insanlarda

dostluklarin anlamimi var artik

yasadigini kar say

yasamadigini yasa

bir dahami geleceksin dünyaya

uyan bak tomurcuklar durmus çiçege 

nedir bu dalginligin

seyyah olur gezersin bilinmezliklerde

toprak gebe yesile

hala oldugun yerdemisin

tut elinden yüreginin

ince ruhlu

inci tanesi bakisli 

kestane gözlü kadin

ilk gençligin asklarindan

kaç ask 

kaç yaz

kaç sonbahar

kaç bahar yasadin

06-03-2003', 'otururdu dört duvar arasinda  cama yakin saçlari kumral gözleri kestane parmaklari sirça kaslari dolgun yanaklari al uyur uyanirdi oldugu ye...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/kac-bahar-yasadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerelerdesin', 'nerelerdesin-cemal-karsavran-sqwrk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'neden yoksun

suskun gecelerden

gün hala dogmadimi pencerene

seni bekler seni özlerim

duymazmisin feryadimi

nerelerdesin...

gölgen geçer gözlerimden

sol yürekte yanginim var

hep boslugu kucaklarim

hayal eder anarim

gözlerin gözümde canlanir

nerelerdesin...

bir var olur yok olursun

özlemlerle bogulurum

varligin yoklugunla 

içimdeki sikintilar

dag bogar deniz bogar

nerelerdesin...

parmaklarim saçlarimda yok olur

gelen geçen içinde aranirim

bakinirim sagima soluma

ha geldin ha geleceksin

gözüm yollarda

nerelerdesin...

gün bitti gece bitti

gelecegim demistin

hala oldugum yerdeyim 

avucumda yeserttigim güller

sunusa hazir seni bekler

nerelerdesin...

17-03-2003', 'neden yoksun suskun gecelerden gün hala dogmadimi pencerene seni bekler seni özlerim duymazmisin feryadimi nerelerdesin... gölgen geçer gözl...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/nerelerdesin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ele Güne Karsi Yalnizliginla', 'ele-gune-karsi-yalnizliginla-cemal-karsavran-3dn2g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hikmetli irfanli tanidim seni

Abihayat çaglayani yüregin

Yardim melegi heran her yerde

Ayrim yoktur sevgilerinde

Tabiyata asik bakan gözlerde

Akarsular coskun olur baharda

Yesil yapraklar renk renk çiçekte

Ilik ilik esen kavak yelleri

Koyar gider seni oldugun yerde

Oymak oymak kare kare gözlerde

Liman olur uzak özlemlere

Aslolan hayattir küçük hayallerde

Sevmekle baslar yasanilanlar

Emek vermek gerek özveri vede

Varligi varlik bilmek yoklugu yok

Güzellikleri görüp almak kendince

Ilgi alaka ister kazanimlarda

Lakin dikkat etmek aldanislara

Eger bir gün yanilipta seversen

Riyakarlik hazan olur baharla

Limanini kaybeder kalirsin ayazda

Ele güne karsi yalnizliginla

01-03-2003', 'Hikmetli irfanli tanidim seni Abihayat çaglayani yüregin Yardim melegi heran her yerde Ayrim yoktur sevgilerinde Tabiyata asik bakan gözlerd...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ele-gune-karsi-yalnizliginla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varligimin Bitimiyle', 'varligimin-bitimiyle-cemal-karsavran-yxzkv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir sevda yarattim

aska dair ne varsa

içimde

simdi kocaman bir yara

sizim sizim sizlar 

ellerim titrer kalbim sikisir

bogar yüregimi

bogum bogum

kelimeler dügümlenir takilir

eski bir fonografin ignesi

takili kalir 

ayni melodide

yutkunlugumda...

elim ruhum parmaklarim titrer

delice düstügünde 

aklima

kaybedisin öyküsü

hükmeder yüregime.

içtigim her damla su 

yedigim her lokma

dügümlenir kursagimda

nefes nefese seyredilen film 

canlanir gözümde

dipsiz kuyudur dalginligim

duragan kalisim 

anlamsiz..

gözlerim ölümün sessiz adidir

sararmis yüzüm

hüzün bulutu..

yagdi yagar

kirpigime düsen damla 

yüregim küçük dayanmaz 

sevdaya

yipratmak istemem

senden bana hediye

azar amansiz yara

biterim..

can kalmaz

elim kolum parmaklarim

bedenim.

canli cenaze

revamiydi bu ceza

kollarim ellerim parmaklarim

dökülsede

parça parça

kapatmayacagim genede

her seye ragmen

bu sayfayi

yok olana kadar

birer birer

kalsamda bir basima

kendi kendimle

vede sevdanla

nefessiz

bogulsam

kalp atislarimin gölgesinde

saniye saniye..

vefasiz degilim 

sevdaya

dolasan kanim damarlarimda

sigmiyor

sigdiramam

baska sevda

yasar yasatacagim

ömrüm oldugunca

inat olsun

vefasizlara

yagarken damla damla

kirpigimden..

eriyip bitsemde

sizim sizim 

sevdayla

kaybolan yok olan

ben olsamda

yasatacagim inadina

sen ve sevdani

varligimin bitimiyle..

24-02-2003', 'bir sevda yarattim aska dair ne varsa içimde simdi kocaman bir yara sizim sizim sizlar  ellerim titrer kalbim sikisir bogar yüregimi bogum b...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/varligimin-bitimiyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Gözyasim Sevdam', 'mutluluk-gozyasim-sevdam-cemal-karsavran-hv2fw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her günkü günlerden bir gündü

seninle günaydin dedigim hayata

arandim bakindim sagima soluma

yüregimde buldugumda

aldim kalemi elime

küçük bir kagit

agzimda sigaram

basimda sevdam

basladim yazmaya

yagmur kar tipi engel degildi

hayalin gözümde canlandiginda

tebessümüm oldun

dost canlisi bakislarinla

sevgim büyürken gün gün

olanaksizliklar kesti yolumu

açligim mide kramplarim tuttugunda

gelirdi aklima

ruhumu sarmasik olup sardin

düsünmedim senden baskasini

acilarim oldun mutluluklarim gibi

agladim gözkapaklarim sisti

sen görmedin

öyle büyüdünki bende

nefes alislarim 

kalp atislarimla

ellerini tutmak istercesine 

uzattigimda ellerimi

boslukta kaldiginda

sen hissetmedin

emegim oldun

kosusturmalarimda

zaman araliklarini iple çektim

sesinle costum

sevinçlerim sigmadi ele avuca

hüzünlendim

gözlerimde yas oldun

agladim gizlice

sen duymadin hiçkiriklarimi

seni anlamadim kirdim

her ayrilisimiz

sevginin çokluguydu

mutluydum 

hüzünlerimle bile

sen vardin seni duyumsuyordum

sesim bogulurdu yalnizligimda

gecem zindan gündüzüm haram

gidisini düsünmüyorum

sen bendesinki

seninle dolup seninle bosaliyorum

sen yüregimdeki tek sevdam

özlem hasret ve ruhuma can verensin

askim sevdigim

her seye ragmen

sönmüs volkanin ilk atesi

ve depremlerin en siddetlisi

kelimelere sigdiramadigim

anlatmaya cümle kuramadigim

varligimin özü 

sevda çekmeyen anlamaz seveni

sen tanrinin vergisisin

korkmam haykiririm

her yerde her zaman

mutluluk gözyasim sevdam...

26-02-2003', 'her günkü günlerden bir gündü seninle günaydin dedigim hayata arandim bakindim sagima soluma yüregimde buldugumda aldim kalemi elime küçük b...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/mutluluk-gozyasim-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdasiz Siir Yazilmaz Ki', 'sevdasiz-siir-yazilmaz-ki-cemal-karsavran-n20v3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden çaldigim kapilar kapanir 

Bir anlam tasirmi sana

Sevda yaratmak istiyorum

Ask istiyorum

Bosluktayim

Yasak mi, suç mu sevmek 

Anlamsiz duvarlar örülür boylu boyunca

Sevgisiz ask yasanir mi

Bu mu hayat yoksa 

Ah! ! bana can veren 

Öksüz yüregim

Ben hasret, sen sila bana

Sen özlem, ben gurbet sana

Kiyilir mi cana

Bir hazin Hürriyet

Kaybolan ümitler özlemlerde

Sormayin bu siir kime diye

Bilirim feryat feryat

Içini çizersin, kapatilmis kafese..

Bu siir, 

Sevgisiz yüregimden sevdama

Rahat ol, bogulma bir damla suda

Dostlarina sicak diye sarilsan da

Anlar mi, bilirler mi

Sevdasiz siir yazilmaz ki..

19-03-2003', 'Neden çaldigim kapilar kapanir  Bir anlam tasirmi sana Sevda yaratmak istiyorum Ask istiyorum Bosluktayim Yasak mi, suç mu sevmek  Anlamsiz ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevdasiz-siir-yazilmaz-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Çingenem Çikolatam', 'kara-cingenem-cikolatam-cemal-karsavran-fjbn4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'birak salinsin

islak saçlarin

savur.. 

dökülsün 

damla damla 

tene

hade ver saçlarini yele

ilik melteme

savrula savrula

gurbetligin özlemi gelsin

sila sila

kara çingenem 

çikolatam

istersen en cici elbiselerini giyin

yirtik pirtik

eski olsun

yüzünüde yikama 

saçlarin sokak çocugu

yüzün çingene

umudum var diye 

köse basinda

ürkek titrek yaz kis

göz kirparken güne

ekmek, emek olursun

kara çingenem 

çikolatam

baliçi gözlerin

olaganüstü yeteneklerin

yardimseverliginle

melek olursun

sana kara çingenem diyenlerin

yüz aki

onuru....

onurlu kraliçesi

taçim yok diye üzülme

sen basimin taçisin

yüregimin

sol kösesinde özgürlügüm

kara çingenem 

çikolatam

20-03-2003', 'birak salinsin islak saçlarin savur..  dökülsün  damla damla  tene hade ver saçlarini yele ilik melteme savrula savrula gurbetligin özlemi g...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kara-cingenem-cikolatam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgünüm', 'uzgunum-cemal-karsavran-1v9hi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gelecegim demistin

sürpriz..

gözlerim yollara düstü

ha bu gün

ha yarin

bekliyorum

geldin

geleceksin

çok özlemissin

seviyormussun

mutluymussun 

benimle sevinip 

üzülüyormussun

görmeliymissin

tanimaliymissin

gelecekmissin

bekliyorum

yoldayim

bir kalkip bir oturuyorum

her ayak sesinde

gözlerim yollara düstü

bu gün yarin

geldin 

geliyorsun

özür dilerim...

üzgünüm...

24-03-2003', 'gelecegim demistin sürpriz.. gözlerim yollara düstü ha bu gün ha yarin bekliyorum geldin geleceksin çok özlemissin seviyormussun mutluymussu...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/uzgunum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiler Sessiz', 'sevgiler-sessiz-cemal-karsavran-t2kyd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ölüm kokuyordu gece

sessiz sakin/karamsar

yaniyordu sigara atesiyle

elektrik direginin dibinde

kara bahtli adam/düsünürken

korku ve yalnizlik

kosuyordu/karaydi/geceydi

ayaz yürege vurulan biçakti

günden kalan umutsuzluklara

kara bahtli adam/sokak ortasinda

zembereginden bosalmis saat

deli divane/sevgililer deli divane

vurgun yemis duygularla

agliyordu/iki gözleri iki çesme

kara bahtli adam/sirtinda hançeriyle

kan kokuyor/umutsuzluklara

deniz titriyor dolunayda

atladi atlar ölüme/kalp sikisir

merdiven basamaklarinda

kara bahtli adam/yosunlu taslar üzerinde

ayrilik sürükler/umutsuzluga

umudu yok ki/geçit vermez daglar

beklentilerine karsilik/kestane gözler inci

anlasilir/zamana birakilir sevdalar

kara bahtli adam/yalniz/sevgiler sessiz

24-03-2003', 'ölüm kokuyordu gece sessiz sakin/karamsar yaniyordu sigara atesiyle elektrik direginin dibinde kara bahtli adam/düsünürken korku ve yalnizli...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevgiler-sessiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikkat Edilmeli Sanal Alemde', 'dikkat-edilmeli-sanal-alemde-cemal-karsavran-7982m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'merhaba ile başlayıp devam eden 

sanal bir dünyadır yaşanılan internette

kimisi derdini unutur kimisi aşkını arar 

dolaşır sevgiye ve ilgiye muhtaç 

ananeler gelenekler töreler unutulur 

bir arayıştır başlar bu ortamda 

şehir ışıkları yıldız olur başında 

konar o çiçekten bu çiçeğe 

bal arar. avcıdır gözü pek 

sosyal olur; sosyalitesini kaybedenlere 

umut olur yarın olur 

varoşlarda kaderiyle baş başa 

yaşamaktan habersiz insanlara 

paylaşılır; kasabalı aşk yaşanır 

şehir ışıkları kırılır gözünde 

romantik olunur 

yağmurda aşklar düşlenir 

gökkuşağıyla renklenip 

güneşin batışıyla kaybolan sularda 

duygusallık aranır seçicilikle 

seni eğlendirebilecek yollarda 

aşktan dem vurulur 

sevgiden sevgisizlik ve ilgisizlikten 

yaşanmamış sevdalardan 

av peşinde gözü pek avcıdır 

bay bayan evli bekar çocuk fark etmez 

tanışılır bir naz bir eda çok seçici olunmasa da.. 

aranan av bulunmuştur sonunda 

alımlıdır cezbedilir resimlerle 

seslerle telefon direğine bülbüller konar 

en ihtişamlı resimler mesajlar iletilir 

ekonomiye sıkışmış şehir yaşantısında 

bunalımdan kurtuluştur bir nebze 

günler yetmez gecelere sığınılır 

kurt dumanlı havayı sever 

telden tele ulaşır kalpten kalbe sevgiler... 

nişan belli ok atılır yüreğe 

hedef dövünür kör karanlıkta 

ihtişamı yansır gecede yürek boştur 

gece uzundur yalnızlığı hisseden yüreğe 

huzurdur yorgun gün koşuşturmalarından sonra 

herkes birbirini satar sanal alemde

gözü pek arar aranırlar 

umuttur; tutunmaktır umuda 

günler günleri kovalar geceler geceleri 

umarsızca,derin uçurumlar yaratacağı gözden kaçar 

zaman her şeye şahittir ruhlar öldürülmediyse 

zaman zaman derin mutluluklar yaşanır 

umutlar vaat edilir umutsuzluklara 

bir kelebek uçuşur bahardır her mevsim 

günler hep güzeldir aykırılıklarına rağmen 

çocuklar devre dışı bırakılır 

dile getirildiklerinde şartlar zorlanır 

kaçamak cümleler kurulur; dertler anılır 

eşler çocukları doğuran ebeveynler değildir 

oyuncaktır çocuklar arada 

yada eşler çocuk olurlar yıllardan sonra 

sıkmıştır sevgi sözcükleri 

en yakın dostluklar biter kalpler kırılır

eskiyen yada eskimeye yüz tutmuş 

sanaldır her şey gerçek gibi 

kaybetmek hazmedilmeden

bencillik ön plana çıkar 

ben severim ben bilirim ben yaparım 

ben bu işte ustayım 

hep bir tekrardır zaman aşımında 

yalandır sahtedir sevmeler aşklar 

evlilikler dostluklar arkadaşlıklar 

yok olur bir anda sanalistanda

tanınan tanınmaz hatırlamıyorumlarla

kim kaç kişiyi sever kaç kişiye aşık olur bilinmez 

söğüt dallarının altı bayram yeridir 

sanal sevişmelerde şehvetin doruğa tırmandığında 

başlar yaslanır göğüslere 

çayırlar bayram yeri olur baharlarda 

paradır hırstır kimilerine göre 

yemek içmek eğlenmektir belkide 

büyük küçük söz konusu değildir 

kurulur bu iletişim herkesle 

bir dengesizliktir sürüklenilir 

kör kurşun hedef teşkil etmez 

eğitimli eğitimsiz ayrım yapmadan 

yıkımlar ve hüsranlarla savrulur 

kimisi benliğini kaybeder 

kimisi düşen bir yapraktır sonbaharda 

saçma sapan bir yoldur gidilen 

dengesizlikler ortamında 

kalpler çalınır gururlarla oynanılır yuvalar yıkılır 

umutlara umutsuzluklar eklenir 

sorumsuzca, onursuzca 

kelime, duygu cambazı 

macera peşinde koşan insanlar

bay bayan çocuk büyük ayırmadan 

kimin eli kimin cebinde bilinmez 

dikkat edilmeli sanal alemde 

03-01-2003', 'merhaba ile başlayıp devam eden  sanal bir dünyadır yaşanılan internette kimisi derdini unutur kimisi aşkını arar  dolaşır sevgiye ve ilgiye...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":96,"source_url":"https://www.antoloji.com/dikkat-edilmeli-sanal-alemde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevim''in Öyküsü', 'sevim-in-oykusu-rasim-eksi-nxm3p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevimin başını bağladılar

Sevimin kanatlarını yoldular

Sevimi bir kafese koydular

Sevim uçamadı.

Paraları gösterdiler Sevime

Dediler özgürlük neyine

Karışma insanların içine

Sevim konuşamadı.

Paraları gösterdiler Sevime

Ah Sevim ah Sevim

Bakma bir o yana bir bu yana gezdiğime

Ben sensiz niderim.', 'Sevimin başını bağladılar Sevimin kanatlarını yoldular Sevimi bir kafese koydular Sevim uçamadı. Paraları gösterdiler Sevime Dediler özgürlü...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevim-in-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşmayana', 'konusmayana-rasim-eksi-bq753', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni kim çaldı masallardan

Kim indirdi tutkuyu yüreğine

Su sesi gibi derinden derine

Çağlayışın senden çok konuşuyor.

Gözlerinden ışıyor ince derdin

Güneş içinde ne varsa gösteriyor

Anlıyorsun süre eski süre değil

Giysilerin senden çok konuşuyor.

Birşeyler söylüyor sana çiçekler

Çiçeklerle ne güzel anlaşıyorsun

Ben konuş diyorum sen susuyorsun

Susuşun senden çok konuşuyor.', 'Seni kim çaldı masallardan Kim indirdi tutkuyu yüreğine Su sesi gibi derinden derine Çağlayışın senden çok konuşuyor. Gözlerinden ışıyor inc...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/konusmayana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Güzelleme', 'gozlerine-guzelleme-rasim-eksi-e0heq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir güzel zindan düşündüm 

Gözlerinin içinde

Bitmeyen yollardan beni kurtaran

Ellerini yitirdiğime ağlardım çağlar öncesi

Şimdi ellerini buldum

Gözlerinin içinde.

Göğü mavi denizi durgun anında severim

Seni en çok ne zaman sevdiğimi bilemem

Oysa gözlerinin sonsuzluğunda yok olmayı

Evrende var olmaktan önce dilerim.

İki yelpaze gözlerin 

Hem sıcak hem de serin

Kanımda uçan kelebeğin ipek kanatları

Yanan yüreğimi kaçırdılar

Gözlerinin dolu dizgin atları.', 'Bir güzel zindan düşündüm  Gözlerinin içinde Bitmeyen yollardan beni kurtaran Ellerini yitirdiğime ağlardım çağlar öncesi Şimdi ellerini bul...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gozlerine-guzelleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Binbir Biçimde', 'binbir-bicimde-derin-oger-whacq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlat bana 

Yaprağıyla hesaplaşan dalları

Öpmemişmiydi o dalı yaprakları

Binbir biçimde

Bir zamanlar bahardık seninle

Ah ki sere serpe

Nasıl da yakışmıştı

Kırmızı çiçekler yeşillerimize

Kucak açardık rüzgarın çığlıklarına

Yine de teslim etmezdik geceyi rüzgarlara

Yüreğimi teslim ettiğin gibi kâbuslara

Sen anlat bana

Hangi rüzgara sorarım olanları

Öpmemişmiydi o dalı yaprakları

Binbir biçimde.........', 'Anlat bana  Yaprağıyla hesaplaşan dalları Öpmemişmiydi o dalı yaprakları Binbir biçimde Bir zamanlar bahardık seninle Ah ki sere serpe Nasıl...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/binbir-bicimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkili Anlaşmalar', 'i-kili-anlasmalar-rasim-eksi-7rb9t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üzme tatlı canını nonoşum

Aramıza çekilen utanç duvarlarını

Belediye yıktıracakmış; 

Gelirler artsın diye.

Sonra ikili anlaşma yapacakmışız; 

Sevgimiz sürsün diye.

Düğünümüz için gerekli parayı da

Bush amca gönderecekmiş; 

Oğlumuz Irak''a gitsin diye.

Üzme tatlı canını nonoşum

Üzme.', 'Üzme tatlı canını nonoşum Aramıza çekilen utanç duvarlarını Belediye yıktıracakmış;  Gelirler artsın diye. Sonra ikili anlaşma yapacakmışız;...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ikili-anlasmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-omer-faruk-cakir-b9jq3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Aşk ta bitti” diyordu bir şair

Aşk bütün biten; benim

Günden güne eksilen; ben

Hergün biraz daha solan; tenim

Tamamen tükendiğinde rengi

Kalan tek şey olacak benden

Aşk, 

Büyüyecek daha da dünyayı saracak

Oyalanacak aşıklar

Aşkla doğup batacak gün

Sana olan sevgimden pay çıkarıp

Şiir yazacak şairler

Ben bitmiş olacağım

Bütün bunlar olmadan

Gelirsin belki

Çoğalırım seninle, yeniden!', '“Aşk ta bitti” diyordu bir şair Aşk bütün biten; benim Günden güne eksilen; ben Hergün biraz daha solan; tenim Tamamen tükendiğinde rengi Ka...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeniden-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''na', 'o-na-omer-faruk-cakir-y8muh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakışların tamamı ürkek artık, 

Bütün bekleyişler sessiz, 

Tedirginliktir büsbütün

Ve bir şarkı çalar radyoda, kimse duymaz

Yüreğinin bir yerinde bir ince sızı

Gece ve ben kenetlenirim o sese

Gece benden dinlerken ben geceden

Hüzün şarkıları söyledi çocuklar

Çocuklar ki henüz doğmamışlar! 

“Hüzne çalık saatlerdi yüreğime sürdüğüm, 

ama zaman büyük acıları iyileştirmiyor, 

ve kasımpatılar açıyor yavaş yavaş, yaralarım gibi”', 'Bakışların tamamı ürkek artık,  Bütün bekleyişler sessiz,  Tedirginliktir büsbütün Ve bir şarkı çalar radyoda, kimse duymaz Yüreğinin bir ye...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-na-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matem', 'matem-omer-faruk-cakir-jj6zb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılığın matemi çökmüş ömrüme, 

Her anı içimde köz

Gündüzler bağlamış ellerimi, 

Gel ey gece beni çöz!', 'Ayrılığın matemi çökmüş ömrüme,  Her anı içimde köz Gündüzler bağlamış ellerimi,  Gel ey gece beni çöz!...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/matem-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahin', 'kahin-omer-faruk-cakir-di8my', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün kadar aşikar değil, 

Görmek için bak

Kahin olmak gereksiz

Kah uçar deli gönül

Kah ezilir sebepsiz', 'Gün kadar aşikar değil,  Görmek için bak Kahin olmak gereksiz Kah uçar deli gönül Kah ezilir sebepsiz...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kahin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanlarım', 'i-syanlarim-yusuf-canturk-u8qp3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yetim  yoksul  bir  çocuk,  yalnız  gurbette., 

                                Anlatamaz  acıları, bu  birkaç  kelime.

                                Küfürler  etmiştim, o  zaman,  ne  geldiyse  dilime.

                                Dua  edemezdim,  beni  dünyaya  getirenlere  elbette! 



                                Çocukluk  çağımda,  çok  defa  isyankar  oldum.

                                Gurbette  kimsesizdim,  nisyanla  doldum.

                                Bir  anda  duyduğum  yazık  ki  acı  ve  kindi.

                                Ne  kadar  pişmanım  Tanrım,  biliyorsun   şimdi:   



                                Hamd-ü  sena  olsun   sana  ey  yüce Tanrım,! 

                                Kimi  zaman  aç  kaldıysam  da,  şimdilerde  tok  karnım, 

                                Senden  yardım  gelmeyeydi  şimdilerde  ben  yandım! 

                                Bazen  günah  işledim,  bilirsin  ya  şeytana  uydum



                                Gençlik  ateşi  bu  ya,  hiç  sönmeyecek  sandım, 

                                Çileli  geçse  de  gençliğim,  geri  gelmeyecek  anladım.

                                Öyle  zaman  geldi  ki,  tövbekar  olup,  zikrine  daldım, 

                                Yalanmış  bu  alem  geç  te  olsa  inandım.

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Yetim  yoksul  bir  çocuk,  yalnız  gurbette.,                                  Anlatamaz  acıları, bu  birkaç  kelime.                     ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isyanlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazidir Asklar Sevgiler Baki', 'mazidir-asklar-sevgiler-baki-cemal-karsavran-p73eb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'canim cicim sözleriyle baslar 

evliliğe giden yolda flört evresi

bir kelebektir uçusan basimizda 

sakli çeyiz sandigidir 

iki kelimeyle dudaklarda 

asktir sevgidir yüreklerde

nikah defteri imzalanır evetlerle

her anı yaşamdan bir sayfa

ilk ayların heyecanıyla

kısa sürer  mutluluklar

sorumluluklarin getirdigi agirlikla

bir kosusturmadir baslar hayat yokusunda

görev bölümü eklenir güne

erken gitmeler geç kalmalar

sabah akşam ve gece

beklenen beklenmez zamanla evliliklerde

iki kelimenin beli kırılmadan

yorgunluğa yenik düşer bedenler

üstü örtülü kalir tozlanmasin diye

sikici bir hal alir paylasilamaz paylasilanlarda

mutluluklar disarda aranmaya baslandiginda

baska sevgiler yaratilir gel gitlerle

kacamaklar ayri birer mutluluktur

aykiriliklarina ragmen

sevgi yarı baygın hasta

dil altindan söylenemeyen 

kekemedir ayriliklar

dile gelir söylenmedik sözler

bitmeyecegine inandigimiz 

mutluluklardan sonra

daha vakit çok erken derken

ayrılık çanları  çalar

yorgun bitkindir yillar

hayat bir şans tanırmı bilinmez

yüreklerde kalir yillar içinde

mazidir asklar sevgiler baki..

02-12-2002', 'canim cicim sözleriyle baslar  evliliğe giden yolda flört evresi bir kelebektir uçusan basimizda  sakli çeyiz sandigidir  iki kelimeyle duda...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/mazidir-asklar-sevgiler-baki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyle', 'geceyle-cemal-karsavran-0906n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'günese vurgun kediydi

kapi araligindan içeri giren

sicakligi gözlerinde haindi

gülüsleri içtenligi yalan

asinaydi artik her güne

misafirim ol dediginde

avini yakalamis kedi sevinciyle

gittim gördüm

elleri ayakları dolanıyor

dili sürçü lisan edecekmişcesine

sahteydi yalandi

sevgileri öpüsleri

gülüsleri gözlerinde

avi ayaklarinda

eglendirdi aklisara 

kadehler boşalıp doldu

kelimeler kekeme

yalandı sözcüklerde dili

bir çirkeflikti an be an artan

zaman içinde

kalkma zamani geldiginde

o gülüs o sicaklik bir anda

ölünün soguk yüzüydü 

penceleri kan içinde 

geceyle

20-11-2002', 'günese vurgun kediydi kapi araligindan içeri giren sicakligi gözlerinde haindi gülüsleri içtenligi yalan asinaydi artik her güne misafirim o...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/geceyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin Ellerimde', 'ellerin-ellerimde-cemal-karsavran-xam0x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim seni ne kadar cok sevdiğimi bilemezsin

Senin beni ne kadar cok sevdiğini bilemem

Gözlerim üstünde olsun

Gözlerin üstümde olsun

Yaşamak bir merdiven

Gir koluma

Bas birinci basamağa benimle

Atsın kalbim atsın kalbin

Yıkalım sana olan bana olan engeli

Ben diyorum ki sen diyorsun ki yok

Bir nefes ver söyleyelim türkümüzü

Hem sana hemde bana yeter bu sevda

Tut elimden 

Bas birinci basamağa benimle

Ellerin ellerimde

13-11-2002', 'Benim seni ne kadar cok sevdiğimi bilemezsin Senin beni ne kadar cok sevdiğini bilemem Gözlerim üstünde olsun Gözlerin üstümde olsun Yaşamak...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ellerin-ellerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-cemal-karsavran-2ylqf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sevgi

küçük bir melektir

yüregimizde eglenen

görülmezdir

iki dudak arasinda 

çok zaman

damarda kandir

igne ucu degdiginde fiskiran

hep karsilasiriz

bilinmezki zaman

çiçektir sunuslarimizda

kaçamak bir bakistir

dokunustur tene degen istemsiz

seslenistir içtenlikli

sözdür dudagimizda

taddir algilarimizda

sevgi...

19-12-2002', 'sevgi küçük bir melektir yüregimizde eglenen görülmezdir iki dudak arasinda  çok zaman damarda kandir igne ucu degdiginde fiskiran hep karsi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevgi-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapsolurduk Bakislara', 'hapsolurduk-bakislara-cemal-karsavran-bqmav', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'umuduz yarina

saganak yagmur ardindan günes açarsa 

cocugum seninle dilsiz kekeme

aynalarda kirilirdin geceyle

yildizlarin güzelligidir senle gelen

gecenin sevgisizliginde

kara bulutlarin arasindan gülen

senle yasanir ilkbaharda

yürüdügüm yollarda bulurum 

seni kendimde hissettigimde

uzakliklar yakin olur sevginle

yildiz olur düsersin yüregime

dalarim okyanuslarin derinliklerine

yutarim seni senin sevginle

zamanlara sigmazsin

sigdiramadigin yüregimde

zaman yasanan andir yasatan sevdan

aynalarin yansimasidir belkide

yumak yumak sevda

boncuk boncuk dizerim kelimeleri gerdanina

süslenmis bayram yeridir

düsen yaprak degilsin akdeniz iklimiyle

ilik meltemdir senden esen

soguk ve ayaz da

atesin vurur bana gün öglene vurmusken

çekilen azaplardan

disarda lapa lapa kar yagsada

dayanmazdi yollar kara tipiye

ates olurduk kaçislara

hapsolurduk bakislara

17-12-2002', 'umuduz yarina saganak yagmur ardindan günes açarsa  cocugum seninle dilsiz kekeme aynalarda kirilirdin geceyle yildizlarin güzelligidir senl...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hapsolurduk-bakislara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Kostum Güne', 'gozlerinde-kostum-gune-cemal-karsavran-ne7o9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geceden yarim kalan mutlulugumdun

sesinin titresimleriydi kulagimda

duymak istedigimde 

dinlendigimi farkettim

hoscakal demekten baska söz bulamadim

ama seni duydum seni hissettim

odama dolan günesin yüzünde

sevgini kucakladim günesle

kapi önünde buldum

sarildim kucak kucak

sarildin kucak kucak 

öptüm yanaklarindan

öptün yanaklarimdan

islakligi durur hala yanagimda

kulagina fisildarken sevgimi

ikimiz bir cocuktuk masum birer

durup durup bakindigimizda gözlerimize

iki can iki küçük yürek

gözlerinde kostum güne

12-11-2002', 'geceden yarim kalan mutlulugumdun sesinin titresimleriydi kulagimda duymak istedigimde  dinlendigimi farkettim hoscakal demekten baska söz b...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerinde-kostum-gune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelken Açıp Güne', 'yelken-acip-gune-cemal-karsavran-gd7ny', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aksam sana geleceğim sevdam gün batmadan 

günesin batışını seyredeceğim gözlerinde 

yedi renk yedi dünya yedi tepesinden İstanbul’un 

mavisini ben tutarım kırmızıyı da sen tut 

deniz kırılsın gök kuşağının renklerinden 

dağlar dize gelsin minareler gölge etmesin 

eğmesin başını öne günebakanlar 

yedi ışık yansın yedi tepesinde İstanbul’umun

yedi gül koysunlar toprağa gün kararmadan 

yediverenler doğsun allısı morlusuyla şafakla

taç yapayım başına başımda renkli sevdalarla 

yelken açıp güne 

26-11-2002', 'aksam sana geleceğim sevdam gün batmadan  günesin batışını seyredeceğim gözlerinde  yedi renk yedi dünya yedi tepesinden İstanbul’un  mavisi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yelken-acip-gune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sabir Döne Döne', 'ya-sabir-done-done-cemal-karsavran-pdtgu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni cizgi cizgi yazmak istiyorum

ayaklarinla ellerinle 

sevda düsmüs yüreginle

yasanmiyan sevgiler özlemlerinle

kök salmissin yilllara

yarim kalmis mutluluklarla

kosarsin kucak kucak

açligindir seni asan denizlerde

kelimeler dügümlenir yüregine

saklarsin yillar içinde

dalga dalga yayilir durgun suda 

kipir kipirdir tatli bir sözle

yangin yeridir sessizlik 

körükler askin atesini

düsüncelerinde kaybolursun

deli esen yeldir hoyratça

geçit vermez daglardir düslerin

siginaksiz gecelerde delirir gökyüzü 

gece melegisindir aynalarda

ya sabir döne döne 

10-12-2002', 'seni cizgi cizgi yazmak istiyorum ayaklarinla ellerinle  sevda düsmüs yüreginle yasanmiyan sevgiler özlemlerinle kök salmissin yilllara yari...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ya-sabir-done-done-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzattığın Yerdedir Ellerim', 'uzattigin-yerdedir-ellerim-cemal-karsavran-9fsil', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'göğsüme yaslasam da başını saçını koklasam 

gözlerine dalıp da denizi bulsam 

uzak ülkeler gelse de aklıma 

mavisi yeter bana gözlerinin 

yeter ki sana bakmasını bilsem 

tut desen tutarım gel desen gelirim 

bir boşluk var bende biliyorum benden öte 

bir gül demeti uzatıyorum al onu 

koklayıp da hasret gider diye 

benim kokum olmasın varsın 

senin kokun olmasın varsın 

gez düşlerindeki boşlukta 

bul onu sol yüreğinde 

sanma ki uzaktır düşlerin 

elini uzatsan belki tutacaksın 

ha de uzat ellerini 

uzattığın yerdedir ellerim 

31-10-2002', 'göğsüme yaslasam da başını saçını koklasam  gözlerine dalıp da denizi bulsam  uzak ülkeler gelse de aklıma  mavisi yeter bana gözlerinin  ye...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uzattigin-yerdedir-ellerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dogarmiyim Güne', 'dogarmiyim-gune-cemal-karsavran-q1vql', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yine kosuyorum sana

karanlik sokaklar

yastigim

ikiz yatagim

yalnizligim

ay dogmamis gece

yildizlar

döne döne uykusuzlugum

yüregimde sancilarim

size diyorum 

dogarmiyim güne

28-11-2002', 'yine kosuyorum sana karanlik sokaklar yastigim ikiz yatagim yalnizligim ay dogmamis gece yildizlar döne döne uykusuzlugum yüregimde sancilar...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dogarmiyim-gune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-yusuf-ziyaeddin-sivaslioglu-prts3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen, 

Sende değilsen, 

Seni, 

Sende kim arar.

Sen, 

Sende değilsen, 

Bunda bir iş var.

Sen, 

Sen olacaksın ki, 

Seni sende bulacaklar.

Sen, 

Sanırsın ki her iş kolay, 

Sen, sende olmadıkça, 

Yol yokuş, yol dar.

Sen, 

Sen ol düzelsin yollar, 

Biliyorsun çalışanı, 

Tanrı da kollar.

(15 Mayıs2003, İstanbul)', 'Sen,  Sende değilsen,  Seni,  Sende kim arar. Sen,  Sende değilsen,  Bunda bir iş var. Sen,  Sen olacaksın ki,  Seni sende bulacaklar. Sen, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-286-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-yusuf-ziyaeddin-sivaslioglu-p6b2x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tut ellerimi, 

Sakın beni bırakma, 

Sıkmaktan yorulsa bileklerin, 

Ellerimi, ellerinden ayırma

Tut ellerimi, 

Sakın beni bırakma, 

Yüreğinde soğusa aşkım, 

Sen ellerimi soğutma.

Tut ellerimi, 

Sakın beni bırakma.

Bir gün soğursa bedenim, 

Benim için ağlama.

(13 Ocak 2002, İstanbul)', 'Tut ellerimi,  Sakın beni bırakma,  Sıkmaktan yorulsa bileklerin,  Ellerimi, ellerinden ayırma Tut ellerimi,  Sakın beni bırakma,  Yüreğinde...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgilim-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Adresler Sokağı', 'eski-adresler-sokagi-umut-yalim-3b55r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimbilir ne kadar çok sözcüktünüz benimçin

Eski Adresler Sokağı'' nda

Oysa ne kadar da küçügen bir kadındınız

Bir yerlerde bir noktalı virgül görsem imlasına uygun

Siz sanardım. Eski Adresler Sokağı'' nda.

Halbuki eski denecek bir yanınız yoktu

Her tarafınız karegendi benimçin

Bir dudak görsem size betimliyordum. Eski Adresler Sokağı'' nda

Ben tüm kadınları kadın sanıyordum

Tüm kadınları siz sanıyordum imlasına uygun

Gözlerinizi makas biliyordum. Topuklu. Çizgi çoraplı...

Dudağ'' nızın değdiği yerde akşamlar bitiyordu tatmimsiz, ansızın

Perdeli alınlarınızda üşüyen ışığı ayın. Eski Adresler Sokağı'' nda.

Eskiden güzelmiş tüm kelimeler

Az kullanıldıklarıçin

Eskiden güzelmiş tüm kadınlar 

Az sevildikleriçin

Ve koltuklarınızda büyüyen bıyıklar

Hala tazeydi

Sırf anımsamakçin seviyordum o kadınları

Sevsem de bilmiyordum sonunu

Belki ayrılıktı, belki siz

Belki de sizinle olabilmekçin uzatıyordum şiirleri

Herşeyden siz çıkıyordunuz:

Yere tükürsem siz, adam öldürsem, yesem, içsem

Ürksem, sevinsem... Sevsem sizi. Siz. Sevmesem sizi. Siz.

Bilip bilmediğim ne çok sözcüktünüz benimçin

Anlamlı anlamsızlar türettiğim.', 'Kimbilir ne kadar çok sözcüktünüz benimçin Eski Adresler Sokağı'' nda Oysa ne kadar da küçügen bir kadındınız Bir yerlerde bir noktalı virgül...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/eski-adresler-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost yok', 'dost-yok-yusuf-ziyaeddin-sivaslioglu-9b47t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan bu, 

Döner sana, bana, ona

Kimden menfaati çok, 

Kim söylerse ona iyi, 

Ondan iyisi yok

İnsan bu, 

Döner sana, bana, ona

Kim keserse suyunun önünü, 

Kim kötülerse ününü, 

Ondan kötüsü yok

İnsan bu, 

Döner sana, bana, ona

Kim yitirirse malını, 

Kim kaybederse şanını, 

Onun dostu yok

(29 Mart 1973, Lüleburgaz)', 'İnsan bu,  Döner sana, bana, ona Kimden menfaati çok,  Kim söylerse ona iyi,  Ondan iyisi yok İnsan bu,  Döner sana, bana, ona Kim keserse s...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dost-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Düşünüyorsun', 'ne-dusunuyorsun-yusuf-ziyaeddin-sivaslioglu-3bn04', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni senden istiyorum

Sen gelesin diye

Seni çok seviyorum

Sen sevesin diye

Ne sen geliyorsun

Ne de seviyorsun

Nedendir bilmiyorum

Ne düşünüyorsun

(20 Mayıs 1973, Lüleburgaz)', 'Seni senden istiyorum Sen gelesin diye Seni çok seviyorum Sen sevesin diye Ne sen geliyorsun Ne de seviyorsun Nedendir bilmiyorum Ne düşünüy...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ne-dusunuyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-yusuf-ziyaeddin-sivaslioglu-sw1ar', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elveda gençlik yıllarım

Elveda özgürlüğüm

Şimdi artık ben

Yarım hürüm

Bütün ömrüm

Bu dört düğme altında

Senin özgürlüğün, senin mutluluğun, 

Senin şerefin için geçecek.

Ya sıhhatim, 

O da yarım senin için

Sıcak demeden, soğuk demeden, 

Koskoca bir ömür tükenecek

Senin her gece gördüğün, 

Tatlı bir rüyayı göremeden

Mutsuz sanma beni, 

Millete adamışım varlığımı ben, 

Duydukça  her gün erlerimin, 

Gürleyen sağol sesini, 

Yüceyim , mutluyum ben.

(9 Ekim 1972, Lüleburgaz)', 'Elveda gençlik yıllarım Elveda özgürlüğüm Şimdi artık ben Yarım hürüm Bütün ömrüm Bu dört düğme altında Senin özgürlüğün, senin mutluluğun, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/elveda-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Savaşçılar', 'yeni-savascilar-rasim-eksi-zvca0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karşı karşıya geldiler

Savaştılar

Yenildiler

Ağlaştılar yürek yürek.

Nerde yenilenlerin yılgınlığı? 

Bir boğuşmanın girdiği aralarına

Bir barışmanın ayırdığı

Dalgalara birlikte çektiler kürek.', 'Karşı karşıya geldiler Savaştılar Yenildiler Ağlaştılar yürek yürek. Nerde yenilenlerin yılgınlığı?  Bir boğuşmanın girdiği aralarına Bir ba...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yeni-savascilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyene', 'bekleyene-rasim-eksi-gea5o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ufukta ne ışık ne de bir gemi

Kıyıda oturmuş ağlayan kadın

Bırak da gözlerim seyretsin seni

Beni deli diye çağıran kadın.

Dalgalar yalıyor ayaklarını

Martılar öpüyor yanaklarını

Bekleme enginin aldıklarını

Olanlara inat gülelim kadın.

Neler neler çektim senin elinden

Yaşama başlamak için yeniden

Kolumu sarayım ince belinden

Çarpmaya başlasın yüreğim kadın.

Ben de çoktan senin gibi öksüzüm

İçimdeki  özlemi anlatır yüzüm

Belki mutlu eder bizi şu sözüm

Geçmişi haritadan silelim kadın.', 'Ufukta ne ışık ne de bir gemi Kıyıda oturmuş ağlayan kadın Bırak da gözlerim seyretsin seni Beni deli diye çağıran kadın. Dalgalar yalıyor a...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekleyene-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Platonik Aşk', 'platonik-ask-ugur-oguz-sahin-vdg4m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ulaşamadığın aşk

Senin değildir

Acı verir sancı çektirir

Zordur

Durmadan

Yürekte duran bir kordur

Onunla uykuya dalmak zordur

Ne yemek ne bir şey ister

Dizlerde takat''ı keser

Ne zordur bu

Platonik aşk

Sevginin

En sonsuz zahmeti onda

Alkol sınırı aşar gibi kanda

Çile çekersin isyan edersin

Derdini kimseye söyleyemezsin

Derbedersin

Yıldızlar kadar asilsin

Çünkü sen gerçeksin

Sahte değilsin

Platonikte olsa

Adam gibi sevensin

Sen hayat yolunda

Ağır gönül işçisi

En zora mahkûm edilensin

Hiç hile bilmez

Hüküm sürmez

Sevilmeden sevensin', 'Ulaşamadığın aşk Senin değildir Acı verir sancı çektirir Zordur Durmadan Yürekte duran bir kordur Onunla uykuya dalmak zordur Ne yemek ne bi...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/platonik-ask-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sormayın', 'sormayin-oguzkan-bolukbasi-i1ra0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nasıl seni seviyorsam

öyle bir sevgi benimki hayata karşı

anlamsız bulduğum anlar da olmuyor değil

bazen de tek mana sanki nefes almakmış sanıyorum

gün geliyor herkes aşina

gün geliyor gurbette dolaşıyorum

ben bana olduğu kadar

olanlara da şaşıyorum

sevgilim

hayat ve sen aynı anda

içimi sarmalısınız

tercihimi sorarsanız

yemin etmiştim

canımı vermeye sevgiliye

şimdi dardayım

bence hiç sormayın', 'nasıl seni seviyorsam öyle bir sevgi benimki hayata karşı anlamsız bulduğum anlar da olmuyor değil bazen de tek mana sanki nefes almakmış sa...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sormayin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşvermişlik', 'bosvermislik-giray-ozer-4313d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O sesi duydum yine

Hayat ve yaşamak kavramları canlandı

Elektriksizlik vardı camlarda

Neşesiz bir buğu kaplamış yaprakları

Fırtınada evini taşıyanların yorgunluğu var üzerimde

Bir el uzansa diyorum yıldızların arasından

Çekip alsa, sürüklese beni amacıma

Kurtarıcı ben değilim ki...

Boş verdim bir an insanlara hoyratça

Değilmi ki “Herkes severken, sen nefret edemezsin”

Sözünün doğru olduğu

Ama bil ki seni kendilerine benzetip

Kendine ihanet ettirecekler sonunda

Yine de yaşadığımız bu hayatın

Tangovari kıvraklığı sürüp gidecek

Bir o yana, bir bu yana

Bir Ona benzeyeceksin, bir Buna

Ama ben seni, sen olarak istiyorum

Başkası olarak değil.', 'O sesi duydum yine Hayat ve yaşamak kavramları canlandı Elektriksizlik vardı camlarda Neşesiz bir buğu kaplamış yaprakları Fırtınada evini t...', ARRAY['Türk Edebiyatı','Şiir','Giray Özer']::text[], 8.5, '{"poet":"Giray Özer","poet_slug":"giray-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bosvermislik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuleler ve Mantar Evler', 'kuleler-ve-mantar-evler-giray-ozer-dvtfz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşam ufuklardan uzatmış gölgesini bize

Kaptırmaktan korkuyoruz kendimizi mutluluklara

Oysa ki yalan gelmiştir hep mutlu yaşayış doğamıza

Biliriz ki hep kulelerin dibinde biten mantar evler gibiyiz

Aslında biz öyle zannederiz bu şaşkınlıkla

Bir de bize uzaktan bakanlar vardır, bizlerden biraz farklı

Onlar bilirler ki bu kuleler, şu ufak mantar evlere dayalı.', 'Yaşam ufuklardan uzatmış gölgesini bize Kaptırmaktan korkuyoruz kendimizi mutluluklara Oysa ki yalan gelmiştir hep mutlu yaşayış doğamıza Bi...', ARRAY['Türk Edebiyatı','Şiir','Giray Özer']::text[], 8.5, '{"poet":"Giray Özer","poet_slug":"giray-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kuleler-ve-mantar-evler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vapurdaki Deli', 'vapurdaki-deli-giray-ozer-n6njl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kez daha yaşamak istemedi bunları

Yüzünde kilitlenmiş bir kahkaha, hep gülüyormuş gibi

Acır aslında diğerlerine yüreğinin içinde kalır pıhtılar

İnceler duru tavan kirişlerini ama onun karmaşasında değildi.

Onun güldüğü bu kirişlerin, bu taşıma araçlarının

Nasıl da basit olduğudur ve ağlar bir odada sessiz

Yerinde dueamıyor bir göçmen gibi

Kendi zihin karmaşalarında gidip gelir delice

Bir kara torbanın içindeki şansa bağlanamazdı

Sayılar, kavramlar eski yaratıydı, ama değersiz

Yanımdan gölge gibi süzüldü kendi karanlığına

Oturup karşıma yediği simidin susamlarını saydı

İçim dondu birden, yöneltilen alaylarla boğazım tıkandı

Söyleyecek sözüm yoktu yırtık yamalara

100 binlerden daha önemliydi, bol sıfırların darlığından uzak

Artık hiçbir yenilik yoktu

Olabilecek en değerli şeye sahipti: “Kendine”

Aklı kendini yaşatıyordu ya bu da yeterdi

Ve öyle yaptı ölene kadar yaşadı da.', 'Bir kez daha yaşamak istemedi bunları Yüzünde kilitlenmiş bir kahkaha, hep gülüyormuş gibi Acır aslında diğerlerine yüreğinin içinde kalır p...', ARRAY['Türk Edebiyatı','Şiir','Giray Özer']::text[], 8.5, '{"poet":"Giray Özer","poet_slug":"giray-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/vapurdaki-deli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-atila-gunal-bla52', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öff..

Ne kadar kibirli...

Ne kadar da kendini beğenmiş şeysin sen öyle...

Yanına kimseyi yaklaştırmıyorsun...

Ama Dünya sana da kalmaz...

Bilesin...', 'Öff.. Ne kadar kibirli... Ne kadar da kendini beğenmiş şeysin sen öyle... Yanına kimseyi yaklaştırmıyorsun... Ama Dünya sana da kalmaz... Bi...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizligim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimdeydin', 'gozlerimdeydin-seyda-sarica-4l3yp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Durdun, gözlerimdeydin

Yitirdiklerine bakıyordun.

Hayır ıslanmamıştı henüz gözlerin.

Kapıyı kapatıp, 

Dönüp gitmeyi bekliyordu

Gözyaşların akmak için.

Yüreğinde yalnızlığın kalmıştı.

Kaç kez dönmek ve yitirdiklerini

Ellerinde bulmak istedin.

Kaç kez yıkıldığına inanamadın ve

Kaç kez öldüğünü zannettin

Ne kadar da hırslıydım oysa

Hep yarım kaldığını sandığım 

Seni sevmeyi bırakmamaya.', 'Durdun, gözlerimdeydin Yitirdiklerine bakıyordun. Hayır ıslanmamıştı henüz gözlerin. Kapıyı kapatıp,  Dönüp gitmeyi bekliyordu Gözyaşların a...', ARRAY['Türk Edebiyatı','Şiir','Şeyda Sarıca']::text[], 8.5, '{"poet":"Şeyda Sarıca","poet_slug":"seyda-sarica","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozlerimdeydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sabah', 'bu-sabah-hikmet-yakisir-crn1a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sabah  rüzgar olsam, 

Uludağ eteklerinden esen.

Bütün güzel kokuları toplasam, 

Bir aroma olsam.

Pencerenden içeri süzülsem, 

Odana dolsam.

Uyanmamış yarı çıplak teninde, 

Bir esinti olsam.

Bütün gece yanan bedenini, 

Serinletsem bu sabah.

Cennet bahçesine dönmüş odanda, 

Kokumu hissetsen, 

Usulca gözlerini açıp baksan, 

Gülümsesen, 

Kollarını açıp kucaklasan beni, 

Kendine çeksen.

Bedenime güller ekercesine, 

Öpsen beni, öpüşsek.

Çılgınca sevişsek, 

Seninle bu sabah.

Deli bir nehir olsam yüksekten akan, 

Şelale olsam.

Dağları yırtarak aksam, 

İçine dolsam, 

Dibimde gölet olsan, 

Beni toplasan.

Doğru yatağa yönlendirsen.

Özgürce uzansam, 

Ovalardan denize doğru, 

Usulca aksam bu sabah.

(31 Temmuz 2003', 'Bu sabah  rüzgar olsam,  Uludağ eteklerinden esen. Bütün güzel kokuları toplasam,  Bir aroma olsam. Pencerenden içeri süzülsem,  Odana dolsa...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bu-sabah-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Yağmuru', 'yaz-yagmuru-hikmet-yakisir-nfsdk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzüne bakıyorum, 

Berrak, pırıl pırıl bir asiman.

Masmavi

Güneş tüm yakıcılığı ile tepemde, 

Beni gölgesiyle saracak bir bulut bile yok.

Kör eden ışıltısına inat, 

Dikiyorum gözlerimi güneşe.

Sıcak bir gülümseme görüyorum.

Güneşte, 

Seni görüyorum.

Bana gülümsüyorsun, 

Kör eden ışınlarınla, 

Kavuran sıcaklığınla, 

Beni yakıyorsun.

Kapkara bir bulut yaklaşıyor sana, 

Kapatıyor seni bana.

Gürleyerek boşaltıyor yağmurlarını, 

İnat değil mi? 

Kaçmıyorum yağmurdan.

Sırılsıklam ıslanıyorum aşkınla.

Yaz yağmuru bu.

Bulut geçiyor, 

Işıldamaya başlıyorsun yeniden.

Doğanın bütün renkleri ile, 

Üstümde bir gökkuşağı oluyorsun.

Gülümseyerek bakıyorsun hala, 

Bir dilek tutup altından geçiyorum.

Dileğimi sorma, 

Tahmin et.

(01 Ağustos 2003)', 'Gökyüzüne bakıyorum,  Berrak, pırıl pırıl bir asiman. Masmavi Güneş tüm yakıcılığı ile tepemde,  Beni gölgesiyle saracak bir bulut bile yok....', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yaz-yagmuru-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün-Ay', 'gun-ay-hikmet-yakisir-jko2i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzel başlayan arkadaşlık, 

Gelişen bir dostluk, 

Bir kelimeyle bozulur mu.

Özledim seni arkadaş.

Nerdesin.

Yalan konuşmadım, 

Riya nedir bilmedim, 

İçten davrandım sana

Özledim seni arkadaş.

Nerdesin.

İnatçısın bilirim, 

Gidersen üzülürüm, 

Kaybettiğime yanarım

Özledim seni arkadaş.

Nerdesin.

Tatlı dilli sohbetini, 

Kulak okşayan sesini, 

Melodi gibi gülümsemeni, 

Özledim seni arkadaş.

Nerdesin.

Samimi içten duygulu, 

Gururlumu gururlu

Ela gözleri buğulu, 

Özledim seni arkadaş.

Nerdesin

Gün bakışlı, ay yüzlü.

Yeşil hareli ela gözlü, 

Hoş sohbetli tatlı sözlü, 

Özledim seni arkadaş.

Nerdesin.

(31 Ağustos 2003)', 'Güzel başlayan arkadaşlık,  Gelişen bir dostluk,  Bir kelimeyle bozulur mu. Özledim seni arkadaş. Nerdesin. Yalan konuşmadım,  Riya nedir bi...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gun-ay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süreğen Yazgı', 'suregen-yazgi-umut-yalim-fqwuq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alın yazımı ben mi yazdım ki? 

Ben sileyim

Eğer yazabilseydim

Avcuma yazardım

Daha kolay silinirdi...

                      1995', 'Alın yazımı ben mi yazdım ki?  Ben sileyim Eğer yazabilseydim Avcuma yazardım Daha kolay silinirdi...                       1995...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/suregen-yazgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Otopsi', 'mavi-otopsi-umut-yalim-513v3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Emine Hoca'' ma

Ellerime otopsi gerek'' cek

O anamdan gelen beleş ellere...

Hiç kullandığım.

Ellerime ölüyor Hoca! 

Ellerime suni teneffüs, 

Güllerin yırtık yerlerinden.

Ellerime otopsi gerek'' cek, 

Neşter vurup kirine ellerimin, 

Mavi nefesli terlerinden

Güllerin suni teneffüs...

Gerek'' cek. Ölen ellerime.

Ölüyor beleş ellerim Hoca! 

O anamdan gelen beleş ellerim, 

Güllerin sadece yarısı benim...

Ölmememçin suni teneffüs...

Gerek'' cek, mavi nefesli terlerinden güllerin,', 'Emine Hoca'' ma Ellerime otopsi gerek'' cek O anamdan gelen beleş ellere... Hiç kullandığım. Ellerime ölüyor Hoca!  Ellerime suni teneffüs,  G...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mavi-otopsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sedefli', 'sedefli-umut-yalim-gf7f8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir demir gibi sessizleştin

Gözlerin aktı yüzüne, sedefli

Yüzlerin kaçtı gözüne, 

Çok, çok çirkinleştin

Belki de güzelliğin tasviriçin.

Belki de yarın dudağında

Bir çekirdek fesleğen

Güzel çirkin, öleceksin

Sırf yaşamın tarifiçin.

                                2002', 'Bir demir gibi sessizleştin Gözlerin aktı yüzüne, sedefli Yüzlerin kaçtı gözüne,  Çok, çok çirkinleştin Belki de güzelliğin tasviriçin. Belk...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sedefli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-umut-yalim-914fn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdiğinden önceki gece, 

Yaşamının en yalın, en kısa gecesiydi.

Ama birşey vardı ki birşeyde

Damarları soğuk soğuk yanıyordu.

Yanıyordu milyonlarca Yoldanı ile.

Ve sevmek onlar için doğdu, 

                  Dün gece.

                                           2002', 'Sevdiğinden önceki gece,  Yaşamının en yalın, en kısa gecesiydi. Ama birşey vardı ki birşeyde Damarları soğuk soğuk yanıyordu. Yanıyordu mil...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dun-gece-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalındıkça anımsanan kadın', 'calindikca-animsanan-kadin-umut-yalim-iarj2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlıktaki biçimli karaltılar aralıklarla

Bir sevme zamanı biçimsiz

Doğmuşsam eğer kesin ellerimdem doğmuşum

Kim sevmişse ellerinden sevmiş beni

Karanlıklardaki dakka dakka Noktürn

Karaltılarla soğ'' muş Şohpen

Ellerim en güzeldi bu zamanlarda

Ama ellerim de elsizdi

Ellerimsiz çalmak seni ne güzeldi

Bir sevme zamanı şimdi biçimsiz

Ne güzel elleri yoktu ellerin

Benim de yoktu

Belki de ellerim ellerini saklayan çocuktu

Karanlıklardaki dakka dakka Noktürn

Şohpen bile ısıtamaz bizi

Bir sevme zamanı şimdi ellerimsiz

Bana doğru sevdim seni

Çalındıkça anımsanan o kadın

Ellerimsiz güzeldi sevda çalamazdım

Anımsandıkça sevilen o kadın çalındıkça

Köroğlu dinlerken evrenin tüm ezgilerini dinliyorum sanki: Seni.

Yalnız sen de biteceksin sonsuz kadanslarda

Ama ilkin çalayım seni ellerimsiz

Sonra severiz birbirimizi

Çalındıkça anımsanan o kadın', 'Karanlıktaki biçimli karaltılar aralıklarla Bir sevme zamanı biçimsiz Doğmuşsam eğer kesin ellerimdem doğmuşum Kim sevmişse ellerinden sevmi...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/calindikca-animsanan-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıyor Yanakların', 'aciyor-yanaklarin-umut-yalim-1r8v7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öptüm yanaklarından, dudaklarım sende kaldı

Yanaklarınsa bende

Ben hiç dudaklarımı bilmezdim

Dudaklarım sende kaldı

Sevmeyi bilmezmişim dudaklarımı

Dudaklarım sende kaldı

Öptüğüm dudakların bir türlü dudaklaşmayışı

Kaybolmak sokaklarında çıkmaz dudakların

Öpüşlerim kaç dudak çıkarır dudaklarımdan

Dudaklarım sende kaldı

Sevebildiğim kadınların dayanılmaz dudaksızlığı

Ben hiç dudaklarımı bilemedim

Bilmekçin

Dudaklarımdan öpüyorum seni

Acıyor yanakların', 'Öptüm yanaklarından, dudaklarım sende kaldı Yanaklarınsa bende Ben hiç dudaklarımı bilmezdim Dudaklarım sende kaldı Sevmeyi bilmezmişim duda...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aciyor-yanaklarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-umut-yalim-4qzth', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bekliyorum seni... Bekliyorum.

Sensiz, sessiz bir silah gibi tekliyorum, 

Bekliyorum, beklemek...

Sonsuz deryalara bir damla eklemek gibi, 

Bekliyorum seni... Bekliyorum.

Aybaşı maaşını beklemeyen memur gibi

Beni öldürmek istemeyen memnun ur gibi, 

Bekliyorum seni... Bekliyorum.

Ama gelmedin, gelmiyorsun, gelmeyecen...

Ren Nehirleri'' nde boğulan İren gibi

En bilmediğim sıvıları bana içiren gibi

Gelmedin, gelmiyorsun, gelmeyecen...

Ve şimdi beklememin tek nedeni

Korkmak bekleyememekten

Bununçin bekliyorum seni... Bekliyorum

Tekliyorum sessiz bir silah gibi, sensiz

Sonsuz deryalara bir damla daha ekliyorum...

Ve bekliyorum seni kendimden habersiz.

2000', 'Bekliyorum seni... Bekliyorum. Sensiz, sessiz bir silah gibi tekliyorum,  Bekliyorum, beklemek... Sonsuz deryalara bir damla eklemek gibi,  ...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bekliyorum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Bir Değildir', 'belki-bir-degildir-umut-yalim-u209s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boş aydınlığı havanın bir

Yaram yörelerime indiniz

Dinlediniz eski kulağı bir

Bir avurt yağmurçin

Koca bulutlar eskittiniz

Gittiniz hiçbiryere bir

*

Gözümün aynasında gösteremem seni

Göremem

Rahat genişliğin boyun ne de derinliğin sığar bana

Sığsa sığsa gözlerin ama uzun

Göremem

Onlar da çürüyor onlarda

Bir boşluğumda gözümün bir

*

Sevda mutlu ve güzeldir

Sade betimlerken sevdayı

Yankılıdır ağzımızdaki sesi: Sevdaaaaaaa

Güzeldir bir

Söylemek sevdayı sevdalanmaktan daha güzeldir

Güzeldir bir

Belki bir değildir', 'Boş aydınlığı havanın bir Yaram yörelerime indiniz Dinlediniz eski kulağı bir Bir avurt yağmurçin Koca bulutlar eskittiniz Gittiniz hiçbirye...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/belki-bir-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karen Her Dilde Güzel / Yozlukla Savaşım', 'karen-her-dilde-guzel-yozlukla-savasim-umut-yalim-11ru0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çevirsem Fıransızcaya

Yarı yarıya yitiriyorsun anlamını

Sen Türkçe güzel, Türkçemle

Türkçem gibi seviyorum seni

Kırgın yalnız ve bulanık

Türkçem kadar seviyorum

Biraz anlaşılmaz

Sevdam Türkçemle harfleniyor

Uzun uzun ağır ağır yorgun

Türkçe konuştukça seviyorum seni

Sustukça ayrılık  - bilmem hangi dil -

Sevdam satır satır kirlenir

Kustukça emper emper

Sevdam başka başka dillenir

Dilenir ayrılığa - bilmem hangi dil -

Sen Türkçe güzel, Türkçemle

Türkçe sevdiğim kız

Kirlenme sakın

Bak yakın tüm dilleri Anadolumun

Onlarla da severim seni Türkçem kadar

*

Ama Karen her dilde güzel', 'Çevirsem Fıransızcaya Yarı yarıya yitiriyorsun anlamını Sen Türkçe güzel, Türkçemle Türkçem gibi seviyorum seni Kırgın yalnız ve bulanık Tür...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/karen-her-dilde-guzel-yozlukla-savasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Çınar', 'koca-cinar-yasar-yildiz-pjwsq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir azgın ırmağın kenarında,

çalılar arasında boy atmış

tek başına koca bir çınarım.

Hangi rüzgar taşımıştı buraya, 

toprağa ne zaman düşmüştü tohumlarım? 

Böyle tek başıma kaç yıl yaşadım? 

Oysa; 

Bine kadar da saymıştım.

Irmağın sularıyla  aktı yıllar.

 saymaktan yoruldum.

Kaç yıldır saymıyorum, 

onu bile unuttum.

Kaç dalım kırıldı, 

kaç yaprağım koparıldı? 

Özgürlüğe sıkılan kurşunlar 

bedenime saplandı.

Aydınlığa çekilen bıçaklarla 

çizgi çizgi yarıldı.

Dallarımda serçeler dondu kaldı.

Kor ateşler içinde kaldığım 

günler de oldu.

Her gelen birşeyler aldı.

Hele de yıllar, yıllar...

Yalnızlıklar sa hiç bırakmadılar.

Yapraklarım gibi; 

Dallarımda hep asılı kaldılar.

Gün geldi; 

Ormanda olmayı özledim.

Yüksekçe bir tepeye tırmanıp 

yıldızlara dokunmak.; 

Irmağın sularına karışıp, 

denizlerin mavilerine akmak. 

Ama, köklerim bırakmadılar.', 'Bir azgın ırmağın kenarında, çalılar arasında boy atmış tek başına koca bir çınarım. Hangi rüzgar taşımıştı buraya,  toprağa ne zaman düşmüş...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yıldız']::text[], 8.5, '{"poet":"Yaşar Yıldız","poet_slug":"yasar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/koca-cinar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevebileceğim Tek Vakitte', 'seni-sevebilecegim-tek-vakitte-umut-yalim-yx26q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece nizamına aykırı

Tepede bir ay kırık

Ak şavkında bir ayrılık

Seni sevebileceğim tek vakitte

Bilirisn dardır zaman

Seni sevebileceğim tek vakitte

Ne yazık ak şavkında bir ayrılık

Tepede bir ay kırık

Sevda nizamına aykırı

Bilirsin kanım dar

Bu anlarda dardır zaman

Seni sevebileceğim tek vakitte

Ne kadar da güzeldin değildin

Bir bilseydin sen de sevseydin

Seni sevebileceğim tek vakitte

Yine de sen bilirsin belki gelirdin

Seni sevebileceğim tek vakitte', 'Gece nizamına aykırı Tepede bir ay kırık Ak şavkında bir ayrılık Seni sevebileceğim tek vakitte Bilirisn dardır zaman Seni sevebileceğim tek...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-sevebilecegim-tek-vakitte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem Kağıt İlişkisi', 'kalem-kagit-i-liskisi-sahin-yenilmez-e1fug', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kağıt ile kaleme benzer çoğumuzun sevgisi

Kalem sürekli yazmak 

Kağıt ise zaman ister

Çünkü kısadır kağıdın ömrü

Kalem bir sürü kağıda yazabilir ama

Kağıt dolduğu zaman bir daha silinmez.

Sevgi sınır tanımaz çoğu zaman

Çoğu zaman bütün engelleri aşmak ister

Ama ille bir yerde takılır

Bir daha gidemez.

Sınırsız hiç bir şey yoktur hayatta

Her şeyin bir sınırı vardır

Gecenin, gündüzün hatta yaşamın bile.

Gün gelir

Ne kalem yazmak ister 

Nede kağıt kalemi

Çünkü ikisinin de ömrü azalır

Kalan birkaç satırlık yere ömürlerini sığdırmaya çalışılar.

Ve bir gün

Ya kalemin hiç bitmeyeceği sandığı mürekkebi

Yada kağıdın ömrü biter.

İşte o zaman ispatlanır 

Hiç bitmez dediğimiz şeylerin bir gün biteceği.', 'Kağıt ile kaleme benzer çoğumuzun sevgisi Kalem sürekli yazmak  Kağıt ise zaman ister Çünkü kısadır kağıdın ömrü Kalem bir sürü kağıda yazab...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kalem-kagit-iliskisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yıldıza Hasret', 'gece-yildiza-hasret-ahmet-kurt-eecyw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşin battığı günden bu yana, 

Yıldızlara hasret kaldı geceler.

Deliller toplandı geldi divana, 

Gerçeklere hasret kaldı geceler.

Sitemsiz hayatın kendisi sitem, 

Duraksız yolların sonudur matem, 

Nedir bu ateşsiz bacadan tüten, 

Hayallere hasret kaldı geceler.

Umudun söndüğü noktaya yakın, 

Canlandı varlıklar başlıyor akın, 

Hangi yol olursa gözünü sakın, 

Güzellere hasret kaldı geceler.

Yırtındı, çırpındı soluyor yaprak, 

Açmış gözlerini arıyor toprak, 

Kurdoğlu feryadı figanı bırak, 

Yiğitlere hasret kaldı geceler.', 'Güneşin battığı günden bu yana,  Yıldızlara hasret kaldı geceler. Deliller toplandı geldi divana,  Gerçeklere hasret kaldı geceler. Sitemsiz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-yildiza-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurgular,', 'vurgular-caglar-akarsu-eryc2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...

Bir elinde davul, bir elinde tokmak, 

Meydana dökmüşler, tüm kelimeleri, 

Kağıtlar üzerinde bir rakkase

Ayaklarını yere vur vura, 

Fikirlerini  orta yere, vurguladı

Kalp atışlarını  zorlarken notalar, 

Ritim havasına girdi tüm insanlar, 

Gözler, dalmışken çok uzaklara, 

Beden sanki  candan ayrı

Derin sıkıntıların telleri, 

Tın-tın ötüyordu, bu gece, 

...

Kendi kendini, çalmak istedi, 

Bırakıp da gitmek istedi, 

Vurdular bir mühür mantığına, 

Düşüncelerin tümünü silmek, istedi

..

Kemanların tiz bir sesi, 

Anlamların  ortada birleştiği, 

Dudaklardan dökülen sözler, 

Suskun bir ünlemin yalnızlığında, 

Ellerinde ıstıraplı dokunuşları, 

Vurgun yemiş dalgıçların, 

Mercanların renginde kalmış, 

Biçare yazılarında kirli kelimeler, 

Taşınırken, akıl  süzgeçlerine, 

Anlatamadığım tüm vurgular, 

Ezerken tüm benliğimi, 

Beni yine benden aldı ve geçti, 

...

2003-08-31', '... Bir elinde davul, bir elinde tokmak,  Meydana dökmüşler, tüm kelimeleri,  Kağıtlar üzerinde bir rakkase Ayaklarını yere vur vura,  Fikir...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/vurgular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güçsüzler', 'gucsuzler-caglar-akarsu-1g7w4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arşa yükselirken tüm alem, 

 Bir meddücezir başlangıcında, 

 Dünya da, tüm buzlar erirken, 

Birden bire sular yükseldi, 

Zaman tünelinden geçerken, 

Zirvelerde sonsuz, ormanlar sonsuz

 Kavuşmak, için açtılar bağırlarını, 

Binlerce bitki yayıldı orta yere, 

Ağaçlar ne kadar kısa ise, 

Gövdeleri yere yakın, 

Başları toprağa eğik

Rüzgarlar acımasız, 

Yüreğini hiç yıpratamadı, 

...

Kayın yapraklarına  uçurduk

Sözler bir hüzün  gibi kaydı, 

Yokuşları tırmanmak  güç ise, 

Gücü elinde tutabilmek, , 

Marifet devşirmek gibi güzeldi.

...

Yeşermişti her cins ağaçlar, 

İçinde buruk bir hüzün, 

Kor gibi yaktı geçti, 

Göz yaşlarımı taşıdım, 

Can versin, diye tüm köklere

Ne kadar çaresizim biliyorum, 

Ağaçsız ve susuz kalmışım, 

  Bir meddücezir, iniş ve çıkışlardayım.

....

31/ağus/2003', 'Arşa yükselirken tüm alem,   Bir meddücezir başlangıcında,   Dünya da, tüm buzlar erirken,  Birden bire sular yükseldi,  Zaman tünelinden ge...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gucsuzler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincikler Diyarında', 'gelincikler-diyarinda-hayati-yavuzer-n89ry', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Valandova, Çalıklı’da

Gelincikler içindeyim

Boşalmış köyleri gördüm

‘Neden? ’deyim, ‘niçin? ’deyim 

Hıdırellez günlerinde

Yıkanmış bir yeşillik var

Yağmur taradı, ben ördüm

Mor sümbülün saçındayım

Hangi hoyrat yel savurdu

Boşalttı bu güzel yurdu

Bilmem hangi iklimdeyim

Bilmem ayın kaçındayım

Zaman tıkır tıkır saat

Yelkovanın peşindeyim

Gelincikler diyarında

Bir pınarın başındayım

Çağlar akıyor elimden

Yüzyılların yaşındayım

Sona ermiş bir masalın

Sonsuza dek peşindeyim

(06 Mayıs 2001/Çalıklı-Valandova)', 'Valandova, Çalıklı’da Gelincikler içindeyim Boşalmış köyleri gördüm ‘Neden? ’deyim, ‘niçin? ’deyim  Hıdırellez günlerinde Yıkanmış bir yeşil...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gelincikler-diyarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimelerin Efendisi', 'kelimelerin-efendisi-oguzkan-bolukbasi-kzuha', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanıdık geliyor kelimeler

Çünkü anlattıklarım yaşananlar

Çok farklı değil hayatlar

Çok farklı değil umutlar

Ben de söyleyecektim demez miyiz çoğu zaman

Bir cümleyi duyduğumuzda 

Ya da bir sevdayı yaşadığımızda

O yüzden anlaşırız çoğu kez ve kavgalıyızdır çoğu kez

Ama kimse bilmez

Nasıl zordur kurmak can alıcı cümleyi

Fethetmek kaleyi canlar yakmadan kanlar dökmeden

Tek çiçek koparmadan bahçeleri önüne sermek sevgilinin

Yani ta kendisi olmak kelimelerin efendisinin

Bir gün sana söylenmemiş sözcüklerle geleceğim

Pencerede ol 

Perdeler ardına kadar açık yüzün cama dayalı olsun

Ya da kapının önüne çık

Sesimi duymak kolay olsun

Çünkü bir kez söyleyeceğim yalnızca bir kez

Sonra söylenmemiş sözleri sana bırakıp

Ben rüzgarla uçup gideceğim', 'Tanıdık geliyor kelimeler Çünkü anlattıklarım yaşananlar Çok farklı değil hayatlar Çok farklı değil umutlar Ben de söyleyecektim demez miyiz...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kelimelerin-efendisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marmara Depremi', 'marmara-depremi-yusuf-canturk-oqw9r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir   felaket   yaşadık,  17  Ağustostu,  bu  gece.

Karşı   koymak  ne   mümkün,  deprem  denen  o  güce.

Korkunç   bir  sarsıntıydı, tatlı  uykuyu  böldü.

Saniyeler   değil,  sanki,,  asırlar   sürdü.

                                                              

Kabus  ile  gerçek   birbirine   karıştı.

Kurtulanlar,   kaçanlar   zaman   ile   yarıştı.

Sokaklar,   meydanlar   biranda   mahşere  döndü, 

Gece   aydınlık,  yıldızlar  normal dan   parlak   göründü.



Mahşer   yerine   dönen   bu   memlekette, 

Göçük   altında   kalan   canlılar   imdat   demekte, 

Kimi  sağa,   sola koşuyor, sarmış  da  korku  ve  dehşet, 

Kimi  “yavrum”  diye  bağırıyor,  endişesi   tek! 



Sis   perdesi   kalkar,  kalkmaz   şafakta, 

Korkunç   bir   manzara   göze   görünen, 

Nice   Canlar   yakalanmış,   uykusunda,   yatakta, 

Binlerce   bina   var  ki,   enkaz   olup   yere   serilen.



Vurgun   yemiş  Yalova,  Kocaeli,   Adapazarı, 

Birbirine   karışmış   halkın   feryadı,   ah-u  zarı.

Korkunç   boyutta   depremin   görünen   zararı, 

Yasa   boğdu,  asrın   felaketi,   yâr-ı,   ağyârı.



On binler   yaralı,   binlerce   göçük, 

Depremin   merkez   üssü,   o   şirin   Gölcük.

Öyle   sarmış   ki   insanları   korku   ve   ilk   şok! 

Yazık   ki   can   kaybı,   on   binden   de   çok! 



İlk   tepki,   sağ   kalan   konu,   komşudan, 

İmdat   çığlığını   duyan,   yardıma   koşan; 

Kimi   tırnakla    kazıyor   betonu,   kimi   kazma,   kürek, 

Birleşmişler   tasada,   olmuşlar   tek   yürek.



Yıkıp   geçmiş   Marmara’yı   depremin  (7.4)    şiddeti, 

Gözyaşı   döksek   de,  yakın   çekimlerde,   canlı   yayında.

Yas   tutsa  da  bütün   Dünya   Türk’ün   yanında, 

Ancak,   yaşayan  gerçekten   hisseder   korkuyu,   dehşeti.)



Bir   turistik   belde   ki,  fındıkla   tanınan,  aynı   bölgede, 

Dağları,   bağları,  halâ   yeşil   Değirmendere, 

Sıcakta,   çınar   altlarında,   gölgede, 

Serinlemiştim   deniz   kenarında,   belki,   yüz   kere.



Ne   çay bahçesi  kalmış   şimdi,  ne  de,  gönül   sarayı, 

Deniz   yutmuş   evleri,   işgal   etmiş   karayı.

Sanki   kavrulmuş   gibi   Ağustos   sıcağında

Binalarla,   sakinleri   yatıyor   denizin   kucağında.



Nerede   deniz   biter,   nerede   başlar  kara? 

Deniz  bahçe   sanki,   çınarlar   su   altından   boy   atmış, 

Çay   bahçeleri,   gazinolar,   deniz   dibine   batmış, 

Görünen   o  ki,  insana   elem   veren,   korkunç, manzara.



Bir   çocuk   feryadı   duyulur   göçük   altından, 

Bilinmez   ki,   apartmanın   hangi   katından? 

Neden   çocuk   ağlaması   var   da   ninni   sesi   yok? 

Artık   Onların  şefkâte,   sevgiye   ihtiyacı   çok.

)



Ne   kefen,   ne   tören,   yaratıldı,  toplu   mezarlar, 

Kazma,   kürek   yerine,   makine   ile   kazarlar.

Bazıları  için   kılınmış   normal    cenaze    namazı, 

Kimilerinin   ardından,   ne   yazık  ki,   bundan  da  azı.



Bir   depremzede,   canlı   kalmış,   duyamamış   sevinci, 

Beş   çocuk   kaybetmiş,   her biri,   birer   İnci! 

Yok   olunca,   ömür boyu   kazancı,   birikimi, 

Ne   çalışma   gücü   kalmış,   ne  de   yapacak   bir   işi.



Kimi  ayağını   kaybetmiş,   kimi   kolunu, 

Kimi   feleğini   şaşırmış,   kimi   yolunu.

Ölüm   yakınına   gelip   çatmış,   bakmadan   yaşa, 

Zengin   iken,   birden   muhtaç   olmuş   ekmeğe,  aşa. 



Varını,   yoğunu   kaybedip   kalsa   da   muhtaç, 

İstemesini   bilmez   ki,   alışık   değil! 

Alırken   mütereddit,  üstelik   de   utangaç, 

İçi  buruk   olsa   da,   yılışık   değil.

)

Yasa   büründü   bir   anda,   güzel   yurdumuz, 

Kim   bilir,  ne  ümitler   vardı   ne  hayaller  kurdunuz

Kiminiz   depremde   yavrunuza   siper   oldunuz, 

Kiminiz   ölümden   dönüp,   yeniden  hayat   buldunuz.



Haftalar  önce, Güneşi   karartmıştı   dünyamızın   uydusu

Yunan   da   yaşadı  depremi,   az   da   olsa,   şiddeti, 

Belirdi  her  iki   toplumda,  yakınlaşma   duygusu, 

Acep   var  mı,   bunların   bilinmeyen   hikmeti? 



Milyonları   cezbeden   güzel   Marmara   bölgesi, 

Depremle   düştü   üstüne,   ölümün   gölgesi.

Tarihte   yaşanmamış,   felâketin   böylesi, 

Öyle   çok   suçlu   var   ki,   affedilmez   tövbesi.



Can   korkusu   yüreklere   hakim   olunca, 

Moraller   bozulup,   ümitler   de   solunca, 

Göç   etmek   zorunda   kaldı   insanlar.

Ayrılık   zor   ama,   gönüllerde   isyan   var.



Göçenler   duygusal   olmakta   ne   kadar   haklı.

Terk   edilen   yerlerde   bin bir   hatıra   saklı.

Ayrılmak   kolay   değil  bu   yerden,  çok   da   firaklı, 

Mal   ve   can   kaybedenlerin   geride   kalır   aklı.



Kurtulanlar   veriyor    her   türlü  yaşam   savaşı

Paylaştık,   paylaşmalıyız   ekmeği,  aşı.

Silinmeli   Canların   akan   göz   yaşı, 

Sürmeli   maddî   ve   manevî   dayanışma   yarışı.



Geride   kalmış   binler   kimsesiz,  binlerce   yetim, 

Bağrına   basacak   fert  ve   fert   asil   milletim

Göstermenin   tam   zamanıdır  bilinen   hasletin, 

Sarsın   Onların  tümünü   sevgin   ve   şefkatin



Bütün   Dünya   uzattı   yardım    elini, 

Gönül   kapısı   açıldı,   bazen   gözlerde   yaş, 

Eser   görünce   her  yönden,   dostluk   yelini, 

Anladık   ki,  yalnız  Türk   değilmiş,  Türk’e  arkadaş.)



Yurt   içi,   yurt   dışı   yardımlar  sel   gibi   aksa  da, 

Hâlâ   kimi  aç,   kimi  açıkta,   kimi   de   hasta, 

Çare   bulunmazsa   acele   her   hususta, 

Depremzeler   devamlı   kalır,  öylece   yasta.



Can   kaybı   yüreklerde,  ancak  buna   çare   yok, 

Maddi   kayıplar   için   muhtaç   olsak  da,  yabana   ele, 

Bölge   insanı   şikayetçi   olsa   da,  geçmeden   ilk   şok, 

Yaraları   sarmada   birlikteyiz,  Devlet,   millet  el  ele.



Silinir   mi   kolay,   kolay   bu   dehşetin   izleri? 

Yıllar   sürer   ruhtaki,   bellekteki   gizleri, 

Acımız   öyle   büyük  ki,   tüm   ulusça   yastayız

Depremzeler   gibi   biz   de,   ruhen  çok   hastayız.





Her   an   sallanır   gibiyiz, gerçekten   sarsılmasak   da! 

Depremin   şiddetini   hâlâ   yüreğimizde   taşıyoruz

Aylar   sonra   olsa   da,   depremin   korkusuyla, 

Yatıp  kalkıyor, mecburen artçı   şoklarla,  yaşıyoruz.)



Sanki   masal   ülkesinde   yaşar   gibiyiz.

Her   adımda   yeri,   göğü   titreten, 

Meşhur   devin   korkusundan   tedirginiz   çok.

Yazık   ki  onu  etkisiz   kılacak   kahramanımız   yok! 



Her   tarafta   dolaşıyor   rivayetler,   yalanlar, 

Öyle   çok   ki   tevatüre   inananlar,  kananlar, 

Bu   nedenle,  sokaklarda   geceleyip   kalan  var.

Vicdansız  ve   ahlaksızdır  kargaşaya   sebep   olanlar? 



Durumdan   faydalanan   vurguncular   olacak, 

Eğer   varsa   vicdanını  bir   tarafa   bırakarak, 

Bir   tarafta,   gitgide   fakirleşen   halk, 

Yine   devam   edecek,   kayırma   ve   zengine   kıyak! 



Vicdansızlar,   güya,   halkın   yuvasını   yaptılar! 

Yılların   tasarrufunu   yalanlarla   kaptılar.

Doğru   yol  dururken,   eğri   yola   saptılar, 

Tanrıya   değil   de,   yalnız   paraya   taptılar.)



Evsiz,   barksız   kalan   yüz   binler   olunca, 

Çadır kentler   kurulmuş,   ama   ihtiyaca   yetmiyor

Köyler,   kenar   mahalleler   gözden   ırak  kalınca, 

Yardımlar   yerli-  yerine   gitmiyor,  istekler  de bitmiyor.



Kış   mevsimi   çetin   geçen   doğa   olayı, 

Yağmuru,   çamuru,   soğuğu   ve  lapa,  lapa   karı, 

Bulunmazsa,   öncelikle,  barınmanın   kolayı, 

Depremzedeler   çeker  yine   sıkıntıyı,  zararı.



Dönmek   mümkün   değil   hemen   normal   yaşama, 

Yaralar   sarılacak   mutlak,  aşama,   aşama.

İhtiyaç   var   yine   de    tutunacak   sağlam   bir   dala, 

Bunu  Devlet- Millet   birliğinde,  biraz  da  kendinde  ara! 



Onların  endişesi,  gelecek,  iş   ve   daimi   konut, 

Devlet   adım   atmış   bu   yönde,   gerçek   ve   somut, 

Yuvasız   kalan   yüz   binlere  bu,   büyük   bir   umut.

Yaşama   sarılma   vakti   artık,  endişeyi,   korkuyu   unut! 



     Yusuf  Cantürk(E.Hv.Kur.Alb.)                                   8Eylül 1999)', 'Bir   felaket   yaşadık,  17  Ağustostu,  bu  gece. Karşı   koymak  ne   mümkün,  deprem  denen  o  güce. Korkunç   bir  sarsıntıydı, tatlı ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":147,"source_url":"https://www.antoloji.com/marmara-depremi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakarış', 'yakaris-yusuf-canturk-6kz9e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Otuz  sene  dile  kolay, bir  yastığı  paylaştık, 

                Nice  badireler  atlattık,  mutluluğa  ulaştık.

                Son  bir  sene  içinde  kader  ağlarını  ördü, 

                Bunca  insan  içinde  TÜMÖR  seni  mi  gördü? 



                Ameliyat  dediler,  saatler  geçmez  oldu, 

                Endişe ve  üzüntü  yüreğimi  doldurdu.

                Doktorlara  sormadan  melül, mahzun  bakardım.

                Defalarca  TANRIYA  şifa  diye  yakardım.



                Zaman  oldu  seni,  üzdüm,  affını  dilerim.

                Gözyaşımı  tutamaz  mendil  yetmez  silerim.

                Evimizde,  her yerde  birlikteyiz  sanki, 

                Sensiz  nefes  almak  bana,  öyle  yavan ki.



                Ben  şimdi  sensizim,  dayanacak  dalım  yok, 

                Bu  dünyada  yapayalnız,  sevgilim  yok, yarim  yok.

                İsterim ki  seninle  ben  de  hemen  öleyim, 

                Hasret  kalmam  gül  yüzüne,  her  an  onu  göreyim.



                TANRI  duymuş  yakarışı,  gönül  sesimi, 

                Anladım  ki  bağışlamış  bana, güzel  eşimi.

                Açar,  açmaz  gülümsedi  yeşil  gözleri, 

                Tutuşunca  ellerimiz,  ‘şükür’ oldu  sözleri

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Otuz  sene  dile  kolay, bir  yastığı  paylaştık,                  Nice  badireler  atlattık,  mutluluğa  ulaştık.                 Son  bir ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yakaris-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vah Diye Diye', 'vah-diye-diye-murat-demir-4a6wp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bülbül terk eğlemiş, bağı bahçeyi

Tanımıyor artık, gülü çiçeyi

Dost etmiş kendine, derdi çileği

Ağlar zarı zarı, vah diye diye

Yaban olmuş, hayallerde geziyor

Yaman olmuş, her hileyi seziyor

Onu o yerlerde, görenler diyor

Ağlar zarı zarı, vah diye diye

Aşkını yitirmiş, günü şaşırmış

O gönül küpünden, sabrı taşırmış

Düşmüş bir kötüye, yandıkça yanmış

Ağlar zarı zarı, vah diye diye

Ela gözlerini, pınar eylemiş

Talihine küsmüş, bir gün gülmemiş

Sevmiş ama, sevdiğine ermemiş

Ağlar zarı zarı, vah diye diye

Murat der can dostum, ah ile darda

Hala da yüreği, vafasız yarda

Çareler tükenmiş, bulunmaz fayda

Ağlar zarı zarı, vah diye diye', 'Bülbül terk eğlemiş, bağı bahçeyi Tanımıyor artık, gülü çiçeyi Dost etmiş kendine, derdi çileği Ağlar zarı zarı, vah diye diye Yaban olmuş, ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vah-diye-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Güzel Yapan Benim', 'seni-guzel-yapan-benim-murat-demir-rxyam', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen kendini, güzel sanma

Naz a girip, havalanma

Eller güzel derse kanma

Seni güzel yapan benim, benim aşkımdır

Gel deyince, gelmiyorsun

Sev deyince, sevmiyorsun

Oysa iyi biliyorsun

Seni güzel yapan benim, benim aşkımdır

Benden başka, seni seven

Varmıdır, gönlünü veren

Bilmiyorsan, iyi öğren

Seni güzel yapan benim, benim aşkımdır

Sen üzülsen, ben ağlarım

Ateşte korda, yanarım

Kıymetini, bil sevdamın

Seni güzel yapan benim, benim aşkımdır', 'Sen kendini, güzel sanma Naz a girip, havalanma Eller güzel derse kanma Seni güzel yapan benim, benim aşkımdır Gel deyince, gelmiyorsun Sev ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-guzel-yapan-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaman Kız', 'yaman-kiz-murat-demir-gspjg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç ağlama, can ciğerim boşuna

Zaman bitti, artık bizden iş geçti

Bu bir gerçek, gitmesede hoşuna

Ölümüne sevmek için, yaş geçti

Sen nazlıydın, ben havalı bir zaman

Uçuyorduk, havalarda kanatsız

Bitmeyecek, sanmış idik bu derman

Hani nerde, güzelliğin yaman kız

Biz bu bağın, yaprağını soldurduk

Su vermek kar etmez, kökler kurumuş

Biz güllerin, bülbülünü öldürdük

Can vermek imkansız, beden çürümüş

İnadına böyle, bittik ikimiz

Ne sen bana geldin, nede ben sana

Aşkın ateşiyle, yandı içimiz

Ne hikmetse, olamadık yan yana

Sende yalnız, bende yalnız, şimdiyse

Yaşıyoruz, ayrı ayrı yerlerde

Sen çocuksuz, ben çocuksuz ah ile

Bekliyoruz, sonumuzu evlerde

Gözün aydın olsun, dediğin oldu

Senden başkasıyle, olamam derdin

Bu gönül gülleri, sonunda soldu

Benide tükettin, sende tükendin', 'Hiç ağlama, can ciğerim boşuna Zaman bitti, artık bizden iş geçti Bu bir gerçek, gitmesede hoşuna Ölümüne sevmek için, yaş geçti Sen nazlıyd...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yaman-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbaharinan', 'sonbaharinan-cemal-karsavran-oc87m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sesinin boguklugunda kayboldum

yillar vardi yalnizliginda

ulu bir cinardi bedenin

sonbaharla yaprak dökercesine

siziliydi

agriliydi sanciliydi

bahar gelse diyordu sanki

içinden

günese vurulsam

pencerenin camindan

perdeyi aralayipta 

güneşliği kaldırsam

güne dönüp 

yeniden yeniden doğuşa

gercek olan gündür dünden kalan

dolasıp boylum boylum

sonbaharinan

31-10-2002', 'sesinin boguklugunda kayboldum yillar vardi yalnizliginda ulu bir cinardi bedenin sonbaharla yaprak dökercesine siziliydi agriliydi sanciliy...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sonbaharinan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-cemal-karsavran-z99mv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'düslerin renkli gökkusagi olsun 

geceyle

hiç bir sekilde hiç bir sey için 

kendini zorlama

seni dolu dolu yasamak istercesine

hayal ederak yazsamda

bir düs ülkesi yüregim

düslerimde paylasmak

düslerimde ayak izlerine gelmek

düslerimde ask

düslerimde ayak izlerinle 

gidiyorum deme diyorum sana

askimi yüregimde sakliyorum

oldugum yerde bekleyecegim

seni bagrima basmak için

beni yüregnde bul

unutma...

10-11-2002', 'düslerin renkli gökkusagi olsun  geceyle hiç bir sekilde hiç bir sey için  kendini zorlama seni dolu dolu yasamak istercesine hayal ederak y...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unutma-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sükrandir Bize', 'sukrandir-bize-cemal-karsavran-jywzq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'koca bir bahcesin yillar içinde

aynalarin yalani yok bu sensin 

yüreginden kopup gelen sevgi

kayip kiyilar ve dolunayla

ayni kaderi paylasan sen ve ben

bir sihir ask ve sevgi

duygular sir gibi kalsada kalbimizde

sakli hayat bu iki kelimede 

sevgi agacisin gönül yolunda

irmaksin iliman akdeniz sicakliginda

bir çinarin kenarindan akan

kan yürür damarlarimda

kalp yaslanmaz biliyorsun

ilk gençligin korkak sevinciyle

noktalanir simsicak busemizle

sevda yasanir elele kolkola

kürek cekeriz firtinalara

limanini bulamamis kaptaniz

siginiriz gözlerin koylarina

sevi güzelliktir sükrandir bize

14-12-2002', 'koca bir bahcesin yillar içinde aynalarin yalani yok bu sensin  yüreginden kopup gelen sevgi kayip kiyilar ve dolunayla ayni kaderi paylasan...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sukrandir-bize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hih', 'hih-cemal-karsavran-zosdp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayat bir 

mer

di

ven

kamburunu tasirim yillarin

yas otuz sekiz

inerim cikarim

son kata ne kaldiki

sunun surasinda

nefesim kalir basamaklarda

bitti 

bittim 

biterim

is ekmek mutluluk

inerim cikarim hergün

ayni saatte

mer

di

ven

le

ri

hih..

11-12-2002', 'hayat bir  mer di ven kamburunu tasirim yillarin yas otuz sekiz inerim cikarim son kata ne kaldiki sunun surasinda nefesim kalir basamaklard...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takma Dislerim', 'takma-dislerim-cemal-karsavran-0s2tj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çekersin yil oldu 

kahrimi..

ögütürsün tuz buz

midemin bayramligi

agzima ilk taktigimda

alisana kadar 

yedin bitirdin beni..

senden öncesi yoktum

eriyen mumdum

günbe gün

alistim..

alistin..

sevdigimden önce

bakarim kancalarin ve dubalarina

özenle...

cikarir koyarim her gece

yüzersin bir bardak suda

unutamam seni 

aklimdasin..

sen yoksan

bende yokum 

artik...

takma dislerim

12-12-2002', 'çekersin yil oldu  kahrimi.. ögütürsün tuz buz midemin bayramligi agzima ilk taktigimda alisana kadar  yedin bitirdin beni.. senden öncesi y...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/takma-dislerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemi', 'gemi-cemal-karsavran-0x0xo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bana deme 

deli dolu

gülünce 

senin yüzüne

içimde binbir gami

yüregim 

sevgilerle

rotasini kaybetmis 

gemi

21-11-2002', 'bana deme  deli dolu gülünce  senin yüzüne içimde binbir gami yüregim  sevgilerle rotasini kaybetmis  gemi 21-11-2002...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gemi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Olur Düslerim', 'mavi-olur-duslerim-cemal-karsavran-1gt37', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'mavi olur düslerim

umutsuz bakislarimda

gözlerinin yesilinde kaybolurum

sari sari yapraklar düserken topraga

saclarinin teline tutunmak isterim

kapi önüne cikarim

agaçlar yaprak dökerken

bende düserim saclarinin telinden

içimden bir irmak akar

mavi sularinda yesili yikayarak

uzaklarda cok uzaklarda 

bir ceylan balasi iner su kenarina

ürkek vede korkak

bir avcidir atesiyle yakan yüregini

rahvana gider caliliklarin arasindan

kaçmak kurtulussa

kurtulmustur kacmaktan

mavidir düşlerim

01-11-2002', 'mavi olur düslerim umutsuz bakislarimda gözlerinin yesilinde kaybolurum sari sari yapraklar düserken topraga saclarinin teline tutunmak iste...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mavi-olur-duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Yarina Kaldi', 'umut-yarina-kaldi-cemal-karsavran-xl30b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'demircinin balyozudur

anamin nasirli elleri

kaderini parçaladi

kiraç topraklar üstünde

günes tepeden vururdu

bebek gölgede uyurdu

çavdar tarlasinda

temmuzun onbesinde

bir of dedi dogruldu

gözleri ufka daldi

bu yilda kisi çikaririz 

umut yarina kaldi

08-11-2002', 'demircinin balyozudur anamin nasirli elleri kaderini parçaladi kiraç topraklar üstünde günes tepeden vururdu bebek gölgede uyurdu çavdar tar...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umut-yarina-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala', 'hala-cemal-karsavran-96tf3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tadidir mutlulugun

yasanilasi hayatta

paylasmaya yürek gerek onuda

bir öpücük özlem olur

tatli söz hasret

duygular çok güzel hayallerdir

korkak parmaklarla

dokunuldugunda tenine

yumusak

kaybolmak mavisinde

gözlerin

ilik meltem eser

denizlerinde

sonbahara dönmüs

yazdan kalan sicaklik var 

yüzündeki tebesümünde

hala...

13-12-2002', 'tadidir mutlulugun yasanilasi hayatta paylasmaya yürek gerek onuda bir öpücük özlem olur tatli söz hasret duygular çok güzel hayallerdir kor...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hala-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyle Gülen Gözlerim Var', 'geceyle-gulen-gozlerim-var-cemal-karsavran-upvh6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'simdi sensiz dalacagim geceye

havalarda o kadar kötü ki 

yavas yavas yagmurla islanaraktan

konusmadan yürüyecegim 

sehir isiklariyla

sen bana kalacaksin 

benim küçük bebegim 

seni dizlerimde tasiyacagim sevgiyle 

basini kucaginda gözlerini gözlerimde 

seni sevmekten korkmayacagim

kanimin her damlasinda

paylasmasini bilirim baharla

benim yüregim sevgi dolu

ve yüregimde sen

sevdigim kadar seviyorum senide 

ikimizin arasinda bir sey 

ince bir iletisim

istemiyorum kiskanilmak

kader birligim yok kimseyle

mutlu olmadigim içindirki

insanlari seviyorum

siirler kader dostum

karsilikli tutkular gerektirmedikce 

seni seviyorum diyorum

bu benim seni insan olarak

yüregini seviyorum anlamina gelmeli

kendi duygularimla 

aski kendimde yaratiyorum

hayalimde göklere cikariripta

beni ben yapan duygusalligimi

kendi kendime olan aski

yüregimi sevmeyimde kimi seveyim

düslerinde mutluluklar 

geceyle gülen gözlerim var

25-11-2002', 'simdi sensiz dalacagim geceye havalarda o kadar kötü ki  yavas yavas yagmurla islanaraktan konusmadan yürüyecegim  sehir isiklariyla sen ban...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/geceyle-gulen-gozlerim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islakligi Var Hala Tadinla', 'islakligi-var-hala-tadinla-cemal-karsavran-kclkg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'deli bir firtinaydin gecede

akdeniz sicakligiydin yatagimda

ellerim yüzün ter içinde

püfür püfür esen rüzgarla

yirtarken geceyi rüzgar

sicakliginlaydin sarilisinla

özlemlerim dag doguruyorken

fisildadigim sarkilarla

geceyi sana yazdim

sen kahkahaydin 

uykularimda melektin gülümseyen

öpüsümle uyandiginda

ak pembeydi yanagin 

sicacik sütün bugusunda

seni içtim sabahin ayazinda

dudaklarindan tebessümünle

bir buse aldigimda

islakligi var hala tadinla

15-12-2002', 'deli bir firtinaydin gecede akdeniz sicakligiydin yatagimda ellerim yüzün ter içinde püfür püfür esen rüzgarla yirtarken geceyi rüzgar sicak...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/islakligi-var-hala-tadinla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemin Çigligidir Sevgiye', 'ozlemin-cigligidir-sevgiye-cemal-karsavran-4n5g7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'askimiz ates kadar yakici 

sevgiyle gülen gözlerimiz var 

sen benimle ben seninleyken

bir sehirdir cok uzaklarda yanan

bir ben oluyorum masumiyetimle 

bir senin tas araligindan bakan gözlerin

yanyana yaslanmis iki dag gibiyiz

eteklerinde boylum yesiliyle

candan cana soylenen türküdür

avuc içlerimizin sicakligi

gözlerinin içinden gülüslerin

bir özlemin çigligidir sevgiye

02-11-2002', 'askimiz ates kadar yakici  sevgiyle gülen gözlerimiz var  sen benimle ben seninleyken bir sehirdir cok uzaklarda yanan bir ben oluyorum masu...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozlemin-cigligidir-sevgiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Sessiz Damlalarıyla', 'sevginin-sessiz-damlalariyla-cemal-karsavran-u1e4s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen benim sığınağımsın bende senin 

bana yüreğini verdin bende sana 

kolay mı almak bundan sonra 

çoksun bende bunu unutma 

yasayacak bu sevda ve bu aşk 

kimseler bilmeyecek sende bilmeyeceksin

yaşayacak yüreğimin en nadide yerinde

Çünkü bana can veren sensin 

zaman zaman yüreğim sığınaksız 

yüreğim üşümelerde kalacak biliyorum

ama içinde hep sen olacaksın 

koparamayacak hiç kimse 

hüzün bulutları dolanmakta başımda 

her an yağmaya hazır ve yağmakta

yüreğin benim sıcak kollarımda yüreğimde sıcacık 

hissediyorum şu an bile 

sen benim marinamsın bende senin 

hüzün bulutları dolu dizgin aşk

sicim gibi dökülmekte gözlerimden 

sevginin sessiz damlalarıyla 

01-12-2002

Cemal Karsavran', 'sen benim sığınağımsın bende senin  bana yüreğini verdin bende sana  kolay mı almak bundan sonra  çoksun bende bunu unutma  yasayacak bu sev...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevginin-sessiz-damlalariyla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Hayat Verende', 'ben-hayat-verende-cemal-karsavran-q6ejs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen narcicegisin gülün pembesinden

baharla dogan yüreklere

tadidir öpüslerimizin

narcicegi tadinda

sen yüreksin yüreginden öte

dost canlisi dost yüreklere

içinden sevda akan irmaksin

engebeli topraklarda

gel desem gelirim diyecek kadar yürekli

sev desem engel tanimazsin

sen senden öte varsin

seviyorum diyene

paylasmak umarsizca 

siginmak gecelere

sen narcicegi tadinda

ben hayat verende..

21-11-2002', 'sen narcicegisin gülün pembesinden baharla dogan yüreklere tadidir öpüslerimizin narcicegi tadinda sen yüreksin yüreginden öte dost canlisi ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-hayat-verende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Ayı Gelince', 'eylul-ayi-gelince-mehmet-ali-cibikli-gw9gb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her yer toz toprak olur, 

Rüzgarlar eser daha bir hızlı, 

Yemyeşil bahar mevsimine inat, 

Yapraklar sararır önce usul usul

Ve ardından yere dökülür çaresiz, 

Geleceği karanlık yola koyulur

Eylül ayı gelince...

Kuşlar en içli ezgileriyle, 

Ağıt yakarlar solan güllerin ardından, 

Acılarını haykırırlar çekinmeksizin.

Ne anlayan olur hallerinden, 

Ne birileri gelip tutar ellerini.

Defalarca ölürler batan güneşle, 

Çırpınıp dururlar gün boyu umutsuz, 

Eylül ayı gelince...

Veda türküleri söylenir, aşk istasyonlarında, 

Ardı sıra ayrılıklar başlar sıra sıra.

Yarınlar koyu karanlık, kalpler yaralı, 

Umutlar keder yüklü, darmadağın.

Damla damla yaşlar süzülür gözlerden, 

Çaresizlikler filizlenir, ince ince

Mendiller ıslanır, gözler nemlenir, 

Eylül ayı gelince...', 'Her yer toz toprak olur,  Rüzgarlar eser daha bir hızlı,  Yemyeşil bahar mevsimine inat,  Yapraklar sararır önce usul usul Ve ardından yere ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/eylul-ayi-gelince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmistim Seni', 'sevmistim-seni-guner-kaymak-8vtna', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmistim seni gok yuzunde yildizda

bulutlar sahit yagmurlar sahit buna

Anliyorum seni inanmiyorsun sevgime

Bir gun yanacaksin bosa giden yillarina

Ayipliyorum seni neden baktin yuzume

Bu luzumsuz ask icin kiziyorum kendime

Degermiydi acaba soruyorum sizlere

Cok yorgunum ben efkarliyim hastayim

Bu ask yuzunden perisanim dustum dile

tovbe ettim bu aska olecegimi bile bile

Amsterdam/ 2003', 'Sevmistim seni gok yuzunde yildizda bulutlar sahit yagmurlar sahit buna Anliyorum seni inanmiyorsun sevgime Bir gun yanacaksin bosa giden yi...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevmistim-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Şey İstemedim', 'cok-sey-i-stemedim-i-brahim-bayraktar-nxmr2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağları devirmeni istemedim, 

İklimleri değiştir demedim, 

Buruk bir sevgi gösterisi, 

Kuru bir selâmını umdum.

Öyle ağdalı sözler sarf etme, 

Acı da söylesen kabulüm, 

Sade ve öz, anlaşılır dilde, 

Saf bir kelâmını umdum.

Ağıtlarımız birdi, sevinçlerimiz bir, 

Konuşmazsak bunları kim bilir? 

Aradaki engelleri yıkıp da bir bir, 

Meramını paylaşmanı umdum.

Çok şey istemedim senden; 

Selâmını paylaşmanı, 

Kelâmını paylaşmanı, 

Meramını paylaşmanı umdum.

Çünkü benim dostumdun, 

Ve halâ dostumsun...

01.09.2003', 'Dağları devirmeni istemedim,  İklimleri değiştir demedim,  Buruk bir sevgi gösterisi,  Kuru bir selâmını umdum. Öyle ağdalı sözler sarf etme...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cok-sey-istemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Gorevi', 'vatan-gorevi-guner-kaymak-6zzan', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cekecegiz basa gelen halleri

Dokecegiz goze dolan selleri

Bekliyecegiz bu bitmeyen gunleri

Uzulme sevgilim gelirim elbet

Bende istiyorum seninle olmak

Her zaman seni yanimda gormek

O eski gunlere cabucak donmek

Istiyorum bir tanem donerim elbet

Yapmam gerekiyor  bu vatan gorevi

Alirsam teskere donerim  hemen geri

Hasretinle sevgilim oldum serseri

biterse askerlik donerim elbet

 Aybasti / Ordu /09.11.1980', 'Cekecegiz basa gelen halleri Dokecegiz goze dolan selleri Bekliyecegiz bu bitmeyen gunleri Uzulme sevgilim gelirim elbet Bende istiyorum sen...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vatan-gorevi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sana Yönlendir', 'beni-sana-yonlendir-ugur-arslan-9or5k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Telefon numaranı bana yönlendir bundan sonra 

Arayan benden duysun sesini 

Ben anlatayım her günün, bütün ömrünün efsanesini 

Bütün hilelerini benden bilsinler senin 

Bütün yalanlarını ben söyledim sevdaların 

Her ayrılığın fâiliyim bundan sonra 

Ben yalancı, ben zalim, ben kaçak 

Ben sözünde durmaz, ben kazandığı gün çekip giden... 

Benden bilsinler; Ben her hikayenin katili. 

Gamzelerine astığın suçluluğu, 

Gençliğimin firâri fikrine yönlendir 

Arayan benden sorsun tarihinin ağır günahlarını 

Bırak benden bilsinler bu ayaklanmayı 

Bütün ipuçlarını bende arasınlar bu eylemin 

Bende kurulsun adaletin mahkemesi 

Yakınların çeksinler ipimi 

Sen yine yalancı şahit, meçhul tanık 

Sen hep olduğun gibi kal yani. 

Sen yine bana ödet, 

Harcadığın bütün kıymetli değerlerin bedelini 

Benden bilsin herkes hayata taktığın borçları 

Ben bağladım masumiyeti haraca 

Ben kestim bütün sevmelerin yüklü hesabını 

Aşkın sesini duyduğumda kaçacağım ben 

Ben bütün uyruksuz oyunların öz vatanı 

Ben yalnızlığın acı sitemi 

Ben eylemci, ben firâri, ben yok! 

Silah kullanmam hiç. Aldatırım ben 

Sen dünyanın bütün denizlerini, kuraklığının terkisine yönlendir bundan sonra 

Özleyen bende baksın gözlerinin mavi demine 

Bırak benden bilsinler sulak yerleşim bölgelerine giden toplu göçleri 

Çağların bütün savaşlarında beni yensinler 

Bende arasınlar dünyanın aşka açlığının ekolojik nedenlerini 

Sen ölü kuşların kanatsız ruhlarına takılıp cennete git. 

Sen yine yalan söyle. 

Sen ihanet et her sevgiye yine 

Sen kavgalarımın ilk tokadını atıp kaçıver kalleşçe 

Sen sancı ol, deliliğimin koğuşu ol. 

Yokluk ol sen yine

Benden bilsinler bu evin viraneliğini 

Ben yıktım duvarlarını bütün binaların 

Ben korktum yüreğimi açık etmekten 

Kaçtım iste bir aşkın esaretine düşmekten 

Kaçtım iste 

Bütün gidişlerin sebebiyim aslında 

Ben korkak, ben deli, ben tokatçı. 

Ne kadar asil bir eylem de olsa 

Boyun eğilmez aşka! 

İçimde esaretin kütlesini duyumsadığım an 

geçerim verdiğin her güzellikten. 

Ben asırlık sevdaların kelepçesine tüneyen 

hain kusun ta kendisiyim. 

Sen en iyisi hiçbir şeyini yönlendirme bana 

Sen en iyisi beni sırtımdan vurmakla kal 

Yalnızca benden götürdüklerinden ibaret dur orada 

Yalnızlığımın bas ağrıları gibi kal aklımda 

Sen bana hiçbir şeyini yönlendirme sakın 

Sen aslında kendini benden sakın 

Hiçliğine alışmak mümkün gibi 

Sigarayı bırakmak gibi yani 

alışkanlığını üzerimden silkelemek 

Yani ilk gün çıkmıyorsun aklımdan 

İkinci gün daha çok özlediğim de doğru 

Diğer günlerin halini hatırlamıyorum bile 

Bildiğim bir şey var lakin; 

hala ara sıra sigara gibi sabrımı yokladığım. 

Dumanımda bir görünüp kaybolduğum 

Sen en iyisi hiçbir şeyini yönlendirme bana 

Batak sularımda devir dur 

Ara sıra ufkumda görünüp, kır dümenini sonra 

İnsanlığımın tarihine çektiğin bıçağı taşıyamıyor gururum 

Yokluğuna alışmayı sanki daha hassasiyetli buluyorum 

Sen en iyisi benden uzak dur 

Ben yalnızlığın acı sitemi 

Ben eylemci, ben firâri, ben yok! 

Silah kullanmam hiç aldatırım ben! .', 'Telefon numaranı bana yönlendir bundan sonra  Arayan benden duysun sesini  Ben anlatayım her günün, bütün ömrünün efsanesini  Bütün hileleri...', ARRAY['Türk Edebiyatı','Şiir','Uğur Arslan']::text[], 8.5, '{"poet":"Uğur Arslan","poet_slug":"ugur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/beni-sana-yonlendir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglama', 'aglama-guner-kaymak-328y8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aglama dagit su gamlarini

Su dunyada bir kac gun kalmami 

Eger istiyorsan iyi olmami

Aglama diyorum ne olur aglama

Her seyden vaz gectim umudim kirik

Bu sevdamiz caresiz bir hastalik

Belki dayanamam tutar hickirik

Gozbebegim gozlerime bakip aglama

 Aybasti-Ordu / 01.12.1980', 'Aglama dagit su gamlarini Su dunyada bir kac gun kalmami  Eger istiyorsan iyi olmami Aglama diyorum ne olur aglama Her seyden vaz gectim umu...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aglama-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doneriz Birgun', 'doneriz-birgun-guner-kaymak-4yly6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Teslim oldum Foca''ya yuregim sizlar

Her gece ruyama giriyor kizlar

Gel teskere diye caliyor sazlar

Aldirma arkadas doneriz bir gun

Nizamiye kapisindan iceri daldim

Ihtiyaclarimin hepsini Izmir''de aldim

Cuvaldan elbiseyi karsimda buldum

Uzulme arkadas doneriz bir gun

Yanasik duzenmis cokup kalkmasi

Herhalde burda marifmis takla atmasi

Bayagi guzel olurmus tufek catmasi

Merak etme arkadas doneriz bir gun

Bir gun gelip bu askerlik bitecek

Susumus o diller bulbul gibi otecek

Emir komuta denen nesne bitecek

Dert etme arkadas olmezsek doneriz elbet

Foca/ 1979', 'Teslim oldum Foca''ya yuregim sizlar Her gece ruyama giriyor kizlar Gel teskere diye caliyor sazlar Aldirma arkadas doneriz bir gun Nizamiye ...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/doneriz-birgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzular', 'arzular-i-brahim-bayraktar-a0hn8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şehvetli dudaklarda, 

Yalnızken yataklarda, 

Açılan kucaklarda, 

Hep seni aradım.

Kollarını açta gel, 

Kurban olduğum, 

Artık dayanamıyorum.', 'Şehvetli dudaklarda,  Yalnızken yataklarda,  Açılan kucaklarda,  Hep seni aradım. Kollarını açta gel,  Kurban olduğum,  Artık dayanamıyorum....', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/arzular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orada Sen Burada Ben', 'orada-sen-burada-ben-guner-kaymak-hsfcc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzun yollar var aramizda 

Bir ucunda sen bir ucunda ben

Bir ruzgar esiyor kalbimde

Atesi sensin  kulude ben

Umut isigi gozlerimde

Aglatan sen aglayan ben

Hasret birikmis kalbimde

Soyleten sen soyleyen ben

Askin dile geliyor misralarinda

Kagidi sen kalemi ben

Bekliyorum aylarin bitmesini

orada sen burada ben

Trabzon / 13.12.1979', 'Uzun yollar var aramizda  Bir ucunda sen bir ucunda ben Bir ruzgar esiyor kalbimde Atesi sensin  kulude ben Umut isigi gozlerimde Aglatan se...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/orada-sen-burada-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piyango', 'piyango-can-akin-2-qtar3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir erkeğin acı çekmesi, 

Cezalandırılması gerekiyordu:

Şanslı erkek bendim…', 'Bir erkeğin acı çekmesi,  Cezalandırılması gerekiyordu: Şanslı erkek bendim…...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/piyango-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Durma', 'uzak-durma-guner-kaymak-lnkq7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oyle uzak durma birtanem benden

Ben seni cokama  cok seviyorum

Gel gulum gel hadi yaklas yanima

Senden ayrilmak hic istemiyorum

Yaslarla dolu gozlerim aci icindeyim

Hep seni ozluyor seni dusunuyorum

Biraktigin guzel hatiralarla avunup

Kendi kendime bir teselli ariyorum

Bir gun mutlaka doneceksin diye

Yollara bakar oldum  yollarda gozum

Senden baska kimim var kimselere

Nazim gecmiyor bir tanem gecmiyor

Aybasti / 21.10.1980', 'Oyle uzak durma birtanem benden Ben seni cokama  cok seviyorum Gel gulum gel hadi yaklas yanima Senden ayrilmak hic istemiyorum Yaslarla dol...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uzak-durma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Bir Şiir', 'aci-bir-siir-can-akin-2-7gs03', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kadar acı, 

Sana böylesine yakın olmak

Ve sensiz olmak…

Seni izlemek umarsızca…

Her an, her saniye benden uzaklaşmana tanıklık etmek…

İzlemek insanlara davranışlarını, 

(Biliyorsun yüzünden okunur herşeyin, saklayamazsın) 

İçim acırken senin cilveli kahkahalarını duymak, 

Ne kadar acı…

Başkalarıyla olan konuşmalarının bitmesini beklemek, 

Hatta heyecanlandığında yaptığın o şuh ayak çevirmelerini izlemek…

Seni an-be- an hissetmek, 

Arayışlarını, duygularını, korkularını izlemek bir film gibi…

Ne kadar acı, 

İnsanların senin için söylediklerini, 

Senin hakkında sorduklarını, 

Boş sözlerle savuşturmaya çalışmak…

Yaşamakta olduklarını ve yaşayacaklarını bilerek, 

Görünmez bir camın arkasındaymışçasına öylece sana bakmak…

O en çaresiz anlarında, sana hiç bir şey diyememek, 

Sana sarılamamak, 

Dayanamadığım gözyaşlarını silememek…

Ne kadar acı, 

Hiç bir şey olmamışçasına, 

Bir yabancıymışcasına sana davranmak, 

Ve her an, 

Neyin bedelini ödediğimi bilmeden, 

Biraz daha senden uzaklaştırılmak… 

Acı olan, 

-senin gibi birini- böylesine sevmiş olmak!', 'Ne kadar acı,  Sana böylesine yakın olmak Ve sensiz olmak… Seni izlemek umarsızca… Her an, her saniye benden uzaklaşmana tanıklık etmek… İzl...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aci-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Seni Sevecegim', 'yine-seni-sevecegim-recep-camliguney-dvle8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dakikalar, dakikaları kovalasada

               Bu aşkımız ortaya çıksada

               Seven kalbler senin olsada

               Parlayan ışık gibi dogsanda

               Yine seni sevecegim

               Aşıklar  aşka doysada

               Sevdalılar sevdiklerine yansada

               Güneş yeniden dogsada

               Yagmur sel olup yagsada

               Yine seni sevecegim

  

               Hayaller düşlere karışsada

               Yürekler yansada

               Dönülmeyecek bir yol olsada

               Aşk melegim olsanda

               Yine seni sevecegim

               Uzaklarda bir yerlerde olsanda

               Beni düşünüp pişman olsanda

               Kaderine baglanıp aglasanda

               Seni hatırlatacak bir dost bulsamda

               Yine seni sevecegim

               Diyar diyar gezip arasamda

               Dostlarıma aşkı anlatsamda

               Sevinçden gökyüzüne uçsamda

               Sensiz bu aşkı yaşatsamda

               Yine sen, sevecegim

                                                                                       Recep   ÇAMLIGÜNEY

         gsm:0535 473 06 71', 'Dakikalar, dakikaları kovalasada                Bu aşkımız ortaya çıksada                Seven kalbler senin olsada                Parlayan ...', ARRAY['Türk Edebiyatı','Şiir','Recep Çamlıgüney']::text[], 8.5, '{"poet":"Recep Çamlıgüney","poet_slug":"recep-camliguney","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yine-seni-sevecegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-recep-camliguney-qca7i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arkadaş arıyorum dertleşeçek

                  Beni gerçekden sevecek

                  Aşk arıyorum, geleçek

                  Beni gerçekden seveçek

                  Kalb arıyorum, göreçek

                  Aşkıma karşılık vereçek

                  Yürek arıyorum, söyleyeçek

                   Beni gerçekden seveçek

                   Seni arıyorum, yalnızlıgımı gidereçek

                   Ölümüne seveçek

                   Terk edip gitmeyeçek

                   Sevgimiz ömür boyu süreçek

                 

                   Akıl arıyorum yöneteçek

                   Aşkımızı dile getireçek

                   Bakışlarıyla etkileyeçek

                   Sevgisinden delirteçek

0535 473 06 71', 'Arkadaş arıyorum dertleşeçek                   Beni gerçekden sevecek                   Aşk arıyorum, geleçek                   Beni gerçekd...', ARRAY['Türk Edebiyatı','Şiir','Recep Çamlıgüney']::text[], 8.5, '{"poet":"Recep Çamlıgüney","poet_slug":"recep-camliguney","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizim-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak yakamı', 'birak-yakami-ahmet-turan-altunsu-6p17i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahın mahmurluğu üzerimde halâ, 

Gecenin yorgunluğunu taşıyorum.

Uykusuz geçen bir gece

Ve gecenin bam teli, mim noktası sen! 

Yüreğimin isyan çığlıklarını duyuyorum, 

Giderek küçüldüğümü hissediyorum, 

Büzülüp kalıyorum koltuğuma - üşüyorum -

Kulaklarım halâ çınlıyor...

Sıradışı, hattâ aykırı duygulara gebeyim...

Çek gölyeşili gözlerini gözlerimden, 

Öleceksem öleyim! ...

01.09.2003 - Ankara -', 'Sabahın mahmurluğu üzerimde halâ,  Gecenin yorgunluğunu taşıyorum. Uykusuz geçen bir gece Ve gecenin bam teli, mim noktası sen!  Yüreğimin i...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birak-yakami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirk Yil Sonra', 'kirk-yil-sonra-cemal-karsavran-6yx3i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'daha cok bakamadim rengine 

göz göze gelemedim gözlerinle

kaybolmustu göz bebeklerinde

kahkahalarin cinlar kulaklarimda

ilgimi ceken balik eti gerdanin

siktirilmisti sinendeki güllerin

sevecenligin candan

yaklasimin içtenligin gözlerinden

tutmak isterdim ellerinden

gecenin ayazinda kaybolmadan

sahiplenmek geceyi

ay küsmeden bulutlarin arkasindan

yildizlar düssün camin araligindan omzuna

ates böcegi konsun dudaklarina

kahve içseydim gözlerinden

tadi kalirdi dudagimda kirk yil

acliga sevgiye aska

gerilerde kalan susuzlugum

kuruyan dudaklarimda

kirk yil sonra

25-11-2002', 'daha cok bakamadim rengine  göz göze gelemedim gözlerinle kaybolmustu göz bebeklerinde kahkahalarin cinlar kulaklarimda ilgimi ceken balik e...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kirk-yil-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlisin Tatli', 'tatlisin-tatli-cemal-karsavran-0tfmn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tadin damagimda

soframda lezzetsin

ekmegim tuzum

su kadar azizsin 

sevgilim

tadimlik degilsin

yanimda istiyorum her an 

öpülesi ellerin

öpülesi yanagin

öpülesi alnin

öpülesi dudaklarinla

tatlisin tatli

04-12-2002', 'tadin damagimda soframda lezzetsin ekmegim tuzum su kadar azizsin  sevgilim tadimlik degilsin yanimda istiyorum her an  öpülesi ellerin öpül...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tatlisin-tatli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönülden Gönüle Muhabbetle', 'gonulden-gonule-muhabbetle-cemal-karsavran-kq651', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutluluğun baki kalsın geceden

günaydın günle gelen sevgili

doğdum senden önce seninle

hoş geldin gönül bahçeme

Nasıl geçti zamansız vakitlerin

uzun çıplak geceden

coştum seller gibi seninle uyandığımda

meltem rüzgarıydın kalbime düsen

Rüzgar ol kanat tak uçan maviliklerde

bulutlar boyun eğer geçit vermez dağlara

ip ol rüzgar ol uçurtmalara

uzaklardan koş gel bana

Küçük bir serçeyim sigarım kanatlarına

al beni de yanına yağmur dolu bulutlarla

tat olur dudağıma acılar seninle

süzülen her damla baldır

Koparsın apansız zamanlarda

sevdasın yüreğimde ateşisin aşkın

çığlıklarımız ortak sevincimize

gönülden gönüle muhabbetle

16-12-2002', 'Mutluluğun baki kalsın geceden günaydın günle gelen sevgili doğdum senden önce seninle hoş geldin gönül bahçeme Nasıl geçti zamansız vakitle...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gonulden-gonule-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Sordum Gülbahardı', 'adini-sordum-gulbahardi-cemal-karsavran-rvjts', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözüm yoldaydı 

biri geldi dukanın önüne 

bekledi bir müddet 

bakındı sağına soluna 

ilgili ilgisiz 

yüzü bana dönük değildi 

saçları kısaydı 

karşısına geçtim baktım 

küçük bir tebessüm ettim 

gamzeleri sendin 

buğday tenliydi yüzü 

gözlerine baktım 

yanından yakın geçerken 

gözleri sen değildin 

kocamandı 

göğüsleri sendin 

yüzü sana yakin 

küpeleri kulaklarında çemberdi 

kokusu başımı döndürdüğünde 

adını sordum gülbahardı 

29-11-2002', 'gözüm yoldaydı  biri geldi dukanın önüne  bekledi bir müddet  bakındı sağına soluna  ilgili ilgisiz  yüzü bana dönük değildi  saçları kısayd...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adini-sordum-gulbahardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz', 'sessiz-cemal-karsavran-uad54', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sana gülüm demeyecegim

gülmüyorsun yüzüme

gülmeni istemiyorum

kendi kendimi kandirim 

dört duvar arasinda

geceden dinmeyen arzularimdi

sevgisizligi doguran 

bir yastik birde dösekten kalan

sevimsiz bir gece

günde sevgisiz ve sessiz

30-11-2002', 'sana gülüm demeyecegim gülmüyorsun yüzüme gülmeni istemiyorum kendi kendimi kandirim  dört duvar arasinda geceden dinmeyen arzularimdi sevgi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sessiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylasanımda', 'paylasanimda-cemal-karsavran-r6pqs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'karanlıklar yıldıramaz beni 

parmaklarımda gizlidir şiir 

coştur ki coşsun yürek 

ben sana sevdalı 

sen bana vefalı 

kalplerimiz yaralı

sen söylerdin tatlı sözler 

sen susardın ben baslardım 

kulağımda sesin çınlar 

sürüklenirdik bulutlara 

ne sen yetişebilirsin 

nede ben bundan sonra 

paylaşırız yüreklerimizi 

sen kuş olup uçamazsın 

ben yağamam yağmurlarla 

eseriz meltem sıcaklığında 

esintisi vurur kalbe 

sıkılma iç çekme 

kendinden öte düşün 

sevenim var paylaşanımda 

16-12-2002

16-12-2002', 'karanlıklar yıldıramaz beni  parmaklarımda gizlidir şiir  coştur ki coşsun yürek  ben sana sevdalı  sen bana vefalı  kalplerimiz yaralı sen ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/paylasanimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Dudaklarim Kan Içinde', 'dudaklarim-kan-icinde-cemal-karsavran-3b91b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dalgali bir denizdi gece

mercan gözlü 

deniz kizinin kulac atislariyla

dalgalar yüregimi dövüyordu

bir tek ates böceginin sesi duyuluyordu gecede

yildizlar cümbüs çaliyordu 

ay dolundu 

aydinlatirken geceyi

dalgalar yüregimi dövüyordu

gecede

mercan gözlü deniz kizinin kulac atislariyla

kanter içinde uyandigimda

dudaklarim kan içinde

03-11-2002', 'dalgali bir denizdi gece mercan gözlü  deniz kizinin kulac atislariyla dalgalar yüregimi dövüyordu bir tek ates böceginin sesi duyuluyordu g...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dudaklarim-kan-icinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göklerin Mavililiğinden Gelinlik', 'goklerin-mavililiginden-gelinlik-sedef-unal-bj44a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uykumun en derin anında

Beliriverdin karşımda

Uyurla uyanık arası mıydı, Yoksa rüya mıydı? 

O her zamanki muzip halinde

Sana dedin, göklerin mavililiğinden

Gelinlik, yıldızlardan taç getirdim

Görkeminden gözlerim kamaşarak

Yüreğim tüy gibi hafif uçarken

Başım dizlerine koydum

Hayran hayran bakarken yüzüne

Yıldız yıldız ışıldayan gözlerinde

Haps oldum....

Üzüm yedik birbirimizin avucundan

Dans ettik ayda gezer gibi, başım Omuzun da

Hasret, özlem giderdik sabaha kadar

Ardına kadar açtığın kalbinin kapısından

Usulca süzüldüm, Cennetin yeşil Zebercetten

Kapısından geçer gibi....

01-09-2003', 'Uykumun en derin anında Beliriverdin karşımda Uyurla uyanık arası mıydı, Yoksa rüya mıydı?  O her zamanki muzip halinde Sana dedin, göklerin...', ARRAY['Türk Edebiyatı','Şiir','Sedef Ünal']::text[], 8.5, '{"poet":"Sedef Ünal","poet_slug":"sedef-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/goklerin-mavililiginden-gelinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Gün', 'beklenen-gun-abdurrahman-cankaloglu-8bddw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şafak defterimde son sayfalar

Çizilmiş onca gün ve aylar

Hepsinde beklediğim gün, 

Hasretim ve duam var

Sen, beklenen sevgili

Yüreğinde kalayım 

Soluduğum her nefesimde

Hep sen varsın.

Biliyorum artık az kaldı

Kavuşmak tek dileğimiz

Kedersiz ve mutlu

Ayrılmamasına ellerimiz.', 'Şafak defterimde son sayfalar Çizilmiş onca gün ve aylar Hepsinde beklediğim gün,  Hasretim ve duam var Sen, beklenen sevgili Yüreğinde kala...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Çankaloğlu']::text[], 8.5, '{"poet":"Abdurrahman Çankaloğlu","poet_slug":"abdurrahman-cankaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beklenen-gun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meme'' m', 'meme-m-umut-yalim-lkl65', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koparsa başım ölemem

Başım babamdan yadigar

Koparsa yürek ölemem

Yürek de senindir Meme'' m

Acırsa yerim bağ'' ramam

Acım babamdan yadigar

Yaş dolarsa dökemem

Yaşım da senindir Meme'' m

Kan dolarsam tüküremem

Kanım babamdan yadigar

Dudağıma gem vuramam

Dudak da senindir Meme'' m

Sağ tarafımı kesemem

Sağım babamdan yadigar

Sol tarafımı kesemem

Solum da senindir Meme'' m

1999', 'Koparsa başım ölemem Başım babamdan yadigar Koparsa yürek ölemem Yürek de senindir Meme'' m Acırsa yerim bağ'' ramam Acım babamdan yadigar Yaş...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/meme-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.. '' dan Doldurun Beni', 'dan-doldurun-beni-umut-yalim-mhmip', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boşluklarımdan doldurun beni

Taşırmadan ve kurşun kalemle

Lütfen okunaklı ve büyük yazın

İşaretli yerlerden kesin. Kanatmadan.

Ardına kadar kapanıyor ellerin

Alıp yüzümde yüzdürüyorum

Bir sonsuzluk sınırlıyor beni

Ellerim sımsıkı açılıyor ellerim

Ellerimse sabaha kadar beyaz

Yüzünü eldiriyorum ellerime

Öpüyorum sabaha kadar beyaz

Beyazlar gibi utanıyorum

Bulutlar gibi unutuyorum

Sabaha kadar beyaz

Belki istememiştin ama azaldın yarı yarıya

Yarısı beyaz gözlerin sabahın beşi

Gözdürüyorum ellerimi tırnaklarımın altı çökük

Gecenin ucu beyaz yarısına kadar 

Gördüğün sade ellerimin leşi

Sonuna kadar beyaz

Gittin gelmemenle bütün

Boşluklarım kaldı sende

Sonuna kadar beyaz

İşaretli yerlerimden sev taşırmadan

Hani o başlayıp da bitiremediğin yerlerden

Sonuna kadar beyaz beyaz değil

Boşluklarımdan doldurun beni

Taşırmadan ve kurşun kalemle

Lütfen okunaklı ve büyük yazın

Kanatmadan kesin işaretli yerlerimi

Doldurun boşluklarımı acıtmadan

Yoksa acır beyazların', 'Boşluklarımdan doldurun beni Taşırmadan ve kurşun kalemle Lütfen okunaklı ve büyük yazın İşaretli yerlerden kesin. Kanatmadan. Ardına kadar ...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dan-doldurun-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baştan Başa Aşk Olsa', 'bastan-basa-ask-olsa-umut-yalim-88l0r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zulm bardağa konmazdı

Baştan başa aşk olsa

Dost zevkinle içmezdi

Baştan başa aşk olsa

Kulsan divan derilir

Başın göğe değinir

Düşman dostun denilir

Baştan başa aşk olsa

Zikrim fikrim değildir

Avrat kanda zehirdir

Dostan dosta bilinir

Baştan başa aşk olsa

Özde erkeğim azgın

Kalbe uğramaz bozgun

Bana vurulmaz dizgin

Baştan başa aşk olsa

Cebi sikke bürüse

Arşa kervan yürüse

Benim yolum göğsüne

Baştan başa aşk olsa

Boşa yaşın salmasın

Bağrın yarıp almasın

Yürek boşta kalmasın

Baştan başa aşk olsa

Gümüş gönlüm kararsa

Beni mumla ararsa

Bir dem olsun bakarsa

Baştan başa aşk olsa

Pir Sultan'' ım bulunsa

Altına tahta konsa

Baş bedenle dolaşsa

Baştan başa aşk olsa

Zülfün güzel sanılır

Yalan ömrün yanılır

Adın benle anılır

Baştan başa aşk olsa

1999', 'Zulm bardağa konmazdı Baştan başa aşk olsa Dost zevkinle içmezdi Baştan başa aşk olsa Kulsan divan derilir Başın göğe değinir Düşman dostun ...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bastan-basa-ask-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonuç', 'sonuc-rasim-eksi-qv9da', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ya düştü ya serap gördük

Kimi insanları sevdik

Kimi insanlara kıydık

Doğruyu en yalın yerde yitirdik.

Gözlerde parçaladık yürekleri

Renklerle örttük gerçekleri

Boşuna cektik kürekleri

İnsanlığımızı yedik.', 'Ya düştü ya serap gördük Kimi insanları sevdik Kimi insanlara kıydık Doğruyu en yalın yerde yitirdik. Gözlerde parçaladık yürekleri Renklerl...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sonuc-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cum '' Baba '' huriyet Meyhanesi', 'cum-baba-huriyet-meyhanesi-umut-yalim-sd7y0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cumhuriyet Meyhanesi'' nde eylüllü bir akşam

Üç kişi dört bardakla loşluğumuzu çektirmişiz

Ahşap gölgelerimizle Mert, Enis, Umut, bir de ben

O geceden ellerimize anason tohumlar ektirmişiz

Bir de şiir söktürmüşüz tırnaklarımızdan:

'' Rakı, masamızdaki tek kadın

Katkısız, saydam ve yalın

Etlerimizle yiyoruz kadınımızı

Ve anasona banarak dudaklarımızı

Kırmızıdan alıyoruz hızımızı

Kulaklarımızda boğulan kadın sesi

Kurtaracak belki Cumhuriyet Meyhanesi.''

8.09.2002 / 00.05', 'Cumhuriyet Meyhanesi'' nde eylüllü bir akşam Üç kişi dört bardakla loşluğumuzu çektirmişiz Ahşap gölgelerimizle Mert, Enis, Umut, bir de ben ...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cum-baba-huriyet-meyhanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-haydar-meric-c3anw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel

Al yanına 

            Hasretini

                      Ve

                         Sevgini

                                   Doldur yüreğine

                                                        Köpük köpük

                                                        Gel............

Seni       istiyorum

                         Ezgilerinle.....

  

                                       Haydar Meriç', 'Gel Al yanına              Hasretini                       Ve                          Sevgini                                    Doldur yür...', ARRAY['Türk Edebiyatı','Şiir','Haydar Meriç']::text[], 8.5, '{"poet":"Haydar Meriç","poet_slug":"haydar-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gel-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-ugur-oguz-sahin-a9g0z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşık olmak kolay

Zor olan

Önce yakalamak

Gözlerdeki parıltıyı

Sonra yaşatmak yürekte

Ölene dek baharları

Ve birlikte yaşamak

Tüm hazları

Aşk her şarkıda

Mutluluk ve hüzün kaynağı

Aşk felç gibidir

Bir yıldırım gibi

Aniden düşer

İnsanın yüreğine

Beynine ipotek kor

Dağılır tenine bedenine

Estirir her yönden

Rüzgârları

Göğüsleyebiliyorsan eğer

Duygusal fırtınaları

Zor işte o zaman zor

İçine düşünce

Hayatın dönme dolapları', 'Aşık olmak kolay Zor olan Önce yakalamak Gözlerdeki parıltıyı Sonra yaşatmak yürekte Ölene dek baharları Ve birlikte yaşamak Tüm hazları Aşk...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ask-174-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayıklama', 'sayiklama-rasim-eksi-0c036', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yakıyor enginleri delip geçen bakışın

Benziyor bir ışığın ekrana düşüşüne

Sessizce akışıyor saf ve temiz sevgimin

Ardına kadar açık bekleyen kapısına.

Süre mi sona erdi sesini duymuyorum

Beni uyutup kaçma o tatlı gülüşünle

Sonsuz aydınlıklara erişecekken yolum

Elele olmalıyım yine o gün seninle.

Ateşli gözlerinden kızgın oklar atarak

Al dediğim yüreği parça parça edensin

Oysa sonra sevgini ruhuma adayarak

Zavallı umudumun kökünü besleyensin.

Şimdi sultanısın sen girdiğin canevimin

Kubbesinde sonsuzluk kazanacaktır sesin

Ne çıkar elemleri benim olsa evrenin

Gün görmeyen sevimin sen ki tek güneşisin.', 'Yakıyor enginleri delip geçen bakışın Benziyor bir ışığın ekrana düşüşüne Sessizce akışıyor saf ve temiz sevgimin Ardına kadar açık bekleyen...', ARRAY['Türk Edebiyatı','Şiir','Rasim Ekşi']::text[], 8.5, '{"poet":"Rasim Ekşi","poet_slug":"rasim-eksi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sayiklama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun bir kuş gibiyim hayatın çıkmazında', 'yorgun-bir-kus-gibiyim-hayatin-cikmazinda-nuri-can-jrpjh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acıdan titreyen Kar Tanesi 

Yorgun bir kuş gibiyim hayatın çıkmazında

gözlerinde bulutlar taşıyan yağmurlar gibiyim

bir tutam hüzün, bir avuç keder

ve çileli bir ömürden başka nem var

ömrümki, zemheride buzdağı

acıdan titreyen kar tanesi gibi ürkek ruhum

bedenim kış yorgunluğunu kuşanmış

güneş doğmuyor artık, yıldızım da söndü

bir mevsim daha bırakıp gitti ardından gözlerimi …

ne zaman bir çift turna havalansa

ölesiye dağlarımı özlerim

bıraksam uykulara düşecek 

kapanacak gözlerim

bir daha, bir daha hiç açılmayacak

bir dağ isterdim başımı yaslayacak

bir gök sarıp sarmalayacak 

bir yıldız isterdim uzaklarda ışıyacak

benimkisi bir hayal işte arkadaş

biliyorum ki, bunların hiç biri olmayacak

hazanlar düştü beklemelerime

yollarıma yarasalar üşüştü

dönüşü olmayan bir trende

menzili karanlık bir yolun yorgun yolcusuyum artık

dilsiz ve kimsesizlik nedir bilir misin? 

çağlayanlar aktıkça içime acılar yakıyor ruhumu

gel görki, kime ne dersin, kim dinler beni

öylesine yorgun, öylesine kırgın ki bedenim, 

taşıyamayacağım ağırlıklar yüklenmiş canevime

bir türkü düşer dilime akşam olunca

gözlerime iki damla gözyaşı

yarası kanayan acılardan seslenir sesim

üşürüm gurbet olurum, hasret olurum

donar bakışlarım, donar gözyaşlarım

öylesine efkarlıyımki arkadaş, ölesiye

her sabah penceremden kovduğum hüznü

her akşam kapıdan selamla karşılarım

isterdimki, bir akşam kollarımı gerip çarmıha

yüreğimi alıp gitsinler sabahı uzak kentlere

tutup bir denize serpsinler gözyaşlarımı

yalnızca balıklar görsün, 

yalnızca balıklar öpsün diye 

yağmurlar yağsın serviler üstüne

rüzgarlar essin doruklardan

bir tutam kül olsun sevdam

dağılsın okyanuslara

kimseler bilmesin

bir yaprağın ürpertisine sarıp acımı

dikenli teller içinde

yangınlı çöller içinde

ölüm sessizliğinde kalayım

Nuri CAN

www.nurican.com', 'Acıdan titreyen Kar Tanesi  Yorgun bir kuş gibiyim hayatın çıkmazında gözlerinde bulutlar taşıyan yağmurlar gibiyim bir tutam hüzün, bir avu...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/yorgun-bir-kus-gibiyim-hayatin-cikmazinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaktüsüm Darağacı', 'kaktusum-daragaci-ali-tosmer-11qwv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutluluk, çölümde bir susuz kuyum,

Uç uca düğümlü iplerim acı.

Her gün ve her gece kurban olduğum,

Tepemde gölgelik kaktüs ağacı.

Yâr hayâl gölümde bir beyaz kuğum,

Benden ıradıkça gözümde buğum,

Ömrümü yedikçe zaman sayacı,

Gözüme kan döker uykusuzluğum.

(Eylül’2003)', 'Mutluluk, çölümde bir susuz kuyum, Uç uca düğümlü iplerim acı. Her gün ve her gece kurban olduğum, Tepemde gölgelik kaktüs ağacı. Yâr hayâl ...', ARRAY['Türk Edebiyatı','Şiir','Ali Tosmer']::text[], 8.5, '{"poet":"Ali Tosmer","poet_slug":"ali-tosmer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kaktusum-daragaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kural Bozan Gözlerin', 'kural-bozan-gozlerin-rasim-eksi-p0sz6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mor için soğuk bir renktir derler

