INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğe Sesleniş', 'yurege-seslenis-bahar-gulsen-jg393', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'turkuaz bakışlardan süzülen, 

ay ışığında yıkandın, 

ey yüreğim yeniden. 

ve soyundun çırılçıplak, 

