INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hain Yar', 'hain-yar-necat-gundem-8heir', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağların ardında

Ne var

Korkunç bir duvar

Yani

Hasretin var

Beni her gün boğar

Ve hep sana doğar

***********

Hasretimin ortasında 

Ne var

Yılanlar çıyanlar

Yani

Acımasızlığın var

Beni sormazlığın var

Ah ah

Hain yar.



9 Aralık 2000 - BATMAN

NECAT GÜNDEM', 'Dağların ardında Ne var Korkunç bir duvar Yani Hasretin var Beni her gün boğar Ve hep sana doğar *********** Hasretimin ortasında  Ne var Yı...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hain-yar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-necat-gundem-jlz0l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonbahar

