INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurun türküsü', 'yagmurun-turkusu-necat-gundem-pdp78', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Islanmakla kalma

Geride durma

Katıl sen de 

Yağmurun türküsüne

Eşlik et

Yeryüzüne düşen

Her bir yağmur tanesine

Yakalarsın belki de

Peşinde olduğun varlığı; 

Kendini.





27.01.1998

