INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bir Dildara Kul Olmak Diler', 'gonul-bir-dildara-kul-olmak-diler-kuloglu-2n0af', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönül Bir Dildara Kul Olmak Diler 

Hal Mükedder Ola Deyü Korkarım 

Yanıp Yakıldığım Görüp Adülar

Şen Olup Da Güle Deyü Korkarım

Meyledem De İşlemeye Sırrımız 

Bülbül Gibi Arşa Çıkar Zarımız

Aşk Kavline De Sığmaya Da Serimiz

Cümle Alem Duyar Deyü Korkarım

Sermayemiz Ziyan Eder Gücünden 

Alamazsam Ol Güzelin Bacından

Mecnun Gibi Leyli''nin Ucundan

Adım Dilde Kala Deyü Korkarım

Mestane Bakışın Benzer Ceyrana

Kimse Bilmez, Ciğer Döndü Büryana

Gidi Ayrılık, Her Birmiz Bir Yana

Bölük Bölük Böle Deyü Korkarım

Kuloğlu Der, Değer Oldu Telime 

Komaz Felek Gidem Kendi Bileme 

Girmiş İken Dost Eteği Elime

Gine Çekip Ala Deyü Korkarım', 'Gönül Bir Dildara Kul Olmak Diler  Hal Mükedder Ola Deyü Korkarım  Yanıp Yakıldığım Görüp Adülar Şen Olup Da Güle Deyü Korkarım Meyledem De ...', ARRAY['Türk Edebiyatı','Şiir','Kuloğlu']::text[], 8.5, '{"poet":"Kuloğlu","poet_slug":"kuloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonul-bir-dildara-kul-olmak-diler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reftara Başlasa Ol Kaşı Keman', 'reftara-baslasa-ol-kasi-keman-kuloglu-6y2r8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Reftara Başlasa Ol Kaşı Keman

Güneş Damanın Öper Sanırım 

Yavru Dertlerimi Bilirse Heman 

Merhamet Babın Açar Sanırım

Kime Feryat Edip Eyledim Ah-Zar

Kalmışım Hayrette Aldı Beni Zar 

Üsküfün Aldırmış§ Şahine Benzer 

Şikar Edip Gönlüm Kapar Sanırım

Lütfü Katı Az Görünür, Cevri Çok

Kaşların Yay Etmiş, Kirpiklerin Ok 

Canıma Kar Etmiş, Haberimiz Yok 

Sinem Karşısına Siper Sanırım 

Korkarım Halimi Etmeye İlam 

Ahvalime Vakıf Olmasın Alem

Lütüf Edüben Söylerse Bir Kelam 

Bu Viran Kalbimi Yapar Sanırım

Kuloğlu Eydür, Kulak Tut Sözüme 

Yeni''le Bir Sevda Düştü Özüme 

Her Kaçan Sataşsa Gözü Gözüme 

Yüreğim Yerinden Kopar Sanırım', 'Reftara Başlasa Ol Kaşı Keman Güneş Damanın Öper Sanırım  Yavru Dertlerimi Bilirse Heman  Merhamet Babın Açar Sanırım Kime Feryat Edip Eyled...', ARRAY['Türk Edebiyatı','Şiir','Kuloğlu']::text[], 8.5, '{"poet":"Kuloğlu","poet_slug":"kuloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/reftara-baslasa-ol-kasi-keman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazda Kaldım Ben Seninle', 'yazda-kaldim-ben-seninle-bekir-mutlu-gokcesu-9c5m1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu günlerde yine gececiyim

Yüreğimde bir telaş, aceleciyim

Sanki bir ileri, iki geriyim

Yazda kaldım ben seninle

Oysa mevsim güze dönmekte

Uzanıp, yıldızları sayıyorduk

Sevdalara dalıyorduk her gece

Sen, ben, ben, sen oluyorduk gizlice

Sabahları doğurup veriyordun ellerime

Hazda kaldım ben seninle

Oysa mevsim hazana dönmekte', 'Bu günlerde yine gececiyim Yüreğimde bir telaş, aceleciyim Sanki bir ileri, iki geriyim Yazda kaldım ben seninle Oysa mevsim güze dönmekte U...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yazda-kaldim-ben-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşımda Salınan Dilber', 'karsimda-salinan-dilber-kuloglu-nncq7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karşımda Salınan Dilber

Bakma, Beni Ağlatırsın 

Beni Koyup Yad Ellere 

Gitme Beni Ağlatırsın

Şekerden Şerbet Ezerler 

İnci Tülbentten Süzerler 

İncili Mercan Dizerler 

Dizme, Beni Ağlatırsın

Boyun Uzundur Dal Gibi 

Ensem Leblerin Bal Gibi 

Bahçelerde Bülbül Gibi

Ötme Beni Ağlatırsın

Hoş Çekeyim Nazlarını 

Gel Öpeyim Gözlerini

Kelp Rakıbin Sözlerini 

Tutma, Beni Ağlatırsın

Bu Kuloğlu, Sana Kuldur 

Ta Ezelden Böyle Yoldur 

Ya Azat Eyle Ya Öldür 

Satma Beni Ağlatırsın', 'Karşımda Salınan Dilber Bakma, Beni Ağlatırsın  Beni Koyup Yad Ellere  Gitme Beni Ağlatırsın Şekerden Şerbet Ezerler  İnci Tülbentten Süzerl...', ARRAY['Türk Edebiyatı','Şiir','Kuloğlu']::text[], 8.5, '{"poet":"Kuloğlu","poet_slug":"kuloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karsimda-salinan-dilber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Yol''un Yolcusu', 'kutlu-yol-un-yolcusu-i-lyas-ozkan-62s4j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Muhterem büyüğüm İsmet Macit Bey’e...                   

İlklerle aynı safı paylaşmak düşer bahtımıza

Sonsuzluğa kanat çırpmak düşer, omuz omuza.

Mânevi âlemlerden perdeler açılır birgün

Eller, -dupduru- yerden semâya saçılır birgün

Ter ü tâze bahar çiçekleri sarar her yanı…

Maksat belli; kalmasın âlemde gözyaşlı yetim

Artık dinsin, yıllar yılı süregelen vâveyla.

Cemreler düşer şimdilerde; müjdedir, bilirim

İkrardır ağan sabaha ve vedâdır feryâda.

Tertemiz duanda, n’olur gedâyı da anıver...

(08.09.2003

Pazartesi)', 'Muhterem büyüğüm İsmet Macit Bey’e...                    İlklerle aynı safı paylaşmak düşer bahtımıza Sonsuzluğa kanat çırpmak düşer, omuz o...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kutlu-yol-un-yolcusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlginç', 'i-lginc-sair-celebrian-d1uvs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrıldığımız gecenin, 

O nemli, buğulu, hıçkırıklı gecenin

Üstünden çok zaman geçti 

Nice boğucu geceleri yaşadım sensiz

Ve de nice sabahları uyanmaya niyetsiz

Beyaz takvim sayfaları gözlerimin önünde uçtular

Akreple yelkovan durmamacasına koştular

İşte ben bu deli hızda sıkışıp kalıyorum

Ama asıl ilginci ne biliyor musun? 

Seni hala çok seviyorum.', 'Ayrıldığımız gecenin,  O nemli, buğulu, hıçkırıklı gecenin Üstünden çok zaman geçti  Nice boğucu geceleri yaşadım sensiz Ve de nice sabahlar...', ARRAY['Türk Edebiyatı','Şiir','Şair Celebrian']::text[], 8.5, '{"poet":"Şair Celebrian","poet_slug":"sair-celebrian","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ilginc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli oldum, Divane oldum', 'deli-oldum-divane-oldum-muammer-celik-8pgon', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deli oldum, divane oldum, günümü yaşamıyorum artik 

Haritasını çıkardım kaç defa sana giden yolların

Çizdim yüzüme çizik çizik aşkını, sevgini ve hatta resmini 

saçlarıma boyadım alnının aklığını birde yüzünün paklığını 

Gel, oku, hat hat, safha safha, çehremdeki geçmişini 

Gel, oku, satır satır, dize dize, sana yazdığım şiirleri 

Harıtasıni çıkardım kaç defa sana giden yolların yine 

günümü yaşamıyorum artık, deli oldum birde divane 

Büklüm büklüm dürüldü sevgim, sevdam ayyuka çıktı 

dalga dalga yayılan, dağılan duygularımın isyanini 

icime kazıdım, silinmesin diye ismini, adını, hatta soyadını

Sana ulaşmayan ellerimi, uzanmayan kollarımı 

kırdım birer birer, aramızdaki engel ve tüm tabularımı

Gel, gez, sokak sokak, cadde cadde, sevgimin şehrinde 

Gel yıkan inşaa ettiğim şadırvanlardan akan sularda 

Cıkardım harıtasını, bu kaçıncıdır, sana giden yolların 

günümü yaşamıyorum, deli oldum, hemde bağlamalık divane 



Kasım-2001', 'Deli oldum, divane oldum, günümü yaşamıyorum artik  Haritasını çıkardım kaç defa sana giden yolların Çizdim yüzüme çizik çizik aşkını, sevgi...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/deli-oldum-divane-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlenmezmi', 'ozlenmezmi-derin-oger-r5er8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sığ sularınmış benim dipsiz bildiğim

Göğsünde bulutlarım sessizce yüzerdi

Gölgen kaçtıkça tenhalara adımlarım izlerdi

Çığlığa yaklaşmak mı çığlık neydi..

Sen diye uçardı kuşlar gülüşlerimden

Kanatları ışığımı gölgelemeye kıyamazdı

Kollarımda küçülürdü yanardöner dünya

Sanırdım ki dağlarına ulaşan benim sesimdi

Şimdi etten kemikten anılarını yaşattığım yer

Büyüktür silinmez içimde bıraktığın izleri

Hâlâ bir elin omzumda bir elin yüreğimde gibi

Suların buğu buğu çekilip gitti....Özlenmezmi....', 'Sığ sularınmış benim dipsiz bildiğim Göğsünde bulutlarım sessizce yüzerdi Gölgen kaçtıkça tenhalara adımlarım izlerdi Çığlığa yaklaşmak mı ç...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlenmezmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ala Gözlü Nazlı Dilber', 'ala-gozlu-nazli-dilber-gevheri-to1um', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ala gözlü nazlı dilber 

Seni kandan sakınırım

Kandan değil hey efendim

Seni candan sakınırım

O yana bu yana bakma 

Beni ateşlere yakma

Elini koynuna sokma

Seni senden sakınırım

Gevheri der ben bir merdim 

Yüreğimden çıkmaz derdim

Sen bir kuzu ben bir kurdum

Seni benden sakınırım', 'Ala gözlü nazlı dilber  Seni kandan sakınırım Kandan değil hey efendim Seni candan sakınırım O yana bu yana bakma  Beni ateşlere yakma Elini...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ala-gozlu-nazli-dilber-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bad-ı Saba Sevdiğime Gidersen', 'bad-i-saba-sevdigime-gidersen-gevheri-krjel', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bad-ı saba sevdiğime gidersen 

Ol güneş yüzlüye var selam söyle

Sevap kazanırsın hizmet edersen

Aman karşısında dur selam eyle

Ardımdaki karlı dağlar diyesin 

Çeşmim yaşı her dem çağlar diyesin

Derunden ah edip ağlar diyesin

Benimçün hatırın sor selam eyle

Selamımı dünden düne değşirme 

Varıp bir nadan eline düşürme

Gül cemalin görüp kendin şaşırma

Aklını başına der selam eyle

Gevheri bir name verdi bad ile 

Gönderdi elinden sana dad ile

Lutfeylesin konuşmasın yad ile

Kamil olsun onur gör selam eyle', 'Bad-ı saba sevdiğime gidersen  Ol güneş yüzlüye var selam söyle Sevap kazanırsın hizmet edersen Aman karşısında dur selam eyle Ardımdaki kar...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bad-i-saba-sevdigime-gidersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başına Bir Hal Gelirse', 'basina-bir-hal-gelirse-gevheri-3zmde', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başına bir hal gelirse

Dağlara gel bağlara gel

Seni saklar vermez ele

Dağlara gel bağlara gel

Bu canım aşka cinseli

Aşk odu ile pişeli

Yeşil dağlar menevşeli

Dağlara gel bağlara gel

Rakibe miktarın bildir

Yanına civanlar uydur

Zamane dostundan yeğdir

Dağlara gel bağlara gel

Gevheri düşmüş dillere

Diyar-ı gurbet illere

Billahi vermem ellere

Dağlara gel bağlara gel', 'Başına bir hal gelirse Dağlara gel bağlara gel Seni saklar vermez ele Dağlara gel bağlara gel Bu canım aşka cinseli Aşk odu ile pişeli Yeşil...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/basina-bir-hal-gelirse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Behey Dilber Sana Gonül Vereli', 'behey-dilber-sana-gonul-vereli-gevheri-2vusq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Behey dilber sana gönül vereli

Bana hasm olmadık kullar mı kaldı

Dasitan eyledin illere beni

Halim söylemedik diller mi kaldı

Ferhad gibi yol eyledik dağları 

Hangi yar güldürmüş ağlayanları

Şimdi viran oldu dostun bağları

Yad eller değmedik güller mi kaldı

Böyle dilber gelmemiştir devrana 

Şimdiki hublara yoktur bahane

Bir rüzgar musallat oldu cihana

Meyvesin dökmedik dallar mı kaldı

Gel gönül bu dertten olalım ari 

Görelim sonunda ne kılar Bari

Gevheri der ben de ederim zari

Başıma gelmedik haller mi kaldı', 'Behey dilber sana gönül vereli Bana hasm olmadık kullar mı kaldı Dasitan eyledin illere beni Halim söylemedik diller mi kaldı Ferhad gibi yo...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/behey-dilber-sana-gonul-vereli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Güzelim Deyu Havadan Uçma', 'ben-guzelim-deyu-havadan-ucma-gevheri-1d2cb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben güzelim deyu havadan uçma

İndirirler seni el yaman olur

Siyah kaküllerin gerdana saçma

Bad eser dağıtır yel yaman olur

Güzelsin sevdiğim sen de bilirsin

Ettiğin işlere pişman olursun

Gel akşamlayalım yolda kalırsın

Karanlık gecede yol yaman olur

Biçare Gevheri der halim yaman

Dağ başından eksik olmuyor duman

Elendim ben seni sardığım zaman

Aşkımız artar da hal yaman olur', 'Ben güzelim deyu havadan uçma İndirirler seni el yaman olur Siyah kaküllerin gerdana saçma Bad eser dağıtır yel yaman olur Güzelsin sevdiğim...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-guzelim-deyu-havadan-ucma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Göğsün Bana Karşı', 'beyaz-gogsun-bana-karsi-gevheri-ixczv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beyaz göğsün bana karşı

Açma beni öldürürsün

Ela gözler süze süze

Bakma beni öldürürsün

Öldürüp kanıma girme

Her bir yada gönül verme

Ela göze siyah sürme

Çekme beni öldürürsün

Gevheri der şah-ı bülbül

Beyaz gerdan bina-yı pul

Yanağına kırmızı gül

Takma beni öldürürsün', 'Beyaz göğsün bana karşı Açma beni öldürürsün Ela gözler süze süze Bakma beni öldürürsün Öldürüp kanıma girme Her bir yada gönül verme Ela gö...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beyaz-gogsun-bana-karsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Şiirleri 3', 'kader-siirleri-3-oguzkan-bolukbasi-hnkfe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hangi kader

seni sevmek kadar güzel olabilir ki', 'hangi kader seni sevmek kadar güzel olabilir ki...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kader-siirleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizden Selam Olsun Gül Yüzlü Yare', 'bizden-selam-olsun-gul-yuzlu-yare-gevheri-63iqu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizden selam olsun gül yüzlü yare

Salınıp sevdiğim bağlara gelsin

Severim dilberi elde ne çare

Yürekte eriyen dağlara gelsin

Sevda derler bir acayip dengim var 

Güzeller giyecek şali rengim var

Bugün benim adüvlerle cengim var

Kılıçlar bilensin zağlara gelsin

Ne kadar cevr etse şikayet etmem 

Öperim koçarım hiyanet etmem

Canım sende iken feragat etmem

İsterse gerdanım ağlara gelsin

Gevheri bağlamış bir özge eda 

Elinde tesbihi dilinde Hüda

Dellal-i muhabbet eylemiş nida

Mecnunum olanlar dağlara gelsin', 'Bizden selam olsun gül yüzlü yare Salınıp sevdiğim bağlara gelsin Severim dilberi elde ne çare Yürekte eriyen dağlara gelsin Sevda derler bi...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bizden-selam-olsun-gul-yuzlu-yare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Ben Bir Bağa Girdim', 'bugun-ben-bir-baga-girdim-gevheri-muv0e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün ben bir bağa girdim

Ne bağ duydu ne bağbancı

Gülün, şeftalisin derdim

Ne bağ duydu ne bağbancı

Bağın duvarından aştım

Kırmızı gülüne koştum

Öptüm sardım helallaştım

Ne bağ duydu ne bağbancı

Bağın kapışını açtım

Sanasın cennete düştüm

Doldurdum badesin içtim

Ne bağ duydu ne bağbancı

Seherin tan yeri attı

Bülbül elvan elvan öttü

Gevheri yükünü tuttu

Ne bağ duydu ne bağbancı', 'Bugün ben bir bağa girdim Ne bağ duydu ne bağbancı Gülün, şeftalisin derdim Ne bağ duydu ne bağbancı Bağın duvarından aştım Kırmızı gülüne k...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bugun-ben-bir-baga-girdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Ben Bir Güzel Gördüm', 'bugun-ben-bir-guzel-gordum-gevheri-d2o2c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün ben bir güzel gördüm

Hilal kaşı keman olmuş

Dili bülbül saçı sümbül

Yanağı erguvan olmuş

Dedim dilber ne ağlarsın

Sabah akşam ne inlersin

Aşık gibi ne söylersin

Gözün yaşı revan olmuş

Gonca gülün açılmakta

Hal-i hindu saçılmakta

Hep dilberler kocalmakta

Senin vasfın civan olmuş

Gevherî''yim sözüm haktır

Methedecek yerin çoktur

Dilberlerde vefa yoktur

Bildim ahiri kan olmuş', 'Bugün ben bir güzel gördüm Hilal kaşı keman olmuş Dili bülbül saçı sümbül Yanağı erguvan olmuş Dedim dilber ne ağlarsın Sabah akşam ne inler...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bugun-ben-bir-guzel-gordum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbül Ne Yatarsın Yaz Bahar Oldu', 'bulbul-ne-yatarsin-yaz-bahar-oldu-gevheri-c4b6a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bülbül ne yatarsın yaz bahar oldu

Çağrışup ötmenin zamanı geldi

Serviler yeşerdi çiçekler doldu

Cana can katmanın zamanı geldi

Benim yarim yanakları allıdır

Ak elleri deste deste güllüdür

Dertli olan bakışından bellidir

Her derdi atmanın zamanı geldi

Firkatle ağlayup şevkle gülünce

Gözümden dökülen yaşı silince

Bir dilberin elin ele alınca

Yaylaya çıkmanın zamanı geldi

Aşık Gevheri de gider dostuna

Gidi rakiplerin bize kastı ne

Evvelbahar çayır çemen üstüne

Sarılıp yatmanın zamanı geldi', 'Bülbül ne yatarsın yaz bahar oldu Çağrışup ötmenin zamanı geldi Serviler yeşerdi çiçekler doldu Cana can katmanın zamanı geldi Benim yarim y...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bulbul-ne-yatarsin-yaz-bahar-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Sıcağı Gibisin', 'kar-sicagi-gibisin-murat-demir-068xc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derecesi olmayan

Çok tutarsız birisin

Ne soğuk nede ılık

Kar sıcağı gibisin

Sıtma gibi titreten

Ateşlerde yakansın

İçimi aydınlatan

Ne güneşsin ne aysın

Bulunmaz Hint kumaşı

Gibi kendini sanma

Senin gibi birine

Beni sevdalı sayma

Platonik aşk gibi

Ben severim sen sevme

Gidiyorum bu yerden

Sakın arkamdan gelme

Çok düşündüm olmadı

Faydanı zararını

İnan tutturamadım

Ben senin ayarını

Dahası sensiz seni

Kararlıyım sevmeye

Bu dertle sürünsemde

Gelme beni görmeye', 'Derecesi olmayan Çok tutarsız birisin Ne soğuk nede ılık Kar sıcağı gibisin Sıtma gibi titreten Ateşlerde yakansın İçimi aydınlatan Ne güneş...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kar-sicagi-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Dünya', 'yalan-dunya-umit-gulen-f4hcj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk ha aşk hıh inansamda inanmam

Sevgimi duymadım görmedim bilmiyorum 

Dostluk; 

O binbeşyüzlü yıllarda değilmiydi

Ya öylemi günümüze kadar geldi ha

Demekki o da bana uğramadı

Zaten uğrasaydı şaşardım

Gökten altın yağsa

Benim kafama taş düşer.

Kader; 

Bak ona inanırım

Ama oda benim yüzüme gülmedi

Ne zaman yürümeye çalışsam

Biri çelme taktı 

Biri tekme attı

Neyse; 

Artık bana ne çelme takan 

Ne de tekme atan olacak

Ben de ayağa kalkmaya

Derman Kalmadı.', 'Aşk ha aşk hıh inansamda inanmam Sevgimi duymadım görmedim bilmiyorum  Dostluk;  O binbeşyüzlü yıllarda değilmiydi Ya öylemi günümüze kadar ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Gülen']::text[], 8.5, '{"poet":"Ümit Gülen","poet_slug":"umit-gulen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalan-dunya-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bir Kalp', 'kucuk-bir-kalp-can-akin-2-dkk6j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatırlarmısın sevdiğim, 

Nasıl da çocuklar gibi sevinmiştin

O küçük kolyeyi boynuna takdığımda? 

O minik kalp, benim kalbimdi:

Tüm sevgimle, tüm sıcaklığımla sana verdiğim…

Sevdiğim, güvendiğim kadına…

İstemiştim ki, beni sevdiğin sürece hiç çıkmasın boynundan, 

Kalbim, kalbine yakın dursun…

Biliyorum, sen mantıklı kadınsındır, 

Değer vermezsin böyle sembollere…

Ama ne olur, takma onu artık, 

Hatırlatma hergün seni nasıl delice sevdiğimi…

Hem sevmiyorsun ki artık beni, 

Yetmedi mi çektiğim acı bunca zaman?', 'Hatırlarmısın sevdiğim,  Nasıl da çocuklar gibi sevinmiştin O küçük kolyeyi boynuna takdığımda?  O minik kalp, benim kalbimdi: Tüm sevgimle,...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kucuk-bir-kalp-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dila Gör Bu Cihan İçre', 'dila-gor-bu-cihan-i-cre-gevheri-lh8xs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dila gör bu cihan içre

Güzellerde bir adet var

Ne aşk var aşıktan içre

Ne onlarda sadakat var

Ne dostane safa eyler

Ne cevr ile cefa eyler

Ne ağyara vefa eyler

Ne uşşaka inayet var

Biliriz işte dilbersin

Beni öldürmek istersin

Tutalım naz-perversin

Ne bu nazda letafet var

El-insaf Gevheri kemter

Nice sevsin seni dilber

Ne bahtım bir sa''d ahter

Ne tavr u ne kıyafet var', 'Dila gör bu cihan içre Güzellerde bir adet var Ne aşk var aşıktan içre Ne onlarda sadakat var Ne dostane safa eyler Ne cevr ile cefa eyler N...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dila-gor-bu-cihan-icre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Benim Nazlı Cananım', 'ey-benim-nazli-cananim-gevheri-bwi8w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey benim nazlı cananım

Severim kimseler bilmez

Bir iştir geldi başıma

Çekerim kimseler bilmez

Bak şu kalbimin işine

Saldı sevdayı başıma

Gece gün aşk ateşine

Yanarım kimseler bilmez

Varın söylen şu hayına

Girmesin benim kanıma

Bir ateş düştü canıma

Tüterim kimseler bilmez

Gevheri ümidim Hak''tan

Yandı bu bağrım firaktan

Ey efendim derd-i aşktan

Ölürüm kimseler bilmez', 'Ey benim nazlı cananım Severim kimseler bilmez Bir iştir geldi başıma Çekerim kimseler bilmez Bak şu kalbimin işine Saldı sevdayı başıma Gec...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-benim-nazli-cananim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Peri Cihana Sen Gibi Dilber', 'ey-peri-cihana-sen-gibi-dilber-gevheri-bs7i7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey peri cihana sen gibi dilber 

Ne geldi ne gelir ne gelse gerek

La''lin gibi Lokman tiryak-ı ekber

Ne buldu ne bulur ne bulsa gerek

Cefaya başladı kadd-i mevzunum 

Ta arşa dek çıktı ah-ı derunum

Böyle giderse bu çeşm-i pürhunum

Ne güldü ne güler ne gülse gerek

Ey alem-i hüsnün sahip-kıranı 

Öldür kelp rakibi verme emanı

Öldürmezsen kendi elinle anı

Ne öldü ne ölür ne ölse gerek

Bunca dem akarken gözümden yaşlar 

Vaad etmiş iken silmeğe dilber

Ahdine durmadı ol peri-peyker

Ne sildi ne siler ne silse gerek

Gevheri güzeller gitti yabana 

Lale gibi çıktı ol mah meydana

Bu cihana benim gibi merdane

Ne geldi ne gelir ne gelse gerek', 'Ey peri cihana sen gibi dilber  Ne geldi ne gelir ne gelse gerek La''lin gibi Lokman tiryak-ı ekber Ne buldu ne bulur ne bulsa gerek Cefaya b...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ey-peri-cihana-sen-gibi-dilber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Turna Bizi Senden Sorana', 'garip-turna-bizi-senden-sorana-gevheri-i9m15', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Garip turna bizi senden sorana

Şimdi bir yavruya kuldur diyesin

Aşkın zincirini takmış boynuna

Devr içinde Mecnun oldur diyesin

Gece gündüz ağlar hiç bir dem gülmez

Unutmuş eşini dostunu bilmez

Sevmiş bir güzeli artık vazgelmez

Aşık olmak müşkül haldir diyesin

Terkeylemiş eşi ile dostunu

Abdal olmuş eğne almış postunu

Gelen geçen çiğner oldu üstünü

Ayaklar altında yoldur diyesin

A zalim engeller yolumu bağlar 

Yarimin hasreti ciğerim dağlar

Ab-ı revan olmuş durmayıp çağlar

Şol akan yaşları seldir diyesin

Gevheri der bilmem ben ne olduğum 

Gurbet illerinde durup kaldığım

Aceplemem beyim şimdi solduğum

Bülbülün mekanı güldür diyesin', 'Garip turna bizi senden sorana Şimdi bir yavruya kuldur diyesin Aşkın zincirini takmış boynuna Devr içinde Mecnun oldur diyesin Gece gündüz ...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/garip-turna-bizi-senden-sorana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Ağalar Bir Sevdaya Uğradım', 'hey-agalar-bir-sevdaya-ugradim-gevheri-vtsvw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hey ağalar bir sevdaya uğradım

Ah ettikçe gözlerimden kan gider

Avar''oldum elim ermez işime

Düşünürken akşam olur gün gider

Yaz gelince Arap atlar yarışır

Bayram gelir kanlı kinli barışır

Gözüm daim gözün ile irişir

Hilal kaşlar kirpik ile cenk eder

Atamadım aldırmadım şahımı

Artırmışım figanımı ahımı

Kaçan iller ile görsem mahımı

Sanırım ki vücudumdan can gider

Gevheri der varam yarin yanına

Yüzümü de sürem hak-i payına

Bir şeftali versen şu ben kuluna

Al yanaktan nen eksilir nen gider', 'Hey ağalar bir sevdaya uğradım Ah ettikçe gözlerimden kan gider Avar''oldum elim ermez işime Düşünürken akşam olur gün gider Yaz gelince Arap...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hey-agalar-bir-sevdaya-ugradim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Ağalar Zaman Azdı', 'hey-agalar-zaman-azdi-gevheri-c24q8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey ağalar zaman azdı 

Düşmüşe il üşer oldu

Küllükte sürünen eşek

Cins atla yarışır oldu

Palas üstünde yatmıyan 

Bıyığ''na pala batmıyan

Porsuk ardından yetmiyen

Ceylana ulaşır oldu

Evlerinin önü tazı

Yazılır turnası kazı

Yaşına yetmedik kuzu

Koç ile vuruşur oldu

Gevheri der işle hata 

Katırlar baskındır ata

Olur olmaz maslahata

Çocuklar karışır oldu', 'Hey ağalar zaman azdı  Düşmüşe il üşer oldu Küllükte sürünen eşek Cins atla yarışır oldu Palas üstünde yatmıyan  Bıyığ''na pala batmıyan Pors...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hey-agalar-zaman-azdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtulamam Üç Nesnenin Elinden', 'kurtulamam-uc-nesnenin-elinden-gevheri-6oeyx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kurtulamam üç nesnenin elinden 

Biri firkat biri gurbet biri aşk

Üçü bilmez birbirinin halinden

Biri firkat biri gurbet biri aşk

Aşktır beni sevda ile söyleten 

Firkattir cevr ile sinem dağlayan

Gurbettir gözümden kanlar akıtan

Biri firkat biri gurbet biri aşk

Bahri gibi ummanları yüzdüren 

Mecnun gibi sahraları gezdiren

Ferhad gibi dağlar başın kazdıran

Biri firkat biri gurbet biri aşk

Ben bilirim benim aklım şaşıran 

Beni sevdiğimden cüda düşüren

Muhabbet deryasın baştan aşıran

Biri firkat biri gurbet biri aşk

Gevheri der dersim aldım hocadan 

Okuyup hatmettim kara heceden

Koç yiğidi pir eyledin kocadan

Biri firkat biri gurbet biri aşk', 'Kurtulamam üç nesnenin elinden  Biri firkat biri gurbet biri aşk Üçü bilmez birbirinin halinden Biri firkat biri gurbet biri aşk Aşktır beni...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kurtulamam-uc-nesnenin-elinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecnun''a Dönmüşüm Bilmem Gezdiğim', 'mecnun-a-donmusum-bilmem-gezdigim-gevheri-c5yvt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mecnun''a dönmüşüm bilmem gezdiğim

Dağlar mıdır sahra mıdır yol mudur

Dostumun bağına girip dizdiğim

Lale midir sümbül müdür gül müdür

Aşk değil mi beni derde düşüren

Ferhad gibi yüce dağlar aşıran

Yari böyle benden ayrı düşüren

Adu mudur engel midir el midir

Kamil olan belli olur söz ilen

Al yanağa çifte benler dizilen

Mah yüzüne bölük, bölük yazılan

Kakül müdür zülüf müdür tel midir

Gevheri der bulmam kimsede vefa

Dost diye sevdiğim etti kim sefa

Hubların aşıka ettiği cefa

Kanun mudur erkan mıdır yol mudur', 'Mecnun''a dönmüşüm bilmem gezdiğim Dağlar mıdır sahra mıdır yol mudur Dostumun bağına girip dizdiğim Lale midir sümbül müdür gül müdür Aşk de...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mecnun-a-donmusum-bilmem-gezdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözün Bilmez Bazı Nadan Elinden', 'sozun-bilmez-bazi-nadan-elinden-gevheri-96clx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sözün bilmez bazı nadan elinden

Edep ağlar erkan ağlar yol ağlar

Bülbülün feryadı gonca gülünden

Gülşen ağlar bülbül ağlar gül ağlar

Eyiye hizmet et olasın eyi

Öter defler gibi sinemin neyi

Bu çarhın elinden el''aman deyi

Geda ağlar sultan ağlar kul ağlar

Her kaçan cuşedip çağlasa seller 

Açılır laleler sümbüller güller

Davulbaz çalınır çalkanır göller

Şahin ağlar turna ağlar tel ağlar

Kamil olanların bellidir yeri 

Yoluna koyarlar can ile seri

Hakkın didarını görelden beri

Gökler ağlar derya ağlar sel ağlar

Gevheri der sazın hem sözün üstüne 

Armağan eyle gel canını dosta

Kimi abdal olmuş girmiştir posta

Hırka ağlar hem post ağlar çul ağlar', 'Sözün bilmez bazı nadan elinden Edep ağlar erkan ağlar yol ağlar Bülbülün feryadı gonca gülünden Gülşen ağlar bülbül ağlar gül ağlar Eyiye h...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sozun-bilmez-bazi-nadan-elinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-ercan-alparslan-rkqxh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Henüz anladık şiir, ne zorlu san’at imiş, 

Malâyâni derler, boş bir kanaat imiş.

Eskiler dermiş her nefeste ölmez vasiyeti; 

Her bir mısrâı, şâirin bütün haysiyeti! 

Eylül 1997/İSTANBUL', 'Henüz anladık şiir, ne zorlu san’at imiş,  Malâyâni derler, boş bir kanaat imiş. Eskiler dermiş her nefeste ölmez vasiyeti;  Her bir mısrâı,...', ARRAY['Türk Edebiyatı','Şiir','Ercan Alparslan']::text[], 8.5, '{"poet":"Ercan Alparslan","poet_slug":"ercan-alparslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/siir-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Bağının Meyveleri Erişti', 'dost-baginin-meyveleri-eristi-gevheri-dwlsj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dost bağının meyveleri erişti 

Ayva benim alma benim nar benim 

Çeşmim yaşı ummanlara karıştı 

Cefakarım sitemkarım var benim 

Yedi derya boz-bulanık selinden 

Halk-ı alem aciz kaldı dilimden 

Ben bülbülüm ayrı düştüm gülümden 

Efgan benim matem benim zar benim 

Mail oldum kisvesine tacına 

Bend olmuşum siyah zülfü ucuna 

Mansur gibi asılırım saçına 

Kakül benim, perçem benim dar benim 

Gevheri der kime gönül katayım 

Gevherimi nadanlara satayım 

Dost bağında bülbül gibi öteyim 

Gülşen benim güller benim har benim', 'Dost bağının meyveleri erişti  Ayva benim alma benim nar benim  Çeşmim yaşı ummanlara karıştı  Cefakarım sitemkarım var benim  Yedi derya bo...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dost-baginin-meyveleri-eristi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şunda Bir Güzele Gönül Düşürdüm', 'sunda-bir-guzele-gonul-dusurdum-gevheri-2f09x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şunda bir güzele gönül düşürdüm 

Öpmeli kocmalı değmeli değil 

Aşkın deryasını boydan aşırdım 

Karadır gözleri sürmeli değil 

Dilber senin ile yiyüp içmedim 

Yiyüp içüp ak göğsünü açmadım 

Fırsat elde iken bel in koçmadım 

Beni öldürmeli döğmeli değil 

Dilber haram olup yola durmuşsun 

CeIlad olup cana başa kıymışsın 

Kuzum bu gün al hareler giymişsin 

Göğsü sıra sıra düğmeli değil 

Gevheri der yola durur varırlar 

Adam öldürürler kana girerler 

Çok güzeller gördüm zekat verirler 

Zekatsız dilberi sevmeli değil', 'Şunda bir güzele gönül düşürdüm  Öpmeli kocmalı değmeli değil  Aşkın deryasını boydan aşırdım  Karadır gözleri sürmeli değil  Dilber senin i...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sunda-bir-guzele-gonul-dusurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Elinden Zülf-i Kemendim Benim', 'ah-elinden-zulf-i-kemendim-benim-gevheri-bl9yr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah elinden zülf-i kemendim benim 

Müjen urdu sinem yaralandı gel 

Güzel başın içün ağlatma beni 

Dilber gam başımdan aralandı gel 

Gamdan hasar oldu mekanım yurdum 

İşidüp avazım dinlemez virdim 

Bir değil beş değil on değil derdim 

Yaralar baş verdi sıralandı gel 

Aceb gafil midir gelür mü Leyla 

Bu gam bu kasavet kalur mu böyle 

Çok tuz ekmek yedik gel helal eyle 

Bu garibin gönlü zarelendi gel 

Gevheri yar gelür haftada ayda 

Sevüp ayrılması vermeyor fayda 

Başım yastıktadır gözlerim yolda 

Gözümün beyazı karalandı gel', 'Ah elinden zülf-i kemendim benim  Müjen urdu sinem yaralandı gel  Güzel başın içün ağlatma beni  Dilber gam başımdan aralandı gel  Gamdan ha...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-elinden-zulf-i-kemendim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Efendim Bana Meylin Var İse', 'ey-efendim-bana-meylin-var-i-se-gevheri-j26xs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey Efendim, bana meylin var ise

Mahabbetin benim ile yâr olsun

Eğer senden gayri güzel seversem

Bülbül gibi işim ah ü zar olsun.

Tamahım yok bu dünyanın malına

Atlasına, dilbasına, şalına

Ben de Mecnun gibi dostun yoluna

Terkettiğim namus ile ar olsun.

T''an eyleyip niçin eli kınarım

Yad elinden giryan olup yanarım

Pervaneyim, dost şem''ine dönerim

Gam değildir, ko meskenim yâr olsun.

Gevheri der: Fırsat gitti elimden

Anın için korkum yoktur ölümden

Kim cüda kıldıysa beni gülümden

Bencileyin gonceleri hâr olsun!', 'Ey Efendim, bana meylin var ise Mahabbetin benim ile yâr olsun Eğer senden gayri güzel seversem Bülbül gibi işim ah ü zar olsun. Tamahım yok...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-efendim-bana-meylin-var-ise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-ebru-delice-fwyaf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç renk gizli içinde? 

Kaç çiçeği saklarsın gövdende? 

Kaç renk soldu? 

Kaç çiçek öldü seninle? 

Kaç bedel hayatının değeri? 

Benim bedelimden ağır mı? 

Kaç şiir, türkü..., ağıt..

Kaçı bana, kaça sana? 

Kaçı seni kaybedişime yazılı? 

13/03/2002

İstanbul

Ebru Delice', 'Kaç renk gizli içinde?  Kaç çiçeği saklarsın gövdende?  Kaç renk soldu?  Kaç çiçek öldü seninle?  Kaç bedel hayatının değeri?  Benim bedelim...', ARRAY['Türk Edebiyatı','Şiir','Ebru Delice']::text[], 8.5, '{"poet":"Ebru Delice","poet_slug":"ebru-delice","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bedel-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemalin Bağına 1', 'cemalin-bagina-1-gevheri-fijlk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cemalin bağında seyran eyledim

Bülbül sesi, gonca sesi, gül sesi

Gûşume dokundu, ihsana geldim

Ayva sesi, turunç sesi, nar sesi.

Sende ne halet var, ey peri sanem! 

Gönül verir sana her gören âdem

Kâkülünden gelir gûşume her dem

Zenci sesi, Mansur sesi, dâr sesi.

Dost ele alınca tir-ü kemanı

Gör nice eyledi divane beni

Gördüm âşıkların, tutulmuş cihanı

Efgan sesi, girye sesi, zil sesi.

Gevheri! Gözyaşım döndü ırmağa

Yine minnet düştü elden ayağa

Beni Mecnun edip düşürdü dağa

Ahu sesi, maral sesi, yâr sesi.', 'Cemalin bağında seyran eyledim Bülbül sesi, gonca sesi, gül sesi Gûşume dokundu, ihsana geldim Ayva sesi, turunç sesi, nar sesi. Sende ne ha...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cemalin-bagina-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tazelendi Alem Nevbahar Oldu', 'tazelendi-alem-nevbahar-oldu-gevheri-vclz2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tazelendi âlem nevbahar oldu

Gel sevdiğim senin ele gidelim

Açıldı her taraf sebzezar oldu

Gel efendin Şam''a doğru gidelim

Tîg-i gam ile hasmını hakla

Okunu düşmanın bağrında sakla

Küheylan at ile kargı mızrakla

Gel efendim yaylalara gidelim

Andelipsiz bağlar gülşen olmaz

Bunda gamlı gönüller şen olmaz

Bu diyarlar bana mesken olmaz

Gel efendim Şam''a doğru gidelim

İş edelim mest-i müdam olunca

Çamlıbel''de çay kenarı bulunca

Eğlenelim uz-i kasım gelince

Gel efendim Şam''a doğru gidelim

Bilemizce ola şeştar

Amma arada olmaya ağyar

Bu Gevheri bir sen bir de hizmetkar

Gel efendim çöllere doğru gidelim', 'Tazelendi âlem nevbahar oldu Gel sevdiğim senin ele gidelim Açıldı her taraf sebzezar oldu Gel efendin Şam''a doğru gidelim Tîg-i gam ile has...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tazelendi-alem-nevbahar-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neşe''ye', 'nese-ye-asli-karayel-xohst', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüzünü göğe çevirdiğinde

Koy kendini bulutların yerine

Sen en güzelisin

Hani varya biraz mavi biraz beyaz

İşte o sensin.', 'Yüzünü göğe çevirdiğinde Koy kendini bulutların yerine Sen en güzelisin Hani varya biraz mavi biraz beyaz İşte o sensin....', ARRAY['Türk Edebiyatı','Şiir','Aslı Karayel']::text[], 8.5, '{"poet":"Aslı Karayel","poet_slug":"asli-karayel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nese-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kıyas Edersin Behey Bî-vefâ', 'ne-kiyas-edersin-behey-b-vef-gevheri-1fddc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kıyas edersin behey bî-vefâ

Şu dünyada sensiz olamaz mıyım

Nice bir cefalar edersin bana

Ben kul olur sultan bulamaz mıyım

Ezelden beklerim ben gamhâneyi

Alçağa indirdin ben divâneyi

Garip baykuş gibi bir virâneyi

Mekân tutup karar kılamaz mıyım

Sihrine uğrattın şaşırttın beni

Aşk ateşi ile pişirdin beni

Bir aceb sevdâya düşürdün beni

Ya ben seni Hakk''a salamaz mıyım

Gurbete düşeli sevmişim seni

Yoluna koymuşum bu cân ü teni

Lûtf eyle kapından reddetme beni

Ayağın tozunu silemez miyim

Gevherî der yârimin menendi yok

Lebleri kandimin derdimendi çok

Gözleri harâmî kirpikleri ok

Ya ben yâr yoluna ölemez miyim', 'Ne kıyas edersin behey bî-vefâ Şu dünyada sensiz olamaz mıyım Nice bir cefalar edersin bana Ben kul olur sultan bulamaz mıyım Ezelden bekler...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-kiyas-edersin-behey-bi-vefa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kaçarsın Benden Ey Yüzü Mâhım', 'ne-kacarsin-benden-ey-yuzu-m-him-gevheri-phg40', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kaçarsın benden ey yüzü mâhım

Seni seven var mı benden ziyâde

Rûz u şeb durmayıp alırsın âhım

Âşıkım ağlatma bundan ziyâde

Gece gündüz bir visâle ermedim

Bülbül olup gonce gülün dermedim

Bu cefâlar nedir ben de bilmedim

Var mı ki bir zâlim senden ziyâde

Söyle murâdını ben de bileyim

İnsaf eyle çok ağlattın güleyim

Kabul eyle sözüm kurban olayım

Haddim yoktur sana bundan ziyâde

Hercâisin gonce gülüm kokulmaz

Geçer gider hatırcığım sorulmaz

Der Gevherî mâh yüzüne bakılmaz

Yakar hüsnün beni nârdan ziyâde', 'Ne kaçarsın benden ey yüzü mâhım Seni seven var mı benden ziyâde Rûz u şeb durmayıp alırsın âhım Âşıkım ağlatma bundan ziyâde Gece gündüz bi...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-kacarsin-benden-ey-yuzu-mahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaktı Beni Aşk Oduna O Yanmaz', 'yakti-beni-ask-oduna-o-yanmaz-gevheri-2ej2m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaktı beni aşk oduna o yanmaz

Ya ne dersin merhametsiz o yâra

Seher oldu feryadımdan uyanmaz

Umarım ki öte bülbül uyara

Ben âşıkım el göğüste yüz yerde

Gel efendim del sînemi yüz yerde

Yaralarım göz göz oldu yüz yerde

Demem yaram ne yaradır o yâra

Urdu beni zâlim kanlı yaramaz

Gayet çoktur değil benim yaram az

Bana yârdan gayri cerrah yaramaz

Umarım ki yine bağrım o yâra

Gevherî der benim yârim sanemdir

İki gözüm çaylar kurusa nemdir

Gel güzelim dudaklardan sen emdir

Müptelâyım lebler ile o yâra', 'Yaktı beni aşk oduna o yanmaz Ya ne dersin merhametsiz o yâra Seher oldu feryadımdan uyanmaz Umarım ki öte bülbül uyara Ben âşıkım el göğüst...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yakti-beni-ask-oduna-o-yanmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Kimse Eğleyemez', 'beni-kimse-egleyemez-gevheri-qsuhr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni kimse eğleyemez

Benim gönlüm alan gelsin

Tabipler bilmez ilâcım

Beni derde salan gelsin.

Mailim selvi boyuna

Melek karışmış soyuna

Soyunup uryan koynuna

Sinesine saran gelsin.

Kaşların yay, kirpiğin ok

Sana mail olanlar çok

Şu cihanda akranın yok

O kaşları keman gelsin.

Gevheri''yi kimse bilemez

Aşıkın ağlatan gülmez

İsmini söylemek olmaz

Filân kızı filân gelsin...', 'Beni kimse eğleyemez Benim gönlüm alan gelsin Tabipler bilmez ilâcım Beni derde salan gelsin. Mailim selvi boyuna Melek karışmış soyuna Soyu...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-kimse-egleyemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müstezad', 'mustezad-gevheri-ciyps', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülzar-ı hüsünsün benim ey gonca dehanım

Gülşende el canım

Atma sineme gamzen okun kaşı kemanım

Dinle bu figanım

Rahmet bu sinem yaresine ey şep-i huban

Çeşmin hele giryan

Sensiz bu kerem kânı benim şah-ı cihanım

Ey yusuf sanim

Gel etme benim hicr ile bu didemi giryan

Bağrımda bu hicran

Efganıma rahmet benim ey tuti zebanım

Ey taze civanım

Ey kaşı keman cam ile uşşak meye döndü

Kaddim neye döndü

Bu devr-i felekte hele bir Gevherî kânım

Âlemlere şanım', 'Gülzar-ı hüsünsün benim ey gonca dehanım Gülşende el canım Atma sineme gamzen okun kaşı kemanım Dinle bu figanım Rahmet bu sinem yaresine ey...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mustezad-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy sesimi', 'duy-sesimi-cahit-i-pekoglu-vcrke', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Utanacak yüzün her baktığında

sana yankılanan bir ben kalacağım.

Göz yaşın birikecek hep yastığında

senin için ağlayan bir ben kalacağım...

Gücüme gidecek

senin son sözün.

Bu muydu tohumun

bu muydu özün.

Çevirip baktığında her iki gözün

etrafında bir tek ben olacağım...

Filizlenmiş

sevda var benim içimde.

Belki gecenin biribelki üçünde

olurda beklersen beni evinde.

Sana koşarak gelen

ben kalacağım....', 'Utanacak yüzün her baktığında sana yankılanan bir ben kalacağım. Göz yaşın birikecek hep yastığında senin için ağlayan bir ben kalacağım... ...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duy-sesimi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşi yok aşkımın', 'esi-yok-askimin-cahit-i-pekoglu-42ai5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalan söylüyorsun, yalan bana

seviyorum deme gülerim sana.

Ne varsa

yok ettin aşktan yana.

Eşi yok

dünyada bendeki aşkın....

Bir tek

bakışına bin can verirdim.

Yürekten seven

insan bilirdim.

Yanımda olsan

seni vurup hüküm giyerdim.

Eşi yok

dünyada böyle bir aşkın....', 'Yalan söylüyorsun, yalan bana seviyorum deme gülerim sana. Ne varsa yok ettin aşktan yana. Eşi yok dünyada bendeki aşkın.... Bir tek bakışın...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/esi-yok-askimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göster Güzelim Hüsnüne Hayran Olayım Ben (Gazel)', 'goster-guzelim-husnune-hayran-olayim-ben-gazel-gevheri-k5hxq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göster güzelim hüsnüne hayran olayım ben

Firkatte iken diline şadan olayım ben

Ağyar ile sohbetler idüp bade içersin

Layık mı görüp hak ile yeksan olayım ben

Düşürme siyah zülfünü gerdana dökülsün

Zülfün teline ey peri kurban olayım ben

Ey nazeninim lutfun ile iznin olursa

Bir gece girip koynuna uryan olayım ben

Be Gevheri kulunu nice derde düşürdün

Bir buse virüp derdime derman olayım ben', 'Göster güzelim hüsnüne hayran olayım ben Firkatte iken diline şadan olayım ben Ağyar ile sohbetler idüp bade içersin Layık mı görüp hak ile ...', ARRAY['Türk Edebiyatı','Şiir','Gevheri']::text[], 8.5, '{"poet":"Gevheri","poet_slug":"gevheri","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/goster-guzelim-husnune-hayran-olayim-ben-gazel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Şeytanı...', 'i-cimdeki-seytani-suleyman-saylan-yewf7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İÇİMDEKİ  ŞEYTANI...

Boş bir inat uğruna yıllarımı yitirdim, 

Sevmeye yemin edip, kabuğuma çekildim.

Yalnızlık ömür boyu çilem olup sürmesin, 

İçimdeki şeytanı uyandırıver gitsin.

Akan sular duracak, güneşim parlayacak; 

Karanlığa hapsolan bu gönlüm kurtulacak, 

Damarlarım aşk ile yanarak tutuşacak... 

İçimdeki şeytanı uyandırıver gitsin.

Öpüşlerle can bulsun, göğe çıksın tepeler, 

Heyecanla titresin bedenimde her bir yer.

Ondan sonra isterse dünya olsun bir mahşer...     

İçimdeki şeytanı uyandırıver gitsin.

Yanardağlar kükresin içinde bedenimin, 

Muradına erişsin, bitsin artık özlemim, 

Su dökülmüş köz gibi sönüversin yüreğim...

İçimdeki şeytanı uyandırıver gitsin.

Süleyman SAYLAN

31.10.2000 Saat: 00.10

(Ankara-İstanbul yataklı treni restoranı (Eskişehir))    Şarkı sözü olabilir.', 'İÇİMDEKİ  ŞEYTANI... Boş bir inat uğruna yıllarımı yitirdim,  Sevmeye yemin edip, kabuğuma çekildim. Yalnızlık ömür boyu çilem olup sürmesin...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/icimdeki-seytani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçme Deme Meyhaneci', 'i-cme-deme-meyhaneci-suleyman-saylan-fkb3m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İÇME  DEME  MEYHANECİ

Çağlar oldu, coştu derdim, 

Yüreğimi yıktı derdim.

Unutmaya karar verdim...

                “İçme” deme meyhaneci, 

                Sen derdimi bilemezsin.

Nasıl içmem, bağrım yanar, 

Sevda derdim durmaz kanar.

Yüreğim hep onu anar...

                “İçme” deme meyhaneci, 

                Sen derdimi bilemezsin.

Sabaha dek içeceğim, 

Sarhoş olup düşeceğim.

Yaraları deşeceğim...

                “İçme” deme meyhaneci, 

                Sen derdimi bilemezsin.

Beni burda bırak gitsin, 

Meyhaneni kapat gitsin, 

İçkilerin hepsi bitsin...

                “İçme” deme meyhaneci, 

                Sen derdimi bilemezsin.

''İçme” deme, rahat bırak, 

Onsuz kalan kalbim kurak.

Sen de sever, yanarsın bak...

                “İçme” deme meyhaneci, 

                Sen derdimi bilemezsin.

“İç! ” de artık, sen de kurtul, 

Bu ne ilktir, ne de sondur.

Kadehime içki doldur...

                “İçme” deme meyhaneci, 

                Sen derdimi bilemezsin.

Benim için bu son çare, 

Çare oldu içmek, derde.

Erkeklik var bir de serde...

                “İçme” deme meyhaneci, 

                Sen derdimi bilemezsin.

Süleyman SAYLAN

(Ankara,  04-20.04.1994, Saat: (Gecelerin geç saatleri)) 

Şarkı sözü olabilir.', 'İÇME  DEME  MEYHANECİ Çağlar oldu, coştu derdim,  Yüreğimi yıktı derdim. Unutmaya karar verdim...                 “İçme” deme meyhaneci,    ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/icme-deme-meyhaneci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '... Sevdaya Gömdüm.', 'sevdaya-gomdum-suleyman-saylan-nlvrq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '... SEVDAYA  GÖMDÜM.

Yılları boş yere sevdaya gömdüm, 

Mum tükendi artık, ışığı söndü.

Sevda diye diye tükenen ömrüm, 

Serseri mayında fitile döndü.

Yaşam zor derlerse sakın inanma, 

Sevdayla geçmişse ömrüne yanma, 

Körükle yangını sönecek sanma...

Yüreğim aşkınla deliye döndü.

Haydi deneyelim tekrar sevmeyi, 

Kuşun kanadında uçup gezmeyi.

Ben seni, sen beni mutlu etmeyi...

Sevdada talihim seninle döndü.

Bitecekse ömrüm seninle bir gün, 

Bugün bayram olsun, yarınlar düğün.

Sensiz kalacaksam eğer, ölürüm...

Sevdada talihim seninle döndü.

Süleyman SAYLAN

Ankara,15.07.1997  Şarkı sözü olarak yazılmıştır.', '... SEVDAYA  GÖMDÜM. Yılları boş yere sevdaya gömdüm,  Mum tükendi artık, ışığı söndü. Sevda diye diye tükenen ömrüm,  Serseri mayında fitil...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdaya-gomdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Yansın Ağalar Güneş Tutulsun', 'ay-yansin-agalar-gunes-tutulsun-koroglu-45tny', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ay yansın ağalar güneş tutulsun

Parladı parladı çalın kılıncı

Oklar gıcırdasın ayyuka çıksın

Mevlanın aşkına basın kılıncı

Durmayın orada kargı kucakta 

Dolansın yiğitler köşe bucakta

Bir savaş edelim kelle kucakta

Şehitler aşkına çalın kılıncı

Koç yiğitler melemeli dev gibi 

Düşman kanı devrilmeli dağ gibi

Dest vurun avını almış bey gibi

Haykırı haykırı çalın kılıncı

Koç yiğitler bu kış burda kışlasın 

Yılan dili eğri hançer işlesin

Kafir düşman el''amana başlasın

Kaçanı göndermen basın kılıncı

Koç yiğitler düğün bayram eylesin 

Küheylan kişnesin aygır oynasın

Kazanlarda adam kanı kaynasın

Esir etmek yok ha çalın kılıncı

Yürü yiğit beyler namımız kalsın 

Kelle getirenler bahşişin alsın

Öldürün atların hep yayan kalsın

Yaya kalana da çalın kılıncı

Koç Köroğlu girdi meydan almaya 

Nara vurup düşmanına dalmaya

Yemin ettim yedi derya dolmaya

Doldurun denizi basın kılıncı', 'Ay yansın ağalar güneş tutulsun Parladı parladı çalın kılıncı Oklar gıcırdasın ayyuka çıksın Mevlanın aşkına basın kılıncı Durmayın orada ka...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ay-yansin-agalar-gunes-tutulsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim İllerin Beyleri', 'bizim-i-llerin-beyleri-koroglu-072eo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bizim illerin beyleri

Yakar kandili kandili

İçip arslana dönerler

Kadeh döndürü döndürü

Hem içerler hem kanarlar

Düşmana meydan ararlar

Arap atlara binerler

Boyun sündürü sündürü

Çürüdü gönlüm çürüdü

İçerde yürek eridi

Beylerin kolu yoruldu

Kılıç döndürü döndürü

Beyler n''eyleyip n''idelim

Güzellerle göç edelim

Meydanda at oynatalım

Boynun döndürü döndürü

Köroğlu der ki karıdım

İhtiyar oldum çürüdüm

At yoruldu ben yoruldum

Güzel bindiri bindiri', 'Bizim illerin beyleri Yakar kandili kandili İçip arslana dönerler Kadeh döndürü döndürü Hem içerler hem kanarlar Düşmana meydan ararlar Arap...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bizim-illerin-beyleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çar Köşe Fani Dünyada', 'car-kose-fani-dunyada-koroglu-nkawc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çar köşe fani dünyada

Koç yiğitler olmasaydı

Dünyayı zulmet alırdı

Ağlayanlar gülmeseydi

Dünyayı zulüm alırdı

Gün doğmaz öyle kalırdı

Aşıklar mecnun olurdu

Sevdiceğin'' görmeseydi

Sevdiğim karşımda salın

Bilmez misin aşık halin

Yare gönderdiğim gülün

Yapracığı solmasaydı

Vur a koç Köroğlu vur a

Yar derdi ne derman ara

Ölüme bulurdun çare

Emir Hak''tan olmasaydı', 'Çar köşe fani dünyada Koç yiğitler olmasaydı Dünyayı zulmet alırdı Ağlayanlar gülmeseydi Dünyayı zulüm alırdı Gün doğmaz öyle kalırdı Aşıkla...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/car-kose-fani-dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik', 'eksik-atila-gunal-dtak9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlaşılır olmak için

Anlatmak istemiyorum sana...

Anladıklarını da anlatma

Anlattıkların anlamadıkların...', 'Anlaşılır olmak için Anlatmak istemiyorum sana... Anladıklarını da anlatma Anlattıkların anlamadıkların......', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/eksik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle Sözlerimi Han Oğlum Ayvaz', 'dinle-sozlerimi-han-oglum-ayvaz-koroglu-9cz6h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dinle sözlerimi han oğlum Ayvaz

Yükletin kervanı dengine bakın

Erlik meydanına girdiğin zaman

Kuşanın kılıcı gencine bakın 

Düşmanın üstüne eyledim akın

Dönüşüm yok zamanın yakın

Fakir fukarayı incitmen sakın

Mal yemez tamahkar zengine bakın 

Köroğlu her zaman kurdu meydanı

Ben bilirim yahşi ile yamanı

Aman dileyenden kesmen amanı

Dertli olanların derdine bakın', 'Dinle sözlerimi han oğlum Ayvaz Yükletin kervanı dengine bakın Erlik meydanına girdiğin zaman Kuşanın kılıcı gencine bakın  Düşmanın üstüne ...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dinle-sozlerimi-han-oglum-ayvaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Kendülerde Erlik Var İse', 'eger-kendulerde-erlik-var-i-se-koroglu-cduj0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer kendülerde erlik var ise

Gelsin döğüşelim Bolu Beyleri

Kanından susayıp candan geçerse

Gelsin döğüşelim Bolu Beyleri

Atına binende eyledi dizgin 

Alayları çatıp eyledi bozgun

Leşine kondurmak isterse kuzgun

Gelsin döğüşelim Bolu Beyleri

Koç yiğitleri aldım da yanıma 

Keskin kılıcımı çaldım belime

Serimden geçmişim bakmam ölüme

Gelsin döğüşelim Bolu Beyleri

Karşımda durana kalmaz kararım 

Doğrulup gelene yoktur zararım

Ya şehitlik ya gazilik dilerim

Gelsin döğüşelim Bolu Beyleri

Ala sadağımı sundum özüme 

Hezaran kalkanım aldım dizime

Köroğlu der kan göründü gözüme

Gelsin döğüşelim Bolu Beyleri', 'Eğer kendülerde erlik var ise Gelsin döğüşelim Bolu Beyleri Kanından susayıp candan geçerse Gelsin döğüşelim Bolu Beyleri Atına binende eyle...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eger-kendulerde-erlik-var-ise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoylu''m', 'hoylu-m-koroglu-hjafg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bağdat''a sefer edenler,

Hoylu''m nic''oldu gelmedi? 

Turna teline gidenler,

Hoylu''m nic''oldu gelmedi? 

Bagdat''a sefer eyledim,

Hoylu''m da kaldi gelmedi.

Acem ile ceng eyledim,

Hoylu''m da kaldı gelmedi. 

Düğünü bozup gidenler,

Badeyi süzüp gidenler,

Acem ile ceng edenler,

Hoylu''m nic''oldu gelmedi. 

N''olsam koç Köroğlu n''olsam,

Hoylu''yu düşümde görsem,

N''olaydı da ben de ölsem? 

Hoylu''m da kaldı gelmedi.', 'Bağdat''a sefer edenler, Hoylu''m nic''oldu gelmedi?  Turna teline gidenler, Hoylu''m nic''oldu gelmedi?  Bagdat''a sefer eyledim, Hoylu''m da kald...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hoylu-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimisi Pınar Başında', 'kimisi-pinar-basinda-koroglu-nwote', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimisi pınar başında

Kimisi yolun dışında

Al giyen on beş yaşında

İlle mavili mavili

Kimisi dağlarda gezer

Kimisi incisin dizer

Al giyen bağrımı ezer

İlle mavili mavili

Kimisi odun devşirir

Kimisi kahve pişirir

Al giyen aklım şaşırır

İlle mavili mavili

Köroğlu''m der ki n''olacak

Takdir yerini bulacak

Mavilim kaldı alacak

İlle mavili mavili', 'Kimisi pınar başında Kimisi yolun dışında Al giyen on beş yaşında İlle mavili mavili Kimisi dağlarda gezer Kimisi incisin dizer Al giyen bağ...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimisi-pinar-basinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhanetlik Etmek Değil Karımız', 'muhanetlik-etmek-degil-karimiz-koroglu-hag5z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Muhanetlik etmek değil karımız 

Şehriyar sözüne uyanlardanız

Meydana girende yoktur korkumuz

Kazaya ırıza diyenlerdeniz

Ödleklerle hoş değildir aramız 

Teke tek düşmana varmak töremiz

Muhanete sardırmayız yaramız

Yarayı kendimiz saranlardanız

Bineyidim kır atımın üstüne 

Alayıdım hançerimi destime

Gafili varmayız düşman üstüne

Vakta hazır olun diyenlerdeniz', 'Muhanetlik etmek değil karımız  Şehriyar sözüne uyanlardanız Meydana girende yoktur korkumuz Kazaya ırıza diyenlerdeniz Ödleklerle hoş değil...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/muhanetlik-etmek-degil-karimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağ Elde Kılınç Ettiğim', 'sag-elde-kilinc-ettigim-koroglu-zkgfi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sağ elde kılınç ettiğim

Sol elde kalkan tuttuğum

Kol kola sarılıp yattığım

Şirin Döne yerinde mi

Kılınç deyu bağlandığın 

Kalkan deyu kullandığın

Seyreyleyip eğlendiğin

Şirin Döne saçın yoluk

Çamlıbel''in koyağında 

Sular akar ayağında

Şirin Döne yanağında

Ürüşen benler yerinde mi

Çamlıbel''in koyağında 

Su kesilmiş ayağında

Güzel Döne yanağında

Kibar benler soluk soluk

Küçücükten büyüttüğüm 

Saz çalarak uyuttuğum

Mah yüzünü seyrettiğim

Han Ayvaz''ım yerinde mi

Küçücükten büyüttüğün 

Ürgüleyip uyuttuğun

Gül yüzünü seyrettiğin

Han Ayvaz''ın boynu buruk

Köroğlu der öğündüğün 

Taşlar alıp dövündüğün

Arka verip sığındığın

Koca çamlar yerinde mi

Güdümen der karlı dağlar 

Dağda çamlar kara bağlar

Döne söyler Ayvaz ağlar

Ağlaşırlar soluk soluk', 'Sağ elde kılınç ettiğim Sol elde kalkan tuttuğum Kol kola sarılıp yattığım Şirin Döne yerinde mi Kılınç deyu bağlandığın  Kalkan deyu kullan...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sag-elde-kilinc-ettigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Verdim Selam Almaz', 'selam-verdim-selam-almaz-koroglu-oq44q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Selam verdim selam almaz 

Selamıma salam seni

Akçasız pulsuz aşıkım

Nasıl benim kılam seni

Hubluğuna yok bahane 

Gözlerin benzer şahana

Namın çıkmıştır cihana

Bilir cümle alem seni

Nazlım salınır gezersin 

Dertli bağrımı ezersin

Beyaz kağıda benzersin

Yazar m''ola kalem seni

Malım yok ki dökem saçam 

Hazinem yok ağız açam

Çarem budur alam kaçam

Hep yanımda bulam seni

Yeni bahçenin narısın 

Kırmızı gülden arısın

Koç Köroğlu''nun yarısın

Böyle misin bilem seni', 'Selam verdim selam almaz  Selamıma salam seni Akçasız pulsuz aşıkım Nasıl benim kılam seni Hubluğuna yok bahane  Gözlerin benzer şahana Namı...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/selam-verdim-selam-almaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Kaküllerin Dökmüş', 'siyah-kakullerin-dokmus-koroglu-mqghr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Siyah kaküllerin dökmüş

Kızıl güllere güllere

Ela gözlerini dikmiş

İnce yollara yollara

Gel Ayvaz''ım dolaşalım

Çamlı bellere bellere

Doldur elinden içeyim

Mest olup serden geçeyim

Seninle bile göçeyim

Uzak illere illere

Gel Ayvaz''ım dolaşalım

Çamlı bellere bellere

Okursun aşkın kitabın

Komadın aşıkın ta''bın

Akıttın çeşmimin abın

Döndü sellere sellere

Gel Ayvaz''ım dolaşalım

Çamlı bellere bellere

Aşıklara vardır meyli

Riyazet çekmişem hayli

Ben Mecnun olam sen Leyli

Düşüp çöllere çöllere

Gel Ayvaz''ım dolaşalım

Çamlı bellere bellere

Köroğlu der budur derdim

Sarardı çehre-i zerdim

Şu benim nihanî derdim

Düştü dillere dillere

Gel Ayvaz''ım dolaşalım

Çamlı bellere bellere', 'Siyah kaküllerin dökmüş Kızıl güllere güllere Ela gözlerini dikmiş İnce yollara yollara Gel Ayvaz''ım dolaşalım Çamlı bellere bellere Doldur ...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/siyah-kakullerin-dokmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam', 'bu-aksam-ercan-alparslan-b06ay', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gurûb vakti bu akşam

Bir şeyler oluyor bana...

Karlı dağların ardından

Bir vadiden sevgilim sana

Haykırmak istiyorum! 

Lakin tüketmiş sözü şairler

Gurûba dair ne varsa! 

Oysa benim, 

Sözlerden öte gözlerim

Kızıl ufuklarda ağlar...

Erzurum dağlarında kar gibi

Gönlüm erir, ruhum göçer.

Ufuk siyah, yol uzun, gök bulutlu...

Ne gözlerim, ne de ayaklarım 

Yürümekten umutlu! 

Ne düşünmek ne de yazmak, 

En güzeli sana sarılmak; 

Elele İstanbul baharında...

Ah sevgilim! Unutma beni unutma! ...

1999/ERZURUM', 'Gurûb vakti bu akşam Bir şeyler oluyor bana... Karlı dağların ardından Bir vadiden sevgilim sana Haykırmak istiyorum!  Lakin tüketmiş sözü ş...', ARRAY['Türk Edebiyatı','Şiir','Ercan Alparslan']::text[], 8.5, '{"poet":"Ercan Alparslan","poet_slug":"ercan-alparslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-aksam-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceden Gündüze', 'geceden-gunduze-ercan-alparslan-0nxfk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece yağan üstümüze, 

Kahır, elem ve hüzün! 

Zaman akarken gündüze, 

Aydınlatır elbet, bizi gün.

Malûm kolay olmamıştı zira, 

Çöl sıcağında yeşerirken gül.

Cihana feyz vermek için Hîra, 

Bekledi hayli, yüce bir gönül! 

İstanbul', 'Gece yağan üstümüze,  Kahır, elem ve hüzün!  Zaman akarken gündüze,  Aydınlatır elbet, bizi gün. Malûm kolay olmamıştı zira,  Çöl sıcağında ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Alparslan']::text[], 8.5, '{"poet":"Ercan Alparslan","poet_slug":"ercan-alparslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/geceden-gunduze-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tan Yeri Atmadan Şafak Sökende 1', 'tan-yeri-atmadan-safak-sokende-1-koroglu-zvyun', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tan yeri atmadan şafak sökende 

Düşmanın üstüne hörelenmeli

Düşman kalkan alıp kılıç çekende

Yiğit on beş yerinden yaralanmalı

Haber aldım ihvanından kulundan 

Doyuk olduk akçasından pulundan

Hey ağalar akan kanın alından

Altımızda Kır-At kınalanmalı

Köroğlu''m der Mirza gele Han gele 

Ben isterim günde yüz tufan gele

Derelerden oluk oluk kan gele

Sele düşüp gövde kürelenmeli', 'Tan yeri atmadan şafak sökende  Düşmanın üstüne hörelenmeli Düşman kalkan alıp kılıç çekende Yiğit on beş yerinden yaralanmalı Haber aldım i...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tan-yeri-atmadan-safak-sokende-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğit Olan Gümbür Gümbür Gürlesin', 'yigit-olan-gumbur-gumbur-gurlesin-koroglu-8nzjs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yiğit olan gümbür gümbür gürlesin

Yiğidi doğuran ana bin yaşa

Ak gövdede kızıl kanlar şorlasın

Yiğidi doğuran ana bin yaşa

Davlumbazlar yeğde yeğde vuranda 

Çarkacılar sallı solu dönende

Eğri kılıç ak gövdeyi bölende

Yiğidi doğuran ana bin yaşa

Gele beyler cenge harbi çalınsın 

Çamlıbel askeri ayrı bölünsün

Gece gündüz darbı meydan kurulsun

Yiğidi doğuran ana bin yaşa

Asıl koç yiğitler pusuda saklı 

Belleri kılıçlı eli mızraklı

Hep şahin bakışlı arslan sıfatlı

Yürü kan içenler hep binler yaşa

Köroğlu der bugün burda duralım 

Sabah olsun darbı meydan kuralım

Akan kandan dolu şarap vuralım

Yürü Deli Hoylu''m sen binler yaşa', 'Yiğit olan gümbür gümbür gürlesin Yiğidi doğuran ana bin yaşa Ak gövdede kızıl kanlar şorlasın Yiğidi doğuran ana bin yaşa Davlumbazlar yeğd...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yigit-olan-gumbur-gumbur-gurlesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğitler Silkinip Ata Binende 1', 'yigitler-silkinip-ata-binende-1-koroglu-c0apt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yiğitler silkinip ata binende

Derelere aç kurtlara ün olur

Yiğit olan döne döne dövüşür

Kötüler kavgadan kaçar hun olur

Bir yiğit cidasın almış eline

Başın koymuş yiğitliğin yoluna

Kalkan paralana zırhlar deline

Kanlı gömlek koçyiğide don olur

Bir yiğit cidasın almış atıyor

Ağ elleri kızıl ana batıyor

Kötü yoldaşını koymuş kaçıyor

Kaçma kötü kaçma şimdi dön olur

Hasım da çağırır figan ağıtlar

İman ehli birbirini öğütler

Boydan boya demir donlu yiğitler

Çalar cıdasını kahraman olur

Köroğlu da der ki kalmayın naçar

Serçenin gönlünden şahinlik geçer

Şahini görünce ormana kaçar

Gider tenhalarda kahraman olur', 'Yiğitler silkinip ata binende Derelere aç kurtlara ün olur Yiğit olan döne döne dövüşür Kötüler kavgadan kaçar hun olur Bir yiğit cidasın al...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yigitler-silkinip-ata-binende-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devâ', 'dev-ercan-alparslan-igbef', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoktur âşığın derdine devâ, 

Ayrılığı, hem kavuşması cana bin cefâ, 

Lâkin gönül istemez aşktan gayrı hevâ, 

Bir kez olsun görmese de ömründe vefâ! 

İSTANBUL', 'Yoktur âşığın derdine devâ,  Ayrılığı, hem kavuşması cana bin cefâ,  Lâkin gönül istemez aşktan gayrı hevâ,  Bir kez olsun görmese de ömründ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Alparslan']::text[], 8.5, '{"poet":"Ercan Alparslan","poet_slug":"ercan-alparslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deva-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Verin (Ayvaz Geliyor)', 'yol-verin-ayvaz-geliyor-koroglu-qj7uj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yol verin dumanlı dağlar

Aşmaya Ayvaz geliyor

Çağlasın soğuk pınarlar

İçmeye Ayvaz geliyor

Bu dağlarda biten güller

Kokuşu lal eder diller

Dalında cüda bülbüller

Ötüşün Ayvaz geliyor

Bizim yaylanın yiğidi

Belinde gümüş dividi

Yaylanın servi, söğüdü

Gölg''edin Ayvaz geliyor

Bizim yaylalar oluklu

Akar suları balıklı

Al vafalı. mor yelekli

Kız gerek Ayvaz geliyor

Bizim yaylanın uşağı

Belinde Aydın bıçağı

Yaylanın türlü çiçeği

Kokuşun Ayvaz geliyor

Köroğlu der ki tayalar

Ati''imiz hayvan kovalar

Sarptaki yalçın kayalar

Yassılın Ayvaz geliyor', 'Yol verin dumanlı dağlar Aşmaya Ayvaz geliyor Çağlasın soğuk pınarlar İçmeye Ayvaz geliyor Bu dağlarda biten güller Kokuşu lal eder diller D...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yol-verin-ayvaz-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-ercan-alparslan-g4q34', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerime çekilen siyah perdedir ince, 

Narin bir el gibi uzanır üstüme gece...

İSTANBUL', 'Gözlerime çekilen siyah perdedir ince,  Narin bir el gibi uzanır üstüme gece... İSTANBUL...', ARRAY['Türk Edebiyatı','Şiir','Ercan Alparslan']::text[], 8.5, '{"poet":"Ercan Alparslan","poet_slug":"ercan-alparslan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gece-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürün Beyler Korkman', 'yurun-beyler-korkman-koroglu-bzqhl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yürün beyler korkman gününüz doğdu 

Alın kaleleri burçları şimdi

Bir savaş edelim Çin Maçin ile

Basın dereleri leşleri şimdi

Köroğlu''m çıkalım dağlar salına 

At sürelim mal yemezin malına

Başım koydum arkadaşın yoluna

Başı dost yoluna koyanlardanız', 'Yürün beyler korkman gününüz doğdu  Alın kaleleri burçları şimdi Bir savaş edelim Çin Maçin ile Basın dereleri leşleri şimdi Köroğlu''m çıkal...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yurun-beyler-korkman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nefes', 'bir-nefes-ercan-alparslan-pkhpt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne bir ses, ne de bir nefes

Gelir o vefâsız yardan! 

Kalmadı bende eski heves, 

Şuh edâlı, gül kokulu bahardan...

Eylül/İSTANBUL', 'Ne bir ses, ne de bir nefes Gelir o vefâsız yardan!  Kalmadı bende eski heves,  Şuh edâlı, gül kokulu bahardan... Eylül/İSTANBUL...', ARRAY['Türk Edebiyatı','Şiir','Ercan Alparslan']::text[], 8.5, '{"poet":"Ercan Alparslan","poet_slug":"ercan-alparslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-nefes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlı Dağların Ardından', 'karli-daglarin-ardindan-koroglu-bm60l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karlı dağların ardından

Yel olup estiğin var mı

Tek başına bu çöllerde

Ordular bastığın var mı

Kargıyı ucundan salla

Düşman deme eyvallah

Her taraftan üç beş kelle

Terkiden astığın var mı

Köroğlu söyle sanından

Kuş uçurmaz divanından

Avuçla düşman kanından

Doldurup içtiğin var mı', 'Karlı dağların ardından Yel olup estiğin var mı Tek başına bu çöllerde Ordular bastığın var mı Kargıyı ucundan salla Düşman deme eyvallah He...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karli-daglarin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acının Sınırlarında Hep Ben', 'acinin-sinirlarinda-hep-ben-zeynep-civan-9gk2x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nisan sonrası yağan yağmur

Çatlak duvarlardan süzülüp yüzümü bulur

Böylece girer düşlerime mavi bir bulutsuzluk

Düşüm yağmursuz bir gökyüzü

Gel desem sevgiliye gel, rüzgarla gel, yağmurla gel, güneşle gel, 

Gel desem

Dilim belkide kalbimden utanır

Kalbime saklayandım düşlerimi

Oysa söylemek yazgı olup dolanmış dilime

Kaderle sınanmak bedeliymiş mutluluğun

Geç farkettim

Bütün dostlara karşın

Kendime özgü sevdim

Aşkın tarihi yalanmış

Olsun, biz yalan olanı seçtik sevgili

Ve şimdi solgun fotoğraflarda can bulan

Bir ben kaldım birde sen yağmurla gelen', 'Nisan sonrası yağan yağmur Çatlak duvarlardan süzülüp yüzümü bulur Böylece girer düşlerime mavi bir bulutsuzluk Düşüm yağmursuz bir gökyüzü ...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Civan']::text[], 8.5, '{"poet":"Zeynep Civan","poet_slug":"zeynep-civan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/acinin-sinirlarinda-hep-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldığım Nefesimsin', 'aldigim-nefesimsin-erhan-saka-anopw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni ilk görüşte tutuldum kaldım, 

Gözlerin içinde deryaya daldım, 

Kendimi cennette bir yerde sandım, 

Sen benim aldığım her nefesimsin.

Güneşi istemem doğmasın varsın, 

Dünyamın ışığı sen yanımdasın, 

Bitmeyen geceler sabah olmasın, 

Sen benim aldığım her nefesimsin.

Canıma can kattın, ömrüme ömür, 

Acıyı bilirim yüzümü güldür, 

İstersen canımı al, beni öldür, 

Sen benim aldığım her nefesimsin.', 'Seni ilk görüşte tutuldum kaldım,  Gözlerin içinde deryaya daldım,  Kendimi cennette bir yerde sandım,  Sen benim aldığım her nefesimsin. Gü...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aldigim-nefesimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Korusun', 'allah-korusun-erhan-saka-7trcw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşanan yaşandı mazide kaldı, 

İkimiz yabancı birer insanız, 

Unuttu diyemem anısı vardı, 

Bir daha sevmek mi Allah korusun.

Ölürüm unutmam son bakışını, 

Kalbime çiviyle ismini yazdı, 

Ağlayıp kapıdan o çıkışını, 

Bir daha sevmek mi Allah korusun.

Yokluğun kopardı beni dünyadan, 

Şimdi yaşadığım hayat sıradan, 

Mutluyum sananlar bilmez yalandan, 

Bir daha sevmek mi Allah korusun.', 'Yaşanan yaşandı mazide kaldı,  İkimiz yabancı birer insanız,  Unuttu diyemem anısı vardı,  Bir daha sevmek mi Allah korusun. Ölürüm unutmam ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/allah-korusun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürün Aslanlarım Savaş Edelim', 'yurun-aslanlarim-savas-edelim-koroglu-5tbvn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürün aslanlarım savaş edelim

Buna kavga derler bey ne paşa ne

Haykırıp haykırıp kelle keselim

Seyreyleyin eli ayağı şaşana

Yürü beyler cenge harbi çalınır

İyi kötü bu meydanda bilinir

Kılıç değer adam iki bölünür

Nusret bizim beyler neci paşa ne

Gürzün kösteğini kola takmalı

Arap atı sağa sola yıkmalı

Kargılar mızraklar birden kalkmalı

Fırsat vermen Arap atlar kaçana

Köroglu der durman edek cengimiz

Bundan belli olsun yiğit hangimiz

Üç saat sürmeli burda hengimiz

Tarih yazın şu dağlara nişane', 'Yürün aslanlarım savaş edelim Buna kavga derler bey ne paşa ne Haykırıp haykırıp kelle keselim Seyreyleyin eli ayağı şaşana Yürü beyler ceng...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yurun-aslanlarim-savas-edelim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hâtıra', 'h-tira-ercan-alparslan-umkxf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şey hâtıradan ibarettir zannımca, 

Gelecek de döner geçmişe bir zaman sonra.

Ve gün gelip de varınca son durağa ömür...

Mâzinin yâdıyla gözlerden yaşlar süzülür! 

1996/İSTANBUL', 'Her şey hâtıradan ibarettir zannımca,  Gelecek de döner geçmişe bir zaman sonra. Ve gün gelip de varınca son durağa ömür... Mâzinin yâdıyla ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Alparslan']::text[], 8.5, '{"poet":"Ercan Alparslan","poet_slug":"ercan-alparslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hatira-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Yangınlar', 'beyaz-yanginlar-cemil-neseliler-ksvxc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şahlanmış gem tutmaz coşkun yüreğimiz

Kimler takmaya çalıştıysa beyhude ferman dinlemez benliğimiz

Varsın gayretler çabalar olsun, olacak da...

Ruhlar can kafesinde değil, bedensiz düşüncemiz

Deryada sefere çıkmış, yelkeni sevgimiz

Rüzgarı  candan saf muhabbetimiz

Hasret kokacak buram buram özlemimiz

Kimi gün dar gelecek evimiz memleketimiz

Akşamın ufkunda yayılı dizi dizi yıldızlar

Kehkeşan şahit, biri var ki farklı ışıldar

Ne başka bir güneşten alır ışığını

Ne karanlıkta arar esrarlı yolunu

Sinesinden saçar pare pare ateşi

Söndürmez hortumlar, ummanlar  yanmış alevi

Sular döktüm, gazyağı misali tutuşturdu denizi

Ateşi ateş söndürür,  bilirim tek çare ilacı', 'Şahlanmış gem tutmaz coşkun yüreğimiz Kimler takmaya çalıştıysa beyhude ferman dinlemez benliğimiz Varsın gayretler çabalar olsun, olacak da...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beyaz-yanginlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağların Salından Süzülüp İnen', 'daglarin-salindan-suzulup-i-nen-koroglu-eg0hy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağların salından süzülüp inen

Üstü gümüş çullu Kır-Atım benim

Varmış düşmüş bir leke bey eline

Üstü gümüş çulludur, atım benim

Gümüş uyan vurup kişnedem derdim

Seni bir civana besledem derim

Ağalara beylere gösterem derdim

Üstü gümüş çullu Kıratım benim

İki selseli var eli körüklü

Üstüne binenler ejder börüklü

Son demde de kardeş gibi yürekli

Üstü gümüş çullu Kıratım benim

Altıdır, yedidir, sekizdir yaşı

Büyüktür gövdesi küçüktür başı

Şah Hüseyin biner, bir de kardaşı

Üstü gümüş çullu Kıratım benim

Köroğlu der; görebilsem yüzünü

Makramalar alsam silsem gözünü

Şam''da oynatmışlar, gördüm izini

Üstü gümüş çullu Kıratım benim', 'Dağların salından süzülüp inen Üstü gümüş çullu Kır-Atım benim Varmış düşmüş bir leke bey eline Üstü gümüş çulludur, atım benim Gümüş uyan v...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/daglarin-salindan-suzulup-inen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davran Kırat Davran', 'davran-kirat-davran-koroglu-jlunn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Davran Kırat davran, yokuşa davran

Yokuşun başında soyuldu kervan

Düşman karşısında ne yapsın savran

Estir Kıratım es, yare gidelim

Dost, düşman içinde sıla edelim

Kıratı sorarsan yedidir yaşı

İridir gövdesi, ufaktır başı

Dizgini çekende un eder taşı

Estir Kıratım es, yare gidelim

Dost, düşman içinde sıla edelim

Yokuşa yukarı tavşan sekişlim

Bayıra aşağı ceylan büküşlüm

Alnı akıtmalı, göğsü nakışlım

Estir Kıratım es, yare gidelim

Dost, düşman içinde sıla edelim', 'Davran Kırat davran, yokuşa davran Yokuşun başında soyuldu kervan Düşman karşısında ne yapsın savran Estir Kıratım es, yare gidelim Dost, dü...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/davran-kirat-davran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Perçemli Kıratım', 'kiz-percemli-kiratim-koroglu-x9y92', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çamlıbel''e süreyidim yolunu

Altınlardan nalladayım nalını

Üç güzele dokutayım çulunu

Alma gözlü kız perçemli Kıratım

Başını başımdan yukarı tutar

Haykırır köpüğü başından atar

Kaçarsa kurtulur, kovarsa tutar

Alma gözlü kız perçemli Kıratım', 'Çamlıbel''e süreyidim yolunu Altınlardan nalladayım nalını Üç güzele dokutayım çulunu Alma gözlü kız perçemli Kıratım Başını başımdan yukarı ...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kiz-percemli-kiratim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Kırat Gözüm Kırat', 'canim-kirat-gozum-kirat-koroglu-ktrpj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canım Kırat, gözüm Kırat

Kaçıp çekilip gidelim

Her yanında çifte kanat

Uçup çekilip gidelim

Budur Kıratın durağı

Bilmez yakını ırağı

Ab-ı kevserdir sulağı

İçip çekilip gidelim

Köroğlu söyler ezeli

Bağlar döküyor gazeli

Silistre''den güzeli

Alıp çekilip gidelim', 'Canım Kırat, gözüm Kırat Kaçıp çekilip gidelim Her yanında çifte kanat Uçup çekilip gidelim Budur Kıratın durağı Bilmez yakını ırağı Ab-ı ke...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/canim-kirat-gozum-kirat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Sevdiğim Kırat', 'gozlerin-sevdigim-kirat-koroglu-692fg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin sevdiğim Kırat

Seherde gelir geçersin

Şah ordusunda bir civan

Uyarmaz, alır kaçarsın

Dilersin haktan dileğin

Ab-Zemzemden sulağın

...................

Dolusun içip gidersin

Gördükte düşman alayın

Kodurmaz asılı yayın

Şikar almış şahinleyin

Parlayıp geçip gidersin

İrgür aşıkı dostuna

Buluşun çeşm-i mestine

Düşmüşsün gemin üstüne

Köpüğün saçıp gidersin

Köroğlu, bekle yerini

Giymiştir demir yeleği

Gidi düşmandan arzuyu

Haklayıp çarpıp gidersin', 'Gözlerin sevdiğim Kırat Seherde gelir geçersin Şah ordusunda bir civan Uyarmaz, alır kaçarsın Dilersin haktan dileğin Ab-Zemzemden sulağın ....', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerin-sevdigim-kirat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yiğit Benim Diyende', 'bir-yigit-benim-diyende-koroglu-n4ycr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yiğit, ''benim'' diyende

Kaynayıp da coşmamalı

İşin icrasın bilmeyen

Hiç haddinden aşmamalı

Kalmadı beyler, malımdan

Kimse bilmez ahvalımdan

Güzelleri illerinden

Almayınca gelmemeli

Köroğlu der: koçyiğitler

Hazırlansın arap atlar

Sandığa giren yiğitler

Bu sandıktan çıkmamalı', 'Bir yiğit, ''benim'' diyende Kaynayıp da coşmamalı İşin icrasın bilmeyen Hiç haddinden aşmamalı Kalmadı beyler, malımdan Kimse bilmez ahvalımd...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-yigit-benim-diyende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seferim Var Gürcistan''a', 'seferim-var-gurcistan-a-koroglu-4tyf7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seferim var Gürcistan''a

Benim ile göçen gelsin

İnmesin namert meydana

Candan, serden geçen gelsin

İçtiğimiz aslan kanı

Yediğimiz süleymani (1)

Kılıç kabzasından kanı

Şerbet edip içen gelsin

Kulak tut merdin sözüne

İnelim meydan yüzüne

Ecel gömleğin özüne

Kend''eliyle biçen gelsin

Köroğlu bir genç aslandır

...........................

Döğüş bir düğün, bayramdır

Candan, serden geçen gelsin

(1)  Süleymani: Bir tür iyi hurma', 'Seferim var Gürcistan''a Benim ile göçen gelsin İnmesin namert meydana Candan, serden geçen gelsin İçtiğimiz aslan kanı Yediğimiz süleymani (...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seferim-var-gurcistan-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Kalan', 'senden-kalan-i-lyas-ozkan-q952s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '*Babama...

Mâtem kaldı senden geriye.

Esefli günlerden, hüzün kaldı.

Hazin akşamlar gitti; ardında dün kaldı.

Mâziye karıştı herşey; gözyaşı ve acılı gün kaldı.

Elimizden çekildi zaman, gece ve gündüzün kaldı.

Terkedip gittin; hatrımızda, tatlı sözün kaldı.

Özledi şimdiden, sesini-soluğunu, yetimlerin

Zahmetinden kurtulup şu fenâ âlemin; 

Koşar adımlarla, bırakıp bizi, Rabbine gittin.

Ah u efkân kaldı; acı ve ızdırabı, gönüllerin.

Ne yapalım, mukaddermiş.. görüşmeye gün, öbür gün kaldı…

(19.08.2003

Salı) 

*17.08.2003 Pazar,02:00 sularını az bir zaman geçe, bu fani dünyaya vedâ eden babama... Yerin Cennet ola, babam!', '*Babama... Mâtem kaldı senden geriye. Esefli günlerden, hüzün kaldı. Hazin akşamlar gitti; ardında dün kaldı. Mâziye karıştı herşey; gözyaşı...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/senden-kalan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kere...', 'bir-kere-i-lyas-ozkan-mutoz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kıvılcımda tutuştursam, karanlık dehlizi

Bir damlada boğuvereyim, şu engin denizi

Dursun içimdeki fırtına ve dinsin feryadım

Çilekeş dakikalardan özgürlüge gün  saydım

Bir âhımla yanıversin de karanlık geceler

Bir âhımla tutuşuversin hüzünlü heceler

Serpilsin gönlüme, huzur esintisi Rahman’ın

Duyuversem en yüceden ''Kabulümsün! '' sadâsın... 

(08.09.2003

Pazartesi)', 'Bir kıvılcımda tutuştursam, karanlık dehlizi Bir damlada boğuvereyim, şu engin denizi Dursun içimdeki fırtına ve dinsin feryadım Çilekeş dak...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-kere-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gele Zor Bezirgan Beri Gel Hele', 'gele-zor-bezirgan-beri-gel-hele-koroglu-ugnry', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gele ''Zor Bezirgan'' beri gel hele

Bir kule yaptırak baş-baş üstüne

Seçilsin yiğitler seninle bile

Dolmalı deryalar leş-leş üstüne

Gele ''Dağıstanlı Hasan''ım gele

İniver meydana, dev gibi mele

''Hoylu''nun dadını acep kim ala

Koymayın bu şehri taş-taş üstüne

Gele ''Deli Hasan'' in bu meydana

Ejderhalar gibi ateş saçsana

Bu Acem''i vurup öte geçsene

Doldur dereleri leş-leş üstüne

Gele ''Demirc''oğlu'' ne durdun orda

Tenbihe hacet mi sen gibi merde

''Hoylu Bey'' düşürdü beni bu derde

Birkaç kale yapın baş-baş üstüne

Gele ''Han Ayvaz''ım bade içelim

Koç yiğide kanlı gömlek biçelim

''Hoylu'' ölmüş, candan, serden geçelim

Keselim Acem''i baş-baş üstüne

Gele cümle leşker, beri gel beri

Koyalım bu yola can ile seri

Çamlıbel Dağı''na dönmezsem geri

Kalırsa bu iller taş-taş üstüne

Ben de Köroğlu''yum, böyledir emrim

Gün doğandan gün batana kararım

Bugün bu meydana ben de inerim

Şöyle bir cenk edek, yaz kış üstüne

* Tırnak içindeki isimler (Zor Bezirgan, Dağıstanlı Hasan, Demircioğlu, Deli Hasan vb... Köroğlu''nun savaşçılarıdır.

Köroğlu''nun en yakın dostları ve savaşçılarından ''Deli Hoylu'' öldürülmüştür. Köroğlu da intikam kumandasını  bu türküyle veriyor.', 'Gele ''Zor Bezirgan'' beri gel hele Bir kule yaptırak baş-baş üstüne Seçilsin yiğitler seninle bile Dolmalı deryalar leş-leş üstüne Gele ''Dağı...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gele-zor-bezirgan-beri-gel-hele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Koçak Bir Araya Gelince', 'i-ki-kocak-bir-araya-gelince-koroglu-cgbkc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İki koçak bir araya gelince

Yiğit derler arap atı koşana

Çarhacılar birbirini bulunca

Yeğin atlar yer bulamaz kaşana

Yeğin atlar dorusundan, kırından

Şahbazların yahşisinden yeğinden

Koçyiğitler izin ister beyinden

Düşmanına bozkurt gibi boşana

Koç yiğit cıdasın kendi götürür

Kimini vurur, kimisin yatırır

Kelle keser aktarmasın götürür

Hayın derler ol mahalde şaşana

Köroğlu der: ulu meydan kurulsun

Çekilsin sancaklar tuğlar yürünsün

Koç yiğidin bunda adı sorulsun

Buna döğüş derler Bey ne Paşa ne', 'İki koçak bir araya gelince Yiğit derler arap atı koşana Çarhacılar birbirini bulunca Yeğin atlar yer bulamaz kaşana Yeğin atlar dorusundan,...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iki-kocak-bir-araya-gelince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gelince', 'ben-gelince-koroglu-1jw9m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gider oldum beyler Haleb''e Hoy''a

Mevlam yetiştirsin düğüne toya

Bozdurun altını beyaz akçaya

Sarfedin beylere ha ben gelince

Çağırın gelsin Tekeli''nin Beyi''ni

İçinizde yoktur ondan yeğini

Ayırın sürüden bin erkeğini

Kırdırın kasaba ha ben gelince

Kıratım yok, binem gidem sazana

Yiğit odur öz malını kazana

Yüz batman pirinci küçük kazana

Yedirin beylere ha ben gelince

Köroğlum der, devran döndü ahire

Altın madenleri döndü bakıra

Satın Çamlıbel''i verin çakıra

İçirin beylere ha ben gelince', 'Gider oldum beyler Haleb''e Hoy''a Mevlam yetiştirsin düğüne toya Bozdurun altını beyaz akçaya Sarfedin beylere ha ben gelince Çağırın gelsin ...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-gelince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz bir sabah daha', 'sensiz-bir-sabah-daha-mustafa-tekin-pax43', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şehrin limanı bir karartı şeklinde uzanıyor.

safağın kızıl oklarıgecenin kalbine coktan dalmış.

gecenin yerini almış sabah.

doğmak üzere sarı sıcak bir güneş.

şehrin ışıkları bir bir sönüyor

karşımda bir baykuş ufalan gözleriyle bakıyor.

yeniden doğmuş gibi masmavi deniz

doğan güneşin ışıkları dans ediyor maviliğin üstünde

ve sensiz bir sabah daha oldu boş şişelerin üstünde.... 

yine sensiz...

yine sensiz....', 'şehrin limanı bir karartı şeklinde uzanıyor. safağın kızıl oklarıgecenin kalbine coktan dalmış. gecenin yerini almış sabah. doğmak üzere sar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tekin']::text[], 8.5, '{"poet":"Mustafa Tekin","poet_slug":"mustafa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensiz-bir-sabah-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin Hey Ağalar Çekin Kılıncı', 'gelin-hey-agalar-cekin-kilinci-koroglu-ykoun', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelin hey ağalar, çekin kılıncı

Arap atla, koç yiğidin günüdür

Göğüs verip, arka verip, nal atan

Sırma çullu küheylanlar günüdür

Cenk kurulup cıda, oklar atanda

İki leşker birbirine katanda

Kötülerin yakasından tutanda

Yılan dilli dal hançerin günüdür

Gelin hey ağalar vurup geçelim

Koç yiğide kanlı gömlek biçelim

İki saat al kızıl kan içelim

Bunda koç yiğidin şanı günüdür

Hay n''olanda Koç Köroğlu n''olanda

Ara yerde kurt koyuna dalanda

At vurulup yiğit yaya kalanda

Teke şekli Şam kılıcın günüdür', 'Gelin hey ağalar, çekin kılıncı Arap atla, koç yiğidin günüdür Göğüs verip, arka verip, nal atan Sırma çullu küheylanlar günüdür Cenk kurulu...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelin-hey-agalar-cekin-kilinci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meydan İçinde', 'meydan-i-cinde-koroglu-1iiec', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki koçak bir araya gelende

Görelim ne işler meydan içinde

Kesilir kelleler boşanır kanlar

Yeğin olur leşker, meydan içinde

Oklar uçup gider şahanlar gibi

Mert de aşıp gider aslanlar gibi

Kılıçlar oynaşır ceylanlar gibi

Kesilir ne başlar meydan içinde

Yiğitler çağrışır yaman gün olur

Allah allah derler yüksek ün olur

Cerha cerha döğüşecek hun olur

Hasmın arar koçlar meydan içinde

Köroğlu''yum methim merde, yiğide

Koç yiğit değişmez cengi düğüne

Sere serpe gider düşman önüne

Ölümü karşılar meydan içinde', 'İki koçak bir araya gelende Görelim ne işler meydan içinde Kesilir kelleler boşanır kanlar Yeğin olur leşker, meydan içinde Oklar uçup gider...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/meydan-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce Dağların Başında', 'yuce-daglarin-basinda-koroglu-u7olj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüce dağların başında

Kar bir yana kış bir yana

Depreşir ağzım içinde

Dil bir yana diş bir yana

Bahar olur sular coşar

Yüce dağlardan yol aşar

Bir gün olur ayrı düşer

Leş bir yana baş bir yana

Nidelim beyler nidelim

Baş kesip kanlar dökelim

Ayvaz''a imdat gidelim

Üç bir yana beş bir yana

Bire beyler bire paşa

Karlı karlı dağlar aşa

Bir gün ola ayrı düşe

Kol bir yana baş bir yana

Kocadım belim büküldü

Tütünüm arşa dikildi

Gözümden dolu döküldü

Kan bir yana yaş bir yana

N''oldu koç Köroğlu n''oldu

Dereler kan ile doldu

Gördün düşman yeğin geldi

Vur bir yana düş bir yana', 'Yüce dağların başında Kar bir yana kış bir yana Depreşir ağzım içinde Dil bir yana diş bir yana Bahar olur sular coşar Yüce dağlardan yol aş...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yuce-daglarin-basinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine mi?', 'yine-mi-seyda-sarica-u03u8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir daha mı yakacaksın bu ateşi sen? 

Bir daha mı tutuşturacaksın bedenini...

Islak saçlarından dökülen damlaları 

Bir daha mı onun dudaklarında tadacaksın....

Usulca yaklaşıp, seni bekleyen acı çığlıklara, 

Hiç düşünmeden yine mi atacaksın kendini! ...

Hep istediğin, aradığın, hep beklediğin o sevdaya

Yine mi yanılarak koşup yanlışlara varacaksın! ..

Nefes aldığın zamanı yürek burkulmalarına mı

Harcayacaksın........', 'Bir daha mı yakacaksın bu ateşi sen?  Bir daha mı tutuşturacaksın bedenini... Islak saçlarından dökülen damlaları  Bir daha mı onun dudaklar...', ARRAY['Türk Edebiyatı','Şiir','Şeyda Sarıca']::text[], 8.5, '{"poet":"Şeyda Sarıca","poet_slug":"seyda-sarica","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yine-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Ayna', 'kirik-ayna-seyda-sarica-cwwg8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırık bir aynanın ucunda duruyorsun, 

Asılı kalmış gözlerin yıldızlara, nehire..

Bir parça akıp gitsem diyorsun şurdan..

Aksam da kanasam...

Susup kalmasam düşerken...

Dudaklarım seni tanımasa

Ürpertmese anımsadığım nefesin..

Dokunmasa tenime rüzgar, 

Silip gitmese gözyaşımı ellerin

Gözlerin bakmasa bir daha 

Acımasa yüreğim, ağlamasa daha...

Gülmese...

Ya da bazen delice düşünmese yitilecek anları şimdiden...

Tıpkı yitirilenleri düşünmediği gibi....diyorsun...', 'Kırık bir aynanın ucunda duruyorsun,  Asılı kalmış gözlerin yıldızlara, nehire.. Bir parça akıp gitsem diyorsun şurdan.. Aksam da kanasam......', ARRAY['Türk Edebiyatı','Şiir','Şeyda Sarıca']::text[], 8.5, '{"poet":"Şeyda Sarıca","poet_slug":"seyda-sarica","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirik-ayna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Sanmışım', 'i-nsan-sanmisim-mehmet-yucel-jkt0f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yılan''''a Akrep''e dost dediysem

olacağından değil ya! 

yüreksizlerle yola çıktıysam, 

varacağımdan değil ya! 

Koskocaman şehirde yapayalnızsam çoğu zaman

çekilmezliğimdendir herhalde...

kimblir yine hangi menfatçinin menfaatine takoz koymuşumdur

kimbilir hangi sevgi sahtekarını suç üstü yakalamışımdır.

Yada yalan söylemeyi bile becermeyen

beceriksizin tekiyimdir.

Ulan! nerde acayip olay varsa gelir beni bulur

İnsanlığı anlatırken duygulanıp gözlerimi kapamışım

bir açtım ki çevremde bir kişi bile yok

ben meğer dakikalarca boşluğa anlatıyormuşum insanlığı

o kadar insan neden gittiler? 

niye dinlemediler? 

bir türlü anlam veremedim! ! 

ben de güya insanlara insanlık anlatıyorum diye duygulanmıştım

çevremdeki canlı gurubunu insan sanmıştım.

İşte böyle arkadaş 

halimiz ahvalimiz yirmibirinci yüzyılın başlarında

kulaklar sağır

gözler kör

yüreklerde yürek denecek özellik kalmamış

o yürekler ki insanlıktan nasibini almamış.

Günlerce aç susuz yaşayarak büyüdüğüm

acısını, ayrılığını, zulmünü gördüğüm bu topraklarda şair olmak! ! 

duyarlı olmak, birşeyleri görme telaşına düşmek

öyle ağır öyle çileli ki

onu ancak yaşayan bilir.

Dilenci kılığına girip, 

insanları tanımaya çalışan yürek benim

sosyete kılığına girip diğer insanları tanıyan yürekte benim

yani kılıktan kılığa bürünüp, 

kendi dünyasından çıkan

hayata birçok yönden bakan

kendi dünyası dışına sel olup taşan

o deli şair benim arkadaş, 

Her şiirimde binlerce kez yanmışım

insan kılığındakileri yanlışlıkla insan sanmışım.', 'Yılan''''a Akrep''e dost dediysem olacağından değil ya!  yüreksizlerle yola çıktıysam,  varacağımdan değil ya!  Koskocaman şehirde yapayalnızsa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel']::text[], 8.5, '{"poet":"Mehmet Yücel","poet_slug":"mehmet-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/insan-sanmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün Bu Gündür Asılıdır Yüreğim', 'o-gun-bu-gundur-asilidir-yuregim-ahmet-aksoy-s2tpd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce gözünden düştüm 

Sonrada aklından

Ne yavaş ne de hızlı

Zamansız... 

Zaman birimini yitirmiş

Bir yolculuktur aşk, 

İki tarafı da keskin değildir

Yani kılıç gibidir.

Ucu bucağı yok sanır

İnsan başında, 

Oysa bir yol gibi başlayan

Keskin bir sonda sonlanır.

Bir kılıç gibidir aşk

Başında birlikte başlayan

Sonunda daralan yolda

Düşmemeye dayanır durmadan....

Önce gözünden düştüm

Sonra da aklından

Ne yavaş ne de hızlı

Zamansız....

Kılıç gibiydi aşkımız

Ve dar geldi bize de sonunda

Ya sen düşecektin

Ya da ben.

Ama ben düştüm

İstemeden.

Sırf sen; yolunda

Yalnız olmayı seçtiğinden.

Ve bilirsin, burukta olsa

İhmalsizdir sana karşı yüreğim

Sana kıyamam.

Yıkılmışlığı, acıyı ve elemi ben aldım

Düşüşünü düşünerek

Ben kılıcın ucuna

“Düşerken” yüreğimi taktım

Sırf sen yaralanma diye...

O gün bu gündür 

Asılıdır yüreğim 

Sahibinin acılarına simge

Bir madalya gibi kılıcın üzerinde...', 'Önce gözünden düştüm  Sonrada aklından Ne yavaş ne de hızlı Zamansız...  Zaman birimini yitirmiş Bir yolculuktur aşk,  İki tarafı da keskin ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/o-gun-bu-gundur-asilidir-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Büyük Sır Söyleyeceğim Sana', 'bir-buyuk-sir-soyleyecegim-sana-louis-aragon-myv9u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir büyük sır söyleyeceğim sana Zaman sensin

Kadındır zaman sevilmek özlemi duyar

Aşıklar eteğinde otursun ister

Bozulacak bir entaridir zaman

Perçemdir sonsuz

Taranmış

Bir aynadır buğulanan buğuları dağılan

soluklarla

Zaman sensin uyuyan uyandığım şafakta

Sensin bıçak gibi geçen boynumu

Geçmek bilmeyen zamanın işkencesi oy

Mavi damarlardaki kan gibi durmuş zamanın

işkencesi oy

Hep doyumsuz arzudan daha da beterdir bu

Daha da beterdir bu

Sen odada yürürken gözlerin susuzluğundan

Korkarım hep bozulur diye büyü

Daha da beterdir bu senle yabancılaşmaktan

Başın

Kaçak dışarda ve yüreğin başka bir çağda oluşu

Sözcükler ne ağır Tanrım anlatırken bunları

Arzunun ötesinde erişilmez yerlerde bugün aşkım

Sen şakağımda vuran duvar saatisin

Sen solumazsan eğer ben boğulurum

Duraksar ve tenime konar adımın

Bir büyük sır söyleyeceğim sana Dudağımdaki

Her söz dilenen bir yoksulluktur

Bir yoksulluktur ellerin için bakışında kararan

bir şeydir

Bundandır sana sık sık seni seviyorum demem

Boynuna takacağın bir tümcenin saydam

kristalinden yoksunum

Şu sıradan sözlerimi hor görme Onlar

sade bir sudur ateşte o sevimsiz gürültüleri

yapan

Bir büyük sır söyleceğim sana Beceremem ben

Sana benzer zamandan sözetmeyi

Senden sözetmeyi beceremem ben

İnsanlar vardır hani istasyonlarda

El sallayan tren kalktıktan sonra

Yani ağırlığıyla göz yaşlarının

Kolları yana düşer onlara benzerim ben.

Bir büyük sır söyleyeceğim sana Korkuyorum

senden

Korkuyorum ikindilerde seni pencerelere götüren

şeyden

Korkuyorum davranışlarından söylenmedik

sözcüklerden

Hızlı ve usul geçen zamandan korkuyorum

senden

Bir büyük sır söyleyeceğim sana kapıları ört

Ölmek sevmekten daha kolaydır

Bundandır yaşamanın sancılarına yönelmem

Sevgilim.', 'Bir büyük sır söyleyeceğim sana Zaman sensin Kadındır zaman sevilmek özlemi duyar Aşıklar eteğinde otursun ister Bozulacak bir entaridir zam...', ARRAY['Türk Edebiyatı','Şiir','Louis Aragon']::text[], 8.5, '{"poet":"Louis Aragon","poet_slug":"louis-aragon","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/bir-buyuk-sir-soyleyecegim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmıyorlar Bana', 'i-nanmiyorlar-bana-louis-aragon-yov3m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnanmıyorlar bana inanmak istemiyorlar

Boşuna yazıyorum dilim dişim tırnağımla kanımla kemanlarımla

Boşuna yazıyorum uyaklarımla

Gecede dalların eski dilini bilmeyen biri gibiyim

Asılmış suların üstünde

Konuşmak kara dilin erkeğin ve kadının

Birbirine tutuşmuş iki ele yabancı biri gibi konuşmak

Konuşmak mutluluğun çılgını gibi

Öpücüklere benzemeyen sözcükler var ya

İşte o sözcükleri yitirmiş bir ağzın dili ile konuşmak

Tüm bunlardan yakınan bir edayla konuşmak

Dolup taşıp ta sanki susmak istiyor gibi

Ey sözlerin ötesinde yetkin ses

Şarkının yüceliği çığlığın çığlığı

Bir an geliyor nota ulaşılmaz seslerin şarkısını söylüyor

Kulak duymuyor artık yükseklerdeki müziği

İnanmıyorlar bana inanmak istemiyorlar

Boşuna konuşuyorum ilkyaz''la ve orglarla

Boşuna konuşuyorum gökyüzünün tüm heceleriyle

Bilinen şeylerin özel orkestrasıyla

Ve sağır onikiliklerin bayağılığıyla

Boşuna konuşuyorum barbar çalgılarla

Boşuna söylüyorum onu duvarlara vuran yumruğumla

Boşuna söylüyorum derebeyinin ormanlarını ateşe verir gibi

boşuna söylüyorum onu savaş ilan eder gibi

Alev yutan cambazın ağzındaki alev gibi

İnanmak istemiyorlar bana Kendilerine benzer birini

yaratmışlar benden belki de

Belki döküntülerini giydiriyorlar bana

Alıp gezdiriyorlar beni kendileriyle

Dizelerimi söylüyorlar benzetip kendilerine

Dizelerim onlara tatlı şarkılar oluyor

Biraz da onların satlık malıyım ben

Beklerken bir yol olmayı

Sözcüklerindeyim ben

Okul kitaplarındayım

Rezillik yapamam bu bana yasak

Boşuna haykırıyorum ben

Sana aşık birinden başkası değilim diye', 'İnanmıyorlar bana inanmak istemiyorlar Boşuna yazıyorum dilim dişim tırnağımla kanımla kemanlarımla Boşuna yazıyorum uyaklarımla Gecede dall...', ARRAY['Türk Edebiyatı','Şiir','Louis Aragon']::text[], 8.5, '{"poet":"Louis Aragon","poet_slug":"louis-aragon","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/inanmiyorlar-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iraktan Özendim Geldim', 'iraktan-ozendim-geldim-koroglu-m9qqo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Iraktan özendim geldim

Çevre yanın meşe dağlar

Ayvaz''ım almaya geldim

Laleli, sünbüllü dağlar

Gitmez karşımda durursun

Elimde külli varımsın

Ensemde kafadarımsın

İş düşücek başa dağlar

Özengimi gerdim durdum

Beyleri mürvetsiz buldum

Ben sana arkamı verdim

Neyler bana paşa, dağlar

İli başlamış göçmeye

Ter mahbupların koçmaya

Badeler koyup içmeye

Vardır sende köşe dağlar

Köroğlu, Ayvaz''ı sever

Tütünü göklere ağar

Yazın yeşil kemha geyer

Kışın ak-sadeli dağlar', 'Iraktan özendim geldim Çevre yanın meşe dağlar Ayvaz''ım almaya geldim Laleli, sünbüllü dağlar Gitmez karşımda durursun Elimde külli varımsın...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iraktan-ozendim-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Tutsak Anlara Esir', 'tutsak-anlara-esir-cemal-karsavran-v6ez7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'nadide atlas halıydı yürek 

dalga dalga yelkenlilerle 

koylarında gel gitler 

bir ayağı boşluğu kucaklarken 

düşen hatıralarda 

esmelimiydi rüzgarlar 

devrik cümlelerden vurgun yemiş 

yüksek uçurumların kıyısında 

faylar yarılmış engebesiz 

gül açan dikenlerin gölgesinde 

zil takmış baharlar yaşar 

asma çardaklı düşler 

desen desen gökkuşağı 

gözleri çukur ayna yıllarda 

çatısız mekanlara açılan 

avuçlarında bahar yeşerir 

yaşar kelebeğin kanatlarında 

düzlemleri mavi çizgiler 

ezgiler salınır kulaklarında 

ritm tutar kavak yellleri 

kuzeylerin gündönümü 

şafağa düşen sabahlar 

öper yanağını lodos 

aynalara gülen gözler 

düşleri serer güneşe 

eksilen hücreler yenilenir 

gamzelerinde çiçek açan 

sözcükler dolanır mercan kıyılarında 

orkide takılmış saçlar 

rüzgara kanat açardı 

toprağa düşen verimdi 

beyaz sarı mavi yeşil 

nefesleri yağmur damlası 

uzun bir öykünün ilk sayfası 

tutsak anlara esir', 'nadide atlas halıydı yürek  dalga dalga yelkenlilerle  koylarında gel gitler  bir ayağı boşluğu kucaklarken  düşen hatıralarda  esmelimiydi ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/tutsak-anlara-esir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar Duman Oldu', 'daglar-duman-oldu-koroglu-jrwqz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pınar başında bulanır

Sende çok mallar talanır

İner ovayı dolanır

Dağlar duman oldu

Çayır çimen oldu

Ben yari görmedim

Halim yaman oldu

Hiç ovaya inmedin mi

Gam, gussadan doymadın mı

Aşk oduna yanmadın mı

Dağlar duman oldu

Çayır çimen oldu

Ben yari görmedim

Halim yaman oldu

Yaz görmemiş kışa benzer

İçmiş de sarhoşa benzer

Dert görmemiş başa benzer

Dağlar duman oldu

Çayır çimen oldu

Ben yari görmedim

Halim yaman oldu

Köroğlu serinden geçti

Ayvaz gelip bundan göçtü

Aşkın dolusundan içti

Dağlar duman oldu

Çayır çimen oldu

Ben yari görmedim

Halim yaman oldu', 'Pınar başında bulanır Sende çok mallar talanır İner ovayı dolanır Dağlar duman oldu Çayır çimen oldu Ben yari görmedim Halim yaman oldu Hiç ...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/daglar-duman-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göğsün Düğmele Düğmele', 'gogsun-dugmele-dugmele-koroglu-1tlsg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üç güzeller indi çaya

Cemalin benzettim aya

Keten gömlek memen soya

Göğsün düğmele düğmele

Çaya indi allı gelin

Al dudağı ballı gelin

Keten gömlek dallı gelin

Göğsün düğmele düğmele

Saçları kat kat örülür

Al dudağa bal sürülür

Yel vurur memen görünür

Göğsün düğmele düğmele

Köroğlu neden titrersin

Akıl baştan al gidersin

Çamlıbel''de seyredersin

Göğsün düğmele düğmele', 'Üç güzeller indi çaya Cemalin benzettim aya Keten gömlek memen soya Göğsün düğmele düğmele Çaya indi allı gelin Al dudağı ballı gelin Keten ...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gogsun-dugmele-dugmele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-turgay-kadiroglu-i1r3a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kardelen kanadına bir buse iliştirsem, 

Dört bir yanı buz keserken

Beyazlar içinde gelinciklere benzediğinden söz etsem

Toprak bağımlısı kardelen! 

Baksana, 

Benim de hamurum topraktan desem, 

Narin yapraklarıyla dokunur mu içimdeki duvar yazılarına

İçimin ve duvarların destek bildiği satırlara...', 'Kardelen kanadına bir buse iliştirsem,  Dört bir yanı buz keserken Beyazlar içinde gelinciklere benzediğinden söz etsem Toprak bağımlısı kar...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kardelen-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-turgay-kadiroglu-gfn47', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kalemin dili sivridir, 

çizdiği nokta bir hiçtir

ve evren bu noktalardan müteşekkildir.

yaşam anılardır, 

anı anda saklıdır, 

an hiç kadardır

ve zaman anların aktığıdır.

aşk kalptedir, 

kalp ruhun maddeye açılan penceresidir, 

yar pencere önü menekşesidir.

gün olur yar solar

topraksız kalır, 

pencereler kapanır, körfez kana boyanır

ve kalp bir avuç toprağa sarılır.', 'kalemin dili sivridir,  çizdiği nokta bir hiçtir ve evren bu noktalardan müteşekkildir. yaşam anılardır,  anı anda saklıdır,  an hiç kadardı...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hic-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpül Koçul Huzur İle', 'opul-kocul-huzur-i-le-koroglu-04iy0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel ey nazik beden dilber

Öpül koçul huzur ile

Ömrümün hasılı dilber

Öpül koçul huzur ile

Öpülmekten zarar gelmez

Koçulmaktan adam ölmez

Bu güzellik sana kalmaz

Öpül koçul huzur ile

Öpülmek eski adettir

Koçulmak hub saadettir

Hatır yapmak ibadettir

Öpül koçul huzur ile

Karana yağmadan ağın

Menevşem solmadan bağın

Güzelsin geçmeden çağın

Öpül koçul huzur ile

Köroğlu der gamzen oktur

Derdim hiç kimsede yoktur

Koçulmamış dilber yoktur

Öpül koçul huzur ile', 'Gel ey nazik beden dilber Öpül koçul huzur ile Ömrümün hasılı dilber Öpül koçul huzur ile Öpülmekten zarar gelmez Koçulmaktan adam ölmez Bu ...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/opul-kocul-huzur-ile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayvaz Ağlama', 'ayvaz-aglama-koroglu-wocl0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bir Türkmen idim geldim yabandan

Haberini aldım ben bir çobandan

Beşyüz koyun verdim, aldım babandan

Alnı top, başı tel yeşil ağlama

Vardım gördüm, kumru gibi oturur

Ak eli al kınalara batırır

Kırat bizim ikimizi götürür

Başı turna telli Ayvaz ağlama

Geç de gidelim harmana yukarı

Akar leblerinin balı şekeri

Çökerse Ayvazın kahrı çökeri

Alnı top kahküllü yeşil ağlama

Gel Ayvaz''ım bu dağlara gidelim

Bile ağlayalım, bile gülelim

Fırat nehirinden murat alalım

Başı telli turnam Ayvaz ağlama

Geç gidelim biz harmandan beriye

Yüreğimde yağ koymayıp eriye

Şimdi anan baban gelir geriye

Başı telli turnam Ayvaz ağlama

*Köroğlu Ayvaz''ı kaçırmıştır ve Ayvaz ağlamaktadır.', 'Ben bir Türkmen idim geldim yabandan Haberini aldım ben bir çobandan Beşyüz koyun verdim, aldım babandan Alnı top, başı tel yeşil ağlama Var...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ayvaz-aglama-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayvaz Mey Doldur', 'ayvaz-mey-doldur-koroglu-7w6g5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üsküdar''dan seni aldım

Serimi kavgaya saldım

Çamlıbel''e yakın geldim

Ayvaz mey doldur, mey doldur

Arap at gider eşkine

Eyle merhamet düşküne

Çamlıbellerin köşküne

Ayvaz mey doldur, mey doldur

Gideyim bundan yoluma

Sen aldın beni zuluma

Rahmeyle öksüz kuluna

Ayvaz mey doldur, mey doldur

Giderim, benim yolumdur

Zahmanım benim ilimdir

Köroğlu senin kulundur

Ayvaz mey doldur, mey doldur', 'Üsküdar''dan seni aldım Serimi kavgaya saldım Çamlıbel''e yakın geldim Ayvaz mey doldur, mey doldur Arap at gider eşkine Eyle merhamet düşküne...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayvaz-mey-doldur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayvaz''ı Göresim Geldi', 'ayvaz-i-goresim-geldi-koroglu-xlhss', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benden selam eylen Bolu Beyi''ne

Göndersin Ayvaz''ı göresim geldi

Muhabbeti düştü gönlüm evine

Göndersin Ayvaz''ı göresim geldi

Eyerleyip Kıratıma binmeden

Alayları bölük bölük bölmeden

Bolu şehri ateşlere yanmadan

Göndersin Ayvaz''ı göresim geldi

Şimdi Kıratıma biner aşarım

Karadeniz gibi kaynar coşarım

Sinesine eğri kılıç döşerim

Göndersin Ayvaz''ı göresim geldi

Gürzün kösteğini kola takmadan

Koç Kıratı sağa sola yıkmadan

Bolu şehrin ateşlere yakmadan

Göndersin Ayvaz''ı göresim geldi

Ben de Köroğlu''yum yolum salasın

Koç yiğide arz ettirem sılasın

Depretmeden demir yayın, cıdasın

Oğlum Ayvaz, seni göresim geldi', 'Benden selam eylen Bolu Beyi''ne Göndersin Ayvaz''ı göresim geldi Muhabbeti düştü gönlüm evine Göndersin Ayvaz''ı göresim geldi Eyerleyip Kırat...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayvaz-i-goresim-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayvaz''a Övgü', 'ayvaz-a-ovgu-koroglu-qvtns', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yataktan kalkmış bir aslan

Gelir horlayı horlayı

Buluttan çıkmış ay gibi

Gelir parlayı parlayı

Döne, seyreyle Ayvaz''ı(1)

Sim bilekli o zorbazı

Cılbatmış Kara Kabtaz''ı(2)

Gelir gürleyi gürleyi

Şimdi görürsün kendini

Gülden kırmızı rengini

Görmedim bunun dengini

Gelir gürleyi gürleyi

Döne, Ayvaz bunun adı

Geldi bu meydanın tadı

Köroğlu''nun bir evladı

Gelir zorlayı zorlayı

(1)   Döne: Köroğlu''nun karısı Döne Hanım

(2)   Kara Kabtaz: Ayvaz''ın atının adı', 'Yataktan kalkmış bir aslan Gelir horlayı horlayı Buluttan çıkmış ay gibi Gelir parlayı parlayı Döne, seyreyle Ayvaz''ı(1) Sim bilekli o zorba...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayvaz-a-ovgu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Gidinin Oğlu', 'hey-gidinin-oglu-koroglu-hi97h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mevla''m seni bana verse,

Derim hey gidinin oğlu.

Arşa direk direk oldu,

Zarım hey gidinin oğlu.

Beni önünde assınlar,

Emret kellemi kessinler,

Derim aşkına yüzsünler,

Verem, hey gidinin oğlu.

Canım, sen bir adil hansın.

Han oğlusun hem hansın.

Yalancı dünyada sensin,

Varım, hey gidinin oğlu

Köroğlu, gidişin Acem.

Ne günüm belli, ne gecem.

Hem halifemsin, hem hocam.

Pirimsin hey gidinin oğlu.', 'Mevla''m seni bana verse, Derim hey gidinin oğlu. Arşa direk direk oldu, Zarım hey gidinin oğlu. Beni önünde assınlar, Emret kellemi kessinle...', ARRAY['Türk Edebiyatı','Şiir','Köroğlu']::text[], 8.5, '{"poet":"Köroğlu","poet_slug":"koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hey-gidinin-oglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana', 'ana-hebil-akan-ulexs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir mektup gönder bana... 

satırlarında buram buram 

özlem koksun....hasret koksun... 

çocukluğumda oynadığım çam ağaçlarının, 

kokusu sinsin satırlarına... 

ellerinin kokusu sinsin... 

ne olursun ana 

bir mektup gönder bana 

içimdeki hasretin dinsin... 

bir mektup yaz... 

otlayan sürülerden anlat 

oğlakları ayırdınız mı anasından 

kuzular meleşirmi? yamaçtan yamaca

kırlangıçlar tünüyor mu 

inin önündeki ardıca? 

ana bir mektup yaz bana 

sensiz karanlık geceler 

sensizlik ayaz bana... 

ana bir mektup gönder bana 

kışın yağmurun ardından toprak 

baharda badem çiçekleri koksun 

ısdarda kilimlerimizin nakış’ı 

vadilerde ırmaklarımızın akışı koksun... 

hani doğduğum dağda..morkoyak da 

esen poyrazlar sinsin satırlarına.... 

çalkamaya doğradığımız gevreklerin kokusu 

davar güden Yörük kızlarının 

kır çiçeklerinden takısı koksun..satırlarında... 

sen burada adı yıldız olanlara bakma 

kıl çadırlardan gördüğün yıldızlardan yaz... 

kır yaylalardaki kekik kokusunu 

çiğdem kazan kınalı elleri yaz.. 

deme oğlum duyguludur.. deme mektubum ağlatır.. 

ağlamaya razıyım ben 

yeter ki bir mektup gönder 

özlem dolu, hasret dolu satır satır.. 

okumam yok ki oğul deme bana 

paşanın okuma yazma 

seferberliğine gitmiştin ya üç ay 

hani şükran duygun için hoca hanıma 

sen de anandan kalma 

ipi çiğitle boyanmış 

obamızın nakış’ıyla işlenik 

terk heybeyi vermiştin ya... 

işte.. o bilgilerin yeter be ana 

iki cızıktırmaya 

kokunu alayım yeter 

kokun burnumda tüter 

tüter be ana. 

...anacığım.... 

ne olur..ne olur 

unutma bu ciğerpareni 

öyle derdin ya beni severken 

yaramazlık yapınca nasıl çatılırdı kaşların 

nasıl titrerdi yüreğin.. 

şefkatli ellerinle beni döverken.. 

gönlünü ferah tut anacığım 

haram lokma yemedim 

harama el sürmedim 

boşa gitmedi anlayacağın emeklerin 

mektubuyun sonunda her zaman ki gibi 

hayırdualarını beklerim 

canım anacığım 

benim anacığım.... 

Allah’a emanet olasın..



Trafik hastanesi/1993', 'bir mektup gönder bana...  satırlarında buram buram  özlem koksun....hasret koksun...  çocukluğumda oynadığım çam ağaçlarının,  kokusu sinsi...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/ana-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç', 'goc-bulent-gonul-gvfkv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elbet göçüp gideceğim 

Bende bu diyarlardan, 

Sensizlik kadar koyarmı 

Bu gidişler bana, 

Bilirsinki her sabah 

Sana selam yollarım oralardan, 

Ama bana ne fayda sabahlar

Yanımda sen olmadan', 'Elbet göçüp gideceğim  Bende bu diyarlardan,  Sensizlik kadar koyarmı  Bu gidişler bana,  Bilirsinki her sabah  Sana selam yollarım oralarda...', ARRAY['Türk Edebiyatı','Şiir','Bülent Gönül']::text[], 8.5, '{"poet":"Bülent Gönül","poet_slug":"bulent-gonul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/goc-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otobüs', 'otobus-devrim-dinc-6fctv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimsenin bilmediği bir köyde yaşıyorum; 

Nüfus: 1 Rakım: Belirsiz

Hayatın hergün son bulup yeniden başladığı, 

Resminin devamlı kaybolup tekrar bulunduğu, 

Ben, ve hayallerimden başka kimsenin

Uğramayacağı, kimsesiz, ağaçsız bir köy

Bazen bir otobüs bekliyorum yolda, 

Hani her saat başı geçen

Ve sana açılan kapının kolu sandığım, küflü, 

Aynı zamanda emektar, sahipsiz...

Artık bu köyden otobüste geçmiyor sen de, 

Biliyorum hangi köyden, hangi otobüsün geçtiğini, 

Ve ona kimin binip nereye gittiğini...

Haykırmak geliyor içimden bazen, otobüse ve sana:

Beni, bana bırakında nereye olursa defolun gidin! 

Umrumda değil! ! !', 'Kimsenin bilmediği bir köyde yaşıyorum;  Nüfus: 1 Rakım: Belirsiz Hayatın hergün son bulup yeniden başladığı,  Resminin devamlı kaybolup tek...', ARRAY['Türk Edebiyatı','Şiir','Devrim Dinç']::text[], 8.5, '{"poet":"Devrim Dinç","poet_slug":"devrim-dinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/otobus-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalanlar...', 'kalanlar-devrim-dinc-ft4w5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senden geriye kalan şeyler; 

Bir çanta dolusu resim, kaşık, günlük, saç, mektup, kibrit çöpü 

Ve göğsünde kırılmış sigaralar

Farkında olarak, bilerek...

Bir yap-boz gibi birleştirsek hepsini

Sen oluyorsun.

Hepsini ıslatıp, karıştırıp bir kenara atsak 

Ben oluyorum resimdeki, 

Gözleri kanlı, zayıf, üşümüş adam.', 'Senden geriye kalan şeyler;  Bir çanta dolusu resim, kaşık, günlük, saç, mektup, kibrit çöpü  Ve göğsünde kırılmış sigaralar Farkında olarak...', ARRAY['Türk Edebiyatı','Şiir','Devrim Dinç']::text[], 8.5, '{"poet":"Devrim Dinç","poet_slug":"devrim-dinc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kalanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandi Kendine Yetebilme Sanatı', 'kandi-kendine-yetebilme-sanati-devrim-dinc-l4e51', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatının sorumlusu kim şu sıralarda? 

Yani seni sen yapan, hayatına yön veren...

Biliyorum ben değilim aklındaki.

Senin aklında yedi cehennemin yedi zebanisi, 

Senin aklında arkadaşların, 

Senin aklında annen, baban, amcan, üvey kardeşin...

Kesik parmağından bile başkaları fışkırıyor, 

Artık aklındakilerin yani herşeyin esirisin.

Benim değil! ! ! 

Kimseyi esir alamadım, esir de olamadım kimseye, 

Tıka, basa dolu bir caddede yürürken bile yalnızdım, 

Düşlerimle, masallarımla...

Şimdi kafi geliyoruz birbirimize; 

Elim, şişem ve sigaram...', 'Hayatının sorumlusu kim şu sıralarda?  Yani seni sen yapan, hayatına yön veren... Biliyorum ben değilim aklındaki. Senin aklında yedi cehenn...', ARRAY['Türk Edebiyatı','Şiir','Devrim Dinç']::text[], 8.5, '{"poet":"Devrim Dinç","poet_slug":"devrim-dinc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kandi-kendine-yetebilme-sanati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hediye', 'hediye-devrim-dinc-8xkl7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saçlarından yaptığım hasırın üstünde, 

Göğsünü yastık yapmak ümidiyle uyanırdım her sabah.

Ne gelir, ne gider bilinmiyor işte...

Sende, o düşman, o saçma, 

O kendini beğenmiş, sen üzgün olduğun zaman bile 

Nispet yaparcasına parlayan, 

Sabahların birinde gittin.

Artık eski sabahlar değildi onlar, 

Bende eski ben değildim.

Güneşi balçıkla sıvama fikrinin saçmalığına inanmadan

Seni ve senin yanında saf tutan o sarı benizli, 

Herkese yukarıdan bakan yaratığıda sıvıyorum, 

Beynimdeki balçıkla.

Ve zülfikar benzeri bir kılıçla, 

Bölüyorum gövdemi, umutlarımı, düşlerimi iki parçaya, 

Al hadi! Çekinme, 

Yarısı sana, yarısı yoldaşına...', 'Saçlarından yaptığım hasırın üstünde,  Göğsünü yastık yapmak ümidiyle uyanırdım her sabah. Ne gelir, ne gider bilinmiyor işte... Sende, o dü...', ARRAY['Türk Edebiyatı','Şiir','Devrim Dinç']::text[], 8.5, '{"poet":"Devrim Dinç","poet_slug":"devrim-dinc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hediye-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazanan Oldu Mu?', 'kazanan-oldu-mu-devrim-dinc-42m6g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mutsuz günlerimde öğrendim, 

Yelkovanla akrebin, dakikayla saatin kavgasını

Ve bir hakem edasıyla yönettim, 

Hiç karışmadan, birbirlerini öldürsünlerde, 

Zaman hiç geçmesin diye.

Kimseye sormadım adını, adımı

Ki herşeyin farkında olmakta kötüydü, 

Hiçbir şey bilmemekte.

İlkçağ filozoflarından öğrendim gözünden adam tanımayı, 

Meşe fıçılardaki şarapta yüzmeyi

Bir tek seni tanımıştım ilk bakışta, 

Hayata dair fikirlerin varmış gibi bakıyordun.

Fikirlerin can yakan kelimelerde 

Uzak yol kaptanları gibi seyir defterime kazıyordum, 

Noktası virgülüne varana dek hepsini

Zafer çığlıklarıyla sarhoş olacağımız günü bekliyordum, 

Sakin, aklı başında, mağrur.

Tanımadım yoluma çıkan göktaşı, dağ, nehir, tanrı gibi, 

Var olduğuna inanılan şeyleri, 

Geçiyordum devirip, çiğneyip, üstüne tükürerek.

Sonunda bir yerlere varmayı planladım hep, 

Anladım artık yokmuş kazanmakta, kaybetmekte.

Beklenenin ilerisinde bir yerdeyim şimdi, 

Ben erdem sahibi, sen saçma sapan bir oyunun galibisin...', 'Mutsuz günlerimde öğrendim,  Yelkovanla akrebin, dakikayla saatin kavgasını Ve bir hakem edasıyla yönettim,  Hiç karışmadan, birbirlerini öl...', ARRAY['Türk Edebiyatı','Şiir','Devrim Dinç']::text[], 8.5, '{"poet":"Devrim Dinç","poet_slug":"devrim-dinc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kazanan-oldu-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Dostuma', 'hayal-dostuma-fatma-ful-ozok-0lobp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yolum cennete düşmüşken, 

Direnip meleklere

Yolunu gözler, gözlerim...

Bekle dediğin yerde, 

Kadıköy''deyim...

Nerdesin hayal dostum? 

Gün doğdu, düş yollara

Düşlerde mi kaldın hala yoksa?', 'Yolum cennete düşmüşken,  Direnip meleklere Yolunu gözler, gözlerim... Bekle dediğin yerde,  Kadıköy''deyim... Nerdesin hayal dostum?  Gün do...', ARRAY['Türk Edebiyatı','Şiir','Fatma Ful Özok']::text[], 8.5, '{"poet":"Fatma Ful Özok","poet_slug":"fatma-ful-ozok","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayal-dostuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Yıllık Sevgi', 'bin-yillik-sevgi-muammer-celik-52det', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1)  

Bin yıldır yolunu bir bir beklediğim, sen

Eyy Orta Asya yaylarında yalnız bıraktığım kısrak

Bin yıl daha yolunu bekleyecek olduğum, sen

Eyy Kaşgar dağlarında gözlerimle okşadığım 

hayalini Anadolu’ya getirip içimin diyarına yaydığım 

dişi kadın, gel artık, yetmedi mi bunca yol beklediğim 

Horosan’dan geçerken atımın yelesinde oturan, sen 

Malazgirt’e girdiğimde öncülüğümü yapan, ülküm

Eyy Bişkek saraylarında yalnız bıraktığım kadınım 

Sevgini ektim tüm Anadolu’ya, adım adım

Eyy Tibet doruklarında kokladığım çiçeğim 

Yetmedi mi meyvelerini toplamaya beklediğim 

Bin yıldır yolunu diyar diyar gözlediğim, sen

Eyyy Altay dağlarında belek belek saçlarını ördüğüm 

Bin yıl daha geçse yine sevecek olduğum yavuklum 

Kafkasların sarp dağlarından Arap yarımadasına kadar 

Anadolu’dan Alp dağlarına kadar arkasından koştuğum

Şimdi ise Kuzeyin soğuğunda, koynumda ısıttığım, sen 

Eyyy düşlerimin çırılçıplak, örtüsüz, kusursuz KADINI

Yetmedi mi gök kubbeyi inleten çığlıklarla çağırdığım adını...! 

2)  

Selam sana eyy aşk tanrıçası

Babil çöllerinde 

asma bağların amazonu

Asya''dan Avrupa''ya sevdamı taşıyan kısrak

Yatağıma ığıl ığıl, dalga dalga, aşk çarşafı seren 

girip gizlice yüreğime, boş kalan tahtına oturdun

İstanbul Boğazı’nda beni boğazlayan hatun

gönlümde şiir toplayıp, şiir deren, KADIN, selam

Selam sana, eyy Roma''ya giden

tüm yolları kesen Cleopatra

Özgürlük cepheme şelek şelek 

mermi taşıyan KARA FATMA

Ortadoğu’nun ilk ve tek madonnası AYŞE''m

aşkının nar''ına yandım, sevdana öldüm ben

Gel, dirilt beni, diriltebilirsen, KÜLLERİMDEN...! 

20.05.2003', '1)   Bin yıldır yolunu bir bir beklediğim, sen Eyy Orta Asya yaylarında yalnız bıraktığım kısrak Bin yıl daha yolunu bekleyecek olduğum, sen...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bin-yillik-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Alışkanlık *', 'aliskanlik-muammer-celik-8lzcj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne şarkılar

ne şiirler yazdım 

bir fincan kahvenin yanında 

ne sigaralar içtim 

tekrar tekrar okurken onları 

sigaramın markası: Hüzün ve ayrılık 

birde ”Sağlığa zararlı” yazıyordu üstelik… 

Ne ağıtlar yaktım

ne ezgiler söyledim 

resminin başında 

ne zehirler içtim

tekrar tekrar dinlerken onları 

içkimin adı: ''Hüzün ve Ayrılık'' 

birde „Alışkanlık yapar“ yazıyordu üstelik... 

Ne türküler mırıldandım

oynak havalar dinledim yokluğunda 

nice şimşir kaşıklar kırdım

döne döne oynarken oynattım 

Türkümün adi; ''BirDeli YÜREK'' 

elimde bir kazma ile kürek 

''Müzmin Sondur Bu! “ yazıyordum 

hüzün içinde gülümseyerek... 

BirDeli

09.06.2003', 'Ne şarkılar ne şiirler yazdım  bir fincan kahvenin yanında  ne sigaralar içtim  tekrar tekrar okurken onları  sigaramın markası: Hüzün ve ay...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aliskanlik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Sanadır Bu Sitem', 'canim-sanadir-bu-sitem-derin-oger-j8nll', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dön küskün bulutlarıma

Yetsin sılayı gezdiği yollar

Gel geçmişi anlat bana dağ bayır

Sönmesin yüreğimizde yaktığımız ateşler

İnan hiç derdim değil sümbüller laleler

Gel mevsimsiz aşılmıyor mesafeler

Gel neyin karşılığıdır bu ayrılık...

Dön yetiş susuz kervanıma

Uçurumlar sarmalamış yol bilmiyor

Gel hasretimin dengi dağlar tepeler

Sevgi yalan mutluluk yalan yaşanıyor

Gel yıldızlarımıza karanlıklar tırmanıyor

Gel canım canının yoldaşını arıyor

Gel yazgımız olmasın bu ayrılık.....', 'Dön küskün bulutlarıma Yetsin sılayı gezdiği yollar Gel geçmişi anlat bana dağ bayır Sönmesin yüreğimizde yaktığımız ateşler İnan hiç derdim...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/canim-sanadir-bu-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilitlenmiş Aşk', 'kilitlenmis-ask-muammer-celik-hiu39', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unutulmayan, unutulmayacak olan aşkım, 

tadın damağımda kalacak olan meşkim, 

resmi göz kapaklarımda asılı olan sevgilim, 

ardında izin kaldı, eser bıraktığını sanma, 

Onlar senin bıraktıkların değil, sakın unutma 

onlar kendim için alıkoyduğum değerlerim, 

duygularım, mektuplarım, sana olan şiirlerim...! 

Sen alıp götürmedin onları 

götüremedin daha doğrusu...! 

Gittiğine yandığımı hiç düşünme  sadece

kaldığın süreye acıyorum gittiğin sürece...! 

Dönerim de deme sakın, 

gelişine bin kilit vurdum, 

hemde taaa göz kapaklarımdaki 

resminin tam ortasına koydum...! 

10.09.2003', 'Unutulmayan, unutulmayacak olan aşkım,  tadın damağımda kalacak olan meşkim,  resmi göz kapaklarımda asılı olan sevgilim,  ardında izin kald...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kilitlenmis-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-oguzkan-bolukbasi-yzlg7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hikayeler gelir gider

yaşama öykünmeleri anlatır

kadere ilenmeleri bazen

her omuz kendi derdini taşır

her yürek kendi mutluluğunu bilmezler mi

her yaşamı bir insan çeker

her insan ayrı bir yaşamdır

her öpülen kurbağa,  prenses olmaz

her prenses, öpülmek için kurbağa

kaldır gözlerini

etrafına bak

sebepler bolcadır

çözümler yolda

bence sen sen ol da

yaşamanın tadını çıkar

zaman dolmadan', 'hikayeler gelir gider yaşama öykünmeleri anlatır kadere ilenmeleri bazen her omuz kendi derdini taşır her yürek kendi mutluluğunu bilmezler ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ogut-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mıh…', 'mih-aylin-aydin-9gi4v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırıldığı yerden devam edemiyor hayat

Hayatım

Hayatın

Kırık çıkık bir koşuşturma başlıyor

O andan sonrası alçıya alınmış kırık  kaşıntısı gibi

Sızım sızım, ince ince 

Hatta  bazı soğuklarda  ağrımsı

Gecelerde  inleyen yerlerin acısı

Yani bildiğin gibi 

Kırılma anı gibi ve sonrası 

Bildiğin gibi 

Anlattırma bana

Ben mi? 

Hatırlamıyorum

Mevsim, gün, saat 

Hiç bilmiyorum

Bildiğim, 

ayaktaydım 

Dimdiktim

Olmazın olmadığı yaşlardı

Açık seçik aşklar yaşardık

Dilimizin kemiği yoktu

Kemiklerimiz sızlayana kadar seviştiğimiz zamanlardı anlayacağın…

Yani hayatın gülümsediği

Yerlere kadar eğilip bizi selamladığı ve yeniden karşımıza dikildiği zamanlardı.

Yani dost sandığımız zamanlar….

O yüzden ummadık bir anda yakalandık ya! 

Ayaktaydım

ellerim, yüreğim, evim, telefonlarım, beynim dopdoluydu

Kalabalıktan göremediğim duygular geçiriyorken

Yok saydıklarımı  çoktan unutmuşken

Şimdi hatırlıyorum

Seni hatırlıyorum

Bıktığımı ve yok saydığımı hatırlıyorum

Gözlerinle bana seslendiğin o anı hatırlıyorum

Cevapsız bıraktığım bakışlarını yeni aşkların  göğüslerine yumduğumu 

Seninle yarına gidemediğimi

Hayal kırıklığını

Çaresizlikten ellerini sakladığını

Gözlerinde  intihar etmiş çocuğu

hatırlıyorum

Hatırlıyorum 

Hatırlıyorum.', 'Kırıldığı yerden devam edemiyor hayat Hayatım Hayatın Kırık çıkık bir koşuşturma başlıyor O andan sonrası alçıya alınmış kırık  kaşıntısı gi...', ARRAY['Türk Edebiyatı','Şiir','Aylin Aydın']::text[], 8.5, '{"poet":"Aylin Aydın","poet_slug":"aylin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/mih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğur Getirsin Diye', 'ugur-getirsin-diye-aylin-aydin-00q20', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tahmini kararlarla duruyordum  uzağında

Uzağında durmak işime geliyordu

İşime gelen senin varlığındı

Var olduğunu hissedemediğim an ölecektim biliyordum.

Coğrafyanı bilmemek, sesinle sabahlamamak, ellerine yumulmamak 

hiç mühim değildi, mühim olmadı,  olamadı, 

Ayrı kentler ayrı duygular doğuruyordu 

belki de sürekli  ölü duygular doğuruyorduk birbirimiz için

birbirimize ne yaptık hatırlamıyorum.

Mesafesi öyle uzun duraklarda karşılaştık ki seninle

Bir dahası olmayacakmış hissiyle

bu histeki ilgisizlikle

Ahhh ne büyük yanılgı

Ahh ne büyük arıza

Ne büyük tedbirsizlik 

ne kadar gecikmiş olsa da karşımdaydın işte

Kendimi karşıma almış gibi konuşuyordum seninle 

Her seferinde farklı biri

Farklı bir göz donukluğu gözyaşı seferberliği

İşgal edilmişlik,  teslimiyet, kargaşa, toz duman ve ölüler

Bizim olan ölüler, yaralılar, merhem edilen kelimeler

Narkoz etkisindeki ihanet

En bildik şehirlerden çalınan ve en bilmedik dağların doruklarına  gizlenen 

Bizim bile adını koyamadığımız, koymadığımız   öfke:

Ahhh bir anahtar olsaydı da yedi kat yerin altına gömdüğün kapıdan giriverseydim içeri

oysa şöyle bir bakıp çıkacaktım, biri var mı  diye göz atacaktım

Yedi kat yerin dibinde adını fısıldadım 

sayıkladım bağırdım haykırdım

almadın beni içeri

Tarifi ne mümkün ki, 

Seni dostlara anlatmak ne mümkün, 

Çizmek,  sesini taklit etmek 

kelimelerin arasındaki uçurumlara düşmeden cümle sonuna varmak 

ne mümkün

Uğursuz bir yansıması var yüzünün hayatıma

küçük iğnelerin gözbebeklerimi nakşetmesi

iyi yürekli bir cin tarafından sürekli teselli edilişim 

hepsi birer halüsinasyon 

sanrılarla bağladın beni kendine

kitaplar indirdin sabaha karşı düş dağlarıma

bilmediğim dillerde  şiirler yazdın, haritalar çizdin yolları olmayan

kaç rekatla döner yüzün şimdi benden tarafa 

hangi dil anahtar olur kilidine

hangi  yönde durursam kaybolmam

biliyorum

bunların hepsi şizofrenik tanımlar

adın, kitapların, kilitsiz anahtarlar 

hepsi

hayatıma uğur getirsin diye…', 'Tahmini kararlarla duruyordum  uzağında Uzağında durmak işime geliyordu İşime gelen senin varlığındı Var olduğunu hissedemediğim an ölecekti...', ARRAY['Türk Edebiyatı','Şiir','Aylin Aydın']::text[], 8.5, '{"poet":"Aylin Aydın","poet_slug":"aylin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ugur-getirsin-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cafe', 'cafe-aylin-aydin-onqce', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceyi de teslim ettik düşmana

Aşka ve sevdaya

Tetik üstündeki kalp atışları

Kalbin amansız duruşu 

Ateş almayan silah ve gece

iki ayrı kişi, iki ayrı korku…

geceyi de teslim ettik düşmana

aşka ve sevdaya

benimkinin adı aşk

benimki sevgi diyor öteki

bilemediği tek şey

tetik üstündeki aşk 

sevgiyi vurdu.

Üzgünüm

yine teslim ettik geceyi düşmana

Aşka ve sevdaya

Sen oradaydın, 

Gördün

Dudakların aralandıkça sen sustun

Tek kelime çıkmadı ağzından

Oysa ki seviyordun

Sevdiğini biliyordum

Tetik üstündeydi aşkım

Sevgini vuracaktı

Sen susuyordun

Parmaklarını sayıyordun

Bir ömür sayıyordun

Aşkım tetik üstündeydi

Sevgini vuracaktı

Biliyordun

Kaçmadın. 

(04.09.2001)', 'Geceyi de teslim ettik düşmana Aşka ve sevdaya Tetik üstündeki kalp atışları Kalbin amansız duruşu  Ateş almayan silah ve gece iki ayrı kişi...', ARRAY['Türk Edebiyatı','Şiir','Aylin Aydın']::text[], 8.5, '{"poet":"Aylin Aydın","poet_slug":"aylin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cafe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulaç', 'kulac-aylin-aydin-5b86f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tüm denizlerin günahı benim boynumA

Uzun dalgalar, 

yitik mavilere boyanan kum tanecikleri 

hepsi birgün benim için kutsal kitabın günah satırları olacak…. 

ben yaşamı böyle içine içine sokularak 

belki de kıyılarında tek ayak üstü sek sek oynayarak selamlıyorum…

Eyyy gece ve gündüz 

ellerim güneşe tutulmadıkça 

kuşlarla göçüp gitmeyeceğim.

Tüm denizlerin günahı benim olsun… 

bir de senin…

 - deniz kokan adam-

Ne kadar çok tuzlanırsa vücudum 

o kadar deniz olur ellerim, 

gözlerim mavi mavi düşer toprağa. 

Ben iyot kokusunda kumsala vurmuş bir küçük istarvit gibi hazırlanırım 

bir akşamüstü ziyafetine…

Akşamlar… 

Geceler…

Dolunayın gülümsemesiyle birlikte 

belki bu gece kurtulurum.', 'Tüm denizlerin günahı benim boynumA Uzun dalgalar,  yitik mavilere boyanan kum tanecikleri  hepsi birgün benim için kutsal kitabın günah sat...', ARRAY['Türk Edebiyatı','Şiir','Aylin Aydın']::text[], 8.5, '{"poet":"Aylin Aydın","poet_slug":"aylin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kulac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-sair-masmavi-8vyug', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat, 

Her ölümün ardından

Bir yeni doğumu muştular, 

Gülümseyerek sana uzaktan.

Hayat, 

Kaybederken sen onu, 

Buldurur sana seni, 

Anlamadan daha bulduğunu.

Hayat, 

Gülümsetir ağlarken, 

Zifiri karanlığındayken tam sen gecenin, 

Doğan güneş gibi.', 'Hayat,  Her ölümün ardından Bir yeni doğumu muştular,  Gülümseyerek sana uzaktan. Hayat,  Kaybederken sen onu,  Buldurur sana seni,  Anlamad...', ARRAY['Türk Edebiyatı','Şiir','Şair Masmavi']::text[], 8.5, '{"poet":"Şair Masmavi","poet_slug":"sair-masmavi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız', 'adsiz-sair-masmavi-f8yvj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tek başıma çıktım bu yola, 

Gizlisiz, saklısızdım oysa, 

Karanlıkta iz sürmekten

Yoruldum anlasana.

Coşmuştum varlığınla, 

Yaşamın armağanıydın bana, 

Hakedilmemiş sitemlerden

Kırıldım anlasana.', 'Tek başıma çıktım bu yola,  Gizlisiz, saklısızdım oysa,  Karanlıkta iz sürmekten Yoruldum anlasana. Coşmuştum varlığınla,  Yaşamın armağanıy...', ARRAY['Türk Edebiyatı','Şiir','Şair Masmavi']::text[], 8.5, '{"poet":"Şair Masmavi","poet_slug":"sair-masmavi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/adsiz-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamın Eriyim Ben', 'sevdamin-eriyim-ben-murat-demir-1bdew', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkını bir dert gibi

Çekiyorum ben içten

Ne yapsan katlanırım

Hatıran var geçmişten

Nerde o eski günler

Geriye gelirmiki

Hayatıma yeniden

Tanrı gün verirmiki

Güzelliğine kanıp

Yanarım yandığıma

Düşündükçe şaşarım

Sana inandığıma

Her ne yapsan yeridir

Kapılmışım bir kere

Ben seni seviyorum

Öldürsende bin kere

Bu aşkın zehirini

Bal eğleyip içmişim

Senin kadar dünyada

Kimseyi sevmemişim

Sevdamın eriyim ben

Geriye adım atmam

Ateş olup kalbimi

Kavursanda bırakmam', 'Aşkını bir dert gibi Çekiyorum ben içten Ne yapsan katlanırım Hatıran var geçmişten Nerde o eski günler Geriye gelirmiki Hayatıma yeniden Ta...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdamin-eriyim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahardayız Şimdi', 'bahardayiz-simdi-zeki-ergin-x385k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bahardayız şimdi

umut türküleri söylüyoruz doğayla birlik

istemiyoruz akşam olsun

sindiriyoruz hücrelerimize güneşi

yürüyoruz yarınlara

doğa açarken çiçek çiçek

yürüyoruz yarınlara

bahardayız şimdi 

gebeyiz yarınlara doğayla birlik

susamışlara su verme zamanıdır

açıl

serpil

kenetlen

bir senfonidir pikapta dönen

doğal bir senfoni

yarınlara yönelen

el ele verip

kendimizi bir ırmağa bırakıp

baharı ciğerlerimize çekip

yürüyoruz yarınlara

doğa açarken çiçek çiçek

yürüyoruz yarınlara

_hamleciler yt:1975

_sevgiliye isyan  yt:haz04', 'bahardayız şimdi umut türküleri söylüyoruz doğayla birlik istemiyoruz akşam olsun sindiriyoruz hücrelerimize güneşi yürüyoruz yarınlara doğa...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bahardayiz-simdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam Bir Kara Yılan', 'sevdam-bir-kara-yilan-esma-ozdemir-30q14', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdam bir kara yılan

Dolan boynuma dolan

Ak göğsümün üstüne

Kıvran benimle kıvran

Sevdam bir kara zindan

Dayan yüreğim dayan

Kara kara donlara

Boyan benimle boyan

Sevdam bir oynak çengi

Gözleri sürme rengi

Bir elinde tef çalar

Bir elinde zilleri

Sevdam bir taze çağla

Ağla gözlerim ağla

Sen de bir sevda isen

Sevdalığına doyma', 'Sevdam bir kara yılan Dolan boynuma dolan Ak göğsümün üstüne Kıvran benimle kıvran Sevdam bir kara zindan Dayan yüreğim dayan Kara kara donl...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdam-bir-kara-yilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah', 'ah-melek-midikoglu-nuomm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaldırımlara serdim 

kaldırımlara serdim 

vurdum 

ezdim 

ezdirttim bedenimi, 

kanım aktı, 

gözüm yaşardı, 

içimdeki Aşk''ı 

çıkaramadım! 

Ahh 

Sevdiğim..

seni göreli 

sesini duyalı

gözüm kör, 

kulağım sağır, 

derim yok, 

kayboldum bu dünyada 

ve hissetmiyorum acılarını...', 'Kaldırımlara serdim  kaldırımlara serdim  vurdum  ezdim  ezdirttim bedenimi,  kanım aktı,  gözüm yaşardı,  içimdeki Aşk''ı  çıkaramadım!  Ahh...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ah-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gelen Doğan Gün Bize', 'her-gelen-dogan-gun-bize-zeki-ergin-qd5k7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-1-

omuz omuza yaşadığım sevgiliye

bir çift sözüm olacak

istemlerimden yana

uzaydayız gelecekte

uydular yıldızları kucakladı bu günden

göğün katları aşılıyor

makineler güçleniyor

oysa özgürlükten ve uygarlıktan yana çok fakiriz

ve diğer ülkelerde kıyasıya savaş

göğsüm şişiyor

ve kurtuluş için ölenlerle ölüyorum

her dakika ölüyor diriliyorum

-2-

yokluğu kamçılayıp

karanlıklarına perde çektik bu ülkenin

sokaklar niye çıkmaza götürdü hep

niye açılmadı

ak zambaklar kan karanfiller

buğulu gözler bir mitralyoz oldu

gören yok gözyaşlarını

oysa yarına bayram var

bitmiyen sonsuza

her gelen doğan gün bize

_hamleciler  yt:75

_sevgiliye isyan yt:haz04', '-1- omuz omuza yaşadığım sevgiliye bir çift sözüm olacak istemlerimden yana uzaydayız gelecekte uydular yıldızları kucakladı bu günden göğün...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/her-gelen-dogan-gun-bize-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şıpsevdi', 'sipsevdi-bahar-gulsen-09wv3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“Seni seviyorum gülüm'' diyorsun, 

Bu sözleri, yaban güllerine de söylüyorsun.

Söylesene şıpsevdi, 

Sen sevmeyi biliyor musun? 

Sahiden kimi seviyorsun? 

Kandırmaksa niyetin, 

Aldanan sadece kendi yüreğin olur, 

Bilesin!', '“Seni seviyorum gülüm'' diyorsun,  Bu sözleri, yaban güllerine de söylüyorsun. Söylesene şıpsevdi,  Sen sevmeyi biliyor musun?  Sahiden kimi ...', ARRAY['Türk Edebiyatı','Şiir','Bahar Gülşen']::text[], 8.5, '{"poet":"Bahar Gülşen","poet_slug":"bahar-gulsen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sipsevdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maestro', 'maestro-mehmed-arif-pxtdd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'heybemde kelimeler

kimsesiz şehirlerden kalma

sahipsiz sokaklardan devşirme 

ademden beri ne varsa 

işte bu torbada

güllü dikenli

telli duvaklı

ölümlü düğünlü

geceli gündüzlü

aşka ve ayrılığa dair

ne ararsan 

yedi kısım tekmili birden burada

dil yaresi işte

şair kırıntısı

doğum sancısı basar şafak vakti

heybem kusar kelimeleri

dizilirler ardarda

ve gözler maestroda

şefin işaretiyle

başlar büyük senfoni

aman allahım

bu ahenk de ne? 

raksı düş gezgini imgelerin 

lam, mim ve de nun

aşık her dem maşukuna meftun

arıyor sahibini 

beni yaratan kim?', 'heybemde kelimeler kimsesiz şehirlerden kalma sahipsiz sokaklardan devşirme  ademden beri ne varsa  işte bu torbada güllü dikenli telli duva...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Arif']::text[], 8.5, '{"poet":"Mehmed Arif","poet_slug":"mehmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/maestro-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızı', 'sizi-mehmed-arif-zulhc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'madem ki gidecektin dönüp bakmadan

neden söylemedin yutulmazdı denizin suyu

- ki deniz yakar genzimi

aheste yüreğim sürgün 

küsülü yarınlarıma

davacıyım mazimizden 

alacaklıyım esirgediklerinden

Haber verin Kadıya 

dilekçesinin pulları benden

kuruverin şuraya 

üç ayak sehpayı

ne de yakışırım 

yağlı urgana

saçlarım savrulur maltada

sizin günahınızla

bir yalnızlık şarkısı bestelerim

benden sonraya…', 'madem ki gidecektin dönüp bakmadan neden söylemedin yutulmazdı denizin suyu - ki deniz yakar genzimi aheste yüreğim sürgün  küsülü yarınları...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Arif']::text[], 8.5, '{"poet":"Mehmed Arif","poet_slug":"mehmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sizi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-mehmed-arif-akxhm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'işte sonbahar 

mevsim ölüyor yine bedenimde

yokluk denizine akan benim sancılarım

benim helvam himmet kazanında kaynayan

komşu mahalleden beri

benim defterim açılıyor 

evsizlere ilk ders olarak

ey büyülü yolun yolcuları

ey takva ağacının dalları

katarınızda yer var mı bana da

çok şey mi istiyorum yoksa

yetimlerin okşanan başları 

açların doyrulan karınları aşkına

matem yurduna açılan kapılar kapansın artık

bitsin bu dinmeyen susuzluğum

işte o büyülü şehir

işte o gönlümün sultanı beni bekliyor

koyverin beni bana

can yakışır cananına', 'işte sonbahar  mevsim ölüyor yine bedenimde yokluk denizine akan benim sancılarım benim helvam himmet kazanında kaynayan komşu mahalleden be...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Arif']::text[], 8.5, '{"poet":"Mehmed Arif","poet_slug":"mehmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevgili-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Fark', 'i-ste-fark-nazan-danacioglu-8gmlz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hissetmeyi unutmadım, 

Göstermeyi bilmiyorum.

Hep kuytuları sevdi gözyaşım, 

Hep sayfalara döktü içini... 

Kahkahalarımsa 

Beni duyarsız yapan, 

Gözlerimde bul hüznümü, 

Yüreğim, bir yanardağdan püsküren, 

Sıcak küllerle dolu! 

Hala anlamamışsan

Ve tanımadan sevmişsen beni, 

Düşlediğin “biz” olamamışsak, 

Sen ve beni özetleyeyim sana, 

Masaya indirdiğin yumruğu anlatayım:

Senin öfken, ithamlarla dolu; 

Kırıcı bin bir sözcük savuruyor havaya, 

Benim öfkem, kalem veriyor elime, 

Bir şiir yazdırıyor; sana ithaf edilmiş! 

Senin yüreğin adanmışlık istiyor; 

Sen bir ateş, ben pervane, 

Dönmeliyim etrafında...

Benim ki, 

Özgürlüğü paylaşmak.

İşte, aramızdaki fark! 

30/08/2003', 'Hissetmeyi unutmadım,  Göstermeyi bilmiyorum. Hep kuytuları sevdi gözyaşım,  Hep sayfalara döktü içini...  Kahkahalarımsa  Beni duyarsız yap...', ARRAY['Türk Edebiyatı','Şiir','Nazan Danacıoğlu']::text[], 8.5, '{"poet":"Nazan Danacıoğlu","poet_slug":"nazan-danacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/iste-fark-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyü', 'buyu-ahmet-muhsin-tg8up', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eskiden aşklar

Sığamazdı cüzdanlara

Kredi kartlarıyla mı

Bozuldu büyü', 'Eskiden aşklar Sığamazdı cüzdanlara Kredi kartlarıyla mı Bozuldu büyü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Muhsin']::text[], 8.5, '{"poet":"Ahmet Muhsin","poet_slug":"ahmet-muhsin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/buyu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz ve Sen', 'deniz-ve-sen-mustafa-karadeniz-24xwu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şehirde bir seni, 

Bir de denizi sevdim.

Denize baktıkca seni, 

Sana baktıca denizi gördüm. 

Deniz senin kadar masum, 

Sense deniz kadar enginsin. 

Denizi senin kadar güzel, 

Seni ise denizi kıskandıracak kadar

Güzel olduğun için sevdim...', 'Bu şehirde bir seni,  Bir de denizi sevdim. Denize baktıkca seni,  Sana baktıca denizi gördüm.  Deniz senin kadar masum,  Sense deniz kadar ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karadeniz']::text[], 8.5, '{"poet":"Mustafa Karadeniz","poet_slug":"mustafa-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/deniz-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Öyle bir Kumsunki', 'sen-oyle-bir-kumsunki-fazil-husnu-cakiroglu-dm64u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen öyle bir nehirsin ki! 

Denizi olmayan, 

Kivrila kivrila akan kendi yataginda.

Sen öyle bir gülsün ki! 

Yedi mevsim hic solmayan.

Sen öyle bir denizsin ki! 

Kendi cukurunda

Öfkesiyle kiyilari döven.

Sen öyle bir kumsun ki! 

Avuclarimda durmayan, 

Denizin dalgalariyla oynayan.

Sen öyle bir limansin ki! 

Ne inen belli ne binen

Rihtimin mahser yeri.

Icinde unutulmus yüzlerce capari

Marti sesleriyle.', 'Sen öyle bir nehirsin ki!  Denizi olmayan,  Kivrila kivrila akan kendi yataginda. Sen öyle bir gülsün ki!  Yedi mevsim hic solmayan. Sen öyl...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-oyle-bir-kumsunki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşim''e Yani Diğer Yarım''a', 'esim-e-yani-diger-yarim-a-oguzkan-bolukbasi-4x93c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bütün kelimeleri sen bana ver

dilinin ucunda söyleyemediğin

ben sıraya dizerim

hayatıma işlerim ziynet gibi

senin sözcüklerinle elbiseler giyerim

ne kadınlar sevdim

ne aşklar yaşadım

en son sana rastladım

sen benim karımsın

bir elma gibi yarımsın

aşk yok artık sen varsın

sen aşksın

gözlerse senin gözlerin

ellerse senin ellerin

sen farkında bile değilsin

sen varken seni özlerim

bırakma ellerimi düşeceğim

sıcaklığın olmasa üşüyeceğim', 'bütün kelimeleri sen bana ver dilinin ucunda söyleyemediğin ben sıraya dizerim hayatıma işlerim ziynet gibi senin sözcüklerinle elbiseler gi...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/esim-e-yani-diger-yarim-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrımların yokluğu', 'ayrimlarin-yoklugu-mete-tugluk-ze6u2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eriyip iskelete dönüşmüş değerleri

değerleri gömmüşüm yokluğa

mutlu ne

mutsuz ne

bilmiyorum

sevinç ne

üzünç ne

yanlışları silmişim sözlüğümden gibi doğrular

kendindeliğidir varlıkların pasparlak parlayan

sen

maviliğini kargışlarken bile morların

ben

taşa taş diyorum insana insan

duyuyorum

onlar

ayrımlarının yokluğunu haykırıyorlar

seviyorum taşları insanları sevdiğim kadar

mutluzum gibi sanki

sanki gibi mutluzum...', 'eriyip iskelete dönüşmüş değerleri değerleri gömmüşüm yokluğa mutlu ne mutsuz ne bilmiyorum sevinç ne üzünç ne yanlışları silmişim sözlüğümd...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ayrimlarin-yoklugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saydam duvar', 'saydam-duvar-mete-tugluk-5om5v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aşk erdemdir

öğretmişlerdi

mercek onlardı ışık ben ve geçerdim

kaçırılan sevgiler umursanmaz odaklara yönelmiştim

bir de yol vardı ama gizlemişlerdi bilmezdim

kadınların kesik yüzü kanamazdı banka afişlerinde

zor değildi çıkmak sakarya volkanlarına

yanlış giden şeylerin kokusu havada

bir de hız vardı ama gizlemişlerdi bilmezdim

yıllarla yitirip parıltısını keskinliğin

bir çığlık gibi çarpınca saydam duvara

bedenimle odaksız

bedenimle umarsız sevgilere karıştım

ve ruhumu asıp menat''ın boynuna

ve çamurların arasında

ve çıplak

ne olduğumu kavradım...', 'aşk erdemdir öğretmişlerdi mercek onlardı ışık ben ve geçerdim kaçırılan sevgiler umursanmaz odaklara yönelmiştim bir de yol vardı ama gizle...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/saydam-duvar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kadar Acı Çektiğimi Bilmiyor musun?', 'ne-kadar-aci-cektigimi-bilmiyor-musun-tolga-ayla-k3m9l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni bir an içimde hissettiğimde rüzgarı beklerim

Sonra çıkagelir rüzgar, çam ağacımızın tanıdık kollarına yaslanırım.

Avuçlarımı toprağa bırakır, gözyaşım toprağımıza akar; 

Toprak ben olurum: ben, toprak ve biz...

Seni getirecek her neyse bu can feda değil miydi ona? 

Son sözlerin varya; bu dünya sensiz olmaz, bizimle olur, 

Beni bir çağırdığını bilsem gelmez miydim cennetine? 

Varlığımı o çok sevdiğin çam ağacına adadım...

O''na ruhunu verdim...

Hani ölüler her şeyi görür ve bilirlermiş ya, 

Sende acı çektiğimi görüyorsun, değil mi? 

Bu hayata beni mahkum etmeden önce

...birbirimize ne kadar çok sarılırdık, değil mi? 

N''olur bana yine sarıl, kollarını sırtıma dola, 

Tıpkı çam ağacımızın beni sardığı gibi

...bu dalların beni ısıttığı gibi.', 'Seni bir an içimde hissettiğimde rüzgarı beklerim Sonra çıkagelir rüzgar, çam ağacımızın tanıdık kollarına yaslanırım. Avuçlarımı toprağa bı...', ARRAY['Türk Edebiyatı','Şiir','Tolga Ayla']::text[], 8.5, '{"poet":"Tolga Ayla","poet_slug":"tolga-ayla","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-kadar-aci-cektigimi-bilmiyor-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simdi Anladim', 'simdi-anladim-faruk-unal-ur90e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aglamayi gözyaslarini

Simdi anladim

Hasreti cileyi

Simdi anladim

Acilari yanginlari

Simdi anladim

Seni nasil sevmisim 

Simdi anladim

Hepsini

Sen pozanti''ya gelin gidince

Daha''da cok anladim 

Dost edindim', 'Aglamayi gözyaslarini Simdi anladim Hasreti cileyi Simdi anladim Acilari yanginlari Simdi anladim Seni nasil sevmisim  Simdi anladim Hepsini...', ARRAY['Türk Edebiyatı','Şiir','Faruk Ünal']::text[], 8.5, '{"poet":"Faruk Ünal","poet_slug":"faruk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/simdi-anladim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemin Yetişir Gel Diyemem', 'ozlemin-yetisir-gel-diyemem-ahmet-yalcinkaya-t36mt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sana gel diyemem

sen gibiyken gel diyemem

uzak iklimlerden çağırmam seni

korkular öncesinde

              beni bulursan eğer

              bülbülsüz bahçelerde

              kaçarım

/ olur ya gülsüz yakalarsın

yaralarsın belki de /

              açılırım artık denizlere

              enginlere bakmam

/ olur ya gemim sana koşar

sana gelirim uzak iklimlere /', 'sana gel diyemem sen gibiyken gel diyemem uzak iklimlerden çağırmam seni korkular öncesinde               beni bulursan eğer               b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yalçınkaya']::text[], 8.5, '{"poet":"Ahmet Yalçınkaya","poet_slug":"ahmet-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozlemin-yetisir-gel-diyemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-ahmet-yalcinkaya-iqztk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sensiz olmak çok zormuş / çok zormuş sensiz olmak

sözcükler anlatamaz; kuvvetsiz kalır dilim, 

isterim gözlerinin ışığında kaybolmak

yüzünü bulutlara nakşederek, sevgilim

ne zaman baksam güne / ne zaman güne baksam

martıların izini sürerim deli gibi

gökyüzünde süzülsem, uçsam gölgene aksam

yine uzak gibisin canevimin sahibi.

akşamlar çetin burda / burda akşamlar çetin

yalnızlığın tütsülü kokusu ecel taşır.

efkâr çeşmesi artık yüreğimde hasretin, 

bu özlem ateş dansı; yangın taşır, sel taşır…', 'sensiz olmak çok zormuş / çok zormuş sensiz olmak sözcükler anlatamaz; kuvvetsiz kalır dilim,  isterim gözlerinin ışığında kaybolmak yüzünü ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yalçınkaya']::text[], 8.5, '{"poet":"Ahmet Yalçınkaya","poet_slug":"ahmet-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasret-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-ahmet-yalcinkaya-61tuv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdiğim, umutlar bahara benzer

Gönül bilinmez bir diyara benzer

Arzular en yaman ağyâra benzer…

Uğrunda arzunun girgini oldum

Hırçın derya idim kurudu suyum

Coşkun ırmak idim değişti huyum

Sel oldum dağıldı gitti sağduyum

Ve ben suların en durgunu oldum

Ovaları aştım, çölleri aştım

Hayalin bürüdü yolumdan şaştım

Bulamadım seni boşa dolaştım, 

Gezgin vakitlerin dargını oldum

Dediler ki unut her şey geçiyor, 

Kimi zehir kimi şerbet içiyor, 

İnsan ne ekerse onu biçiyor…

Bütün hasatların kırgını oldum

Söylenecek söz çok, yetmedi zaman

Zindanlara girdim bitmedi zaman

Yokuşlarda kaldı gitmedi zaman

Çağların ak saçlı yorgunu oldum

Yaşım otuz değil yüzyetmiş gibi

Aklım ölçüsünü kaybetmiş gibi

Bitmez sandığımız yol bitmiş gibi; 

Dipsiz kuyuların sürgünü oldum

Yıllarca dağlarda aradım seni

Sokaklar geçmeye koymadı beni

Nihayet sırtıma giydim kefeni

Sadık toprakların vurgunu oldum', 'Sevdiğim, umutlar bahara benzer Gönül bilinmez bir diyara benzer Arzular en yaman ağyâra benzer… Uğrunda arzunun girgini oldum Hırçın derya ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yalçınkaya']::text[], 8.5, '{"poet":"Ahmet Yalçınkaya","poet_slug":"ahmet-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/surgun-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Yakıyor Denizlerimi', 'gozlerin-yakiyor-denizlerimi-ahmet-yalcinkaya-znvw5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sana güneşimi getirdim leylâ

yıldızlara uçsuz merdiven saldım

bırak oyalanma mehtâpla, ayla

hüzün dağlarından bir mevsim aldım

sana güneşimi getirdim leylâ

zaman bir bilge kuş gibidir, tanır

ufukların kurnaz ayak izini

anlatayım desem sözler ne sanır

gönlümün kaynayan kor denizini

zaman bir bilge kuş gibidir, tanır…

bu suç edası ne bakışlarında

eylül sanki yorgun düşen gözlerin, 

bakarsın durulur hırçın denizler

şiir bağlarından ayrıldı yerin

kalbin bulut olur rüzgârla gider

eylül sanki yorgun düşen gözlerin

leylâ güneşimi getirdim sana

anla ki senindir bu kanlı şafak

bir derviş ruhuyla geldim kapına

yürek sürgünümü aşmış her yasak

leylâ güneşimi getirdim sana', 'sana güneşimi getirdim leylâ yıldızlara uçsuz merdiven saldım bırak oyalanma mehtâpla, ayla hüzün dağlarından bir mevsim aldım sana güneşimi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yalçınkaya']::text[], 8.5, '{"poet":"Ahmet Yalçınkaya","poet_slug":"ahmet-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gozlerin-yakiyor-denizlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Armağan', 'armagan-ahmet-yalcinkaya-mus7z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözlerin akkor gibi dağlasa şehirleri

yine de güneşimi al senin olsun derim.

çorak iklimlerimi beklesen bir dakika

durmam, ayak izinden haftalarca giderim…

ne çıkıp eller gibi delebildim dağları

ne de garip çöllerde şiir söyledim sana.

benim fazla gücüm yok, duygularım körpedir

dilersen yüreğimi sererim yollarına…

kanatlarım olsaydı kırardım, bilmelisin

yakınında, tutsağın olsam da, kalsam diye.

hayalin alev alev sardı beni, şaşırdım; 

yıldızlar neye benzer söyle mevsimler neye…

mâdem yanarım külüm armağan olsun sana, 

belki elin değer de avuturum kendimi…

istemezsen toprağa gönder bassın bağrına!', 'gözlerin akkor gibi dağlasa şehirleri yine de güneşimi al senin olsun derim. çorak iklimlerimi beklesen bir dakika durmam, ayak izinden haft...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yalçınkaya']::text[], 8.5, '{"poet":"Ahmet Yalçınkaya","poet_slug":"ahmet-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/armagan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikâye', 'hik-ye-ahmet-yalcinkaya-3rlu9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'zaman yaprak sarısıydı o gün

ve kadın ihanet doğurdu 

sedeften

yedi bağbozumu yaşandı 

çığlık çığlığa

yedi çağ devrilmişken

zaman aksak yürüyordu o gün

kan kırmızı olduğu söylense de

yılan doğdu birden

sular ağır ağır çekildi / yok düştü

o gün

pusuda karayeller

bir alevi boğdu zarifce

ve durdu

salkımları beklermiş gibi durdu

yedi gün uyumayan değirmen', 'zaman yaprak sarısıydı o gün ve kadın ihanet doğurdu  sedeften yedi bağbozumu yaşandı  çığlık çığlığa yedi çağ devrilmişken zaman aksak yürü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yalçınkaya']::text[], 8.5, '{"poet":"Ahmet Yalçınkaya","poet_slug":"ahmet-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hikaye-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Bu Közü Kalbime Atma Demiştim', 'sana-bu-kozu-kalbime-atma-demistim-ahmet-yalcinkaya-1whiu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sana bu yollarda bekleme demiştim

canevimi yakarsın.

bir hastalık zuhur eder vakitsiz

alır götürür beni…

ateşin dolaşır da sonra damarlarımda

içime ılık sular gibi akarsın

ve bir yangın tâkip eder izini; 

her yanımı alevler sarar

başucumda küllerime bakarsın.

ne gözyaşın yetişir yardımıma

ne yüreğini dolduran engin deniz.

sana bu yolları gözleme demiştim

canevinden yanarsın.

içine hayaller düşer,

saatler girer düşüncene…

gelmez deme bilinmez bir gün gelir

yolların boş olduğunu görürsün

içine korkular düşer,

güzel demezsin böylece istesen de

güzel demezsin yeşile, maviye, pembeye

ve geçmiş sabahları anarsın.

gecelerle sırdaş olan gözlerin

hâtıralarına taşınır artık sessizce,

kim bilecek sen mi üzgünsün, ama sen bilirsin

kim bilecek…yoksa zaman mı üzgün

belki sise karışıp giden yıllara kanarsın.', 'sana bu yollarda bekleme demiştim canevimi yakarsın. bir hastalık zuhur eder vakitsiz alır götürür beni… ateşin dolaşır da sonra damarlarımd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yalçınkaya']::text[], 8.5, '{"poet":"Ahmet Yalçınkaya","poet_slug":"ahmet-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sana-bu-kozu-kalbime-atma-demistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-i-brahim-atilmis-66d3v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'insanlar insancıklar

her biri birer küçük yalancıklar...

seviyorumda seni hani; 

her ne kadar insan olsakta ikimiz! ?', 'insanlar insancıklar her biri birer küçük yalancıklar... seviyorumda seni hani;  her ne kadar insan olsakta ikimiz! ?...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/insanlar-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-hatice-ari-swwpi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerimde kan kıvılcım alevler, 

Yüreğimde soğumaya demlenmiş korlar, 

Ah, aklımdan, seni unutmak geçer; 

Mümkün mü? 

Dağ başlarında acmış çiğdemlere benzer; 

Tomurcuk salmış, yele yağmura inat, 

Tüm bir evreni anbere bezer, 

Öyle hafif ki kokusu; 

Melekler kanat..

Ürktün mü? 

Her gün, yeni doğan güne tapar, 

Bulutlardan salıncaklar yapardık, 

Bir elimizden yıldız, 

Bir elimizden ay, 

Gökyüzünden sonsuzluğa kayardık, 

Düştün mü? 

Biz mi büyüdük düşlerde, 

Yoksa, gündüzler mi karardı? 

Kısa mıydı ömür, 

Yoksa film mi bu kadardı? 

Artık salınmıyorsun yanımda, 

Belin mi bükük, 

Yoksa saçların mı ağardı? 

Şimdi sen

Bana, 

Onca hayali

İki satıra hapsettim diye

Yoksa, 

Küstün mü?', 'Gözlerimde kan kıvılcım alevler,  Yüreğimde soğumaya demlenmiş korlar,  Ah, aklımdan, seni unutmak geçer;  Mümkün mü?  Dağ başlarında acmış ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Arı']::text[], 8.5, '{"poet":"Hatice Arı","poet_slug":"hatice-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/soru-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-zeynel-yalman-3xim2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimi zaman hayal oldun sadece, 

Kimi zamansa rüya oldun geceme.

Kendimi parçaladığım zamanlar oldu seni düşünerek 

Ve hiç aldırmadığım gidişine...

Sen ne olduğu bilinmez, 

Aslında hiç görülmemiş, 

Hiç tutulmamış, 

Nerde yaşadığı bilinmeyen, 

Değişik iklimlerin

Soğuk sabahlarının karışımısın belki de.

Her seferinde değişik bir üşümek aldı beni

Rüzgarın nereden geldiğini bile bilmeden.

Sen benim güne dair 

Umutlarımın başlangıcı, 

Geceye dair korkularımın kahramanısın.

İçimde, 

Güvensizliğimsin kendime...

Çok uzaklarda bir şehirsin

Her zaman ulaşmak istediğim; 

Fakat bir türlü uzanamadığım.

Sen, 

Kimi zaman tebessüm oldun yaşadığım ana, 

Kimi zamansa hayal kırıklığı; 

Yaşayamadığım, 

Sadece umut ettiğim anlarıma..!', 'Kimi zaman hayal oldun sadece,  Kimi zamansa rüya oldun geceme. Kendimi parçaladığım zamanlar oldu seni düşünerek  Ve hiç aldırmadığım gidiş...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Yalman']::text[], 8.5, '{"poet":"Zeynel Yalman","poet_slug":"zeynel-yalman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-289-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Ev', 'kucuk-ev-zeynel-yalman-qa0ji', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçük bir ev, 

Bir de sokak lambası.

Dönüyoruz.

Gece, 

Kar yağıyor

Ve bembeyaz

Öyle uzanmışızki karın üzerine...

Sevişircesine!', 'Küçük bir ev,  Bir de sokak lambası. Dönüyoruz. Gece,  Kar yağıyor Ve bembeyaz Öyle uzanmışızki karın üzerine... Sevişircesine!...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Yalman']::text[], 8.5, '{"poet":"Zeynel Yalman","poet_slug":"zeynel-yalman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kucuk-ev-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak', 'korkak-zeynel-yalman-t63ln', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hadım olan adamlara

çocuk-çoluk sorulmazmış, 

şerefsiz yaşayanlarda

onur, gurur aranmazmış

insanoğlu korkar fakat

kaçmaz ise korkulardan, 

ödülünü alır elbet

bıkmaz ise savaşmaktan', 'hadım olan adamlara çocuk-çoluk sorulmazmış,  şerefsiz yaşayanlarda onur, gurur aranmazmış insanoğlu korkar fakat kaçmaz ise korkulardan,  ö...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Yalman']::text[], 8.5, '{"poet":"Zeynel Yalman","poet_slug":"zeynel-yalman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/korkak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarsın', 'anlarsin-zeynel-yalman-4ke1y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül diker bahçene yari beklersin, 

Gözlere dalarsın onu ararsın, 

Boş yere yollara küfür edersin, 

Batınca anlarsın diken dediğin.

Güneşten bekleme birşey söylemez, 

Denize aldanma seni dinlemez, 

Bilmezler derdini kimse anlamaz, 

Sönünce anlarsın ışık dediğin.

Yapraklar sararır düşer ağaçtan, 

Gökyüzü kararır döker sarnıçtan, 

Yaz ayları biter geçer kılıçtan, 

Boş kalır anlarsın dalım dediğin

Kuş olup uçmaksa yare ulaşmak, 

Gün olup doğmaksa ona kavuşmak, 

Söz olup yazmaksa asıl savaşmak, 

Kırılır anlarsın kalem dediğin.

Türküler söylemek sana hüzündür, 

Ocakta yananlar senin közündür, 

Bir kadeh rakıyla bir de tütündür, 

Düşünce anlarsın külüm dediğin.

Yaşamak bildiğin pınar gibiymiş, 

İçtikçe içerler sebil günüymüş

Lakin durmaz, akar, hayat faniymiş, 

Ak düşer anlarsın saçım dediğin.', 'Gül diker bahçene yari beklersin,  Gözlere dalarsın onu ararsın,  Boş yere yollara küfür edersin,  Batınca anlarsın diken dediğin. Güneşten ...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Yalman']::text[], 8.5, '{"poet":"Zeynel Yalman","poet_slug":"zeynel-yalman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anlarsin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yine Gülümü Seveyim', 'ben-yine-gulumu-seveyim-esma-ozdemir-51avk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğle gönlünü eğlendiğin yurdunda 

Söyle türkünü sana aşina dostlarına

Konuş kitabından, dinine imanına! 

Ben, yine gülümü seveyim; 

Sen, sevgini kırçiçeklerine sakla! 

Sen aşk ol, sevda ol, sevgi ol; 

Ben gam, ben keder, ben acı olayım.

Sen kutlu, mutlu ve umutlu ol; 

Ben, yine gülümü seveyim, yapayalnız; 

Sen, hevesini kırçiçeklerine sakla! 

Sen beyaz, sen ak, sen tertemiz ol! 

Ben günah, ben ceza, ben kir olayım! 

Sen, elini şehvetle hayalimde yıka 

Ben yine gülümü seveyim; 

Sen, aşkını tertemiz kırçiçeklerine sakla!', 'Eğle gönlünü eğlendiğin yurdunda  Söyle türkünü sana aşina dostlarına Konuş kitabından, dinine imanına!  Ben, yine gülümü seveyim;  Sen, sev...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-yine-gulumu-seveyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bir Söylem', 'kucuk-bir-soylem-zeynel-yalman-o3i0d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz hayatı tümevarım yöntemiyle öğreniyoruz, 

Tek tek yaşıyoruz.

Lakin tüme varamadık henüz.

Malum, parçalarla uğraşıyoruz...

Bestsel yaşantıları vardır kimilerinin, 

Kimilerinse bitkisel..! 

''Havyar''ın derdi beni germedi ama, 

Soganı düşündükçe

Bir dilim havyar geliyor aklıma.

Ekmek zaten aslanın malum yerinde...

Birgün anlarız elbet magazin sayfalarının rengarenklilik nedenini.

Ama öncesinde mapusane yollarını gösterin bize.

Demir parmaklık ardına sığar mıydı hiç düşünce? 

burası küçük bir sahne 

ya oyna, ya s...git geldiğin yere...

kimileri meeeeeliyor olduğu yerde, 

kimileriyse hala siperde, nöbette.

Tüme varıyoruz yavaş, yavaş

acelemiz yok.

soğan zaten bize alıştı, 

lakin herşey soğanlaşmaya başladı!', 'Biz hayatı tümevarım yöntemiyle öğreniyoruz,  Tek tek yaşıyoruz. Lakin tüme varamadık henüz. Malum, parçalarla uğraşıyoruz... Bestsel yaşant...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Yalman']::text[], 8.5, '{"poet":"Zeynel Yalman","poet_slug":"zeynel-yalman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kucuk-bir-soylem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadi', 'olmadi-erkan-uyar-fmtpo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gozlerim yollara dalip gidiyor

Bekledim gunlerce gelen olmadi

Umitler beni tek tek terk ediyor

Perisan halimi bilen olmadi

Yildizlar sahit unuttum uykuyu

Ben aci cekerken sen rahat uyu

Agladim gizlice geceler boyu

Akan gozyasimi silen olmadi.

                                       2001/Eskisehir', 'Gozlerim yollara dalip gidiyor Bekledim gunlerce gelen olmadi Umitler beni tek tek terk ediyor Perisan halimi bilen olmadi Yildizlar sahit u...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uyar']::text[], 8.5, '{"poet":"Erkan Uyar","poet_slug":"erkan-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olmadi-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Karaya Ayak Bastı - şiir öykü -', 'deniz-karaya-ayak-basti-siir-oyku-erdinc-ozdemir-g61bi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapı açıldı

Bazıları içeri giremedi

Ağzını açmış gecenin

Labirentlerinde

Akmayan hayatlarıyla

Ayaktaydılar

Ayakta, değişmeyen tuhaf düşler

- Evini bulamayan bir tren

- Satranç oynamayı unutan karga

- Bisikletle gezinmeyi seven atlar

- Düşleriyle kayak yapan bir kalem

- Saçları uzamış vesikalık fotoğraflar

Onlar

Hiç seyahat etmeyen kulaklarıyla

Sanki hayatın nöbetçi eczanesiydiler

Ölseler yalnızlıkları bile duymazdı

İşte o an 

Tam o an

Köpüren dalgalarıyla

Deniz karaya ayak bastı

Maraton kazanmış atlet gibi

Yorgun bir sevinçle

Kucaklaştılar

Şehrin bütün ışıkları yeşile dönüştü

Deniz onları lokantaya götürdü önce

Mavi yolculuğun serin sularında yol alırken hayat

Sinemaya gittiler

Palyaçobalıklarıyla Lunapark şenliği

Martılar, beyaz uçurtmalar

Aynaya bakmadan geçen

Sayfaları karışmış yılların ardından

Öylesine mutluydular ki

Ahtapotun kollarında yakamoz uykuya daldılar

Kapı açıldı

Bazıları içeri giremedi

Çok yaşlı yeni doğmuş kelebekler

Düşündüler

'''' Kazın ayağı öyle değil ''''

Rengarenk şarkılarıyla

Kapıyı bekleyen akbabaların üstüne çöktüler

Çekilirken akbabalar birer birer

Yüzotuzaltı yıl susmuş bir mızıka

Yeniden çalmaya başlıyor', 'Kapı açıldı Bazıları içeri giremedi Ağzını açmış gecenin Labirentlerinde Akmayan hayatlarıyla Ayaktaydılar Ayakta, değişmeyen tuhaf düşler -...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Özdemir']::text[], 8.5, '{"poet":"Erdinç Özdemir","poet_slug":"erdinc-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/deniz-karaya-ayak-basti-siir-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-mustafa-gideroglu-1fma2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana

Boya kokulu bir odada

Özlemle

Yalnızlığın tadına varmış bir şekilde

Hep senle dolu olarak

Nilüfer çiçeğinin unutkanlığıyla

Kulağım müzikle dolu

Kalbim sen nidalarıyla

Yazıyorum

Adaylardan hiç biri olmayaçağını bilerek

Başka limanlara yelken çevirerek

İsyanlarla kaynayan

bir gemiyle yol alıyorum', 'Sana Boya kokulu bir odada Özlemle Yalnızlığın tadına varmış bir şekilde Hep senle dolu olarak Nilüfer çiçeğinin unutkanlığıyla Kulağım müzi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gideroğlu']::text[], 8.5, '{"poet":"Mustafa Gideroğlu","poet_slug":"mustafa-gideroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sana-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Aşk Olmazdı', 'ask-ask-olmazdi-derin-oger-j3k4g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün de geçer

Geçer her anın dünü gibi

Yarınlarda saklar gönlümün sırlarını

Say ki söndürmüşüm içimdeki kıvılcımlarını

Yaşıyorum güller içinde baharı yazı

Gönlün vefasıdır çizen sabrın sınırlarını

Görürdün başımda olsaydı aşkın tacı

Damlayken sakladım gözyaşımda aşkı

İçimde nasıl da görkemli ateşinin çıtırtıları

Sustum ama dudağımda gümüşledim adını

Aşka değil gurura eğdim başımı

Yalvarsam dilensem aşk....Aşk olmazdı.......', 'Bugün de geçer Geçer her anın dünü gibi Yarınlarda saklar gönlümün sırlarını Say ki söndürmüşüm içimdeki kıvılcımlarını Yaşıyorum güller içi...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-ask-olmazdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Viva La Beyoğlu', 'viva-la-beyoglu-hakan-liman-2jm9s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soğuk odalarda yaşar bizim gibiler..

Üşümek nedir bilmez, 

Karanlıkta kanyak içip ısıtır ve aydınlatırlar geceyi..

En çok sonbaharı severler..

Simsiyah giyinip rüzgarı kozmetik deymemiş teninde hissetmeye bayılır, 

Yağmurun her damlasında binlerce parçaya bölünmüş hayatlar sezer ve sigarayı öyle bir körüklerler ki geçtikleri sokaklar aydınlanır ateşinden..

Polisle işi olmaz bizim gibilerin, 

Ne korunmaya ihtiyaçları vardır ne de kimseye bir zararları..

Hayatı dört dakikalık bir şarkıda yaşarlar

Müzik susar, ağlamaklı şarkıcı keser söylemeyi ve bar sandalyesinde şarkıya devam eder bahsi geçen serseri ruhlar..

Onlar içer, onlar sıçar, onlar Beyoğlu’nu özler..

Delikanlılıkla, adamlıkla de işi yoktur onların, köpekleri sever kurtlardan tiksinirler..

Kavgada kendi kendini öldüren ahmaklara lanet eder, ölüsüne tükürür, arkasından küfrederler..

Düzene uymak düzülmekle eşdeğer

Ölmek mutlu bir günbatımı seyridir..

Onların dininde on emir de yoktur dört büyük kitap da..

Sadece insanları seven ve şarap denen kutsal suyu bir gün bütün nehirlerden akıtacak kıyakçı bir tanrı vardır..', 'Soğuk odalarda yaşar bizim gibiler.. Üşümek nedir bilmez,  Karanlıkta kanyak içip ısıtır ve aydınlatırlar geceyi.. En çok sonbaharı severler...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/viva-la-beyoglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Carpe Diem I', 'carpe-diem-i-hakan-liman-o7est', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş hiç batmazmış

Son diye bir şey yokmuş

Acılar gelir, kapıyı çalar

	evde bulamazsa çeker gidermiş

Göze alınası bütün riskler alınmalı

Ve hayat dört dakikalık bir şarkı havasında yaşanmalıymış

Günler sayılmamalı

Antidepresanın dozu kaçırılmamalı

Ve yakılan her sigara

	ateş filtreye kavuşana kadar içilmeliymiş

-Geçmiş çoktan geçmiş

Gelecekse nasıl olsa gelecek-

Yaşanacak bir şeyler kaldıysa

Bitmediyse masal

Son deyişi söylemeden anlatıcı

Prenses kurbağayı öpmeliymiş..', 'Güneş hiç batmazmış Son diye bir şey yokmuş Acılar gelir, kapıyı çalar 	evde bulamazsa çeker gidermiş Göze alınası bütün riskler alınmalı Ve...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/carpe-diem-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Carpe Diem II', 'carpe-diem-ii-hakan-liman-u5vcb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dolunay görünmüyor artık 

			penceremden..

Gökyüzümü bulutlarla kapladın sen..

Temmuz sonu yağmur yağmış gibi

Ve martılar artık

		ağlamaktan bıkmış gibi

Soğuk duş kıvamında bir ayrılık bu..

Hoşçakal..', 'Dolunay görünmüyor artık  			penceremden.. Gökyüzümü bulutlarla kapladın sen.. Temmuz sonu yağmur yağmış gibi Ve martılar artık 		ağlamaktan...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/carpe-diem-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Üstünde Karam var', 'al-ustunde-karam-var-hayati-yavuzer-1n06q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her akşam tazelenir 

Her akşam filizlenir 

Her akşam bir baş verir 

Bilsem nerde çarem var 

Kimsesizim, yalnızım 

Derinlerde yaram var 

Yüreğim bir bedestan 

Binbir çeşit kumaş var 

Bir yanında düğün dernek 

Bir yanında savaş var 

Bütün uykular deli 

Rüyalarda haram var 

Kimsesizim, yalnızım 

Derinlerde yaram var 

Yüreğimin her yanı 

Menevişli hâreli 

Binbir çeşit hüzünlü 

Binbir çeşit yareli 

Al üstünde karam var 

Kimsesizim, yalnızım 

Derinlerde yaram var 

Bilsem ki son uykuya 

Kiminle varacagım 

Bilsem ki son rüyayı 

Kiminle göreceğim 

Bilsem ki son şarkıyı 

Kiminle diyeceğim 

Bilsem ki mutlulukta 

Benim de bir sıram var 

Kimsesizim, yalnızım 

Derinlerde yaram var 

İçimdeki bu boşluk 

Başımdaki sarhoşluk 

Kuşlardan uzak kuşluk 

Sessiz çığlıklarım ki 

Kaybolur derinlerde 

Karanlık gecelerde 

Gideceğim nere’m var 

Kimsesizim yalnızım 

Derinlerde yaram var 

Acım süzülmüş gibi 

Tenim kazılmış gibi 

Derim yüzülmüş gibi 

Kimsesizim, yalnızım 

Derinlerde yaram var 

(23 Eylül1999/ Üsküp)', 'Her akşam tazelenir  Her akşam filizlenir  Her akşam bir baş verir  Bilsem nerde çarem var  Kimsesizim, yalnızım  Derinlerde yaram var  Yüre...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/al-ustunde-karam-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Titreyen Kar Tanesiyim', 'titreyen-kar-tanesiyim-nuri-can-f5nbx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömrüm zemheride buzdağı

acıdan titreyen kar tanesiyim 

bedenim kış yorgunluğunu kuşanmış 

güneş de doğmuyor artık, yıldızımda söndü 

bir mevsim daha ardında bıraktı gitti gözlerimi

ne zaman bir çift turna havalansa

bilki  ben ölesiye dağlarımı özlerim

bir bıraksam uykulara 

düşecek gözkapaklarım

kapanacak gözlerim

bir daha, bir daha hiç açılmayacak

bir dağ isterdim başımı yaslayacak

bir gök  sarıp kucaklayacak

bir yıldız isterdim uzaklarda ışıyacak

benimkisi bir hayal işte 

biliyorum bunların hiç biri olmayacak

bir türkü düşer dilime akşam olunca 

yarası kanayan acılardan seslenir sesim 

üşürüm gurbet olurum kendime, hasret olurum 

donar bakışlarım, donar haykırışlarım 

donar gözyaşlarım 

öylesine efkarlıyımki dostlar, ölesiye 

her sabah penceremden kovduğum hüznü 

her akşam kapıdan selamla karşılarım 

diyorumki, bir akşam kollarımı gerip çarmıha 

yüreğimi alıp gitsinler sabahı uzak kentlere 

tutup bir denize serpsinler gözyaşlarımı 

ki, balıklardan başkası bilmesin 

ey hayat

ihanetin hançeri saplanınca  kalbime

 sevda adına vur boynumu 

adım mezartaşım olsun 

adım gözyaşım 

bağışlamasın beni hiç bir hatıra

yağmurlar yağsın serviler üstüne 

rüzgarlar essin doruklardan 

bir tutam kül olsun sevdam 

dağılsın okyanuslara 

kimseler bilmesin 

bir yaprağın ürpertisine sarıp acımı 

dikenli teller içinde 

yangınlı çöller içinde

ölüm sessizliğinde kalayım

Kaynak

www.nuricann.com', 'Ömrüm zemheride buzdağı acıdan titreyen kar tanesiyim  bedenim kış yorgunluğunu kuşanmış  güneş de doğmuyor artık, yıldızımda söndü  bir mev...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/titreyen-kar-tanesiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtim', 'vazgectim-mehmet-ali-kepez-xc0u7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'UzadIkça uzar aram

	Sırtımda kanIyor yaram

	Olmasın isterse çarem

	Aramak tan''da vaz geçtim

	Tek turna uçar göklerde

	Gelmezmi insan beklerde

	Làle sùmbùl çiçeklerde

	Vaz geçtim artık vaz geçtim

	Geçmiyor acım bitmiyor

	Anıların uyutmuyor

	Baktım ki çabam yetmiyor

	Direnmekten de vaz geçtim

	Yaktı kavurdu içmi

	Birde  söylese suçumu

	Kırağı  dùşmùs saçımı

	Taramaktanda vaz geçtim

	Bir kimsem yoktur yanımda

	Dere, tepe, ark önùmde

	Bıktım artık bu canımda

	Yaşamaktan da vaz geçtim

	Cenazem kalsın çollerde

	Yùzùm çevirdim gùllerde

	Gözùn kalmasın yollarda

	Sana dönmekte vaz geçtim', 'UzadIkça uzar aram 	Sırtımda kanIyor yaram 	Olmasın isterse çarem 	Aramak tan''da vaz geçtim 	Tek turna uçar göklerde 	Gelmezmi insan beklerd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vazgectim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onsuz Aşk…!', 'onsuz-ask-muammer-celik-lnpbj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk''a bir tokat attım, geldi yüzümü cırmaladı

Aşk''a bir kucak açtım, geldi beni yerden yere vurdu… 

Ey aşk seni duvara çakmak

dar ağacında asmak lazım 

mezarını yedi kat yerin dibine kazmak lazım…

Bilirim, 

sen gene hortlarsın içimde

en iyisi seni ”O”nsuz yaşamayı öğrenmek lazım…! 

19.08.2003', 'Aşk''a bir tokat attım, geldi yüzümü cırmaladı Aşk''a bir kucak açtım, geldi beni yerden yere vurdu…  Ey aşk seni duvara çakmak dar ağacında a...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/onsuz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevda ki…', 'bir-sevda-ki-muammer-celik-ofvpp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.....başımda

duman duman dağ tepesidir tüter de tüter 

bir aşktır ki yüreğimde, 

alev alev ocak ateşidir yakar da yakar.. 

Bir sevgidir içimde, buram buram kokan

bir özlemdir gırtlağıma zokka gibi oturan

düğüm düğüm, vuslatın ipidir, ölesiye beni boğan…!

BirDeli 

18.08.2003', '.....başımda duman duman dağ tepesidir tüter de tüter  bir aşktır ki yüreğimde,  alev alev ocak ateşidir yakar da yakar..  Bir sevgidir içim...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-sevda-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimce Sevdim', 'kendimce-sevdim-muammer-celik-plqa7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni kendimce sevdim, 

en az kendim kadar, 

hatta kendimden biraz fazla..

Umutlarım yıkıldıkça sevdim, 

umutlar kadar, 

hatta kendinden biraz fazla, 

biraz nazla, 

biraz öfke ile...

Her aksam küstüm sana, 

gecelerimde yoksun diye…

Her sabah sana uyandım yeni bir umutla, 

her gün batışında daha çok sevdim, 

seni senden biraz daha fazla…

Daha çok sarıldım yokluğuna

biraz nazla

biraz da öfke ile…

Seni Kendimce sevdim

.., ve kendimce özledim… 

13.05.2003', 'Seni kendimce sevdim,  en az kendim kadar,  hatta kendimden biraz fazla.. Umutlarım yıkıldıkça sevdim,  umutlar kadar,  hatta kendinden bira...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kendimce-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamozlarda Seveceğim', 'yakamozlarda-sevecegim-muammer-celik-gzf1e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sev beni, 

Beynimle

Aklımla

Bedenimle

duygularımla

Her şeyimle

Bir bütün olarak sev beni.

Sev beni hasretinle 

Öyle bir düşle ki beni

Sen beni, ben seni

Güneşle karşıladığımızda

Kırmızı gökyüzü yakaladığında sevgimizi

Yıldızlardan toplayalım birbirimizi

Sen ayda yakala beni

Ben yakamozlarda bekleyim seni

Dans edelim o ıssızların koyunda

Samanyolunun şarkısının yolunda.

Sev beni yüzyıllarda

Sev beni gökkubbede

Ve arş-ı azama yaz beni.

Ben seni yazıyorum satırlara 

Sonsuzlaşsın diye aşkımız

Yüreklerde okunsun diye sevdamız

Ezeli bir türkü olsun diye dillerde

Dinlendikçe evren dursun, devran dönsün.

Ben seni yakamozlarda seveceğim

Sende yıldızlarda sev beni, sevdiceğim. 

08.05.2003', 'Sev beni,  Beynimle Aklımla Bedenimle duygularımla Her şeyimle Bir bütün olarak sev beni. Sev beni hasretinle  Öyle bir düşle ki beni Sen be...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yakamozlarda-sevecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötem', 'otem-vedat-koparan-6c1cb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İhanetin son perdesinde korkularımız 

Savaşlar yol izi alır 

Acıtarak zaman 

Eskiyen yüzümüze düşer çizgi, çizgi 

Saklanırız 

Eski zaman oyunlarında çocuk yanımızla 

Çok şey değildi istenen 

Düşen bir damlada 

Uyumaya beş kala da 

Örtünmek, sarınmak ister yürek 

En saf hali ile uyanan bir gün gibi sevdada.. 

Kırıklarımı toplamaya bakıyorum 

Bir yaz güneşi de geçti 

Yinede özlemde depreşir sancılar 

Kanadıkça 

Bel ki bu yürek daha da açılır.. 

Kaç uçurumdan geçtim kaç uçurum bekler 

Yokluğunla vurma beni.. 

Öte yüzüm anadolum 

Bir baştan bir başa 

Öte yüzüm ülkem 

En saf en masum en temiz olanda 

Ben hep yangınlarda 

Ya  sen Ötem..? 

Vedat.K 06.09.2003 (20:55)   (2000 lere düşen iz düşümü zamansız mekansız hoyrat duygu kaçaklarından.)', 'İhanetin son perdesinde korkularımız  Savaşlar yol izi alır  Acıtarak zaman  Eskiyen yüzümüze düşer çizgi, çizgi  Saklanırız  Eski zaman oyu...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/otem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çare', 'care-vedat-koparan-ko4y2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üzülebilirliğime izin verdim 

Sevgide sevdim 

İçimdeki sevgi arsızı çocuğu 

Doldurman doyurman için 

Ben hep hazırdım 

Diğer yanım yolculuklara 

Benim olmayan sevdana.. 

Bilirim hep sevgi 

Kendi içinde acıyı da getirir 

Her aşkta kaç ah 

Büyütür varlık içinde yoklukları 

Olmadık bir rüzgar her an çıkar 

İnsan gururdan 

Ne çok şeyi yakar yıkar 

Ben kendimi hep ötemden öte 

Daha az sevmişken 

En fazla sen demişken 

Her şeyi senle başlatıp 

Mavileri denizde uyuturken 

Yüzdürürken gemileri 

Küpeştesinde yıldızları düşürürken 

İndirirken bulutlardan gecenin perdesini 

Senle geceleri kapatırken 

Tükenmek bilmezlerle çoğaltırken 

Tükenmeye yüz tutan solgun bir günde.. 

Parlak çiçeğim boynunu büktü 

Kaç gündür yoksun 

Suyu da  eksik kalmış 

Çaresizliğin çaresizliğinde 

Sendin yaşam sevinci direnci 

Gecenin gökyüzü güzellikleri de kıstı ışıklarını 

Bir mevsim kaçağına mavilerin sevgisizliğinde 

Karaları kararan geceleri indirdin ya 

Ben nede çok isimsiz adalara gittim 

Ne çok dağların doruklarında gözlerinin renginde 

Ne çok mavileri karaları içtim sensizliklerde 

Hadi yüreğim hadi toparlan gün açtı bile 

En çaresizliğimde de çare bende..! 

Vedat.K 07.09.2003 (21:44))   (2000 lere düşen iz düşümü zamansız mekansız hoyrat duygu kaçaklarından.)', 'Üzülebilirliğime izin verdim  Sevgide sevdim  İçimdeki sevgi arsızı çocuğu  Doldurman doyurman için  Ben hep hazırdım  Diğer yanım yolculukl...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/care-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılar büyütür/mü.?', 'acilar-buyutur-mu-vedat-koparan-avecb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç yaralanmadın mı çocuk 

Kaç kez  emeklerken 

Başladığın 

Yaşam yolculuğunda

Ne yaralar aldın 

Düştün de kalktın

Biliyorum 

Bu düşüş çok farklı

İnceden bir sızı 

En derin yara 

Bir bende bir bence

Yüreğine yer eden ışıkta

Buzul kesen mavilerde

Üstelik izi çok, çok kalıcı

Zaman denilen mefhum

Sen o zaman içinde..

Hazan geldi çattı hüzün bulutlarıyla 

Döker yağmurları yıkar uçurumları 

Toprak kayar karışır acılar 

Acıları sevinçlerine kat.

Saracaksın elbet 

Kanayan yaralarını 

İstersen sarmada göreyim

Tükenişini..

Bunu istemezsin değil mi.? 

Hadi, hadi çocuk hadi

Toparlan bakalım 

Yeter bu kadar 

Uçurum diplerinde dolandın 

Tutunduğun dağlara 

Varsın karlar yağsın 

Sen güneşe bakmaya devam et

Kökleri o kadar zayıf olana tutunma bir daha..

Nerden bileceksin, diye ne çıkışıyorsun.? 

Anlıyorum biliyorum yürek bu 

Bakma böyle dediğime

Görüyor musun

Ardıç kuşları geçiyor

Ona göre

Hadi at gitsin ardına, bak ileriye

Işık orada 

Nehir yatağına ulaşınca

Dinecek elbet o sızı

Mevsim hazana erdi 

İçe kaçışların anlarımıdır bu yaşananlar

Oysa daha yaşanacak neler var..

Vedat.K10.09.2003 (22:47)   (2000 lere düşen iz düşümü zamansız mekansız hoyrat duygu kaçaklarından.)', 'Hiç yaralanmadın mı çocuk  Kaç kez  emeklerken  Başladığın  Yaşam yolculuğunda Ne yaralar aldın  Düştün de kalktın Biliyorum  Bu düşüş çok f...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/acilar-buyutur-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silinmez Derindir', 'silinmez-derindir-vedat-koparan-rhvgy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamansızlıkta seninle doğdum 

Anızlar yanarken benliğimde 

Ağustosta vurdun 

Yokluk zamanlarında çoğaldıkça çoğaldın.. 

Soğuk bir yel esiyor 

Titredim 

İçim Ürperdi 

Sevda bu 

Bir başka dile geldi 

Güneşimsin 

Güneşten bile kıskanır 

Sakınırım seni 

Sustum mavim sustum 

Sustum yüreğim sustum 

Ben öldüremem bendeki seni 

Gel de sen öldür beni.. 

Vedat.K 01.09.2003 (18:22)  (2000 lere düşen iz düşümü zamansız mekansız hoyrat duygu kaçaklarından.)', 'Zamansızlıkta seninle doğdum  Anızlar yanarken benliğimde  Ağustosta vurdun  Yokluk zamanlarında çoğaldıkça çoğaldın..  Soğuk bir yel esiyor...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/silinmez-derindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaz Geçilmezim', 'vaz-gecilmezim-vedat-koparan-81eby', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilirmisin vaz  geçilmezim 

Ne fırtınalardayım 

Ne gemi azıya almışta gelmişim 

Küreksiz yelkensiz açık denizlerden 

Vurulmuş bir yaşamın paramparçalığında 

Her an yeniden doğuşları yaratıyorum 

Bizim olamayan mutluluk aynasında 

Nice özlemlerdir bir sahil kenti 

Çırılçıplak vururken yürek bendimi 

İstanbul gibi gelirsin akşam kızıllığında 

Her uzaklaştığında mavilerinle 

Bir o kadar yakınlaşırım 

Yüreğimin yangınlarında 

Bahar tazeliği 

Sevinçleridir sığınmalarım 

Sana her varışımda 

Her an beraberiz yaşamda 

Sen dilersen unut ama 

Ben unutmam seni asla.. 

Vedat.K 23.08.2003 (2000 lere düşen iz düşümü zamansız mekansız hoyrat duygu kaçaklarından.)', 'Bilirmisin vaz  geçilmezim  Ne fırtınalardayım  Ne gemi azıya almışta gelmişim  Küreksiz yelkensiz açık denizlerden  Vurulmuş bir yaşamın pa...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vaz-gecilmezim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitimsiz', 'bitimsiz-vedat-koparan-7qbze', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özlemek 

O kadar çok güzel değil

İnce sızıda 

En azından var biliniyordu 

Ve özlenen 

O kadar özel o kadar güzelken 

şimdi oda kalmadı

Yalnızlığın uçurumuna düşerken 

Ben sensizliklerde yanar, kanarken 

Sen bitti desen de sevmesen de 

Bu sevda bu aşk bende oldukça

Sönmez bitmez ne dersen de

Seviyorum seveceğimde..! 

Vedat.k 30.08.2003 (20:14)   (2000 lere düşen iz düşümü zamansız mekansız hoyrat duygu kaçaklarından.)', 'Özlemek  O kadar çok güzel değil İnce sızıda  En azından var biliniyordu  Ve özlenen  O kadar özel o kadar güzelken  şimdi oda kalmadı Yalnı...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bitimsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrün Kuşu', 'omrun-kusu-vedat-koparan-p3awb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman senin oldu 

Ne zaman onun oldun.. 

Ömrün kuşu 

Avuçlarında, 

Avuçlarından saldın 

Maviler susarken 

Suskun suslar da 

Nefesi kesildi 

Ömrün kuşu öldü..! 

(Yüreğini Serin Tut Sakın Üşümesin.) 

Vedat.K 29.08.2003 (01:47)   (2000 lere düşen iz düşümü zamansız mekansız hoyrat duygu kaçaklarından.)', 'Ne zaman senin oldu  Ne zaman onun oldun..  Ömrün kuşu  Avuçlarında,  Avuçlarından saldın  Maviler susarken  Suskun suslar da  Nefesi kesild...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/omrun-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam', 'bir-adam-vedat-koparan-erla8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdası çocuk sevinçlerinde 

Gözleri ışıl, ışıl ne kadar çok sevmişti 

Kendinden öte, hasret ayazlarında 

Hep büyüttü sevdasını 

Büyük bir heyecanla, tirtir, titrerken 

Düştü uçurumuna bir acı 

Açmadı o çiçek 

Kala kaldı buz kesen 

Hasret ayazı vurgunluğunda.. 

Sabah ayazında 

İskelenin serinliği içine işlerken 

Dondu mu, üşüdü mü kimse bilmedi 

Mavileri üşürken 

Bir başına başladığı yolculuğu 

Yine bir başına devamlarda 

Kırıkları acıta, acıta 

Gün karaları toplarken 

Serseri bir mayın tarlasında 

Mavnası çürümüş bir yelkenli 

Yönsüz dümensiz şimdi.. 

Ne geceleri yakmıştı 

Ne mülteci olmuştu kaçaklarında 

İçti durdu, 

O gecelerde, sigaralar birbiri peşine 

Ne yıldızlar düşmüştü gözlerine 

Bulup ta, ulaşamamanın sevinçlerinde 

Yaz mevsimi yılan derisi değişimi 

Kabuk değişti bir anda sevgi.. 

Ne kadar ilginçti 

Sevdiği bir gün ona 

Kardelenim var demişti 

Bu yaz mevsiminde, güneş açımlarında 

Meğer o kardelen hala kar altında 

Saman alevi yangınlığı sevgide 

Yaz geçende yaz, yazda biri üşümede.. 

Yürek duvarında gün sızıyorken 

Kanarken o yürek, ışığa hasret 

Kan damladı, çatladı yürek duvarı 

İçin, için kanadı, sessiz bir direnişte 

Ağlar hep o çocuk yitiklerde.. 

Var mı idi 

Bir hayal mi idi yoksa 

Başlanan sorguda 

Tüm benliğine, akarken maviler 

Kanadı, sustu.. 

Şimdi okyanusta bir sünger 

Bekler avcısını 

Mavi hayal mavi vurgunda.. 

Adını sen koymuştun 

Senin olanda 

Ömrüm kuşunun 

Vurgun 

Bu yangın mavilerine.. 

Sevgi denizine düşen  bir kırık damla.. 

En güzel maviler 

En çok kanarken, acılar yürekte 

Bundan böyle, suskun mavilerde..! 

Vedat.K 29.08.2003 (00:14)  (2000 lere düşen iz düşümü zamansız mekansız hoyrat duygu kaçaklarından.)', 'Sevdası çocuk sevinçlerinde  Gözleri ışıl, ışıl ne kadar çok sevmişti  Kendinden öte, hasret ayazlarında  Hep büyüttü sevdasını  Büyük bir h...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/bir-adam-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın...', 'ansizin-oguzhan-tas-aafne', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ansizin dogar gunes, ansizin kaybolur, 

Ansizin dogum haberini alir bir baba bebeginin, 

Ansizin caktirmadan gelir ayrilik, 

Ansizin hissettirmeden gider sevdiklerin, 

Ansizin deprem olur, gonuller yikilir, 

Ansizin hisler kaybolur, guven yerlerde sürünür, 

Ansizin yolculuklar baslar, ansizin biter, 

&Yacute; nsanlar durur oylece, her sey birden olur.

Sinema seridi gibi akar gider ne varsa, 

Geriye sadece sevgi, dostluk ve ilik bir muhabbet

kalir su uc nefeslik dunyadan.', 'Ansizin dogar gunes, ansizin kaybolur,  Ansizin dogum haberini alir bir baba bebeginin,  Ansizin caktirmadan gelir ayrilik,  Ansizin hissett...', ARRAY['Türk Edebiyatı','Şiir','Oğuzhan Taş']::text[], 8.5, '{"poet":"Oğuzhan Taş","poet_slug":"oguzhan-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ansizin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimizdeki Perdeler', 'gozlerimizdeki-perdeler-mehtap-uyanik-8v155', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerimizin önüne perdeler iner

kimi zaman Pembedir rengi

Dünyadaki herşeyi öyle görür

öyle duyarız

umutlar o rengi alır

yüzler, kalpler hep aynıdır

bazı şeyler yarım kalır

sonra gelir diğer perde

Kırmızı olur batan güneş

Gül kırmızı,  kalp kırmızı

dikenlerin akıttığı kan kırmızı

Bembeyazdır tertemizdir herşey

ilk doğduğunda

gözümüzdeki bu perde

hep o masum  yüzlerde gösterir kendini

o saf gülüşlerde görürüz hayatın anlamını

ya o Mavi,  Leylak,  Mor renkler

kimi hüznü taşır,  kimi dinginlik

bekleyipte gelmeyenlerin ifadesi

hayatın acı hatıraları binlerce yüzde

Siyah beni karmakarışık duygulara iter

hazin ölümler ardından yer, gök

siyah olur

sanki sözleşmişlerdir

en olumsuz anlarda bir sis perdesi olup

kapatmak ister bütün renkleri

sonra göz kapaklarımız ağırlaşır

kapatmak istemeyiz

belkide rengi ne olursa olsun

kaybetmekten korkarız

bize ait olan ne varsa

tatlı, acı

siyaha bile razı oluruz

biliriz ardından gelen beyaz

bize yeni umutlar ve renkler verecektir.

(Nashville,  05/01/2001)', 'Gözlerimizin önüne perdeler iner kimi zaman Pembedir rengi Dünyadaki herşeyi öyle görür öyle duyarız umutlar o rengi alır yüzler, kalpler he...', ARRAY['Türk Edebiyatı','Şiir','Mehtap Uyanık']::text[], 8.5, '{"poet":"Mehtap Uyanık","poet_slug":"mehtap-uyanik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gozlerimizdeki-perdeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Esareti', 'gecenin-esareti-mehtap-uyanik-fpowp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göz kapaklarım taşımıyor beni, 

Gittikçe ağırlaşıyor sözcükler.

Nabız atışlarımı hissediyorum, 

Parmaklarımın ucunda.

Herbir atışı yeni bir kelime

Ne olur bağışla beni, 

Daha fazla yazamadığım için, 

Bedenim gecenin esaretinde.', 'Göz kapaklarım taşımıyor beni,  Gittikçe ağırlaşıyor sözcükler. Nabız atışlarımı hissediyorum,  Parmaklarımın ucunda. Herbir atışı yeni bir ...', ARRAY['Türk Edebiyatı','Şiir','Mehtap Uyanık']::text[], 8.5, '{"poet":"Mehtap Uyanık","poet_slug":"mehtap-uyanik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gecenin-esareti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-mehtap-uyanik-x9dy0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', ''' Dostlara''

Yalnızlık çiçeklerini ektiğimizde

Yalnız, çiçekleri sularız sevgimizle.

İçimizdeki sevgili dostlardır

                  aslında yeşeren

                        çiçek açan

Gözümüz gibi bakarız onlara

Birgün dostlarla buluştuğumuzda

                     çiçeklerini sunarız

Ve demek isteriz ki aslında

Sizi hiç soldurmadık.', ''' Dostlara'' Yalnızlık çiçeklerini ektiğimizde Yalnız, çiçekleri sularız sevgimizle. İçimizdeki sevgili dostlardır                   aslında ...', ARRAY['Türk Edebiyatı','Şiir','Mehtap Uyanık']::text[], 8.5, '{"poet":"Mehtap Uyanık","poet_slug":"mehtap-uyanik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalnizlik-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örümlebek', 'orumlebek-mete-tugluk-4los4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uzatıyorum avucumda bir gökkuşağı kelebek

sevecen gözlerle yüzüne takarak gülüşü sen

haykırıyorsun

nefis

nefis

ve nefisliği öpüyorum ben

uzatıyorum avucumda bir kıllı örümcek

tiksinerek ve iterek elimi sen

haykırıyorsun

iğrenç

iğrenç

ve iğrençliği öpüyorum ben...', 'uzatıyorum avucumda bir gökkuşağı kelebek sevecen gözlerle yüzüne takarak gülüşü sen haykırıyorsun nefis nefis ve nefisliği öpüyorum ben uza...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/orumlebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-melek-midikoglu-oy2d8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiirlerimi

Sana yazmadım

Okurken satır aralarına 

adını koyma 

Kalbimin çarpıntısını 

suya yazmıştım

silinmedi

akıntıya kapılıp ona gitti

ve O GELDİ', 'Şiirlerimi Sana yazmadım Okurken satır aralarına  adını koyma  Kalbimin çarpıntısını  suya yazmıştım silinmedi akıntıya kapılıp ona gitti ve...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mektup-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B i z, H e p i m i z', 'b-i-z-h-e-p-i-m-i-z-mine-ozdemirtas-lg6ab', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kısırız, korkağız, sinmişiz işte.

Bir sıkımlık barut bile değil cesaretimiz.

Buruşmamış çarşaflara uyandığımızda her sabah, 

İç geçirsekte; belli belirsiz

Böylesi bir susuzluğu, hak etmediğimizin

Farkında bile değiliz.

Gözümüzde kara bir bant, 

Kahrolası burnumuz havalarda; 

Teğet geçip giderken ömrümüz sevdalara

Savaşmadan yenilmiş bir durumda

Yerlerde sürünmedeyiz.

Ve; yasakların kıskacında can verirken nefsimiz

Acele yaşanıvermiş aşkların asla

Gerçek tutkularımızla örtüşmediğini

Dillendiremeden, çaresiz tükenmedeyiz.

Suskun bir soru işareti, 

Yorgun bir ünlem gibi; 

Noktadan iri, Virgülden küçük

Minicik ama kocaman bir hiç’iz

Tarifi olmayan bir yerlerde

Kaybolup gitmişiz.

Kolu kırık, kanadı kırık ve yüreksiz

Tutsağız kısacası

Görünmese de zincirlerimiz.

11/09/2003 çamlıca', 'Kısırız, korkağız, sinmişiz işte. Bir sıkımlık barut bile değil cesaretimiz. Buruşmamış çarşaflara uyandığımızda her sabah,  İç geçirsekte; ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/b-i-z-h-e-p-i-m-i-z-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Rengi', 'sevda-rengi-sevcan-koyuncu-1uxbu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Burda her şey gök mavi...

Uzanıp da ellerimin varamadığı bir ay var

Avuçlarımdan dökülüyor dokunamadığım yıldızlar

Yanıp sönüp yanıyorum yağmurla

Gün görmemiş yanaklarım sırılsıklam

En dibindeyken ben denizin

Yüreğim ıpıslak hasretinden

Üşüyorum! 

Burda her şey gün beyaz...

Yanmayan bir ışık var tepemde

Duvarlar devriliyor üzerime kağıt gibi

Apak ellerim karalar bağlamış soyutluğundan

Sen yarsız bir sevdaya koşarken

Gün gibisin gözlerimde

Bir kar tanesi düşüyor alnına

Bembeyaz oluyorum ben

Eriyorum! 

Burda her şey kan kırmızı...

Kuruluktan rengini kaybetmiş güller var masamda

Gözbebeklerime saklı yaşlar akıp da yüreğime

Sıçrıyor evimin her köşesine

Kan renginde desenler çiziyor

Alevleri giyip üzerime çıkıyorum sabahları

Yaklaştıkça sana sönüyorum

Hasretinden ne eller eskittim 

Ne yürekler yitirdim ben

Eskiyorum! 

Burda her şey ölüm kara...

Gece renginde bir kuş var penceremde

Zifiri bir sis çökmüş üzerime

Gözlerimin karasında parlarken yüzün

Saçların kadar kara yüreğin uzak bana

Senli günlere inat sönüyor gözlerim

Yanıyorum! 

Burda her şey sevda rengi...

Her şey senden ibaret

Sevmek kolay da burda

Kavuşmak zor

Acıyorum!', 'Burda her şey gök mavi... Uzanıp da ellerimin varamadığı bir ay var Avuçlarımdan dökülüyor dokunamadığım yıldızlar Yanıp sönüp yanıyorum yağ...', ARRAY['Türk Edebiyatı','Şiir','Sevcan Koyuncu']::text[], 8.5, '{"poet":"Sevcan Koyuncu","poet_slug":"sevcan-koyuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sevda-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Numussuz Namuslular’a', 'numussuz-namuslular-a-arzu-dincer-dwi6l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kayıp bir musumiyet, 

Gizlenmiş namus ağacına...

Meyva niyetine şerefler yenmiş, 

Şerefsizlik zırhına sığınmış

Kurtlar sofrasında...', 'Kayıp bir musumiyet,  Gizlenmiş namus ağacına... Meyva niyetine şerefler yenmiş,  Şerefsizlik zırhına sığınmış Kurtlar sofrasında......', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/numussuz-namuslular-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Anlamı', 'sevginin-anlami-sema-aka-ovkov', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk bir sis bulutu, bir an gelir bir an kaybolur

Sevgi ise bir gerçek, asla ve asla bitmeyecek.

Sevgi, saygı, anlayış sonu olmayan bir arayış

Bulan olurmu bilmem, belkide boş bir yakarış.

Geçmişe dönüp bir baksan yalan, dolan ve riya

Her anında bir hüzün, her hüzünde bir kayıp

Gözyaşı, ayrılık, ızdırap bunlar hep yaşanacak

Nerede o eski sevdalar dilden dile dolaşacak.

Aşkı buldunmu bırakma sakın, sonunda sevgi gelir

Sevgin gerçek ise yaşam sana hoş gelir.

Sevda dillerde dolaşan bir şarkı, sen yaşadıkça sürecek

Yaşamdan ümidini kesme, inan seninde yüzün gülecek.', 'Aşk bir sis bulutu, bir an gelir bir an kaybolur Sevgi ise bir gerçek, asla ve asla bitmeyecek. Sevgi, saygı, anlayış sonu olmayan bir arayı...', ARRAY['Türk Edebiyatı','Şiir','Sema Aka']::text[], 8.5, '{"poet":"Sema Aka","poet_slug":"sema-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevginin-anlami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmenin Güzelliği', 'seni-sevmenin-guzelligi-arzu-dincer-b50g3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beyaz papatya yapraklarına yazdım seni, 

Itır yüklü rüzgarlarla kokunu çektim içime...

Yitik bir sevda türküsünde, haykırdım sevdamı...

Ben seni sevebilmenin güzelliğinde..

Mutluluk sarhoş’u olabilmek için sevdim...

Ben seni sevdiceğim, ben seni...

Tutuşan gecelerde ismini sayıklamak için sevdim...', 'Beyaz papatya yapraklarına yazdım seni,  Itır yüklü rüzgarlarla kokunu çektim içime... Yitik bir sevda türküsünde, haykırdım sevdamı... Ben ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/seni-sevmenin-guzelligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahenge Dönüş!', 'ahenge-donus-naime-erlacin-si6eu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sevişmiyorum artık sözcüklerle

raks etmiyoruz 

oynaşmıyor elleşmiyoruz

çıtır çıtır yiyorum onları! 

heyelan yapmasınlar ruhuma yeter

sarsmasınlar beni depremlerle

bıktım enkaz devşirmekten

yere düştü dillenmeyesi diller

güz yağmuruna kilitlendi gözlerim

vadimi arıyor verimli bir nehirde

sızılarım şimşeklerim çelik yüreğim 

tahtın musalla taşı olacak ey yorgun ölümlü! 

mor dikenler büyütüyorum erbainde

içimde ıssız bir ayna yürüyor

ilahi sırları bana emanet

derinime gizledim ağrıları, gömdüm dünü yarını

kararıyor ışıklar iniyor perde

ruhun ezeli mahzeninde artakalan ne varsa tortu adına

aslına rücu ediyor 

sineye kazıyarak dizeleri gömüyorum imgeyi şiirin kalbine

göktaşı saçılıyor boşluğa 

terk ediyorum tırısı rahvanı

nağmelerin ahenk tahtasında dörtnala ahenge dönüyorum! 

(11 Eylül 2003)

(Bu şiiri buraya getiren, Derin Öger’in dinmeyen bitmeyen çabalarıdır. Derin’e en derin sevgilerimle…)', 'sevişmiyorum artık sözcüklerle raks etmiyoruz  oynaşmıyor elleşmiyoruz çıtır çıtır yiyorum onları!  heyelan yapmasınlar ruhuma yeter sarsmas...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ahenge-donus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yokum Artık', 'ben-yokum-artik-murat-demir-4o99v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmiştim bir zaman delicesine 

Koymuştum kalbimin en yücesine 

Şimdiyse bu kalbi delercesine 

Yıkmana gerek yok ben yokum artık 

Şimdi ne istersen yapabilirsin 

Önüne geleni kapabilirsin 

İstediğin yerden sapabilirsin 

Durmana gerek yok ben yokum artık 

Bitirdin ömrümü göz göre göre 

Kalmadı içimde ne semt ne yöre

Götürüp bir yerde olsa da töre

Vurmana gerek yok ben yokum artık 

Aratmadın bana ipte cambazı 

Hep kışta bıraktın baharı yazı 

Bir çiçek uzatıp olur olmazı 

Sormana gerek yok ben yokum artık 

Neden böyle oldun bilemiyorum 

Ne kadar istesem gülemiyorum 

Her şey senin olsun istemiyorum 

Kırmana gerek yok ben yokum artık 

Muhtaç ettin beni yaban ellere 

Acımadan vurdun yerden yerlere 

Artık bundan sonra ilden illere 

Sürmene gerek yok ben yokum artık 

Düşseydin silmezdim ela gözüme 

Sense kılıç kalkan girdin özüme 

Dost düşman içinde bakıp yüzüme 

Gülmene gerek yok ben yokum artık 

Emsalin var mıdır etrafına bak 

Sönmüş bir ateşi tekrar dersin yak 

Sofranın üstüne çatalla tabak 

Koymana gerek yok ben yokum artık 

Beni öldürmeden verdin toprağa 

Benzettin dalından düşen yaprağa 

Al yeşil giyinip bahçeye bağa 

Çıkmana gerek yok ben yokum artık 

Aramam o masum bakışlarını 

Unutmam canımı yakışlarını 

Pişman olmuş gibi gözyaşlarını 

Dökmene gerek yok ben yokum artık 

Murat der vazgeçtim ben artık senden 

Bütün varlığını sildim gönlümden 

Varımı yoğumu aldın elimden 

Kovmana gerek yok ben yokum artık', 'Sevmiştim bir zaman delicesine  Koymuştum kalbimin en yücesine  Şimdiyse bu kalbi delercesine  Yıkmana gerek yok ben yokum artık  Şimdi ne i...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ben-yokum-artik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-mehmet-zeki-akdag-2qppv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir saniye bir yıl gibi

Oturdu hasret bağrıma

Düne düşman nesil gibi

Köprüleri yaktı gitti

Artık masalımız bitti.

Seven bilir farkımızı

Deniz çekmez korkumuzu

Kim anlar ki şarkımızı

Her bir makam yasın tuttu

Artık masalımız bitti.

Dokuz tuğlu beğler bile 

En özlenen çağlar bile

Taş gönüllü dağlar bile

Sevdamızın yasın tuttu

Gene masalımız bitti.

İnleyen bir kamıştım ben

Adın sevgi komuştum ben

Gövel gözlüm demiştim ben

Yalnız o sözümü tuttu

Kanat çırpa çırpa gitti.

Efsunlanmış gibi olduk

Sanki asırlarca eldik

Bilen var mı bize n''olduk

Şafaksız düşlere yattı

Artık masalımız bitti.', 'Bir saniye bir yıl gibi Oturdu hasret bağrıma Düne düşman nesil gibi Köprüleri yaktı gitti Artık masalımız bitti. Seven bilir farkımızı Deni...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Akdağ']::text[], 8.5, '{"poet":"Mehmet Zeki Akdağ","poet_slug":"mehmet-zeki-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ruya-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum Yalan Sevdalardan', 'yoruldum-yalan-sevdalardan-aysegul-toker-sk5oa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aslında bir çocuk gibi sevilmeye açım.

Sevilmek istiyorum ama sevemiyorum. 

Bu zamana dek yanlış insanları sevdim. 

Yanlış insanlar beni sevdi. 

Çok mu zaman geçti sevme yaşımın üzerinden? 

Kendimi kırkını aşmış biri gibi hissediyorum. 

Otuzların başında olmak da güzel değilmiş meğer.

Şimdi anlıyorum sevmek için geç kaldığımı. 

Sevme yaşımı kaçırdığımı...

Yalan sevdalar yordu yüreğimi... Sonu gelmez sevgiler tüketti beni...

Artık sevmekten kaçıyorum. Yeniden başlamaya korkuyorum.

Yüreğimi sevgilerden saklıyorum. Kendi içimde koruyorum. 

Sevemiyorum artık. Ve nedenini de biliyorum.

Kimliğin söylediği yaş neyi gösterir? 

Benim kalbim bir bebek gibi sevgiye aç

Bana ömür boyu sevgiyi kim verir? 

Kim gerçekten sevdi ki? Kaç. Sen de kaç

Boyalarda gizlemiyor geçen yılları

Her sevdanın verdiği; sadece acı.

Sende uzaklaş benden. hadi git.

Başka da gidenler oldu. Bu kaçıncı.

Her güne yalnız başlıyorum

Yıllardır aynı olanları yaşıyorum.

Her gün aynı''lar yaşanıyor.

Ve ben artık kimseyi sevemiyorum

Yoruldum yalan sevdalardan.

kalbimden vurup kaçanlardan.

Uzaklaşıp, yok olanlardan.

Teşekkür ederim her yalan sevdaya.

Beni küstürdüler hayata.', 'Aslında bir çocuk gibi sevilmeye açım. Sevilmek istiyorum ama sevemiyorum.  Bu zamana dek yanlış insanları sevdim.  Yanlış insanlar beni sev...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yoruldum-yalan-sevdalardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varmı İdi Böylesi Aşk', 'varmi-i-di-boylesi-ask-mehmet-zeki-akdag-jnh4s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sesin çiçek gülüşüydü aşkımız

Arandıkca bilinmeze karıştın

Sevgiden gerekli ne var dünyada

Masallara bulunmaza karıştın

Her şafakta yeni bir sen doğurdum

Sanki senden evvel kördüm sağırdım

Can suları mısralarla çağırdım

Gururundan gelinmeze karıştın.

Umutlar çatladı yazdan bahardan

Son trende kalktı bu yorgun gardan

Bakışın topladım hep aynalardan

Olmazlarla olunmaza karıştın.', 'Sesin çiçek gülüşüydü aşkımız Arandıkca bilinmeze karıştın Sevgiden gerekli ne var dünyada Masallara bulunmaza karıştın Her şafakta yeni bir...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Akdağ']::text[], 8.5, '{"poet":"Mehmet Zeki Akdağ","poet_slug":"mehmet-zeki-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/varmi-idi-boylesi-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus Reis', 'yunus-reis-suleyman-saylan-wlark', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YUNUS  REİS

Kurmuşlar şirin bir teknede, 

Salaş mı salaş bir meyhane.

Kemanın akordu bozuk telinde

Yüreğim seninle, sen yad ellerde.

Tekne sallanır haa.. Sallanır, 

Her kadehte başım döner, dumanlanır.

Gönlüm hasret şarkısına yaslanır...

Yüreğim seninle, sen yad ellerde.

Bu gece bitmesin, sabah olmasın, 

Doldur kadehleri hiç boşalmasın, 

“Yunus Reis” sevdamı unutmasın...

Yüreğim seninle, sen yad ellerde.

Doyumsuz geceydi, zevkle yaşadım; 

Bilmem ki gerçek mi, rüyada mıydım? 

Ömrüm böyle geçecekse, ben varım...

Yüreğim seninle, sen yad ellerde.

Süleyman SAYLAN

İzmir (Kordon’daki Yunus Reis teknesi restoranı) 

24.10.2001, Saat: 21.45', 'YUNUS  REİS Kurmuşlar şirin bir teknede,  Salaş mı salaş bir meyhane. Kemanın akordu bozuk telinde Yüreğim seninle, sen yad ellerde. Tekne s...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yunus-reis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-suleyman-saylan-gs2al', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YENİDEN

Denizlerde yıkadık duygularımızı; 

Pisliklerden, kötülüklerden arındı, 

Aklandı, temizlendi, 

Boyutlanıp evrenselleşti sandık...

Oysa; 

Tuzlara bulandı, 

Paslandı.

Yel esti savrulduk delicesine, 

Yaz geldi kavrulduk acımasızca.

İlkbaharlarda yeşerir gibi olduk

Derken; 

Sonbahara dayanamayıp

Çiçekler gibi solduk, 

Yaprak, yaprak döküldük...

Düşlerimizden daha sağlam çıktı

Kabukları istiridyelerin...

Ya sevgimiz bizi tüketti, 

Ya da biz sevgimizi.

Denedik özverilerle

Sevgisiz sürdürmeyi yaşamı; 

Ahtapotun iki ayrı kolu gibi...

Birimiz kuzey rüzgarlarına kapıldı, 

Çekip gitti Kuzey Kutbu’na, 

Üşümeden...

Üşenmeden...

Diğerimiz pusulasız kaldı; 

Varamadı Güney Kutbu’na...

Ölümün temizliğe çıktığı gün anladık ki; 

Sevgisiz olmuyor, 

Sevgisiz ölünmüyor bile...

Biz ölmeyi bir kuytuda bırakalım; 

Umutla beklesin az daha, 

Pusuda sinsice...

Ama; 

Umutsuzca olsa bile

Sevmeyi deneyelim biz

Baştan, 

Yeniden...

Süleyman SAYLAN

Ankara,08.12.1994, Saat: 00.15', 'YENİDEN Denizlerde yıkadık duygularımızı;  Pisliklerden, kötülüklerden arındı,  Aklandı, temizlendi,  Boyutlanıp evrenselleşti sandık... Oys...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yeniden-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi ay doğuyor yeraltı kadırgalarının serencamında', 'hangi-ay-doguyor-yeralti-kadirgalarinin-serencaminda-esra-aslan-niotv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi ay doğuyor yeraltı kadırgalarının serencamında

ki sencelerdedir taç yapraklı o suretin dövgüsü.

Umutsuz döşeklerimizde

Dimaşk''ın halifeleri ne onulmaz altın ateşlerin

ne de gri zeminin der:

Vaktiyle safran kopyalarının

her bir cildinde pıhtılaşan siyaha, 

su düşer düşmez yangın cevheri 

parıldadığı zahiridir.', 'Hangi ay doğuyor yeraltı kadırgalarının serencamında ki sencelerdedir taç yapraklı o suretin dövgüsü. Umutsuz döşeklerimizde Dimaşk''ın halif...', ARRAY['Türk Edebiyatı','Şiir','Esra Aslan']::text[], 8.5, '{"poet":"Esra Aslan","poet_slug":"esra-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hangi-ay-doguyor-yeralti-kadirgalarinin-serencaminda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğuna Uyanmak', 'yokluguna-uyanmak-cahit-i-pekoglu-bee6l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uyuyamıyorum bu gece

gidişine ihanetmi.

Yokluğuna alışmakmı

korkutan beni bilemiyorum.

Bilemiyorum, bilemiyorum

zerre kadar uyku yok gözlerimde uyuyamıyorum....

Huzursuz

yüreğimi hiç avutamıyorum.

Anladım inan bana

anlattığın kadar seni.

Yüreğimiz 

yannız etten değilimiş.

Bir demir yürekmi sevdim

yoksa anlayamıyorum.

İçinde hapsolmuş uykusuz geceler geçirmek için anlayamıyorum....

Yüreğime olduğu gibi

gözlerimede söz geçmiyor bu gece.

Kandıramıyorum onları

can içim kandıramıyorum.

Tek bildiğim

yarına uyanmak istemiyorum.

Bu yüzdendirki

bu gece uyuyamıyorum, uyuyamıyorum.....', 'Uyuyamıyorum bu gece gidişine ihanetmi. Yokluğuna alışmakmı korkutan beni bilemiyorum. Bilemiyorum, bilemiyorum zerre kadar uyku yok gözleri...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yokluguna-uyanmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimde Kaybolmuştun', 'gozlerimde-kaybolmustun-muammer-celik-6v7bp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sadece bir kac dize 

sadece bir kac dize 

şiir gönder demiştin

bende sana bir araba dolusu

şiir göndermiştim hatırlıyormusun

gönlümü, yüreğimi, benliğimi

açmıştım kainat halısından daha açık…

Sev beni

sadece sev beni demiştin

bende dünya dolusu

sevgi vermiştim

içimi, dışımı, kalbimi

tüm dünyamı açmıştım hatırlıyormusun

bütünlüğümü sermiştim sele serpe…

Hatırlıyormusun; 

sen bir adım geldikçe

ben daha çok yaklaşıyordum

yollar kat ediyordum senin için

sen bir elini vermeye çekiniyordun

ben geldikçe sen uzaklaşıyordun

mesafeler, engeller koyuyordun çin setti gibi…

Sadece bak

sadece gözlerime bak demiştin

bende senin içindeki mahpusa bakmıştım

onun güzelliğini, sığ bakireliğini

onun muhteşemliğini görmüştüm gözlerinde

ben baktıkça, ben gördükçe

sen bakışlarını kaçırmıştın, hatırlıyormusun…

Hatırlıyormusun; 

sen gel deyince

ben sel olup akmıştım

su olup coşmuştum

kalp olup atmıştım

yürek olup çırpınmıştım

kanat takıp uçmuştum sana…

Sadece al

sadece al götür beni demiştin

bende seni kaf dağının ardına

Fizan şehrinin sarayına götürmüştüm

başıma taç, gönlüme sultan etmiştim

ben seni soydukça

sen daha fazla giyinmiştin hatırlıyormusun…

Hatırlıyormusun

sen, Tek kelime ile, 

gözlerimde kaybolmuştun da

ben senin için ölmüştüm

ve yeniden senin için dirilmiştim…

15.04.2003

BirDeli', 'Sadece bir kac dize  sadece bir kac dize  şiir gönder demiştin bende sana bir araba dolusu şiir göndermiştim hatırlıyormusun gönlümü, yüreği...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/gozlerimde-kaybolmustun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-fatime-gokcen-usjtq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yoksun artık...

yoksun yanımda, hayatımda, yazdıklarımda....                     

gittin..

yalnız bir bedevi gibi kalakaldım yürek çöllerimde..

soluk soluk canlanan birde acı gözlerimde...

gittin...

silkeledim bütün benliğimi, temize çektim yüreğimi..sevdamı..

bir eylül rüzgarı geçti kapımdan, alıp götürdü senden kalanları...

korkar oldum sözcüklerden..

adının geçtiği cümlelerden..

sustu..sustu sözlerim, sustu fikirlerim..yoruldu yüreğim....

gittin..üşüdü hazan sarısı güller..

üşüdü serçenin kalbi..üşüdü ellerim...

gittin..

üşüdü serçenin kalbi...', 'yoksun artık... yoksun yanımda, hayatımda, yazdıklarımda....                      gittin.. yalnız bir bedevi gibi kalakaldım yürek çöllerimd...', ARRAY['Türk Edebiyatı','Şiir','Fatime Gökçen']::text[], 8.5, '{"poet":"Fatime Gökçen","poet_slug":"fatime-gokcen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yoksun-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul''a hasret', 'istanbul-a-hasret-fatime-gokcen-bkpyo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yüreğim göçtü yurdundan, yanaştı istanbul kıyılarına..

Bir gül düştü avucumdan, pervane oldu narına..

YAR! 

adını hasret koydum, destursuz daldın bağrıma..

sevdam bir elçi oldu, vuslatı yazdım fermanına..

renkleri soldu baharın, aşkın resmi yarım kaldı..

kara sevda da neymiş hey! gönlüm kızıla boyandı..

ISTANBUL dondu bakışlarımda, seyredurdum mehtabı..

yorgun düştü bu gönül, eylül...

eylül kapıya dayandı...', 'yüreğim göçtü yurdundan, yanaştı istanbul kıyılarına.. Bir gül düştü avucumdan, pervane oldu narına.. YAR!  adını hasret koydum, destursuz d...', ARRAY['Türk Edebiyatı','Şiir','Fatime Gökçen']::text[], 8.5, '{"poet":"Fatime Gökçen","poet_slug":"fatime-gokcen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istanbul-a-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Dersin', 'ne-dersin-cahit-i-pekoglu-v8dp7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşünki

soğuk bir kış günü.

Ellerim üşümüş

yüreğim buz gibi.

Düşünki

ateş düşmüş yüreğime.

Alev, alev

kor, kor yanıyormuş mesala....

Düşünki

Buz tutmuşken heryerler

yüreğim volkan imiş.

Olmaz dme sakın

yannızca hayal et.

Hayal et ve bekle....

Düşünki

Ilık bir bahar sabahı.

Yüreğinde, ellerinde

sımsıcak, aşktan yanan alev gibi.

Düşünki

yollara düşmüşsün.

Güzel bir düş görmüşsün

sonu yokmuş....

Kime ne

olsun varsın kime ne.

Yannızca hayal et

hayal et ve bekle.

Gecenin güzel yüzünü

hayal et sabaha dek bekle.

NE DERSİN.....', 'Düşünki soğuk bir kış günü. Ellerim üşümüş yüreğim buz gibi. Düşünki ateş düşmüş yüreğime. Alev, alev kor, kor yanıyormuş mesala.... Düşünki...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ne-dersin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmıştım ki Ben', 'sanmistim-ki-ben-ayse-mattaogullari-ktjd1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sanmıştım ki ben

hayat bahar olacak

niye düşünmez ki ser

sonra hazan gelecek.

sanmıştım ki ben

gül hep gonca duracak

neden düşünmez ki ser

oda birgün solacak.

sanmıştım ki ben

bitmez bir yoldur sevda

neden düşünmez ki ser

oda düşürür derde. 

sanmıştım ki ben

bütün insanlar mutlu

birde baktım ey dostlar

yüzde doksanı dertli.

sanmıştım ki ben

insanlar hep gülecek

niye düşünmez ki ser

herkes birgün ölecek.

hazana kadar baharı yaşamayı, 

solana kadar gülü koklamayı, 

derde kadar sevgiyi yaşatmayı, 

ölene kadar gülmeyi, 

hayatımızdan eksik etmesin.', 'sanmıştım ki ben hayat bahar olacak niye düşünmez ki ser sonra hazan gelecek. sanmıştım ki ben gül hep gonca duracak neden düşünmez ki ser o...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Mattaoğulları']::text[], 8.5, '{"poet":"Ayşe Mattaoğulları","poet_slug":"ayse-mattaogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sanmistim-ki-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorsan', 'bilmiyorsan-ayse-mattaogullari-kv2l1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmiyorsan sevmesini

Konmayasın gül dalına

Meylin yoksa öğrenmeye

Varmayasın yar yanına.', 'Bilmiyorsan sevmesini Konmayasın gül dalına Meylin yoksa öğrenmeye Varmayasın yar yanına....', ARRAY['Türk Edebiyatı','Şiir','Ayşe Mattaoğulları']::text[], 8.5, '{"poet":"Ayşe Mattaoğulları","poet_slug":"ayse-mattaogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bilmiyorsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelkenimi Doldursana', 'yelkenimi-doldursana-suleyman-saylan-smjyj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YELKENİMİ  DOLDURSANA

Denizinde yelkenliyim, 

Yelkenlerim çoktan fora...

Rüzgarımdır aşkın benim, 

Yelkenimi doldursana.

Fırtınayla gelme bana; 

Pamuk gibi kucağına

Uzanayım doya, doya...

Yelkenimi doldursana.

Nazlanırsan üzülürüm, 

Yel estikçe ben yürürüm, 

Dalgalarla süzülürüm...

Yelkenimi doldursana.

Sevgim sonsuz, derya kadar...

Seni seven bir kalbim var, 

Yüzdür beni diyar, diyar. 

Yelkenimi doldursana.

Hırçın esip batırma ha! 

Dayanamam karanlığa...

Okşa beni rüzgarınla.

Yelkenimi doldursana.

Süleyman SAYLAN

Ankara,15.11.1995, Saat: 18.40    (Şarkı sözü olabilir.)', 'YELKENİMİ  DOLDURSANA Denizinde yelkenliyim,  Yelkenlerim çoktan fora... Rüzgarımdır aşkın benim,  Yelkenimi doldursana. Fırtınayla gelme ba...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yelkenimi-doldursana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaş Kırk Oldu Koşa Koşa.', 'yas-kirk-oldu-kosa-kosa-suleyman-saylan-s05nr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YAŞ  KIRK  OLDU  KOŞA  KOŞA. 

Yaş kırk oldu koşa koşa, (Ömür bitti koşa, koşa,)  

Sevgi denen o yokuşa...

Çakır gözle, kara kaşa

Yandım allah! . Seviyorum, 

Seve, seve eriyorum.

Bir boyu var, sanki selvi, 

Aklım’aldı sineleri, 

Yanağında bir de beni...

Yandım allah! . Seviyorum, 

Seve, seve eriyorum.

Dudakları ateş rengi, 

Sırma saçlı peri sanki...

Sarhoş etti aşkı beni.

Yandım allah! . Seviyorum, 

Seve, seve eriyorum.

Süleyman SAYLAN

Ankara,07.08.1990,  Saat: 01.35   TSM olarak bestelendi:', 'YAŞ  KIRK  OLDU  KOŞA  KOŞA.  Yaş kırk oldu koşa koşa, (Ömür bitti koşa, koşa,)   Sevgi denen o yokuşa... Çakır gözle, kara kaşa Yandım alla...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yas-kirk-oldu-kosa-kosa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesinde Nar Çiçeği Gizli', 'sesinde-nar-cicegi-gizli-goktu-kara-xppzw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ağaçlarında eylülü saklar

nar ağaçları sesiz sedasız

bilmez ki insan derinliğini ölümün

döker gözyaşlarını sessiz sedasız

yine toprak ölgünleşmekte yaşama

yine mavi bırakır yerine sarıyı

yine sesler karışmakta hüzne

ağustos böcekleri sessiz sedasız

gece bulutlara bakarsanız bir bir

dem içine siner insanın

umutsuzluk eylülde can sıkıcıdır

nice  sevgiler bitti sessiz sedasız

seni buldum seni, seni sevdim bu ayda

şarkından tanıdım seni

sesinde nar çiçeği gizli

bak tutuldu sana yüreğim sessiz sedasız', 'ağaçlarında eylülü saklar nar ağaçları sesiz sedasız bilmez ki insan derinliğini ölümün döker gözyaşlarını sessiz sedasız yine toprak ölgünl...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sesinde-nar-cicegi-gizli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam Yetmişbeş Yıl Oldu', 'tam-yetmisbes-yil-oldu-suleyman-saylan-mw7jh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'TAM  YETMİŞBEŞ  YIL  OLDU

Kök salınca özgürlük Türklüğün doğasında; 

Hiç solmadı, güçlendi, çiçek açtı, gül oldu.

Kuruldu cumhuriyet Kurtuluş Savaşı’yla, 

Yıkılamaz bir daha, tam yetmişbeş yıl oldu.

Atatürk’ten güç aldık, baş koyduk biz uğruna, 

Bize karşı duranlar uğradılar bozguna.

Adım, adım güçlendik çağdaş olmak yolunda, 

Demokratız, laikiz, tam yetmişbeş yıl oldu.

Ddostumuzla düşmanı öğrendik teker, teker, 

Dışarda yabancılar, içerde örümcekler...

Evrensel barış için verdiğimiz ders yeter, 

Ortaçağı terkettik, tam yetmişbeş yıl oldu.) 

Kimi topla tüfekle saldırdı kardeşine, 

Kimi dıştan destekle küfretti milletine; 

Herkes aldı dersini, itler güldü leşine...

Yıkılmaz birliğimiz tam yetmişbeş yıl oldu.

Kulaklara küpedir Atatürk’ün gençleri, 

Boğacaktır her zaman bağnaz düşünceleri, 

Karanlık emellere geçit vermez türk eri, 

Ordumuzla el ele tam yetmişbeş yıl oldu.

Anlayana ses verdik bölünmez gücümüzle, 

Toprağımız bütündür, verilmez karış bile.

Gafillerin uğraşı, hainliği nafile; 

Atatürk’le özleştik, tam yetmişbeş yıl oldu.

Süleyman SAYLAN

Ankara,13.05.1998, Saat: 23.45    (Marş sözü olabilir.)', 'TAM  YETMİŞBEŞ  YIL  OLDU Kök salınca özgürlük Türklüğün doğasında;  Hiç solmadı, güçlendi, çiçek açtı, gül oldu. Kuruldu cumhuriyet Kurtulu...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tam-yetmisbes-yil-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınar', 'cinar-alptekin-biber-t3yxy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlk toprağa düştüğünde, 

Minnacık bir tohumdu sadece.

Sarınca 

	bedenini sıcacık toprak

Derince

	bir uykuya daldı hemencek.

...

Mevsimler sonra toprak

Uyandırdı onu okşayarak; 

“Vaktidir kalkmanın, 

Doğrulup güne çıkmanın”

Tabiki hiç kolay değildi

Doğrulupta sıcak yatağından

Hayatla burun buruna gelmek.

Ama sen mecbursun

Yeniden doğmalısın dünyaya, 

Veripte ana emeğinin hakkını

Açmalısın yaprak yaprak yarına.

Bu toprağın içinde başlayan ilk mücadele

Daha neler neler var geride

Bu bir başlangıç, dur hele

Sen bugün; 

	toprağın yarına sakladığı umutsun

 Büyü ve yarın kendi umutlarını bekle.

...

Ve tohum

İlkbaharın ilk sancılarıyla

Yeşilinde çiğ tanesi; merhaba dedi dünyaya.

İlk gün, çok güzeldi, 

Güneşin tadına vardı doya doya

İkinci gün, tam korkularını atarken dışarıya

Bir keçi tırnağı söküp götürüyordu onu azdaha

Dur! 

Geri dönmeye çalışma, 

Direnmelisin önce

Hemen pes etme hayata

Toprak seni koruyacaktır, 

Unutma, 

Kökün hala toprakta! 

Nekadar yukarıdaysan

O kadarda kök salmalısın ona

Emin ol o toprak ana 

Herşeyini verecektir içinde olana.

......

Zaman içinde, 

Kökün üstünde büyüyen bedeni

Hergün daha yüksekten bakarken toprağa

Gözleri aşina oldu ufka

Ama birgün yüzünü çeviripte toprağa

Dağlara tepeden bakmaya kalkınca

Ulu dağ sert bir rüzgarla

Yapıştırdı onu toprağa.

Yaptığı bu hata

Varlığını toprakta araması gerektiğini öğretti ona.

Ve daha bir sıkı sarıldı toprağa.

“Evet; 

Dağı aşan gönül olmalı, 

Yücelere engin düşen onur olmalı, 

Zora eğilmeyen gurur olmalı

Ve yalnızca, 

	umudu yeşerten ulu kalmalı.”

Unutmaki sen

Kendi umutlarını doğurmak için, 

Önce ananın umudunu, 

		yani kendini, 

			yani özünü yüceltmelisin...

...

Ve şimdi yeşeren umudun

Kökü yerde, 

	başı gökte alabildiğine özgür.

Ve artık dalından dökülenler

Kendi umudu olan tohumlar.

Umut meyvesini verdi

Selam sana ulu çınar! ...

			17 ARALIK 1991', 'İlk toprağa düştüğünde,  Minnacık bir tohumdu sadece. Sarınca  	bedenini sıcacık toprak Derince 	bir uykuya daldı hemencek. ... Mevsimler so...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/cinar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Getirdiği', 'gecenin-getirdigi-alptekin-biber-7nvoq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mehtabı mavi, 

	karanfilli bir gecedeyiz

Sevda yürek kakıyor

Çocuk sesiyle boğuluyor ezgisi

		mavi derinliğin

Bir tren geçiyor ansızın

	sessiz tıkırtılarıyla demir soğuğundan

Ve arkasından 

	bir gece doluyor kalan uğultudan.

Gecede köpek sesi

		uzak, yalın ve kinsiz

Ve bir garip adam; 

	sahil betonunda 	

	    yudumlarken buluntu şarabını; 

Denizin tuzlu enginliğini yaşamakta 

			damağında

Kimsesiz ve çaresiz.

Ve bir tiren daha geçiyor

		ritmik uğultularıyla

			esrarengiz bekaretimizden:

Deliyor geceyi

	içindeki binbir umutlu yürekle, 

Bir iş akşamının

	bezgin yorgunluğunu sürüyerek gerisinde.

Bir deli yıldız

dokunuveriyor birden

		herkesten sakladığın göz bebeğine

Ve bağırıyor delicesine

“Uzaklığın; 

	yüreğine olan uzaklığın kadardır bana

				vede umutlarına

Yakınlığın; 

yeşerttiğin yürekten içtiğin sevdadır kana kana

Ulaş bana-ulaş bana

Ulaş ve görki; 

Tren değildir, çucuk değildir, 

   bir kinsiz köpek, bir kimsesiz adam 

			değildir gece sadece

Ulaş ve görki baktığım yerden; 

Gecede yürek vardır ve tüm yaşayanlar adına çarpandır sessizce

Vede seni saran karanlık

	gecenin doğuracağı aydınlığa olan özlemidir sadece.

                                                                                     

 26 ARALIK 1993', 'Mehtabı mavi,  	karanfilli bir gecedeyiz Sevda yürek kakıyor Çocuk sesiyle boğuluyor ezgisi 		mavi derinliğin Bir tren geçiyor ansızın 	sess...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gecenin-getirdigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Bir Haller Var', 'bende-bir-haller-var-ensar-cevval-8gcv1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbul sokaklarında gezinirken

göreceğim son yağmur damlaları bunlar

her düşen, düştüğü yerde iz bırakıyor

ben buradayım dercesine..

gözlerime  düşen damlalar

kirpiklerimin arasında uyuyorken

gözbebeklerimden korkup yanaklarıma tutunuyorlar.

Tutmayın saçlarımda ıslak bedenlerinizi

ben bir sığıntı liman değilim

gözlerimden düşen kardeşlerinize sorun.

İstanbul sokaklarında gezinirken

göreceğim sonbahar günleri bunlar

her yaprak düştüğü yerde sararıyor

el tutmadan bitirilen sevdalar gibi

esme deli rüzgar bırak yansın yüreğim

ateşinden kız kulesi aydınlansın

donmuş balıkçı elleri ısınsın

ne bir yılan soktu sakındığım parmağı

ne kurt düştü yüreğime.. ateşleniyorum

bende bir hal var bu mevsimde; 

lakin tarif edemiyorum...', 'İstanbul sokaklarında gezinirken göreceğim son yağmur damlaları bunlar her düşen, düştüğü yerde iz bırakıyor ben buradayım dercesine.. gözle...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bende-bir-haller-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncesu''da bir ada', 'i-ncesu-da-bir-ada-mete-tugluk-h8hpv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uzayan kara gölgelerdir masanın altına

ve anlam yüklüdür mırıltılar sürekli

çay kokusu akar damarlara

mandal lamba kusar yere ve şüpheli

dinler mi

yayılan müziği

halının kitaplığın ve koltukların dinlediği gibi

kamufleci resimler sırıtır

sırtlarını lekelerine dayayıp duvarların

kalorifer suskun perdeler üşümektedir

doyumlar doyumsuzluktur burada

ağlatılar güldürü

kimi gerçekle içiçe

kimi çingene eşinin ardında yitik

kuş sesleri yayılır odaya

insanlar ayaklanır

çoğalır

ve sokaktaki deli

içerdekilerden titrek bir camla ayrılır...', 'uzayan kara gölgelerdir masanın altına ve anlam yüklüdür mırıltılar sürekli çay kokusu akar damarlara mandal lamba kusar yere ve şüpheli din...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/incesu-da-bir-ada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezsin', 'bilemezsin-aysegul-toker-y9qrj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasıl yanarım bilemezsin

Sen bunları göremezsin. 

Uzaklardan gelip

Göz yaşımı silemezsin.

Ne görür, ne de bilirsin

Ne hislerimi sezersin

Ne de bir telefon edip, 

Hasretliği silersin.

Ah nasıl da bilmezsin

Nasıl da öğrenmezsin. 

Cesaretim yok.

Daha fazlasını söyletemezsin.', 'Nasıl yanarım bilemezsin Sen bunları göremezsin.  Uzaklardan gelip Göz yaşımı silemezsin. Ne görür, ne de bilirsin Ne hislerimi sezersin Ne ...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilemezsin-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-aysegul-toker-1c37e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün gelir hayat biter

Perde iner

Söylenmemişler kalır geride.

Bir de yaşanmamışlar.

Olan olmuş derler

Biten biter, geçer gider

Bir ad kalır dilinde

Bir de unutulmayan anılar.

Belki bir gülüş çınlar kulaklarında.

Belki bir dokunuş canlanır hatırında.

Gözlerin dolar mı bilemem. 

Gelip onları silemem.

Bir gün gelir seni terk edersem 

Bu ölümle olur, sevgisizce değil. 

Bir gün olur aramazsam seni 

Bil ki ölmüşümdür. Unutmuş değil.', 'Bir gün gelir hayat biter Perde iner Söylenmemişler kalır geride. Bir de yaşanmamışlar. Olan olmuş derler Biten biter, geçer gider Bir ad ka...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gun-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-aysegul-toker-5jzyi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu dünyada güzel olan sevmek hissi. 

Karşılıksız seveceksin birisini.

Eğer o da sevebilirse seni

Doyumsuz olur sevgi. 

Dünyada her şey yalan; sevgiden başka.

İnsanoğlu hasrettir hep aşka.

Bir tatlı bakışa, gönülden gönüle akışa

Razıdır aşk odunda yanışa

Kimse bilmez mi sevginin değerini

Para satın almaz bir gram sevgiyi

Yaymak gerek dünyaya  sevme hissini

Öğrenmek gerek sevmeyi, sevilmeyi.', 'Bu dünyada güzel olan sevmek hissi.  Karşılıksız seveceksin birisini. Eğer o da sevebilirse seni Doyumsuz olur sevgi.  Dünyada her şey yalan...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgi-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Biz', 'ah-biz-aysegul-toker-a0ucj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah biz ne kötü ettik. 

Bir günü daha küskün bitirdik.

Ne söz söyledik, ne laf dinledik.

Oysa ne güzel bir ikiliydik.

Özürler fayda etmedi.

Sadece söyleneler boşa gitmedi.

Sevgi dolu arkadaşlığımız için.

Yaptıklarımız hep boşa gitti.

Ömürden bir günü yok ettik.

Kalan zamanı tükettik. 

Ah biz ne kötü ettik. 

Arkadaşlığımızdan bir gün yitirdik.

Ah biz ne güzel dost idik.

Gün oldu birbirimizi sevdik.

Gün geldi bir sözü esirgedik.

Şimdi bir günü daha yitirdik.

Ne geçti elimize bir kırık kalpten başka.

Oysa vermeli gönülde sevgiye, aşka.

Hani nasıldı o yaptığın şaka? 

Yalandı her şey demiştin bana.

Şakaydı değil mi sözlerin? 

Küskün bakamaz bana gözlerin.

Yalan olmazdı bizim aramızda.

Son olmazdı dostluklarda.

Ah bir günü daha yok ettik.

Bir günü daha dargın bitirdik.

Dostluğumuzdan bir gün yitirdik.

Ah biz ne kötü ettik.', 'Ah biz ne kötü ettik.  Bir günü daha küskün bitirdik. Ne söz söyledik, ne laf dinledik. Oysa ne güzel bir ikiliydik. Özürler fayda etmedi. S...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ah-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Olur', 'gun-olur-zeki-ergin-h0bn9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gün olur

çıkar galata kulesine 

seyredersin istanbul''u

gün olur

inersin karaköy''e 

seyreder istanbul seni

sahte gülüşler

sahte kahkahalar olmalıdır yüzünde

hakkın değildir

köydeki yavuklunu düşünmek

hakkın değildir 

arada bir hüzünlenmek

_erenköy  12eylül2003', 'gün olur çıkar galata kulesine  seyredersin istanbul''u gün olur inersin karaköy''e  seyreder istanbul seni sahte gülüşler sahte kahkahalar ol...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gun-olur-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Şok*', 'i-lk-sok-bayram-tunca-zynhs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah ne vakit göbek bağım koptu

Korkudan sanki de ödüm koptu

Bu hayatta gördüğüm ilk şoktu

Çünkü onun gibi bir huri yoktu

12.09.2003-12.09', 'Ah ne vakit göbek bağım koptu Korkudan sanki de ödüm koptu Bu hayatta gördüğüm ilk şoktu Çünkü onun gibi bir huri yoktu 12.09.2003-12.09...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ilk-sok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Yaşamak Yok! ...', 'yasamak-yok-naime-erlacin-yz85q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'teninde güller açan düşler ey

kanayan güze verdim sizi

içimde sancılar büyüdü 

kara bir delikte

gücünü günbatımından alan heves

süzüldü zamanın imbiğinden 

deştim yüreğimi

fışkıran şıvgınlar gördüm

kimliğim 

sürek avında acemi süvarilerin

dokunarak geçtiler yanımdan

yüzüme vurdu ağrılı rengi uyanışın 

ağırdı konuklar acılı düşüme

yolculuk ağır

günbatımı ağır

uyanış ağır

tutundum kalbime var gücümle

ve ne varsa yanında ışık saçan

aşktı beni sil baştan yaratan 

hayata dair her şey 

ölüme dâhil

aşk yoksa eğer 

(12 Eylül 2003)', 'teninde güller açan düşler ey kanayan güze verdim sizi içimde sancılar büyüdü  kara bir delikte gücünü günbatımından alan heves süzüldü zama...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasamak-yok-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Masum Belleme Gülüm', 'beni-masum-belleme-gulum-aydan-alim-6z77t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni masum belleme gülüm

Ben ne erkeğim, ne de  dişiyim

Merhamet tanımaz elimde kemendim

Acımadan geçiririm boynuna çile yolunda...

Beni masum belleme gülüm

Bakma bebeleri, sübyanları öptüğüme

Parçalarım sevdam önü duranları

Dişlerim sıcak bir ekmek niyetine...

Sesimi titrek duyup beni biçâr belleme gülüm

Haykırırım gerekirse  yumuşak  kulak memelerine

Sürerim kaval niyetine efkârlı sesimle 

Bütün aşk yorgunlarını azgın Murat nehrine...

Beni masum belleme gülüm

Himmet etme şu halime

Ruhum zalim, ruhum gaddar  bir dehak 

Zorbayım tanrının aşk şerbetini kana kana içmeyenlerine...

Elimde yediveren güllerini görüp

Beni asil bir soylu  belleme gülüm

Yolarım tüm yapraklarını

Açmazlarsa senin tapındığım  ellerinde...

Beni masum belleme gülüm

Ben masum değilim

Ama inan 

İnan yine de 

Yeni doğmuş bebek gözlerime...', 'Beni masum belleme gülüm Ben ne erkeğim, ne de  dişiyim Merhamet tanımaz elimde kemendim Acımadan geçiririm boynuna çile yolunda... Beni mas...', ARRAY['Türk Edebiyatı','Şiir','Aydan Alim']::text[], 8.5, '{"poet":"Aydan Alim","poet_slug":"aydan-alim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/beni-masum-belleme-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyarbekir Surları', 'diyarbekir-surlari-aydan-alim-wueck', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Surlar söyleyemez ki; 

Bu şehrin büyüklüğünü, 

Sen gel de

Hasretime sor.

Bir de kanayan yüreğime.

Kırağı yağmış umutlara nicedir

Çıkmaz sokaklar da bırakmaya çabaladığım özlemlerime...

Ve sormak isterim uzun zamandır, 

Cemre düşmüş müdür acep,

Beden dibine? 

Bıçak altına sürdüm fikirleri.

Şiirlerle dokunmak isterim omzunuza.

Can suyumu akıttım ben bu aşk yoluna

Bu yüzdendir size düşkünlüğüm, 

Bir de Diyarbekir’e.

Kayda değer bulunmadı mı 

Nezdinizde? 

Zor  geliyor, 

Restleşmek... 

Çok  zor  geliyor yüreğimle

Ölüm ne çare? 

Eşitler mi dersiniz bizi? 

Öte yanda 

Birbirimizle...', 'Surlar söyleyemez ki;  Bu şehrin büyüklüğünü,  Sen gel de Hasretime sor. Bir de kanayan yüreğime. Kırağı yağmış umutlara nicedir Çıkmaz soka...', ARRAY['Türk Edebiyatı','Şiir','Aydan Alim']::text[], 8.5, '{"poet":"Aydan Alim","poet_slug":"aydan-alim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/diyarbekir-surlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğun...', 'dogun-suleyman-saylan-ufiny', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DOĞUN...

Can atmayın sakın

Bu dünyaya doğmaya; 

Ekşimeye yüz tutmuş yoğurt gibi

Mayası bozuk bu dünyada

Bir bok yok.

Çirkefliklerle yoğrula yoğrula 

Çirkefleşmiş, 

Yüzsüz muhabbetler kurmuş, 

Onlarla düşüp kalkmaktan

Yüzsüz olmuş...

Dost görünenler bile

Dostluklarını unutmuş; 

Dıştan bakınca insan, 

İçlerine girince şeytan bunlar...

Orospularla dolu bu evren

Kadınıyla, erkeğiyle...

Doğmayın sakın bu evrene; 

Acırım sonra, üzülürüm size.

Yılanlarla yatmak, 

Baykuşlarla el ele vererek

Soytarılara tapmak zorunda kalabilirsiniz.

Tercih sırasında siz

Sonlara düşerseniz, 

Sokak köpeğinden beterdir geleceğiniz.

Yine de, 

Siz bilirsiniz...

                                            

Fakaaat; 

Babanızın suyundan, 

Ananızın huyundan miras alacaksanız; 

Çalacaksanız, çırpacaksanız, 

İyi bir sahtekar olacaksanız, 

Her gelenle yatacak, 

Boynuzlarınız uzasa bile, 

Sakal sıvazlayıp, cilalayacaksanız...

Bugünü var, yarını yok sayıp

Dalganıza bakacak, 

El pençe divan duracaksanız...

Giden ağanız, gelen paşanızsa; 

Makbul, muteber insan olursunuz.

Bu meziyetler varsa sizde, 

Ne beklersiniz daha

Ananızda, yerinizde? ...

Doğun orospu çocukları.

Süleyman SAYLAN

Ankara,19.07.2000, Saat: 00.50', 'DOĞUN... Can atmayın sakın Bu dünyaya doğmaya;  Ekşimeye yüz tutmuş yoğurt gibi Mayası bozuk bu dünyada Bir bok yok. Çirkefliklerle yoğrula ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/dogun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Deme Hiç...', 'elveda-deme-hic-suleyman-saylan-3vhyj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ELVEDA  DEME  HİÇ...

Elveda deme hiç, bir gün gidersen; 

Sakın geri dönüp bakma, istemem...

O solgun resmini isteme benden; 

Kalbime kazıdım, geri veremem.

Gözlerin gönlümde yanan bir ışık, 

Saçların kalbimi saran sarmaşık, 

Isıtır dudağın, aşkla karışık...

Kalbime kazıdım, geri veremem.

Seni hiç görmesem, çekip gitsen de, 

Benden başkasına gönül versen de, 

Üstelik ecele boyun eğsen de...

Kalbime kazıdım, geri veremem.

Süleyman SAYLAN

(Ankara,28.06.1993, Saat: 14.30)  Şarkı sözü olarak yazılmıştır.', 'ELVEDA  DEME  HİÇ... Elveda deme hiç, bir gün gidersen;  Sakın geri dönüp bakma, istemem... O solgun resmini isteme benden;  Kalbime kazıdım...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/elveda-deme-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feleğin Şaşar.', 'felegin-sasar-suleyman-saylan-86kz0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'FELEĞİN  ŞAŞAR.

Sevdanın çiçeği ansızın açar,                            

Evreni doldurur, yürekten taşar.                         

Vurgun yemiş gibi sendelersin hep;          

İnletir insanı, feleğin şaşar.                                

Limanlara sığmaz özgür denizde,                            

Savrulur rüzgarın hoyrat elinde,                          

Arzu denen sazın ince telinde                                   

Kaybolur gidersin, feleğin şaşar.                           

Aklını başından alır götürür,                                  

Ruhunu zindanda, yerlerde sürür.                          

Yıl olur geceler, seni öldürür...                             

Ağlamak nafile, feleğin şaşar.                                                         

Süleyman SAYLAN

(Ankara,10.05.2002, Saat: 00.47)   Şarkı sözü olabilir.', 'FELEĞİN  ŞAŞAR. Sevdanın çiçeği ansızın açar,                             Evreni doldurur, yürekten taşar.                          Vurgun y...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/felegin-sasar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bal Kız', 'bal-kiz-ozlem-torkul-tekan-dxowq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıranı savma, tendeki can gündeliktir.

Aydınlık meyiyle sarhoş ol, tazeliktir.

Yavana kanma, git hülyaları biriktir.

Sırrın gergefinde işlensin bal kız...

Arıya kızma, emeği şifada gizlidir.

Ruhsatını peteğinden al, inceliktir.

Çiçeği kırma, dalda evrenler yetişir.

Gönlünün dilinden damlasın bal kız...

(22 Ağustos 2002)', 'Sıranı savma, tendeki can gündeliktir. Aydınlık meyiyle sarhoş ol, tazeliktir. Yavana kanma, git hülyaları biriktir. Sırrın gergefinde işlen...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bal-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hükümlümsün', 'hukumlumsun-aydan-alim-zo3p4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünyanın bir ucu ben

Ve yanlızlığıma zaza zılgıtlarıyla halaya duran 

Sen...

Mavilerim kara

Mavilerim laciverde keserken

Uykularında ağlayan çocuklar gibi

Anılarda bıraktığım aşkıma ağlarım ben...

Aclarımın zanlısı

Dünyanın neresine götürürsen götür 

Kendini

İstediğin yere sakla

Bir kere hüküm giymiştir 

O taş yüreğin

Benim zorba aşkıma...', 'Dünyanın bir ucu ben Ve yanlızlığıma zaza zılgıtlarıyla halaya duran  Sen... Mavilerim kara Mavilerim laciverde keserken Uykularında ağlayan...', ARRAY['Türk Edebiyatı','Şiir','Aydan Alim']::text[], 8.5, '{"poet":"Aydan Alim","poet_slug":"aydan-alim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hukumlumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Ben..', 'bir-gun-ben-mehmet-cevik-hazerfen-bho5f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün olacak, ben

Bende mutlu olucam ben

Çocukluğumu bulacağım belki bir gün

Büyüyüp kök salınca dünyaya

Güllerimi takacağım işte o zaman, 

Sevdiğimin saçına.

Yüreğimi ıslatan yağmurları, 

Bir şemsiyeye hapsedip, 

Atacağım en derin mazgallara, 

Kuruyunca bedenim tamamen, 

Bırakacağım şiirleri, 

Yada bir bir soracağım, 

Hepsine nedenlerini...

Bir gün olacak, ben

Çıkacağım gökyüzüne, 

Ele güne bakacağım.

Bir kuş olup belki, 

Yarin penceresine konacağım.

Kendimi kurtaracağım o zaman, 

İçimi kemiren, 

Beni bir yere götüremeyen hislerimden.

Acılarıma soracağım, 

Nereden geldiklerini, 

Hıncımı duvarlardan alacağım, 

Öfkemi katıp rüzgarlara, 

Eseceğim Ankara’da ki tutsaklığıma...

Bir gün olacak, ben

Yaşadığım yerlerde, 

Dağ yolları, caddeler, sokaklarda, 

Vurulduğum neresi varsa, 

Açılıpta yüzüme kapanan kapılara, 

Başkalarının elinde meşale gibi yanan, 

Üzerine titrediğim hayatıma...

Lanet edip, 

Esip gideceğim, 

Bana fazla gelen şu zalim dünyaya...

20.01.2002

 Mehmet Çevik (Hazerfen)', 'Bir gün olacak, ben Bende mutlu olucam ben Çocukluğumu bulacağım belki bir gün Büyüyüp kök salınca dünyaya Güllerimi takacağım işte o zaman,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bir-gun-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Dışım...', 'i-cim-disim-mehmet-cevik-hazerfen-yvblt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğan görünümlü şahin gibiyim

İçim dışıma uymuyor

Ama

Her yere beraber gidiyoruz...

Yüreğim ayrı söyler

Yüzüm ayrı

Beni ele veren 

Belki gözlerimdir

Bunu anlayan

Bakmayı bilenlerdir...

07.07.2002

 Mehmet Çevik (Hazerfen)', 'Doğan görünümlü şahin gibiyim İçim dışıma uymuyor Ama Her yere beraber gidiyoruz... Yüreğim ayrı söyler Yüzüm ayrı Beni ele veren  Belki göz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icim-disim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Gözlerin', 'sensiz-gozlerin-mehmet-cevik-hazerfen-hikoa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin gelip geçiyor hayalimden

Bir gecenin zifiri karanlığında

Görmesin düşlerim bi daha seni

Yalanım varsa

Sevmiyorsam eğer.

Seni düşündükçe, 

Güller açıyor yüreğimde, 

Yüreğimdeki gülden kopan damlalar, 

Susuz topraklara

Irmak olup akıyor sesinle.

Şimdi, şu gece vaktinde, 

Uzansam, uyku girmez gözüme, 

Senden bir çağrı beklerken ben, 

Bilmem ki, 

Kim bilir nerelerdesin sen.

19.07.2003

 Mehmet Çevik (Hazerfen)', 'Gözlerin gelip geçiyor hayalimden Bir gecenin zifiri karanlığında Görmesin düşlerim bi daha seni Yalanım varsa Sevmiyorsam eğer. Seni düşünd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensiz-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakitsiz Zina', 'vakitsiz-zina-aydan-alim-1c0y3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çıkarım dersin bana

Zengibar kalesimi

Yoksa Alamut’mu 

Tırmandığın belli değil? 

Define arama dedim sana

Geleceği iğdişlenmiş

Bu zavallı insanlar arasında.

Saatlerin hedefi ölümdür, 

Zaman ayır ruhuna, 

Bazı bazı boşalsın

O da biraz soluk alsın.

Ölüm geliverir birden 

Vakitsiz bir zina gibi 

Baş ucuna

Sonra çok

Ama 

Pek çok 

Yanarsın...

Korkular ateşten gömlek

Giymek istemedim

Ayak diredim

Hayatım boyunca

Kurulu düzene inat.

Sen kendi korkularını

Mayın tarlalarında değil 

Teker teker

Kendi yüreğinde patlat...

Madem ki hayatımı dinamitledin

Katlet düşlerimi de

Rahat et! 

Bitsin gitsin

Dehasında yaşarsın belki sonra

O muhteşem

Fikirlerinin...



Geç kalmış sayılmazsın

Sızlanma

Kendini ağıtlarla 

Yerden yere hiç vurma

Rüzgarlara karıştım artık ben

Eserim kendi boşluğumda

Düşlerimin mağrur sultanı idin

Cellatlık yaparsın şimdi

Neden? 

Cevap ver neden? 

Kabuslarımda

Bir söğüt gölgesi ara

Kınalı bir keklik yerine 

Asabi dağlarda

Avlandık tarih boyunca

Avcılık bize göre bir iş değildi

Derim 

Ben yine  sana

Boşver artık benim derd-i derunumu

Ruhani mahlukatın

Bil cümlesinin malûmu

Sen sen ol

Kurmayı unutma artık cebindeki

Şimendifer marka

Saatin  paslanmış kolunu

 

Kör bir bataklık uzansa da  önümde

Ben artık şikayetçi değilim

Izdırabım yetişir imdadıma

Hiç bekletmeden

Kökleri sarmış her yanı çok önceden

Zehirli bir sarmaşıkcasına ezelden

Sen kendi yanlızlığına yan

Tülbentte sirke

Amerikan bezi dürülmüş

Yüklükte 

Ve gözlerin dikili kalır

Asla sahip olamayacağın

Eşkini kıvrak tayların peşinde', 'Çıkarım dersin bana Zengibar kalesimi Yoksa Alamut’mu  Tırmandığın belli değil?  Define arama dedim sana Geleceği iğdişlenmiş Bu zavallı ins...', ARRAY['Türk Edebiyatı','Şiir','Aydan Alim']::text[], 8.5, '{"poet":"Aydan Alim","poet_slug":"aydan-alim","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/vakitsiz-zina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zorlu Yürek', 'zorlu-yurek-aydan-alim-f7a2l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgarımsın dalga dalga

Kır saçlarımda

Söyle 

Nereye bu uzun yolculuk? 

Bu telaş niye? 

Korsan  yerinden kaçar gibi

Koca koca adımlarla 

Ve beyninde cevaplanmamış sorularla.

Ağaçlar fısıldar kulağıma

Gittiğin yeri 

Bırak bu fikirleri

Gitme! 

Henüz hazır değilim

Ebedi ayrılıklara.

Kokunu taşıyan rüzgar 

Merhemdir yaralarıma

Zemheri ayazı deymez

İçimin alev alev yangınına

Beynim yüreğime

Yüreğim beynime

Karşı dursa da memnu mıntıkalar da

Mayın döşerim

Pusu atarım yollarına

Gitme 

Gitme 

Gün vurmaz olur sensiz alanlara.

Zorlu yürek

Zorludur 

Diyarbekir surları gibi 

Amma

Gidersen 

Bilmem ki

Dayanır mı dersin? 

Bu vakitsiz ayrılığa.', 'Rüzgarımsın dalga dalga Kır saçlarımda Söyle  Nereye bu uzun yolculuk?  Bu telaş niye?  Korsan  yerinden kaçar gibi Koca koca adımlarla  Ve ...', ARRAY['Türk Edebiyatı','Şiir','Aydan Alim']::text[], 8.5, '{"poet":"Aydan Alim","poet_slug":"aydan-alim","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/zorlu-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyarbekir''de Tutsak', 'diyarbekir-de-tutsak-aydan-alim-3qxhb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yollama bakışlarını

İstemem.

Tutkuludur sinem... 

Bakarsan

Küllenir yangını

Dokunma! 

Kalsın içimde

Kalsın bu yangın.

Bu dağlarına 

Özlem....

Yollama bakışlarını

Her göz kırpış bir hain tuzak

Bir pusat 

Aşk lekeleri kımıldar üzerinden...

Öksüz ve yetim çocuk avuçlarında

Bir parça kurumuş tezek

Savururlarken umutlarına

Bana bakma öyle.

Her bakışın sinem de bir mızrak.

Gül yaprakları döker göklerim

Gülden

Gül yaprağından bir sağnak...

Oysaki dağ çeker 

Dağ tüter ayak

Bağlama adımlarımı

Gözlerinle...

Kelepçeler bana

Diyarbekir’de tutsak...', 'Yollama bakışlarını İstemem. Tutkuludur sinem...  Bakarsan Küllenir yangını Dokunma!  Kalsın içimde Kalsın bu yangın. Bu dağlarına  Özlem......', ARRAY['Türk Edebiyatı','Şiir','Aydan Alim']::text[], 8.5, '{"poet":"Aydan Alim","poet_slug":"aydan-alim","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/diyarbekir-de-tutsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece Eve Giderken', 'dun-gece-eve-giderken-bekir-mutlu-gokcesu-qodid', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gece eve giderken

Sapıverdim ışıklara gelmeden

Okulu kırar gibi hani	

Oturduk kendi kendimle

Bir yudum rakıdan

Bir parça peynir ve rokadan

Oh be dedim kendi kendime

İyi ki gelmişiz

Ne kadar da çok yorulmuşum

Neydi ki bu kadar zorum

Böyle kasım, kasım kasılmışım

Kaşları çatmış, çehreyi karartmışım

Bir yudum rakıdan 

Bir dilim kavundan

Attım ceketi sandalyeye

Çözdüm meret kravatı

Bir güzel de sıvadım kolları

Bir yudum rakıdan

Bir nefes cigaradan

Oh be dedim kendi kendime

İyi ki gelmişiz', 'Dün gece eve giderken Sapıverdim ışıklara gelmeden Okulu kırar gibi hani	 Oturduk kendi kendimle Bir yudum rakıdan Bir parça peynir ve rokad...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dun-gece-eve-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Kıran', 'gul-kiran-aydan-alim-0e7ep', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiirler hep gül üstüne.

Kan gülleri, 

Kızıl güller, 

Pembe güller, 

Ve bizim güller 

Diyarbekir’de yediverenler

Aşka dair, sevdaya dair, sevgiliye dair ne varsa

Gülle işlenmiş, 

Gülle bezenmiş, 

Gül gibi.

Ya gül kıranlar, 

Ya yediveren güllerini kıranlar.

Ama dünyamızda onlar da var

Onları neden anlatmaz şiirler?', 'Şiirler hep gül üstüne. Kan gülleri,  Kızıl güller,  Pembe güller,  Ve bizim güller  Diyarbekir’de yediverenler Aşka dair, sevdaya dair, sev...', ARRAY['Türk Edebiyatı','Şiir','Aydan Alim']::text[], 8.5, '{"poet":"Aydan Alim","poet_slug":"aydan-alim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gul-kiran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasa Dışıdır Sevgim', 'yasa-disidir-sevgim-aydan-alim-h1cxb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aranıyor ilanım sende

Geçmişin izleri bende kalsın

Gideceğim...

Ve küllenmiş artık bakışlarım

Acılarla yüklenmiş

Taşıyamaz olmuş granit yüreğim

Peşkeş çekilmiş bir gönül

Peşmurde olmuş bir ömür

Bir genç kız danteli gibi 

Sökülür

İlmek

İlmek

Kızmaca yok dostum

Çareleri tükettim

Korkuların benim kuşatılmış şehirlerim

Karanlık odalar da yüklüklere hapsettiğim

Cinnetim.

Cinayetim....

Sevda 

Bir derin uçurumdu benim için

Kalabalıklarda bulup

Tenhalarda yitirdiğim

Ve artık uçurumun dibindeyim

Giderim

Çünkü yasa dışıdır sevgim...', 'Aranıyor ilanım sende Geçmişin izleri bende kalsın Gideceğim... Ve küllenmiş artık bakışlarım Acılarla yüklenmiş Taşıyamaz olmuş granit yüre...', ARRAY['Türk Edebiyatı','Şiir','Aydan Alim']::text[], 8.5, '{"poet":"Aydan Alim","poet_slug":"aydan-alim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yasa-disidir-sevgim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmelisin', 'bilmelisin-osman-turkmen-ezwce', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana gülmeyi sen öğrettin, 

Unutmuş olmalıyım.

Sensiz gülmenin bir anlamı olmadığını.

Beni sen mutlu ettin, 

Unutmuş olmalısın, 

Bende bir sen kaldığını.

Bana bazı şeyi sen öğrettin, 

Biliyor olmalıyım, 

Sensiz her şeyin, hiçbir şey ettiğini, 

Şimdi beni terk ettin, 

Tahmin etmelisin, 

Bendeki senin bittiğini, 

Sana büyüttüğüm sevgimin, 

                           artık intihar ettiğini, 

Bilmelisin!', 'Bana gülmeyi sen öğrettin,  Unutmuş olmalıyım. Sensiz gülmenin bir anlamı olmadığını. Beni sen mutlu ettin,  Unutmuş olmalısın,  Bende bir s...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bilmelisin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Zamanlar (Yazı)', 'sensiz-zamanlar-yazi-i-brahim-tolga-ozsoy-3bl8e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç yaşanmamış sayıyorum sensiz geçirilmiş zamanları. Ölüyüm yokluğunda, varlığınla yaşıyorum. 

          Bu bekleyişin ardından sürüklenirken, umut rehberim oluyor, gözlerin güdülerimle oynuyor. Şakalaşıyorlar geleceğimiz üzerine. Seninle ilgili yaşanmamış ne varsa, senin manalarına katıyorum. Yaşanmışlar birer yol çizgisi, kaldırım taşı. Manalar T.C. Karayolları haritası. Kaset çalar''a bir kaset koyuyorum, yeni yıkanmış saç kokunu çalıyor. Yollar uzun, yollar acımasız, her bir adımım aşkımdan eksiliyor. Kavuşmaya binyıllar var, ömrüm yeter mi bilmiyorum. Yollar uzun, yollar aldatmaca, kıvrıla kıvrıla başka bedenlere çıkıyorlar. Soruyorum annem''e ''Anne daha çok kaldı mı? Gelmedik mi? ''. Cevaplıyor: ''Geldik evladım, geldik, gelmeni hiç istemediğim yerlere''.

          Dağları çiziyorum yollara, yeşil ovalara iniyor yollar. Yeşil gözlerinin üzerinde konaklıyorum. Kamp ateşi yakıyorum gözbebeklerinde. Aşk ateşi yakıyorum, kirpiklerinden çalı, çırpı toplayıp. Sonra kıvrılıp uyuyorum, fırtına öncesi kararmış bulutlar gibi üzerimi örten, saçlarının altında. Gözlerinin verdiği güvenceyle, ne bir haşere rahatsız ediyor beni, ne korkulu düşler. Ne gelecek, ne geçmiş... Ama uyanıncaya kadar tüm ömrü bu dumanlı ateşin.

          Uyandığımda hiç yoksun, terkediyorsun. Rüyalarımda gelip uyanınca giden bir peri kızı mısın? Yoksa deli beynimin yarattığı boş bir imge mi?  Korkuyorum bin yıllık bu öykü, birkaç bin yıl daha sürer mi? Uyanınca sönmüş olurmu bu ateş, bu maratona ömrüm yeter mi? 

          Hiç yaşanmamış sayıyorum sensiz geçirilmiş zamanları. Ölüyüm yokluğunda, varlığınla yaşıyorum.

          Sen açasın diye şakıyorum her sabah. Solduğunda kırılıyor kanadım, ölüyorum. Soğuklar bastırıyor her ölümle. Sanıyorlar soğuktandır ölümüm. Sen her halükarda yılda 7 kez açacaksın. Yılda 7 kez doğup,7 kez ölen bir serçeye armağansın. Soğuklar vergi memuru, her ölüşün ardından cenaze levazımatçısı. Aşkımın %7 sini tahsil ederler devlet adına. Sonra gelip gübre niyetine gömerler cesedimi toprağına. 

          Soğuklar geldi diye sanırlar ya ölüşüm. Ölüşüm yokluğundan, ölüşüm sessiz, cıvıltısız. Üzerimi örten toprak kolların, bana sarılan köklerin. Efsaneyi sürdürmek için her açışında, sanırsın cıvıldayan hep aynı serçe. Yok aslında birkez öldü, binkez öldü. Sen duyduğunu sandığın sese açarsın yapraklarını. Senden başkası duymaz, bilmez, bilemez. Açtığını görenler susar, sen beni dinlediklerini sanırsın. Kabullenme sen öldüğümü sakın. Cıvıltım yüreğinde kesildiği zaman esas ölümüm. Kabullenme tek sorumlusu olduğunu ölümümün. Utanma dikenlerinden, lekeleme efsaneyi.

          Hiç yaşanmamış sayıyorum sensiz geçirilmiş zamanları. Ölüyüm yokluğunda, varlığınla yaşıyorum.

          Senli zamanların hataları, çağırıyor sensiz zamanları peşinden. Seni hep affediyorum, beni edemiyorum. Yaptıkların safça, umarsızca, sorumsuzca. Ben ise planlı hatalarla kirletmişim tarihimizi. Ben bu yola devam ederken zamanla yoldaş, taşıdımın yakıdı sevgi olur. Her pompacıda durup adınla öderim, gelip sen doldurursun. Yol boyunca '' umut'' hikayeler anlatır bana sıkılmayayım diye. Gözlerin benimle oyun oynar ve birlikte şakalaşırlar geleceğimiz üzerine. Kasetçalar''a dokunuşlarını koyarım, teninin ezgilerini çalar. Yollar uzun, acımasız yollar. Hiç yaşanmamış sensiz yıllar.

          Ölüyüm yokluğunda, varlığınla yaşıyorum

          Sensiz geçirilmiş zamanları, hiç yaşanmamış sayıyorum...', 'Hiç yaşanmamış sayıyorum sensiz geçirilmiş zamanları. Ölüyüm yokluğunda, varlığınla yaşıyorum.            Bu bekleyişin ardından sürüklenirk...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tolga Özsoy']::text[], 8.5, '{"poet":"İbrahim Tolga Özsoy","poet_slug":"i-brahim-tolga-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensiz-zamanlar-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyoruz Tuğra', 'gidiyoruz-tugra-huseyin-ateskaan-ch7ju', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnanmak tek taşımak üç yaşamak ilahi

At sırtında omuzunda oku sırtıda son avladığından kürk

Bileğinde kalkanı kılıncında kan kurumamışki

Dünya sen iyi bilirsin onlar Türk

Topraktan gelmişi  toprağa vermişi

Dağların titriyor dünya kıyametine dek ürk

Yüzyıllar değişti Tuğra bende

Şereflice ölmek yalnız bende

Özgürlükten kurt bende

Semalardan hilal bende

Sonunda ey dünya sende

Son bulacaksın bizimle

İsteseydik oturmaya yer bulamazdınız

İpekten kefeniniz dağlardan makber denizlerce kanınız

Kurban olsun torunlarınız

Atalarım kutsalmış yinede siz oturmayınız

Bizlerde sevmeyiz biz heryerdeyiz koşunuz durmayınız', 'İnanmak tek taşımak üç yaşamak ilahi At sırtında omuzunda oku sırtıda son avladığından kürk Bileğinde kalkanı kılıncında kan kurumamışki Dün...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ateşkaan']::text[], 8.5, '{"poet":"Hüseyin Ateşkaan","poet_slug":"huseyin-ateskaan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gidiyoruz-tugra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler Yalan Söylemez', 'gozler-yalan-soylemez-salih-ozalasan-itdjh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözler yalan söylemez

Yüreğin aynası derler onlara

Tanrım yaratırken özenmiş

Her bedene vermiş, nurdan iki damla

Dilin kemiği yok, söylüyor aklına geleni

Seviyorum derse mutlusun, 

Hoşça kalsa saçma

Ruhumu sıkıyor aşk denen pranga

Gözler başka söylüyor dil başka

Bakamadım gözlerine, son bir kez

İhanetin okunuyor muydu onlar da

Belki de görmekten korktum

Bir başkasını bakışlarında

Kim bilir belki de ağladığımı

Görmeni istemedim, gururum oldu engel

Ruhum isyanlarda, yıkılmış hayallerim

Kalbim canımın içine oldu  bedel

Her sevdanın bir bedeli varmış

Benden de yüreğimi söküp aldı kader

Sevdalar yaşanırken her şey çok güzel

Yürekler otel değil ki

Her isteyene ver kalacak yer 

Belki bir gün, belki bir yıl, belki asırlar

Belki bir an sürecek sevmeler

Unutulmak zor ama, yapacak ne kaldı 

Bir başkasına ait artık o gözler

Her ateş sönermiş yandığı gibi

Geride kalıyor unutulmaz izler

İnsanız hata bizde hırs bizde

Öyle ki bizden utanıyor artık gözler

Gözler yalan söylemez

Gözlere bakamaz ediyor insanı sözler

Sevgiler yaşar kapansa da 

Seven yürekler, sevgiliye bakan gözler

Y.tarihi 11-09-2003

Salih Özalaşan', 'Gözler yalan söylemez Yüreğin aynası derler onlara Tanrım yaratırken özenmiş Her bedene vermiş, nurdan iki damla Dilin kemiği yok, söylüyor ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gozler-yalan-soylemez-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara 12''ler', 'kara-12-ler-vedat-koparan-fo5qd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sarı sıcak geldi 

Güneş değildi gelen 

Güneş değildi yakan 

Birer beşer onar yüzer 

Geçer sanıldı kimilerince 

Binlere varıldı 

Kıyımdı bunun adı göçtü 

Sürgündü süngü ucu 

Sürgün verdi 

Kendi ülkesinde 

Kara oniki’lerde 

Tele çekildi sevdamız 

Bir baştan bir başa 

İşkenceler, darağaçları azgınca 

Lime, lime parçalandı bedenler 

Yasaktı 

Süngü ucunda 

Özgürlük

Sıkı sıkıya geldi 

“Bir gece ansızın gelebilirim 

Uyumamışsan 

Kapında”(1)  kurşuna dizebilirim 

Uykuda 

Palada. Satırda, süngü ucunda 

Bebekler yetmişlik nineler 

Kör kuyularda 

''Namus bekçileri'' namusu kirlettiler 

Can kardeşlerimin bedenleri 

Maraş’ta, Malatya’da, Fatsa’da… 

Katliam 

İz sürüldü dağ taşta.. 

 “İsterse kimse görmesin 

Ateş böcekleri kendini 

Yıldız sanmaktan çekinmesin”(1) 

Bir dizi ''rasyonalizasyon'' tedbirleriyle

Kendi açmaz bunalımlarının kâr faturasını

Deli gömleği giydirilerek bu tarihi süreçte 

Hala yaşayan halklar var güzel ülkemde

“Bu gün kor anıdır yarın akkor zamanıdır..”(2)

Tarihe kara bir gündü düşen kan izinde

Aydınlık günler bu güne vurup gelende

Bitmedi… Vedat Koparan 11.09.2003

1-Öykünme(anımsayamadım özür dilerim) 

2-Sanat müziğine kazandırılan Ümit Yaşar Oğuzcan şiiri

3-Joze Marti (1853 – 1895)  Küba Ulusal Önderi', 'Sarı sıcak geldi  Güneş değildi gelen  Güneş değildi yakan  Birer beşer onar yüzer  Geçer sanıldı kimilerince  Binlere varıldı  Kıyımdı bunu...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kara-12-ler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizil Duygular Sapağı', 'gizil-duygular-sapagi-vedat-koparan-1ih0e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlah olsan benim için 

Hiç bir anlamın olmaz 

Seni bende duyup 

Tende yaşamadıktan sonra 

Düşmedik mi 

Birbirimizin uçurumlarına 

Ne anlamı olur ki 

Gezinmek keşfetmek var 

Her milim tende kaşif edası 

Venüslerin de içmek 

Sağmak geceyi 

Sabaha eren bembeyaz bir günde 

Dişlemek en hoyrat duyguları 

Kanatırcasına doruklarda 

“Aşk''ta organzma ulaşsak” 

Dalga kıran fırtınalarıyla 

Koyaklarında gezinmek 

Dalgaların her vuruşunda kıyılarına 

Gitmek fiyortlarına en gizil artçılarla 

Gürlemek şimşek hızında 

Engin bir denizsin

Deryalarda kulaçlarım hep sana 

Güneş ışığı gezinirken 

İç geçirişlerin, iniltilerin 

Teninde sürtünmenin verdiği hazla 

Bırak kendini sonsuzluğun gezintisine 

Dilimle, dilim dil uçlarında 

Beyninin titreşimlerinde 

En kıyılarında hassas noktalarında 

Çiğdem çiçeğim 

Ahularında koşturup teninde bittiğim 

Ahu nehirler akar dilberim 

İçeriz birbirimizi 

En gizil duygular sapağında 

Doyumsuz kanayan akşamlarda 

Yine yaktım, yine yattım gecede 

Harelerle güzel gözlerinde 

İlk gün doğumu sancılarında.. 

Vedat.K 11.09.2003.(11:19)  (2000 lere düşen iz düşümü zamansız mekansız hoyrat duygu kaçaklarından.)', 'İlah olsan benim için  Hiç bir anlamın olmaz  Seni bende duyup  Tende yaşamadıktan sonra  Düşmedik mi  Birbirimizin uçurumlarına  Ne anlamı ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gizil-duygular-sapagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurgun', 'vurgun-vedat-koparan-eyq8v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kavşaktı Ağustos dönencesi 

Bir mars gecesi yangın yeri kıpkızıl

Beklenen an, yakınlığa dönerken

Meğer uzaklaşmanın da habercisi

Kesişme noktasında kırılma..

Açmaya hazırdı sabah gülü 

Güzel yüzü gülüşünde

Solgundu ben günüm 

Kalmışken gözlerimin feri 

Yoksun mavi gecede 

Günün uyanan ilk ışıklarında

Sabah serinliğinde sahilde

Salmışım gözlerimi denize

Eylül’dü yaprak titremesinde 

Hazana düştü ilk üşüme 

Suda gidişini, gecede izini sürer

Bir adam şimdi..

Boşluğunda, bir göçmen kuştun

Bir daldı adeta yüreğim kondun 

Boşluğumu nasılda doldurdun

Göç yolları başladı yine

Gidişindesin yeni dallara

Kırdın güzel kuşum kırdın 

O dal şimdi yerde kurumada..

Gece nöbetleri bir başkadır

Özlemler ayaza vurur gecede

Bir yerlerde bir şeyler depreşir

Ağrısında, kanar sızlar 

Hani hiç yok mu güzel anılar

Gökyüzü kapkaranlık

Resmine bile bakamam

Gözlerime mil çekili 

Göremem mavileri ela hareler karalar  içinde

O kadar çoksun yoksun biliyorum 

Yokluğuna sarınıp giderken

Zaten beterim kuşatmalarda yüreğim

Deprem sonu  yıkıntılar arasında

Bir  şehir düşer 

Bir ben, birde bende sen 

Düşersin..! 

(Say Ki Tavla Oynadık Bir Mars/ta Bitti İşimiz..)

Vedat.K  09.0.2003 (08:3)   (2000 lere düşen iz düşümü zamansız mekansız hoyrat duygu kaçaklarından.)', 'Bir kavşaktı Ağustos dönencesi  Bir mars gecesi yangın yeri kıpkızıl Beklenen an, yakınlığa dönerken Meğer uzaklaşmanın da habercisi Kesişme...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/vurgun-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Sende Kaldı', 'yuregim-sende-kaldi-salih-ozalasan-yg61a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni unutamadım

Sende kaldı yüreğim

Yolumu bulamadım

Nerdeyim, nereye gidiyorum? 

Bir mıh saplanmış beynime

Çekiç benim elimde

Mıhsa senin elinde

Bende durmadan vuruyorum

Kanım akmıyor

Buz tutmuş bedenime

Göz bebeklerimde yaşlarım tomurcuk

Ağlamalıyım; ama ağlayamıyorum

Haykırmalıyım; isyanımı bastırmak için

Dilim tutulmuş konuşamıyorum

Gözlerim takılı kalmış

Uzaklarda sabit bir noktaya

Bakıyorum, sisten bir perde

Sisler arasında kayboluyorum

Yüreğim atıyor, sesini duyuyorum

Hafiften ritmi bozuk tik tak sesleri

Damarlarımda kanım akıyor

Ama ben; yaşamıyorum

Ruhum bedenimi terk etmiş gibiyim

Ellerim kaybetmiş dokunma yeteneğini

Dokunuyorum sana benzer gölgelere

Ama bir şey hissetmiyorum

Sudan çıkmış balık misali

Güneş altında, batağa saplanmış

Belli belirsiz damak atıyorum

Ölümle yaşam arası bir noktada

Oksijen yok sadece kuru bir hava

Şaşırıp kalmışım can çekişlerim boşuna

Yaşamaksa bu canlıyım

Can bedende ama ben yaşamıyorum

Kelimeler dil ucumda dizilmiş 

Kara tren misali katar, katar

Söylesem dil söylemez

Yazsam kalem kırık yazamıyorum

Bindiğim dalı kestim desem

Sanırım az gelecek

Ağacı kökünden kestim, inadına

Yenisini eksem, mümkün mü ekemiyorum

Söküp attım toprağıyla

Yüreğimi söküp attığım gibi

Her şey yerli yerinde

Eksik olan yüreğim

Yüreğim sende kaldı

Geri istesem isteyemiyorum

Yüreğim yok bedenim kaldı

Ben artık yaşamıyorum

Ben gidiyorum demiştim ya

Hoşça kal mutlu ol dostlarınla

Sen dostlarınla kaldın

Peki ben nereye gidiyorum

Denizdeysem hangi limana

Karadaysam hangi durağa

Sevdalıysam hangi sevgiliye

Yüreğim sende, kimseyi sevemiyorum

Yerde miyim gökte miyim

Canlı mıyım cansız mı

Hep vefadan dem vururdum

Yoksa ben vefasız mıyım

Hasretin çöktü kara bir bulut

Sorularsa fırtına sarsıyor bedenimi

Çakılıp kaldım bilinmez bir yerde

Yüreğim sende ver diyemiyorum

Gitmek mi zordu yoksa kalmak mı

Ben giden miydim yoksa kalan mı

Bu sevdayı yaşatmaya çalışan mı 

Yoksa bir hiç uğruna yıkan mı

Bilen varsa söylesin

Beklemesin ne olur yalvarmamı

Bildiğim tek şey bir sevgi

Kıskandıran Kerem’ i Ferhat’ı

Nasıl ki yağmurlar besliyorsa toprağı

Yağmurlar bitti, 

Kuruttum beden denen bu toprağı

Bu toprağa hayat veren yüreğim, sende kaldı

Y, Tarihi 12-09-2003 Saat 18-50

Salih Özalaşan', 'Seni unutamadım Sende kaldı yüreğim Yolumu bulamadım Nerdeyim, nereye gidiyorum?  Bir mıh saplanmış beynime Çekiç benim elimde Mıhsa senin e...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/yuregim-sende-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-vedat-koparan-fb5dm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyandığım her şafakta

Varsın yüreğim kanasın 

Sensizlik hep kapkara bir gece 

Ay büyüdükçe büyüsün 

Kaybolsun karanlıklar

Kan deryasında büyür umutlar

Çırılçıplak

Güneşe soyunmuş

Vurulmuş

Yalınayak gelsin gün 

Aşk  satırını vurdu

Kentin kalbine

Bir gece bir gece düştü 

Antik çağdan kalma 

Sonsuzlukta o gizli bakışta

Ruhlar sevişti, şiire düştü gece

Yasak elma böylece düşte yenildi

Geceden geriye kalan 

Sadece elma kabukları 

Ve karanfil  gülüşlerdi..

Vedat.K 12.09.2003 (2000 lere düşen iz düşümü zamansız mekansız hoyrat duygu kaçaklarından.)', 'Uyandığım her şafakta Varsın yüreğim kanasın  Sensizlik hep kapkara bir gece  Ay büyüdükçe büyüsün  Kaybolsun karanlıklar Kan deryasında büy...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dus-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-sair-mecit-ihu3h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Git artık, bekleme...

Soğuk bir öksürük takıldı kalbime

Soğuk ama yakıyor gözlerin kadar

Beni artık sadece sensizlik anlar..

Bekleme, git artık

Erimeden yüreğimdeki kar...

Ben de gideceğim ardından

Ayrılıkla randevum var...', 'Git artık, bekleme... Soğuk bir öksürük takıldı kalbime Soğuk ama yakıyor gözlerin kadar Beni artık sadece sensizlik anlar.. Bekleme, git ar...', ARRAY['Türk Edebiyatı','Şiir','Şair Mecit']::text[], 8.5, '{"poet":"Şair Mecit","poet_slug":"sair-mecit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/git-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleme', 'bekleme-kamil-bintas-b9hnv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat beni mutlu etsin diyorsan, 

Olduğundan fazlasını isteme.

Heybelerim meyve dolsun diyorsan, 

Ağaç dikmeden meyve bekleme....', 'Hayat beni mutlu etsin diyorsan,  Olduğundan fazlasını isteme. Heybelerim meyve dolsun diyorsan,  Ağaç dikmeden meyve bekleme.......', ARRAY['Türk Edebiyatı','Şiir','Kamil Bintaş']::text[], 8.5, '{"poet":"Kamil Bintaş","poet_slug":"kamil-bintas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bekleme-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-aysegul-toker-wnoay', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olmuyor.

Çok denedim ama olmuyor. 

Kimse senin gibi olmuyor. 

Senin yerin hiç dolmuyor.

Isıtmıyor. 

Kimse senin gibi ısıtmıyor.

O eller ve sözler..

Seninkiler gibi olmuyor.

Bakmıyor. 

Kimse öyle güzel bakmıyor. 

Gözleri benzemiyor.

Okşar gibi bakmıyor.

Çarpmıyor. 

Başka sevgilerle çarpmıyor.

Kalbim onlarla deli gibi atmıyor.

Seni gördüğümdeki gibi çarpmıyor.

Dolmuyor. 

Senin yerin dolmuyor. 

Kimsenin sevgisi 

Senin gibi yüce olmuyor. 

Sevilene….', 'Olmuyor. Çok denedim ama olmuyor.  Kimse senin gibi olmuyor.  Senin yerin hiç dolmuyor. Isıtmıyor.  Kimse senin gibi ısıtmıyor. O eller ve s...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olmuyor-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dön', 'geri-don-aysegul-toker-ak1tx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GERİ DÖN

Gittiğin yollara baka kalalı mevsimler geçti.

Rüzgarlar silip, geçti ayak izlerini. 

Ama ne zaman

Ne de mevsimler unutturabildi seni bana.

Kimseler yerini alamadı. 

İnsanlar halimi anlamadı. 

Artık sabır kalmadı. 

Baktığım yollardan dön geri.

Bekliyorum. Bekleyeceğim de..

Bir başkasının sen olmayacağını biliyorum.

Kimseleri sen gibi sevemiyorum. 

Bekliyorum.Döneceksin… Biliyorum.', 'GERİ DÖN Gittiğin yollara baka kalalı mevsimler geçti. Rüzgarlar silip, geçti ayak izlerini.  Ama ne zaman Ne de mevsimler unutturabildi sen...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/geri-don-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Olsam', 'ben-olsam-aysegul-toker-oekun', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah seni bir kollarıma bir alsam.

Alsam da uyutsam seni kucağımda.

Ah o güzel teni bir sarsam.

Sarsam da onu bir ben koklasam.

Sabahlara birlikte selam eylesek.

Bir yastığa baş koysak.

Baş koyunca yastığa, bakışsak.

Bakışarak, gülümsesek.

Bir yanımda olsan yar.

Sana neler sunmazdım. 

Bir kavuşsak senle yar.

Senin neyin olmazdım? 

Bir tutsam pamuk ellerinden.

Bir daha bırakmazdım seni

Bir görsem seni gerçekten.

Rüyalara uğurlamazdım geri.

Sarsam seni defalarca kollarımda.

Korusam geceleri kötü rüyalardan.

Bir çocuk gibi uyusan koynumda.

Gözlerime bakınca, sevdiğim olsan.

Gözlerine bakınca can evimden vurulsam.

Bir tek senin yanında mutlu olsam.

Sonsuza dek yanında kalsam.

Ah ne olurdu sen benim olsan..', 'Ah seni bir kollarıma bir alsam. Alsam da uyutsam seni kucağımda. Ah o güzel teni bir sarsam. Sarsam da onu bir ben koklasam. Sabahlara birl...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-olsam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yada', 'yada-senol-can-us2tr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ya biz geç kaldık hayata yada o çok erken çıktı karşımıza.

Ya bilemedik zamanın değerini yada o hissettiremedi bize değerli olduğunu.

Ya biz ifade edemedik duygularımızı zamanında yada onlar ifade edilmek istemediler, istedikleri halde.

Ya günler akıp geçti anlamsızlıklarla yada günler bir anlam aramadı kendilerine.

Ya biz kaçırdık başlangıçları yada onlar hiç gelmedi.

Ya biz mutlu olmayı seçmedik yada mutluluk bir seçenek değildi.

Ya anların değerini bilemedik yada anlar zaten değersizdi.

Ya günler ayları kovaladı yada aylar günleri içinde boğdu.

Ya dertlerimiz büyüktü yada biz onlara göre çok küçük.

Ya başarmak çok güçtü yada başarmayı istemek.

Şimdi önünde iki seçenek var:

Ya bundan sonrası için dört elle sarılmak hayata yada hiç bitmeyecek bu listeyi tamamlamaya çalışmak.', 'Ya biz geç kaldık hayata yada o çok erken çıktı karşımıza. Ya bilemedik zamanın değerini yada o hissettiremedi bize değerli olduğunu. Ya biz...', ARRAY['Türk Edebiyatı','Şiir','Şenol Can']::text[], 8.5, '{"poet":"Şenol Can","poet_slug":"senol-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yada-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyacım Var', 'i-htiyacim-var-aysegul-toker-hb5b2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden sustu güzel sözlerin? 

Hani bana sevdiğini söylerdin.

Mahrum bırakma beni sözlerinden.

Sözlerine ihtiyacım var.

Neden eskisi gibi bakmaz gözlerin? 

Oysa nasılda içimi eritirdin.

Mahrum bırakma beni gözlerinden.

Gözlerine ihtiyacım var.

Ya ellerimi tutmuş ellerin? 

Neden tutmaz ellerimi şimdi? 

Mahrum bırakma beni ellerinden.

Ellerine ihtiyacım var.

Aşkına ihtiyacım varken.

Sana böylesi muhtaç iken

Tek buluşma olan hayallerimizden

Ansızın çıkıp, gittin sen.', 'Neden sustu güzel sözlerin?  Hani bana sevdiğini söylerdin. Mahrum bırakma beni sözlerinden. Sözlerine ihtiyacım var. Neden eskisi gibi bakm...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ihtiyacim-var-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedi', 'gelmedi-aysegul-toker-ydnay', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saçıma dokunan ellerini tutabilseydim, 

Avuçlarında ellerini hapsedebilseydim.

Ama bana dokunuşun güzeldi. 

Ellerine tutmaya sıra gelmedi.

Güzel sözlerine yanıt veremedim.

Sana sevdiğimi söylemedim.

Sözlerinle büyülenmiş gibiydim.

Benim sözlerime zaman gelmedi.

Bakışlarında kenetlenemedi gözlerim.

Gözlerinin içine bakmayı beceremedim.

Bakışların ve gözlerin güzeldi. 

Utangaç gözlerime güven gelmedi.', 'Saçıma dokunan ellerini tutabilseydim,  Avuçlarında ellerini hapsedebilseydim. Ama bana dokunuşun güzeldi.  Ellerine tutmaya sıra gelmedi. G...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sevda şiiri', 'bir-sevda-siiri-fatime-gokcen-fevdg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hüzzam bir şarkıdır istanbul duduklarımda

nazlı bir yardır salınır rüyalarımın doruklarında

bir kordur tutamadığım bırakınca yandığım avuçlarımda

bir sevda bir sevda oluk oluk damarlarımda

uzaklarda yanıbaşımda demir bir fermandır beni sana çağıran

hicran

gül kokulu bir hicran gönlümü kasıp kavuran

yüreğimdir ey yar

yüreğimdir surlarının çatlaklarından limanına sıza

mabvi bir sevda benimki istanbul''un gözlerinde buğulanan.

istanbul

kızıl bir hançer yüreğime saplanan', 'hüzzam bir şarkıdır istanbul duduklarımda nazlı bir yardır salınır rüyalarımın doruklarında bir kordur tutamadığım bırakınca yandığım avuçla...', ARRAY['Türk Edebiyatı','Şiir','Fatime Gökçen']::text[], 8.5, '{"poet":"Fatime Gökçen","poet_slug":"fatime-gokcen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-sevda-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Mevsimi', 'hazan-mevsimi-aysegul-toker-96j0w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne güneş, ne de sevgi var 

İçimi ısıtacak.

Gökten düşen damlalar gibi

Yanağımdan yaşlar akacak.

Kalbim yağmurlarda ıslanacak. 

Bir omuz yok dayanacak. 

Gözlerim yaşla dolacak. 

Bir el yok yanağımı kurulayacak.

Mevsim ne olursa olsun.

Gönlüm hazan mevsiminde.

Rüyalar, hayaller tükenmiş.

Kimse kalmamış elimi tutacak.', 'Ne güneş, ne de sevgi var  İçimi ısıtacak. Gökten düşen damlalar gibi Yanağımdan yaşlar akacak. Kalbim yağmurlarda ıslanacak.  Bir omuz yok ...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hazan-mevsimi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-aysegul-toker-r7vbh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Varlığın kilometreler, 

Sıcaklığın aylar ötede kaldı.

Seni yad eller aldı da, 

Bana hasretin kaldı.

Oysa nasıl ihtiyacım var sana.

Sokulmaya kollarına, 

Bir kuş gibi sıcağına sığınmaya

Nasıl da hasretim sana.

Bir ses ver uzaklardan

Bir haber gönder o diyarlardan.

Ruhuma sevinç dolsun. 

Günlerimiz güzel olsun. 

Ah şimdi çok uzaktasın.

Sana ihtiyacım var. Duymaz mısın? 

Sevgimi veriyorum. Almaz mısın? 

Özledim diyorum. Koşmaz mısın? 

Seni öyle çok seviyorum ki.

Uğruna hasrete bile razıyım.

Sevgim öylesine büyük ki.

Onu sensiz de yaşarım. 

Ama sen varsan her şeye katlanırım.', 'Varlığın kilometreler,  Sıcaklığın aylar ötede kaldı. Seni yad eller aldı da,  Bana hasretin kaldı. Oysa nasıl ihtiyacım var sana. Sokulmaya...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hasret-123-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur Zaman', 'dur-zaman-aysegul-toker-3iifg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman ne olur geçme. 

Sesimi yükseltemiyorum ama lütfen beni duy.

Şu anda onun kollarındayım.

Ve bu anın bitmesini istemiyorum. 

Zaman ne olur duy sesimi ve dur.

Geçmesin dakikalar, bitmesin saatler. 

Mutluyum işte. Huzurluyum da. 

Ne olur dur zaman. 

Fısıltımı sana iletsin rüzgarlar. 

Bizi sarıp sarmalayan mutluluk havası ulaşır belki ona. 

Mesajımı iletmeli çalışkan zamana. 

Biraz durmalı o hiç dinlemeden akıp giden zaman. 

Şimdi durmalı o kısacık dakikalar ve saniyeler.

Kahpe zaman. Yine dinlemedi beni. 

Birlikte geçirdiğimiz zaman tükendi. 

Yine başladı işte özlem vakti. 

Oysa onunla olmak ne güzeldi. 

Ne yapacağım ben şimdi? 

Susuz kalmış çiçek gibi solacağım. 

Zaman beni sevdiğimden ayırdı işte. 

Onun ellerinden uzaklardayım yine. 

Geçme! Dur demiştim sana zaman.

Dinlemedin tek bir kelam. 

Yine sen olabilirsin derde derman. 

Sevdiğimi geri ver zaman.', 'Zaman ne olur geçme.  Sesimi yükseltemiyorum ama lütfen beni duy. Şu anda onun kollarındayım. Ve bu anın bitmesini istemiyorum.  Zaman ne ol...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dur-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susma', 'susma-aysegul-toker-4fq0t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne olur öyle suskun durma. 

Bir şeyler anlatsana bana. 

Öyle soru da sorma ama. 

Sadece kendini anlat bana. 

Bana sevgiyi anlat. 

Sonra aşkı  hatırlat.

Ne olur suskun durma.

Nedir şu fani hayat? 

Sevmeyecekse insan.

Sevilmeyecekse canan.

Ne iş yarar sevecek o can? 

Neden bedbaht olur aşık olan? 

Susma. Bana her şeyi söyle.

Susma.Sevdiğini söyle.

Hayatı, dünyayı, çiçekleri...

Haydi beni de sevdiğini söyle.

Susma. Sustukça uzuyor sessizlik.

Durma. Durdukça uzuyor sensizlik.

Susma. İçinde uyuyor yalnız bir kimlik.

Susma. Sustukça büyüyor sevgisizlik.

Sevgini söyle. Aşkını anlat. 

Haydi durma. Bak geçiyor hayat.

Susma. Sevdiğini söyle, anlat.

Sustukça soluyor bir hayat.', 'Ne olur öyle suskun durma.  Bir şeyler anlatsana bana.  Öyle soru da sorma ama.  Sadece kendini anlat bana.  Bana sevgiyi anlat.  Sonra aşkı...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/susma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Bilmeyecek', 'kimse-bilmeyecek-aysegul-toker-4o3q5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimse bilmeyecek 

Aramızda geçenleri

Kimse bilmeyecek 

Yaşadığımız hislerimi.

Ne sen konuşabileceksin bir iki söz.

Ne bende olacak iki damlı yaşlı göz.

Bitiverecek hepsi birden. 

O gün gelince aniden. 

Ne ben anlatacağım onlara. 

Ne sen bir şey diyeceksin bana.

Kimse bilmeyecek yaşadıklarımızı.

Kimse öğrenmeyecek hayallerimdeki aşkımızı.', 'Kimse bilmeyecek  Aramızda geçenleri Kimse bilmeyecek  Yaşadığımız hislerimi. Ne sen konuşabileceksin bir iki söz. Ne bende olacak iki damlı...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kimse-bilmeyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-aysegul-toker-uqixf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine yalnız uzandım yatağıma

Kışın mı yoksa yalnızlığın soğuğu mu bu? 

Bakmak istemiyorum etrafıma.

Düşünmekten kaçıyorum yalnız olduğumu.

Yeni bir güne yine yalnız başlamak.

Her sabah aynı duyguyu yaşamak.

Bir gün her şey değişecek demek.

Anlamsız mı böylesine umutlanmak? 

Her sabah aynı. Her gece aynı.

Hepsi sensiz ve hepsi sessiz.

Hep birbirimizden ayrı.

Sen bensiz.Ben sensiz.Kimsesiz.

Yanında bir sıcaklık duymak.

Sevdiğinle yan yana uyumak.

Hatta onun beline sarılmak.

Hayır. Sonuç hep aynı.Yalnız kalmak.', 'Yine yalnız uzandım yatağıma Kışın mı yoksa yalnızlığın soğuğu mu bu?  Bakmak istemiyorum etrafıma. Düşünmekten kaçıyorum yalnız olduğumu. Y...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizlik-123-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter', 'yeter-aysegul-toker-34fqx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok şey istemem senden

Seni kendimle paylaşmak yeter.

Uzaklarda çok kalmadan gel.

Bir dakika görsem seni yeter. 

Sadece elimi tut benim.

Sevgili gibi olmasa da dostça tut.

Bu bile yeter sevgimi yaşatmaya.

Arkadaş sözünü söyleme.Unut.

Ne sen sevgi sözleri söyle.Ne de ben.

Ben dinlerim sıradan sohbetini, sözlerini.

Bir şeyler söylememi isteme benden.

Olur ya. Söyleyiveririm. Açıklarım hislerimi.

Bir gün olsun benim için gel yeter.

Ne sevdiğini söyle. Ne acı ver. 

Bir gün olsun paylaştığımız.

Sonra sevgimle ayrılırım senden.

Yaşadıklarımız bana yeter. 

Varlığın çok şeye bedel.

Bir gün gibi gelir hayat biter.

Sessizce ayrılırım senden ve dünyadan.

O zaman bir duan bana yeter.

Uzaklıkları ve özlemleri siler.

Bir dua gönder.

İnan bu bana yeter.', 'Çok şey istemem senden Seni kendimle paylaşmak yeter. Uzaklarda çok kalmadan gel. Bir dakika görsem seni yeter.  Sadece elimi tut benim. Sev...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yeter-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Kaldım', 'sende-kaldim-bulent-gonul-nqbt9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gitsemde bir

Kalsamda bir

Senin için fark etmiyor ya

Benim için en büyük acı...

Küskün değil kırgınım

Depremden beter yıkıldım

Yapamıyorum sensiz

Aşığım, sende takılı kaldım...', 'Gitsemde bir Kalsamda bir Senin için fark etmiyor ya Benim için en büyük acı... Küskün değil kırgınım Depremden beter yıkıldım Yapamıyorum s...', ARRAY['Türk Edebiyatı','Şiir','Bülent Gönül']::text[], 8.5, '{"poet":"Bülent Gönül","poet_slug":"bulent-gonul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sende-kaldim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahmaran Ve Eftalya', 'sahmaran-ve-eftalya-hikmet-karakus-7bucd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şahmaran aşkına

                 deniz atları

                   köpüklü yeleleriyle

                     geçtiler sıra sıra, 

Ve uğurlandı

         karşı kıyıya

             deniz kızı Eftalya, 

Buluştular

        bandıran zehri tadında, 

Ne denizin

          ne de ölümsüzlüğün

                        sırrına erdiler, 

Sevdalarını gizlerle ördüler, 

Sevdalarına  gizlice öldüler...

                                             

(İst.1989)', 'Şahmaran aşkına                  deniz atları                    köpüklü yeleleriyle                      geçtiler sıra sıra,  Ve uğurlandı ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sahmaran-ve-eftalya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla yüreğim', 'agla-yuregim-yunus-ors-va8ni', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ağla yüregim ağla   onusevdigim için ağla  bilmiyorum dayanırmı  kalbimbu acıya unutabilirmiyim anıları birbaşkasını sevebilirmiyim birdaha bilmiyorum bilmiyorum umutların mutlulukların sevginin hayallerin bittigi dünya nefretin kinin ihanetin yalnızlıgın başladıgı dünya nereden bileceksinki hayatın bukadar acı oldugunu', 'ağla yüregim ağla   onusevdigim için ağla  bilmiyorum dayanırmı  kalbimbu acıya unutabilirmiyim anıları birbaşkasını sevebilirmiyim birdaha ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Örs']::text[], 8.5, '{"poet":"Yunus Örs","poet_slug":"yunus-ors","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/agla-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zoraki veda', 'zoraki-veda-hebil-akan-4fymt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ümit yitirdim, bir gönül öldü

Sevda yollarında dün akşam üstü

Beni kahreden şans, ellere güldü

Sevda yollarında dün akşam üstü.

Kulak asmadığın bir nida vardı

Gecede çınlayan bir seda vardı

Gözyaşıyla dolu bir veda vardı

Sevda yollarında dün akşam üstü

Gülleri dalından nasıl yolmuşlar

Dökülüp yerlere cansız solmuşlar

Islak bir mendil, bir gül bulmuşlar

Sevda yollarında dün akşam üstü

Damağım kurudu dur diye diye

Ne hale getirdin gör diye diye

Yalvardım Leyla’ya yar diye diye

Sevda yollarında dün akşam üstü

Bazen boyun büktüm, bazen hıçkırdım

Bazen nara attım, bazen haykırdım

Bilir misin ki sen kaç kadeh kırdım

Sevda yollarında dün akşam üstü

İlkbaharken birden güz kesti gönlün

Hasret kutup’undan buz kesti gönlün

Neden ayrılığa söz kesti gönlün

Sevda yollarında dün akşam üstü

…………………………………...

……………………………………

…………………………………...

……………………………………

kalp kırmayın demiş cenabı Huda

kırmadı mı şimdi bu haksız veda

bitti …biliyorum bir fani sevda

sevda yollarında dün akşam üstü

sırtımdan inince böyle fani yük

gördüm ki bastığım dal ince, çürük

anladım ki Mevla aşkı en büyük

sevda yollarında dün akşam üstü

günah döktüm..mutlu..mutlu ağladım

gönlümü başka LEYLA’YA  bağladım

sayende yüce Mevla’ya bağladım

sevda yollarında dün akşam üstü

1982 /Hacettepe', 'Bir ümit yitirdim, bir gönül öldü Sevda yollarında dün akşam üstü Beni kahreden şans, ellere güldü Sevda yollarında dün akşam üstü. Kulak as...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/zoraki-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-hebil-akan-x2ehv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Asla solmayacak güller gibisin

Bülbülde şakıyan diller gibisin

Yare doğru giden yollar gibisin

Sen olmazsan hasret bitmez yürekte

Hasretlik çekmek olsa da ceremem

Başka gül deremem çiçek deremem

Senden başkasına gönül veremem

Yaban çiçekleri bitmez yürekte

Uçan turnalara sorum sen oldun

Ateşim sen oldun korum sen oldun

Bu ateşi yakan yarim sen oldun

Senden başka sevda tütmez yürekte

Balgat/1994', 'Asla solmayacak güller gibisin Bülbülde şakıyan diller gibisin Yare doğru giden yollar gibisin Sen olmazsan hasret bitmez yürekte Hasretlik ...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/itiraf-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaretsizim', 'cesaretsizim-hebil-akan-py53p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Heyecanımı affet kor dudağından

Öpmeye cesaret bulamadıysam

Sana gelen yola Elmadağ’ından

Sapmaya cesaret bulamadıysam

Köle olmuşken candan aziz cana 

Nasıl düştüm bilmem ben bu hicrana

Affet... tanrıdan utanıp da sana 

Tapmaya cesaret bulamadıysam

Elmadağ/1996', 'Heyecanımı affet kor dudağından Öpmeye cesaret bulamadıysam Sana gelen yola Elmadağ’ından Sapmaya cesaret bulamadıysam Köle olmuşken candan ...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cesaretsizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslı Yolunda Kerem Meyli midir Aşk?', 'asli-yolunda-kerem-meyli-midir-ask-nuri-can-ixyce', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eftelya''ya

Koyup herşeyi bir yana

çekip ellerini hayatımdan

git 

artık ne kaybedecek

ne de konuşacak bir şeyimiz kaldı

bütün sözler tükendi... 

Gözlerini

ıstırabımı

hicranımı

seven yanımı

hayatımdan al git

sar git yüreğimdeki yarayı 

say ki, hiç yaşamadık bu aşkı

sevişmedik geceler boyu

varsın bütün şiirler, 

bütün şarkılar yarım kalsın

neyin varsa topla git 

Git 

mim koyup efkarıma

bir güvercin gibi

kanadımda taşırım ateşimi

bir mecnun gibi çölde de yaşarım

Leyla''ysa aşkım

yeterki, 

düştüğüm yerden

vurmasın sırtımdan hayat 

Zaten ben bu ihanet kokan dünyanın

bu yeryüzünün kara sevdalısıyım 

iflah olmam 

yüreğimi kimsesiz sevgilere bırak git

varsın tüm köşe başlarında yalnız kalayım

bütün elveda istasyonlarında ben ağlayayım

yüreğimdeki ağrıları al git

Alevler içinde tutuşan iksirler istiyorum artık

değilmi ki, 

her aynaya baktığımda

niftrit asit ter döküyorum bardak bardak

Git 

oklarını

duygu bahçemden topladıklarını

ve yüreğimden kopardıklarını bırak

koy bir yana sancılarımı

kelepçeni vur git hayatıma

ihanet prangaları vur git bu sevdaya

Bırak çözülsün dizlerimin bağı

hasret dilimin ucunda

suküt gibi naçar

susku gibi suküt kalsın 

Bırak beni hayat aşkın oklarıyla 

vursun vuracaksa

tam orta yerinden kalbimin

sevda bahçelerinde gül toplarken

kışları bana bırakıp 

alıp yanına tüm baharları

viran şehirler gibi gibi terkedip git beni. 

Git 

indir yükünü duygularımın

bir avuç ateş değil midir? aşk

gömülüp soluğuna hasretin

bırak yaksın kanatlarımı

varsın acıdan parça parça olsun yüreğim

açmasın bir daha hiç bir çiçek

bütün kuşlar terkedip gitsin bahçemi

al yanına tüm baharları

sonbaharda sarı bir yaprak gibi kalayım

Git 

mevsimlere yazarım adını, sonbaharlara

bulutlara yazarım, yağmurlara, yalnızlıklara

bir veda sözcüğü düşer gibi uçurumdan

rüzgarlara saklayıp adını giderim ben de

Aslı yolunda Kerem meyli değil midir AŞK?', 'Eftelya''ya Koyup herşeyi bir yana çekip ellerini hayatımdan git  artık ne kaybedecek ne de konuşacak bir şeyimiz kaldı bütün sözler tükendi....', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/asli-yolunda-kerem-meyli-midir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-hebil-akan-0rq96', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bahara hasret kaldı kış

Hüzün gergef nakış nakış

Düşerken tutanlar alkış 

Çelme takar felahıma

Uzatıp da ellerimi

Açtım pencerelerimi

Kıskanıp gecelerimi

Güneş doğmaz sabahıma

Terk edince baht yıldızı

Kesilir sevdanın hızı

Ta..derinlerden bir sızı

Koydular sol cenahıma

Gidin hülyalarım gidin

Benimmiş anladım bu din

Can dostlarım dua edin

Yöneleyim Allah’ıma', 'Bahara hasret kaldı kış Hüzün gergef nakış nakış Düşerken tutanlar alkış  Çelme takar felahıma Uzatıp da ellerimi Açtım pencerelerimi Kıskan...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dua-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanırım ben', 'utanirim-ben-hebil-akan-vdb1t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülden de nazenin o beyaz teni

Sunup sarhoş etmek istersin beni

Niyetlensem bile öpmeye seni

Titrer dudaklarım utanırım ben

Koru sensin sanki sigara yaksam

Gözlerim kamaşır yüzüne baksam 

Şiirlerle seni tarife kalksam

Titrer parmaklarım utanırım ben

Kara sevda koymuş gönlüme rahman

Yakar alev, alev aman be aman 

Seviyorum seni dediğin zaman 

Titrer yanaklarım utanırım ben

Göründü vuslata giden yol desen

Unut derdi gamı artık gül desen

Çağırsan yanına beni gel desen

Titrer ayaklarım utanırım ben

Balgat/1994', 'Gülden de nazenin o beyaz teni Sunup sarhoş etmek istersin beni Niyetlensem bile öpmeye seni Titrer dudaklarım utanırım ben Koru sensin sank...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/utanirim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-hebil-akan-89l7k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sırtına binmişin bir yeşil düzün

Bulutlara doğru dönmüşün yüzün

Ceylanı unutup bir güzel gözün

Menekşe rengine eğildin dağlar

Kerem’den mecnun’dan selam var sana

Hangi çeşmelerden su içer suna

Ferhat’a yol verdin vermedin bana 

Sen eskiden böyle değildin dağlar

Yaz kış taşıyorsun kardan hırkanı

Korktukça korkuttun senden korkanı

İçinde yanınca aşkın volkanı

Duman duman olup dağıldın dağlar', 'Sırtına binmişin bir yeşil düzün Bulutlara doğru dönmüşün yüzün Ceylanı unutup bir güzel gözün Menekşe rengine eğildin dağlar Kerem’den mecn...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/daglar-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Anladım', 'gec-anladim-hebil-akan-bd7ww', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir günahkar sevda koyup sineye

Çeker mi bu omuz yükü demedin

Ümit verdinde en geç seneye

Hasretlik ömrünce baki demedin

Alevden bir buse sunup verdinde

Sevda mubah dedin vardır her dinde

Her şey çift olurmuş öyle derdinde 

Gözyaşı sevdanın eki demedin

Benmişim çarmıhın sözde İsa’sı 

‘’hamdım, piştim, oldum’’sözün kısası

çile mektebinin varmış yasası

sende al, sende gör, oku demedin

23/01/1998

Elmadağ', 'Bir günahkar sevda koyup sineye Çeker mi bu omuz yükü demedin Ümit verdinde en geç seneye Hasretlik ömrünce baki demedin Alevden bir buse su...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gec-anladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Kırıklığı', 'hayal-kirikligi-mehmet-caner-sumengen-rrfw8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keşke ile başlayan pişmanlık cümlelerinden

Biriktirdiğim acı anılar aşklığımda, 

Adının büyük harflerle yazılı olduğu

O kapkara, bitmek bilmez sayfada

Bir hayal kırıklığımsın artık...', 'Keşke ile başlayan pişmanlık cümlelerinden Biriktirdiğim acı anılar aşklığımda,  Adının büyük harflerle yazılı olduğu O kapkara, bitmek bilm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hayal-kirikligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Sokağına Elveda', 'dusler-sokagina-elveda-vedat-koparan-8vv7w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uyandığım her şafakta

varsın yüreğim kanasın 

sensizlik hep kapkara 

bir gece 

ay büyüdükçe büyüsün 

kaybolsun karanlıklar 

benden öte

umutlar kan deryasında büyür 

sen umudunu yinede diri tut 

ağlamasın maviler

çırılçıplak

güneşe soyunmuş

vurulmuş

yalınayak gelsin gün

ben ölürken benden öte..

aşk  satırını vurdu

kentin kalbine

bir gece bir gece düştü 

asariatika dan kalma 

sonsuzlukta o gizli bakışta

ruhlar sevişti, şiire düştü gece

ve o gece 

düşle birlikte gerçekte yenildi

geceden geriye kalan 

sadece karanfil  gülüştü..

mutluydum düşler sokağında

bir bir bıraktım 

bir bir dağıttım

saçtım 

savurdum 

vuruldum

mutlulukları

şiirleri 

aşkı 

sizlere bıraktım

“şair 24 saattir der yürek ağrısı “

olmayanın bellidir izi iş’te

sayın ki karanlığın içinden

eşkıya bir kızıl yıldız düştü

bırakın kalmasın izim 

bir kalemde siz çekin

buda son seslenişim 

alır sizleri giderim 

hoşça kalın şiir dillerim

Vedat.K 13.09.2003(05:45)', 'uyandığım her şafakta varsın yüreğim kanasın  sensizlik hep kapkara  bir gece  ay büyüdükçe büyüsün  kaybolsun karanlıklar  benden öte umutl...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/dusler-sokagina-elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açılın Kapılar Şah''a Gidelim', 'acilin-kapilar-sah-a-gidelim-pir-sultan-abdal-4pr1p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hızır Paşa bizi berdar etmeden,

Açılın kapılar Şah''a gidelim,

Siyaset günleri gelip çatmadan,

Açılın kapılar Şah''a gidelim.

Bunda bilmeyeni bildirirler mi

Eli bağlı namaz kıldırırlar mı

Yoksa Şah diyeni öldürürler mi

Açılın kapılar Şah''a gidelim.

Aslımız Muhammet kıyman cellatlar

Üstümüzde bite davacı otlar

Ölüm Allah emri ya eziyetler

Açılın kapılar Şah''a gidelim.

Sağlıklı mı ola dostun illeri

Karşıda görünen tozlu yolları

Şah''tan elçi gelmiş dem bülbülleri

Açılın kapılar Şah''a gidelim.

Her nereye gitsem, yolum dumandır

Bizi böyle kılan, ahd-ü amandır

Zincir boynum sıktı hayli zamandır

Açılın kapılar Şah''a gidelim.

Güzel Şah''ım çıktı m''ola köşküne

Can dayanmaz gayretine müşkine

Seni beni Yaradan''ın aşkına

Açılın kapılar Şah''a gidelim.

Kapısı yok bacasından bakarım

Gözlerimden hasret yaşı dökerim

Şah''a giden bir bezirgan tutarım

Açılın kapılar Şah''a gidelim.

Pir Sultan Abdal''ım güzel şah canım

Ağlamaktır benim demim devranım

Arşta melek yerde çeşm-i efgânım

Açılın kapılar Şah''a gidelim.', 'Hızır Paşa bizi berdar etmeden, Açılın kapılar Şah''a gidelim, Siyaset günleri gelip çatmadan, Açılın kapılar Şah''a gidelim. Bunda bilmeyeni ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/acilin-kapilar-sah-a-gidelim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben De Şu Dünyada Üç Güzel Gördüm', 'ben-de-su-dunyada-uc-guzel-gordum-pir-sultan-abdal-vvmjb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben de şu dünyada üç güzel gördüm

Birisi kalbimde durana benzer

Birisi Muhammet birisi Ali

Şu garip halimden bilene benzer

Mümin olanların tez gelir yazı

Cennette huriye benziyor yüzü

Şu nazlı dilberin hercayi sözü

Mart ayında esen borana benzer

Yaz gelince sular köpük saçılır

Lâle sümbül çiçekleri açılır

Zoğal avcı çıkmış diye kaçınır

Çöllerde sevdiğim cerana benzer

Mümin olanların kalbi tacıdır

Mürşit eşiğine varan hacıdır

Berk basma sabana boynum acıdır

Zor edip zerveyi kırana benzer

Abdal Pir Sultan''ım göğe süzüldü

Sırat''ın üstünde nizam kuruldu

Mümin olan gaflet gıllet yazıldı

Dört kitap içinde Kur''an''a benzer', 'Ben de şu dünyada üç güzel gördüm Birisi kalbimde durana benzer Birisi Muhammet birisi Ali Şu garip halimden bilene benzer Mümin olanların t...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-de-su-dunyada-uc-guzel-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben De Şu Dünyaya Geldim Giderim', 'ben-de-su-dunyaya-geldim-giderim-pir-sultan-abdal-aoe2k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben de şu dünyaya geldim giderim

Kalsın benim davam divana kalsın

Muhammed Ali''dir benim vekilim

Kalsın benim davam divana kalsın

Yorulan yorulsun ben yorulmazam

Derviş makamından ben ayrılmazam

Dünya kadısından ben sorulmazam

Kalsın benim davam divana kalsın

Ben de vekil ettim Bari Hüda''mı

O da kulu gibi zulüm ede mi

Orda söyletirler bir bir adamı

Kalsın benim davam divana kalsın

Mümin müslim düşürür de cem olur

Anda sınık yaralara em olur

Kara taş erir de safi mum olur

Kalsın benim davam divana kalsın

Pir Sultan Abdal''ım dünya kovandır

Gitti adil beyler kalan avamdır

Muhammed divanı ulu divandır

Kalsın benim davam divana kalsın', 'Ben de şu dünyaya geldim giderim Kalsın benim davam divana kalsın Muhammed Ali''dir benim vekilim Kalsın benim davam divana kalsın Yorulan yo...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-de-su-dunyaya-geldim-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nefesçik Söyliyeyim', 'bir-nefescik-soyliyeyim-pir-sultan-abdal-14p7f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir nefescik söyliyeyim

Dinlemezsen neyliyeyim

Aşk deryasın boylayayım

Ummana dalmağa geldim

Ban Hak ile oldum aşna

Gönlümüzde yoktur nesne

Pervaneyim ateşine

Oduna yanmağa geldim

Aşk harmanında savruldum

Hem elendim hem yuğruldum

Kazana girdim kavruldum

Meydana yetmeğe geldim

Ben Hakk''ın edna kuluyum

Kem damarlardan beriyim

Ayn-ı cemin bülbülüyüm

Meydana ötmeğe geldim

Pir Sultan''ım der gözümde

Hiç hata yoktur sözümde

Eksiklik kendi özümde

Darına durmağa geldim', 'Bir nefescik söyliyeyim Dinlemezsen neyliyeyim Aşk deryasın boylayayım Ummana dalmağa geldim Ban Hak ile oldum aşna Gönlümüzde yoktur nesne ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-nefescik-soyliyeyim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize De Banaz''da Pir Sultan Derler', 'bize-de-banaz-da-pir-sultan-derler-pir-sultan-abdal-t030h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bize de Banaz''da Pir Sultan derler

Bizi de kem kişi bellemesinler

Paşa hademine tembih eylesin

Kolum çekip elim bağlamasınlar

Hüseyin Gazi Sultan binsin atına

Dayanılmaz çarh-ı felek zatına

Bizden selâm söylen ev külfetine

Çıkıp ele karşı ağlamasınlar

Ala gözlüm zülfün kelep eylesin

Döksün mah yüzüne nikap eylesin

Ali Baba Hak''tan dilek dilesin

Bizi dâr dibinde eğlemesinler

Ali Baba eğer söze uyarsa

Emir Hüdâ''nındır, beyler kıyarsa

Ala gözlü yavrularım duyarsa

Alı çözüp kara bağlamasınlar

Surum işlemedi, kaddim büküldü

Beyaz vücudumun bendi söküldü

Önüm sıra kırklar, pirler çekildi

Daha beyler bizi dillemesinler

Pir Sultan Abdal''ım coşkun akarım

Akar akar dost yoluna bakarım

Pirim aldım seyrangâha çıkarım

Daha Yıldız Dağı''n yaylamasınlar', 'Bize de Banaz''da Pir Sultan derler Bizi de kem kişi bellemesinler Paşa hademine tembih eylesin Kolum çekip elim bağlamasınlar Hüseyin Gazi S...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bize-de-banaz-da-pir-sultan-derler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenik Düştüm Aşka*', 'yenik-dustum-aska-bayram-tunca-hjj5h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şok üstüne/şok yedim

Gayrisine tövbe dedim

Düne dek çok deliydim

Bak aşka boyun eğdim

Aşk getirdi beni bu hale

Göz yaşlarım oldu şelâle

Boynum sanki bükük lâle

Her bir uzvumsa, meşale

Aşk, gece başka, gündüz başka

Ben nasıl baş edeyim ki o aşkla

Ah dostlar yenik düştüm o aşka

Ama yine de pes etmedim aşka

Garip bir sevda geldi şu başıma

Kimler siler ki gözlerimin yaşını

Ah ahbaplar bu sevda bir başka

Kimlere anlatayım ki bu aşkımı

Bir günde dört mevsim yaşarım

Bu nasıl bir aşk ben de şaşarım

Bu aşkla daha ne kadar yaşarım

Aşkımı paylaşacak olana şaşarım

24.08.2003-18:08', 'Şok üstüne/şok yedim Gayrisine tövbe dedim Düne dek çok deliydim Bak aşka boyun eğdim Aşk getirdi beni bu hale Göz yaşlarım oldu şelâle Boyn...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yenik-dustum-aska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evvel Bu Dergâhtan Kısmet', 'evvel-bu-derg-htan-kismet-pir-sultan-abdal-l3d4e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evvel bu dergâhtan kısmet

Alır da var almaz da var

Tarikate kadem basıp

Gelir de var gelmez de var

Bazını almış destine

Hizmet ederdi dostuna

Ahd ile ikrar üstüne

Durur da var durmaz da var

Olayım der isen Hızır

İrfan defterine yazıl

Hak her yerde hazır nazır

Görür de var görmez de var

Hem bizim dolumuzdan

Çıkman sakın yolumuzdan

Pir Sultan''ım halimizden

Bilir de var bilmez de var', 'Evvel bu dergâhtan kısmet Alır da var almaz da var Tarikate kadem basıp Gelir de var gelmez de var Bazını almış destine Hizmet ederdi dostun...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/evvel-bu-dergahtan-kismet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçebilirsen Gel Beri', 'gecebilirsen-gel-beri-pir-sultan-abdal-v97v0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Açıldı cennet kapısı

Lal-ü gülherdir yapısı

Kıldan incedir köprüsü

Geçebilirsen gel beri

Canımız melek canıdır

Tenimiz süleyman tenidir

İçtiğimiz aslan sütüdür

İçebilirsen gel beri

Ben hocama kul olmuşum

Üstattan öğüt almışım

Ben kanadım bağlamışım

Çözebilirsen gel beri

Ben has bahçenin gülüyüm

Ayn-ı cemin bülbülüyüm

Kırk kapının kilidiyim

Açabilirsen gel beri

PİR SULTAN''ım Haydar heman, 

Dağları bürüdü duman

İşte İncil, işte Kur''an

Seçebilirsen gel beri', 'Açıldı cennet kapısı Lal-ü gülherdir yapısı Kıldan incedir köprüsü Geçebilirsen gel beri Canımız melek canıdır Tenimiz süleyman tenidir İçti...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecebilirsen-gel-beri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Seninle Ahd-ü Peyman Edelim', 'gel-seninle-ahd-u-peyman-edelim-pir-sultan-abdal-7whib', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel seninle ahd-ü peyman edelim

Ne sen beni unut ne de ben seni

İkimiz de bir ikrarı güdelim

Ne sen beni unut ne de ben seni

Aman kaşı keman elinden aman

Sürdük sefasını etmedik tamam

Ehl-i irfan içre olduğum zaman

Ne sen beni unut ne de ben seni

Hem saza mailem hem de sohbete

Hem sana mailem hem de devlete

Aşkın ile düştüm diyar gurbete

Ne sen beni unut ne de ben seni

Yarimin cemali güneşte mahı

Sana aşık olan çekmez mi ahı

Getir and içelim Kelamullahı

Ne sen beni unut ne de ben seni

Abdal Pir Sultan''ı çektiler dara

Düşmüşüm aşkına yanarım nara

Bakın hey erenler şu giden yara

Ne sen beni unut ne de ben seni', 'Gel seninle ahd-ü peyman edelim Ne sen beni unut ne de ben seni İkimiz de bir ikrarı güdelim Ne sen beni unut ne de ben seni Aman kaşı keman...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-seninle-ahd-u-peyman-edelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleyi Gözleyi Gözüm Dört Oldu', 'gozleyi-gozleyi-gozum-dort-oldu-pir-sultan-abdal-jxbvt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözleyi gözleyi gözüm dört oldu

Ali''m ne yatarsın günlerin geldi

Korular kalmadı kara yurt oldu

Ali''m ne yatarsın günlerin geldi

Kızılırmak gibi bendinden boşan

Hama''dan Mardin''den Sıvas''a döşen

Düldül eğerlendi Zülfikâr kuşan

Ali''m ne yatarsın günlerin geldi

Mümin olan bir nihana çekilsin

Münafık başına taşlar üşürsün

Sancağımız Kazova''ya dikilsin

Ali''m ne yatarsın günlerin geldi

Şah''ın geleceğin bir gün duydular

Yezitler lânet gömleğini giydiler

İmam Aliyyürriza''ya kıydılar

Ali''m ne yatarsın günlerin geldi

Pir Sultan Abdal''ım bu sözüm haktır

Vallahi sözümün hatası yoktur

Şimdiki sofunun Yezit''i çoktur

Ali''m ne yatarsın günlerin geldi', 'Gözleyi gözleyi gözüm dört oldu Ali''m ne yatarsın günlerin geldi Korular kalmadı kara yurt oldu Ali''m ne yatarsın günlerin geldi Kızılırmak ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozleyi-gozleyi-gozum-dort-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyil Verme Nasa Murdar Olursun', 'meyil-verme-nasa-murdar-olursun-pir-sultan-abdal-jax3f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Meyil verme nasa murdar olursun

Dünya kadar malın olsa ne fayda

Tutulur dilin söylemez olursun

Bülbül gibi dilin olsa ne fayda

Bir gün olur çıkarırlar evinden

Allah''ın ismini koyma dilinden

Kurtulamazsın Azrail''in elinden

Dünya kadar fendin olsa ne fayda

Yalan söyler kov gıybette sözün var

Güvenir gezersin oğlun kızın var

Şunda senin üç beş arşın bezin var

Dünya kadar malın olsa ne fayda

Yalan söyler kov gıybetten geçmezsin

Yersin haram helal geçmezsin

Kesilir nefesin su da içmezsin

Akan çaylar senin olsa ne fayda

Pir Sultan''ım bunu böyle vird etti

Vardı bir mürşitten el etek tuttu

Mürşidin ağırlayan Hakk''a yetti

Tutulmaz nasihatim söylesem ne fayda', 'Meyil verme nasa murdar olursun Dünya kadar malın olsa ne fayda Tutulur dilin söylemez olursun Bülbül gibi dilin olsa ne fayda Bir gün olur ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/meyil-verme-nasa-murdar-olursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yatarsın Bülbül Kalk Figan Eyle', 'ne-yatarsin-bulbul-kalk-figan-eyle-pir-sultan-abdal-iuc3u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne yatarsın bülbül kalk figan eyle

Çağırıp ötmenin zamanı şimdi

Kırmızı gül yeşil yaprakta kaldı

Dalında ötmenin zamanı şimdi

Benim Şah''ım gelir türlü naz ile

Dili tuti kalbi irfan söz ile

Kırmızı badeyle cura saz ile

Muhabbet etmenin zamanı şimdi

Benim Şah''ım gelişinden bellidir

Ak elleri deste deste güllüdür

Dertli olanların derdi bellidir

Derde dert katmanın zamanı şimdi

Hoca Ahmet söyle sözünü doğru

Akar boz bulanık dağların seli

Yanına almıştır kuzu dilberi

Sarılıp yatmanın zamanı şimdi

Pir Sultan''ım Haydar netti neyledi

Sarardı gül benzim ayvaya döndü

Dertli olanın derdi belli oldu

Merhemi sarmanın zamanı şimdi', 'Ne yatarsın bülbül kalk figan eyle Çağırıp ötmenin zamanı şimdi Kırmızı gül yeşil yaprakta kaldı Dalında ötmenin zamanı şimdi Benim Şah''ım g...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-yatarsin-bulbul-kalk-figan-eyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahtan Uğradım Ben De Suna''ma', 'sabahtan-ugradim-ben-de-suna-ma-pir-sultan-abdal-e7oim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabahtan uğradım ben de Suna''ma

Dedim, Şah''ım gafletlerden uyana

Eğildim lebine bir buse kıldım

Dedim uyan, dedi, var git o yana

İnci, sedef, mercan döken kamildir

Kamillere hizmet eden kamildir

Kamil otur, kamil söyle, kamil dur

Kamil demen cahil sözüne uyana

Niçin melil melil baktın bize yar

İhsan eyle, şirin söyle bize yar

Ben teklif eyledim, sen gel bize yar

Sakın ikrarından dönme o yana

Bak şu kamet şu gerdan ne şahane

Arz edeyim şu sultana şu han''a

Bizi bu aşkın oduna yakma

Umarım ki bizden beter o yana

Pir Sultan Abdal''ım gönlüm harabat

Aşık isen bir gül için hare bat

Menzil almaz bu meydanda harab at

Çevir başın dizginini o yana', 'Sabahtan uğradım ben de Suna''ma Dedim, Şah''ım gafletlerden uyana Eğildim lebine bir buse kıldım Dedim uyan, dedi, var git o yana İnci, sedef...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sabahtan-ugradim-ben-de-suna-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sordum Sarı Çiğdeme', 'sordum-sari-cigdeme-pir-sultan-abdal-t50tt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sordum sarı çiğdeme

-Sen nerede kışlarsın

-Ne sorarsın hey derviş

Yer altında kışlarım

Sordum sarı çiğdeme

-Yer altında ne yersin

-Ne sorarsın hey derviş

Kudret lokması yerim

Sordum sarı çiğdeme

-Senin benzin ne sarı

-Ne sorarsın hey derviş

Hak korkusun çekerim

Sordum sarı çiğdeme

-Anan baban var mıdır

-Ne sorarsın hey derviş

Anam yer babam yağmur

Sordum sarı çiğdeme

Asacığı elinde

Hak kelamı dilinde

Çiğdemde dervişlik var

Pir Sultan''ım erlerle

Yüzü dolu nurlarla

Ak sakallı pirlerle

Çiğdemde dervişlik var', 'Sordum sarı çiğdeme -Sen nerede kışlarsın -Ne sorarsın hey derviş Yer altında kışlarım Sordum sarı çiğdeme -Yer altında ne yersin -Ne sorars...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sordum-sari-cigdeme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyyah Olup Şu Alemi Gezerim', 'seyyah-olup-su-alemi-gezerim-pir-sultan-abdal-78rxk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seyyah olup şu alemi gezerim     

Bir dost bulamadım gün akşam oldu     

Kendi efkarımca okur yazarım     

Bir dost bulamadım gün akşam oldu     

        

İki elim kalkmaz oldu dizimden     

Bilmem amelimden bilmem özümden     

Akıttim kanlı yaş iki gözümden     

Bir dost bulamadım gün akşam oldu     

        

Yine boralandı dağların başı     

Akıttım gözümden kan ile yaşı     

Emaneti alır ol veren kişi     

Bir dost bulamadım gün akşam oldu     

        

Bozuk şu cihanın pergeli bozuk     

Yazıktır şu geçen ömre yazık

Tükendi daneler kalmadı azık     

Bir dost bulamadım gün akşam oldu     

        

Pir Sultan''ım eydür ummana dalam     

Gidenler gelmedi bir haber alam     

Abdal oldum çullar giydim bir zaman     

Bir dost bulamadım gün akşam oldu', 'Seyyah olup şu alemi gezerim      Bir dost bulamadım gün akşam oldu      Kendi efkarımca okur yazarım      Bir dost bulamadım gün akşam oldu...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seyyah-olup-su-alemi-gezerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahtan Uğradım Ben Bir Figana', 'sabahtan-ugradim-ben-bir-figana-pir-sultan-abdal-kso4n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabahtan uğradım ben bir figana

Bülbül ağlar ağlar güle getirir

Bakın şu feleğin çürük işine 

Her bir cefasını kula getirir

      

Depreştirme benim dertlerim tamam

Muhabbet şirindir vermiyor aman

Üstümüzde dönen çarh ile devran

Felek bizi halden hale getirir

      

Pir Sultan Abdal''ım sözlerim haktır

Hakk diyen kullardan hiç süphem yoktur

Cehennemde ateş olmaz nar yoktur

Herkes ateşini bile götürür', 'Sabahtan uğradım ben bir figana Bülbül ağlar ağlar güle getirir Bakın şu feleğin çürük işine  Her bir cefasını kula getirir        Depreştir...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sabahtan-ugradim-ben-bir-figana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yıl Bu Dağların Karı Erimez', 'bu-yil-bu-daglarin-kari-erimez-pir-sultan-abdal-89vdb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu yıl bu dağların karı erimez

Eser bâd-ı sabâ yel bozuk bozuk               

Türkmen kalkıp yaylasına yürümez

Yıkılmış aşiret il bozuk bozuk

Kızılırmak gibi çağladım aktım

El vurdum göğsümün bendini yıktım

Gül yüzlü cerenin bağına çıktım

Girdim bahçesine gül bozuk bozuk

Elim tutmaz güllerini dermeye

Dilim tutmaz hasta hâlin sormaya

Dört cevabın mânasını vermeye

Sazım düzen tutmaz tel bozuk bozuk

Pir Sultan''ım yaratıldım kul diye

Zalim paşa elinden mi öl diye

Dostum beni ısmarlamış gel diye

Gideceğim amma yol bozuk bozuk', 'Bu yıl bu dağların karı erimez Eser bâd-ı sabâ yel bozuk bozuk                Türkmen kalkıp yaylasına yürümez Yıkılmış aşiret il bozuk bozu...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-yil-bu-daglarin-kari-erimez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niçin Gitmez Yıldızdağı Dumanın', 'nicin-gitmez-yildizdagi-dumanin-pir-sultan-abdal-cj6pp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelmiş iken bir habercik sorayım

Niçin gitmez Yıldızdağı dumanın

Gerçek erenlere yüzler süreyim

Niçin gitmez Yıldızdağı dumanın

  

Alçağında al kırmızı taşın var

Yükseğinde turnaların sesi var

Ben de bilmem ne talihsiz başın var

Niçin gitmez Yıldızdağı dumanın

  

Benim Şah''ım al kırmızı bürünür

Dost yüzün görmeyen düşman bilinir

Yücesinden Şah''ın ili görünür

Niçin gitmez Yıldızdağı dumanın

  

El ettiler turnalar bazlara

Dağlar yeşillendi döndü yazlara

Çiğdemler taşınsın söylen kızlara

Niçin gitmez Yıldızdağı dumanın

  

Şah''in bahçesinde gonca gül biter

Anda garip garip bülbüller öter

Bunda ayrılık var ölümden beter

Niçin gitmez Yıldızdağı dumanın

  

Ben de bildim şu dağların şahısın

Gerçek erenlerin nazargâhısın

Abdal Pir Sultan''ın seyrangâhısın

Niçin gitmez Yıldızdağı dumanın', 'Gelmiş iken bir habercik sorayım Niçin gitmez Yıldızdağı dumanın Gerçek erenlere yüzler süreyim Niçin gitmez Yıldızdağı dumanın    Alçağında...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nicin-gitmez-yildizdagi-dumanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnilersin Dolap Derdin Ne Senin', 'i-nilersin-dolap-derdin-ne-senin-pir-sultan-abdal-kboci', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ali Ali deyip ne inilersin

İnilersin dolap derdin ne senin

Sen de benim gibi yaralı mısın

İnilersin dolap derdin ne senin

     

Kim söktü getirdi seni yerinden

Dağlar taşlar ah eyleyi zarından

Sen de mi ayrıldın nazlı yârinden

İnilersin dolap derdin ne senin

     

Pir Sultan''ım ahım arşa dayandı

Hasret nârı ile yüreğim yandı

Yoksa Hüseyin''den haber mi geldi

İnilersin dolap derdin ne senin', 'Ali Ali deyip ne inilersin İnilersin dolap derdin ne senin Sen de benim gibi yaralı mısın İnilersin dolap derdin ne senin       Kim söktü ge...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/inilersin-dolap-derdin-ne-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-pir-sultan-abdal-xx1t3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Amanın eyle mürüvvet

Gördüğüne tapma gönül

Yüzüne bakmayanın sen

Tozuna da bakma gönül

Bir kardaşa meyil verip

Tuz ile ekmeğini yiyip

Azıcık noksanını görüp

Tez başına kakma gönül

Arap ata binip coşma

Karlı buzlu dağlar aşma

Her gördüğüne sır açma

Doluları dökme gönül

Pir Sultan''ım gündür ava

Çektiğim emekler hava

Nasihatım olsun sana

Sen hatırlar yıkma gönül', 'Amanın eyle mürüvvet Gördüğüne tapma gönül Yüzüne bakmayanın sen Tozuna da bakma gönül Bir kardaşa meyil verip Tuz ile ekmeğini yiyip Azıcık...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayır Edem Derken İşlerim Şer Oldu', 'hayir-edem-derken-i-slerim-ser-oldu-pir-sultan-abdal-s872c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayır edem derken işlerim şer oldu

Elimden bir kaza çıktı erenler

Evliye ceminde yerim dar oldu

Elimden bir kaza çıktı erenler

Benim ahdim oldur hatır yıkmayım

Evliyanın buyruğundan çıkmayım

Yüzümü çevirip şerre bakmayım

Elimden bir kaza çıktı erenler

İndim ilim deryasını boyladım

Günahım çok ama bir bir söyledim

Sanki yanınızda hata eyledim

Elimden bir kaza çıktı erenler

Benim bir sözüm var efsane sözde

Ne günah der isen bulunur bizde

Erenler nişanı var ise bizde

Elimden bir kaza çıktı erenler

Pîr Sultan Abdal''ım belalı başım

Ferahtan ayrıldım gamdır yoldaşım

Al olan malimi sağ eyle başım

Elimden bir kaza çıktı erenler', 'Hayır edem derken işlerim şer oldu Elimden bir kaza çıktı erenler Evliye ceminde yerim dar oldu Elimden bir kaza çıktı erenler Benim ahdim o...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayir-edem-derken-islerim-ser-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emek Çektim Bir Ev Yaptım Erenler', 'emek-cektim-bir-ev-yaptim-erenler-pir-sultan-abdal-ini73', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Emek çektim bir ev yaptım erenler

Yine bu güzele bildiremedim

Bahar geldi çiçek bitti ot bitti

Toprak güldü taşı güldüremedim

Yüreğimde belli belli yaralar

Şeytan kalbin almış gözün köreler

Hakk''ın niyaz eylemeye âr eyler

Eğilip bir secde kıldıramadım

Hû demine bir ikrarı güdenin

Tu yüzüne ikrarından dönenin

Pîr Sultan''ım münafığı nâdanın

Gönül aynasını sildiremedim', 'Emek çektim bir ev yaptım erenler Yine bu güzele bildiremedim Bahar geldi çiçek bitti ot bitti Toprak güldü taşı güldüremedim Yüreğimde bell...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/emek-cektim-bir-ev-yaptim-erenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönül İnil İnil İnleme', 'deli-gonul-i-nil-i-nil-i-nleme-pir-sultan-abdal-7nm86', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Deli gönül inil inil inleme

Kadir mevlam hasretime sal beni

Viranlıkta görsen baykuş sanırsın

Bir huma kuşuyum sen de bil beni

Ulu bezirganım kumaş satarım

Gökyüzünden uçan kuşu tutarım

Yetmiş iki dilden bilir öterim

Anın için fark edemez el beni

Ak pınarın boz bulanık seliyim

Ol sebepten aklım yoktur deliyim

Naci derler dört güruhun biriyim

Ararsan hak divanında bul beni

Gider idim ben de kendi işime

Aşkın doluları yağdı başıma

Ağu kattı benim tatlı aşıma

Ummanlara gark eyledi sel beni

Pir Sultan''ım ırak yoldan gelirsin

Gevherin kıymetini nerden bilirsin

Eksikliğim çoktur sen de bilirsin

Eksiklikle kabul eyle gel beni', 'Deli gönül inil inil inleme Kadir mevlam hasretime sal beni Viranlıkta görsen baykuş sanırsın Bir huma kuşuyum sen de bil beni Ulu bezirganı...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deli-gonul-inil-inil-inleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıçak Yarası', 'bicak-yarasi-ayfer-ersoy-mcbe4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alıp başımı gittim bu şehirden

Seninle dolu sokaklardan 

Kaldırımlardaki izlerinden Kaçtım...

Hiç bilmediğim yollar karşıladı beni

Hiç tanımadığım sokaklara saldım kendimi

Senin izinden eser yok artık...

Yakomoz kucakladı gece yarısı 

Rüzgar yüzümü okşadı

Sensizliğe kadeh kaldırdık dolunay'' la

Bilmediğim yolların yolcusu, 

Tanımadığım sokakların kaldırım taşıydım artık...

Saklı kalan bütün cümleler döküldü sahilin kumlarına

Dalgalar alıp gitti sonra

Ve biliyormusun

Söylenmemiş hiç bir söz kalmadı artık bende

Tanımadığım bir şehir

Bilmediğim yollar

Ve senden iz taşımayan kaldırımlar

Birde tanımadığım hayallerle beynimi de doldurabilsem

Tanımadığım heyecanlarla yüreğimi doldurabilsem

Bıçak yarası izini yok edebilsem benden

Kimbilir belki....

Yabancılaşırım', 'Alıp başımı gittim bu şehirden Seninle dolu sokaklardan  Kaldırımlardaki izlerinden Kaçtım... Hiç bilmediğim yollar karşıladı beni Hiç tanım...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bicak-yarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostun Bahçesine Bir Hoyrat Girmis', 'dostun-bahcesine-bir-hoyrat-girmis-pir-sultan-abdal-35kjc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dostun bahçesine bir hoyrat girmis

Korudur hey benli dilber korudur

Gülünü dererken dalını kırmış

Kurutur hey benli dilber kurutur

Şu meydanda serilidir postumuz (*)                

Çok şükür Mevlâ''ya gördük dostumuz             

Bir gün kara toprak bürür üstümüz             

Çürütür hey benli dilber çürütür              

Kendisi okur da kendisi yazar

Hak hilâl kaşına eylemiş nazar

Senin akranların cennette gezer

Hürüdür hey benli dilber hürüdür

Hangi dinde isen ona tapayım

Yarın mahşer günü bile kopayım

Eğil bir yol ak gerdandan öpeyim

Beri dur hey benli dilber beri dur

Dervişe n''olursa kendi tacından(*)                 

Irakibe ölüm yâre geçinden                    

Benzimin sarısı senin ucundan

Sarıdır hey benli dilber sarıdır

Pîr Sultan Abdal''ım başından başlar

İyisini yer de kemini taşlar

Bin çiçekten bir kovana bal işler

Arıdır hey benli dilber arıdır

(*)   Post: Alevî Bektasî törenlerinin yapıldığı meydanda (odada)   tarikat ulularının onikisinin makamı sayılan oniki post.

(*)   Taç :  Dervislerin giydigi başlık', 'Dostun bahçesine bir hoyrat girmis Korudur hey benli dilber korudur Gülünü dererken dalını kırmış Kurutur hey benli dilber kurutur Şu meydan...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dostun-bahcesine-bir-hoyrat-girmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Allah Desem Kalksam Yürüsem', 'allah-allah-desem-kalksam-yurusem-pir-sultan-abdal-3ajd7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Allah Allah desem, kalksam yürüsem

Acap şu dağları aşamam mola

Boz atlı Hızır''ı yoldaş eylesem

Varıp efendime düşemem mola

Sevdiğim, bağında güllerin gonca 

Usuldur boyların, bellerin ince

Adı güzel imamların önünce

Kerbelâ''da şehit düşemem mola

Sakın hey sevdiğim, nâsiden sakın

Erenler geri almaz attığı okun

Irak yerlerini sen eyle yakın

İki atlayıp bir dem düşemem mola

Ben güzel pîrîme verdiğim ikrar

Doluda, kırçından, borandan saklar(*)             

İhlâs âşık olan ikrarın bekler

İkrarın bendini çesemem mola(*)                   

PIR SULTAN ABDAL''ım, dost çiresine

Arzumanım kaldı Şah cilvesine

Altmış ile yetmiş üçün arasına

Özümü irfana koşamam mola

(*)  kırçı : küçük taneli kar

(*)  çesmek: çözmek', 'Allah Allah desem, kalksam yürüsem Acap şu dağları aşamam mola Boz atlı Hızır''ı yoldaş eylesem Varıp efendime düşemem mola Sevdiğim, bağında...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/allah-allah-desem-kalksam-yurusem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sevgilimi Buldum', 'ben-sevgilimi-buldum-necdet-cobanli-ayfbl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana hep (seni cok seviyorum)   diyen hanimlar, 

(seninle tanismak istiyorum)   diye aldatanlar, 

Sonra sirtini bana donup baskasiyla yatanlar, 

Artik sizlere inanmiyorum ben; kara fatmalar, 

Benim artik yeni bir sevgilim var buralarda, 

Ister kiskanin, kizarsanizda hemen cikin dama, 

Cunku ben deli gibi tutuldum bu genc hanima, 

Hanim deyip gecmeyin o benzer bir sultana, 

Bana (ihtiyar)   deyip yuz vermeyenler, 

Sonra da beni uyutup hic sevmeyenler, 

Anlayiniz artik beni vardir bekleyenler, 

Kulak verin sesime szi beni dinlemeyenler, 

Peki merak etmeyiniz soyleyecegim onun adini, 

Sizde gorurseniz onu, anlarsiniz hemen tadini, 

O benim en son sevgilim anlayin kim oldugunu, 

Yasi dokuz ama o benim laram, tanimalisiniz onu.', 'Bana hep (seni cok seviyorum)   diyen hanimlar,  (seninle tanismak istiyorum)   diye aldatanlar,  Sonra sirtini bana donup baskasiyla yatanl...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-sevgilimi-buldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat Sattir, Duymazki Sesinizi..', 'saat-sattir-duymazki-sesinizi-necdet-cobanli-tskhp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelin siz de bir gün benim gibi yapın, 

Rahat bir gününüzde yatağınıza uzanın, 

Pencerelerinizin hepsini ardına kadar açın, 

Ve o tertemiz bahar havasını soluyun.

Sonra gözlerinizi kapatıp rüyalara dalın, 

Yaşamınızın tümünü hatırlamaya çalışın.

Yarınlarınızı da bir düşünüzde hatırlayın, 

Bırakıp da rüyanızı uyanmayın sakın.

Yaşamınızın güzelliklerini orada bulacaksınız, 

Düşlerinizi, aşklarınızı da orada bulacaksınız.

Yaşamın boş olduğunun da farkına varacaksınız. 

Ama kendinizi sakın karamsarlığa kaptırmayınız.

Karamsarlık birden gelir ve bulaşıcıdır, 

Çıkagelir ve sizi tutsak almağa kalkar. 

İzin vermeyin buna; yeni bir sabahın olacağını unutmayın, 

Bu işte; ne yapalım, yazgımız buraya kadarmış..'' demeyin. 

Uyandığınız da, aksine, iyi bir izlenime erişmişseniz, 

Hemen iyimserliğe de kapılmanız da gereksizdir.

Düşleriniz gerçekleşmiş bile olsa, bu gereksiz iyimserliğiniz de boşunadır. 

''Oh, ne güzel, yaşam benim için hep böyle gidecek! ''

diyerek yersiz bir sevince kaptırmayın kendinizi. 

Çünkü ikisi de yanlıştır. Yaşam, uzun ve çok sürprizlerle doludur. 

Belki daha nice güzellikler görecek, kalbiniz yeni aşklarla dolacaktır.

Kimbilir nasıl büyük bu aşklarla tepeden tırnağa kafanız sarsılacaktır, 

Yaşamın türlü boşluklarını görüp öğrenecek, Kimi kez nefrete boğulacak, 

Ya da varılmaz sandığınız düşlerin sıcaklığına kendinizi bırakacaksınız. 

Yaşam dediğimiz budur; çünkü budur ve iki yüzlüdür. 

Yaşamın size sonsuza dek ''Bonjour'' demesine de, 

''Bonsoir'' demesine de giderek alıştırın kendinizi. 

Fransız şairi Alfred de Musset gibi yapın….

Yaşamınızın mutsuzluklarını düşünün

Gece yarısına doğru saate dönerek: 

''Koş saat, koş, ne olur, '' diye yalvarın.

Mutsuzluklardan kurtulup yeni güne yeni bir ''Bonjour'' demek için. 

Mutluluğun sonsuza dek sürmeyeceğini da iyi bilin, 

Gözünüz gene saatte olsun. 

Mutluluktan düşlerine eriştiğinizde de; 

''Dur saat, dur, ne olur, '' diye seslenin bu kez.

Mutluluğunuzun bir ''Bonsoir'' la kısa sürmemesi için. 

Fakat saat, saattir. Ne ağzı, ne dili, ne de kulağı vardır.

Dinlemez ki ne Musset''yi ne de sizi.

İşitmez; sesinizi, bağırmalarınızı, 

Yüzyıllardır bilip yürüdüğü yolda, yürür durur. 

Duymaz haykırışlarınızı..... 

Ne koşar sizi mutsuzluklardan kurtarmak için, 

Ne de durur sizi yeni mutluluklara kavuşturmak için. 

Mutluluk gelir ve gider; yerini mutsuzluğa bırakır. 

Her akşamın bir sabahı, her karanlığın yine bir aydınlığı vardır.

Ne bunu, ne de her akşam ''Bonsoir'' la yatıp

Sabahına ''Bonjour'' la kalkacağınızı hiç unutmayın. 

Umut, asla Kaf dağının ardında değildir.

Akşamlarınız ''Bonsoir'' la bitse bile, 

Her sabahın bir ''Bonjour''u vardır.

Tabii, bu ikisinin, kaçınılmaz ortak bir de sonu var: Ölüm!', 'Gelin siz de bir gün benim gibi yapın,  Rahat bir gününüzde yatağınıza uzanın,  Pencerelerinizin hepsini ardına kadar açın,  Ve o tertemiz b...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/saat-sattir-duymazki-sesinizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korudaki Rüya', 'korudaki-ruya-necdet-cobanli-luyyj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün, ben ağır ağır yürüyordum koruda, 

Güzel kokulu çam ağaçlarının altında, 

Bilmem neden gözlerim hep yukarıda, 

Sanki arıyordum ben birini oralarda, 

Yürürken aradığımı buldum sonunda, 

O bir eski sevgilimdi kolları boynumda, 

Bitirdim yürüyüşümü ben onu ana ana, 

Eve dönünce onu görmiyeyim mi karşımda? 

Şasırıp kaldım, koşarak boynuna sarıldım, 

Sonrada onu öpüp, doya doya kucakladım, 

Ama sürmedi keyfim, biraz sonra uyandım, 

Uyanınca da bunun rüya olduğunu anladım.

Aldırmayın siz, rüya da olsa ona razımısınız? 

Ya hiç olmasaydı diye diye keyfinize bakınız, 

Rüyam bir gün gerçek olur diye umutlanınız, 

Sonra da yanınıza dönüp gene uyumaya bakınız.

Size yaşamınızca güzel rüyalı uykular dilerim, 

Rüyalarınızın bir gün hakikat olmasını isterim, 

O zamanda ben sizin koruda yolunuzu gözlerim, 

Mutluluktan uçup boynuma sarılmanızı beklerim.', 'Dün, ben ağır ağır yürüyordum koruda,  Güzel kokulu çam ağaçlarının altında,  Bilmem neden gözlerim hep yukarıda,  Sanki arıyordum ben birin...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/korudaki-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ve Meşk', 'ask-ve-mesk-necdet-cobanli-sb6c2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“Aşk” dediler, inanıp yıllarca peşinden koştum.

Güneşli günlerden sonra kendimi karanlıklarda buldum.

“Meşk” dediler, heveslenip, deli divane oldum, 

Kendimi birden mahkeme koridorların da buldum.

	

Yaptığıma, “Hayır, yapmadım” deyip kurtuldum.

Her seferinde “aşkla  meşkin” kurbanı oldum.

İnanın bana, pişman olan hep ben oldum.

Sonunda kurtuluşu anama sığınmak la buldum.

Mutluluğu onun bulduğu kadınla tanıdım, 

Kendimi yıllarca ona teslim ederek uyudum, 

Uyandığımda dünyalar benim olmuştu sandım, 

İşte böyle “aşk ile meşk” in esiri oldum.', '“Aşk” dediler, inanıp yıllarca peşinden koştum. Güneşli günlerden sonra kendimi karanlıklarda buldum. “Meşk” dediler, heveslenip, deli divan...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-ve-mesk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlâ''m Çün Yarattı Ahmed''i Nurdan', 'mevl-m-cun-yaratti-ahmed-i-nurdan-pir-sultan-abdal-44c33', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mevlâ''m çün yarattı Ahmed''i nurdan

İnsan olan gelir nura çevrilir                 

Böyle kurulmuştur bu çarh-ı devran           

Mansur olan gelir dâra çevrilir                

                     

Yeğin sular dâim engine akar                   

Pervaneler özün odlara yakar

Serçe kanda olsa aslına çeker                  

Bülbül olan gelir güle çevrilir

  

Gümanlı gönülde nur mu eğlenir      

Cennet haricinde hur mu eğlenir                  

Arısız kovanda bal mı eğlenir

Arı olan gelir bala çevrilir

  

Bir sürçmekle at ayağı kesilmez

Bir suç ile âdemoglu asılmaz                   

Bu yolu erenler kurdu basılmaz

Yol ehli kandaysa yola çevrilir

  

Pîr Sultan Abdal''ım yatır hastadır         

Elinde gülleri deste destedir

Âdemoglu bir acayip nesnedir

Muhabbetle tatlı dile çevrilir', 'Mevlâ''m çün yarattı Ahmed''i nurdan İnsan olan gelir nura çevrilir                  Böyle kurulmuştur bu çarh-ı devran            Mansur olan...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mevla-m-cun-yaratti-ahmed-i-nurdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canim Sevgilim', 'canim-sevgilim-necdet-cobanli-lkwpw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duydum ki beni düşünüp üzülürmşsün, 

Uzulme  canım yakında buna da alışırsın, 

Her kadının bunlari çektigini  bilmelisin, 

Koltuguna kurulup keyfine bakmalısın.

Yarınlarin yalnızlıgına da  alışmalısın.

Hayat budur, böyle gelmiş böyle gidecektir, 

Aşktan uzakta kalanlar sana  anlatacaktır.

Seni sevenlerin seni  hic unutmayacaklardır, 

Bir gün gelip senin boynuna sarılacaklardır.

Yok yok,  biliyorum sende çok seversin beni, 

Sizin ''Allah”  dediğiniz o, ayırdı seninle beni, 

Inanki, o, bana mutlak kavusturacaktır seni, 

Yoksa   bela okurum  görmeden  cehennemi.

                                                      

Anlasınlar onlar da '' aşk'' ın ne olduğunu, 

Sensiz yaşamanin hiç bir anlamı olmadığını, 

Olursa zaten benim sensiz yaşayamıyacağımı, 

''Hayır''dersen benim çok uzaklarda olacağimı.

 Aşkın cahili olana,  aşkı anlatmak  niye  ki, 

Seni ölesiye sevdiğimi dünya alem bilmeli, 

 Anlamali her biri ve ''Büyük aşk bu'' demeli, 

Sensiz geçen hayatın hiç bir tadı olmaz ki

Bunu anlayamayanın, bilmem akibeti ne olur? 

Bilmeyip öğrenenin de Allah yanında olur.', 'Duydum ki beni düşünüp üzülürmşsün,  Uzulme  canım yakında buna da alışırsın,  Her kadının bunlari çektigini  bilmelisin,  Koltuguna kurulup...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/canim-sevgilim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri Girme Meydana', 'serseri-girme-meydana-pir-sultan-abdal-uvnae', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Serseri girme meydana

Aşıktan ahval isterler

Kallaşlık ile urma dem                

Tasdik ehli kal isterler              

                                                       

Uyan bu gaflet habından              

İsbat isterler batından(*)                

Her aşıka sohbetinden

İkrar ile yol isterler

  

Erenler oynar utulmaz                 

Bu yola hile katılmaz

Burda harmühre satılmaz(*)                 

Ya gevher ya lâ''l isterler            

                                          

Kılı kırk pare ederler                

Birin yol tutup giderler             

Dile n''itibar ederler                 

Hâl içinde hâl isterler

  

Pir Sultan Abdal n''eylersin

Muşkil halledip söylersin

Arısın çiçek yaylarsın

Yarın senden bal isterler

  

(*)  Batın: İç yüz  (tarikat bilgileri)

(*)  Harmühre: Katır boncuğu', 'Serseri girme meydana Aşıktan ahval isterler Kallaşlık ile urma dem                 Tasdik ehli kal isterler                                ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/serseri-girme-meydana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnizlik', 'yalnizlik-necdet-cobanli-03whc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bende bilmezdim, sevgili Yılmaz kardeşim, 

Ama gel görki zamanla onu da öğrendim, 

O vakit (Neden neden)   diye bende inledim

Yaşdaşlarımdan da aynı sesleri dinledim.

(Bak bir varmış bir yokmuş eski günlerde)   diye, 

Başlayan o güzel şarkıyı doladım birden dilime, 

Ve hatırladım eski günlerimi bende inleye inleye, 

Ve de imrenip daldım eski günlerimin güzelliğine.

Ve andım seni (bilmezdim...)   dediğin o güzel şiirinle, 

Bilmek güzel şey, ama bilmemek dopdolu hüzünlerle, 

Çaresi yokmuş bunun, çekmiş senin gibi herkeslerde, 

Anlıyorum senin çektiğin çaresizlikleri şimdi ben de.

Yalnız duyan çeker derim en doğru söz budur, demiş, 

Şairin biri, ona inanıp gününü gün etmek en iyisiymiş, 

Ama gel gör ki bizde bunu yapacak takat bile kalmamış.

Onun için en iyisi galiba hemen yatıp rüyalara dalmakmış.

Gel çaresizlikle boğuşmaktansa biz de bunu yapalım, 

Sarılacak kadınımız yoksa bile yatıp rüyalara dalalım, 

Ve sanki o rüya hakikatmiş gibi kendimizi kandıralım.

Rüyalarımız devam etsin diye yataktanda kalkmıyalım.

Bizleri kaldıracak birileri bulunur ve duamız da okunur

Herkes gibi vücüdümüzü kefene saracak birisi de bulunur, 

Keyfine bak sen, giittiğin yer Cennet, Hurilerle doludur.

Benimki ise Cehenem, orada ise Zebanilere esir olunur.', 'Bende bilmezdim, sevgili Yılmaz kardeşim,  Ama gel görki zamanla onu da öğrendim,  O vakit (Neden neden)   diye bende inledim Yaşdaşlarımdan...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalnizlik-124-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoksun', 'sen-yoksun-ozer-sutcu-im0zh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün gece yapayalnız kalıp

Duvarlarla konuştum sabaha kadar

Öylesine boş duvarlara bakıp

Seni hayal ettim sonsuza kadar.

Anladım ki sensizlk sonum olacak

Yaşama hevesim bitti bir anda.

Sen kalbimde açan bir çiçek

Sen yoksan yaşayamam dünyada.

Sen yoksan herşey yalan oluyor.

Herşey bitmiş artık benim gözümde

Kalbim yalnız seninle hayat buluyor

Hep sen varsın dünümde, bu günümde.', 'Dün gece yapayalnız kalıp Duvarlarla konuştum sabaha kadar Öylesine boş duvarlara bakıp Seni hayal ettim sonsuza kadar. Anladım ki sensizlk ...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-yoksun-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Dostlar', 'elveda-dostlar-necdet-cobanli-eeh0u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmem beni hatırlıyacak mısınız? 

İsmimi duyunca şaşıracak mısınız? 

Gene de kahkahayı basacak mısınız? 

''Aaa, bu Necdet! '' diyecek misiniz? 

Bu satırlar size halimi anlatacaktır, 

Belki de ilginizi de uyandıracaktır. 

Bilirsiniz, her hayatın bir sonu vardır. 

''Son''gelince onu kimse durduramıyacaktır. 

Sizlere ''Allahaısmarladık'' demeye geldim, 

Gülümseyerek beni hatırlamanızı istedim. 

Bilmem gideceğim yerden dönebilecek miyim? 

Dönebilsem de elinizi tutabilecek miyim? 

Yıllar çabuk geçti, yaş limitine dayandı, 

Bende zaten artık dayanacak takat kalmadı. 

Kalsaydı da zaten bu halde neye yarardı? 

Bir şeye yarasa da benden kim ne yapardı? 

Onun için lütfen bana helâl edin hakkınızı, 

Ama gene isterim arada sırada beni anmanızı, 

''Deliydi doluydu ama, fena adam değildi''demenizi. 

Sonra da hayatınıza, güzelliklerle devam etmenizi. 

Evet; ''Elveda dostlar Elveda, '' benden sizlere, 

İnanız bana, bakmayınız onun bunun sözlerine, 

Beyhude aramayınız beni, sizin yeriniz Cennette, 

Dinden pek anlamayan benimki ise Cehennemde.', 'Bilmem beni hatırlıyacak mısınız?  İsmimi duyunca şaşıracak mısınız?  Gene de kahkahayı basacak mısınız?  ''Aaa, bu Necdet! '' diyecek misiniz...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/elveda-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aman Canim Olmaz Ki', 'aman-canim-olmaz-ki-necdet-cobanli-nupzo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmem beni hatırlıyacak mısınız? 

İsmimi duyunca şaşıracak mısınız? 

Gene de kahkahayı basacak mısınız? 

''Aaa, bu Necdet! '' diyecek misiniz? 

Bu satırlar size halimi anlatacaktır, 

Belki de ilginizi de uyandıracaktır. 

Bilirsiniz, her hayatın bir sonu vardır. 

''Son''gelince onu kimse durduramıyacaktır. 

Sizlere ''Allahaısmarladık'' demeye geldim, 

Gülümseyerek beni hatırlamanızı istedim. 

Bilmem gideceğim yerden dönebilecek miyim? 

Dönebilsem de elinizi tutabilecek miyim? 

Yıllar çabuk geçti, yaş limitine dayandı, 

Bende zaten artık dayanacak takat kalmadı. 

Kalsaydı da zaten bu halde neye yarardı? 

Bir şeye yarasa da benden kim ne yapardı? 

Onun için lütfen bana helâl edin hakkınızı, 

Ama gene isterim arada sırada beni anmanızı, 

''Deliydi doluydu ama, fena adam değildi''demenizi. 

Sonra da hayatınıza, güzelliklerle devam etmenizi. 

Evet; ''Elveda dostlar Elveda, '' benden sizlere, 

İnanız bana, bakmayınız onun bunun sözlerine, 

Beyhude aramayınız beni, sizin yeriniz Cennette, 

Dinden pek anlamayan benimki ise Cehennemde.', 'Bilmem beni hatırlıyacak mısınız?  İsmimi duyunca şaşıracak mısınız?  Gene de kahkahayı basacak mısınız?  ''Aaa, bu Necdet! '' diyecek misiniz...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aman-canim-olmaz-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.San''ât', 'san-t-mustafa-engin-karatay-7yvlj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yedi Milyar Punta''lı, muazzâm bir Defter''de; 

Al eline mikroskop, seyreyle yerin nerde? ! 

Her Punta''nın içinde, Binbir çeşit Kâinât; 

Bu nakşı tezyîn eden, o ne muhteşem san''ât...', 'Yedi Milyar Punta''lı, muazzâm bir Defter''de;  Al eline mikroskop, seyreyle yerin nerde? !  Her Punta''nın içinde, Binbir çeşit Kâinât;  Bu na...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/san-at-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bu Babanin Evladiyim', 'ben-bu-babanin-evladiyim-necdet-cobanli-tx9ep', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Necdet''in sefinei hayatındaki dürbünü, 

pusulası, dümeni yahut babasının ilk ve 

son nasihati: 

Dininde, imanında, itikadın olsun, 

İffet, istikamet, düsturun olsun, 

Nezaket, insaniyet, şehrâhın olsun, 

Sayü gayret, gıdayı ruhun olsun, 

Onur, şeref, gaye''i emelin olsun, 

Mesleğinde, sanatında, sebatın olsun, 

İşret safahat, dersi ibretin olsun, 

Fene, sanata meyil ve muhabbetin olsun, 

''Lisan-ı ecnebiye'' ye'' gayretin olsun, 

İlme, büyüğe, hürmetin olsun, 

Hocana, ebeveynine, itaatin olsun, 

Öksüze fukaraya, merhametin olsun, 

Ailene çocuklarına, merbutiyetin olsun, 

SANCAğA, VATANA hizmetin olsun, 

Sözüne, vaadi''ne, sadakatin olsun, 

Kibir ve gurura, hiddetin olsun, 

Zulüm ve taadi''ye, nefretin olsun, 

Sırdaşın, mahremin yalnız nefsin olsun, 

Borç, faiz''de, gözün olmasın. 

Masrafın, zevkin kazandığın olsun. 

İstiklâl muharebesinde üçüncü Kafkas Fırkası Topçu Kumandanı baban 

Cemal. İmza''', 'Necdet''in sefinei hayatındaki dürbünü,  pusulası, dümeni yahut babasının ilk ve  son nasihati:  Dininde, imanında, itikadın olsun,  İffet, i...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-bu-babanin-evladiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular', 'duygular-mustafa-sureyya-sezgin-um4r9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oynadığımız hayat oyununda

Kıpırdayan  her duygu

Perdelenir çoğu kez

O nedenle gerçek değildir.

İzlediğin  her oyun.

Bir şifre çözer gibi

Çözmelisin her davranışı

Ve her kelimeyi.

Gülerken bir insanın yüzü

Duygular  ağlayamaz mı? 

Ve “ İstemiyorum “ derken sen

Özlemler kabarmaz mı? 

Duygular,  sınırsızdır

Duygular,  amansızdır

Onlar, 

Zincirlidir görüntünün ardında

Bir oyun  kurgulanır, 

Oynayan da anlamaz bu oyunu. 

“Kavuşmak istemem”; dersin

Arzularsın,  bilmezsin

Duygular,  sabırsızdır

Duygular,  insafsızdır

Sahnelerde bir  oyun oynanır

Duygular yüreğin kulisinde saklanır.

İstanbul,11.09.2003', 'Oynadığımız hayat oyununda Kıpırdayan  her duygu Perdelenir çoğu kez O nedenle gerçek değildir. İzlediğin  her oyun. Bir şifre çözer gibi Çö...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/duygular-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sabah', 'bir-sabah-i-smail-haki-simsek-1l8rh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün doğuşunda

Ellerde kızıl güller

Uykulu sabahlara

Koşar mavi yelkenler

İnciler sabahı aydınlatır

Kuytular güvercinleri

Kalplerde ayrılık vardır

Aşktır serüvenleri

Pençesiz kartallar uçar

Sorgusuz yarınlara

Umut umutsuzca bakar

Gamzesiz dudaklara

Bir sabah

Sen olmayı beklersin

Düşlerinle yaşamayı

Gerçeklere yeğlersin', 'Gün doğuşunda Ellerde kızıl güller Uykulu sabahlara Koşar mavi yelkenler İnciler sabahı aydınlatır Kuytular güvercinleri Kalplerde ayrılık v...', ARRAY['Türk Edebiyatı','Şiir','İsmail Haki Şimşek']::text[], 8.5, '{"poet":"İsmail Haki Şimşek","poet_slug":"i-smail-haki-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sabah-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanımdamısın?', 'yanimdamisin-mehmet-ali-kepez-20fxn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sarp kayada çekirgeye benzerdin

	Poyraz gibi kırat ile tozardın

	Nerde çağırınca orda hazırdın

	Şimdi yolsuzların yanındamısın

	Yerdiğin şeyleri alıp satmışsın

	Döşek beğenmezdin yerde yatmışsın

	Ne diye vatana dönmem demişsin

	Yoksa firavun un inindemisin

	Balıklar baliğa yem olur yerler

	Gurbette çakkalla aslan ezerler

	Gùnbe gùn çamura batıyor derler

	Aklın gitmiş şimdi canındamısın

	Biraktığın yerde baykuş ötüyor

	Zorbalarr köyùnù yakıp, yıkıyor

	Gel artık siperler seni bekliyor

                De hele kepezin yanında mısın', 'Sarp kayada çekirgeye benzerdin 	Poyraz gibi kırat ile tozardın 	Nerde çağırınca orda hazırdın 	Şimdi yolsuzların yanındamısın 	Yerdiğin şey...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanimdamisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeller esecek', 'yeller-esecek-mehmet-ali-kepez-exem8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derdim çoktur aman, aman

	Gurbette özlem pek yaman

	Dost dönùp geldigin zaman

	Yerimde yeller esecek

	Hiçmi görmùyon rùyada

	Gönlùn sert imiş kayada

	Ölùmlù koca dùnyada

	Ne vardı böyle kùsecek

	Mevsim geçer gùller solar

	Sayılı gùn çabuk dolar

	Bağlanınca çene, kollar

	Payımıza ne  dùşecek', 'Derdim çoktur aman, aman 	Gurbette özlem pek yaman 	Dost dönùp geldigin zaman 	Yerimde yeller esecek 	Hiçmi görmùyon rùyada 	Gönlùn sert imi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeller-esecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simdi ben', 'simdi-ben-mehmet-ali-kepez-qj44h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dagin basi duman oldu gorùnmez

	dag sislerde basim dert te arinmaz

	serçe bile artik burda barinmaz

	yikilmis koyùmùn çevligindeyim

	bir yola gidilmez sapilmak için

	gorùnmez seylere tapinmak niçin

	orak çekiç yildiz yapilmak içn

	seçilmis demirin tavligindayim

	bilimle ilimle girdik bu yola

	bakma simdi firtinali havaya

	takimi olmayan dùmdùz ovaya

	saçilmis tohumun evlegindeyim', 'dagin basi duman oldu gorùnmez 	dag sislerde basim dert te arinmaz 	serçe bile artik burda barinmaz 	yikilmis koyùmùn çevligindeyim 	bir yol...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/simdi-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaylalar', 'yaylalar-mehmet-ali-kepez-nv24e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Serin eser yaylaların havası

	Gözùm, gönlùm sende kaldı yaylalar

	İçimi yakıyor yayla hevesi

	Làle, sùmbùl, çiğdem dolu yaylalar

	Çoban''in elinde bir dertli kaval

	Uzun bir hava ki çal bire haval

	Kayadan kayaya sıçrardım evel

	Sorma hiç halimi noldu yaylalar

	İçerime hùzùn doldu yaylalar

	Koyaklari benek, benek kar şimdi

	Kara gözlù emlik kuzum var şimdi

	Kepez''in etrafı gayet dar şimdi

	Hùrriyetim tutsak oldu yaylalar', 'Serin eser yaylaların havası 	Gözùm, gönlùm sende kaldı yaylalar 	İçimi yakıyor yayla hevesi 	Làle, sùmbùl, çiğdem dolu yaylalar 	Çoban''in e...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaylalar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soba', 'soba-mehmet-ali-kepez-2m4ez', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toprak damim sipir sipir

	bakir legene damliyor

	yùregimiz kipir, kipir

	gok yùzù gùm, gùm''lùyor

	herkes bùrùnmùs abaya

	kimi duyarsiz çabaya

	tezek doldurduk sobaya

	gaz doktùk yine yanmiyor

	adimiz çikti kotùye

	dordùmùz cikti çatiya

	bacamiz dondù batiya

	teneke soba yanmiyor

	kimi soguga alisti

	kimi yakmaya çalisti

	sagir sobamis alisti

	ceyhani doksen sonmùyor', 'Toprak damim sipir sipir 	bakir legene damliyor 	yùregimiz kipir, kipir 	gok yùzù gùm, gùm''lùyor 	herkes bùrùnmùs abaya 	kimi duyarsiz çabay...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana yanar', 'sana-yanar-mehmet-ali-kepez-6prsi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yùrağimde bir yaravar

	Kanar, kanar sana kanar

	Ateştadir yar bedenim

	Yanar, yanar sana yanar

	Göreceğim gùn kalmadı

	çok sevdiğim anlamadı

	Gideceğim yön kalmadı

	Döner, döner sana döner

	Aklımdasın uyusamda

	Gùlmez bana ne desemde

	Can alıcı baş ucumda

	Döner, döner cana döner', 'Yùrağimde bir yaravar 	Kanar, kanar sana kanar 	Ateştadir yar bedenim 	Yanar, yanar sana yanar 	Göreceğim gùn kalmadı 	çok sevdiğim anlamadı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-yanar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrùm''e', 'omr-m-e-mehmet-ali-kepez-ls903', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vay benim ziyan ömrùme

	Boş harmanı savurmuşum

	Yar oldu kıyan ömrùme

 	Ben ne kadar severmişim

	Aklımı verdim periye

	Bilmeden yönùm nereye

	Bir dönùp baktım geriye

	Koca yıllar devirmişim

	Her kusuru hoş görerek

	Duygusuza baş vurarak

	Yangınıma boş vererek

	Yùreğimi kavurmuşum

	Ben akılda fıkarayım

	Yaklaştı gùnlerim, ayım

	Mercan, zùmrùttù sarayım

	Harabaya çevirmişim', 'Vay benim ziyan ömrùme 	Boş harmanı savurmuşum 	Yar oldu kıyan ömrùme  	Ben ne kadar severmişim 	Aklımı verdim periye 	Bilmeden yönùm nereye...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/omrum-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekonomik kriz', 'ekonomik-kriz-mehmet-ali-kepez-1qsuc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arasan bulunmaz bir yerli malı

	Belçika satıyor Konyada halı

	Japonya da gelir itlerin yalı

	Neden çıktı bu ekomok kriz

	işcisi köylùsù hepimiz biriz

	Mecliste köfte yap uyu sen uyu

	Önùne eşilmiş derin bir kuyu

	Dùkkanda satılır frasız suyu

	Nerden çıktı   ekonomik kriz

	Alavi sùnùsù hepimiz biriz

	çocuklar içiyor şimdi marlbora

	Köylùyù çevirdin kevgir halbura

	Ne sazımız kaldı ne kısa cura

	Ekonomik kriz nerede çıktıi

	isciler, köylùler yaşamda bıktı

	Otobùs alırsın demiryol yapman

	Göbekte bağlısın u s a   da bıkman

	El fùze yaparken sen bir pul yapman

	Kriz kiriz ekomik kriz

	Bizi sanma dostum bu kadar keriz

	Gùmrùklerin kapısını  kıran siz

	Devlet kasasını çalıp doyan siz

	Bağımsızlık isteyeni vuran siz

	Neden çıkıyor ekonomik kriz

	Doğusu batısı hepimiz biriz

	Tùrkiyede Tùrkçe konuşulmuyor

	Kriz içmizde kimse bilmiyor

	Böyle kriz ABD ye gelmiyor

                Bizimkiler sanki bunu bilmiyor

              

                Baş bakan baş bakan bizim baş bakan

	isçiye, köylùye gözù şaş bakan 

	Fakir fukaranın elini  yakan

	Kriz, kriz ekomik kiriz

	Kùrdù Tùrkù hepimiz biriz

	Aman ha ithal et sakın ùretme

	Bu milleti boş boşuna çùrùtme

	Avrupanın çıkarını  yùrùtme

	Birde dersin Kriz çok komik kriz

	i m f de aldıkların çeteye

	senin canin cehennem de öteye

	bizi böyle köle ettin batıya

	kriz, kriz hepimiz körùz

	Tùrkiye de yaşamanın tadı yok

	Millet varda milliyetin adı yok

	Koca bùtçe kim yediyse yedi yok

	Nerde çıktı ekomoik kriz

	Yalvardik, yakardık bak i m f ye

	Biri attı gitti yine kefeye

	Laf atmadık uysun diye kafiye 

	Kriz krizz ekomik  kriz

	Yùz milyar dolari yedi iç savaş

	Dağları  tùketir sel yavaş yavaş

	Bölersen, kùrt, tùrk sùnni kizilbaş

	Nasıl çıkıyor ekonomik kriz

	Ellerin elinde atın yuları

	Boş boşuna akar zemzem suları

	Neme gerek sam amcanın doları

	Kriz keriz körùz  biriz  sürünürüz

	Borç alınca sözùmùz de geçmiyor

	Vekilleri millet bulup seçmiyor

	Amerika siç demese siçmiyor 

	Kriz işte bu komik Kriz

	Devlet kasasını çeteler vurmuş

	Marka giyer oldu sonrada görmùş

	Yolsuz köye coca colası  girmiş

	Ekonomik kiriz ne kadar körùz

	Avrupanın sirketleri kök saldı

	Kaldıysa bizlere köşkerlik kaldı

	Neyimiz var ise ABD çaldı

	Nerde çıktıi yahu ekomik kriz

	halla halla! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! 

	Dışarıda gelir bùtùn ilacın

	Ne kadar paradır bir yıllık hac''ın

	Kalmadı iyneyi alacak gùcùn

	Nerde çıktı bu ekomik kiriz

	incirle, ùzùmle millet tok olmaz

	Bağımsızlık isteyenler yok olmaz

	Sizden uşak olur başaka sey olmaz

	Nerde çıktı birden ekomik, kriz

	Ne alırsan sende ona bir şey sat

	Nede diyorsunki işlerim kesat

	Hesabın bilmeyen kasapta masat

	Ekomik kriz ne kadar köruz 

	Alevi Sùnnùsù hepimiz biriz

	Fıkaranın neyi kalmış canı  bu

	Sömùrgeyiz satmıyoruz konu bu

	Uretmezsen tùketirsen sonu bu

	Birde diyorsunki ekomik kiriz

        Sanmaki bu kadar àmàyız körùz', 'Arasan bulunmaz bir yerli malı 	Belçika satıyor Konyada halı 	Japonya da gelir itlerin yalı 	Neden çıktı bu ekomok kriz 	işcisi köylùsù hepi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/ekonomik-kriz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem firarisi', 'cehennem-firarisi-mehmet-ali-kepez-7ehz9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz davet etmeden geldi buyurdu

	Biraz kaldı  sohbetiyle doyurdu

	Zabaniler seni nasıI koyurdu

	Yoksa cehennemde firarmı  ettin

	Bin sene mağrada yatmış uyumuş

	Uyanır uyanmaz benimi bulmuş

	İnsan sıfatını şeytanda çalmış

	Vampirle ortaktın zararmı ettin', 'Biz davet etmeden geldi buyurdu 	Biraz kaldı  sohbetiyle doyurdu 	Zabaniler seni nasıI koyurdu 	Yoksa cehennemde firarmı  ettin 	Bin sene ma...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cehennem-firarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenci', 'dilenci-mehmet-ali-kepez-k45g2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gazeteyi döşek etmiş altına

	Damlalar buz tutmuş bak suratına

	Yalvarır her sabah Tanrı katına

	Benide kulunda say nolur diye

	Aylardır kirlenmiş yıkanmaz yaka

	Düştükçe utanır yere sadaka

	Teneke de çatmış bir göz baraka

	Muska yapmış saray sayılır diye

	Pazarda gizlice birşey  seçiyor

	Zabıta da suçlu gibi kaçiyor

	Aç iken camide bol su içiyor

	Kandırır miydeyi doyulur diye

	Sürünen ler ne çok yaşarmış

	Tanrıda düşünce vurun be dermiş

	Her seçimde umutları yeşermiş

	Gelen baskan bizi kayırır diye', 'Gazeteyi döşek etmiş altına 	Damlalar buz tutmuş bak suratına 	Yalvarır her sabah Tanrı katına 	Benide kulunda say nolur diye 	Aylardır kirl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dilenci-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak kanasın', 'birak-kanasin-mehmet-ali-kepez-sg1my', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En sonuncu dalımdın sen

	Sende kırıdın tutunamadan

	Çekeceğim en dayanılmaz acı bu

	Yok artık dayanmaz buna yüreyim

	Bırak kanasın çarpabildiği kadar

                İki iki daha dört eder', 'En sonuncu dalımdın sen 	Sende kırıdın tutunamadan 	Çekeceğim en dayanılmaz acı bu 	Yok artık dayanmaz buna yüreyim 	Bırak kanasın çarpabild...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/birak-kanasin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerek', 'gerek-mehmet-ali-kepez-jgroh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bülbül''e derdin dökecek

Has bahçenin gülü gerek

Dünya nın kahrın çekecek

Benim gibi deli gerek

Tutuşturdu nara beni

Attı bir kenara beni

Çekmek için dàra beni

Yar zülfünün teli gerek

Gelmişim ben sürünmeye

Anam bu hakim görmeye

Yangınımı söndürmeye

Sarsap çayın seli gerek

Kanayan yüreğim gelki

Görünce ferahlar belki

Neylerim ben, malı, mülkü

Dostun  tatlı dili gerek', 'Bülbül''e derdin dökecek Has bahçenin gülü gerek Dünya nın kahrın çekecek Benim gibi deli gerek Tutuşturdu nara beni Attı bir kenara beni Çek...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gerek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fatih', 'fatih-mehmet-ali-kepez-z2a79', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zifiri bir karanlıkta

	Yıldız gibi aktı gitti

	Unutuldu bence çokta

	İçimizde çıktı gitti

	O candan içeri candı

	O hep emeğe inandı

	O yoldaş Fatih Dönen''di

	Onun gibi yoktu gitti

	Zalim kaçardı o varken

       Vurdular yolda giderken

	Canı bedende çıkarken

	Kor güneşe baktı gitti

	Sığarmıydın hiç Erzine

	Kimler vurmadı dizine

	İskenderun körfezine

	Al kanını döktü gitti', 'Zifiri bir karanlıkta 	Yıldız gibi aktı gitti 	Unutuldu bence çokta 	İçimizde çıktı gitti 	O candan içeri candı 	O hep emeğe inandı 	O yolda...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fatih-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konamazsın', 'konamazsin-mehmet-ali-kepez-7c8da', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umutlan ma, umutlan ma

	Geldin artık dönemezsin

	Bir sefer tutuşup yanma

	Ömür biter sönemezsin

	Gurbet elde kaldın darda

	Dost, ahpaplar hani nerde

	Tireni kaçırdın garda

	Çabalama binemezsin

	Yel esse yıkıyor seni

	Toprağın çekiyor seni

	Harap etti o yar seni	 

	Yar felekte yanamısın

	Kanat çırpıp heves ettim

	Güle, bülbüle ses ettim

	Bin kere tövbe pes ettim

	Sen bir dala konamazsın

	Yandın daha yanamazsın', 'Umutlan ma, umutlan ma 	Geldin artık dönemezsin 	Bir sefer tutuşup yanma 	Ömür biter sönemezsin 	Gurbet elde kaldın darda 	Dost, ahpaplar ha...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/konamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahrol dünya', 'kahrol-dunya-necat-gundem-5q1tk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bin zehrini saçtın yine

Çocukların bebelerin üstüne

Özgürlük diye

Elleri balda değil diye

Aç bedenlere

Ölüm ağır gelirken

Gökyüzünden

Ölüm yağdırdın

Rahmet yağmurlarını 

bile kıskandırdın

Hem öldürdün

Hem acıdın

Ve de seyrettin

Seyrettin

Seyrettin

Yetmedi mi 

Tekrar baştan

Ölenler

Tekrar ölemezken

öldürüverdin

Tek tek

Petrole bulanmış her canı

Kuşu, otu, ağacı

Seyir keyfin kaçmasın yeter ki.

Kahrol dünya e mi.



28 AĞUSTOS 2003', 'Bin zehrini saçtın yine Çocukların bebelerin üstüne Özgürlük diye Elleri balda değil diye Aç bedenlere Ölüm ağır gelirken Gökyüzünden Ölüm y...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kahrol-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemler Marş Marş', 'kalemler-mars-mars-necat-gundem-bqulr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalemler marş marş

Dizilin sıraya

Haydi bakalım

Sol sağ

Sol sağ

Veya

Rap rap

Rap rap

Ama nereye

Durun dedim size

Barışı 

Kağıda yazmadan

Öyle kaytarmak niye

Kalemler marş marş

Omuzlar dik

Başlar yukarı

Sol sağ

Sol sağ

Veya 

Rap rap

Rap rap

Ama nereye

Duru dedim size

Sevgiyi 

Kağıda yazmadan

Öyle kaytarmak niye

Durmayın tembelleşmeyin

Karanlıklar tembel değil çünkü

Barış ve sevgiyi

Karalayın kağıda

Mürekkep mi kara

Hadi onu da akça yazarcasına

Peki ya sonra

Karanlıklar dağıldığında

Güneşin merhabasını işittiğinizde

Hemen istirahatgahınıza.

 1988', 'Kalemler marş marş Dizilin sıraya Haydi bakalım Sol sağ Sol sağ Veya Rap rap Rap rap Ama nereye Durun dedim size Barışı  Kağıda yazmadan Öyl...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kalemler-mars-mars-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin İsyanı', 'sairin-i-syani-necat-gundem-nzdm6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şairin isyanıdır bu

Korktuğu ölüme

Küstüğü sevgiye

Özlediği yeşile

Hitaben.



Şairin isyanıdır bu

Yarınsız dakikalara

Mektubu gelmeyen yare

Afrikalı küçüğün açlığına

Çocuk öldüren savaşlara

O suskun orkestraya

Ve de kısır uykulara

Hitaben.



Şairin isyanıdır bu

Böylesi

Karamsar şiirlere

Hitaben.', 'Şairin isyanıdır bu Korktuğu ölüme Küstüğü sevgiye Özlediği yeşile Hitaben. Şairin isyanıdır bu Yarınsız dakikalara Mektubu gelmeyen yare Af...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sairin-isyani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tozu gerçek rengi hayal umutlarım', 'tozu-gercek-rengi-hayal-umutlarim-necat-gundem-zcifv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gerçekleştiremediğim umutlarıma

Gecenin sessizliğinde

Verdiğim konserin

Kansere dönüşeceğini

Ne bilebilirdim ki.



Gerçekleştiremediğim umutlarıma

Sabahın köründe

Yazdığım şiirlerin

İntikamcı olacağını

Zamanımı çalacağını

Ne bilebilirdim ki.



Gerçekleştiremediğim umutlarıma

Baykuşların ötüş saatinde

Vaat ettiğim sözlerin

Göz çıkaracağını 

Ne bilebilirdim ki.



Ama gelin görün ki

Tozu gerçek rengi hayal

Umutlarım

Suçsuzluğuma

Bir türlü inanmıyor ki.



30.7.1990', 'Gerçekleştiremediğim umutlarıma Gecenin sessizliğinde Verdiğim konserin Kansere dönüşeceğini Ne bilebilirdim ki. Gerçekleştiremediğim umutla...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tozu-gercek-rengi-hayal-umutlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak', 'uzak-necat-gundem-nxbgl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin uzak

Gözlerim bakışlarında boğulduğunda

Sözlerin uzak

Yüreğimi her kelimesiyle yaktığında

Ellerin uzak

Ellerimi sımsıkı sardığını sandığımda

O zalim hasretin var ya

Yüzde yüz

Bana tuzak

Ölümün ardına takılıverdiğinde.

10.09.2003', 'Gözlerin uzak Gözlerim bakışlarında boğulduğunda Sözlerin uzak Yüreğimi her kelimesiyle yaktığında Ellerin uzak Ellerimi sımsıkı sardığını s...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uzak-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umrumda değil', 'umrumda-degil-necat-gundem-ctls5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş beni selamsız bırakmazken

Her yeni gün bensiz başlamazken

Sevgi şiirlerinin cesur mısralarında 

Dolaşmadan yaşayamazken ben

Bir karıncayı bile incitemezken ben

Ve yüreğim her şeye 

Özellikle de sana dair sevgi coşkunluğundayken

Duymuşum ki

Dargın kalmış yüreğin benden

Selamından mahrum kalacakmışım

Ömrümün geri kalan günü boyunca

Umrumda değil

Unutma ki 

Yüreğim de grev ilan eder

Sevgisiz bırakır seni

Sevgini kazanacağı güne kadar.

13.09.2003 - Batman', 'Güneş beni selamsız bırakmazken Her yeni gün bensiz başlamazken Sevgi şiirlerinin cesur mısralarında  Dolaşmadan yaşayamazken ben Bir karınc...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/umrumda-degil-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Sensiz', 'sensiz-sensiz-mehmet-sait-simdi-2-p7eft', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte yine gidiyorsun, 

“Baş” geçecek sensiz, sensiz.

Günü zehir ediyorsun, 

“Aş” geçecek sensiz, sensiz...

Sensiz bıraktın giderek, 

Ayrılığa var mı gerek? 

Gidişinle buruk yürek, 

“Taş” geçecek sensiz, sensiz...

Senle mana, bulur sözüm, 

Mutlu dünyam, gülen yüzüm, 

Korkarım ki iki gözüm, 

“Yaş” geçecek sensiz, sensiz...

Bu ayrılık can yakacak, 

Derdin ateş, aşkın ocak, 

Gözüm nereye bakacak, 

“Boş” geçecek sensiz sensiz...', 'İşte yine gidiyorsun,  “Baş” geçecek sensiz, sensiz. Günü zehir ediyorsun,  “Aş” geçecek sensiz, sensiz... Sensiz bıraktın giderek,  Ayrılığ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Şimdi 2']::text[], 8.5, '{"poet":"Mehmet Sait Şimdi 2","poet_slug":"mehmet-sait-simdi-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensiz-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nikah...', 'nikah-mehmet-sait-simdi-2-ocqw7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir imza, 

Bir yüzük, 

Mutluyuz...Evlendik...

Bir pasta, 

Bir düğün, 

Aşkımız kördüğüm..

On günlük balayı, 

Bitirdik üç ayı, 

Şimdilik çok iyi, 

Yanlış bir seçim, 

Mümkün mü geçim, 

Maalesef..! canım, cicim....

Zor geçer iklimler, 

Psikolog, hekimler, 

Ve...Merhaba..Hakimler..

Sahi..”Biz ne olacağız biz”

Mümkün değilse evliliğimiz, 

Halka olsun sevgimiz..

Ellerini, ellerime, 

Gözlerimi gözlerine bağladım..

Yüreğimi yüreğine nikahladım....', 'Bir imza,  Bir yüzük,  Mutluyuz...Evlendik... Bir pasta,  Bir düğün,  Aşkımız kördüğüm.. On günlük balayı,  Bitirdik üç ayı,  Şimdilik çok i...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Şimdi 2']::text[], 8.5, '{"poet":"Mehmet Sait Şimdi 2","poet_slug":"mehmet-sait-simdi-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nikah-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş Zor...', 'donus-zor-mehmet-sait-simdi-2-t71np', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana Gelmek, 

Seni Görmek

Senin Olmak...

Ellerini tutmak, 

Saçlarının Okşamak, 

Gözlerinin Ateşi, 

Boynuna Sarılmak

Göz Göze Bakışmak

Teninin Kokusu

Her şey Güzelde....

Seni Bir Yalnız Başına

Bırakıp 

Geri Dönmek

Gücüme Gidiyor....', 'Sana Gelmek,  Seni Görmek Senin Olmak... Ellerini tutmak,  Saçlarının Okşamak,  Gözlerinin Ateşi,  Boynuna Sarılmak Göz Göze Bakışmak Tenini...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Şimdi 2']::text[], 8.5, '{"poet":"Mehmet Sait Şimdi 2","poet_slug":"mehmet-sait-simdi-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/donus-zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Izdırap', 'izdirap-ahmet-turan-altunsu-ggx13', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaldırsam şu başımı ölümü görmekteyim, 

İndirsem şu başımı, ölümü özlemekte....

Kolay mı derde düşmek, dertle iç içe kalıp, 

Uçmağın kapısını dertle düşlemekteyim! ..

Beni hayallerimden ettiğin yetmez gibi; 

Sana ait ne varsa bir bir yitirmekteyim! ..

Kaldırsam şu başımı ölümü görmekteyim, 

İndirsem şu başımı, ölümü özlemekte...

Kolay mı derde düşmek, dertle iç içe kalıp, 

Her gün bir kerre daha bin kerre ölmekteyim.

                                      A.Turan Altunsu (13.09.2003) 

                                                                    Ankara', 'Kaldırsam şu başımı ölümü görmekteyim,  İndirsem şu başımı, ölümü özlemekte.... Kolay mı derde düşmek, dertle iç içe kalıp,  Uçmağın kapısın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/izdirap-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küskündür Sana Küllerim', 'kuskundur-sana-kullerim-ahmet-aksoy-8srk4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küskündür sana küllerim, 

Artık yakmak için bile 

Hatırlamadığından.

Bir nefes arasında bile

Geçmediğinden, 

Gözlerinden gölgem, 

Kırıktır küllerim.

Oysa ben, 

Hektarlarımı sende yitirdim, 

Bir kış günü, 

Bir yaz yangınıyla, 

Ki artık ciğersizim.

Buruktur sana yüreğim

Sana olan haykırışlarına

Dönüp bakmadığından

Bir çölün ortasında, 

Rüzgarsız bir, 

Gece sessizliğinde bile

İrkilmediğinden

Oysa ben, 

Damarlarımdan sana, 

Tel tel duvaklar ördüm, 

Kırmızıyı sevdiğinden, 

Ki artık damarsızım.

Ve sen; 

Duymayan, hatırlamayan

Mümkün müdür ki 

Hatırlamıyor olasın

Senden aldıklarımı

Sana verdiklerimi

Aşkımı, aşkını, 

Sevgimi, sevgini.

Ki almadığını, vermediğini 

Söyleyebilirsin.

Çoğu davalıdan

Beklendiği gibi

Ama sana son verdiğim

Son sözüm üzerine olsun ki

Sanma ki hukuk yanılır ahrette, 

Bilesin....', 'Küskündür sana küllerim,  Artık yakmak için bile  Hatırlamadığından. Bir nefes arasında bile Geçmediğinden,  Gözlerinden gölgem,  Kırıktır k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kuskundur-sana-kullerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılan (Acınılamaz)', 'yikilan-acinilamaz-ahmet-aksoy-iow2j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıkılan bir sur değil elbet

Üflenen bir sur değil

“Çözümsüz”, bitmişlik 

Ya da bitmemişlik

Ayakta duran, gölge değil elbet

Işığın bedeni yoktur

Sadece ateşin yalımları

“Dikilen” vücutsuz birey

Son pencere açılmadı elbet, 

Sonunu gören sadece, tek

İşte bu yüzden; ezici çoğunluk

Çullanıyor, tek olana

“Linç” kapılar bir kez açıldı ya

Kilit yoktur zincirden boşalana

Yıkılan bir kez yıkıldı ya 

Uçsuz bir doğrudur keder

Umut, 

Tekmeyi yemiş bir sehpa

Bedeni et bedeni kemik

Açık bir göğüs her kurşuna

Ve yıkılan; 

Ne son ne de ilk kez

Sıyrılmış dünyadan

Gölgesiz, sarhoş...

“Acınılamaz”.', 'Yıkılan bir sur değil elbet Üflenen bir sur değil “Çözümsüz”, bitmişlik  Ya da bitmemişlik Ayakta duran, gölge değil elbet Işığın bedeni yok...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yikilan-acinilamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiirde Sevdim Seni', 'bir-siirde-sevdim-seni-muammer-celik-ipvk9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne idi o Allah aşkına 

gözlerimi fal taşı gibi açan 

yüreğime şimşek gibi çakan 

gönlümde gökkuşağı gibi açan? 

Ne elin vardı dokunacak 

ne gözlerin vardı bakacak! 

dizelerde yazılı idi 

duygularında belli idi 

senin beni 

benim seni 

ezelden beri 

ruhlar aleminde 

sevdiğimiz, seviştiğimiz… 

Ne şeklin vardı düşleyecek 

ne resmin vardı etkileyecek! 

şiirde yazılı idi 

düşlerinden belli idi 

gözlerinde pırıltı 

gönlünde aşk şerbeti 

Yüreğinde bir kıvılcım vardı 

aklım ermiyor hala, 

beni benden nasıl aldı… 

Kuşağında kırk düğümle 

bogazında kırk boğumla 

dilinde prangalar 

içinde el değmemiş 

kadınla tanıdım, bildim, 

seni ”SEN” olduğun için 

aşık olup, sevdim… 

Bir Şiirde okumuştum seni 

bin şiirde yazdım 

binbir gece düşümde gördüm seni 

buradan oraya kadar, 

oradan buraya kadar 

sevdim ve seviyorum seni… 

şimdi…; 

Efil efil esiyor BirDeli gönlüm 

sevda yellerinde 

Elif Elif, zülüf zülüf okşuyorum 

saçlarını ellerimde...

Muammer Çelik', 'Ne idi o Allah aşkına  gözlerimi fal taşı gibi açan  yüreğime şimşek gibi çakan  gönlümde gökkuşağı gibi açan?  Ne elin vardı dokunacak  ne ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bir-siirde-sevdim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk…', 'cocuk-muammer-celik-2qxr8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani sen uçurtmamı 

almıştın elimden 

göklere salıvermiştin 

koparıp yüreğimden… 

”uçurtma özgürlük” demiştin 

ben daha fazla zırlamıştım 

ayaklarımı yere vurarak 

„özgürlüğümü kaçırdın elimden“ demiştim …! 

İşte böylesi bir çocukluk aşkımız 

vardı aramızda beraber yaşadığımız...! 

Büyüdük de ne oldu? 

Sana çok şey oldu, 

evlendin, 

çoluk çocuğun oldu…! 

Bense hiç bir şey olmadım 

hala çocuğum, çocuk kaldım…

Muammer Çelik 

20.08.2003', 'Hani sen uçurtmamı  almıştın elimden  göklere salıvermiştin  koparıp yüreğimden…  ”uçurtma özgürlük” demiştin  ben daha fazla zırlamıştım  a...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cocuk-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakamayacağımsın benim…', 'birakamayacagimsin-benim-muammer-celik-xaexn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siyah beyazdı bu dünya 

seni tanıyıncaya kadar..! 

Boyadım gözbebeklerimi ışıl mışıl senin renklerinle 

Işıttım dünyalarımı, gecelerimi renkli renkli bakışınla..! 

Sen ”Bin yıllık Şiir''im 

sen ”İçimden Dışıma Seyehat''im 

Sen benim ”Alışkanlık”ımsın bırakamadığım…! 

Muammer Çelik 

15.08.2003', 'Siyah beyazdı bu dünya  seni tanıyıncaya kadar..!  Boyadım gözbebeklerimi ışıl mışıl senin renklerinle  Işıttım dünyalarımı, gecelerimi renk...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/birakamayacagimsin-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgı', 'yanilgi-muammer-celik-9kh6h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bende boşverdim arkadaşım 

sana sevgilimsin diyen şarkılarımı 

şiirlerim, duygularım, içimdeki sevgilimi... 

Yanılmışlar hepsi birden topyekün 

yanıltmışlar birde beni yetmemiş gibi 

Bir yanılgıdır akıp gidiyor zaman gibi

sağımdan solumdan geciyor sürü gibi… 

Bir yanılgıdır ki, beni sana deli ediyor..! 

Bir yanılgıdır varlığın, 

Bir yanılgıdır en çok ta benim varlığım… 

Say ki, yokum 

say ki, sen hiç yoksun.… 

Böylece darma dağınık kalsın... 

Bırak yanılgı ise de bende kalsın..! 

Muammer Çelik 

14.08.2003', 'Bende boşverdim arkadaşım  sana sevgilimsin diyen şarkılarımı  şiirlerim, duygularım, içimdeki sevgilimi...  Yanılmışlar hepsi birden topyek...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanilgi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teller ve Kelebekler', 'teller-ve-kelebekler-i-lyas-sahin-5wu9f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Teller ah teller! teller getirir daha çok haberleri

Oysa ki haberleşmemiz yürekten, yüreğe olmalıydı

Yürek alıcımızda bir problem olsa gerek

Sinyaller devamlı geliyor ama yürek...

Teller daha çok acınızı iletiyorlar

Çok küçük aralarda da gülümseyen gül yüzünüzü 

Anlıyoruz yaşıyorsunuz karanlığı değil gündüzü

Tellerden yine haber var.Kelebeklerden

Haber sıkıyor bedenimi kelepçe misali

Gözkapaklarım kapan komutuna uymuyor gibi yarı açık

Duyargalarım pür dikkat tıkaçlarına rağmen

Gözyaşlarım rahatlatıyor beni demek ki ağlamamalıyım 

Rahatlık=duyarsızlık

Gözyaşlarınız rahatlatıyorsa sizi lütfen ağlayın

Rahatlığınız=genelde anlık

Tellerden kaçmalı sorumluluk yüklüyor

Mümkün değil her zaman yakalıyor 

ve sorumluluk

Tellere bağımlıyım her şeye rağmen

Ta ki yürek alıcısını onarana değin

Sinyaller ulaştığında yüreğe kesintisiz

Tuğlalar yerinde saf tuttuğunda ve binamız', 'Teller ah teller! teller getirir daha çok haberleri Oysa ki haberleşmemiz yürekten, yüreğe olmalıydı Yürek alıcımızda bir problem olsa gerek...', ARRAY['Türk Edebiyatı','Şiir','İlyas Şahin']::text[], 8.5, '{"poet":"İlyas Şahin","poet_slug":"i-lyas-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/teller-ve-kelebekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir lahzalık Hürriyet', 'bir-lahzalik-hurriyet-i-lyas-sahin-xfs4i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sıkılmıştı artık çıkmalıydı, yetmeliydi beklediği

Zamanı geldi, çirkinlik sona erdi

Yırtıldı koza, aman Allah’ım bu kimdi! 

Özgürdü artık ama farkında değildi

Ömür bitti ölüm geldi

Diğerlerine haber vermeliydi

Kısacıkta olsa hür olmak ne güzeldi

Karanlığın içindeki aydınlığı farketti

Hızla çırptı kanatçıklarını yetişmeliydi, özlemiydi

Bir lahzalık yaşamın hakikatini keşfetmişti

Aydınlığın devamı için yanmak gerekliydi

Külleri el salladı selamladı bizleri

Yırtın kozalarınızı dedi zamanı geldi

Kelebek olmak gerçekten de güzeldi', 'Sıkılmıştı artık çıkmalıydı, yetmeliydi beklediği Zamanı geldi, çirkinlik sona erdi Yırtıldı koza, aman Allah’ım bu kimdi!  Özgürdü artık am...', ARRAY['Türk Edebiyatı','Şiir','İlyas Şahin']::text[], 8.5, '{"poet":"İlyas Şahin","poet_slug":"i-lyas-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-lahzalik-hurriyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galiba', 'galiba-yasar-aslan-g2sw6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soluk alışlarım derinleşsede günden güne

En güzel çiçeklere verdiştim ismini

Ricayla karışık sevgiyle büyüttüm seni

Ya sevgileşmiş anne 

Ya anneleşmiş sevgilim oldun

Tuza bandırdığım soğanım 

Yada ekmeğim oldun 

Sonramı ne oldun

Bir yabancıdan öte 

Dosttan az 

Sadece birisi oldun.!', 'Soluk alışlarım derinleşsede günden güne En güzel çiçeklere verdiştim ismini Ricayla karışık sevgiyle büyüttüm seni Ya sevgileşmiş anne  Ya ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/galiba-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Sesleniyorum', 'sana-sesleniyorum-sair-moda-pse5a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deniz kıyısından

Başka bir ülkeye

Başka bir ülkeden

Sena sesleniyorum.

Gökyüzünden

Başka bir ülkeye

Başka bir ülkeden

Sana sesleniyorum.

Dağlardan

Başka bir ülkeye

Başka bir ülkeden

Sana sesleniyorum.

Dağların tepesinde

Rügârın sesiyle

Dalgaların içinde

Sana sesleniyorum.

Bir pencerenin kenarından

Saksıların ağzından

Çiçeklerin içinden

Sana sesleniyorum.

Belki bir zindandan

Bir kuşla

Kanatların altından

Sana sesleniyorum.

Belki bir okuldan

Mürekkeple yazılmış

Bir kâğıttan

Sana sesleniyorum.

Belki Ay''dan

Kimbilir

Belki de Mars''tan

Sana sesleniyorum. 

Bir çay molasında

Belki de coşkulu, güzel

Bir resimden

Sana sesleniyorum.

Belki de şimdiki gibi...

Zor, ama çok zor

Bir şiirden

Sana sesleniyorum.

Bir öyküde

Belki bir kurt

Belki de bir kuş olarak

Sana sesleniyorum.

Bir bahçeden

Bir gölden

Gökyüzünden

Sana sesleniyorum.

Vazodaki şekilden

Çiçek poleninden

Çocukluk sevincimle

Sana sesleniyorum.

Bir bahçenin içinde

Yaprakların sesiyle

Çocukların gülüşüyle

Sana sesleniyorum.', 'Deniz kıyısından Başka bir ülkeye Başka bir ülkeden Sena sesleniyorum. Gökyüzünden Başka bir ülkeye Başka bir ülkeden Sana sesleniyorum. Dağ...', ARRAY['Türk Edebiyatı','Şiir','Şair Moda']::text[], 8.5, '{"poet":"Şair Moda","poet_slug":"sair-moda","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sana-sesleniyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-mustafa-gideroglu-1qbfg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Korku vapurda gelen

Hava yapmış bir deniz

Onu yarmaya çabalayan bir vapur.

Ağlayan korkan kadınlar

Olayı espri yapan, cesurluk maskesi giymiş erkek tipleri

Farkında olmayan biri

Martılar her şeyi boş vermiş, balık peşinde

Ufak hesaplar peşinde kişiler

Ufak hayalleriyle, 

araba, eğlence daha ne? 

Yıpranırcasına çabalama

Karın tokluğuna

Martılar her şeyi boş vermiş

Denizde balık aramakta

Düdük sesleri insanları telaşlandırmakta

Ufak hayallerle dolu vapur

Ağır ağır karşıya yolalıyor.

Martılar her şeyi boş vermiş

Denize öylecesine bağlanmış

Olduğu gibi

Yaşamları ondan..

Nasıl ölümleri ondansa? 

Martılarla aynı kaderin yolcuları yüzleşmekte', 'Korku vapurda gelen Hava yapmış bir deniz Onu yarmaya çabalayan bir vapur. Ağlayan korkan kadınlar Olayı espri yapan, cesurluk maskesi giymi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gideroğlu']::text[], 8.5, '{"poet":"Mustafa Gideroğlu","poet_slug":"mustafa-gideroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/korku-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolunay Kabarması', 'dolunay-kabarmasi-naime-erlacin-jxc1z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gecelerden 

dolunay bu gece

gökyüzünde hırsız var 

soyuluyor gök çırılçıplak 

geç kalmış bir duygu hakim

kapatıyorum gözlerimi

kendimi kaçırıyorum geceden

ay delice koşuyor gökyüzü öksüzlüğünde

-köşede bir köpek ağlamakta

nedir bu yalnızlık...bu melankoli

içinde dolaşık kaldığım hüzün

terk edilmişlik hissi

''insem'' diyorum sokağa

sarışsak köpekle 

sığınsak birbirimize

hayal işte! 

ışıklar sönüyor 

kanıyor ev içleri

o eski gramofonda takılmış içli bir hasret şarkısıyım

tenimde derin bir soluk alış ve ıssızlık ve sancı

çıkarıyorum kalbimdeki bıçağı

adı özlem! 

gece uzun olacak 

şahdamarımda kabaran acıyla

cezalardayım 

dolunay nöbetinde

bu yalnızlık duygusu ne! 

yaşanmayandan arta kalan sessiz çığlık 

kıyılarıma vurup duran ayrılık

bu haksızlık 

nedir bu! 

(13 Eylül 2003)', 'gecelerden  dolunay bu gece gökyüzünde hırsız var  soyuluyor gök çırılçıplak  geç kalmış bir duygu hakim kapatıyorum gözlerimi kendimi kaçır...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dolunay-kabarmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimlere Benzerim', 'mevsimlere-benzerim-hikmet-karakus-mobwo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mayıs''ta

      çiçek vurur dallarıma

      tutsağı olurum baharın aşkla, 

Eylül''de

       toprağa düşer yüreğim

       sararmış bir yaprak gibi 

       savrulurum rüzgarla, 

Mart''ta

        donar  gönlüm kışlarım

         sen  terkin çözülmesini 

                      beklersin sabırla, 

Anlayacağın; 

Ben mevsimlere benzerim

                 mevsimler de bana...

(Ank.1996)', 'Mayıs''ta       çiçek vurur dallarıma       tutsağı olurum baharın aşkla,  Eylül''de        toprağa düşer yüreğim        sararmış bir yaprak g...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mevsimlere-benzerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkın Yok', 'hakkin-yok-ozgur-sirius-3c9dn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevilmeden sevmenin derdini çekiyorum

Bu kadar derdi bana çektirmeye hakkın yok

Ömrümün her anında sıratı geçiyorum

Ölünce sıratından geçtirmeye hakkın yok

Varlık denilen yolda durmadan yürüyorum

Yokluğun kadehini içtirmeye hakkın yok

Ferhat’a uğramıştım Yunusa dönüyorum

Arada bir kendini seçtirmeye hakkın yok

Gönül oldu kalemim kalbime yazıyorum

Satır satır ismini sildirmeye hakkın yok

Ayrılık bestesini sazıma kazıyorum

Sevenlerin yanında bildirmeye hakkın yok

Artık buzdan bedenim güneşi yakıyorum

Kanlı göz yaşlarınla söndürmeye hakkın yok

Yolun sonuna geldim son birkez bakıyorum

Yalancı sözlerinle döndürmeye hakkın yok', 'Sevilmeden sevmenin derdini çekiyorum Bu kadar derdi bana çektirmeye hakkın yok Ömrümün her anında sıratı geçiyorum Ölünce sıratından geçtir...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hakkin-yok-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-ozgur-sirius-cyh0s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Silmiyor silgiler artık resmini

Görmüyor gözlerim şimdi hepsini

Gönüller koparıp çaldı ismini

Yazmasam ne olur yazsam ne olur

Kalbimin kimseye değmez nazarı

Çekemez olmuşum böyle azarı

Gönlüme derince bir aşk mezarı

Kazmasam ne olur kazsam ne olur

Sevmekmi günahtır sevilmiyorken

Ölmekmi günahtır yaşamıyorken

Kader oyununu oynamıyorken

Bozmasam ne olur bozsam ne olur

Özgürüm böylece sona varırsın

Seversin gönlünce yanlız kalırsın

Sevdiğin elinden yaralanırsın

Azmasam ne olur azsam ne olur', 'Silmiyor silgiler artık resmini Görmüyor gözlerim şimdi hepsini Gönüller koparıp çaldı ismini Yazmasam ne olur yazsam ne olur Kalbimin kimse...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-olur-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demedim mi', 'demedim-mi-ozgur-sirius-0l7gv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın ızdırabı esti gönlüme

Vahşi bir aslandan döndü kediye

Hiçbir şey olmazmış derler kötüye

Kendini sebepsiz as demedim mi

Seni kim düşünüp  dua edecek

Kendine bir mezar kaz demedim mi

Öteki dünyada hesap gelecek

Sana bu sevaplar az demedim mi

Ne işin vardı da birini sevdin

Bir Gönül’e derken nereye girdin

Herkesin sevdiği aşık değildin

Ferhat’ın dağları yüz demedim mi

Yalanlar içinde doğruyu bulduk

Zarara uğrayan yine biz olduk

Kalplerin yolunu bile unuttuk

Dökülen her kadeh iz demedim mi', 'Aşkın ızdırabı esti gönlüme Vahşi bir aslandan döndü kediye Hiçbir şey olmazmış derler kötüye Kendini sebepsiz as demedim mi Seni kim düşünü...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/demedim-mi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl Saçlı Kız', 'kizil-sacli-kiz-ensar-aktas-265ji', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Binmiş te salına salına kürek çekiyor aşk sandalında

Saçlarına kızıl güneş ışığı düşmüş bir kızın, gün batımında

Dilinde bir aşk şarkısı cilveli cilveli mırıldanıyor

Sanki beyaz atlı prensini arıyor, kav rengi denizin ortasında

Yaklaştım yanına, aman Tanrı’m, o ne endam o ne gülüş

Gözlerinde masum bir parıltı, gamzesine cemre düşmüş

Biraz utangaç, biraz mağrur, gözlerime bakmaya çekiniyor

Kızıl saçlarının arasında beyaz bir gül, o ne işveli süzülüş

Dedim ki; “Ey kızıl saçlı, ürkek bakışlı, cesur kız! ...

Ne yaparsın tek başına, dalgaların arasında, yapayalnız? 

Dikkat et, emi? ! yutar seni, bu dalgalar çok insafsız! ..”

Dedi ki; “Dokunamaz saçımın bir tek teline hiç kimse, 

Çünkü yıllardır beklediğim beyaz atlı prensim benimle…”

Kimdi beyaz atlı prensi, kızıl saçlı kızın, sizce? … 

Woerden,18-08-2003', 'Binmiş te salına salına kürek çekiyor aşk sandalında Saçlarına kızıl güneş ışığı düşmüş bir kızın, gün batımında Dilinde bir aşk şarkısı cil...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kizil-sacli-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmeye Doyamadım', 'seni-sevmeye-doyamadim-salih-ozalasan-3pko9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşanmamış bir sevdaydı sende yaşadığım

Yalnız seninleydi mutluluktan ağladığım

Geceyi özlediğim buram, buram

Allah’ın verdiği canı uğruna adadığım

Sevgiydi, karşılıksız gönlümde çağlayan

Anamın ak sütü gibi tertemiz

Titrediğim adını anarken zaman, zaman

Yalnızca sendin, tanrıya yaklaşır gibi yaklaştığım

Deniz gözlüm sendin

Göz rengin inadına siyah olsa bile

Bir melek kadar masumdu gülüşlerin

Dört bir yanın şeytan dolsa bile

Benim için kadın gibi kadındın

Karda açan bir kardelen

Hiç yaşanmamış sevdamdın

Tanıdığımda dönüp ardıma bakmadığım

Bu güne dek yazamadığım şiirdin

Notalara dökülmemiş ölümsüz beste

Seninle razıydım kalsam da ateşte

Yüreğimde bir alevdin, ateşiyle yanamadığım

Yaşanmamış bir sevdaydın

Bu güne kadar hiç yaşamadığım

Canımdan bir candın

Bir cennet meyvesi hiç tatmadığım

Adın bende saklı kaldı

Bir sendin asla unutamadığım

Yaşanmamış bir aşktı

Senin bana kısa da olsa yaşattığın

Karda leke var bizde yok dediğim

Haşa, tanrıdan sonra taptığım

Adın sevgiydi, melek soyadın

Sevgi meleğimdin, tek muradım

Şimdi yarım kaldı yaşanmamış sevdamız

Bir seni sevmeye asla doyamadım

Y.Tarihi 13-09-2003 Saat14,30

Salih özalaşan', 'Yaşanmamış bir sevdaydı sende yaşadığım Yalnız seninleydi mutluluktan ağladığım Geceyi özlediğim buram, buram Allah’ın verdiği canı uğruna a...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/seni-sevmeye-doyamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-ensar-aktas-5ndfq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen sen ol sakın karşıma çıkayım deme

Kırgınım ben, çok kırıcıyım bugün

Yıllarca sineye çektiğim ihanetlerine

Bir çırpıda cevap veririm bugün

Bir şamar gibi yüzüne vururum bugün

Acı patlıcanı kırağı çalmaz, bilirim

Yine de ağıza alınmaz sözler söylerim

Ar, edep duvarlarını yıkmışım bugün

Sabrımın kulvarından çıkmışım bugün

Gözünün yaşına bakmadan seni vururum bugün

Rotterdam,11-06-2003', 'Sen sen ol sakın karşıma çıkayım deme Kırgınım ben, çok kırıcıyım bugün Yıllarca sineye çektiğim ihanetlerine Bir çırpıda cevap veririm bugü...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bugun-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Ortasında', 'gecenin-ortasinda-ensar-aktas-a424u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşerse düşlerin karanlığa

Gecenin ortasında

Bırak gark olsunlar yalnızlığa

Çünkü ben varım orada

Bulanırsa gülüşlerin gözyaşlarına

Medet umma sakın yıldızlardan

Aç gözlerini, ben gelirim aklına

Gül yaprağı olur silerim yanağından

Sen yalnız değilsin bebeğim

Gecenin ortasında

Belleğinde duruyor şiirlerim

Kokumsa yastığında

Hüzün galip gelir sanma bu yarıştan

Gecedir yalnız olan, yıldızlardır ağlayan

Güneş gibi doğacağım az sonra ufuktan

Pencerene mutluluk çizeceğim gök kuşağından

Rotterdam,06-09-2003', 'Düşerse düşlerin karanlığa Gecenin ortasında Bırak gark olsunlar yalnızlığa Çünkü ben varım orada Bulanırsa gülüşlerin gözyaşlarına Medet um...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gecenin-ortasinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birikmişliğindir unutamamam', 'birikmisligindir-unutamamam-derin-oger-01gh7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anılar koşuyor içimden

Bulutlar iki ateş arasında

Her damla sen diye düşüyor 

Her damla sicim gibi dolanıyor

Dolanıyor soluğumun çaresiz boynuna

Selli sulara kapılıyor cümlelerim

Camların buğusuyla akıyor sevgim

Yükseklerden dökülüyorum sokaklara

Uçurumlarca dolanıyor düşlerim

Yuvarlanıyorum uçsuz bucaksız boşluklara 

Anılar koşuyor içimden

Her damla bir sen daha bırakıyor bana

Dudaklarımdan gözlerimden taşıyorsun da

Birikmişliğin oluyor unutamamam

Ne farkeder ki sevgili gözlerimi kapasam....', 'Anılar koşuyor içimden Bulutlar iki ateş arasında Her damla sen diye düşüyor  Her damla sicim gibi dolanıyor Dolanıyor soluğumun çaresiz boy...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/birikmisligindir-unutamamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Nihayetin', 'yok-nihayetin-derin-oger-9h2b5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ana gibi

Taşırım sevgini

En masum duygularla

Kalbimin güzelliğinde

Hayalini kucaklar kollarım

Göğsüme çarpar duygularım

Adını fısıldadıkça dudağım

Gönlümdür suç ortağım

Havalandırır götürür beni

Ayrılamam ayılamam uykulardan

Ana gibi yar gibi sana sevgim

Ey sevgili yok yok  nihayetin.........', 'Ana gibi Taşırım sevgini En masum duygularla Kalbimin güzelliğinde Hayalini kucaklar kollarım Göğsüme çarpar duygularım Adını fısıldadıkça d...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yok-nihayetin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Vuslat', 'vuslat-gunay-aktag-3zat5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlemdi belki de bizi aşka çağıran

Hasretti belki de bizi vuslata salan

Seninle karşılaştığım  yağmurlu  ilk an

Yürek yangınımdı seni alev alev yakan

Aradaki mesafeleri yok etti zaman

Zamanla kayboldu duygular duruldu bir an

Vuslata erdi sonunda iki beden iki can

Hasret bitti dersem sakın inanma hepsi yalan

Bitmesin özlemlerimiz bitmesin hasret

Mesafeler bitsin vuslata ersin herkes

Zaman dursa da zamansız aşk durmaz elbet

Akar... akar...  akar... akar içine aşk hisset

Vuslata ermekti ya tüm hayâllerimiz

Koklaşmaktı belki de tüm ümitlerimiz

Yarınlara kaldı yanan bedenlerimiz

Umutlar tükenmez aşk içimde kaldı hisset', 'Özlemdi belki de bizi aşka çağıran Hasretti belki de bizi vuslata salan Seninle karşılaştığım  yağmurlu  ilk an Yürek yangınımdı seni alev a...', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vuslat-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavrum', 'yavrum-selvi-celik-iyuki', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Okumayi sevmedigini biliyorum.

Insanlari sevmedigin gibi.

Suclusu ben degilim nefretleriyin.

Anlamak istemesende yazdiklarimi, 

Son kez benim icin birsey yap.

Oku oku...

Yavrum diye bagrima basip hic sevemedim seni.

Birgün olsun nese ile yüzüne gülmedim.

Bunda benim sucum yok.

Kader diyelim, avunmak icin.

Biliyorum hic söylemesende isyanini.

Keske sen annem olmasaydin diye ettigin beddualari, 

Fisildayarak kendine soyledigini, sen duymasanda duydum.

O suskunluguyun ardinda, yüreginde ettigin isyankar feryatlarini duydum.

Seni anladigimi, yasadigimi, hic bir zaman söyleyemesemde.

O en üzgün günlerinde saclarini oksayarak teselli veremedimse, 

Seni sevmedigimden degil, 

Sen uyurken her gece gizli girdim odana.

Bazen yastigin islakti, agladigini biliyordum.

O anlarda hep ölmek istedim.

Bazende elinde esarbimi tutarak uyudugunu görürdüm.o gece korkarak uyudugunu anlardim.

Iste o an kendime isyanlarim hic dinmezdi.

Hayal dünyanda bana yer vermedin.

Cizdigin resimlerde anne yüzünü hic cizmedin.

Cok görmem hakliydin..

Senin gibi bir evlata, benim gibi anne zulumdu.

Bunlari hak etmedin, biliyorum.

Yarata bilseydim bu hayati yeniden.

Sana melekten anne armagan ederdim.

Sana ulasilmayacak kadar en güzel mutluluklari, en büyük sevincleri tertemez duygulari verirdim.

Olmadi yapamadim sana anne olamadim.

Affet beni

Affet beni dünyani karanliga biraktigim icin.

Affet beni nefretlerle büyüttügüm icin.

Affet beni sana anne olamadigim icin.

Affet yavrum sana hic yavrum diyemedigim icin.

Konusan dilsizlerden, gören körlerdendim.

Gidiyorum yillarimi bosa yedim biliyorum.

Mutsuzlugun sebebi sen degilsin, senin sucun yok yavrum.

Bu dünyamizi calan zalimlerden al hakkini.

Annelik hakkimi calanlardan al.

YAVRUM..

Yavruuuumm..............', 'Okumayi sevmedigini biliyorum. Insanlari sevmedigin gibi. Suclusu ben degilim nefretleriyin. Anlamak istemesende yazdiklarimi,  Son kez beni...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/yavrum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalim Ellerimdeki Umudum', 'hayalim-ellerimdeki-umudum-kadir-kavak-qgayf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yürek kanar, ağlar yanar

Her bir damla yaşla

Can verir her damlası toprağa

Canım benim canım sevgilim

Hayalim ellerimdeki umudum

Her gün ışığı ile

Bir köylü kadını çapa vurur

Çiy düşmüş, yeşermemiş umuduma

Denizlerin okyonusların

Üzerlerinde durmaksızın koşarım

Her karaya adım attığımda

Islattığın paçalarımla', 'Yürek kanar, ağlar yanar Her bir damla yaşla Can verir her damlası toprağa Canım benim canım sevgilim Hayalim ellerimdeki umudum Her gün ışı...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kavak']::text[], 8.5, '{"poet":"Kadir Kavak","poet_slug":"kadir-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayalim-ellerimdeki-umudum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreği Omzunda Asker', 'yuregi-omzunda-asker-kadir-kavak-eb3m7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğini omzuna almış

Bir ferhat gidiyor

Vatan için millet için

Bizler için rahat uyumamız için

Ardından bir ana ağlıyor

Biricik, tek ciğeri gidiyor diye

Gözlerinden yaşlar akıyor

Pırlanta olmnuş en değerli yaşlar

Bir baba elini sıkıyor

Vatan borcu gerekisrse? Diyor

Elini biraz daha sıktıktan sonra

Canınla öde diyor, babaya ağlayamazya

Yüreği omzunda gidiyor

Ödeyeceğim borcumu diyor

Bir ferhat gidiyor

Yüreği omzunda, umutları beklemede

Yarini bırakmış gidiyor

O kalbinde, o parmağında

Onsekiz ay beklemede

Yari anası hepsi onu bekliyor

Gittiği andan sonra

Onsekiz ayı sayıyor, tesekere bekliyor

Onsekiz ay bitecek, gidecek ailesine

Evlenecek aile kuracak

Tam onyedi ay kalmışken

Kader teskereyi veriyor

Kader öyle istedi onyedi ay

Erken terhiz veriyor ferhata

Yüreği omzunda giden ferhat

Bir tabutla, şanlı bayrakla

Dört kişinin omzunda geliyor

Yine ferhatın yüreği omzunda

Ana oğlunun karşısında durup

Selam çakmasını beklerken

Tabut selamlıyor evin önünde

Sanki ayağa kalmış, selam duruyor

Yüreği omuzlamış ferhat giderken

Pırlanta gibi yaşlar döken anne

Şimdi o gözlerden kan damlıyor

Parçalıyor ciğerini, yüreğini

İçini yakıyor her damla yaşta

Ferhatını kaybetmedi o ana

Ciğerini, canını, herşeyini kaybetti

Sönermi o ciğer yanar yanar

Hatırlamazmı her genç, askerde

Ferhatını hatırlamazmı

Durarmı o yaşlar durarmı

Ta yürekten kanayan yara hiç durarmı

O gerekirse canını ver diyen

ferhatı giderken sıktığı yumruklarını

Kafasına vuruyor, kafasına

Bir ferhatımda olsa oda feda olsun diyor

Yari kucaklamayı beklerken

Şimdi toprağı kucaklıyor ferhat

Vatan borcunu bitirip gelmeyi beklerken

Şehit oluyor meleklerle geliyor

Yüreği omzunda binlerce ferhat

Vatan sağ olsun bayrak inmesin

Siz razı olmasınız demi ferhatlar

O bayrağın inmesine

Siz o toprakta yattıkça

O bayraklar inmeyecek ferhatlar

Ardınızda milyonlarca ferhat var

Vatan sağ olsun be Ferhatlar', 'Yüreğini omzuna almış Bir ferhat gidiyor Vatan için millet için Bizler için rahat uyumamız için Ardından bir ana ağlıyor Biricik, tek ciğeri...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kavak']::text[], 8.5, '{"poet":"Kadir Kavak","poet_slug":"kadir-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/yuregi-omzunda-asker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedavadan Ucuz Sevgiler', 'bedavadan-ucuz-sevgiler-kadir-kavak-g73mo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Satılığa çıkarıldı sevgiler

Bedavadan daha ucuza

Alanın elinde kalıyor

Bedavadan ucuz sevgiler

Sevgi satılırmıydı

Sevgi alınırmıydı

Satılan sevgiden alınan sevgiden

Hayır gelirmiydi o sevgiden

Gidip bedavaya sevgi alıp

Üzerine birde sahte duygular katıp

Birkaçta yalan sözler serpip

Bu sevgiden doğan aşk, aşk olurmuydu', 'Satılığa çıkarıldı sevgiler Bedavadan daha ucuza Alanın elinde kalıyor Bedavadan ucuz sevgiler Sevgi satılırmıydı Sevgi alınırmıydı Satılan ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kavak']::text[], 8.5, '{"poet":"Kadir Kavak","poet_slug":"kadir-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bedavadan-ucuz-sevgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Rüzgarlar', 'huzunlu-ruzgarlar-kadir-kavak-yaikw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bulutlar var buralarda

Sanki rüzgarlar hüzünlü bugün

Yıldırımlar hıçkırıyor

Sanki gökler şimdi ağlayacak gibi

Sevgilisindenmi ayrılmıştı bulutlar

Yoksa rüzgar hasretmi kaldı yarine

Yoksa yıldırımlar kavuşamadımı aşkına

Bende senden, belki ayrılacağım yarın

Belki bulutlar birgün kavuşur

Kucaklaştıkları gün çöllere ağlarlar

Belki rüzgarlar kavuşur, güneşteki aşkına

Ama ben sana, ölümden sonra bile kavuşamam

Zordur bilirim ağlamak kadar beklemek

Zordur bilirim sensiz yaşamak, ölmekten

Kolaymı sanırsın unutmak seni

Korkmam aslında, bekle desen, yıllardan, beklerim

Ama tek korktuğum 

Bekleyip bekleyip

Ellerim boş dönmekten korkarım tek

Ölemkten, ölmek kadar beterdir bu

Tek unutmayacağın bir şey olsun bu dünyada

Oda kalbinin ta ortasında ben olayım

Eğer unutman gerekirse bir gün beni

Unutacağın en son şey ben olayım yarim', 'Bulutlar var buralarda Sanki rüzgarlar hüzünlü bugün Yıldırımlar hıçkırıyor Sanki gökler şimdi ağlayacak gibi Sevgilisindenmi ayrılmıştı bul...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kavak']::text[], 8.5, '{"poet":"Kadir Kavak","poet_slug":"kadir-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/huzunlu-ruzgarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Vurgunu', 'eylul-vurgunu-seval-kemertas-z9hz5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'içimde bir sonbahar 

savrulan umutlarım dallarından 

yaprak yaprak dökülüyor 

içimde sapsarı bir sevda 

kendi seçmediği bir kadere boyun eğiyor... 

bu yorgun argın inen güz akşamında 

beni hüzünlendiren Eylül değil 

yollarımızın ayrılması bir yerde 

şimdi gönlümde yorgun bir hazan 

ihanetlere kapısını aralıyor 

ve kalemimin ucunda bir sevda intihar ediyor... 

sözlerin beni terkettiği bu saatlerde 

ateş böcekleri sönerken bir bir gözlerimde 

yakamozların denizlere yazdığı, 

rüzgarın söylediği bir masal gibi 

düşlerinden akıp gidiyorum sessizce... 

dalgaların kıyıya vurup ağladığı yerde 

köpükler sahillere çizmeyecek resmimi 

sesim çınlamayacak martıların çığlığında 

sarhoş hazanın serseri rüzgarları 

adımı fısıldamayacak bir daha kulaklarına... 

içimde hüzzam bir sevdanın sessizliği 

elimde solmuş küçük bir resmin 

kalbimde durmadan kanayan yara 

ve yastığım ıslanırken gözlerimin yağmuruyla 

bir Eylül daha kapaklanıp yıkılıyor 

yüreğimin kaldırımlarına... 

Şimdi bağıra bağıra ağlamak yakışır bana... 

13/09/2003', 'içimde bir sonbahar  savrulan umutlarım dallarından  yaprak yaprak dökülüyor  içimde sapsarı bir sevda  kendi seçmediği bir kadere boyun eği...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/eylul-vurgunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki....', 'i-yi-ki-sair-masmavi-c2j8n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen ki yıldızımdın gökyüzünde, 

Karanlık gecelerin gökte asılı lambası, 

Kimi dost, sımsıcak

Kimi aşk, pırıl pırıl.

Sen ki dalgasıydın denizlerimin, 

Nefesimle bir coşup, bir duran

Kimi üzerinde salındığım yumuşacık, 

Kimi boğuştuğum, boğulmamak için.

Sen ki gökkuşağıydın yaşamımın

Sağanaklarından sonra gözlerimin, ışıklar saçan

Kimi sapsarı başak, doğurmak için ürünleri biçilesi, 

Kimi Kıpkırmızı kan kesmiş, öfkesi şarap gibi içilesi.

İyi ki...

İyi ki...', 'Sen ki yıldızımdın gökyüzünde,  Karanlık gecelerin gökte asılı lambası,  Kimi dost, sımsıcak Kimi aşk, pırıl pırıl. Sen ki dalgasıydın deniz...', ARRAY['Türk Edebiyatı','Şiir','Şair Masmavi']::text[], 8.5, '{"poet":"Şair Masmavi","poet_slug":"sair-masmavi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iyi-ki-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustosta Ölüm', 'agustosta-olum-necat-gundem-d3qxc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sene 1945

Mevsimse yaz

Kızgın bir Ağustos günü

Rüzgar değil ölüm esti o gün

Çekik gözlülerin diyarında

Hiroşimada

Tatmamışken Hiroşimalı çocuklar

Kırmızı Horoz şekerini

Tattırdılar çocuklara

Ölümün Amerikancasını

'' MADE İN USA'' etiketiyle

Vahşet dansının

Kanayan ritmiyle

Kim ne derse desin

Kardeşler bundan böyle

'' Oturan Boğa''nın kabilesiyle

Yazgıları aynı diye.

                1988', 'Sene 1945 Mevsimse yaz Kızgın bir Ağustos günü Rüzgar değil ölüm esti o gün Çekik gözlülerin diyarında Hiroşimada Tatmamışken Hiroşimalı çoc...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/agustosta-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Ara', 'beni-ara-necat-gundem-8d068', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşin her doğuşunda

Çocuğun her gülüşünde

Söylenen her şarkıda

Beni ara

Beni ara

Bulabilirsen

Al beni sakla

Yüreğinin sıcaklığında

Umut de bana

Yarın de bana

Ne dersen de

Ama

Bırakma beni

Karanlık kuyulara.', 'Güneşin her doğuşunda Çocuğun her gülüşünde Söylenen her şarkıda Beni ara Beni ara Bulabilirsen Al beni sakla Yüreğinin sıcaklığında Umut de...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/beni-ara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çengelli İğne', 'cengelli-i-gne-necat-gundem-fvypv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılığının ayrıntısında

Kör sensizliğinin peyzajında

Gülüşünü iliştirdin aklıma

Çengelli iğneyle



Yetmiyormuş gibi

Yüzünü de

Aşkını da

Gözlerinle maviliğini kuruttuğun

Denizin isyanlarına aldırmayıp

Mavi mavi bakışını da

Başlı başına sensizliğini de



Be insafsız

Yer kalmadı kafamda

Hepsine bedel

Kendin gelsen yanıma

Yıksan bu ayrılığı

Sevgimizin çengelli iğnesini

Atsak bir kenara

Olmaz mı ki', 'Ayrılığının ayrıntısında Kör sensizliğinin peyzajında Gülüşünü iliştirdin aklıma Çengelli iğneyle Yetmiyormuş gibi Yüzünü de Aşkını da Gözle...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cengelli-igne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecekonducu Aşk', 'gecekonducu-ask-necat-gundem-vxaia', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine aşk

Yuva kurmuş

Kanı deli gönlüme

Soğan ekmek kadar gerçek

Aslanın ağzındaki kadar zorlu

Pembe panjurlu evsiz hayallar 

Kadar yoksul

Bir aşk.

Ama onurlu bir aşk.

Ne demeli ki ona

Bir '' Afiyette oturunuz''dan başka.', 'Yine aşk Yuva kurmuş Kanı deli gönlüme Soğan ekmek kadar gerçek Aslanın ağzındaki kadar zorlu Pembe panjurlu evsiz hayallar  Kadar yoksul Bi...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gecekonducu-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Seni', 'gozlerim-seni-necat-gundem-xmcsb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerim aydınlık bekler

Yüreğim seni

Gözlerim ışık ister

Kulağım sesini

Gözlerim görmek ister seni

Masmavi gözlerini

Gözlerim seni

Gizli gizli

Ya sen

Gözler misin

Hem yolumu

Hem beni.



20 Ağustos 1996', 'Gözlerim aydınlık bekler Yüreğim seni Gözlerim ışık ister Kulağım sesini Gözlerim görmek ister seni Masmavi gözlerini Gözlerim seni Gizli gi...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık', 'i-nsanlik-necat-gundem-1fzgl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdalarına yenik

Bin ezginin 

Eksik notası

Sen; 

İnsanlık

Harman zamanı şimdi

Buğdayın, barışın, umutlu günlerin.

Doğan güneşle doğ bir defa, 

Yetmezse bin defa

Her savaşta 

Yitirdiğin oğulların kızların 

Umutla yeşeren günlerin hasretlerin için.

Ağlamasın artık gözlerin

Doğan güneş sana da gülümsüyor

Ve insanlık unutma

Savaşmak yok bir daha.', 'Sevdalarına yenik Bin ezginin  Eksik notası Sen;  İnsanlık Harman zamanı şimdi Buğdayın, barışın, umutlu günlerin. Doğan güneşle doğ bir def...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/insanlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirli Trafik', 'kirli-trafik-necat-gundem-nk26o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Trafiği 

daha bir katliame bulanır

Dünyanın.

Kirlenmiştir

Kana bulanmıştır

Yine ve yeniden

Vızır vızır 

Tanklar

Uçaklar ve de toplar

Gelir gider.

Varil varil

Kan doldurulur

Depolarına

Tankların

Uçakların

Ve de topların.

Birilerinin

Zafer çığlıkları

Sessizliği boğar, 

Şarabın 

Suyu kıskandırdığında.



Aslında her savaşta

Yitip giden

İnsanlığı kendisi ya

Anlamaz bunu

Zafer histerikleri

Varsa yoksa

Kana bulanmış çıkarları.



Öteden beri

Trafiği 

Böyledir dünyanın

Saati 

Barışa dönmez

Habil İle Kabilden beri

İnsanlar

İnsancıklara

Kurban gelir

Kurban gider

Ama artık

YETER.', 'Trafiği  daha bir katliame bulanır Dünyanın. Kirlenmiştir Kana bulanmıştır Yine ve yeniden Vızır vızır  Tanklar Uçaklar ve de toplar Gelir g...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kirli-trafik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhabam Alınterim ve Demli Çayım', 'merhabam-alinterim-ve-demli-cayim-necat-gundem-cz8ok', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne güzel durur 

Ellerimde

Cennet görkemliğiyle

Alınterim

Tırpanım.



Hasadından gelirim

Nasılsa

Karanlığın, umutsuzluğun

Ve sairenin.

Tırpanımla keserim

Karanlığı günlerden

Umuda gül biçerim

Güne sevgi ekerim

Sevgiliye de gül veririm.



Güneşe dayadım

Üşenmeden

Nasırlaşmış ellerimi

Düşmesin batmasın diye

Elime sağlık öyleyse

İyi de

Merhabam nerde? 



Merhabamı söyleyin

Demli çayımı da yanında

Cigaramı da yakın

Dinleneyim olmaz mı

Aydınlık işçisiyim şairim

Kolay mı? 



Burdur

20 Ağustos 1996', 'Ne güzel durur  Ellerimde Cennet görkemliğiyle Alınterim Tırpanım. Hasadından gelirim Nasılsa Karanlığın, umutsuzluğun Ve sairenin. Tırpanım...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/merhabam-alinterim-ve-demli-cayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşme', 'cesme-caglar-akarsu-qi7qu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çeşme

...

Boş durma, 

Taslarımız ayrı çeşmelerden dolmasın, 

İnançlarımız ve fikirlerimiz aynı, 

Sen hala “ boş “ taslarla  dolaşmaktasın, 

Aradığımız çeşmeye mührü vuralım, 

Bulduğumuz mucizelerde İslam’a koşalım, 

..

Birlik ve beraberlik, inanç ve güven, 

Taslarımız, ayrı çeşmelerden dolmasın.

...

Cağlar Akarsu', 'Çeşme ... Boş durma,  Taslarımız ayrı çeşmelerden dolmasın,  İnançlarımız ve fikirlerimiz aynı,  Sen hala “ boş “ taslarla  dolaşmaktasın,  ...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cesme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-caglar-akarsu-28gkz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fırtına, 

..

Akşam çöktü üzerime, her yer karanlık, 

Ruhumda dinmez bir fırtına esen, 

Sonsuz denizlerde kaybolmuş, gitmişim, 

Ummanlarda, sürüklermiş balıklar, 

Bir koy da tek başına kıyıya vurmuş, 

...

Önümde engin bir deniz ve gökte ufuk, 

İçimde bir dalga, alçalan-yükselen, 

Kalbimde senin ismin; vaz geçilmez, 

Medet umarken, menzile giden yolda, 

Ruhum düşmüş kalmış bu yollarda, 

...

Heyhat! mevlam; bu arş-ı alemde, 

Deniz ve toprak, tüm canlılar, 

Müjde kapıların bir –bir aralanışında, 

Seni buldum, seni gördüm, 

Seni sevdim! ! 

..

Cağlar Akarsu', 'Fırtına,  .. Akşam çöktü üzerime, her yer karanlık,  Ruhumda dinmez bir fırtına esen,  Sonsuz denizlerde kaybolmuş, gitmişim,  Ummanlarda, s...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/firtina-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu', 'anadolu-caglar-akarsu-sv5s2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '...

Anadolu, boynu bükük yetim toprağım, 

Neden; kederli boynun bükülmüş, 

Neden; ağlıyorsun devamlı, 

..

Söyle, dertlerine “ derman “olayım

O topraklarda yetiştim, 

Hep seninle yaşadım bilesin

Bağrını aç bana  bırak geleyim.

Hep seninle, doğdum  orada, öleyim

...

Başımı yorgun dağlarına yaslayım, 

Nehirlerinde ki ırmaklarında çağlayım, 

Gel etme  eyleme, beni terk etme, 

Anadolu  güzel yurdum.

..

Bahçelerinde olgun  meyveler

Bağlarında, akçe üzümler, 

Ak ninelerin  ak sütü gibi helal, 

Otlarlarındaki, kuzularının, 

Çobanı olayım, 

Anadolu! ! 

...', '... Anadolu, boynu bükük yetim toprağım,  Neden; kederli boynun bükülmüş,  Neden; ağlıyorsun devamlı,  .. Söyle, dertlerine “ derman “olayım...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anadolu-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Yıldızı,', 'coban-yildizi-caglar-akarsu-3n3n7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çoban Yıldızı, 

..

Gökteki yıldızlar parıldarken, 

Gözlerini bir kez daha  kapatmalısın, 

Bu gece bir dilek dileyelim, 

...

Gönlüne dolsun tüm ışıklar, 

Çoban yıldızları rehberimiz, 

Önümüzde, bizimle  gidiyor, 

Bu gece, gel! .. beraber  yürüyelim.

Ellerimizde, mevsimlerden kalmış, 

Binlerse yapraklar varsa, 

Yüreğinde büyümüş hasret şarkıları, 

Üzerimizde ışıklardan bir kuşak, 

Altından geçmişse  binlerce yıllar, 

Topraklar üzerinde yığılmışsa kemikler, 

Bir mezarın derinliklerinde kalmışsa, 

Korku dolu iskeletler, 

..

Sonsuzlukların yıldızlarını toplayalım, 

Dünya şimdi bize uzak bir gezegen, 

Kevser ırmaklarında gezer huriler, 

Beş vakitte öter arşın horozları, 

Yeryüzünde zümrüt renkli taşlar, 

Gözlerinden akan binlerce yaş, 

Gönül kapılarına yıldızları taşısın, 

Taşısın! ! 

...

Çağlar Akarsu', 'Çoban Yıldızı,  .. Gökteki yıldızlar parıldarken,  Gözlerini bir kez daha  kapatmalısın,  Bu gece bir dilek dileyelim,  ... Gönlüne dolsun t...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/coban-yildizi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zirve', 'zirve-kamil-bintas-4bv8l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '_Gölge Adam''a_

Mayamızda ihanet yok bizim.

Sevgi ve sadakatle yoğrulmuş, 

Çile çeken muzdarip gönüllerimiz.

Ve dünya hayretler içerisinde, 

Nice acı günlerdeki direnişimize...

Eğer sular yükselecekse ters-yüz, 

Çağlayanların en üst zirvesine.

Şaşırma, korkma, ürkme! 

Eğer sevdalar delecekse yürekleri, 

Beyaz bir küheylan misali, 

Yol alacaksa alabildiğine, 

Hayret etme! 

Eğer gemiler dönecekse, 

O eski liman şehrine.

Bir gözü dünyaya kapalı kaptan, 

Gülümseyecekse diğer gözüyle.

Bir eli kopmuş garip tayfa, 

El sallayacaksa sonsuz engine....

O an bir sızı, bir sıcaklık, 

Dolacaksa o küçücük yüreğine.

Ve kuvvet gelecekse o an, 

İğne ipliğe dönmüş bileğine.

Çek ağları aldırmadan, 

Dirensin dünya, direndiğince...

Varacağın tek yer kaldı ey dostum, 

Orası ZİRVE! 

                                   14.09.2003', '_Gölge Adam''a_ Mayamızda ihanet yok bizim. Sevgi ve sadakatle yoğrulmuş,  Çile çeken muzdarip gönüllerimiz. Ve dünya hayretler içerisinde,  ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Bintaş']::text[], 8.5, '{"poet":"Kamil Bintaş","poet_slug":"kamil-bintas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/zirve-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiz Kalemim.', 'ciz-kalemim-kamil-bintas-e00h0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir hayal çiz ey kalemim, 

Yeşillikler içinde dumansız, kirsiz.

Uzun, yayvan dallarıyla bir çınar, 

Şırıl şırıl akan bir pınar.

Ve...

Kınalı, nazik ayakları suya değmiş, 

Bir dilber çiz...

Su boyundaki yaban mersini varya, 

İşte onun kokusu gibi olsun, 

Teninin kokusu.

Hani göz alabildiğine uzanan ovada, 

O sarı başaklar varya.

İşte öylesine sarı olsun saçları.

Gözlerine  ne demeli ey kalem? 

Gözlerini nasıl çizeceksin, söylermisin? 

Yeşil, üzüm tanesi mi? 

Yoksa uçsuz bucaksız denizlerin, 

Tatlı mavisi mi olsun? 

O yanakları, o dudakları, 

Hele o selvi gibi boyu nasıl çizersin? 

Ey kalem, sen ne görüyorsan çiz! 

Nasıl biliyorsan öyle çiz! 

Fakat bir ricam var, naçizane, 

Sonunda onu benim için çiz, 

Olur mu? 

                      

                                 27.11.1998', 'Bir hayal çiz ey kalemim,  Yeşillikler içinde dumansız, kirsiz. Uzun, yayvan dallarıyla bir çınar,  Şırıl şırıl akan bir pınar. Ve... Kınalı...', ARRAY['Türk Edebiyatı','Şiir','Kamil Bintaş']::text[], 8.5, '{"poet":"Kamil Bintaş","poet_slug":"kamil-bintas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ciz-kalemim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı', 'aci-adil-han-talat-ivfrj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acıyı anlayabilmek için, çekmek; 

Yaşayabilmek için acıyı anlamak gerek...', 'Acıyı anlayabilmek için, çekmek;  Yaşayabilmek için acıyı anlamak gerek......', ARRAY['Türk Edebiyatı','Şiir','Adil Han Talat']::text[], 8.5, '{"poet":"Adil Han Talat","poet_slug":"adil-han-talat","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/aci-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçinden Dışıma Seyahat', 'i-cinden-disima-seyahat-muammer-celik-80wto', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '”Gel, gel hadi, 

öp şu dudaklarımı, sabahlar olmasın 

gel, bak gözlerime, geceler bitmesin 

gel, sar beni iyice, mehtaplar batmasın 

gel sev, okşa, seviş benimle tüm gece 

ki, bitmesin arzularım sana, hiç bitmesin'' 

……….………………..derken sen bana 

çığlıkların sedası tırmalıyor kulaklarımı… 

Tabularınla bastırıp, isyanını zor tutuyorsun 

çoktan baslamış bile, kemiriyor için için seni 

yavaş yavaş savaşa hazırlanan cepheler gibi 

kırılmaya, yüz tutmuş surların zorluyor seni… 

Patlayacak fitil biliyorum, sen daha iyi biliyorsun 

infilak edecek engellerin, tabuların ve kabukların 

yırtacaksın, dileceksin, böleceksin ikiye bedenini 

açılacak lavlar kadar yanmış yüreğin çatal çatal… 

Çıkacak gönlünde gizlediğin o vahşi kadın cıkacak, 

yürüyecek amazon edalım, kendi üstüne yürüyecek 

kıracak parça parça tüm dışını kaplayan zırhlarını 

kaldıracak sevda üfleyerek yaktığı aşk meşalesini 

sana inat, getirecek bana zincirlerinden tuturak seni... 

Sarmaş olacağız, dolaş dolaş olacağız her üçümüzde 

evrenin uçsuz bucaksız açıklığında ve olabildiğince 

mehtabın çırılsıklam ışıklarının altında alabildiğince 

yıldızlar tutuşacak ateşimizden, evreni aydınlatacak 

yürüyeceğiz birlikte, saçların rüzgarlarıma takılacak 

Değdireceğiz başlarımızı önce birer birer Arş-ı Azam''a 

Sonra gireceğiz kapıdan, kovuldugumuz Cennet-i Ala’ya..! 

BirDeli

14.08.2003', '”Gel, gel hadi,  öp şu dudaklarımı, sabahlar olmasın  gel, bak gözlerime, geceler bitmesin  gel, sar beni iyice, mehtaplar batmasın  gel sev...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/icinden-disima-seyahat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana ne!', 'bana-ne-muammer-celik-ib9aa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toplantın varmış birazdan, bana ne! 

benimde bir toplantım var seninle 

Hemde bir ömür boyunca sürecek 

Ajandamdan hiç mi hiç silinmeyecek…! 

Ötekilere benden sonraki son sıraları ver 

Toplantımızın bitmesini oturup beklesinler...! 

Muammer Çelik 

13.08.2003', 'Toplantın varmış birazdan, bana ne!  benimde bir toplantım var seninle  Hemde bir ömür boyunca sürecek  Ajandamdan hiç mi hiç silinmeyecek…!...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bana-ne-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Av kim, avcı kim?', 'av-kim-avci-kim-muammer-celik-813c2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni nede güzel tavlamışım… 

ama, farkında değilim, 

ava giderken sana avlanmışım...! 

Muammer Çelik 

13.08.2003', 'Ben seni nede güzel tavlamışım…  ama, farkında değilim,  ava giderken sana avlanmışım...!  Muammer Çelik  13.08.2003...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/av-kim-avci-kim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fukaranın Aşkı', 'fukaranin-aski-muammer-celik-emkcg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaldıracağım ellerimi, 

diz çöküp yere 

Sereceğim şiltemi, 

sele serpe kuru yere… 

Anadan uriyen görünce 

Zembil ile inerken seni 

Saracağım ruhumun 

çuluna sımsıkı, 

soğutacağım seni…! 

Muammer Çelik 

13.08.2003', 'Kaldıracağım ellerimi,  diz çöküp yere  Sereceğim şiltemi,  sele serpe kuru yere…  Anadan uriyen görünce  Zembil ile inerken seni  Saracağım...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/fukaranin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazin Ak Olsun Yaşın Kutlu Olsun', 'yazin-ak-olsun-yasin-kutlu-olsun-hayati-yavuzer-ghxx7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aslıhan’a

Ömrünün her demi sihhatli olsun

Hayatın lezzeti sana bal tatlı olsun

Çevrendeki herkes şefkatli olsun

	Bahar dalım, ana şefkatlim, canım

	Yazın ak olsun, yaşın kutlu olsun

Yeşertsin Tanrı’m bastığın yerleri

Düz eylesin engelleri, yarları

Yağdırsın başından sonsuz nurları

	Bahar dalım, ana şefkatlim, canım

	Yazın ak olsun, yaşın kutlu olsun

	(10 Şubat 2001 Üsküp)', 'Aslıhan’a Ömrünün her demi sihhatli olsun Hayatın lezzeti sana bal tatlı olsun Çevrendeki herkes şefkatli olsun 	Bahar dalım, ana şefkatlim,...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yazin-ak-olsun-yasin-kutlu-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Gülüm', 'uc-gulum-hayati-yavuzer-x1vsa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aslıhan, Selvihan ve Oğuzhan''a

Günün yorulduğu saatlerde

Ben yüzümü size dönerim

Uzaklardan aydınlığınız gelir

Aslı''m som yürek bir annedir

Üstüme Selvi serinlikleri çöker

Bir Oğuz destanı dinlercesine

Başımı size yaslar dinlenirim

Uykularım düşe vurmadan önce

Saçlarınıza, ellerinize uğrar yolum

Resimlerden fışkırır tebessümleriniz

Yüreğimde her an yeniden açar

Umudum, varlık sebebim, üç gülüm

Dualar sizi, siz duaları getirirsiniz aklıma

Yeşerir hergün yeni filizler içimde

Bugüne, yarına ve size dair

Hergün yeniden yaşarım sizinle

Her yaşınızı, her anınızı bir bir

(19 Eylül 2002/Üsküp)', 'Aslıhan, Selvihan ve Oğuzhan''a Günün yorulduğu saatlerde Ben yüzümü size dönerim Uzaklardan aydınlığınız gelir Aslı''m som yürek bir annedir ...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uc-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Sürgünüm', 'i-lk-surgunum-hayati-yavuzer-uyt60', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aslıhan’a

Kulağım işitmez oldu sesini

Salıver yanıma gelsin gölgeni

Ayrı geçen günler yakıyor beni

İlk sürgünüm, bahar dalım, çiçeğim

Hayatın seninle bir anlamı var

Sesinle tatlanır bütün acılar

Sen oldun bana hep dar günümde yar

İlk sürgünüm, bahar dalım, çiçeğim

Gözümde tütensin, dilimde lezzet

Ayrılık geçici, bitecek elbet

Alın yazımızda varmış bu gurbet

İlk sürgünüm, bahar dalım, çiçeğim

Dilerim ki alın yazın  ak olsun

Hep mutlu ol, hüzün hep ırak olsun

Bahtın açık, talihin berrak olsun

İlk sürgünüm, bahar dalım, çiçeğim

(24 Mart 2000/Üsküp)', 'Aslıhan’a Kulağım işitmez oldu sesini Salıver yanıma gelsin gölgeni Ayrı geçen günler yakıyor beni İlk sürgünüm, bahar dalım, çiçeğim Hayatı...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ilk-surgunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimi Sizinle Doldurdum', 'yuregimi-sizinle-doldurdum-hayati-yavuzer-yivxw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üsküp’teki Öğrencilerime

Ah çocuklar ah

Alınlarınızda nice şafaklar görüyorum

Yağmurlarla yıkanmış

Umuda uyanmış mütebessim bir güneşle

Nice Şafaklar

Ah çocuklar ah

Vardar yüreğinizden doğar

Dilinizde gül biter

Yüreğiniz geniş yaylalar kadar

Ah çocuklar ah

Bir bezm-i elest sevdasıyla sevdim sizi

Sevdalandım

Yüreğimi burada bırakacağım çocuklar

Onu sizinle doldurdum

Gölgeniz, varlığınızdan daha büyük düşer bu toprağa

Ulu çınarlar gibi kökleriniz derinlerdedir

Yürekleriniz toprak kadar dost

Ve okyanuslarca enginlerdedir

Kollarınızı birbirinize açın

Sema’a yürüyen dervişler gibi

Kucaklayın, omuzlayın birbirinizi

Yarlar, kardaşlar gibi

Hala rüzgarlar seherleri yoklar

Alev yeleli atların kasırga kanatlarinda

Hala Vardar sizinle uyanır sabahlara

Ki hala sevgililer kıyısında buluşur

Yahya Kemal gençliğini sizde arar

Ve sizinle bir dau’s-silayı bölüşür

Ah çocuklar ah

Sizinle geçen saatleri

İbadet gibi kutsal saydım

Keşke hiç bitmeseydi

Hep sizlerle olsaydım

(13 Aralık 2001/ Bulgaristan)', 'Üsküp’teki Öğrencilerime Ah çocuklar ah Alınlarınızda nice şafaklar görüyorum Yağmurlarla yıkanmış Umuda uyanmış mütebessim bir güneşle Nice...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yuregimi-sizinle-doldurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşinin Kalıntılarından Çalmıştım Dünya', 'gunesinin-kalintilarindan-calmistim-dunya-derin-oger-pwmfc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesimi duysaydı şu gökyüzün

Sitemim olurmuydu  bulutlarına

Bulutların ki bir velveleyle gelir geçerler

Dallarım yüzüne uzanır günboyu

Ayağının altında kalmak dokunur bana

Ufalanır hayallerim değirmen misali dönüp duruşunda

Yörüngenden çıkmaz ama el sallarsın

Mehtabını düşürürsün yakamoz diye sularıma

Renklerinin yalan oynaşlarıyla gözlerimi yakar geçersin

Genişliğinmidir kuşlarının kanatlarının kalbime değişi

Tuzağın ki günlerinle mevsimlerinle işbirliği içinde

Ben umudun yolcusuyum

Yasını biçemediğim gönlümden gelip geçenlerle

Güneşinin kalıntılarından çalmıştım

Ve hâlâ avuçlarımda..................', 'Sesimi duysaydı şu gökyüzün Sitemim olurmuydu  bulutlarına Bulutların ki bir velveleyle gelir geçerler Dallarım yüzüne uzanır günboyu Ayağın...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gunesinin-kalintilarindan-calmistim-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman tünelinde..!', 'zaman-tunelinde-muammer-celik-l015v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hızlanacak ömür treni 

zamanın karanlık tünelinde

taşıyacak bir gün 

beni de evrenin kara deliğine…

Dudaklarımda senin şarkını 

samanyolunda mırıldanırken

kanatsız, dikişsiz, yakasız

ve düğmesiz beyaz giysimle 

resmi geçitte uygun adım yürürken…

Selam duracak yıldızlar 

yaşanmamış evrensel aşkımın 

bayrağı elimdeyken

dünyada bıraktığım sen 

ruhumla birlikte uçarken...

Sormaya bile cesaret edemeyecekler, 

Zaman Tüneli çıkışında sual soran melekler...! 

Muammer Çelik

14.09.2003', 'Hızlanacak ömür treni  zamanın karanlık tünelinde taşıyacak bir gün  beni de evrenin kara deliğine… Dudaklarımda senin şarkını  samanyolunda...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zaman-tunelinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-hayati-yavuzer-u746n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz kaç geceyle beraber oldum

Kaç şafağı içtim ben

Kaç sabahı kuşanıp

Kaç sabah kundaklandım

Kaç gündüze yürüyüp

Ve kaç hüznü paylaştım

Sensiz kaç mevsime darıldım

Ve konuşmadım, sustum

Ne sari güller güldü yüzüme

Ne papatyalar açtı

Ben mısralarımla hep 

Sensizliği konuştum

Başımda esen kavak yelleri değildi

Her gece içimde bir ay kanadı

Kök saldığım yalnızlık

Çınarlarca büyüdü

Bulduğum yerde yittin

Kör kuyulara düştüm

(27 Kasım 2000/Üsküp)', 'Sensiz kaç geceyle beraber oldum Kaç şafağı içtim ben Kaç sabahı kuşanıp Kaç sabah kundaklandım Kaç gündüze yürüyüp Ve kaç hüznü paylaştım S...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sensiz-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıyorum Ey Aşk, Tut Beni!', 'kayiyorum-ey-ask-tut-beni-naime-erlacin-pa00r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'size sesleniyorum beyaz anlar

bana katılın

aklım beni bırakmadan 

arınmak istiyorum 

iklim ılıman olmalı

üşümemeliyim

celladım soğuk oysa

çekiliyor ip 

celladım buz

ilmeğin bir adı vardı! 

nerede bitecek bu yol 

ey kader yolcusu

kendimizi sınayarak geçtik bütün tuzaklardan

hem avcıyız hem av

isyankar tipide buzlanıp

devasa bir çığda saklanıyoruz

gerisi yalan! 

yaşam lanet bir patinaj

kayıyorum ey aşk

tut beni 

tut beni! 

(14 Eylül 2003)', 'size sesleniyorum beyaz anlar bana katılın aklım beni bırakmadan  arınmak istiyorum  iklim ılıman olmalı üşümemeliyim celladım soğuk oysa çe...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kayiyorum-ey-ask-tut-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalniz Ben', 'yalniz-ben-gul-pembe-aybgf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim bir benligim var, 

Bir de kendim....

Biri hayat dolu civil civil, 

Digeri inler derdim.....derdim...

Biri beni sana baglar da birakip gidemem, 

Digeri ise sensizlikte bulur huzuru....

Gitsem gidilmez, kalsam kalinmaz....

Biri der derdinin caresi bulunur, 

Digeri, bulunmaz...

Biri kahkahadan bogulur gulerken, 

Digeri gulumsemeyi unutmus.....

Biri azmini asla kaybetmez, 

Digeri yenilgilerin esiri olmus...

Birinin gozleri umit dolu piril piril, 

Digeri umitsizlikle kardes olmus, 

Benligimin yanaklari gul pembe, 

Kendiminse hayat belirtileri solmus...

Benim benden baska kimsem yok...

Ha! bir de kurtulmak isteyip de kurtulamadigim kendim...

Ben, yine ''yalniz ben''olmak istiyorum

Birak pesimi kendim..........', 'Benim bir benligim var,  Bir de kendim.... Biri hayat dolu civil civil,  Digeri inler derdim.....derdim... Biri beni sana baglar da birakip ...', ARRAY['Türk Edebiyatı','Şiir','Gul Pembe']::text[], 8.5, '{"poet":"Gul Pembe","poet_slug":"gul-pembe","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalniz-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Kırıklığı', 'hayal-kirikligi-deli-hasanzan-21oup', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinin içine baktığımda, 

Öylesine huzur buluyordum ki, 

Sanki hiç bitmeyecek, 

Sonunun gelmesini istemediğim bir rüyadaydım.

Bu rüya bitmeyecekti, 

Çünkü hayatım boyunca beklediğim insandı o.

Bir çok kez denedim, 

Ama hep hayalkırıklığıydı benim için aşk.

Hep suçu kendimde aradım.

Kendime kızdım, 

Kendimi başarısız saydım.

“Unut bunları, hayatın tadını çıkar.” Demedim, 

diyemedim kendime.

Taki onu görene kadar, 

O kadar sade ve güzeldi ki, 

Beni kendine hapsetti.

Orada sonsuza kadar kalabilirdim.

Ama yine olmadı.

“Yine başaramadım.” Demedim kendime bu sefer.

Suçu onda aradım ve buldum.

Peki ne değişti? 

Yine hayal kırıklığı...', 'Gözlerinin içine baktığımda,  Öylesine huzur buluyordum ki,  Sanki hiç bitmeyecek,  Sonunun gelmesini istemediğim bir rüyadaydım. Bu rüya bi...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hayal-kirikligi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aptal Adam', 'aptal-adam-deli-hasanzan-zqe8i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Sen ne anlarsın bu işten! 

Kaç kez söyledim sana aşk sana göre değil.

Sen de aptal adam! ” demiştim ona, 

Ama beni dinlemedi, 

“Kız milletinin sağı solu belli olmaz” dedim, 

Gitti yine körkütük aşık oldu.

Gözleri parlıyordu, 

Kalbinin atışını ben duyuyordum, 

O kadar net ve gürdü ki, 

“Bu adam aşık, yazık.” Dedim.

Aşk gerçekten ona göre değildi.

Hemen telaşa kapılır, 

Günü kurtarmak için kıza iltifat edip dururdu.

Hergün daha da bağlanıyordu.

“Kendine bir bak! Ne hale geldin.

Bu kadar erken bağlanma aptal adam! ” dedim.

Artık çok geçti.

Daha ilk hafta bitmişti ki, 

Kıza aşık olduğunu söylemişti.

Sonra da bana gelip, gözlerini açarak

Ve gülerek, 

“Başardım, ona aşık olduğumu söyledim.” Dedi.

“İyi bok yedin.” Dedim içimden, hevesini kırmamak için.

İki üç gün sonra bir bankta otururken gördüm onu.

Daha dünkü o neşeli adam gitmiş, 

Yerine somurtkan ve asabi bir adam gelmişti, 

“Ne oldu? ”  diye sordum.

Dudağını bükerek: “Ayrıldık.” Dedi.

Sonra da bana sarılarak:

“Ben aptal adamın tekiyim! ”', '“Sen ne anlarsın bu işten!  Kaç kez söyledim sana aşk sana göre değil. Sen de aptal adam! ” demiştim ona,  Ama beni dinlemedi,  “Kız milleti...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aptal-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serdar', 'serdar-deli-hasanzan-a2acb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zor anlar yaşar insanlar, 

Dönüm noktaları vardır hayatta, 

Bir seçim yapmak zorunda kalırsınız, 

Bu seçim her zaman size kalmaz.

İşte böyle bir zamanda tanıştım serdarla.

Yurt hayatımın başlangıcında, 

Hiç tanımadığım bir adamdı.

Çok garip, hiç tanımadığım

Ve bu kadar sıcakkanlı.

Bana bir abimi yoksa arkadaş mı oldu? 

Hiç belli olmadı...

Her ikisi de desem.

Onunda hayatında inişler çıkışlar olmuştu.

Bazıları onu çok zayıf görüyorlardı.

Ben ise tam tersini düşünüyordum.

Karşımda kararlı ve azimli bir serdar vardı.

Ve bana belki de ogüne kadar hiçbir insan, 

Bu kadar sıcak ve içten davranmamıştı.

Çok konuştuk, dertleştik, içtik

Özellikle iyi bir dinleyiciydi

Ve kelimeleri çok dikkatli seçiyordu.

Karşısındakini kırmadan, 

Hatalarını yüzüne vuruyordu.

Benim hayatımın dönüm noktasında, 

Onunla tanışmam benim şansımdı.

Onunda kalbi kırıktı, 

Sonra tanıştığı o kız, 

Evet o kız herşeyi değiştirdi.

Serdarında o kızla tanışması, 

Onun şansıydı.

Serdarın günden güne kendine gelmesi, 

Gözlerinde ki ışık o kadar hoşuma gidiyordu ki, 

“Helal olsun kıza, adamı hayata döndürdü.” Dedim.

Onu asla kıskanmadım, 

Aksine onunla gurur duyuyorum.

Ve de kendimle.

Onunla aynı odayı paylaştığım için.', 'Zor anlar yaşar insanlar,  Dönüm noktaları vardır hayatta,  Bir seçim yapmak zorunda kalırsınız,  Bu seçim her zaman size kalmaz. İşte böyle...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/serdar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-deli-hasanzan-2h2mx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmek nedir? 

Defalarca ölmek mi? 

Mutluluktan gözyaşı dökmek mi? 

Belkide bir kavuşma...

Yoksa bir ruhun canlanması mı? 

Sevmek midir, 

Soğuk bir havada sıcak bir nefes? 

Ya da bir dokunuş, 

Kim bilir belki bir bakış...

Sevmek denebilir mi? 

Bir yüreğin heyecanına, 

Ellerini terleten duygulara, 

Nefesini kesenlere...

Peki ya nasıl sevmektir, 

Bir kerede öldürmek, 

Acı çekerek ağlamak, 

Bir veda sahnesi, 

Ya da bir ruhun çöküşü? 

Sevmek bu mudur? 

Her gün daha da soğumak, 

Son dokunuş, 

Soğuk bir bakış? 

Hayır, sevmek değildir, 

Bir yüreği burkmak.

Ellerimi tutmamak, 

Nefesimi kesmek.', 'Sevmek nedir?  Defalarca ölmek mi?  Mutluluktan gözyaşı dökmek mi?  Belkide bir kavuşma... Yoksa bir ruhun canlanması mı?  Sevmek midir,  So...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevmek-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Son Aşkım', 'en-son-askim-deli-hasanzan-znuj6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok şey var öğrendiğim, 

En son aşkımdan...

Gözlerini kaçırmazdı benden, 

Hele bakışlarını asla, 

Peki niye, niye son kez baktı gözlerime? 

Kendimi kandırdım diye düşünürken, 

“Suç bendeydi.” Dedi bana.

Kendine güvenmeyen bir insandı, 

En son aşkım...

Güzelim güzelliğine ihanet ederek, 

Kendini beğenmiyor, 

Ve inkar ediyordu sadeliğini.

Bense içimdeki duygularla, 

Amansız bir savaş veriyordum.

Her zaman yaptığım gibi.

Bıraktı beni birgün durduk yere, 

En son aşkım...

Oysa ben hergece sesini duymak, 

Hergün yüzünü görmek, 

İstiyordum en son aşkımın.

Eğer öğrendiğim bir şey varsa, 

İnsanlara umut vermek, 

Acı vermektir.

En son aşkım...', 'Çok şey var öğrendiğim,  En son aşkımdan... Gözlerini kaçırmazdı benden,  Hele bakışlarını asla,  Peki niye, niye son kez baktı gözlerime?  ...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/en-son-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Milleti İşte', 'kiz-milleti-i-ste-deli-hasanzan-1amqq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her haraketiyle bu kadar sempatik, 

Her davranışıyla bu kadar kırıcıdır, kız milleti.

Onlara aldanmayın desem, 

Kaç erkek dinler beni? 

Birde ben kendimi dinlesem...

Gülüşleri, bakışları bitirir adamı, 

Hele o nazlanmaları, dudaklarını büküşleri.

Masum gözlerle bakıp, 

Biz erkeleri heyecanlandıran, 

Değil midir kız milleti? 

Dedikoduları, kıskançlıkları, 

Dostlukları, sevgileri, 

Hepsi olay değil midir? 

Birbirlerine bakarak, 

Bağırarak şarkı söylemelerinden tut, 

Cep telefonuna gülümseyerek, 

Çektikleri mesajlara kadar...

Peki ya suçu karşındakine atmaktaki ustalıklarına? 

Dengesiz davranışlarına? 

Bütün ilgiyi üstlerinde topladıkları zamanki, 

O dik ve kendinden emin duruşları? 

Bütün bunların amacı nedir? 

Hiçbir şey, 

Kız milleti işte!', 'Her haraketiyle bu kadar sempatik,  Her davranışıyla bu kadar kırıcıdır, kız milleti. Onlara aldanmayın desem,  Kaç erkek dinler beni?  Bird...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kiz-milleti-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onu Unutmak', 'onu-unutmak-deli-hasanzan-de20d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hepmi onunla yaşayacağım? 

Hele beni terkettikten sonra...

Biliyorum çok zor onu unutmak.

O güzel gülüşünü, 

Bana gülümseyişini, 

Sıcak tenini.

Bütün bunlar benim için yalan bugünlerde.

Ondan uzaktayım, 

Üzgün olmam mı gerek, 

Yoksa gülüp geçmem mi? 

“Unuturum biter.” Mi demeliyim? 

Suç ortağımı kaderim olarak mı ilan etmeliyim, 

Vicdanıma verdiğim ifadede? 

Bu ifade beni kurtarmaz.

Herhalde en soğuk koğuşunda yatacağım, 

Duygularımın.

Bütün bu savaşı vermek zorundamıyım, 

Onu unutmak için?', 'Hepmi onunla yaşayacağım?  Hele beni terkettikten sonra... Biliyorum çok zor onu unutmak. O güzel gülüşünü,  Bana gülümseyişini,  Sıcak teni...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/onu-unutmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine de Hayat', 'yine-de-hayat-deli-hasanzan-sco6o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok kelek yaptın bana! 

Zor anlar yaşattın, 

Bazen delirttin, 

Çoğu zaman şanslı olduğumu hissetirdin

En şanssız zamanlarımda.

Yani beni aldattın.

Bir anamı ve ailemi çok görmedin bana, 

Bir de dostlarımı.

Bunlar için teşekkürler.

Peki ya aldıkıların benden? 

En hayalperest zamanlarımda, 

Ümitlerimi çaldın benden.

Umutlandırdın beni lüzumu yokken.

Sevdiklerimi aldın! 

Aşklarımı almana alıştımda, 

Sonuncusu çok koydu be! 

Yine de hayatsın, 

Yaşayacağım seni içim kan ağlarken, 

Yüzüm güleçken...', 'Çok kelek yaptın bana!  Zor anlar yaşattın,  Bazen delirttin,  Çoğu zaman şanslı olduğumu hissetirdin En şanssız zamanlarımda. Yani beni ald...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yine-de-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzeller Güzelim', 'guzeller-guzelim-deli-hasanzan-5a0kh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani derler ya, 

“İlk görüşte aşka inanırmısın? ”

Ben inanırım arkadaş.

Güzeller güzelim, 

Sen de inan! 

Sen de inan, 

Seni sevenlere, 

Ve onlara değer ver.

Sen benim güzeller güzelimdin.

Saçlarındı güzel olan.

Yok, hayır gözlerin, 

Yoksa o gülüşün müydü? 

Evet, o gülüşün! 

Beni kendimden geçiren, 

Aklımı başımdan alan, 

Hatta zor anlar yaşatan.

Sen çok güzeldin, 

Güzeller güzelim.

İnsanlığınla da! 

Alçalgönüllülüğün, 

Samimiyetin.

Ama en çok sadeliğindi, 

Beni kendine aşık eden.

Ben ilk görüşte aşka inanırım.

Sen de inan, 

Güzeller güzelim...', 'Hani derler ya,  “İlk görüşte aşka inanırmısın? ” Ben inanırım arkadaş. Güzeller güzelim,  Sen de inan!  Sen de inan,  Seni sevenlere,  Ve o...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/guzeller-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi Yalan', 'hepsi-yalan-deli-hasanzan-rpjyl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki insan, 

İki yabancı, 

Birbirlerinden habersiz, 

Geçirdikleri onca yıl.

Karşılaştılar günün birinde, 

İlk bakış, ilk gülüş.

Ve tanıştılar.

İlk buluşma, ilk heyecan.

Seviştiler, 

İlk dokunuş, ilk öpücük.

Aşık oldular, 

İlk sevgi sözcükleri, 

Hepsi yalan! 

Ayrıldılar, 

Belki ilk değil, ama son da olmayacak...', 'İki insan,  İki yabancı,  Birbirlerinden habersiz,  Geçirdikleri onca yıl. Karşılaştılar günün birinde,  İlk bakış, ilk gülüş. Ve tanıştılar...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hepsi-yalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz olmalıydık', 'biz-olmaliydik-muammer-celik-dgkb9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sendeki sen varya, işte o sendeki sen

Sevdi işte, lanet olası bu bendeki ben

Sendeki sen ile bendeki ben, 

BiZ olmalıydık, biz, ebediyyen...

Muammer Çelik

15.09.2003', 'Sendeki sen varya, işte o sendeki sen Sevdi işte, lanet olası bu bendeki ben Sendeki sen ile bendeki ben,  BiZ olmalıydık, biz, ebediyyen......', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/biz-olmaliydik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbuldum', 'i-stanbuldum-omer-faruk-cakir-4mf3e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbullu değildim, istanbuldum, 

Sen istanbulun yerlisiydin

Öyle aşina bir yüz içimde, 

Tepelerimden seyrederdin, 

Karamlığımdaki ışıkları

Gecelerimse, hep biraz soğuk olurdu

Üşürdün

Ellerin ürperirdi

Nefesin yetmezdi ısıtmaya, 

Şömineyi, içindeki ateşle yakardın

Hüzün tüterdi bacan, zehirlenirdim

Kalabalıktı sabahlarım çığlık çığlığa

Bir sen susardın içimde

İstanbuldum, sen gitmeden önce', 'İstanbullu değildim, istanbuldum,  Sen istanbulun yerlisiydin Öyle aşina bir yüz içimde,  Tepelerimden seyrederdin,  Karamlığımdaki ışıkları...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istanbuldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ne İdin Ne Yapmışlar', 'sen-ne-i-din-ne-yapmislar-murat-demir-gu3vd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ne idin, ne yapmışlar

Nasıl böyle bırakmışlar

Alıp kenara atmışlar

Atan eller kırılsaydı

Bakılmaya kıyılmazdın

Sen sıradan sayılmazdın

Kolay kolay yıkılmazdın

Yıkan eller kırılsaydı

Kaşlarını çattırmışlar

Hayatından bıktırmışlar

İdam edip astırmışlar

Asan eller kırılsaydı

Böyledemi olacaktın

Gül gibimi solacaktın

Can sendemi yanacaktın

Yakan eller kırılsaydı

Önce sevip okşamışlar

Saflığını yoklamışlar

Yerden yerlere vurmuşlar

Vuran eller kırılsaydı

Saçlarını kestirmişler

Mezarını eştirmişler

Gül bahçeni biçtirmişler

Biçen eller kırılsaydı', 'Sen ne idin, ne yapmışlar Nasıl böyle bırakmışlar Alıp kenara atmışlar Atan eller kırılsaydı Bakılmaya kıyılmazdın Sen sıradan sayılmazdın K...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-ne-idin-ne-yapmislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canı Cana Sal Benimle', 'cani-cana-sal-benimle-murat-demir-gj6wu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel elveda deme bana

Yokluğuna dayanamam

Alem gitse anlarımda

Sen gidersen anlayamam

Seviyorsan kal benimle

Canı cana sal benimle

Seve seve, güle güle

Bu aşk için öl benimle

Gurbet kötü eller beter

Giden geri dönemiyor

Felek kahpe dünya fani

Dönenlerde göremiyor

Senelerin akıp gider

Bahçene su veremezsin

Yaşın geçer ömrün biter

Güllerini deremezsin

Seviyorsan kal benimle

Canı cana sal benimle

Seve seve güle güle

Bu aşk için öl benimle', 'Gel elveda deme bana Yokluğuna dayanamam Alem gitse anlarımda Sen gidersen anlayamam Seviyorsan kal benimle Canı cana sal benimle Seve seve,...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cani-cana-sal-benimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-ozlem-torkul-tekan-cndfi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlat yolcu! 

Belli yıllar yılı suskun durmuşsun

İçinde bin bir volkan uyutmuşsun.

Akrep ve yelkovanla yarışırken

Saatini hep şafağa kurmuşsun...

Yaş kaç yolcu? 

Daha yolun başında yorulmuşsun

İlk zorlu ayaza teslim olmuşsun.

Anlık sevinçleri yaşayamazken

Bir ömür mutluluğu umuyorsun...

Dön bak yolcu! 

Dünkü çocukluğunu unutmuşsun

Şimdi büyük adamı oynuyorsun.

Bugünden yarınını hesaplarken

Zaman havuzunda boğuluyorsun...

Vur kaç yolcu! 

Elemin ölümü elinden olsun.

Hayatın ibresi umutta dursun.

Yedi kat ellere deva bulurken

Dert küpünde kaybolma ne olursun...

(8 Ocak 2002)', 'Anlat yolcu!  Belli yıllar yılı suskun durmuşsun İçinde bin bir volkan uyutmuşsun. Akrep ve yelkovanla yarışırken Saatini hep şafağa kurmuşs...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yolcu-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanımız Var', 'i-nsanimiz-var-ozlem-torkul-tekan-guxd8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanımız var ekmek sırasında

Evdeki garibi ondan aş bekler.

İnsanımız var kendi havasında

Memur maaşını bir gecede yer.

İnsanımız var üç kuruş paraya

Çalışıp kalanla yetimi gözler.

İnsanımız var düşmanlar başına

Aklı sade gezip tozmaya yeter.

İnsanımız var marka sevdasında

Modaya uymamak ona bin keder.

İnsanımız var kışın ortasında

Karda altı delik postalla gezer.

İnsanımız var özel otosunda

Evinden işine tasasız gider.

İnsanımız var çalışmak uğruna

Yol parasını boğazından keser. 

(29 Ocak 2002)', 'İnsanımız var ekmek sırasında Evdeki garibi ondan aş bekler. İnsanımız var kendi havasında Memur maaşını bir gecede yer. İnsanımız var üç ku...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/insanimiz-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durdurdum Zamanı', 'durdurdum-zamani-kenan-soyalp-izvjr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kollarımın uzanabileceği

yakınlıktasın, 

uzakta..

yarın kadar, uzak..

ben sana bu akşam tutukken…

akrebi sakladım, 

yelkovan, deli gibi dönerken..

durdurdum zamanı, 

yokluğun akmıyor artık..

uzak, 

kollarımın uzanabileceği

yakınlıkta…

akrep takıldı, 

kum saatinin boğazına', 'kollarımın uzanabileceği yakınlıktasın,  uzakta.. yarın kadar, uzak.. ben sana bu akşam tutukken… akrebi sakladım,  yelkovan, deli gibi döne...', ARRAY['Türk Edebiyatı','Şiir','Kenan Soyalp']::text[], 8.5, '{"poet":"Kenan Soyalp","poet_slug":"kenan-soyalp","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/durdurdum-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ondördüm', 'ondordum-ali-soyyigit-wc7gy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinde gizlenen 

Sevgiyi gördüm.

Aşk ateşten bir gömlek

Giy sana ördüm.

Gördüm seni, 

Sevdim; 

Sevmesem kördüm.

Sen güneşim yıldızım, 

Ayım ondördüm.', 'Gözlerinde gizlenen  Sevgiyi gördüm. Aşk ateşten bir gömlek Giy sana ördüm. Gördüm seni,  Sevdim;  Sevmesem kördüm. Sen güneşim yıldızım,  A...', ARRAY['Türk Edebiyatı','Şiir','Ali Soyyiğit']::text[], 8.5, '{"poet":"Ali Soyyiğit","poet_slug":"ali-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ondordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanetin Siyah İnciden Döktüğüm', 'i-hanetin-siyah-i-nciden-doktugum-sule-aydemir-5hqtw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dedin – çok sevildiniz

sevindi kumru yüreğim

bilir miydi siyah inciler 

dökülecek gözlerinden

sen hep eflatun

sen hep med-cezirken

ihanettir bu ağzından 

düşürmediğin sevdaya

yalan yanmadan 

dökülürken dudaklarından

kadir kıymet bilmezken

dokunup da ta yüreğe

kırdın da yar kumrumun kanadını kolunu

bir yalan bu kadar zalim olur mu

dedim – ayrılık kavuşmak içinse 

sevdadan bir çukur

sevgimin ağırlığında derin

boğdurma beni acısı eştir

çukur değilmiş  yar

bunun adı yalan

DerinYar

avuçlarında yüreğim demiştim

ne zaman şahinlere verdin

sen ki seviyorum çok derken 

tırnaklarınla nasıl ki çizdin ezdin

eller acır mı sandın yar

duygunun kapıları açıldı ışıktın karanlık gönlüme

içim sana döndü aysız gece de

nasıl kıydın nasıl şimdi vicdanın

bilemedim adım olup aşkın bağını yaksaydım

dedim ki 

geçmişteki günlerde

-ahım kaldı 

kırılan bir umut 

yanan bir bahardı

yaşam versin belanı

sevdan kendine

ihanetin sevdaya', 'dedin – çok sevildiniz sevindi kumru yüreğim bilir miydi siyah inciler  dökülecek gözlerinden sen hep eflatun sen hep med-cezirken ihanettir...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ihanetin-siyah-inciden-doktugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tescilsiz Hayat', 'tescilsiz-hayat-gurkal-aylan-tbpv1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Parmaklarımın arası açıldı benle

Yüzüklerim  tavır takınır

Saçlarım uzamaz artık

Bizi okşayan bir sevgili yok diye

Kalemlerim rüzgarlarla uçamaz 

Sevişemez bembeyaz aşk sayfalarıyla

Geriye dönüş biletimi imzalayamaz

Tertemiz kanatlar çizecek bir aşk meleğim yok diye...', 'Parmaklarımın arası açıldı benle Yüzüklerim  tavır takınır Saçlarım uzamaz artık Bizi okşayan bir sevgili yok diye Kalemlerim rüzgarlarla uç...', ARRAY['Türk Edebiyatı','Şiir','Gürkal Aylan']::text[], 8.5, '{"poet":"Gürkal Aylan","poet_slug":"gurkal-aylan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tescilsiz-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın Bugün mü?', 'yarin-bugun-mu-bekir-mutlu-gokcesu-uv5f3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yarın bugün mü baba? 

Diye sorduğunda oğlum bana

Gülmüştüm, anlayamamıştım

Sonra, sonra dank etti kafama

Parka çıkmayı, gezmeyi

Koşup oynamayı, gülmeyi

Dondurmayı, anneanneyi

Hep erteliyorduk yarına

Yarına yavrum yarına

Takılmış plak, tekrar, tekrar başa

Yarına yavrum yarına

Çocukluğuydu ertelenen aslında

Çocukluk hiç kalır mı yarına

Biraz geç oldu ama uyandım

Koştum oğlumun yanına

Yarın bugün oğlum diye haykırdım

Hiç güneş görmemiş haykırışımla

Kaptığım gibi çocuğu, doğru lunaparka

Aldık soluğu dönme dolapta', 'Yarın bugün mü baba?  Diye sorduğunda oğlum bana Gülmüştüm, anlayamamıştım Sonra, sonra dank etti kafama Parka çıkmayı, gezmeyi Koşup oynama...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yarin-bugun-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-caglar-akarsu-p01ok', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceler

...

İnmişse  perdeler, ardı arkasına, 

Her yanımı siyah bir örtü sarmışsa, 

Her zerreni şimdi ne kadar, 

Arıyorum, 

Her gece çaresizlikler içinde, 

Pencereme  doğru koşarken, 

Mavi rengi ne kadar çok sevdiğimi

Biliyorum.

Sunduğun tek şeyde, ulaşan, 

Kırmızı rengin yakıcı ateşinde

Kavruluyorum, 

Bir sessizlik sarmışsa çevremi, 

Geride dostum olmuşsa geceler, 

Parmaklarım uçundaki harfler, 

İsyan içinde benden kaçıyorlarsa, 

Bil ki bu gece yine biçareyim, 

Minik  bir not bırak sayfama, 

Geceler örtüleri kaldırırken, 

Yalnızlığımda dert olsun, 

İstiyorum, 

Kaymışsa uzaydaki yıldızlar, 

Sarmışsa  bedenimi matemin, 

Yakama iliştirdim, siyah kurdeleyi, 

Görüyorum, 

Masamda ki vazomda  bir tek

Susuz kurumuş bir çiçek, 

Kırlardan topladığımız, gelincikleri, 

Saklıyorum, 

Ölümün eli omuzsuma  yapışmışsa, 

Her yolun bir sonu gelmişse, 

Istıraplarımı her gece 

Savuruyorum

Zaman  bir tahsildar kapımda, 

Alacaklarını almış götürmüş, 

Bensiz kalmışım bir kez, 

Seninle “biz” olduğumuz

O günleri, akan gecelerden

Çalıyorum.

Hüsran  dolu sözlerimi, 

Kara tren vagonlarına, 

Katar-karar yüklerken, 

Makus kalmış kaderime, 

Küsüyorum.

Dudaklarında hep bir gülücük, 

Arkamdan, bakıp da geçerken, 

Hüzünleri “yazma” sözcüklerini, 

Hatırlıyorum.

Perişan halimle, bir başına, 

Gönül kuşlarım,  kalmışsa

Ebediyete  uçuruyorum.

2003-09-15', 'Geceler ... İnmişse  perdeler, ardı arkasına,  Her yanımı siyah bir örtü sarmışsa,  Her zerreni şimdi ne kadar,  Arıyorum,  Her gece çaresiz...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/geceler-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek ve Arı*', 'cicek-ve-ari-bayram-tunca-e5mj5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelince bahar yeryüzünde açar çiçekler

Bey arısı hangi çiçeğe konacağını şaşar

Sevincinden geçit vermeyen dağları aşar

Arıyla çiçeğin aşkını görenler, kalır naçar

Geldi mi ilkbahar tüm çiçekler koku yayar

Bey arılarıysa, çiçekler içinde çiçeğini arar

Çiçekler içindeki bir çiçek o arıyı cezbeder

O arı da o çiçeği için her şeyini feda eder

15.09.2003-15.09', 'Gelince bahar yeryüzünde açar çiçekler Bey arısı hangi çiçeğe konacağını şaşar Sevincinden geçit vermeyen dağları aşar Arıyla çiçeğin aşkını...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cicek-ve-ari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet Asla İse Kurbandı Fark Etmeze', 'i-hanet-asla-i-se-kurbandi-fark-etmeze-sule-aydemir-d9vwg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir eylül ikindisine

sıkıştırdın ayaz aralık gecesini

daha yaprak dökemeden 

hasat edemeden serpiştirdiğin 

bir tutam kar ensemde 

ölüm sessizliğinde sinsice

kitap -yağmur kokusu diyordu

kimine yaşam kimine leş

ya senin 

ne yaşamının

ne leşinin kokusu var

ölüşler bu kadar beleş 

niye

şiir –bahar bahçe diyordu

yaprak dökümüne kafesledin

ayrılıklar buluşmaya derdik

kavuşmakmış gül ve dikenine

göze kaçmış diken ihanete

bir sabah ya da bir akşam

sorma adımı anma 

yandı köprüler

bir mimarmış gibi

yeniden yapılır sanma

duygudan dere idim oynadı yerinden taşlar

nehir oldum yatak değiştirdi tüm akarlar

çağlayanım kaynağım gözlerimin pınarından

ahım var unutma kan damlar yüreğime dudağımdan

dokunduğun yerler can dağlıyor

verdiğin sözler ahım da kalıyor

yaşattığın tüm duygular yüzüme çarpıyor

yemin verdim bir ahtım geriye kalıyor

unutma gönül kolay düşmez

düşse de dilden dile gezmez

geziyorsa bitiş gelmez

bu kahrın şarkısı burada bitmez

kaldı bir tek görüntü beynimde

elim ellerinde bir köprü üstünde

vaatler yeminler vardı gözlerinde

asla, mümkün değil, kesinlikle kelimelerin de 

kurban gitti bilesin bir fark etmeze', 'bir eylül ikindisine sıkıştırdın ayaz aralık gecesini daha yaprak dökemeden  hasat edemeden serpiştirdiğin  bir tutam kar ensemde  ölüm sess...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ihanet-asla-ise-kurbandi-fark-etmeze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Bir Kelime', 'zor-bir-kelime-mehmet-fatih-kahraman-gyupr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Git! düşlerini aldıgın geceye...

Yaşamak için degil, düşünmek için yürü.

Gecende parıldayan yıldızlara bak

Bak ve gör.bakmak ile görmek arasındaki farkı....', 'Git! düşlerini aldıgın geceye... Yaşamak için degil, düşünmek için yürü. Gecende parıldayan yıldızlara bak Bak ve gör.bakmak ile görmek aras...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Kahraman']::text[], 8.5, '{"poet":"Mehmet Fatih Kahraman","poet_slug":"mehmet-fatih-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zor-bir-kelime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmedim ama bilirim', 'gormedim-ama-bilirim-mete-tugluk-2hjtx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'görmedim ama bilirim

bu çizgi vardı

senden beni ayıran benden seni bu çizgi

nar çiçeklerinin mavisi

döllenmiş beden

hüzün doğuran beynin kurbağa korkusu

labirentler

düşler

aşklar

görmedim ama bilirim

vardılar...', 'görmedim ama bilirim bu çizgi vardı senden beni ayıran benden seni bu çizgi nar çiçeklerinin mavisi döllenmiş beden hüzün doğuran beynin kur...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gormedim-ama-bilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-mete-tugluk-bx7em', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'severim yolculukları hele geceyse zaman

gözlerim karışır akıp giden karanlığa

sevinci mi

üzüncü mü

bilemem

varışın ya da ayrılışın

bir boşluk yükselir içimden

anlamdan yoksun

anlamam...', 'severim yolculukları hele geceyse zaman gözlerim karışır akıp giden karanlığa sevinci mi üzüncü mü bilemem varışın ya da ayrılışın bir boşlu...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yolculuk-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan çemberi', 'seytan-cemberi-mete-tugluk-cv8rc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'başım dönüyor dostum

beynim bir çingenenin cinselliğine yapışmış

kemanın sesi içimi tırmalıyor

kulaklarımı kapatamıyorum

ellerim yaşama sarılmış sımsıkı

bırakamıyorum...', 'başım dönüyor dostum beynim bir çingenenin cinselliğine yapışmış kemanın sesi içimi tırmalıyor kulaklarımı kapatamıyorum ellerim yaşama sarı...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seytan-cemberi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyden Sevdim Bir Kenti', 'koyden-sevdim-bir-kenti-sule-aydemir-vhjoi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'fistanımın cebindeydi tüm hayallerim

köy güzeli gibiydi tüm umutlarım

kentin duvarlarından kopmuş sevdiğim

sonradan öğrendi tesadüfen geçtiği yüreğim

yoklukta yaşadığım zenginlik akar kalbimden

bir gülümseme satın alırken tüm alınmazları

verdim gitti dedirdi ruhumda tüm açılmazları

katlandı geri geldi ağrılı kentin gri duvarları

acılar var bağrımda bıçaktan öte örselenmiş

açsam göğsümü durmaz ağlardı gören yerli yersiz

yaralarımı açan kentin gri duvarları

çaldığın sevgiden yerinde daha çok var 

köy köşesinden sevdim kenti

kentte asla sığmaz akan bir saflıktan

kapattım gözlerimi', 'fistanımın cebindeydi tüm hayallerim köy güzeli gibiydi tüm umutlarım kentin duvarlarından kopmuş sevdiğim sonradan öğrendi tesadüfen geçtiğ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/koyden-sevdim-bir-kenti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Le le yarey', 'le-le-yarey-mehmet-ali-kepez-ycrmi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saçıma dùştù kirağı

Mesken tutunca yırağı

Üç satırlık mektup yazmış

Zalimin yanmaz  yùreği

Hasretini gizledim çok

Yar yolunu gözledim çok

Gönlùmùn yarasi azdı

Bilmiyonmu özledim çok

Le le yarey le le yarey

Yaktı beni alev harey

Sen yoksun ya burada

Bol dùnya başıma darey

Yaptığın olacak şeymi

Sevda bu solacak şeymi

Hayat dediğin bir nefes

Kepez e kalacak şeymi', 'Saçıma dùştù kirağı Mesken tutunca yırağı Üç satırlık mektup yazmış Zalimin yanmaz  yùreği Hasretini gizledim çok Yar yolunu gözledim çok Gö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/le-le-yarey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatyalar Derleyem', 'papatyalar-derleyem-gul-pembe-mffls', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yitirmisim ben   kendi ozumu, 

Gayri bu diyarlari terk eyleyem......

Kimler yerse yesin baglar uzumu

Ben sizlere papatyalar derleyem...

Atam kendim yuce viran daglara, 

Papatyalar derleyem de... derleyem....

Beni bende bulan nice saglara

Sevgi ile bol selamlar soyleyem...

Gul Pembe der, ozsuz beni neyleyem? 

Yanik yanik turkulerle soyleyem...

Gun ola ki ozlu beni eyleyem, 

Papatyalar derleyem de...derleyem...', 'Yitirmisim ben   kendi ozumu,  Gayri bu diyarlari terk eyleyem...... Kimler yerse yesin baglar uzumu Ben sizlere papatyalar derleyem... Atam...', ARRAY['Türk Edebiyatı','Şiir','Gul Pembe']::text[], 8.5, '{"poet":"Gul Pembe","poet_slug":"gul-pembe","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/papatyalar-derleyem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık', 'kirik-muharrem-koray-pj68y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sanki senin gibi

kırık bir adı olmalı

insanın

deli bir yanı olmalı

beyaz, kumaştan bir

kaptan şapkası

hayata 

selam çakmalı

pazartesi ya da salı

her gün, her gün yaşamalı

devrik aşkların

geçer de yarası

kabullenmek

işte

oyunun kuralı', 'sanki senin gibi kırık bir adı olmalı insanın deli bir yanı olmalı beyaz, kumaştan bir kaptan şapkası hayata  selam çakmalı pazartesi ya da ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Koray']::text[], 8.5, '{"poet":"Muharrem Koray","poet_slug":"muharrem-koray","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kirik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tırnak arası', 'tirnak-arasi-muharrem-koray-sjbv9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çakırkeyif isimlerin efendisi! 

Bir dakika var, sonra işte puff...

Kalburüstü bir intikamdın, 

Bir intikamdın, 

Çok uzaktan da uzaktın...

Sabah uyanır da arardım seni, 

Yokluğunun yoklamasını bile alamazdım.

Duvarlara yazardım, 

Şeklini duvarlara yazardım! 

İki tırnak arasına alırdım, 

Tırnak yaralarını saklardım.', 'Çakırkeyif isimlerin efendisi!  Bir dakika var, sonra işte puff... Kalburüstü bir intikamdın,  Bir intikamdın,  Çok uzaktan da uzaktın... Sa...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Koray']::text[], 8.5, '{"poet":"Muharrem Koray","poet_slug":"muharrem-koray","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tirnak-arasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş', 'tas-muharrem-koray-6zxzj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorulmak yok! 

Hadi kalk da gidelim...

Bunlar olacak elbet, 

Bir dahakine diyelim.

Üzülmek yok! 

Hadi gül de geçelim...

Artık öğrendin elbet, 

Öyle kabul edelim.

Ağlamak yok! 

Hadi evet de bilelim...

Yol uzun elbet, 

Biz yolumuza gidelim.', 'Yorulmak yok!  Hadi kalk da gidelim... Bunlar olacak elbet,  Bir dahakine diyelim. Üzülmek yok!  Hadi gül de geçelim... Artık öğrendin elbet...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Koray']::text[], 8.5, '{"poet":"Muharrem Koray","poet_slug":"muharrem-koray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tas-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duman', 'duman-muharrem-koray-8k6tn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'adını dillere sarmalı senin

söyleye söyleye bitirmeli seni

ateşe vermeli ismini

seni duman edip üflemeli', 'adını dillere sarmalı senin söyleye söyleye bitirmeli seni ateşe vermeli ismini seni duman edip üflemeli...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Koray']::text[], 8.5, '{"poet":"Muharrem Koray","poet_slug":"muharrem-koray","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/duman-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülme', 'uzulme-derin-oger-ujazg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni içime hapsettim

Kan çiçekleri gibi açacaksın

Güzümde sararacak 

Güneşlerimde kavrulacaksın

Kalbimde kopan fırtınalarda

Sen de ters yüz olacaksın

Üzülme bir kaç damla gözyaşıma

Ağlasam boğulacaksın........', 'Seni içime hapsettim Kan çiçekleri gibi açacaksın Güzümde sararacak  Güneşlerimde kavrulacaksın Kalbimde kopan fırtınalarda Sen de ters yüz ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzulme-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni', 'beni-ozgur-sirius-kp5cw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgarına kapılırsam es beni

Yaprak yaprak defterinden kes beni

Tek hatası sevmek diye yazdırıp

Sayfa sayfa duvarlara as beni

Böyle aşklar tarihtede görülmüş

Görülenler üzerine yaz beni

Kefenim de siyah iple örülmüş

Örenlere mezar olsun kaz beni

Bedenimle acılara doymuşum

Etkilenmez durma sende üz beni

Yanıyorum kaderime uymuşum

Söndüremez sevgilerle buz beni

Yazılmıyor kara sevda kağıda

Aşkın ile terk ediyor söz beni

Aşılmıyor sensiz gönül dağıda

Anlatamaz oldu artık saz beni

Kar etmiyor unutmaya içkiler

Şişelere boşaltsanız az beni

Aşka kurban yine beni seçtiler

Kaderimse ilk sıraya yaz beni', 'Rüzgarına kapılırsam es beni Yaprak yaprak defterinden kes beni Tek hatası sevmek diye yazdırıp Sayfa sayfa duvarlara as beni Böyle aşklar t...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beni-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-ozgur-sirius-upnjv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gece yıldızım yine parlıyor

Gittiğin geceye güne ağlıyor

Bu yollar seveni sana bağlıyor

Girmesem olmuyor girsem olmuyor

Gün çoktan ağarmış saat çalmıyor

Yelkovan ağlamış akrep gülmüyor

Gittiğin saatte durmuş dönmüyor

Sevmesem olmuyor sevsem olmuyor

Karanlık bastırdı rüzgar esmiyor

İçtiğim içkiler beni kesmiyor

Rüyada gibiyim ölüm sesliyor

Kalkmasam olmuyor kalksam olmuyor

Kendimi öldürsem kimse bilmiyor

Bıçağı kalbime itsem girmiyor

Saatler maziyi sensiz silmiyor

Sevmesem olmuyor sevsem olmuyor

Ne yapsam gönlümün suçu gitmiyor

Sevginin kadere gücü yetmiyor

Aşkımız bir kumar oldu bitmiyor

Yenmesem olmuyor yensem olmuyor', 'Bu gece yıldızım yine parlıyor Gittiğin geceye güne ağlıyor Bu yollar seveni sana bağlıyor Girmesem olmuyor girsem olmuyor Gün çoktan ağarmı...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olmuyor-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Kabahat', 'sende-kabahat-ozgur-sirius-j9lx0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkın ateşiyle kavrulup  piştim		

Büyük bir çırada içine sen at

Sabahlara kadar ayılıp içtim

İçkinin suçu yok sende kabahat

Evinin önünden bin kere geçtim

Aç şu pencereyi dışarı göz at

Bin güzel dururken ben seni seçtim

Bu aşkın sonu yok sende kabahat

Aşk diye yanmadan önce bir hiçtim

Gönül bir resimmiş sevmekse sanat

Sevgiyi ekerken ayrılık biçtim

Gönlümün derdi çok sende kabahat

Bende bir zamanlar sevgili gençtim

Konuyu açmadan ne olur kapat

Bu hayat derdine düşmeden dinçtim

Derdime çare yok bende kabahat', 'Aşkın ateşiyle kavrulup  piştim		 Büyük bir çırada içine sen at Sabahlara kadar ayılıp içtim İçkinin suçu yok sende kabahat Evinin önünden b...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sende-kabahat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemiyorum', 'sevemiyorum-ozgur-sirius-fx9ul', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgilim dünyalar yıkılsa bile

Aşıklar sebepsiz ayrılsa bile

Gözlerim gözünü unutsa bile

Senden başkasını sevemiyorum

Elbette dileğim gerçek olacak

Ben değil sözlerim geri kalacak

Yanacak bu gönlüm sensiz yanacak

Senden başkasını sevemiyorum 

Hatalar peş peşe sıralanıyor

Aşkımız günahla karalanıyor

Tertemiz kalbimiz yaralanıyor

Senden başkasını sevemiyorum

Bedenim girecek bir gün toprağa

Gerçekler çıkacak bensiz açığa

Ağlarsın yazdığım bu son satıra

Senden başkasını sevemiyorum', 'Sevgilim dünyalar yıkılsa bile Aşıklar sebepsiz ayrılsa bile Gözlerim gözünü unutsa bile Senden başkasını sevemiyorum Elbette dileğim gerçek...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevemiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevilmez', 'sevilmez-ozgur-sirius-u4f6d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiyle başlayan her kötü sonda

Alacağın bir ders vardır bilinmez

Biri diğerine tutmuyor oysa

Sevdiğim en kötü yardır sevilmez

Gördüğün rüyayı sen hayra yor da

Hayallere dalıp aşka gidilmez

Gitmeden öncesi bana bir sorda

Yar üstüne yardan başka sevilmez

Sözlerim başkadır fikirim başka

Bir garip haldeyim sırrım çözülmez

Ben seni sevmeden ölseydim keşke

Çileler çekmeden yarim sevilmez

Çekinme şu teni ver kuşa kurda

Sevmekten sararmış belki yenilmez

Musalla taşına koyduğun anda

Gönül son sözünü derki sevilmez', 'Sevgiyle başlayan her kötü sonda Alacağın bir ders vardır bilinmez Biri diğerine tutmuyor oysa Sevdiğim en kötü yardır sevilmez Gördüğün rüy...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevilmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sormadan', 'sormadan-ozgur-sirius-zihtv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günler geçiyor gülüm bize sormadan

Hayat bitiyor bizi bizi bulmadan

Sana bana oynanan bu oyunları

Unutalım mı bizi bizi yormadan

Sevgi çiçeği gülüm daha solmadan

Aşk rüzgarları yine yine durmadan

Seni beni sevmeyen şu insanları

Yok edelim sevgilim bizi vurmadan

Aşkımızın güneşi daha batmadan

Ayrılık ateşleri böyle yanmadan

Sevgi sözü etmeyen o dudakları

Kapatalım kimseler bunu duymadan

Kader söylüyor bize atla korkmadan

Birlikte gideriz biz geri bakmadan

Doya doya sevmeyen kör gönülleri

Kurtaralım idama mahkum olmadan', 'Günler geçiyor gülüm bize sormadan Hayat bitiyor bizi bizi bulmadan Sana bana oynanan bu oyunları Unutalım mı bizi bizi yormadan Sevgi çiçeğ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sormadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gittin gideli', 'sen-gittin-gideli-ozgur-sirius-vscb9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerim uzağa hiç dalmamıştı

Gözyaşım yerlere damlamamıştı

Uyurken bedenim ağlamamıştı

Sen gittin gideli canım sevgilim

Bu günde nedensiz ağlıyorum ben

Durmadan aklıma geliyorsun sen

Kalbimin kapısı artık demirden

Sen gittin gideli canım sevgilim

Kararı belki de kader veriyor

Gerçeği şüphesiz öne seriyor

Gelip geçen herkes seni soruyor

Sen gittin gideli canım sevgilim

Bir ateş yanıyor deli gönlümde

Kader utanıyor benim ömrümde

Gözyaşım kuruyor iki gözümde

Sen gittin gideli canım sevgilim

Ayrılık izi var yaşlı tenimde

Gençliğim yok oldu senin elinde

Şarabın tadı yok artık dilimde

Sen gittin gideli canım sevgilim

Sensizim demeye çok korkuyorum

Kim bilir belki de utanıyorum

Gönlüme başka yar bulamıyorum

Sen gittin gideli canım sevgilim', 'Gözlerim uzağa hiç dalmamıştı Gözyaşım yerlere damlamamıştı Uyurken bedenim ağlamamıştı Sen gittin gideli canım sevgilim Bu günde nedensiz a...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-gittin-gideli-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-ozgur-sirius-yhsy5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her gün sarhoş olmaktan usandım artık

En sevdiğim içkiyi içmedim bu gün

Gönül defterinden de silersin artık

Gülüm diye ismini anmadım bu gün

Gömleğimin kolunda kocaman yırtık

Hediye ettiğini giymedim bu gün

Bir mum gibi erittin üzülme artık

Kaç gündür yanıyorum bitmedim bu gün

Kıskanılan bu aşkı ateşe attık

Yanar durur külleri uçuşur bu gün

Biz cehennem için mi cenneti sattık

Melekler bile ağlar üzülür bu gün

Gözlerim kan damlıyor göremem artık

Vücudum tir titriyor üşüyor bu gün

Sevenlerle birlikte ağlarız artık

Ahirette yolumuz düşerse bir gün', 'Her gün sarhoş olmaktan usandım artık En sevdiğim içkiyi içmedim bu gün Gönül defterinden de silersin artık Gülüm diye ismini anmadım bu gün...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gun-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diye', 'diye-ozgur-sirius-ibx0j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerin yanacak, yüzün solacak

Benden başkasını bekledin diye

Kalbine demirden bir kuş konacak

Aşkıma ihanet ekledin diye

O şarkı bir gece yine çalacak

Mumların ışığı cama vuracak

Masada tertemiz her şey kalacak

Bu gece yanıma gelmedin diye

Hasretin kolları bizi saracak

Tertemiz kalbimde sızı azacak

Bedenim kendine mezar kazacak

Derdimin dermanı olmadın diye

Aşkımız tarihe konu olacak

Nede çok seviyor diye yazacak

Ferhat da Şirinde unutulacak

Sevgimi herkese söyledin diye

Sözlerim kanımla karalanacak

Cennetin kapısı aralanacak

Melekler ardıma sıralanacak

Sen beni gerçekten sevmedin diye

Özgüre söyleyen diller susacak

Hayretle izleyen gözler asacak

Bedenim bu sırra kadem basacak

Aşkımı kimseler duymasın diye

Çığlığım ne yüce dağlar aşacak

Sevgimi duyanlar öyle şaşacak

Sadece sevenler benden kaçacak

Onlara nazarım deymesin diye', 'Ellerin yanacak, yüzün solacak Benden başkasını bekledin diye Kalbine demirden bir kuş konacak Aşkıma ihanet ekledin diye O şarkı bir gece y...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/diye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmadı', 'kalmadi-ozgur-sirius-5s0ab', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yazacak öyle çok kağıdım varda

Bu aşkın sonunda sözüm kalmadı

Sazımın teline vurduğum anda 

Seni anlatmaya lüzum kalmadı

Kördüğüm olmuşum çözümüm yarda

Diye diye yanan közüm kalmadı

Öldürüp bıraktın beni dünyada

Ağlamak için göz yaşım kalmadı

Özgürüm ne işin varki bu handa

Hadi git tek dostun sazın kalmadı

Sevginin çoğuna layıksın sanma

Çoğundan vazgeçtim azın kalmadı', 'Yazacak öyle çok kağıdım varda Bu aşkın sonunda sözüm kalmadı Sazımın teline vurduğum anda  Seni anlatmaya lüzum kalmadı Kördüğüm olmuşum çö...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalmadi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helal Sevda', 'helal-sevda-abdurrahman-cankaloglu-3q6lh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zordur kadere gülümsemek, 

Ümidini kaderinle beslemek, 

Zordur bir kere sevebilmek; 

Sevdin mi tam sevmek.

Sevdalar vardır, iskele misali

Yanlızca mola verir, beklersin; 

Birgün muhakkak biter bekleyişin

O zaman anlarsın bu senin kaderin

Seni seviyorum demek, tertemiz

Ve ağlamak yeri geldiğinde; 

Kimin için ve neye ağladığını bilerek

İşte budur sevmek demek! 

Kaderimin en mübarek yazgısı

Kalbimin efendisi tek sahibi

Yaşama sebebim, tek rüyam

Seni seviyorum Helal Sevdam.', 'Zordur kadere gülümsemek,  Ümidini kaderinle beslemek,  Zordur bir kere sevebilmek;  Sevdin mi tam sevmek. Sevdalar vardır, iskele misali Ya...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Çankaloğlu']::text[], 8.5, '{"poet":"Abdurrahman Çankaloğlu","poet_slug":"abdurrahman-cankaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/helal-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk - Etme', 'terk-etme-ahmet-aksoy-xj7ts', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soracaksan neden diye

Terk-etme

Soracaksan hesabını

Yaptıklarımın

Terk-etme

Çünkü ben hesaplayamam

Yapacaklarımı

Eğer gidersen

Bil ki gidişinle

Ne aklım kalır ne de yüreğim

İkisi de peşinde gelecektir

Ve ben akılsız

Ve ben yüreksiz

Ne yaparım

Soracaksan eğer

Neden öldün diye

Terk-etme

Çünkü

Bu terk edişin

Benim için ancak

Cerrahlıktan cellatlığa 

Geçişin.', 'Soracaksan neden diye Terk-etme Soracaksan hesabını Yaptıklarımın Terk-etme Çünkü ben hesaplayamam Yapacaklarımı Eğer gidersen Bil ki gidişi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/terk-etme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü Beklemek', 'olumu-beklemek-ahmet-aksoy-ypacx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece boğulurken her şafak

Nesnelliğini yitirmiş bir sabahta

Beklemek, bir ölümü izleyerek

Ki sanki canlıyım der

Her gece, şafakta ölerek

Aydınlık bir kefen içinde

An an eriyerek.

Beklemek bir hüzün içinde

Bitmek tükenmek bilmeden

Bitmez tükenmez bir kederle

Süzülmek bir şişenin gözlerinde

Aşksız, sevgisiz sarhoş olarak

Ah bir ölüme ortak olmak

Beklemek bir sabahı

Beklemek bir geceyi

Geceyi güne 

Günü geceye sunarak.

Ve ah çilelere çile ekmek

Dolmuş bir kumbaraya

Yeni acılar sıkıştırmak

Ve beklemek, 

Yaşamın kumbarası

Bir yüreği bozdurmayı

Son karanlığa dek...', 'Gece boğulurken her şafak Nesnelliğini yitirmiş bir sabahta Beklemek, bir ölümü izleyerek Ki sanki canlıyım der Her gece, şafakta ölerek Ayd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olumu-beklemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğinden Sevgi Aldım', 'yureginden-sevgi-aldim-hulya-arisan-u9sxr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni o gizemli dünyana aldın, 

beni o hayatla tanıştırdın.

Yaşamı senin gözlerinde

mutluluğu  dudaklarında buldum.

Gece ve gündüz birbirine karıştı, 

bir an geldi arkadaş, 

bir an geldi dost oldun

ama geceme MAVİ ışık, 

dünyama nur oldun.

Sesinden etkilendim

ruhundan tat, 

duygularından coşku, 

yüreğinden sevgi aldım.

İstanbul, Eylül 2003', 'Beni o gizemli dünyana aldın,  beni o hayatla tanıştırdın. Yaşamı senin gözlerinde mutluluğu  dudaklarında buldum. Gece ve gündüz birbirine ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yureginden-sevgi-aldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-seref-kaya-9tud3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gece, gelmeye bilirim

Bir gece, yazamaya bilirim

Bir gün, konusamaya bilirim

Bir gün, göremeye bilirim

Bir bilsen; neler, neler düslüyorum

Bir bilsen; duymasam sesini üsüyorum

Bir bilsen; neler yazmak istiyorum

Bir bilsen; ne kadar cok özlüyorum

Bilmek istemiyorsun

Duymak istemiyorsun

Yazmak istemiyorsun

Gercekgi söyle, hic mi? sevmiyorsun! !      seref kaya 11.09.03 ffm.', 'Bir gece, gelmeye bilirim Bir gece, yazamaya bilirim Bir gün, konusamaya bilirim Bir gün, göremeye bilirim Bir bilsen; neler, neler düslüyor...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soyle-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son gece', 'son-gece-seref-kaya-amgu8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne seni; anama anlatmalarim

Ne senin icin, yazdigim siirlerim

Ne sevdasina ilk baslangicim

Bu gece ikimizin son gecesi

Ne sana; benim dogrularim

Ne sevdigimi bilen, sahitlerim

Ne sevdami, ilk haykirisim

Bu gece ikimizin son gecesi

Ne saatlerin tikir, tikir isleyisi

Ne gökyüzünde, kopan firtinalar

Ne uykusuz kaldigim, geceler

Bu gece ikimizin son gecesi

Ne senin, ürkek yesil gözlerin ceylanim

Ne kör kuyuda askini arayan benim

Ne sonu gelecek, aglamalarimiz

Bu gece ikimizin son gecesi

Ne sevildim, ne güvenildim

Ne dogrularima inandin, 

 ne yalanlarima

Neden agladim, hala anliyamadim.

(Devami var! !)       13-10-03   seref.kaya ffm.', 'Ne seni; anama anlatmalarim Ne senin icin, yazdigim siirlerim Ne sevdasina ilk baslangicim Bu gece ikimizin son gecesi Ne sana; benim dogrul...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/son-gece-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gir Koynuma', 'gir-koynuma-ali-osman-yilmaz-ssiig', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GİR KOYNUMA

Neden baktın güzel bana böyle

Tanışmı geldim sana söyle

Mahçupluğun nedendir öyle

Yakarsın ya beni; bakma öyle

Tanıdığın belli haydi söyle

Canım yanıyor bakınca bana

Gözün ısırıyorsa bir yerden 

Gir koynuma sarıver şöyle', 'GİR KOYNUMA Neden baktın güzel bana böyle Tanışmı geldim sana söyle Mahçupluğun nedendir öyle Yakarsın ya beni; bakma öyle Tanıdığın belli h...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gir-koynuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-emre-ozoran-d1xb2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen şiir, 

Gündüz rüya görmektir.

Nedense seni şiir etmek zor.', 'Bazen şiir,  Gündüz rüya görmektir. Nedense seni şiir etmek zor....', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/siir-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elif', 'elif-ali-osman-yilmaz-0gvdr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elif gibi burcu burcu kokarsın

Benim halim hep dertlere sokarsın

Olsam arı tatmak için balından

Geldiğimde benim iğnem ile sokarsın.', 'Elif gibi burcu burcu kokarsın Benim halim hep dertlere sokarsın Olsam arı tatmak için balından Geldiğimde benim iğnem ile sokarsın....', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/elif-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Gibi', 'ay-gibi-ali-osman-yilmaz-it1q1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzün ay gibi berrak ve temiz

Ellerin ana sütü gibi tertemiz

Yaklaş bitsin bu gurbet acısı

Özlemimiz bir; aynı güle hasretiz

Eğer bir gün buluşursa sevgimiz

Mutluluk ondandır iyi biliriz

Verir kendini saran kollarıma

Sevgilim sanki enginlerden bir deniz

Girerim koynuna beni sarar bir anda

Sevdası içten, aşkı canandır bana

Gitmem artık kavuşmuşken ben ona

Bu illerden başkada bir yabana', 'Yüzün ay gibi berrak ve temiz Ellerin ana sütü gibi tertemiz Yaklaş bitsin bu gurbet acısı Özlemimiz bir; aynı güle hasretiz Eğer bir gün bu...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ay-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Gözler', 'kirik-gozler-emre-ozoran-9bo0l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığı

Kaldırımda kaçış sesleri, 

Yağmurun içinde

Uzaklaşma isteği...

Kaybolur mu gecenin içinde gölgeler? 

Gözler parlamaz mı? 

Yalan söylesem, 

Beni aldatsan, 

Anlar mısın? 

Gözlerim kırılır mı bakarken?', 'Gecenin karanlığı Kaldırımda kaçış sesleri,  Yağmurun içinde Uzaklaşma isteği... Kaybolur mu gecenin içinde gölgeler?  Gözler parlamaz mı?  ...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kirik-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De-me-ye-ce-ğim', 'de-me-ye-ce-gim-ahmet-aksoy-e1mf0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıvanmış bir duvarken ördüğün

Tuğlalarını tek tek dizdiğin

Sana gitme deme-yeceğim

Kara bir örümcek gibi

Öyle sık öyle sık örerken ağını

Sana dur deme-yeceğim

Bir ışıklık yer bırakmazken

Ancak bir bakışlık yakın olmaya

Sana yapma deme-yeceğim

Beni suçlarken durmadan

Suçüstü yakalamışçasına

Masumum, masumum deme-yeceğim

Çünkü bilirim, 

Bir ayrılık duvarı nasıl örülür

İşte bu yüzden, harcına kan 

Toprağına göz yaşı vereceğim

Fakat dönmeyeceğini bildiğimden

“Dur gitme sonsuzluğa” de-me-ye-ce-ğim.', 'Sıvanmış bir duvarken ördüğün Tuğlalarını tek tek dizdiğin Sana gitme deme-yeceğim Kara bir örümcek gibi Öyle sık öyle sık örerken ağını San...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/de-me-ye-ce-gim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paşa Babanın Paşadır Gönlü', 'pasa-babanin-pasadir-gonlu-ahmet-aksoy-tt2pq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni, bir hisarda bıraktım

Atımla yeni bir sefer için uzaklaşırken

Ve sen el sallıyordun

Hisarın yüksek bir kulesinden

Gidiyordum uzak bir kente

Sırf biraz daha umut yüklemek için

Senin sedeften kalbine, 

Aslında biliyordum senin bilmediğini

Umut yoktu bizim için

Çünkü vermişti kararını paşa baban

Bizi evlendirmek vaadiyle

Beni düşman komutanına yollarken.', 'Ben seni, bir hisarda bıraktım Atımla yeni bir sefer için uzaklaşırken Ve sen el sallıyordun Hisarın yüksek bir kulesinden Gidiyordum uzak b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/pasa-babanin-pasadir-gonlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ürpermek Gibidir Sensizlik Cennette', 'urpermek-gibidir-sensizlik-cennette-ahmet-aksoy-ieg3c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ürpermek gibidir sensizlik Cennette

Ölmek gibidir ölümsüzlük şerbetini içip de

Ve kaybolmak yok olurcasına kaybolmak

Kendi içine dönük, senin olmadığın her yerde.

Karıncalar taşır umut taneciklerini

Ki onlar azimli ve çalışkandır

Ama yazık ki yapraklarla batarlar

Sulardan geçerken, nehirlere.

Çünkü sensizlik akar sel gibi

Katarak akıntısına doğan umutlarımı

Ah yeşermek ne günlere kaldı

Sensizlik gömerken tüm umutlarımı.', 'Ürpermek gibidir sensizlik Cennette Ölmek gibidir ölümsüzlük şerbetini içip de Ve kaybolmak yok olurcasına kaybolmak Kendi içine dönük, seni...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/urpermek-gibidir-sensizlik-cennette-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sılada Ölmek Gibidir Ayrılık', 'silada-olmek-gibidir-ayrilik-ahmet-aksoy-adylg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sılada ölmek gibidir ayrılık

Yad ellerde kalır yürek

Bir çürümeye yüz tutuştur

Bir terk edişin ardına gizlenmiş.

Sindiği yerden kalkmaya yeltenir

Ve ne yazık ne yazık ki

Sinsiliğiyle yücelir

Ne diş geçer ona

Ne de tırnak

Etten kemikten değildir, 

Gölge gibi dolanır ayrılık.

Belki bir gece 

Bir gece aydınlanır

Bir umut kırıntısı kalmıştır

İçi geçer ölenlerin

Oysa bir umut değildir.

Geceyi aydınlatan

Havayi fişekler

Yalnızca sinsiliğin

Zafer kutlamalarıdır.', 'Sılada ölmek gibidir ayrılık Yad ellerde kalır yürek Bir çürümeye yüz tutuştur Bir terk edişin ardına gizlenmiş. Sindiği yerden kalkmaya yel...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/silada-olmek-gibidir-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluşma tarihimiz', 'bulusma-tarihimiz-muammer-celik-lu8jq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonsuzluk takviminin

Ölümden sonraki

ilk yılın

ikinci ayının

adı henüz konmamış 

gününün akşamına

serilmemiş döşeği

ile örtülmemiş yorganı

arasındaki öpülmemiş

dudaklarda olacak

seninle buluşmamız…! 

BirDeli

Eylül 2003', 'Sonsuzluk takviminin Ölümden sonraki ilk yılın ikinci ayının adı henüz konmamış  gününün akşamına serilmemiş döşeği ile örtülmemiş yorganı a...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bulusma-tarihimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çek Tetiği', 'cek-tetigi-muammer-celik-w2k2w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kirpiklerine takılan 

yeşil bakışım

damla damla ıslanıyor, 

yüreğine çakılan

kara sevdam

cayır cayır yanıyor…

Akan özlem terlerim

Göbek çukurunda çoğalıyor

Taşıyor dalga dalga

Beni daha da çıldırtıyor...

İstesemde kendimi tutamıyorum

Tetiği çekmeyi sana bırakıyorum

Muammer Çelik

Eylül-2003', 'Kirpiklerine takılan  yeşil bakışım damla damla ıslanıyor,  yüreğine çakılan kara sevdam cayır cayır yanıyor… Akan özlem terlerim Göbek çuku...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cek-tetigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülü seviyorsun Kendin için', 'gulu-seviyorsun-kendin-icin-muammer-celik-4ocby', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gönül dergahında motif motif gül dokurken, 

içeri alacak mısın diye, ben kapında bekliyorum… 

Sen gönül cennetinde geziyorken, 

ben yağmurlu havada gözlerimi siliyorum... 

Sen gülü seviyorken Kendin için, 

ben gözlerimden dökülen incileri okşuyorum, 

........................................................senin icin...! 

Muammer Çelik 

11.08.2003', 'Sen gönül dergahında motif motif gül dokurken,  içeri alacak mısın diye, ben kapında bekliyorum…  Sen gönül cennetinde geziyorken,  ben yağm...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gulu-seviyorsun-kendin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doluyum Sana', 'doluyum-sana-muammer-celik-pjzhn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sana asırlardır doluyum 

ve hala sana boşalamadım 

seni gördüm, dokundum 

yinede boşalamadım 

sadece tutamadığımdan 

bir kaç damla yaşla ezdim, 

kırdım, içimi dolduranları parçaladım… 

Sen anlatmakla bitmeyecek KADINSIN 

sen şiirlere bile sığmayacaksın 

sadece anlatmaya çalışırım seni 

yetmeyen ve hiç yetmeyecek dağarcığımla… 

Duygular bile ima edemez 

hisler bile ifade edemez seni 

sen sadece ve yalnızca 

iliklerine kadar, 

kemiklerin eriyinceye kadar 

yaşınırsın ve yaşanmalısın... 

Seni yaşamakta yetmez 

seninle ancak bütünleşmek gerek 

o zaman sana ulaşılabilinir, dokunulabilinir... 

Sen ezelden ayrı düştüğüm 

zaman ve mekan içinde bulamadığım, 

sen cennete kadar içimde sakladığım, 

koklamaya bile kıyamadığımsın... 

Sen 

şiir şiir yazdığım 

name name okuduğum 

aldığım nefesim 

ve en son vereceğim CANIMSIN... 

Muammer Çelik 

11.08.2003

Muammer Çelik', 'Ben sana asırlardır doluyum  ve hala sana boşalamadım  seni gördüm, dokundum  yinede boşalamadım  sadece tutamadığımdan  bir kaç damla yaşla...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/doluyum-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte', 'i-ste-mehmet-ali-kepez-n4fzu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onursuz yaşamın tadı olurmu

	Olmayan şeylerin adı olurmu

	Fakir şükr ederek rızık bulurmu

	Bir ekmek peşine koşuyor iste

	Alma sözlerimi dostum şakaya

	Böyle düşmedikmi sanki fakaya

	Yapıştırdık zalimleri yakaya

	Kopmuyor bir türlü yaşıyor işte

	Özgürlük layıkmı korkak canına

	Bir türlü gelmedin  hakkın yanına

	Kuzgun pençesini takmış karnına

	Kanlı sofrasinda deşiyor iste

	Sen bir marabaydın oğlun àmele

	Memleketim dokuz aylık hamile

	Bir bina yapmalı sağlam temele

	Temelsiz duvarlar düşüyor iste', 'Onursuz yaşamın tadı olurmu 	Olmayan şeylerin adı olurmu 	Fakir şükr ederek rızık bulurmu 	Bir ekmek peşine koşuyor iste 	Alma sözlerimi dos...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iste-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler Gömüyorum Her Gece', 'oluler-gomuyorum-her-gece-ahmet-aksoy-eidx2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bir mezarcıyım

Ölüler gömüyorum her gece

Benliğime, etrafta kimse yokken

Sesler nesneleri terk etmişken 

Ben bir gardiyanım

Milyonlarca mahkum kilitliyorum

Milyonlarca umutla

Umudun ekmek olduğu hücrelerime

Ben bir yargıcım

Binlerce kalem kırıyorum

Suçu masumiyet olan

Dökülmüş göz yaşlarıma

Ben bir bahçıvanım

Her gece mezarlardaki

Ölü çiçeklerine can suyu veriyorum

Gideni döndürmek istercesine

Ve ben meşhur bir kumpanyanın

Afişlerde kalmış oyuncusuyum

Son senaryonun son ezberleriyle

Hasta yatağımda “yalnız” ve “yalnızca”

Ölümü bekliyorum....', 'Ben bir mezarcıyım Ölüler gömüyorum her gece Benliğime, etrafta kimse yokken Sesler nesneleri terk etmişken  Ben bir gardiyanım Milyonlarca ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oluler-gomuyorum-her-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışlarının Derinliklerindeyim', 'bakislarinin-derinliklerindeyim-derin-oger-dsthx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlamı yok artık

Parçalanmış bakışların

Gözlerinde vurgun yemiş gözlerim

Batık gemiler misali

Bakışlarının derinliklerindeyim

Gözlerim savunmasız

Sesten soluktan yoksun

Dalgalanıp durdukça yosunların

Yavaş yavaş örter üstünü kumların

Seni görmenin imkânsızlıklarındayım

Anlamı yok artık 

Menekşe kokulu rüzgârların

Çıplak kollarıma dalan güneşi aramanın

Adını anımsamadan yaşamanın

Muhalefetindeyim çözümsüz duygularımın 

Sorgularında kendi sesimin..............', 'Anlamı yok artık Parçalanmış bakışların Gözlerinde vurgun yemiş gözlerim Batık gemiler misali Bakışlarının derinliklerindeyim Gözlerim savun...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bakislarinin-derinliklerindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-ali-soyyigit-3xy3p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çiçeklerin sultanı

Sembolü güzelliğin.

Düşme elimden

Gülüm; 

Gitmesin güzelliğin...', 'Çiçeklerin sultanı Sembolü güzelliğin. Düşme elimden Gülüm;  Gitmesin güzelliğin......', ARRAY['Türk Edebiyatı','Şiir','Ali Soyyiğit']::text[], 8.5, '{"poet":"Ali Soyyiğit","poet_slug":"ali-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gul-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün', 'bu-gun-ayse-mattaogullari-0amit', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu gün yatağımdan çok mutlu kalktım

şöyle bir etrafıma bakıp

doğruca çaydanlığın altını yaktım.

öperek uyardığım yavrularımla

orta halli bir kahvaltı yaptım.

eşim doldururken çayları

ben işimin hazırlıklarını yaptım.

''Allah ısmarladık'' diyen çocukların

sesiyle irkilip, 

arkalarından camdan baktım.

eşimle vedalaşıp

çantamı koluma taktım.

beni taşıyan ayaklarıma

teşekkür edip, 

mutluluğumun nedenini kafama taktım.

yaşıyorum, sağlıklıyım 

sevenlerim ve sevdiklerimin

sevgilerine bereket

sepetteki mutluluk bulutlarını

tüm insanların üzerlerine attım.

haydi yakalayın...', 'bu gün yatağımdan çok mutlu kalktım şöyle bir etrafıma bakıp doğruca çaydanlığın altını yaktım. öperek uyardığım yavrularımla orta halli bir...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Mattaoğulları']::text[], 8.5, '{"poet":"Ayşe Mattaoğulları","poet_slug":"ayse-mattaogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-gun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhuma Geceler Yağıyor', 'ruhuma-geceler-yagiyor-sule-aydemir-f42ay', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ruhuma geceler yağıyor yağmur gibi

ellerim buz kesmiş

bir aptala dönmüş yalnızlığında

gelir miydi ki diyor kapanan kapılar ardında

birkaç damla yaş akıyor

KanÇiçeği Yarim Haziran’ a

önce bir zirve kar kaplanıyor

ardından yalan bir çığlık

sonra bir çığ sarsıyor yüreğimi

buz kesen oluyor

yoksa ellerim mi 

şair fısıldadı sanki yine; 

-sıkıntılarım dağlar kadar

 cebimdeki misketler dağlar

yürür müyüm 

derman serden mi

gönül vermiş bir de almış sanmış

niye bu kadar sersem mi

adım adım yaşam demiştim

hissetmek anlam demiştim

sevince geceler gündüz demiştim

baharım kış neden 

ihanet yakar 

kışın ortası sarı çöl ateşindeyim

ruhuma geceler yağıyor yağmur gibi

toprağı da özlettin 

zerrelere ayrılmaya hazır bir mevtâ gibi

kapattım gözlerimi', 'ruhuma geceler yağıyor yağmur gibi ellerim buz kesmiş bir aptala dönmüş yalnızlığında gelir miydi ki diyor kapanan kapılar ardında birkaç da...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ruhuma-geceler-yagiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksenleri koparılan', 'eksenleri-koparilan-mete-tugluk-8d1qp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'grafikseldir aşk yükselip alçalan

ve bu kırık çizgilerdir

gözyaşları

kahkahalardır

ölümü somurtan

yitirmek ve kazanmak

yaşamak mıdır

çıkmak gibi inmek

düz çizgi nedir

kim bilebilir

parçalanınca ruh ruhlara

ruhlar tek

tekler kör mü

körlerse kandırılmıştır

ruha yengi düşerse sessizce

kim şaşabilir

yüreklere yenilgi düşmekte

fırlar gece karanlıktan topallayarak

ve gerçekle

ve yalanla

üstalta

yuvarlanarak yukarı aşağı

kalkarak sağa sola

kim anlayabilir

aşk bir yanılgıdır

yaşamsa yaşamak yalnızca

çizgisiz

çizgili-siz...', 'grafikseldir aşk yükselip alçalan ve bu kırık çizgilerdir gözyaşları kahkahalardır ölümü somurtan yitirmek ve kazanmak yaşamak mıdır çıkmak ...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/eksenleri-koparilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhule Bıraktığım', 'mechule-biraktigim-ensar-cevval-6zp1l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Meçhul olsan bile, 

Ellerim boş gelemezdim

gözlerimde ıslaklık

yüreğimde kıpırtılar da olmalıydı

zamansız girdin dümenime

Yangınlardan kaçırdığım

birkaç kelimeden başkası yok elimde

dilim damağımı

özlemin gözlerimi yakıyor

gözyaşlarım ateşlerde.

Bedenimi akıtıyorum 

bir vazoya nakkaş titizliğinde

bir demet saman çöpüyle

bir tutam yazgıyı harmanlayıp

kökünden bedene sevdalar

bekle! 

gonca açacak, filizlenecek çiçekler

uzayınca boyunları, kollarıma yatırıp

senin için, sevdam adına

bir buket halinde sunacağım kollarına.

Yüzüne düşmüş gölgeyi kaldır ne olur

say ki, en güzel çiçek kokuları olsun

Züleyha bakışlı güzellliğinden esinli

Yusuf güzelliği düşsün her bir goncasına

yüreğinin ıslak kenarlarında büyümüş

sevda ormanında rüzgar yememiş

yemyeşil bir yaprak olsun kokulu 

Yanağına düşmüş damlayı sil ne olur

bu suskunluğun adı nedir sevgili! 

hangi goncasını sevmedin gülün

hangi şarkısını beğenmedin bülbülün

tenini gezdirdiğin nehirler kurudu yokluğunda

kokunu gezdirdiğin ovalar bozkır 

Güneş biçare dolanmakta etrafımızda

Ay şekilden şekile girmekte geceleri

akşamlar ağrıtıyor artık

denizin mavisine ak düştü sevgili

bir damla olup düştüm toprağına

buhar olup yükseldim beyazlığına

teninin sıcaklığını hissettir artık ne olur! 

ne olur meçhulum! 

meçhule bıraktığım  ne olur! 

12 Eylül 2003 İstanbul', 'Meçhul olsan bile,  Ellerim boş gelemezdim gözlerimde ıslaklık yüreğimde kıpırtılar da olmalıydı zamansız girdin dümenime Yangınlardan kaçır...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/mechule-biraktigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-ahmet-turan-altunsu-55lkq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Şarkı) 

Sular akar çağıl çağıl 

Kötü dersen ağıl ağıl 

Ana ağlar oğul oğul 

Görem artık yüzün oğul

Öpem artık gözün oğul

Sensiz neyleyim acunda

Öbür dünya cennet oğul

Kuzu meler yaylalarda

Öter keklik nur dağlarda

Şu terkedilmiş bağlarda

Ana oğul diye ağlar

İnleşir ovalar dağlar

Ağır ağır diner sızı

Ah der ah şu karayazı

Bırak artık çoğu azı

Olanını bulamadım

Oğulumun sevgisine

Bir nebzecik doyamadım.

              A.T.A   (11.03.1978)   Erzurum', '(Şarkı)  Sular akar çağıl çağıl  Kötü dersen ağıl ağıl  Ana ağlar oğul oğul  Görem artık yüzün oğul Öpem artık gözün oğul Sensiz neyleyim ac...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/agit-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-zeynep-civan-5y1b4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kızım oldu

Adı yağmur oldu

Yüreği yağmur doldu

Gözleri güneş doğdu

Yağmur yağdı

Gözleri ısıttı

Gözleri ısıttı

Gökkuşağı çıktı

Yağmur, Güneş ve Gökkuşağı

Kızım oldu

Adı yağmur oldu

Müjdeli haberi yağmur yağarken verdi.

Kızım oldu, kızım  y



ağmurum  oldu', 'Kızım oldu Adı yağmur oldu Yüreği yağmur doldu Gözleri güneş doğdu Yağmur yağdı Gözleri ısıttı Gözleri ısıttı Gökkuşağı çıktı Yağmur, Güneş ...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Civan']::text[], 8.5, '{"poet":"Zeynep Civan","poet_slug":"zeynep-civan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yagmur-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Böyle Sev Seveceksen', 'beni-boyle-sev-seveceksen-bekir-gedikoglu-4meyh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben korkuluk isem

Sen çevremde kanat çırpan kuş olacaksın

Ben kütürüm isem

Sen bana çorba içiren hemşirem olacaksın

Ben hasta isem

Sen doktorumu bulacaksın

İşte

Beni böyle sev

Seveceksen

Ben baba isem

Sen çocuklarıma bakacaksın

Ben yıldız isem

Sen ayım olacaksın

Ben kuru bir dere isem 

Sen çağıl çağıl akan suyum olacaksın

İşte 

Beni böyle sev

Seveceksen

Ben ağlıyor isem

Sen göz yaşım olacaksın

Ben kör isem

Sen gözlerim olacaksın

Ben hasta isem

Sen ilacım olacaksın

İşte

Beni böyle sev

Seveceksen

Ben deniz isem

Bu denizde yüzeceksin

Ben uçak isem

Sen pilotum olacaksın

Ben tren isem

Makinisti sen olacaksın

İşte 

Beni böyle sev

Seveceksen

Ben çayır isem

Beni yeşerten suyum olacaksın

Ben meyve ağcı isem

Sen meyvelarım olacaksın

Ben yağmur isem

Sen toprağım olacaksın

İşte 

Beni böyle sev

Seveceksen

Ben bayrak isen

Sen burcum olacaksın

İşte

Beni böyle sev

Seveceksen', 'Ben korkuluk isem Sen çevremde kanat çırpan kuş olacaksın Ben kütürüm isem Sen bana çorba içiren hemşirem olacaksın Ben hasta isem Sen dokto...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/beni-boyle-sev-seveceksen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhacir', 'muhacir-erdal-noyan-brqz9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir anı solgun sayfalarda

Uyandırır eski düşleri

Döner yaralı kısrağa aşk

Kanar kül rengi sönüşleri

Yanardı mehtap eleminden

Evler örtmese ölüşleri

Hasat mevsiminde azizem

Muhacir eyler dönüşleri.', 'Bir anı solgun sayfalarda Uyandırır eski düşleri Döner yaralı kısrağa aşk Kanar kül rengi sönüşleri Yanardı mehtap eleminden Evler örtmese ö...', ARRAY['Türk Edebiyatı','Şiir','Erdal Noyan']::text[], 8.5, '{"poet":"Erdal Noyan","poet_slug":"erdal-noyan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/muhacir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı şarap değildir', 'kirmizi-sarap-degildir-mete-tugluk-pxlgf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kırmızı şarap değildir lekeler gibi

sayrılı aşklara karşıydım

bungun bir mavi çöküp de esrik gecelerden olunca

gizil isteklerin kaçtığı an

bir çocuk

bir baba

haydut ve doktor

unutulan geçmiş

yitirilmiş yaşamlaşırdım hiç yaşanmamışçasına

ve belirsizliklerden kuştüyü bulutlar yapıp yatardım

ıslanıp

ıslanıp

ıslaklığımı yalardım

haykırmazdım

haykırmazdım ama

sustum da sanılmasın...', 'kırmızı şarap değildir lekeler gibi sayrılı aşklara karşıydım bungun bir mavi çöküp de esrik gecelerden olunca gizil isteklerin kaçtığı an b...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirmizi-sarap-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuğular', 'kugular-erdal-noyan-cbdou', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yetim kuğular düşer

Gözlerime her seher

Küsüp giden göllerin

Belirlerim izini

Bilmeyişler kurbanı

Kuşlarıma kıyamam.', 'Yetim kuğular düşer Gözlerime her seher Küsüp giden göllerin Belirlerim izini Bilmeyişler kurbanı Kuşlarıma kıyamam....', ARRAY['Türk Edebiyatı','Şiir','Erdal Noyan']::text[], 8.5, '{"poet":"Erdal Noyan","poet_slug":"erdal-noyan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kugular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meltemim', 'meltemim-cahit-i-pekoglu-iav2y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sizlerden çok özür dileyerek bu sayfaya bir şey yazmak istiyorum....

Çok ama çok yakın bir arkadaımın yaşamış oldu aşkı tabiki anlatacak değilim ama onun hazin hikayesini çok sevdiği kişiyi kaybetmiş olmasının ardından ona yazmış olduğum bir şiirimi inanın o ölen kişinin ruhuna arkadaşımın ağzından yazılıyormuş gibi hediye ediyorum....

MELTEMİM

Yüreğimin parçası canım MELTE''mim

Yüreği sevgi dolu, benim meleğim.

Hiç bir şeyi yoktu, aniden oldu

O bir çiçekti, soldu MELTE''mim.

Kanım donmuştu, o an MELTE''mim ölmüştü

O gönül bahçemde, sanki bir tomurcuktu

Acısı, sanki bedenimi ikiye böldü

Beni per perişan ettide gitti melte''MİM.

Mükemmel bir aşıktı, eşsiz bir sevgili

Aşka yeni alışmıştı, çok sevinçli.

Aşık olmanın haklı sevincini

Yaşayamadan gitti benim MELTE''mim.

Onlarca kişiyle doldu taştı cemaati

onlarca insan yürüdü, bir sen için.

Dileğimdirki, o dünyada çiçekler açsın

Genç yaşta ölenlere, selam söyle MELTE''mim.

Otuz dördünü yeni bitirmişti

Henüz otuzbeşindeydi.

Evlilik için ilk adım atılmıştı

Evlilik cüzdanını alamadan gitti MELTE''mim.

Bu aşk acısına dayanmaz yürek

Ama takdir böyleymiş, katlanmak gerek.

Bana ölümüyle veda ederek

Şaadet şerbetini içti MELTE''mim.....   

(Canım arkadaşımın yerine yazdım beni affetsin)', 'Sizlerden çok özür dileyerek bu sayfaya bir şey yazmak istiyorum.... Çok ama çok yakın bir arkadaımın yaşamış oldu aşkı tabiki anlatacak değ...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/meltemim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksan Neyleyeyim Sırça Sarayı', 'sen-yoksan-neyleyeyim-sirca-sarayi-cahit-i-pekoglu-dc0ay', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neyleyeyim 

sırça sarayım olmuş, neyleyeyim. 

İçinde yarim yokmuş 

kime sesleneyim kime sesleneyim. 

Bir lanbadırki aydınlık vermez 

bir yürektirki bakarken görmez. 

Bir odadırki 

aydınlıkta bile farkedilmez

İçimde bir seski 

nefesi sen olmassan hissedilemez...

Korkarım 

işte böylesine bir aşktan, korkarım 

Canlanan resimlerde 

yaşayamaz ruhum. 

Söylerse, söyleyen 

duyarsa, duyan. 

Anılarda kalmayan 

bir sen var içimde bir sen... 

Sanmaki anlatılan iki anın vardır 

lanbanın öylesine dinlediği. 

Dinlemeyle anlatılamayan 

dokunmayla hissedilemeyen bir sen var içimde. 

Sen korkmassın dokunmaya 

bilirim. 

Ben dokunamam 

dokunursam canlanır, ben ölürüm. 

Sadece kalem olurum 

seni anlatır, satırlarım bir ömür boyu. 

Sözlerini hatırlarım 

bebeğim, bebeğim ol der gibi her gece... 

Söylerse iyisini söyler dedim 

bende ona sadece CAN İÇİM dedim. 

Aşkını aldım kabul ettim 

yüreğime sanki yastık gibi. 

Renkleri aradım gözlerinde 

bir, bir. 

En güzel beni gördüm 

sadece beni gördüm, gördüm tek bir. 

Zannedermisinizki 

bir atlasa sığacak bir aşk yoktur. 

Aşk çoktur ama 

ne böylesine bir aşk, nede senin gibisi yoktur.... 

Aşıklar sana, bana bakmasınlar 

sırça saray değil, bir yürek arasınlar. 

Sen sırça sarayı 

seçtim gülüm. 

Oysaki ben 

senin için bir kulübede bile ölürdüm....', 'Neyleyeyim  sırça sarayım olmuş, neyleyeyim.  İçinde yarim yokmuş  kime sesleneyim kime sesleneyim.  Bir lanbadırki aydınlık vermez  bir yür...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/sen-yoksan-neyleyeyim-sirca-sarayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözüm', 'gozum-ali-soyyigit-k5z4g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kamer senin aynandır.

Güneş ise gül yüzün.

Kömüre karalığı

Sadaka vermiş gözün.', 'Kamer senin aynandır. Güneş ise gül yüzün. Kömüre karalığı Sadaka vermiş gözün....', ARRAY['Türk Edebiyatı','Şiir','Ali Soyyiğit']::text[], 8.5, '{"poet":"Ali Soyyiğit","poet_slug":"ali-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun Hep Aynı Oyun', 'oyun-hep-ayni-oyun-ahmet-aksoy-z7puh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonsuz bir

Kutu kutu pense 

Oyunudur yaşam, 

Oyuncular değişir

Ama oyun 

Hep aynı oyun.', 'Sonsuz bir Kutu kutu pense  Oyunudur yaşam,  Oyuncular değişir Ama oyun  Hep aynı oyun....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/oyun-hep-ayni-oyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşveli Güzel Aşk', 'i-sveli-guzel-ask-ahmet-aksoy-akjw0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceye uzanan ışık

Nasıl kaybolmaya mahkumsa

Bende sende

Öyle yittim aşk

Geri dönüşsüz bir duvardın

Haykırışlarım sende kayboldu

Sürekli emiyor emiyordun da

Hiç doymuyordun

Gecenin güzelliğinde gizlenip

Sabahı unutturuyordun

Çalıyordun işveli bir güzel gibi

Nice gençliği

Ey suçu karanlığında saklı

Büyük oyunbaz 

Nice can gibi

Beni de toprağına kattın 

Ve 

Bana uzattığın havuç

Erişilemez de olsa

Son sözümü işit

Sen 

Yine de 

Bir ölü için

En güzel tabuttun.', 'Geceye uzanan ışık Nasıl kaybolmaya mahkumsa Bende sende Öyle yittim aşk Geri dönüşsüz bir duvardın Haykırışlarım sende kayboldu Sürekli emi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/isveli-guzel-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Canım Sana Kürk Aldım', 'bak-canim-sana-kurk-aldim-ahmet-aksoy-mb7zy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak canım sana kürk aldım

Hep istiyordun ya

Herkes de var deyip

Bak canım ne kadar da güzel

Rengi kırmızı olsa da boş ver.

Bak canım sana kürk aldım

Hep istiyordun ya

Herkes de var deyip

Bak canım ne kadar da güzel

Biraz kokuyor ama boş ver.

Haydi canım giy üstüne 

Son kez üstünde göreyim

Zenginlik değil miydi

Beni terk etme nedenin

Tadını çıkar o zaman

Taşı üstünde ömrün boyunca

Bu kürk benim kürküm

Candan bir hediye anlayacağın

Bak üstüne ne kadar da yakıştı

Bak isteklerin bir bir oluyor

Hep git derdin, üzülmeni 

İstemediğimden ben de gidiyorum 

İstediğin oldu 

Elde bir intihar

Yolun açık olsun.', 'Bak canım sana kürk aldım Hep istiyordun ya Herkes de var deyip Bak canım ne kadar da güzel Rengi kırmızı olsa da boş ver. Bak canım sana kü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bak-canim-sana-kurk-aldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyümüş Bir Kız Çocuğu', 'buyumus-bir-kiz-cocugu-ceyhun-yilmaz-kxvj7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir gün sen de anlayacaksın

kalabalıklardan kaçıp

dizlerini karnına kadar çekip ağlayacaksın

işteo an özleyeceksin

eski sevgilini değil

pili bitmiş oyuncak ayını.

yanından ayırmadığın, yatarken sarıldığın saflığını

tel sarar kızıma tel sarar diyen babana benzemeyecek her erkeğin gözleri.

o küçük kız çocuğu değilsin artık

ama birgün sen de ağlayacaksın! 

kenarları dantelli elbisesiyle 

saçlarıı ördüğün oyuncak bebeğini

nereye koyduğunu htırlaman gerektiğini anlayacaksın! 

tel sarar kızıma tel sarar diyen babana benzemeyecek her erkeğin gözleri.', 'bir gün sen de anlayacaksın kalabalıklardan kaçıp dizlerini karnına kadar çekip ağlayacaksın işteo an özleyeceksin eski sevgilini değil pili...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/buyumus-bir-kiz-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirmizi Biber', 'kirmizi-biber-gul-pembe-4j5eb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen de nankorsun, 

Cok nankor......

Kalbimi gogsumden ciplak ellerinle cikartip 

Gunes alinda kuruttun da...

Sonra oguttun parca parca...

Iste kalbim.........................

...........................................

Bir avuc kirmizi biber...', 'Sen de nankorsun,  Cok nankor...... Kalbimi gogsumden ciplak ellerinle cikartip  Gunes alinda kuruttun da... Sonra oguttun parca parca... Is...', ARRAY['Türk Edebiyatı','Şiir','Gul Pembe']::text[], 8.5, '{"poet":"Gul Pembe","poet_slug":"gul-pembe","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kirmizi-biber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Seni Ver!', 'bana-seni-ver-naime-erlacin-e1sb3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çok şey istemem senden

tek başına çıktığın yolculuklar var hani 

benim katılmadığım

sesini bırak bana 

dalgaları dinlerim 

beklerken o lir sesinde

güzellikler yapmasan da olur

tenini bırak ve kokunu

sarılırım doyasıya ne dersin 

gecenin ıssız bir vaktinde

durmadan “bir yerlere gidelim

bir şeyler yapalım” diyorsun ya

yapmasak da fark etmez

soluğum kesildiğinde bir gün

bana nefesini ver yeter

saklarım onu 

salarım en son nefesimde 

bu eylül gecesinde 

seni istiyorum senden

bana beni

bana seni ver yeter! 

(16 Eylül 2003)', 'çok şey istemem senden tek başına çıktığın yolculuklar var hani  benim katılmadığım sesini bırak bana  dalgaları dinlerim  beklerken o lir s...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bana-seni-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Vardın....', 'sen-vardin-haci-ozturk-u4vmp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O   çakır  gözlerine  şiirler    dokudum, 

Sigaramda duman, duman sen vardın

Sevda  kanunu sayfa, sayfa  okudum, 

Her satırında  cümle, cümle sen vardın.

Sevda  vadisinden  bir ırmak  geçer, 

İçine  ateş  düşen  bu sudan     içer, 

Yüzüne  ay doğar, sinenede sümbüller  açar, 

Bir  anlık  hasretimde bile hep sen vardın.

Saçlarının   renginde  görünür  bahar, 

Süren  filizde, açan  gülde  kokun  var, 

Oylum, oylum  oldu  içimdeki  yaralar, 

Sürem  diyom  merhemimde sen vardın.

Düşünüp  düşünüp  dalma  çok  uzaklara, 

Sen  gel  seni  benim  içimde  ara, 

“Hacım,  bu zamanda düşmüştür dara, 

Çare sende diyemem çarede sen vardın..

Hacı  Öztürk                      18/08/2003

                                            LİBYA

KAYDEDEN                     Hacı  Öztürk', 'O   çakır  gözlerine  şiirler    dokudum,  Sigaramda duman, duman sen vardın Sevda  kanunu sayfa, sayfa  okudum,  Her satırında  cümle, cüml...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-vardin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek ve Tuğra', 'melek-ve-tugra-huseyin-ateskaan-czqfv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yaşanmış hayat bir yazılmış edebiyat

Yine bir Mecnun yine bir Ferhat

İki gönülden yine biri mat

Nasip rüyada mı? 

Hissizandayım mertebeler arası kilit

Olmazmıydı ikisi canlıdan saf bağlayanlar

Kulak verin feryadıma sultanım sen işit

Şefaaten himmet diye bu gönüller ağlıyorlar

Evveliyattan hasret bu gün geçtikçe çığlaşan 

Bir sükut içinde melekler midir ağlaşan

Sessizliğin etrafından isteksizce dolaşan

Çaresiz küskün manen ezik', 'Bir yaşanmış hayat bir yazılmış edebiyat Yine bir Mecnun yine bir Ferhat İki gönülden yine biri mat Nasip rüyada mı?  Hissizandayım mertebel...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ateşkaan']::text[], 8.5, '{"poet":"Hüseyin Ateşkaan","poet_slug":"huseyin-ateskaan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/melek-ve-tugra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilebilsem...', 'bir-bilebilsem-haci-ozturk-ublra', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaç  gündür  dosttan  haber gelmiyor

Başı  dardamıdır  bir  bilebilsem..

Hal  hatır  sorup, selam  vermiyor, 

Günü  zordamıdır  bir  bilebilsem.....

Gidersen  seni  unutamam  derdi, 

Unutanı da asla  affetmem   derdi, 

Uzakta  olsa  aramız  yakınız  derdi, 

Bir  hatamı  ettim  bir  bilebilsem......

Dostların arasında olmaz dargınlık, 

Feryadım sahrada  hep çığlık, çığlık, 

Zorla   elbette  olmaz  güzellik, 

Ne dedimde küstü bir  bilebilsem......

Değer  verirdim hep seven   insana, 

Arar  derdim  başı  düşürse  dara

O aramadı  bari  “hacım   sen  ara, 

Düşüncemde   yanlışmıyım  bir bilebilsem....                                       

Hacı  Öztürk                       18/08/2003

                                              LİBYA

KAYDEDEN                     Hacı  Öztürk', 'Kaç  gündür  dosttan  haber gelmiyor Başı  dardamıdır  bir  bilebilsem.. Hal  hatır  sorup, selam  vermiyor,  Günü  zordamıdır  bir  bilebil...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-bilebilsem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neleri var neleri...', 'neleri-var-neleri-haci-ozturk-1mxlu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülüm  başını  şu sineme  yaslasan, 

Sana   söyleyecek neleri var, neleri.

Naz  edipte şu gönlümü  yormasan, 

Dinlesen  söyleyecek  neleri var, neleri.

Senin  için  derya, deniz  aşarım, 

Nerde olursan ol orayada  koşarım, 

Bu  sevdaya  inanmayana  şaşarım, 

Dilimin  söyleyecek  neleri var, neleri.

Görmezden  gelme  ne olur seni  seveni, 

Ugruna  feda  eder bilki bu  bedeni, 

Ayağıma  dolaştırma çalıyla  dikeni, 

Gözlerimin söyleyecek neleri var neleri...

Çöllerdeyim  serabımsın  durmaz  ararım, 

Turnalar   katarına  seni seni  sorarım, 

Bir  umudum olsa  AKDENİZ’i yararım, 

“Hacının, da söyleyecek neleri var, neleri

Hacı  Öztürk              30/08/2003

                                   LİBYA 

KAYDEDEN              Hacı  Öztürk', 'Gülüm  başını  şu sineme  yaslasan,  Sana   söyleyecek neleri var, neleri. Naz  edipte şu gönlümü  yormasan,  Dinlesen  söyleyecek  neleri v...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/neleri-var-neleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuğrasızlar', 'tugrasizlar-huseyin-ateskaan-b84m1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biri duygusal diğeri asabi

Saçları taranmış gözleride sürmeli

Güneşle gözler açık geceleri kapalı

Zaman acılala uzun gülümsedikçe uzamalı

Meyler kırda meyhanede içilmeli

Deniz kenarında bir başka yüzmeli

Bu da olmazsa yarın başkasını sevmeli

Akçeler oldukça mutlu umutlarınca sosyal

Ne zaman tarih olacak savaşsız general', 'Biri duygusal diğeri asabi Saçları taranmış gözleride sürmeli Güneşle gözler açık geceleri kapalı Zaman acılala uzun gülümsedikçe uzamalı Me...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ateşkaan']::text[], 8.5, '{"poet":"Hüseyin Ateşkaan","poet_slug":"huseyin-ateskaan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tugrasizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahtasız', 'tahtasiz-huseyin-ateskaan-oezd7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim kalbimle ben severim 

Kendimle ben sevinirim

Bende olan kalır silemem

Sende ben var mı bilemem

Bende yoruldum sende varsa benden nhemen geleyim

Kelebekler kefenlenemez

Ekin tarlalarına uçarlar kelebekler

Okyanustaki teknede cesetler tuzlanır

Sessiz stadyuma tuzlanmadan giremezler

Buğdaydaki kelebek tek kişilik kayıkta nasıl barınır?', 'Benim kalbimle ben severim  Kendimle ben sevinirim Bende olan kalır silemem Sende ben var mı bilemem Bende yoruldum sende varsa benden nheme...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ateşkaan']::text[], 8.5, '{"poet":"Hüseyin Ateşkaan","poet_slug":"huseyin-ateskaan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tahtasiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçemediğim İstanbulsun.', 'vazgecemedigim-i-stanbulsun-turgay-kadiroglu-uxzjl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'boğazımda düğümlenir ruhuma sarılan aşkın, 

tüm benliğimi ta canından yakalar, 

yanaklarım kızıla çalar, ateşin ellerimi yakar, 

boğazındadır ey yar! 

hücrelerime can katan damlalar.

aşıkların yanaştığı liman

ve aşkın yaşadığı diyarsın

altında yıldızlar yatan

üstünde kandiller yanan

bengisuyunda kaybolduğum pınarsın.

dört bir yanımı kuşatan beldesin

sultanahmette güvercinlerinle

çamlıcada sarı yapraklı çiçekle

bağrında salınan kız kulesiyle

ey İstanbul! sen bendesin.

yedi kapıdan girilir

ve yedi tepeden göklere çıkılır

balıkçı kayıkları haliçe açılır

kıyıların martı kanadına boyanır

minareler düete başlar

vapurun düdüğü susar

ey yar! gönlüm bir yudum aşkına susar.

güneşin fitili adalarda yanar

boynu bükük eğrilir süleymaniyede söner, 

ılık bir meltem hisara gecenin şarkısını söyler

her bir köşeden binbir ışık yükselir, 

evrenin karanlığı bu şehre yıldızlar serpiştirir, 

iki yaka arası ışık takı, 

dönerken beyaz, giderken kırmızı, 

ey istanbul! gündüzün başka güzel, 

gecelerin gönlümün tacı.

kat kat göklerde, 

kanatsız meleklerin gözleri sende

tek kubbe iki kanat, kelebek silüeti çehrende, 

kıyılarında aşkın sınırlarını çizen sursun, 

karanlık gecelerde Hilal''in yakamozlarına aktığı ahsennursun, 

sana yan bakan göz, sende kabristan bulsun, 

sen ey yar! vazgeçemediğim istanbulsun.', 'boğazımda düğümlenir ruhuma sarılan aşkın,  tüm benliğimi ta canından yakalar,  yanaklarım kızıla çalar, ateşin ellerimi yakar,  boğazındadı...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/vazgecemedigim-istanbulsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yaşamım vardı benim', 'bir-yasamim-vardi-benim-i-brahim-tolga-ozsoy-8w835', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir salgın anında uçup gitmiş yaşamlar.

Anıların ardısıra dizilmiş, 

Gecikmişliklerine sırtlarını dönmüş insanlar.

Anımsar mısınız bir zamanlar, 

Bir yaşamım vardı benim.

Kirpiklerim ıslandığında hatırlananlar, 

Ve bol keseden saçtığımız kahkahalar, 

Tükendiler ansızın.

Hapsolmuş, sarsıntılarla dolu rüyalarıma, 

ve sulanmış defter yaprakları

nice gözyaşlarıyla.

Kuru, katıksız, tatsız aşklar, 

İnişleri çıkışları endeksli yalnızlığa.

Yalnız geçen kaç gece, 

Kaç ay, kaç sene, 

Kaç ömür daha harcayabilirim.

Bir yaşamım vardı benim...

Saf aşklarla bezenmiş bir kız çocuğuydum, 

Yaşamım böyle anılacak sanmıştım.

Birayla ve müzikle sakinleştirdiğim ızdıraplarda, 

Planlanmamış, rastgele ihtiyaçlarda, 

Saklandım sinsice bunca yıkıntıyı aslında.

İndirdim katkısız bakışlarımı yenilmeden, 

Yok hayır yenilmedim diyorum asla, 

Sadece vazgeçtim beklentilerimden.

Ter kokulu aşk gecelerinde belki hatırlayanlar, 

Ve bolca ağlayanlar, 

Bir zamanlar, 

Çocuktum ben, amaçsız günü kokan baharımda.

* O''nun anısına.

1997 İstanbul', 'Bir salgın anında uçup gitmiş yaşamlar. Anıların ardısıra dizilmiş,  Gecikmişliklerine sırtlarını dönmüş insanlar. Anımsar mısınız bir zaman...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tolga Özsoy']::text[], 8.5, '{"poet":"İbrahim Tolga Özsoy","poet_slug":"i-brahim-tolga-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-yasamim-vardi-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni biriktirdim icimde', 'seni-biriktirdim-icimde-i-lker-sahin-0crgf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sustuklarımı biriktirdim icimde, suskunluklarımı

sevgi dolu günleri, aksamları

o en masum o en sevecen yıllarımı, umutları

seninle yasanacak yarınları, hatıraları biriktirdim

Sustuklarımı biriktirdim icimde, suskunluklarımı

gidisinin verdigi göz yaslarını 

günbegün kanayan yaralarımı

yoklugunun verdigi acıları biriktirdim

Sustuklarımı biriktirdim icimde, suskunluklarımı

bir kıta oldu yuregim gezdigimiz yerleri biriktirdim

ay her gece bende dogdu sectigimiz yıldızları biriktirdim

yasamı, mutlulugu, hüznü, askı, sevgiyi ve sevgimi biriktirdim

seni biriktirdim icimde yalnız seni...', 'Sustuklarımı biriktirdim icimde, suskunluklarımı sevgi dolu günleri, aksamları o en masum o en sevecen yıllarımı, umutları seninle yasanacak...', ARRAY['Türk Edebiyatı','Şiir','İlker Şahin']::text[], 8.5, '{"poet":"İlker Şahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-biriktirdim-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçeksiz...', 'gerceksiz-nihan-demirel-s5yj4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hayat, anlamsızlaşıyor; 

bazen...

bir sonraki gerçekliğe

geçerken...

gerçeklikleri, seçemiyorsun; 

geçerken uğruyorsun 

illaki..

hayat sana

tek çeşit; 

ama saf, ama koskocaman, 

ama doyurucu, ama özel, 

ama tek...

gerçeklik yaratmıyor...

seçemiyorsun, tercih edemiyorsun; 

geçerken uğruyorsun illaki...

ve illaki canın acıyor...

sahip sıfatın yok; 

olamayacak...

hiçbir gerçek, senin değil...

kimisine; geçerken uğruyorsun, 

kimisi ise; parmaklarının ucundan

kanatarak canını, 

çekilip, gidiyor...

canın acıyor; 

bağıramıyorsun...

her öykü gibi; 

hayal...

her rüya gibi; 

gerçeksiz...

hayatın dışında bir yerlerde, 

sevinçler; sonsuz tanımlı...

sen, 

hayatı kucaklarken; 

güçlü, 

canın acıyor...

kanıyorsun, bir yerlerde...

ve sahibi değilsin; 

hiçbir gerçeğin...

15/09/03', 'hayat, anlamsızlaşıyor;  bazen... bir sonraki gerçekliğe geçerken... gerçeklikleri, seçemiyorsun;  geçerken uğruyorsun  illaki.. hayat sana ...', ARRAY['Türk Edebiyatı','Şiir','Nihan Demirel']::text[], 8.5, '{"poet":"Nihan Demirel","poet_slug":"nihan-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gerceksiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birlikteliğimiz', 'birlikteligimiz-ahmet-aksoy-3xo0f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yapılışı eksik kalmış

Bir sepet gibiydi

Birleşmemiz

“Dipsiz”

Ve yol, 

Taşınılası onca  yük

İstemek yetmezdi şüphesiz

Çünkü taşımalıdır

Her yükü birliktelik

Suç senin değil elbet

Sadece ikimizin

Delik bir sepetle 

Yola çıktığımız için.', 'Yapılışı eksik kalmış Bir sepet gibiydi Birleşmemiz “Dipsiz” Ve yol,  Taşınılası onca  yük İstemek yetmezdi şüphesiz Çünkü taşımalıdır Her y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birlikteligimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunca Neşe Ne Diye', 'bunca-nese-ne-diye-ahmet-aksoy-bi673', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Açık geniş bir sofra

Üzerinde beyaz bir örtü

Temiz pak yeni ütülenmiş

Etrafında sekiz sandalye

Ve yedi düşüncesiz kişi

Konuşuyorlar hararetli

Ara sıra kısık kahkahalarla

Donanmış masa ama kuş sütü yok

Zengin bir adamın zengin evinin

Zengin sofrasında

Ev; geniş yemek odalı

Geniş misafir salonlu

Ve bir çok yatak odalı

Duvarları temiz yeni boyanmış

Ama bir yatak boş

Çarşafları dağınık

Diğer yataklar gibi değil toplanmamış

Belli ki sahibi yeni çıkmış

Fakat kimse bilmiyor nereye gittiğini

Giderken açık bir adres bırakmamış

Açık geniş bir sofra

Üzerinde beyaz bir örtü

Temiz pak yeni ütülenmiş

Etrafında sekiz sandalye

Ve yedi riyakar kişi

Konuşuyorlar hararetli

Ara sıra kısık kahkahalarla

Belli ki bilmiyorlar

Ev sahibinin nereye gittiğini

Yoksa bunca neşe ne diye.', 'Açık geniş bir sofra Üzerinde beyaz bir örtü Temiz pak yeni ütülenmiş Etrafında sekiz sandalye Ve yedi düşüncesiz kişi Konuşuyorlar hararetl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bunca-nese-ne-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk Edemedikten Sonra', 'terk-edemedikten-sonra-ahmet-aksoy-pr71i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir miçoydum

Seni görene kadar

Görünce aşık olduğum

Ve sana erişmek

Kaptanlığa geçmek azmim

Sırf sana şirin görünmek

Fark edilmemenin öfkesi

Birleşti çalışma azmimle

Neyse ki uzandım sana

Fakat sürmedi mutluluk

Her giden gibi

Sende gittin sonunda

Şimdiyse, kasırga pişmanlık

Savuruyor direkleri

Ve kaptan olmak

Neye yarar

Gemiyi terk 

Edemedikten sonra.', 'Ben bir miçoydum Seni görene kadar Görünce aşık olduğum Ve sana erişmek Kaptanlığa geçmek azmim Sırf sana şirin görünmek Fark edilmemenin öf...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/terk-edemedikten-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'X Eşittir Ölüm', 'x-esittir-olum-ahmet-aksoy-yrz42', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir balıkçı kasabasında

Denize açılırdı insanlar

Kimi zaman şahit olurdu

Binlerce dönmeyene

Kasabanın taşlık kıyıları

Ve denizin üstündeki sema

Yorulmuştu dinlemekten

Yakılmış ortak ağıtları

Ve her insan gibi

Balıkçılar içinde

Tek bilinmeyenli

Denklemdi hayat

X eşittir ölüm

Bilineniyse malum

Ekmek, ekmek, ekmek.', 'Bir balıkçı kasabasında Denize açılırdı insanlar Kimi zaman şahit olurdu Binlerce dönmeyene Kasabanın taşlık kıyıları Ve denizin üstündeki s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/x-esittir-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir taş olsam...', 'bir-tas-olsam-i-lyas-sahin-6cvm1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir taş olsam içinden sular fışkıran

Çatlatılsam, yarılsam bir filiz tarafından 

Bir sapanın mermisi olsam ve kuşu ıskalasam

Taşa mermi sıkanı on ikiden vursam

O na ait saygımla yuvarlansam yardan 

Yüreklerde ki yerimi merhamete bıraksam

Bir ucu bana diğeri boyna bağlı urgandan kurtulsam

Yeni bir nefesin mutluluğunu tattırsam boynun sahibine

Doğum...ölüm...kazısalar üzerime; 

ağlatsam, hatırlatsam sevenlerine

Hedefe süzülsem ebabilin ayağından

Göğe yükselse birisi, basarak omzuma aksa’dan

Bir yüzüğün üzerinde, parmağa takılan sevgi olsam

Çıkmasam dirensem yüzükten, yüzükse parmaktan

Bir deli tarafından atılsam kuyuya

Bir veli çıkarsa, çıkarılmazsam kırk akıllı tarafından

Gökten ağırlığınca düşsem, mazlumun duasınca 

meteorca yağsam ezenlerin kafasına, taşca

Çağlardan gelsem, büyükleniş çağlarından 

Bir harabe olsam, haberdar etsem yıkılıştan

Siyah taş koysalar adımı, İbrahim’in diyarından

Hiç yalnız kalmasam beyaz elbiseli adamlardan

Taş da olsam durmayacağım inan

Durmuyor taştan dağlar, dönüyorlar durmadan.

09/2003', 'Bir taş olsam içinden sular fışkıran Çatlatılsam, yarılsam bir filiz tarafından  Bir sapanın mermisi olsam ve kuşu ıskalasam Taşa mermi sıka...', ARRAY['Türk Edebiyatı','Şiir','İlyas Şahin']::text[], 8.5, '{"poet":"İlyas Şahin","poet_slug":"i-lyas-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-tas-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fadime ile Mahmut', 'fadime-ile-mahmut-ali-osman-yilmaz-inlld', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'FADİME İLE MAHMUT

Sabah güneşi doğmuş, ortalık aydınlık

Çadırında bir genç kız, gözleri yarı açık

Gece gördüğü rüyasını düşünüyor

Etekleri yarı beline kadar açık

Kapatıyor gözlerini yeniden.geceki rüyayı görmek için

Tatlı bir serinlik esiyor çadırında, 

Çıplak bacaklarını yalayarak.

Kalay ocağının körüğüne basıyor, kalçalarını kıvırarak, 

Öteki çadırın delikanlısı Mahmut geçiyor ilerden

Memeleri sallanıyor fadimenin, kalbi küt küt atarak

Ela gözleriyle öteki çadırın delikanlısı mahmuda doğru 

Vücudunda davetkar çağırışlar, mahzun mahzun bakarak

Alacağım kız seni diyen bakışlarıyla geçiyor Mahmut

Sallanan fadimenin kalçalarına iç çekişle bakarak

Yüzünde tatlı bir tebessüm, işmar ediyor başını sallayarak

Gülüyor, uzaktaki ağaçların altına doğru yavaşça uzaklaşarak.

Anasına dal toplayacağını söylüyor fadime ateş için

Ocağı yakıp kap kacakları kalaylayacak.

Koşarcasına seyirtiyor ağaçlığa doğru 

Arıyor gönlünün erini ağaçların altında heyecanla

Mahmut sesleniyor ardından, fadime kız baksana

Sarılıyor Mahmud’una Fadime kıkırdayarak

Elleri eteklerine ulaşınca fadimeden bir naz

Daha beni istetmedin babamdan şimdi olmaz

Bir atlı geçiyor ağaçlığın yanından türkü çağırarak

Hınzır fadime fırsat bu deyip çöküyor erine asılarak

Mahmut sevinçle sarılıyor fadimeye, fısıldayarak

Otur kız kucağıma görmesinler  seni beline sarılarak

Halinden memnun sevgilisinin kucağına oturarak

Sarılıyorlar bir ten.bir beden hızlıca soluyarak

Sıcaklıklarını tenden deme geçirmek için

Elleri mahmudun gizli hazineleri bulmak için

Dolaşıyor fadimenin bedeninde arzulayarak

Tam kendini bırakmışken arzuyla mahmuda

Ne zaman söyleyecen beni ananla babana

Ter içinde soğuk soğuk titrerken Fadime

Gözleri açılır şaşkın ve mutlu sorar kendine

Ne zaman istemeye gelir acep gacı halime

Eteklerini indirirken bakar bacaklarına sanki bir sütun

Elleri gezinir bedeninde düşünür hepside mahmudun

Ayaklanır kalay ocağının ateşini yakmak için

Gözleri dolaşır rüyadaki mahmudunu arayarak

Körüğe bir umutla saldırır, kalçalarını kıvırarak

Bu çingen kızı sonunda mahmuduna varacak.', 'FADİME İLE MAHMUT Sabah güneşi doğmuş, ortalık aydınlık Çadırında bir genç kız, gözleri yarı açık Gece gördüğü rüyasını düşünüyor Etekleri y...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/fadime-ile-mahmut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Post bulmalı', 'post-bulmali-aysenur-yazici-khcp1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öfkemi bir ipeğe sarmalıyım....

talihe çatmamam

dostuma küsmemem için 

sevgime post bulmalıyım

ellerine aşık olduğumu

söylemek için sevdiğime

şubatın 14''ünü de beklememem gerek! 

bu sabah, 

çay demlikte

 '' bugün pazar '' diye bağırırken 

itiraf etmeliyim

               27.06.02

                 (18:45) 

              Çengelköy', 'Öfkemi bir ipeğe sarmalıyım.... talihe çatmamam dostuma küsmemem için  sevgime post bulmalıyım ellerine aşık olduğumu söylemek için sevdiğim...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/post-bulmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kastın', 'kastin-aysenur-yazici-5kv3n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aslında hayataydı kastın...

durdun durdun

