INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultan-ı Taht Eyledim', 'sultan-i-taht-eyledim-muammer-celik-ncys3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kurulur elbet bu gönüllerde tahtlar 

................sultanı ben 

…………………….….mihrabi ben 

...............................………..........taci ben 

Dikilir elbet bu gönüllerde güller 

...........dikeni ben

…………………...bahcivani ben 

..........................………….........seveni ben! 

20.06.2003

BirDeli', 'Kurulur elbet bu gönüllerde tahtlar  ................sultanı ben  …………………….….mihrabi ben  ...............................………..........taci b...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sultan-i-taht-eyledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İKİ''de BİR...!', 'i-ki-de-bi-r-muammer-celik-dtr6r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki gönülde bir gül açtık 

İki Yürekte bir attık 

İki yatakta bir yattık 

İki Cihanda bir sevdik 

İki ruhta bir seviştik 

İki bedende bütünleştik...! 

Sen artı ben = iki’de bir sevda ki 

söyle; bu aşkı başka ne geçer ki...? 

19.06.2003 

BirDeli

(sevgi nelere kadir Ya Râb!)', 'İki gönülde bir gül açtık  İki Yürekte bir attık  İki yatakta bir yattık  İki Cihanda bir sevdik  İki ruhta bir seviştik  İki bedende bütünl...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iki-de-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Sus''um', 've-sus-um-derin-oger-2og55', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gündüzü beklesem gece

Geceyi beklesem sabah oluyor

Çağırsamda geçen günleri geri gelmiyor

Kalbimdeki gömünün adı mazi oluyor

Bir bulutla yağıp bir yıldızdan bakıyorum

Güneşe dokunsam yanığı yara oluyor

Dallarını taşıyamayan ağaçlar misali

Gölgesi gürültüyle çöküşün acısı büyük oluyor

Zamanın çağrıya yargısı kesin 

Herşeye varken herşey bir hiç oluyor

Kabuğuna adımı kazıdım ey yalan dünya

Biliyorum dönüşünün yolları sonum oluyor

Ve sus''um...........', 'Gündüzü beklesem gece Geceyi beklesem sabah oluyor Çağırsamda geçen günleri geri gelmiyor Kalbimdeki gömünün adı mazi oluyor Bir bulutla yağ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ve-sus-um-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Çocukluğum', 'elveda-cocuklugum-oguzkan-bolukbasi-mu44o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hatıram kalsın

Çocuk akşamlarımın hepsi senin olsun

Yeşile çalan baharlarım

Sarı renkli yazlarım

Çekip gideceğim ben çocukluğumdan

Bilyelerim

Kos helvalarım

Pamuk şekerlerim

Hayallerim 

Beni beklemeyin

Şimdi ben uzak baharlardayım

Dönülmez zamanlardayım', 'Hatıram kalsın Çocuk akşamlarımın hepsi senin olsun Yeşile çalan baharlarım Sarı renkli yazlarım Çekip gideceğim ben çocukluğumdan Bilyeleri...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/elveda-cocuklugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açılın Zindanlar Pire Gidelim', 'acilin-zindanlar-pire-gidelim-pir-sultan-abdal-7rudy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hızır Paşa bizi berdar eyledi

Kesti kollarımı kızak bağladı

İşiten muhipler hep kan ağladı

Açılın zindanlar pire gidelim

Kalenin kapısı taştan demirden

Yanlarım çürüdü yaştan yağmurdan

Bir kimsem de yok ki dellal çağırtam

Açılın zindanlar pire gidelim

Kalenin kapısı taştan çıkılmaz

Penceresi yüce Şah''a bakılmaz

Bir ben ölmeyinen cihan yıkılmaz

Açılın zindanlar pire gidelim

Çıkarım bakarım kale başına

Mümin müslim olan gider işine

Bir ben mi düşmüşüm can telaşına

Açılın zindanlar pire gidelim

İlimi sorarsan köyümdür Banaz

Yakılsın yıkılsın ol kanlı Sivas

Bir ben ölmeyinen cihan yıkılmaz

Açılın zindanlar pire gidelim

Pir Sultan Abdal''ım hey Hızır Paşa

Yazılanlar gelir sağ olan başa

Hasret koydun beni kavim kardaşa

Açılın zindanlar pire gidelim', 'Hızır Paşa bizi berdar eyledi Kesti kollarımı kızak bağladı İşiten muhipler hep kan ağladı Açılın zindanlar pire gidelim Kalenin kapısı taşt...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/acilin-zindanlar-pire-gidelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağ Gül İle Kırmızı Gül', 'ag-gul-i-le-kirmizi-gul-pir-sultan-abdal-4xt4u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cem-i çiçeklerin hası

Ağ gül ile kırmızı gül

Deli gönül eğlencesi

Ağ gül ile kırmızı gül

Demi demi şirin demi

Gelir geçer dünya gamı

Talip olmak pirindendir

İrenk almak gülündendir

Muhammed'' in terindendir

Ağ gül ile kırmızı gül

Demi demi şirin demi

Gelir geçer dünya gamı

Pir Sultan''ım ey gaziler

Alnımızda al yazılar

Talip de Pir''in arzular

Ağ gül ile kırmızı gül

Demi demi şirin demi

Gelir geçer dünya gamı', 'Cem-i çiçeklerin hası Ağ gül ile kırmızı gül Deli gönül eğlencesi Ağ gül ile kırmızı gül Demi demi şirin demi Gelir geçer dünya gamı Talip o...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ag-gul-ile-kirmizi-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayı Ağlayı Durma Karşımda', 'aglayi-aglayi-durma-karsimda-pir-sultan-abdal-ufkwl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlayı ağlayı durma karşımda

Dost beni gönder de var andan ağla

Kirpikleri top top etmiş kaşında

Dost bizi gönder de var andan ağla

Dostun zülüfleri bölük bölüktür

Menim ciğerciğim delik deliktir

Muhabbetin sonu tez ayrılıktır

Dost beni gönder de var andan ağla

Başına bağlamış aldır valası

Aldı beni kaşlarının karası

Hasan ile Hüseyin''in anası

Dost beni gönder de var andan ağla

Başına bağlamış al ile sarı

Arkamızca etme ah ile zarı

Koca Pir Sultan''ın gül yüzlü yarı

Dost bizi gönder de var andan ağla', 'Ağlayı ağlayı durma karşımda Dost beni gönder de var andan ağla Kirpikleri top top etmiş kaşında Dost bizi gönder de var andan ağla Dostun z...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aglayi-aglayi-durma-karsimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Hüseyin Vah Hüseyin', 'ah-huseyin-vah-huseyin-pir-sultan-abdal-daq4p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alemlerin serverisin

Ah Hüseyin, vah Hüseyin

Şehitlerin serdarısın

Ah Hüseyin, vah Hüseyin

Hasan, Hüseyin''in yari

Muhammed''in gözü nuru

Hem Ali''nin yadigarı

Ah Hüseyin, vah Hüseyin

Zuhur oldun İmam Zeynel

Muhammet Bakır''dan evvel

Didene yanayım gönül

Ah Hüseyin, vah Hüseyin

İmam Cafer''dir yarimiz

Musa-i Kazım şahımız

Budur şems ile mahımız

Ah Hüseyin, vah Hüseyin

Ali Musa ilim hüner

Muhammet Taki el sunar

Hüseyin''im deyip yanar

Ah Hüseyin, vah Hüseyin

Ali Taki, Hasan Asker

Muhammet Mehdi ser-defter

İmam-ı Seyyid-i ekber

Ah Hüseyin, vah Hüseyin

Pir Sultan haber ver dosttan

Bülbül ötüyor kafesten

Hem gül ağlar, hem gülistan

Ah Hüseyin, vah Hüseyin', 'Alemlerin serverisin Ah Hüseyin, vah Hüseyin Şehitlerin serdarısın Ah Hüseyin, vah Hüseyin Hasan, Hüseyin''in yari Muhammed''in gözü nuru Hem ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ah-huseyin-vah-huseyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al-i Yar Semahı', 'al-i-yar-semahi-pir-sultan-abdal-6f89b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yas-ı matem günü derdim yeniler

Yarin sesi kulağımda çınılar

Sordum ki dağlara niçin iniler

Dedi çekticeğim karın elinden

Varıp bir pir ile pazar edersin

Oturup da ikrarını güdersin

Sordum garip bülbül niçin ötersin

Dedi çekticeğim harın elinden

Ser çeşmeden gelir suyun durusu

Nasibimiz verir pirin birisi

Dedim Pir Sultan’ ım benzim sarısı

Dedi çekticeğim yarin elinden', 'Yas-ı matem günü derdim yeniler Yarin sesi kulağımda çınılar Sordum ki dağlara niçin iniler Dedi çekticeğim karın elinden Varıp bir pir ile ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/al-i-yar-semahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali''nin Düldül''ün Bin De Göreyim', 'ali-nin-duldul-un-bin-de-goreyim-pir-sultan-abdal-90gap', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ali''m gelir diye karşı giderler

Ali''nin Düldül''ün bin de göreyim

Bindiği Düldül''ün mehdin ederler

Ali''nin Düldül''ün bin de göreyim

Ayağına altın nallar çaktırmış

Gözlerine yeşil sürme çektirmiş

Üzengisin cevahirden yaptırmış

Ali''nin Düldül''ün bin de göreyim

Kuduretten gem vurulmuş başına

Lezzet vermiş dudağına dişine

Bir nur doğmuş eğerinin kaşına

Ali''nin Düldül''ün bin de göreyim

Üstüne binersen yükseğe basar

Bir dizgin eylesen yel gibi eser

Nice kafirlerin kellesin keser

Ali''nin Düldül''ün bin de göreyim

Pir Sultan Abdal''ım dengi bulunmaz

Bin konaklık yere gitse yorulmaz

Kısmet olsa havalarda görünmez

Ali''nin Düldül''ün bin de göreyim', 'Ali''m gelir diye karşı giderler Ali''nin Düldül''ün bin de göreyim Bindiği Düldül''ün mehdin ederler Ali''nin Düldül''ün bin de göreyim Ayağına a...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ali-nin-duldul-un-bin-de-goreyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali''nin Sırrına Erebilirsen', 'ali-nin-sirrina-erebilirsen-pir-sultan-abdal-x6129', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Muhammet Ali''nin kurduğu yoldur

Ak üstünde kara seçebilirsen

Gönülden itikat söyleyen dildir

Ali''nin sırrına erebilirsen

Erenler der seni ceme katarlar

Kötü amellerin taşra atarlar

Bir gün yularından tutup çekerler

Çektikleri yere varabilirsen

Erenler seni de ceme götürür

Kalmış işlerini anda bitirir

Gördüm Hak evinde mihman oturur

Mihmanın gözüyle görebilirsen

Aslı mervan olan ummana dalmaz

Küfre meyledende aşıklık olmaz

Müminin suali ahrete kalmaz

Dünyada cevabın verebilirsen

Pir Sultan Abdal''ım gonca gül olur

Dört kapıdan sana daim gel olur

Dünyadan ahrete doğru yol olur

Verdiğin ikrarda durabilirsen', 'Muhammet Ali''nin kurduğu yoldur Ak üstünde kara seçebilirsen Gönülden itikat söyleyen dildir Ali''nin sırrına erebilirsen Erenler der seni ce...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ali-nin-sirrina-erebilirsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Allah Desem Gelsem', 'allah-allah-desem-gelsem-pir-sultan-abdal-ozxg9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Allah Allah Desem Gelsem

Hakkın Divanına Dursam

Ben Bir Yanıl Alma Olsam

Dalında Bitsem Ne Dersin

Sen Bir Yanıl Alma Olsan

Dalımda Bitmeye Gelsen

Ben Bir Gümüş Çövmen Olsam

Çeksem İndirsem Ne Dersin

Sen Bir Gümüş Çövmen Olsan

Çekip İndirmeye Gelsen

Ben Bir Avuç Çavdar Olsam

Yere Saçılsam Ne Dersin

Sen Bir Avuç Çavdar Olsan

Yere Saçılmaya Gelsen

Ben Bir Güzel Keklik Olsam

Bir De Toplasam Ne Dersin

Sen Bir Güzel Keklik Olsan

Bir Bir Toplamaya Gelsen

Ben Bir Yavru Şahin Olsam

Kapsam Kaldırsam Ne Dersin

Sen Bir Yavru Şahin Olsan

Kapıp Kaldırmaya Gelsen

Ben Bir Sulu Sepken Olsam

Kanadın Kırsam Ne Dersin

Sen Bir Sulu Sepken Olsan

Kanadım Kırmaya Gelsen

Ben Bir Deli Poyraz Olsam

Tepsem Dağıtsam Ne Dersin

Sen Bir Deli Poyraz Olsan

Tepip Dağıtmaya Gelsen

Ben Bir Ulu Hasta Olsam

Yoluna Yatsam Ne Dersin

Sen Bir Ulu Hasta Olsan

Yoluma Yatmaya Gelsen

Ben Bir Can Alıcı Olsam

Canını Alsam Ne Dersin

Sen Bir Can Alıcı Olsan

Canımı Almaya Gelsen

Ben Bir Cennetlik Kul Olsam

Cennete Girsem Ne Dersin

Sen Bir Cennetlik Kul Olsan

Cennete Girmeye Gelsen

Pir Sultan Üstadın Bulsan

Bilecek Girsek Ne Dersin', 'Allah Allah Desem Gelsem Hakkın Divanına Dursam Ben Bir Yanıl Alma Olsam Dalında Bitsem Ne Dersin Sen Bir Yanıl Alma Olsan Dalımda Bitmeye G...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/allah-allah-desem-gelsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslı Nedir', 'asli-nedir-pir-sultan-abdal-z81sv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel Şah''ım çok yerlerden görünür

Aslı nedir neye verdin Bağdad''ı

Şahım birdir binbir dona bürünür

Aslı nedir neye verdin Bağdad''ı

Eremedim ben bu sırrın aslına

Yazık değil mi müminle müslime

Getirin Mervan''ı Bağdad üstüne

Aslı nedir neye verdin Bağdad''ı

Yok mu bunda erenlerin yardımı

Ne çekersin bu cefanın derdini

Yiğitlere ardır vermek yurdunu

Ah Hünkar''ım neye verdin Bağdad''ı

Geldi Mervan hendekleri doldurdu

Kırdı Hurmalığı aldı Bağdad''ı

Çığrışıp geliyor yeşil ördeği

Aslı nedir neye verdin Bağdad''ı

Pir Sultan''ım der ki üçler yediler

Kırklar da bu demde hazır idiler

Bağdad''ı Basra''yı verdi dediler

Aslı nedir neye verdin Bağdad''ı', 'Güzel Şah''ım çok yerlerden görünür Aslı nedir neye verdin Bağdad''ı Şahım birdir binbir dona bürünür Aslı nedir neye verdin Bağdad''ı Eremedim...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asli-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Derdinin Dermanı Nedir', 'ayrilik-derdinin-dermani-nedir-pir-sultan-abdal-4prff', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uğrum sıra giden Boz Atlı Hızır

Ayrılık derdinin dermanı nedir

Şu iki aleme olmuşsun nazır

Ayrılık derdinin dermanı nedir

Sığanmıştır ağca kolda bilekler

Hak katında kabul olsun dilekler

Arş yüzünde secde kılan melekler

Ayrılık derdinin dermanı nedir

Küseyim de ben yarime küseyim

Siyah zülfün mah yüzüne asayım

Kerbela''da yatan İmam Hüseyin

Ayrılık derdinin dermanı nedir

Hani şu dünyanın toprağı taşı

Akıttım gözümden kan ile yaşı

Urum illerimin Hacı Bektaş''ı

Ayrılık derdinin dermanı nedir

Ak saya giyinmiş incedir beli

Ben pirimi gördüm tatlıdır dili

Allah''ın arslanı Hazret-i Ali

Ayrılık derdinin dermanı nedir

Gıcılar da dağlar başı gıcılar

Çıkmaz oldu içerimden acılar

Arafat Dağı''ndan gelen hacılar

Ayrılık derdinin dermanı nedir

Dünyayı sorarsan bir dipsiz anbar

Ali''nin yoldaşı Zülfikar Kanber

Kabe''yi yaptıran Halil Peygamber

Ayrılık derdinin dermanı nedir

Deryanın yüzünde dönen üç gemi

Yiyelim içelim sürelim demi

Geminin sahibi ol Hızır Nebi

Ayrılık derdinin dermanı nedir

Pir Sultan Abdal''ım içtim cür''adan

Okudum ağını bilmem karadan

Yeri göğü cüml''alemi Yaradan

Ayrılık derdinin dermanı nedir', 'Uğrum sıra giden Boz Atlı Hızır Ayrılık derdinin dermanı nedir Şu iki aleme olmuşsun nazır Ayrılık derdinin dermanı nedir Sığanmıştır ağca k...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ayrilik-derdinin-dermani-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılmam Katardan Ben Şimden Geri', 'ayrilmam-katardan-ben-simden-geri-pir-sultan-abdal-u0djm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şah''a giden ben bir bezirgan gördüm

Ayrılmam katardan ben şimden geri

Hemen tutmuş hakikatın yolunu

Ayrılmam katardan ben şimden geri

Bezirgan yükünü nereden tutmuş

Ona hizmet eden dergaha yetmiş

Sevdiğim sılada bir oda tutmuş

Ayrılmam katardan ben şimden geri

Bezirganın yükü la''l ile gevher

Ana kar mı kılar harami dafer

Bezirganlar başı ol Cafer

Ayrılmam katardan ben şimden geri

Bezirganın yükü nereye gider

Uğramaz Sırat''a Mirac''a gider

Bezirgan başıdır Şah Gani Haydar

Ayrılmam katardan ben şimden geri

Bezirganın yükü ilm-i hamail

Doğru işleyene Hak ola kail

Bezirgan başıdır ahir Cebrail

Ayrılmam katardan ben şimden geri

Deryalar bekçisi dağlara nazır

Her nerde çağırsan orada hazır

Bezirgan başıdır Boz Atlı Hızır

Ayrılmam katardan ben şimden geri

Pir Sultan Abdal''ım aşıkı çoklar

Hiç kardaş bulmamış kend''özün yoklar

Korktuğumuz yerden Yaradan saklar

Ayrılmam katardan ben şimden geri', 'Şah''a giden ben bir bezirgan gördüm Ayrılmam katardan ben şimden geri Hemen tutmuş hakikatın yolunu Ayrılmam katardan ben şimden geri Bezirg...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ayrilmam-katardan-ben-simden-geri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azizim Sultanım Sen Safa Geldin', 'azizim-sultanim-sen-safa-geldin-pir-sultan-abdal-wbyll', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaynat muhabbetin kazanın kaynat

Bir nasihat eyle dostlara dinlet

Gevher deryasında gevher al da sat

Azizim sultanım sen safa geldin

Sohbette hezaran muhabbet açar

Mümin kullarına Hak rahmet saçar

Yari olan yarinden geçer

Azizim sultanım sen safa geldin

Yari olan arar yarini bulur

Eser bad-ı saba gönlüm de farır

Yükün katerlenmiş Nevruz''dan gelir

Azizim sultanım sen safa geldin

Abdal olan giyer hırkayı şalı

Yar için çekeriz ah ile zarı

Er irfan ceminde süreriz demi

Azizim sultanım sen safa geldin

Pir Sultan Abdal''ım ağladım güldüm

Yardan ayrılalı dar halde kaldım

Çok şükürler olsun cemalin gördüm

Azizim sultanım sen safa geldin', 'Kaynat muhabbetin kazanın kaynat Bir nasihat eyle dostlara dinlet Gevher deryasında gevher al da sat Azizim sultanım sen safa geldin Sohbett...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/azizim-sultanim-sen-safa-geldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Suskunluğunu', 'seviyorum-suskunlugunu-pablo-neruda-n3j9z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seviyorum suskunluğunu, sanki sen

yokmuşçasına burada

duyarsın beni uzaktan, dokunmaz sana sesim.

Uçup gitmiş gibi gözlerin

ve ağzın bir öpüşle mühürlenmiş.

Seviyorum suskunluğunu, çok uzakta

görünüyorsun

Sanki yas tutuyorsun, kumrular gibi cilveleşen

kelebek benzeri.

Uzaklardan duyuyorsun beni, ulaşmıyor sana sesim.

Bırak da varayım dinginliğine sessizliğinde.

Ve konuşayım sessizliğinle

bir lamba gibi parlak, bir yüzük gibi yalın.

Gece gibisin, suskunluğun ve takım yıldızlarınla

Yıldızlarınki gibidir sessizliğin, öyle uzak, önyargısız.

Seviyorum suskunluğunu, sanki sen yokmuşçasına burada

uzakta ve hüzün dolu, sanki ölmüşsün gibi.

İşte o zaman bir sözcük yeter

Uçarım, uçarım sevinciyle yaşadığının.

Çeviri: Ergin Koparan', 'Seviyorum suskunluğunu, sanki sen yokmuşçasına burada duyarsın beni uzaktan, dokunmaz sana sesim. Uçup gitmiş gibi gözlerin ve ağzın bir öpü...', ARRAY['Türk Edebiyatı','Şiir','Pablo Neruda']::text[], 8.5, '{"poet":"Pablo Neruda","poet_slug":"pablo-neruda","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seviyorum-suskunlugunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlı Düşler', 'nazli-dusler-nalan-kazazoglu-qe5jv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerim kamaşır kuşlar içime göçer

Alınca reçine kokusunu öykü dağlarının

Hiçbiri tehlikeli değil nazlı dost düşlerin

Öte yanına geçmez de, kalıp anlatırsan eğer...', 'Gözlerim kamaşır kuşlar içime göçer Alınca reçine kokusunu öykü dağlarının Hiçbiri tehlikeli değil nazlı dost düşlerin Öte yanına geçmez de,...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nazli-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçemediğim Sen', 'vazgecemedigim-sen-hikmet-yakisir-hkt2v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her ne olursa olsun.

İster senin olayım, ister olmayayım, 

Yüreğim senindir.

Çok sevdiğim senin, 

Sadece senin.

Geçici olmadığını biliyorum, 

Yüreğimin en derin yerinde, 

En gizli köşesinde saklayacağım seni.

Bazen gözlerimden yaş olup akacaksın, 

Bazen dudaklarımda bir gülümseme olarak kalacaksın.

Bazen de boğazımda bir düğüm olacaksın

Yutkunamadığım.

Hüznümde sevincimde sen olacaksın, 

Kimse bilmeyecek.

Kalbimin sızısı gönlümün sahibi olacaksın her zaman.

Seni sevdiğim için hiç pişman olmayacağım, 

Bir gün gideceksin biliyorum, 

Ama sen unutsan da ben seni unutmayacağım.

İşte bu kadar seviyorum, 

Daha fazlası var mı bilmiyorum.

Keşke yasak olmasaydın bana.

Evet sen yaşadığım en güzel rüyasın.

Bu rüyadan uyanacağımı bilsem de.

Senin kadının olamadığım için affet beni.

Bu seni istemediğimden değil, 

Senin olmayı, 

Senin kadının olmayı

Her şeyden çok isterdim.

Ne olur kırılma bana.

Bedenen sevişmesek de, 

Ruhlarımızın seviştiğini hissediyorum.

Bedenen olmasa da ruhen kadınınım.

Bence buda çok güzel, 

Seninle her şey güzel.

Beni böyle istediğin sürece hep olacağım.

Seni özlüyorum, özleyeceğim.

............. Seni seviyorum.

Sen benim biricik.............sın.

Vazgeçemediğim sen.

Belki bir gün.

Kimbilir.

(07 Eylül 2003) 

(Not: Bu şiir ''NE OLURDU SANKİ'' adlı şiirime bayan bir okuyucum tarafından gönderilen mailden alıntılar yapılarak oluşturulmuştur.)', 'Her ne olursa olsun. İster senin olayım, ister olmayayım,  Yüreğim senindir. Çok sevdiğim senin,  Sadece senin. Geçici olmadığını biliyorum,...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/vazgecemedigim-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz', 'olumsuz-zeki-caglar-cetin-w9jda', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün ışıklar bana

Tüm konuşmalar yok

Yeniden vazgeçmek üzere

Ben dahil tüm deliler sevgiden

Aşık, yani kaça kaça susmak

Öldürme beni ışık 

Bana aşık olunmadan ölemem', 'Bütün ışıklar bana Tüm konuşmalar yok Yeniden vazgeçmek üzere Ben dahil tüm deliler sevgiden Aşık, yani kaça kaça susmak Öldürme beni ışık  ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Çağlar Çetin']::text[], 8.5, '{"poet":"Zeki Çağlar Çetin","poet_slug":"zeki-caglar-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olumsuz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydınsız', 'gunaydinsiz-zeki-caglar-cetin-3137y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gülmeyi seviyorum 

Bir güneşi

Gülerken güneşler açıyor gözlerinde

Görüyorum

Bir uyanmayı seviyorum yanı başında 

Bir de susmayı seviyorum

Yanımda her olmadığında', 'Bir gülmeyi seviyorum  Bir güneşi Gülerken güneşler açıyor gözlerinde Görüyorum Bir uyanmayı seviyorum yanı başında  Bir de susmayı seviyoru...', ARRAY['Türk Edebiyatı','Şiir','Zeki Çağlar Çetin']::text[], 8.5, '{"poet":"Zeki Çağlar Çetin","poet_slug":"zeki-caglar-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gunaydinsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Boşlukta Öylesine - 1', 'bir-boslukta-oylesine-1-naime-erlacin-jviw0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '“pencereme bu gece ay düşse”

yüreğim suskun

sesini kısmış yüreğim

elinde bıçak

kör bir sokak 

bir çıkmazda parçalıyor kendini

“karanlıkta ölmem” demiştim hani

unutmuşum oysa korkabileceğimi

ne zor şeydir gözünü dikip 

seçilmiş bir boşluğa bakmak biliyor musun 

ürküyor yalnızlık düşüncesi

ruhumda tetiklenen katil mermiden

kaç tane ve ne çıkartabilirim bölsem doğrasam beni

geriye ne kalır ya da benden 

elimden düşürdüğümde kendimi

ay düşse pencereme bu gece

ay düşse gözyaşlarını indirerek dizlerime

yuvasında bekliyor mermi! 

(23 Eylül 2003)', '“pencereme bu gece ay düşse” yüreğim suskun sesini kısmış yüreğim elinde bıçak kör bir sokak  bir çıkmazda parçalıyor kendini “karanlıkta öl...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-boslukta-oylesine-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Verin beni bana', 'verin-beni-bana-cahit-i-pekoglu-ymfd0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben beni arıyorum 

benden eser kalmışsa eğer. 

Hiç var olmamışımki ben 

zaman nede çabuk geçmiş meğer. 

Ben beni hiç bulamadım 

beni sen yok etmişsin meğer... 

Ben beni arıyorum 

benden eser kalmışsa eğer 

Kalan yanımla dolaşıyorum 

Hayalde olsa bana ulaşıyorum.... 

Uyku halim, hayal halim 

galiba bu benim gerçek halim. 

Gerçek halim, gerçekte benimdir 

uykuda yaşansada, aşkım dediğimdir. 

Verin beni bana 

gerçeğe döneyim. 

Gerçekde ben benimle değilim 

aşkla eleleyim.....', 'Ben beni arıyorum  benden eser kalmışsa eğer.  Hiç var olmamışımki ben  zaman nede çabuk geçmiş meğer.  Ben beni hiç bulamadım  beni sen yok...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/verin-beni-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tilsim', 'tilsim-fazil-husnu-cakiroglu-auv86', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz yazgimizin insaniyiz, 

Muskasi boynunda asili.

Zamanin tilsimini tasiyaniz.

Bes vakit kiyam duran, 

Yüzündeki kani hayra yoraniz.

Yagmaya dursun bir zürel yagmuru, 

Ici disina cikaniz biz.

Uzagi yakin kilan, 

Görünmez elleri sikaniz biz.

Yazgiyi yazan degil yasayaniz biz.

Bilinmez efsanelerdeki bilinmez giziz

Ondandir bizi, ne siz anlarsiniz, 

Nede sizi biz.

Temelinden su cikan eski bir urum evi, 

Duvarindan tas düsürüyor.

Agustosda bir ihlamur, 

Erken kis yasiyor

Bu sehir günlerdir geceleri agliyor.

Gün isiyanda gece kimin umrunda, 

Zaman dedigin akip geciyor.', 'Biz yazgimizin insaniyiz,  Muskasi boynunda asili. Zamanin tilsimini tasiyaniz. Bes vakit kiyam duran,  Yüzündeki kani hayra yoraniz. Yagmay...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tilsim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıklar Kentinde Bir Gece', 'yalnizliklar-kentinde-bir-gece-vedat-didari-p5mbd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeşil kanatlı bir baykuştu tüneyen

Öksüz bırakıp gittiğin kaldırımlarında kentin

Bir geceydi yıldızların döküldüğü gökten

Gözleri yaşlı, gönülleri kırık göçmenlerin

Bir de sarhoşların ve başıboş köpeklerin

Yollara düştüğü saatlerden bir saatti

Ölüm gibiydi sessizliği bulvarların

Bekçisiz parkların sırılsıklam çimenlerinde

İnan şarap kokuyordu toprak ellerimde

Uzarken yapışkan kaldırımlara gölgem

Bir gizemli, meçhul sis içinde

İpince yürüyordun yarı kör gözlerimde

Yalnızlıklar kentinin yorgun göçmenleri

En içli türküleri halice döküyorlardı

Ötede balıkçılar ''denizi söküyorlardı''

Yüzlerce insan ağlıyor gibi geldi bana

Görkemli gemiler ağır ağır çıkarken limandan

Ölümü soluyordu yüzlerce insan o an

Kızıl bir ampuldü ufukta güneş

Kar gibi erirken sis saçlarımda, 

Gözlerimde ve avuçlarımda

Tezgâhlar kuruluyordu balık pazarında

Acıkan göçmenleri yalnızlıklar kentinin

Sabahını açıyorlardı yorgun gecelerinin

Yürüdüm yokuşlar boyunca bomboş

Yokuşlar boyunca seni düşündüm

Yürüdüm yokuşlar boyunca sarhoş

Anlatamam nasıl eziliyordu içim

Uykusuz gözlerim nasıl yanıyordu

Sensizliğe mahkûm bir kent uyanıyordu

Ekmek peşine insanlar çıkıyorlardı evlerinden

Paltolarının yakaları çekili kulaklarına

İnsanlar yürüyordu otobüs duraklarına

Yüzlerce insan ağlıyor gibiydi

Ben sitemler kuruyorken sana

İnsanlar ölü gibi bakıyordu bana

Bir anlamsız türküydü yaşanan bu kentte

Yüzlerce insan bakıyordu yüzüme görmediğim

Gözlerinde öylesi elemler benim bilmediğim

Anlatamam sana o zehirli tadı ağzımdaki

Kaçışımı anlatamam sokak aralarından

Giderek çoğalan gürültülerle her yandan

Zavallı göçmenleri yalnızlıklar kentinin

Terkederlerken yılgınlıklarını rıhtımda bir esime

Doldurdum kentin sensiz havasını nefesime', 'Yeşil kanatlı bir baykuştu tüneyen Öksüz bırakıp gittiğin kaldırımlarında kentin Bir geceydi yıldızların döküldüğü gökten Gözleri yaşlı, gön...', ARRAY['Türk Edebiyatı','Şiir','Vedat Didari']::text[], 8.5, '{"poet":"Vedat Didari","poet_slug":"vedat-didari","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yalnizliklar-kentinde-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin Efendisi', 'kalbimin-efendisi-selma-unsal-is90z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buldum seni kalbimin efendisi

Gözlerinde sevgilerin en güzelini

Sözlerinde anlamlarin en degerlisini

Gülüsünde buldum kendimi

Buldum seni kalbimin efendisi

Karanlik dünyamin günesini

Durgun denizimin firtinasini

Gecmisimi unutturan umutisigimi

Kalbinde buldum kendimi

Sen kalbimin efendisi

Eksik etme benden sevgini

Birakma ömrünce ellerimi

Üsüdügümde sar isit beni

Vazgecip unutma hic birzaman 

Senin icin aglayan bu gözleri

Seni seviyorum kalbimin efendisi

Asigim sana yok ötesi

Eger birgün birakicak olursan beni

Al götür yaninda sana tapan kalbimi

Sevemez birdaha, SENSIN TEK SEVDIGI!', 'Buldum seni kalbimin efendisi Gözlerinde sevgilerin en güzelini Sözlerinde anlamlarin en degerlisini Gülüsünde buldum kendimi Buldum seni ka...', ARRAY['Türk Edebiyatı','Şiir','Selma Ünsal']::text[], 8.5, '{"poet":"Selma Ünsal","poet_slug":"selma-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kalbimin-efendisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Biliyor musun?', 'sen-biliyor-musun-vedat-didari-94pus', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen biliyor musun

Gece gündüz, yerli yersiz

Yüreğimin kahırlarla burkulduğunu

Kahkahalarımın ucunda

Gözyaşlarımın savrulduğunu? 

Sen biliyor musun

O çakmak çakmak gözlerinde 

Sevgileri dokumaktan

O güzelim dudaklarından

Şarkıları okumaktan

Başkaca bir şey istemediğimi? 

Sen biliyor musun

Anlamsızlığını sitemlerinin

Beni bunca hiçlemelerin varken

Gözlerimin içine bakıp bakıp ta

Başka sevdaları yaşarken? 

Sen biliyor musun

Bütün olumsuzluklara inat

Yaşamımın baştanbaşa

Seni özlemek olduğunu? 

Sen biliyor musun allah aşkına

Benim için 

Ne demek olduğunu?', 'Sen biliyor musun Gece gündüz, yerli yersiz Yüreğimin kahırlarla burkulduğunu Kahkahalarımın ucunda Gözyaşlarımın savrulduğunu?  Sen biliyor...', ARRAY['Türk Edebiyatı','Şiir','Vedat Didari']::text[], 8.5, '{"poet":"Vedat Didari","poet_slug":"vedat-didari","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-biliyor-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sınavı Geçeceğim.', 'bu-sinavi-gececegim-suleyman-saylan-a4ojz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BU  SINAVI  GEÇECEĞİM.

Mutluluktan içeceğim, 

Sarhoş olup düşeceğim.

Senin aşkın ile yanıp, 

Yana yana pişeceğim.

Uyku girmez gözlerime, 

“Seni nerden sevdim? ” diye.

Sevgin sırat olsa bile, 

Bu sınavı geçeceğim.

Sevdan ile boğma beni, 

Sevdim diye yorma beni, 

Başkasından sorma beni, 

Ölsem bile seveceğim.

Öyle kolay olmayacak, 

Sevda gülüm solmayacak, 

Asla elin olmayacak, 

Muradıma ereceğim.

Al duvaklar giyeceksin, 

Bana gelin geleceksin, 

Gönlümde gül vereceksin, 

Tutam tutam dereceğim.

Bugün varsın, yarın varsın, 

Hep benimle olacaksın, 

Bir de oğlan vereceksin, 

Sevincimden öleceğim.

Mutluluktan içeceğim, 

Sarhoş olup düşeceğim.

Ben senin aşkın yüzünden, 

Yana yana pişeceğim.

Süleyman  SAYLAN

((İzmir-Selçuk (Yoncaköy) ,07.08.1999,  Saat: 03.05))

Not: Şarkı sözü olarak yazılmıştır.', 'BU  SINAVI  GEÇECEĞİM. Mutluluktan içeceğim,  Sarhoş olup düşeceğim. Senin aşkın ile yanıp,  Yana yana pişeceğim. Uyku girmez gözlerime,  “S...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bu-sinavi-gececegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimdeki Hayal', 'resimdeki-hayal-vedat-koparan-1s5q6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelişinle bir ok gibi saplandın geceye 

Yıldız düşürdün gözlerime

İz düştü yüreğime şimdi  ince bir sızı

Senli sensizliklerde..

Yine ben ve yine sen 

Tüm çekici güzelliğinle karşımdasın

Bu platonik hayaller ötesi perdede 

Beynimde ki titreşimler ve

İçimde kıpırdanan zıpır çocuk

Nasıl hoyratlaşıp nasıl esmekte bir bilsen

Yitip gidiyorum 

Değerli varlığını yansıtan resmindeki hayalinle...

Seni görmek sanki gerçekliğine ermekti o an gece nasılda ısındı

Bir gelip bir gidiyorsun özleniyorsun acabalar dedirtiyorsun..

İçimde senler kıpırdanıyor çoğaldıkça çoğalıyorum

Biliyorum  ki 

Bundan senin hiç haberin bile olmuyor.

Düşten gerçeğe 

Herkes kendi yanlızlığını  kendinde çoğalarak yaşar

Bense senin yanlızlığını azaltmak adına 

Uzansam dokunabilir miyim, Tutabilirmiyim düşlerini..

Beynimde ur yüreğimde yara

Seni sonsuza kadar taşırım

Bu vurgun yoksun yaşamda..

Vedat.K 20.09.2003 (07.31)', 'Gelişinle bir ok gibi saplandın geceye  Yıldız düşürdün gözlerime İz düştü yüreğime şimdi  ince bir sızı Senli sensizliklerde.. Yine ben ve ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/resimdeki-hayal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldüm Dedin', 'oldum-dedin-vedat-koparan-r933s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalan de  gerçek olmasın bu rüya

Beni kahretti

Bu varlığını bilip yok oluşun

Yüreğim titredi sessizliğin sesi ürperdi

Adına kaç zaman yattım 

Uykusuz geceler yakarak hüzünlere sardım 

Şiir içitim su diye  şiirlere düştüm 

Acıların en büyüğünde sensizlikte 

Öldüm dedin senle öldüm

Gel ne olursun yalandı de yeter ki..

Vedat.K 19.09.2003', 'Yalan de  gerçek olmasın bu rüya Beni kahretti Bu varlığını bilip yok oluşun Yüreğim titredi sessizliğin sesi ürperdi Adına kaç zaman yattım...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/oldum-dedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak', 'safak-vedat-koparan-a10im', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soyunduk en gizli karanlıklardan

Tüm gizil duygulardan sıyrılarak

Güneşten aldığımız aydınlıkla

Ver gözlerini gözlerime 

Ardımıza bakmadan gidelim

Sevda türkülü şiirlerle

Öpüşler uyandırsın bizi sabaha..

Hangi gece vurur beni

Savrulurum her  poyrazda

Hangi gece düşerim o masaya

Serilir mi gölgem

Güneş aldığım günden geceye..

Ok kirpiklerin  acıtır 

Yanık türkü gözlerin

Bakamaya doyamam

Hüzünde yoksunluk yangını 

O koca  kavak

Benim sana yandığımdır vurgun şafak..! 

VedatKoparan 22.09.2003 (23:19)', 'Soyunduk en gizli karanlıklardan Tüm gizil duygulardan sıyrılarak Güneşten aldığımız aydınlıkla Ver gözlerini gözlerime  Ardımıza bakmadan g...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/safak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Boşlukta Öylesine - 2', 'bir-boslukta-oylesine-2-naime-erlacin-8ia99', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'eksilirken 

öyle doluyorum ki yapayalnızlıkla

kalabalıklaşıyoruz birden

ağır çeken bir terazi asıyorum boşluğa

denge bir o yana 

bir bu yana

doluyor kefe... boşalıyor kefe

sürgün verip yazıcı kimliğimle

vahşice buduyorum sonra dalları 

terk ediyor içim

ak bir buluta yakalatıp kendimi

soluk bir sayfa gibi asıyorum yüzüme

bir hesaplaşma 

bir yüzleşme 

ve yüreğimi öpen o yapışkan duygu:

''ay neden düşmüyor pencereme 

dizlerim neden göz yaşlarımla yıkanıyor! '' 

kendi izini süren avcıyım artık 

yağmur tutuyor yüzüm

yüreğim ıslak 

karanlık

yüreğim derin bir kederde...

(23 Eylül 2003)', 'eksilirken  öyle doluyorum ki yapayalnızlıkla kalabalıklaşıyoruz birden ağır çeken bir terazi asıyorum boşluğa denge bir o yana  bir bu yana...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-boslukta-oylesine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Halkının Valisine-(Hamisine)', 'turk-halkinin-valisine-hamisine-mehmet-budak-by5vs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adı-Recep  Yazıcıoğlu

Görevi-Halkın valisi-hamisi

Sevdi seni alevisi, sünnisi, şafisi, 

Sevdi seni işçisi, memuru, çiftçisi

Bazen şöfor oldun bazen çiftçi

Bazen işçi oldun bazen emekli

Hatta belkide köşedeki simitçi

İşçinin, emeklinin, esnafın hamisi

Aydın, Erzincan, Denizli derken

Daha yapacağın çok şey varken

İnsanlara insanlığı anlatırken

Trafik canavarına neden sen

Halktan geldin hakka gittin

Unutulan değerleri bize sen öğrettin.

Atılgan gözü kara bir yiğittin

Bizleri bırakıpta neden gittin

Bazen ak kağıt oldun bazen kara kalem

Sen geldin düzenbazlık yok oldu sırra kadem

Tanrı seni bizden çok sevdi tutuyoruz matem

Seni unutmayacağız anacağız hep dönem dönem

(10/09/2003 Söke)', 'Adı-Recep  Yazıcıoğlu Görevi-Halkın valisi-hamisi Sevdi seni alevisi, sünnisi, şafisi,  Sevdi seni işçisi, memuru, çiftçisi Bazen şöfor oldu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Budak']::text[], 8.5, '{"poet":"Mehmet Budak","poet_slug":"mehmet-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/turk-halkinin-valisine-hamisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Sensiz', 'seninle-sensiz-alpaslan-i-pek-u0f9a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığı çöktüğünde yüreğime

Bir martının çığlığı değil, beynimi kemiren

Dizlerim  diremeyipte düştüğümde yerime, 

İşte insafsız, o benim yokluğunda deliren.

Bak şimdi ellerim bomboş, kafamsa sarhoş

Belki de gülüyorsun, mühim değil gözyaşlarım

Beyhude diyemem ki; şimdi gel, bana koş, 

Yıkamam yığılmışsa önüme kader taşları.

Eğirtmece doladığın çürük ip değilim ben 

Seni göremeyecek bir yarasa hiç değilim

Ama benim aşk ateşinden güneşini yiyen

Karanlığında boğulan sızmış mum da değilim

Güneşin özlemi değil mi bulutlarla olmak

Toprağın da gerdeği değil mi suya kavuşmak

Bülbüle yakışır mı hiçgülsüz bahçelerde uçmak

Toprak suya, bülbül güle, bense sana hasret', 'Gecenin karanlığı çöktüğünde yüreğime Bir martının çığlığı değil, beynimi kemiren Dizlerim  diremeyipte düştüğümde yerime,  İşte insafsız, o...', ARRAY['Türk Edebiyatı','Şiir','Alpaslan İpek']::text[], 8.5, '{"poet":"Alpaslan İpek","poet_slug":"alpaslan-i-pek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seninle-sensiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Ayaktayım', 'seninle-ayaktayim-mehmet-ali-cibikli-g3klk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yokluğun soğuk savaş, 

Yüreğimi dağladı.

Eridim yavaş yavaş, 

Gözyaşlarım ağladı.

Gözlerimde yaş olsam, 

Senin için ağlardım.

Çaresiz bir kuş olsam, 

Sana doğru uçardım.

Seni sensiz yaşamak, 

Yaşamak sayılmıyor.

Yokluğuna dayanmak, 

Hiç de kolay olmuyor.

Sevdan beni bitirdi, 

Ümidim sendin benim.

Tükenmişim ben şimdi, 

Hani benim sevenim? 

Sevdam taşkın sel gibi, 

Duramıyor yerinde.

Gözyaşlarım göl gibi, 

Büyüyor hep içimde.

Sana ben kadar yakın, 

Sen kadar uzaktayım.

Beni bırakma sakın, 

Seninle ayaktayım.', 'Yokluğun soğuk savaş,  Yüreğimi dağladı. Eridim yavaş yavaş,  Gözyaşlarım ağladı. Gözlerimde yaş olsam,  Senin için ağlardım. Çaresiz bir ku...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seninle-ayaktayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum', 'yorgunum-mehmet-ali-cibikli-wvqzz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana aşığım ben, çok seviyorum, 

Gece gündüz hergün, hep benimlesin.

Bir gölge gibisin, benim yanımda, 

Gözümde hayalin, aklımda sesin.

Sevgi yağmurların beni ıslattı, 

Aşk nezlesi oldum, artık sayende.

Hislerim yeşerdi, şimdi yeniden, 

Derdimin dermanı, senin elinde.

Derdime derman ol, kalbimi dinle, 

Arzularım sensin, emelim sensin.

Sevmişim işte ben, hiç düşünmeden, 

Söyle şu kalbine, birazcık sevsin.

Aşk olunca mantık, aranmaz derler, 

Bırak şu inadı, sevmeyi dene.

Duygularım yoğun, sevgim çoğaldı, 

Seni düşünmekten, yorgunum yine.', 'Sana aşığım ben, çok seviyorum,  Gece gündüz hergün, hep benimlesin. Bir gölge gibisin, benim yanımda,  Gözümde hayalin, aklımda sesin. Sevg...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yorgunum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeçenya', 'cecenya-burhan-gumus-qknre', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ÇEÇENYA

Kan ve gözyaşı yüreğimde biteviye

Acıları kuşanırım bu şiire

Ki bu şiir alıp götürecek 

Vahşet dolu günlerin yaşandığı ülkeye.

Aah! Çeçenya Çeçenim

Masumiyet bahçesinin fidanları

Kevserim

Gümüş servilerim

Kolum kanadım

Ateş arkadaşlarım 

Atam Şamil’in emaneti

Hak’kın Kafkaslardaki kalesi

Derken

Bir fecir zamanı gün perde perde aralanırken

Acı feryatlar yükseldi Çeçenyadan

Ve sona 

Dalga dalga yayıldı ölüm.

Ölüm ne ki bir kurtuluş

Nasıl anlatsam bilemiyorum

Kelimeler kifayetsiz

Renkler yetersiz

Cihanda yok eşi ve benzeri böylesine bir vahşetin.

Öyle ki

İnsan kılığına girmiş ağzı salyalı çakal sürüleri

Arkalarında leş kargaları

Ülkemin bütün coğrafyasında 

Ve her bir karışında kustular bütün kinlerini

Öyle ki

Bir çirkin görüntü sergilendi güllerin binlercesinde

Göğü ve yeri utandıran

El değmemiş kızlar ve dahi analar

Karadulların en necis kanlarıyla sulandılar

Ya çocuklar

Çocuklar ki 

Saklambaç oynarlar gölgesinde mermilerin

Mermiler ki 

Kurulmuş can pazarı çığlık üretir ölüm star

Öyle ki 

Zoraki hicretin pusu kurulmuş yollarında 

El ayak buz kesmiş

Günlerce aç ve susuz kalmış Çeçenistan

Çeçenim öz yurdunda prangalı

Yalnız ezik yorgun savaşçı

Bense başım eğik utanırım

Utanırım onsuz hürriyete 

Kültür ve sanat abidelerim

Gökyüzüne uzanan minarelerim

Şen şakrak şarkılarım

Neş’em hüznüm

Bağım bostanım

Hayallerim hatıralarım

Heyhaaat şimdi hepsi geride kaldı.

Artık ağıtlar yakıyorum sana

Eeyyy  yeryüzünün efendileri! 

Ey insanlık! 

Çeçenyada 

Mavi dünyamın her köşesinde

Korkunç feryatlar yükselirken

Alevler içinde 

Sen neredesin? 

Sen neredesin? 

Gözü yaşlı bulutlar kan ağlıyor

Sen ağlamıyorsun

Ey sevgili! 

Ey benim uyuyan güzelim

Hele siz! 

Çıldır çıldır bakan yıldızım

Kevser bildiğim arkadaşım

Baykuşun ölüm sessizliğinde 

Bakıyorsun, görüyorsun düşünce yok

Bir hal ki kuvvet var rabıta yok

Sen ağlamıyorsun

Hava ağlıyor

Sen yine ağlamıyorsun.', 'ÇEÇENYA Kan ve gözyaşı yüreğimde biteviye Acıları kuşanırım bu şiire Ki bu şiir alıp götürecek  Vahşet dolu günlerin yaşandığı ülkeye. Aah! ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Gümüş']::text[], 8.5, '{"poet":"Burhan Gümüş","poet_slug":"burhan-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/cecenya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-mehmet-ali-cibikli-3ssl7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerine baktıkça, 

Kendimi buluyorum.

Gözlerinin içinde, 

Hemen kayboluyorum.

Sanki Tanrım yaratmış, 

Çok özene bezene.

Aman nazar değmesin, 

O güzelim gözüne.

Gözlerini dinledim, 

Beni çok seviyormuş.

Benim de sevdiğimi, 

Gözlerin biliyormuş.

Ben bakayım, o baksın, 

Gözler birbirimize.

Görenler gıpta etsin, 

Şu bizim sevgimize.

Bak artık bahar geldi, 

Yeşersin ümitlerim.

Sen bir kez evet dersen, 

Ben hep seni severim.', 'Gözlerine baktıkça,  Kendimi buluyorum. Gözlerinin içinde,  Hemen kayboluyorum. Sanki Tanrım yaratmış,  Çok özene bezene. Aman nazar değmesi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerin-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kahkaha', 'son-kahkaha-salih-ozalasan-8j3f7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben sonbahardım senden önce

Bir yaprak misali, savrulurdum yerlerde

Gecelerim karanlık, yıldıza hasrettim gökte

Sevgi pınarlarım kurumuş dönmüştüm bir çöle

Issız bir vadiydim, gözlerden ırak

Yönümü dönsem de hangi yöne

Yalnızlık sarmıştı bedenimi inadına

Bekledim gün ola devran döne

Sen çıktın karşıma, gecenin bir yerinde

Umutların tükenip, her şeye veda ettiğimde

İsyanlara çeyrek kala, zavallı kalbimde

Yağmur olup yağdın, hayat verdin bu çöle

Şarkılar seni söylüyor artık

Kulak ver bak, bir dinle

Sevdalar coşmuş kemanımın tellerinde

Adın dilimde ölmeyen nağme

Yıldızlar parlıyor karanlık yok

Bir güneş oldun her geceme

Üşümüyorum artık, içimde bir ateş

Sevdan sarmış, tüm bedenime

Seni yaşıyorum, ciğerlerimde nefes

Damarlarımda kan, yükselen beynime

Ellerimi uzattığımda dokunduğum

Hapsettiğim iki bedeni bir bedene

Gecelerde düşlerimin kara sevdası

Gün boyu parlayan ışık gözlerimde

Hasretini ekmeğime katık ettiğim

Can veren sensin seven yüreğime

Sen bende bensin, sevdaya uzanan

Sen bende aşksın, coşkuyla yaşanan

Sen bende güneşsin, bedenimi ısıtan

Sen bende duasın, adı her daim okunan

Sen bülbülün sevdasını çektiği gül

Sen Ay gecelerimde asla batmayan

Sen gülmeyen yüzümdeki son kahkaha

Seni kaybedersem asla yaşayamam

Y.Tarihi 23-09-2003 Saat 12,20

Salih Özalaşan', 'Ben sonbahardım senden önce Bir yaprak misali, savrulurdum yerlerde Gecelerim karanlık, yıldıza hasrettim gökte Sevgi pınarlarım kurumuş dön...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/son-kahkaha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu benim', 'suclu-benim-adem-aydin-ehndk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne ise verin artık cezamı... 

suçlu benim çekmem gerek...

kendi kendime buldum belamı

bu sevdadan geçmem gerek...

neyime benim bu aşk, bu sevda

kaç defa yıkıldım böyle kaç defa

müstahak bana her türlü cefa...

suçlu benim çekmem gerek....

çağırın celladı vursun başımı

çatlattım sonunda sabır taşımı

genç olsamda sorma yaşımı

suçlu benim çekmem gerek...', 'ne ise verin artık cezamı...  suçlu benim çekmem gerek... kendi kendime buldum belamı bu sevdadan geçmem gerek... neyime benim bu aşk, bu se...', ARRAY['Türk Edebiyatı','Şiir','Adem Aydın']::text[], 8.5, '{"poet":"Adem Aydın","poet_slug":"adem-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/suclu-benim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-gulay-yildiz-ilhis', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yakınsın bana aynadaki görüntüm kadar

Ve tıpkı onun gibi sanalsın dokunmak imkansız

Yanımdasın besbelli işte, doğruca

Ama olmamalı gibi uzaksın

Karanlığın sonunda sevgim bekler sevgini

Kusursuz imkanı fırsat gözler

Gözyaşım pınar olsa da bil ki; 

Bu acıya bin gülüş bedel...', 'Yakınsın bana aynadaki görüntüm kadar Ve tıpkı onun gibi sanalsın dokunmak imkansız Yanımdasın besbelli işte, doğruca Ama olmamalı gibi uzak...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bedel-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanım', 'i-syanim-gulay-yildiz-187yt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Işık terketti bizleri, gözüktü kara çarşaf

Yıldızların varlığımı çoğaldı ne! 

Sanki daha bir parlak, daha bir çok

Ve kayanlarda öyle...

Her kayan yıldız birinin ömrünün son simgesi

Onunla beraber terkediyor bizleri

Tıpkı isyanım gibi...

Yıldızım kaydı ve kara çarşafı terketti

İsyanımda beni...', 'Işık terketti bizleri, gözüktü kara çarşaf Yıldızların varlığımı çoğaldı ne!  Sanki daha bir parlak, daha bir çok Ve kayanlarda öyle... Her ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/isyanim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir taş düşün, işte o benim yüreğim...', 'bir-tas-dusun-iste-o-benim-yuregim-gulay-yildiz-e08df', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir taş düşün, işte o benim yüreğim

Ve bir damla benim gözlerim

Düşer damlalar taşa, taş erir

Ve yanlız ben öldürürüm katilini

Yanlız ben azad ederim yüreğini

Yanlız bana çalışır azrail

Yanlız benim yanımda durur o huri...

Bense tatminsiz yaşarım hayatı

Beklerim o taş erisin, bitsin

Ve yanlız yanında seni getirsin sular

Ne azrail, ne huri

Canım sadece seni diler', 'Bir taş düşün, işte o benim yüreğim Ve bir damla benim gözlerim Düşer damlalar taşa, taş erir Ve yanlız ben öldürürüm katilini Yanlız ben az...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-tas-dusun-iste-o-benim-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve O Dört Melek Bile Şaşar Kalır...', 've-o-dort-melek-bile-sasar-kalir-gulay-yildiz-4wwmg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir iniş ve bir çıkış yaşam

Ve bir tepe benim tırmandığım

O çıkışın verdiği hazla iyice inatlaştığım...

Bilirdi mantığım, 

Haz arttıkça acı verecek iniş.

Ve verdi de o inanılmaz acıyı! 

Dayanmaz yürek, iniltilerin tınısı sarsar

Öyle ki, göğün sonsuz karanlığı kaplar alacakaranlığı

Bir mevsim ölür, bir gece batar, yeni bir gece doğar; 

Daha karanlık, daha iniltili...

Ve gözüm yemin eder ağlamamaya

Göğüslerimden akar yaşım

Süzülür yanaklarım yerine bedenime

ve o dört melek bile şaşar kalır; 

''Sevdan kadar büyük acın'' derler

''Ve kalbin kadar hırpalanmış bedenin''

Özleme yetim körelir ve yerini bir pırıltı alır

O bir ışık karanlığın son örütüsünde

Bir akis olup göz kırpar

Bazen büyük sarı bir misket, 

Bazen de bir toz zerreciği ciğerimde

Ve o dört melek bile şaşar kalır...

Derler ki; 

''Sevdan kadar büyük hayal gücün''

''Kalbin kadar hırpalanmış sevgin''

Ve ben onlara cevap veririm; 

''İsyanım kadar büyük acım''

''Kalbim kadar hırpalanmış tüm yetilerim''

Ve ölüm sessizliği çökünce gürültülü hatıralara

Ben, ben olmaktan çıkınca, benden öte

Tek isyanım ve onun acısı kalır bedende

Hatta bedenden öte...

Giden Selen''e', 'Bir iniş ve bir çıkış yaşam Ve bir tepe benim tırmandığım O çıkışın verdiği hazla iyice inatlaştığım... Bilirdi mantığım,  Haz arttıkça acı ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ve-o-dort-melek-bile-sasar-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Not', 'not-gulay-yildiz-j324u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sürdürsede zaman sonsuz aralığını açmaya

Ve solsada güller her seferinde yeşeren yaprakla

Bitsede acılar sonsuz hüzünle gülümseyen dudakta

Kamçılasada bir bedeni mutluluğun ateşiyle yanan kırbaç, 

Kanatsada her yarayı damla damla, merhemler

Ben olmasamda sensiz ve gülsem yine

Kalsam yanında gecelerce ve ağlasam saatlerce

Cehennem kapısından girerken sevinç çığlıkları atsalar

Cennetten içeri bakınca üzüntüden ağlasa insanlar

Ve bitmesi imkansız aşklar bitmek için yırtınsada

Ve kalbim durduğunda bile durmasa gözyaşlarım...

Bu kadar imkansızlıklar içinde gerçek olan tek hayal, 

Ömür boyu birliktelik, ömür boyu yanımda sen...

Bu kadar hayalin içinde hayal olan tek gerçek, 

Seni daima sevecek bir ben! 

Ve unutma! 

Hayaller geçmişten, gerçekler gelecekten...', 'Sürdürsede zaman sonsuz aralığını açmaya Ve solsada güller her seferinde yeşeren yaprakla Bitsede acılar sonsuz hüzünle gülümseyen dudakta K...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/not-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzüne Yağmur Olmuşum Ben', 'yuzune-yagmur-olmusum-ben-gulay-yildiz-2hilz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Titreşir yıldızlar, belli ki ürperir soğumdan

Bekleşir yelkovan, belli ki yapamaz akrepsiz

Sevişir melekler, neden? Bilinmez, öylesine

Kemikleşir bakışlar, belli ki ağır kelamlar

Haran uçmuş gitmiş feza da bir yere

Selen''e ise ulaşmış bir balık adam

Akhileus'' u çıkartmışlar bir dar ağacına

Koparmışlar yüreğini ayak bileğiyle

Ve sonsuzun ucu gözükmüş

Sen olmuş dağ, taş

Dağ taş ters dönmüş ben olmuş

Sen olmuş kara zebaniler

Birden perileşmiş ben olmuş

Ve çakışmış bir ara tüm değişimler

Meyve vermiş, su olmuş damla damla

Yüzüne yağmur olmuşum ben

Yüzüme kar olmuşsun sen...

Dondurmuşlar, tazeliğin gitmiş

Yıllamışlar mahsende

3 yıl,7 yıl bekletmişler

Demlenmişsin ama daha bir acımışsın

Çıkagelmiş birgün, yağmur inmiş yüzüne zamansız

Sen kar bile olamamışsın...', 'Titreşir yıldızlar, belli ki ürperir soğumdan Bekleşir yelkovan, belli ki yapamaz akrepsiz Sevişir melekler, neden? Bilinmez, öylesine Kemik...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yuzune-yagmur-olmusum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılsama', 'yanilsama-ahmet-aksoy-b24mx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yanılsama mı bu 

Yoksa gerçekten 

Kapının önünden 

Biri mi geçti az önce

Neler oluyor bana

Gözlerim mi şaşırtıyor yoksa

Olmayanla olan arasında

Süregelen oyun mu bu', 'Bir yanılsama mı bu  Yoksa gerçekten  Kapının önünden  Biri mi geçti az önce Neler oluyor bana Gözlerim mi şaşırtıyor yoksa Olmayanla olan a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yanilsama-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyahla Beyaz', 'siyahla-beyaz-ahmet-aksoy-yt8e0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatla ölüm

Siyahla beyaz

Hayat beyaz

Ölüm siyah

Arası yok bu işin

Ya siyah ya beyaz.', 'Hayatla ölüm Siyahla beyaz Hayat beyaz Ölüm siyah Arası yok bu işin Ya siyah ya beyaz....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/siyahla-beyaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Osman Çavuş', 'osman-cavus-ahmet-aksoy-9ipyc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşman dayanmış kapıya

Osman çavuş direniyor düşmana

Kaçacak yer yok

Tek vatan bu topraklar

Osman çavuşun kolu yok

Bacağı yok artık

Yüreği aklı yok

Hepsi bu toprakların

Osman çavuş ne yapsın.', 'Düşman dayanmış kapıya Osman çavuş direniyor düşmana Kaçacak yer yok Tek vatan bu topraklar Osman çavuşun kolu yok Bacağı yok artık Yüreği a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/osman-cavus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tualdeki Gölgemsin', 'tualdeki-golgemsin-gulay-yildiz-k6cck', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çırpınışın sesi var iniltinde 

Suya düşen damla tınısında 

_''gel'' diyorsun, 

kalbim o kadar dingin. 

ve erbain denli puslu, ağır,yorgun 

Hissediyorum… 

uzağındasın resmin 

evet,evet hissediyorum 

Gelip giden bakışın alaca renkli 

Siyahın yok, 

ama fırçan hep siyahtan yana 

Umudun…kazınmış aşkların bitişindeki iz’e 

iki kalp atışı arasında kalakalmış, Mutluluğun; 

askıda ki o küçücük zaman diliminde 

Sessiz; 

Sensiz! 

Gelsem çat kapı, 

kuş olacak belki ruhun 

Sesim de 

Belki aradığın hüzün... 

Ve; 

Ellerin, çalakalem izlerin yorgunluğunda 

Gözlerimin damlalarına yol yazdıkların, 

Sözlerinden kalanların yankısı içimde içimi açan. 

Bilmek güzel, 

iyi ki varoluşunda gizem asılı kalmış 

Sen; 

Tualimin gölgesine gölge katıyorsun... 

Sesime ses, 

yazıma yazı, 

varlığıma can... 

Aşkın olmadığı aşkı anlatıyorsun, 

Yol gösteriyorsun sevdanın en körüne 

En puslusunda gecelerin 

Hayallerdeki resmi boyuyorsun 

bu cüzamlı aşkı çizerken ben; 

Fırçam; sözlerin, 

Tualimdeki gölgemsin, 

Yastığımdaki nefes değil belki 

Tebessüm; 

yüzümdeki derin çizgilerin sahibi 

Sen; 

varolmayan gezegendeki 

olmayan sevginin beyaz atlı prensi, 

anılmayan tanrının kösnül ibadeti 

Sen; 

gizemli büyünün en tanıdık yüzü, 

Ve; 

Sen; 

hak edilen sevginin hakkını alamamış sahibi! 

***Nazım Ercan... Destek için teşekkürler', 'Bir çırpınışın sesi var iniltinde  Suya düşen damla tınısında  _''gel'' diyorsun,  kalbim o kadar dingin.  ve erbain denli puslu, ağır,yorgun ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/tualdeki-golgemsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mekan-ı Evren, Aşk-ı Devran…', 'mekan-i-evren-ask-i-devran-muammer-celik-e13j9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O ”Sensizlik” yok mu. 

Ahh „O“ sensizlik...! 

Biliyorum, 

boğuyordur  bensizligin içinde seni...

Senin

benim

onun

ve 

ötekinin yeri „UZAY“ değil mi zaten, dostum Şair! 

Bizi paklayacak başka yer mi var evrende, zahir! 

Savurun benden kalanları Feza’ya

Her Galaksi’deki 

”O”nu anlatan her Yıldız’dan 

Toprak atın üstüme

ve Güneş’ten bir tutam

Mehtap’tan bir avuç 

ile tüm evreni saçın üstüme

„Hep Evrensel düşünmek, 

evrensel SEVMEK isterdi” yazın Taş’ıma

Sakın el değmeyin, sevdiğimden önce

el değmedik Naaş’ıma…

23.09.2003

BirDeli', 'O ”Sensizlik” yok mu.  Ahh „O“ sensizlik...!  Biliyorum,  boğuyordur  bensizligin içinde seni... Senin benim onun ve  ötekinin yeri „UZAY“ d...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mekan-i-evren-ask-i-devran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirli Suratı Dünyanın', 'kirli-surati-dunyanin-muammer-celik-mkdh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göbek çukurundu 

gece içine düştüğüm 

göğüslerindi tutunup çıktığım

Dudaklarında asılı kalan dilimle 

Kenetleyerek ellerimi

Tutmasaydım belinden

Nasıl kurtulubilirdim değilse 

bu suratı kirli dünyanın elinden? 

23.09.2003

BirDeli', 'Göbek çukurundu  gece içine düştüğüm  göğüslerindi tutunup çıktığım Dudaklarında asılı kalan dilimle  Kenetleyerek ellerimi Tutmasaydım beli...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kirli-surati-dunyanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-muammer-celik-b3p2y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cennet’te Havva’m 

Dünya’da sevdiğim 

iki gözümde 

tek bebeğimsin 

..................sen benim 



19.06.2003

BirDeli', 'Cennet’te Havva’m  Dünya’da sevdiğim  iki gözümde  tek bebeğimsin  ..................sen benim  19.06.2003 BirDeli...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bebegim-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Yeniden Fetholuyor!', 'i-stanbul-yeniden-fetholuyor-muammer-celik-gk9co', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neler oluyor Allah aşkına 

İstanbul’un fethine mi çıktın... 

Ben içimde kocaman 

tarihi bir İstanbul taşırım, 

istanbul’lu olmasamda… 

Surlarıma tırmanıyorsun 

inatla, azimle, 

Ulubatlı Hasan gibi 

Karaya inat 

gemiler çekiyorsun 

tek tek Haliç''ime 

taşınıyorsun yavaş yavaş içime… 

Soğuk ve serin terler 

akıyor yüzümden... 

Bölük bölük saldığın Leventler 

meltem esen denizime 

yelken açıyorlar...

Gemilere FORA...! 

Neler oluyor sana Allah aşkına 

dışımdan sardın... 

Beni içimden fethediyorsun 

yavaş yavaş… 

Beyaz bayrak 

elimde yarı havada 

algın algın bakıyorum 

kıpraşmadan, direnmeden 

karşı koymadan… 

İstesemde karşı koyamıyorum...! 

Aşkın feth’ine mi karar kıldın, ne? 

Neler oluyor sana ve bana 

ateş bacayı sarmış, görmüyorum 

ve ben hala direnemiyorum...! 

18.06.2003

BirDeli', 'Neler oluyor Allah aşkına  İstanbul’un fethine mi çıktın...  Ben içimde kocaman  tarihi bir İstanbul taşırım,  istanbul’lu olmasamda…  Surla...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/istanbul-yeniden-fetholuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Olur Çocukların Gözleri, ANNE!', 'buyuk-olur-cocuklarin-gozleri-anne-muammer-celik-bjjt3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu göl niye kıpkırmızı kesilmiş 

yoksa koyun sürüsü mü boğazlanmış 

şarapnel parcaları yollara serilmiş

ayaklarıma batıyor, anne...

Ben mi yanlışın içine düştüm 

yanlış mı benim başıma düştü! 

Yoksa sende mi gittin de, 

ben tek başıma kaldım, Anne! 

Niye sesin çıkmıyor, anne! 

Halbuki o örük örük saçların 

rüzgarda dalga dalga idi biraz önce... 

Ya babam nerde, Anne, 

elinde çoban değneği ile 

dağa çıkmıştı geçenlerde 

bu sabah taşıdılar tekrar köye

elinde mavizer, alnında kurşun yarası ile! 

Gözlerim elbette büyüdükce büyür, Halide, 

hem yağan yağmuru sel edip akıtsın diye, 

hemde görünmeyen gelecekleri iyi göreyim diye...! 

17.06.2003

BirDeli', 'Bu göl niye kıpkırmızı kesilmiş  yoksa koyun sürüsü mü boğazlanmış  şarapnel parcaları yollara serilmiş ayaklarıma batıyor, anne... Ben mi y...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/buyuk-olur-cocuklarin-gozleri-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalet Gemi', 'hayalet-gemi-burcu-karakaya-92a27', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir hayalet gemiydi, 

Sendeki demir atmış yanlızlığının, 

Ben merkezcisi...

Bu gece ayar oldum yine sana, 

Yelkenlerin fora olduğu, 

İki çıgının aşk hikayesi.

Alkolün beynini esir ettiği anda, 

Dalarsın derin okyanusuma, 

Tadarsın yudum yudum, 

Unutamadığın aşk iksirimden, 

Etkiler, iliklerine kadar işler, 

Senin olduğum gelir aklına, 

Beni de etkilersin.

Aralık bıraktığım kapımdan, 

Kafana göre rüyalarıma girersin.

Bir hayalet gemiydi, 

Kamaraları dolu.

Yaşamın içinden, 

Daha çok yaşam almak için gelen, 

Güzel renk bulamayıp ta, 

Kelebeklerimi çabucak toplamayı istemek endişen.

Bir zamanlar rüzgara karşı açtığın yelkenlerini indirip

Tekrar yelkenler fora demek, 

Acizliğe yüz tutmuş cesaretini göstermek belki

Anlamlandıramadığım

Islak rüyam...

Azgın dalgalarım sürükler, 

Hayalet gemini. 

Bildiğin ve devam ettiğin, 

Senin olan yaşamına, 

Karşı koyamazsın, çünkü

Çoştu düşlerim...

Ve benden alabileceği tek renk, 

''Sarıdır ''

Bitmiş yüreğinin...

24/09/2003

C.Burcu Karakaya

Antalya', 'Bir hayalet gemiydi,  Sendeki demir atmış yanlızlığının,  Ben merkezcisi... Bu gece ayar oldum yine sana,  Yelkenlerin fora olduğu,  İki çıg...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hayalet-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kaç Kere', 'bir-kac-kere-selim-eysioglu-ujvww', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adını anmıyorum haftalardır, 

Sadece aklıma gelirsin, günde bir kaç kere.

Bunun da nedeni hatıralardır.

Dedim ya zaten, sadece bir kaç kere.

Sokağından geçmiyorum günlerdir.

Bunun tek nedeni bıraktığın hüzünlerdir.

Sadece aklıma gelirsin, günde bir kaç yüz kere.

O da eğer, bakarsam eskimiş resimlere.

Aramıyorum seni,  yaklaşık altı aydır.

Bu şiirler, bu sevdadan, bana kalan tek paydır.

Seni sevmemek orucundayım

Ve bozamam orucumu, niyet ettim bir kere.

Sadece aklıma gelirsin artık, günde bir kaç bin kere...

Bakmıyorum gözlerine belki de senelerdir.

Bunun bütün sebepleri, benden değil sendendir.

Nadiren de olsa, hatırlıyorsam seni, bitmeyen sevgimdendir.

Sadece aklıma gelirsin, günde bir kaç milyon kere.

Ah be güzel.  Aslında: 

Sen beynimi kemiren bir düşüncesin.

Fikir çilesine denk, şiddetli bir çilesin.

Ve çıkmazsın aklımdan, günde bir kere bile.

(Eylül 2003 - Ankara)', 'Adını anmıyorum haftalardır,  Sadece aklıma gelirsin, günde bir kaç kere. Bunun da nedeni hatıralardır. Dedim ya zaten, sadece bir kaç kere....', ARRAY['Türk Edebiyatı','Şiir','Selim Eyşioğlu']::text[], 8.5, '{"poet":"Selim Eyşioğlu","poet_slug":"selim-eysioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-kac-kere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendeki Ben', 'sendeki-ben-serkan-madak-kb1me', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her gün batımında bekledim seni

Rüyamda da olsa gelirsin diye

Hayalimde kendimden sakladım seni

Olur ya bir kusurunu bulurum diye

Duyguyla mantığı kaç kez eledim

Çıkamadım içinden râb’den diledim

Daha önce bir çok aşık dinledim

Tarifleri etmezdi saç telin bile

Gözümde büyümen belki bir hiçti 

Sana bu değeri yüreğim biçti

Dostuma anlattım güldü ve geçti

Gözlerin sırata en güzel eşti

Bulmadı geceler bende sonunu 

Vermedi alimler aşk’a yorumu

Hayatın tadımı yoksa kor’umu

Senin tarifini bulamıyorum

Sustum kınadılar dediler korkak

Bilmezler ki bu can sende ve tutsak

Şimdi ya cevap ver yada not bırak

Aşk’ın dergahına sen mi son durak', 'Her gün batımında bekledim seni Rüyamda da olsa gelirsin diye Hayalimde kendimden sakladım seni Olur ya bir kusurunu bulurum diye Duyguyla m...', ARRAY['Türk Edebiyatı','Şiir','Serkan Madak']::text[], 8.5, '{"poet":"Serkan Madak","poet_slug":"serkan-madak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sendeki-ben-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılelma', 'kizilelma-orkun-isik-ks0ak', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaklaştıkca Uzaklaşıyorsun! 

Yollarına Düştüğümsün Sen  “ Kızılelma”

Düşlerde, Gönüllerde Yaşıyorsun

Ölümsüzlük Gibi, 

Düşümsün Sen  “Kızılelma”.

Ne Bir Su, Ne Bir Gül Sensizlikte Gelsede Aşka

Hiçbir Şey İstemedim, Seni Yaşamaktan  Başka

Turan Eller Hep Birden Gelecek Aşka

Sonsuzluk Kadar Uzak Ruhum Gibi, 

Yakınımsın Sen  “Kızılelma”.

Kürşad’lar Gibi Uğrunda Safa Dizildik

Anadan Babadan Yardan Geçtik

Ezildik, Bükülmedik.  Aman Dilemedik

Damarımdaki Kan Gibi, 

Geleceğimsin Sen “Kızılelma”.

Dile Gelsede Şu Çektiğim Günler

Bak Haykırıyor Artık Alperenler

Dokuz Tuğ Adına Edilen Yeminler

Gerçeğim Gibi, 

Tılsımımsın Sen “Kızılelma”.', 'Yaklaştıkca Uzaklaşıyorsun!  Yollarına Düştüğümsün Sen  “ Kızılelma” Düşlerde, Gönüllerde Yaşıyorsun Ölümsüzlük Gibi,  Düşümsün Sen  “Kızıle...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kizilelma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsiz', 'belirsiz-hakki-hakan-kaya-ppr5q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilinmeyeni sevmek gibiydi seni sevmek, 

Sadece yolu görüyorsun önünü görmeden. 

Ve bilemiyorsun yolun sonundakini, 

Ama o yolu yürürken duyduğun haz ve heyecan, 

Her adım atışında başka diyarlar, 

Başka umutlar çıkmıyormuydu karşıma, 

Sanki birden bitecek bu deli yürüyüş, 

Ve birden beyaz ışıklar içersinde sen... 

Belki bir hipnozdu bu, 

Yada sevgiye muhtaç bir yüreğin serab, ı 

Sıcaktan çatlamış bedenin suya duyduğu ihtiyacı, 

Beynin yanılmasıyla gördüğü bir hayal gibi, 

Belirsizliklerin ve bensizliklerin bir harmanı, 

Bir afrodizyak gibi beynimi uyuşturan, 

Komutların yetersiz kaldığı ve robotlaşan beden, 

Belkide bu belirsizlikti seni umarsızca sevdiren... 

Hedefte belliydi aslında, 

Birincil hedef sevgi, 

İkinci hedef sen...', 'Bilinmeyeni sevmek gibiydi seni sevmek,  Sadece yolu görüyorsun önünü görmeden.  Ve bilemiyorsun yolun sonundakini,  Ama o yolu yürürken duy...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/belirsiz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miraç Kandili', 'mirac-kandili-bekir-gedikoglu-11qck', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgili şairler, 

Kalpler vardır sevgiyi yaşatmak için

İnsanlar vardır dostluğu paylaşmak için

Şairler vardır şiirlerini okutmak için

........Ve KANDİLLER vardır rahmet dilemek için

Tekmil şairlerin kandili mübarek olsun

Ankara,24.09.2003', 'Sevgili şairler,  Kalpler vardır sevgiyi yaşatmak için İnsanlar vardır dostluğu paylaşmak için Şairler vardır şiirlerini okutmak için .........', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mirac-kandili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç', 'agac-bekir-gedikoglu-rn1hy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Penceremin önünde kocaman bir ağaç var

Sabahın soğuk yelinde dışarıda ne arar? 

Esen rüzgarda, yağan yağmurda sığınacak yer arar

Kaçmak için bir sağa bir sola sallanır

Bir daha bir daha bu işi tekrarlar

Gidemez, kaçamaz ama akşama kadar bu işi yapar

Kırılmış dalları yere doğru bakar

Ha düştüm düşeceğim diye hep yere sarkar

O ağcın acısı bir kat daha artar

...Günün birinde kırılan dalları

Çürümüş, toprak olmuş dibinde yatar

Ne ağlayanı ne koruyanı var

Yazın, kışın baltayı alan ona koşar

Gençleşsin diye kollarını budar

Yada; 

Odun yapalım diye bellerini kırar

Hiç kaybolmaz bir kötülüğün izleri

İyi bakın anlarsınız onun değerini

Kestiniz bir kuşa yuva olacak elini

Yıllar geçse bile kapanmaz oldu izleri

Bir balta vuruşta kesti hainin biri', 'Penceremin önünde kocaman bir ağaç var Sabahın soğuk yelinde dışarıda ne arar?  Esen rüzgarda, yağan yağmurda sığınacak yer arar Kaçmak için...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/agac-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erotika', 'erotika-burhan-gumus-65upg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'EROTİKA

Diliyle yaladı önce beni

Korkuyla irkildim birden

Neye uğradığımı bilemeden

Tutuşuverdi tenimin her teli

Ve sonra bir yılan kıvraklığında

Arzuyla sarmaladı bedenimi

Acı sevişmeler yürüdü kanımın her zerresine

Boğuk anlaşılmaz sesler çıkardım

Öyle ki 

Şehvetiyle inliyordu canım

Ben ben değildim artık

Dayanamıyorum. Bırakıyorum kendimi kollarına.

Ve sonra hayal - meyal hatırlıyorum

İtfaiyeciler gelmiş söndürüyorlardı

Hayırdır inşallah

Düşte kendimi böyle gördüm.', 'EROTİKA Diliyle yaladı önce beni Korkuyla irkildim birden Neye uğradığımı bilemeden Tutuşuverdi tenimin her teli Ve sonra bir yılan kıvraklı...', ARRAY['Türk Edebiyatı','Şiir','Burhan Gümüş']::text[], 8.5, '{"poet":"Burhan Gümüş","poet_slug":"burhan-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/erotika-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğraflar', 'fotograflar-oguzkan-bolukbasi-oit6o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fotoğraflar toplardım ben

İnsan fotoğrafları

Yüzlerde asılıdır

Aşkları

İhtirasları

Yalanları

Doğruları 

Sen hep o fotoğraflardaki kızdın hatırlar mısın

Yalnızdın

Ben insanları hep böyle tanıdım

Gülümsemeler zoraki mi içten mi

Hüzünlü mü

Şimdi hepsini yakıyorum

Çünkü ölümler 

En güzel bölümlerini hayatımın alıp götürüyor

Fotoğraflar acımı artırıyor

Baktıkça onlara burnumda hasret tütüyor

Yüreğimde hicran atıyor

Şimdi hepsini yakıyorum', 'Fotoğraflar toplardım ben İnsan fotoğrafları Yüzlerde asılıdır Aşkları İhtirasları Yalanları Doğruları  Sen hep o fotoğraflardaki kızdın hat...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/fotograflar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık', 'ciglik-nalan-kazazoglu-6ayqo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaçtıkça uykularım yazıyorum

Güneşin battığı yerde

Aynı ağırlık omuzlarımda

Damarlarımda anılar

Bir diken batar

Yanar yazarken avuçlarım

Bir ipliği ötekine

Beyazı karaya düğümlerim

Çöz çözebilirsen

Ben boyuna düğümlerim..', 'Kaçtıkça uykularım yazıyorum Güneşin battığı yerde Aynı ağırlık omuzlarımda Damarlarımda anılar Bir diken batar Yanar yazarken avuçlarım Bir...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ciglik-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Seninle Buluşmazsak...', 'biz-seninle-bulusmazsak-suleyman-saylan-ug13r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BİZ  SENİNLE  BULUŞMAZSAK...

Düşlerimi esir aldın, 

Duygularım sana tutsak.

Allah bile gücenecek

Biz seninle buluşmazsak.

Yıldırımlar gibi çarptın, 

Yanardağlar gibi yaktın.

Derde deva olamazsın, 

Biz seninle buluşmazsak.

Cismin sende, düşün bende, 

Benimlesin gündüz gece.

Öleceğim göre göre

Biz seninle buluşmazsak.

Yaşam sensiz haram oldu, 

Zindan oldu, dünya durdu.                

Ölmek olur en doğrusu

Biz seninle buluşmazsak.

Süleyman  SAYLAN

(Ankara,18.07.1998,  Saat: 01.30)', 'BİZ  SENİNLE  BULUŞMAZSAK... Düşlerimi esir aldın,  Duygularım sana tutsak. Allah bile gücenecek Biz seninle buluşmazsak. Yıldırımlar gibi ç...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/biz-seninle-bulusmazsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşuna Yanma.', 'bosuna-yanma-suleyman-saylan-d08yz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BOŞUNA  YANMA.

Kendini bulunmaz dünya nimeti

Sanıpta, beni de mecburum sanma.

Sevsem de bilirim “hayır” demeyi

İş işten geçince boşuna yanma.

Dertlerin derdimdi, hevesin heves, 

Seninle doluydu aldığım nefes...

Çok daraldı artık göğsümde kafes, 

İş işten geçince boşuna yanma.

Ellerin sözüne kanarak gittin, 

Çılgınca düşlerle kendinden geçtin, 

Meleği bırakıp şeytanı seçtin...

İş işten geçince boşuna yanma.

Bu hayat sensiz de yaşanır elbet, 

Sen de öğrenirsin, az daha sabret.

İnsan gibi sevmek, büyük fazilet...

İş işten geçince boşuna yanma.

Süleyman  SAYLAN

(Ankara,17.02.1994, Saat: 01.35)', 'BOŞUNA  YANMA. Kendini bulunmaz dünya nimeti Sanıpta, beni de mecburum sanma. Sevsem de bilirim “hayır” demeyi İş işten geçince boşuna yanma...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bosuna-yanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün ve Veda', 'huzun-ve-veda-hakki-hakan-kaya-dqdwm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İndi gizemi yüzümden yaşamın, 

Yılların heyecanı silindi, soldu. 

Göründü karanlığın kasvetli yüzü, 

Gündüzün güneşin vakti doldu. 

Söndü hayatın feri gözümden, 

Takvimler artık ilerlemez oldu. 

Düştü yaşamın sevinci elimden, 

Kuşlar göçtü, yağmurlar durdu. 

Şimdi beni eller üstünde taşıyın, 

Ağlamayın, alkışlayarak uğurlayın, 

Anacım gözyaşlarını akıtma sakın, 

Topraktı bu beden, yine toprak oldu.', 'İndi gizemi yüzümden yaşamın,  Yılların heyecanı silindi, soldu.  Göründü karanlığın kasvetli yüzü,  Gündüzün güneşin vakti doldu.  Söndü ha...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/huzun-ve-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Çağda Bu Kafa...', 'bu-cagda-bu-kafa-suleyman-saylan-guyxv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BU  ÇAĞDA  BU  KAFA...

Bilmem düşündünüz mü hiç

Niye geldiniz dünyaya? 

Sevindiniz mi

İyi ki dünyaya gelmişim diye? 

Kandınız mı

Sevmeye, sevilmeye? 

Uğraştınız mı mutlu olmak için? 

Çalıştınız mı

İnsanları mutlu etmeye? ...

Çok iyi niyetlisiniz

Ya da

İnsansınız diye, 

Çıktı mı adınız kerize, 

Enayiye? 

Hoş

Bu çağda bu kafa, 

Sevilmemek de caba...

Süleyman  SAYLAN

(Ankara,21.07.2001, Saat: 01.45) 

(Şiirin bütün hakları Süleyman Saylan ve varislerine aittir.)', 'BU  ÇAĞDA  BU  KAFA... Bilmem düşündünüz mü hiç Niye geldiniz dünyaya?  Sevindiniz mi İyi ki dünyaya gelmişim diye?  Kandınız mı Sevmeye, se...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-cagda-bu-kafa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Posası çıkmış şair', 'posasi-cikmis-sair-erol-sen-e2xqw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevip değer vermek senin hatan

Buldum sanıp sarıldığın sevgin yalan

Değer verip karşılık bulamamak

Yaptığın en büyük hatan

Sevgi çiçeklerini soldurdun gönlünün

Günleri geceleri haram ederek kendine

Değmeyenlere sunmakla büyük sevgini

Seni sevenleri hiçe saymak büyük hatan

Artık posasını çıkarmışsın gönlünün

Sevgini yalancı gönüllere sunarak

Yeniden yeşertmelisin sevgi tomurcuklarını

Sevgiye sırtını dönüp çekip gitmen hatan

Dönülmez akşamın ufkundayım vakit çok geç demiş şair

Dönemem kapıldım gidiyorum bahtımın rüzgarına demiş diğer bir şair

Bir başkası ben seni ellerin olasın diye mi sevdim demiş

Ben de diyorum ki rotası belli bu yolun bir avuç toprak 

Hayat sen ne çabuk harcadın beni belki de diğer bir başlık.....

24.09.03', 'Sevip değer vermek senin hatan Buldum sanıp sarıldığın sevgin yalan Değer verip karşılık bulamamak Yaptığın en büyük hatan Sevgi çiçeklerini...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/posasi-cikmis-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvaklar İçinde... (Bir Damla Gözyaşı...)', 'duvaklar-i-cinde-bir-damla-gozyasi-suleyman-saylan-k4tlm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'DUVAKLAR  İÇİNDE...  (BİR  DAMLA  GÖZYAŞI...) 

Duvaklar içinde gelin olmuşsun, 

Davullar çalıyor düğün evinden.

Anladım, artık sen elin olmuşsun, 

Bir damla gözyaşı aktı gözümden.

Elveda demeden çekip giderken, 

Ayrılık kor olup, yaktı peşinden, 

Ağlarım sanmıştım pınarlar gibi

Bir damla gözyaşı aktı gözümden.

Rüzgarın önünde yelken açmışım, 

Sana ben yıllarca boşa kanmışım, 

Yanında derbeder, perişanmışım, 

Bir damla gözyaşı aktı gözümden.

Seninle beyhude geçen yılların, 

Sana değer sanıp akan yaşların

Katresi harammış şimdi anladım.

Bir damla gözyaşı aktı gözümden.

Geriye dönsen de artık nafile, 

Yerini boşalttım seven kalbimde, 

Perişan perişan ağlarken bile

Bir damla gözyaşı aktı gözümden.

     Süleyman SAYLAN

     (Ankara,14.09.1996, Saat: 01.20) 

Şarkı sözü olarak yazılmıştır.', 'DUVAKLAR  İÇİNDE...  (BİR  DAMLA  GÖZYAŞI...)  Duvaklar içinde gelin olmuşsun,  Davullar çalıyor düğün evinden. Anladım, artık sen elin olmu...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/duvaklar-icinde-bir-damla-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimize Vuruyor Sıcak!', 'i-cimize-vuruyor-sicak-naime-erlacin-57rr8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'soluyor akasya düşler

ağlayarak kuruyor ilk yaprak 

hüzün kaynıyor kanımızda

zifir akşamlarda geceye asılıyor tozlu hayaller 

acı bir rüzgar savruluyor potasında beynin

çölleşiyor yaşam giderayak

yeniden sorguluyoruz hayatı 

günahları bizde gizli gök kubbenin 

sıkı sahiplenin ateşinizi ey tanrılar! 

varoluş doğurganlığında taptaze bir diriliş isteriz 

ve kendimizde rehin kaldık 

bunca köprüyü yıkarak

fidye ödenmeyecek! 

önce ölüm 

sonra dirim

çekilecek bu ip 

kan asi 

yürek ahraz

kanımız koyu 

kanımız buz

içimize vuruyor sıcak! 

(24 Eylül 2003)', 'soluyor akasya düşler ağlayarak kuruyor ilk yaprak  hüzün kaynıyor kanımızda zifir akşamlarda geceye asılıyor tozlu hayaller  acı bir rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/icimize-vuruyor-sicak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkasın', 'baskasin-hakki-hakan-kaya-15jnu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başka gözlerle bakma bana, 

Sen gözlerimde başkasın.

Başkaları başka yerde, 

Sense BAMBAŞKASIN...', 'Başka gözlerle bakma bana,  Sen gözlerimde başkasın. Başkaları başka yerde,  Sense BAMBAŞKASIN......', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/baskasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alkış Bekliyorum Sizden; Lütfen!', 'alkis-bekliyorum-sizden-lutfen-mine-ozdemirtas-ju6u2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sizden; 

Alkış rica ediyorum.

Ayakta.

Fonda; 

En güzeli olmalı şarkıların.

Sazların ise; en ustası.

Yerde; Gül yaprakları, 

Ve kadehimde şampanya.

Bir türlü gelmeyen yarınlar var ya! ! ! ! 

İşte; O yarınlara, 

Yaşamayı hep ertelediklerimiz var ya! ! ! ! 

İşte;  O anlara, 

“Yeni aşk, eskisinden büyük olur” derler ya! ! ! ! 

İşte; O aşka

Sizden alkış, 

Benden ise; 

MERHABA

23/09/2003', 'Sizden;  Alkış rica ediyorum. Ayakta. Fonda;  En güzeli olmalı şarkıların. Sazların ise; en ustası. Yerde; Gül yaprakları,  Ve kadehimde şam...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/alkis-bekliyorum-sizden-lutfen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özetle; Hazırım İşte,', 'ozetle-hazirim-i-ste-mine-ozdemirtas-wnrz5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdanın, dolu dizgin at koştuğu o yerde; 

Bir yıldız kaydı az önce. Sessizce.

İki damla göz yaşı; peş peşe, 

Düştü önüme.

Birini düne saydım, birini de bu güne

Düşemeyen damlayı ise; 

Saklıyorum. Yarına kalsın diye.

Kazananı olmayan bir kavgaydı. Bitti.

Yenilen pehlivan güreşe doymazmış

Yeni aşka, yeni güne

Özetle

Hazırım işte.

23/09/2003 çamlıca', 'Sevdanın, dolu dizgin at koştuğu o yerde;  Bir yıldız kaydı az önce. Sessizce. İki damla göz yaşı; peş peşe,  Düştü önüme. Birini düne saydı...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozetle-hazirim-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarının Adresi Dünden Sorulur', 'yarinin-adresi-dunden-sorulur-i-brahim-bayraktar-72g1z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yarının adresi dünden sorulur,

Geçmişi kirletip, gelme yarına,

Küçük bir oy, bir iktidar uğruna,

Koca bir lekeyi sürme alnına.

Ahvaliniz kötü, ruhumuz ince,

Boş vaatlerle çıkmayın karşıma,

Sandığın ucu popona değince,

Nışadır sürülmüş gibi zıplama.

Esamimizi anıp arada bir,

Çantada keklik mi sanırsın bizi? 

Entrikalar, tezgâhlar dizi dizi,

Kolaysa Sıratı kazasız geçir.

Sade vatandaş, sadece bireyiz,

Bilesiniz ki, sandıkta bir reyiz,

Köleysen vatandaştan gayrisine,

O zaman biz, sizin için fireyiz.

24.09.2003/Ankara', 'Yarının adresi dünden sorulur, Geçmişi kirletip, gelme yarına, Küçük bir oy, bir iktidar uğruna, Koca bir lekeyi sürme alnına. Ahvaliniz köt...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yarinin-adresi-dunden-sorulur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü Yaktım Gözlerine', 'turku-yaktim-gozlerine-esma-ozdemir-e37n5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bak, türkü yaktım gözlerine!;

Kınası, ellerimde

Yeşili gözlerimde

Buğusu, dilimde

Dumanı, başımda

Ateşi, ta içimde kaldı!

Anlıyor musun beni? 

Biliyor musun

Nasıl yaşadığımı seni? 

Görüyor musun gözlerimde

Gözlerini?', 'Bak, türkü yaktım gözlerine!; Kınası, ellerimde Yeşili gözlerimde Buğusu, dilimde Dumanı, başımda Ateşi, ta içimde kaldı! Anlıyor musun beni...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/turku-yaktim-gozlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Işıkları', 'gecenin-isiklari-i-smail-haki-simsek-539hy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gölgelerden korkuyorum

Sönsün

Gecenin ışıkları

Ki görebileyim

Ki seçebileyim aşkını

Sabah olmadan', 'Gölgelerden korkuyorum Sönsün Gecenin ışıkları Ki görebileyim Ki seçebileyim aşkını Sabah olmadan...', ARRAY['Türk Edebiyatı','Şiir','İsmail Haki Şimşek']::text[], 8.5, '{"poet":"İsmail Haki Şimşek","poet_slug":"i-smail-haki-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gecenin-isiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-bekir-gedikoglu-szgdy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Işıksız kapının arkası karanlık

Susuz ağaçlarda olmaz canlılık

Baharın ilk müjdesini veriyor arılık

Tozlu yolların hepsi de bulanık

Sensiz hayata küstüm ebedi olarak

Güneşsiz çiçek açar mı hiç solmayarak

Mevsimin getirdiği sessizliğe bakarak

Yalnızlığımı hatırladım şimdi ağlayarak

Çamurlu akan sular bir gün durulur

Bu dertli alemde ne ararsan bulunur

Sevgiliden ne kadar uzaksan insan yorulur 

Aşkı talep eden elbette bulur

Şu bir günlük dünyada gel dost olalım

Mutluluk yuvasını beraber kuralım 

Bülbüllerin sesinde, kuşların cıvıltısında

Göz göze diz dize kucak kucağa kalalım', 'Işıksız kapının arkası karanlık Susuz ağaçlarda olmaz canlılık Baharın ilk müjdesini veriyor arılık Tozlu yolların hepsi de bulanık Sensiz h...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgilim-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sar', 'sar-melek-midikoglu-852or', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son yapraklarını bırak

Dökülmesin ne olur

Bitmesin bu şarkımız

Dinmesin ateşimiz

İlkbaharda yeşeren

Sonbaharda boy veren

Kışın da serinleyen

Aşkım sana kanmasın

Son yapraklarını bırak

Dökülmesin ne olur

Bitmesin bu şarkımız

Dinmesin ateşimiz

Son yapraklarını bırak

Son yapraklarını bırak', 'Son yapraklarını bırak Dökülmesin ne olur Bitmesin bu şarkımız Dinmesin ateşimiz İlkbaharda yeşeren Sonbaharda boy veren Kışın da serinleyen...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Yâr Bil ki*+', 'hey-y-r-bil-ki-bayram-tunca-7ymi4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimdeki sevgi meşalen hiç sönmeyecek

Bunu senden başka hiç kimse görmeyecek

Meşalemiz sönmedikçe, aşkımız ölmeyecek

Değerlerine benden başkası el sürmeyecek

24.09.2003-09:24', 'Kalbimdeki sevgi meşalen hiç sönmeyecek Bunu senden başka hiç kimse görmeyecek Meşalemiz sönmedikçe, aşkımız ölmeyecek Değerlerine benden ba...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hey-yar-bil-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Seni de', 'seni-de-melek-midikoglu-ngd4y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denizlerin dalgaları 

Dökülse üzerime

Tonlarca ağırlık verse

Seni de  diye 

Sayıklar kalbim..

Alsam üzerime

Nefes olursun

Isı olursun

Üşümem hiç

Soğuktan ölsemde', 'Denizlerin dalgaları  Dökülse üzerime Tonlarca ağırlık verse Seni de  diye  Sayıklar kalbim.. Alsam üzerime Nefes olursun Isı olursun Üşümem...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim', 'hasretim-abdulkadir-karaman-p05jt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana olan özlemim aşılmaz dağlar gibi 

Mümkün değil varamam, aramız çağlar gibi. 

Nafile bekle deme, beklemeye halim yok

Sensizliği çekmeye anla, hiç mecâlim yok.

Kangren gibi derdim, kimselere diyemem 

Tıkandı çıkış yolum, hiç bir yere gidemem. 

Senden gelen derdimi yine sana açarım 

Anla, ne olur anla perişanım, naçarım.

Hayâlin kâfi gelmez ruhumu teselliye 

Kimse de yardım etmez deli diye bu deliye. 

Zaman geçmez, sevgisiz zamanlarda ne yapsam

Yüreğime dolarsın gözlerimi kapatsam.

Yalvarıyorum sana uzanan elimi tut 

Ölümümü iste tek, ne olur deme unut. 

Mümkün değil unutmak, şu andan sonra seni

Sensizliğe hükümlü etme ne olur beni.

Düşlerim sana mahkum, hayalim esir sana

Merhamet, cezâ verme, sensizliğe mahkuma.', 'Sana olan özlemim aşılmaz dağlar gibi  Mümkün değil varamam, aramız çağlar gibi.  Nafile bekle deme, beklemeye halim yok Sensizliği çekmeye ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hasretim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin (1)', 'yemin-1-vedat-didari-4cyd8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne ıslıklarımızda tutsak ayrılık şarkıları

Ne her gün batımı değişen karanfil vazolarımızda

Ne de en güzel şiirler dilimizden düşürmediğimiz

artık biz değiliz

en çılgınları bu kentin

en çok sevenleri biz değiliz

Zaman, ele avuca gelmez bir bomba tıkır tıkır

Zaman, omuzlarımıza basa basa yürüyen bir dev

Nerede o eski parıltı, nerede o eski alev? 

Şimdi apacı yılgınlıklarla doludur gözlerimiz

    

 o en çocuk sevinçlerimiz

 gömülü bir yağmurlu gecede 

 ve bütün gençliğimiz

Şimdi ne bir erkek döner bakar senin ardından

Ne bir kadın yanıtlar benim bakışlarımı

Tenimizde yılların korkunç birikintisi 

O çoktandır yitirdiğimiz arzu yaşamakta

Beden güçsüz, gönül ihtiyarlamakta

Örümcek ağlarını süslemekte ümitlerimiz

       

artık biz değiliz

en çılgınları bu kentin

en çok sevenleri biz değiliz

Yemin, pas tutmuş bir anahtar gönül kapılarımızda

Yemin, istesek te bozamayacağımız bir kutsal büyü

Şimdi anımsamak bile güç o eşsiz türküyü

Artık topraklarımız çorak bizim nehirlerimiz susuz

Ve hala ikimiz de uykususuz 

Ve hala mahkûmuz birbirimize

       

 o en içten sevinçlerimize

 mezardır bir yağmurlu gece

 ve bütün gençliğimize', 'Ne ıslıklarımızda tutsak ayrılık şarkıları Ne her gün batımı değişen karanfil vazolarımızda Ne de en güzel şiirler dilimizden düşürmediğimiz...', ARRAY['Türk Edebiyatı','Şiir','Vedat Didari']::text[], 8.5, '{"poet":"Vedat Didari","poet_slug":"vedat-didari","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yemin-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Bulamadım', 'gul-bulamadim-murat-demir-orzjg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Döndüm sağa sola, bağda bahçede

Konaklar yaptırdım, ilde ilçede

Toz ettim yolları, her gün her yerde

Tutup koklanacak gül bulamadım 

Dereden tepeden, dağları aştım

Düştüm çöl içine, kuyular eştim

Ne güzeller gördüm, ne yerler geçtim

Gönlümü koyacak, yer bulamadım

Turnalara baktım, yellere sordum

Güneşte eridim, buzlarda dondum

Ateşler içine, başımı koydum

İçimi yakacak, kor bulamadım

Laleler okşadım, çiçekler dizdim

Krallar tanıdım, zındanlar gezdim

Ömrümü tükettim, canımdan bezdim

Yürekten sevecek, yar bulamadım', 'Döndüm sağa sola, bağda bahçede Konaklar yaptırdım, ilde ilçede Toz ettim yolları, her gün her yerde Tutup koklanacak gül bulamadım  Dereden...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-bulamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin (2)', 'yemin-2-vedat-didari-c9tst', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kura kura eskitemediğimiz hatıralar

Ne ıstırabın verdiği o yüce gurur

Ne de en pahalı avuntuları İstanbul''un

Artık bitmiştir bu anlamsız kumar

Kaybettikçe oynadığımız bu garip oyun

Sevmek, yine de sevmek, daha da sevmek

Tiryakisi olduğumuz bu şahane azap

Bu en güzel zehir, bir türlü kanamadığımız

Ben alabildiğine çılgın bir genç adam

Sen o gün batımı, doyulmaz güzel kız

Tüm evrene kör, geçip giden yıllarımız

      

 lakin dinlemez oldu geçmişin sesini

 artık yitirdi gönül tüm tesellisini

Bu ebedi yalnızlığın mahkûmu döşek

Bu kapı bu pencereler, bu duvarlar

Geceler en yalan yerlerinde böler uykularımızı

Bir sıcak nehir yanaklarımızdan akar

Ve çehrelerimize düşmanca bakar

Aynalar...geceleri...aynalar

Sen nazarlarında en eski özlemleri büyüten

Bilmem hangi asırdan kalma sarışın kadın

Gözlerin bir kirli yeşil, saçların darmadağın

Ve alkole doyamayan, yaşlı bir serseri ben

Nedensiz, başıboş, sorumsuz bir ruhun

Oyuncağı olmuş, günden güne tükenen

Bu şekilsiz, bu anlamsız, bu zavallı beden

Artık bir acısız bitiştir tutkuyla beklenen

        

doğmuşuz, tanışmışız 

ve sevmişiz birbirimizi

bir yağmurlu gecede bize sormadan 

kaldırıp gitmişler cenazemizi

bundan ötesi yok zaten yaşamlarımızın', 'Ne kura kura eskitemediğimiz hatıralar Ne ıstırabın verdiği o yüce gurur Ne de en pahalı avuntuları İstanbul''un Artık bitmiştir bu anlamsız ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Didari']::text[], 8.5, '{"poet":"Vedat Didari","poet_slug":"vedat-didari","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yemin-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evvel Zaman İçinde', 'evvel-zaman-i-cinde-bekir-mutlu-gokcesu-tekid', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimden bir tramvay geçti

Beni tam ortamdan ikiye biçti

Bir yarım nostalji, diğer yarım da nostalji

Daha önceleri nerelerdeydin ey teknoloji

Evvel zaman içinde kalmışım ben

Yani hala bıraktığın yerde

Yaslandığımız o ağacın dibinde

Sana yazıp, okuduğum o dört dizede

O gün kafa kafaya verip çektirdiğimiz

“İstanbul Hatırası” siyah beyaz resimde', 'İçimden bir tramvay geçti Beni tam ortamdan ikiye biçti Bir yarım nostalji, diğer yarım da nostalji Daha önceleri nerelerdeydin ey teknoloji...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/evvel-zaman-icinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Oldun mu Sandın?', 'adam-oldun-mu-sandin-suleyman-saylan-e4ohb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ADAM OLDUN MU SANDIN? 

Kuru sıkı bir tüfek gibi patladın, 

Kabak çiçeği gibi çok erken açtın.

Sen zaten gösterişe, şöhrete açtın...

Senin burnun büyüdü birden, aniden, 

Adam oldun mu sandın? Daha çok erken.

Düne kadar herkesle düşüp kalkarken

Üçtü, beşti demeden takla atarken; 

Kökenleri olmayan bir çiçektin sen...

Senin burnun büyüdü birden, aniden, 

Adam oldun mu sandın? Daha çok erken.

İsterik kahkahalar atar dururdun, 

Baygın bakıp süzerek, avları vururdun.

Hayal kurar, düş görür, zengin olurdun...

(Şöhret için kudurur, çılgın olurdun...)  

Senin burnun büyüdü birden, aniden, 

Adam oldun mu sandın? Daha çok erken.

Ne çabuk da unuttun, o günlerini, 

Dolaşırdın damgalı, kötü pul gibi.

Bir kenar mahallenin sürtük dilberi...

Senin burnun büyüdü birden, aniden, 

Adam oldun mu sandın? Daha çok erken.

Adını söyleyemem, sana (o)     derler; 

Güzelliğin durdukça seni isterler, 

Pörsüyüp dökülünce, çiğner geçerler...

Senin burnun büyüdü birden, aniden, 

Adam oldun mu sandın? Daha çok erken.

Süleyman SAYLAN

Ankara,18.02.1994, Saat: 22.20', 'ADAM OLDUN MU SANDIN?  Kuru sıkı bir tüfek gibi patladın,  Kabak çiçeği gibi çok erken açtın. Sen zaten gösterişe, şöhrete açtın... Senin bu...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/adam-oldun-mu-sandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamaz Görünme...', 'anlamaz-gorunme-suleyman-saylan-k8fp7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ANLAMAZ  GÖRÜNME...

Yüreğimde coşan sevginin seli, 

Başımda esişen kavak yelleri, 

İçimi kanatan yaban gülleri

Anlamaz görünme sensin biricik.

Yorulan yüreğim sensiz olmasın, 

Sevgi ırmaklarım susuz kalmasın, 

Aktığım her yerde inan sen varsın

Anlamaz görünme sensin biricik.

Başımda esen bu kavak yelleri, 

Sevdamı anlatan sazın telleri, 

Karanlık gecemde gözlerin feri

Anlamaz görünme sensin biricik.

İçimi kanatan yaban gülleri, 

Yaban güllerinin batan dikeni, 

Yorgun gönlümdeki bülbülün sesi

Anlamaz görünme sensin biricik.

Yüreğimde coşan sevginin seli, 

Göklere uçuran hortumun yeli, 

Bana öğretensin içten gülmeyi

Anlamaz görünme sensin biricik.

Süleyman SAYLAN

(Ankara,19.12.2001, Saat: 01.43)', 'ANLAMAZ  GÖRÜNME... Yüreğimde coşan sevginin seli,  Başımda esişen kavak yelleri,  İçimi kanatan yaban gülleri Anlamaz görünme sensin birici...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anlamaz-gorunme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanım', 'pismanim-numan-yapa-tafy5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dönüşü olmayan bir yola girdim

Bilmem ki ne etsem bu garip handa

Dedim ya dönüşü olmayan bir yola girdim

Dışarıda herşey gül gülistan olsa da

İçimde zakkumlar açıyor gül bahçesinde

Atiyi göremez oldum 

Bilmem ki ne etsem bu garip handa 

Dedim ya dönüşü olmayan bir yola girdim

Ağlasam ne fayda kimse duymaz sesimi

Görmezler gözümden akan kanları

Bilmem ki ne etsem bu garip handa

Dedim ya dönüşü olmayan bir yola girdim', 'Dönüşü olmayan bir yola girdim Bilmem ki ne etsem bu garip handa Dedim ya dönüşü olmayan bir yola girdim Dışarıda herşey gül gülistan olsa d...', ARRAY['Türk Edebiyatı','Şiir','Numan Yapa']::text[], 8.5, '{"poet":"Numan Yapa","poet_slug":"numan-yapa","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/pismanim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tren Gitti', 'tren-gitti-kader-demir-x5bk1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tren gitti! 

Kaçırdık az öncekini de...

Dumanlarını üfleyerek, sigara tiryakileri gibi, 

İzin vererek mendil sallamalarına ayrılanların, 

Yavaş yavaş hızlanarak, gitti! ..

Bu son “ tren” di...

Son ayrılık ve son şansımız, 

Yazık! 

Gitti!', 'Tren gitti!  Kaçırdık az öncekini de... Dumanlarını üfleyerek, sigara tiryakileri gibi,  İzin vererek mendil sallamalarına ayrılanların,  Ya...', ARRAY['Türk Edebiyatı','Şiir','Kader Demir']::text[], 8.5, '{"poet":"Kader Demir","poet_slug":"kader-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tren-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsız Kaldı', 'anlamsiz-kaldi-suleyman-saylan-jftav', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ANLAMSIZ  KALDI

Oturup saydım da geceler boyu, 

Ömrümde yaşanan üç, beş gün vardı.

Göründü bak artık ömrümün sonu

Beyhude...  Yaşamak anlamsız kaldı.

Mutluyum diyemem, mutsuz hiç değil, 

Duygular başıboş, yüreğim sefil.

Sevgisiz sevdaya olamam kefil...

Beyhude...  Yaşamak anlamsız kaldı.

İçince yazılan sahte şiirler, 

Çıldırır yüreğim, sevdasız inler.

Paran yoksa seni züğürtler dinler...

Beyhude...  Yaşamak anlamsız kaldı.

İnsanlar aşkını sattı parayla, 

Kör, topal demedi, akla, karayla, 

Yaşlısı genciyle yattı sırayla...

Beyhude...  Yaşamak anlamsız kaldı.

Çarpık, yüreklerin düzeni çarpık, 

Ardamarı çatlak, yüzleri yırtık.

Sevgiyi boş verip paraya taptık...

Beyhude...  Yaşamak anlamsız kaldı.

Süleyman SAYLAN

(Denizli (Mantar restoran) ,10.09.1994, Saat: 22.00)', 'ANLAMSIZ  KALDI Oturup saydım da geceler boyu,  Ömrümde yaşanan üç, beş gün vardı. Göründü bak artık ömrümün sonu Beyhude...  Yaşamak anlams...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anlamsiz-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çamsakızı', 'camsakizi-ahmet-kose-wlo33', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dilim bağlandı

gözümdeyken ruhun

Yüreğim bağlandı

gözümdeyken sesin

Perdeyi kapattım

bulantısında yaşamın.

Sabah oldun kırkımda

yüreğime açtın

Güneş oldun 

dilimi yaktın

Ay oldun

gözüme kaçtın

hangi çoban armağan etti seni bana kuzum..! 

15/16/haz.Bitez/03', 'Dilim bağlandı gözümdeyken ruhun Yüreğim bağlandı gözümdeyken sesin Perdeyi kapattım bulantısında yaşamın. Sabah oldun kırkımda yüreğime açt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/camsakizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevdam', 'kara-sevdam-mehmet-ali-cibikli-w4jiu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duygularım sen yüklü, 

Hep sen yağdın  gönlüme.

Bir ömürsün yavrum sen, 

Ömür kattın ömrüme.

Yaşam sensin bitanem, 

Yaşam seninle güzel.

Mutluluk bize yakın, 

Onu yaşayalım gel.

Bu ömür feda olsun, 

İşte senin uğruna.

Seni çok seviyorum, 

Ölürüm bak yoluna.

Mezar taşıma sonra, 

Her gün gelir ağlarsın.

Ağlamak yetmezse de, 

Karaları bağlarsın.

Siyah rengi hiç sevmem, 

Hele kara toprağı.

Mutluluğu bulalım, 

Bitir şu ayrılığı.', 'Duygularım sen yüklü,  Hep sen yağdın  gönlüme. Bir ömürsün yavrum sen,  Ömür kattın ömrüme. Yaşam sensin bitanem,  Yaşam seninle güzel. Mut...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kara-sevdam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-i-brahim-tolga-ozsoy-tq5y1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bunların hangisisin sen? 

Hangisiydim ben? 

Seçemiyorum bu kadar uzaktan.

Belki de hiçbiri değiliz artık.

Fakat onlar ''Ben'' olduklarının farkında baştan.

Peki sen? 

''Biz'' olduğunun farkında mısın? 

Onlar değiller.

Onlar beni ''Ben'', 

Seni de ''Sen'' sanıyorlar ta baştan.

Onlardan bendeki seni gizliyorum

Bir biz var ki bende 

Onu bir ben yaşıyorum 

Bir sana yaşatıyorum

Üzerine bir tutam yalnızlık katıyorum, 

Boş zamanları dolduran.

Dağınık odamın ışığında, 

Gözlerimden akanları biriktiriyorum

Her ayrılışta onları seninle paylaşıyorum.', 'Bunların hangisisin sen?  Hangisiydim ben?  Seçemiyorum bu kadar uzaktan. Belki de hiçbiri değiliz artık. Fakat onlar ''Ben'' olduklarının far...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tolga Özsoy']::text[], 8.5, '{"poet":"İbrahim Tolga Özsoy","poet_slug":"i-brahim-tolga-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-ve-ben-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorsun', 'seviyorsun-mehmet-ali-cibikli-x42m2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözler yalan söylemezse, 

Bil ki beni seviyorsun.

Sözler yalan söylemezse, 

Belki beni seviyorsun.

Bakışların alev gibi, 

Yaktı birden yüreğimi, 

Haykır bana sevdiğini, 

Sen ki beni seviyorsun.

O gülüşler, o gülüşler, 

Gece gündüz içimdeler, 

Bana birşeyler söylerler, 

Sanki beni seviyorsun.', 'Gözler yalan söylemezse,  Bil ki beni seviyorsun. Sözler yalan söylemezse,  Belki beni seviyorsun. Bakışların alev gibi,  Yaktı birden yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seviyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kor Düşmüş Gönlüme', 'bir-kor-dusmus-gonlume-mehmet-ali-cibikli-967s0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kor düşmüş gönlüme, 

Sevmişim seni birden.

Nasıl çıktın önüme, 

Ayrılamam ben senden.

Şu küçücük yüreğim, 

Senin için çarpıyor.

Sana olan hasretim, 

Günden güne artıyor.

Ben hep seni düşündüm, 

Gece gündüz demeden.

Yokluğunda üzüldüm, 

Hoşlanıyorum senden.

Severim deli gibi, 

Sen de beni seversen.

Anlarsın şu sevgimi, 

Birazcık beni sevsen.', 'Bir kor düşmüş gönlüme,  Sevmişim seni birden. Nasıl çıktın önüme,  Ayrılamam ben senden. Şu küçücük yüreğim,  Senin için çarpıyor. Sana ola...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-kor-dusmus-gonlume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Aşksın', 'sen-asksin-salih-ozalasan-lgn3r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen aşksın yaşanacak yüreklerde

Sen cansın atacak sinelerde

Sen kansın akan damardan kalbe

Seninle hayat ne kadar güzel

Sen bülbülün sevdasını çektiği

Sen Şirin'' sin Ferhat'' ın dağlar deldiği

Sen benimsin tanrımın bana lûtfettiği

Seni senden çok sevmek ne kadar güzel

Sen gözlerimde fersin parlayan

Sen ahu gözlü ceylan ruhumu okşayan

Sen öldüğümde makber, sağlığımda aşiyan

Senin kollarında olmak ne kadar güzel

Sen sevdasın yüreklere hayat veren

Sen pınarsın kara sevda olur seni içen

Sen baharsın kışlar silinir her takvimden

Seninle hayat bir ömre bedel

Y.Tarihi 24-09-2003 Saat 19,14

Salih Özalaşan', 'Sen aşksın yaşanacak yüreklerde Sen cansın atacak sinelerde Sen kansın akan damardan kalbe Seninle hayat ne kadar güzel Sen bülbülün sevdası...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-asksin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Ayrılmadık', 'hic-ayrilmadik-burhan-gumus-lwqyz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'HİÇ AYRILMADIK

Bir gölge gibi hiç yanımdan ayrılmadı

Taaki onu ilk tanıdığımdan beri

Öyle ki odalardan odalara koşuştuk

Kırlarda sokaklarda yürüdük

Saklambaç oynadık çoğu kez

Ağladığımda, güldüğümde hep o vardı yanımda

Okula gittik

İlk defa deftere onun adını yazdım

Okumayı öğrendiğimde onu daha çok sevdim

Gençliğimin zapt edilmez azgınlığında

Beni hep o frenledi

Sevmeyi sevilmeyi 

Hayatı öğretti bana

Çoluk çocuğa karıştığımda 

Yüreğime şefkati

Omuzlarıma emaneti yükledi

Acıyı sevinci yaşattı bana

İnsanlara, hayvanlara

Doğaya karşı 

Nasıl davranacağımı söyledi

İhtiyarladığımda  da bana  destek oldu

İlk günkü gibi hep beraber olduk

Hiç ayrılmadık

Taaki son nefeste 

Can tenden ayrıldı 

O baki kaldı', 'HİÇ AYRILMADIK Bir gölge gibi hiç yanımdan ayrılmadı Taaki onu ilk tanıdığımdan beri Öyle ki odalardan odalara koşuştuk Kırlarda sokaklarda ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Gümüş']::text[], 8.5, '{"poet":"Burhan Gümüş","poet_slug":"burhan-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hic-ayrilmadik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizi Gördüğüm An', 'sizi-gordugum-an-burhan-gumus-p7jux', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SİZİ ÖRDÜĞÜM AN

Ayaklarım gitmiyordu isyan edercesine

Ellerim felç olmuştu

Titriyordum sıtma nöbetine yakalanmışçasına

Başım dönüyordu

İpnotizma edilmiştim adeta

Ve sonra 

Bir kuğu gibi geçtiniz yanımdan

Gözlerim yapışmıştı sanki

Bilmiyorum ne kadar kaldım öyle

Ayaklarım çözüldü

Ellerim boşaldı

Titremiyordum artık

Başımda dönmüyordu 

Fakat içim yanıyordu

Güneşi yutmuşçasına.', 'SİZİ ÖRDÜĞÜM AN Ayaklarım gitmiyordu isyan edercesine Ellerim felç olmuştu Titriyordum sıtma nöbetine yakalanmışçasına Başım dönüyordu İpnot...', ARRAY['Türk Edebiyatı','Şiir','Burhan Gümüş']::text[], 8.5, '{"poet":"Burhan Gümüş","poet_slug":"burhan-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sizi-gordugum-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hemsire', 'hemsire-erkan-uyar-ew0ec', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni gorur gormez acile geldim

derbeder adimi sicile geldim

bitmeyen derdimi tecile geldim

yara bende care sende hemsire

kahrim cekilecek cileme dolgu

yegane ilac; ask, emsalsiz bulgu

anamdan dogali bahtdenen olgu 

kara bende care sende hemsire

anlatsam ustune usteligini...

bak iste, konustur ustaligini

dunyanin en vehim hastaligini 

ara bende care sende hemsire

al beni kalbine yogun bakmaya

sevginden bir yudum serum takmaya

sicacik elinle basla yakmaya

cira ben de care sende hemsire

halime ayandir sevda cekenler 

bir gulu tutunca batar dikenler 

sana bakiyorken butun yelkenler 

fora bende care sende hemsire

sevk edemem subatina martina 

imzami atarim her bir sartina

yoklugun felaket askin firtina

bora bende care sende hemsire

saclarin arttirdi gonul agrimi 

dudaklarin atesledi sagrimi

bakislarin nester yirtti bagrimi

nara bende care sende hemsire

cemalin dondurdu beni amaya

nacizane aklim girdi komaya

cenazemi kaldirsinlar cumaya

sira bende care sende hemsire

                               DERBEDER/2003', 'Seni gorur gormez acile geldim derbeder adimi sicile geldim bitmeyen derdimi tecile geldim yara bende care sende hemsire kahrim cekilecek ci...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uyar']::text[], 8.5, '{"poet":"Erkan Uyar","poet_slug":"erkan-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hemsire-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanak', 'dayanak-hatice-ari-s847p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden kırkağaç kesildiniz, 

Dar günümde dost bildiğim, 

Tutunduğum ince dallar? 

Gölgesinde gönül serdiğim, 

Bir esintide kendimden geçtiğim, 

Ben mi çok narindim, 

Uzandığım masum eller? 

Hani, sanki

Üzerinden epey geçti

Ağladığım anlar, 

Sanma, kirpik kıyılarım yalnız

Dalgalar, 

Ah, yüreğimin teknesine çarpar; 

Taşar, taşar...

Bil ki, hasret kıyıları, 

Yarin dudaklarını yıkar, 

Ve sıcacık gözyaşlarım

Damlar damlar...

Yoksa, 

Sen de mi incindin

Benim içimde? 

Öyle apansız ki anlar, 

Bir de bakmışsın

Dibe vurmuşum; 

Kendi teknemde, 

Hem de 

O biçimde...', 'Neden kırkağaç kesildiniz,  Dar günümde dost bildiğim,  Tutunduğum ince dallar?  Gölgesinde gönül serdiğim,  Bir esintide kendimden geçtiğim...', ARRAY['Türk Edebiyatı','Şiir','Hatice Arı']::text[], 8.5, '{"poet":"Hatice Arı","poet_slug":"hatice-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dayanak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-hatice-ari-0g9ba', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu nasıl  bir çiledir; 

Tarümar olur ömrüm de hasat vermez? 

Harman yeli gibi yüzümü sıvazlar, 

Yar, hasretin ince bir kesik olmuş; 

Ne yöne dönsem, sızlar içim..

Bu ne biçim adalettir ey kader? 

Ses etmedimse de onca vakit, 

Artık bir yere dek; 

Ne biçim bir hiledir

Yaptığın? 

Bilmez misin, 

Acılar, yalnız aşılmaz; 

Aşılırsa, 

Adı, paylaşım olmaz!', 'Bu nasıl  bir çiledir;  Tarümar olur ömrüm de hasat vermez?  Harman yeli gibi yüzümü sıvazlar,  Yar, hasretin ince bir kesik olmuş;  Ne yöne...', ARRAY['Türk Edebiyatı','Şiir','Hatice Arı']::text[], 8.5, '{"poet":"Hatice Arı","poet_slug":"hatice-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/isyan-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanayım', 'yanayim-ahmet-kose-up1bv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '...mavi ince kıza

Suları yaktım 

donların üstünde

Işığın yanar 

buzların üstünde

erir giderim.

Ben deniz feneri

neredeysen

oraya yanayım.

12/13/haz./03-bitez', '...mavi ince kıza Suları yaktım  donların üstünde Işığın yanar  buzların üstünde erir giderim. Ben deniz feneri neredeysen oraya yanayım. 12...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yanayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama... Ne hoş insandın sen', 'babama-ne-hos-insandin-sen-ahmet-kose-lp0qh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine işten güçten

olur olmaz şeylerden

insanların hatalarından

tapınamadım bugün

konuşamadım tanrıyla.

Geldim senin yanına

yaktım sigaramı

bir sana 

bir dünyaya baktım.

Seni gördüm

sen dünyaymışsın meğer

sevdiğim...sevdiğim

dostlarımla birlikteydim

ama sen hep önümdeydin.

Ay geldi şimdi.

Sular saçların tarar gibi

salındıda salındı saçların

aya baktım

suya değmiş

Ay Su olmuşlar

Biz yakamoz olduk demişler.

Ay var

Su var

Yakamoz var

Sende varsın aslında

Yakamozun içinde

BABA.                     

11/12/TEM/cuma/Kadıkalesi/03', 'Yine işten güçten olur olmaz şeylerden insanların hatalarından tapınamadım bugün konuşamadım tanrıyla. Geldim senin yanına yaktım sigaramı b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/babama-ne-hos-insandin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsiz birşey', 'belirsiz-birsey-ahmet-kose-jra6n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce 

sular gibiydi

şırıl şırıl

renksiz renksiz

Sonra deniz oldu

gök oldu

derinden bir eylül oldu

mayısı andırıyordu

gözlerin baharı

Ve şimdi yağmur oldun

toprağıma

Bir derinlikteyim

ümitli

ümitsiz.

Ama sana dokunamadım.

Çünkü konuşamadık daha.

5/6/eyl/''89/turgutreis', 'Önce  sular gibiydi şırıl şırıl renksiz renksiz Sonra deniz oldu gök oldu derinden bir eylül oldu mayısı andırıyordu gözlerin baharı Ve şimd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/belirsiz-birsey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne yapmalıyım bilmiyom', 'ne-yapmaliyim-bilmiyom-ahmet-kose-qd1ek', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dudaklarımı ısırıyorum

Türküler kanıma giriyor

Gözlerimi sıkıyorum iyicene

Deniz galeyana getiriyor

Ellerimi tırmalıyorum

Sözcükler savaşa sürüklüyor

Bir gece

Bir gündüz yaratmalıyım

Baş köşeye birçift el koymalıyım

Yüreğimi sarmalasın

Yaşantıma mola vermeliyim

Olası değil bu istek

Ancak ölümde dinleneceğim

Yüreğime bakıyorum

Hergün bir başka bahar

Robinson yalnızlığında

Gullıver gibiyim

Umarsızım ne güzel! 

En iyisi bir umarı sarmalamak.   

21/eyl/89/turgutreis', 'Dudaklarımı ısırıyorum Türküler kanıma giriyor Gözlerimi sıkıyorum iyicene Deniz galeyana getiriyor Ellerimi tırmalıyorum Sözcükler savaşa s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-yapmaliyim-bilmiyom-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımıyor', 'tanimiyor-menevis-koylu-vf5k8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Komşunun köpekleri

