INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutsuzluğumun Güzel Mimarı', 'mutsuzlugumun-guzel-mimari-mehmet-caner-sumengen-4hjms', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutsuzluğumun güzel mimarı

Yıktığın bu kale gibi adam

Onarılmayı bekleyen bir aşık artık...

Gel! Gel de! ...

Baştan aşağıya yenile beni.

O sevgi dolu günlerde ki gibi

Işıldayan gözlerinle bak gözlerime.

Kalbimin kapısını aç, gir! 

İstediğin şekilde düzenle içimi.

Sana teslim ettiğim sefil yüreğimi

Kokusuna bayıldığın çiçeklerle donat.

Yokluğundan eskimiş gönül duvarlarımı

Yaşam kadar rengarenk boyat...

Ellerinin yumuşaklığında kalsın yanaklarım

Dudaklarının vazgeçilmez şevkatinde.

Saçlarına esen rüzgarlar alsın götürsün

Yalnızlığın hüzzam makamı kederini.

Ve hiç te olmasın kaderde ayrılık

Olmasın sensizlik

Uyanınca biten rüyalardan olsun 

Omzuma yüklediğin deli hasretlik...

Mutsuzluğumun güzel mimarı

Yıktığın bu kale gibi adam

Onarılmayı bekleyen bir aşık artık...

Kimseye söyleyemediğim acılar besledim 

Pişmanlık kafesim doldu taştı.

Tutsaklığında kaldım hep gecelerin

Ezilmişliğin lanetine yenildim.

Kelepçe taktığın canımın çilesini

Yalan gülüşlerle süsledim.

Yitirdiğim tadı buruk zamana inat

Kahkahalar bile besteledim...

Çocukluğuma döndüm, düşündükçe...

Anneme bağlılığımı, babamın dizinde oturuşumu

Evimizin önünden uzaklaşmayan uslu yanımı...

Anladım ki...Aynısındayım yine...

Yine sadakatim kendimden öte...

Böyle işte kara sevdam

Böyle işte tutkum

Böyle işte böyle! 

Varlığına mahkum dimdik duruşum...

Mutsuzluğumun güzel mimarı

Yıktığın bu kale gibi adam

Onarılmayı bekleyen bir aşık artık...', 'Mutsuzluğumun güzel mimarı Yıktığın bu kale gibi adam Onarılmayı bekleyen bir aşık artık... Gel! Gel de! ... Baştan aşağıya yenile beni. O s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/mutsuzlugumun-guzel-mimari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Amazon''un Sesi! ...', 'amazon-un-sesi-naime-erlacin-0g5ee', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yüzümde takvimler eskitebilirsiniz

bahçelerimi soldurabilir

susturabilirsiniz baharı

denizlerimi çalın isterseniz 

yıldızları gökyüzünden

bulutları katarım yanınıza

kılıç şakırtılarım duyulmaz olur

nal seslerinde gizler çılgın süvarileri

acıya emanet ederim

kör bıçaklar üzerindeki yürüyüşlerinizi

savaş alanlarını cennete gömdüm 

kan tozuyla suladığım 

yetim yarınlarınızı

varsın kurusun nehirler! 

son nefeste bile döl vereceğim

dursa da yüreğin yelkovanı 

korkmayın yakalarım günışığını ben

nasıl susturabilirsiniz 

ihanete ceza yazan bu dansı 

elinden tutuyorum rüzgârın 

fırtına gözünde beklemekteyim

fırtına yüzlü

fırtına özlü

fırtınanın kendisi

Amazon’un sesiyiz biz! 

yeter ki çalınmasın hayaller

yeter ki bize kalsın dizelerimiz 

(28 Eylül 2003)', 'yüzümde takvimler eskitebilirsiniz bahçelerimi soldurabilir susturabilirsiniz baharı denizlerimi çalın isterseniz  yıldızları gökyüzünden bu...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/amazon-un-sesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kağıt At (Yürek)', 'kagit-at-yurek-ahmet-aksoy-03i75', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kağıt bir attın 

Kimi zaman üstü yazılası 

Kimi zaman üstü silinesi

Bir banknot gibi, değeri 

Üzerinde yazılanla bir

Kağıttan bir attın

Rüzgarlarda uçan

Yangınlarda yanan

Üstünde aşk taşıyan

Üstünde medeniyetler yaşatan

İnce ve narin şiir gibi

Hükmü kullananın

Kullanma gücüne 

Denk verimli

Kiminde hamurun iyilikten

Kiminde hamurun kötülükten

Kalite kalite birinci, ikinci, 

Üçüncü hamur, çeşit çeşit yani

Hatta birle iki arasındaki sayılar kadar.', 'Kağıt bir attın  Kimi zaman üstü yazılası  Kimi zaman üstü silinesi Bir banknot gibi, değeri  Üzerinde yazılanla bir Kağıttan bir attın Rüzg...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kagit-at-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar ve Sırları', 'kadinlar-ve-sirlari-ali-osman-yilmaz-8vknk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kadınlar; 

Çeyiz sandığının gizemi gibi sır dolu kadınlar.

Her şeyleri sır, her şeyleri saklıdır onların, 

Açarsınız sandığını, kat kat çeyizler arasında ararsınız

Ama bulamazsınız bir türlü.

Maharetle saklanmış el emeği işlemeler

Gipür danteller arasında gizlenmiş kadınlıklar

Yıllar sonrasına uzanan bir dolu eskiyecek anılar.

Açarsınız, ararsınız kadını; bulamazsınız gizlenmiş, 

Nasıl bakarsanız bakın göremezsiniz, ama süslenmiş

Ne zaman istese açar kendini gösterir biraz, 

İnce dudaklarında bir gülüş, Sonra çeker kendini geriye

Saklanır, göstermez yüzünü yeniden belirir sırrı, 

Öğrenmek için kadınları, bir ömür harcamanız gerekir

Bir ömür bittiğinde giderken dört kolluyla

Yine ardınızda bir dolu sır bırakırsınız, öğrenemeden.

Ardınızdan gelir kadında, sırlarıyla dolu olarak yanınıza, 

Sırlarıyla birlikte, ama orada da söylemez size.

Yine öğrenemeyeceksiniz orada da kadının sırrını

Tarih boyunca, hangi erkek çözebilmiş ki bilen var mı bunu? 

İskender’in düğümünü çözmeyi başaran bir er kişi, 

Çözemeden ölür, çünkü tarih kadar eski, bu kadınların işi.

                                                                Ali Osman Yılmaz', 'Kadınlar;  Çeyiz sandığının gizemi gibi sır dolu kadınlar. Her şeyleri sır, her şeyleri saklıdır onların,  Açarsınız sandığını, kat kat çeyi...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kadinlar-ve-sirlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kristal At (Günah)', 'kristal-at-gunah-ahmet-aksoy-d9v0d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kristal bir attın

İnsanın gözünü alırdın

Seni satan öyle bir satardı ki

Kim alsa elinde kalırdın

Pazarlık gücü yüksek

Bir satıcıydı seni satan

İşte bu yüzden, hiçbir 

Müzayede olmamıştır

Satıcıların elinde kaldığın

Oysa değildi değerin

Parlaklığınla bir, üstelik 

İnsanlara zararlıydın

Ki karanlık bir güçten

Yansırdı varlığın.', 'Kristal bir attın İnsanın gözünü alırdın Seni satan öyle bir satardı ki Kim alsa elinde kalırdın Pazarlık gücü yüksek Bir satıcıydı seni sat...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kristal-at-gunah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece', 'bir-gece-gunes-ozhan-5lvur', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yagmurun cigligi var cantamda

topraga kavusunca kesilen cigligi...

agustos böceklerinin haykirislarini biriktirdim bir gözünde

güz gelince susacaklarini düsünerek...

bir kösesine biraz günisigi koydum ya kis bitmezse diye...

sonra biraz yasemin kokusu ve taze kanat cirpislari güvercinlerin...

sakalarin günü kucaklayislari uyandikca sira sira...

ve soguk gecelerin tanigi ciy damlalarindan attim icine, 

biraz lavanta serptim ustlerine ozenle...

...ve gülümsedim gökyüzüne...', 'yagmurun cigligi var cantamda topraga kavusunca kesilen cigligi... agustos böceklerinin haykirislarini biriktirdim bir gözünde güz gelince s...', ARRAY['Türk Edebiyatı','Şiir','Günes Özhan']::text[], 8.5, '{"poet":"Günes Özhan","poet_slug":"gunes-ozhan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-gece-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sev Ya Unut Beni', 'ya-sev-ya-unut-beni-derin-oger-6zq0t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey başıboş yolcu

Keyfinle geçemezsin kalbimden

Çoğalıpta cümle alem olduktan sonra

Taşınamazsın kaderimden

Ey kalbimin ihtilâlcisi

Öğrenmen şart değil nedensiz sevgiyi

Zaman dokundurmaz bir daha geçmişe ellerini

Ya sev ya da unut beni...........', 'Ey başıboş yolcu Keyfinle geçemezsin kalbimden Çoğalıpta cümle alem olduktan sonra Taşınamazsın kaderimden Ey kalbimin ihtilâlcisi Öğrenmen ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ya-sev-ya-unut-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme Sesleniş 1', 'anneme-seslenis-1-refik-yildiz-zuet0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dizine baş koysam bir bulut gibi

Hıçkıra hıçkıra ağlasam anne

Saysam dertlerimi dizinde saysam

Bir volkan gibi patlasam anne

Gezinse pamuktan elin saçımda

Kucağında doyasıya ağlasam anne

Yüzümden anlasan derdi yüzümden

Derdimle dertlenip ağlasan anne

Issız köşelerde ağlarım sensiz

Ne olur sarılsan sarılsan anne

Usandım yalnızlıktan bıktım hayattan

Şefkatin bağrında güldürsen anne

Geçemez yerine kimse geçemez

Anladım geç oldu anladım anne

Ayakta görüpte yaşar sanılsın

Öldüğün gün seninle öldüm ya anne...!', 'Dizine baş koysam bir bulut gibi Hıçkıra hıçkıra ağlasam anne Saysam dertlerimi dizinde saysam Bir volkan gibi patlasam anne Gezinse pamukta...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anneme-seslenis-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme sesleniş 2', 'anneme-seslenis-2-refik-yildiz-xt4g5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün baharı gördüm bağında

Güller bile seninle güzelmiş anne

Mendil bağlamışlar mezar taşına

Taşlar bile seninle güzelmiş anne

Korkar idim mezardan mezar taşından

Geçmezdim geçsede yolum içinden

Çevirirdim başımı gitsin içimden

Mezarlar seninle güzelmiş anne', 'Bugün baharı gördüm bağında Güller bile seninle güzelmiş anne Mendil bağlamışlar mezar taşına Taşlar bile seninle güzelmiş anne Korkar idim ...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anneme-seslenis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Demir At (Gurur)', 'demir-at-gurur-ahmet-aksoy-w0dvg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sudan korkardın demir at 

Paslanmaktı tek derdin

Her şey güzeldi yoksa

Diğer atlar arasında

Saygın bir yerin vardı

Senin bir ağırlığın vardı

Demirdendin.

(Gurur Su Kaldırmaz.)', 'Sudan korkardın demir at  Paslanmaktı tek derdin Her şey güzeldi yoksa Diğer atlar arasında Saygın bir yerin vardı Senin bir ağırlığın vardı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/demir-at-gurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Mermer At (Zenginlik)', 'mermer-at-zenginlik-ahmet-aksoy-ku1th', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mermere oyma

Mermerden at

Şehrin göbeğindeki

İhtişamlı, mermer at

İnsanlar, nasılda hayrandı sana

Kaç yıl durdun ortada

Mağrur ve gururla

Yüksekten bakarak insanlara

Ama ne yazık ki

Kaç şehrin ya da

Kaç insanın ömrü

Mermere denk olabilir

Sonunda insanlar öldü

Şehir tarihe gömüldü

Ne şan ne şöhret

Kaldı senden geriye

İhtişamlı, mermer at

Tepeden baktığın, 

İnsanlar kadarmış ömrün

Bak artık sende yoksun.', 'Mermere oyma Mermerden at Şehrin göbeğindeki İhtişamlı, mermer at İnsanlar, nasılda hayrandı sana Kaç yıl durdun ortada Mağrur ve gururla Yü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mermer-at-zenginlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidemezsin', 'gidemezsin-ahmet-aksoy-x6uan', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanadı kırık uçağının

Tekeri patlak arabanın

Nalları yok atının

Yelkeni yok teknenin

Hatta ayaklarında yok

Gidemezsin hiçbir yere

Ben olmadan canım.', 'Kanadı kırık uçağının Tekeri patlak arabanın Nalları yok atının Yelkeni yok teknenin Hatta ayaklarında yok Gidemezsin hiçbir yere Ben olmada...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gidemezsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme sesleniş 3', 'anneme-seslenis-3-refik-yildiz-fkeey', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni andım da yine dua dua dün gece

Seccademe kapandım beni duydun mu anne? 

Bir kez daha okşayıp sarsam diye yeniden

Kapını çaldım tak tak, sesler duydun mu anne? 

Duaların içinde saldığım selamlardan

Hiç ulaşan oldu mu; beni duydun mu anne? 

Hep içimde yaşadın hiç ayrı kalmadın ama

Çok özledim seni, sende özledin mi anne?', 'Seni andım da yine dua dua dün gece Seccademe kapandım beni duydun mu anne?  Bir kez daha okşayıp sarsam diye yeniden Kapını çaldım tak tak,...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anneme-seslenis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile', 'cile-refik-yildiz-joi4u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde kıvrım kıvrım kıvranır çile

Dile gelir, hece olur, kelimesi öldürür

Bin başlı ejderdir, dolanıyor beynimde

Akla gelir, fikir olur, kaste döner öldürür

Yumarım gözümü çıksın içimden diye

Gece olur, düşe gelir, kabus olur öldürür

Fırlarım yataktan tutup kastedeyim diye

Ufka gelir, selam verir, el sallayıp öldürür', 'İçimde kıvrım kıvrım kıvranır çile Dile gelir, hece olur, kelimesi öldürür Bin başlı ejderdir, dolanıyor beynimde Akla gelir, fikir olur, ka...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cile-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Damlasın Gözpınarımda…!', 'bir-damlasin-gozpinarimda-muammer-celik-xs2x7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gece tek tek topladığım

parmak uçlarımla tuttuğum

yere düşürmeye kıyamadığım

bir damlasın gözpınarımdan 

inci edasıyla süzülerek akan 

29.03.2003 (01:00) 

BirDeli', 'Her gece tek tek topladığım parmak uçlarımla tuttuğum yere düşürmeye kıyamadığım bir damlasın gözpınarımdan  inci edasıyla süzülerek akan  2...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-damlasin-gozpinarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Dolu’yum', 'deli-dolu-yum-muammer-celik-z2n1j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle doluyum ki...

Nasıl desem, nasıl anlatsam sana? 

Hani dokunsan ağlayacağım denir ya

hani dokunsan patlayacağım denir ya

hani kendimi zor tutuyorum denir ya

hani bir öpsen, buhar olup ucacağım denir ya

hani tenimi sarsan, melek olup kanatlanacağım denir ya

hani bir nefes versen, canlanıp şahlanacağım denir ya

hani gozlerime bir baksan, ırmak olup akacağım denir ya

hani bir parmak ucu değsen, yıkacağım barajları

coşacağım, coşacağım, köpüreceğim, köpüreceğim

ve nerde neyim varsa, hepsi ile boşalacağım denir ya...? 

İşte kelimenin tam anlamıyla; 

Böyle Dolu Dolu Deliyim, KADINIM, ben sana! 

……………. E’ hadi, akıt gayri, akıtabilirsen...! 

29.09.2003

BirDeli', 'Öyle doluyum ki... Nasıl desem, nasıl anlatsam sana?  Hani dokunsan ağlayacağım denir ya hani dokunsan patlayacağım denir ya hani kendimi zo...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/deli-dolu-yum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Son Gece Rakılık''tır...', 'o-son-gece-rakilik-tir-okan-savci-uvb7l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey özüne kurban olup da 

Yalan dünyasına sövdüğüm

Sen var git yoluna, aldırma...

Bu ilk yalan değil ki gördüğüm! 

Şimdi şehre yağmurlar indi

Bu da bana yalnızlık demektir

Türkülerim yarım kaldı 

Bu mevsimde vedalar adettendir

Yine susmak düştü payıma

Bir kapı daha kapandı, ayrılıktır.

Yine kaldım gecenin kucağında

Senin gecelerin kaç paralıktır? 

Benim bu kırılgan gülüşlerim 

Senin gibilere bil ki satılıktır...

Kalırsa son gece kalır aklımda 

O da meyhanede rakılıktır....', 'Ey özüne kurban olup da  Yalan dünyasına sövdüğüm Sen var git yoluna, aldırma... Bu ilk yalan değil ki gördüğüm!  Şimdi şehre yağmurlar indi...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-son-gece-rakilik-tir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler Terkediyorum', 'geceler-terkediyorum-derin-oger-b01vl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanıdık oluyor günler

Kalbimin küçülüşlerinde

Sanki okyanus büzülüyor gözlerimde

Gürleyince gökyüzü gökte

Yeryüzü yerde kalıyor 

Su yolunu biliyor

Sıcaklığı olmayan resimler yırtıyorum

Ateşi avuçlarımda tutarak

Tenimde yanıyorum

Meçhule seslenişlerimde

Sesimin sesime çarpmasından yorgun 

Geceler terkediyorum geçmişe

Zaman harcanırken

Yaşamak anlamsızlaşıyor bazen

Birbirinden habersiz yürekler tükeniyor

Ateşte küller uçuşurken

Benim olduğunu bildiğim bir günüm olsa 

Sonsuzca sonsuzluğunca

Kaç günlük olduğumu bilemediğim şu dünyada

Oysa imkansızlığı seyrediyorum

Suskunluğuma noktalar koyarak

Bir nefes sevgi uğruna

Geceler terkediyorum

Geçmişin ağlarına

Tanıdık oluyor günler

Tanıdık oluyor..........................', 'Tanıdık oluyor günler Kalbimin küçülüşlerinde Sanki okyanus büzülüyor gözlerimde Gürleyince gökyüzü gökte Yeryüzü yerde kalıyor  Su yolunu b...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/geceler-terkediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Beş Kişiyim....', 'ben-bes-kisiyim-orkun-isik-pkviw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '‘Ay Yüzlüm’, ‘Işık Soylum’ Ve Asya’m

Bir Ben Birde ‘İnleyen’ Dünyam

Benimkisi Bu Kavgada Zor Ölüm

Nefesim Kadardır Size  Sevdam.

Kaptırmayın Nefsinizi Dünyaya

Harama, Zinaya, Sonra Riyaya.

Kapılıp Sel Olursunuz, 

İhanete, Ve İnkar Dolu Rüyaya..

Aslını Unutma, Unutamazsın

Dil’siz Ve Kültür’süz Yapamazsın

Meyletme “Havari” Aydınlığına

Sen Bozkırlardan Kopamazsın.

‘Ay Yüzlüm’, ‘Işık Soylum’ Ve Asya’m

Ey! ‘İnleyen’ Dünyam, Size Tutunsam

Benimkisi Bu Kavgada Kor Zûlüm

Yanacağım Kadardır Size Sevdam..............', '‘Ay Yüzlüm’, ‘Işık Soylum’ Ve Asya’m Bir Ben Birde ‘İnleyen’ Dünyam Benimkisi Bu Kavgada Zor Ölüm Nefesim Kadardır Size  Sevdam. Kaptırmayın...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-bes-kisiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzzam', 'huzzam-aysel-coban-esqvn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adına yakılan bin bir ağıttı sevdam

Sesindi Hüzzam şarkısında nakarat

Doyasıya dinlesem, 

Hasret gidersem.

Okusam, okusam yine okusam, 

Kendimden geçsem.

Duygularımdı, 

İçinde sol anahtarı.

Açsam içindekileri görsem.

Gördükçe sana çıldırsam.

Seni göklere çıkarsam.

Kaf dağında mistik bir yaşam sürsek

Çaldığın LİR’ de  parmağın olsam.

Ben hissettikçe sen şarkı söylesen.', 'Adına yakılan bin bir ağıttı sevdam Sesindi Hüzzam şarkısında nakarat Doyasıya dinlesem,  Hasret gidersem. Okusam, okusam yine okusam,  Kend...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/huzzam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar Buluştu', 'dostlar-bulustu-hakki-hakan-kaya-p8afk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrıyken canlar, bedenler, 

Kalplerde bir koro oluştu, 

Aşk uğruna, şiir uğruna, 

Dostlar birleşti, Dostlar buluştu.

Aynı sazda olduk türkü, 

Mızraptık, dildik sanki, 

Türküler, sazlar ayrı değil ki, 

Dağlar birleşti, Dostlar buluştu.

Bir söyledik, iki dinledik, 

Dostluğumuza Dost ekledik, 

Yeter artık, çok bekledik, 

Yollar birleşti, Dostlar buluştu.

Dergah kurduk ettik kelam, 

Gönül yarenleri aktı heman, 

Gelene gelmeyene olsun selam

Diller birleşti, Dostlar buluştu.

Gönül odasında sofra kurduk, 

Döktük, sohbet şerbetin içtik, 

Kah ağladık, kah güldük, 

Kalpler birleşti, Dostlar buluştu.', 'Ayrıyken canlar, bedenler,  Kalplerde bir koro oluştu,  Aşk uğruna, şiir uğruna,  Dostlar birleşti, Dostlar buluştu. Aynı sazda olduk türkü,...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dostlar-bulustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elzem', 'elzem-aysel-coban-9fcec', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adım adım kaldırımlarda ayak izlerim.

Bir sonu olmalı

Geride kalan bu izlerin

Yürüdükçe üstüne, acımasız yaşamlara

Dur demeli bu gidişe

Hala bir beklenti varsa

İnadına direnmek hayata

Yalnızlık çeken, tinsel beyinlere

Kan gibi, su gibi, hava gibi, 

Ruhları yaşatmak için sevgi ELZEM

Anlarım ki işte o an, 

Bir nefes içimde özlemlerim

Bir ses ki; 

Beni çağırır aşk sarhoşluğuna

Önce sen, can özüm, sevda yoluna

Ben ardı sıra, senin gönül gözünde', 'Adım adım kaldırımlarda ayak izlerim. Bir sonu olmalı Geride kalan bu izlerin Yürüdükçe üstüne, acımasız yaşamlara Dur demeli bu gidişe Hala...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/elzem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kuru Ekmek Gibi Sevdan', 'bir-kuru-ekmek-gibi-sevdan-aysel-coban-lov5p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beklenen hayel bahçesinde gizli yüzün

Tomurcuk açmış yüreğinde bitmez ümidim

Beklenmedik zamanda çıkar karşına beklentin

O zaman son bulur vuslatın

Belki bir dağ çiçeğinde o mis koku

Belki bir dağ köylüsünün saf bakışlarında

Belki hiç ummadığın tanıdık bir yüzde

Belki ekin tarlalarında başak tadında

Acıktığında tadına varılan, 

BİR KURU EKMEK GİBİ SEVDAN

Alınan her hazda, unutulan duygular senin

Belki en sevdiğin yemekteki lezzet

Yudumladığın her damla sudaki serinlik

Belki heyecanlandığında yüreğindeki o garip atış

Belki sevgiyle bakan gözlerle süzülüş

Belki de yaşamla ölüm arasındaki  o ince geçiş', 'Beklenen hayel bahçesinde gizli yüzün Tomurcuk açmış yüreğinde bitmez ümidim Beklenmedik zamanda çıkar karşına beklentin O zaman son bulur v...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-kuru-ekmek-gibi-sevdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gel....', 'hadi-gel-aysel-coban-khjfa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hadi gel...., 

Duyduğum özlemlerde, 

Rüyalarımda son bir kez bulun.

Hançerle oyulacak gibi kıvranan

O masum kalbime dayan.

Hadi gel...., 

İçime sindire sindire çektiğim kokunu

Hissetmeme izin ver.

Hadi gel...., 

İçtiğim her yudumda, 

Yediğim her lokmada, 

Gördüğüm her nesnede

SEN....

Anlatamadığım özlemlerimde

Yalnız bıraktığın her an da sen varsın.

Hadi gel...., 

Gelemezsin ki, 

Gittiğin yerde göremezsin ki, 

Bulunduğun yerden hissedemezsin ki, 

Gelemeyeceğini bile bile gelmesini istiyorum.

Son bir kez gel, 

Hadi gel..., 

Ölüm uykusunda olduğun halde

Yine de gel, 

GEL.....', 'Hadi gel....,  Duyduğum özlemlerde,  Rüyalarımda son bir kez bulun. Hançerle oyulacak gibi kıvranan O masum kalbime dayan. Hadi gel....,  İç...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hadi-gel-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip desem', 'bir-garip-desem-aysel-coban-2dos9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dilimde haykırışlar sazımın telinde

Ozanım desem, ozan değilim, anlatayım.

Gizlilik  içinde sevda yükü çekerim.

Şahmaran değilim, dehlizlerde gezemem

Bir garip gezer dururum, Özendim erenlere

O kadar iyi değilim, hoşgörü gösteremem

Kavgasız güzel bir dünya isterim

Gücüm yetmez, insanları ikna edemem

Ağıtlarım dağları aşsın, obalara ulaşsın

Kızların yemenisinde, oyalarda dile gelsin

Her cefa bende desem, güzelim

Onlar gibi değilim naz çekemem', 'Dilimde haykırışlar sazımın telinde Ozanım desem, ozan değilim, anlatayım. Gizlilik  içinde sevda yükü çekerim. Şahmaran değilim, dehlizlerd...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-garip-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Ayazı', 'kis-ayazi-aysel-coban-hr5hv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kış ayazı kalbimde, için için, içim üşüyor

Üşüdükçe gülüm, belleğim sarsılıyor

Sarsıldıkça çaresiz beynim emrediyor

O zaman her şey tek tek ortaya çıkıyor

Kış ayazında, duygularım buz kesmiş

Her soluk alışım, gidip gelmekten bezmiş

Öyle yorgun ki bedenim, sıcak işlemez

Kemikleşmiş içimde, istesen de erimez

Kış ayazı gözlerimde, soğuk bakışlarda

Ta derinlerde kar ışıltısı parlaklığında

Kış ayazında ellerim, dokunmaya korkar

Oysa ki ellerim, ellerinde sıcaklığını arar', 'Kış ayazı kalbimde, için için, içim üşüyor Üşüdükçe gülüm, belleğim sarsılıyor Sarsıldıkça çaresiz beynim emrediyor O zaman her şey tek tek ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kis-ayazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Avuçlarımda', 'kalbim-avuclarimda-aysel-coban-4fbay', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küf tutmuş duygularla

Puslu düşüncelerimle

Rüzgar gülüyüm.

Döndükçe başım dönüyor.

Yeterince yalnız, 

Yeterince  şaşkınım, 

Gitme dostum, bari sen terketme

Üstelik onsuzum, 

Gözlerimde korlanmış ateş

Tutunacak dal ararım.

Bir şans ver bana, 

Beni anlaman için

Kalbim avuçlarımda sana sunulmaya hazır.', 'Küf tutmuş duygularla Puslu düşüncelerimle Rüzgar gülüyüm. Döndükçe başım dönüyor. Yeterince yalnız,  Yeterince  şaşkınım,  Gitme dostum, ba...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kalbim-avuclarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-aysel-coban-5sz3i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kar tanesi, sanki doğanın incisi

Gökyüzü hüzünlenince,

Kusuyor tüm azametini.

O yumuşak soğuğun uçuşu, 

Ve şekilli beyazın, 

Yer yüzünde birer birer eriyişi.

Gök kubbe bir kalbur sanki

Elendikçe serpilir gideceği yerlere

O an soğuk 

ve yaramaz bir çocuk gibidir..

Gece ve gündüz fark etmez  onun için, 

Katmer katmer birleşince

Parlak yorgan oluştuğunda

Işığın kırılmasıyla çiçek demetidir sanki

Beyaz gelinlik giymiş, 

bir kızdır artık o an yeryüzü', 'Kar tanesi, sanki doğanın incisi Gökyüzü hüzünlenince, Kusuyor tüm azametini. O yumuşak soğuğun uçuşu,  Ve şekilli beyazın,  Yer yüzünde bir...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kar-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naçar', 'nacar-aysel-coban-87z38', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dorukları buzul tutmuş dağ köyünde, 

Yalçın kayaları tırmanan elik.

Tut ellerimden götür beni patikalara.

Çıkalım ağır ağır, 

Hırsım hırslarına yenilsin.

Her adımda, 

Aldığım her nefeste, 

Döktüğüm terlerin değerini anlayayım.

Buz kesmiş  duygularım titredikçe, 

Isıt her adımda, 

Eriyen mum lafta kalsın.

Gönül gözüm görmez olmuş, 

Naçar kalmış kalbimi aydınlat

Ateşböceği kıskansın seni, 

Her uçuşunda.', 'Dorukları buzul tutmuş dağ köyünde,  Yalçın kayaları tırmanan elik. Tut ellerimden götür beni patikalara. Çıkalım ağır ağır,  Hırsım hırslar...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nacar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koza', 'koza-aysel-coban-argqf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimdeki coşkulu duygular, 

Bir kelebeğin kozası gibi açılmaya hazır.

Açıldığında bir renk cümbüşünde uçmaya başlar.

Hadi gel, katıl bana.

Seninle kanat açıp insanların kalbine konalım, 

Her renkten, her güzellikten verelim.

Onlardaki bu değişikliği gördükçe, 

Uçup başka diyarlara göçelim.

Yeni kozalar yapıp, yeni yuvalar kuralım.', 'İçimdeki coşkulu duygular,  Bir kelebeğin kozası gibi açılmaya hazır. Açıldığında bir renk cümbüşünde uçmaya başlar. Hadi gel, katıl bana. S...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/koza-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosun Yeşili', 'yosun-yesili-aysel-coban-2zhn7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yosun yeşili gözlerinde, 

Ateşi sönmeye yüz tutmuş bir bakış

Yosun yeşili bakışlarında hüzün

Hüzünlü bakışlardaki sen, 

Sen değilsin, bir başkası ışıltılarda.

Gizemli o bakışlar, çözülmek istemiyor.

Yüzünde sana ait olmayan bir maske

Aslında duygulusun.

Alın çizgisinde yılgınlık

Yorgun ruhunla inanmak istiyorsun

Güçlü görünmek isterken, 

Nefretinle beraber duygularının esirisin.

Yaşananlar saplanıp kalmış belleğinde

Sen kaçtıkça kovalıyor geçmişe', 'Yosun yeşili gözlerinde,  Ateşi sönmeye yüz tutmuş bir bakış Yosun yeşili bakışlarında hüzün Hüzünlü bakışlardaki sen,  Sen değilsin, bir ba...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yosun-yesili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik', 'kimlik-aysel-coban-1adcu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimim ben? 

Kendimi arıyorum, 

Bilmiyorum ne olmalı yım

Anadolu Türk kızı mıyım? 

Yoksa batılı biri miyim.

Neye göre kendimi itham etmeliyim.

Aşk dolu türküleriyle 

Elinde sazları, halk ozanları.

Çarık giydiğin günler, çok uzak değil güzel

Anadolu’nun soğuk çeşmeleri, 

Soğuk çeşmeden, bir yudum su içen kınalı eller

Tarla tapanda çalışmış o eller, 

Nasırlı ellere bakıp, özünü unutmazsın.

Akşam olup ağıllar açılınca

Sarı kız eve geldiğinde süt verecek.

Sabahları ilk ışıkla, 

Atın Rüzgar Gülüyle uçacaksın.

İlk tohumları atacaksın

Öğle vakti, güneş ortalığı kasıp kavururken

Bir bakraçtan ayran içeceksin.

Yetişin dağlarıma, ovalarıma

Seyredin derelerimi, 

Suda oynayan sazanları

Ve şehirli kızımın, koca koca binaları

Fabrikalardan tüten dumanları, 

Kalabalık araba yığınları, 

Akşam olunca, eve dönen insan seli.

Okulları, hastaneleri, 

Televizyonu, radyosu, 

Bir de batılı olma sevdası

Okullarında çeşitli insanlar

Kimi örtülü, kimileri mini etekli, 

Kimi belirsiz, kimileri entel görünüşte

Kimileri ise gerçek çağdaş

Ben hangisiyim?', 'Kimim ben?  Kendimi arıyorum,  Bilmiyorum ne olmalı yım Anadolu Türk kızı mıyım?  Yoksa batılı biri miyim. Neye göre kendimi itham etmeliyim...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kimlik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül yüzlüm', 'gul-yuzlum-aysel-coban-6b3z7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaldır kafanı gül yüzlüm, bak bana

Niçin ışıldamıyor gözlerin, 

Yüzünde bir hüzün var, 

Çok çekmişsin belli, anlat bana

Bir de ben bileyim, 

Aç o kilitli kalbini, çıksın ortaya sırların, 

Nedir derdin? 

Korkma benden.

Bil ki temizsin her şeyden

Öyle güzel ki yüzün, 

Korkarım solacak kederden

Olmaz ki, bu böyle olmaz.

Seni, sana düşman eden yar

Ne hayırsızmış gittiği an, 

Anlamıştım gül yüzlüm

Belli oluyordu gözlerinden

Olanları unut gülüm, 

Gülen yüzün bir daha solmasın

Bir vefasızın ardından, değmez bu çektiklerin', 'Kaldır kafanı gül yüzlüm, bak bana Niçin ışıldamıyor gözlerin,  Yüzünde bir hüzün var,  Çok çekmişsin belli, anlat bana Bir de ben bileyim, ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gul-yuzlum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-aysel-coban-1kqhy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakakalmak ardından sen giderken

Bir daha ne zaman görürüm düşüncesiyle

El sallamak arkandan

Dönüşünü görmek ümidiyle beklemek

Çıldırtır  insanı uzayan  ayrılık

Ayrılığı kabullenemeyip peşin sıra koşarım.

Geç kalan saniyelerde

Uzaklaşan vapurda kaldı kalbim.', 'Bakakalmak ardından sen giderken Bir daha ne zaman görürüm düşüncesiyle El sallamak arkandan Dönüşünü görmek ümidiyle beklemek Çıldırtır  in...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niyet', 'niyet-aysel-coban-ttlv4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O hiç inanmadığın soğuk algınlığını yaşıyorum.

görmezden geldiğin bu aşkı, 

dolu dizgin yaşıyorum.

Varlığın hiç tahmin etmediğin

Ağrı kesici niyetine.

Sevgin can simidi yerinde, 

Korkup kaçarken, boğulmaman için, 

Kalp kapakçıklarım birer filika sana

Tehlike geçene kadar benimlesin.', 'O hiç inanmadığın soğuk algınlığını yaşıyorum. görmezden geldiğin bu aşkı,  dolu dizgin yaşıyorum. Varlığın hiç tahmin etmediğin Ağrı kesici...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/niyet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Portre', 'portre-aysel-coban-gnpwk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir delikanlı yaşlılığın ilk durağında, 

Şartlar öyle yıpratmış ki.

Zamanından önce şakakları beyazlamış.

Öylesi derin dertler, 

Arsız yaşamın binlerce kepeği var saçlarında

Yüzünde derin çizgiler, 

Güneşten kızıllaşmış teninde çöküş

Elleri sert sevgili yari görünümünde

Kaç yaşın darbeleri yüreğinde

Ürkekliğini saklayan  cesurluğunda

Eleğe dönmüş ceketinde saklı sevdası

Çoğu zaman ikinci kez değiştiremediği gömleğinde, 

Oluşan kirli çizginin son saniyeleri boynunda.

Her şeyden vazgeçmiş, yarı bükülmüş kemerinde

Yamalarını sergileyen pantolonuna isyan var

Zamana kafa tutan son ayakkabısı da

Terk ediyor onu, yolculuğunun son durağında

Oysa ki ayakkabının altında, 

Kaldırımlarla fazlaca yüz göz olmuş, 

Bir çift delik, ısrar edercesine

Tanıt kendini ey yabancı sınır ihlali var.', 'Bir delikanlı yaşlılığın ilk durağında,  Şartlar öyle yıpratmış ki. Zamanından önce şakakları beyazlamış. Öylesi derin dertler,  Arsız yaşam...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/portre-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine de', 'yine-de-aysel-coban-hq1xu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakma öyle yüzüme ne olur

Gözlerinde suçluluğumu görürüm

Bir anlatabilsem içimdekileri

Yaşananlar öyle insafsız değil

Yine de affedebilir misin 

Konuşma öyle acımasızca ne olur

Sözlerinde vefasızlığı hissederim

Bir inandırabilsem söyleceklerime

Her şey o kadar kolay değil

Yine de sevebilir misin 

Bakma öyle gözlerime ne olur

Gözlerindeki  hüznü sezerim

Bir yaşatabilsem yaşayamadıklarımızı

Hayat hiç sorunsuz değil

Yine de ümit eder misin

Dalma öyle derin düşüncelere ne olur

İçinde hissettiğin isyanları bilirim

Bir bilsen senden çok acı çektiğimi

Aldığım her nefes sancısız değil

Yine de beraber olmak ister misin 

Küsme öyle incinerek ne olur

Yüzünde ki her halin anlamını bilirim

Bir görebilsen gerçekleri

Yaptığım hiçbir şey sorumsuz değil', 'Bakma öyle yüzüme ne olur Gözlerinde suçluluğumu görürüm Bir anlatabilsem içimdekileri Yaşananlar öyle insafsız değil Yine de affedebilir mi...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yine-de-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Olmadığı Kadar', 'hic-olmadigi-kadar-aysel-coban-5kted', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnız gecemde boş gözlerle seyrediyorum olup bitenleri

Gördüklerim ne kadar kasvetli

Bir o kadar sebepsiz

Halbuki, şimdi gördüklerim aynısıydı dünler

Düşlerimin solgunluğu yüzüme yansıyor

Oysa içimde hak edilmeyen duygular

Yaz sıcağında kurutulmuş düşünceler

Ruhumda kırık bir buz parçası serinliği

Tepkilere donuk bakıyor, tepkisizliğim

Yerini kızgın sözlere bırakıyor 

Beynimde düşünceler uzayıp kalmış

Soruyor kendince

Bir hiç miydi yaşadıklarımız

Bu vakit

Korkuyla üşüme arasında hisselerim

O an

Gecenin gözlerinde ufalıp kalmıştı bedenim

Yalnızlığı haykırıyordu yüzüme hiç olmadığı kadar', 'Yalnız gecemde boş gözlerle seyrediyorum olup bitenleri Gördüklerim ne kadar kasvetli Bir o kadar sebepsiz Halbuki, şimdi gördüklerim aynısı...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hic-olmadigi-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-aysel-coban-gqykl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uyku arası düşüncelerdeyken 

Pencere aralığından esen ılık rüzgar okşuyor bedenimi

Perdeyse özgürlüğün bayrağı gibi eşlik ediyor

Ve sen yoksun yanımda

Ve sen yoksun düşlerimde

İçimde özlem tünelleri açılıyor

Hasret akıyor yarınlarıma

Gözlerim evreni gözlüyor sessizce

Yoksun sen gözlerimde

Umutsuzluğum kara delik günlerime

Beklemelerime yolculuk başlıyor umutsuzca

Ve sen yoksun yarınlarımda

Ve sen yoksun yaşamımda

Dilimin ucunda adın pelesenk olur

Alışılmadık bir istek duyar ruhum

Ve sen yoksun kelimelerde

Ve sen yoksun bedenimde

Uyku arası firarda düşüncelerim

Hep yalnız paylaşımlarda sensiz günlerim

Ve sen yoksun yanımda

Ve sen yoksun düşlerimde', 'Uyku arası düşüncelerdeyken  Pencere aralığından esen ılık rüzgar okşuyor bedenimi Perdeyse özgürlüğün bayrağı gibi eşlik ediyor Ve sen yoks...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yoksun-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizem', 'gizem-aysel-coban-e9eo3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bilinmezliği  oynuyorsun

Bir amaç mı yoksa araç mı bilmiyorum

Çözmek gibi bir çabaya girmiyorum

Sen bir o kadar bilinmez görünürken

Bir o kadar da senden uzaklaşıyorum

Ben şeffaflığın içinde yüzerken

Sen karanlığa bürünüyorsun', 'Bir bilinmezliği  oynuyorsun Bir amaç mı yoksa araç mı bilmiyorum Çözmek gibi bir çabaya girmiyorum Sen bir o kadar bilinmez görünürken Bir ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gizem-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Med -Cezir', 'med-cezir-aysel-coban-y8mj5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çatallaşmış düşüncelerimi çözemem

Sessiz haykırışlarımı duyuramam

Sana dert yansam anlar mısın

Bir su samuru gibi içimde sebepsiz kemirmeler

Gözlerim doğruları göremez

Nasıl istiyorsa öyle görüyor yarınları

Ümitlerim batan güneşin son hali

Asık çehrelere hiç gülmeyecekmiş gibi gülümser

Hani yüreğimizdeki sözler biter

Akıl yüreğimize hükmedemezse

İşte şu an  o haldeyim bilmeden

Med-cezirler yaşıyor hüzünlerim

Her geliş gidişler tüketiyor sabrımı 

Dipsiz kuyu olan karamsarlığım su yüzünde

Sabır çiçeklerimi taşa çevirsem

Söyle güzelim

Sonu var mı bu çaresizliğin', 'Çatallaşmış düşüncelerimi çözemem Sessiz haykırışlarımı duyuramam Sana dert yansam anlar mısın Bir su samuru gibi içimde sebepsiz kemirmeler...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/med-cezir-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz İsyan', 'sessiz-i-syan-aysel-coban-yzah8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ümitlerin yıkıldığı andı duydukların

Gözlerindeki yıldız parlaklığı söner

Benliğini saran çaresizliğin kıskacında

Beklemediğin bir zamanda 

Seni sefalete sürüklüyorlarsa

Emeklerin heba olması birilerine bağlıysa

Alın terinin yok olup gitmesi, an  meselesiyse

Gel de isyan etme.

Emek mi kazanacaktı, yoksa birilerimi

Döktüğün alın terinde yılların emek kokusu

Bir anda başka ellere mahkum olmuşsa

Erk’e hayat veren masumlar eziliyorsa

Her şeye  rağmen emek yenik düşüyorsa

İnsanlar oyuncak gibi fırlatıp atılıyorsa

Geceleri yataklarında rahat uyuyorlarsa

Gel de isyan etme

İnsanların isyanları, gözyaşlarında saklıysa

Düşen her damla bir sessiz haykırışsa

Bu haykırışları duyurmak için, eli kolu bağlıysa

Çocuğuna, çekilen sıkıntının cevabı verilemiyorsa

Namuslu insanların hakkı yeniyorsa

Yanlışı düzeltmenin imkanı varken

Birileri bunlara ses çıkarmıyorsa

Gel de isyan etme', 'Ümitlerin yıkıldığı andı duydukların Gözlerindeki yıldız parlaklığı söner Benliğini saran çaresizliğin kıskacında Beklemediğin bir zamanda  ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sessiz-isyan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senli Yalnızlık', 'senli-yalnizlik-aysel-coban-208yt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni tanıdım gülen gözlerinle bir zamanlar

Çok değil ayrı kaldığımız, değişen ne? 

Şimdi ne haldesin, vurgun misali

Yağmur kaçağı yaşlar gözlerinde

Yüreğinde yumruk izleri derinleşmiş

İçten içe, yalnızlığın göz hapsinde olan

Yoksa yalnızlık mıydı, seni yalnız kılan

Yada masum yüzlerle masun olunan

Bu sen misin? böyle ortada kalan

Sanki yüzünde yılların yılgınlığı

Kalbinde zamanın çifte yorgunluğu

Avuç içi kadar umutla çırpınan sen

Neden bu haldesin? 

Nedir seni bu kadar çaresiz bırakan.

Niye kaçıyorsun benden? 

Çok değil ayrı kaldığımız, değişen ne? 

Her şeye rağmen yaşamı alaya alan 

Gülünce gözleri de gülen

Umutları bile umutla bekleyen sendin

Şuan günahları sonsuz, suçlu gibi kaçıyorsun

Bak yine yanındayım

Yeniden, gülen gözlerin baksın bana

Yeniden, yine sen ol

Yine, benimle eskisi gibi ol

Yeniden', 'Seni tanıdım gülen gözlerinle bir zamanlar Çok değil ayrı kaldığımız, değişen ne?  Şimdi ne haldesin, vurgun misali Yağmur kaçağı yaşlar göz...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/senli-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşfedilmemiş Şarkı', 'kesfedilmemis-sarki-melih-coskun-pdszd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar boyu keşfedemediğim 

Bir şarkı gibi geldi sesin 

Duyupta anlayamadığım

Baksam da hiç bir zaman göremediğim 

Sonra gözlerinin kıyısına vurdu yüreğim 

Kara bir bulut geçti üzerimden 

Oysa ne güzel başlamıştı gün

Kıpırtısız, sakin 

Sanki dünya bile dönmüyordu o vakit 

İlk dalga kalbime vurdu 

Alabora oldum 

Sahipsiz denizlerde...

Tanımını değiştirdim 

İçimdeki bütün mavilerin 

Ne bir çıkmaz sokak 

Ne umutsuzça beklediğim o köşebaşı yalnızlığı 

Ne zor şeydi 

Bölmek 

Koskoca bir okyanusu 

Ortadan ikiye, 

Ve anlatabilmek 

Bu kadar çok sevilebileceğini 

Hiç kimseden 

Hiç bir şey beklemeden...', 'Yıllar boyu keşfedemediğim  Bir şarkı gibi geldi sesin  Duyupta anlayamadığım Baksam da hiç bir zaman göremediğim  Sonra gözlerinin kıyısına...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kesfedilmemis-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Kim Durduracak', 'bizi-kim-durduracak-bekir-gedikoglu-zazsp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ansızın galipte kalbime tosladın! 

Bulamadım sana engel olacak kirman! 

Kaçkar dağlarından gelen zambak gibisin

Ciğerlerimi parçalayacak bu kokun senin

Coşkun  sevginden dondum da kaldım! 

Hayret!  bir Allaha bir de sana kul oldum

Beni kuşatacak sevgine şimdi muhtacım

Şayet terk edersen harap olurum

Vuslatın beni mest etti bilir misin? 

Göğsüm parçalandı kalbim uçacak

Gözlerimi doldurdu mavi gözlerin, yeşil elbisen

Saatlerce dans edelim bizi kim durduracak?', 'Ansızın galipte kalbime tosladın!  Bulamadım sana engel olacak kirman!  Kaçkar dağlarından gelen zambak gibisin Ciğerlerimi parçalayacak bu ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bizi-kim-durduracak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme, Gidersen, Gidince', 'gitme-gidersen-gidince-oguzkan-bolukbasi-2kr3g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gitme yaram kanıyor merhemim sende

Gitme bitmedi acım dermanım sende

Gitme özlemin  yakıyor içerimi

Gitme bu can bir çöldür, sensiz bedende

Gidersen umut bırak tatlı sesinde

Gidersen ruhuma in her nefesinde

Gidersen aşkın meleğidir Azrail

Gidersen, yerim ölümün teknesinde

Gidince öleceğimi sandım bir an

Gidince bir boşluktu hayatta kalan

Gidince kalmayacaktı bende anlam

Gidince öğrendim tek ilaçmış zaman

Yelkenin büyük olmalı yeni aşklara açılacaksan', 'Gitme yaram kanıyor merhemim sende Gitme bitmedi acım dermanım sende Gitme özlemin  yakıyor içerimi Gitme bu can bir çöldür, sensiz bedende ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gitme-gidersen-gidince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Sofrası', 'dost-sofrasi-refik-recep-pelit-0mi22', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağardı loş ışıkta, gülen yüzler, 

Dost gönüller muhabbeti hep özler, 

Gördüm elmas gibi, yalız yürekler, 

Dirayetsiz kaldı akıldaki cümleler.

Şiirle çağladı, coştu  yürekler 

Yakın oldu ıraktaki yad eller, 

Birleşiverdi sevgi ile tüm eller, 

Yarenlik için çarptı gökçe kalpler.

Sevdayı  yudum yudum içenler, 

Meşk şarabı ile kendinden geçenler, 

Aşk uğruna göz yaşı dökenler, 

Beraberdi dost sofrasında erenler.

Gönül kapısını ardınca açanlar, 

Damlaları derya, umman yapanlar, 

Teveccühle alev alev yananlar, 

Kanat çırptı muhabbete bir canlar', 'Ağardı loş ışıkta, gülen yüzler,  Dost gönüller muhabbeti hep özler,  Gördüm elmas gibi, yalız yürekler,  Dirayetsiz kaldı akıldaki cümleler...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dost-sofrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-galip-tas-paxg2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz hep bizdik

Sadece önceleri ben ben gibi, sende sen gibi

Ama aslında uzaktan uzağa bizdik

Biz Birdik

Bizi biz yapan

Yüreklerimizdi

Alnımız ak gözümüz toktu

Yetmiştik birbirimize

Gözlerimizde görmüştük aydınlığı

Kalbimizde bitirmiştik

Ellerimizle mühürlemiştik

Geri dönülen, Bilinmeze giden ayrılık yolunu

Şimdi elele

Yürüyelim yıldızlı ama karanlık geceden

Umutla doğan aydınlık bizli yarınlara

Haydi şimdi

Ömrümüz yettiğince birbirimiz için var olalım...', 'Biz hep bizdik Sadece önceleri ben ben gibi, sende sen gibi Ama aslında uzaktan uzağa bizdik Biz Birdik Bizi biz yapan Yüreklerimizdi Alnımı...', ARRAY['Türk Edebiyatı','Şiir','Galip Tas']::text[], 8.5, '{"poet":"Galip Tas","poet_slug":"galip-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biz-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Bende Su Sende', 'ates-bende-su-sende-mustafa-karamelek-4je3j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ATEŞ BENDE SU SENDE

Bu gönlü ateşe koyan sensin

Ne arayıp, ne de soran sensin

İçimdeki fırtına boran sensin

Ateş bende su sende kaldı

Yaz ile kışı hayal ile düşü bilmedin

Boş kaldı açık kaldı kollarım gelmedin

Gençliğim soldu gitti de yüzüme gülmedin

Sevda bende heves sende kaldı

Sevgi dolu bir mektubun ucunu yakmadan

Çağlayan sevgin bana doğru hiç akmadan

Oynayıp durdun duygularımla hiç bıkmadan

Geçip gittin bir gün ardına bakmadan

Dert bende derman sende kaldı..

   Mustafa KARAMELEK', 'ATEŞ BENDE SU SENDE Bu gönlü ateşe koyan sensin Ne arayıp, ne de soran sensin İçimdeki fırtına boran sensin Ateş bende su sende kaldı Yaz il...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ates-bende-su-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Yakışmadı Bize', 'ayrilik-yakismadi-bize-mustafa-karamelek-2wgns', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'AYRILIK YAKIŞMADI BİZE

Bir yanlışın kurbanı olduk

Daha baharı yaşamadan solduk

Ayrılığın acısını kapıda bulduk

Sevdalar deryasına giden yolduk

Sen bir yana ben bir yana savrulduk...

Yaşanacak daha çok yıllar vardı

Yıllarımızı sudan sebepler aldı

Beklediğimiz mutluluğu acılar sardı

Yar dediğin senin gibi, benim gibi yardı

Sen bir yanda ben bir yanda vurulduk.....

Toprak olmak yakışmadı aşkımıza

Çok sevmek dert açtı başımıza

Hiçbir mendil kar etmedi yaşımıza

Denk gelmedi ne ayrılık, ne hasret taşımıza

Sen bir ateşte ben bir ateşte kavrulduk......

          Mustafa KARAMELEK', 'AYRILIK YAKIŞMADI BİZE Bir yanlışın kurbanı olduk Daha baharı yaşamadan solduk Ayrılığın acısını kapıda bulduk Sevdalar deryasına giden yold...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayrilik-yakismadi-bize-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana onu anlat', 'bana-onu-anlat-mustafa-karamelek-s54ui', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BANA ONU ANLAT

Bana onu anlat

Gözlerinin, saçlarının rengini

Boyunu,  endamını 

Dilini, dişini, gülüşünü

Ceylanları kıskandıran

Yürüyüşünü anlat bana

	Bana onu anlat

	Nereliymiş, kimmiş? 

	Ne yer, ne içermiş? 

	Neye güler, 

	Neye ağlarmış? 

	Gülüşünü anlat bana.

Bana onu anlat

Saçlarını savuruşunu, 

Kalbe vuruşunu, 

Sevdalı duruşunu, 

Kalkıp oturuşunu, 

Bakışını anlat bana...

	Bana onu anlat, 

	Sıcaklığını güneşten alışını, 

	Güzelliğini bahardan alışını, 

	Kaşlarını hilalden alışını, 

	Cana can katışını, 

	Yakışını anlat bana.....

Bana onu anlat, 

İlmek, ilmek sevda ördüğünü, 

Arada bir gölgemi gördüğünü

Görenleri kalbinden vurduğunu

O baharın, o hayalin esrarını, 

Nakışını anlat bana.....

	Beni ona anlat, 

	Ne çok özlediğimi, 

	Yollarını gözlediğimi

	Geceme gündüzüme

	Hayalime düşüme

	Aldığımı anlat ona.

                Anlat....

     Mustafa KARAMELEK', 'BANA ONU ANLAT Bana onu anlat Gözlerinin, saçlarının rengini Boyunu,  endamını  Dilini, dişini, gülüşünü Ceylanları kıskandıran Yürüyüşünü a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bana-onu-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana bir sebep göster', 'bana-bir-sebep-goster-mustafa-karamelek-zyjsp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BANA BİR SEBEP GÖSTER

Sevginle, sevgiyi yakaladıysam, 

Gönlümü sevdaya, aşka saldıysam, 

Doğan güneşe yar diye baktıysam, 

Bana senden başka bir sebep göster.....

Goncamda, gülümde, nar çiçeğimde, 

Hem nefesimdesin, hem içtiğimde, 

Seni görüyorsam geleceğimde, 

Bana senden başka bir sebep göster...

Bazen, bir cennete dönüyor gönlüm.

Sonsuz mutluluklar doluyor gönlüm.

Sevdiyse sen diye hayatı gönlüm, 

Bana, senden başka bir sebep göster...

Derin  uykularda, renkli rüyalar, 

Gönül aleminde,  zevkli hülyalar, 

Benim oluyorsa bütün dünyalar, 

Bana, senden başka bir sebep göster.....

     Mustafa KARAMELEK', 'BANA BİR SEBEP GÖSTER Sevginle, sevgiyi yakaladıysam,  Gönlümü sevdaya, aşka saldıysam,  Doğan güneşe yar diye baktıysam,  Bana senden başka...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bana-bir-sebep-goster-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüldeki Özlem', 'gonuldeki-ozlem-mustafa-karamelek-1kwmf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GÖNÜLDEKİ ÖZLEM            

Bu gece önüme muhabbet masası kurulsun

İsterse masama sadece bade konsun

Karşımda bir de resmin olsun

Gözlerine baka baka içerim

Meze istersem namerdim..

İki yandan kırılsa kanadım kolum

Taş kesilse, felç’e uğrasa sol yanım

Sırat köprüsüne düşse yolum

Gözlerine baka baka geçerim

Kılavuz ararsam namerdim..

Arada bir geçip otursan karşıma

Gezmek için uğrasan gönül çarşıma

Bilsen ne sevdalar dökerim karşına

Gözlerine baka baka göçerim

İmdat istersem namerdim..

O gözler

O gözler ne öyle

O gözler

Yaşam çağlıyor ışıl ışıl

Huriler uçuşuyor usul usul

Gözlerine baka baka naçarım

Çare  ararsam namerdim....

Mustafa KARAMELEK', 'GÖNÜLDEKİ ÖZLEM             Bu gece önüme muhabbet masası kurulsun İsterse masama sadece bade konsun Karşımda bir de resmin olsun Gözlerine ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gonuldeki-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Burak', 'i-cimdeki-burak-muammer-celik-qqims', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cigaramda duman 

kıvrım kıvrım yükseliyor 

hasret torbaları gözlerimde 

her geçen gün daha büyüyor… 

Yüzümde anıların 

çizik çizik oluyor 

titrek bir ses 

kuruyan dudaklarımda 

her geçen gün daha çatlıyor… 

Çayımda buhar 

buram buram dağılıyor 

uzak, ırak varlığınla 

buruk bir sitem içimde 

her geçen gün demleniyor… 

İçimde bir burak 

ne dur dinliyor ne durak 

azgın bir yular ellerimde 

her geçen gün sıyrılıyor

iplerini ya kırdı, ya kıracak… 

10.06.2003

BirDeli', 'Cigaramda duman  kıvrım kıvrım yükseliyor  hasret torbaları gözlerimde  her geçen gün daha büyüyor…  Yüzümde anıların  çizik çizik oluyor  t...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/icimdeki-burak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufkumun Sonsuzluğunda...', 'ufkumun-sonsuzlugunda-namik-kemal-kara-qgfym', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durdum bir sahil kenarında, 

Baktım sonsuz ufka, 

Aşkıma ve gözyaşlarıma.

Kavuşmak bir hayaldi sanki, 

Belkide daha da ötesi! 

İmkansızı kabullenmesemde, 

İmkansız geliyordu birlikteliğimizin ihtimali.

Bu acılar kahrediyor yüreğimi.

Gözlerim her yerde seni arıyor, 

Fakat bununla yetiniyor.

Gözlerim sürekli gözlerini arzuluyor, 

Ama bu da yetmiyor.

Çaresizliğim hayatıma mani oluyor! 

Yaşama arzum, 

Sensiz geçen her dakikada, 

Bir gün daha azalıyor.

Varlığın karanlık gecemde bir güneş gibi ışık saçıyor.

Ama bir türlü yüreğimi ısıtamıyor.

İşte burda başlıyor imkansız birlikteliğimin yüreğimdeki sisi! 

Dağıtmaya ne nefesim yetiyor ne de gücüm.

Ooof...

Dermanım kalmadı ağlamaya.

Bu hayatta alıştım sanırım

İmkansızlığını yaşamaya! 

Belki bir başka yerde, bir başka zamanda, 

Farklı bir hayatta! 

Sakın unutma! 

Daima içimdesin, hayalin daima rüyalarımda, 

Varlığınsa; gözyaşlarımda, soluduğum havada, içtiğim sigarada, 

Ufkumun sonsuzluğunda...

(12.08.2003 Ordu)', 'Durdum bir sahil kenarında,  Baktım sonsuz ufka,  Aşkıma ve gözyaşlarıma. Kavuşmak bir hayaldi sanki,  Belkide daha da ötesi!  İmkansızı kab...', ARRAY['Türk Edebiyatı','Şiir','Namık Kemal Kara']::text[], 8.5, '{"poet":"Namık Kemal Kara","poet_slug":"namik-kemal-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ufkumun-sonsuzlugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutukluyum, yağamıyorum...', 'tutukluyum-yagamiyorum-muammer-celik-qi980', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bulut yüklü yoğun bir semadayım 

yağamıyorum, sana tutuklu kaldım

gönlüm kapalı, ama seni özlüyorum 

aşkın teknesinde seni yoğuruyorum 

Duygu yüklü yoğun bir gecedeyim 

kurtulamıyorum, gecede esaretteyim 

gözlerim kapalı, ama seni görüyorum 

odamın tavanında resmini okşuyorum

BirDeli

(doğum tarihi bilinmeyenlerden)', 'Bulut yüklü yoğun bir semadayım  yağamıyorum, sana tutuklu kaldım gönlüm kapalı, ama seni özlüyorum  aşkın teknesinde seni yoğuruyorum  Duyg...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tutukluyum-yagamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyen Ellerinde Tüm Sıcaklığım', 'usuyen-ellerinde-tum-sicakligim-muammer-celik-o9i2c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnız gecelerde yine sana baktım 

hasretini mehtaplı bulutlara yazdım

sahildeki dalgalara kendimi vurdum

deniz kızının elleriydi dokunduğum

Gözlerinden süzülüp yüreğine aktım, 

üşüyen ellerindeydi tüm sıcaklığım..! 

05.06.2003 

BirDeli

(Not: Tüm siir dostlarima. Siirlerinize uzun zamandir yazamiyorum, su günlerde ki yugunlugum yuzunden. Ama hepsini bir bir okuyorum)', 'Yalnız gecelerde yine sana baktım  hasretini mehtaplı bulutlara yazdım sahildeki dalgalara kendimi vurdum deniz kızının elleriydi dokunduğum...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/usuyen-ellerinde-tum-sicakligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Koydum Adını', 'gul-koydum-adini-i-brahim-bayraktar-q1t8y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlünün aynası gülen gözüne, 

Çiy dolu bakışlar yakışıyor mu? 

Bana ilham veren şirin sözüne, 

Gül koydum adını, gül ahu gözlüm.

Güzel gözlerinin yeri nerede? 

Işığı kaybolmuş, feri nerede? 

İçimi ısıtan nuru nerede? 

Gül koydum adını, gül ahu gözlüm.

Pınarların sevince aksın diye, 

Bakışın gönlümü okşasın diye,

Dolunay gibi aydınlatsın diye, 

Gül koydum adını, gül ahu gözlüm.

Deryadan deryaya uçar giderim, 

Zamansız, mekânsız göçer giderim, 

Gönlünden gönlüme geçen kederin,

Gül koydum adını, gül ahu gözlüm.

29.09.2003', 'Gönlünün aynası gülen gözüne,  Çiy dolu bakışlar yakışıyor mu?  Bana ilham veren şirin sözüne,  Gül koydum adını, gül ahu gözlüm. Güzel gözl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gul-koydum-adini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül ki Tadında Sevda', 'eylul-ki-tadinda-sevda-ethem-vayvayli-gwb4v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu ne mutluluk! 

görkemli şövalye havasında yüreğim.

eylül ki tadında sevda

kırılmış cevizlerle çiğnenmekte

şurup güzeli dudakların ardında

eylül ki tadında sevda.

29.09.2003', 'bu ne mutluluk!  görkemli şövalye havasında yüreğim. eylül ki tadında sevda kırılmış cevizlerle çiğnenmekte şurup güzeli dudakların ardında ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/eylul-ki-tadinda-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-bilal-yalcinkaya-o8xn2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne  zaman  görsem  sizde  mahzun bir  gölgeyi

Geçmişimi anımsarım  hayallerim   hep  öteyi

Görebilir miyim sizde  bir tebessüm  bilinmez

Görülmeyen  alınyazısıdır   bu  hiç  silinmez

Yaş yirmi beş diye, kaygısız olamam yarınlara

Azrail  dert dinlemez, çalmadan dayanır kapılara

Ömrün neresindeyiz, erkendir karar  veremem

Cahit Sıtkı düştü bu hataya ben peşin süremem.

      

Kırışan alnımın vadilerini  siz  hatırlatınız

Gençliğime püryan, dertlerime dert kattınız

Ne zaman geldiyse içimden çiğ bir tebessüm

Hemen karşıma çıktınız onu da siz  aldınız

Aynaların diline düşmeden  tez  davranmalı

Vakitken her dem çoluk çocuğa  karışmalı

Yarından tezi yok bugün görünse de erken

Geçmişe ağlarız, ne gelir bilmeden gelecekten

                                                                  

Yıllar,   takvimlerle   anlaşıp   geçmekte

Gün  geçtikçe  saçlarıma aklar  düşmekte

Gittikçe yaklaşmakta  hayatın  günbatımı

Belki bugün, belki yarın son  nabız atımı.', 'Ne  zaman  görsem  sizde  mahzun bir  gölgeyi Geçmişimi anımsarım  hayallerim   hep  öteyi Görebilir miyim sizde  bir tebessüm  bilinmez Gör...', ARRAY['Türk Edebiyatı','Şiir','Bilal Yalçınkaya']::text[], 8.5, '{"poet":"Bilal Yalçınkaya","poet_slug":"bilal-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aynalar-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün Misali', 'surgun-misali-bilal-yalcinkaya-h2k69', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Onsekizinde tanıştım apartmanlarla

Annemin diline yabancı olduğum kadar

Yabancı olduğum apartmanlarla

Hayata çocukluk ertesi yılarda başladım

Var say ki hiç çocuk olmadım ben

Yaşayamadığım çocukluğumu

Deniz bildiğim

Van gölünün soğuk sularına

Annemin nasırlı elleri gibi

Çatlak ve kurak

Muş ovasında kaybettim

Hep hayal ettim

Ben oynarken Süphan dağının

Bağdaş kurup beni seyretmesini

Hep hayal ettim

Ve benim sen diye hayallerim vardı.

Senin hayal etmediğin yerlerde

Yitik bir coğrafyanın virane sokaklarında

Gönlümün doğusunu bulduğum gün

Ülkenin batısında

Benim sen diye hayallerim

Senelerden kopup gelmişti artık

Yeryüzünün en yorgun coğrafyasının

T erini silmekle geçti ömrüm

Bu yüzden nasırlıdır ellerim

Ve yüreğim

İklimim serttir benim

Tutulmaz ellerim

Ellerim nasırlıdır benim

Izdırap coğrafyanın

Dert iklimini solukladım

Kenger kokulu baharlarda

Hayatımın bütün monotonluğunu

Perşembeleri okuldan izinli gittiğim 

Mapushane ziyaretleri bozuyordu

Yıllar sonra anladım

Kimliğimdeki yaraların şifresini

Ve yıllar sonra anladım

O günden kayıtlanmış yüreğim

Senin gözlerinde dinlenirken

İstanbul akşamları............ 

Ben toprak damlı bir odanın

Kerpiç duyarlı yoksulluğunda

Gamzeli yanakların

Mezarım olur ümidiyle

Her gün biraz daha

Uçurum uçurum gözlerinde

İntihara sürükleniyordum.



...Ve yine toprak damlı bir odada

Gaz lambasının düşük voltajında

Karanlığa boğulan gecelerime

Uzat gece sürgünü zeytin gözlerini

Şehirlerden ve sen den çok uzaklarda

Olağanüstü halin paslı pranga1arında

Çürüyen ömrüne............ 

Uzat ay misali hasret bakışlarını

Var say ki hiç şehir görmedim ben

Şehirleri küçük mezarlıkları büyük

Kayıp isimli dört yamalı bir ülke

İçimde sayısız nabız atışımdır

Fırat ve Dicle‘nin kıvrımları

Dicle’yi Fırat’a gelin etmiş atalarım

Asırlık kanın diyetidir Dicle

Düşman evine gider gibi

Giderken Fırat’ın kollarına

İçimde sayısız nabız atışımdır

Fırat ve Dicle’nin kıvrımları

Bir köylü kadının

Yoğurduğu hamur saflığında

Benim sen diye hayallerim vardı

Senin hayal etmediğin yerlerde

Yitik bir coğrafya’nın virane sokaklarında

Gönlümün doğusunu bulduğum gün

Ülke inin batısında

Benim sen diye hayallerim

Senelerden kopup gelmişti artık', 'Onsekizinde tanıştım apartmanlarla Annemin diline yabancı olduğum kadar Yabancı olduğum apartmanlarla Hayata çocukluk ertesi yılarda başladı...', ARRAY['Türk Edebiyatı','Şiir','Bilal Yalçınkaya']::text[], 8.5, '{"poet":"Bilal Yalçınkaya","poet_slug":"bilal-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/surgun-misali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nöbette', 'nobette-bilal-yalcinkaya-1kuy3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kanım da yüz elli promillik

Yokluğun, 

Gece sarhoş, ben virane

Dudaklarımda

Kaçıncı paketten

Olduğunu bilmediğim

Usul usul yanan bir sigara

Bir kibritin ucundaki alevle

Yanmaya hazır bedenim

Bütün acıların dert anası

Cehennem adayı yüreğim

Her biri bir köşeye dağılmış

Sana ait olan benliğim

Her şeyimle emrindeyim

Nöbetteyim nöbette', 'Kanım da yüz elli promillik Yokluğun,  Gece sarhoş, ben virane Dudaklarımda Kaçıncı paketten Olduğunu bilmediğim Usul usul yanan bir sigara ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Yalçınkaya']::text[], 8.5, '{"poet":"Bilal Yalçınkaya","poet_slug":"bilal-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nobette-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluk ve Sen', 'yokluk-ve-sen-bilal-yalcinkaya-argwt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gidişini hatırlatıyor

Her gıcırdayarak kapanan kapı

Yokluğunu haykırıyor

Sensizlik dolu, bomboş odalar', 'Gidişini hatırlatıyor Her gıcırdayarak kapanan kapı Yokluğunu haykırıyor Sensizlik dolu, bomboş odalar...', ARRAY['Türk Edebiyatı','Şiir','Bilal Yalçınkaya']::text[], 8.5, '{"poet":"Bilal Yalçınkaya","poet_slug":"bilal-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yokluk-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hıçkırık', 'hickirik-bilal-yalcinkaya-8rrg1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz her mevsim içimde sonbahar

Rüzgarın bütün hüznünü taşıyor yapraklar

Hazan düşse kırılsa da tüm dallarım

Kurumuş bir asa gibi, yine de seni beklerim

Her yerde bağ bozumu toplansa da meyveler

Sensizlik her mevsim dertlerime dert ekler

Çare bilmez yolların sürgünüyüm, gecelerin

Gurbetinde hasretim özlerim, gündüzlerin

Her gün batımı gönlümde solan çiçekler

Her giydiğin elbisenin desenlerinde filizlenir

Haberin bile olmaz yalnızlığı hecelerim

Yaradana yalvarıştır adressiz dilekçelerim

Bir gün yüreğimdeki ateş belki küllenecek

Ama küllerin altında köz hep yanacak

Derinden bir volkan hıçkırığı saracak bedenimi

Ve zamansız bir rüzgar savuracak küllerimi', 'Sensiz her mevsim içimde sonbahar Rüzgarın bütün hüznünü taşıyor yapraklar Hazan düşse kırılsa da tüm dallarım Kurumuş bir asa gibi, yine de...', ARRAY['Türk Edebiyatı','Şiir','Bilal Yalçınkaya']::text[], 8.5, '{"poet":"Bilal Yalçınkaya","poet_slug":"bilal-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hickirik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmekten Korkmuyorum!', 'olmekten-korkmuyorum-burcu-karakaya-hyxcu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğinizin kanadığını

Ve akan kanlarınızın

Bir hayat sulamadığını

Hatırlar mısınız hiç...

Yaşamdan ders almak için

Gücü parayla satın alabilir misiniz...

Hiç sevgi tomurcukları açtırıp

Kuruttuğunuz oldu mu ellerinizle...

Ve her kuruttuğunuz tomurcuk için

Tanrıya dua ettiniz mi...

Başınızı öne eğmenin 

Gülünç olduğunu düşünenlere inat, 

Hiç karınca saydınız mı yere bakıp...

Ve aslında

Çalışmanın bedel, 

Sevginin bedel, 

Arkadaşlığın ve dostluğun bedel, 

Kardeşliğin bedel, 

Hatta 

Kendinize kendinizin bile

Bedel olduğunu anladınız mı...

Hayatın yalan olduğunu bilip te

Yalan söyleyenleri kınadınız mı...

Hayatın oyun olduğunu düşünüp te

Oyun oynayanlarını kıskandınız mı...

Evet, herşeyi yaptınız

Yapamadığınız ve belki de yapmadığınız

Bir şey kaldı...

Ve bu da, 

Ölümün içinizde açtığı derin acıyı

Sarıpta, 

Onca anlamsızlığın ortasında

''Ölmekten korkmuyorum''

Demek ti! ...

29/09/2003

C.Burcu Karakaya

Antalya', 'Yüreğinizin kanadığını Ve akan kanlarınızın Bir hayat sulamadığını Hatırlar mısınız hiç... Yaşamdan ders almak için Gücü parayla satın alabi...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/olmekten-korkmuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komik İniş', 'komik-i-nis-burcu-karakaya-yo618', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün paraşütle kanat çırptı bedenim, 

Anlam yükleyemediğim boşlukta... 

Eşsiz bir sessizlik hakimdi, 

Yüreğim maviyle demlendi... 

Aklım kanatlandı 

Çığlık çığlığa bağırdım yaradana... 

Seviyorum seviyorummm! 

Aşağıdan bir ses yankılandı 

Abla ''''çekiyorum çekiyorum'''' 

Tekrar paraşütle kanat çırptı bedenim 

Anlamını keşfettim yanlızlığın 

Komik inişte... 

25/07/2003 

C.Burcu Karakaya 

Antalya', 'Bugün paraşütle kanat çırptı bedenim,  Anlam yükleyemediğim boşlukta...  Eşsiz bir sessizlik hakimdi,  Yüreğim maviyle demlendi...  Aklım ka...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/komik-inis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Kalbim!', 'ah-kalbim-ahmet-yilmaz-01-4tlhv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani kimseye vermezdin onu, 

Kimseyi yar etmezdin ona, 

Gördün ya bu işin de sonu, 

Atılıp satılmakmış zavallı kalbim! 

Eğer kendini bana bıraksaydın, 

Renkli hayallere hiç dalasaydın, 

Belki caydırır kandırır seni, 

Böyle harcatmazdım zavallı kalbim!', 'Hani kimseye vermezdin onu,  Kimseyi yar etmezdin ona,  Gördün ya bu işin de sonu,  Atılıp satılmakmış zavallı kalbim!  Eğer kendini bana bı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yılmaz 01']::text[], 8.5, '{"poet":"Ahmet Yılmaz 01","poet_slug":"ahmet-yilmaz-01","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ah-kalbim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-vedat-koparan-h9da7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kentler uykuya dalarken 

Gecelerim uyumaz 

Geceler anayurdum 

Gündüzleri mülteci olurum 

Üşüdüğümden değil 

Yokluğundan buz keser ellerim 

Düşlerim dalga, dalga sana köpürüp 

Gözlerim hep seni sorar 

Puslu gecelerde aydınlık suretini ararım 

Ülkem gibi severim seni 

Ülkem gibi kah acılı, kah direngen 

ve umutlarla 

Ülkem gibi med cezir. 

Çam sakızı kokularında ararken tenini 

Anayurdumda çam sakızı kokuların gelir 

Gecenin çukurunda sobelerim dudaklarını 

Susadım..! 

Nefesler kesilircesine 

Dudaklarında içmek isterim zamanı 

Sessiz bir çığlıktır gecede böğrüme saplanan 

Anılardır sarıldığım hani 

Yoksun-çoksun zamanlarında 

Saçlarım, sakalım daha bir uzadı, 

Gözlerim daha bir çökük avurtlarım gibi 

Yalnızlık dişlerini gösterdiğinde 

Yitik yankılarda kırılgan ışıklarda 

Sesini arıyorum 

Bulmayı nasılda iyi belledim oysa 

Yakınımdasın biliyorum 

Yüreğim! 

Bir el basımı uzaklığın.. 

Her ana yurdumda 

Bilmem kaçıncı uykunda iken 

Düşlerimle düşüne girerim 

Asi rüzgarlarla okşarım yüzünü 

Özlemle düşerim uçurumuna 

Sımsıcak sevgimi getirim sana 

İstersen darıl kız isyan et 

Hadi durma! 

Durma ne olur tut elimi 

Tut yüreğimi sarıl bana.. 

Vedat.K 29.09.2003', 'Kentler uykuya dalarken  Gecelerim uyumaz  Geceler anayurdum  Gündüzleri mülteci olurum  Üşüdüğümden değil  Yokluğundan buz keser ellerim  D...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sana-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecekmisin', 'gelecekmisin-melek-bagac-hf5g5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Suan benden cok uzaklardasin

Uzak oldugun kadar da yakin

Cünki suan sen yanimdasin

Düsüncemde aklimda benimlesin

Suan neler yapiyorsun

Neler düsüyorsun

Sende benim gibimisin

Sende beni düsüyorumusun

Suan benden cok uzaklardasin

Bende sana uzak oldugum kadar yakinmiyim

Bensiz olan seninlemiyim

Senin benimle oldugun gibi

Suan nerelerdesin bilmiyorum

Bildigim seni özledigim

Yolunu gözledigim

Gelmeni bekledigim

Gelecekmisin

Hissedecekmisin

Sevecekmisin

Bana benden yakin olacakmisin

Cumartesi 09.08.03   20.03', 'Suan benden cok uzaklardasin Uzak oldugun kadar da yakin Cünki suan sen yanimdasin Düsüncemde aklimda benimlesin Suan neler yapiyorsun Neler...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gelecekmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece bir tebessüm', 'sadece-bir-tebessum-melek-bagac-nuxg9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ilk seni rüzgar gibi eserken gördüm

Gördüm ve firtinalar koptu

Icimi günes gibi sicacik sardin

Ve ben seni sevdim

Benim gülen yüzüm 

Hasretle beklenen özlemim

Dayanilmaz tutkum oldun

Suan sensizim üsüyorum

Sen yoksun karanliklar icindeyim

Biraktigin sensizliginle kaybettigim benleyim

Sende kaybettigim kendimle 

nerden bilebilirdim  kendimi sende kaybedecegimi

karanlik  isiz sokaklarda kaybettigim seni arayacagmi

kolaymi bana cikmayan yollarda seni aramak

seni bulamayacagimi bildigim yollarda

Yoklugunla yaktigin bir ates

Rüzgar gibi esip gectigin hayatimda

Artik hatirladigimda sadece güzel bir tebessüm

Sadece bir tebessüm kadarsin', 'Ilk seni rüzgar gibi eserken gördüm Gördüm ve firtinalar koptu Icimi günes gibi sicacik sardin Ve ben seni sevdim Benim gülen yüzüm  Hasretl...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sadece-bir-tebessum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O sen olurmusun', 'o-sen-olurmusun-melek-bagac-advb7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O sen olurmusun

Suan aklimdasin seni düsüyorum

Sende benim gibi beni düsüyormusun

tebessüm sariyor seni   düsündügümde

biliyormusun sende vazgecilmez oldugunu artik benim icin

Seni düsüyorum

Seni düsündügümde mutlu oluyorum

Sende beni düsündügünde mutlu oluyormusun

Mutluluk seni düsünmek mi 

Insanlar ne cözülmez bazen degil mi

Bazen olmamasi gerekenleri yaparlarlar

Kaptirip giderler kendilerini bilinmeze dogru

Peki  ben kendimi sana kaptirisam nereye dogru giderim

Suan seni düsünyorrum icime sicacik doguyorsun

Gözlerimi kapattim mavi denizlerin üstüne dogru gidiyorum

Dalgalari gectikten sonra sana dogru geldigimi hissetdiyormusun

Seninle olmasamda seninle oldugumu biliyormusun

Bana her daim acan yüregim 

beni sarip isitan günesim 

Seni benle dolduran 

 Beni yakan sevdam olurmusun

04.08.03', 'O sen olurmusun Suan aklimdasin seni düsüyorum Sende benim gibi beni düsüyormusun tebessüm sariyor seni   düsündügümde biliyormusun sende va...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/o-sen-olurmusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-melek-bagac-frtmp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aklimda sen

Düsüncemde sen

Hayalimde sen

Benle sen

Gecem seninle

gündüzüm seninle

Her anim seninle

Hayatima sessice giren senle

Sensiz olamayan ben

Seni yücelten ben

Seni yasayan ben

Seni seven ben

Farkinda olmadan hayatima giren sen

 Aliskanlanlik yapan sen

Sensiz yapamayacagini hisseden beni

Biliyor ve hissediyormusun sen

09.08.03   19:38', 'Aklimda sen Düsüncemde sen Hayalimde sen Benle sen Gecem seninle gündüzüm seninle Her anim seninle Hayatima sessice giren senle Sensiz olama...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-291-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ben ve biz', 'sen-ben-ve-biz-melek-bagac-w701b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen

Güzel bir insan

Güvenen bir insan

Sicacik bir insan

Ben

O güzellikleri gören

Seni anlayan

Seni seven

Biz

Iyi vakit geciren

Zamanin nasil gectigini anlamayan

Sadece iki iyi bir dost', 'Sen Güzel bir insan Güvenen bir insan Sicacik bir insan Ben O güzellikleri gören Seni anlayan Seni seven Biz Iyi vakit geciren Zamanin nasil...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-ben-ve-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve ben', 'sen-ve-ben-melek-bagac-yhsff', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen ve ben 

Sen ve ben

Tanistik 

Konustuk

Anlastik

Ilgi duydum

Hoslandim

Sevdim

Anlasilmamak icin mi

Incindim 

kirildim

yoruldum

Iyimser oldugum icin mi

Degistin

Uzaklastin

Sogudun

Anlamadigin icin mi

Anlamak 

Anlasilmamak

Yanlis anlamak, anlasilmak

Neden bu kadar acitiyor

Dün güzel

Bugün cok zor

Yarin bilinmeyen

Ve sen artik yarindan ötesin', 'Sen ve ben  Sen ve ben Tanistik  Konustuk Anlastik Ilgi duydum Hoslandim Sevdim Anlasilmamak icin mi Incindim  kirildim yoruldum Iyimser old...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-ve-ben-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanidigin o mu', 'tanidigin-o-mu-melek-bagac-gh2x7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanidigin o mu

Beni  tanidigini biliyormusun 

Yada bildigini taniyormusun

Hic tanidigini düsündün mü

Yada düsündügünü tanidin mi

Senin bildigin sandigin senin düsündügün mi

Yoksa düsündügün  zaten bildiklerin mi

Hep bu ikilemi yasadin mi 

Gel gitler kararsizliklar

Ve simdi peki simdi

Ne kadar eminsin

Bildigin 

Düsündügün

Tandigin o mu?', 'Tanidigin o mu Beni  tanidigini biliyormusun  Yada bildigini taniyormusun Hic tanidigini düsündün mü Yada düsündügünü tanidin mi Senin bildi...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tanidigin-o-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni bir seyler', 'yeni-bir-seyler-melek-bagac-z6xas', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeni bir seyler

Yeni bir seyler yazmak istiyorum

Yeni bir güne baslar gibi

Beyaz sayfalara güzel sözler yazmak  istiyorum

Ayni haytimda bembeyaz günlere yürümek  gibi

Kalemimi elime aldim ve basladim

Basladim yürümeye güzel mavi bulutlara dogru

Günesi gördüm gülümsedi bana

Basladim düsüncelerimi dökmeye satirlara 

Yaziyorum artik, hayat seni seviyorum

Sana uzaktan bakmiyorum artik seni yasamaya karar verdim

Baslamkmis zor olan  ve gördüm simdi zor degilmis

Sözlere yeni anlamlar heyecan katmali 

Hayatin beni yeniledigi, beni yeniden heyecanlandirdigi gibi

Yazmak haykirmak istiyorum düsüncelerim, 

hayata haykirmak gibi

Elimdeki kalem degil yazilar yazan 

Benim hayati yeniden yazan ve yasayan', 'Yeni bir seyler Yeni bir seyler yazmak istiyorum Yeni bir güne baslar gibi Beyaz sayfalara güzel sözler yazmak  istiyorum Ayni haytimda bemb...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yeni-bir-seyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-burcu-karakaya-c73hl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey sevgili, 

Nedendir sana bu kadar yakınlığım! ...

Nicedir, 

Duygularımın mantığımı kamuflajı! ...

Nedendir, 

Kalbimde büyüttüğün papatyanın

Bu sonbahara aldırmayışı

Ve

Yapraklarına konan minik kelebeğin

Her ''''seviyor''''u farklı algılayışı! ...

Niçindir, 

Sessiz geçen günlerin senle doluşu

Bu kudurmuş insanlık okyanusunda

Sakin duruluğun, adil dövüşün.

Ne güzeldir, 

Gerçek ''''sen''''in ''''ben''''i buluşu

Sana söylüyorum ey prens! 

Al tut ellerimi

Tut ve çek bedenimi denizlerine...

Dudaklarının her hayat verişinde

Biraz daha hissedeyim tutkunun ateşini

Büyülü bir melodi fısılda gözlerime

Her sevişmemizde

Bir parçamız daha erisin bedenlerimizde

Ve en güzel dansını yapsın derinlerde

Aşkımızın dansını! 

Bırakma prensim ellerinden

Şehvetimizin yıldızını... 

01/11/2000

C.Burcu Karakaya

İzmir', 'Ey sevgili,  Nedendir sana bu kadar yakınlığım! ... Nicedir,  Duygularımın mantığımı kamuflajı! ... Nedendir,  Kalbimde büyüttüğün papatyanı...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevgiliye-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şüpheci Olma', 'supheci-olma-rafet-maden-mebgg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varlığının kıymetini biliyorum, 

Ne olur bir tanem şüpheci olma.

Yuvamız için hergün çalışıyorum,

Ne olursun sevgilim şüpheci olma.

Hiçbirşey düşünmem inan,

Hep o gözlerin hayalimde kalan,

Hiçbir sözümde arama yalan,

Ne olursun artık şüpheci olma.

Hayalin hiç aklımdan çıkmaz,

Seni sevmekten kalbim bıkmaz,

Senden başkasına asla bakmaz,

Ne olursun güzelim şüpheci olma.

1998', 'Varlığının kıymetini biliyorum,  Ne olur bir tanem şüpheci olma. Yuvamız için hergün çalışıyorum, Ne olursun sevgilim şüpheci olma. Hiçbirşe...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/supheci-olma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece bir rüya', 'sadece-bir-ruya-erhan-ergun-7p1o5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah be Sevdigim gölün basinda oturuyorum

ve günes batimini seyrediyorum.

Sende yanima geldin ve oturdun, 

sigindin kucagima, saclarini oksuyorum

ve seni nekadar Sevdigimi anlatiyorum.

Birden etrafimda hersey kayipoluyor, 

uyandim ve anladimki sadece bir rüya görmüsüm.

Agliyorum her gece, cünkü gördügüm  gercek degil.

Neden gercek olamiyor gördüklerim, Sevdigim?', 'Ah be Sevdigim gölün basinda oturuyorum ve günes batimini seyrediyorum. Sende yanima geldin ve oturdun,  sigindin kucagima, saclarini oksuyo...', ARRAY['Türk Edebiyatı','Şiir','Erhan Ergün']::text[], 8.5, '{"poet":"Erhan Ergün","poet_slug":"erhan-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sadece-bir-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece rüya', 'sadece-ruya-erhan-ergun-ytqqw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah be Sevdigim gölün basinda oturuyorum

ve günes batimini seyrediyorum.

Sende yanima geldin ve oturdun, 

sigindin kucagima, saclarini oksuyorum

ve seni nekadar Sevdigimi anlatiyorum.

Birden etrafimda hersey kayipoluyor, 

uyandim ve anladimki sadece bir rüya görmüsüm.

Agliyorum her gece, cünkü gördügüm  gercek degil.

Neden gercek olamiyor gördüklerim, Sevdigim?', 'Ah be Sevdigim gölün basinda oturuyorum ve günes batimini seyrediyorum. Sende yanima geldin ve oturdun,  sigindin kucagima, saclarini oksuyo...', ARRAY['Türk Edebiyatı','Şiir','Erhan Ergün']::text[], 8.5, '{"poet":"Erhan Ergün","poet_slug":"erhan-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sadece-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus', 'sus-bayram-ustundag-twyqg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Değişirken her eşyanın giysisi, 

İnsanın dünyaya açılan penceresinden, 

Sanki bir kabus görüyormuş gibi, 

Kaçarız hep, acı veren o gerçeklerden...

Daralı ufkumuz ayırt etmekle hayatı, 

Farkında olmasak da hiçbir zaman! 

Asıl ufkumuzu daraltan biziz, 

Dünyaya o açılan pencerelerden...

Yükleriz gözyaşlarına en ağır sitemleri

Şimşekler çakar sessiz bir şehirde, 

Ve bir zaman olur haykırmak istesek de

Sanki gaipten “SUS”der biri...', 'Değişirken her eşyanın giysisi,  İnsanın dünyaya açılan penceresinden,  Sanki bir kabus görüyormuş gibi,  Kaçarız hep, acı veren o gerçekler...', ARRAY['Türk Edebiyatı','Şiir','Bayram Üstündağ']::text[], 8.5, '{"poet":"Bayram Üstündağ","poet_slug":"bayram-ustundag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sus-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Güzeli', 'guz-guzeli-bekir-mutlu-gokcesu-iu7jh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarışın

Gökyüzü mavisi gözleri

Baharı da andırır, işveli

Cazibe, endam yerinde

Deniz kokar yanık teninde

Yazdan kalma güz güzeli

Savurarak geçer eteklerini

Eylül güzeli bir gündür

Geçen penceremin önünden 

Ağaçlar dem vurur hala yeşilden

Kına yakmış yapraklar kimi 

Evlendireceklermiş Eylül ile Ekim’i 

Gelin olacakmış afet; güz güzeli', 'Sarışın Gökyüzü mavisi gözleri Baharı da andırır, işveli Cazibe, endam yerinde Deniz kokar yanık teninde Yazdan kalma güz güzeli Savurarak g...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/guz-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-bayram-ustundag-bepbj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevsiminde yağan bu kar, vuslatımı perçinledi...

Buğulu camlardan uzaklara mıhlandı gözlerim.

Bir nida yankılandı kalbimin kuytu  köşesinden.

Gökler sitemimin rengiyle boyandı...

İçim içime sığmıyor, tarifi zor halimin..! 

Bir bedevi gibi yaşıyorum, yardan uzak bir şehirde...

Hatıralar göz yaşlarımla bir imgeye dönüştü.

Nerdesin yar, sana varan yollarıma karlar düştü..! 

25.12.2001', 'Mevsiminde yağan bu kar, vuslatımı perçinledi... Buğulu camlardan uzaklara mıhlandı gözlerim. Bir nida yankılandı kalbimin kuytu  köşesinden...', ARRAY['Türk Edebiyatı','Şiir','Bayram Üstündağ']::text[], 8.5, '{"poet":"Bayram Üstündağ","poet_slug":"bayram-ustundag","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozlem-120-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-bayram-ustundag-degmj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Devran döne dursun, devam etsin yine çiçekler açmaya...

Kırmızı bir gül anlatsın yine sana söyleyemediklerimi, 

buruk bir veda, birkaç damla gözyaşı anlatsın yine ayrılığı, 

ama her yalnızlık  onu hatırlatmalı sana, işte o zaman haykırmalı! ..

vuslatını perçinleyen halden anlamaz yollara haykırmalı.! 

ve bir kibrit çakmalı bitip tükenmek bilmeyen ümitlere, 

yahut ondan kalan her şeyi  bir kağıt gibi yakmalı.

ey benim mahkum gönlüm söyle seni ne yapmalı! ! ! 

Kimsesiz olaydın, virane kalaydın keşke bu derde beni koymasaydın...

Uçan bir kuş olaydım kanadımı kıraydın keşke bu derde beni koymasaydın.

Gökler senin kadar ağır gelmezdi sırtımda taşısaydım eğer, 

bir kurşun bile senin verdiğin kadar acı vermezdi, 

bir sarhoş olsaydım bu kadar aşağılanmazdım, 

bir kilim olsaydım bu kadar çiğnenmezdim ayaklar altında, 

ateş bile senin kadar yakmazdı beni...

ey gönül beni öyle bir ateşe attın ki..! 

Yanıpta kül olaydım, ateşinle kavrulaydım keşke bu derde beni koymasaydın..

''Keşke''', 'Devran döne dursun, devam etsin yine çiçekler açmaya... Kırmızı bir gül anlatsın yine sana söyleyemediklerimi,  buruk bir veda, birkaç damla...', ARRAY['Türk Edebiyatı','Şiir','Bayram Üstündağ']::text[], 8.5, '{"poet":"Bayram Üstündağ","poet_slug":"bayram-ustundag","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/keske-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyimser bir şiir bu', 'i-yimser-bir-siir-bu-gok-tengri-gnk23', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi okul olmasa

Alıp başımı gitsem

Ya Ege ovalarına

Ya Toroslara

Anadolum içinde kaybolsam

Kaybolsam da kimse bulamasa beni

Geride bırakacağım çok şey de yok zaten

Arkadaşmış, dostmuş

Bir iki tanesi dışında 

Hepsi yalan...

Ya ben yalan ettim onları

Ya da hep yalandı dostlukları

Fark edemedim

Küskün değilim hiç bir şeye, hiç kimseye

Ne benim beklediklerim olmuyor; 

Ne de onlar gibi değilim diye..

Kimseye laf sokup sokuşturduğum da yok

İyimser bir yazı bu

İyimser bir dilek

Akarsular gibi iyimser

Elbet denizi bulacağını bilen akarsular gibi...

Hani insan araştırır ya her şeyi, sorgular

''Neden, niye'' lafları eksik olmaz dilinden

Hartalara bakıyorum çekiyor beni Anadolu

Annemin yüzüne bakıyorum; çekip gidemiyorum

Yani kısılmışım bir kapana

__________Ne yapsam ne etsem bilemiyorum

İşte insan bırakıyor bu halde düşünmeyi

Nafile.. Gideceği bir yer yok; 

Demekten başka bir şey kalmıyor ki:

''Mevlam ne eylerse güzel eyler''*

*Anadolu Halk Ozanı Yunus Emre''nin dizelerinden

27Mart2003; Perşembe', 'Şimdi okul olmasa Alıp başımı gitsem Ya Ege ovalarına Ya Toroslara Anadolum içinde kaybolsam Kaybolsam da kimse bulamasa beni Geride bırakac...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/iyimser-bir-siir-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-i-brahim-atilmis-0dojm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kardelen? 

kardelen ne demek mi yavrum? 

hani tabiat ana çevirirya mevsimleri ardın sıra, 

hani yemyeşil elbisesini 

usul usul çıkarırda toprağın sırtından

hani sararan benzi 

birden bire beyazlanırya zemheride, 

bilirsin! 

hani lapa lapa karlar yağar

santim santim kar kaplanırya her taraf

işte! 

o kalın kar örtüsünün altından

başını gök yüzüne, 

özgürlüğe uzatan tek çiçektir...', 'Kardelen?  kardelen ne demek mi yavrum?  hani tabiat ana çevirirya mevsimleri ardın sıra,  hani yemyeşil elbisesini  usul usul çıkarırda top...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kardelen-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülme Bebeğim', 'uzulme-bebegim-ugur-oguz-sahin-0e7dn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen üzülme 

Yarın güneş doğar

Sen üzülme

Mutluluk hasreti boğar

Sen düşünme

Yarın bir çiçek açar

Rüzgâr keser

Yine yağmur yağar

Sen incinme

Yazgı kader içinde

Sar sarmala sevgiyi

Yaşam sevgi gücünde', 'Sen üzülme  Yarın güneş doğar Sen üzülme Mutluluk hasreti boğar Sen düşünme Yarın bir çiçek açar Rüzgâr keser Yine yağmur yağar Sen incinme ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzulme-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül''e', 'eylul-e-serkan-dogan-10ecj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir eylül parmağı var bu işte

biliyorum

gelmeyecek ama

hatırlamayacak da

gölge oyunu muydu bu yaptığı

eylülün bana

kıyasıya kanayarak

karşılıklı çatışmalarda 

ölmüştü penceremden

doyasıya izlediğim

bulutlar ve dolunay

sarıkamıştan dönüşüm

dokuzu beş geçe, eylülün başı

savaş bitmiş, sakın şaşma

mahmurlar garında karşıla 

ikilemelerin tesadüfleriyle

sıkışık hayatlar yaşıyoruz

daha sona tam erişmeden

yeni baştan başlıyoruz

darılmasın şehrim ankara

karsa kıyasla yakındı bana 

hava bozdu bozuldu 

karardı darıldı 

bir boran bir sağanak

gönlüm ta ortadan yarıldı', 'bir eylül parmağı var bu işte biliyorum gelmeyecek ama hatırlamayacak da gölge oyunu muydu bu yaptığı eylülün bana kıyasıya kanayarak karşıl...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/eylul-e-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örtülü ve kırmızılı', 'ortulu-ve-kirmizili-serkan-dogan-sadsw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir

Elizabeth ya da Catherine

hasılı kırmızılı kadınsın

kurtarırsa beni 

upuzun uzuvların

gülücükler yoklayan dudaklarınla

kalbimin toprağında yeşeriyorsun

kuşların götürdüğü özgürlüğüme

gizlenmiştim sanma

ikirciklendiren seni

belli başlı başka şeylerdi

tanımadık ki birbirimizi

görmeden inanmam

ve satırlarını duymadan

topallıyor zira beyinciğim

ruh yalnızlığın akrebidir çünkü

yeryüzünün tüm çukurlarında.

iki

şenlikli evimizde bizleri bir görebilseydin

doğulu öyküler anlatır sonra kaçar

hayranlıkla dağlarına sığınırdık ya

bahsettiğim, bu simyacı yabancı

gerçeğin güneşe bakan en güzel yüzü

tercihler maratonu devam ederken

ne söyleyeyim, örtünün altındayız

örtü kalktığında, burada olmayacağız.', 'bir Elizabeth ya da Catherine hasılı kırmızılı kadınsın kurtarırsa beni  upuzun uzuvların gülücükler yoklayan dudaklarınla kalbimin toprağın...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ortulu-ve-kirmizili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'I am not the angel of this city', 'i-am-not-the-angel-of-this-city-serkan-dogan-m0268', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şehrinizden biriyim

iki yüzüm var sizin gibi biri

içime çevrili diğeri çamura

denizi severim çölü de sevdiğimde

taşı toprağı ve parayı

yıkamadan koyarım cebime

elbisemin temizliği bir yana

yana yakıla 

solurum caddelerin iğrenç havasını

günahları siner yüzüme

utanırım, ancak eve gittiğimde

ben de sizin kadar yabancıyım

kalıntısı kalmayan insanlık onuruna

ama, hayır, hürüm de ruhlar meşherinde 

şehrinizden değilim', 'şehrinizden biriyim iki yüzüm var sizin gibi biri içime çevrili diğeri çamura denizi severim çölü de sevdiğimde taşı toprağı ve parayı yıkam...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/i-am-not-the-angel-of-this-city-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'My love is my love', 'my-love-is-my-love-serkan-dogan-ub5ua', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gölgenin ağzında yankılandı yalanlarım

ikilemlerle sevişen kara kaplı defterimde hüzün

kederli demlerinden sıyırdı beni gamlı günlere

serdi emrine râm olunan sultanın elifine

yalın yalnızlıklarla örtüşürdü akşamlarım

ve yıkık bir çocuk bahçesiydi yüzün

tam da ortasındayız, ikimiz, geceyi ayıran ikiz karanlıkların

şarkılar çıktı ağzımdan seni söylerken çıktı canım

dilimi kilitlerdi bana bakarken ettiğin bir sözün

yaşlı alışkanlıkları bir bir çözüveren ellerin

kifayetsiz kalırdı ama onlarda dağılan senelere

değmez gibidir anlamsız gelir diye diye

gölgeler de inceldi dibe yalanlandı yankılarım', 'gölgenin ağzında yankılandı yalanlarım ikilemlerle sevişen kara kaplı defterimde hüzün kederli demlerinden sıyırdı beni gamlı günlere serdi ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/my-love-is-my-love-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Afrika', 'afrika-serkan-dogan-a0wzd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gelme bana afrika, gelme üstüme

sana küçük gelir dedim bu yaka

zenci iskelelerine yanaşıp kıtanın, adanın

siyah bakışlarından kumsallar soyacağım

ırkçı güneyine inat, kuzeyine aşık olacağım

gelme bana afrika, çarpma bana

kesik iskeletleri parçalanan

kamboçyalı maymunlarına tapınma', 'gelme bana afrika, gelme üstüme sana küçük gelir dedim bu yaka zenci iskelelerine yanaşıp kıtanın, adanın siyah bakışlarından kumsallar soya...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/afrika-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İllaki', 'i-llaki-hakan-ak-xb4dh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En doğrusu olmalı dimi? 

dimi değil değilmi? 

hadi diil de...

duygularım gibidir dilim.

ne mutlu ki bana 

illakisiz birşeylerim 

ve, var hala diyebildiklerim

anlayabilenlerim var hala

illaki olacaksa şayet

bende böyle durmamalı

yakışmayacak kadar olmalı

öyle basit değilli diili bilenlerim

sığarmı sonra sana

yetermi onlarınkisizlerine 

ve başka herkezin

anlayabilebilemediklerine

duygularım gibidir dilim

bazen ben söylerem

bazen ben dinlerem

ne kadar da illakidir aşkım 

kelimeler dudak aralarında

ifadesi hala çözülememişliğiyle

buz gibi, alev, kan, can tutmuşluğuyla

susabilirmi illaki şekliyle

ben ve benden ötürü herbirşeyim

bu gün kızgınım anlayabilenlerim

bu gün dargın...daraltamam şiiri 

ya susmalı yada illaki yazmaklıyım

başka türlü yazsaydım hem

anlarmıydı duygu yüklü, 

şair kıskandıran

illaki deli sevdam.', 'En doğrusu olmalı dimi?  dimi değil değilmi?  hadi diil de... duygularım gibidir dilim. ne mutlu ki bana  illakisiz birşeylerim  ve, var hal...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ak']::text[], 8.5, '{"poet":"Hakan Ak","poet_slug":"hakan-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/illaki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvar', 'duvar-serkan-dogan-1gk4r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'duvar bedenime dayalı mezar

taşları taşındıkça karşımda aşınan 

sarıya boyalı karmaşanın şahidi odalar

cinayet mahallinde ayak izleri bulunan', 'duvar bedenime dayalı mezar taşları taşındıkça karşımda aşınan  sarıya boyalı karmaşanın şahidi odalar cinayet mahallinde ayak izleri buluna...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/duvar-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prova', 'prova-serkan-dogan-djh5g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yeryüzünün şehvetine esir

bireysel tutkuların ucunda

bir yanlışlık şaheseriydi

tevellüdüm ve ölümüm

ikisi de aynı yolda

ikisi de çırılçıplak, karanlıkta

ve ağlama doluydu sokakları

dargın değilim uzaklara

intihar provası, kısa nefes

masa başında bir semaver sessizliği

ve ilaç şişeleri, kutular

alkış yüklüydü hava ama sis

bundan sonrası otopsi sonrası ışık

toplumsal acılara gebe yılışık korkular', 'yeryüzünün şehvetine esir bireysel tutkuların ucunda bir yanlışlık şaheseriydi tevellüdüm ve ölümüm ikisi de aynı yolda ikisi de çırılçıplak...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/prova-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar-delen', 'kar-delen-serkan-dogan-xr4w4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kar olur yağar sevindirir

direnişine güç katar insanın

kar olur mevsimi belirler

yağdı mı sonudur nisanın

kar olur adamı olgunlaştırır

yaşantısına farklı bir renk katar

kar olur isyankarlığa sevk eder

karamsar yapar onu katil yapar', 'kar olur yağar sevindirir direnişine güç katar insanın kar olur mevsimi belirler yağdı mı sonudur nisanın kar olur adamı olgunlaştırır yaşan...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kar-delen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Saddam', 'sair-saddam-ensar-aktas-sbijb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Parayla şan olmaz

Zorbalıkla iman

Bu dünya sana da kalmaz

Sanmaki Bağdat hep sütliman

Silahla barış olmaz

Kalemle savaş

Tepene binerler anka gibi

Erirsin mum misali yavaş yavaş

Benden lider olmadığı gibi

Senden de şair olmaz

Edersin bir kemküm, iki laklak

Gidersin tepetaklak

Rotterdam,28-09-2003', 'Parayla şan olmaz Zorbalıkla iman Bu dünya sana da kalmaz Sanmaki Bağdat hep sütliman Silahla barış olmaz Kalemle savaş Tepene binerler anka...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sair-saddam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece...', 'gece-fatime-gokcen-oi31a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hüzün kokuyor yine gece...

yıldızların büyülü zemheresinde, sessizliğin sesinde sen

gece soğuk, üşüyor ellerim

koca bir yangından arta kalanları bağrıma süpürdü rüzgar..

üşüyor ellerim, yanıyor yüreğim..

uykuyu unuttu, sevdayı yeşil gözlerinde yudumlayan gözlerim..

hep bir yangına tutulmuşum..

ama..karda açan çiçeği unutmuşum..

her kar tanesini soğuk sanırdım

kardelene hayat veren, eriyen kar tanesinin serin busesiymiş..

avuçlarımda kurumuş hazan sarısı güller..

hala sevdayı kokuyor

yalnız damarlarında susuzluğun acısı..

yüreğimde seninle doğacak vuslatın sancısı..

gece soğuk, üşüyor ellerim..yanıyor yüreğim..', 'hüzün kokuyor yine gece... yıldızların büyülü zemheresinde, sessizliğin sesinde sen gece soğuk, üşüyor ellerim koca bir yangından arta kalan...', ARRAY['Türk Edebiyatı','Şiir','Fatime Gökçen']::text[], 8.5, '{"poet":"Fatime Gökçen","poet_slug":"fatime-gokcen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gece-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dizelerim Ellerim Benim!', 'dizelerim-ellerim-benim-naime-erlacin-bqs91', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gülüşümde kekik kokusu 

taşıyacağım size dağlarımdan

ruhumun gizli saklı 

koyaklarını okutacağım satır satır

özgür yeleli meleklerin 

tel saçında saklayacağım baharlarınızı

ana nefesi kadar yumuşak

sevda nefesi gibi sıcak eseceğim içinizden

destanlarda bulacaksınız izlerimi

henüz yazılmamış senfoniler dinlerken

bırakmalısınız şiirin akarına 

şiirin su yoluna düşlerinizi

beklerken siz 

başkaldırarak güçlenen

ve giderek güzelleşen gölgenizi

ruhunuza dokunacağım 

kekik kokulu çıplak ellerimle

unutmayınız! 

dizelerim nefesim

dizelerim ellerim benim! 

(29 Eylül 2003)', 'gülüşümde kekik kokusu  taşıyacağım size dağlarımdan ruhumun gizli saklı  koyaklarını okutacağım satır satır özgür yeleli meleklerin  tel sa...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dizelerim-ellerim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Yaşıyah', 'aski-yasiyah-fatime-gokcen-x7u8t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'birşey ögrendim

gel değişik sevah

sen beni sev ben seni sevim

sevdayı yaşıyah

sen benim için yan 

ben seni severah yanim dutuşim

platonik aşk neyse oni yaşıyah

yada sen sevme

ben sene sevdalanıp dolaşim

platonik aşk neyse oni yaşıyah

sevdada oturah, yiyah içah

ele olahki kan kusak

tombilik aşk neyse oni yaşıyah

istersen sevdandan kendimi kesim

sağımi solimi doğriyim biçim

psikopatik aşk neyse oni yaşıyah

dur ben kerem olim, sen asli

sonumuz ele bitsin yasli

nostaljik aşk neyse oni yaşıyah

ele sevahki gara sevda olah

zencilere benziyah, gapgara olah

gara aşk neyse oni yaşıyah

yalan söylemiyah hep doğri diyah

beraber oturah beraber yiyah

realist aşk neyse oni yaşıyah

birbirimize türki söyliyah mizildiyah

elele tarlalarda bostanlarda gezah

romantik aşk neyse oni yaşıyah

kediyi gudiyi sen diye sevim

sende horozi culluği ben diye sev

otantik aşk neyse oni yaşıyah

elele tutuşah, birbirimize bağlanah

elektiriğe tutunah zangır zangır titriyah

sanal aşk neyse oni yaşıyah

sen beni sevirsen bilirem, bende seni

ele pustlukları bırahah hakket sevah

adam gibi sevah, aşkı yaşıyah', 'birşey ögrendim gel değişik sevah sen beni sev ben seni sevim sevdayı yaşıyah sen benim için yan  ben seni severah yanim dutuşim platonik aş...', ARRAY['Türk Edebiyatı','Şiir','Fatime Gökçen']::text[], 8.5, '{"poet":"Fatime Gökçen","poet_slug":"fatime-gokcen","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/aski-yasiyah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeğim...', 'cicegim-cemal-safi-xybjk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çiçeğim, bir misal var, eski atasözü, 

Zararın neresinden dönersen kâr çiçeğim.

Senin hayat çağının henüz baharı, yazı, 

Benim ömür bahçeme kar düştü, kar çiçeğim...

Baktığım her aynada aldığım tek uyarı, 

Terk etmen yakın diyor dünya denen  diyarı.

Renk düştü grubuma altın saçından sarı, 

Menekşe gözlerinden mor düştü, mor çiçeğim...

Sebebini ararsan ağlamaklı sesimin, 

Elveda bestesidir sana olan hissimin! 

Bahçeleri süslerken senin kiraz mevsimin, 

Benim ömür payıma nar düştü, nar çiçeğim...

Hiç sevip sevilmedim derken şansım değişti, 

Gönlümün imdadına bakışların yetişti.

Senin lâle devrine billur jaleler düştü, 

Benim kasımpatıma kır düştü, kır çiçeğim...

Uyanıp bir rüyanın rengarenk yatağından, 

Ayrılmak ne kadar zor sımsıcak kucağından.

Dünyadan giderayak öptüğüm dudağından, 

Yüreğime aşk denen kor düştü, kor çiçeğim...

Seninle gezemedim, çıkmadım bir tarafa, 

Dile düşeriz diye görünmedim etrafa.

Utancım mâni oldu aşkımı itirafa! 

Yüzüme ateş düştü, ar düştü, ar çiçeğim...', 'Çiçeğim, bir misal var, eski atasözü,  Zararın neresinden dönersen kâr çiçeğim. Senin hayat çağının henüz baharı, yazı,  Benim ömür bahçeme ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cicegim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz İki Gün', 'sensiz-i-ki-gun-cemal-safi-99lka', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nere gizlendimse aşikâr oldum

Hedefte gördüler sensiz iki gün

Dertler avcı oldu, ben şikâr oldum

İnsafsız vurdular sensiz iki gün.

Gözlerde avcıya yaranmak hazzı

Zevkten dört köşeydi hepsinin ağzı

Üstüme atıldı yüzlerce tazı

Başımda durdular sensiz iki gün.

Ayağıma prangalar taktılar

Gözlerimi dağladılar yaktılar

İki koldan, bir alnımdan çaktılar

Çarmıha gerdiler sensiz iki gün.

Kâle almadılar dileklerimi

Yaraslar emdi iliklerimi

Bükülmez sandığın bileklerimi

Kırk yerden kırdılar sensiz iki gün.

Tenimle bin çeşit dert senli benli

Her yanım kan revan gör ki ne denli

İğneli, çivili, çatal dikenli

Tellere sardılar sensiz iki gün.

Her cevre göğsünü geren kalbime

Eyyub''un sabrına eren kalbime

Cennete sorgusuz giren kalbime

Sırrını sordular sensiz iki gün.

Eseni Efsanem olmasın kuşkun

Ecel âciz kaldı, Azrail şaşkın

Nihayet onlarda ölümsüz aşkın

Farkına vardılar sensiz iki gün.', 'Nere gizlendimse aşikâr oldum Hedefte gördüler sensiz iki gün Dertler avcı oldu, ben şikâr oldum İnsafsız vurdular sensiz iki gün. Gözlerde ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sensiz-iki-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkardı', 'cikardi-cemal-safi-u019l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Harami hırlıydı şimdiki beyden, 

Eşkiya eskiden dağa çıkardı.

Konuğa kem gören şu köhne köyden, 

Eskiden essahtan ağa çıkardı! ...

Hanzonun, hırbonun, nüfusu azdı.

Doksan bin içinde dokuz olmazdı! 

Sığırın hepisi öküz olmazdı, 

Daha çok tosunla, boğa çıkardı...

Devletin cebinden çeken çekene, 

Üstünü başını söken sökene, 

Önünü ardını diken dikene, 

Deh soktu, çüş çekti, oha çıkardı! ...

Kimdir bu utanmaz yüzü sırımlı? 

Yeşilin katlinden kimdir sorumlu? 

Tarlaya fabrika kurdu Çorumlu''lu, 

Hesabı bahçeye bağa çıkardı! ...

Haberler terörden şehitler sunar, 

Sözcüler lâf olsun babından kınar, 

Eskiden bir cana bir cihan yanar, 

Feryâd''ı figanlar göğe çıkardı! ...

Seçilen bu kadar dönek olmazdı, 

Seçen de bu kadar binek olmazdı, 

Bu kadar süt veren inek olmazdı, 

Sağsalar bin kova daha çıkardı! ...

Takip et şu giden süslü dişiyi, 

Pasaktan geçilmez kapı eşiği, 

Cemal''ce bu kadar süfli kişiyi

Mayası bozulmuş doğa çıkardı! ...', 'Harami hırlıydı şimdiki beyden,  Eşkiya eskiden dağa çıkardı. Konuğa kem gören şu köhne köyden,  Eskiden essahtan ağa çıkardı! ... Hanzonun,...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cikardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Şu Şairliğim', 'ah-su-sairligim-cemal-safi-k9yvm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elimle kuyumu kazdırdı bana, 

Ah şu şairliğim olmaz olaydı! 

Aklına eseni yazdırdı bana, 

Bütün sırlarımı aleme yaydı; 

Ah şu şairliğim olmaz olaydı! ...

Ona her gün güzel, her hava hoştu, 

Sevgisiz hayatın manası boştu, 

Gördüğü kısrağın peşinden koştu, 

Uslanmak bilmeyen bir deli taydı; 

Ah şu şairliğim olmaz olaydı! ...

Evimden barkımdan çözdürdü beni, 

İşimden gücümden bezdirdi beni, 

Bulutlar üstünde gezdirdi beni, 

Bastığım yıldızlar hüsrana kaydı; 

Ah şu şairliğim olmaz olaydı! ...

Ak yazımı baht-ı siyah eyledi, 

Gençliğime yazık, günah eyledi, 

Nerde akşam, orda sabah eyledi, 

Serseri hayatı marifet saydı; 

Ah şu şairliğim olmaz olaydı! ...

Alnım da açıktı, yüzüm de aktı, 

Kimseye verecek hesabım yoktu, 

Günah kervanımı pazara çekti, 

Yükümde ne varsa, hepsini saydı; 

Ah şu şairliğim olmaz olaydı! ...

Hayal aleminde gezmem dese de, 

Seni bundan böyle üzmem dese de, 

Bu gece, tek hece, yazmam dese de, 

Sabaha çıkmadan sözünden caydı; 

Ah şu şairliğim olmaz olaydı! ...', 'Elimle kuyumu kazdırdı bana,  Ah şu şairliğim olmaz olaydı!  Aklına eseni yazdırdı bana,  Bütün sırlarımı aleme yaydı;  Ah şu şairliğim olma...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ah-su-sairligim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Müydü', 'dus-muydu-cemal-safi-gaun9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şairim, hülyadan vazgeç diyorsun, 

Gönlüne münasip yar seç diyorsun

Ayrılık yazgımız er geç diyorsun

Yanlış mı işittim duydum, düş müydü? 

Gel, demiştin kıramadım ricanı

Güçlü sevgim hiçe saydı bu canı, 

Nasıl unuturum o heyecanı, 

Çocuk gibi ürkek, toydum düş müydü? 

İlk zifaf gecesi yaşarcasına, 

Şarab-ı aşkınla coşarcasına 

Nefes nefeseydik koşarcasına, 

Zevkimden sırsıklam suydum, düş müydü? 

Şiirle çınlattım kulaklarını, 

Hazdan al al ettim yanaklarını, 

Busemle o dolgun dudaklarını, 

Kan revan içinde koydum, düş müydü? 

İki iri azat ettim yunustan, 

Kütür kütür diri idi genç kızdan, 

Topuktan başladım sırttan omuzdan 

Öperek çırçıplak soydum, düş müydü? 

Ben usta süvari sense kısraktın, 

Dizgini arzuma bana bıraktın, 

Güçlükle zaptettim  öyle kıvraktın, 

Bir ara kalçandan kaydım, düş müydü? 

Aradan utancı kaldırıyorduk, 

Sevişmekten öte saldırıyorduk, 

Zevkten ser-mest olup çıldırıyorduk

Vuslata doyurdum doydum, düş müydü? 

Sevgilim Cemalim erkeğim, derken, 

Busenle irkildim şafak sökerken, 

Son defa sarılıp veda ederken, 

Aşkın kanununa uydum, düş müydü?', 'Şairim, hülyadan vazgeç diyorsun,  Gönlüne münasip yar seç diyorsun Ayrılık yazgımız er geç diyorsun Yanlış mı işittim duydum, düş müydü?  G...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dus-muydu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardiyan...', 'gardiyan-cemal-safi-xwqpt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kader kurbanına mağrur bakışın

Esaretten beter kor be gardiyan.

Taşyürek denince şöyle bir düşün! 

Önünde saygıyla dur be gardiyan...

Söyle gasbı mı var cinayeti mi? 

Neden engellersin ziyaretimi? 

Kime arz edeyim şikayetimi? 

Adalet nerede var be gardiyan? ...

Dostun kelamını sıradan sanma 

Henüz çözülmedi öyle muamma

Bu milletten şair çok çıkar amma

Hayati gibisi zor be gardiyan...

Bir kez düşmeye gör aşkın narına

Yanardağlar volkan kusar bağrına! 

Kerem nasıl yanar Aslı uğruna! 

Sen bir de Vasfi’ye sor be gardiyan...

Şayet meraklıysan bülbül diline

Dokunman kafidir gönül teline

Yeter ki üstadın mahir eline

Bir kağıt, bir kalem, ver be gardiyan.

Yaşlı gözlerimde hasret tütmede

Kimi esirgesem elden gitmede

Tek ona saygıda kusur etme de

Cemal’i çarmıha ger be gardiyan! ...', 'Kader kurbanına mağrur bakışın Esaretten beter kor be gardiyan. Taşyürek denince şöyle bir düşün!  Önünde saygıyla dur be gardiyan... Söyle ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gardiyan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskandır...', 'kiskandir-cemal-safi-52owk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ateş-i aşkınla öyle dağla ki, 

Nar-ı cehennemde koru kıskandır...

Şu kara bahtıma öyle çağla ki, 

Mehtabı, gurubu, nuru kıskandır! ...

Bahçelere veda ederken hayat, 

Yeşersin gözlerin hazana inat.

Allah’ın aşkına bir kahkaha at! 

Besbeter çatlasın, narı kıskandır! ..

Kimseye yar demem senin dışında, 

Bekletme hasretin kara kışında.

Süt beyaz sineni aç dağ başında, 

Kahrından erisin, karı kıskandır! ...', 'Ateş-i aşkınla öyle dağla ki,  Nar-ı cehennemde koru kıskandır... Şu kara bahtıma öyle çağla ki,  Mehtabı, gurubu, nuru kıskandır! ... Bahçe...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiskandir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nuroya...', 'nuroya-cemal-safi-rtl29', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bülbüllere has sedanı duymuşum, 

Dinlemeye doyulmaz ki Nuroya.

Kor busenin katresiyle sarhoşum, 

Seni içen ayılmaz ki Nuroya! ...

Sen her gönül savaşında muzaffer, 

Ben her emre boyun bükmüş bir nefer, 

Sana esir düşmek bile bir zafer, 

Sana karşı koyulmaz ki Nuroya! ...

Divanedir sana gönül vermeyen, 

Selamına servetini sermeyen...

Şu dünyada seni bir kez görmeyen, 

Kadın görmüş sayılmaz ki Nuroya! ...

Her sevene yar olmayı bilen sen, 

Her akıldan evliliği silen sen, 

Her şaire ilham için gelen sen; 

Sana nikah kıyılmaz ki Nuroya! ...

İmkan olsa keşke seni üzmesem, 

Dertlerimle huzurunu bozmasam, 

Hislerimi söylemesem, yazmasam, 

Aşkın sesi duyulmaz ki Nuroya! ...', 'Bülbüllere has sedanı duymuşum,  Dinlemeye doyulmaz ki Nuroya. Kor busenin katresiyle sarhoşum,  Seni içen ayılmaz ki Nuroya! ... Sen her gö...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nuroya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tufan Öncesi...', 'tufan-oncesi-cemal-safi-d74rv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nuh’un gemisine beni de alın! 

Tufan öncesini sezenlerdenim! 

Yalanı çıkmadı açtığım falın, 

Sırrın Çince’sini çözenlerdenim! ...

Hayat kavgasında çizmeyi atıp, 

Barış çarığını giydim yamatıp, 

Sabır imbiğinde duygu damıtıp, 

Gönül sancısını süzenlerdenim...

Çok resmini yaptım aşk afetinin, 

Ehliyim ressamın marifetinin, 

Ceylan bileğinin zarafetinin, 

Daha incesini çizenlerdenim! ...

Değişmem manasız zevki elemle, 

Hislerim şiire döndü çilemle, 

Ak kağıt üstüne kara kalemle, 

Sözün incisini dizenlerdenim...

Neden çekemezler, bilmem ki niye? 

Bu hüner ruhuma Hak’tan hediye! 

Mana kervanına katıldım diye, 

Madde hancısını üzenlerdenim! ...', 'Nuh’un gemisine beni de alın!  Tufan öncesini sezenlerdenim!  Yalanı çıkmadı açtığım falın,  Sırrın Çince’sini çözenlerdenim! ... Hayat kavg...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tufan-oncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık...', 'yalnizlik-cemal-safi-3bnv8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen küsüp giderken bir çift sözüme, 

Sessizce karşıma çıktı yalnızlık...

Pişmanlık hissiyle yanan yüzüme, 

Beter ol der gibi baktı yalnızlık! ...

Dilimden düşünce o çirkin hece, 

Kapımı sen açtın bu zalim güce.

Dört yanım karlı dağ oldu her gece

Çığ gibi üstüme çöktü yalnızlık! ...

Ne kadar hasretsem bir tebessüme, 

O kadar muhtacım son nefesime.

Ruhumda beliren her hevesime, 

Bir hüsran perdesi çekti yalnızlık...

Bu nasıl bir garez, bu nasıl bir kin? 

Serviler şehrini gösterir her gün? 

Sevgilim seni de ağlatır bir gün, 

Gözünü canıma dikti yalnızlık! ...', 'Sen küsüp giderken bir çift sözüme,  Sessizce karşıma çıktı yalnızlık... Pişmanlık hissiyle yanan yüzüme,  Beter ol der gibi baktı yalnızlık...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizlik-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Andan Şimdiye', 'o-andan-simdiye-ahmet-aksoy-uj0hk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir daralan bir genişleyen

Bir odanın içindeydik.

Gölgelerimiz göz gözeydi

Biz ise sırt sırta, belli ki

Gölgelerimiz kadar cesur değildik.

Hala damlamaktaydı, masadan halıya, 

Öfkelenerek devirdiğim, sürahiden su.

O da bizim gibiydi aslında 

Boynu bükük başı devrilmiş 

Kan kaybetmekteydi umutsuzca

Belki bir el gerekiyordu, 

Onu yerden kaldırmaya ama

Yazık ki, umutsuz görünüyordu o da.

O an dayanamadım, kalkıp düzelttim

Ve devrilmiş bir aşkı yerde bırakıp

Yüzüne bakmadan odayı terk ettim.

Biliyorum ben çıkarken, gölgelerimiz

Hala göz gözeydi ve bizden 

Daha cesurlardı şüphesiz 

Şimdiyse, hala aklımdadır bir soru 

O ayrılıştan bu yana

Aşk her şeyi affetmeli miydi

Ve sorunun cevabı aynı mıydı

Bir ayrış arifesiyle

Bir ayrılıştan sonra,', 'Bir daralan bir genişleyen Bir odanın içindeydik. Gölgelerimiz göz gözeydi Biz ise sırt sırta, belli ki Gölgelerimiz kadar cesur değildik. H...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/o-andan-simdiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acep?', 'acep-ahmet-aksoy-4u2c0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görünmez bulutlar sinmiştir

Yazımın üstüne

Ki ben ne zaman çıksam

Bardaktan yağmurlar boşalır

Leylekler uçmaya görsün

Sıcak iklimlere

Ki bende takılıp peşlerine

Göçmeyeyim kış ikindilerine

Yıldızlar doluşmasın gecelere

Gönlüm çeker ışıklarını

Oysa bilirim yalnızlıktır bulacağım

Ne zaman başımı kaldırsam göklere

Ben mi şanssızım yoksa gölgem mi

Beni takip eden karanlık mı

Yoksa ben mi daha aydınlığım

Takılıdır ilhamına bir çelme

Şairler mi yalnızdır,  yalnızlar mı şair?', 'Görünmez bulutlar sinmiştir Yazımın üstüne Ki ben ne zaman çıksam Bardaktan yağmurlar boşalır Leylekler uçmaya görsün Sıcak iklimlere Ki ben...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/acep-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Çürümektir', 'karanlik-curumektir-ahmet-aksoy-xdha9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pluton’ dan gelen var

Aç kapıyı yer yüzü

Elinde kırılmış dişler var

Köpeklere özgü

Derdi  biraz can sıkıcı

Değiş tokuş etmek niyeti

Elindeki kırık dişleri

Bir avuç tohumla

Pluton’ dan gelen var

Aç kapıyı yer yüzü

Elinde bir çift boynuz var

Boğalara özgü

Derdi biraz can sıkıcı

Değiş tokuş etmek niyeti

Elindeki bir çift boynuzu

Bir yudum suyla

Amacı zenginlik götürmek

Yer üstünden yer altına

Aç kapıyı yer yüzü

Acı çürümüş suratına

Ki o Pluton’ dan gelmiş

Hades’ e dönecek

Ver istediklerini 

Götürsün yer altı kralına

Yardım et ona yeryüzü

Sakınma verdiklerinden

Unutma ki güneştir asıl zenginlik

Karanlık çürümektir.

*Pluton Yun. Ve Rom. Mitolojisinde ölüler ülkesinin tanrısı hades’in adlarından  biri Pluton adı tarımsal zenginliği yöneten yer altı tanrısının iyi yönünü yansıtır

*Hades Yun ve Rom. Mitolojisinde yer altı ve ölüler ülkesinin tanrısı.', 'Pluton’ dan gelen var Aç kapıyı yer yüzü Elinde kırılmış dişler var Köpeklere özgü Derdi  biraz can sıkıcı Değiş tokuş etmek niyeti Elindeki...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/karanlik-curumektir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Ertesi', 'ayrilik-ertesi-ahmet-aksoy-w60qy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çat kapı uğraklarına döner

Her tende yalnızlık ayrılık ertesinde 

Yüzünde sahtekar bir asaletle

Uğrayan ulaktır sayısız kere

Her ne kadar elçiye zeval olmaz dense de

Elçiye göre değişir eylem de

Ki yapışmışsa yüzüne

Dolandırıcının dolambaçlığı 

Elindeki umuttan imzalı haberle

Gülüyorsa yalancı bir hüzünle

Bir de gözünden damlayan yaşlar

Çalınmışsa bir çocuğu mendilinden

İşte o vaki çalar saat on ikiyi

Ve aklı başına gelir yalnızın

Beklediği sesin henüz çıkmadığını belki de

Hiçbir zaman çıkmayacağını anlar yeniden.', 'Çat kapı uğraklarına döner Her tende yalnızlık ayrılık ertesinde  Yüzünde sahtekar bir asaletle Uğrayan ulaktır sayısız kere Her ne kadar el...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilik-ertesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Bir Çiçek', 'sevda-bir-cicek-ali-osman-yilmaz-wg2fz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda bir çiçek, 

Gönül ise bir böcek, 

Aşk çiçekteki tohum

Düştüğü gönülde filizlenecek, 

İnsansa çiçeğe hayat veren kök.

Sevgi bir okyanus, 

İçine dalmak, doyasıya yunmak gerek

Kaynağı yalnız insandır sevginin, 

Ve insanca üretilecek.

Var olmak için, varım diyebilmek

Yaşamı, ilmek ilmek, sevgi  koncasıyla örmek, 

Yarin yanağındaki gamzede

Karanfiller, Güller, kır çiçekleriyle dolu

El ele, gönül gönüle

Çiçek çiçek  gezinmek.

Bak yüreğine, bu hikayede varmısın? 

Çiçek bahçesinde  toprakmısın? 

Aşk dolu, sevda dolu bir dünyanın

Sevgi hamurunu yoğuran

Ustasımısın? 

Kan kırmızı kadife bir gül, 

Can kırmızı yanakta gamze, 

Aşk kırmızısı dudakta davetkar şehvet, 

Aç gönlünü geliyorum güzel, 

Sen yalnızca emret.', 'Sevda bir çiçek,  Gönül ise bir böcek,  Aşk çiçekteki tohum Düştüğü gönülde filizlenecek,  İnsansa çiçeğe hayat veren kök. Sevgi bir okyanus...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevda-bir-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dualarımda hep varsın', 'dualarimda-hep-varsin-ali-osman-yilmaz-fzc5v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mezarının  başında okunur taşın

Yanında fatiha isteyen  arkadaşın

Ellerim açık gönlüm sana duada

Yalnız kodun bu alemde beni arkadaşım.

Yaşadım ama sana doymadım bir an

Sensiz nasıl geçer, bilirmisin zaman? 

Özlem özlem gülerdi dudakların

Hasretinden kurudu bak dudaklarım.

Cennette sefa sürersin şimdi aşkımın gülü

Ben divane yaşarken sensiz bu günü

İsterdim gamzende olmak küçücük bir ben

Yüzünde aşkımı çağıran güllerin açarken.

Geliyorum yanına yer aç bana ey sevgili

Aradım, bulamadım senden daha güzeli

Canlansan diyorum, seviyorum dese yine dilin

Bağrımda  sıcaklığın, gönlümde dolmayacak yerin.', 'Mezarının  başında okunur taşın Yanında fatiha isteyen  arkadaşın Ellerim açık gönlüm sana duada Yalnız kodun bu alemde beni arkadaşım. Yaşa...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dualarimda-hep-varsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Bir Çift Elâ', 'o-bir-cift-el-derin-oger-34jaz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine aklıma düştü

O bir çift elâ

Sandımki ay doğdu ruhuma

Alev alev yangın 

Derin kızıl sularda bir çift elâ

Kahverengimsi birer yara

Kalbime çarparak kapattı kirpiklerini

Sevmek istediğimde parmaklarımla

Boğuldu içim alacakaranlığa......', 'Yine aklıma düştü O bir çift elâ Sandımki ay doğdu ruhuma Alev alev yangın  Derin kızıl sularda bir çift elâ Kahverengimsi birer yara Kalbim...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/o-bir-cift-ela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruh-Ceset', 'ruh-ceset-rafet-maden-zjtlh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yaz akşamıydı, 

Ayrıldı ruhla ceset.

Ceset uzak yoldaydı, 

Ruhsa cesete hasret.

Ruhu temiz bir insan, 

Saf olan bir ceset.

Ruhun ismi..........., 

Cesetin ismi RAFET.', 'Bir yaz akşamıydı,  Ayrıldı ruhla ceset. Ceset uzak yoldaydı,  Ruhsa cesete hasret. Ruhu temiz bir insan,  Saf olan bir ceset. Ruhun ismi......', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruh-ceset-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simav Akşamları', 'simav-aksamlari-rafet-maden-otoks', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hüzünleri toplamış kendi üstüne,

Bir başka oluyor simav akşamları.

Hiç benzemez gecesi gündüzüne,

Bir başka oluyor simav akşamları.

Gurbeti unutup dalarken kızıl gruba,

Aklına gelmez asla, ne ana ne baba,

Hele olursa yanında bir bira,

Bir başka oluyor simav akşamları.

Topladım dertleri saldım akşamlara,

Saldığımda dağıldı karanlıklara,

Dert kalmıyor onunla sabahlara,

Bir başka oluyor simav akşamları.

RAFET''in gurbeti içinde sılası burada,

Tesellisi o güzel akşamlarında,

Kahretsin ki yine güneş doğmakta,

Batacak elbet eninde sonunda,

Bir başka oluyor simav akşamları.

1996', 'Hüzünleri toplamış kendi üstüne, Bir başka oluyor simav akşamları. Hiç benzemez gecesi gündüzüne, Bir başka oluyor simav akşamları. Gurbeti ...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/simav-aksamlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Devam Ediyor', 'hayat-devam-ediyor-rafet-maden-0ylhf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'DÜNYADA KALMAZ SEVGİSİZ KALPLER, 

SİLİNİR MAZİDEN ESEN YELLER, 

KURUR BAKILMAYAN GÜZEL GÜLLER, 

BAK KARDEŞİM İŞTE GELEN GİDİYOR, 

GERÇEKLERİ GÖR YİNE HAYAT DEVAM EDİYOR.

SEN MAHSUN OLDUKÇA KENDİNE EDERSİN, 

İÇİNE KAPANIK YAŞARSAN ÇÜRÜR GİDERSİN, 

GİDENLE AĞLANMAZ BU GÜNLERİ ÖZLERSİN, 

BAK HERKES BİR İŞLE UĞRAŞIYOR, 

SARIL HAYATA HAYAT DEVAM EDİYOR.

ÖLÜM HAK DÜNYA GERÇEK DEĞİLMİ, 

BİR AVUÇ TOPRAK SONUMUZ DEĞİLMİ, 

HER GEÇEN SANİYE GEÇMİŞİMİZ DEĞİLMİ, 

NASIL KAHROLURSUN ZATEN HAYAT KAHREDİYOR, 

GÜLÜMSE BİRAZ BAK HAYAT DEVAM EDİYOR.

SIKMA CANINI SENDE SEVENİ BULURSUN, 

BENİM GİBİ SENDE MESUT OLURSUN, 

İHTİYARLAYINCA GENÇLERE ÖZENİR DURURSUN, 

VAKİT GEÇMEDİ AMA SANİYELER GEÇİYOR, 

GEÇECEK BU GİDİŞLE HAYAT DEVAM EDİYOR.

RAFET''İN MAZİSİDE SENİN GİBİYDİ, 

YÜRÜYEN BİR ÖLÜDEN FARKSIZ BİRİYDİ, 

ÖLEN ARKADAŞI  ONUN MAZİSİYDİ, 

AMA O MAZİLER GEÇMİŞTE YAŞIYOR, 

BAK BUGÜNE HAYAT DEVAM EDİYOR.

(KARABÜK-safranbolu) 

(1999)', 'DÜNYADA KALMAZ SEVGİSİZ KALPLER,  SİLİNİR MAZİDEN ESEN YELLER,  KURUR BAKILMAYAN GÜZEL GÜLLER,  BAK KARDEŞİM İŞTE GELEN GİDİYOR,  GERÇEKLERİ...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hayat-devam-ediyor-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Anlattım', 'seni-anlattim-rafet-maden-p7nr5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceler sabaha hasret yaşarken,

Aradığım her satıra seni anlattım.

Şiirler yazdım sana ağlarken,

Feleğe gözyaşımla seni anlattım.

Dağlara çıktım mecnunlar gibi,

Mezarlıkta yattım ölüler gibi,

İnledim hergün nağmeler gibi,

Kırık sazlara seni anlattım.

Bağrıma taş bastım kırıldı,

Bedenim uykusuzluktan yoruldu,

Kullar isyan etti, bana darıldı,

Usanmadan yine seni anlattım.

Titredi güneş benim derdimden,

Karlar yağdı odama sensizken,

Bu can tenden isyan ederken,

Gelmeyen ecele seni anlattım.

Kullar acıdı mezarıma geldikçe,

Duaya geldiler sevenler evlendikçe,

Utandılar halimi gördükçe,

Çilekeşlere seni anlattım.

Gelenler pişman şimdi yanıma,

Ölüler de ağlıyor yaşadıklarıma,

Kırılan şu mezartaşıma,

Sebep benim, seni anlattım.

RAFET''in aşkı cehennem''de de,

Bitmedi bitemez de,

Alevler isyan etti bedenimde,

Yakan alevlere seni anlattım.', 'Geceler sabaha hasret yaşarken, Aradığım her satıra seni anlattım. Şiirler yazdım sana ağlarken, Feleğe gözyaşımla seni anlattım. Dağlara çı...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seni-anlattim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazin Bir Öykü', 'hazin-bir-oyku-rafet-maden-akn6z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'HAZİN BİR ÖYKÜYDÜ BİR BULUTU KISKANDIĞIM, 

ÇARMIHA GERİLEN İSA GİBİ GÜNAHSIZLIĞIM.

BELKİ TEZKERE BEKLİYORDUM ÇİLEKEŞ ORDUSUNDAN, 

BİR GÜVERCİN GÖZYAŞIYDI YÜREĞİMDEN AKITTIĞIM.

UMUT DOLU SABAHA GÖZLERİMİ AÇMAK İÇİN, 

KARANLIK GECELERİ YIRTIP KARAMSARLIKTAN KAÇMAK İÇİN, 

ÇOK UYKUSUZLUK ÇEKTİM ŞAİR OLMAK İÇİN, 

BİR BERRAK UMMAN SEVDASINI HÜCREMDE YAŞADIM.

HAZİN BİR ÖYKÜYDÜ GERÇEKLERİ YAŞAYAN, 

BİR ŞİİR BİTERKEN DİĞERİNE BAŞLAYAN, 

KERBELA''DA YAŞANAN BİR MATEMDİ YÜREĞİMDE KANAYAN, 

FANİ HAYATTA ÖLÜMSÜZLÜKTÜ DİZELERDE ARADIĞIM.

(İSTANBUL) 

(08.04.2002) 

(Saat:09.45)', 'HAZİN BİR ÖYKÜYDÜ BİR BULUTU KISKANDIĞIM,  ÇARMIHA GERİLEN İSA GİBİ GÜNAHSIZLIĞIM. BELKİ TEZKERE BEKLİYORDUM ÇİLEKEŞ ORDUSUNDAN,  BİR GÜVERC...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hazin-bir-oyku-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Kışlasında', 'hayat-kislasinda-rafet-maden-cdvyh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BAZEN UMUTSUZLUĞU KARALIYORUM, 

İCTİMALARA ÇIKIYORUM HAYAT KIŞLASINDA.

GÜZEL GÜNLER İÇİN ŞAFAK SAYIYORUM, 

DOĞACAK GÜNEŞLERE HAYAT KIŞLASINDA.

AYNANIN KARŞISINDA GENÇLİĞİMİ ARARKEN, 

RESİMLERE BAKIP YAŞLANDIĞIMI GÖRÜRKEN, 

ÇALIŞMAKTAN BELİM BÜKÜLÜRKEN, 

SABIR ÇEKİYORUM HAYAT KIŞLASINDA.

GEL TEZKERE GEL DİYEREK COŞARKEN, 

İŞTEN EVE EVDEN İŞE KOŞARKEN, 

HERKES GİBİ BENDE ÖZGÜRLÜK BEKLERKEN, 

NÖBETLERE KOŞUYORUM HAYAT KIŞLASINDA.

FELEK RÜTBELİ KADERİM OLMUŞ ÇAVUŞ, 

MUTLULUK ELİMDEN KAÇMIŞ BİR KUŞ, 

BELKİ OLUR İÇİMDE YENİDEN DOĞUŞ, 

ÖMRÜM ''SELAM DUR'' LA GEÇMİŞ HAYAT KIŞLASINDA.

BİTMEYECEK YİNE İÇİMDEKİ AĞIDIM, 

BUGÜNDE GELMEDİ TEZKERE KAĞIDIM, 

İNANCIM İÇİN HEP BAĞIRDIM, 

SAĞIRLAŞMIŞ HERKES HAYAT KIŞLASINDA.

(İSTANBUL) 

(17.04.2002) 

(Saat:08.30)', 'BAZEN UMUTSUZLUĞU KARALIYORUM,  İCTİMALARA ÇIKIYORUM HAYAT KIŞLASINDA. GÜZEL GÜNLER İÇİN ŞAFAK SAYIYORUM,  DOĞACAK GÜNEŞLERE HAYAT KIŞLASIND...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hayat-kislasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel......mesutnameden......', 'gel-mesutnameden-refik-yildiz-yz9ua', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde bitmeyen şarkıyı dinle

Dinlede gönlümün dilini anla

Tut elimi yum gözünü kalbime gir de

Kalbimin dinmeyen sözünü anla

Gönlünü gönlümle akord edelim

Zemheri dünyanın yazını anla

Bakışlarını gönlüme değdiriver de

Son deminde ömrümün,sen beni anla', 'İçimde bitmeyen şarkıyı dinle Dinlede gönlümün dilini anla Tut elimi yum gözünü kalbime gir de Kalbimin dinmeyen sözünü anla Gönlünü gönlüml...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-mesutnameden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Bakalım', 'git-bakalim-rafet-maden-xt8xc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Git bakalım.

Nereye kadar gideceksin.

Ne kadar uzaklaşsanda

Yine bana döneceksin.

Git bakalım.

Avucuna sığdıramazsın hasretimi, 

Alevlere anlatamazsın.

Görmezden gelemezsin benliğimi, 

Değer biçemezsin dalgaları.

Benim sevdam çok yücelerde

Git bakalım.

Git bakalım.

Gittiğin yerlerde masallar okunmayacak

Tatlı sözleri kulağına kimse fısıldamayacak

Gün gelecek yüzüne bakan olmayacak

Git bakalım.

Git bakalım., 

Söyle gitmemen için ne yapayım? 

Deli olup peşinde mi koşayım? 

Yoksa dizlerine mi kapanayım? 

Mademki niyetlisin

Git bakalım.

(İSTANBUL-2002)', 'Git bakalım. Nereye kadar gideceksin. Ne kadar uzaklaşsanda Yine bana döneceksin. Git bakalım. Avucuna sığdıramazsın hasretimi,  Alevlere an...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/git-bakalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceye Sor', 'geceye-sor-refik-yildiz-nmkpf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceye sor

Aşıklar neden ah çeker derinden

Kimin gözünde canlanır hatıralar

Nerededir sevgililer

Nasıldır ayrılıklar...

Elimi alnıma dayar iç çekerim derinden

Ey gönül sızım, yaş olup gözlerimden akan

Siz söyleyin halimden, aşktan

Özlenen sevgiliden

Geceye sor nasıldır ayrılıklar...!', 'Geceye sor Aşıklar neden ah çeker derinden Kimin gözünde canlanır hatıralar Nerededir sevgililer Nasıldır ayrılıklar... Elimi alnıma dayar i...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/geceye-sor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençleşiyorum', 'genclesiyorum-rafet-maden-1p0gn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen yüreğime derlediğim gülümsün, 

Herşeyimle seni yaşatıyorum.

Bırak da gönüllerimiz gülsün, 

Sen gülünce ben gençleşiyorum.

Güzelliğin içimi yakmış bir kere, 

Kimseye bakamam gözüm sende, 

Seni görüyorum baktığım her yerde, 

Seni gördükçe gençleşiyorum.

Yorgun bir hayatım vardı senden önce, 

Dünyam değişti sen dünyama girince, 

Hele bu yorgun yüreğim sevilince, 

İşte o zaman ben gençleşiyorum.

Bugün de aç kaldık ama ne çıkar, 

Feleğe fırsat verirsek yuvamızı yıkar, 

Herşey onurlu yaşamaya bakar, 

Seni umutlu gördükçe gençleşiyorum.

Umudumu kesme, umutsuzluğunu istemem, 

Sen ağlarsan ben gülemem, 

Bu hayat kavgasında mücadele edemem, 

Kavgalar yıpratsa da seninle dinçleşiyorum.

Aynaya değil sana bakınca gençleşiyorum.

(İSTANBUL-2002)', 'Sen yüreğime derlediğim gülümsün,  Herşeyimle seni yaşatıyorum. Bırak da gönüllerimiz gülsün,  Sen gülünce ben gençleşiyorum. Güzelliğin içi...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/genclesiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemi Özledim', 'annemi-ozledim-refik-yildiz-rcn7k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birgün yine yatınca tarmada

Evet barakta

Yıldızlar toplanıp kucakta

Nerelerdesin arkadaş diyecekler

Sessizce...

Sanki hiç ayrılmadım

Bak yatağımda sıcakca

Bekliyorum uyumadım

Annem üstümü örtecek ya...', 'Birgün yine yatınca tarmada Evet barakta Yıldızlar toplanıp kucakta Nerelerdesin arkadaş diyecekler Sessizce... Sanki hiç ayrılmadım Bak yat...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/annemi-ozledim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezar', 'mezar-refik-yildiz-d46r4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayattan hoştur bazen mezar

Sevgilinin dizinde uyumak gibidir

Uzun bir hasretin ardından

Kavuşmaktır ona kucaklayan

Bir anı bir ömür kadar uzun olan

Visalse soğuk olur mu mezar...? 

İlkbaharda attığı tohumu sabırla bekler

Dua eder her gün okşayan bakışlarıyla

Temmuz güneşi altında kavrulurken

Bazen bir günü bir yıl kadar uzun olan

Mevsimden şikayet etmez, şikayet etmez çabasından

Hasatsa soğuk olur mu mezar...?', 'Hayattan hoştur bazen mezar Sevgilinin dizinde uyumak gibidir Uzun bir hasretin ardından Kavuşmaktır ona kucaklayan Bir anı bir ömür kadar u...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mezar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Ve Tonları, Onun Zamanı Yaşanan...', 'mor-ve-tonlari-onun-zamani-yasanan-burcu-karakaya-ll23g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(O kendini biliyorrrrrrr.........) 

Bilmediğim bir dünya açıldı, 

Beklemediğim bir zaman tünelinde, 

Cılızdan bir ışık çarptı gözlerime, 

Olmasını beklediğim renk mor ve tonları, 

Asil ve hırslı...

Önce zaman da sıkıştığımı hissettim

Hiç bir söylem

Hiç bir eylem

Ve aşk ta dahil

Etkilemiyordu benliğimi...

Bir ses ve kahkaha işittim derinlerde, 

Ilık tebessümün alışılmamış kokusunu duydum, 

Bir an silkinip

Onun boyutuna attım yüreğimi, 

Beden hala yerinde! 

İkiye bölünmüşlüğü, 

Hiç bu kadar içten yaşatmamıştı kimse! 

Her dua kabul olsaydı Tanrı katında, 

Bu gece rüyama girerdin...

Bilmediğim bir beden için

Çıldırıyor bilinenlere inat, 

Duygularım...

Onun zamanı yaşanan! 

Aynı şekilde benim zamanım olmasını da istediğim...

Hırçınlığının yanında

Bir şevkat yumağının her boğumunda 

Ayrı ayrı karışıyor insan...

Sadece o çözebiliyor, 

Sen kitlenip kalakalıyorsun.

Çünkü onun zamanı yaşanan! 

Güçlü bir dalganın içinde

Sana bir balık, türünün ne olduğu bilinmeyen, 

Türünün son örneği tek bilinen...

Her söylem 

Her eylem

Ve aşk...

Şimdi farkedilen...

Ayrıntılarını gizlemeyen, 

Düşünceleri onun değil de, 

Düşüncelerin onu düşündüğü, 

Eşsiz bir tablo...

İçinde tüm renklerin belli olduğu

Belirsiz renklerin bile onu kıskanacağı kadar

Çarpıcı ve etkileyici, 

Zamanının, en parlak yıldızı.

Işığının farkında, 

Belki kendince kırmızı ya da sarı, 

Bana sorarsanız mor ve tonları, 

Asil ve hırslı...

Uyumuyorum zamanın bir yerinde

Neden arıyorum 

Bedenimin diğer tarafta beni bırakışını

Anlıyamıyorum...

Gelicek bir zaman teklif ettim, 

Bekliyorum....

C.Burcu Karakaya

30/09/2003

Antalya', '(O kendini biliyorrrrrrr.........)  Bilmediğim bir dünya açıldı,  Beklemediğim bir zaman tünelinde,  Cılızdan bir ışık çarptı gözlerime,  Ol...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/mor-ve-tonlari-onun-zamani-yasanan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne İstedik Sanki', 'ne-i-stedik-sanki-refik-yildiz-7ifgh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce uzun sopası olan vurdu

Aldı kısa sopalının her şeyini

Ona baltası olan vurdu

Çaldı herşeyini

Beyler ve krallar çıktı sonra

Sanki kanları bizden farklı gibi

Topluca alıp sattılar onlar bizi

Sanki bir tutam ot gibi, toprak gibi

Uzak kıtalarda avladılar bacılarımı kardeşlerimi

Tarlalarına ve bahçelerine bağladılar bizi

Sanki köpek gibi

Oysa biz işlemiştik torağı, ve biz üretmiştik

Tıpkı dar dehlizlerde kömürü ürettiğimiz gibi

Başında da ortasında da sonunda da asırların

Hangi asırda yaşadıysak o asırda

Bir ekmek, bir urba, bir de sıcak bir yuva

Ve adalet istemiştik sadece...', 'Önce uzun sopası olan vurdu Aldı kısa sopalının her şeyini Ona baltası olan vurdu Çaldı herşeyini Beyler ve krallar çıktı sonra Sanki kanlar...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-istedik-sanki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alt Tarafı Bir Yara Saracaktın', 'alt-tarafi-bir-yara-saracaktin-derin-oger-kivf2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dost dedim bakışından yola çıktım

Yemyeşil umutlarla ne hayaller kuruttum

Dost içeri can dışarı dedikçe

Sanki en yakın dostuma düşman oldum

Kime sövsem kime kızsam kime darılsam

Söyle dost dediğim yabancı

Neye yarar seni yeniden dosttan saysam

Rüzgarın sisliydi suyuna daldım bulanık

Hepimiz gidiciyiz ama benim kapım aralık

Anlamamazlıktan gelmekse daha da büyük ayıp

Sıkıca tut gizle çoklarına benzemeni

Tanrıya emanet can rüsva olmaz suç olmaz

Ey dost yüzbin deve katar istemedim senden

Alt tarafı bir yara saracaktın gönülden.......', 'Dost dedim bakışından yola çıktım Yemyeşil umutlarla ne hayaller kuruttum Dost içeri can dışarı dedikçe Sanki en yakın dostuma düşman oldum ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/alt-tarafi-bir-yara-saracaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çek Git', 'cek-git-arif-baltaci-6m76h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne gökyüzü eskisi kadar mavi 

Ne de gözlerin eskisi kadar yeşil 

Sonbaharın yapraklarına benzettiğim

Sarı saçlarının dalgalanışı bile umrumda değil

Sen başka rüyalarda koşturursun atını

Benim rüyalarım artık sersefil

Erkekliğe bir damla yaş düşürmeden 

Geçirmek isterdim bütün kışları 

Bir günbatımında deniz üstünde 

Kaybettim o sevdalı bakışları 

Yalan mıydı tüm yaşananlar şimdi

Geri verebilir misin sana verdiklerimi

Geriverebilir misin masum düşlerimi

Geriverebilir misin gülüşlerimi

Bırak bana hiçbir şeyden bahsetme 

Çek git hayatımdan çek git sadece...

					04.08.2003

					KONYA', 'Ne gökyüzü eskisi kadar mavi  Ne de gözlerin eskisi kadar yeşil  Sonbaharın yapraklarına benzettiğim Sarı saçlarının dalgalanışı bile umrumd...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cek-git-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Verebilir Misin?', 'geri-verebilir-misin-arif-baltaci-yzcyh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutlarım vardı, gökyüzünden daha mavi

Temiz bir kalbim vardı sevdanın esiri

Gülüşlerim vardı kahkahalar misali

Şimdi bana bunları geri verebilir misin? 

Uğruna akıttığım onca gözyaşından bir damlasını 

Seni düşündüğüm anların bir dakikasını 

Sevdanla büyüttüğüm gülümün goncasını 

Şimdi bana bunları geri verebilir misin? 

					04.08.1998

				Yerköy/YOZGAT', 'Umutlarım vardı, gökyüzünden daha mavi Temiz bir kalbim vardı sevdanın esiri Gülüşlerim vardı kahkahalar misali Şimdi bana bunları geri vere...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/geri-verebilir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprağın Aşkı', 'yapragin-aski-arif-baltaci-jvbta', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hoyrat rüzgarların ucuna 

Sonbahar yaprakları gibi

Takılmıştı kalbim 

Ben senin rüzgarınla savruldum

Yaprak sonbaharın rüzgarıyla 

Ben senin yokluğunda vuruldum

Yaprak yeni gelen baharla

Sen beni yeni bir sevdaya değiştin

Mevsim yaprağı taze bahara

Oysa ben sana kuru bir yaprağın 

Ağaca olan tutkusuyla bağlanmışım

Ne ağaç yaprağa sevdalıymış 

Ne de sen bana 

Ben bu yalanlara aldanmışım 

Şimdi yüreğim yapraklar gibi 

Dağılmış dört bir yana 

Kırılmış bin bir yerinden 

Umarsız insanlar çiğneyip 

Geçmiş acımasızca üzerinden.

Uzanmışım yatağa boylu boyunca

Bütün güllerimi sana dermişim

Son yaprakta ihanete uğrayınca 

Son nefesimi yapraklara vermişim

Son nefesimi yapraklara vermişim...

						09.08.2003

						KONYA', 'Hoyrat rüzgarların ucuna  Sonbahar yaprakları gibi Takılmıştı kalbim  Ben senin rüzgarınla savruldum Yaprak sonbaharın rüzgarıyla  Ben senin...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yapragin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlar Dinene Dek', 'yagmurlar-dinene-dek-arif-baltaci-vc1mt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim ona baktığım gibi 

Bana bakmıyorsa bir insan 

Bu ilişkiye hiç başlamamak 

En iyi seçimdir inan

Ya da gökyüzündeki bulutlardan 

Yağmur yerine hüzün yüreğine yağacaksa 

Boş ver bırak gökkuşağını omzuma 

Yaksın bu aşk bizi yakacaksa 

Hiç kimsenin olmadığı boş sokaklarda 

Serseri mayındır benim adım 

Bir üsküdarda el ele geçirdiğimiz günleri

Bir de omzuma koyduğun gökkuşağını unutmadım 

Benim baktığım gibi bakamazdın bana 

Ben mecnun olurdum sen leyla olsan

Benim baktığım gibi bana bakamasan da 

Bu yağmurlar dinene dek yanımda kalsan...

						07.08.2003

						KONYA', 'Benim ona baktığım gibi  Bana bakmıyorsa bir insan  Bu ilişkiye hiç başlamamak  En iyi seçimdir inan Ya da gökyüzündeki bulutlardan  Yağmur ...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yagmurlar-dinene-dek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Çocuğuyla Söyleşiden', 'sokak-cocuguyla-soylesiden-arif-baltaci-p5z2v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '‘Bir kalemin mürekkebinden sızan

Asi bir haykırıştı yaşamak

Oysa hep gökyüzü mavisi adında yaşamak isterdik

Sonsuz ve sınırsız bir dünyaydı hayalini kurduğumuz

Yıldızlarımız vardı altında dilekler tutup oturduğumuz.

Birileri gelip yıldızımızı çaldı

Birileri gökyüzünden mavimizi söküp aldı.

Öksüz bir çocuk gibi sokaklardaydık

Ama ne yıldızlarımız kalmıştı 

Ne gökyüzünde mavimiz’

Saatler hep yalnızlığa vururdu

Mevsimler hep sonbahar

Minicik ellerinde yaralar vardı

Yaralar ki çocuğun kendisi kadar 

‘Kaldırımları da alamazlardı ya elimizden 

Üstümüze örttüğümüz yalnızlığı da

Hangi güç silebilirdi bu anı kaderimizden

Hangi güç silebilirdi gördüğümüz yalnızlığı da 

Her gece hayalini kurarak bir anne dizinin 

Kafamı dayadım soğuk kaldırım taşlarına

Ben sokak çocuğuyum aldırmayın siz gönlümün yaşlarına 

Gönlümün yaşlarına.’

Çocuğun hikayesi bu kadardı 

Ardına bile bakmadan gitti

Ne bir yardım bekledi 

Ne de bir şey istedi

Onun tek dileği tanrıdandı

Gözyaşını gizledi.

Ondan anne istedi.

									

						09.08.2003

				  	                KONYA', '‘Bir kalemin mürekkebinden sızan Asi bir haykırıştı yaşamak Oysa hep gökyüzü mavisi adında yaşamak isterdik Sonsuz ve sınırsız bir dünyaydı ...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sokak-cocuguyla-soylesiden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuz Beş Yaş', 'otuz-bes-yas-arif-baltaci-wnbcp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaş otuz beş değil ama 

Yolun yarısına geldik

Hayat yıprattı bizi 

Yirmimizde tükendik

İnsanlardan korkup ta 

Sokaklara çıkmadık 

Yüzleşemedik kendimizle

Aynalara bakmadık 

Kabus görmemek için 

Uykulara dalmadık 

Kaybolup ta yaşamda 

Kendimizi bulmadık...

			09,08,2003

			KONYA', 'Yaş otuz beş değil ama  Yolun yarısına geldik Hayat yıprattı bizi  Yirmimizde tükendik İnsanlardan korkup ta  Sokaklara çıkmadık  Yüzleşemed...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/otuz-bes-yas-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Şal', 'kirmizi-sal-muharrem-koray-rcy99', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tarçın kokulu

çayın içine

bir kaşık da bal

dumanı üzerinde

yavaşça kapıyı çal

kırmızı renkli 

omzuna

yavaştan bir şal

üşüyor gibisin

bir yudum da sen al

kısık sesli 

rüzgara

kırılan bir dal

yağmur da geliyor

ne olur yanımda kal', 'tarçın kokulu çayın içine bir kaşık da bal dumanı üzerinde yavaşça kapıyı çal kırmızı renkli  omzuna yavaştan bir şal üşüyor gibisin bir yud...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Koray']::text[], 8.5, '{"poet":"Muharrem Koray","poet_slug":"muharrem-koray","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kirmizi-sal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapılar', 'kapilar-yasar-ersahan-jwqil', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapılar ne olur, kapanmayın yüzüme, 

Bir ışık hüznesiyle, açılın da önümde.

İçeri buyur edin, layık görmesenizde, 

Uzak yollardan gelen yolculara su verin, 

Yorulmuş bedenlere bir yatak, örtü verin, 

Bana seccade verin, kırık lamba önünde, 

İçeri buyur edin layık görmesenizde.

Dua, dua; anahtar, eşiklerde kapılar, 

Bir anne şefkatiyle, açılırken üstüme

Bana bir hal verin, hal dilinden kapılar.

		       26.09.2003

		        ANKARA', 'Kapılar ne olur, kapanmayın yüzüme,  Bir ışık hüznesiyle, açılın da önümde. İçeri buyur edin, layık görmesenizde,  Uzak yollardan gelen yolc...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Erşahan']::text[], 8.5, '{"poet":"Yaşar Erşahan","poet_slug":"yasar-ersahan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kapilar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-hakki-hakan-kaya-aoek3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen handa yolcu iken, 

Ben çayda bekçi idim.

Sen canda sevgi iken, 

Ben dilde ezgi idim.', 'Sen handa yolcu iken,  Ben çayda bekçi idim. Sen canda sevgi iken,  Ben dilde ezgi idim....', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-ve-ben-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün yattım, Dünde uyandım', 'bugun-yattim-dunde-uyandim-muammer-celik-1czxs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün yatmıştım 

düşümde görmek için seni 

dünde uyandım 

dünlerde sen hiç yoktun… 

Dünden bugüne 

bugünden yarına 

yarından geleceğe kadar sevdim 

seviyorum ve seveceğim 

yokluğunda varlığına 

varlığında yokluğuna vuruldum 

aşk ırmağında yıkandım

ve sevginle dupduru duruldum 

hayalinle yoğrulup 

öyle çok yoruldum…ki; 

Çelik halatlarla çekiyorum 

vuslatın büyük gününü 

içimde bir kıpırtı var ki,

uçuruyor heyecandan beni 

bir kaç vakte kadar 

göreceğim diye gül yüzünü… 

Şimdi gene yatıyorum 

gerçekte görmek için seni 

Dünde uyandırma beni.... 

yemin ederim bu defa 

asla ve asla affetmem 

kendi içimde boğarım seni…. 

04.05.2003

BirDeli', 'Bugün yatmıştım  düşümde görmek için seni  dünde uyandım  dünlerde sen hiç yoktun…  Dünden bugüne  bugünden yarına  yarından geleceğe kadar ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bugun-yattim-dunde-uyandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne gül göçer, Ne gönül geçer', 'ne-gul-gocer-ne-gonul-gecer-muammer-celik-dt08p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ahhhh bu güller, dost... 

Ahhh bu güller... 

Dut yemis bülbüller... 

Bahce bahce acar bu deli gönüller, 

söylerde söylerler... 

Öterde öterler... 

Ne goncagülüm yerinden göçer... 

Nede bu deli gönül senden geçer... 

30.05.2003 

BirDeli', 'Ahhhh bu güller, dost...  Ahhh bu güller...  Dut yemis bülbüller...  Bahce bahce acar bu deli gönüller,  söylerde söylerler...  Öterde öterl...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-gul-gocer-ne-gonul-gecer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığımın Sahili', 'yalnizligimin-sahili-muammer-celik-e1urt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayaklarıma vurmakta olan taşlara 

adını yazdığım o büyük çakıllara 

yalnızlık sahillerine kendimi attım

seni de dalgakıran kayalara çaktım 

Ellerime vuran, çarpan dalgalarla 

resminin asılı olduğu duvarlarla 

akan gözyaşlarıyla kendimi ovdum 

seni de azgın akan sulara koydum 

Gözlerime doğmakta olan yıldızlara 

yüzüme parlamakta olan yakamozlara 

önümde serilen denize kendimi soydum 

seni de içimdeki bir kaşık suda boğdum 

28.05.2003

BirDeli', 'Ayaklarıma vurmakta olan taşlara  adını yazdığım o büyük çakıllara  yalnızlık sahillerine kendimi attım seni de dalgakıran kayalara çaktım  ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalnizligimin-sahili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibrit Çöpü', 'kibrit-copu-bilal-yalcinkaya-g6mjj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen

Bir kibrit çöpü özetliyor

Aramızdaki engebeli ilişkiyi

Ben, 

Kibrit çöpünün yanan tarafı

Sen ise, 

Benden en uzak olabileceğin kadar

Öbür tarafı

Ve anladım ki

Ancak yanarak ulaşabilirim SANA', 'Bazen Bir kibrit çöpü özetliyor Aramızdaki engebeli ilişkiyi Ben,  Kibrit çöpünün yanan tarafı Sen ise,  Benden en uzak olabileceğin kadar Ö...', ARRAY['Türk Edebiyatı','Şiir','Bilal Yalçınkaya']::text[], 8.5, '{"poet":"Bilal Yalçınkaya","poet_slug":"bilal-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kibrit-copu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Kahvesi', 'kir-kahvesi-sermest-capan-1y71f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bırak, gün battığı yerden batsın

Balıçılar çoktan topladı ağlarını

Limanın parlaklığında çayın buğusu

Bırak, yaksın gençliğimizi...

Sabaha daha çok var

Bırak, rüzgar savursun ateşimizi

Kır kahvesi kapanalı aylar oldu

Bırak, ilkyaz kızdırsın bizi...', 'Bırak, gün battığı yerden batsın Balıçılar çoktan topladı ağlarını Limanın parlaklığında çayın buğusu Bırak, yaksın gençliğimizi... Sabaha d...', ARRAY['Türk Edebiyatı','Şiir','Sermest Çapan']::text[], 8.5, '{"poet":"Sermest Çapan","poet_slug":"sermest-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kir-kahvesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geveze', 'geveze-sermest-capan-q4ld1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana

daha

son

sözümü

söylemedim

çünkü

daha 

son

nefesimi 

vermedim...', 'Sana daha son sözümü söylemedim çünkü daha  son nefesimi  vermedim......', ARRAY['Türk Edebiyatı','Şiir','Sermest Çapan']::text[], 8.5, '{"poet":"Sermest Çapan","poet_slug":"sermest-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/geveze-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme Türkülerle', 'anneme-turkulerle-sila-gul-savas-ax8tm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yaklaşırım anneme

sevgi dolu türkülerle

türkülerde annem var

sımsıcak gözleri var

Prenses mi desem? Değil, 

Bir rüya mı desem? Değil, 

Bal akan dilleriyle 

Annem en güzel melek

En güzel sevgiyi 

En müthiş şefkati

En göz alıcı güzelliği

Sende buldum ben annem

Her fırsatta öptüğüm ellerinle

Işık saçan gözlerinle

Müthiş sarı saçlarınla

Hep o bildiğim melek kalacaksın sen annem.', 'yaklaşırım anneme sevgi dolu türkülerle türkülerde annem var sımsıcak gözleri var Prenses mi desem? Değil,  Bir rüya mı desem? Değil,  Bal a...', ARRAY['Türk Edebiyatı','Şiir','Sıla Gül Savaş']::text[], 8.5, '{"poet":"Sıla Gül Savaş","poet_slug":"sila-gul-savas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anneme-turkulerle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk gibi Aşk', 'ask-gibi-ask-muammer-celik-fm2qi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adam gibi Adam 

sırılsıklam 

ve aşk 

unutulmaz o zaman

kaldıysa azıcık bir tadı damakta 

kadehte bir kirmizi şarap damlası gibi

sevdanın kızıla çalan mosmor rengine çarparlar 

güneşin batımında, ufukta kalan tek tük bulutlar 

Kadın gibi Kadın 

Anadan uriyen 

Ve aşk 

Unutulamaz o zaman

var idiyse azıcık bir aş tabakta 

yeterde artar, cennet bahçesi gibi durmakta 

çilingir sofrası 

iki dilim karpuz ile 

üç dilim ekmek 

yüz gram beyaz peynir 

yarım kase pekmez ile açılır.. 

Yetinir 

Geçinir 

Sevilir 

Sevinir 

Adam ile Kadın 

Kadın ile Adam… 

Aşk işte o zaman ADAM gibi ADAM… 

27.05.2003 

BirDeli', 'Adam gibi Adam  sırılsıklam  ve aşk  unutulmaz o zaman kaldıysa azıcık bir tadı damakta  kadehte bir kirmizi şarap damlası gibi sevdanın kız...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ask-gibi-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Güzeli', 'mor-guzeli-sermest-capan-34daa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sabah caddeler yine bomboş

Çöpçüler kahpeleri çoktan süpürmüş

Az ötede kayıkhanenin başucu

Martılar mahmur geceyi esir almış

Sabaha ağaçlar tırmanırken

Günü izledim pencereden

Bir seni aradım suların ardında

Bir de Mor Güzeli', 'Bu sabah caddeler yine bomboş Çöpçüler kahpeleri çoktan süpürmüş Az ötede kayıkhanenin başucu Martılar mahmur geceyi esir almış Sabaha ağaçl...', ARRAY['Türk Edebiyatı','Şiir','Sermest Çapan']::text[], 8.5, '{"poet":"Sermest Çapan","poet_slug":"sermest-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mor-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mendil', 'mendil-cigdem-bir-genc-igvfg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarım aktı aktı....

Tuzlu bir özlem 

Mendilimin kenarından

Bana göz kırptı.', 'Gözyaşlarım aktı aktı.... Tuzlu bir özlem  Mendilimin kenarından Bana göz kırptı....', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mendil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklıma Gelenler', 'aklima-gelenler-vedat-koseoglu-0urco', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman içimden bir tren geçse, 

Veda edişin gelir aklıma

Ve gözlerin...

Ne zaman aklıma gelse gözlerin, 

Söz verişini hatırlarım

Binlerce yeminle....

Ne zaman sözlerin gelse aklıma

Dudakların gelir hiç bitmez tebessümle

Alır başımı giderim peşinden.....

Saçların düşer hayalime

Saçlarında yalnızlığım gelir aklıma

Takılır her bir teline bir hayalim....

Ne zaman geçse içimden bir yolculuk

Binbir sevda masalı söyler türküler

Türkülerde bulurum seni

Ne zaman, ne zaman desem

Bütün vakitlerim sanadır

Sende var olur, sende yok olurum....

Bir tren geçer içimden karanlık sabahlarda 

Bir tren yalnızlık dolu

Bilir misin.?', 'Ne zaman içimden bir tren geçse,  Veda edişin gelir aklıma Ve gözlerin... Ne zaman aklıma gelse gözlerin,  Söz verişini hatırlarım Binlerce ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Köseoğlu']::text[], 8.5, '{"poet":"Vedat Köseoğlu","poet_slug":"vedat-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aklima-gelenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüksünme', 'yuksunme-abdulkadir-karaman-7k9v4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüksündüğüm meçhul dert, ceremesi dilimim…

Gönlümün külfetidir, akıttığım gözyaşı…

Kölesi olmuş kâlbim aşk diye bir zâlimin

Ayrılık meydanında kaybedince savaşı…

Güç yetiremem, bittim, yalvarır, ilenirim

Bir gözün serâbından, ilhamlar dilenirim

Ayrılık zamanına ilk ândan bilenirim

Tuttum dertten yükümü, mekanım dağlar başı… 

Kim koydu vicdanıma, iltimassız yargıcı

Aynalarda gördüğü gözlerimin, yabancı

Çökelen karanlığın içimde başlangıcı

Köklerinde hastalık, ne yapsam tutmaz aşı…

Kim avladı belirsiz, nerde göçmen kuşları? 

Anlayamam, yüreğim niçin döker yaşları? 

Tek tek söker canımdan küf bağlamış taşları

Huzurumu kaçıran acıların talaşı…

Çıkmaz kalbim, çok ürkmüş, gizlendiği siperden

Gözyaşlarıymış canı temizleyen kirlerden

Çabukluğu beklemek ne kadar yanlış körden

Bu yorgunluk, bıkkınlık gecikmenin telâşı…

27.07.03', 'Yüksündüğüm meçhul dert, ceremesi dilimim… Gönlümün külfetidir, akıttığım gözyaşı… Kölesi olmuş kâlbim aşk diye bir zâlimin Ayrılık meydanın...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yuksunme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Ben', 'ben-ve-ben-naime-erlacin-xpyg8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-ben neyim

kimim ben? 

durmalıyım benden geri

anlam yüklemeli varlığıma

benden 

bir adım ileri

yitirilen eklenmeli

eklediğimi 

yeniden gözden geçirmeli

özüm 

salt benden beslenmeli

bir kum zerresi insan 

aslında kâinatın kendisi

yaradanın aynasında

yaradanın ölümsüz nefesi

insan “ben”i önce

“ben”den bilmeli

(30 Eylül 2003)', '-ben neyim kimim ben?  durmalıyım benden geri anlam yüklemeli varlığıma benden  bir adım ileri yitirilen eklenmeli eklediğimi  yeniden gözde...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-ve-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Bir İzmir', 'seninle-bir-i-zmir-vedat-didari-xoohn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seninle bir izmir olduk

konakta iç içe kalabalıklarla 

karşıyakada tenhalar arandık

iskeleden iskeleye taşındık

çocuksu heyecanlarla

önce bir yağmur kaçağıydın

ıslak bir kedi yavrusu

sonra kıvılcımlandı gözlerinde

bir genç kızın coşkusu

deniz lokantasında

tüm dişiliğine büründüğün

o anda

öyle güzeldin ki, 

anlatamam

belki de izmirdigüzel olan

ya da biz izmiri bulduk

ama bildim ki tâ yüreğimden

seninle bir izmir olduk

yanlış mı, doğru mu, 

kim yapabilir bu ayrımı? 

onca çaresizlik varken

yasak mıydı sevmek? 

yasak mıydı prangaları çözmek

tutsak yüreklerden? 

gözbebeklerinde duraksız

hüzün çiçekleri açan

yükleyip te tutsak yüreğini

o hüzünlere

uzaklara, hep uzaklara kaçan

gün batımı kız

bak geldim işte onca yoldan

bak hazırım tutuşmaya

kirpiklerinden, dudaklarından

bilmiyorsun ki bu görkemli kent

baştanbaşa sevgi, baştanbaşa sen

kordonlarında imbat değil artık

sevda rüzgârlarıdır esen

geç oldu belki ama, kader

verdi ya bana seni, 

ne farkeder? 

belki tuşlardan düştün dünyama

belki de düşlerden

belki ekrandan dokundun

belki de akıverdin tellerden

bilemem.

bildiğim, seni saklayacağım

canımda, usumda

ve gün gelip

yalnızlığıma açılan bu pencere

kapandığında

dilerim gözlerindeki

hüznün yerine

sevinçler dolsun

yüreğim de bilsin bunu

seninle bir izmir olsun', 'seninle bir izmir olduk konakta iç içe kalabalıklarla  karşıyakada tenhalar arandık iskeleden iskeleye taşındık çocuksu heyecanlarla önce bi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Didari']::text[], 8.5, '{"poet":"Vedat Didari","poet_slug":"vedat-didari","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/seninle-bir-izmir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yusuf Yakup', 'yusuf-yakup-abdulkadir-karaman-8wu71', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İhtiras, kıskançlık müzmin hastalık

Tasarı, yok etmek engel hedefi…

Nankörlük ruhlarda pörsük yamalık

Yangına bir çıra kelime kâfi.

Hareket başladı, hikaye hazır

Seyirde her şeyi, kayıtta Hızır. 

Her yanda sessizlik, her taraf ıssız

Ne kurt,  ne kuş; dehşet, vâhim manzara

Duygular körebe oynar ışıksız

Yusuf çoktan düştü kör kâlp mezara. 

Şâhitler şâhidi seyirde hâli

Yüklenir kardeşler ağır vebâli. 

Çok İnsaflı bir kurt, suçun fâili…

Gömlekte kan var, yok diş izleri(! ?) 

Aldatan ihtiras, şaşkın câhili…

Yaşla dolu gökyüzünün gözleri. 

Faydasız yalvarma, yakarma boşa

Gözyaşı işlemez, kâlp ise, taşa. 

Kuyuda Yusuf’un Yakup gözleri…

Yakup’un gözleri yangın diyarı..

Her sabah, her akşam; umut izleri…

Umut, kainatı dolaşan arı. 

Bir sevdâ kavuşmak, hüzün ayrılık

Boğar duyguları, çözün, ayrılık. 

13 – 07 – 2001', 'İhtiras, kıskançlık müzmin hastalık Tasarı, yok etmek engel hedefi… Nankörlük ruhlarda pörsük yamalık Yangına bir çıra kelime kâfi. Hareket ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yusuf-yakup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyin bir tarafı vardır.', 'herseyin-bir-tarafi-vardir-ensar-cevval-cgemy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bîtaraf bir şey yoktur yaşamda; 

nefes alıyorsa insan

yaşamdan  taraftır, 

ağlayan  çocuğa uzanan el

merhamet ise, 

ağlatılanın yüzünde

merhametsizliğe taraftır

öfke karşısında suskunluk

hüzün karşısında mutluluk

geceye karşı gündüz de taraftır.

Sevgiliyi  Gül''e

çile çeken aşığı Bülbül''e

kaşı Hilal''e, 

dudağı bal''a benzetmek

emsallerine karşı taraf olmaktır.

Gökyüzünde kanat çırpan kuşa rüzgar, 

denizde yüzen balığa akıntı taraftır.

Yüreğe yüklenen sevda özel ise

yürek de taraftır.

yaşadıklarımdan öğrendim ki

bîtaraf birşey yoktur yaşamda

ki yaşam bile ölümlülüğe taraftır.

29 Eylül 2003 Sirkeci-İstanbul', 'Bîtaraf bir şey yoktur yaşamda;  nefes alıyorsa insan yaşamdan  taraftır,  ağlayan  çocuğa uzanan el merhamet ise,  ağlatılanın yüzünde merh...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/herseyin-bir-tarafi-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Hiç', 'senin-hic-bilal-yalcinkaya-t1q73', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tank paletlerinde ezilen şehirlerin oldu mu? 

Mezarlıkları andıran şehirlerin

Deprem vurdu mu şehirlerini senin

Ve çadır çadır büyüdü mü

Yıkık kentlerin

 Senin hiç

Yakılan köylerin oldu mu? 

Yıkılan umutların

Senin hiç

İntihara giden evlatların oldu mu? 

Gidip dönmeyen

Senin hiç, 

Gök kubbeyi yırtan feryatların oldu mu? 

Karanlık geceden kalan

Şafağa düşman gecelerin oldu mu? 

Senin hiç, 

gözyaşlarını içtiğin gecelerin

Gencecik toprağa verip

Mezarda yaşını saydığın çocukların oldu mu? 

Senin hiç, 

Hayal kırıklıkların oldu mu? 

Kurduğun geleceğe batan

Senin hiç, 

Gölgesiz tebessümlerin oldu mu? 

Aynalarda kırılan

Bir çocuğun yüzünde yırtılan

Tebessümlerin.', 'Tank paletlerinde ezilen şehirlerin oldu mu?  Mezarlıkları andıran şehirlerin Deprem vurdu mu şehirlerini senin Ve çadır çadır büyüdü mü Yık...', ARRAY['Türk Edebiyatı','Şiir','Bilal Yalçınkaya']::text[], 8.5, '{"poet":"Bilal Yalçınkaya","poet_slug":"bilal-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/senin-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorunsuz Ülke Düşleri', 'sorunsuz-ulke-dusleri-bilal-yalcinkaya-ftb5k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim tanımsız yaralarım var

Kimseye tarif edemediğim

Hissettirmeden yaşanası yaralarım var benim

Özlemleri var dili bağlı gönlümün

Ve sen o gönlümün

Parasız pulsuz dilekçesiydin

Kimliğinden yaralı bir ceylandı bakışların

Haritanın en görünmez köşesinde

Bütüne ulaşmadan parçalara bölünmüştün

Bazen yokluğu yaşayan bir ülke

Bazen yoksulluk genini taşıyan 

bir halk oluyordun

isminin yasaklı duruşunda

hece hece büyüyordun sen

ama büyüyordun

kendini sonradan bulmuşluğun yüzyıl sıcaklığında

ihanet zehirli bir tohumdur toprağında ekilen

Ankara’dan görünmez acıların

Sıradağlar ardında gizli 

Batıdan doğuya doğru gittikçe

Artan bir ülkenin acısı

Ve sen

Acı bir müzik eşliğinde

Yaşıyordun hayatı

Acının en acımasızlaştığı

Çıkmaz sokakta........', 'Benim tanımsız yaralarım var Kimseye tarif edemediğim Hissettirmeden yaşanası yaralarım var benim Özlemleri var dili bağlı gönlümün Ve sen o...', ARRAY['Türk Edebiyatı','Şiir','Bilal Yalçınkaya']::text[], 8.5, '{"poet":"Bilal Yalçınkaya","poet_slug":"bilal-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sorunsuz-ulke-dusleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Yabangülü...', 'yabangulu-naime-erlacin-5d6sp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şiirin kölesi

ruhun efendisi 

ey söz! 

rüzgârın kölesi 

bozkır esintisi 

kemirgen soğuk! 

söyleyin 

kim buluşturdu sizi yüreğimde 

böylesine don tutucu 

bu iklimde 

kim vurdu kapımı habersiz 

bileğimde zincir 

elimde meşale beklerken 

kapı arkası nöbetinde

sözün dağ yolu patikasında

severek yoğurdum sizi 

yabangülü kadar nazenin bir ateşle

sıradan yolcular değildiniz

söyleyin 

kapımı kim vurdu? 

bu ses 

ilâhi bir armağan 

yabangülü gibi tanrının sunduğu

kapım mı çalınıyor yine? 

(30 Eylül 2003)', 'şiirin kölesi ruhun efendisi  ey söz!  rüzgârın kölesi  bozkır esintisi  kemirgen soğuk!  söyleyin  kim buluşturdu sizi yüreğimde  böylesine...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yabangulu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yolculuk', 'son-yolculuk-hicabi-ceylan-pgkxr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden dünya karardı

Sırtımda bunca senelerin yorgunluğu

Yaşantım bir flim şeridi gibi geçiyor gözlerimin önünden

Oturmuş ağlıyor yakınlarım, beni sevenler

Hissediyorum

Ayaklarım soğumaya başladı

Ne oldu sıkı örtün üstümü

O çok sevdiğim insan geliyor gözlerimin önüne

İster istemez bir iki damla yaş akıyor gözümden 

Hissediyorum

Dualar okunuyor baş ucumda

Üzerimde ölümün hafifği var

Birazdan götürecekler beni, yalnız hatıralarım kalacak dünyada

Herkes gelmiş son yolculuğumda beni uğurlamaya

Bir tek o yok canım kadar sevdiğim

Hissediyorum

Şimdi yalnızım kara toprakta

Ne sevenim var nede dostlarım yanımda

Üzerimdeki çiçeklerle, kuşlarla konuşuyorum

Bayramlarda sevdiklerim geliyor ziyaretime

Gözlerim yollarda onu bekliyorum gelmeyecek

Hissediyorum.

Hicabi Ceylan', 'Neden dünya karardı Sırtımda bunca senelerin yorgunluğu Yaşantım bir flim şeridi gibi geçiyor gözlerimin önünden Oturmuş ağlıyor yakınlarım,...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/son-yolculuk-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buralısın Arkadaş', 'buralisin-arkadas-hicabi-ceylan-waidy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oturmuşsun köşeye

Dikmişsin gözlerini şişeye

Bir adım daha yaklaşmışsın gerçeye

Belli bu akşam buralısın arkadaş

Ne o gözlerin yaşlanmış

Damlalardan gömleğinin yakası ıslanmış

Sen değil senin gönlün yaşlanmış

Belli bu akşam buralısın arkadaş

Başını eğmişsin yere

Sanki küsmüşsün kadere

Kapılmış gidiyorsun karşılıksız bir sevgiye

Belli bu akşam buralısın arkadaş

Yudum, yudum çektinmi içkini

Söylemeye başlarsın bütün derdini

Boş ver bu kadar bırakma kendini

Belli bu akşam buralısın arkadaş.

Hicabi Ceylan', 'Oturmuşsun köşeye Dikmişsin gözlerini şişeye Bir adım daha yaklaşmışsın gerçeye Belli bu akşam buralısın arkadaş Ne o gözlerin yaşlanmış Dam...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/buralisin-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sensizlik unutturamaz', 'seni-sensizlik-unutturamaz-hicabi-ceylan-3e0ht', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizlik sardı her yanımı

Kesseler bileğimi akıtsalar kanımı

Azrail gelse alsalar canımı

Sakın merak etme sen

Atamazlar içimden unutturamazlar adını

Doğru belki senden uzaktayım

Baktım kimse yok

O an ağlamaktayım

Unuttum sanma sakın 

Her gün adını anmaktayım

Hicabi Ceylan', 'Sensizlik sardı her yanımı Kesseler bileğimi akıtsalar kanımı Azrail gelse alsalar canımı Sakın merak etme sen Atamazlar içimden unutturamaz...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-sensizlik-unutturamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk', 'sonsuzluk-hicabi-ceylan-xv07v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün gece 

Deniz yine çağırdı beni

Oturdum sahil taşlarına

Derin bir nefes çektim sigaramdan

Aklımda bir tek sen vardın, yalnız sen

Ay''ın gölgesi düşmüştü deniz sularına

Sanki beni çağırıyordu ebedi sonsuzluğa

Dün gece 

Avazım çıktığı kadar bağırdım

Belki binlerce kere ismini andım

Seni çok sevdiğimi haykırdım

Hiç kimse yoktu yanımda, çaresizdim

Gözlerimden yaşlar bir, bir düşüyordu deniz sularına

Sanki beni çağırıyordu ebedi sonsuzluğa

Dün gece

Buralardan gitmek, uzaklaşmak istedim

Ama çare değildi

Senden uzaklarda, sensiz yaşayamazdım

O yüzden gidemiyorum buralardan

Sonra bir nefes daha çektim sigaramdan

Sigaramın külü düştü deniz sularına

Sanki beni çağırıyordu ebedi sonsuzluğa', 'Dün gece  Deniz yine çağırdı beni Oturdum sahil taşlarına Derin bir nefes çektim sigaramdan Aklımda bir tek sen vardın, yalnız sen Ay''ın göl...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sonsuzluk-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Üzülme', 'sen-uzulme-hicabi-ceylan-pff56', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni üzmemek için

Bu aşkı gömdüm içime

Seni unutmam imkansız

Artık her şey gidiyor gücüme

Buralardan gitmek istiyorum

Bu şehri terk etmek istiyorum

Vallahi ölmek istiyorum

Beni mutlu etsede

Bu aşkın acısı

Kalbim dayanmıyor artık

Bitmiyor''ki sancısı

Buralardan gitmek istiyorum

Bu şehri terk etmek istiyorum

Vallahi ölmek istiyorum

Gündüzlerim döndü geceye

Geçti ömrümün ilkbaharı

Hazırım bu aşk için ölmeye

Bak döktüm bütün yaprakları

Buralardan gitmek istiyorum

Bu şehri terk etmek istiyorum

Vallahi ölmek istiyorum

Hicabi Ceylan', 'Seni üzmemek için Bu aşkı gömdüm içime Seni unutmam imkansız Artık her şey gidiyor gücüme Buralardan gitmek istiyorum Bu şehri terk etmek is...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-uzulme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim', 'bekleyecegim-hicabi-ceylan-hi4lb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç umudum kalmasada

Gözlerim durmadan ağlasada

Kalbim bu ayrılığa dayanmasada

Seni bekleyeceğim

Benden ayrı yaşasanda

Senin için eriyip yansamda

Gelmeyeceğini bilsemde

Seni bekleyeceğim

Dünyama güneş doğmasada

Sana kavuşmam imkansız olsada

Yorgun bedenimi kara toprak alsada

Seni bekleyeceğim

Seni mahşerde bile bekleyeceğim

Hicabi Ceylan', 'Hiç umudum kalmasada Gözlerim durmadan ağlasada Kalbim bu ayrılığa dayanmasada Seni bekleyeceğim Benden ayrı yaşasanda Senin için eriyip yan...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bekleyecegim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-hicabi-ceylan-7csqg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün gece 

Saydım gökyüzündeki bütün yıldızları

Dilekler tuttum

Yalvardım Allahıma

Seni getirsin diye bana

Ama yoktun gelmedin

Ben yine yalnızdım karanlıkta

Dün gece

Başım eğik dolaştım şehrin karanlık sokaklarında

Hayaller kurdum

Çıkartım kalbimden resmini

Onunla konuştum

Ona anlattım bütün dertlerimi

Seni ölesiye, ölesiye sevdiğimi

Dün gece

Hep karanlıklarda kalmak ölmek istedim

Ne pısırık adamın ölmeyi bile beceremedim

Hicabi Ceylan', 'Dün gece  Saydım gökyüzündeki bütün yıldızları Dilekler tuttum Yalvardım Allahıma Seni getirsin diye bana Ama yoktun gelmedin Ben yine yalnı...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dilek-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürmeli', 'surmeli-sair-i-kincibaharim-86dne', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sürmeli gözlerin sürmeli, 

bilmem ki sana ne demeli..', 'Sürmeli gözlerin sürmeli,  bilmem ki sana ne demeli.....', ARRAY['Türk Edebiyatı','Şiir','Şair İkincibaharım']::text[], 8.5, '{"poet":"Şair İkincibaharım","poet_slug":"sair-i-kincibaharim","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/surmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaz geçmem senden', 'vaz-gecmem-senden-hicabi-ceylan-ul3av', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu aşkta hiç umudum olmasada

Gözlerim dolup, dolup ağlasada

Sen beni hiç sevmesende 

Vaz geçmem senden

Sevmişem seni

Önüme koysalar bütün engelleri

Kırsalar ayaklarımı ellerimi

Söylemez etseler dilimi

Vaz geçmem senden

Sevmişem seni

Dünyamı kara bulutlar sarsada

Sana ulaşacağım bütün yollar kapansada

Bu aşkın sonu ölüm olsada

Vaz geçmem senden

Sevmişem seni

Seni aramakla geçse bütün ömrüm

Daha tomurcukken açmadan solsa gülüm

Sana kavuşmadan gelse bana ölüm

Vaz geçmem senden 

Sevmişem seni.

Hicabi Ceylan', 'Bu aşkta hiç umudum olmasada Gözlerim dolup, dolup ağlasada Sen beni hiç sevmesende  Vaz geçmem senden Sevmişem seni Önüme koysalar bütün en...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vaz-gecmem-senden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akışkanlık', 'akiskanlik-muammer-celik-q3voi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir alışkanlığım var

Bir fobi ile 

Birde hobim var

Bir suçum var

Bir günahımla

Birde sevabım var

Bir eksiğim var

Bir hatam ile

Birde fazlam var

Bir ömrüm var

Bir yaşam ile

Birde ahiretim var

Bir sözcükte toplamak gerkirse hepsini

Bende bir tek ”senin aşkın” var

Gözlerinden ayıramadığım ”Bakışkanlığım” ile

Birde sana olan ”AKIŞKANLIĞIM”  var…

30.09.2003

BirDeli', 'Bir alışkanlığım var Bir fobi ile  Birde hobim var Bir suçum var Bir günahımla Birde sevabım var Bir eksiğim var Bir hatam ile Birde fazlam ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/akiskanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahne', 'sahne-hanife-efendioglu-5jl6l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamımın sahnesinde, 

Bir tek benim rolüm yok.

Oyuncuları hep, 

Sahne arkasından alkışlıyorum.', 'Yaşamımın sahnesinde,  Bir tek benim rolüm yok. Oyuncuları hep,  Sahne arkasından alkışlıyorum....', ARRAY['Türk Edebiyatı','Şiir','Hanife Efendioğlu']::text[], 8.5, '{"poet":"Hanife Efendioğlu","poet_slug":"hanife-efendioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sahne-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür', 'omur-hicabi-ceylan-h4h4p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu dünyaya gelen gider

Gül artık bitsin keder

Dostlar bizi birer, birer

Zamanı gelince terk eder

İşte bir ömür böyle geçti

Bazen yürü bazen koş

Bazen acı bazen hoş

Bazen ağla bazen coş

Bu dünya inanki boş

İşte bir ömür böyle geçti

Hicabi Ceylan', 'Bu dünyaya gelen gider Gül artık bitsin keder Dostlar bizi birer, birer Zamanı gelince terk eder İşte bir ömür böyle geçti Bazen yürü bazen ...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/omur-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaçan', 'gunacan-oguzkan-bolukbasi-oufx0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin adın Günaçan olsun

Yani güneş

Yani rüzgar

Yani yağmursun

Sen kimsin bilmiyorum

Tek bildiğim 

Ararsam bulunursun', 'Senin adın Günaçan olsun Yani güneş Yani rüzgar Yani yağmursun Sen kimsin bilmiyorum Tek bildiğim  Ararsam bulunursun...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gunacan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarının Umudum Olsun', 'yarinin-umudum-olsun-engin-aktepe-ntzh7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürek kapıda sırt bıçak olsa

Kanatacak benliğimi umarsızca sonsuza

Dosta sevda sözlerim var yaşatacak gençliğim

Ellerin uzak bana rüzgarlara tutundum

Bugün değil yarınımsın

Deniz değil deryamsın

Sana hasret gecelerde 

Düşüm değil yanımdasın

Sende koş sevdalara

Çiyan dolu sarp yollara

Yarının umudum olsun

Sal kendini bulutlara', 'Yürek kapıda sırt bıçak olsa Kanatacak benliğimi umarsızca sonsuza Dosta sevda sözlerim var yaşatacak gençliğim Ellerin uzak bana rüzgarlara...', ARRAY['Türk Edebiyatı','Şiir','Engin Aktepe']::text[], 8.5, '{"poet":"Engin Aktepe","poet_slug":"engin-aktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yarinin-umudum-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasaydın, Sormazdın', 'anlasaydin-sormazdin-muammer-celik-tsvy8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir itirazım

birde maruzatım

var sana… 

Eyy aşk-i murazım

Söylemem; 

”Neydi? ” diye

 sorma sakın 

anlasaydın

sormazdın 

ve yapardın zaten…! 

30.09.2003

BirDeli', 'Bir itirazım birde maruzatım var sana…  Eyy aşk-i murazım Söylemem;  ”Neydi? ” diye  sorma sakın  anlasaydın sormazdın  ve yapardın zaten…! ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlasaydin-sormazdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgaci', 'dalgaci-huseyin-cayikli-paryg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dalgaci

isi olmadigi zaman 

disari cikip gezen adamdir...

aslinda hic isi olmadi dalgacinin

neden ona dalgaci derler 

bilmem...

belki:noktali virgullerle ayirmistir hayatini

aslinda isi hic olmamistir dalgacinin

aksam cikip gezmek disinda

neden ona dalgaci derler 

bilmem

belki de:dalgalara karsi geldigi icindir

dalgaci aksamlari cikar sokaga

sokak fahiselerinin cigliklariyla yurur

oysa o kac fahiseye asik olmustur

dalgaci yine daldi bu gece denize

belki istiridye kabugu seklinde ki evinde

aksamalari cikar sokaga

caddelerin sorunudur yalnizlik

ama onda da yalnizlik var.

erkeklik degildir ama 

boynunun borcudur aksamlari yasamak

zor istir dalgaci olmak

hep baska sehirlere 

goc etmek kolay degildir...

her sehirde bir kadina vurulmak...

dalgaci daldi bugun uzak bir denize 

en son gorenler dalgaciyi 

dalgaya kapildi dediler...', 'dalgaci isi olmadigi zaman  disari cikip gezen adamdir... aslinda hic isi olmadi dalgacinin neden ona dalgaci derler  bilmem... belki:noktal...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dalgaci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırgınım', 'kirginim-tuncay-ulak-dt6jc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Korkarak baktım gündüz, 

Hep aynı kederli yüz, 

Mutluluktan yok bir iz, 

Aynalara kırgınım.

Bedenim kırık dökük, 

Takat ve ruh kalmış sönük, 

Tebessümler neden tek tük? 

Sebebime kırgınım.

Düşüncemse allak bullak, 

Her umudum tepe taklak, 

Geziyorum aylak aylak, 

Yarınlara kırgınım.

Sözlerim hep fuzuli, 

Keder bitap yapmış dili, 

Fikir ahmak zihin deli, 

Gülenime kırgınım.', 'Korkarak baktım gündüz,  Hep aynı kederli yüz,  Mutluluktan yok bir iz,  Aynalara kırgınım. Bedenim kırık dökük,  Takat ve ruh kalmış sönük,...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Ulak']::text[], 8.5, '{"poet":"Tuncay Ulak","poet_slug":"tuncay-ulak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirginim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dermanim', 'dermanim-erhan-ergun-clhuz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Esmer güzelim benim dermanimi görmüyormusun? 

Siir yazmayan bir adamdim ben, 

ama sana olan sevgimi Siir''lere yazmaya basladim, 

kalbimdeki duygularimi anliyasin diye.

Siir''lerimi okuyorsun ve güzel olmus diyorsun

ama anlamiyorsunki bu Siir''leri sadece

sana yazdigimi!', 'Esmer güzelim benim dermanimi görmüyormusun?  Siir yazmayan bir adamdim ben,  ama sana olan sevgimi Siir''lere yazmaya basladim,  kalbimdeki ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Ergün']::text[], 8.5, '{"poet":"Erhan Ergün","poet_slug":"erhan-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dermanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minik Yürek', 'minik-yurek-serpil-baskic-oezic', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana bu ilk şiirim

Senin için ilk damlam

İçimde bir kelebek durmadan çırpınıyor

Sanki; 

Anlamını çözemediğim birşeyler diyor

Ne dersin aşk mı bu? 

Hani aşk yoktu...........? 

Peki bu içimdeki neyin nesi

Bu yüreğimdeki kazı çalışmasıda nereden çıktı? 

Eski sayfaları sildim

Anladım ki hiç bir şey yaşamamışım

Şimdi sen yazılacaksın yüreğimin her köşesine

Ve

Yüreğimin en temiz yeriyle seveceğim seni

Hissedebiliyorum

Sana olan sevğim bambaşka hissedebiliyorum

Sen başkasın

Sen sevimli şirin bir bebeksin

Bu minik yürekte ölürcesine sevilmek istiyorsan

Tut bilekleri ve çek kendine İşte yüreğimdesin

Ömür boyu sevileceksin.

06.05.2003', 'Sana bu ilk şiirim Senin için ilk damlam İçimde bir kelebek durmadan çırpınıyor Sanki;  Anlamını çözemediğim birşeyler diyor Ne dersin aşk m...', ARRAY['Türk Edebiyatı','Şiir','Serpil Baskıç']::text[], 8.5, '{"poet":"Serpil Baskıç","poet_slug":"serpil-baskic","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/minik-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-ali-osman-yilmaz-hp8f6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilinmiyor acep neden? 

Bu güzellikleri yaratan kim? 

Tüm doğaya yalnızca odur hakim

İyice bakın belki bileceksiniz o kim.

Doğadaki güzelliklerin anası sevgidir

Sevda ateşinde bağlanan ona er’idir

Aşk ocağında filizlenir, çiçek açar yeşerir

Tomurcuk gül olur, bakan her canlı iç geçirir.

Mine taşı gibi beyaz ve berraktır sevgi

Öz’den gelir sağlamdır Demir gibi

Taş gibi sert, Engin gönüllerde yumuşak

Aşk ocağının ateşini durmadan yakar sevgi.

Ateşinin közünde yanar olgunlaşır aşık

Sarrafın elinden yansır sanki bir ışık

Bazen başta taç olur, bazen gönülde sultan

Sanki ak gerdanda dizili incidir, parıldayan.

Sevgi ekilen gönüllerde açar yeni sevgiler

El ele tutuşur bahçelerde gezinir sevgililer

Kırmızı güldür Yetmez aşığa, bir sarılmak ister 

Hareler oluşur gül yanakta, gülümserken gamzeler.', 'Bilinmiyor acep neden?  Bu güzellikleri yaratan kim?  Tüm doğaya yalnızca odur hakim İyice bakın belki bileceksiniz o kim. Doğadaki güzellik...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgi-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen? ? ? ?', 'sen-seyda-sarica-2lubx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aklıma acımla işliyorum seni.....

her gelişin yokluğunu..

her gidişin de 

varlığını anımsatıyor....

28.09.2003', 'aklıma acımla işliyorum seni..... her gelişin yokluğunu.. her gidişin de  varlığını anımsatıyor.... 28.09.2003...', ARRAY['Türk Edebiyatı','Şiir','Şeyda Sarıca']::text[], 8.5, '{"poet":"Şeyda Sarıca","poet_slug":"seyda-sarica","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-292-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözüm Var', 'gozum-var-fatih-konuk-7m178', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne parada 

ne pulda

ne de sarayda

gözüm var

ne dosta

ne düşmana

ne de gardaşa

sözüm var

ne gülecek

ne ağlayacak

ne de eğlenecek 

halım var', 'ne parada  ne pulda ne de sarayda gözüm var ne dosta ne düşmana ne de gardaşa sözüm var ne gülecek ne ağlayacak ne de eğlenecek  halım var...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozum-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sür''ât', 'son-sur-t-mustafa-engin-karatay-vu6ay', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gün Yetmiş günâhı, tamamlamak maksatla; 

Dehşetengiz biçimde gayret sarfediyorsun... 

Olmadı, Yetmiş arttır; çoğalt, iyice katla! 

Cehennem ateşine, son sür''ât gidiyorsun... 

10.08.2003 Münih 05:05', 'Her gün Yetmiş günâhı, tamamlamak maksatla;  Dehşetengiz biçimde gayret sarfediyorsun...  Olmadı, Yetmiş arttır; çoğalt, iyice katla!  Cehen...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/son-sur-at-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadım', 'yasadim-celal-sahin-veiai', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarın olmayacakmış gibi bugünü  yaşadım

Ufukların berraktı, İşten başımı kaldırmadım

Bütün dengelerimi başarı üzerine kurdum

Başkalarını mutlu etmeyi muradım sandım

Yamalı hakikatler peşinde hep kaybettim.

Gün geldi artık yaşadıklarıma yeter dedim

Fil mezarlığına dönmeye hazırlandım.

Beyaz lale üzerinde mavi çiğ tanesi gözlerin

Sevda ateşine gümüş tömbeki gibi ellerin

Gönül zindanımın anahtarı oldu sözlerin.

Gözlerinle gökkuşağına merdiven dayadım.

İçimdeki çocuğa sarılma zamanımı yaşadım

Kış uykusundan uyanır gibi uyandım

Bütün kurallarımı itina ile yıktım.

Sana gelmek için kendimi bile hiçe saydım.

Geridi kalanları düşünmeden gemileri yaktım

                               11/09/2003', 'Yarın olmayacakmış gibi bugünü  yaşadım Ufukların berraktı, İşten başımı kaldırmadım Bütün dengelerimi başarı üzerine kurdum Başkalarını mut...', ARRAY['Türk Edebiyatı','Şiir','Celal Şahin']::text[], 8.5, '{"poet":"Celal Şahin","poet_slug":"celal-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasadim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-salih-ozalasan-k3wvi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitme diyemedim bakıp kaldım ardından

Yüreğim seninleydi mecnun olmuştum aşkından

Bir gün olsun gülmedim çekiyorum bahtımdan

Gitme; yüreğim sende vazgeçemem senden

Sevda denizinde yüzen bir gemiydik

Aşkın rüzgarına kapılmış ne yerde ne gökteydik

Gidişin ölümden beter, hırsa yenildik

Gitme; yüreğim sende vazgeçemem senden

Gece sensiz ıssız, yıldızlar sönmüş

Umutlarım tükenmiş omuzlarım çökmüş

Dualarım hep sana, gözyaşım sele dönmüş

Gitme; yüreğim sende vazgeçemem senden

Biliyorum gideceksin yalvarmam boşuna

Aşkınla mecnun oldum gitmedi hoşuna

Bir sana adadım ömrümü muhtacım aşkına

Gitme; yüreğim sende vazgeçemem senden

Belliydi böyle habersiz gideceğin

Bana eyvallah sana güle, güle diyeceğin

Sevdan yalanmış sende gör diyeceğim

Gitme; yüreğim sende vazgeçemem senden

Üşürüm sensizliğe asla alışamam

Yüreğim sendeyken sensiz yaşayamam

Gözüm açtım seni gördüm, gözlerimi sensiz kapayamam

Gitme; yüreğim sende vazgeçemem senden

Gittiğin yerlerde bendeki sevgiyi bulamazsın

Bensiz yaşarsın ama mutlu olamazsın

Gidiyorum diyorsan al yüreğim sende kalsın

Gitme; yüreğim sende vazgeçemem senden

Y.Tarihi 30-09-2003 Saat 20.35

Salih ÖZALAŞAN', 'Gitme diyemedim bakıp kaldım ardından Yüreğim seninleydi mecnun olmuştum aşkından Bir gün olsun gülmedim çekiyorum bahtımdan Gitme; yüreğim ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gitme-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zülfü-yare Dokundu...', 'zulfu-yare-dokundu-umut-gul-67lsj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'iki satır bir şey yazdım 

kendimi şair sandım, 

aşk badesini içtim

kendimi mecnun sandım

yazdım gönül dolusu

zülfü yare dokundu

caydım yazmıyorum dedim

yarin zülfü  döküldü...', 'iki satır bir şey yazdım  kendimi şair sandım,  aşk badesini içtim kendimi mecnun sandım yazdım gönül dolusu zülfü yare dokundu caydım yazmı...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zulfu-yare-dokundu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yazdık', 'seni-yazdik-yasemin-kaplan-x5rb7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'maşrabasından 

güneş döktük saçlarına

biz seni yazdık

ey derya-dil kızım

hüsnü derununda

denizine değdik

demlendik

uzun yollardan geldik

herşeyi yaktık

bir sen kaldın

bir de sokrates sözlerin

yani diyorum

serden geçtik 

sana geldik

gül üşümelerinde

gülüşüne sığındık en çok

bir de yangın sözlerine

sözlerinle ısındık

derya-dil kızım

annendim

derdindim

sensiz

sözünsüz

üşümekteyim...', 'maşrabasından  güneş döktük saçlarına biz seni yazdık ey derya-dil kızım hüsnü derununda denizine değdik demlendik uzun yollardan geldik her...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Kaplan']::text[], 8.5, '{"poet":"Yasemin Kaplan","poet_slug":"yasemin-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-yazdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çatal Yürek', 'catal-yurek-muammer-celik-dmb4f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vur bre yürektaşım

daha hızlı vur 

o yumrukları bağrıma...

Vur ki delinsin

hatta çatlasın

bölünsün ikiye 

göğüs kafesim…

Olmazsa sapla iyice

dibine kadar bir sancak…

Korkma! 

içinden sadece

lavları yakıcı

sıcağı kavurucu

ateşi ısıtıcı

çarpışı ve cırpınışı 

AŞK olan 

ikiye bölünmüş

kocaman 

ÇATAL bir yürek 

............................çıkar ancak! 

01.10.2003

BirDeli

(Gönül  Gönül akmış bir şiire, çeşni kıvamında bir karşılık)', 'Vur bre yürektaşım daha hızlı vur  o yumrukları bağrıma... Vur ki delinsin hatta çatlasın bölünsün ikiye  göğüs kafesim… Olmazsa sapla iyice...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/catal-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Dinledikçe', 'siir-dinledikce-zeki-ergin-fvg0h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ilk kez karşılaşsam da

kırk yıllık dostlarımdı onlar

şiir üstüne 

koyulaşıyordu sohbet

kadehler yenilendikçe

şarkı ve şiir dinledikçe

hasret mişiz meğer

içten dostluklara

dünden  yarınlara uzanacak

ve birbirimizi kucaklayacak

_kadıköy 30eyl03

_sevgiliye isyan yt:haz04', 'ilk kez karşılaşsam da kırk yıllık dostlarımdı onlar şiir üstüne  koyulaşıyordu sohbet kadehler yenilendikçe şarkı ve şiir dinledikçe hasret...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siir-dinledikce-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kördüğüm', 'kordugum-ahmet-aksoy-zx7yx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gök taşı tufanına maruz kalmışken yüreğim

Ki bir gezegendir, dünyandır yüreğim senin

Sanır mısın en hassas yerinden vurmaz seni

Beni yakarken kızgın parçalar, dikilirken önünde

Beni delip geçmez mi sanırsın gerçekten

Daha ne kadar dayanırım bilmezken

Sen bilir misin ne zaman biter bu tufan

Elbette bilemezsin çünkü sen sadece

Yaramaz bir çocuk gibi düşürdün halıya kibriti

Bense yanıyorum yangınının içinde 

Ki artık korkmuyorum zarar görmenden

Çünkü ben kıvranırken bir kez olsun

Düşünmedin tattığım ateşin yakışını

Tek korkun zarar görmekti zaten

Öyle ki ben ölürken tek düşündüğün

Gitmekti ve gittin de lakin gidişinle

Öyle büyüdü ki acım, dünyan bir depren arifesinde', 'Gök taşı tufanına maruz kalmışken yüreğim Ki bir gezegendir, dünyandır yüreğim senin Sanır mısın en hassas yerinden vurmaz seni Beni yakarke...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kordugum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Karşılaşmamız', 'i-lk-karsilasmamiz-ahmet-aksoy-82mor', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk karşılaşmamız 

Bir alışveriş soluklanmasında

Bir köşe başındaydı

Aşkımızsa

Bir merhabanın ortasında başlamıştı

Elin kolun doluydu o an

Yanındaysa bir arkadaşın vardı

Gözlerimiz raks etmişti 

Vücudumuzdaki damarlar titrerken

Ve oradan ayrılmıştık

Gözlerimiz edepsiz dilimiz emekli

Ki ilk görüşte aşk bu olmalıydı 

Diye düşünüyorum şimdilerde

Öyle ki daha kaç kez  aynı yerde

Karşılaşmıştık yapay tesadüflerde

Ki kaç kez daha dans etmişti gözlerimiz

Ve bir merhaba da başlayan aşkımız

Yetişmesi gereken insanların acelesinde

Aynı köşe başında bir çarpışma halindeydi

Bir merhabadan bir affedersinize kadar

Sürebilmişti birlikteliğimiz

İlerlemiş yaşımıza denk olmalıydı ki

Utangaçlığımız ir daha ne sen oradayken

Ne de ben oradayken karşılaşmıştık 

Neyse ki sonumuz bir aşka uygun düşmüştü

En azından bu dünyada ayrılmıştık.', 'İlk karşılaşmamız  Bir alışveriş soluklanmasında Bir köşe başındaydı Aşkımızsa Bir merhabanın ortasında başlamıştı Elin kolun doluydu o an Y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ilk-karsilasmamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Bu Yüzden', 'i-ste-bu-yuzden-ahmet-aksoy-3yke5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhumu karanlığa boğarak

Ritmini tutturmuş

Bir saat gibi 

Vurur aklıma gölgen

İşte bu yüzdendir

Doğamamış çocuk huzursuzluğum

Çıkarken kapıya kapatmadığındandır

Gözlerimin hala eşikte oluşu

Oysa nasılda daralıyordu

Sen uzaklaşırken ardından sokak

Ki bakış açım ilelebet sana açılıyordu

İşte bu yüzden olmalı ufuksuzluğum

Yürüyüşünle dünyan genişliyordu

Ve her adımınla, zaman

Sanki bana sırtını dönüyordu

Ki perspektifi ters bir yürüyüştü bu.

Sana zamanı veriyorum demiştin giderken

Çünkü bir geleceğim vardı senden sonra

Unuttuğundan mı yoksa 

Bilerek bıraktığından mı bilmem

Aslında bana verdiğin 

Sadece bir saatti giderken

İşte bu yüzden olmalı 

Hediyene sahip çıkışım

İşte bu yüzden olmalı

Bir akreple ve bir yelkovanla  ahbap oluşum

İşte bu yüzden olmalı

Günde 86400 kez seni hatırlayışım.', 'Ruhumu karanlığa boğarak Ritmini tutturmuş Bir saat gibi  Vurur aklıma gölgen İşte bu yüzdendir Doğamamış çocuk huzursuzluğum Çıkarken kapıy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/iste-bu-yuzden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onaltı yaş', 'onalti-yas-nejat-karagoz-2unkw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ateş saldın gönlüme, bu zamansız gidişinle

Yaktın yüreğimi yavrum, sönmeyecek ateşinle

Yüreğime serptiğim su yandı; söndürmedi beni

Belki teselli bulurum duvardaki gülüşünle.', 'Bir ateş saldın gönlüme, bu zamansız gidişinle Yaktın yüreğimi yavrum, sönmeyecek ateşinle Yüreğime serptiğim su yandı; söndürmedi beni Belk...', ARRAY['Türk Edebiyatı','Şiir','Nejat Karagöz']::text[], 8.5, '{"poet":"Nejat Karagöz","poet_slug":"nejat-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/onalti-yas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-aysun-elagoz-qbo8k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüzün çöker bahar bahçeme

ne zaman 

ayağında yırtık pabuçlarla

bir çocuk görsem

zemheri günlerinde....

ayazın çatlattığı yüzdeki

masum bakışlar

yüreğime batar

ok gibi, bıçak gibi

Yağmur taşar gözlerimden

sel basar mutluluklarımı

ne zaman

bir çocuk görsem

üşümüş, aç

ve yırtık pabuçlu...', 'Hüzün çöker bahar bahçeme ne zaman  ayağında yırtık pabuçlarla bir çocuk görsem zemheri günlerinde.... ayazın çatlattığı yüzdeki masum bakış...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cocuk-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgı', 'yanilgi-aysun-elagoz-3jows', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç şiir yazamam sanmıştım 

sen

beni böyle bırakıp

gittikten sonra, 

işte yazıyorum.....

demek ki hala yaşıyorum...', 'Hiç şiir yazamam sanmıştım  sen beni böyle bırakıp gittikten sonra,  işte yazıyorum..... demek ki hala yaşıyorum......', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yanilgi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-gulay-yildiz-aobay', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessiz ve ılık bir sıcaklıktı gecenin sunduğu 

Ardından derin bir çığlık ve ağlama 

''Yeryüzünün en nadide parçası'' demiş annem adıma 

Adımla bütünleşmişim o an 

Hassas, alıngan, kırılgan... 

Gülümseyen, gülümseten 

Gül kadar narin ama kutsal 

Ay kadar parlak ve sadık olmuşum 

Dönmüşüm etrafında sevdiklerimin bin tavaf adına 

Yıldız kadar parlamışım kendi yüzüme 

Yansımış kalbimden ışıklar sevdiklerime 

Ve en soysuz günün birinde 

Çalmışlar kalbimi, sevgimi... 

Bekleyen olmuş adım 

Uğursuz geceleri bekleyen, 

Aşksız hayatı bekleyen olmuşum... 

Acı olmuş diğer adım, yüzüm solmuş 

Dedim ya, 

''Yeryüzünün en nadide parçası'' demiş annem adıma 

Almış tekrar koynuna, ısıtmış 

Hergün bıkmadan yeni bir ben olmuşum...', 'Sessiz ve ılık bir sıcaklıktı gecenin sunduğu  Ardından derin bir çığlık ve ağlama  ''Yeryüzünün en nadide parçası'' demiş annem adıma  Adımla...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parabolik Paranoya', 'parabolik-paranoya-oguzkan-bolukbasi-nfjjm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu evrende ne varsa zevk-ü sefa adına

Beni cehenneme götürmek için yaratılmış

Neyin varmak ister  isem tadına

Peşine affedilmez bir de günah takılmış', 'Bu evrende ne varsa zevk-ü sefa adına Beni cehenneme götürmek için yaratılmış Neyin varmak ister  isem tadına Peşine affedilmez bir de günah...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/parabolik-paranoya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmemeliydim Seni', 'sevmemeliydim-seni-salih-ozalasan-3lq77', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmemeliydim böyle delicesine seni

Bilmeliydim seninle yaşayacağımı cehennemi

Hayat senle güzeldi, yokluğun yaktı sinemi

Gideceğini biliyordum neden sevdimki seni

Sen sevdalara açmayacaktın benimle yelken

Hiç ama hiç tanımayacaktım seni

Şimdi cehennemde bir zebani

Tanrım senin sevdan ile yakıyor beni

Gözyaşım aksada yok bana bir faydası

Geceler zindan yok bunun çaresi

Gönlüm olmuş bir dama tahtası

Gelişin meltem, gidişin karayel yokettin beni

Y.Tarihi 30-09-2003 Saat 23.55

Salih ÖZALAŞAN', 'Sevmemeliydim böyle delicesine seni Bilmeliydim seninle yaşayacağımı cehennemi Hayat senle güzeldi, yokluğun yaktı sinemi Gideceğini biliyor...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevmemeliydim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıplak Çocuklar', 'ciplak-cocuklar-yasemin-kaplan-u4c8o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çıplak çocuklar vardı 

düş denizinde gezinen

minik ellerinde 

hayatın

küçük görünen

dev ayrıntıları

ve hepsi 

düşlerinin denizine daldı...', 'çıplak çocuklar vardı  düş denizinde gezinen minik ellerinde  hayatın küçük görünen dev ayrıntıları ve hepsi  düşlerinin denizine daldı......', ARRAY['Türk Edebiyatı','Şiir','Yasemin Kaplan']::text[], 8.5, '{"poet":"Yasemin Kaplan","poet_slug":"yasemin-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ciplak-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme Sesleniş 4', 'anneme-seslenis-4-refik-yildiz-nt22n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep hasretten koşardım sarılsam diye sana

Anlatırdım derdimi bir sen anlardın anne

Yollar bitmek bilmezdi kavuşana dek sana

İzlerini kaybettim nerelerdesin anne 

Oğlum dedikçe ağzın şefkat beni bürürdü

Tebessümün hüznümü alıp da götürürdü                          

Bakışın ki içimde açan tazecik bir güldü

Sesini duyamadım nerelerdesin anne

Üstümü açsam uykuları bölünürdü

Hafifçe öksürsem koşar hemen gelirdi

Yemeyip yedirir, giymeyip giydirirdi

Seni ararım seni nerelerdesin  anne', 'Hep hasretten koşardım sarılsam diye sana Anlatırdım derdimi bir sen anlardın anne Yollar bitmek bilmezdi kavuşana dek sana İzlerini kaybett...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anneme-seslenis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmıştım', 'sanmistim-refik-yildiz-qumu3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buz tutmuş sokaklardan sana koşarken bu gün

Ne de ümit doluydum; el açarsın sanmıştım

Benzersiz baharlardan yıldız çalan gözlerin

Gözlerin alır beni sarar beni sanmıştım

Bazen hayat öyle zor öyle acımasızki canım

Sen bilirsin anlarsın anlaşırız sanmıştım

Dökülsede ne çıkar birkaç damla gözlerden

Avuçlarında kurur, geçer gider sanmıştım', 'Buz tutmuş sokaklardan sana koşarken bu gün Ne de ümit doluydum; el açarsın sanmıştım Benzersiz baharlardan yıldız çalan gözlerin Gözlerin a...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sanmistim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-refik-yildiz-dqcf3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dertler dert üstüne konduğu zaman

Haykırsam olmuyor, sussam olmuyor

Keder içten içe yıktığı zaman

Ağlasam olmuyor, sussam olmuyor

Dostlarım elimi ittiği zaman

Verilen ahitler bittiği zaman

Sevinç semtimizden gittiği zaman

Yaşasam olmuyor, ölsem olmuyor

Vaadlerin vadesi bittiği zaman

Bel bağlanan dağlar çöktüğü zaman

İnsanların asıl yüzü çıktığı zaman

Yıkılsam olmuyor, kalsam olmuyor

Kurtlar sahte postu attığı zaman

Sırtlanlar pusuya yattığı zaman

Dünya maskesini yırttığı zaman

Sensiz yaşanmıyor, sensiz olmuyor

Yüzümü kıbleye döndüğüm zaman

Kutlu dergahına girdiğim zaman

Yüz çevirip yeniden döndüğüm zaman

Konuşsam olmuyor, sussam olmuyor

Hicabım yaş olup aktığı zaman

Ve gözyaşım yüzümü yaktığı zaman

Sesim titreyerek çıktığı zaman

Secdeden gayrisi o an olmuyor...', 'Dertler dert üstüne konduğu zaman Haykırsam olmuyor, sussam olmuyor Keder içten içe yıktığı zaman Ağlasam olmuyor, sussam olmuyor Dostlarım ...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olmuyor-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-sinan-guven-wtaor', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanıma gel tut elimi, 

Kalbim fırlasın yerinden.

Gözlerin kilitlensin gözlerime, 

Bir ateş sarsın vücudumu derinden.

Olmaz deme yaklaş biraz, 

Bedenim hissetsin sıcaklığını.

Dudaklarım dudaklarına değsin, 

Doya doya tatsın ıslaklığını.', 'Yanıma gel tut elimi,  Kalbim fırlasın yerinden. Gözlerin kilitlensin gözlerime,  Bir ateş sarsın vücudumu derinden. Olmaz deme yaklaş biraz...', ARRAY['Türk Edebiyatı','Şiir','Sinan Güven']::text[], 8.5, '{"poet":"Sinan Güven","poet_slug":"sinan-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevda-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-sinan-guven-p2um6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni öyle özlüyorum anlatamam

Yüreğim tepeden tırnağa seninle doluyor

Hani iki kadeh te içince  akşam

Hasretin inan dayanılmaz oluyor.', 'Seni öyle özlüyorum anlatamam Yüreğim tepeden tırnağa seninle doluyor Hani iki kadeh te içince  akşam Hasretin inan dayanılmaz oluyor....', ARRAY['Türk Edebiyatı','Şiir','Sinan Güven']::text[], 8.5, '{"poet":"Sinan Güven","poet_slug":"sinan-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozlem-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-sinan-guven-79f87', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özledim birtanem özledim seni

Ela gözlerini ince belini

Özledim topuz saçlarını, narin tenini

Özledim birtanem çok özledim

Tepeden tırnağa seni.', 'Özledim birtanem özledim seni Ela gözlerini ince belini Özledim topuz saçlarını, narin tenini Özledim birtanem çok özledim Tepeden tırnağa s...', ARRAY['Türk Edebiyatı','Şiir','Sinan Güven']::text[], 8.5, '{"poet":"Sinan Güven","poet_slug":"sinan-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ozledim-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutsuzum', 'mutsuzum-sinan-guven-ul8bk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnız seni görmek yetmiyor bana

Öpüp okşayamadiktan sonra seni, 

Dokunamadıktan sonra sana, 

Mutsuzum, 

Yetmiyor yalnız telefon etmek, 

Mesaj yollamak numarana, 

Çoğu kez bunları bile yapmak zor

Öyle kızıyorum ki bazen babana…

Mutsuzum, 

Başkasıyla gözgöze görünce seni, 

Hele tutunca bir başkası ellerini, 

Bir ateş sarıyor tüm bedenimi, 

Çünki ben seni seviyorum, seni', 'Yalnız seni görmek yetmiyor bana Öpüp okşayamadiktan sonra seni,  Dokunamadıktan sonra sana,  Mutsuzum,  Yetmiyor yalnız telefon etmek,  Mes...', ARRAY['Türk Edebiyatı','Şiir','Sinan Güven']::text[], 8.5, '{"poet":"Sinan Güven","poet_slug":"sinan-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mutsuzum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-sinan-guven-1a345', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluk nedir bilir misin? 

Mutluluk seni her sabah görmektir.

Birkaç kelime konuşmak, 

Senin gözlerine bakıp gülmektir.

Mutluluk nedir bilir misin? 

Mutluluk dokunmaktır sana, 

İnce beline sarılıp sıkıca, 

Şükretmektir tanrıya.

Mutluluk nedir bilir misin? 

Mutluluk koklamaktır tenini, 

Dudaklarımı dokundurup dudaklarına, 

Doyasıya öpmektir seni.', 'Mutluluk nedir bilir misin?  Mutluluk seni her sabah görmektir. Birkaç kelime konuşmak,  Senin gözlerine bakıp gülmektir. Mutluluk nedir bil...', ARRAY['Türk Edebiyatı','Şiir','Sinan Güven']::text[], 8.5, '{"poet":"Sinan Güven","poet_slug":"sinan-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mutluluk-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne ilkim, Ne de son olacağım', 'ne-ilkim-ne-de-son-olacagim-muammer-celik-txe9v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben oğulum

ben kocayım

ne ilkim

nede son olacağım...

ben askerim

ben muhafızım

hem beklerim

hem severim

ben anamın oğluyum...

gelin kumasıdır anamın

ben yatarım

ben kalkarım

ben söverim

ben erkeğim

ben kadına köleyim aslında…! 

Babaya nesil

evlada geçmişim

anam kalkanım

namusumdur avradım

ben onlara yemin ederim

yeminimde anamı avradım

bacımı da karım ederim

karıma söveni ise döverim…! 

Ben neymişim

kendimde anlamadım

biliyorum ben ne ilkim 

ne de son olacağım…

Ama bu silsileyi

oğlumdan önce 

ben kıracağım…! 

01.10.2003 

BirDeli', 'Ben oğulum ben kocayım ne ilkim nede son olacağım... ben askerim ben muhafızım hem beklerim hem severim ben anamın oğluyum... gelin kumasıdı...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ne-ilkim-ne-de-son-olacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkarım', 'korkarim-sair-archi-o2ndh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarımla suluyorum

Hergece; 

Yüreğime ektiğin acıları.

Dikenleri büyüdükçe, 

Daha çok kanatıyor içimi.

Kanadıkça; 

Yüceltiyor sevgimi.

Sana anlatamam, 

Gülü severken 

Dikene sarılmayı.

Anlamandan korkarım...', 'Gözyaşlarımla suluyorum Hergece;  Yüreğime ektiğin acıları. Dikenleri büyüdükçe,  Daha çok kanatıyor içimi. Kanadıkça;  Yüceltiyor sevgimi. ...', ARRAY['Türk Edebiyatı','Şiir','Şair Archi']::text[], 8.5, '{"poet":"Şair Archi","poet_slug":"sair-archi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/korkarim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kartopu', 'kartopu-orhan-balta-ablr0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bebek yuzlu..

Yarim guluslu..

mahsun bakisli..

 kartopum

belki bir kardan adam yapacaklar seni..

hayat denen bahcede

burnuna bir havuc takip gulecekler..

belkide cocuklar haylazca taslayacaklar seni.

direnme gucun sogugun oldugu kadar guclu..

ruzgarin estigi kadar var olacak..

bir gunes sicakliginda eriyip gideceksin....

belkide  yasamdan..

Oysa...

sen tum guzellikleri yasayabilecek asirlik bir cinar gibi..

var olmalisin hayatin icinde..

birileri seni yonlendirmemeli..

sen birilerini suruklemelisin pesinde..

ozgur bir tay gibi kosabilmelisin kirlarda..

sevgiyle kucaklaya bilmelisin sevdiklerini..

icine akitmamalisin gozyaslarini..

seninle bir olan sevenlerinle aglamalisin..

iste  o zaman..

yasadikca kocamanlasacak...

 yasadikca anlamlastiracaksin hayati..

unutma..

bolusmek gerek....

 sevincler gibi.....

 acilarida....

o.balta..', 'Bebek yuzlu.. Yarim guluslu.. mahsun bakisli..  kartopum belki bir kardan adam yapacaklar seni.. hayat denen bahcede burnuna bir havuc takip...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kartopu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yumusak Karnim', 'yumusak-karnim-orhan-balta-mualm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gun icim aciyor, 

yuregim kaniyor..

Sanmayinki her zaman 

simdi ilk defa...

Kolumu kesseler direnirim

kafami kesseler anlarim

ama ayrilik..

yumusak karnim..

Dayanamiyorum..

O.BALTA', 'Bu gun icim aciyor,  yuregim kaniyor.. Sanmayinki her zaman  simdi ilk defa... Kolumu kesseler direnirim kafami kesseler anlarim ama ayrilik...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yumusak-karnim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdigim', 'sevdigim-orhan-balta-58ol5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kadinim, sevdigim, ortagim, 

dogurmadigin cocugumun anasi

dogurduklarinin babasi, 

Gozu sevda, yuregi yara, bahti kara 

 sevdigim.

Acilarda yasama  dair, sevinclerimiz gibi

gozyaslarida...., guluslerimiz gibi

Ya..... ayriliklarin adi ne? 

Hic yasanmamis gibi.

Bosuna dememis sair..

(olum ile ayriligi tartmislar elli gram fazla gelmis ayrilik) 

Yarin bebegimizden(kartopumuzdan)  ayriliyoruz, 

artik.

O ayni kente ayri bir evde yasayacak, 

oyle istedi, oyle olacak.

gulme..

Sen ben acimisiz farketmiyor..

o kazanacaklarin savasini veriyor..

yada oyle biliyor..

Elbet uzulecegiz gulum..

elbet aciyacak yuregimiz..

ona veremedigimiz sevgimize aglayacagiz belkide, 

Aglayacagiz mutlak..ama yenilmeyecegiz.

el ele, omuz omuza, yurek yurege olmanin, 

hazzini yasayacagiz.

buruk ve inancli.

O.Balta', 'Kadinim, sevdigim, ortagim,  dogurmadigin cocugumun anasi dogurduklarinin babasi,  Gozu sevda, yuregi yara, bahti kara   sevdigim. Acilarda ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sevdigim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Bir Umut Yeşeriyor', 'son-bir-umut-yeseriyor-sair-archi-tbft8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni derin dalgalara bırakıyorum

Kendimin nerde kaldığını hatırlamıyorum.

Bir ben kaldım

Bir ben sensiz ve sessiz...

Cümle kuramıyorum artık

Bütün kelimeler boğazımda.

Son da olsa bir umut

Yemşil duruyor içimde.

Bir gün; 

Dua ediyorum

Çıkacaksın yoluma

Geç kalma; 

Mahşere kadar bekleyemem.

Seni derin dalgalara bıraktım

Beni boşver...', 'Seni derin dalgalara bırakıyorum Kendimin nerde kaldığını hatırlamıyorum. Bir ben kaldım Bir ben sensiz ve sessiz... Cümle kuramıyorum artık...', ARRAY['Türk Edebiyatı','Şiir','Şair Archi']::text[], 8.5, '{"poet":"Şair Archi","poet_slug":"sair-archi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/son-bir-umut-yeseriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun', 'sen-yoksun-mustafa-i-lhan-guldemir-wqhy2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sustu şarkılar

Sustu kalemim

Sustu şiirler

Gelmiyor aşk şarkıları

Gelmiyor sevda türküleri

Cıvıldaşmıyor kuşlar

Koşuşmuyor çocuklar

Seyyar satıcılara ne oldu

Nerede bu insanlar

Tekmi kaldım bu dünyada.

Yoksa senden sonra

Benmi terk ettim dünyayı.

Sen yoksun, desene ölü bir şehirdeyim

Nasıl duyarım, nasıl yazarım 

Sen yoksun kim söyler şarkı, türkü

Sen yoksun neden cıvıldaş''sın kuşlar

Sen yoksun çocuklar nasıl olsun

Satıcılar kime, ne satsın

Sen olmayınca yaşam nasıl olsun

Sen yoksun anlasana ben öldüm

Anla sensiz olmuyor, her gün ölüyorum

Anla çırpındıkça can çekişiyorum.', 'Sustu şarkılar Sustu kalemim Sustu şiirler Gelmiyor aşk şarkıları Gelmiyor sevda türküleri Cıvıldaşmıyor kuşlar Koşuşmuyor çocuklar Seyyar s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan Güldemir']::text[], 8.5, '{"poet":"Mustafa İlhan Güldemir","poet_slug":"mustafa-i-lhan-guldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-yoksun-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi, Çiçek, v.s', 'sevgi-cicek-v-s-ali-osman-yilmaz-dcbtl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gizliden sevdim seni

Haberin yok çılgınca aşık oldum sana

Her gece koynuna girerim

Haberin bile olmaz

Doyasıya sevişirim seninle

Çılgınlar gibi.

Haberin olmaz.

Sana sarıldığımda, karanfil bahçesinde

Kokun bastırır tüm çiçeklerin kokusunu

Teninden yayılan o müthiş rayiha

Bir başka sarhoş eder beni

Derken sana sunarım kırmızı bir gül

Burnuna çektinmi kokusunu dolu dolu

Sendede başlar bir sarhoşluk

İşte tam o anda iki sarhoş

Bir beden, bir ten olurum seninle

Tüm ruhumun tohumlarını 

Dökerim sana

Çiçek çiçek döllenirsin bana

Doyumsuz sevişme biter ve

Seni öylesine bırakır giderim

Ne olur kızma bana

Seviştiğimizden haberin olmaz hiç

Bilemezsin benden gebe kaldığını

Doğurursun ayıplayan bakışlar arasında

Kır çiçeklerini, karanfilleri, gonca gülleri

Tüm gönüllerde açan sevgileri

Kıskanırlar seni, onlar derler herkese

Doğurduğun bu çiçekler, bu sevgi

Piç.', 'Gizliden sevdim seni Haberin yok çılgınca aşık oldum sana Her gece koynuna girerim Haberin bile olmaz Doyasıya sevişirim seninle Çılgınlar g...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevgi-cicek-v-s-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Gülü', 'kis-gulu-mustafa-i-lhan-guldemir-0gds0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çatık kaşlı yüzüne

Yağmurlar düşmüş kış gülü

Yakışmıyor sana bu bakışlar

Gülebilirsin bundan böyle 

Yokum artık senin dünyanda

Sunmayacağım artık kötülüklerimi

Surat asmayacağım

Sert bakmayacağım

Kem söylemeyeceğim

Yumuşat artık sert bakışlarını

Şen kahkahalarla çınlat Gökgubbeyi

Gülüşlerinle süsle dünyayı

Neşelen gününü gün et.

Yokum artık senin dünyanda

Yaşamıyorum senden sonra

Çatma kaşlarınıki

Yağmurlar sana değil, mezarıma düşsün

Çatma kaşlarını şen ol, neşeli ol

Gözünden yaş damlamayan 

Yaz gülü ol

Ben öldüm senden sonra

Sen şen ol, neşeli ol..', 'Çatık kaşlı yüzüne Yağmurlar düşmüş kış gülü Yakışmıyor sana bu bakışlar Gülebilirsin bundan böyle  Yokum artık senin dünyanda Sunmayacağım ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan Güldemir']::text[], 8.5, '{"poet":"Mustafa İlhan Güldemir","poet_slug":"mustafa-i-lhan-guldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kis-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmektir Hakkım', 'seni-sevmektir-hakkim-bekir-gedikoglu-wczfl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akşam oldu uykum yok

Kalbime gir derdim çok

Ruhumu dinlendiren

Şarkılardan eser yok

Yüreğime saplanan

Sanki balık zıpkını

O bakışlar yarabbim 

Gözümü kamaştırdı

Bir ceylana rastladım

Tadım tuzum yok bugün

Elimden kaçtı gitti

Sormayın perişanım

Kalbimin eşiğini

Yıkıp ta kaçarmısın? 

Ellerimi tutup ta 

Boşta bırkırmısın? 

Bu sevdaya tutuldum

Kurtulamam ben artık

Yıldızları da tutsam

Seni sevmektir hakkım', 'Akşam oldu uykum yok Kalbime gir derdim çok Ruhumu dinlendiren Şarkılardan eser yok Yüreğime saplanan Sanki balık zıpkını O bakışlar yarabbi...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-sevmektir-hakkim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Ey Sevgili', 'neredesin-ey-sevgili-mustafa-i-lhan-guldemir-mlswt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani neredesin ey sevgili

Kayboldun, yoksun yanımda

Ne oldu sevgine aşkına

Niye koştun başkasına

Hani bakarken dalıp gitmeler

Nerede gözlerimdeki denizler

Nerede tenindeki dudaklarım

Ne çabuk bıktın sevgimden

Hani bakınca gözlerime

Okyanusları görüyordun

Kaçırırdın gözlerini, gözlerimden

Korkardın okyanusta boğulmaktan

Hani yanımda hissettiğin kadınlığın

Kolumda kıvrılan dişiliğin

Nerede insanca sevilmeyi isteyişin

Bunları yanlız bende bulduğun

Hani neredesin ey sevgili

Yoksun yanımda, nerede sevgin 

Yoksa masmavi okyanustan kaçıp

Bulanık göletlerdemi boğuldun

Hani neredesin ey sevgili..', 'Hani neredesin ey sevgili Kayboldun, yoksun yanımda Ne oldu sevgine aşkına Niye koştun başkasına Hani bakarken dalıp gitmeler Nerede gözleri...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan Güldemir']::text[], 8.5, '{"poet":"Mustafa İlhan Güldemir","poet_slug":"mustafa-i-lhan-guldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/neredesin-ey-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abesle İştigal', 'abesle-i-stigal-oguzkan-bolukbasi-nmin0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Amacımız yaşamı tatlandırmak değil mi

Ben demiştim yaşam acıdır diye

Amacımız aşkı yaşatmak değil mi

Ben demiştim aşk bitkisel hayattır diye

O halde niye……….', 'Amacımız yaşamı tatlandırmak değil mi Ben demiştim yaşam acıdır diye Amacımız aşkı yaşatmak değil mi Ben demiştim aşk bitkisel hayattır diye...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/abesle-istigal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önemsiz Aşk', 'onemsiz-ask-mustafa-i-lhan-guldemir-273lt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Koyu gözleri sert bakışlı 

Sevdalıyı kendine esir eden

Omuzu saçından şallı bayan.

Söyle aşkı kaça sattın? 

Kaç görücüye çıktı, uzun saçların

Kaç delikanlıya aşkını değiştin söyle

Kaç kez gerçek aşık oldun

Zaten her şey para olmuş

Sen aşkı satsan ne olur

Sevgilim sen olmazsan 

Aşkımın ne önemi var...', 'Koyu gözleri sert bakışlı  Sevdalıyı kendine esir eden Omuzu saçından şallı bayan. Söyle aşkı kaça sattın?  Kaç görücüye çıktı, uzun saçları...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan Güldemir']::text[], 8.5, '{"poet":"Mustafa İlhan Güldemir","poet_slug":"mustafa-i-lhan-guldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/onemsiz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmayın ki', 'sanmayin-ki-oguzkan-bolukbasi-nrkj0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'biz şairi de okuruz

yalnızca şiiri değil

yılanın ağzından damlayan balı da

gül üzerindeki çiy damlasını da biliriz

ruhu aydınlatanı görünce seviniriz

ve her şey çelişkisiyle vardır

güzeli arar buluruz.....', 'biz şairi de okuruz yalnızca şiiri değil yılanın ağzından damlayan balı da gül üzerindeki çiy damlasını da biliriz ruhu aydınlatanı görünce ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sanmayin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-tevfik-mengulluoglu-2ha21', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalkıp yürüyorum arkama baktığımda gözlerinden akan o durma kal birşeyler daha var sözcükleri okuyabiliyorum.Benimde Aslında Direnen bir yanım ayaklarıma dolanmış durumda ama herşeye rağmen gidiyorum Gidiyorum çünkü bir süre sonra bir başka bahaneyle geri döneceğimi biliyorum, ve yine herzamanki gibi masum çocukluğumuzu bu bencil davranışlara alet edip çocukluktu bizimkisi diyeceğiz.Ve ne zaman bir çocukluk yapsak bizdik diyoruz biliyormusun aslında hiç büyümemişiz belkide istememişizdir büyümeyi! Anne şefkati baba himayesi duygulara sığınarak geçiyor hayatımız, Hatırlıyorum çocukluğumda ne zaman annemden birşey istesem evden çıkar giderdim sonra annem yetişir beni sarmalardı.Muhtemelen hep kabuğuna çekişlerek alırdın isteklerini, Ne kadar kocaman geliyor bize bu yabancı bedenler değilmi :)', 'Kalkıp yürüyorum arkama baktığımda gözlerinden akan o durma kal birşeyler daha var sözcükleri okuyabiliyorum.Benimde Aslında Direnen bir yan...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/celiski-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvardaki Resimde', 'duvardaki-resimde-bekir-mutlu-gokcesu-d1xr3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yol var

İki yanı sık ağaçlar

Yağmur kokusu havada

Sanki yağmur arkası da kar

Ya sabah oluyor

Ya da akşam

Belli belirsiz anlaşılmıyor

Işıksız bir gün duvardaki resimde

Ben akşam niyetine

Ve illaki sana kavuşacağım diye

Girmiş bulundum tablonun içine

Yol boyu ilerledim gözlerimle

Yol iyice daralıyor ileride

Epeyce yürüdüm, üşüdüm de

Fakat dönmek olmaz artık

Böyle bir günde

Mutlaka beni bekliyor olmalısın

Önüme çıkacak ilk kulübede', 'Bir yol var İki yanı sık ağaçlar Yağmur kokusu havada Sanki yağmur arkası da kar Ya sabah oluyor Ya da akşam Belli belirsiz anlaşılmıyor Işı...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/duvardaki-resimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer...', 'eger-mumtaz-begen-25aef', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yediğin hep kaymak olsun bal olsun, 

Günün gün, hâlin en güzel hâl olsun, 

Gözlerim görmesin, dilim lâl olsun, 

Adını bir daha anarsam eğer…

Kulundum kölendim yaranamadım, 

Uzaklaştın benden hep adım adım, 

Kırılsın ayağım kopsun kanadım, 

Dalına bir daha konarsam eğer…

Ölümsüz değilim gelip gidenim, 

İstersen benim de sen ol nedenim, 

Canım çıksın küle dönsün bedenim, 

Uğruna bir daha yanarsam eğer…

Hak edersem bunu divan kurulsun, 

Kurulsun da bana da bir sorulsun, 

Katlime râzıyım, boynum vurulsun, 

Sözüne bir daha kanarsam eğer…', 'Yediğin hep kaymak olsun bal olsun,  Günün gün, hâlin en güzel hâl olsun,  Gözlerim görmesin, dilim lâl olsun,  Adını bir daha anarsam eğer…...', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Beğen']::text[], 8.5, '{"poet":"Mümtaz Beğen","poet_slug":"mumtaz-begen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eger-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başımız Göğe Erecek mi', 'basimiz-goge-erecek-mi-i-brahim-bayraktar-uh5yo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vatandaş seçimini yapmış arkadaş, 

Yeni bir seçimin yararı nedir? 

Şapkayı koyup da düşündünüz mü? 

Vatana millete yararı nedir? 

Haksızlığı ortadan kaldıracak mı? 

Mazlumun yüzünü güldürecek mi? 

Başımızı göğe erdirecek mi? 

Konuya komşuya yararı nedir? 

İstikrarı sağlayıp, ufukları açmışken, 

Unumuzu elemiş, kepekleri uçmuşken, 

Paçaları sıvayıp, ummanı geçmişken, 

Derede boğulmanın yararı nedir? 

Iskartaya ayrılan, kalburüstü gezenlere, 

Yoksulu, fakiri ezim ezim ezenlere, 

Canımızı yakan, gücümüzü üzenlere, 

Yeniden paye vermenin yararı nedir? 

01.10.2003', 'Vatandaş seçimini yapmış arkadaş,  Yeni bir seçimin yararı nedir?  Şapkayı koyup da düşündünüz mü?  Vatana millete yararı nedir?  Haksızlığı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/basimiz-goge-erecek-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıp Giden Zamana Sitem', 'akip-giden-zamana-sitem-mehmet-akar-xwphk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne telefon çalar artık, ne de kapı çalınır.

Göçen kuşlar gibi; gidenler, hatıralara yazılır.

Ömrün son nöbetleri tutulurken, özlenen yıllar arasında, 

gözler ağlar ağlar da, gene de zamana bakakalır.

Zaman akıp gitmiştir; sudan bile daha hızlı...

Önce o narin, o sevimli çocukluk çağları, sonra, , , 

o deli, o mert, çılgın delikanlılık anları ve ardı.

Anne, baba göçer gider zamanla, yaşlar arasında

çoluk çocuk ta vefasızlaşır sonra; hani ele karışınca.

Bir eş kalır, onu da Tanrı alır, akıp giden zamanda.

Ölümdür bu Allah''ın emri:Ağlamak ne fayda.

Belli zaman sonra unutur seni herkes, vefasızlaşır dostlar da, 

tek başına geldiğin dünyada; kalırsın yine tek başına.

Arayan soran olmaz; ne telefon çalar artık, ne de kapı çalınır, 

göçen kuşlar gibi, gidenler, kalanlar, .. hatıralarda tozlanır

Ömrün son nöbetleri tüketilirken; ağlanan hatıra yıllardan sonra, 

geçen yıllarla beraber gözler ağlar ağlar da; yaşlarla kapanır.', 'Ne telefon çalar artık, ne de kapı çalınır. Göçen kuşlar gibi; gidenler, hatıralara yazılır. Ömrün son nöbetleri tutulurken, özlenen yıllar ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akar']::text[], 8.5, '{"poet":"Mehmet Akar","poet_slug":"mehmet-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/akip-giden-zamana-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Yıldızı', 'coban-yildizi-i-brahim-bayraktar-2emv2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Engelli patikaların, parlak yıldızı, 

Kır küheylânın çifte sallar arada, 

Dönüşün muhteşem, gidişin kırmızı, 

İsmin dilden düşmez hep ilk sırada.

Değişmez lehçesiyle eski kılavuz, 

Hem maharetli, hem de çok yavuz, 

Dili baldan tatlı, gönlü bir havuz, 

Çağlar enginlere, akar Murat’a.

Kelepçe vurdurup azgın sulara, 

Kulağından tutup aldın yulara, 

Adını yazdırıp, yüce dağlara, 

Övünerek bakar deli Fırat’a.

Kiminin babasısın, kiminin dayısı, 

Elli yıllık geçmişin kırık aynası, 

İndirip tahtından çilli seyisi, 

Yoldan geçeni bindirir kırata.

30.09.2003', 'Engelli patikaların, parlak yıldızı,  Kır küheylânın çifte sallar arada,  Dönüşün muhteşem, gidişin kırmızı,  İsmin dilden düşmez hep ilk sı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/coban-yildizi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım!', 'askim-tolga-ayla-jzrnl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazı insanların hayalleri vardır; 

Dünyaları dilerler yıldızlardan.

Bazı insanların duaları vardır; 

Sağlık ve huzur isterler Tanrılarından.

Bazıları da vardır ne yıldızlardan...

...ne de Tanrılarında bir şey ister; 

Onlar küçük şeylerde yakalarlar:

...mutluluğu ve huzuru...

Büyük dünyalarını mutlu etmesini bilirler; 

Anlarlar ne olursa olsun ayrılık üzerine yaşanır bu hayat, 

Bulurlar geç kalınmayacak anları.

Sende bana bir kere sarılsana; 

Küçük dünyamı uçsuz bucaksız denizlere, 

Sonu olmayan cihanlara çevirsene.', 'Bazı insanların hayalleri vardır;  Dünyaları dilerler yıldızlardan. Bazı insanların duaları vardır;  Sağlık ve huzur isterler Tanrılarından....', ARRAY['Türk Edebiyatı','Şiir','Tolga Ayla']::text[], 8.5, '{"poet":"Tolga Ayla","poet_slug":"tolga-ayla","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/askim-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yırt', 'yirt-nalan-kazazoglu-w710v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doldur dünyaları göğsüne

İnsanlara ver avuç avuç

Yürekli duy kendini

Sonuna kadar kavgaya

Bir hamlede süzül yıldızlara

Sevda dörtnala

Yaman dengede bekleyen

Alnına kıvrımlar bırakan zamanı

Yırtılması gibi taş düşünce suyun

Koca yüreğinle yırt, parçala...', 'Doldur dünyaları göğsüne İnsanlara ver avuç avuç Yürekli duy kendini Sonuna kadar kavgaya Bir hamlede süzül yıldızlara Sevda dörtnala Yaman ...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yirt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yanarım Güneş Doğunca', 'sana-yanarim-gunes-dogunca-derin-oger-xiapk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökyüzümsün demiştim ya

Gündüzü firuze

Bin yıldız yürek bağlamışım

Sen diye gecenin kadifemsi lacivertine

Gökyüzümsün demiştim ya sana

Olmayan gözlerine baka baka

Sevgim savurmuştu beni benden sana senden bana

Hani şu başı sonu olmayan boşluğuna

Gökyüzümsün ağlatma desem gülüşlerimi

Çıplaktır ayaklarım kavrulur toprağında

Bulutum ol sen yine yakın dur rüzgarlarıma 

Sessiz bir yağmur gibi yağ rüyalarıma ağla

Yağ ağla ışıltılı berrak ve yalnız bana

Sana yanayım güneş doğunca

Sana üşüyeyim gece olunca

Gökyüzümsün benim demiştim ya

Gökyüzüm ol her halinle

Gökyüzümki bir siyahi 

Bir firuze...................', 'Gökyüzümsün demiştim ya Gündüzü firuze Bin yıldız yürek bağlamışım Sen diye gecenin kadifemsi lacivertine Gökyüzümsün demiştim ya sana Olmay...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sana-yanarim-gunes-dogunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş', 'kus-selami-selok-qwanq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kuş

Pırpır eder, 

Bir kuş var yüreğimde.

Salmalımıyım onu gökyüzüne.

Bağırmalı, 

Kuşlara özgürlük diye.

Çabucak dönmeliyim sırtımı, 

Etmeden tek kelime.

Neden, niçin, niye? 

Söylemeyin kimselere.

Bir kuş o, narindir, 

Darılır sonra sözlerime.

Selami Selok', 'Kuş Pırpır eder,  Bir kuş var yüreğimde. Salmalımıyım onu gökyüzüne. Bağırmalı,  Kuşlara özgürlük diye. Çabucak dönmeliyim sırtımı,  Etmeden...', ARRAY['Türk Edebiyatı','Şiir','Selami Selok']::text[], 8.5, '{"poet":"Selami Selok","poet_slug":"selami-selok","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kus-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gece', 'o-gece-hakki-hakan-kaya-c80f6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daldım en gizemli hislere

Seni gördüğüm o gece

Kalbimin hırsızı oldu sessizce

Rüyama girdiğin o gece

Ateşböcekleri şarkılar söyledi

Bülbüller sustu güller dinledi

Gönlümün kodesi inledi

Sesini duyduğum o gece

Yanında güller sümbüller soldu

Gönlümün mekanı seninle doldu

Zaman dondu saatler durdu

Yanıma geldiğin o gece

Açıldı kalbim sonsuz bir hana

Kilitlerin anahtarını verdim sana

Ben bende değildim dönüpte bana

Seviyorum dediğin o gece', 'Daldım en gizemli hislere Seni gördüğüm o gece Kalbimin hırsızı oldu sessizce Rüyama girdiğin o gece Ateşböcekleri şarkılar söyledi Bülbülle...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-gece-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bir Yar Olsa', 'bana-bir-yar-olsa-pir-sultan-abdal-zbhvz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana bir yar olsa gönül verdiğim

Çıksa bari yüreğimden bu acı

Yaresin bekleyip ahdın güttüğüm

Bulunsa bir sınık yare sarıcı

Yarinden ayrılan hiç gülmez imiş

Akar çeşmi yaşı silinmez imiş

Kişinin dediği olunmaz imiş

Salar imiş her yanına salıcı

Aşk elinden ciğerciğim delindi

Gönlün kal dediği yerde kalındı

Her nerede olsa bize bulundu

Gıybet edip yüzümüze gülücü

Nice bezirganlar kond bu hana

Dünya baki değil sultana hana

Bir kalleş yar ile girme meydana

Erin ere doğru gerek kılıcı

Pir Sultan Abdal''ım çoştum giderim

Bir kuru kavgayı sürüp niderim

Yiyelim içelim sohbet edelim

Gelir bir gün emanetin alıcı', 'Bana bir yar olsa gönül verdiğim Çıksa bari yüreğimden bu acı Yaresin bekleyip ahdın güttüğüm Bulunsa bir sınık yare sarıcı Yarinden ayrılan...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bana-bir-yar-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Medet Senden Olur', 'bana-medet-senden-olur-pir-sultan-abdal-8fdn6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana medet senden olur efendim 

Aşılmaz dağların dost ardında kaldım 

Eller dosta doğru çeker göçünü 

Elsiz viranede çöllerde kaldım 

Sana derim sana ey kaşı kare 

Artıyor eksilmez dost sinemde yare 

Bir aşinam yok ki halımı sora 

Yalanlı dolanlı dillerde kaldım 

Sabahtan sabahtan semah tutarım 

Dosta kadar gider oy benim katarım 

Baykuş gibi viranede öterim 

Gel gör ne perişan hallerde kaldım 

Pir Sultan Abdalım ben de gülmedim 

Aradım derdime dost derman bulmadım 

Yol nereden gelir gider bilmedim 

Kesildi kervanım bellerde kaldım', 'Bana medet senden olur efendim  Aşılmaz dağların dost ardında kaldım  Eller dosta doğru çeker göçünü  Elsiz viranede çöllerde kaldım  Sana d...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bana-medet-senden-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Eşsiz Şöleni', 'gecenin-essiz-soleni-sedef-unal-522bw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıldızlar kırıtarak geceyi tahrik ederken

Yakamozlar denizle sarmaş dolaş dans ederken

Özlemin bir çığ gibi büyüyüp beni esir aldı

Adin dudağımın son gülüşünde takıldı kaldı

İpek böceği gibi sabırla beklediğini kutsamak için

Uzun zamandır düşünüp de cesaret edemediğim

Delice bir karar verdim

Tüm tabuları yıkıp sana gitmek

Kayıp ettiğim cesaretimi buldum biraz önce

Nede çok aramıştım oysa, ayağımın ucundaymış

En sevdiğin beyaz giysimi giyeceğim sana gelirken

Yanıma fazla bir şey almadan

Bugünler için sakladığım neşemi

Hiç kullanmadığım umutlarımı getireceğim

Peşime takmayacağım ne bilinmezliği, nede geçmiş anılarımı

Sadakatim sinirsiz güvenim şüphesiz olacak

Doğanın desteğini ardım sıra peşime takip

Zamanın hızına yenik düşmeden

Tan yeri ağarmadan

Kollarında yakıcı bir vuslat kokusu yayılacak

Avuç içinde kalp atışımı hissedeceksin

Sevdiğim gözlerinde yeniden doğacağım

1 Ekim 2003', 'Yıldızlar kırıtarak geceyi tahrik ederken Yakamozlar denizle sarmaş dolaş dans ederken Özlemin bir çığ gibi büyüyüp beni esir aldı Adin duda...', ARRAY['Türk Edebiyatı','Şiir','Sedef Ünal']::text[], 8.5, '{"poet":"Sedef Ünal","poet_slug":"sedef-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gecenin-essiz-soleni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter ki Ufacık Öpmeden Gitme', 'yeter-ki-ufacik-opmeden-gitme-murat-demir-6ny1z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karışmam işine ne yaparsan yap 

Dayansın yüreğim etsem de feryat 

Bir paçavra gibi istersen tut at 

Yeter ki gözüme bakmadan gitme 

Yolların olurum seven ben isem 

Darılmam üstümde gezen sen isen 

Laf etmem tırpanla ot diye biçsen 

Yeter ki kapımda durmadan gitme 

Bir tatlı hatıra senden hediye 

Benim olmazsan da bakma el diye 

Gözyaşım sel olsa demem gel diye 

Yeter ki yüzüme gülmeden gitme 

Bağıma bahçeme hasret eksem de 

fark etmez bitişim olsa da sem de 

Razıyım her şeye azap çeksem de 

Yeter ki elimi tutmadan gitme 

Sen olmazsan bile anılar yeter 

Kimseye aldırmam desinler biter 

Unutamam seni olsam bin beter 

Yeter ki ufacık öpmeden gitme', 'Karışmam işine ne yaparsan yap  Dayansın yüreğim etsem de feryat  Bir paçavra gibi istersen tut at  Yeter ki gözüme bakmadan gitme  Yolların...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeter-ki-ufacik-opmeden-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Be Hey Acayip Adem', 'be-hey-acayip-adem-pir-sultan-abdal-pin7c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Be hey acayip adem

Öldüğünü bilemezsin

Korlar bir karanlık dama

Kapı baca bulamazsın

Yağmur yağar yeller eser

Mezarı başına yıkar

Seksen bin canavar sıkar

Hiç birine vuramazsın

Gel bu öğüdü al benden

Yarın fırsat gider elden

Hak saklasın cehennemden

Karanlıktır çıkamazsın

Yer pamuk olur atılır

Cümle deryalar katılır

Dilin damağın tutulur

Doğru cevap veremezsin

Pir Sultan''ım der ki deli

Elden koymaz doğru yolu

Ne yanarsın dünya malı

Birin alıp gidemezsin', 'Be hey acayip adem Öldüğünü bilemezsin Korlar bir karanlık dama Kapı baca bulamazsın Yağmur yağar yeller eser Mezarı başına yıkar Seksen bin...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/be-hey-acayip-adem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Be Sevdiğim', 'be-sevdigim-pir-sultan-abdal-bt7tp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Be sevdiğim seni benden ayıran

Din iman bulmaya diyelim Allah

Şu sinemi aşk oduna dağlayan

Bekası olmayan diyelim Allah

Bir münafık sebep oldu bu işe

Umarım başına hem taşlar düşe

Kör yılanlar ura cesedi şişe

Eriye döküle diyelim Allah

O da benim gibi yana kuruya

Kısmeti tükene başı çürüye

Seyit Vakkas bir ok ura devire

Cennet''e girmeye diyelim Allah

Allah anı bin bir belaya ata

Kısmeti tükene vadesi yete

Yetmiş seksen sene döşekte yata

Yata da kalkmaya diyelim Allah

Pir Sultan Abdal''ım almadım hızaz

O kelp rakip bize eyledi garaz

Başka dertten gayrı bin kantar maraz

Gire de çıkmaya diyelim Allah', 'Be sevdiğim seni benden ayıran Din iman bulmaya diyelim Allah Şu sinemi aşk oduna dağlayan Bekası olmayan diyelim Allah Bir münafık sebep ol...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/be-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bilemem', 'ben-bilemem-pir-sultan-abdal-4gybn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sar''öküzü benden sual sorarlar

Ben bilemem bilenlere sorayım

Şu dünyayı uçtan uca ararlar

Ben bilemem bilenlere sorayım

Dünyayı üstüne kurdu hu deyü

Öküzün başının altı su deyü

Şu dünyanın damızlığı ne deyü

Ben bilemem bilenlere sorayım

Hindistan''a indi öküzün dili

Kabe''yi sırtında getürür beli

Evveli Muhammet ahiri Ali

Ben bilemem bilenlere sorayım

Kuyruğunu gördüm Yemen ilinde

Nurdan taç başında kemer belinde

Muhammet kalbinde Ali dilinde

Ben bilemem bilenlere sorayım

Mağripten maşrıka dünyanın ucu

Sarraf olan bilir altını tucu

Yalan imiş şu dünyanın sonucu

Ben bilemem bilenlere sorayım

Gün doğunca boynuzuna nur düşer

Bir yandan doğar da bir yandan aşar

Çiftçisi kim imiş çifte kim koşar

Ben bilemem bilenlere sorayım

Pir Sultan Abdal''ım yazmış göndermiş

Yedi yerden suyun vermiş kandırmış

Yönünü de Hak''tan yana döndermiş

Ben bilemem bilenlere sorayım', 'Sar''öküzü benden sual sorarlar Ben bilemem bilenlere sorayım Şu dünyayı uçtan uca ararlar Ben bilemem bilenlere sorayım Dünyayı üstüne kurdu...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-bilemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Selam Söyle O Güzel Şaha', 'benden-selam-soyle-o-guzel-saha-pir-sultan-abdal-86ngs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benden selam söyle o güzel şaha

Kurduğu yollara gitmiyor talip

Herkes kendisine bir yol sürüyor

Mürşit buyruğunu tutmuyor talip

İçeri girilen ikrar hak diyor

Dışarı çıkılan ikrar yok diyor

Senden gayrı bana mürşit çok diyor

Verdiği ikrardan dönüyor talip

Yolum uğrar ise söylerim sözün

Varsın doğru yola gitmesin talip

Sen mürşitlik hakkın ifa eylersen

Günahı boynuna tutmasın talip

Pir Sultan Abdal''ım ben bir biçare

Boynunu de eğip durmuyor dara

Gönüle de düştü bir sınık yara

İnliye inliye geliyor talip', 'Benden selam söyle o güzel şaha Kurduğu yollara gitmiyor talip Herkes kendisine bir yol sürüyor Mürşit buyruğunu tutmuyor talip İçeri girile...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benden-selam-soyle-o-guzel-saha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Afet-i Bomba', 'afet-i-bomba-hakki-hakan-kaya-z66fl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bakar zinhar akıllara zarar, 

Elimi nereye koyacağımı bilemedim.

Kokusu, meşrufesi alemi sarar, 

Döndü başım, tutuldu dilim.

Ah bir sarılsam ince beline, 

Hissetse bedenini bedenim, 

Hayali ile yandım kavruldum, 

Çekildi içim, kurudu iliğim.

Öyle bir güzel sarstı ki gönlümü, 

Ben böyle bir zelzele görmedim, 

Vücud-u Endam cümlesiyle titredi, 

Ne yayım kaldı ne de milim.', 'Bir bakar zinhar akıllara zarar,  Elimi nereye koyacağımı bilemedim. Kokusu, meşrufesi alemi sarar,  Döndü başım, tutuldu dilim. Ah bir sarı...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/afet-i-bomba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çocuk Da Anasından Doğunca', 'bir-cocuk-da-anasindan-dogunca-pir-sultan-abdal-s5gpe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir çocuk da anasından doğunca

Bedenini pişirmeye tuz ister

Üryan büryan ortalıkta kalınca

Setirini örtünmeye bez ister

Konla sudan gelir anın gıdası

Nasibini veren Barı Huda''sı

Beşiklere beler onun anası

Akşam sabah emzirmeye yüz ister

Bir yaşında ürüm ürüm ürünür

İkisinde sürüm sürüm sürünür

Üç yaşında adım adım yürünür

Dört yaşında söylemeye söz ister

Beş yaşında dili civan sevişir

Altısında uşağınan döğüşür

Yedisinde dişlerini değişir

Sekizinde her gediğin düz ister

Dokuzunda olur bir tosun maya

Onunda da benzer kaşları yaya

Onbirinde başı girer sevdaya

Onbeşinde ala gözlü kız ister

Yirmisinde akıl baştan savrulur

Otuzunda vursa dağa devrilir

Kırk yaşında akıl başa çevrilir

Ellisinde avın olmış baz ister

Altmışında iner bir merdivenden

Yetmişinde binse düşer duvardan

Sekseninde su getirmez pınardan

Doksanında döşeğini düz ister

Pir Sultan Abdal bu söz hepimize

Tonus girinceye belki de yaza

Yüz yaşında ölümünü gözede

Zemheriyi çıkarmaya yaz ister', 'Bir çocuk da anasından doğunca Bedenini pişirmeye tuz ister Üryan büryan ortalıkta kalınca Setirini örtünmeye bez ister Konla sudan gelir an...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-cocuk-da-anasindan-dogunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasam 4 Mevsim', 'yasam-4-mevsim-ceylan-yarar-wjc9j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yasam dört mevsimdir derler

İlkbahara benzer çocukluk

Cıvıl cıvıl, kıpır kıpır

Yeni patlayan çiçekler gibi

Tazedir bedenleri

Olmamış meyveler gibi

Çığlık çığlığa çocuklar

Baharı müjdeleyen kuşlar gibi

Ardından yaz gelir

Ne sevdalar ne aşklar yaşanır

Alev alev yakar ateşi

İlk tecrübeler, heyecanlar

Kız, erkek gençlik günleri

Yaşamayan varmı, bu güzellikleri? 

Sırada dır sonbahar

Yolun yarısı der ŞAİR

Dökülür sarı, kuru yapraklar

Biten aşklar, sevdalalar gibi

Hüzündedir yürekler

Ömrün hazan mevsimi

Yaşarız hep eylül hüznünü

Ahh lar vahh lar cekeriz

Geri kalan üç mevsime

Dökülen yaprakları gördükce

Yeni fidanlar dikeriz

Kuruyacağını bile bile

Özetidir sanki hayatın KIŞ

Son çabalayışları yaşamın

Deli esen ruzgarlar

Yapamadıklarımızın isyanı

Ani çıkar fırtınalar

Yaşayamadıklarımızın feryadı

Kar beyaz olsada, ak saçlar gibi

Buz gibidir, soğuktur

Yitirdiğimiz sevgiler misali

Arada çıksada güneş bulutludur

Heran gelecek ölüm gibi

Hava yine çok soğuktur

Tek tek geçer mevsimler

Yaşamlar sona erer

Bu kısacık dört mevsimi

Yaşamalıyız hiç bitmeyecek gibi....', 'Yasam dört mevsimdir derler İlkbahara benzer çocukluk Cıvıl cıvıl, kıpır kıpır Yeni patlayan çiçekler gibi Tazedir bedenleri Olmamış meyvele...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yasam-4-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece Muhammet', 'bir-gece-muhammet-pir-sultan-abdal-n6udt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gece Muhammet evde yatarken

Üç melek geldi de nida getirdi

Selman''ın şeklinde bir oğlan girdi

Ne güzel izzetle sala getirdi

Muhammet oğlana yerini verdi

Geçti oğlan seccadeye oturdu

Cebrail oğlandan nişan istedi

Zühre yıldızını alna getirdi

Bu oğlanın Ali olduğun bildiler

Aman mürvet deyü dara durdular

Özlerinden hayli sitem sordular

Cebrail Cennet''ten elma getirdi

Getirip elmayı terceman verdi

Şah eline alıp dört pare kıldı

Bir paresin Şah''ım nuş edip kandı

Üçünü melekler Hakk''a götürdü

Bak Bari Taala hoş nazar kıldı

Yed''iklim çar köşe Ali''ye verdi

Biri Düldül biri Zülfikar oldu

Fatma da Kanber''i ana götürdü

Pir Sultan''ım eydür gitti gelenler

Arayrp özünde gevher bulanlar

Muhammet Ali''yle arşa duranlar

Cümle melekleri ceme götürdü', 'Bir gece Muhammet evde yatarken Üç melek geldi de nida getirdi Selman''ın şeklinde bir oğlan girdi Ne güzel izzetle sala getirdi Muhammet oğl...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-gece-muhammet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-ceylan-yarar-1lkp0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İhanete uğradın mı hiç

Şalteri indirilmiş motor gibi

Yaşamın durdu mu hiç

Nefes alamadığını hissetmek

İçtiğin sudan bile tad almadan yaşadın mı hiç...

Yandı mı ciğerin koparttılar mı yüreğini

Bakıpta gördüğün tüm güzellikleri 

Göremez oldun mu hiç...

Bunca yıl sevgine verdiğin emeği

Harcadılar mı bozuk para gibi

Sofi''nin seçimi gibi zorlandın mı hiç...

Savaşmak ya da bırakmak

Gitmek ya da kalmak gibi

Nefret ettin mi tüm kadınlardan

Annen, kızın kendinde kadın olduğun halde

İhanete uğradın mı hiç...

Öldürdüler mi seni

Yaşanacak çok şey varken henüz...', 'İhanete uğradın mı hiç Şalteri indirilmiş motor gibi Yaşamın durdu mu hiç Nefes alamadığını hissetmek İçtiğin sudan bile tad almadan yaşadın...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ihanet-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kişi Özünde İkilik Olsa', 'bir-kisi-ozunde-i-kilik-olsa-pir-sultan-abdal-02gvj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kişi özünde ikilik olsa

Hakk''ın didarını görmez billahi

Hor bakarsa evliyanın yoluna

Eli bir gerçeğe ermez billahi

Cihanı seyahat edip gezerse

Doksan bin kelamı okur yazarsa

Bir mümin yezide kuşak çözerse

Derdine dermanı bulmaz billahi

Eli ile komadığın alırsa

Yalan söyler Hakk''a asi olursa

Tövbe etmez günah gümrah olursa

Cehennem oduna yanar billahi

Bir mümin yezide kızını verse

Anası babası ilayık görse

Yüz bin kere başı secdeye varsa

Hak da günahından geçmez billahi

Bir mümin yezidin yüzüne baksa

Gayet gökçek olsa şol meyli aksa

Ol müslim bacıdan zürriyet doğsa

Arsız meydanında kalır billahi

Pir Sultan''ım der ki Hakk''ın emrini

Koyuverse bir kişi avradını

Mümin olan bilir bunun dadını

Yedi başlı hınzır olur billahi', 'Bir kişi özünde ikilik olsa Hakk''ın didarını görmez billahi Hor bakarsa evliyanın yoluna Eli bir gerçeğe ermez billahi Cihanı seyahat edip g...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-kisi-ozunde-ikilik-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygularımın Katili', 'duygularimin-katili-ceylan-yarar-t6f8l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soruyorum sana aşkım...

Sen beni mi kendini mi aldadtın... 

Cevabın ne birtanem? 

Bulamıyorsun değil mi? 

Düşün bir süre bulacaksın

Kaybettiklerini fark edince

Sende ciğerinden yanacaksın

Kaybettiklerin mi sevgilim? 

Önce kendine saygını, 

Tutkulu bir aşığı, 

Bu asrın sevdasını

Sıcak bir yuvadaki

Sevinç çığlıkları atanlarını

Sevgilileri birbirine bağlayan güveni

Ararsın belki dönüşü aşkım...

Dönersin belkide hatalarından

Tekrar denersiniz belkide

Bulursun kaybettiklerini bir bir

Bulamayacağın nemi birtanem

Apansız yüreğinden vurduğun

Gözünü bile kırpmadan öldürdüğün

Gözlerime bak şimdi ölüler değil mi? 

Duygularım birtanem

Yüreğimden gözlerime akan

Duygularımın katilisin sen...', 'Soruyorum sana aşkım... Sen beni mi kendini mi aldadtın...  Cevabın ne birtanem?  Bulamıyorsun değil mi?  Düşün bir süre bulacaksın Kaybetti...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/duygularimin-katili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Seferim Vardır', 'bir-seferim-vardir-pir-sultan-abdal-mlhaz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir seferim vardır Urum üstüne

Yüce dağ başında eri gözlerim

Al elimi kaldır kırklar yediler

Bir himmeti keskin piri gözlerim

Bismillah dedim de girdim helale

Gözüm açıp baktım bir hub cemale

Sıdk ile çağırdım ceddim celale

Eriş Hızır Nebi carı gözlerim

Kuduretten yanar şem''a ışığı

Mevla''m Hak diyenin üğrür beşiği

Din serveri Muhammed''in eşiği

Halil''e yapılan şarı gözlerim

Keskin Zülfikar''la Ali gazada

Umarım inayet ede bize de

Bağdat''ta Mansur''un canı cezada

Kemendim boynumda darı gözlerim

Pir Sultan Abdal''ım sır Ali sırrı

Sırat''ı geçenin Cennet''tir yeri

Veyselkara Hint''ten Yemen''den beri

Muhammet Ali''de nuru gözlerim', 'Bir seferim vardır Urum üstüne Yüce dağ başında eri gözlerim Al elimi kaldır kırklar yediler Bir himmeti keskin piri gözlerim Bismillah dedi...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-seferim-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-ceylan-yarar-4b22q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neredesin ANNEM

Neden bukadar erken gittin? 

Hiç düşünmedinmi sana ihtiyacım olduğunu...

Geri dön ne olur ANNEM! 

İhtiyacım var sevgine

Dertlerimi dökmeye, omuzunda ağlamaya

Saçımı okşa ANNEM! 

Geçer bunlar kızım de

Sil gözümdeki yaşları

Zaman en büyük ilaçtır de...

Bana güç ver ANNEM! 

Biliyorum geri gelemessin

Dönüşü olmayan yerdesin

Neolur duy beni ANNEM! 

Ben uykudayken

Geliver sessizce ruyalarıma

Sarıl bana ANNEM! 

İnan buda yeter ayakta durmama

Benim canım ANNEM! ...', 'Neredesin ANNEM Neden bukadar erken gittin?  Hiç düşünmedinmi sana ihtiyacım olduğunu... Geri dön ne olur ANNEM!  İhtiyacım var sevgine Dert...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/annem-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmeyen Bilinmezlere Götürecegim seni...', 'bilinmeyen-bilinmezlere-goturecegim-seni-muammer-celik-i8erj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanrı dağlarının ardından 

doğacak güneş bir gün; 

olabildiğince hür, 

alabildiğince özgür… 

Işıtacak hem gökleri 

hem tüm dünyayı

sonra; 

batının 

en kuzeyinden 

yapayalnız 

bir yıldız parlayacak 

mehtabı kıskandıracak 

gece karanlığında

gül yüzüne doğacak 

seni senden alıp 

bilmediğin bilinmezlere götürecek... 

İşte orada sevecek seni 

işte orada sevişecek seninle 

Bırak zaman ve mekanı, ötekilere kalsın… 

26.05.2003

BirDeli', 'Tanrı dağlarının ardından  doğacak güneş bir gün;  olabildiğince hür,  alabildiğince özgür…  Işıtacak hem gökleri  hem tüm dünyayı sonra;  b...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilinmeyen-bilinmezlere-goturecegim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oku Oğlum', 'oku-oglum-ceylan-yarar-7vtr7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha onüçündeydi evlendirilmişti

Çocuk olmadan anneydi şimdi

Yıllar akıp geçiyor

Hızlı adımlarla ayak uyduruyordu

Biri hasta dört çocuğu olmuştu

Hayatındaki en güzel şeyse

Üçüncü oğlunun okuluydu

Başarılıydı okuyacak büyük adam olacaktı

Evlere temizliğe gidiyordu

kazancıyla mutluydu

Öyle büyük yüreği vardıki

Fabrikadaki işinden atılan eşi için, 

Patronun karşısına dikilmiş, 

İŞİ geri almıştı

Oğluna kurs parası gerekiyordu

Çırpınıyor yedi gün çalışıyordu

Tanrı yüreğine göre verdi

İş verenleri bankada hesap açtı ona

Çok mutluydu evine giderken

İçi içine sığmıyordu

Müjde verecekti oğluna

Her akşam geçitten geçerdi

Bu kez tren yolundan geçmeliydi

Eve varmalıydı biran önce

Bir ekspres tren oracıkta yıktı hayallerini

Son nefesini vermeden hastanede

Bir gayretle hesap nosunu verdi

Oğluna baktı gözleriyle OKU dedi

Bunlar EMİNE nin son sözleriydi.', 'Daha onüçündeydi evlendirilmişti Çocuk olmadan anneydi şimdi Yıllar akıp geçiyor Hızlı adımlarla ayak uyduruyordu Biri hasta dört çocuğu olm...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/oku-oglum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Ver Özgürlüğümü', 'geri-ver-ozgurlugumu-muammer-celik-katsw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vefayı geceye koymuştun hani 

hani sabahlar düşmanındı senin 

gündüze kahredip, sitem ederdin

Akşam olma, güne batma derdin... 

Onun için değilmiydi kadınım 

benim hep gecelerde kaldığım 

yatağına ve yorganına kokumu 

için için içinde tutuklu kaldığım... 

Her gece içine çekirdin sen beni 

sehere kadar okşardım bende seni 

gidivermiştin dolun ay’ın ardından

sende tutuklu kalan özgürlüğüm idi 

bende geri istiyorum hepsini şimdi... 

24.05.2003

BirDeli', 'Vefayı geceye koymuştun hani  hani sabahlar düşmanındı senin  gündüze kahredip, sitem ederdin Akşam olma, güne batma derdin...  Onun için de...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/geri-ver-ozgurlugumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceylan', 'ceylan-ceylan-yarar-uabk1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimşekler çakıyor beynimde

İçimde gök gürültüleri

Seller gibi akıyor yaşlar gözlerimden

Yüreğimde kar taneleri

Oysa ki yüreğim sevgi doluydu

Gözlerim yakamoz gibi ışıl ışıl

Dans ederdim yürürken

Her yer kahkahalarımla çınlardı

Diğer adım da ceylandı...

Vurdular beni taaaa yüreğimden

Apansız beklemediğim bir anda

Bir anlık zevkleri uğruna

Harcadılar sevgimi kahpece sorumsuzca

Ceylanlar vurulduğunda

Gözleri ölür önce

Gözpınarlarında iki damla yaş

Neden mi? 

Kahpece vuruldu diye...

Boşuna demezler 

Yaralı CeYLaN ağlar diye...', 'Şimşekler çakıyor beynimde İçimde gök gürültüleri Seller gibi akıyor yaşlar gözlerimden Yüreğimde kar taneleri Oysa ki yüreğim sevgi doluydu...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ceylan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarmıha mı Germeli Seni', 'carmiha-mi-germeli-seni-muammer-celik-8iwup', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmem sana ne etmeli 

çarmıha gerip 

ellerinin içinden çivilemeli 

ki, 

parmakların yazacağına 

dillerin şakır şakır söylemeli… 

İnsafa gelir misin bilmem, 

ammaa; 

imansız gidişin bu bes belli...! 



22.05.2003 

BirDeli', 'Bilmem sana ne etmeli  çarmıha gerip  ellerinin içinden çivilemeli  ki,  parmakların yazacağına  dillerin şakır şakır söylemeli…  İnsafa gel...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/carmiha-mi-germeli-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurgun', 'vurgun-ceylan-yarar-44in3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine doğmakta güneş

Uykusuz gecelerimin üzerine

Yorgun düştü yine umutlarım

Bakamaz oldum enginlere

Gözlerimde ruhum gibi

Alıştı artık karanlığa

Başlamak istesemde yeni güne

Koşsam bedenim yorgun

Saçlarım, yüzüm, bakışlarım solgun

Müebbet yemiş sevdam 

Umutlarım sürgünde

Vurgun yemiş yüreğim...vurgun', 'Yine doğmakta güneş Uykusuz gecelerimin üzerine Yorgun düştü yine umutlarım Bakamaz oldum enginlere Gözlerimde ruhum gibi Alıştı artık karan...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vurgun-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdama Af', 'sevdama-af-ceylan-yarar-n9qt2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdamı esir yapmış yarim

Köle pazarında satıyor, 

Açık arttırmadayım ben

Gelen vuruyor, giden sövüyor.

Sevmek bumu? 

Yıllar sonra sevdan, 

Yarinin esirimi oluyor, 

Değersiz bir mal gibi

Köle pazarındamı satılıyor.

Emekler boşa, 

sevdan üç kuruşa gidiyor

Azat edilene dek

Sevdan yarin esiri kalıyor...', 'Sevdamı esir yapmış yarim Köle pazarında satıyor,  Açık arttırmadayım ben Gelen vuruyor, giden sövüyor. Sevmek bumu?  Yıllar sonra sevdan,  ...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdama-af-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi Sultan', 'yedi-sultan-ahmet-aksoy-2s2vm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yedi sultan varmış

Bir zamanlar yedi diyarın

Yedi doruğunda yaşarlarmış

Biri kadınmış sultanların biri erkek

Üçüncüsü sevgiymiş bu sultanların, 

Katıksız sevgi karşılıksız sevgi

Bırakmış diyarını aşka koşmuş

Dördüncü sultan aşkın olmuş

Aşk ve sevgi birleşince 

Rahat durmamışlar elbet

Tatlının kıymeti acı olmadan

Olmaz deyip, ayrılığa gitmişler

Ayrılıkla birlikteyken

Ayrılığın çocuğu özlem doğmuş

Sevinmişler özlemin doğumuna

Her şey çok güzelmiş ilk günler

Oysa özlemin tek hasretiyse ölümmüş

Ve sonunda kavuşmuş özleyen

Yedinci sultana 

Yedi diyarın son sultanına.', 'Yedi sultan varmış Bir zamanlar yedi diyarın Yedi doruğunda yaşarlarmış Biri kadınmış sultanların biri erkek Üçüncüsü sevgiymiş bu sultanlar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yedi-sultan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaratılış', 'yaratilis-ahmet-aksoy-ftvud', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden mi? 

Çünkü göl göl deniz deniz artık

Neden mi? Mavi mavi 

Siyah siyah artık

Nedeni açık

Gök gök, yer yer artık

Görmüyor musun güneşi

Görmüyor musun ayı

Hepsi yerli yerinde artık

İşte dünya işte insan

Cennet cennet, cehennem cehennem artık

Sınav başladı insan, sınav başladı artık.', 'Neden mi?  Çünkü göl göl deniz deniz artık Neden mi? Mavi mavi  Siyah siyah artık Nedeni açık Gök gök, yer yer artık Görmüyor musun güneşi G...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yaratilis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün, Bügün, Yarın', 'dun-bugun-yarin-gunay-aktag-5stm3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün

Bugüne benzemez

Bugün yarına.

Her gün

Başka bir gündür, 

Sakın unutma.', 'Dün Bugüne benzemez Bugün yarına. Her gün Başka bir gündür,  Sakın unutma....', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dun-bugun-yarin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üsdat Orhan Veli...', 'usdat-orhan-veli-umut-gul-7n4f1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Ağlasam sesimi duyar mısınız, 

Mısralarımda; '' 

Orhan Veli Kanık''

Diyorsun ya beni bu havalar mahvetti

işte beni de senin bu dizelerin cezbetti

nur içinde yat üstadım Orhan Veli

senin sayende  hastalığım nüksetti

okuyunca nasırlı Süleyman efendiyi

hele de sezince sendeki  ince nükteyi

kabardı ki sorma  bendeki şairlik hevesi

yazdım bende gündüz edip her geceyi

hep kafama takıldı şu tramvay meselesi 

hele gökyüzünü maviye boyama hikayesi

en çok neden seviyorum biliyor musun? seni

sanırım derdimiz aynı sözcüklerin kifayetsiz gelmesi…', '''Ağlasam sesimi duyar mısınız,  Mısralarımda; ''  Orhan Veli Kanık'' Diyorsun ya beni bu havalar mahvetti işte beni de senin bu dizelerin cezb...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/usdat-orhan-veli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyalıyım', 'dunyaliyim-i-brahim-atilmis-6xupu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kim çizdi bu sınırları, 

kim koydu habersiz bunca kanunları, 

ben varmıydım siz çizerken, 

ben varmıydım siz yasa çıkarırken? 

anımsamıyorum ve tasvipte etmiyorum! 

biliyorum boşuna serzeniş ediyorum

ama

genede kabul etmiyorum

ben dünya vatandaşıyım...

istemedende gelmiş olsam şu hayata

yaşayacağım varmı başka bir dünya? 

belki benimki bir rüya

ama

genede kabul etmiyorum

ben dünya vatandaşıyım...

din, dil, ırk, cinsiyet fark etmez

hayat denen kavgada sorunlar bitmez

istesekte başımızdan bela eksilmez

bilirim değiştirmeye gücüm yetmez 

ama

genede kabul etmiyorum

ben dünya vatandaşıyım...

istesem bu konuda destanlar yazarım

gideceğim en son yer toprak mezarım

değmesin aman barışa nazarım

kendi mezarımı ben kendim kazarım

ama

genede kabul etmiyorum 

ben dünya vatandaşıyım...', 'kim çizdi bu sınırları,  kim koydu habersiz bunca kanunları,  ben varmıydım siz çizerken,  ben varmıydım siz yasa çıkarırken?  anımsamıyorum...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dunyaliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bence', 'bence-i-brahim-atilmis-x11au', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gül''e gül diyebilmek, 

gül''ü güldürebilmek gülümseyerek.

ama! 

dalından koparmadan, 

bükmeden boynunu soldurmadan, 

sarartmadan yapraklarını, 

dikenlerini kesmeden! 

işte öylecesine olduğu gibi.

bence budur gerçek sevgi...', 'Gül''e gül diyebilmek,  gül''ü güldürebilmek gülümseyerek. ama!  dalından koparmadan,  bükmeden boynunu soldurmadan,  sarartmadan yapraklarını...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bence-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirazın Hikayesi', 'kirazin-hikayesi-ali-osman-yilmaz-cdbj1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seven gönül, sevilen de gönül

Bir araya gelince eder iki gönül 

İki gönül bir olunca samanlık seyran

Böyle sevgilere kim olmaz hayran

İki gönül çarpışır olur gönül karesi

Aşk doğurur döner ortalıkta aşk haresi

Verir meyvasını sevda çiçiçeğinin dalında

O güzelin güller açar bak o pak alnında

Aşk bahçesinin dört köşesinde dört güzel

Beklerler gönüllerini çalacak bir yiğit er

Yüzlerinde bir gülücük, gönüllerinde neşe

Bahçeye baktım o bile  zevkten dört köşe

Beklediğine kavuşunca, güller gibi açılır

Sevinçle koşturur, yel estirir etekleri saçılır

Kalbinde sevinçli bir titreme sevdiğine atılır

Sarılır kollarına, tek beden aşk yatağına yatılır.

Üç yıl sonra doğurur, adına derler Kiraz

Yuvasında mutludur, etmez er''ine naz

Dalar düşünceye, bulunur mu böyle bir haz

Ellerini açarak göklere, dua da eder biraz

İki genç oturur kıyıda, akşam güneşi vuruyor

Havalar sıcak mı sıcak, mevsimlerden yaz

Sevda çiçekleri saçarak oğlan kızı öpüyor

Çaktırmadan baktım, mutlu gülüyor Kiraz.', 'Seven gönül, sevilen de gönül Bir araya gelince eder iki gönül  İki gönül bir olunca samanlık seyran Böyle sevgilere kim olmaz hayran İki gö...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kirazin-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-hanife-efendioglu-ltg7j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim içimdeki ben, 

Sırtı bana dönük, 

Önü arka tarafa bakıyor.', 'Benim içimdeki ben,  Sırtı bana dönük,  Önü arka tarafa bakıyor....', ARRAY['Türk Edebiyatı','Şiir','Hanife Efendioğlu']::text[], 8.5, '{"poet":"Hanife Efendioğlu","poet_slug":"hanife-efendioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ben-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen İç', 'bir-sen-i-c-pir-sultan-abdal-l5bwq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel şahtan bana bir dolu geldi

Bir sen iç sevdiğim bir de bana ver

Kavlim sultan Kızıl Veli''den geldi

Bir sen iç sevdiğim bir de bana ver

Payım gelir erenlerin payından

On İki İmam nesli Ali soyundan

Selman''ın içtiği üzüm suyundan

Bir sen iç sevdiğim bir de bana ver

Beline kuşanmış nurdan bir kemer

Aşkın dolusunu içenler kanar

Herkes sevdiğine bir dolu sunar

Bir sen iç sevdiğim bir de bana ver

Pir Sultan''ım hamı hası seçerim

Hak okurum aşk kitabın açarım

Yar elinden ağu gelse içerim

Bir sen iç sevdiğim bir de bana ver', 'Güzel şahtan bana bir dolu geldi Bir sen iç sevdiğim bir de bana ver Kavlim sultan Kızıl Veli''den geldi Bir sen iç sevdiğim bir de bana ver ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sen-ic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri Sabır Biri Şükür Bir Dua', 'biri-sabir-biri-sukur-bir-dua-pir-sultan-abdal-bmg0i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Muhammed''in üç beni var yüzünde

Biri sabır biri şükür bir dua

Kudret ile yanar anın çırağı

Biri sabır biri şükür bir dua

Şükür imiş her işleri bitiren

Mümin kulu rahmetine yetiren

Sabır imiş şu dünyayı götüren

Biri sabır biri şükür bir dua

Sabır imiş şu dünyanın temeli

Verdiği nasibe şükür demeli

İsteyen kullara hayır ameli

Biri sabır biri şükür bir dua

Sabr edelim gönül ne gelir elden

Sabırlı kulunu sevmez mi sultan

Yusuf''u kurtardı kuyudan gölden

Biri sabır biri şükür bir dua

Pir Sultan Abdal''ım gönlüme giren

Suçluyu suçsuzu bakmadan gören

İsteyen kulların muradın veren

Biri sabır biri şükür bir dua', 'Muhammed''in üç beni var yüzünde Biri sabır biri şükür bir dua Kudret ile yanar anın çırağı Biri sabır biri şükür bir dua Şükür imiş her işle...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biri-sabir-biri-sukur-bir-dua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Muhammet Ali Diyenlerdeniz', 'biz-muhammet-ali-diyenlerdeniz-pir-sultan-abdal-tg23q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey yezit bizlerde kıl ü kal olmaz

Biz Muhammet Ali diyenlerdeniz

Tarikat ehline mezhep sorulmaz

Biz Muhammet Ali diyenlerdeniz

Eğnimize kırmızılar giyeriz

Halimizce her manadan duyarız

İmam Cafer mezhebine uyarız

Biz Muhammet Ali diyenlerdeniz

Her kimin çerağın yoksa Hak yakar

Mümin olanları katara çeker

Aslımız on iki imama çıkar

Biz Muhammet Ali diyenlerdeniz

Muhammet Ali''dir kırkların başı

Anı sevmeyenin nic''olur işi

Atalım yezide laneti taşı

Biz Muhammet Ali diyenlerdeniz

Biz tüccar değiliz alıp satmayız

Erkandır yolumuz yoldan sapmayız

Karnımız geniştir biz kin tutmayız

Biz Muhammet Ali diyenlerdeniz

Baharda açılır gonca gülümüz

Ol dergaha doğru gider yolumuz

On iki imamı okur dilimiz

Biz Muhammet Ali diyenlerdeniz

Pir Sultan''ım eyder erenler gani

Evveli Muhammet ahiri Ali

Anlardan öğrendik erkanı yolu

Biz Muhammet Ali diyenlerdeniz', 'Ey yezit bizlerde kıl ü kal olmaz Biz Muhammet Ali diyenlerdeniz Tarikat ehline mezhep sorulmaz Biz Muhammet Ali diyenlerdeniz Eğnimize kırm...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/biz-muhammet-ali-diyenlerdeniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim İçtiğimiz Dolu', 'bizim-i-ctigimiz-dolu-pir-sultan-abdal-nbzv9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizim içtiğimiz dolu

Doluların dolusudur

Ela gözlü mestaneler

Şah Ali''nin kuzusudur

Ol Şahtan gelen gaziler

Gönül mürşidin arzular

Bu gün de bayramdır bize

Her gün de bayramdır bize

Hak bize nasibin verdi

Lokmanların hasın verdi

Yezid''e cevr-ü cefasın

Mümine safasın verdi

Alçacık yemiş dalı

Altında yeşil halı

Ver muradımı benim

Ya Muhammet ya Ali

Yezitler aralandı ya

Müminler sıralandı ya

On iki imam, Şah Ali

Bu yolda paralandı ya

Kırmızı geyen gelsin

Yezid''i kıran gelsin

On sekiz bin alemin

Nasibin veren gelsin

Pir Sultan''ım der gaziler

Yazıldı nurdan yazılar

Durdu analı kuzular

Mürşit de pirin arzular', 'Bizim içtiğimiz dolu Doluların dolusudur Ela gözlü mestaneler Şah Ali''nin kuzusudur Ol Şahtan gelen gaziler Gönül mürşidin arzular Bu gün de...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bizim-ictigimiz-dolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boz Atlı Hızır', 'boz-atli-hizir-pir-sultan-abdal-7bmwm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yavru yolladım gurbet ellere

Emaneti sana boz atlı Hızır

Seni bekçilerler nice ellere

Emaneti sana boz atlı Hızır 

Nice günler gördüm bahtı karalı

Nice günler gördüm dertli çareli

Bir yavru yolladım yürek yaralı

Emaneti sana boz atlı Hızır 

Hak''tan bize bizden halka zulüm yok

İmanım var vadesize ölüm yok 

Senden başka kanadım yok kolum yok 

Emaneti sana boz atlı Hızır 

Pir Sultan Abdal’ım böyle m''olacak 

Beklerim yolların yavrum gelecek 

Analı babalı murad alacak 

Emaneti sana boz atlı Hızır', 'Bir yavru yolladım gurbet ellere Emaneti sana boz atlı Hızır Seni bekçilerler nice ellere Emaneti sana boz atlı Hızır  Nice günler gördüm ba...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/boz-atli-hizir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolun Düşerse Sor Beni', 'yolun-duserse-sor-beni-salih-ozalasan-81647', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün yolun düşerse

Benim doğduğum

Sevda çektiğim yerlere

Beni göremesen de

Sor beni bilenlere

Sevdaya düşmezden 

Öncemi bilenlere

Sor ki söylesinler sana

Bir kara sevda

Düşürmüş beni ne hallere

Şiirler yazdığım, fal baktığım

Hayal ağacımda dur biraz dinlen

Eşele şöyle bir toprağı

Göz yaşlarım nasıl karışmış yerlere

Dalında ki bülbüle sor beni

Anlatsın nasıl düştüğümü yerlere

Nasıl sevdalandığımı 

Yediveren güller içinde bir güle

Sor beni, sor ki tabiat gelsin dile

Söylesinler sana gizli sırlarımı

Gülmek nasip olmuş mu bir günüme

Serseri sevdalar düştüğünde 

Apansız günün birinde gönlüme

Nasılda nikahlanmışım ben hüzünle

Sor beni adını verdiğim çoban yıldızına

Nasıl döndüğümü pervane olup etrafında

Seninle sensiz kalıp ağladığımı

Sor, sor ki söylesinler sana

Y.Tarihi 01-10-2003 Saat 19.30

Salih ÖZALAŞAN', 'Bir gün yolun düşerse Benim doğduğum Sevda çektiğim yerlere Beni göremesen de Sor beni bilenlere Sevdaya düşmezden  Öncemi bilenlere Sor ki ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yolun-duserse-sor-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dünyanın Evvelini Sorarsan', 'bu-dunyanin-evvelini-sorarsan-pir-sultan-abdal-4ywdq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu dünyanın evvelini sorarsan

Allah bir Muhammet Ali''dir Ali

Sen bu yolun sahibini ararsan

Allah bir Muhammet Ali''dir Ali

Tahtını terketti İbrahim Edhem

Süleyman Nebi''ye verildi hatem

Her kulun alnına yazıldı sitem

Kişinin çektiği yoludur yolu

Erenler öldürür yoldan şaşanı

İhlas ile kaldırırlar düşeni

Tarikatta her kişinin nişanı

Erenler katında bellidir belli

Erenler elinden dolu içildi

Ol saatte kıl-ü kalden geçildi

Firdevs-i alada güller açıldı

Cennet-i alanın gülüdür gülü

Pir Sultan Abdal''ım ummana daldı

Yenemedi kendin engine saldı

Hak-i payınıza yüz süre geldi

Erenlerin kemter kuludur kulu', 'Bu dünyanın evvelini sorarsan Allah bir Muhammet Ali''dir Ali Sen bu yolun sahibini ararsan Allah bir Muhammet Ali''dir Ali Tahtını terketti İ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-dunyanin-evvelini-sorarsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Yardan Haber Geldi', 'bugun-yardan-haber-geldi-pir-sultan-abdal-6ab41', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün Yardan Haber Geldi

Bir Bir Yandan Bir Bir Yandan

Eğildim Bir Buse Aldım

Bir Bir Yandan Bir Bir Yandan

Güzel Olanı Severler

Yanağından Gül Dererler

Kulakta Mengiç Küpeler

Bir Bir Yandan Bir Bir Yandan

Baş Koydum Yarin Dizine

Uykular Girmez Gözüme

Ağ Ellerin Sür Yüzüme

Bir Bir Yandan Bir Bir Yandan

Şekerden Şerbet Ezerler

İnce Tülbentten Süzerler

Dört Yanım Almış Güzeller

Bir Bir Yandan Bir Bir Yandan

Pir Sultanım Gel Yanıma 

Seni Sarayım Canıma

Dola Kolların Boynuma

Bir Bir Yandan Bir Bir Yandan', 'Bugün Yardan Haber Geldi Bir Bir Yandan Bir Bir Yandan Eğildim Bir Buse Aldım Bir Bir Yandan Bir Bir Yandan Güzel Olanı Severler Yanağından ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bugun-yardan-haber-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara', 'ara-serkan-dogan-2mftg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yüreğim sendeledi derinde

ay bulutları gömüldü

ve gölgeyi doğuran ışık söndü.

..

odama yabancılaşan kaçışların adımları soğuk

koğulan şeytanla eşinin izdivacı

kadar dar soluklu ve lekelisiniz

gündüzüne özenen bir bedende

kızıla dalıp boğulmuş dudaklarınızı

saklayamazsınız ateş dolusu öpüşmenizi 

..

cennet uzak ve yitiktir kirli kisvelerde

araf ise rafa kaldırılmış şık defterlerde, 

kudüs şehri gibi zarif 

karanlıktaki fırtına

seni andığımda yağmurlar yağdıran

utancımın kaldırımında

kimse anlayamadı ki yalnızlıkların 

yıkıcı bir yanının olduğunu 

senden başka ayyüzlüm özleminin

felaketler doğurduğunu

kimseye söyleyemezdi sezse de 

anıların yanılmaz hafızası.

balçığa saplandığı söylenen

hüzün çöllerimiz ne yöne düşerdi

ey, herşey çok saf olmalı 

diyen zübdesi silik kanat uçlarımın

tanığı suçlu semada masum kulaçlarımın

yetişmediği yere yeten zamanın kölesi

ışık saçan altın yayım ve arzu oklarım

kulu olduğuma isyan etmekten 

korkarım ve yakarım gemileri sahilinde

kalbimi bir kere bıraktığım, 

yalan değildir ama mısralardır 

hiçliklerde aradığımız aşkımıza çağıran.

(Yedi İklim 111/13)', 'yüreğim sendeledi derinde ay bulutları gömüldü ve gölgeyi doğuran ışık söndü. .. odama yabancılaşan kaçışların adımları soğuk koğulan şeytan...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ara-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbül Gibi Zar Eylesem', 'bulbul-gibi-zar-eylesem-pir-sultan-abdal-tjrs4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Takdir-i İlahi budur nasibim

Az vermiştir çok istemem çare ne

Bu kadar nasibim budur kisibim

Bülbül gibi zar eylesem çare ne

Düşmanımın yaraları azmaya

Dostumun hayrını şerre yazmaya

Bu dünyada melül mahzun gezmeye

Mahlukattan ar eylesem çare ne

Bakmaz mısın viran olmuş bendime

Halim malum olsun ol efendime

Hançer alsam hamle kılsam kendime

Kendi kendim paralasam çare ne

Gam kasavet yuva yaptı sineme

Kahır gömleğini eğnime

Perişanlık düştü viran göynüme

Türlü türlü aşk bağlasam çare ne

Pir Sultan Abdal''ım çekerim çoktan

Ya İlahi bizi kurtar tutsaktan

Bu derdin dermanın isterim Hak''tan

Halka halim arz eylesem çare ne', 'Takdir-i İlahi budur nasibim Az vermiştir çok istemem çare ne Bu kadar nasibim budur kisibim Bülbül gibi zar eylesem çare ne Düşmanımın yara...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bulbul-gibi-zar-eylesem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devir', 'devir-serkan-dogan-7lwjy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sus, konuşma

ruh zindanım ve beden duvarım

kilitlendi yalvarışıma

aykırı, soylu yolların uşağı

merdivenlerinden devrilen 

içindeki nehir gibi evlerin

değildir kör devinim / bu vahşi kargaşa

hayal lanet olasıca uykular yumağı

iğrenmenin gülleri gelir ve iğneler

elimde silinen lekeli kelimeler

susayıverirse sana, devir

gerisine aldırma

(Yedi İklim 112/49)', 'sus, konuşma ruh zindanım ve beden duvarım kilitlendi yalvarışıma aykırı, soylu yolların uşağı merdivenlerinden devrilen  içindeki nehir gib...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/devir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalan Murtaza Ali''dir', 'calan-murtaza-ali-dir-pir-sultan-abdal-1zgr8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gafil olman hey erenler

Gelen Murtaza Ali''dir

Yezid''e batın kılıcın

Çalan Murtaza Ali''dir

Alçağa tutmuş yüzünü

Hakk''a bağlamış özünü

Kırklar ile bir üzümü

Yiyen Murtaza Ali''dir

Turnaya vermiş sesini

Aşıklar tutsun yasını

Hem önünce devesini

Yeden Murtaza Ali''dir

Ali''dir Allah''ın dostu

Hü dedi Zülfikar kesti

Selman''a sünbüllü desti

Veren Murtaza Ali''dir

Gülün bağlar deste deste

Bağlar da gönderir dosta

Mihmandan bir dolu iste

Sunan Murtaza Ali''dir

Derildi çıktı havaya

İndi döşendi ovaya

Güvercin donda kayaya

Konan Murtaza Ali''dir

Gülün bağlar baka baka

Bağlar da gönderir Hakk''a

Ejderhayı iki şakka

Bölen Murtaza Ali''dir

Dost bağında kızıl alma

Gül rengi sararıp solma

Pir Sultan''ım gafil olma

Gelen Murtaza Ali''dir', 'Gafil olman hey erenler Gelen Murtaza Ali''dir Yezid''e batın kılıcın Çalan Murtaza Ali''dir Alçağa tutmuş yüzünü Hakk''a bağlamış özünü Kırklar...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/calan-murtaza-ali-dir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğunun isyanları', 'dogunun-isyanlari-serkan-dogan-g8g05', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'doğunun isyanları - 1

doğunun isyanları serildi şehre

kalbi soğuktur anlamı

aklının sonunda galebe çaldığı yerdir

kaybolan kimliklerimizi örten kalabalık

titrer gibisin ötekinin simyasına gömülüp

çömelmiş ve ağlıyorsun bir harabeye bakıp

bağırma boşuna

duymazlar yakarışını yakışıksız

sanrılardan ibaret şimdilik hulyan

açıkta ve üryan ve uzun bir kalp görüntüsünde

buz yığınlarını dağlayan bahar

-

doğunun isyanları - 2

sev beni asla sömürme

verme ömründen dakika bile

sevimli bir mevsimin hatırlattığıydı

seninle birlikte kaybettiklerimiz

ve doğan sarışın güneşin ensesinde

sendeleyen bir bebek gibi bu yolda

yollananları yaşayışımız

-

dudaklarının yıkıldığı derinde 

fırtınalar ayıklayan  burgaçlı kasırgalar çıkaran

görkemi kemerinde ve verimli bir ırmakla

gökyüzünü sıvadığım tiz tınılı sesin

bronzlaşan gözlerinin donukluğuna karıştı

burnunun iki kıyısından iki damla gözyaşı

suladı sevdalı sadağımın bağlarını



doğunun isyanları - 3

dönüşümlerde devinen öpüşlerini getirdim sana

ver bana ulaşılmaz yalnızlığımdan

küçük olsun elleri bir de yumuk olsun

açıldığında açılsın da sarssın gökleri

kapadığı zaman denizleri dağlara kapasın.

okşandı benliğim gururun hançerleri bilendi

taşmaya yüz tutan içimdeki kan gölleri

kopup gelen kaynağını görünce sahneden elendi

kuma vurdum ama çöller çağırmaz oldu

sahipsiz bir semada kalıverdim öylece

gergin ve ince bir ipin anımsattığıydı

daha dün düşlediğimiz yıldızlardan vazgeçiren

seçilip ayrılan bütün günlerimi saydım da hayatta

tutmadı memnunluk taşıyan bir mutlu an..

aslı yokmuş her yarım kaldığında tam sayılan

dünün daha bugünden yarını yaşadığı söylemi

-

doğunun isyanları - 4

uyandığımda ruhum isyan doldurdu kadehimi

kıyametin arefesiymiş dinlemedi yedi dikişte içti

iklimleri devrildi geçmiş zamanın

susuzluktan kurudu dudakları bulutların

şimal yıldızının ışığı sustu.

yine de ben çeviririm virdini direne direne

suyun, ağacın, toprağın puslu hükmüne

boyun eğmem başkaldıran doğasına

felaketimin böylesine silik uyarlamasının

sakınan, susan sen miydin ben mi sürgünde

öyleyse soksun kınına kılıçlarını korkuluklar

sonra bir kuş olsun ruhum aniden

girsin yittiği kafesine.

doğunun isyanları -son

geldiğin yer pek iyi değildi

gideceğin yere de o kadar bayılmıyorsun

söyle, nedendir şimdiki sabırsızlığın.

(Yedi İklim 124/19 3-4)', 'doğunun isyanları - 1 doğunun isyanları serildi şehre kalbi soğuktur anlamı aklının sonunda galebe çaldığı yerdir kaybolan kimliklerimizi ör...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/dogunun-isyanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Dediler', 'can-dediler-pir-sultan-abdal-8iulz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırklar ile yedik içtik 

Kaynayıp sellere coştuk 

Baş koyup niyaz eyledik 

Geç otur meydan dediler 

Can dediler pir dediler 

Geç otur meydan dediler 

Yolumuz sevgi yoludur 

Sen de serin koy dediler 

Pir Sultanım kanım katlim 

Gönlümü gönlüne kattım 

Yüzelli yıl ölü yattım 

Daha sağsın can dediler', 'Kırklar ile yedik içtik  Kaynayıp sellere coştuk  Baş koyup niyaz eyledik  Geç otur meydan dediler  Can dediler pir dediler  Geç otur meydan...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/can-dediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Dağlarının Dirilişi', 'eylul-daglarinin-dirilisi-i-lyas-sahin-lrvre', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bin dağ diriliyor, usulca

Tatlı bir yel esiyor, arkası kasırga

Bir damla sanırsın onu

Dikkatle baksan görürsün okyanusu

Samimiyetin varsa yani hazinen

Açmalısın kapağını ve paylaşmalı

Gönül paylaşımının mükafatı

Bire kırk belki de kırk milyon kere kırk olmalı

Yıkılan dağ şaşırtmasın seni

Dağı yıkan gücün değil miydi? 

İçtenliğin, gücün ve yardım

Bileşkelerin en güzeli bu sanki

Yiğitliğin bedeli, sözün eri olmaktır eri

Tutulan her söz bir hedefin merdiveni

Tırmanır basamakları bakar isen aşağıya

Dağ değil ülkeler olur hayali

Yüce sevgiliye yüce sevgiyle ulaşılır

Cüce korkular yüce korkuyla aşılır

Fiildir çözümü problemin, zamanın

Dirilişin zamanı yok, aslında her zamandır

Süzülmek gökte, hayalde midir sadece? 

Gerçeğin de gerçeğidir varoluşu bilenlere

Amelin karşılığı mükafat ya da müeyyide

Hayalle başlar, ardından erişirsin gerçeğe

Yatanlar, oturanlar, ayağa kalkanlar

Duranlar, yürüyenler, koşanlar 

Düşenler, takılanlar, takla atanlar

İnanılmaz, asla bir olmazlar

Nice azlıklar vardır; tek yürek, tek beden

Tek atar şah damarları, tek olana varana dek

Bilirler kemiyet değil önemli olan keyfiyet

Hedefleri de tek sevinçleri de tek

10/2003', 'Bin dağ diriliyor, usulca Tatlı bir yel esiyor, arkası kasırga Bir damla sanırsın onu Dikkatle baksan görürsün okyanusu Samimiyetin varsa ya...', ARRAY['Türk Edebiyatı','Şiir','İlyas Şahin']::text[], 8.5, '{"poet":"İlyas Şahin","poet_slug":"i-lyas-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/eylul-daglarinin-dirilisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeke Çeke (Seversen Ali''yi)', 'ceke-ceke-seversen-ali-yi-pir-sultan-abdal-9c1mh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çeke çeke ben bu dertten ölürüm

Seversen Ali''yi değme yaram

Ali''nin yoluna serim veririm

Seversen Ali''yi değme yarama

Ali''nin yarası yar yarasıdır

Buna merhem olmaz dil yarasıdır

Ali''yi sevmeyen Hakk''ığn nesider

Seversen Ali''yi değme yarama

Bu yurt senin değil konup göçersin

Ali''nin dolusun bir gün içersin

Körpe kuzulardan nasıl geçersin

Seversen Ali''yi değme yarama

Ilgıt ılgıt oldu akıyor kanım

Kem gelde didara talihim benim

Benim derdim bana yeter ey canım

Seversen Ali''yi değme yarama

Pir Sultan Abdal''ım deftere yazar

Hilebaz yar ile olur mu pazar

Pir merhem çalmazsa yaralar azar

Seversen Ali''yi değme yarama', 'Çeke çeke ben bu dertten ölürüm Seversen Ali''yi değme yaram Ali''nin yoluna serim veririm Seversen Ali''yi değme yarama Ali''nin yarası yar yar...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ceke-ceke-seversen-ali-yi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin gülleri', 'gecenin-gulleri-serkan-dogan-r14jf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hubris uğruna, 

gecenin beyaz gülleri ökçesine takıldılar

sanrılarım olmasın ne olur, sen ol, aynan olayım

delilik hiç bu kadar yakışmamıştı insana

ayrılık peronları, kimilerinin kimlikleri orada

ölü doğuşunu saklıyorlar son yolculuklara

akmayan gözyaşlarının taş kesilen ve yarım

düğümlü soluğu ışığımı kırıyor

törpülenen tereddüdün tozları bir anda

yatıya kalan kadim dost sayılıyor

durulan o gölün suları şimdi dağılıyor

ormanın bol renklerinden iki mor tebessüm

sırıtışıyla eğretileri apaçık bir balçığı

çağrıştırır ırmak balığına fısıldar benim

içimde yaprak kımıldamıyor

içim içime sığmıyor

mesafesi kadar inleyen rüzgâr, şiir

nâmeyi sıyıran kavislerini öpüp yakama taktığım

ayağımın altına serili antika melekler

yayla dumanları taze tezatlarla sevişir

bir çırpıda kaç kez sevdim dediğim

arı ve üryan penceremdeki kıpkızıl şafak

yine yepyeni bir bedrin siperi

sâyelenmiş perdesine açılmış allığının mahremi

korkudan başka sığınacak liman göremedim

gönlüme sığdıramadığım aşkını öremedim

(Yedi İklim 103/10)', 'hubris uğruna,  gecenin beyaz gülleri ökçesine takıldılar sanrılarım olmasın ne olur, sen ol, aynan olayım delilik hiç bu kadar yakışmamıştı...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gecenin-gulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taze bezemeler', 'taze-bezemeler-serkan-dogan-ilay5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1.

meyve vermeyen ağaç gibi

yararsız olsun bu şiir

onun o ölesiye

uzayan dallarını 

saymazsak.

2.

sen susmalarımı sorarsın

sonra, seneler sonra, 

elinde bir sebeple gelirsin

3.

devrimler devrinde 

hepimiz nihilisttik

gün devrildi

güz sevindi

biz bittik...

4.

otel odaları denilen

düşman memleketi

mahvetti kalbimizi

5.

kimi başında taçla doğar

kimi elinde kılıçla

ben kalemle doğdum

başka eşyaya el sürmem

6.

some of these days

you’ll miss me honey

and, when you leave me

just nothing will remain..

7.

kısa ve az kişili bir oyun bu

unutmak her şeyi bitirir mi

hatıralara dönmek istediğinde

dünyayı aynı gözle göremezsin

bir kez gittiğinde şansın yok

kazanır kaybedersin mutlaka

bir türlü sevinemezsin', '1. meyve vermeyen ağaç gibi yararsız olsun bu şiir onun o ölesiye uzayan dallarını  saymazsak. 2. sen susmalarımı sorarsın sonra, seneler so...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/taze-bezemeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çektiğim Cevr-ü Cefayı', 'cektigim-cevr-u-cefayi-pir-sultan-abdal-44gf2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çektiğim cevr-ü cefayı

Çekerim senden ötürü

İkrar iman bir olunca

Sen de çek benden ötürü

İkrar imanı güderim

Sensiz alemi niderim

İşte geldim, uş giderim

Bir tatlı dilden ötürü

Severim tatlı dilleri

Koklarım gonca gülleri

Sararım ince belleri

Gittiğim yoldan ötürü

Bana ne kıyak bakarsın

Sinemi oda yakarsın

Bana ne sitem edersin

İkrarsız elden ötürü

Ferhat Şirin''ine tapar

Külüngün havaya atar

Başını altına tutar

Can verir candan ötürü

Mümin olan Hakk''a tapar

Münafıklar yoldan sapar

Arka vermiş dağı çeker

Ferhat Şirin''den ötürü

Pir Sultan''ım deme yalan

Etme imanına talan

Bu dünyada gerçek olan

Ser verir sırdan ötürü', 'Çektiğim cevr-ü cefayı Çekerim senden ötürü İkrar iman bir olunca Sen de çek benden ötürü İkrar imanı güderim Sensiz alemi niderim İşte geld...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cektigim-cevr-u-cefayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berrak', 'berrak-serkan-dogan-ov2jk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1.

gotik, barok ve arabesk

beyaz zambaklar topluyorum

rutubetimi kusuyorum yıllara.

2.

yazgın kararmış, hüzünden öte

böğürttüler beni, cesedim kanlı sote

biletimi aldım ve yeltendiydim ölmeye

imkanı yok teyellenmişim bir kere 

imlası bozuk bir gecenin çetelesi

ne kadar tutulursa artık

öyle gerilmekte ay.

3.

karıncalandı kanatlarım

kuşkularım gürültü devşirir

açık seçik görülmekte meydan

onlara kalmış örümcek yığınlarına

bakıyordu parlak ve irice gözleriyle, 

kum tepelerini yağmalayan bir bedevi

ağını örüyordu belki o da kendi kendine

4.

naif bedenimi örtüyor haki elbiseler

sen beni değil şapkamı seviyorsun

savursan da beni, savunsan da kendini

mırıltıların artık gıdıklamıyor diyorum

dudakların kovuklarında konaklar

bir aşk aşiretin vardır biliyorum, 

ama bitti şimdi aldanmıyorum

5.

acıklı prova, yanılma payı, yorum hatası dersin, 

bağrış çağrış yalan işte böyle geçmişti bir ömür

gel al sen de al ruhumu kendine benzet sömür.

6.

yön sorar yordam dilenir 

ıslığını kıssa ıpıssız kalır.

parlar ışığında menekşeler

kollarımda kelepçeler durur

yorulur annem vurulduğunda

bilinçaltımdakiler belirir hemen

esir alınıp hapsolunur sipahiler.

7. 

ne pahasına göçtüm anayurdumdan 

vurdumduymaz aymazların sözüne kanıp

ne diye terk eyledim cennet düşsel vatanımı

rap rap diyerek inlettiğim vazgeçilmiş toprakları

ayak basılmamış ne köşesi kalmıştır halbuki

iklimleri değiştiren bir hasrettir çektiğimiz 

biz ikimiz ve öteki sanki diğerleri gibidir

kabuğundan sıyrılan bir gelincik bir

kardelen maviliğinde gecenin

kördüğüm aşka uzanırım.', '1. gotik, barok ve arabesk beyaz zambaklar topluyorum rutubetimi kusuyorum yıllara. 2. yazgın kararmış, hüzünden öte böğürttüler beni, cesed...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/berrak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aralık', 'aralik-serkan-dogan-yq6mi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ölümlüler üzerine susunca gün

karanlığa gömülür koyu kırmızı sokaklar

ve kalabalıklara direnen kayıtsızlığa sürünür

benim aramadan usanmayan ömür törpüsü günlüğüm

''tepe tepe kullan ve harca kalbimi

ucuz özürler kalsın kıvamında''

yarası kimsenin umrunda değil çocuğun

kanarken çıkmaz yollar harmanında bırakılan

o değilmiş gibi yine de gülüyor acılarına

küçük bir öpücük çıkmaz mı sokaktan

silik anılara tütsüler yaksın, korlar söndürsün

onun soğuk yüzünü bir kere görsen bin defa ölürsün

demeden de edemem masum hafızanın tenhasında

iklimini bilmediğim kelimelere değmeden gidemem

''ayrılığa soyunan kış kapıyı vurdu

definemin efendisi yazıya durdu''

antik çağların melankolik coğrafyasında

biçilen bedelini ödeye dursun ikizlerin

öyküsünü mırıldanır posası cıvıyan metaforlar

cam yamalı sıkıntı panayarına görücüye çıkmış

yozluğuna susayan kızıl kıyamet kaçkınları

sarhoş şairler yolu şarışın şarkılarla dolu şehrin

ana caddelerini ölesiye severim evimin

kapanan kapı cilasını tattığımdan bu yana

nerede kına boyalı pencere görsem için için acınırım

nedeni olduğum ilkel mülkiyet kavgaları anısına

''dün gece bütün keşkelerimi temize çektim

yetmedi odamın velvelesi yürüdüm geldim sana''

terkedişinin lirik isyanına gebedir mistik endişelerim

sıfıra dayandı zemheri mühürledi susuz dudağım

ayrı komazdı aykırı korku kalyonlarını kırağı kılığında

ayrılık kara renkliydi ve besbelli mevsim ayazdı

yasak sayfalara özet çıkardım en derin dehlizlerinden

erken kilitlenmiş debdebeli delilik yemininin

sözü edilmez oldu, söyle sevgili, ne oldu

niye yarım söylenir zincire vurulu dizeler

''ardından bakarken aynada adımlarını izledim

yüz sürdüğüm düğümlerden bekleyişler çözüldü''

ölü inişlerin belki de yoktu yokuşu

kuşkusunu sakladı kayıp korsan haritaları arasına

inleyen leşlerini peşpeş çeken şüphelileri

de dinlemedim deldim feleğin fitilli ipliğini

bağladım dolunayların aydınlık elbisesine

bol gerilimli kaldırımına bastım da ayağımı

öyle süsledim utançtan yanmış yanağını

ben bittim, bitirildim sen de gitme diyemeden

şaşkın ve üşüyen gözlerle gördüm gelişini

bronz sadalarla ısıttın yüreğimi sevgilim.....', 'ölümlüler üzerine susunca gün karanlığa gömülür koyu kırmızı sokaklar ve kalabalıklara direnen kayıtsızlığa sürünür benim aramadan usanmayan...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/aralik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman', 'pisman-ahmet-aksoy-tp7xm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğime takılmış kancan

Ne zaman çeksen misinanı

Beni de sürüklüyorsun peşinden

Çaresizim ki çaresizlik

Sövdürüyor beni

Lanet olsun

Onca balık arasından 

Beni çektiğin güne', 'Yüreğime takılmış kancan Ne zaman çeksen misinanı Beni de sürüklüyorsun peşinden Çaresizim ki çaresizlik Sövdürüyor beni Lanet olsun Onca ba...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/pisman-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Sonbahar', 'mevsim-sonbahar-salih-ozalasan-fhmdj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mevsim yine sonbahar

Takvimler 20 eylül 2003

İlk ağladığım gün

Hayata gözlerimi açtığımda

Anamın ak sütünü ilk içtiğim gün

Dönüp ardıma bakıyorum

Nasılda geçmiş zaman

Ömür aşmış yolun yarısını

Oysa doğdum daha sanki dün

Sonbaharın hazanı çökmüş üzerime

Gülüşlerimde bile sırıtıyor hüzün

Kazandıklarım denizde bir damla

Kaybetmişim; ellerim boş gülmüyor yüzüm

Sevdalara dalmışım göl dururken denizlere

Dağlar çekmez hasret dolmuş içimize

Yıkılıp yerlerde sürünürüz

Kulak veren yok sesimize

Sonbaharda dökülen yaprak misali ömrüm

Savrulup gitmiş bilinmeze

Yıllar yılları yıpratıyor ömrüm gibi

Sevda yüreğimde yeni yıla merhaba

Muhtacım mutlu yıllar dileğinize

Aslında kimse hatırlamaz ya 

Kutlarım sadece hayallerde

Umutlar bir başka sonbahara

Kısmet belki bir gün uğurlarım sevenlerle

Yeni bir yıl yeni bir umut

Kısmet belki yenisi kıymet bilenlerle

Y.Tarihi 20-09-2003 

Salih ÖZALAŞAN', 'Mevsim yine sonbahar Takvimler 20 eylül 2003 İlk ağladığım gün Hayata gözlerimi açtığımda Anamın ak sütünü ilk içtiğim gün Dönüp ardıma bakı...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mevsim-sonbahar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ertesi Göç', 'ertesi-goc-ahmet-aksoy-f0z4b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdası elinde kalan

Aslına sadık kalınmış

Bir kopya gibidir

Bir terk ediş ertesinde

Öyle ki aslında yalnızca 

Bir gidiş değildir bir terk ediş

İki kişilik bir bilettir

Lakin farklı yönlere

Biri yelkenleri açıp

Açılırken yeni ufuklara

Diğeri çoktan

Parçalanmıştır kayalıklarda', 'Sevdası elinde kalan Aslına sadık kalınmış Bir kopya gibidir Bir terk ediş ertesinde Öyle ki aslında yalnızca  Bir gidiş değildir bir terk e...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ertesi-goc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yakıp Bir Söndürdüğüm', 'bir-yakip-bir-sondurdugum-ahmet-aksoy-97idf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yakıp bir söndürdüğüm

Sigara gibisin zaman

Bense bile bile seni içiyorum

Damarlarımda dolaşan

Kan gibi muhtacım sana

Ve kahrediyor beni

Avare gençlerin bilmediğini bilmek

Ah yaşam sigara gibi paket paket

Ki beden kaç dal dayanır daha.', 'Bir yakıp bir söndürdüğüm Sigara gibisin zaman Bense bile bile seni içiyorum Damarlarımda dolaşan Kan gibi muhtacım sana Ve kahrediyor beni ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-yakip-bir-sondurdugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çam Kokan Bir Selvi Ağacı', 'cam-kokan-bir-selvi-agaci-ahmet-aksoy-vkyna', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçmişi kalabalık

Şimdisi ıssız bir 

Tren istasyonu kenarında

Çam kokan bir selvi ağacı

Dikilmekte umursamadan zamanı

Uzatmış dört yana dallarını

Meydan okurcasına hayata

Çam kokuyor mağrur selvi ağacı

Anlamıyor, tek tük istasyon sakini

Nasıl olup da çam kokusu yaydığını

Kimi mucize diyor kimi rastlantı

İradesine hakim oysa

Çam kokarken selvi ağacı

Bu onda, daha fidanlıktan gelme 

Bir yeti, öğrenmiş nice yolcudan

Olmadığı gibi, görünmeyi.', 'Geçmişi kalabalık Şimdisi ıssız bir  Tren istasyonu kenarında Çam kokan bir selvi ağacı Dikilmekte umursamadan zamanı Uzatmış dört yana dall...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cam-kokan-bir-selvi-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş', 'tas-serkan-dogan-k11tf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'taş taş üstüne kalmadı gönül bağımda

biri gurbet türküsü yakar, içimi dağlar

yanaşıp dururken kenarına zamanın

bir garip dava olur ya bizimkisi

kirletir mi gökyüzü denizlerimizi

asker dediğin özgürlük bilmez ki

taş sulardan alır şeklini

kesilmesi akışın ölümü getirir

merkezine gerçeğin aldıkça kendini 

bu senin felaketin demektir

giderken her günkü sevimli yuvana

şansın bir daha dönmeyebilir

taş başlatır bütün savaşları

tartışmaya bir taş ile sona verilir

taş attıkça çağın yangınlarına

taş baş ağrıtır korku saldırır

bağrına taş basman iyi gelir

çok gülen, ağlayan taş kesilir

karşısına geçeni içine alır, yatıştırır

taş yaşıttır bu aldatıcı dünya ile

tadını bir dağlar bilir, bir de ben

yıkık çarşılarda gezinen aşklar

hep taş darbesine uğramıştır

bir taş kalpliden kopup gelen

şaşırıp kalma bu senin hikayen

taştın taş olacaksın kitabımca

bir taşa vurdum bir de sana

seni seviyorum anlasana

taşım, bal yanaklım, tatlım

ela gözlüm, şeker dillim, telaşım', 'taş taş üstüne kalmadı gönül bağımda biri gurbet türküsü yakar, içimi dağlar yanaşıp dururken kenarına zamanın bir garip dava olur ya bizimk...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tas-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanış', 'aldanis-serkan-dogan-mcmzy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aslı sanmışım nasılsa, masalsı çıktı

merakımı çoğaltırım kırık mısralarla

sarmal patikalarda yitik kitaplardan, 

tekdüze manzumeler büzdük dizdik 

kuzuların sessizliğinde gezen bizdik

Azrail oldum dağlar aştım ruh aldım

kah kaf dağı zirvesinde ufka baktım

tarihi gerekçeler ileri sürdüm kaçtım

aldatamaz yarı politik Noel süsleri, 

bizzat kader sahibinin el yazısı kazılı alnımda

kısarken sıkıntım bağlarımı yüreğim ağlar

bir biblo gibi parçalanışımdan beridir belki

yastadır masal anlatan bir nine şefkati

ve avutan, olanca dingin uzayıyla

yol veren köprü kuran dizginleyen

zamanı gelince gem vurup tetikleyen

gevşek fugu balığı jölesi iliklerimde 

tedirgin Şili gerillaları yanında öfkeliyim

vatan borcunu öderken yaptığımızdan

korkarak yurt-sevgisi kitaplarını okurduk

ne çok kötü anı bırakmıştık geride

savaşım bitti şimdi beklemedeyim 

yaşamanın tam da en tatlı yerinde

suçlar arasına sevgimizi dokuduk.', 'aslı sanmışım nasılsa, masalsı çıktı merakımı çoğaltırım kırık mısralarla sarmal patikalarda yitik kitaplardan,  tekdüze manzumeler büzdük d...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aldanis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki-lem', 'i-ki-lem-serkan-dogan-51oe0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'erikler tomurcuk verir

terör aynı terör yamaçlarımda

bahar gelir kuşlar öter

ter ve kan karışır şakaklarımda

kuzular meleşir güller açar

çaresiz insanlar ölür şafaklarımda

kadınlar bir başka güzeldir

dizili yan yana cesetler ay ışığımda 

gökyüzünü kaplar bir ebemkuşağı

karanlık gelecek oturur durur karşımda', 'erikler tomurcuk verir terör aynı terör yamaçlarımda bahar gelir kuşlar öter ter ve kan karışır şakaklarımda kuzular meleşir güller açar çar...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iki-lem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlaşan Sevgi', 'taslasan-sevgi-ali-osman-yilmaz-dtriy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ömür baktım sana hiç gözyaşın yok 

Bende bilirim sen  ağlayamazsın ki

Katı yüreğinle kimseleri sevemedin 

Taşlaşan  kalbin bak yosun tutmuş 

Sulamış gökler gözyaşlarıyla bedenini

Yinede yumuşatamamış taş kalbini

Sevmek haram aşık olmak günah

Bana gelince yalnız gurbet iller mübah

ilinden yarime koşturur beni sevdası

Tarihten bu güne nice çağları aşar

Tahir’in, kamber’in, Del’osman’ın sevdası', 'Bir ömür baktım sana hiç gözyaşın yok  Bende bilirim sen  ağlayamazsın ki Katı yüreğinle kimseleri sevemedin  Taşlaşan  kalbin bak yosun tut...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/taslasan-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamane', 'zamane-serkan-dogan-tqrr3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aşkın tedavülden kaldırıldığı

bir son dakika gelişmesi gibiydin

şahane zamanlarda yaşayabilen

ve ana haber bültenlerinde seslendirilen

fütürüstik, ucuz bir caz resitali

çalınırken bile dilek-şart eki koşullarında

depremli sabahlara uyanan.

o zamanlarda fantastik cinayetler tutulur

güncel köprü intiharlar ise pek yavandır

hem sen nereden bilebilirdin

bu kadar yakışıklı çıktığını

ölülerde çektirdiğin resimlerde

ayağını bastığın yerde pusula durdu

işleyecek yön bulamadı belki

diyerek bitti şiir

(Yedi İklim 132/15)', 'aşkın tedavülden kaldırıldığı bir son dakika gelişmesi gibiydin şahane zamanlarda yaşayabilen ve ana haber bültenlerinde seslendirilen fütür...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zamane-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-serkan-dogan-50xfk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'mevsim baharsa

her tekrarı usandırır peri masalının

aşkının doğası bulanır

eğer kışı eksik olmayan tahtında

güzü yaşamışsa sultanı bir kere

vezir libasıyla nasıl salınır

mevsim baharsa

buzdan soğuk, baldan tatlı

kevser akar yavuz erlerin kılıcına

ve gökler iki taze erguvana yazılır

yaşam ki çırılçıplak bir yalnızlıktı

ya da odama kaçan o unutulası ayrıntı

kelimelerde didiklenmedik bir şey kalır

mevsim baharsa

eşkiyalar yakayı ele verir canlı dallarda 

ölümü özlemek bile kesik bir cümleyi anlatır

kayıp şiirlerin anatomisi

gücünün yetişemediği uykusundan uyanırsa

(Yedi İklim,113/10)', 'mevsim baharsa her tekrarı usandırır peri masalının aşkının doğası bulanır eğer kışı eksik olmayan tahtında güzü yaşamışsa sultanı bir kere ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bahar-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seksek', 'seksek-serkan-dogan-bs4n3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şakaklarıma saplı hür hançer yaraları her dem

milâdını çiziyor üşüten ağlama nöbetlerinin

nasılsa uzun bir imge gibi karamsar yanaklarında suskun

gezinen öpüşlerime dur diyen dervişlerin inadı

ısmarladıkları sağılan, damıtılan yedek yüreklerinin kini

ihtimali bile lanet getiren felaket şarkıları

ırmağın ortasında şimşir kafatasları ya da uysal işkenceler

çiçeklerini devşirenlerin iskeletleri, bal des pendus

..

sokakları ucuz zevkli kadınlar birikmiş şehir

bilincimizin her bilenişinde terkedilen dehşetince

üçüncü şahısların yosma alışkanlıklarıyla döllenir

şubat güneşinde gevşeyen iğrenç nefesi şehvetin

intikam kamaları sırayla inerken nehrin kıyısına

narına koşan tilmizlerini emziren yas soluklu ensesinde 

devinen seksek tekerine takılan boşluklarında zamanın

karaya vuran darağacı yankılarını duyarsan sus

(Yedi İklim,113/10)', 'şakaklarıma saplı hür hançer yaraları her dem milâdını çiziyor üşüten ağlama nöbetlerinin nasılsa uzun bir imge gibi karamsar yanaklarında s...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seksek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük Yadigâr', 'en-buyuk-yadig-r-aydan-alim-wgxvl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret ayak izlerine takıldı kaldı.

Şu acımasız dünya da

Lüzumsuz bir kelime gibidir

Benim sevdam.

Acıları derdest edip, adımlarına bağladım.

Görsem bazı- bazı 

Lûtfun olur, 

Acılarda gizlenen 

O tatlı an.

An be an

Saniyelerde yaşana

Hazlardan, 

Kalmadı elimde yedeğim.

Tükettim

Izdırabımdan.

Bakmak istemem yollarına.

Bilirim

Gelmeyeceksin

Artık bir daha

Kendi yenilmez

Korkularından.

Gitgide dayanılmaz hale gelince acılar, 

Dayanılmaz olacak, 

Duyulan gerilla vuruşlu kahkahalar.

Yer bulunmaz bana bu âlemde, 

Neyleyim? 

Ak kefen kısa, 

Soğuk çukur mezar, 

Bana dar...

Izdırabım sığmasa da dünyalara, 

Bir bakışından aldığım hazdır, 

Yaşamdan bana kalan

O en büyük yadigâr...', 'Hasret ayak izlerine takıldı kaldı. Şu acımasız dünya da Lüzumsuz bir kelime gibidir Benim sevdam. Acıları derdest edip, adımlarına bağladım...', ARRAY['Türk Edebiyatı','Şiir','Aydan Alim']::text[], 8.5, '{"poet":"Aydan Alim","poet_slug":"aydan-alim","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/en-buyuk-yadigar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-serkan-dogan-xap3n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni ben enis diye sîneme çekmiştim

vicdan buz tutmuş seylâb idi, eridi

gönlümün gülü soldu

soyundum ve tutundum kıyısına suyun

Bî-sütunlar da seddeyleyemedi tenimin dalgalanmasına

atlastan cânıma karalar bağladım, kalbimi dağladım

kayıtsız bir kasırga boyu ağladım

özlemini çektiğim şen şelalelerdi

şeydalığımın delili beklerim bezmin

ve izinsiz gezdiğim bir meclisin

serzeniş ve sitemden edinilen ikizini

..

âh, külüngüm sîneme indi

vücûdu cefâdan ibaret sevgilime kavuşmadan

elifler ucuna asılı salındığım

Mûsikâr mahlaslı senelik kuşun

kanatlarındaki küllere karıştım

(Yedi İklim,130/27)', 'seni ben enis diye sîneme çekmiştim vicdan buz tutmuş seylâb idi, eridi gönlümün gülü soldu soyundum ve tutundum kıyısına suyun Bî-sütunlar ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buzdan düğün', 'buzdan-dugun-serkan-dogan-vebq7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'buzdan düğünümde ezberimi unuttum mısra

kuşattı ve ısırdı direnemeyen belleğimi

baktım ki sahne bomboş, senaryo yarım kalmış

seyrimin kulisinde piyesimi okudum içten içe

cılız mı cılız cânıma yağmur yağmakta talan

ânında yalan söylemek ötekinin işi

kalemin ucundaki şeyin kâğıda değişi

değiştirsin seksek oynayan kekeme tekerlemeyi

ve ısıtsın donakalan yârsız duvağımı

yalvarmamı beklemesin de duâmı işitsin

doğdum, kızıl balçıktan, gün doğdu

kuru kemikler vâdisindeki ilginç levha

cennet cehennem ve arası yazın

eşiyle karşılaştım kaçınılmazdı seçimim

yetim beyit tekti yitti ıssızlık

mısra iste kara noktadır esin

alçak değildi uçurum, uçtum, gün soldu

(Yedi İklim,102/11)', 'buzdan düğünümde ezberimi unuttum mısra kuşattı ve ısırdı direnemeyen belleğimi baktım ki sahne bomboş, senaryo yarım kalmış seyrimin kulisi...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/buzdan-dugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tılsım', 'tilsim-serkan-dogan-17shg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'halhalları koparsam tılsım bozulur mu

öyleyse size bahar ülkesinde eşlik edeyim

çıkrığı çekip çıkarsam ipsiz kuyunuzdan

ayrılmamak için bencil koynunuzdan

seramik sazlara ud duruşu yakışır

bu bir mahşer faslı, uyanın

bir dem olsun benim de adımı anın

ben şımarık hızımla nereye koşuyorum

tâcınızın hükmü sınırlarımı aşıyor

size lâyık değilim, biliyorum, ama

bana sizdeki hazdan bir yansıma lâzım

yapay ışığı gezinir izinizde avizelerin

dolunaylar su taşır, evvelce kalbim yatışır nedense

ertesinde derinden içime sızan o sinsi doyum

her yudumda binlerce kez ölüyorum

korkuma yetişmenin aşkıyla, bir bilseniz

ne hâlde hangi yolda yürüyorum

(Yedi İklim,101/19)', 'halhalları koparsam tılsım bozulur mu öyleyse size bahar ülkesinde eşlik edeyim çıkrığı çekip çıkarsam ipsiz kuyunuzdan ayrılmamak için benc...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tilsim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-zeynep-ser-72px3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her aynaya bakışımda

Ve her kendimi arayışımda, 

Seni bulacağım.

Görmeyecekler ve duymayacaklar

Her kalbime baktıklarında

Seni yansıtacağım.

Bir seviyi anlamak

Bir yaşam harcamaktır

Anlatacağım.

Seni hep yaşatacağım

Ağlayacağım gözlerinde

Ve her karşıma çıkışında

Sana yeniden başlayacağım.', 'Her aynaya bakışımda Ve her kendimi arayışımda,  Seni bulacağım. Görmeyecekler ve duymayacaklar Her kalbime baktıklarında Seni yansıtacağım....', ARRAY['Türk Edebiyatı','Şiir','Zeynep Ser']::text[], 8.5, '{"poet":"Zeynep Ser","poet_slug":"zeynep-ser","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-ve-ben-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazo', 'vazo-serkan-dogan-s4djm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'vazosundan düşmüş çiçek

uzağına serili bir yığın palmiye yaprağı

delice çağırır onu kendi duvağına

en tepede güneş

Basilikos soksun seni, lanetlendi gözkapakların

sunağın son yudumunu sunduğu an

o, benim yıldırımımdı

atılmamış bir adım

gibi boşlukta devingen ve yarımdı

sen öteki âleme ait olamazsın

sanrılarınla aranda daralan alanı da saramazsın

hani öğle mahmurluğundaki gözlerinde şaşkın mumlar

sorulanı yorumlamak oyalayıcı ve yasak

yazgının yalnız şarkılarıyla saksına uçuşsak

zeminde yığılı ve hayli yaralısın

sen gel de devrin seyrine bir sığın

âh, saydamdır kalbin, şimdi ürkek ve kuytu

kelimelerin derinlemesine kutsanışı ilişmiş omzuna

Vade retro, Satana! 

vazona geri dön, yuvana

(Yedi İklim,137/40)', 'vazosundan düşmüş çiçek uzağına serili bir yığın palmiye yaprağı delice çağırır onu kendi duvağına en tepede güneş Basilikos soksun seni, la...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vazo-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-serkan-dogan-o9xc4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hüzünleri bana bırakın

vefâsızlığımı bana 

satırlar arasına sıkışan

taşları delip geçişimi

sahrada su diye inleyişimi

cinnetlerimi bana bırakın

uyanıkken ağına düştüğüm

fena düşlerimi

ve hayallerimi 

bana bırakın

susuşlarımı 

ya da bir mektuba iç açışlarımı

ıssızlığımı bana bırakın

sıra dağlarımı bana

yıkıntıların ardına kurulan şehirlerin

uçurumları arasına astığım 

sancağımı kurutan

yazlara veda

(Yedi İklim,114/16)', 'hüzünleri bana bırakın vefâsızlığımı bana  satırlar arasına sıkışan taşları delip geçişimi sahrada su diye inleyişimi cinnetlerimi bana bıra...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/veda-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncilin esintileri', 'i-ncilin-esintileri-serkan-dogan-z28od', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'alfa ve omega

sekran olmuşum yedi kilisenin iksiriyle

eliyle sunduğu şaraptır etini ıslatan

işaretler ertesinde anlatır ihanetleri

Fırat’ ı kan kokutan cinayetleri

göğe asılı yaslı muştudur o çanlar

eseri silinmiş bir sele inciler saçanlar

Efes’ e sorsak esefler esinlenir nefesinden

“ne gelir elden, başlanmaz yeniden”

okudu mu Tanrı’nın ‘sevgi’ olduğunu Yuhannâ

kutsanmış bir kuzu’dur boğazlanan o âna

(Yedi İklim,91/27)', 'alfa ve omega sekran olmuşum yedi kilisenin iksiriyle eliyle sunduğu şaraptır etini ıslatan işaretler ertesinde anlatır ihanetleri Fırat’ ı ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/incilin-esintileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çift', 'cift-serkan-dogan-eh8bj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'keşişler çiçektir

iki kalpli nehrimde

ya da bir derviş elinin

suya banmış girdaba dönmüş

sağanak vezinli şarkısı

hangi gün göğe gelse ulak

kerpiç masa, gölge sürgün

kaftanı giymek izin ister – perçin

elçi geçit ve geçti çile

fazla lafza kulak asma

‘oku’mayı açmassan çanı asma

ve sayfaya şaşma

volkan külleriyle ölgün parıltı

ömür kısa geçer

	zamanın gecesi uzun

artık beni unuttun

Allah benden çok daha güzeldir

(Yedi İklim,96/24)', 'keşişler çiçektir iki kalpli nehrimde ya da bir derviş elinin suya banmış girdaba dönmüş sağanak vezinli şarkısı hangi gün göğe gelse ulak k...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cift-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çevrilir (Hak Yarattı)', 'cevrilir-hak-yaratti-pir-sultan-abdal-ty2yq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hak yarattı Muhammet''i nurundan

İnsan olan gelir nura çevrilir

Çark kurulmuş dolap daim dönmede

Mansur olan gelir dara çevrilir

Bir sürçmede at ayağı kesilmez

Bir suç ile ademoğlu asılmaz

Erenler bir yol kurmuştur basılmaz

Yol ehli kaniyse yola çevrilir

Gümanlı gönülde pir mi eğlenir

Cennet taşrasında hur mu eğlenir

Balsız petekte arı mı eğlenir

Arı kane ise bala çevrilir

Erenler evinde kem söz söylenmez

Cennet derununda huri gizlenmez

Balsız peteksiz arı eğlenmez

Arı olanda bahara çevrilir

Başlı sular daim alçağa akar

Pervane kendini odlara yakar

Serçe kane ise aslına çeker

Bülbül olan gelir güle çevrilir

Pir Sultan Abdal''ım yatar hastadır

Elinde gülleri deste destedir

İnsanoğlu bir acayip nesnedir

Muhabbetle tatlı dile çevrilir', 'Hak yarattı Muhammet''i nurundan İnsan olan gelir nura çevrilir Çark kurulmuş dolap daim dönmede Mansur olan gelir dara çevrilir Bir sürçmede...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cevrilir-hak-yaratti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoktan Beri Yollarını Gözlerim 1', 'coktan-beri-yollarini-gozlerim-1-pir-sultan-abdal-ngtw4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çoktan beri yollarını gözlerim

Hatırım sormaya yar sen mi geldin

Gönlümün yemişi bağı bostanı

Ayva ile turunç nar sen mi geldin

Gelip şu yanımda oturan mısın

Serimi sevdaya yetiren misin

Ağır yüklerimi götüren misin

Katar maya ile dür sen mi geldin

Yüzünde benlerin hindidir hindi

Bilmem melek midir arştan mı indi

Bir su ver içeyim yüreğim yandı

Ağustos ayında kar sen mi geldin

Bülbüller ötüyor hüsnün bağında

İntizarım kaldı göğsün ağında

Elim kelepçede cellat önünde

Derdimin dermanı car sen mi geldin

Ol nesl-i Adem''in belinden misin

Gülşen bahçesinin gülünden misin

Firdevs-i Ala''nın ilinden misin

Cennet-i Ala''dan hur sen mi geldin

Pir Sultan Abdal''ım sen seni döşür

Yarin sevdaları sere ulaşır

Türlü libasları giyer kuşanır

Çarşılar bezenmiş al sen mi geldin', 'Çoktan beri yollarını gözlerim Hatırım sormaya yar sen mi geldin Gönlümün yemişi bağı bostanı Ayva ile turunç nar sen mi geldin Gelip şu yan...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/coktan-beri-yollarini-gozlerim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldin Albayım.', 'hos-geldin-albayim-mine-ozdemirtas-22zu4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Havada; keskin bir çam kokusu var.

İğne yapraklı. Batan, kanatan cinsten.

Bu senin sevdan. Bu sensin.

Sen kokuyor her yer. Tıpkı sen.

Hasretine gebe olduğumu biliyorsun.

Yokluğuna kararan gecelerden.

Çok mu şaşırırdın? Kavuşmaları doğuruversem? 

Sen çok uzaklardasın. Bense çok çaresiz.

Elinde ceketin; 

Eskilerin yanına; yeni bir yıldız dikerken, 

İsim değiştirmede gölgen.

Hüzünlü ve sessizsin. Üstelikte; bensiz. 

Ne yazık, 

Ne yazık ki seni bir daha hiç görmeyeceğim Yarbayım.

Çok istesem de, Bir daha asla göremeyeceğim.

Bir gün, sen, çıkıp geldiğinde uzaklardan; 

Ben yeni bir sen''i  kucaklayacağım, 

''Hoşgeldin Albayım''...... derken

İçimde hem kıvanç olacak, hem de sitem.

Bu öksüz duygu isimsiz kalmamalı.

Biz onun adını  şimdiden; 

“Burukluk” koyalım bir tanem.

Sen, farkında mısın? Bilmem.

Ben. / O kadar çok isterdim ki

Değişirken Rütben, 

Seni ilk kutlayan ben olayım.

Ve seni ilk öpen Ben.

Utanma. /  Dudaklarından değil asker.

Sadece gözlerinden. Sadece gözlerinden.

30 ağustos/ Çamlıca', 'Havada; keskin bir çam kokusu var. İğne yapraklı. Batan, kanatan cinsten. Bu senin sevdan. Bu sensin. Sen kokuyor her yer. Tıpkı sen. Hasret...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hos-geldin-albayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir zamanlama anı', 'bir-zamanlama-ani-ahmet-kose-6c14m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '...evliliğe 2 gün kala..

Akrebine yelkovanına dokunulan bir saat gibiyim.

tozlu, paslı

kirli, yağsız

ama çalışan.

Kuruyorum kendimi şimdi

yağlıyorum şimdi

arınıyorum tozlarımdan.

Zaman  bildiğimiz zaman değil

bizim zamanımız başka vakit

Çocukluk, evcilik

gençlik, özgürlük

olgunlık, yiğitlik

dostluk, birlik.

Dostluğum

birliğim benim

zamanımız bizim

anları saniyeleri

kurulduk zamanımıza

tik-tak, tak-tik

sen akrep 

ben yelkovan

zaman bizim

tik-tak

yüreğimiz önümüzde.

22/12/94/bodrum', '...evliliğe 2 gün kala.. Akrebine yelkovanına dokunulan bir saat gibiyim. tozlu, paslı kirli, yağsız ama çalışan. Kuruyorum kendimi şimdi ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-zamanlama-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-diyarbakirli-mehmet-sdt7l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidiyorum iste buralardan 

Insallah mutlu olursun 

Belki bensiz huzuru bulursun 

Dilerimki allahtan her sey gönlünce olsun 

Birakalim bu sevda burada bitsin 

Kavusamadik seninle kara gözlüm neylersin 

Sol tarafimdaki adinin bas harfiyle 

Ve kulaklarimdaki gülüsünle

Gidecegim be kara gözlüm bu divardan 

Bilki bir baskasi olmayacak 

Tabiki vede sen 

Sende olmayacaksin 

Nezaman olabildinki yanimda 

Simdi ve bundan sonra olasin 

Gidiyorum iste buralardan 

Üstündeki kara bulutlari alip üzerinden 

Dindirip akan yaslari gözlerinden 

Söndürüp sevda atesini yüreginden 

Telefondaki sesimi

Seni seviyorum deyisimi

Sana sadece yasadigimiz seyleri 

Birakipta gidecegim kara gözlüm', 'Gidiyorum iste buralardan  Insallah mutlu olursun  Belki bensiz huzuru bulursun  Dilerimki allahtan her sey gönlünce olsun  Birakalim bu sev...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakirli Mehmet']::text[], 8.5, '{"poet":"Diyarbakirli Mehmet","poet_slug":"diyarbakirli-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gidiyorum-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ya Hep ya Hiç', 'ya-hep-ya-hic-gunay-aktag-90qke', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ya hiç görmeseydim seni

Ya da gitmeseydin benden.

/serseri! ...', 'Ya hiç görmeseydim seni Ya da gitmeseydin benden. /serseri! ......', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ya-hep-ya-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkına Yandığım', 'askina-yandigim-hikmet-karakus-4wpju', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkına yandığım, 

Uğruna acı çektiğim, 

Ayrılıklara düştüğüm 

                             sevdam, 

Fırtınalar arasında tutkumsun

              vazgeçemediğim, 

Uzaklara düşsem de

              rüzgarlara tutunup

              yine sana geleceğim.

(Ank.1999)', 'Aşkına yandığım,  Uğruna acı çektiğim,  Ayrılıklara düştüğüm                               sevdam,  Fırtınalar arasında tutkumsun           ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/askina-yandigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-refik-yildiz-4ebbi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerdesin ey sevginin ikliminde şavkıyan

Tut ki, güneşini arayan ay dım dün gece

Hasretle yanmış gönül suya kanmaz dediler

En duru pınarlarla geldin sandım dün gece

Biz hiç yazı görmedik kışta doğdun dediler

Nevbaharla geleni sensin sandım dün gece

Bu bahçeler onundur bazen uğrar dediler

Bir gülün kokusunda seni duydum dün gece

Dallarda tomurcuklar ufukta bulutlar var

Efendim Sultanım çok yalvardım dün gece

Tam çiçekler açıyorken başaklar bağlanmışken

Titredim efendim seni andım dün gece

Arzın yüreğine dön ve halini arzet dediler

Diz çöktüm boyun büktüm avuç açtım dün gece

Onun geçtiği sokaklar miskler saçar dediler

Ötelerden kokularla geldin sandım dün gece

Biz devrin yetimiyiz yok derler sahibiniz

Sahibim efendim sensin sandım dün gece

Bir muzdarip kalbe akan yaşa gelir dediler

Ellerinle elimi tuttun sandım dün gece', 'Nerdesin ey sevginin ikliminde şavkıyan Tut ki, güneşini arayan ay dım dün gece Hasretle yanmış gönül suya kanmaz dediler En duru pınarlarla...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dun-gece-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dallarında Çiçek Açacağım', 'dallarinda-cicek-acacagim-muammer-celik-mi4ub', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ağaç da ben dikeceğim

salacak köklerini

ezelden ebede... 

İncirler, erikler, 

çağlalar toplayacağım

sahibine inat, 

bahcivanina inat... 

Bir ağaç da ben dikeceğim 

yemyeşil dallarına

tutunacağım...

fırtına ve yağmurda 

altında kıvrılacağım... 

Yuvamı yaprakların arasına kurup 

aşkın kuluçkasına yatacağım 

taşacak tüylerim saçak saçak... 

ve olursa yavrularımız

birer birer yuvamızdan uçacak... 

Ağaçta tutsak kalacağım 

her baharda sana

yine çiçekler açacağım… 

21.05.2003

BirDeli', 'Bir ağaç da ben dikeceğim salacak köklerini ezelden ebede...  İncirler, erikler,  çağlalar toplayacağım sahibine inat,  bahcivanina inat... ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dallarinda-cicek-acacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çal Çalabilirsen', 'cal-calabilirsen-muammer-celik-kzge3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözleri bebeğinden 

bebeği gözlerinden kara 

gönlü yüreğinden 

yüreği gönlünden yara 

seç hadi seçebilirsen… 

Gül dikenlerinden 

diken güllerinden biçare 

bülbül çığlığından 

nida bülbülden ahuzare 

ayır hadi ayırabilirsen… 

Can bedenden 

beden candan tutar 

et tırnaktan 

tırnak kemikten tutar 

kopar hadi koparabilirsen... 

Ruh yürekten 

yürek ruhtan çıkar 

ciğer nefesten 

Nefes NEY’den çıkar 

çal hadi çalabilirsen… 

Saçları geceden 

gece saçlarından siyah 

güneş yıldızlardan 

yıldızlar mehtaptan mübah 

bil hadi bilebilirsen… 

Ben kendimden 

Kendim benden haklı 

dışım içimde 

içim bende saklı 

Bul  Hadi Bulabilirsen... 

19.05.2003

BirDeli', 'Gözleri bebeğinden  bebeği gözlerinden kara  gönlü yüreğinden  yüreği gönlünden yara  seç hadi seçebilirsen…  Gül dikenlerinden  diken gülle...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cal-calabilirsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Bir Zümrüt', 'kara-bir-zumrut-ahmet-ozturk-zdqf7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kara bir zümrüt elimi yakan

Işıldıyor bir dirhem denize düşüyorum

İstanbul’un sarıp sarmaladığı bir kutuda 

Açıp kıyamıyorum 

öylece uzaklara salınıveriyor kutusuyla beraber

ama ağladığımla kalıyorum

bir de elime alıp da elimi yakamadığıyla

(2003 Temmuz) 

(Florya) 

(Bulgaristan Dönüşü)', 'Kara bir zümrüt elimi yakan Işıldıyor bir dirhem denize düşüyorum İstanbul’un sarıp sarmaladığı bir kutuda  Açıp kıyamıyorum  öylece uzaklar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kara-bir-zumrut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrımlar', 'ayrimlar-ahmet-ozturk-3qcpa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Değil misiniz sonsuzluğun çocukları tek dişini kırıp da 

Beni yolumdan çeviren

Hepinizi tek tek ataşlarla ayırıyorum artık

Sırtımı hissetmeden göğüs geriyorum 

Ne cesaret ama elimde böbreklerimle 

çitlerle bölünmüş bozkırlarda

Ve ayrışan kıvırcık taze koyunlar

Silahlar beyaz göğüslerinde mi kadınların

Ne acıklı az önce bir mermiyi vurmuşlar sokakta

	

Piyanonun tuşlarındaki kan sizin miydi

Tuhaf...? 

O şarkı ne de yakışıyordu düşlerimize

(02 Ekim 2003 Perşembe) 

(Akatlar)', 'Değil misiniz sonsuzluğun çocukları tek dişini kırıp da  Beni yolumdan çeviren Hepinizi tek tek ataşlarla ayırıyorum artık Sırtımı hissetmed...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayrimlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecek Senin Olsun', 'gelecek-senin-olsun-muammer-celik-db02b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tarih kadar eski

gün kadar tazeydi

sevdam 

doğadaki renklerden de canlı 

doğacak bebek kadar da beklenirdi 

Çınar kadar heybetli

filiz kadar tazeydi

sevdam 

açmış çiçeklerden de renkli 

açmamış güller kadar da beklenirdi 

İnanç kadar kutsal 

iman kadar tazeydi 

sevdam

yaşanmış masallardan da güzel 

yaşanmamış kadar da beklenirdi 

Zemzem kadar temiz 

meltem gibi serindi

sevdam 

doğan güneşten de parlak 

gün görmemiş kadar da beklenirdi 

Doğmadan öldü 

sevdam

sizlere ömür 

yaşamadan yaşlandı 

gençlere uzun ömür 

Gelecek sana kalsın yavrum 

Ben gelmeden geri gidiyorum…! 

18.05.2003

BirDeli', 'Tarih kadar eski gün kadar tazeydi sevdam  doğadaki renklerden de canlı  doğacak bebek kadar da beklenirdi  Çınar kadar heybetli filiz kadar...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gelecek-senin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saygı', 'saygi-necmettin-karaman-bkjr3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'güneş 

gündüz 

ay 

gece 

parlıyor

sabahlar aksam

akşamlar sabah oluyor 

dünya dönüyor 

kimin umurunda 

sevgi pul olmuş 

yapışmış zarflara 

gideceği yer belli 

postacıyı bekliyor 

saygı ise olmus bozuk para 

ağırlık yapıyor 

cebim yine delindi 

düşer mi ayağa

Necmettin Karaman

12 Eylül 2003 Cuma 14:18 - İstanbul', 'güneş  gündüz  ay  gece  parlıyor sabahlar aksam akşamlar sabah oluyor  dünya dönüyor  kimin umurunda  sevgi pul olmuş  yapışmış zarflara  g...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Karaman']::text[], 8.5, '{"poet":"Necmettin Karaman","poet_slug":"necmettin-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/saygi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmaki gelmeyecek senden iyisi', 'sanmaki-gelmeyecek-senden-iyisi-mustafa-i-lhan-guldemir-kh6ih', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanmaki gelmeyecek senden iyisi

Bu alem harcadı ne güzelleri

Ben ne güzeller gördüm

Taptıklarım benimle üç gün yaşadı

Sanmaki tapmadım yenilerine

Sanmaki sende bu gençlik

Bende bu inat bitmeyecek

Bitince gençliğin ruhun solacak

Geçince inadım senden vazgeçeceğim

Sanmaki o zaman kıyamet kopacak

Sanmaki hayalinle yaşamayacağım

Sevdiklerimin en çirkini sen olsanda

Seni hep ilah olarak anlatacağım

Sana başkası tapmasın diye

Sanmaki seni kötüleyeceğim

Sanmaki gözden düşeceksin

Her zaman yüceliğini anlatıp

Yanlışlarını hiç unutmayacağım

Maddiyata her kezi satar diyeceğim

Sanmaki üç kuruşa harcandığımı unutacağım

Sanmaki dünyada teksin

Bana göre her zaman özelsin

Lakin sen çirkin güzelsin

Biliyorum hiç sevmedin, sevenide bilmedin

Sanmaki seni bir daha sevmeyeceğim

Sanmaki dünyaya garip hislerle geldin 

Bilki bu hislerle yaşamayacaksın

Bir gün dişiliğini hissedecek 

Kendini yanlış tanıdığını anlayacaksın

Belki o zaman gerçek dişi olcaksın

Sanmaki o gün seni daha çok isteyeceğim...', 'Sanmaki gelmeyecek senden iyisi Bu alem harcadı ne güzelleri Ben ne güzeller gördüm Taptıklarım benimle üç gün yaşadı Sanmaki tapmadım yenil...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan Güldemir']::text[], 8.5, '{"poet":"Mustafa İlhan Güldemir","poet_slug":"mustafa-i-lhan-guldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sanmaki-gelmeyecek-senden-iyisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay', 'ay-tuncay-ulak-k7krs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen parıldamasını düşünüp güneşin, 

Büyüklüğünü anladın güneş olmayı seçtin, 

Gün oldun, günleri gün ettin.

Sevildin, 

Çünkü insanlar senle aydınlandılar.

Seni hep yüreği çocuklar gibi cıvıl cıvıl olanlar bekledi

Bir an önce geceyi öldürüp sabaha doğman için, 

.

Ve o insanlarla arkadaş oldun. 

Yani sen güneş oldun…

Bense bir ay oldum sevda evreninde. 

Aslında güneşin tutsaklığında cılız bir parıltıydı ay. 

Aldandım  gecenin zifirinde görünce,.

Devleştirdim fikir büyütecimde, 

Ay oldum, güneşe bağlandım.

Yalnız gecelere merhaba dedim, sevilmedim.

Senin ışıkların altında günboyu kahırlanan, 

Takatları kalmamış geceyi düşünen, 

İhtiyar ruhlu insanlar bekledi beni.

Işıkların yormuş onları, beni görüp uyudular.

Anlayacağın sen güneşsin, ben ayım. 

Ben senden ışık alırım, sana bağımlıyım, sensiz olamam

Sende benle olamazsın. 

Öyle ya; ne zaman gündüz kucağında ay gördük ki? 

Sen binlerce cıvıl cıvıl çocuğun, yüreği zengin anası, 

Ben gecelerin fakir yetimiyim.

Dedim ya; sen güneşsin ben ayım, 

Benzer ama ayrı, 

Varsın gündüzler senin olsun, 

Karanlıkları ben alayım, 

Ben zaten sevdanın yetimi, 

Ben zaten gecelerin adamıyım.', 'Sen parıldamasını düşünüp güneşin,  Büyüklüğünü anladın güneş olmayı seçtin,  Gün oldun, günleri gün ettin. Sevildin,  Çünkü insanlar senle ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Ulak']::text[], 8.5, '{"poet":"Tuncay Ulak","poet_slug":"tuncay-ulak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ay-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Gözlük', 'eski-gozluk-tuncay-ulak-q7nqp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülüşümde masumluk, 

Tavrımda saçmalık bul, 

Ağlayışım çocuksu olsun

Farklı gözle bakma bana.

Aşkı bilmeyenlerden olayım, 

Hani o eskisi gibi, 

Sadece oyun olsun bildiğim.

O son gördüğün halimle bil, 

Farzet ki yıllara direnmişim.

Ben gelmiyorum, 

Sizler gidin demişim.

Eski gözlüklerini tak, 

Bakışların maziden gelsin, 

Benim gibi sende değişme

Farklı gözle bakma

Bir aynaya bir de bana', 'Gülüşümde masumluk,  Tavrımda saçmalık bul,  Ağlayışım çocuksu olsun Farklı gözle bakma bana. Aşkı bilmeyenlerden olayım,  Hani o eskisi gib...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Ulak']::text[], 8.5, '{"poet":"Tuncay Ulak","poet_slug":"tuncay-ulak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eski-gozluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-tuncay-ulak-bs886', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karşıdan gelirken yüzüme karşı, 

Gözünün diliyle dostum deyiver, 

Yanağa düşmeden gözümün yaşı, 

Pembe bir mendille gelip siliver.

Amacımdan uzak dar yerlerdeyken, 

Gurbetin adında bir seferdeyken, 

İçimdeki ağıt pır pır ederken, 

Yüreğimi elinle gel kapayıver.', 'Karşıdan gelirken yüzüme karşı,  Gözünün diliyle dostum deyiver,  Yanağa düşmeden gözümün yaşı,  Pembe bir mendille gelip siliver. Amacımdan...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Ulak']::text[], 8.5, '{"poet":"Tuncay Ulak","poet_slug":"tuncay-ulak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellere Verdin', 'ellere-verdin-hakki-hakan-kaya-ds92h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerinde büyüttüğün aşkımızı, 

Ellerinle ellere verdin, 

Eller sordu sen söyledin, 

Dillerinle dillere verdin.', 'Ellerinde büyüttüğün aşkımızı,  Ellerinle ellere verdin,  Eller sordu sen söyledin,  Dillerinle dillere verdin....', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ellere-verdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde akşam orda sabah', 'nerde-aksam-orda-sabah-nalan-kazazoglu-1as4f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerimi aldı

Çarptım kuyruklu yıldıza

Yüreğimin ipiyle indim

Gezinen çoban yıldızına

Çağırdım geldi dolunay

Gözlerini yumdu aynalar

Dolunayı masallarla uyuttum

Bir bulutu yakama tutturdum.

Kondu sevinç kirpiğimin yanına

Denizler sürekli ses verir kulağıma

Saldım kuşları dünyanın paslı sırtına.

Sevincim ipin ucunu kaçırdı

Topsuz tüfeksiz çıkartma yaptı

Kanıma işlemiş şiir

Yine dilime dolandı..

Uzandım gecenin üstüne

Her yanım parlak yıldız ormanı

Koştu geldi bir şarkı

Nerde akşam orda sabaha

Bir çeyrek uzattım hayatı....', 'Gözlerimi aldı Çarptım kuyruklu yıldıza Yüreğimin ipiyle indim Gezinen çoban yıldızına Çağırdım geldi dolunay Gözlerini yumdu aynalar Doluna...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nerde-aksam-orda-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Senmisin', 'ask-senmisin-cahit-i-pekoglu-p5h0i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey aşk senmisin gelen senmisin

ismini bilmediğim.

Sen misin içimdeki beni doğuran

sen misin bendeki beni kılan.

Ey aşk ismin aşkmıdır yoksa

yoksa varolmayan bir canmısın....

Ey aşk

bazen varolduğun yerde yaşayamayanmısın.

Bazende kalbin başka yerde

ayakların başka yerde yaşayanmısın.

Söyle sen nesin

söyle yoksa varolmayan içimdeki benmisin....

Adını bilmesemde beni bana bırak

adına aşk diiyeyim.

Ey aşk

söyle şimdi neredesin.

Bendemisin eldemisin bilemiyorum

aşk galkiba, ben seni seviyorum.....', 'Ey aşk senmisin gelen senmisin ismini bilmediğim. Sen misin içimdeki beni doğuran sen misin bendeki beni kılan. Ey aşk ismin aşkmıdır yoksa ...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-senmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Seni Dostum', 'ozledim-seni-dostum-tulay-sustam-kgtj2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Candostum Nilgün''e...) 

Hiçbir dostluğa benzemez bizimkisi

Ne çıkar vardır ne de herhangi bir beklenti

Senin bir derdin olsa ben ağlarım

Benim bir derdim olsa sen ağlarsın

Aslında dostluktan da öte ya bizimkisi

Seninle kardeş gibiyiz ikimiz

İstemem hiçbir zaman sen üzülesin

O güzel gözlerin gözyaşı nedir bilmesin

Biliyorum aradığın aşkı bulamadın benim gibi

Belki de bulduk hiç sebepsiz elimizden kaçırdık

Ya da onlar kaybetti bizi

Soranlara ayrı dünyaların insanlarıyız, 

Tenlerimiz uyuşmadı dedik.

Biz bu lafları bilmezdik ama bize de bunlar söylendi.

Ne dostluklar yaşadık birbirimizden habersiz

Ben senden başkasına henüz dost demedim

Benim arkadaşım çok oldu, dostumsa bir tane

Söylemeye gerek yok dostum sensin işte

Ben seninle tattım dostluğu

Gecenin bir vaktinden sabahlara kadar seninle dertleştik.

Sevdamı, yalnızlığımı bir sana anlattım.

Hiçbir şey önemli değildi benim için

Yanımda sen olunca derdimi unuturdum

Unuttururdun bana her şeyi

Kıvırcık saçlı, güzel yüzlü, tatlı dilli dostum

Kendin gibi yüreğin de güzeldir senin

Allah her şeyi o güzel kalbine göre versin

Dostum bir bilsen ne kadar özledim seni

Keşke şimdi yanımda olsan

Dertleşsek yine seninle sabahlara kadar

Telefon defterim bir hayli kabarık isimlerle dolu

Nedense parmaklarım hep senin numaralarını çeviriyor.

Bu karakız bir seninle dertleşmek istiyor.

Neredeysen, kiminleysen hadi çık gel artık

Bu bîçare dostun kucak açmış seni bekliyor

Özledim sohbetini candostum.

Özledim seni dostum.

(02.10.2003 Perşembe 11.00 İstanbul)', '(Candostum Nilgün''e...)  Hiçbir dostluğa benzemez bizimkisi Ne çıkar vardır ne de herhangi bir beklenti Senin bir derdin olsa ben ağlarım Be...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ozledim-seni-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Oktavlık Yaşam', 'kac-oktavlik-yasam-naime-erlacin-po0jd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çocukluğumu bıraktığım

uzak kentte üşüyor kalbim

tanıdık bir ağrı yapışıyor yüreğime…

palmiye topluyorum nehir ışıklarından

renksiz bir cibinlikte hapis yeniyetmeliğim

“tel”i buluyor lunaparkta

üzerinden kayarken 

çıngıraklı kahkahalarla ilkyazları süslediğim

nerelere göç ettiniz açık hava sinemalarım ey! 

gazoz şişelerinden kaçarak 

ve buzlu kovalardan ey gafiller! 

bir hırsız gibi

sizler de beni terk mi ettiniz

yaz bahçelerinde yitirdiğim

boz alacalı salkım sevinçler badem ağacında kaldı

yeşil yapraklarda unutulan

yeşil tırtıllı ebem kuşağı günlerim

yaşam un ufak şimdi eleğinde zamanın

süzgece takılıyor “geçmiş”

asarak masum günleri kalbime yorgun suretinde güzün 

haykırıyor üşüyor titriyorum

hesap ödeniyor! 

ağlıyor hüznüm

soyunun utanmayın çıplaklığınızdan

kaç oktavlık yaşamlar sunuldu her birinize

kaç oktavlık bir yaşam seçerdiniz kendinize! 

(02 Ekim 2003)', 'çocukluğumu bıraktığım uzak kentte üşüyor kalbim tanıdık bir ağrı yapışıyor yüreğime… palmiye topluyorum nehir ışıklarından renksiz bir cibi...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kac-oktavlik-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öksüz Çocuk Bakışlarımızda', 'oksuz-cocuk-bakislarimizda-zeki-ergin-i12ui', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'anaç ve doğurganlığınla

yeniden yeşert

kurumuş dallarımı

sevgi dolu yüreğinle

yeniden doğur beni

sevgi yüklü sesinle

öksüz çocuk bakışlarımızda

yazılmıştır en güzel şiirler

ve içimizdedir

yaşanmamış  günler

_erenköy  2eki03

_sevgiliye isyan yt:haz04', 'anaç ve doğurganlığınla yeniden yeşert kurumuş dallarımı sevgi dolu yüreğinle yeniden doğur beni sevgi yüklü sesinle öksüz çocuk bakışlarımı...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oksuz-cocuk-bakislarimizda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Ve Keder', 'umut-ve-keder-ali-osman-yilmaz-9m9dm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki şekilde üzülür insan

Yitirdiği umutlarının ardından

Ya da ulaşamadığı, hayalleri için

Hani o kasabın önündeki kedi gibi.

Dükkanın içinde olmayı düşler hep

Dışarıda soğuk bir yalnızlık

Omuzlar buz tutmuş, her yan sarkıt dolu 

Isıtır o an içini, ulaşmak istediği bir umut

O umut ki, ayakta tutmakta Mabud’u

Neler beklemedi ki umutlarından

Çiçek bahçelerinin içinde

Olacaktı bir güzeli

Saçları kara, gözleri kara

Yürürken endamı, akıllara ziya

Ulaşmak için o güzele

Hayal etmekten öte bir şeyde yapmadı

Umut fakirin ekmeğiymiş

Oda hep umudunu yedi

Şimdi bekler durur düşleriyle

Kasap dükkanının önündeki kedi gibi.

Ya elindeki düşlerin değerini bilmeyen

Doymaz bu şaşkına ne demeli? 

Çok söze gerekte yok o da

Olacak sonunda kasabın  önündeki kedi

Bir şair demiş ki; 

Aşka izin verdim, o şimdi tatile gitti

Söyleyemez aslında umudu bitti

Aşka izin vermek, mezardakinin işi

Yaşama izin vermek kimin haddine

Umut kuşunu elinden kaçırmış şaşkın

Aynalarda perişan bakar kendine

Sevmek için ter dökmek gerek

Ulaşmak için kara gözlüye

Her sabah bahçelerden sevda dermek

Diz çöküp önünde, buket buket

Gönül sultanına sevdayı vermek

Aşk bahçesindeki sevgilinin gönlünde

Renk renk gül, mis kokulu karanfil

Belki de kır çiçekleri olarak

Her sabah yeniden açmak gerek

                                         Ali Osman Yılmaz', 'İki şekilde üzülür insan Yitirdiği umutlarının ardından Ya da ulaşamadığı, hayalleri için Hani o kasabın önündeki kedi gibi. Dükkanın içinde...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/umut-ve-keder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Sanma', 'uzun-sanma-sema-oztabak-zyb1d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakma sakın ona buna

                     geçer gider zaman

Uzun sanma ömür, bir gün

                     göçer gider insan.', 'Bakma sakın ona buna                      geçer gider zaman Uzun sanma ömür, bir gün                      göçer gider insan....', ARRAY['Türk Edebiyatı','Şiir','Sema Öztabak']::text[], 8.5, '{"poet":"Sema Öztabak","poet_slug":"sema-oztabak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uzun-sanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devirdim', 'devirdim-sema-oztabak-qb9i8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kokmuş bir balığı attım çöpe

İçi kof bir ağacı devirdim yere

Gönderdeki bayrağı elbette indiririm

Bana zorluk çıkarana pes dedirtirim.', 'Kokmuş bir balığı attım çöpe İçi kof bir ağacı devirdim yere Gönderdeki bayrağı elbette indiririm Bana zorluk çıkarana pes dedirtirim....', ARRAY['Türk Edebiyatı','Şiir','Sema Öztabak']::text[], 8.5, '{"poet":"Sema Öztabak","poet_slug":"sema-oztabak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/devirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Özlem Koydum', 'adini-ozlem-koydum-sema-oztabak-ykkgr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adın düşer dilimden, kalbimde sızın kalır

Siman Gider Gözümden, içimde aşkın kalır

Kokun uçar tenimden, dokunuşların kalır

Tüm bunlardan geriye koca bir ''özlem'' kalır.', 'Adın düşer dilimden, kalbimde sızın kalır Siman Gider Gözümden, içimde aşkın kalır Kokun uçar tenimden, dokunuşların kalır Tüm bunlardan ger...', ARRAY['Türk Edebiyatı','Şiir','Sema Öztabak']::text[], 8.5, '{"poet":"Sema Öztabak","poet_slug":"sema-oztabak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/adini-ozlem-koydum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seneler', 'seneler-sema-oztabak-bj2i5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanki seneler ile yarışmışsın saçlarım

En uzun gece bile dinmemiş göz yaşlarım

Mutluluk diye her gün inlemiş dudaklarım

Aşk aradın ömrünce bulabildin mi canım.', 'Sanki seneler ile yarışmışsın saçlarım En uzun gece bile dinmemiş göz yaşlarım Mutluluk diye her gün inlemiş dudaklarım Aşk aradın ömrünce b...', ARRAY['Türk Edebiyatı','Şiir','Sema Öztabak']::text[], 8.5, '{"poet":"Sema Öztabak","poet_slug":"sema-oztabak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seneler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biorop''at (Sevişelim)', 'biorop-at-seviselim-sema-oztabak-53fkt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Handtzo var na dtzanashe    (Bu sene olmazsa seneye)

Gamabitkhvat bichilât           (Evlenelim)

Hadtzi mokhti chkimde do    (Şimdi gel bana da)

Sin do ma biorop’at              (Sen ve ben sevişelim)

Trangik hesho mskva tolep  (Tanrı öyle güzel gözleri)

Musheni megochanu            (Sana neden verdi)

Skani ochumalûte                 (Seni beklemekten)

Tomapet memakchanu        (Saçım da beyazladı)

Dtzanape skan ustine           (Yıllar senin yüzünden)

Hich var golilams                   (Geçmek bilmiyor)

Skani ochumalute                  (Seni beklemekten)

Ora ti mek’emilams               (Zamanım geçiyor)

Handtzo var na dtzanashe    (Bu sene olmazsa seneye)

Gamabitkhvat bichilât            (Evlenelim)

Hadtzi mokhti chkimde do    (Şimdi gel bana da)

Sin do ma biorop’at               (Sen ve ben sevişelim)

.... (26/06/1987 - Sema Öztabak)  

Handtzo var na dtzanashe     (Bu sene olmazsa seneye)

Bere dop’at bikhelât               (Çocuk yapalım sevinelim)

Hadtzi mokhti chkimde do     (Şimdi gel bana da)

Sin do ma biorop’at                (Sen ve ben sevişelim)

....(01/06/1995 - Sema Öztabak)

Lap’ardepe ibirnan                         (Çakallar şarkı söylüyor)   

Hadtzi mtdzhima mtdzhimasen     (Şimdi yağmur yağacak)                  

Mokhti chkwa gamabitkhwat         (E gel hadi evlenelim)                             

Dtzanashe mik mu vasen               (Seneye kim ne yapacak)

...(29/04/2004 - Nihat Özyılmaz)', 'Handtzo var na dtzanashe    (Bu sene olmazsa seneye) Gamabitkhvat bichilât           (Evlenelim) Hadtzi mokhti chkimde do    (Şimdi gel bana...', ARRAY['Türk Edebiyatı','Şiir','Sema Öztabak']::text[], 8.5, '{"poet":"Sema Öztabak","poet_slug":"sema-oztabak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/biorop-at-seviselim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Değilim Bugün', 'i-yi-degilim-bugun-muammer-celik-s29g2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başımda bir çöpcü

elinde tenekesiyle 

topluyor, toparlıyor

beni süpürgesiyle…! 

Bitik bir kavganın 

yenik bir yanıyım

yitik bir aşkın 

tütmekte olan külüyüm…! 

02.10.2003

BirDeli', 'Başımda bir çöpcü elinde tenekesiyle  topluyor, toparlıyor beni süpürgesiyle…!  Bitik bir kavganın  yenik bir yanıyım yitik bir aşkın  tütme...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iyi-degilim-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menfaat', 'menfaat-kerem-korkut-7zqyd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hele büyükse sahnedeki payi; 

Degisiverirler zakkum çiçegine, hercai meneksenin kokusunu.

Hele sevgilere girmeye görsün.

Nice sevda sarkilari söyletir, siritan sahtekár suratlarda..

Gülü bülbüle, yagmuru topraga, evladi''da ata''ya düsman ediverir.

Nice evlatlar yetim, nice gelinler dul, nice intiharlar, 

Sir kalmistir bu yüzden.

Aids''ten, veremden, sitma''dan beterdir körolasi...

Íçten içe öldürür sizi, hiç farkina varmadan.

Birde bakmissiniz, 

Ruhunuzu sativermissiniz seytana.

Yok oluvermis insanliginiz, yani sizi siz yapan benliginiz.

Ve onca güzel seyler; çiçek gibi, kitap gibi, Ask gibi.

Sabahin ilk isiklariyla seyrettiginiz o güzelim mehtap gibi.

Annenizin sevkatli bir bakisi, aldiginiz ilk hediye.

Hasretlerin arkasindan gelen kavusmalar.

Veya bir tren garinda, bir otobüste yaptiginiz

 küçücük bir sohbet gibi, 

hepsi ama hepsi yokoluvermis bir anda.

Kalakalmissiniz o kara çaliyla

Artik hepona çalisir onun için yasar ve onun ugruna ölürsünüz.

Oysa''ki yasam tüm çiplakligiyla güzeldir.

Hele o olmadan, 

denizler daha bir mavi, yildizlar alabildigine isil, 

Çiçekler daha bir baska güzel kokar yüreklerde.

Atin içinizdeki bu iblisi, yok edin beyninizdeki kara çibani.

Yedi kati yerin dibine gömúp, kezzap dökün anisina, 

Sakin sizde degismeyin zakkum çiçegini, 

Hercai meneksenin kokusuna...

Kerem Korkut 18/10/1995', 'Hele büyükse sahnedeki payi;  Degisiverirler zakkum çiçegine, hercai meneksenin kokusunu. Hele sevgilere girmeye görsün. Nice sevda sarkilar...', ARRAY['Türk Edebiyatı','Şiir','Kerem Korkut']::text[], 8.5, '{"poet":"Kerem Korkut","poet_slug":"kerem-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/menfaat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Uyku', 'son-uyku-adem-ozdemir-kql4z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artık tamam olmuşsa vakit, şimdi ne çâre,

Tekrar acı bir beste çalar ince minâre.

Kuşlar yine çığlıklar atar vakt-i seherde,

Ürperti dolar kalplere durgun gecelerde.

Herkesçe ölümdür hayatın en hazîn ânı,

Topraktaki sâkin eve yollanma zamânı.

Bir kuytu çınar gölgesi altında serince,

Son uykuya dalmak bu yamaçlarda derince.

Beyhûde geçen bunca yılın son baharında,

Bekler bizi hicrân, gece, bir yol kenarında.

Son arzusudur sâdece âsûde hayâtın; 

Ey tatlı ölüm, sen ne bugün gel, ne de yârın. 

                                          

                                      13.07.1996 / Düzce

        Mefûlü  mefâîlü  mefâîlü  feûlün', 'Artık tamam olmuşsa vakit, şimdi ne çâre, Tekrar acı bir beste çalar ince minâre. Kuşlar yine çığlıklar atar vakt-i seherde, Ürperti dolar k...', ARRAY['Türk Edebiyatı','Şiir','Adem Özdemir']::text[], 8.5, '{"poet":"Adem Özdemir","poet_slug":"adem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/son-uyku-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitsin', 'gitsin-ozgur-sirius-34v94', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağaçlar kalemim, deniz defterim

Sayısız günahı bana yaz gitsin

Ölsemde orada seni beklerim

Gönlüne mezarı derin kaz gitsin

Bedenim dağılıp ruhum varırsa

Azrail bu canı sensiz alırsa

Kalbine başkası girip kalırsa

Çalmayı unutan dertli saz gitsin

Özgürüm gözlerin derdinde âmâ

Pabucun delinmiş elbisen yama

Elif’de sonunda kavuştu lâm’a

Yazmasan da söyle söyle söz gitsin

Nicedir bu halin ey aşık senin

Yokmudur güzelce bir yurdun yerin

Derdime yanarım akıl sır verin

Bilinmez yarayım yine az gitsin', 'Ağaçlar kalemim, deniz defterim Sayısız günahı bana yaz gitsin Ölsemde orada seni beklerim Gönlüne mezarı derin kaz gitsin Bedenim dağılıp r...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gitsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-rafet-maden-r39cm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sigaranın dumanındayım

Dinliyorum yağmur sesini

Gözle görünsemde uzaktayım

Özledim mazinin güzelliğini.

Bir başkaydım o zamanlar

Bilirler benimle yaşayanlar

O gurbete çıkmadan önce

Tanıştığım karamsarlıklar

Sizlere veda ederken

Aranıza geliyorum unutulanlar.

Bir toprak kadar temiz kokan

Beni diyardan diyara atan

Sazımın teline nağme olan

Türküler hatırlarmısınız

Neleri yaşadık biz o zaman.

Bilmez benim gibi çekmeyenler

Hasreti içki gibi içmeyenler

Elveda artık beni ağlatan

Yar bildiğim kara ecel.

RAFET size veda ediyor

Elveda artık çilekeşler.', 'Bir sigaranın dumanındayım Dinliyorum yağmur sesini Gözle görünsemde uzaktayım Özledim mazinin güzelliğini. Bir başkaydım o zamanlar Bilirle...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/elveda-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Olamamak', 'seninle-olamamak-rafet-maden-5fja7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kolay değil hasreti yaşamak, 

Yarına nice umutları taşımak, 

Tut ellerimden koşalım yarına, 

Benim tek derdim seninle olamamak.

Uykularım kaçıp, sana gelmek isterken, 

Senin bu halini düşünüp vazgeçerken, 

O anda delice sana hasret çekerken, 

Beni kahrediyor seninle olamamak.

Bu dünyadaki tek varlığımsın, 

Herşeyden önce, sen sevdalımsın, 

Beni üzerek ne kazanırsın? 

Zaten kahrediyor seninle olamamak.

                         

1997', 'Kolay değil hasreti yaşamak,  Yarına nice umutları taşımak,  Tut ellerimden koşalım yarına,  Benim tek derdim seninle olamamak. Uykularım ka...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seninle-olamamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Susmak Zamanı', 'simdi-susmak-zamani-oguzkan-bolukbasi-f6xwd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kan kırmızı yanıyor gözlerim

Uykusuzluk değil

Gözyaşı değil sebebim

Nefretim 

Teslim almış her şeyimi

Ejderhaya büründüm

Çünkü aşkımı gömdüm kan kırmızı  bir denize

Ne kadeh kaldırabilirim şerefinize

Ne de gülebilirim yüzünüze

Aniden olmaz düzelmesi kimyası ruhumun

O sadece kendimin sahip olduğu orospumun

Öyle birdenbire beklemeyin güneşin açmasını 

Bir başka aşkın  tuzağına kadar dağılmasını gökteki bulutumun

Kan kırmızı yanıyor gözlerim

Şaraplardayım kadehlerde boşalmayan

Hiç esrimiyor başım 

Ağzım dilim dolaşmıyor ki konuşsam kıyıdaki Adem babayla

Ne anlatabilirim bu ayık kafayla şimdi ona 

Aczimi göstermek istiyorum

Çaresizliğimi 

Yangınlarını içdenizlerimin batan gemilerinde yükselen dumanları

Filikalar yok kurtulan yok

Şimdi susmak zamanı …..', 'Kan kırmızı yanıyor gözlerim Uykusuzluk değil Gözyaşı değil sebebim Nefretim  Teslim almış her şeyimi Ejderhaya büründüm Çünkü aşkımı gömdüm...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/simdi-susmak-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anı', 'ani-hafize-kilic-2-3l7v5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anı defterime yazamam seni,

Belki de okuyan olursa diye,

Nazardan korkarım diyemem seni,

Belkide kıskanan olursa diye,

Kalbime kazıdım anılarını,

Orada benimle kalırsa diye,

Karanlık bir yere koyamam seni,

Birileri seni incitir diye,

Dağlara yücelere koyasım gelir,

Bulutlara bir duvak gibi örtesim gelir...

Bu şiirim sevgili gelinim Ayşeme armağanımdır...', 'Anı defterime yazamam seni, Belki de okuyan olursa diye, Nazardan korkarım diyemem seni, Belkide kıskanan olursa diye, Kalbime kazıdım anıla...', ARRAY['Türk Edebiyatı','Şiir','Hafize Kılıç 2']::text[], 8.5, '{"poet":"Hafize Kılıç 2","poet_slug":"hafize-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ani-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavilerimi geri aldım', 'mavilerimi-geri-aldim-erol-sen-35603', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerden diyene cevap yok

Ben içimde yaşarım herşeyimi

Sevinçlerim de var benim

Boğazıma takılan güzel duygularım

Kötü haberler şaşırtmaz gönlümü

Alışkanlık demek çok kötü

Alışmak istemiyorum acılara

Beklentim güzel haberlere

Yaşayan fikirlerim doğmamış günlere

Geceler umuda yeşertecek baharı

Neden Geceler

Benim gecelerimde mavi

Anlamazsın gece bakmadıysan yıldızlara

Yada o güzelim aya

Bir yıldız kayarken

Dilek diledin mi sen? 

Sahil kasabaları romantik yapar gönlümü

Yaşarım doyasıya yaşamın renklerine

Kimse anlamasa da beni

Ben MAVİlerimi geri aldım....

02.10.03', 'Nerden diyene cevap yok Ben içimde yaşarım herşeyimi Sevinçlerim de var benim Boğazıma takılan güzel duygularım Kötü haberler şaşırtmaz gönl...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mavilerimi-geri-aldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mustafa Kemal Atatürk', 'mustafa-kemal-ataturk-guner-kaymak-mw4ed', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Millet şükran borçlu sana gönülden 

Unutamayız biz seni yüce Atatürk

Seviyoruz seni tah derinden yürekten

Teşekkür ederiz sana ey yüce Türk

Attığın her adım bize ışık olmuştur

Fırsatçı yobazlar çok geride kalmıştır

Artık cahalet hurafe tarihe karışmıştır

Kurtuluş savaşını millet ile kazandın

En zor şartlarda bile hürriyet''ti inadın

Mollalarla softalarla''da çok uğraştın

Akıl fikir ermiyor başarına gücüne

Lanet olsun nimmeti inkar eden haine

Atam  Cumhurriyet''in dünya''ya örnek

Türkiyem aydın medeni özgur ve laik 

Atamız her türlü övgüye elbet''te layık

Tarihler bu kahraman türkü unutmayacak

Ülkümüz yükselecek hep ileri gidecek

Rahmet''le anacak seni Türküm diyenler

Kahrından ölecek güneşi sevmeyenler

Ozan Güner Kaymak

Amsterdam / 02.10.2003', 'Millet şükran borçlu sana gönülden  Unutamayız biz seni yüce Atatürk Seviyoruz seni tah derinden yürekten Teşekkür ederiz sana ey yüce Türk ...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mustafa-kemal-ataturk-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Yük', 'bi-yuk-bekir-mutlu-gokcesu-gf0f1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben hiç büyüyemedim

Bildim bileli küçüktüm

Büyük laflar edemedim

Büyük düşünemedim

Büyük isteklerim olmadı

Büyük bana, hep bi yük geldi

Bana öyle geldi belki de

Sen nasıl bu kadar büyüdün? 

Küçücük içimde', 'Ben hiç büyüyemedim Bildim bileli küçüktüm Büyük laflar edemedim Büyük düşünemedim Büyük isteklerim olmadı Büyük bana, hep bi yük geldi Bana...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bi-yuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şah Damarımı Kesmeseydin', 'sah-damarimi-kesmeseydin-salih-ozalasan-p81kz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Türkü sendin yüreğimle söylediğim

Halay sendin neşeyle çektiğim

Damarda akan kanım sendin

Şah damarım kesildi akmıyor kanım

Ağaçlar bir gün olur kurur

Kurumazsa da bir gün odun olur

Sevdan yüreğimde dağlar secde durur

Kıblem sendin yıkıldı kıblem

Seninle hüznü sevmiştim sevgili gibi

Seninle güneşler altında yakmıştım geceleri

Ölmeyen şarkılara çevirdim anlamsız kelimeleri

Hayat pınarım sendin kestin suyumu

Kara bulutlar sarsa da korkmazdı yüreğim

Sen varsan ateşlerde yansam gülerim

Umudum sendin bir dağdı senle yüreğim

Kırdın umudumu biçareyim be güzelim

Beklemezdim doğmasa da güne Güneş

Benim için sendin mahşere dek sönmeyen ateş

Benim için candın, canımdan öte; sevgiliye eş

Canımı alsaydın sen kalsaydın be güzelim

Y.Tarihi 02-10-2003 Saat 18.00

Salih ÖZALAŞAN', 'Türkü sendin yüreğimle söylediğim Halay sendin neşeyle çektiğim Damarda akan kanım sendin Şah damarım kesildi akmıyor kanım Ağaçlar bir gün ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sah-damarimi-kesmeseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buzlar Altındayım', 'buzlar-altindayim-salih-ozalasan-sj0nf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen bensiz üşüyorsun belki

Belki karlar yağıyor yüreğine

Oysa ben sensiz üşümeye razıyım

Buzlar altındayım kan akmıyor yüreğime

Gözlerim görmüyor baktığı cisimleri

Yüreğime bastım ısıtır diye tüm resimleri

Çaresizim getirseler de tüm hekimleri

Buzlar altındayım çare yok derdime

Kesseler kolumu akmayacak kanım

Azrail gelse yok alınacak canım

Beni anlatacak bulamam ki bir tanım

Buzlar altındayım ulaşamam yüreğime

Gel gör neylemiş beni sensizlik

Seni sadece sevmiştim bumu densizlik

Eritecek Güneş sendin gidişin şansızlık

Buzdan bir adam muhtaç sevgine

Y.Tarihi 02-10-2003 Saat 17.35

Salih ÖZALAŞAN', 'Sen bensiz üşüyorsun belki Belki karlar yağıyor yüreğine Oysa ben sensiz üşümeye razıyım Buzlar altındayım kan akmıyor yüreğime Gözlerim gör...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/buzlar-altindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bendi', 'gonul-bendi-mehmet-husnu-asan-pzxzg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Miadı dolmuş yaprak misali 

Dalından solarak yere düşersin

Surları yıkılmış kale misali 

Taşlarla yamalanıp gönül eylersin

Bir soluktur oysa geride kalan 

Son nefeste belki “Keşke” düşersin

Ütopyalar düşler dara düşlersin

Yaprak misali solup âna düşersin

Mazi bir kaleymiş anlamadın mı 

Dertler “Şahi” misali sallamadı mı

Taşlar üst üste yamalanmadı mı 

Yamalı bohça gibi yola düşersin

Köşklerde sarayda yaşayıp durdun

Tavuklar gibi her gün yemine durdun 

Kaç defa aradın ki kaç defa buldun 

Peynir gemisinde liman düşlersin

Rüzgâr dalı kırmış yenilenir mi

Daldan özür dilese hiç geri gelir mi

Kırılan dallar yeşillenir mi 

Fırtınaya dönerken affı düşlersin

Bu sevda  gönüle öyle ki düşer 

Ravza-i Muratta gül-i remzidir

İmdi kifayetsiz kalır kelimeler

Âna sana malik gönül bendidir

Mehmet Hüsnü ASAN

16.09.2003-ŞIRNAK', 'Miadı dolmuş yaprak misali  Dalından solarak yere düşersin Surları yıkılmış kale misali  Taşlarla yamalanıp gönül eylersin Bir soluktur oysa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Hüsnü Asan']::text[], 8.5, '{"poet":"Mehmet Hüsnü Asan","poet_slug":"mehmet-husnu-asan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gonul-bendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severim Susmalarını*', 'severim-susmalarini-naime-erlacin-2kn63', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'severim susmalarını

güzelliğindir beni 

böylesi boynu bükük bırakan

yanık sevdalar büyütmüşsün

ruhunun siyah telvelerinde

isyana kalkışmak üzre gibiydin oysa

her gün

her dem

her saniye

severim aşkı saklamanı

sararak yorgun düşlerine

sürgit eskitirken yalnızlığı

suskun bir volkan tepesinde 

soyluca susmanı 

tutkulu bir lisanın var bana karşı

giderek artıyor güzelliğin 

suskun kalmalısın böyle

çözmeliyiz 

susarak sevmenin zorlu anlamlarını

her an yanımda olsan bile

severim susmalarını! 

(02 Ekim 2003) 

(*)   Bu şiirin bazı dizelerini ve ana temasını vererek, şiiri yazmamı sağlayan Sevgili Eşim Şahin Erlaçin’e teşekkür ve sevgilerimle.', 'severim susmalarını güzelliğindir beni  böylesi boynu bükük bırakan yanık sevdalar büyütmüşsün ruhunun siyah telvelerinde isyana kalkışmak ü...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/severim-susmalarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana', 'ana-hakan-gokcesu-zupsq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anacığım, sencanımın bir parçasısın, 

Sensiz dünyanın tadı tuzu yoktur.

Sen beni doğuran, beni büyütensin, 

Sen benim dünyamsın.

Şimdi düşünüyorum ki, 

Sen acaba beni seviyormusun? 

Ben senin beni sevdiğini düşünüyorum, 

Çünkü seni çok seviyorum.', 'Anacığım, sencanımın bir parçasısın,  Sensiz dünyanın tadı tuzu yoktur. Sen beni doğuran, beni büyütensin,  Sen benim dünyamsın. Şimdi düşün...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gökçesu']::text[], 8.5, '{"poet":"Hakan Gökçesu","poet_slug":"hakan-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ana-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen mi', 'sen-mi-derin-oger-ov1cz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen mi 

akşamın yüzündeki o pırıltılı bakış

yıldızlar mı kayar yüreğime

göğün dallarından sarkıp Sen mi

bu dokunuşlar bu cennet sıcağı öpüşü 

dağların menekşe kokularıyla kucağına alır gibi

uzanan tenime Sen mi

görünmez el güneşi tutan gizli bulut

batışı yaklaştıkça içime doğan yaşam kaynağı 

bir nefes kadar yakın Sen mi.................', 'sen mi  akşamın yüzündeki o pırıltılı bakış yıldızlar mı kayar yüreğime göğün dallarından sarkıp Sen mi bu dokunuşlar bu cennet sıcağı öpüşü...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor ettim sabahı', 'zor-ettim-sabahi-sinan-guven-6uoc9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zor ettim sabahı zor…

Öyle özledim anlıyor musun beni? 

Bir nefes gibi içime çekmek, 

Koklamak istiyorum seni…

Öpmek dudaklarını

Okşamak narin tenini, 

Zor ettim sabahı zor

Anlıyor musun beni?', 'Zor ettim sabahı zor… Öyle özledim anlıyor musun beni?  Bir nefes gibi içime çekmek,  Koklamak istiyorum seni… Öpmek dudaklarını Okşamak nar...', ARRAY['Türk Edebiyatı','Şiir','Sinan Güven']::text[], 8.5, '{"poet":"Sinan Güven","poet_slug":"sinan-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zor-ettim-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gen Yürekli', 'gen-yurekli-sema-senel-4nahu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her genin de bir sevda yatar

her genin de ayri bir yalan

her genin de...

ücgen yüreklimin

bense ciktim yüreginden

dokuz genin de 

dokuz kan

her geninden bir yürek kanar

her genin de

göz yasi

fahise yüreklimin

dokunsam

bin ah isitecegim yüz genin den

esir kalan yüreklerden

irkildim senden', 'her genin de bir sevda yatar her genin de ayri bir yalan her genin de... ücgen yüreklimin bense ciktim yüreginden dokuz genin de  dokuz kan ...', ARRAY['Türk Edebiyatı','Şiir','Sema Senel']::text[], 8.5, '{"poet":"Sema Senel","poet_slug":"sema-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gen-yurekli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz İstemem', 'sensiz-i-stemem-hicabi-ceylan-bwhq6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensiz olan dünyayı istemem

Sensiz görünen rüyayı istemem

Sensiz bulunan sarayı istemem

Sen ol yeterki, çadır olsun yaşadığım yer

Sensiz açan gülleri istemem

Sensiz öten bülbülleri istemem

Sensiz olan çölleri istemem

Sen ol yeterki, susuzluktan yanan dudağıma su istemem

Sensiz olan yolları istemem

Sensiz açılan kolları istemem

Sensiz dökülen yaprakları, son baharı istemem

Sen ol yeterki aklaşsın saçlarım, dökülsün bütün yapraklarım

Hicabi Ceylen', 'Sensiz olan dünyayı istemem Sensiz görünen rüyayı istemem Sensiz bulunan sarayı istemem Sen ol yeterki, çadır olsun yaşadığım yer Sensiz aça...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sensiz-istemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ak Saçlı Dinazora', 'ak-sacli-dinazora-ali-osman-yilmaz-s57f6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden diye sormayın

Şaşkın şaşkın bakıp doğaya

Siz yaşlanıp eskimekteyken

Nasılda yenilenir doğa

Ve binlece yıldır

Böyle olduğunu 

Unutuyorsunuz.

Sevgi yüklü toprağında

Her bahar sevda doğurur

Aşk Doğurur yeniden

Aşk çiçekleri goncalanır

Her dem taze aşklara

Kucak açar.

Ya sen bay dinazor? 

Her bahar gönlünde sevdayı

Her bahar yeniden aşkı

Yaşayamadığın için mi? 

Yitirdiğin her güzelden sonra

Engin maviliklerin derinliklerinden,

Gelen aşkı kucaklamak

Yeniden sevda ateşinde yanmak için,

Gücün kalmamışsa,

Niye üzülürsün? 

Çevren, enkazlarla dolmuş, 

Her Yanında mezar kazıcısı

Sense ortalarda bir voyvoda,

Sevgi üretmekten yoksun,

Yaşayamadığı güzelliklere düşman,

Yaşamadığın o aşkı,

Kimse yaşamasın diye

Kazık çakıyorsun aşk’a

Ak saçlı, heykel suratlı 

Dinazorlaşmış ihtiyar.', 'Neden diye sormayın Şaşkın şaşkın bakıp doğaya Siz yaşlanıp eskimekteyken Nasılda yenilenir doğa Ve binlece yıldır Böyle olduğunu  Unutuyors...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ak-sacli-dinazora-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözler ve Gözyaşları', 'sozler-ve-gozyaslari-ali-osman-yilmaz-ngayz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözler dilimden

Göz yaşlarım gibi dökülmekte

Ey güzel! 

Neden, neden diye soruyorum? 

Döktüğüm bu göz yaşlarım

Aşk türküsü söyler gibi

Kelimelerle dolu.

Seni görmeden, 

Hayalimdeki sen, 

Bana o sözleri söyleten.

Göz yaşım gibi söz, 

Bağrımı yakan köz, 

Uludağları deldiren öz.

Gelmekte olan sevgiliye duyulan

Hasretten başka, 

Hayalden öte nedir ki? 

Mine gibi beyaz

Gözümden dükülen inci

Dizilir bende şiir, şiir

Sevda ateşi yüklü onca söz.', 'Sözler dilimden Göz yaşlarım gibi dökülmekte Ey güzel!  Neden, neden diye soruyorum?  Döktüğüm bu göz yaşlarım Aşk türküsü söyler gibi Kelim...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sozler-ve-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırlanmış Zamanlar', 'sirlanmis-zamanlar-ahmet-aksoy-lb8kw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sırlanmış zamanlar bilirim

Açılma arifesinde

Kapanmışlık sonbaharında

Adamın yüreğine sıkışıklık verir.

Sırlanmış zamanlar bilirim

Zaman bir şimendiferdir

Lakin tek gücü rüzgardır

İlerlemek bilmemektedir.

Sırlanmış zamanlar bilirim

Ruhun daraldığı anlardır

Etraf durgun bir göl gibidir

Rüzgarda yaprak kıpırdamamaktadır

Sırlanmış zamanlar bilirim

Kederin hakim olduğu 

Huzursuzluğun hüküm sürdüğü

Nedensizdir fakat umutlar kördüğüm.', 'Sırlanmış zamanlar bilirim Açılma arifesinde Kapanmışlık sonbaharında Adamın yüreğine sıkışıklık verir. Sırlanmış zamanlar bilirim Zaman bir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sirlanmis-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dediler Bir Suna Aştı', 'dediler-bir-suna-asti-pir-sultan-abdal-9c62v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hacı Bektaş tekkesinin dışından

Dediler bir suna aştı yalınız

Ayırmışlar yareninden eşinden

Dediler bir suna aştı yalınız

Eşinden ayrıldı Bektaş''a vardı

Kuru göllerde çok savaşlar kıldı

Ayrılık haberin Mucur''dan aldı

Dediler bir suna aştı yalınız

Geçti m''ola Kızılırmak boyunca

Çeken bilir ayrılığın doyunca

Ayırmışlar on''ki imam soyunca

Dediler bir suna aştı yalınız

Aştı m''ola Kırlangıc''ın belini

Avcı rast gelirse yolar telini

Arzulamış gider dostun ilini

Dediler bir suna aştı yalınız

Pir Sultan Abdal''ım gönlümüz paslı

Dudu kumru gibi kafeste besli

Hünkar Hacı Bektaş Veli''dir nesli

Dediler bir suna aştı yalınız', 'Hacı Bektaş tekkesinin dışından Dediler bir suna aştı yalınız Ayırmışlar yareninden eşinden Dediler bir suna aştı yalınız Eşinden ayrıldı Be...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dediler-bir-suna-asti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Taneleri', 'kar-taneleri-ahmet-aksoy-jkrkg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaçıncı fasikülünde bilmiyorum

Birinde yazıyor olmalı fakat

İşte bu yüzden arıyorum

Ki etmekteyim sebat

Ümit tohumları ekilidir yüreğime

Karamsarlık yoktur bu uğurda

Ki yakamaz çaresizlik güneşi

Azmin gölgesi altında

Cilt cilttir, emin ol hayat

Ve yüklüdür evrenin manaları onda 

Ki yaşamın anlamları da

Muhakkak yazmaktadır onda

Kimi şanslıdır bu yolda

Ulaşır aşka ilk bakışta

Kimi biraz daha şanssız

Çaba sarf etmeden ulaşamaz ona

Lakin hayat aşktır

Bu yüzden döner maddeler

Işık saçan çekirdeğin etrafında

Bununla beraber; 

Yapmak

Yaptığını anlamak 

Değildir şüphesiz....', 'Kaçıncı fasikülünde bilmiyorum Birinde yazıyor olmalı fakat İşte bu yüzden arıyorum Ki etmekteyim sebat Ümit tohumları ekilidir yüreğime Kar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kar-taneleri-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dereyi Aşağı Gelir Kurt İzi', 'dereyi-asagi-gelir-kurt-i-zi-pir-sultan-abdal-msny2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dereyi aşağı gelir kurd izi

Aç kurdun ağzında bir körpe kuzu

Mevlayı seversen ağlatma bizi

Meleme koyunum vazgel kuzundan

Koyun sen kuzunu kuzulamadın mı

Sağında solunda gizlemedin mi

Aç kurt gelir deyi gözlemedin mi

Meleme koyunum vazgel kuzundan

Yüreğimin ince sızısı mısın

Alnımızın kara yazısı mısın

Abdal Pir Sultan’ ın kuzusu musun

Meleme koyunum vazgel kuzundan', 'Dereyi aşağı gelir kurd izi Aç kurdun ağzında bir körpe kuzu Mevlayı seversen ağlatma bizi Meleme koyunum vazgel kuzundan Koyun sen kuzunu k...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dereyi-asagi-gelir-kurt-izi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diken Arasında Bir Gül Açıldı', 'diken-arasinda-bir-gul-acildi-pir-sultan-abdal-9c94l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Diken arasında bir gül açıldı

Bülbülüm bahçene ötmeğe geldim

Bezirganım yüküm gevher satarım

Ali pazarına dökmeğe geldim

Baç''ım vermeyince yüküm satılmaz

Gevherin hasına hile katılmaz

İnkar toru ile şahin tutulmaz

Bir gerçek tor''una düşmeğe geldim

Ben bend oldum şu meydana atıldım

İkrar verdim ikrarıma tutuldum

İbtida taliptim pire katıldım

Pirin eteğini tutmağa geldim

Pir Sultan Abdal''ım yüreğim döğün

İmamlar rengine boyandım bugün

İrehber pişirir talibin çiğin

Ahiri bu imiş pişmeğe geldim', 'Diken arasında bir gül açıldı Bülbülüm bahçene ötmeğe geldim Bezirganım yüküm gevher satarım Ali pazarına dökmeğe geldim Baç''ım vermeyince y...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/diken-arasinda-bir-gul-acildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamam', 'anlatamam-deniz-koktas-rhijm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle anlar vardır ki anlatılmaz, hissedilir

Mutluluk gibi, sevgi gibi

Sadece yaşarsın..

Yada bulamazsın mutluluğu anlatacak kelimeyi

Anlatmaya çalışırsın ama beceremezsin

Denersin, saçma gelir başkasına

Bir kuş kondu yüreğime, aldı uçurdu beni, pırpır etti yüreğim

Sen de anlamadın değil mi? 

Yine bazı anlar vardırki onlarda anlatılmaz

Ayrılık gibi, yalnızlık gibi

Kime ne anlatabilirsin! 

Kimi boşver unut der, kimi zamanla geçer.Ne anlarlarki! 

Sen yaşamışsın sen hissetmişsin

Bir ara anlatmaya çalışırsın yine beceremezsin

Bir kor düştü yüreğime

Boğazım düğümlendi, yaktı kavurdu beni

Acısını ruhumda hissettim...

Yine anlamadın değil mi? Çünkü anlatamadım.

Tek kişilik oyun gibi ben oynadım, 

Sen seyrettin....', 'Öyle anlar vardır ki anlatılmaz, hissedilir Mutluluk gibi, sevgi gibi Sadece yaşarsın.. Yada bulamazsın mutluluğu anlatacak kelimeyi Anlatma...', ARRAY['Türk Edebiyatı','Şiir','Deniz Köktaş']::text[], 8.5, '{"poet":"Deniz Köktaş","poet_slug":"deniz-koktas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlatamam-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle Sana Bir Nasihat Edeyim', 'dinle-sana-bir-nasihat-edeyim-pir-sultan-abdal-1gfmr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dinle Sana Bir Nasihat Edeyim

Hatırdan Gönülden Geçici Olma

Yiğidin Başına Bir Hal Gelirse

Bunu Ellere Açıcı Olma

Mecliste Arif Ol Kelamı Dinle

El İki Söylerse Sen De Bir Söyle

Elinden Geldikçe Sen İyilik Eyle

Hatıra Dokunup Yıkıcı Olma

El Ariftir Yoklar Senin Fendini

Dağıtırlar Tuzağını Bendini

Alçaklarda Otur Gözet Kendini

Kat-i Yükseklerden Uçucu Olma

Pir Sultan Abdalım Sözüm Başarır

Aşkın Deryasını Boydan Aşırır

Seni Bir Mecliste Hacil Düşürür

Kötülerle Konuş Gocucu Olma', 'Dinle Sana Bir Nasihat Edeyim Hatırdan Gönülden Geçici Olma Yiğidin Başına Bir Hal Gelirse Bunu Ellere Açıcı Olma Mecliste Arif Ol Kelamı Di...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dinle-sana-bir-nasihat-edeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Yalan', 'dunya-yalan-hikmet-karakus-z33bq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne bu dünyada

         ne de öbür dünyada, 

Herkes kendi dünyasında, 

Gerisi dünya kadar yalan..

(İst.1997)', 'Ne bu dünyada          ne de öbür dünyada,  Herkes kendi dünyasında,  Gerisi dünya kadar yalan.. (İst.1997)...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dunya-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döndün Mü Benden Yüzü Dönesi 1', 'dondun-mu-benden-yuzu-donesi-1-pir-sultan-abdal-gnhp7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Döndün mü benden yüzü dönesi

Verdiğin ikrara saldım ben seni

İkrarı boynuna kement olası

Verdiğin ikrara saldım ben seni

Zemheride yağan karlar erimez

Aşk atına binen gönül farımaz

İkrar birdir iki yere verilmez

Verdiğin ikrara saldım ben seni

İkrar verdim ikrarıma güderim

İkrarsız dilberi ya ben n''iderim

Varıp bir ikrarlıya şefaat ederim

Verdiğin ikrara saldım ben seni

İkrar verir ikrarından dönücü

Arayıp da kendi gibisin bulucu

Bak sonunda gelsin hakkın kılıcı

Verdiğin ikrara saldım ben seni

Uzun yaylana da çıkmayım derdim

Soğuk sularını içmeyeim derdim

Serden geçip senden geçmeyim derdim

Verdiğin ikrara saldım ben seni

Pir Sultan Abdal''ım ahirim aman

Münkirin göynünden gitmesin güman

Şefaat etmesin o ahir zaman

Verdiğin ikrara saldım ben seni', 'Döndün mü benden yüzü dönesi Verdiğin ikrara saldım ben seni İkrarı boynuna kement olası Verdiğin ikrara saldım ben seni Zemheride yağan kar...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dondun-mu-benden-yuzu-donesi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-i-smail-ateran-w7fyo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabah olmak üzere, gökyüzü koyu mavi 

Havada hafif bir esinti var

Horozlar ötüyor uzakta, yapraklar hışırdıyor

Biraz ilerde derede akan suyun sesi geliyor

Bir meçhulu beklemeye doğa destek çıkıyor

zevk katıyor beklemenin yorgunluğuna

Esen vakti esiyor yine...

Kokusu doluyor içine; kırağının ıslattığı çimen kokusu

Böyle çekecek içine, böyle sevecek

Her sabah öncesi böyle bekleyecek...

Ve bu gün; meçhul, kabanının üzerinde odaya girince

Verdiği serinlik hissiyle serinletecek yanan yüreğini

O gelecek! o gelecek, tatlı bir serinlik esecek

Araba büyük bir şehre giriyor bir sabah vakti

Caddeler bomboş, şehir esniyor

Simitçi çocuklar erkenci

Onlar da esniyor

Taksi ilerlerken cadde de

Güneş yüksek binaların arasından

Bir görünüp bir kayboluyor

Mola veriyorlar bir sabahçı kahvesinde 

Bir masaya oturuyorlar

Konuşmaya korkuyorlar; yaşayacak çok şey var! 

Çay kazanından buharlar çıkıyor

Ve masadaki bardaklardan

Aniden bardak havada kalıyor

Takadı kesiliyor onu tutan elin

Ve ikinciside meçhule 

Yerde yatarlarken 

Artık o serinliği ikisi de yaşamıyor!', 'Sabah olmak üzere, gökyüzü koyu mavi  Havada hafif bir esinti var Horozlar ötüyor uzakta, yapraklar hışırdıyor Biraz ilerde derede akan suyu...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ateran']::text[], 8.5, '{"poet":"İsmail Ateran","poet_slug":"i-smail-ateran","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kacis-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar Bizi Safa İle Gönderin', 'dostlar-bizi-safa-i-le-gonderin-pir-sultan-abdal-j7r4d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geldim gider oldum illerinize

Dostlar bizi safa ile gönderin

Doyamadım tatlı dillerinize

Dostlar bizi safa ile gönderin

Şöyle bir güzelden ahd alamadım

Bir ahdine bütün yar bulamadım

Bir daha ya geldim ya gelemedim

Dostlar bizi safa ile gönderin

Himmet eylen şu dağları aşalım

Pir aşkına kaynaşalım coşalım

Gelin birer birer helallaşalım

Dostlar bizi safa ile gönderin

Çıkalım yaylaya inelim düze

Himmet eylen yaran ahbaplar bize

Bir selam göndersem gelir mi size

Dostlar bizi safa ile gönderin

Pir Sultan Abdal''ım Hakk''a yakındır

Edebi erkanı hemen takın dur

Ölüm uzak derler hemen yakındır

Dostlar bizi safa ile gönderin', 'Geldim gider oldum illerinize Dostlar bizi safa ile gönderin Doyamadım tatlı dillerinize Dostlar bizi safa ile gönderin Şöyle bir güzelden a...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dostlar-bizi-safa-ile-gonderin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durmaz Yezit Oklar Bizi', 'durmaz-yezit-oklar-bizi-pir-sultan-abdal-2970s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geldik darına duşlandık

İrehbere bağışlandık

Bir aşıyla aşılandık

Durmaz Yezit oklar bizi

Gönül bir ulu şehirdir

Rızasız lokma zehirdir

Talib yiyemez haklar bizi

Hak iyesi haklar bizi

Tarikattadır elimiz

Hakikattadır yurdumuz

Hak''la olunca virdimiz

Her kazadan saklar bizi

Meydana meydan güzarım

Hak olan yere nazarım

Gaibde sırda gezerim

Göremesin çoklar bizi

Pir Sultan talib devirir

Mervanın külün savurur

Yedi kat barü çevirir

Ali anda saklar bizi', 'Geldik darına duşlandık İrehbere bağışlandık Bir aşıyla aşılandık Durmaz Yezit oklar bizi Gönül bir ulu şehirdir Rızasız lokma zehirdir Tali...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/durmaz-yezit-oklar-bizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duysun Canlar Deyü Bizi Asarlar', 'duysun-canlar-deyu-bizi-asarlar-pir-sultan-abdal-l9p1u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeşil başlı ördek göllere uçtu

Duysun canlar deyü bizi asarlar

Bir taş oynamasın yerli yerinden

Duysun canlar deyü bizi asarlar

Çıkardılar ağ bedenden atmaya

Şimdi indirdiler yine dahmeye

Kanrıldım çevrildim baktım zahmaya

Duysun canlar deyü bizi asarlar

Varlığın çevresi dopdolu incir

Severim demeye canım zarıncır

Elimde kelepçe boynumda zincir

Duysun canlar deyü bizi asarlar

İlimi sorarsan köyümdür Banaz

Dilerim onmasın ol karılı Sivas

Bir ben ölmeyinen alem yıkılmaz

Duysun canlar deyü bizi asarlar

Pir Sultan Abdal''ım kaddim büküldü

Gözümün gevheri yere döküldü

Kendir kement boğazıma takıldı

Duysun canlar deyü bizi asarlar', 'Yeşil başlı ördek göllere uçtu Duysun canlar deyü bizi asarlar Bir taş oynamasın yerli yerinden Duysun canlar deyü bizi asarlar Çıkardılar a...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duysun-canlar-deyu-bizi-asarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecel Burcu', 'ecel-burcu-pir-sultan-abdal-f097h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hak belasın versin Mülcem Oğlu''nun

Hançer ile kanın saçtı Ali''nin

Terk eyledi Bağdat gibi şarını

Ecel burcu boynun büktü Ali''nin

Ali''m çeker idi dünya firkatın

Cümle kullarını alırdı satın

Fatma Ana ile Şehriban Hatun

Libasın üstüne döktü Ali''nin

Ali''m ah eyledi eridi sızdı

Kanber de bu işte ayrılık sezdi

Oğlu İmam Hasan tabutu düzdü

Tabutu misk anber koktu Ali''nin

Bir nur doğdu Muhammed''in veçhinde

Zülfikar oynadı Çin ü Maçin''de

Doksan bin evliya sancak içinde

Gözleri kan ile doldu Ali''nin

Pir Sultan Abdal''ım sever hazırı

İstemişler Üveys ile Hızır''ı

Yükletmişler Ab-ı Zemzem çadırı

Deve kapısına çöktü Ali''nin', 'Hak belasın versin Mülcem Oğlu''nun Hançer ile kanın saçtı Ali''nin Terk eyledi Bağdat gibi şarını Ecel burcu boynun büktü Ali''nin Ali''m çeker...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ecel-burcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Dost Irmağın', 'eger-dost-irmagin-pir-sultan-abdal-pw5rm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğer dost ırmağın gözün ararsan

Serçeşme''den gelir suyun durusu

Ali Muhammet''tir Muhammet Ali

İkisi de bir elmanın yarısı

Ali''m engür ezdi kırklar da içti

Kırkı da mest oldu kendinden geçti

Muhabbetin kapısını kim açtı

Cümlesi de bir ikrarın çerisi

Ali''m yola gider menzili keser

Sofi nerde olsa yalanı basar

Bir kale yaptırmış on iki hisar

Sor nedendir duvarının örüsü

Dört kapısı vardır kırk da dükkanı

Üçyüz altmış altı gevher madeni

On yedi kişidir alıp satanı

Cümlesinin sarrafıdır birisi

O kalenin bedenine kuş konar

Kanadı üstünde kandiller yanar

Pir Sultan Abdal''ım secdeye iner

Aşık oldum gitmez benzim sarısı', 'Eğer dost ırmağın gözün ararsan Serçeşme''den gelir suyun durusu Ali Muhammet''tir Muhammet Ali İkisi de bir elmanın yarısı Ali''m engür ezdi k...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eger-dost-irmagin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekeyim De Eğleneyim Bir Zaman', 'ekeyim-de-egleneyim-bir-zaman-pir-sultan-abdal-shg9c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gurbet elde yad ellerin derdini

Çekeyim de eğleneyim bir zaman

Yaralı sineme bal ile tuzu

Ekeyim de eğleneyim bir zaman

Sılaya gönderdim gönül kuşunu

Seyredip gidiyor dağlar başını

Akıttığın gözlerimin yaşını

Dökeyim de eğleneyim bir zaman

Aşıp gider var mı bizim illeri

Yel ırgalar zülfündeki telleri

Dostlarımın göreceği yerleri

Gezeyim de eğleneyim bir zaman

Pir Sultan Abdal''ım Seyyit Nesimi

Destan etti şu illerde sesimi

Uğrun uğrun bir kenarda yasını

Tutayım da eğleneyim bir zaman', 'Gurbet elde yad ellerin derdini Çekeyim de eğleneyim bir zaman Yaralı sineme bal ile tuzu Ekeyim de eğleneyim bir zaman Sılaya gönderdim gön...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ekeyim-de-egleneyim-bir-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ela Gözlü Yardan Bize Gel Oldu', 'ela-gozlu-yardan-bize-gel-oldu-pir-sultan-abdal-l4yh3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ela gözlü yardan bize gel oldu

Varamam şu yerler yazlanmayınca

Hiç talip kalmadı ehl-i dil oldu

Gerçekler bilinmez izlenmeyince

Ali''yi sevenler ayan eylemez

Saklayıp sırrını beyan eylemez

Erenler nutkunu nihan eylemez

Muhabbet kurulup sözlenmeyince

Ali''yi sevenler gönül döşürür

Döşürür de aşk kazanın taşırır

Her mürşit çiğ talip mi pişirir

Ateş yakıp altı közlenmeyince

Pir Sultan Abdal''ım demek olur mu

Hercai dilbere emek olur mu

Rızasız lokmasın yemek olur mu

Mürşit nazarında tuzlanmayınca', 'Ela gözlü yardan bize gel oldu Varamam şu yerler yazlanmayınca Hiç talip kalmadı ehl-i dil oldu Gerçekler bilinmez izlenmeyince Ali''yi seven...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ela-gozlu-yardan-bize-gel-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emeğin Yite Mi Dersin', 'emegin-yite-mi-dersin-pir-sultan-abdal-l53yh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir aşkın deryasın boyla

Kıyısı öte mi dersin

Bir gerçeğe hizmet eyle

Emeğin yite mi dersin

Nadanı kondurma bağa

Düşürür seni tuzağa

Şekerler yedirsen sen zağa

Tuti olup öte mi dersin

Arifler yola giderler

İrfanda sohbet ederler

Nişansız yari n''ederler

Can gönül kata mı dersin

Bellidir kalbi boş olan

Nişan verendir hoş olan

Hercaiye yoldaş olan

Menzile yete mi dersin

Pir Sultan Abdal coşmayan

Aşk küresinde pişmeyen

İlkin Hakk''a ulaşmayan

Sonradan yete mi dersin', 'Bir aşkın deryasın boyla Kıyısı öte mi dersin Bir gerçeğe hizmet eyle Emeğin yite mi dersin Nadanı kondurma bağa Düşürür seni tuzağa Şekerle...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/emegin-yite-mi-dersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En İyi Dostundan Sakın Sen Seni', 'en-i-yi-dostundan-sakin-sen-seni-pir-sultan-abdal-s5cv7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir öğüdüm vardır sana söyleyem

En iyi dostundan sakın sen seni

Öğüdüm dinlersen manası budur

En iyi dostundan sakın sen seni

Gelir senin ile güler de oynar

Ardınca önünce ayıbın söyler

Bir vakit gelince önüne çıkar

En iyi dostundan sakın sen seni

Senin ile hüsnün bahçesin gezer

Gönül aşk elinden satırlar yazar

Ardınca önünce kuyular kazar

En iyi dostundan sakın sen seni

Gelir senden önce yükseğe çıkar

Gözlerinden kanlı yaşını döker

Ayağın kayınca urganın çeker

En iyi dostundan sakın sen seni

Pir Sultan Abdal''ım böyle söyledi

İndi aşkın deryasını boyladı

Bunu işlemeyen kula söyledi

En iyi dostundan sakın sen seni', 'Bir öğüdüm vardır sana söyleyem En iyi dostundan sakın sen seni Öğüdüm dinlersen manası budur En iyi dostundan sakın sen seni Gelir senin il...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/en-iyi-dostundan-sakin-sen-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erenler Kahretti Saldı İşkile', 'erenler-kahretti-saldi-i-skile-pir-sultan-abdal-mokmt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Erenler kahretti saldı işkile

Gönlüm şifalandı gümana geldim

Ali oğlu çare eyle müşküle

Sana mürvet ile amana geldim

Can evinde muhabbetim azaldı

Gönül aşkın deryasında yüzerdi

Yarelerim sağalmışken tazeldi

Gaziler derdime dermana geldim

Hak''tan kula her ne gelirse haktır

Erkansız işlere ırızam yoktur

Erenlerin lutfu keremi çoktur

Yarem sızıladı imana geldim

Himmet edin erler bir dahi yetem

Kalbimden şekkile şüphemi atam

Zat-ı sıfat olam bir dilden ötem

Bir desti tutmaya damana geldim

Pir Sultan Abdal''ım gör bize n''oldu

Ali''nin gülbengi bize zulm oldu

Muhabbet yurduna vesvese doldu

Sen bir padişahsın demana geldim', 'Erenler kahretti saldı işkile Gönlüm şifalandı gümana geldim Ali oğlu çare eyle müşküle Sana mürvet ile amana geldim Can evinde muhabbetim a...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/erenler-kahretti-saldi-iskile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erenlere Eş Olayım', 'erenlere-es-olayim-pir-sultan-abdal-4dcup', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erenlere eş olayım 

Bu yola yoldaş olayım 

İçeyim sarhoş olayım 

Aymak elinden gelir mi 

Alna yazılmış yazıyı

Besili körpe kuzuyu

Hakk''ın yazdığı yazıyı

Bozmak elinden gelir mi

Dere tepe dümdüz olur 

Gece geçip gündüz olur 

Gökte kaç bin yıldız olur 

Saymak elinden gelir mi 

Pir Sultan''ım der Hatayi 

Dilimiz söyler hatayı 

Pişmedik çiğ yumurtayı 

Soymak elinden gelir mi', 'Erenlere eş olayım  Bu yola yoldaş olayım  İçeyim sarhoş olayım  Aymak elinden gelir mi  Alna yazılmış yazıyı Besili körpe kuzuyu Hakk''ın ya...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erenlere-es-olayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünler Benim Yüreğimde Sevda', 'huzunler-benim-yuregimde-sevda-salih-ozalasan-ik70d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ağlama ben ağlarım senin yerine

Kıyamam bakmaya doyamadığım gözlerine

Aldırma sen benim sitem dolu sözlerime

Hüzünler benim yüreğimde sevda

Sevdalar yaşamak sevgiler yaşatmak içindir

Umutlar yüreğin tuzu biberi aşkın yemeğidir

Gidenler olmasa, gelenlerin kıymeti nasıl bilinir

Giden değil kalandır yüreğimde sevda

Y.Tarihi 03-10-2003 Saat 00.30

Salih ÖZALAŞAN', 'Sen ağlama ben ağlarım senin yerine Kıyamam bakmaya doyamadığım gözlerine Aldırma sen benim sitem dolu sözlerime Hüzünler benim yüreğimde se...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/huzunler-benim-yuregimde-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erler Himmet Edin', 'erler-himmet-edin-pir-sultan-abdal-z33te', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Banaz''dan sürdüler bizi Sivas''a

Erler himmet edin ben gidiyorum

Garipçe canıma kıldılar cefa

Erler himmet edin ben gidiyorum

Gidi kafir gelir dedim imana

Kuzular ağlıyor hem yana yana

Getirip de haps ettiler zindana

Erler himmet edin ben gidiyorum

Gidi dideceğim yoldan kalmadı

Güzel Şah''a gelir dedim gelmedi

Pirimizden bize himmet olmadı

Erler himmet edin ben gidiyorum

Urganım çekildi sığındım dara

Üstüme döküldü ağ ile kara

Muhbirim üstünde çıralar yara

Erler himmet edin ben gidiyorum

Pir Sultan Abdal''ım kolum büküldü

Aktı gözüm yaşı yere döküldü

Ahir urgan boğazıma takıldı

Erler himmet edin ben gidiyorum', 'Banaz''dan sürdüler bizi Sivas''a Erler himmet edin ben gidiyorum Garipçe canıma kıldılar cefa Erler himmet edin ben gidiyorum Gidi kafir geli...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/erler-himmet-edin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Erenler Çün Bu Sırrı Dinledim', 'ey-erenler-cun-bu-sirri-dinledim-pir-sultan-abdal-awujh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey erenler çün bu sırrı dinledim

Huzur-ı mürşide vardım bu gece

Hakikat sırrını andan anladım

Evliya merdanın gördüm bu gece

Mürşidim Muhammet buldum yolumu

Rehberim Ali''dir verdim elimi

Tiğbend ile bağladılar belimi

Erenler sırrına erdim bu gece

Erenler rahına eyledim iman

Kalmadı gönlümde şek ile güman

Ne bilir bu sırrı Yezid''le Mervan

Küll-i varım Hakk''a verdim bu gece

Andelip misali avaz ederek

Kati sema üzre pervaz ederek

Yedi aza ile niyaz ederek

Ayn-ı cem güllerin derdim bu gece

Pir Sultan''ım Hakk''a niyaz ederim

Erenler rahına doğru giderim

Küll-i varım Hakk''a teslim ederim

Hakk''ın cemalini gördüm bu gece', 'Ey erenler çün bu sırrı dinledim Huzur-ı mürşide vardım bu gece Hakikat sırrını andan anladım Evliya merdanın gördüm bu gece Mürşidim Muhamm...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ey-erenler-cun-bu-sirri-dinledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sofi Özüne Bir Muradım Var', 'ey-sofi-ozune-bir-muradim-var-pir-sultan-abdal-4h3p0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey sofi özüne bir muradım var

Elin günahını sen mi görürsün

Yüzün kara bir külhanda yerin var

Ali divanına nasıl varırsın

Rehberin kim olduğunu bilmezsin

Kov ile gıybeti elden koymazsın

Ahrette yatacak yer de bulamazsın

Toprak kabül etmez nerde kalırsın

Lokman sofusunu eli tutarsın

Hakk''ın döşeğine yere yatarsın

Bilmem yetmiş iki dilden ötersin

Sen bu dilin kangısını bilirsin

Pir Sultan Abdal''ım böyle olunca

İhlas talip muradını alınca

Devir dönüp halin ile gelince

Sen de bu huy ile murdar olursun', 'Ey sofi özüne bir muradım var Elin günahını sen mi görürsün Yüzün kara bir külhanda yerin var Ali divanına nasıl varırsın Rehberin kim olduğ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-sofi-ozune-bir-muradim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Yezit Sen Neden Yeldin', 'ey-yezit-sen-neden-yeldin-pir-sultan-abdal-yjvij', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey Yezit sen neden yeldin kastıma

Erdebil''de Şah Safi''den buyruğum

İlettin Urum''a çoban eyledin

Sırtımdaki alet midir çağlığım

Mağripten de çatal nurlar doğarsa

Mümin kula Hak rahmeti yağarsa

Hasan Hüseyin bana sahip olursa

Yanımdakine çok olur eyliğim

Ol İmam Zeynel''e merdan uyarsa

İmam-ı Bakır''dan içer ayarsa

İmam Cafer buyruğunu duyarsa

Anın için Hak yanında baylığım

Musa Kazım ciğerimi yakıyor

Irmaklar Cennet''te kevser akıyor

Aslımız İmam Rıza''ya çıkıyor

Muhammet Ali''ye vardır soyluğum

Taki Naki''ye iradet getirdiğim

Düldül oldum Şah Ali''ye götürdüm

Yöğrük oldum üç yaşında satıldım

Kimseler de bilmez benim taylığım

Pir Sultan Abdal''ım alır satarım

Askeri Mehdi''ye meyil katarım

Mansur olup şu cihanı atarım

Her ağaçta olmaz benim yaylığım', 'Ey Yezit sen neden yeldin kastıma Erdebil''de Şah Safi''den buyruğum İlettin Urum''a çoban eyledin Sırtımdaki alet midir çağlığım Mağripten de ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ey-yezit-sen-neden-yeldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felek Beni Nazlı Yardan Ayırdı', 'felek-beni-nazli-yardan-ayirdi-pir-sultan-abdal-9rdny', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne güzel de muradıma ererken

Felek beni nazlı yardan ayırdı

Ak gül kırmızı gül dererken

Felek beni nazlı yardan ayırdı

Kızardı kayalar don giydi dağlar

Yeşil yaprak ile bezendi bağlar

Yar ile sahraya çıktığım çağlar

Felek beni nazlı yardan ayırdı

Demir kafes idim doldum ıssıldım

Kurulu yay idim durdum kasıldım

Yemeden içmeden sudan kesildim

Felek beni nazlı yardan ayırdı

Yaz gelende yazı yaban yurt olur

Ak sürüye kara koyun kurt olur

Sevip sevip ayrılması dert olur

Felek beni nazlı yardan ayırdı

Pir Sultan Abdal''ım inem yarışam

Yarışam da ummanlara karışam

Başına gelmiş yok varam danışam

Felek beni nazlı yardan ayırdı', 'Ne güzel de muradıma ererken Felek beni nazlı yardan ayırdı Ak gül kırmızı gül dererken Felek beni nazlı yardan ayırdı Kızardı kayalar don g...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/felek-beni-nazli-yardan-ayirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felekler Zuhur Olalı', 'felekler-zuhur-olali-pir-sultan-abdal-n6fax', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Felekler zuhur olalı

Arttı derdim fizahım var

Günahım çoktur gamım yok

Mehdi gibi bir mahım var

Gayettir Ali''nin demi

İmam Hasan gevher kanı

Şah İmam Hüseyin gibi

Muallakta dergahım var

İmam Zeynel leyl ü nehar

İmam Bakır kırdı küffar

Mehr içinde İmam Cafer

Şemsi gibi bir mahım var

Musa-yı Kazım''a düştük

Ali Rıza''ya eriştik

Muhammet Taki''den içtik

Türlü türlü kadehim var

Pir Sultan''ım Naki candır

Askeri dindir imandır

Mehdi sahib-i zamandır

Mürvetli padişahım var', 'Felekler zuhur olalı Arttı derdim fizahım var Günahım çoktur gamım yok Mehdi gibi bir mahım var Gayettir Ali''nin demi İmam Hasan gevher kanı...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/felekler-zuhur-olali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fetva Vermiş Koca Başlı Kör Kadı', 'fetva-vermis-koca-basli-kor-kadi-pir-sultan-abdal-hsgxx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fetva vermiş koca başlı kör kadı

Şah diyenin dilin keseyim deyü

Satır yaptırmış Allah''ın laneti

Ali''yi seveni keseyim deyü

Şen kulların örüğünü uzatmış

Müminlerin baharını güz etmiş

On ikiler bir arada söz etmiş

Aşıkların yayın yaşayım deyü

Hakk''ı seven aşık geçmez mi candan

Korkarım Allah''tan korkum yok senden

Ferman almış Hıdır Paşa sultandan

Pir Sultan Abdal''ı asayım deyü', 'Fetva vermiş koca başlı kör kadı Şah diyenin dilin keseyim deyü Satır yaptırmış Allah''ın laneti Ali''yi seveni keseyim deyü Şen kulların örüğ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fetva-vermis-koca-basli-kor-kadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firdevs-i Ala', 'firdevs-i-ala-pir-sultan-abdal-m4s7q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Firdevs-i Ala''da bir yanal elma

On sekiz bin ilmin nuru dediler

Muhammet Mustafa Haydar-i Kerrar

Hünkar Hacı Bektaş Veli dediler

Çocuktu mektebe babası götürdü

Elif be demeden mana yetürdü

Akıttı pınarı susam bitürdü

Hacısı hocası beli dediler

Pirim der ki Bektaşiyim Bektaşi

Size nasip veren ol nasıl kişi

Sıkar un ederdi örk gibi taşı

Budur cümlemizden ulu dediler

Derildi geldiler halfeler pirler

Bektaşi namında er yok dediler

Bize bir yeşil el nasip verdiler

Görünce tanırız eli dediler

Er isen darı çeç üstünde otur

Ulu kişi isen maksudun bitir

Senedin var ise senedin getir

N''edelim senetsiz eli dediler

Kimi inandı beli bes dedi

Kimi inanmadı senet istedi

Ol Şah''ım anlara elin gösterdi

Budur ol Şah''ımız Ali dediler

Evvel Ali idi sonra Vel''oldu

Yol erkan bir zaman batında kaldı

Urum ellerinden nameler geldi

Budur Hakk''ın doğru yolu dediler

Pir Sultan Abdal''ım Şah''ım velidir

Cihanı bürüyen anın nurudur

Şüphemiz yok Hak Muhammet Ali''dir

Bilmeyene Mülcem soyu dediler', 'Firdevs-i Ala''da bir yanal elma On sekiz bin ilmin nuru dediler Muhammet Mustafa Haydar-i Kerrar Hünkar Hacı Bektaş Veli dediler Çocuktu mek...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/firdevs-i-ala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firdevs-i Ala İçinde', 'firdevs-i-ala-i-cinde-pir-sultan-abdal-tf15g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tarikate ikrar verdim

Lanet Yezit''ten el yudum

Muhammet Ali''yi gördüm

Firdevs-i ala içinde

Allah bir Muhammet haktı

Rehberim kemendi taktı

Çekti pire teslim etti

Firdevs-i ala içinde

Pirden nasihatı aldım

Ben belimi bağlı gördüm

Kendimi Mirac''da buldum

Firdevs-i ala içinde

Ben kutlu postuma geçtim

Sekahüm şerbetin içtim

Ol saat kıl-kalden geçtim

Firdevs-i ala içinde

Didar defterine geçtim

Münkir münafıkı seçtim

Mezhebde Cafere düştüm

Firdevs-i ala içinde

Mehdi''ye vardır niyazım

İmamlara bağlı özüm

Şükür didar gördü gözüm

Firdevs-i ala içinde

Pir Sultan''ım dünya fani

Bizdedir Hakk''ın nişanı

Hakk''a kurban verdim canı

Firdevs-i ala içinde', 'Tarikate ikrar verdim Lanet Yezit''ten el yudum Muhammet Ali''yi gördüm Firdevs-i ala içinde Allah bir Muhammet haktı Rehberim kemendi taktı Ç...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/firdevs-i-ala-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Henüz Aşka Doymadık', 'henuz-aska-doymadik-hayati-yavuzer-v7vm4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adına aşk denilen o ezeli cevheri

Tadarız her saniye bezm-i elest''ten beri

Kanımızda dolaşır, işlemiş zerremize

Hiçbir aşık doymadı, usanmadı hiçbiri

Ey ecel unut bizi, henüz aşka doymadık

Sevdalı başımızı bir yastığa koymadık

İçimiz hâlâ taze, dışımız solgun bir yüz

Bağdaş kurmuş oturmuş bahtımızda sultan güz

Can Meleği elinde ilahi bir fermanla

Dolaşır peşimizde durmadan gece gündüz

Ey ecel unut bizi, henüz aşka doymadık

Sevdalı başımızı bir yastığa koymadık

(2 Ekim 2003 /İstanbul)', 'Adına aşk denilen o ezeli cevheri Tadarız her saniye bezm-i elest''ten beri Kanımızda dolaşır, işlemiş zerremize Hiçbir aşık doymadı, usanmad...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/henuz-aska-doymadik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetime Estin', 'gurbetime-estin-hayati-yavuzer-r1pin', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar gibi gelip geçtin ömrümden

Sancısı çekilen her mısraya

Doğan her şarkıya kendini söylettin

Ipılık bir meltemdin düşlerimde

Can bahşeden bir nefestin

Sonra poyrazlaştın, karayel oldun

Gurbetime estin

Soldu aşk, yaprağında sonbaharın

Düştü umudun kanatları mecalsiz

Göklere çekildi yağmurlar

Artık masallara damlamıyor ay

Sevdamıza gülümsemiyor deniz

Sen içimde  dinmeyen bir sestin

Yıllar boyu solmayan hevestin

Bir keskin vedayla bölündü rüya

İflahımı kestin

(30 Eylül 2003/İstanbul)', 'Bir rüzgar gibi gelip geçtin ömrümden Sancısı çekilen her mısraya Doğan her şarkıya kendini söylettin Ipılık bir meltemdin düşlerimde Can ba...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gurbetime-estin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayda', 'hayda-umut-yalim-6eat2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölenler yüreklerinden öldüler

Gülenler hep yüreklerinden

Bilmedikleri topraklara gömüldüler

Sürülenler topraklarından

Aktı incirlerin hep süt ağlakları

İnsanlar baktılar büyük elleriyle

Ördüler gözlerine gözkapakları

Sustular hep büyük dilleriyle

Gözlerimiz kapanmamalı ölsek de

İzlemeliyiz göğü bize bakan çocuğu

Belki gözlerimiz çember olmalı eline

Vermeliyiz ölsek de hep varı yoğu

Oynamalılar başımızda öldüğümüz yerde

Çevirmeliler gözlerimizi görebilmekçin evreni yeniden

Yenilen halkları tekrar güldürebilmekçin gözlerimizle

Gözlerimiz ki özünde hep halkların gözleri

Sözleri bir türlü söyleyemedikleri ama yinelenen

Ellerimizde karanfiller olmalı ellerimizde açan yeniden

74 nisanından Portekiz''in İspanya'' nın 36 yazından

Göğüslemeliyiz biz Lorka'' ya atılan kurşunu

Kuşunu Nazım'' ın penceresinden uçan

Biz beslemeliyiz yokluğundan özgürlüğün.

Kapanmamalı yüreklerimiz sevmesek de

Çünkü bizim sevdamız '' Onlar'' ın sevdası 

Sevdamız Aragon Neruda Mayakovski''nin sevdası

Bizim sevdamız bizle sevdalananların sevdası

Bizle sevdalanamayanların uzun geniş yarası

Gözlerimiz kapanmamalı ölsek de

İzlemeliyiz bizi izleyen çocuğu

Çocuğu izleyen karışık göğü

Göğü izleyen katar kuşları

Kuşları izleyen insanları

İnsanları bekleyen hürlüğü

Hürlüğü isteyen sevdayı

Sevdayı isteyen mavi alı

Gözlerimiz izlemeli ölsek de

59'' da Küba'' da olan oğlanları 

Kızları gözlerine ağır menveşlerle

İşledikleri 917''yi 922''sini Kemal''in

Ve halkları... Severcesine ölenlerin

Gözlerimiz kapanmamalı ölsek de

Görmeliyiz bizden öncekini gelecek olanı

Gözlerimizi gözkapaklarımıza örmeliyiz

Sürmeliyiz  yüreklerimizi gözlerimize

Birini severek ölmeliyiz yattığımız yerden

Düşünmeden yattığımız yeri yeniden

Ölenler hep yüreklerinden öldüler

Gülenler hep yüreklerinden

Bilmedikleri topraklara gömüldüler

Sürüldükleri topraklardan

Baktı zincirlerin değmeyen

Özgür yanları ellerine

İnsanlar ki insanlarla insan kadar alakadar

Yaktı boyun eğmeyen

Özgür kanları ellerini

Haydaaaa karanfilleri dillerini...

                                2003', 'Ölenler yüreklerinden öldüler Gülenler hep yüreklerinden Bilmedikleri topraklara gömüldüler Sürülenler topraklarından Aktı incirlerin hep sü...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/hayda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrildik', 'ayrildik-diyarbakirli-mehmet-0w4n5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrildik iste bebegim sonunda 

Hüsranla bitti bak bu sevdada 

Askimiz yenik düstü hasrete karsi bu savasta

Isgala ugradi yüregim sarayinda 

Boyun büktü seni benden alanlara 

Simdi aciyorum kendime 

Sararken sen diye sim siki yastigi bagrima

Engel olamiyorum gözümden akan yaslara 

Hani eskiden yaptigin gibi agladigimda 

Usulca sokulup yanima 

Silerdin akan yaslari yanaklarimdan 

Aglama canim deyisin yetiyordu bile bana 

Ama simdi dört duvar arasindayim tek basima 

Kimseler yok yanimda 

Ariyorum seni her an 

Aldigim nefeste saniyorum bazen seni 

Kaliyorum o an soluk soluga 

Baktigim her yerde BELKI SEN orada

gizlenmis beni seyrediyorsun umuduyla 

Ariyorum seni her an 

Dinledigim sarkilarda 

Yazdigim siirlerde 

Kagidimda kalemimde 

Özledim seni bebegim neredesin 

Alisamadim ben senin yokluguna 

Ne olursun ne olursun geri dön bana', 'Ayrildik iste bebegim sonunda  Hüsranla bitti bak bu sevdada  Askimiz yenik düstü hasrete karsi bu savasta Isgala ugradi yüregim sarayinda  ...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakirli Mehmet']::text[], 8.5, '{"poet":"Diyarbakirli Mehmet","poet_slug":"diyarbakirli-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ayrildik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tren bana ninni söyledi', 'tren-bana-ninni-soyledi-aysenur-yazici-xhha1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günler üstüme üstüme gelirken

Ankara çağırdı birden! 

bir tren kucağına alıp beni

gece boyu ninni söyledi

....pencereden akıp gitti Istanbul..

..gündüz elini geceye verdi...

raylarda sitem

uyku seslerine biraktım gözlerimi

çocukluğum, gençkızlığım   pencereden geçti..

ağaçlar, yıldızlar, senelerim...

tren koynunda avuttu yüreğimi

...salladı..salladı..başımı sevdi! 

'' yollardan uçur '' dedi, 

'' uçur seni inciten herşeyi '' 

başını koy , tıkırtılarımda

saracağım kabuğu düşmüş

suçiçeği izlerini...

ağrılarında başucunda beklemeyen

sahte sevgililerini ben kovacağım 

güvercin yuvalarından! 

sen gönlündeki yumurtaları sakla, 

ben ısıtacağım

koltukaltlarımda...

tam senin başını koyduğun yerde

sana ''umutlar'' çıkaracağım

kabukları kırmadan.

gel düşlerinin kucağına

ben götüreceğim seni.

hıçkırıkların olmayacak artık.

sıtmaların, koleraların..

zalim aşkların

toz olacak raylarımda.

hepsini kovacağım

uyu...uyu kollarımda 

'' sen başını bana yasla '' dedi tren

ben ana kucağı, ben huzur boşluğu

sen sadece tıkırtılarımda uyu! 

tren sağaltıyor beni

ben bir fındık kabuğu, tren bir dalgalı deniz...

...sahi siz...

...trene en son ne zaman bindiniz? 

                         24.09.2003

                         Ankara

                          (17:30)', 'Günler üstüme üstüme gelirken Ankara çağırdı birden!  bir tren kucağına alıp beni gece boyu ninni söyledi ....pencereden akıp gitti Istanbul...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/tren-bana-ninni-soyledi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Bir Rüzgar', 'kor-bir-ruzgar-sule-aydemir-q3pu2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zaman döndü değdi yaşamı yaktı

çılgın bir suskunluk bağrına bastı

ağırlığında tutulmaz deli aşktı

bu sebep herkes nazarlı baktı

kurudu gökte kör bir rüzgar aşk asıldı

ASlı kaldı', 'zaman döndü değdi yaşamı yaktı çılgın bir suskunluk bağrına bastı ağırlığında tutulmaz deli aşktı bu sebep herkes nazarlı baktı kurudu gökte...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kor-bir-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uslanmaz Aşık', 'uslanmaz-asik-tulay-sustam-qs02w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben delinin biriyim

Kolay kolay yola gelmem

Darbeler alırım, tövbe ederim

Yine aynı şeyleri yaparım

Ders almam geçmişten

Acıları yinelerim

Kısır döngü misali hayatım

Dönüp dolaşıp aynı şeyleri yaşarım

Aşktan yaralar alırım

Kendi yaramı merhem niyetine kendim sararım

Kimseden saklayamam sevdamı

Uslanmaz aşığım ben

Aşksız yapamam bak yine aşığım

(02.10.2003 Perşembe İstanbul)', 'Ben delinin biriyim Kolay kolay yola gelmem Darbeler alırım, tövbe ederim Yine aynı şeyleri yaparım Ders almam geçmişten Acıları yinelerim K...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uslanmaz-asik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bilmecesi', 'ask-bilmecesi-tulay-sustam-28jfj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben kaç kere aşık oldum biliyor musun? 

Bir keresinde sevdim ama sevilmedim

Sonra sevildim ama sevmedim

Sonunda bende sevdim, sevildim 

Bil bakalım ben kaç kere sevdim? 

Ben hiç aşık olmadım desem inanmayacaksın

Zaten sana yalan söylemiş olurum

Hiç aşık olmasaydım yazar mıydım bu satırları

Yaz gelmeden yaşar mıydım sonbaharı

Söylesene dostum sence ben kaç kere sevdim

İnsan bir kere sevmeli dostum bir kere

O da her şeyiyle ölümüne sevmeli

Ben bu hakkımı kullandım 

Benden geçti artık ben sıramı sana verdim

(02.10.2003 Perşembe İstanbul)', 'Ben kaç kere aşık oldum biliyor musun?  Bir keresinde sevdim ama sevilmedim Sonra sevildim ama sevmedim Sonunda bende sevdim, sevildim  Bil ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-bilmecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asi Kız', 'asi-kiz-tulay-sustam-ghare', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Candostum Şebo''ya; 

Asilik ruhumda var benim damarıma kimse basmasın

Sevdim mi ölümüne severim, sildim mi bir kalemde

Biri dostumsa benim ölümüne bir ben gibi severim

Kimse düşmanım olmasın gölge misali peşindeyim.

Deliyim, doluyum asi bir kızım 

Ben her yerdeyim, herkese yardım ederim

Dostum çağırırsa beni iki elim kanda olsa giderim

Aslında ela gözlü benli dilberim

Kendimle barışığım bir o kadar da güzelim

Kimse ilk gördüğünde sevmez beni

Biraz ukala, biraz sivri dilliyim

Doğrularım, yanlışlarım var bildiğimden hiç şaşmam

Aldım mı bir karar kimsenin gözünün yaşına bakmam

Ben ne dostsuz ne de aşksız yapamam

Asi bir kızım herkes beni böyle bilsin

İsteyen sevsin, istemeyen sevmesin

Benim herkese gönül kapım açık 

İsteyen kapıdan içeri girsin, istemeyen girmesin

Asi bir kızım beni seven bu halimle sevsin.

(30.09.2003 Salı İstanbul)', 'Candostum Şebo''ya;  Asilik ruhumda var benim damarıma kimse basmasın Sevdim mi ölümüne severim, sildim mi bir kalemde Biri dostumsa benim öl...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/asi-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyorum Seni', 'yasiyorum-seni-muammer-celik-42jvp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Pul pul yasıyorum  sen

denizin köpüren dalgalarıyla 

bahardaki ağaç yapraklarıyla 

güzde döküyorum seni 

tekrar agaç dölleriyle ekiyorum 

içime tohum tohum seni... 

Renk renk yaşıyorum seni 

ebemkusağının tonlarında 

şelalede su damlacıklaryla 

gölümde ıslatıyorum seni 

yosunların yeşile karışan 

mavileri arasında öpüyorum

düş bulutlarımda yaşıyorum... 

İnci inci işliyorum içime seni 

halıdaki motif ilmeklerinde 

çöldeki pırıl pırıl kumlarda 

doku doku dokuyorum seni 

şiirlerde, misralarda yaşıyorum 

dize dize dizelere diziyorum seni...

(doğum tarihi bilinmeyenlerden)

BirDeli', 'Pul pul yasıyorum  sen denizin köpüren dalgalarıyla  bahardaki ağaç yapraklarıyla  güzde döküyorum seni  tekrar agaç dölleriyle ekiyorum  iç...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasiyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık', 'artik-aylin-aydin-y7cg7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tesadüfü yaklaşımların artığısın sen

artık diyorsam, öyle kokuşmuşluk değil, 

Bitirilmişlik belki, belki başlanılamamışlık

Yani adının duyulduğu anda boğaza yerleşen ve 

hiç yüreğe inememiş o  boğum boğum maddecilik

maddeyle ilişkilisin kanımca daha çok 

aşkın parlak, sevgin dekoratif

tutku rengin gözalıcı

gönül alıcı

ten alıcı

alıcı kuşların  unutkanlığını getiriyor akla

sesindeki her tını…

yani diyeceğim, 

şehirlerarası yollarda

 tesadüfü otellerde barınmak gibi senin olmak

son hızla giderken birden yorulduğunu hissedip 

gözlerini kapama arzusundaki tesadüfü karşılaşma

neon ışıklarındaki cazibe

yatağı vasat

 içkisi vasat 

azığı vasat konuk odası.

Senin olmak, hem olmak hem olamamaktı aslında.

Ekim,03', 'Tesadüfü yaklaşımların artığısın sen artık diyorsam, öyle kokuşmuşluk değil,  Bitirilmişlik belki, belki başlanılamamışlık Yani adının duyul...', ARRAY['Türk Edebiyatı','Şiir','Aylin Aydın']::text[], 8.5, '{"poet":"Aylin Aydın","poet_slug":"aylin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/artik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemimsin', 'ozlemimsin-i-brahim-cagri-saglik-qb36u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimde açılır derin bir yara

Bırakıp giderken ardımda seni

Kaçınçı kez düşüşüm şu yollara

Gözüm dumanlanır öperken seni

Gide gele ezberledim yolları 

Dakikaları saydım ardı sıra

Amaçsız edilen yol kelamları

Hüzün çokça, sevinç arasıra

Hasretin bitmez, yanımdayken bile

Gülüşün, bakışın her dem aklımda

Buldukları en ufak bir vesile

Gözlerim arar seni hep karşımda', 'Kalbimde açılır derin bir yara Bırakıp giderken ardımda seni Kaçınçı kez düşüşüm şu yollara Gözüm dumanlanır öperken seni Gide gele ezberled...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlemimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başka', 'senden-baska-muammer-celik-mo3yb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üfle bir defa

aşk gemimin yelkenine 

bir defa üfle 

bir nefes olsun üfle 

içinde fırtına estiren

sevda yelinden… 

Usulca, usulca 

bir tut bu adamın elinden… 

Kalmadı artık 

kürek çekecek dermanı 

ama gönül bu işte, kahretsin 

dinlemiyor gayri ne beni, nede fermanı…! 

Fırtına öncesi sessizikleri 

fırtına sonrası sensizlikleri 

çooook yaşadı bu aciz gönül

Issız adalar bile 

suya gömüldü 

gözlerimin yaşında 

Gidecek yeri yok

olmadı da 

eyyyy sevgili, 

senden başka 

limanı bu geminin…! 

15.05.2003

BirDeli', 'Üfle bir defa aşk gemimin yelkenine  bir defa üfle  bir nefes olsun üfle  içinde fırtına estiren sevda yelinden…  Usulca, usulca  bir tut bu...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/senden-baska-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık', 'isik-aylin-aydin-eyzm5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Asılsız bir kederin var 

Senin olmayan acıları tutuyorsun ellerinde

Bir de ucuna taktığın gözlerinin

Çipil çipil gözyaşı modelleri 

İnan ki her sahnede takdire değersin…

İnan ki yürekten alkışlıyorum seni…

Ama in artık o sahneden

Birazdan karanlıkta kalacaksın.

Ekim,03', 'Asılsız bir kederin var  Senin olmayan acıları tutuyorsun ellerinde Bir de ucuna taktığın gözlerinin Çipil çipil gözyaşı modelleri  İnan ki ...', ARRAY['Türk Edebiyatı','Şiir','Aylin Aydın']::text[], 8.5, '{"poet":"Aylin Aydın","poet_slug":"aylin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/isik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hediye', 'hediye-aylin-aydin-8abdu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Büyük büyük aşklar hazırladım 

Kucak dolusu

Yürek dolusu

Ağız dolusu

Taşıyamayınca adamlar

Küçük küçük parçalara böldüm.

Şimdi herkes mutlu. 

Ekim,03', 'Büyük büyük aşklar hazırladım  Kucak dolusu Yürek dolusu Ağız dolusu Taşıyamayınca adamlar Küçük küçük parçalara böldüm. Şimdi herkes mutlu....', ARRAY['Türk Edebiyatı','Şiir','Aylin Aydın']::text[], 8.5, '{"poet":"Aylin Aydın","poet_slug":"aylin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hediye-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadeh Şarapla İçtim Seni', 'bir-kadeh-sarapla-i-ctim-seni-muammer-celik-jha18', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hapsettim düşüncemi 

loş bir ışığa, 

gömdüm duygularımı 

tınsız bir sessizliğe... 

şömünenin önünde 

aşkın kıpkızıl ateşiyle

Okşadım önce aşk pirini

bir kadeh şarapla

içtim sensizliğin zehrini…! 

2002

BirDeli', 'Hapsettim düşüncemi  loş bir ışığa,  gömdüm duygularımı  tınsız bir sessizliğe...  şömünenin önünde  aşkın kıpkızıl ateşiyle Okşadım önce aş...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-kadeh-sarapla-ictim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyhude Yaşam', 'beyhude-yasam-i-brahim-cagri-saglik-aek8a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendimi şu dünyada bildim bileli

Akıp gitti zaman, durduran olmadı

Yaşamı sonsuz gibi benimseyeli

Küçük mutlulukların tadı kalmadı

Kimseler bilemiyor son nefes nerede

Bunca ehl-i kabiri hatırlayan yok.

Sanki umutlar hep başka seherde

Seherleri bitirip çekip giden çok

Beyhude bu yaşam, bak geldi geçiyor

Geriye ne kaldı yılların ardından

Gençliğin baharı elden gidiyor

Ne farkı var saçların, güz yaprağından

Bilirim bu günlerde çabuk geçecek

Binlerce nesile tanık olan zaman

Bu saç, sakala da aklar düşürecek

Anladım artık gerçek, külliyen yalan', 'Kendimi şu dünyada bildim bileli Akıp gitti zaman, durduran olmadı Yaşamı sonsuz gibi benimseyeli Küçük mutlulukların tadı kalmadı Kimseler ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beyhude-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimce Nazlandım', 'kendimce-nazlandim-muammer-celik-fmx0y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendimce sevdim seni

en az kendim kadar 

hatta kendimden fazla… 

sevdim yıkıldıkça umutlarım 

en az umutlarım kadar 

hatta kendinden fazla… 

Biraz nazla, 

biraz da hırsla...! 

Her aksam küstüm sana 

hiç bir gece yoksun diye… 

Her sabah uyandım 

gözlerimde yeni bir umutla 

her gün batışıyla 

daha çok sevdim seni

senden biraz daha fazla

daha cok sarıldım yokluğuna 

biraz nazla 

biraz da öfke ile…! 

Kendimce okşadım 

kendimce özledim 

kendimce sevdim

kendime hırslandım

birazda nazlandım hani…! 

13.05.2003

BirDeli', 'Kendimce sevdim seni en az kendim kadar  hatta kendimden fazla…  sevdim yıkıldıkça umutlarım  en az umutlarım kadar  hatta kendinden fazla… ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kendimce-nazlandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-nalan-kazazoglu-sotir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Islak kokulu toprak

Koluma değen yaprak

Aynı denizle gök

Deniz durur gökte

Göğün yüzü denizde

Takıldı gölgeme

Yürüdü geldi benimle

Benim gözüm güneşte

Sırtımda sımsıcak..', 'Islak kokulu toprak Koluma değen yaprak Aynı denizle gök Deniz durur gökte Göğün yüzü denizde Takıldı gölgeme Yürüdü geldi benimle Benim göz...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/golge-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haiku dünyam', 'haiku-dunyam-serkan-dogan-p8r57', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gelmeyecek ama

hatırlamayacak da

kederlerini

.................

İstanbul’dayım

gerçek bir cennet şimdi

benim toprağım

.................

kopar çiçeği

uzat yetiştirene 

borcun bitmiştir

.................

kaçamaz benden

hiçbir hüzün fırsatı

bunalımdayım

.................

telefonu aç

cevap versene bana

neden evdesin

.................

çarpıtmak değil

fikirlerini asla

ölçmek amacım

.................

sporla geçti

korkunçtu askerliğim

bir o kadar mat

.................

seni seyrettim

çırılçıplaktın yine

uykudaymışım

.................

lirizmden de öte

bir şeyler var şiirde

nasıl anlatsam

.................

süpersin yahu

nasıl attın o golü

ulaşılmazdı

.................

sutram nerede

budist mi oluverdim

güz gelince

.................

sorularımdı

yanıtlanmadı, gerçek

kuşku götürmez.

.................

gece koşusu

yaprak döken mevsimde

yatıya kaldım

.................

yaptığın azap

bil ki sen ey sevgilim

yanına kalmaz

.................

aynayla doğan

koridora açılan

beyaz kanattım

.................

isyan ve hüznün

kol gezmekte olduğu

yollarıma gel

.................

görece yarim 

ver sevecenliğimi

geri ver hemen

.................

sis koridorum

kubbemsi ve siyahtır

ve yalazlanmaz 

.................

hayal dünyamın

korteksinde yaşandı

anlattıklarım

.................

akşamdan kalmış

bezginler meyhanemde

uçuk kaçıktım

.................

ne alırsınız

çay, kahve, kola

veya sıkıntı suyu

.................

ayartma vakti 

geldi dünyanın

boğazın ardındaki 

.................', 'gelmeyecek ama hatırlamayacak da kederlerini ................. İstanbul’dayım gerçek bir cennet şimdi benim toprağım ................. kopar...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/haiku-dunyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıfatlar tüketiyor hayatı', 'sifatlar-tuketiyor-hayati-arzu-dincer-6liz2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatın sıfatları, 

Çelik kapılar örüyor...

Uzansan tutabileceğin

Cennet misali 

Şu dünya’da!', 'Hayatın sıfatları,  Çelik kapılar örüyor... Uzansan tutabileceğin Cennet misali  Şu dünya’da!...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sifatlar-tuketiyor-hayati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Dersin Doktor?', 'ne-dersin-doktor-mine-ozdemirtas-9igr5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tecrübelerin kadar donanımlı mısın  Doktor? 

Bu bendeki; Kara Sevda.

Nefes alırken bile boğuluyorum. Diyorum ya? 

Ciğerlerime tıka basa aşk dolmuş.

Araya bir de; Vuslattan yana fukaralık girince, 

Bu illete yenik düştüm iyice.

Ateşler içinde yanıyor ve kıvranıyorum ya? 

Umudu koymadan önce çaresiz ellerime

İyi düşün. Güveniyor musun reçetene.? 

Yüreğin kadar cesur musun Doktor? 

Bu bekleme devresi; bittiğinde, 

“Birlikte başardık işte”

Diyebilecek misin? / bakarak gözlerime? 

Yoksa; o gün geldiğinde; 

İkimiz de   / Eğip başımızı öne, 

Teslim mi olacağız kadere? 

03/10/2003 Çamlıca.', 'Tecrübelerin kadar donanımlı mısın  Doktor?  Bu bendeki; Kara Sevda. Nefes alırken bile boğuluyorum. Diyorum ya?  Ciğerlerime tıka basa aşk ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-dersin-doktor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Ölüm Bir Doğumdur.', 'her-olum-bir-dogumdur-murat-tali-k51pl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'her ölüm bir yalnızlıktır

bu yüzden hıçkırır yürek

bu yüzden akar gözlerden yaşlar

her ölüm bir terkediştir

bu yüzden nefesler tutulur 

bu yüzden sancır düşünceler

her ölüm bir yitikliktir

bu yüzden sarıdır rengi

bu yüzden karalara bürünür

her ölüm bir boyun bükmedir

bu yüzden susuz kalır mevsimler

bu yüzden kurur nehirler

her ölüm bir doğumdur

bu yüzden sevinci sadece ölen yaşar

bu yüzden beyaz mermerler dikilir

beyaz aydınlıklara girmemiş 

bedenlere.', 'her ölüm bir yalnızlıktır bu yüzden hıçkırır yürek bu yüzden akar gözlerden yaşlar her ölüm bir terkediştir bu yüzden nefesler tutulur  bu y...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/her-olum-bir-dogumdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değersiz', 'degersiz-hakki-hakan-kaya-vpgt5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir değersize değer verdim, 

