INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçardın Gözümden', 'kacardin-gozumden-safure-yildirim-lfbz3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ürkek serçe misali bakışın

bir konar bir kaçardın gözümden.

gittiğin heryerde

dal oldu yüreğim

damar damar ayaklarının dibine, 

sevemedim, doya doya

tutamadım elinden.

uçup gitsen de

uçsuz bucaksız göğün

en açık renginde

özgürlüğün en koyu deminde

sevginle sarhoş, 

aşksız bomboş gönlüm

seninle, yalnız sana tutunur, 

senle uçar kanatlarının altında

göğsüne en yakın yerde..

ilkim 17.9.03', 'ürkek serçe misali bakışın bir konar bir kaçardın gözümden. gittiğin heryerde dal oldu yüreğim damar damar ayaklarının dibine,  sevemedim, d...', ARRAY['Türk Edebiyatı','Şiir','Safure Yıldırım']::text[], 8.5, '{"poet":"Safure Yıldırım","poet_slug":"safure-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kacardin-gozumden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma Ki', 'sanma-ki-safure-yildirim-9kdlt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sanma ki gittiğinde

kurur gözpınarlarım, 

kesilir can damarlarım

seni unutamam kapanır tüm yollarım, 

sanma ki gittiğinde, 

hazan gelir günlerime, 

yas çöker yüreğime, 

sen olursun hep dilimde

sen merkezinde dolanırım, 

sanma ki gittiğinde, 

çiçek açmaz menekşelerim, 

kokusuz kalır fesleğenlerim, 

tüm filizlerim kurur sensizlikten, 

dikenleşir yeşermişlerim, 

sanma ki gittiğinde, 

duman kaplar her yanımı, 

karanlığında boğulurum, 

sanma ki, sen yoksan

kimse olmaz yanımda

tek başıma kaybolurum..

sanma,

sanma ki,

ben yalnız  seninle varolurum!..

yoksan ben kahrolurum..

sanma

sanma!

İnan o zaman ben, tam ben olurum!

ilkim... ağus.2003', 'sanma ki gittiğinde kurur gözpınarlarım,  kesilir can damarlarım seni unutamam kapanır tüm yollarım,  sanma ki gittiğinde,  hazan gelir günl...', ARRAY['Türk Edebiyatı','Şiir','Safure Yıldırım']::text[], 8.5, '{"poet":"Safure Yıldırım","poet_slug":"safure-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sanma-ki-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-umut-yalim-gtcsz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belki gözlerin

Elişinden sözlerin

Kağıt parçasına bir

Güzelliğin güzel

Az önce yazdığın gazel

Kağıt parçasına bir

Sevmek seni 

Su içerken susamak gibi

Kağıt parçasına bir

Ama belki seni sevmek

Sevmek değildir

2003', 'Belki gözlerin Elişinden sözlerin Kağıt parçasına bir Güzelliğin güzel Az önce yazdığın gazel Kağıt parçasına bir Sevmek seni  Su içerken su...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/belki-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçgen', 'ucgen-sair-celebrian-f6ivc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensizlik, çaresizlik

Ve elbetteki aşk.

Kenarlar eşit, 

Toplam açı 180. 

Gel de çık şimdi işin içinden

Çıkabilirsen…', 'Sensizlik, çaresizlik Ve elbetteki aşk. Kenarlar eşit,  Toplam açı 180.  Gel de çık şimdi işin içinden Çıkabilirsen…...', ARRAY['Türk Edebiyatı','Şiir','Şair Celebrian']::text[], 8.5, '{"poet":"Şair Celebrian","poet_slug":"sair-celebrian","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ucgen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönenç', 'donenc-umut-yalim-s9iea', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben hiç elma yemedim ki

Peki nerden biliyorum tadını elmanın

Uzun yatmışlığım duvarlarında damların

Ben hiç suç işlemedim ki

Neden korkuşum bu beyaz karanlıklardan

Işığım kitlenmedi ki hiç

Belirsiz alları daha da alları sevişim

Sevişim seni belli belirsiz neden

Ben seni hiç sevemedim ki

2003', 'Ben hiç elma yemedim ki Peki nerden biliyorum tadını elmanın Uzun yatmışlığım duvarlarında damların Ben hiç suç işlemedim ki Neden korkuşum ...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/donenc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet''e Alistik', 'gurbet-e-alistik-guner-kaymak-c2r7a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yillar oldu gurbet ele geleli

Gurbet bize biz gurbete alistik

Her bayramda buruk sevinc yasadik

Huzun bize biz huzune alistik

Anadan babadan yardan ayrildik

Her birimiz bir tarafa savrulduk

Beyhude dolandik bosa yorulduk

Cile bize biz cileye alistik

Umut besledik gelecege yarina

Goz diktik su dunyanin malina

Cogumuz aldirmadi sagligina canina

Dertler bize biz dertlere alistik

Gece gunduz para icin calistik

Evlendik coluk cocuga karistik

Kah dovustuk darildik kah baristik

Onlar bize biz onlara alistik

Her sene izine gayret ettik ayrildik

Sila yolunda eza cektik yorulduk

Kendi vatanimizda''da alamanci gorulduk

Gariplik bize biz gariplige alistik

Bulundugumuz her yeri islah eyledik

Is yerleri acip ticareti denedik

Kirkpinari getirip avrupa''ya tasidik

Gures bize biz gurese alistik

Anadilimiz icin cok ugraslar verdik

Oz dillerini cocuklarimiza ogrettik

Kulturumuzden zerre taviz vermedik

Tarih bize biz tarihe alistik

Milli maclara her bir yandan kosturduk

Heyecanla sevkle millileri costurduk

Avrupalilari gollere bogduk susturduk

Galibiyet bize biz galibiyete alistik

Gonlumuz Anavatanda serimiz burda

Yuce mevlam kimseyi koymasin darda

Ozan Guner diyor olursek gurbette burda 

Vatan bize biz vatana alistik', 'Yillar oldu gurbet ele geleli Gurbet bize biz gurbete alistik Her bayramda buruk sevinc yasadik Huzun bize biz huzune alistik Anadan babadan...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gurbet-e-alistik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allı Turnam', 'alli-turnam-umut-yalim-bzdjb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedir bu göklerde peki

Toprağımı anımsatan

Baktıkça yorulduğum 

Solunduğum itlerce

Ezgimi anımsatan

Nedir bu göklerdeki

Bura gökleri benzemez

Altında çağlarca 

Yaşadığım göklere

Sökmez mavinliği

Bura göklerinin

Gözüm pasını

Bura gökleri benzemez

Altında ağlarca

Sevdiğim göklere

Dökmez mavinliği

Bura göklerinin

Gözüm yaşını

Hey toprağımdan

Bana yabancı

Allı Turnam

Bizim eve varırsan

Sevda söyle

Toprak söyle

Dost söyle

Bitik soluğum

Tutmuyor gözüm

Diyecek sözüm

Yok Turnam 

Söyle sen hepsini söyle

Yollar hepsini THY

9.15 uçağınlan

Londra/ 4.10.2003/ 22.58', 'Nedir bu göklerde peki Toprağımı anımsatan Baktıkça yorulduğum  Solunduğum itlerce Ezgimi anımsatan Nedir bu göklerdeki Bura gökleri benzeme...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/alli-turnam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme Serenat', 'anneme-serenat-salih-ozalasan-6xpf8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç yıl oldu sen gideli

Gözlerden ırak 

Gönüllerde yaşanan yerlere

Bedenin bir avuç toprak

İsmini dualarla anıyoruz anne

Alışamadım, alışamadık sensizliğe

Her kapı çaldığında

Yüreğimde o inanılmaz titreme

Sanki komşudan dönecekmiş gibisin

Umutla, sabırla seni bekliyoruz anne

Yerin hala odamda baş köşe

Karşımda bana bakan resmin, sevgiyle

Kokun sinmiş odamın her yerine

Sen toprak olsan da

Biliyorum ruhun benimle anne

Yine saçlarımı okşuyorsun

Yine basıyorsun özlemle

Hasretle yanan sinene

Hissediyorum tüm bedenimde

Böyle olmasa gidişin

Ben sensiz yaşayamazdım anne

Bak torunlar büyümüş birer, birer

Soruyorlar ne zaman gelecek baba anne

Bunlar beni unutur derdin ya

Seni unutmak ne mümkün anne

Bak sana dua ediyor ellerini açmış

Gözleri yaşlı canın Lütfiye

Kim bilir kaçınca hatim sana hediye

Sağlığında gülmedin; ruhun şad olsun anne

Sen olsan gururlanacaktın keyifle

Okumaz dediğin Gonca okuyor üniversite

Senin yokluğun hırs yaptı ona belki de

Çocuklarda seni örnek alıyor anne

Gülyonca’ n bile büyüdü

O bile okuyor lise

Hatırlar mısın nede zıtlaşırdı seninle

Ah olsan da bizleri yine azarlasan anne

Adını taşıyan bir eş istemiştin ya bana

Senin huylarını da kapmış bu bence

Salih, Lütfiye, Gonca, Gülyonca ve Emine

Ne zaman döneceksin seni bekliyoruz anne

Biliyorum dönülmez yerde bedenin

Fani Dünya’ da kaldı her sevenin

Olmadı bilirim hiç nefret edenin

Sen sevilmeye layıksın anne

İçin kan ağlarken yüzün gülerdi

Yüreğine atardın gamı derdi

Üç vefasız evlat, babam başına yıkıverdi

Yetimler için yaşadın hep anne

Biliyorum gizli, gizli ağladın geceleri

Görmesinler diye kapattın peçeleri

Sen ağladığın için sevmiyorum geceleri

Sana bir mutlu gün yaşatamadık anne 

İçimdesin, içimizdesin, sen hep bizimlesin

Dualarımız hep sana ruhun yerinmesin

Benim cennetim ayağın altından gitmesin

Mekanın daima cennet olsun anne

Y.Tarihi 03-10-2003 Saat 11.00-12.00

Salih ÖZALAŞAN', 'Kaç yıl oldu sen gideli Gözlerden ırak  Gönüllerde yaşanan yerlere Bedenin bir avuç toprak İsmini dualarla anıyoruz anne Alışamadım, alışama...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/anneme-serenat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Efendim Gel (Hasretinle Beni)', 'gel-efendim-gel-hasretinle-beni-pir-sultan-abdal-hkqmb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretinle beni üryan eyledin

Beklerim yolların gel efendim gel

Gönül kuşu kalktı cevlan eyledi

Beklerim yolların ali ali gel efendim gel

Evvel ahir sensin dönmezem senden

Meyl ü muhabbetin çıkar mı candan

Gönül göç eyledi kevn ü mekandan

Beklerim yolların gel efendim gel

Tevarih çoğaldı da hadden aştı

Urum sofuları bildiğin şaştı

Şimdi gayret Şah-ı Merdan''a düştü

Gözlerim yolların gel efendim gel

Horasan''dan kalktı Hind''i yararak

Top top olmuş hariciler kırarak

Bendelerin Şah''ına yalvararak

Beklerim yolların gel efendim gel

Bozuldu yolcular yollarda kaldı

Ayin erkan gitti dillerde kaldı

Bendelerin zayıf hallerde kaldı

Beklerim yolların gel efendim gel

Pir Sultan''ım Allah Allah diyelim

Gelin nikabını elden koyalım

Takdir böyle imiş biz ne diyelim

Beklerim yolların gel efendim gel', 'Hasretinle beni üryan eyledin Beklerim yolların gel efendim gel Gönül kuşu kalktı cevlan eyledi Beklerim yolların ali ali gel efendim gel Ev...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gel-efendim-gel-hasretinle-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Ey Dostum', 'gel-ey-dostum-pir-sultan-abdal-h6xor', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aç artık dost kollarını

Gel ey dostum yavaş yavaş

Yol karlık gözüm görmez

Gel ey dostum yavaş yavaş

Haydar-ı şah senin adın

Bilirim sende muradım

Çok peygambere uğradım

Gel ey dostum yavaş yavaş

Bir su içtim derin gölden

Hiç ayrılmam ben bu yoldan

Arif olan anlar halden

Cahillerden bilen yoktur

Pir Sultan''ım konar göçer

Halini bilene açar

Misafirler gelir geçer

Eğlenip de kalan yoktur', 'Aç artık dost kollarını Gel ey dostum yavaş yavaş Yol karlık gözüm görmez Gel ey dostum yavaş yavaş Haydar-ı şah senin adın Bilirim sende mu...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-ey-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Ey Zahit', 'gel-ey-zahit-pir-sultan-abdal-e3tn6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel ey zahit bizim ile çekişme

Hakk''ın yarattığı kul bana neyler

Kendi kalbin arıt bize ilişme

Sendeki küfr bendek''imana neyler

Zahit sen bu sırra erem mi dersin

Erenler halinden bilem mi dersin

Mescit hak meyhane haram mı dersin

Hak olan mescide meyhane neyler

Zahit sen bu yola diken ekersin

Hatıra dokunur gönül yıkarsın

Yüküm vardır deyü zahmet çekersin

Yavuz baçcı yüksüz kervana neyler

Sekiz derler şol Cennet''in kapısı

Hakk''a doğru açılırmış hepisi

Korkusun çektiğin Sırat köprüsü

Onu doğru geçen insana neyler

Pir Sultan Abdal''ım er haksın er hak

Münkir olanlardan ıraksın ırak

Kurdun işi namert lokmasın yemek

Hak için adanan kurbana neyler', 'Gel ey zahit bizim ile çekişme Hakk''ın yarattığı kul bana neyler Kendi kalbin arıt bize ilişme Sendeki küfr bendek''imana neyler Zahit sen bu...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-ey-zahit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Güzelim Kaçma Benden', 'gel-guzelim-kacma-benden-pir-sultan-abdal-wjdz1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel güzelim kaçma benden

Yad değiliz bülbülüz biz

Biz yol ehli kardaşlarız

Erkan içinde yoluz biz

Söyleşelim halden hale

Dilleşelim dilden dile

Biz gezeriz ilden ile

Taze açılmış gülüz biz

Gel söyleşelim bu sözü

Hakk''a edelim niyazı

Ko kınasın iller bizi

..............................biz

Eğer zahirde batında

Görünen her sıfatında

Cevahir sarraf katında

Nadan yanında puluz biz

Pir Sultan''ım ne ağlarsın

Gözünden kan yaş dağlarsın

Sen bizden ateş umarsın

Yanmış üfrülmüş külüz biz', 'Gel güzelim kaçma benden Yad değiliz bülbülüz biz Biz yol ehli kardaşlarız Erkan içinde yoluz biz Söyleşelim halden hale Dilleşelim dilden d...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-guzelim-kacma-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel İmdi Oku', 'gel-i-mdi-oku-pir-sultan-abdal-7if5t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel imdi oku ol Ümmül Kitab-ı

Gözü ile görmüş var mıdır Hakk''ı

On iki bahçede kırk sekiz kapı

Daim hizmetinde duran kul nedir

Başlayım yoluna ben de Ali''nin

Duası makbuldür gerçek velinin

Üçyüz altmış altı selvi dalının

Budağında açan iki gül nedir

Sana mana verdim sen de al imdi

Eğer arif isen sen de bil imdi

Ezelden Cennet''te sen de bu imdi

Bir kandil içinde iki nur nedir

Pir Sultan Abdal''ım çağır ya Gani

Veren Allah yine alır ol canı

Gönül bir gemidir akıl dümeni

Akıl dümen ya söyleyen dil nedir', 'Gel imdi oku ol Ümmül Kitab-ı Gözü ile görmüş var mıdır Hakk''ı On iki bahçede kırk sekiz kapı Daim hizmetinde duran kul nedir Başlayım yolun...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-imdi-oku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Koyun Meleme', 'gel-koyun-meleme-pir-sultan-abdal-6yip6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabah olur koyun kuşluğa gelir

Her koyun arar da kuzusun bulur

Ağca koyun meler arada kalır

Gel koyun meleme vazgel kuzundan

Benim kuzum kuzuların beyidir

Ağca koyun yüreğimin yağıdır

Anın gideceği Yıldız Dağı''dır

Gel koyun meleme vazgel kuzundan

Koyun meler kuzusunun adı yok

Sıra sıra küleklerin südü yok

Kuzusuz yaylanın hiçbir tadı yok

Gel koyun meleme vazgel kuzundan

Koyunun başına bodcak takayım

Yönüm dönüp o koyuna bakayım

Kuzun nerde ise kuzun bulayım

Gel koyun meleme vazgel kuzundan

Koyun sen şurada kuzlamadın mı

Sağını solunu gözlemedin mi

Aç kurt gelir diye gizlemedin mi

Gel koyun meleme vazgel kuzundan

Dereye aşağı gider kurt izi

Kurt ağzında gördüm bir körpe kuzu

Seversen Mevla''yı ağlatma bizi

Gel koyun meleme vazgel kuzundan

Seni yayan çoban bir delikanlı

İbrişim bıyıklı hem ince belli

Sağında solunda püskülü belli

Gel koyun meleme vazgel kuzundan

Seni yayan çoban yetip gitmesin

Bahçesinde lale sünbül bitmesin

Seni incitenler Hakk''a yetmesin

Gel koyun meleme vazgel kuzundan

Pir Sultan Abdal''ım bu kuzu n''oldu

Koyunun feryadı ciğerim deldi

Yoksa bir aç kurt mu kuzunu aldı

Gel koyun meleme vazgel kuzundan', 'Sabah olur koyun kuşluğa gelir Her koyun arar da kuzusun bulur Ağca koyun meler arada kalır Gel koyun meleme vazgel kuzundan Benim kuzum kuz...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gel-koyun-meleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin Kardaş Pirden Ayak Tutalım', 'gelin-kardas-pirden-ayak-tutalim-pir-sultan-abdal-y4ikj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelin kardaş pirden ayak tutalım

Biz tutalım tutmayandan bize ne

Hakikatı muhabbete katalım

Biz katalım katmayandan bize ne

Bizim dine yeni bir din demişler

Bir lokmayı kırk can ile yemişler

Erenler de doğru yolu komuşlar

Biz gidelim gitmeyenden bize ne

Bizim yine evvel baharımızdan

Her demde çığruşur seherimizden

Alın ey sofular gevherimizden

Biz satarız satmayandan bize ne

Yine hak sendedir sen sana bakın

Kalbini pak eyle küfürden sakın

Biz niyaz kılalım can Hakk''a yakın

Biz kılalım kılmayandan bize ne

Pir Sultan Abdal''ım ikrar güdelim

Biz bizi görelim eli n''edelim

Sınık gönülleri mamur edelim

Biz edelim etmeyenden bize ne', 'Gelin kardaş pirden ayak tutalım Biz tutalım tutmayandan bize ne Hakikatı muhabbete katalım Biz katalım katmayandan bize ne Bizim dine yeni ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelin-kardas-pirden-ayak-tutalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin Yiyelim İçelim', 'gelin-yiyelim-i-celim-pir-sultan-abdal-d8top', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelin yiyelim içelim

Bu güzellik geçer bir gün

Alem yaran yaran olmuş

Ali''m sırrın açar bir gün

Yeyip yediren bir adem

Eksik etmez Bari Hüda''m

Gök ekine misal adem

Anı eken biçer bir gün

Yeyip yedirmesi hoştur

Dayan, kahbe yürek taştır

Can dedikleri bir kuştur

Kuş kafesten uçar bir gün

Ağaçlarda yeşil yaprak

Bastığımız kara toprak

Yer altında kefen yırtmak

Boynumuzdan aşar bir gün

Pir Sultan''ım düşümüzde

Uzak değil karşımızda

Baykuş mezar taşımızda

Dertli dertli öter bir gün', 'Gelin yiyelim içelim Bu güzellik geçer bir gün Alem yaran yaran olmuş Ali''m sırrın açar bir gün Yeyip yediren bir adem Eksik etmez Bari Hüda...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelin-yiyelim-icelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekler Bilinmez', 'gercekler-bilinmez-pir-sultan-abdal-xpnro', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzeller semtinden bize gel oldu

Varamam şu iller yazlanmayınca

Kalmadı hiç talib ehl-i dil oldu

Gerçekler bilinmez azlanmayınca

Yezid''e verildi cevr ile cefa

Mümine verildi zevk ile sefa

Bunda inanmazlar, lafınız hava

Yalan ile gerçek gözlenmeyince

Ali''yi seversen dilinden koma

Bek sakla sırrını kimseye deme

Bu bir sırr-ullahtır beyan eyleme

Cemiyet kurulup sözlenmeyince

Ali''yi sevenler gönül düşürür

Düşürüben aşk kazanın taşırır

Değme rehber çiğ talib mi pişirir

Ocaklar yanıp ta közlenmeyince

Pir Sultan Abdal''ım demek mi olur

Hercai güzele emek mi olur

Terbiyesiz, ey can semek mi olur

Mürşit huzurunda tuzlanmayınca', 'Güzeller semtinden bize gel oldu Varamam şu iller yazlanmayınca Kalmadı hiç talib ehl-i dil oldu Gerçekler bilinmez azlanmayınca Yezid''e ver...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gercekler-bilinmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezdim Seyrettim Dünyayı', 'gezdim-seyrettim-dunyayi-pir-sultan-abdal-g7ftk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gezdim seyrettim dünyayı

Şu dünyada melamet var

Silindi gönlümün pası

Yüreğimde zılalet var

Ne yolcular izin izler

Ne meşayih sırrın gizler

Ne kadı şer''isin gözler

Ne beylerde adalet var

Ne kız hicap saklar

Ne gelinler usül bekler

Ne kocalar özün yoklar

Ne yiğitte marifet var

Şeriat göğe çekildi

Yüz suyu yere döküldü

Alem zulm ile yakıldı

Kıyametten işaret var

Pir Sultan''ım eyder erlik

İşin bilmektir serverlik

Allah''a yakışır benlik

İnsanda da keramet var', 'Gezdim seyrettim dünyayı Şu dünyada melamet var Silindi gönlümün pası Yüreğimde zılalet var Ne yolcular izin izler Ne meşayih sırrın gizler ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gezdim-seyrettim-dunyayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyor (Bir Tenhada Gördüm)', 'gidiyor-bir-tenhada-gordum-pir-sultan-abdal-e6sl8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tenhada gördüm o nazlı yari

Böyle uğrun uğrun baktı gidiyor

Siyah saçlarını dökmüş yüzüne

Gönlümü ateşe yaktı gidiyor

Yüzüne baktıkça tutuldu dilim

Kırıldı kollarım tutmuyor elim

Hey dost bu diyarda n''olacak halim

Gözlerimden kan yaş aktı gidiyor

Dost dost diye dostu hergün sorarım

Yitirdim o yari durmaz ararım

Abdal Pir Sultan''ım edem kervanım

Bak işte sel gibi yıktı gidiyor', 'Bir tenhada gördüm o nazlı yari Böyle uğrun uğrun baktı gidiyor Siyah saçlarını dökmüş yüzüne Gönlümü ateşe yaktı gidiyor Yüzüne baktıkça tu...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gidiyor-bir-tenhada-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Giden Gitme', 'gitme-giden-gitme-pir-sultan-abdal-a1utl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitme Giden Gitme Sual Sorayım 

Ya Ne Bu Dünyanın Üstünde Durur 

Vallahi Billahi Ben Onu Gördüm 

Dünya Sarı Öküz''ün Üstünde Durur 

Gitme Giden Gitme Bir Dahi Soram 

Ya Bu Öküz Neyin Üstünde Durur 

Vallahi Billahi Ben Onu Gördüm 

Öküz De Bir Salın Üstünde Durur 

Gitme Giden Gitme Bir Dahi Soram 

Ya Bu Sal Da Neyin Üstünde Durur 

Vallahi Billahi Ben Onu Gördüm 

Sal Da Bir Balığın Üstünde Durur 

Gitme Giden Gitme Bir Dahi Soram 

Ya Bu Balık Neyin Üstünde Durur 

Vallahi Billahi Ben Onu Gördüm 

Balık Da Deryanın Üstünde Durur 

Gitme Giden Gitme Bir Dahi Soram 

Ya Bu Derya Neyin Üstünde Durur 

Vallahi Billahi Ben Onu Gördüm 

Derya Da İkrarın Üstünde Durur 

Gitme Giden Gitme Bir Dahi Soram 

Ya Bu İkrar Neyin Üstünde Durur 

Pır Sultan’ım Der Ki Ben Onu Gördüm 

İkrar Da İmanın Üstünde Durur', 'Gitme Giden Gitme Sual Sorayım  Ya Ne Bu Dünyanın Üstünde Durur  Vallahi Billahi Ben Onu Gördüm  Dünya Sarı Öküz''ün Üstünde Durur  Gitme Gid...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gitme-giden-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçen Canlar Dönmez İmiş', 'gocen-canlar-donmez-i-mis-pir-sultan-abdal-q7jcp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İsm-i azam duasıdır

Hergiz usanılmaz imiş

Uçtu bülbül kafesinden

Göçen canlar dönmez imiş

Alay göçmüş yurd''uğradım

Bir acıkmış kurd''uğradım

Bir acayip derd''uğradım

Çekmeyenler bilmez imiş

Ezelidir gönül ezel

Olur bahçelerde gazel

Gel ahımı alma güzel

Bir ah yerde kalmaz imiş

Cevrilüben konan iller

Yaylamızdır Çamlıbel''ler

Bülbülün arzusu güller

Hüb açılan solmaz imiş

Pir Sultan''ım Emirzade

Gel sırrını verme yade

Gaziler fani dünyada

Pir ağlatan gülmez imiş', 'İsm-i azam duasıdır Hergiz usanılmaz imiş Uçtu bülbül kafesinden Göçen canlar dönmez imiş Alay göçmüş yurd''uğradım Bir acıkmış kurd''uğradım ...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gocen-canlar-donmez-imis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-aysegul-toker-gd5io', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kusura bakma dostum..

Zaman doldu. Gitme vakti şimdi.

Hayat en güçlü dostlukları ayıracak kadar acımasız.

zamanımız doldu.Gitmeliyim şimdi.

Tek tek düşen yapraklar gibi yok oldular

Dost ve arkadaşlar aramızdan.

Yıldızlar gibi kayıp kayboldular.

Kimler eksildi yaşantımızdan.

Bak günlerimiz gelip geçiyor.

Süre doluyor, zaman azalıyor.

Sıra bize de geliyor.

Birimiz gidecek diğerinin hayatından.

Zaman doldu dostum. 

Ben gidiyorum şimdi buralardan. 

Son günlerim belki bunlar. 

Son satırlar bırakıyorum ardımdan.

Ne kadar boş geliyor anlamsız tartışmalarımız.

Ne de güzeldi saatler süren konuşmalarımız.

Acısı ve tatlı ile tüm yaşadıklarımız.

Silinip gidecek bu dünyadan ve hayatlarımızdan.

Dün gibi aklımda şakalaşmalarımız

Halen hatırımda paylaştığımız sırlarımız

Birlikte söylediğimiz şarkılarımız

Beraber paylaştığımız anlarımız.

Ne sıcak, ne güzel kokulu hatıralar.

Ah bir daha gelmeyecek o zamanlar.

Son nefesi verdikten sonra.

Bilmem beni kimler hatırlar? 

Kaç tane kaldı o eski dostlar? 

Kolay koparılmazdı o bağlar.

Yitip giden arkadaşlar ve anılar.

Sıra bana geldi.Hoş çakalın a dostlar....', 'Kusura bakma dostum.. Zaman doldu. Gitme vakti şimdi. Hayat en güçlü dostlukları ayıracak kadar acımasız. zamanımız doldu.Gitmeliyim şimdi. ...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/veda-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi', 'hangi-diyarbakirli-mehmet-vue6r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hangi yil hangi mevsim 

Yoklugunu unutturur bana 

Sensizligi siler beynimden 

Huzur verir dünyama

Hangi cöpcü hangi eskici

Alir bu yirtik pirtik resimlerini

Süpürür senden kalan bu aci mazimi

Parcalayip cöpe atar senin eserini

Hangi ay hangi günes 

Gecelerimde ümit isigim olur

Karanlik odami aydinlatir 

Üsüdügümde senin yerine beni isitir', 'Hangi yil hangi mevsim  Yoklugunu unutturur bana  Sensizligi siler beynimden  Huzur verir dünyama Hangi cöpcü hangi eskici Alir bu yirtik pi...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakirli Mehmet']::text[], 8.5, '{"poet":"Diyarbakirli Mehmet","poet_slug":"diyarbakirli-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hangi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönder Bizi Safa İle', 'gonder-bizi-safa-i-le-pir-sultan-abdal-kdla4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mihman olmuşum gelmişim

Hakk''a bağlamışım özüm

Ev sahibi iki gözüm

Gönder bizi safa ile

Gelin örselemen bizi

Hakk''a ısmarladık sizi

Ayağın tozuna yüzü

Sürdür bizi safa ile

Sürüye katılan koçlar

O da Hakk''ın emrin işler

Yiyip içtiğimiz kardaşlar

Gönder bizi safa ile

Hey dedeler hey babalar

Yerde gökte hü diyenler

Rıza lokmasın yiyenler

Gönder bizi safa ile

Gidiyoruz hoşça kalın

Gahi siz de bize gelin

Heybemize azık koyun

Gönder bizi safa ile

Pir Sultan ere varalım

Hak divanına duralım

Yolcu çizmesin giyelim

Gönder bizi safa ile', 'Mihman olmuşum gelmişim Hakk''a bağlamışım özüm Ev sahibi iki gözüm Gönder bizi safa ile Gelin örselemen bizi Hakk''a ısmarladık sizi Ayağın t...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gonder-bizi-safa-ile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımsız', 'adimsiz-umut-yalim-ahdin', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamdır aslında en yalnızlığı insanın

Bir sevda ki kadınsız sevilir en güzel

Ve sevdayla sevilemeyen bir kadın

Kadınsız harfleri gibi gereksiz adımın

Burnumsuz soluduğum bir havanın

İri mavi taneleri yaşamama engel

Sesli yağmur gibi nemli bir hayvanın

Bilmediği yalnızlığındadır yaşamım

Yüzümde akamayan kanımdır yalnızlığım

Kanım çokça yalnızlığımda sanki çengel

Tutturulmuş türlü uhularla geçmiyor anım

Akmıyor saatimde ağır kumlardan camım

Sensiz sevdalardır bana armağanın

Sevmemden seni çok daha evvel

Şimdi seni sevmek darmadağın

Çokça içinde senli sevdaların

Sendir ağzımda yaşlarımsız ağladığım

Ağlamak gözüm altına ördüğün dantel

Yalnızlığım gölgem ardlarına bağladığım

Şimdi gereksiz sevdaları gibi ayrılığın

Yaşamdır aslında en yalnızlığı insanın 

Bir sevda ki kadınsız sevilir en güzel

Ve sevdayla sevilemeyen bir kadın

Kadınsız harfleri gibi gereksiz adımın

2003', 'Yaşamdır aslında en yalnızlığı insanın Bir sevda ki kadınsız sevilir en güzel Ve sevdayla sevilemeyen bir kadın Kadınsız harfleri gibi gerek...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/adimsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Arzediyor', 'gonul-arzediyor-pir-sultan-abdal-bwu15', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönül arzediyor dosta gitmeyi

Aman Allah yolun pareler beni

Ölem de kurtulam elin dilinden

Yuyalar kefene saralar beni

Bu dünyada hiçbir eyi kalmamış

Yaralısın ama cerrah gelmemiş

Elif sevdiğine malum olmamış

Yakma yar oy diyor yareler beni

Ben Allahtan gelen gazadan kaçmam

Sürahi dibinden badeler içmem

Alem bir yan olsa ben yardan geçmem

Meğer ahdedeler vuralar beni

Evleri var Gürcüm damda tevekte

Yar gele derdime merhemler kata

Mezarım üstünde bu otlar bite

Meğer çift koşalar süreler beni

Pir Sultan Abdalım can göğe ağmaz

Haktan emrolmazsa ırahmet yağmaz

Bu ellerin sözü hiç bana değmez

İlle dostun gülü yareler beni', 'Gönül arzediyor dosta gitmeyi Aman Allah yolun pareler beni Ölem de kurtulam elin dilinden Yuyalar kefene saralar beni Bu dünyada hiçbir eyi...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonul-arzediyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Azm Ediyor Azm-i Didarı', 'gonul-azm-ediyor-azm-i-didari-pir-sultan-abdal-oeovc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül azm ediyor azm-i didarı

Yenilmiyor efkarımız ne acep

Garip bülbül gibi kılarım zarı

Açılmıyor gülşenimiz ne acep

Her dem aşkın kervanları çekilir

Şu didemden kanlı yaşlar dökülür

Günden güne yaralarım sökülür

Artar gider firkatımız ne acep

Pir Sultan Abdal''ım dosta mailim

Yüz sürüben kapısında sailim

Hak''tan gelen tecellime kailim

Böyle imiş kaderimiz ne acep', 'Gönül azm ediyor azm-i didarı Yenilmiyor efkarımız ne acep Garip bülbül gibi kılarım zarı Açılmıyor gülşenimiz ne acep Her dem aşkın kervanl...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-azm-ediyor-azm-i-didari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahsun bakislarin', 'mahsun-bakislarin-diyarbakirli-mehmet-kgezx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine bu aksam aklimdasin 

Durdu gecmek bilmiyor zaman sanki 

Kulaklarimda susmak bilmeyen sesin 

Gözlerimde o mahsun bakislarin 

Uyku girmez oldu gözlerime 

Doymak bilmezki bu deli gönül izlemekle 

Hancerler saplaniyor pes pese su kalbime 

O mahsun bakislari görünce

Bilmiyorum ne yapacagimi artik 

Ne kadar dayanabilirim ben senin hasretine 

Baskasini koyamamki senin yerine 

Sevememki onu senin gibi böyle

Ne yaparsin sevdi seni bu gönül bir kere 

Simdi fayda etmezki bu pismanligim 

Sevmeseydim seni keske desemde 

Ugruna harcadigim yillarim dönermi geriye 

Kaybolan o gülen yüzümü

Kim bulupta verir bana geriye! ! !', 'Yine bu aksam aklimdasin  Durdu gecmek bilmiyor zaman sanki  Kulaklarimda susmak bilmeyen sesin  Gözlerimde o mahsun bakislarin  Uyku girmez...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakirli Mehmet']::text[], 8.5, '{"poet":"Diyarbakirli Mehmet","poet_slug":"diyarbakirli-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mahsun-bakislarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sair deniz ve bir oyun', 'sair-deniz-ve-bir-oyun-huseyin-cayikli-yipp9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'elimde fotografin bile yok artik

nede adresin 

bir tiyatro oyununu hatirlarim

ne kadar sanat seviceligin...

oyun cikisinda birbirbirimizi kaybettik

devamsizlik yuzunden tarih dersini aldik...

elimde sana ait hic birsey yok

adindan baska

eski bir siir okur sair

ben o sairin bilinmez misralarinda 

senin sesini kaybettim

simdi ellerim duyarsiz oldu misralara

ben seni benden irakta seviyordum

senin vucudun kanapede uzanmis yatiyordu

arada sirada adamin yankisini sayikliyordun

ben senin benden alip gittiklerinle kaybettim...

sair yaziyordu misralarini

akip giden bir suyun ustunde elleri bogazi oksuyordu...

istanbulu seviyordu sair 

senin adini bile bilmiyordu...

sonra gemi kalkti limandan

son gemiydi 

yetisilecek yerleri vardi sairin

seni seviyordu sair...

seviyordu...

sevdi...

ucaga binmesi lazimdi

belkide otobus

hayir en iyisi 

deniz

denizde buldu kendini sair

eline bir aksam finli bir sair dokundu

sair islik caldi

dunya durdu...', 'elimde fotografin bile yok artik nede adresin  bir tiyatro oyununu hatirlarim ne kadar sanat seviceligin... oyun cikisinda birbirbirimizi ka...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sair-deniz-ve-bir-oyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz üc gün', 'sensiz-uc-gun-diyarbakirli-mehmet-67xf6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak yine sensiz gecti 3 günüm 

Bana sanki 3 ay 3 yil 3 hayat gibi gecti 

Sana susuz sana uykusuz sana muhtactim 

Seni özledim seni bekledim sesine hasrettim 

Tükendi sabrim bitti umudum soldu gülüm 

Ama sana olan sevgim ama yanan sevda atesim 

Beni yakti beni küle cevirdi duman oldum 

Savurdu beni kayboldum 

Sanki bir yalan oldum 

Simdi bundan sonra ve ebediyen artik yokum', 'Bak yine sensiz gecti 3 günüm  Bana sanki 3 ay 3 yil 3 hayat gibi gecti  Sana susuz sana uykusuz sana muhtactim  Seni özledim seni bekledim ...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakirli Mehmet']::text[], 8.5, '{"poet":"Diyarbakirli Mehmet","poet_slug":"diyarbakirli-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensiz-uc-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdigimden ayirdilar', 'sevdigimden-ayirdilar-diyarbakirli-mehmet-jofle', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sevdim beni sevdigimden ayirdilar 

Yeni yeseren bir yapraktim

Beni dalimdan kopardilar 

Ayrilik rüzgarini estiler üzerime 

Tutunamadim dalima 

Alip beni gurbet ele savurdular

Tek basima yalnizlik dolu unutulmus bir sehire 

Bende unutuldum o sehirde sardi beni yalnizliklar 

Kacamadim kurtulamadim 

Dört tarafimda duvarlar 

Kacmak istedim birakmadilar 

Ya üzerindeki tel örgüler 

Beni yaraladilar 

Ben sevdim onlar beni sucladilar 

Ask mahkemesinde yargilandim 

Cezalandirdilar 

Sensiz yasamaya mahkum ettiler 

Yalnizlik hapisanesine attilar 

Ayagima pirangalar 

Ellerime kelepceler taktilar 

Ben sevdim sadece sevdim 

Onlar beni yanlis anladilar! ! !', 'Ben sevdim beni sevdigimden ayirdilar  Yeni yeseren bir yapraktim Beni dalimdan kopardilar  Ayrilik rüzgarini estiler üzerime  Tutunamadim d...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakirli Mehmet']::text[], 8.5, '{"poet":"Diyarbakirli Mehmet","poet_slug":"diyarbakirli-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevdigimden-ayirdilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seven bile bilemez', 'seven-bile-bilemez-diyarbakirli-mehmet-8bgdu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevilmek cok zor

Kolay bulunmaz 

Sevmek yürek ister

O olmasa olmaz 

Seviyorum seni diyen cok

Ama gönüldenmi bilinmez 

Sevginin ne oldugunu 

Inan seven bile bilemez 

Baglanirsin ona

Nedenini bilemezsin 

Taparcasina seversin

Gün olur unutup gidersin 

Özlem atesiyle yanarsin

Yinede gururuna yediremezsin 

Heves diye kendini avutup

Hayat bu yasamaya devam edersin', 'Sevilmek cok zor Kolay bulunmaz  Sevmek yürek ister O olmasa olmaz  Seviyorum seni diyen cok Ama gönüldenmi bilinmez  Sevginin ne oldugunu  ...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakirli Mehmet']::text[], 8.5, '{"poet":"Diyarbakirli Mehmet","poet_slug":"diyarbakirli-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seven-bile-bilemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir', 'bilir-umut-yalim-ebtmk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hangi sevda bilir

İçindeki sevenleri

Hangi ayrılık

Kendisine sövenleri

2003', 'Hangi sevda bilir İçindeki sevenleri Hangi ayrılık Kendisine sövenleri 2003...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bilir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benzer', 'benzer-umut-yalim-smjca', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdanın iyisi

Ne sevdaya benzer

Ne iyiye

İnsana benzer

Sana bana ona

Kavgamıza', 'Sevdanın iyisi Ne sevdaya benzer Ne iyiye İnsana benzer Sana bana ona Kavgamıza...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/benzer-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamak', 'anlamak-umut-yalim-kdxxh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Severken anladım

Seni sevemeyeceğimi Verda

Ama Verda da ne sevda', 'Severken anladım Seni sevemeyeceğimi Verda Ama Verda da ne sevda...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/anlamak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '4 Mevsim...', '4-mevsim-hakan-sinkiler-np28x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baharda yeşeren yapraklar gibiydi bizim aşkımız…

Tazecikti…

Minicikti…

Olabildiğine güzeldi…

Sonra yaz geldi…

İyice yeşerdi yapraklar…

Aşkımızın gücü…

Benim sana sevgim gibi…

Sonra havalar soğudu…

Sen de bana soğudun…

Sarardı yüzün beni görünce…

Ağacımızın yaprakları gibi…

Teker teker döküldü yaprakları…

Kalbindeki sevgi kırıntıları gibi…

Ve son…

Bembeyaz kar taneleri…

Döküldü sevgimizin üstüne…

Kapadı üstüne yaprakların…

Hani geçen bahar yemyeşil olanların…', 'Baharda yeşeren yapraklar gibiydi bizim aşkımız… Tazecikti… Minicikti… Olabildiğine güzeldi… Sonra yaz geldi… İyice yeşerdi yapraklar… Aşkım...', ARRAY['Türk Edebiyatı','Şiir','Hakan Sinkiler']::text[], 8.5, '{"poet":"Hakan Sinkiler","poet_slug":"hakan-sinkiler","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/4-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Sevmek', 'ne-sevmek-umut-yalim-703c3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevmekçin

Ne sevda isterim

Ne de seni

Oturup kendimi severim

Resmin karşında

Resimsiz

2003', 'Seni sevmekçin Ne sevda isterim Ne de seni Oturup kendimi severim Resmin karşında Resimsiz 2003...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ne-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı…', 'gozyasi-hakan-sinkiler-2bow8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deli olmak lazımdı böyle bir şey yapmak için…

Beklide sadece aşk dedikleri saçma bir duygunun esiri olmamdandı tüm bunlar…

Bunların arasından sıyrılan tek gerçek ise benim sana olan sevgim…

İşte budur tüm bu olayların sebebi…

Seni mutlu etme çabası…

Kimi zaman sağdan soldan alınan fikirler…

Kimi zaman saatler boyu  kafa patlatmanın sonucu ortaya çıkan orijinal fikirler…

Bir zerre sevgi için yapılmış  onca çaba…

Ve sonunda senin için yapılmayan bir şey yaptım…

Bir ilki gerçekleştirdim…

Kimsenim cesaret edemediği bir şeyi…

Tek bir şeyi umarak…

Toprağımdaki gözyaşlarının bir damlasının bile sana ait olmasını dileyerek', 'Deli olmak lazımdı böyle bir şey yapmak için… Beklide sadece aşk dedikleri saçma bir duygunun esiri olmamdandı tüm bunlar… Bunların arasında...', ARRAY['Türk Edebiyatı','Şiir','Hakan Sinkiler']::text[], 8.5, '{"poet":"Hakan Sinkiler","poet_slug":"hakan-sinkiler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozyasi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnandıran', 'i-nandiran-umut-yalim-207ed', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzel olduğunu söylemek ne güç

Miyobum büyük gözlerimse küçük

Ama güzel olduğuna inandıran bir şey var bu gece

Başlangıcı ayıp sonu kayıp soyup soyup', 'Güzel olduğunu söylemek ne güç Miyobum büyük gözlerimse küçük Ama güzel olduğuna inandıran bir şey var bu gece Başlangıcı ayıp sonu kayıp so...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/inandiran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznü Sebep', 'huznu-sebep-hayrettin-turk-4yc74', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar var ki 

biriktirmekteyim hüzünleri

her gün batımı

bir damla olup indi yüreğime

gözlerim her yastıkta iz bıraktı

her uyku öncesi ıslak ıslak

…..

damlaların dolduğu bir andı

umutların solduğu bir andı…

“bağda bağban soluklandı”

güllere can oldu nefesin

madem vardın

yıllardır nerdesin…

umutlar gül oldu

güller nefesin

boşa değilmiş o hüzünler

anladım

güneşin batığı yerdesin…', 'Yıllar var ki  biriktirmekteyim hüzünleri her gün batımı bir damla olup indi yüreğime gözlerim her yastıkta iz bıraktı her uyku öncesi ıslak...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/huznu-sebep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözcük Tutmaz Papyekuşe', 'sozcuk-tutmaz-papyekuse-yasar-aslan-0mluh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'papyekuşe birde kalem arıyorum

şekillerde bahar kokulu mevsimlere boyuyorum

pastel boya ve papyekuşe birde seni arıyorum

bazen nefesin bile az geliyor ve o tanıdık kokun

en olmadık zamanda belirivermen ne güzel şey

bilirsin işte düşüncenin derine dalmış hali 

nehir misali akıntıyla sürüklenilmesinden

ve tatlı bir huzur dilimiyle gelen hayallerden bahsediyorum

resim yapıyorum 

kuşlar uçuruyorum 

olmadı yine eksik yine eksik diyor doymuyorum

yeni bir kağıt daha istiyorum

işte yine sözün bittiği yerde

düşüncenin derinleşmiş halindeyim

ne çok uzak ne yakın bir yerdeyim

sana senden yakın 

karanlıktaki siyah nokta kadarda uzak yerdeyim

yine her zaman ki gibi 

sözün bittiği yerde

kağıtlarin sözcük tutmaz dilimindeyim...', 'papyekuşe birde kalem arıyorum şekillerde bahar kokulu mevsimlere boyuyorum pastel boya ve papyekuşe birde seni arıyorum bazen nefesin bile ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sozcuk-tutmaz-papyekuse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılmaz Erdoğan''a', 'yilmaz-erdogan-a-alibey-cakir-i32h7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yılmazdı o hiç hayattan...

Irak olmadı hiç bir umudu ona..

Lal akşamlarda yazdı

Mum ışığında bile

Antik acılarını hayatının

Zehir Zemberek bölümünü

Ekmeği kalemdi, tuzu kağıt, 

Ruhu şairdi onun, yüreği şiir, 

Dobra dobraydı her kelamı, her satırı

Oynadığı her oyununun...

Gülüşünde bir mana vardı

Alkol İkindisinde bile, 

Neden yazıyordu?', 'Yılmazdı o hiç hayattan... Irak olmadı hiç bir umudu ona.. Lal akşamlarda yazdı Mum ışığında bile Antik acılarını hayatının Zehir Zemberek b...', ARRAY['Türk Edebiyatı','Şiir','Alibey Çakır']::text[], 8.5, '{"poet":"Alibey Çakır","poet_slug":"alibey-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yilmaz-erdogan-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Dağıtmak Suçmuş', 'sevgi-dagitmak-sucmus-ali-osman-yilmaz-msr5y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kafeste yaşarım, ellerim kollarım bağsız

Ama ayaklarımdan prangalı bir halde

Sırtımda inançlarımdan oluşan sevgi yüküm

Taşırım her gün, kan ter içinde.

Şaşkın seyrederlerken  ordan geçenler beni

Yüzümdeki mutlu gülümsemeyle

Yaşam sırtımda daha da bir ağırlaşır

Taşırım yükümü içleri sevgi dolu, ellerim belimde

Bilirmisiniz hey insanlar, insancıklar, 

Taşıdığım bu yük bana az gelir, 

Verin bana sevgilerinizi, onlarıda koyun sırtıma

Götüreyim hepsini, sevgi çiçeğinin bahçesine.

Her sabah doğan güneşe bakıp, 

Yağan yağmurun altında yeniden yeşersinler, 

Açsınlar yeniden sevgi çiçekleri olarak, 

Kimi kırmızı, kimi Mine beyazı gibi bir gül

Bazıları şaşkın hercai, yada mor menekşe

Esen yellere güzel kokularını serperek

Ulaşsınlar sevgiye aç gönüllere

Sırtımdaki yükler arasında dağıtayım dört bir yana, 

Seslenerek insanlara, yokmu sevgi isteyen? 

Demet, demet elinize tutuşturayım sevgi çiçeklerinin

Yeniden yeşerttiği sevgi gülleri olarak.

Dönerim akşam olunca kafesime yeniden

Ellerim bağsız, ayaklarımda pranga

Prangalar üstünde yazar mahkumiyet kararım

Hükmüm benim müebbede mahkum, 

Layihasında derki, Bu karar

Herkesi sevdiği ve sevgiyi dağıttığı için, 

Sevginin yasaklandığı bu dünyada

Aşık olmak istediği için.

İyi bakın, kafeste gördüğünüz o sevgi hamalı

Dikkatle bakın, o benim, 

Her gün sevgi taşımak ve dağıtmak için

Açın gönüllerinizi, bekleyin beni

Güneşin doğmasını, sabahı sabırla beklerim.', 'Kafeste yaşarım, ellerim kollarım bağsız Ama ayaklarımdan prangalı bir halde Sırtımda inançlarımdan oluşan sevgi yüküm Taşırım her gün, kan ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevgi-dagitmak-sucmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadın, Bir Adam ve...', 'bir-kadin-bir-adam-ve-umut-gul-iysy0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir kadın 

sevilir, 

sevilmek hakkıdır. 

sevmek yetmez 

tapınmak gerek... 

bir adam 

sever, 

koca bir yürek taşır 

dünyadaki tüm sevdalara bedel 

sevmesi yetmez 

bunu bilmez, 

belki bilirde gönlü ferman dinlemez... 

bir kadın, 

titrer yüreği, 

ama korkar, 

gönlü sevmek ister, 

bedeni aşk oduyla erimek 

ama aklı dur der 

daha değildir zamanı 

neyine gerek, senin vuslata ermek... 

bir adam... 

hemde ne yaman adam, 

üzülmesin diye kadını, 

yüreğine basar taşları 

nerdeyse unutacak kendi adını, 

anmaktan kadınını...

bir kadın ve bir adam... 

yangın yerine döner yürekleri 

hasretle kavrulurken bedenleri 

çığrından çıkmışken arzuları 

beklemek... 

özlemektir...

sevdaları...

ne çare ki 

boşa çekerler kürekleri...

....

bir kadın, bir adam...

ve bir de kara sevda...', 'bir kadın  sevilir,  sevilmek hakkıdır.  sevmek yetmez  tapınmak gerek...  bir adam  sever,  koca bir yürek taşır  dünyadaki tüm sevdalara b...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bir-kadin-bir-adam-ve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza dek...', 'sonsuza-dek-sezgin-keles-huo7a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bildiklerimin hepsini unutmak 

Yeniden dünyaya gelmek istiyorum

Küçük yemyeşil köyümde

Cahil doğmak, cahil büyümek, cahilce ölmek

Ama mutlu, arkadaşça, samimi olmak

Sonsuza dek...', 'Bildiklerimin hepsini unutmak  Yeniden dünyaya gelmek istiyorum Küçük yemyeşil köyümde Cahil doğmak, cahil büyümek, cahilce ölmek Ama mutlu,...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sonsuza-dek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz mutluluk', 'sonsuz-mutluluk-sezgin-keles-qpnij', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yenilmeyecektim bu büyük kente

Çok güzeldi İstanbul gözümde 

Ama İstanbul Aysberg gibi

Görünen sadece güzel, mutlu, zengin küçük bir yeri

İçine girdiğinde kaybolduğun gibi

Şimdi pişmanım keşke dönmeseydim geri

Veya hiç gelmeseydim köyümden İstanbula

Temiz hava, temiz toprak ve temiz su 

Budur insanın sonsuz mutluluğu.', 'Yenilmeyecektim bu büyük kente Çok güzeldi İstanbul gözümde  Ama İstanbul Aysberg gibi Görünen sadece güzel, mutlu, zengin küçük bir yeri İç...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sonsuz-mutluluk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naylon', 'naylon-orkan-sanci-p8q0l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşüncelerimi vurdum bu sabah 

Kalbimi attım içimden 

Bir bardak su 

Zor aktı boğazımdan 

Kulaklarım sesine doymuş, 

Gözlerimse senden bıkmıştı. 

Nefesim bile küskündü bana, 

Sebepsizce. 

Aşık bedenim yalpaladı 

Gelecek, hızlandı. 

Aşka acıkmıştım; 

Kendime yediremedim. 

Sonra kalbimi aldım yerden 

Gururumdan sokağa atamadım 

En temiz olan havaydı, 

Havaya fırlattım. 

Düştüğünde akşam olmuş, 

Gölgem çoktan kaybolmuştu.', 'Düşüncelerimi vurdum bu sabah  Kalbimi attım içimden  Bir bardak su  Zor aktı boğazımdan  Kulaklarım sesine doymuş,  Gözlerimse senden bıkmı...', ARRAY['Türk Edebiyatı','Şiir','Orkan Şancı']::text[], 8.5, '{"poet":"Orkan Şancı","poet_slug":"orkan-sanci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/naylon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybettim', 'kaybettim-orkan-sanci-3yf0l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarımı kaybettim 

Ağlayamıyorum 

Tutunurken sana 

Yaşayamıyorum 

Gözyaşlarımı kaybettim 

Konuşamıyorum 

Dengem yok 

Sana çarpıyorum 

Gözyaşlarımı kaybettim 

Sende bulamıyorum.', 'Gözyaşlarımı kaybettim  Ağlayamıyorum  Tutunurken sana  Yaşayamıyorum  Gözyaşlarımı kaybettim  Konuşamıyorum  Dengem yok  Sana çarpıyorum  G...', ARRAY['Türk Edebiyatı','Şiir','Orkan Şancı']::text[], 8.5, '{"poet":"Orkan Şancı","poet_slug":"orkan-sanci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kaybettim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Özgür Olamadım', 'ben-ozgur-olamadim-orkan-sanci-q3nlc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben hiç özgür olmadım

Dibe vurduğumda olduğum kadar

Buralar sessiz, sakin

Sen git şimdi

Gidebildiğin kadar

Dibe vurmanın iyi yönü

Dipten güç alıp yüzeye çıkmak

Ben hiç özgür olamadım

Ölüme yaklaştığım kadar', 'Ben hiç özgür olmadım Dibe vurduğumda olduğum kadar Buralar sessiz, sakin Sen git şimdi Gidebildiğin kadar Dibe vurmanın iyi yönü Dipten güç...', ARRAY['Türk Edebiyatı','Şiir','Orkan Şancı']::text[], 8.5, '{"poet":"Orkan Şancı","poet_slug":"orkan-sanci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ben-ozgur-olamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık', 'kirik-orkan-sanci-ivthc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni düşünüyorum

ellerim soğuk

yazmak için uzanıyorum

kağıt ıslak

elini koy

kalbimin üstüne

bir ritm duyacaksın

kalbim var ya

kırık', 'seni düşünüyorum ellerim soğuk yazmak için uzanıyorum kağıt ıslak elini koy kalbimin üstüne bir ritm duyacaksın kalbim var ya kırık...', ARRAY['Türk Edebiyatı','Şiir','Orkan Şancı']::text[], 8.5, '{"poet":"Orkan Şancı","poet_slug":"orkan-sanci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kirik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlilik teklifi', 'evlilik-teklifi-sezgin-keles-hkppi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi yanımda olsan

Yanyana, gözgöze, dizdize

Dayasak başımızı aynı yastığa

Hiç bir zaman sabah olmasa, 

Hiç ayrılmasak birbirimizden

İşte o zaman aydınlanır dünyam

Gerek kalmaz senden başka güneşe

Gerek kalmaz ayrılık çilesine

Sana son bir sözüm var 

Sevgilim evlenir misin benimle?', 'Şimdi yanımda olsan Yanyana, gözgöze, dizdize Dayasak başımızı aynı yastığa Hiç bir zaman sabah olmasa,  Hiç ayrılmasak birbirimizden İşte o...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/evlilik-teklifi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takip', 'takip-orkan-sanci-f2kge', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karda yürüyorum 

Ayak izlerim beni takip ediyor. 

Yalnızlığımı düşünüyorum 

Anılarım beni teskin ediyor. 

Yaşıyorum. 

Ölüm beni takip ediyor. 

Sana sesleniyorum, 

Sesim geri geliyor.', 'Karda yürüyorum  Ayak izlerim beni takip ediyor.  Yalnızlığımı düşünüyorum  Anılarım beni teskin ediyor.  Yaşıyorum.  Ölüm beni takip ediyor...', ARRAY['Türk Edebiyatı','Şiir','Orkan Şancı']::text[], 8.5, '{"poet":"Orkan Şancı","poet_slug":"orkan-sanci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/takip-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-cahit-i-pekoglu-w1rlh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kadını sevmekle başlar her şey 

ama bir kadını, tanımakla çıkılır keyifli serüvenlere. 

Hayatla dalga geçmesini bilir kadın 

tıpkı kendi ile dalga geçmesini bildiği gibi. 

Agız dolusu gülüşlere teslim olur 

bir damla sevgiye, veren için kul olur.... 

Bir kadını sevmekle başlar her şey 

ama bir kadını tanımakla tanık olunur. 

Çekip gitmeyi 

sahip olduklarindan vazgeçmeyi bilir kadın. 

Karşılık beklememeyi 

ama sevmeyi bilir kadın. 

Mücadele eder 

kızar, bağırır ama hep sever KADIN...', 'Bir kadını sevmekle başlar her şey  ama bir kadını, tanımakla çıkılır keyifli serüvenlere.  Hayatla dalga geçmesini bilir kadın  tıpkı kendi...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kadin-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım sana', 'asigim-sana-sezgin-keles-bgp20', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece de şükrediyorum

Seni tanıdığım güne

Bu gece de gidiyorum

Seni gördüğüm yere

Bu gece de yanıyorum 

Ayrılık ateşiyle

Bu gece de sensizim

Yalnızlıkla birlikte

Bu gece de geliyorum

Uçurum kenarına

Gökyüzüne bakıyorum

Ve haykırıyorum uzaklara

Ne olur beni anla

Birtanem aşığım sana', 'Bu gece de şükrediyorum Seni tanıdığım güne Bu gece de gidiyorum Seni gördüğüm yere Bu gece de yanıyorum  Ayrılık ateşiyle Bu gece de sensiz...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/asigim-sana-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalim', 'hayalim-sirma-mersin-0xxxk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dökülen sarı yaprakların arasında

Yürüyorken  yorgun ayaklarım...

Düşüncemde dağılıyor; 

hüznümün resmi...

Gerçeklerin içinde! 

Soluk almaya çalışan; benliğimle beraber, 

Sana gelemiyorum.

HAYALİM! ...

5.10.03', 'Dökülen sarı yaprakların arasında Yürüyorken  yorgun ayaklarım... Düşüncemde dağılıyor;  hüznümün resmi... Gerçeklerin içinde!  Soluk almaya...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayalim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her şeyim', 'her-seyim-sezgin-keles-cyxqj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlık, karanlık her şey vardı odamda

Bir sen eksiktin şu kocaman dünyamda

Tat vermiyor artık sensiz hiç bir şey bana

Ne olur sevgilim beni sensiz bırakma

Kağıtlardan uçak yaptım ama uzaklara uçma

Demirlerden gemi yaptım akıntıya kapılma

Bir gün karşına benden başkası çıkarsa

Dayanamam bu acıya sakın ona bakma

Yazdığım bütün nağmeler gelecekse diline

Söylediğim iki kelime gelirse hayaline

Düşündükçe gözünde hayalim büyürse

İşte o zaman ''seni seviyorum'' de

Seviyorsan halı olur serilirim önüne

Seviyorsan, sana hem kul olurum hem köle

Seviyorsan, mutluluktan dönerim ben deliye

Artık herşeyim ne kaldı ki geriye.', 'Yalnızlık, karanlık her şey vardı odamda Bir sen eksiktin şu kocaman dünyamda Tat vermiyor artık sensiz hiç bir şey bana Ne olur sevgilim be...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-seyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benlik', 'benlik-sirma-mersin-zy8td', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boş hayallerin peşine takılanlar

Adını unuttuğun sevgililer

Tükenmeyen çaresizlikle beraber; 

Sevginin özlemine duyulan, 

Karanlığın içine düşmüş, umutlar...

Ömrün öteki yüzüne yansımış, gerçekler

Birbiri ardına gelmiş, düşünceler, 

Bitmeyen yalnızlığın izini taşıyor, benlikler...

19.06.03', 'Boş hayallerin peşine takılanlar Adını unuttuğun sevgililer Tükenmeyen çaresizlikle beraber;  Sevginin özlemine duyulan,  Karanlığın içine d...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/benlik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama', 'aglama-ufuk-nazim-uqrup', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlama sevgilim; 

Göm acını göğsüme.

Hadi gel; 

Sarayım seni, 

Kollarımla.

Acını emeyim; 

Dudaklarından.

Ağlayıpda yıkma; 

Göğü yüzüme.

Yağmur yağmur yığılma; 

Çaresiz uzaklığıma.

Gül hadi gülümse.

Yüzünde gene çiçekler; 

Gönlünde sevdamız açsın.

Sesin uzak değil sevgilim.

Ve göz yaşlarının tuzu; 

Dudaklarımda. 

Dudakların ürkek bir ceylan; 

Sesin titrek bir; 

Mum ışığı.

Benmiyim sesini titreten; 

Deli poyraz.

Bilmezmisin değerini; 

Zümrüt gözyaşlarının.

Ağalayıpda kabartma; 

Gönlümün nehrlerini.

Başını omuzuma yasla; 

Yüreğimde taşıyayım seni.

Seni yüreğinde taşıyan biri var; 

Unutma sevgilim.

Umutlarım gözyaşlarında; 

Ağlayıpda azaltma umutlarımı.

.', 'Ağlama sevgilim;  Göm acını göğsüme. Hadi gel;  Sarayım seni,  Kollarımla. Acını emeyim;  Dudaklarından. Ağlayıpda yıkma;  Göğü yüzüme. Yağm...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aglama-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Ne Olur', 'gitme-ne-olur-hakan-bektas-vp89i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gitme ne olursun! 

Koyma bir başıma beni bu ıssız sokaklarda

Bırakma yalnızlığın pençesine, 

Karanlığın soğuk nefesine

Gitme ne olursun! 

Gitme ne olursun! 

Beni benden aldın, bari sensiz bırakma

Tek başıma olamayacağım koskoca deryada

Kimse aldırmaz ve kimse yetişmez bu feryada

Gitme ne olursun! 

Gitme ne olursun! 

Gitme bir dinle söyleyeceklerimi

Dinle yaralı yüreğimin çırpınış sesini

Ve sakın deneme ''keşke yapmasaydım''diyeceklerini

Gitme ne olursun! 

Gün gelir ki pişmanlıklar denizinde bir yolcu olursun

Büyüktür bu derya kaybolursun

Boşuna çırpınışlar boşuna, yorulursun

Ve gün gelir o ıssız mavilerde boğulursun

Gitme ne olursun! 

                            (03.10.2003)', 'Gitme ne olursun!  Koyma bir başıma beni bu ıssız sokaklarda Bırakma yalnızlığın pençesine,  Karanlığın soğuk nefesine Gitme ne olursun!  Gi...', ARRAY['Türk Edebiyatı','Şiir','Hakan Bektaş']::text[], 8.5, '{"poet":"Hakan Bektaş","poet_slug":"hakan-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gitme-ne-olur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşuna Gitme', 'bosuna-gitme-hakan-bektas-5un9p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer döneceksen bir gün  boşuna gitme! 

Yorma boşuna kanadı kırık sevgimizi

Harcama tükenmekte olan enerjimizi

Ve sakın incitme yaralı güvercinimizi

Eğer döneceksen bir gün  boşuna gitme! 

Eğer döneceksen bir gün  boşuna gitme! 

Tüketme ömrümüzü boşuna telaşlarda

Susuz bırakma gülümüzü

Acılra mahkum etme günümüzü

Ve bir heves uğruna ipotek etme ömrümüzü

Eğer döneceksen bir gün  boşuna gitme! 

Eğer gidersen bir gün  boşuna dönme! 

Çünkü bulamazsın bıraktığın yerde

Bulamazsın bıraktığın gibi

Tarihin sarı sayfalarına gömülen sevgimizi

Arayıpta bulamazsan sakın üzülme

Eğer üzülecksen bir gün  boşuna gitme!', 'Eğer döneceksen bir gün  boşuna gitme!  Yorma boşuna kanadı kırık sevgimizi Harcama tükenmekte olan enerjimizi Ve sakın incitme yaralı güver...', ARRAY['Türk Edebiyatı','Şiir','Hakan Bektaş']::text[], 8.5, '{"poet":"Hakan Bektaş","poet_slug":"hakan-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bosuna-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
