INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Mutluluk', 'kucuk-mutluluk-sirma-mersin-w5hjm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçük mutluluklar yaşıyorum; 

Hayal kırıntılarının arasında, 

Yeni bir günü kucaklıyorum; 

Yalnızlığımın dünyası ile

Kaybolmuş sevginin izini arıyorum; 

Hüzün kokan kalbin içinde, 

Özlemin adını biliyorum; 

Sensizliğin tadı ile...

8.10.03', 'Küçük mutluluklar yaşıyorum;  Hayal kırıntılarının arasında,  Yeni bir günü kucaklıyorum;  Yalnızlığımın dünyası ile Kaybolmuş sevginin izin...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kucuk-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye', 'niye-olcay-kose-cnncm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne çaresizliklerle dolu yollar izledim

uğruna kim bilir

bulmak için sevdim seni

sevgilim

aramak için değil..', 'ne çaresizliklerle dolu yollar izledim uğruna kim bilir bulmak için sevdim seni sevgilim aramak için değil.....', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/niye-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
