INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanda olsa', 'yalanda-olsa-olcay-kose-wsep0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bana bilmediğim bir şey söyle

kanadı kırık bir kuşu iyileştirdiğini

suya muhtaç bi çiçeğe su verdiğini 

ellerinle 

beni gizli gizli sevdiğini söyle 

sevmesende..', 'bana bilmediğim bir şey söyle kanadı kırık bir kuşu iyileştirdiğini suya muhtaç bi çiçeğe su verdiğini  ellerinle  beni gizli gizli sevdiğin...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalanda-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunun fotoğrafı', 'yoklugunun-fotografi-olcay-kose-i0u4g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ilk değil bu yalnız kalışım

sevdiğim

