INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalımsın', 'sevdalimsin-rafet-maden-jrv86', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cennetin güzelliğini üstünde toplamış, 

Cehennem sıcaklığını kalbime saplamış, 

Bu aşk yolunda çilelerime katlanmış, 

Sevda yüklü meleğimsin, sevdalımsın. 

Bazen azrail olur canımı alırsın, 

Bazen israfil olur kıyamet koparırsın, 

Ama sen varya sen, 

Sen sonuçta melek kalpli sevdalımsın.', 'Cennetin güzelliğini üstünde toplamış,  Cehennem sıcaklığını kalbime saplamış,  Bu aşk yolunda çilelerime katlanmış,  Sevda yüklü meleğimsin...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevdalimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlak hüzünler', 'mutlak-huzunler-ersin-sen-mrn7t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '01-09-2003  

                                                                                                                             -Dilek ‘ e

Yalnızlığımızı göz yaşlarıyla yıkarız 

Misler gibi koksun diye

Gece duaları 

Hep karanlık olur

Sense mutluluklarına mezar

Günahları  toprağa eken şeytanlar

Verem kıvamında  sunar

Üç koyu beyaz hiçliği

Büyük hasretler çarşısında

Uzun cümleler arıyorum adına

Gülmelisin hep 

Kötülüklere  karşıca durup

Sevinmelisin rüyalarına

Hüzün sarkan günlere 

Kangren ağlamalar bırakarak

Gevezeliğine küsmüş bir saksağan gibisin

O kadar derin susuyorsun ki

Boğuluyorum  sükutunda 

Kimseler görmesin diye geceleri yazarım

Ben şiirlerimi 

Hain korkularına inat

Durmaksızın 

İsyanlar mayalarım styx nehrine', '01-09-2003                                                                                                                                -D...', ARRAY['Türk Edebiyatı','Şiir','Ersin Şen']::text[], 8.5, '{"poet":"Ersin Şen","poet_slug":"ersin-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mutlak-huzunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kadının', 'ben-kadinin-vatan-toplucan-ikmev', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben kadının İstanbul gibi olanını severim, 

Hem fethi zor

Hem fatihi büyük

Ben kadının istanbul gibi olanını severim.', 'Ben kadının İstanbul gibi olanını severim,  Hem fethi zor Hem fatihi büyük Ben kadının istanbul gibi olanını severim....', ARRAY['Türk Edebiyatı','Şiir','Vatan Toplucan']::text[], 8.5, '{"poet":"Vatan Toplucan","poet_slug":"vatan-toplucan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ben-kadinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin Ederim', 'yemin-ederim-rafet-maden-xhc8f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne kadar uzakta olsanda bana, 

Ben seni yinede severim.

Bir gün veda etsemde sana, 

Unutmayacağım yemin ederim.

Biri vardı derim adını saklarım, 

Hiç açılmaz bu dudaklarım, 

Yakama yapışsada günahlarım, 

Seni seveceğim yemin ederim.

(VAN-merkez) 

(29.12.2001) 

(Saat:21.15)', 'Ne kadar uzakta olsanda bana,  Ben seni yinede severim. Bir gün veda etsemde sana,  Unutmayacağım yemin ederim. Biri vardı derim adını sakla...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yemin-ederim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ve beyaz', 've-beyaz-yildiz-yildiz-z3phb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sahiplendim yıllar boyu

Biriktirdim

Sevgiler, hüzünler

Kurallar, değerler, 

Sorumluluklar, önyargılar, 

kabullenmişlikler, 

incinmeler, 

melankoliler

Ve en çok da neşeler.

Rengarenktiler, çeşit çeşit, 

Sıkıştılar, 

göğüs kafesimi daralttılar.

İyi kötü diye ayırmadan

Doldurdum hepsini eteğime, 

Çıktım gönlümün yücesine, 

Derin, sıkı bir nefes aldım

Açıverdim eteğimi

Onlarda sıkılmış

dörtbir yana kaçıştılar..

Şimdi içim bembeyaz

Boş..

Hiççç...

Ve hep merak ettiğim

Cesaret edemeyip 

Özlemini çektiğim

Sıfır noktasındayım', 'Sahiplendim yıllar boyu Biriktirdim Sevgiler, hüzünler Kurallar, değerler,  Sorumluluklar, önyargılar,  kabullenmişlikler,  incinmeler,  mel...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ve-beyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitlenmişim Aşkım', 'bitlenmisim-askim-kibar-tavasav-roqcx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıl: 1993

Kuzey Irak  haftanin bölgesi

İçimde bin dokuz yüz otuz sekiz’in sızısı

Kan tükürüyor geçen yıllar döşüme

Ben senin için buradayım

Sen toprakta 

Kalk Allah aşkına Atam bana yalvartma

Aşkım 

Bu sana yazdığım kaçıncı mektup 

Sorma bilemiyorum

Sorma ne yazdığımı da bilmiyorum 

Bildiğim tek şey sen  ve TÜRKİYE

Ancak bunu diyebiliyorum

Bu gün on kasım 

Ölüm yıl dönümü Atamızın ve ben sana yazıyor

Özlüyor ve sizleri seviyorum 

Bitlenmişim aşkım

Sağanak yağmurun, sert esen güz rüzgarlarıyla hüküm sürdüğü  kap kara koca dağların doruklarında  üç metre önümüzü göremediğimiz  esrarlı bir gecede aklımdasın... 

Yürüdük zamanın öte yakasından bu satırları yazdığım gerçeğe doğru 

Islandık, 

Yıkandık, 

Üşüdük, 

Sel oldu aşkımız,... 

Okyanuslarda fırtınaya yakalanmış  dört ağaç gövdesinden oluşmuş bir sal gibi  ufukta bilinmeyen fakat var olan zamana doğru  sürüklendik hain gecenin içimize yüklediği hasret kokan şarkıların eşliğinde. Bir,bir yalnızlık ve sevda türküleri tutturduk yürüdüğümüz bu ıssız yolculukta. Ruhumuzu ve canımızı koltuk altımızda taşıyarak  koşuşturduk yalnız lık kokan patikalarda. 

Sevdamız koştu içimizde coşkuyla 

Sen koştun içimde dolu dizgin 

Yanık motor yağını boş bir kola kutusunun içine döküp  üslübüyü mum ipliği niyetine  yağın içine batırıp yakarak 

Taş duvarlarını aydınlattığımız  zik  zaklar çizen habur çayının yakınlarındaki  kayalık bir tepenin eteğinde bulunan  beş insanın sığabileceği genişlikte, küf kokan, loş karanlık bir mağaradayız. Bodur çalılar kaplamış mağaranın girişini. Loş ışıkta bedenlerimiz bizden daha büyük yansıyor, yarık ve çatlakların yer aldığı mağaranın duvarlarında  örümcek ağları yer almakta. Bu ağlarda yer, yer örümceklerin içlerini yedikleri  sinek iskeletleri göze çarpmaktadır. Ağların üstlerinde parmak büyüklüğüne yakın  örümcekler avını beklerken hareketsiz durmakta 

Bu çatlak ve yarıklardan içeri dışarı  tesbih böcekleri, kırk ayaklar dolanmaktadır. 

Şurada taş duvarın dibinde 

Sırt çantam duruyor 

Sevda yüklü içi 

Hasret yüklü tutam, tutam 

Sen yüklüsün... 

Yoruldum çok, omuzlarımda 

Seni taşıdığım bu yükün altında 

Yinede taşıdım ama sen yoksun 

Vay kahpe felek vay! ... 

Parkam, pedim, pançom var sevdamın yanında, çift şarjörlü, dürbünlü, bomba atarlı  gece görüşe ayarlı, pointer''li tüfeğim  dayalı durmakta sırt çantama.  Biraz önce yağmurdan ıslanan tüfeğimden, ıslattığım için özür dileyip 

Bir gelin gibi okşayarak temizledim. Islak mermilerini mendilimle sildim. 

Şimdi yanık yağın aydınlığında  parıldayarak neşeli, neşeli bana bakıyor.

Bu yağmurda biz buraya sığınıncaya kadar 

Kaç saat yol aldık, 

Kaç saat yürüdük, 

İnan seni düşünürken hiç hatırlamıyorum. yalnız sabah gün ağarmıştı tan sökümünde, şimdi ortalık karanlık. 

İşte bu geçen zaman sürecinde  sen hep yanımdaydın. Şu an ise ölümsüz satırlara dökülüyorsun gönlümden 

Eline geçtiğinde bu dizeleri okuyacaksın 

Biz yürüdük yağmurda... 

Yağmur yağdı üstümüze 

Biz yürüdük yağmurda... 

Yağmur yağdı içimize, soluksuz, nefessiz, ta katsız kaldık  ve kilotlarımıza kadarda ıslandık.

Bu sensiz, soğuk, ürperten karanlıklarda İliklerimiz su doldu ve üşüttü beni 

Bak keskin kokulu havasız mağaranın  şu tarafında, dışarıdan topladığımız  yağmur suyu içmiş, ıslak çalıları tutuşturmak için  şiir defterimden yırttığım sayfalarla yaktığım  yüzümüzü yalayan ateş yanıyor.

Yüksekliği yüz elli santimetre olan  sadece bir insanın geçebileceği genişlikteki  bu rutubetli mağaranın kapısına ateşin ışığının dışarıya yansımaması için  battaniyemi gerdim. 

İşte ben sana bu mektubu  sığındığımız bu kasvetli mağarada  soğuk taştan duvarları olan  kapısındaki battaniyenin parmaklık olduğu  bir mahpushaneden yazıyorum.

Gönlüm kalem oldu, 

Sevgim sayfalar, 

Dökülüyorum sana, gönlüne 

Sana olan sevdam dağların doruklarındaki karı 

Tek bir nefesimle yere indirecek kadar 

ve şu an seni çok özlüyorum 

Ateşten çıkan duman mağaranın kapısındaki battaniyeden dışarıya çıkamadan, içeriye dolup  gözlerimi yaşartıyor.

Bu yaşlar üşümüş yanaklarımdan  süzülüp buz gibi soğuyarak  boynumdan aşağı inip  yanan içimi serinleterek, birazda üşüterek koynuma doluyor. 

Ben göremiyorum ama arkadaşlarım  göz yaşlarımda senin adının yazdığını söylüyor. 

Adın süzüle, süzüle soğuk bir esintiyle 

Yağmurdan ıslanmış, 

Yürümekten terlemiş, 

Soğuktan üşümüş içime, 

Göz yaşlarımın içinde billur, billur akıyor aşkım 

Sen akıyorsun içime 

Yağ işte, dol gönlüme durma 

Söndür ateşimi, titreyeyim varlığınla 

Sür yüzünü kaç gündür kesemediğim 

Uzamış, içinde beş beyaz teli saklayan sakallarıma 

Bende doyayım sana 

Sırt çantamda haki renkli kalın kazağım var. Havlum, playboy dergisi haziranda izinde aldığım. Yüzümü silip, biraz kadın vücutlarına baktım. En son ne zaman gördüm bir kadını  aha vallahi hatırlayamadım. 

Bırak vücudunu bir yana  kadın göremiyorum ki daha ne diyeyim. 

Belki inanmayacaksın ama  izinden gelirken bir kadın kokusu aldım. 

Arada sırada çıkarıp kokluyorum 

Sırt çantamda bir kaç parça bir şeyler daha var ve... 

Boydan çekilmiş bir resmin 

Gülümsüyorsun resminde, sanki yanımdasın 

Sıcak nefesin vuruyor, resmine bakarken yüzüme 

Yağmurdan ıslanmış resmini  ateşte kurutmaya çalışıyorum 

Kuruturken tutuşuyor saçların 

Ben tutuşuyorum 

Yanıyorsun 

Yanıyorum 

Bir tarafından yanık saçlarının kaldığı 

Resmin elimde öylece ortada kala kalıyorum 

Hayal olmuş çıplak bedenin  bir an bile çıkmıyor aklımdan, gitmiyor gözlerimden. 

Sen ne yaptın böyle bana 

Vuruyorum ben de bu sersem başımı  mağaranın taş duvarlarına 

Niye diye sorma bana, anla işte 

Hafızamı yitirip dağ, dağ memelerini unutmak için 

Belki hayal olacak ama  allı, beyazlı bir gelin gibi  yağmur yerine sen dökülsen üstüme  tutuşurum işte o an teninde ve... 

Söndüremez yanık kokuları yayılırken etrafa beni hiç kimse 

Yanarım! ... 

Midyelerin içinde incileşen kum taneleri gibi 

Efsunlu gözlerle baksan gözlerime dilim, yüreğim, her şeyim efsunkar kalır gözlerinin içinde 

Kül olurum! ... 

Geçen zamanı kollarken tetikte  ben de yürüsem şeytanın ayak izlerinde 

Tutuşurum 

Tutuşurda  söndüremez beni tüm bulutların yağmurları inse bile üstüme 

Adına yaşamak dediğimiz feryat  dağları delip serhat bile olsak budur işte 

Oysa senden önce kaç tane kadın geçti yatağımdan 

Kaç kadına dokundu ateşli vücuduma 

Kaç incecik narin kadın parmakları gezindi omuzlarımı 

Kaç batan tırnak kırıldı etimin içinde 

Kaç dudak emdi dudaklarımı ve ben emdim 

Kaç kadın inledi sabaha kadar 

Kaç kadın beni inletti ateşli gecelerde 

Evet hepsi senin tenimde doğuşunla  bir bıçak gibi kesilerek silinip kazındı şimdi yok hafızamda 

Öyle bir girdin ki vücuduma  sanki aıds''e tutuldum. 

Hiç bir zaman silinemeyecek şekilde kanata, kanata kalbime kazındın 

Yürü tenimde yürüyebildiğin kadar 

Yürü... 

Sana açık, 

Sana özgür vücudumdaki her santimetre kare toprağım 

Dokun bana,... 

Öp, 

Hadi ısır, sustur dilimi 

Göm satırlarda konuşan dudaklarıma dudaklarını 

Ellerin gezinsin boynumda, aşağılarda 

Bende bu başımı dağ dağ memelerine yaslayıp uyuyayım  meleklerin benim için kurduğu salıncaklarda

Ne olur meleğim uyuyayım

Biliyor musun kaç gündür hiç uyumadım? 

Kaç gündür yollardayım 

Kaç gündür seni arzulamaktayım 

Ayaklarıma giydiğim çoraplar kağıt olmuş  parmaklarım çıkmış dışarıya, erimiş altları 

Gözlerim kanlı, altı şişmiş olmuş mosmor kan bardağı, yıkadıkça dumandan akan göz yaşlarım  cayır, cayır yanıyor mosmor olmuş gözlerimin altındaki kan bardaklarım. 

Yanıyorum ben acı acı, 

Hani ateş basmayı, 

Hani kor ateşte yanmayı, 

Hani alev, alev erimeyi, 

Hani yanarken terlemeyi yaşıyorum ben yudum, yudum ah! 

Çok zormuş sensiz olmak 

Çok zormuş ağlarken gülmeye çalışmak, böyle tutuşurcasına yanmak 

Yani böyle ateşlerde kalmak, yaşarken işte yaşamamak  zormuş, 

Çok zormuş,... 

Bunu şimdi ben çok daha iyi anladım 

Soydum tükenmek bilmeyen derman yüklü bedenimi  iç çamaşırlarıyla kaldım  terim ıslak ve titriyorum biraz canım 

Derinlerimden bir pınar gibi ne kadar silsem de akıyor debisini hiç kesmeden içimden tekrar terim. 

Bu terin ıslaklığında üşüyorum  bir birine vuruyor dişlerim, dudaklarım, 

Ateşin yanında dizlerime koyduğum  kürkümle, elbiselerimi kurutuyorum 

Yürüdükçe beyaz köpüklerden bir harita yapmış terimdeki tuzlarla elbiselerimde bedenim. 

İşte Ege, Marmara 

İşte Karadeniz, Akdeniz 

İşte Van gölü 

İşte Trakya, Anadolu 

Çizmiş bir bir tenim misakı-milli hudutlarını  ama ben ne yazık ki dışarıda kaldım. 

Elbiselerimden duman olmuş buhar çıkıyor. 

Islak, terli, çıplak bedenimden  mağaranın tavanına duman, duman bir şeyler yükseliyor 

Sevdam yükseliyor 

Sevdam buhar olup mağaranın içine doluyor 

Sökemiyorum 

Yakamıyorum 

Atamıyorum içimden seni 

Ne yapacağımı artık çok şaşırdım 

Hangi dağa çıksam 

Hangi ırmakta yıkansam 

Hangi uçurumdan iple insem 

Hangi vadinin patikalarında dolansam 

Kim söker seni bir kerpeden gibi içimden 

Kim dağlar kalbimi 

Kim unutturur seni bana 

Yada hangi kurşunla vurulayım kalbimden sonsuza kadar yok olman için 

Doçka mı? 

Bikeyzi  mi? 

Kanas mı? 

Yada bin metreden beni param parça etmek için  üstüme, üstüme gelen bir re pe ge on bir  roketiyle mi? 

Yoksa elektrik fünyeli, beş kiloluk bir tnt kalıbıyla  hazırlanmış bubi tuzağıyla 

Yetmiş beş parçaya bölünüp 

Yetmiş beş akbabanın sivri gagalarının arasında parçalanarak mı? 

Söyle Allahsız söyle! 

Vurma beni ölümden beter edipte 

Sen kalbimde büyüdükçe 

Ben kabul edemeyip isyanlardayım 

Söyle nasıl sakin olayım? 

Ya da söyle nasıl kendimi avutayım? 

Mor dağları mı indirip yıkayım? 

Irmakların yollarını mı değiştireyim? 

Dünyadaki tüm zehirleri karıştırıp 

Yetmişlik bir şişenin içinde iki saniyede dibini mi bulayım 

Yada ne yapayım söyle? 

Sen hangi zehirsinde içtim ben seni böyle? 

Yüreğimi parçalarcasına...  Allah kahretsin

Görüyor musun?  Efkarın kucağında  yaktığım sigarayla konuşuyorum bir başıma o bile senin gibi duman olup benden kaçıyor. 

Bu nedir Allah aşkına 

Yangınlardayım 

Soyunda gel yanıma 

Sana görünse de sana değil aslında isyanım 

Ben aramızdaki aşamadığım mesafelerle kavgalardayım 

Yıkılsın! 

Yıkılayım! 

Ellerini tutamadığımdan 

Gözlerine bakamadığımdan 

Seni sevip okşayamadığımdan 

Sana sarılıp dokunamadığımdan 

Dudaklarında yaşayamadığımdandır bu isyanım 

Başka bir şeye değil 

Saat gecenin yirmi üç otuz beş i...  yağmur yağıyor hala, baykuşlar ötmekte dışarıda 

Mağaranın köşesinde yanan ateşin üstünde  fokur, fokur bir çaydanlık kaynıyor 

Biraz sonra arap çayıyla habur kenarında yakalayıp ta  bıçağımla başını kesip  baş ve kuyruk deliklerini çamurla kapatarak  ateşte pişmeye bıraktığımız tospağa ile  derisini yüzüp, baş ve kuyruk kısımlarından  birer karış kesip çakallara attığımız, kalan beş karışını da  ateşte kızartıp, beş parçaya bölerek paylaştığımız  kara yılanla karnımızı doyuracağız. 

Pişen tospağanın kokusu mis gibi içimizi dolduruyor 

Ateşte pişen üst kabuğu açılarak  nar gibi kızarmış sırt eti açığa çıkıyor 

Yutkunuyorum... 

Çok açım, 

Ama ekmeğimiz ıslanmış,  yani ekmeksiz kaldık, 

Olsun aşkım,... 

Yüklü bulutların yeryüzüne serbest bıraktığı  bereket dolu yağmurlar yağdı  her yer kurbağa ve solucan kaynıyor.

Toplayıp  on altı litrelik bir yağ tenekesinin kapağında pişirip tuzlayarak kurbağanın sadece arka bacaklarını  ve ateşte kıkırdak halini alan solucanları cips olarak yemekten sonra yiyeceğiz. 

Baharatımız özlem, sevda oldu 

Dostluk, arkadaşlık salatamız 

Hadi bebeğim sende bir öpücük ver de 

Tam doysun bu gece karnım 

Mağaranın soğuk taştan duvarlarına militanlar '''' Gebereceksiniz Türk Ordusu '''' yazmışlar 

Gülüyorum)))   

Bende elime sivri bir kaya parçası alıp 

'''' Bendensiniz, öpeceğim sizi eşkıya lar '''' yazıyorum)))   

Belli ki onlarda burayı kullanmışlar, kim bilir belki de çok yakınımızdalar, hatta belki de bizi de görüyorlar. 

Hadi ulan çıkın ortaya, biz buradayız, siz neredesiniz? 

Nerede alçak yürekleriniz, sakın azmayın, aklınızı alırım 

Biz sizlerin ve bu dağların efendisiyiz 

Bitlenmişim aşkım! ... 

İç çamaşırlarımın dikiş aralarını toprak biti kaplamış  tatlı, tatlı kaşındırıyorlar. 

Yemekten sonra arkadaşlarla bisküi kutusunun üstünde sigarasına yarıştıracağız 

Yarışa katılacak bitimin koydum sıfır üç Osman adını da 

Kahve renkli bir şey  başı küçük, karnı şişkince  ayakları kısa, yere yapışık yürüyor ama heybetli 

Bir sevgilisi var sıfır üç Osman ın, onunda adını koydum şule sıfır yedi, ne çocuklar doğuracaklar ırklarına 

İçlerinden en irileri sıfır üç Osman  galiba vücudumun efendisi aynı zamanda onların reisi o 

Belli ki bileğinin hakkıyla çok kanımı emerek gelmiş bu duruma, çok çalışmış,kim bilir nerelerimde gezindi

Acaba gözleri var mı? Yok galiba bildiğim kadarıyla 

Sıfır üç Osman ın sırt kısmı şeffaf beyaz 

yarışı kazanırsa sevgilisi şuleyle beraber dört saat  koltuğumun altında ödül olarak balayında kalacak sıfır üç Osman 

Emsinler kanımı emebildikleri kadar 

Madem biz evlenemiyoruz  onlar evlensin 

Yuva yapmak sevaptır nede olsa 

Helal olsun kanım birinci gelecek sıfır üç Osman a 

Osmanlar, şuleler benim alın terim, hizmetlerim 

Tanrının ödül olarak bana verdiği bir armağan 

Wolkmen radyomun kulaklıkları kulağımda  en çok sevdiğim şarkılar çalıyor şu anda 

Biraz önce Kıraç; 

'''' Kara hisar kalesi yıkılır geliri '''' i söyledi 

Şimdide Cem Karaca; 

'''' Vurun ulan vurun, vurun 

Ben kolay ölmem 

Ocakta küllenmiş aşım var 

Kirvem hallarını böyle yaz 

Rivayet olur belki 

Gül memeler değil bu domdom kurşunu 

Param parça ağızındaki '''' yi söylüyor 

Bende eriyorum bu şarkılarda, 

Bitiyorum... 

Hiç bir acı 

Hiç bir yorgunluk 

Hiç bir şey senin yokluğun kadar koymuyor bu Tanrının kulu Kibar''a 

Hiç bir mutlu olay senin yanımda olma mutluluğunu 

Hiç bir zaman yaşatmıyor bana 

Yokluğunda mor dağlar sanki üstüme kapaklanıyor 

Hasretim sana 

Hasretim denizin dalgasını andıran saçlarına 

Hasretim beni içine çeken okyanus dudaklarına 

Aşkım 

Bir gün namert bir namlunun ağzından çıkan kahpe bir kurşunla vurulup ta  toprağa düşersem eğer  sakın ardımdan ağlama 

Bil ki ben çok mutluyum bu yolda yok olmaktan 

Yalnız ne olur  mezarımı kırmızı beyaz ve kokulu çiçeklerle süsle 

Arada bir gübrele, çapala, sula 

Genç, diri bir çınar dik baş ucuma  kök salsın  toprağımda 

Sonra beni unut Allah aşkına 

Bu gün denizlerde seninle beraber olamıyoruz belki ama 

Bir gün mutlaka buluşacağız bir tanem ikimiz okyanuslarda 

Öptüm bal tadındaki dudaklarından 

Hoş çakal 

Sınır kartalı 

Kibar', 'Yıl: 1993 Kuzey Irak  haftanin bölgesi İçimde bin dokuz yüz otuz sekiz’in sızısı Kan tükürüyor geçen yıllar döşüme Ben senin için buradayım ...', ARRAY['Türk Edebiyatı','Şiir','Kibar Tavasav']::text[], 8.5, '{"poet":"Kibar Tavasav","poet_slug":"kibar-tavasav","theme":"Türk Şiiri","is_hero":false,"total_lines":276,"source_url":"https://www.antoloji.com/bitlenmisim-askim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Yaşıyorum', 'gozlerinde-yasiyorum-i-smail-ateran-lx2dx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünyayı dolaşmak, şehirleri gezmek istiyorum

Sokaklarda kaybolmak, seni daha çok tanıdık 

Hissetmek, istiyorum

Dizlerinde uyumak

Koşmak soluk soluğa, nefessiz koşmak 

Çünkü, sana koşmak! 

Sana, ekmeğe, suya, havaya gözlerinde

Doymak istiyorum

Bunları gözlerinde yaşamak mümkün ela

Sen gözlerini hiç yumma!', 'Dünyayı dolaşmak, şehirleri gezmek istiyorum Sokaklarda kaybolmak, seni daha çok tanıdık  Hissetmek, istiyorum Dizlerinde uyumak Koşmak solu...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ateran']::text[], 8.5, '{"poet":"İsmail Ateran","poet_slug":"i-smail-ateran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerinde-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Adım Umut', 'benim-adim-umut-kamil-aydemir-nhhmv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'halen daha içime hüzün damlar

akşam karanlığında sarıyı giyinince camlar

beni santım santım büyüttü sokaklar

aç kaldım

susuz kaldım

çöplerden yiyecek topladım

acısını bilirim

hiç kimsenin sevinçlerini çalmadım

zorlukları onurumla adımladım

ben koydum adımı

umut benim adım

sanki iki kanatsız yavru kuştum

sokaklara çocukluğumda düştüm

geceleri saçak altlarına iliştim

üşüdüğümde üzerime yıldızları örttüm

bazı geceler annem sanıp ayı öptüm

bu mangal gibi yüreği

sokaklarda büyüttüm

cazibelerine kapılmayın görülselerde loş

ben sokakların adamıyım

yırtık ceplerim boş

yaralı yüreğim dolu

ustamdan öğrendim insana çıkan yolu

kanarsın dostum dokunma saklıma

ateş böcekleri düştükçe aklıma

ateş yakarım ülkemin karanlıklarına

sevdam nasılda yakışır nasırlı avuçlarıma

kendimi yakıştırırım dik duran insanların arasına

güneş dökerim çocukların yarasına

taşımaktan bıktım emanet gülüşleri

yorgun evlerin solgun duvarlarına

mıhlar beni duvar yazıları

düşlerimi büyütür bazıları

ayaz gecelerde dişlerimi kırdım da yakmadım

güzel günlerin davetiyesi afişleri

katmerli yedim zehir zemberek acıları

acılarda olgunlaştırır insanı

zorlukların en berbatlarını yaşadım

ama satmadım kendimi ve hüriyetimi

sokakların hediyesi bir kızı sevdim

ince uzun bacaklı

biraz da meraklı

yere çakılmıştı yukarlardaki aklı

öğrenince yıkıldım etini sattığını

sevdamı başka kollarda yıprattığını

hiç görmedim

fayşelerin sokakları kirlettiğini

tanığıyım çağımın getirmeliyim dile

zor inandırdım gözlerime bile

faili meçhul  listesine eklenenlere tetik yıkanları

ve adları kahramana çıkanları

dönen fırıldakları

sönen ocakları

kirli insanlar boşuna sevmiyor karanlıkları

ben sokaların adamı

çırağıyım hayat denen ustanın

hayal kırıklığına uğratmadım ustamı

“her koyun kendi bacağından asılır”

deselerde inanma

kör değilse yüreğin

acısı gelir seni bulur

tanımam anamı ama

anaların gözyaşları beni vurur

bana soran olmadı sorsalardı

  sokaklarda büyüyecegimi bilseydim

    doğmayı istemezdim

hayatın hoyrat ellerinde yoğruldum

acılara takılıp her düştüğümde 

insanlığıma tutunup doğruldum

öğrenciyim hayat okulunda

öğrenmeyi öğrendim

sevmeyi sevdim

günlerin girişinde ülkemin kanatıldığını görmeseydim

sokaklara düşürülmüş

     nice umutların toplamıyım ben

sokaklardan geldim

ama sokaklar benden sorulmaz 

beni de sokaklara sormayın

sokaklar adresimi bilmez

kötü insanlar sevmeyi

isterim ki

insan kardeşim unutma gülmeyi

yanından hiç ayırma düşünmeyi

güzelliklere aç

güzel günlere yüreği

bir ülkenin aynasıdır sokaklar

topraklar kan

               can kokuyorsa şafaklar

her taraftan yükseliyorsa pis kokular

çoğunluktadır korkaklar

ama tarih dürüst olanı aklar

bu kirliliğe layık değil insan

kendine bile hayrın olmaz ayakta duramasan

hadi arkadaşım elimden tut

benim adım umut', 'halen daha içime hüzün damlar akşam karanlığında sarıyı giyinince camlar beni santım santım büyüttü sokaklar aç kaldım susuz kaldım çöplerde...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/benim-adim-umut-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılarından da Uzat Bana', 'acilarindan-da-uzat-bana-kamil-aydemir-jrrhq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hep takılıyor acılarda

dünya sanki bozuk plak

yaşlı gözler bana tuzak

olsa da firarda

mutluluk değil uzak

ne de hayat rüya

yerin olmasın korkuya

gönlümün kapısını açarak

insanlığımla geldim sana

acılarından da uzat bana

içinin karalmasını

yüreğinin ağlamasını

                        ve yasını

azaltırm bel ki

acılarını paylaşarak

mutluluğun kanatlarından da tutarız inan ki

hayatın aşk limanına yanaşarak

anılarınla avunma

oyun olmaz zamanla

yüzünü yarına dönmek yakışır insana

acılarından da uzat bana

güzel günler vermek istiyorum sana

yeter ki gönlünün kapısını aç sevdama

yalnızlığımla kalacaksam yine ben

git seni daha fazla sevmeden', 'hep takılıyor acılarda dünya sanki bozuk plak yaşlı gözler bana tuzak olsa da firarda mutluluk değil uzak ne de hayat rüya yerin olmasın kor...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/acilarindan-da-uzat-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkamızda Kalan Duygular...', 'arkamizda-kalan-duygular-hulya-topcuoglu-jbdw6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangimiz yaşamadık

Çocuksu heyecanları

Hangimiz estirmedik

Yüreğimizde fırtınaları 

Bazen mutlu da olduk 

Çoğu kez ağlasak da 

Boşverdiğimiz de oldu 

Kahreden mutsuzluklara

Bazen bir hovarda gibi

Döktük saçtık aşkları 

Ağlattığımızda oldu

Arkamızda kalan duyguları....', 'Hangimiz yaşamadık Çocuksu heyecanları Hangimiz estirmedik Yüreğimizde fırtınaları  Bazen mutlu da olduk  Çoğu kez ağlasak da  Boşverdiğimiz...', ARRAY['Türk Edebiyatı','Şiir','Hülya Topçuoğlu']::text[], 8.5, '{"poet":"Hülya Topçuoğlu","poet_slug":"hulya-topcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/arkamizda-kalan-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan İnsanlık', 'kaybolan-i-nsanlik-hatice-kuzu-imm0b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulutlar dolaşıyor gökyüzünde

Evlerden hüzünlü sesler geliyor bugün

Çocukların boynu bükülmüş hep

Güllerse dalında solmuş renk renk...

İnsanların yüzünden düşen bin parça, 

Nağmeler kırık dökük.

Masanın üzerinde parçalanmış bir çerçeve

Esen rüzgarla savruluyor yırtılmış resimler yere.

Kırılan camlar değil, canlar olmuş sanki.

En değerli duyguların yitirildiği an

Yakalamaya çalışıyorum, durduramıyorum

Akıp gidiyor esen rüzgarla zaman...

Yitirilen neydi o ılık sonbahar akşamında

Ve geriye kalan neydi kurşun yarası gibi içimde

Uzatıyorum başımı kırık camların arasından

Bağırıyorum haykırırcasına:

-Tüm dünyayı, tüm insanları yok sayarak-

“ Yüreğimdeki bu savaş bitsin artık “

“ Kahrolsun yürek emperyalistleri”

16 Kasım 2001 İstanbul', 'Bulutlar dolaşıyor gökyüzünde Evlerden hüzünlü sesler geliyor bugün Çocukların boynu bükülmüş hep Güllerse dalında solmuş renk renk... İnsan...', ARRAY['Türk Edebiyatı','Şiir','Hatice Kuzu']::text[], 8.5, '{"poet":"Hatice Kuzu","poet_slug":"hatice-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kaybolan-insanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Şaşkın Şair''im Ben', 'saskin-sair-im-ben-cemal-karsavran-tqhxh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen benim için nesin bilirmisin

yüreğimin hoyrat çayırlarında kıpırdayan 

gözlerimde uçuşan

kelebek kadar zarif

şuan kadar yakınsın

tutmak istediğimde sol yanımdasın

gözlerim düştü parmaklarıma

güneş yüzüme

hiç düşünemiyeceğim kadar yakın

hergün beklediğim durakta 

yola çıktı senin için gözlerim

ve göğsümde karanfilim

simgelerim küçülüyor

aşıp giden güneşle

fakir yüreğimde

ufukta yedi dünya

resmini çiziyorum buluta

engin mavilerde

içimdesin kalp atışlarımda

hiç tanımadığım 

bilmediğim kadar

yitik düşlersin

labirent bulmacanın

çözümüsün öğrendiğim 

imlası yanlış şiir''imin

ilk ve son mısrasısın

şaşkın şair''im ben', 'sen benim için nesin bilirmisin yüreğimin hoyrat çayırlarında kıpırdayan  gözlerimde uçuşan kelebek kadar zarif şuan kadar yakınsın tutmak i...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/saskin-sair-im-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Deliklerin Sonunda', 'kara-deliklerin-sonunda-naime-erlacin-rywmc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sıcaklık akıyor yüreğime

suya karışıyor buzum

yürüyor su

nerden geliyor bu ateş! 

 sevginin sesi çınlıyor kulaklarımda

dağları aşıp bana ulaşıyor

kimden çınlıyor ses! 

kara delikleri geçeli çok oldu

kalbin yedi kat dibine gömdüm cehennemi

dipsiz kuyularına uykusuzluğun

keşiş oldum 

çilekeş oldum

gide gide ancak vardım sınırlarıma

boşluğa sızarak sonsuzda 

yaşamın sihrine terk ettim gizlerimi

aynalığını unutturdum aynalara

bakınca göremediğiniz bir yerdeyim

oldukça yakınınızda ve çok uzaklarda

işte yine o ses! 

hıçkırıkları içinde saklayan

benimle savaşan

bir yandan aşka tutunan

bana dair 

bana teslim bir armağan

yürüsün su

yürüsün aşk! 

(11 Ekim 2003)  - Aşk Sözcükleri Dosyasından', 'sıcaklık akıyor yüreğime suya karışıyor buzum yürüyor su nerden geliyor bu ateş!   sevginin sesi çınlıyor kulaklarımda dağları aşıp bana ula...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kara-deliklerin-sonunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-ozgur-kayim-1fwyp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlığım, 

İnsanlığım, 

Dağıtmak için aldığım 

şekerin, 

Tamamını ben yedim...', 'Yalnızlığım,  İnsanlığım,  Dağıtmak için aldığım  şekerin,  Tamamını ben yedim......', ARRAY['Türk Edebiyatı','Şiir','Özgür Kayım']::text[], 8.5, '{"poet":"Özgür Kayım","poet_slug":"ozgur-kayim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yalnizligim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kamp İnsanları', 'kamp-i-nsanlari-ozgur-kayim-bssrv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kamp insanları, 

hitler Almanyasında, 

			ya da Kamboçya’da, 

Kamp insanları, 

 Sırbistan’da, Avustralya’da, 

			ya da Afrika’da, 

Kamp insanları, 

		susuz, aç, 

			    dizi, dizi, 

Kamp insanları

		bitkin, solgun, 

				ağızları dikili, 

Kamp çocukları öksüz, 

		kamp kadınları yanlız, 

Kamp erkekleri tedirgin, 

		başları öne eğik, 

				erkekliklerinden utandıkları belli, 

Kalbim vuruyor “kamp”, “kamp”, 

Beynim zonkluyor “kamp”, “kamp”, 

Elimde “kamp”,  dilimde “kamp”, 

Kampana sesleri arasında kamp insanları 

izliyor bizi, hepimizi.', 'Kamp insanları,  hitler Almanyasında,  			ya da Kamboçya’da,  Kamp insanları,   Sırbistan’da, Avustralya’da,  			ya da Afrika’da,  Kamp insa...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kayım']::text[], 8.5, '{"poet":"Özgür Kayım","poet_slug":"ozgur-kayim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kamp-insanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fanus', 'fanus-yildiz-yildiz-mdaxo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kristal fanus içinde

Korunmadaydı yüreğim.

İncinmesin acımasın diye

Tüm önlemler alınmış. 

İncinmedi, acıtamadı kimse, 

Ama fanusun içinde soluksuz kalmış.

Kalbim kırılmadı da 

Kırıldı kristal  kafesim 

Buz rengi cam kırıklarının içinde 

Kanamadı da buza kesti kalbim', 'Bir kristal fanus içinde Korunmadaydı yüreğim. İncinmesin acımasın diye Tüm önlemler alınmış.  İncinmedi, acıtamadı kimse,  Ama fanusun için...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/fanus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Umut', 'merhaba-umut-i-srafil-yildizkan-s2zes', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu ilk değil

Fırtınaya yakalanışım, 

Sarp kayalıklar dan yuvarlanışım.

Bu kaçıncı ölümüm, 

Kaçıncı dirilişim bilmiyorum.

Şu nu öğrendim ki; 

Nerede? 

   Ne durum da olursam olayım, 

Bir yerlerden 

   bir güneş doğar 

Öldüğümü, 

   yok olduğumu sandığım anlarda.

Ve ben de; 

Güneş ile birlikte yeniden doğarım.

Merhaba dünya.

  Merhaba insanlar.

    Merhaba tüm güzellikler.

Merhaba umut..', 'Bu ilk değil Fırtınaya yakalanışım,  Sarp kayalıklar dan yuvarlanışım. Bu kaçıncı ölümüm,  Kaçıncı dirilişim bilmiyorum. Şu nu öğrendim ki; ...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Yıldızkan']::text[], 8.5, '{"poet":"İsrafil Yıldızkan","poet_slug":"i-srafil-yildizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/merhaba-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak simdi!', 'bak-simdi-seref-kaya-ijqa0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak simdi! 

Bos duygularla, dolu degil icim! 

Sobahar geldi, yaprak dökümü basladi! 

Icimde ki bos sevdalar gibi dökülecekler! 

Zor da olsa, unutmak teker, teker, silinecekler. 

                                                            

06-10.03.Ffm.D seref kaya', 'Bak simdi!  Bos duygularla, dolu degil icim!  Sobahar geldi, yaprak dökümü basladi!  Icimde ki bos sevdalar gibi dökülecekler!  Zor da olsa,...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bak-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altmışsekiz', 'altmissekiz-halim-yazici-igpfz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'boyun atkısına bakıp göğün ağlardık

gizli gizli, kırmızı, gizli

düşlerimiz vardı

ateşböceği yüreğinden damlayan

tutunup kanatlarına alevden yelesine aşkın

kor olur uçardık, ölürdük, çocuktuk

gizli gizli, kırmızı, gizli

öldük.', 'boyun atkısına bakıp göğün ağlardık gizli gizli, kırmızı, gizli düşlerimiz vardı ateşböceği yüreğinden damlayan tutunup kanatlarına alevden ...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/altmissekiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kardeş', 'ask-kardes-halim-yazici-ox4h3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'durakta na beklenir sence serçe kardeş

patiska eteğini yıldızlara savuran ses

sende ne beklenir sence aşk kardeş

rüzgârların getirdiği yıldız tenesi ipekten sis

uçurtmalarım yırtılır, kasnaklarım kırılır

bildiğim ne varsa yeniden biçimlernir

bilmem neden ikiye ayrılır orta yerinden

bu deniz yeniden

yağmurlar ıslanır

bunu yapar hep deli vapurlar

görmezlikten gelir

üstelik seni bütün körler

süzerken kalbini kan tanesi

a kardeş aşklar.', 'durakta na beklenir sence serçe kardeş patiska eteğini yıldızlara savuran ses sende ne beklenir sence aşk kardeş rüzgârların getirdiği yıldı...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokun Tenine Denizlerimin', 'dokun-tenine-denizlerimin-halim-yazici-vj9j0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mintanı mavi desenli çocuk

sislerini arala, gir koynuna düşlerimin

dokun tenine denizlerimin

hanidir kanatları üşüyor sensizliğimin

nasıl da büyüyor gözleri çocukluğumun

işte bu aşk benim istediğim

düşleri mavi çiniler çoğaltan çocuk

usulca gir koynuna aşklarımın

sesinde tahta at arabalarının

işittim bütün güvercinlerini annemin

yum gözlerini çocukluğum

ki sarsın ömrünü bir ölü güzgârgülü.', 'mintanı mavi desenli çocuk sislerini arala, gir koynuna düşlerimin dokun tenine denizlerimin hanidir kanatları üşüyor sensizliğimin nasıl da...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dokun-tenine-denizlerimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekliyorum', 'seni-bekliyorum-rafet-maden-qiapp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman hasretin çökse üzerime, 

Tanrıma el açıp seni istiyorum.

Resmini saklıyorum cebimde, 

Gittiğin yollardan seni bekliyorum.

İmreniyorum uçan kuşlara, 

Gelmek istiyorum senin yanına, 

Kanadı kırık bir kuşum burada, 

İlacım sensin seni bekliyorum.

Biliyorum birgün bitecek dertlerimiz, 

Hiç ayrılmayacak bu ellerimiz, 

Bizim herşeyimiz yüce sevgimiz, 

O günlere doğru seni bekliyorum.', 'Ne zaman hasretin çökse üzerime,  Tanrıma el açıp seni istiyorum. Resmini saklıyorum cebimde,  Gittiğin yollardan seni bekliyorum. İmreniyor...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-bekliyorum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekliyor', 'seni-bekliyor-rafet-maden-hl3i1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçmişe hasret duyan birisiyim, 

Gönlümde bir sarhoş var dur diyor.

Anılar canlandı şimdi sevgilim, 

İçimde bir his seni bekliyor.

Kapılar her an açılacakmış gibi, 

Kulaklarım sesini duyacakmış gibi, 

Kalbim yerinden fırlayacakmış gibi, 

Aklımda bir soru seni bekliyor.

Kimseye derdimi açamaz oldum, 

Mutluluk yolunu seçemez oldum, 

Ayaklarım prangalı kaçamaz oldum, 

Yollarda bedenim seni bekliyor.

(KÜTAHYA-1997)', 'Geçmişe hasret duyan birisiyim,  Gönlümde bir sarhoş var dur diyor. Anılar canlandı şimdi sevgilim,  İçimde bir his seni bekliyor. Kapılar h...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-bekliyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Cazdır', 'ask-cazdir-halim-yazici-yytba', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'terimin terine bulaştığı gün

başlar tınlamaya senkron sesiyle

bir zafer şarkısıdır tenor sax

arkasından inci dilleriyle zencilerin

hayatın yarım küresi güney zilleriyle

bir zafer şarkısıdır tenor sax

hüznün hüznüme bulaştığı gün

başlar atmaya nabzında şiirimin

bir zafer şarkısıdır tenor sax

o yıllardır ölgün akan fısıltısı flütümün

çoğaltır nasılsa zenci elleriyle sevinci

bir zafer şarkısıdır tenor sax

özgürlüğün özgürlüğümü çoğalttığı gün

bütün nehirleri birleşir dünyanın

bir zafer şarkısıdır tenor sax.', 'terimin terine bulaştığı gün başlar tınlamaya senkron sesiyle bir zafer şarkısıdır tenor sax arkasından inci dilleriyle zencilerin hayatın y...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-cazdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Timur Selçuk', 'timur-selcuk-halim-yazici-nqaer', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'adını bilmediğim bir şehrin son durağından

şu sigara kağıdına yazıyorum şarkılarınla çoğalan

hatıralar uçup giderdi avuçlarımdan

dışarda olağan ayyaş bir sabahı yaşayan istanbul

cebimde eskimeyen bir eluard nefesi

ve terkedilmeye hazırlanan bir sevgi

sanki şarkıların yangınıdır şimdi

birden gülümseyen dudağındaki gül.', 'adını bilmediğim bir şehrin son durağından şu sigara kağıdına yazıyorum şarkılarınla çoğalan hatıralar uçup giderdi avuçlarımdan dışarda ola...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/timur-selcuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Joan Baez', 'joan-baez-halim-yazici-ihzsv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'belki bir hüznü yeniden yaşama hükmü

değilse de hayatın yarım kalan hecesi

biliyorum ki ayrılık getirir ayrılıklar

ve belki de her ayrılık bir kavuşma sevinci.', 'belki bir hüznü yeniden yaşama hükmü değilse de hayatın yarım kalan hecesi biliyorum ki ayrılık getirir ayrılıklar ve belki de her ayrılık b...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/joan-baez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bob Dylan', 'bob-dylan-halim-yazici-4071f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'geçerken yavaşça savaşın treni

aşkla yorumla beni

mızıkayla büyür ve kanla esmerleşirdi

çünkü dünyanın teni.', 'geçerken yavaşça savaşın treni aşkla yorumla beni mızıkayla büyür ve kanla esmerleşirdi çünkü dünyanın teni....', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bob-dylan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ella Fitzgerald', 'ella-fitzgerald-halim-yazici-ccdp4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'siyah dudaklı bir çift siyah giz

şarkı söylüyordu ince ayrıntısına

kalın damarlı parmaklarıyla hayatın

türküler mırıldanıyordu mızıkasıyla ömrün

marşlar geziniyordu kirpiklerinde

ardıç ağacı gülüşü örneğin

yakaladığı bağımsızlığıydı ritmin

yeniden yaratılıyordu çıplak ayaklı tanrılarla

alçakgönüllü bir dîde gizemindeydi sesin

çoğaldığı gibi vurulup düşen

afrika''da bir siyahi selin.', 'siyah dudaklı bir çift siyah giz şarkı söylüyordu ince ayrıntısına kalın damarlı parmaklarıyla hayatın türküler mırıldanıyordu mızıkasıyla ö...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ella-fitzgerald-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ravi Shankar, Sitar / Alla Rakha, Tabla', 'ravi-shankar-sitar-alla-rakha-tabla-halim-yazici-05f6d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'pigmeler uçuşuyordu afrika''da

adımları hintli sevgilim

uzuyordu bir ülkenin esirliği

ingilizceydi gramajı ekmeğin

bir insandan daha uzun olur mu

ömrü ve omzu bir silahın

atıyor nabzı sevgimle

harp yaşıyor sanki kemanlar.', 'pigmeler uçuşuyordu afrika''da adımları hintli sevgilim uzuyordu bir ülkenin esirliği ingilizceydi gramajı ekmeğin bir insandan daha uzun olu...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ravi-shankar-sitar-alla-rakha-tabla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çimen Seymen', 'cimen-seymen-halim-yazici-ksv5l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ağlarını topluyorduk âmâ balıkçıların

güllerle kalkar konardı yakamozlar yakamıza

dünya çok gençti

birden zaman şok gibi geçti

artık gözleriyle konuşuyor

ama balıkçılar.', 'ağlarını topluyorduk âmâ balıkçıların güllerle kalkar konardı yakamozlar yakamıza dünya çok gençti birden zaman şok gibi geçti artık gözleri...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cimen-seymen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Türküsü', 'yagmur-turkusu-halim-yazici-db9lx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yağmur türküsü

yağmur altında

sırılsıklam söylenir.', 'yağmur türküsü yağmur altında sırılsıklam söylenir....', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yagmur-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar', 'neye-yarar-rafet-maden-0jmd1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmeye hasret değilse gözlerin, 

Peşinden koşsam neye yarar.

Aşkı anlatmıyorsa sözlerin, 

Dikenle konuşsamda neye yarar.

Eline aldığın güller kuruyorsa, 

Sözlerin kalbimi kırıyorsa, 

Tebessüm mahşere kalıyorsa, 

Hergün konuşsamda neye yarar.

Kötü günde benden pes diyorsan, 

Ben ağlarken sen gülüyorsan, 

Ben koşarken sen yürüyorsan, 

Elimi uzatsam neye yarar.

Dertleri yüklenmeden sevda olmaz, 

Herşeyde hemen sevda olmaz, 

Kırık kalbe ümit dolmaz, 

Ümitlerim kırıldıysa neye yarar.

İnatta kaldıysa bizim aşkımız, 

Pişmanlık olduysa her şarkımız, 

Yarım kalacaksa rüyalarımız, 

Yaşamak artık neye yarar.

Daldığım yerler senin vefasızlığın, 

Ecel bile senden daha yakın, 

RAFET için o eski halin, 

Safran çiçeğim solduysa neye yarar.', 'Sevmeye hasret değilse gözlerin,  Peşinden koşsam neye yarar. Aşkı anlatmıyorsa sözlerin,  Dikenle konuşsamda neye yarar. Eline aldığın güll...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/neye-yarar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneannemin Tül Kalbi', 'anneannemin-tul-kalbi-halim-yazici-d3rfd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mavi gözlerinde sardunyalar, düşler

papatyalar, kağnılar, hanımelleri

yanardağ kalbi, şarapnel parçası

savaşlar, incelikler, göçler

bir aralık kapıdan gülümser

anneannemin tül kalbi.', 'mavi gözlerinde sardunyalar, düşler papatyalar, kağnılar, hanımelleri yanardağ kalbi, şarapnel parçası savaşlar, incelikler, göçler bir aral...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anneannemin-tul-kalbi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Caz / ''Can Baba''ya''', 'beyaz-caz-can-baba-ya-halim-yazici-m3o4t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ağustos sıcağında

ardıç ağacının dalında

bi böcek

el sallar, gül sallar, aşk sallar

dudağında bir sarı klârnet

el

  gül

      aşk

ağustos sıcağında

tam kapı aralığında

çiftleşirken ay

komşu kızı leylayla

gece bekçisi kılığında

gül

    ey

       aşk.', 'ağustos sıcağında ardıç ağacının dalında bi böcek el sallar, gül sallar, aşk sallar dudağında bir sarı klârnet el   gül       aşk ağustos sı...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beyaz-caz-can-baba-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul -1', 'i-stanbul-1-sirma-mersin-bztg4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Işıl ışıl İstanbul

Gecesi ayrı, gündüz ayrı

Her semtinde; 

Bambaşka bir mozaiğin izi

Arnavut kaldırımlı, dar sokaklarında

Denizle dans eden martıları ile, 

Kokusunu savurmuş, hayallere

Bi nefeslik sigarada; tiryakilik  yapıp vazgeçilmez

Bir şehir olmuş, İstanbul! ...

11.10.03', 'Işıl ışıl İstanbul Gecesi ayrı, gündüz ayrı Her semtinde;  Bambaşka bir mozaiğin izi Arnavut kaldırımlı, dar sokaklarında Denizle dans eden ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istanbul-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskilere Gidelim', 'eskilere-gidelim-andrei-shopovski-431iw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgiler 

Saf ve temizdiler

Gözlerdeki gülümseme 

Ellerdeki sıcaklık

Eski yıllar, anılar 

Herşey uzaklarda artık

Öyküler

Öyküler vardı üzmeyen

Hep mutlu sonla biten

Yaşlı bir dilden 

Yavaş yavaş dökülen

Eski kelimeler

Eski insanlar

Hepsi çok uzak artık

Şarkılar

Onlarda eski artık

Ne kaldı bugüne? 

Kaybettik hepsini yine

Bizim suçumuz peki? 

Çabuk algıladık herşeyi

Çabuk gördük 

Çabuk sevdik

Değişince zaman

Eskinin insanı olduk

Eskiyi arar olduk

Sevemedik bugünü

Sevemedik yenileri

Herşey uzaklarda artık

Yapabilecegimiz tek şey

Toplayıp tüm eşyaları

Eskilerin yanına gitmek artık...', 'Sevgiler  Saf ve temizdiler Gözlerdeki gülümseme  Ellerdeki sıcaklık Eski yıllar, anılar  Herşey uzaklarda artık Öyküler Öyküler vardı üzmey...', ARRAY['Türk Edebiyatı','Şiir','Andrei Shopovski']::text[], 8.5, '{"poet":"Andrei Shopovski","poet_slug":"andrei-shopovski","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/eskilere-gidelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybettik Çocukluğumuzu', 'kaybettik-cocuklugumuzu-andrei-shopovski-o9osh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deniz kenarı

İyot kokuyor yine

Hava soguk

Kulaklarımı şapkama sokup

Bir bank üzerinde

Dinliyorum sesleri

Küçük bir çocuk

Koşuyor annesinin yanında

Agzından çıkan buhar

Gözlük camlarını buğulandırıyor

Hayat işte, herkes küçüktü bi zamanlar

Kimimiz böyle mutlu

Kimimiz korku dolu...

Çocuktuk işte 

Biliyormuyduk acımıyor zaman

Biliyormuyduk ki ayrılık var

Her acıda 

Her ayrılıkta

Kaybettik çocuklugumuzu

Büyük planlarımız vardı

Olmadılar

İstediğimiz insanları

Tutamadık yanımızda

İstediğimiz işleri

Yapamadık, başaramadık

Bizler

Büyük insan olamadık

Ve kaybettik çocuklugumuzu da

Şimdi görünce bir çocuk

Üzülüyoruz

Ya o da başaramazsa...

Kulaklarımı şapkadan çıkardım

Son sigarayı yakıp

Üşüye üşüye evimin yolunu tuttum

Ayaklarım ıslak

Yanaklarım nemli

Gözlerim

Gözlerim buğulu...', 'Deniz kenarı İyot kokuyor yine Hava soguk Kulaklarımı şapkama sokup Bir bank üzerinde Dinliyorum sesleri Küçük bir çocuk Koşuyor annesinin y...', ARRAY['Türk Edebiyatı','Şiir','Andrei Shopovski']::text[], 8.5, '{"poet":"Andrei Shopovski","poet_slug":"andrei-shopovski","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kaybettik-cocuklugumuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla', 'damla-andrei-shopovski-pmzxk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzünden düşen küçük damla

Sana soruyorum neden ben? 

Yoksa damladıgın insanın

Kupkuru ve mutsuz oldugunu

Görebilmişmiydin yukarıdan?', 'Gökyüzünden düşen küçük damla Sana soruyorum neden ben?  Yoksa damladıgın insanın Kupkuru ve mutsuz oldugunu Görebilmişmiydin yukarıdan?...', ARRAY['Türk Edebiyatı','Şiir','Andrei Shopovski']::text[], 8.5, '{"poet":"Andrei Shopovski","poet_slug":"andrei-shopovski","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/damla-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda2', 'sevda2-sinan-guven-y0ddv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alamıyorum kendimi senden, 

Duramıyorum tutmadan, o incecik ellerini.

Yüreğim  coşkun bir ırmak gibi akıyor, 

Dinlemiyor aklımın dediklerini.

Yapamam görmeden seni, 

Sana dokunmadan duramam.

Şaşırdım kaldım nasıl atmalıyım adım, 

Bundan sonra ben asla eski insan olamam.

Aşk bu mudur, değilse bu nedir? 

Nedir bu gelen benim başıma.

Seninle olmadan ölürsem eğer, 

……….’i sevdi yazın mezar taşıma.', 'Alamıyorum kendimi senden,  Duramıyorum tutmadan, o incecik ellerini. Yüreğim  coşkun bir ırmak gibi akıyor,  Dinlemiyor aklımın dediklerini...', ARRAY['Türk Edebiyatı','Şiir','Sinan Güven']::text[], 8.5, '{"poet":"Sinan Güven","poet_slug":"sinan-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevda2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sinan-guven-5cok4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birkaç gün aramadım diye seni, 

Aşkımın ateşi söndü zannettin, 

Koyunca elini göğsüme, 

Kor gibi yanan yüreğimi farkettin.

Haykırdım aşkımı yokluğunda, 

Bulutlara, kuşlara, çiçeklere, 

Seni sevmekle yalnız bedenim değil, 

Ruhum da katlanır tüm eziyetlere.

Aşksa bu, aşığım ben, sana aşığım.

Delilikse bu, deliyim ben, sana deliyim.

Sakın alay etme, incitme beni

Seninki kadar hassastır  benim de yüreğim.', 'Birkaç gün aramadım diye seni,  Aşkımın ateşi söndü zannettin,  Koyunca elini göğsüme,  Kor gibi yanan yüreğimi farkettin. Haykırdım aşkımı ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Güven']::text[], 8.5, '{"poet":"Sinan Güven","poet_slug":"sinan-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-295-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değilmiydi? ..', 'degilmiydi-i-brahim-ozcan-18oqa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Sevgili dostum Alman Pilot Yüzbaşı Bernd KUGLER''in anısına) 

Aldanma böyle sessiz

ve masumluklarına...

Değilmiydi bu yıldızlar

Son yolculugunda 

Ardından kayıtsız kalan? ..

Bu karanlık 

Bu gece

Bu gökyüzü; 

Değilmiydi ölüm yolunda çaresiz bırakan? ..

Bu bulutlar 

Bu soysuzlar

Gece uçuşunu ecel kaçışına çeviren

Sierra dağlarında...

Değilmiydi bu Sirüsler

Bu Kümülüsler

Bak şimdi de benim başımdalar

Farketmez ki bunlara

Bandırmalar, Almanyalar, Kaliforniyalar..

Yine pusudalar.

Bu karanlık, bu gece, bu yıldızlar, bu gökyüzü; 

Hepsi birer cana susamış canavar...

Tanıştık seninle kirli bir savaş gününde

Kardeş olmuştuk birbirimize

Farklı millet, farklı kuvvet olsak bile

Yaşadığım her günümde 

Saydıgım bu kahpelere

Ağzım dolusu sövüp-sayacağım

Bernd dostum, senin yerine...

21 Ekim 98 

Bandırma Uçuş Kulesi', '(Sevgili dostum Alman Pilot Yüzbaşı Bernd KUGLER''in anısına)  Aldanma böyle sessiz ve masumluklarına... Değilmiydi bu yıldızlar Son yolculug...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/degilmiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumu Benden Alıp Gülümseyen Esere', 'ruhumu-benden-alip-gulumseyen-esere-emin-baydil-aqw0s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşmüşüm ben, bir yaprak sarısıyla yerlere

Deşmişim bin mezarlık sonbaharı zamansız

Benliğimin kaybolan bir ömre bedel/cansız

Zehrini içmiş gibi şu yaslı ince dere.

Esiyor bir yabancı lisânıyla saçlarım

Bundan böyle sulara mehtâb görünür yarım

Eskiden bir dünyayı kucaklayan kollarım

Şimdi kapanır oldu, gölgelenen yerlere.

Kaldırımlar alaylı, gece sokaklar tenha

Tekme atarım, cansız, soluyan her sabaha.

İntikamla bakarım taşıdığım bir daha

Ruhumu benden alıp gülümseyen esere.

Toz bulanık bir yolda adım adım düşüşüm, 

Sonbahara can atar acıyla her gülüşüm.

Yeni bir çiçek açar, akşama kadar başım

Sevdâsına kapılır uyanamaz ne çare.

Nereye bu yolculuk, ey gârip nasıl şimdi? 

Yakar beni ızdırap, ayrılık asıl şimdi.

Bu can, serde cânan geçerken fâsıl şimdi

Bakarım iplik olmuş mecâlsiz geçenlere.', 'Düşmüşüm ben, bir yaprak sarısıyla yerlere Deşmişim bin mezarlık sonbaharı zamansız Benliğimin kaybolan bir ömre bedel/cansız Zehrini içmiş ...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ruhumu-benden-alip-gulumseyen-esere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Bekleyiş', 'zor-bekleyis-selim-sar-wu2oe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel demeden önce, duydum sesini gökyüzünün

Sönük ufuklara yansıdı bakışlarım zamanla

Dur; rüzgar sürümeden, yağmur eritmeden bekle

Son anlarımda gözlerim senlen, sana kapansın 

Saril bana gitme öyle uzaklara pınar''ım

Adın’a dem tuttu gökyüzü bak, 

Topluyor bütün enerjisini zamanin

Boşalacak bir bir aramiza, sağnak sağnak.

Ağlama ne olur, bari sen ağlama

Ya Rab! Ne gün ki böyle her yer islak, 

Akittiğin yaşlarin damarlarima ulaşsa

Dudaklarim içse onu; dile ab-ı hayat aksa, 

Ölüm ırak düşse bize, güneş hiç uzaklaşmasa

Binbir gece görse bu gözler yildizlarin altinda

Binbür güne bülbül sesiyle uyansa

Hiç ayrilik yakin olurmuydu bu pınar’a.

Ama neyler ki gönül zaman doldu

Sarıl bana bütün özlemlerini boşalt

Unut geçmişte kalanlari, ağlama sakın 

Aşk ile, şevk ile sarıl bana, sevgini boşalt

Son deminde bahar görmek ne boşmuş meğer

Bir ömür beklemekti adım

Zor geçer bu kabir hayatı bana

Hayali bir dostu beklemekse eğer...', 'Gel demeden önce, duydum sesini gökyüzünün Sönük ufuklara yansıdı bakışlarım zamanla Dur; rüzgar sürümeden, yağmur eritmeden bekle Son anlar...', ARRAY['Türk Edebiyatı','Şiir','Selim Sar']::text[], 8.5, '{"poet":"Selim Sar","poet_slug":"selim-sar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zor-bekleyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekâreti Yok Yaşamın', 'bek-reti-yok-yasamin-naime-erlacin-lwcs0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir dolu hüzün indi yine

gidip geliyorum 

başından sonuna yolun

kilitler vuruluyor kalbin kapısına

birbiri üstüne 

kanayarak gittim yüzleşmelere

şiirin aynasına düştü suretim 

derin bir kederde boğulmuşum meğer

ömrün yorgun bekçiliğinden geçtim

damlalar acı kustu yanaklarıma 

tozlu bir kiler odasında yaşamın

örümcek ağına takılmıştı umutlar

alt alta topluyorum artıları

avucumda 

kocaman bir sıfır var

yalnızca rüyaydı yaşamak

fırtınalı bir yolculukta

kalabalıklarda azalıp durmaksızın

kendimi kendime vererek yalnızca 

yılanın zehri tek

akrebin de öyle ey şair 

sofraya bir yemek daha 

konulmamıştı zehirden başka

bekâreti yoktu yaşamın...

(12 Ekim 2003)', 'bir dolu hüzün indi yine gidip geliyorum  başından sonuna yolun kilitler vuruluyor kalbin kapısına birbiri üstüne  kanayarak gittim yüzleşme...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bekareti-yok-yasamin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tısss Tıs', 'tisss-tis-emin-baydil-z1u6d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitti lisânımız elden

Çaldılar ismimizi...

Allah bilir, artık bizi

Bir güzel ölüm pâklar...

Güllük gülistanlık zâr! ..

Mavi boncuk takınalım biz artık.

Bizi Allah korusun, değmesin nazar.

İncirliğe doluşmuş 

Kocamış kızlar bizim

Yap bir sorti, sert olsun

Kara kaşlı yâr bizim.

İster konuş-konuşma, yap sorti! 

''I love you, I love you'' hep sorti...

Yetti artık, yetti be! Şimdi...

-Tısss! ...

Boş ver, 

Ye pilici, iç burdan

Ortada kuyu var, geç burdan.

Bire üç mü, üçe bir mi, 

Çözdüğünüz cebir mi? 

Vur be âbey katla gitsin

Musul-Kerkük atla gitsin.

...........................

Öyle ya, 

Tavla bizim, zar bizim

İncirliğimiz var bizim...

-Tısss tıs! 

Boş veer, 

Ye pilici, iç burdan

Ortada kuyu var, geç burdan.

Şu İ-me-fe

Ne efe! 

Koydular bizi tefe, 

Bir güzel çaldılar âbey...

-Tıs, 

Yooo, hayır! 

...........................

Neden neden, tıs tısçı âbey neden

Bir türlü dağılmıyor, başımızdan bulutlar? 

Ekilen biçilmez mi? Elbette bulur eden, 

Bizi köprü altında aç-susuz unuttular...

-Tısss tıs, tıs! 

Boş veeer, 

Ye pilici, iç burdan 

Ortada kuyu var, geç burdan.

Yaaa, iş böyle, tamam mı? ..', 'Gitti lisânımız elden Çaldılar ismimizi... Allah bilir, artık bizi Bir güzel ölüm pâklar... Güllük gülistanlık zâr! .. Mavi boncuk takınalım...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/tisss-tis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paslı Gönüller', 'pasli-gonuller-emin-baydil-a77jl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün gelir de rüzgâr, aşk ile yırtar belki

Gönüllere taht kurmuş şu kandan mâtemi.

Dönerse, bir gün geceler güne, biter belki

Biter, milletin paslı gönüllere sitemi...', 'Bir gün gelir de rüzgâr, aşk ile yırtar belki Gönüllere taht kurmuş şu kandan mâtemi. Dönerse, bir gün geceler güne, biter belki Biter, mill...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pasli-gonuller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Bir Çagı Yürüdüm Iki Adımda', 'koca-bir-cagi-yurudum-iki-adimda-sedef-unal-1zq0d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocukluğum bir ilkbahar mevsimi gibi 

Nede çabuk gelip geçti 

Yılları yürüdüm iki adımda.... 

Daha hevesimi alamadan oyunlardan 

Oysa yetişkin olmaya pek hevesliydim 

Nerden bilirdim bedelinin bu kadar ağır olacağını 

Bilseydim terk eder miydim  hiç çocukluğumu? 

O kadar acele eder miydim hiç? 

Sırtıma vurup çocukluk heyecanlarımı 

Yollarıma anıların acı izlerinden duvarlar ördüm 

Tepeden tırnağa bezeliyken umutlarla mavi mavi 

Günesin ısısına yağan lapa lapa karlara döndüm 

Ben zamana yenik, yıllar zamana galip 

Zaman nereden bilecek ki? 

Yüreğimin en kuytu köselerine 

Köse bucak sakladığım çocukluk hallerimi 

Koca bir çağı yürüdüm iki adımda...

Doyamadan masum çocukluk yıllarıma

6-10-2003', 'Çocukluğum bir ilkbahar mevsimi gibi  Nede çabuk gelip geçti  Yılları yürüdüm iki adımda....  Daha hevesimi alamadan oyunlardan  Oysa yetişk...', ARRAY['Türk Edebiyatı','Şiir','Sedef Ünal']::text[], 8.5, '{"poet":"Sedef Ünal","poet_slug":"sedef-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/koca-bir-cagi-yurudum-iki-adimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah! Neler Yazacaktım..', 'ah-neler-yazacaktim-i-brahim-ozcan-qk703', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ah! neler yazacaktım sana neler

ne şarkılar ne şiirler...

olmasaydı gitar gıygıyıyla sarmaşık

ruhunu sanala gömmüş

o ecnebi dinletiler..

olmasaydı mevcud-u mekan

kiralık meshaneler dolusu 

kokuşmuş meyhaneler

08.10.2003

Adana', 'ah! neler yazacaktım sana neler ne şarkılar ne şiirler... olmasaydı gitar gıygıyıyla sarmaşık ruhunu sanala gömmüş o ecnebi dinletiler.. olm...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ah-neler-yazacaktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine...', 'yine-i-brahim-ozcan-4u13p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine Güneş

Zülfünü tarıyor

Gül kurusu ufkunda 

Çukurova''nın

Yine Adam

Hüznünü ağlıyor

Turunç sarısı akşamında

Adana''nın', 'Yine Güneş Zülfünü tarıyor Gül kurusu ufkunda  Çukurova''nın Yine Adam Hüznünü ağlıyor Turunç sarısı akşamında Adana''nın...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yine-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevgili İstiyorum', 'bir-sevgili-i-stiyorum-rafet-maden-lavxz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzelliği dünyanın olsun, sevgisi yeter, 

Bir sevgili istiyorum Allah''ım.

Yalnızlık ölümden de beter, 

Bir sevgili istiyorum Allah''ım.

Seni unutturmasın, fazla güzel olmasın, 

Farketmez isterse güneş doğmasın, 

Yeterki yanımdan hiç ayrılmasın, 

Bir sevgili istiyorum Allah''ım.

Şimdi derken şu anda bile hazırım, 

Göğsüne yaslanır meçhule dalarım, 

Düğünü bu yaz yaptırırım, 

Bir sevgili istiyorum Allah''ım.

RAFET''in hayalleri gerçek olursa, 

KASTAMONU''nun milli gelini olursa, 

İsmi YUNUS EMRE olur oğlum olursa, 

Bir sevgili istiyorum Allah''ım.', 'Güzelliği dünyanın olsun, sevgisi yeter,  Bir sevgili istiyorum Allah''ım. Yalnızlık ölümden de beter,  Bir sevgili istiyorum Allah''ım. Seni ...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sevgili-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tevellüt 15.02.1965 -?', 'tevellut-15-02-1965-i-brahim-ozcan-qys9f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tam tamına sekiz haneli

İşaret-i meçhulle arasından tire''li

Bir zaman trenidir

Ömür denen yaşam tüneli...

Önünde tevellüt

Sonunda fatiha-mevlüt

Arası; 

Doğdun, büyüdün, sevdin, kızdın, yazdın, çizdin...

Hepsi boş... Birer  terelelli...

Rakam yüklü katardır ömür treni

Tevellüt belli, diğeri şüpheli..

Tirenin uzunluğu değiştirmez ki tünelinkini...

11 Ekim 2003

Mersin', 'Tam tamına sekiz haneli İşaret-i meçhulle arasından tire''li Bir zaman trenidir Ömür denen yaşam tüneli... Önünde tevellüt Sonunda fatiha-mev...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tevellut-15-02-1965-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simav Akşamında', 'simav-aksaminda-rafet-maden-p8jvk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak bu akşam bir başka Simav''ın havası, 

Sanki seni bana getirecekmişcesine.

Ilgıt ılgıt kokuyor KARŞIYAKA''sı, 

Sanki seni anlatıyor her esişinde.

Biliyorum sen yoksun yanımda, 

Biliyorum hiçbir zaman gelmeyeceksin.

Ama inanki kokun yanımda.

Elimi uzatsam tutacakmış gibisin, 

İşte ben böyleyim bu akşamda.

Ne yapıyorsun diye sorasım geliyor, 

Uykularım kabus oldu gecemi bölüyor, 

Bedenim seni ararken yorgun düşüyor, 

Herşeyinle yaşıyorum bu akşamda.

Sensizken böyleyim Simav akşamında.

Ahh sevdiğim, içimde ateşin kaldıkça, 

Bu bekleyiş beni ızdıraba saldıkça, 

Gözlerimde bir damla yaş oldukça

Seni arayacağım bu akşamda.

Seni arayacağım Simav akşamında.

                                            

(KÜTAHYA-1997)', 'Bak bu akşam bir başka Simav''ın havası,  Sanki seni bana getirecekmişcesine. Ilgıt ılgıt kokuyor KARŞIYAKA''sı,  Sanki seni anlatıyor her esi...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/simav-aksaminda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hülya', 'hulya-halim-yazici-hlq9t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'koştum

kaslarım alevden donuncaya

damarlarım asitle doluncaya

kadar koştum

sarışın atlar kekiklere duruncaya

doru kalbim güvercinleşinceye

kırmızı narlarla

koştum

sonra baktım yarılan kan pıhtısına

baktım elimde kalan saydam cama

duru tayların yelesine

durdum.', 'koştum kaslarım alevden donuncaya damarlarım asitle doluncaya kadar koştum sarışın atlar kekiklere duruncaya doru kalbim güvercinleşinceye k...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hulya-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolunu Gözlerim+', 'yolunu-gozlerim-bayram-tunca-1qtj6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah şu hicranlı ela gözlerim gözlerim

Gözlemekten yorgun düştü gözlerim

Akkor oldu içimdeki yanan közlerim

Ne edeyim ma kes bulmadı sözlerim

Gece gündüz her an yolunu gözlerim

Ah bak kan çanağına döndü gözlerim

Ezik kalbimi hasret ateşinle közlerim

Ne edeyim, ma kes bulmadı sözlerim

Kraterler oluşturdu akan gözyaşlarım

Bak ağardı saçlarımdan önce sakalım

Çevirsen de kara kışa baharımı/yazımı

Bozmadım bozmayacağım bu vakarımı

Sanki Maraş biberi sürülmüş gözlerime

Aldırmayın siz benim sitemli sözlerime

O Leyla’m, tez söndürür közümü gelse

Fer gelir gözlerime, nur yağar yüzüme

İstemem dünyada ne mevki ne makam

İstemem şu âlemde ne han ne hamam

Olmasın isterim yüreğimde keder/gam

Yanımda Leyla olsa işler olur tastamam

12.10.2003-10:12

Aşk Ateşten Gömlek', 'Ah şu hicranlı ela gözlerim gözlerim Gözlemekten yorgun düştü gözlerim Akkor oldu içimdeki yanan közlerim Ne edeyim ma kes bulmadı sözlerim ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yolunu-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazandınmı', 'kazandinmi-i-brahim-atilmis-148s4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kazandım diyebiliyorsan eğer yaşamında; 

dönüp bir bak kaybettiklerine? 

çünkü! 

kazanılanlar kaybedilenlerin toplamıdır hayatta.', 'kazandım diyebiliyorsan eğer yaşamında;  dönüp bir bak kaybettiklerine?  çünkü!  kazanılanlar kaybedilenlerin toplamıdır hayatta....', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kazandinmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Çamaşır İpinde Sabah', 've-camasir-i-pinde-sabah-cemal-karsavran-35qco', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gökyüzü yarılıyordu orta yerinden

şimşekler çakarken

çığlık çığlığa gece

mavileri yırtarken

ağladı köprü altı çocukları

yıkık terkedilmiş evlerden

aktı şıpır şıpır gözyaşları

olukları kırık çatılardan

mazgallar doldu taştı

işçi mehmet’in tek göz evinde

metrepol uyandı deniz ortasında

yüzüyordu kara

köylünün gözünde bereket

nadasa bırakılmamış toprakta

gülüyordu sarı sıcak nene

kış ortasında yazdı 

gecede telaş çığrış bağrış

bardaktan boşanırcasına

ıslanmış kuru çamaşırlar

ve çamaşır ipinde sabah', 'gökyüzü yarılıyordu orta yerinden şimşekler çakarken çığlık çığlığa gece mavileri yırtarken ağladı köprü altı çocukları yıkık terkedilmiş ev...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ve-camasir-ipinde-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Denize', 'gunes-denize-cemal-karsavran-wdym4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'raks ediyordu 

göçmen kuşun kanadında sonbahar

yeleleri alevden

dudağında buruk tebessüm

gidipte dönememek

esirdi şafağa gün

esaret her yeni doğuş

tarih sayfasında izi kalan

bir takvim yaprağı daha 

düştü gözlere

salınıyordu gerdanında

asma bahçesi 

kara benler

şarap damıtıyordu

yüzünde bahar

meriç''e saçtım umutlarımı

ayçiçeğinin göbeğinde

toprağa düştü sevda

çisi çisi yağmurlarla

bereket saç tellerinde

izin istemez aşk

çalar kapıyı aniden

boğulup kelimeler

mimiklere düşer yalın kılıç

gözler olur nokta

yeniden doğuştur istenç

güneş toplayan gözlerde

kar çiçeğinde açan

beyaz mutluluktur

baharla gülen

erteleme zamanı

mevsim dönüyor

arala perdeyi bak

gölge düşüyor güneşe

güneş denize', 'raks ediyordu  göçmen kuşun kanadında sonbahar yeleleri alevden dudağında buruk tebessüm gidipte dönememek esirdi şafağa gün esaret her yeni...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gunes-denize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ask bu!', 'ask-bu-pedaliza-onder-wz1x6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tatlı bir neşe kaplar içimi 

Bir şarkı dökülür dudaklarımdan 

Kalbimde tatlı bir sarhoşluk 

Ela gözlerine baktığım zaman', 'Tatlı bir neşe kaplar içimi  Bir şarkı dökülür dudaklarımdan  Kalbimde tatlı bir sarhoşluk  Ela gözlerine baktığım zaman...', ARRAY['Türk Edebiyatı','Şiir','Pedaliza Onder']::text[], 8.5, '{"poet":"Pedaliza Onder","poet_slug":"pedaliza-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-bu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk başlarken', 'ask-baslarken-pedaliza-onder-ozara', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah bir söyleyebilsem

Gözlerinin bana neler ettiğini

Seni gördüğüm zaman 

Neden çekindiğimi

Sesini her duyduğumda

İçimdeki heyecanı

Bir anlatabilsem sana

Neden artık gözlerimin

Çiçekleri gördüğünü

Neden yüzümde güller açtığını

Bir anlatabilsem.', 'Ah bir söyleyebilsem Gözlerinin bana neler ettiğini Seni gördüğüm zaman  Neden çekindiğimi Sesini her duyduğumda İçimdeki heyecanı Bir anlat...', ARRAY['Türk Edebiyatı','Şiir','Pedaliza Onder']::text[], 8.5, '{"poet":"Pedaliza Onder","poet_slug":"pedaliza-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-baslarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Platonik!', 'platonik-pedaliza-onder-57rlr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hayallerim vardı hayata dair

çizgi roman okurken lise yıllarında

tek göz odamın penceresinden izlerken hayatı

badanası dökülen duvara yazmıştım ismini

ve her sabah seyrettim

perdesiz pencereye taktığım

gazeteye astığım resmini

umutlarım vardı gelecek günlerden

tozlanmış ceketimi silerken

yırtık ayakkabıma çare düşünürken cami avlusunda

şiirlerim vardı sana dair

boş geçen derlerden kalma

şarkılarım vardı seni anlatan

ama ben avuturken kendimi hayallerinle

bir yanlışlık oldu, farketmedin', 'hayallerim vardı hayata dair çizgi roman okurken lise yıllarında tek göz odamın penceresinden izlerken hayatı badanası dökülen duvara yazmış...', ARRAY['Türk Edebiyatı','Şiir','Pedaliza Onder']::text[], 8.5, '{"poet":"Pedaliza Onder","poet_slug":"pedaliza-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/platonik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Olma Demişti Anası', 'sair-olma-demisti-anasi-zeki-ergin-5hrdm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dün gece 

eski bir dost aradı

uzun zaman sonra

telefonda sesi 

eskisi kadar gür değildi

farkındaydım

anası memur ol demişti

o hala para kazanamıyordu

ne şiir ne de resimden

onurluydu ama

hiç taviz vermemişti

özgürlüğünden

_kadıköy 12eki03

_numune kas03 sayı:4

_sevgiliye isyan yt:haz04', 'dün gece  eski bir dost aradı uzun zaman sonra telefonda sesi  eskisi kadar gür değildi farkındaydım anası memur ol demişti o hala para kaza...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sair-olma-demisti-anasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gözlüm', 'yagmur-gozlum-hulya-arisan-gfo3r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecelerimin MAVİ dostu,

gündüzlerimin esin kaynağı.

Yağmur gözlüm,

 ömrümün gerçeği...

Bir yudum aşk için geldim, 

kristal kayalıklara.

Elimde bir demet çiçek, 

sana sunmaya...

İstanbul,    Ekim 2003', 'Gecelerimin MAVİ dostu, gündüzlerimin esin kaynağı. Yağmur gözlüm,  ömrümün gerçeği... Bir yudum aşk için geldim,  kristal kayalıklara. Elim...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yagmur-gozlum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntizar ve', 'i-ntizar-ve-emin-baydil-sk45j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu rüzgâr, hangi yönden, nasıl eserse essin

En zalim rüzgârlara duvar bağrımız bizim.

Aşinâdır çileye, ızdıraba gönlümüz

İçten içe tutuşur, dinmez ağrımız bizim.

Ellerinde mendille gelsin o ateşe râm

Alnımızı secdeye koyduğumuz her akşam.

Damarlarımdan alsın kanımı gram gram

Düşmana değil elbet, dosta kahrımız bizim.

İstemem artık burda, ne eğlence ne düğün

İstemem, şu karanlık geceye doğmasın gün

Bahardı vuslâtımız, gönüllerde kış bugün

Çiçeklerin sultanı, güle çağrımız bizim.

Meyhaneler dolsun be! Boşansın sabah-akşam

Çarşı-pazar bizimdir, Arabınsa Halep, Şam.

Yâd ellerin doğrusu, güzeli bize haram

Dünyalara bin defa, bedel eğrimiz bizim.

Dâvetimdir kahırla söylediğim her mısra

Çünkü, gömdüler geçen beni yirminci asra.

İhtişamın uyanır, çağların ardısıra

Cümle âlem biliyor, duymuş sağrımız bizim.', 'Bu rüzgâr, hangi yönden, nasıl eserse essin En zalim rüzgârlara duvar bağrımız bizim. Aşinâdır çileye, ızdıraba gönlümüz İçten içe tutuşur, ...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/intizar-ve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudakların Dokundu Dünya ya', 'dudaklarin-dokundu-dunya-ya-yasar-yildiz-ejgqj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle bir dokundu ki

dudakların Dünya ya...

Sonyazda olduğunu unuttular

sararıp, kurumaya yüztutmuş yapraklar.

Yeniden yeşillenmeye başladılar,

 dallarına tutunup kaldılar.

 Bir sıcaklık yayıldı ki geceye...

Güneyin çağrısını dinlemediler bile, 

göç etmeye hazırlanan kuşlar.

ilkyaz düşleri görmek için 

yeniden uykuya daldılar.

Rüzgarlar o an esmeye korktular.

Gökyüzünü örten kapkara bulutlar, 

bu geceye yakışmadıklarını anladılar.

Utanç içinde 

usul usul dağıldılar.

Lacivertler içinden yıldızlar, 

birer birer inip gökten, 

saçlarına yapıştılar.

İkiye bölündü Dolunay, 

gelip gözbebeklerine oturdular.

Dudakların Dünya ya; 

İşte böyle dokundular.', 'Öyle bir dokundu ki dudakların Dünya ya... Sonyazda olduğunu unuttular sararıp, kurumaya yüztutmuş yapraklar. Yeniden yeşillenmeye başladıla...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yıldız']::text[], 8.5, '{"poet":"Yaşar Yıldız","poet_slug":"yasar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dudaklarin-dokundu-dunya-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Meğerse', 'ask-megerse-halim-yazici-skgn7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yürüyorum

kalbimde sarhoş balıklar

bi telâş bi heyecan bende

dışarda aşk meğerse.', 'yürüyorum kalbimde sarhoş balıklar bi telâş bi heyecan bende dışarda aşk meğerse....', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-megerse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Yürekli Küçük Yağmur', 'i-yi-yurekli-kucuk-yagmur-halim-yazici-n6bpy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'iyi yürekli küçük yağmur

bahar geldi biliyorsun

mavi kaşlı bir çocuğun hülyasında

akan ırmakta düştüm

koşarken yalınayak yalnızlıklara

aşk hüznüne denk düştüm.', 'iyi yürekli küçük yağmur bahar geldi biliyorsun mavi kaşlı bir çocuğun hülyasında akan ırmakta düştüm koşarken yalınayak yalnızlıklara aşk h...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/iyi-yurekli-kucuk-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havada Caz Kokusu Var', 'havada-caz-kokusu-var-halim-yazici-nclb9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yağmur yağıyor

seller akıyor

-havada caz kokusu var-

kısa saçlı aşklar

camdan bakıyor.', 'yağmur yağıyor seller akıyor -havada caz kokusu var- kısa saçlı aşklar camdan bakıyor....', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/havada-caz-kokusu-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emzirir Mi Seni Aşk', 'emzirir-mi-seni-ask-halim-yazici-6agvv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kadın; - emzirir mi seni aşk? 

adam; - ufuk çizgisine bak.

adam; - bildiğin bir dağ var mı? 

kadın; - öpüşsün mü kirpiklerimiz o zaman

                inince vapurdan?', 'kadın; - emzirir mi seni aşk?  adam; - ufuk çizgisine bak. adam; - bildiğin bir dağ var mı?  kadın; - öpüşsün mü kirpiklerimiz o zaman      ...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/emzirir-mi-seni-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Varmış Hep Aşkmış', 'bir-varmis-hep-askmis-halim-yazici-62tbz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'evvel zaman içinde

kalbur saman içinde

bir varmış bir aşkmış

tüketirken kendini insan

kuş dönermiş teleğinden

deve tellâl iken

pire berber iken

bir varmış hep aşkmış.', 'evvel zaman içinde kalbur saman içinde bir varmış bir aşkmış tüketirken kendini insan kuş dönermiş teleğinden deve tellâl iken pire berber i...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-varmis-hep-askmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Diyeceksin', 'merhaba-diyeceksin-hamit-karadag-5uk6f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Merhaba diyeceksin

Her gördüğüne, 

Gülerek yürüyeceksin yolları.

Bir erik dalı görceksin

Meyvaya durmuş, taze

Dayanamayacak  koparacaksın

Çok değil ama, 

Yalnızca bir tane.

Tadını getireceksin

Ekşiliğini hissedecek; 

Bir erikte bin erik tadı alacaksın.

Bir çiçek göreceksin, güzel

Koklayacaksın.

Bazen daha güzel biri için koparacaksın.

Yağmur yağacak ıslanacaksın

Yürüyeceksin aldırmaksızın ıslaklığına...

Ay ışığı seni çıldırtacak

Yanında biri olsun isteyeceksin

Bir kızı öpeceksin ağız dolusu

Teni tenine değdiğinde 

Ürperecek titreyeceksin...

Bursa-02.05.2001', 'Merhaba diyeceksin Her gördüğüne,  Gülerek yürüyeceksin yolları. Bir erik dalı görceksin Meyvaya durmuş, taze Dayanamayacak  koparacaksın Ço...', ARRAY['Türk Edebiyatı','Şiir','Hamit Karadağ']::text[], 8.5, '{"poet":"Hamit Karadağ","poet_slug":"hamit-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/merhaba-diyeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heykel', 'heykel-halim-yazici-fq97e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'c.koççoban''a

1.yüzün yıldızdağı''na

   kirpiklerin mermer

   tozlu akşamlara

   mavi çocukların

   koştuğu yalnızlıklara

   dönük olsun

   kalbin aşka

   hüznün beyaz gecelere

   turuncu ve siyah heykellere

   küçük dudaklı kadınlar

   akçakgönüllü aşklara

   dönük olsun

   aşkolsun.

2.ey çocuk

   küçük beyaz ellerin

   kelebek ve rüzgârların sesini

   sesinde çoğaltır ve getirirdin

   ey kil

   ey demir, ey toprak

   yelkenlerin şişirdiği hayat

   gece ve aydın

   sana kırk defa söyledim

   bu yüzden sana benziyor

   ince boyun atkısı heykellerin.', 'c.koççoban''a 1.yüzün yıldızdağı''na    kirpiklerin mermer    tozlu akşamlara    mavi çocukların    koştuğu yalnızlıklara    dönük olsun    ka...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/heykel-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alelade', 'alelade-i-brahim-atilmis-5fnpv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen 

karsimda dururken 

.............alelade oylesine

ben 

coktan ulasmis oluyorum 

.............doruklarına mutlulugun.

bakinca gozlerine, 

hele daha yakından bakinca icine

göremediklerimi görüyorum 

..............kapali kapilarin ardindaki.

sonra 

tutunca ellerini, 

birde islanmissa azicik 

............................terden

gokyuzunun rengi degisiyor 

...................kizila yakin mavi.

ve

sen 

karsimda dururken 

..................alelade oylesine

ben 

coktan girmis oluyorum 

..............pembenin esrarina

nefesin karistiginda nefesime 

...............................anlatamam

olum neki, 

.........azrail kim ki? 

          guluyorum dar agacina

sen 

karşımda dururken alelade 

................................öylesine

ben 

coktan gitmis oluyorum 

...........................kendimden...', 'sen  karsimda dururken  .............alelade oylesine ben  coktan ulasmis oluyorum  .............doruklarına mutlulugun. bakinca gozlerine, ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/alelade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali haydar', 'ali-haydar-i-brahim-atilmis-lcn64', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'haydar haydar ali haydar

seni arzular oldu cümle canlar

dökülmesin artık bu kanlar

haydar haydar ali haydar

gün oldu böldüler kavmimizi

gün oldu kestiler dilimizi

gün oldu verdik yoluna serimizi

haydar haydar ali haydar

biz seçmeden seçildiler başa

baharı görmeden düşürdüler kışa

aldılar özümüzü yüreğimiz döndü taşa

haydar haydar ali haydar

atılmışım kime dert yanayım

seni özüm bildim haykırmaktayım

için için ben yanmaktayım

haydar haydar ali haydar

durmaz bu dünya elbet döner

gün olur sabret devran döner

kurt ile kuzu yan yana döner

haydar haydar ali haydar', 'haydar haydar ali haydar seni arzular oldu cümle canlar dökülmesin artık bu kanlar haydar haydar ali haydar gün oldu böldüler kavmimizi gün ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ali-haydar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön artık', 'don-artik-murat-alemdar-fnbos', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bahar akşamıydı gidişin

Belki de kalbime  en ağır yükü yükledin.

Ne kadar yalvarsam boşaydı, 

Dönerim demiştin belki bir gün

O günü her gün bekledim.

Kim bilir  kaçıncı   sigara dudaklarımda

Seni düşünüyorum artık umutsuzca, 

Gözlerimde uyku yerine sen vardın geceleri.

Uyuyamıyorum  artık.

Uyu diyor rüzgarlar, artık uyu

Yapamıyorum be güzelim olmuyor.

Sevdalı bulutlarla sürüyor artık dostluğum.

Hala anımsıyorum o günleri, 

Ve  o günlere dair eminim ki! 

Eskiden daha da inançlı ve azimli olduğumuza, 

Dön artık selvi boylum, 

Bizi bıraktığı yerde bekliyor aşkımız.

Duymadın mı bak dinle, 

Rüzgar sana fısıldıyor; 

Seni  seviyorum...', 'Bir bahar akşamıydı gidişin Belki de kalbime  en ağır yükü yükledin. Ne kadar yalvarsam boşaydı,  Dönerim demiştin belki bir gün O günü her ...', ARRAY['Türk Edebiyatı','Şiir','Murat Alemdar']::text[], 8.5, '{"poet":"Murat Alemdar","poet_slug":"murat-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/don-artik-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-murat-alemdar-nkcp3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir umudum vardı yarınlardan 

Belki de  gerçekleşmeyecek  hayallerim di umutlarım, 

Bir bardak suda eriyen tuz gibiydi  sanki; 

Güden güne yok oluyor  ve kayboluyordu düşlerim.

Anılarımın silinmeyen bir parçasıydı benim için o günler, 

Yüreğimi yakıyordu bir kaç  namert söz.

Yüreğimi zincirlere vurdum.

Göz yaşlarımı ise dağlanan yüreğimde kuruttum..', 'Bir umudum vardı yarınlardan  Belki de  gerçekleşmeyecek  hayallerim di umutlarım,  Bir bardak suda eriyen tuz gibiydi  sanki;  Güden güne y...', ARRAY['Türk Edebiyatı','Şiir','Murat Alemdar']::text[], 8.5, '{"poet":"Murat Alemdar","poet_slug":"murat-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Ağlarını Ördü', 'kader-aglarini-ordu-aziz-pinar-xie9u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaçıncı gidişin vefasız söyle

Ben saymadım amma oldu kırk kere

Son bir şansın vardı olmadı yine

Kader ağlarını oldu bir kere.

Ne nazın niyazın, ne çilen biter

Ne huzur verirsin ne özlem diner

Geçmişe dönmekse maksadın eğer

Kader ağlarını ördü bir kere.

Sevenle bu kadar oyun olurmu? 

Çıktığın o kapı açık durur mu? 

Sararan sevgiler dalda kalırmı? 

Kader ağlarını ördü bir kere.

Yaktığımız ateş sen yokken söndü

Bir müddet gönlümde dumanu tüttü

Yeniden yanamaz, külleri bitti

Kader ağlarını ördü bir kere.

Susuz kalan çeşme akmıyor işte

Elek oldu bu aşk dolmuyor işte

Kırılan kollarım sarmıyor işte

Kader ağlarını ördü bir kere.', 'Kaçıncı gidişin vefasız söyle Ben saymadım amma oldu kırk kere Son bir şansın vardı olmadı yine Kader ağlarını oldu bir kere. Ne nazın niyaz...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kader-aglarini-ordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Aşkı', 'bahar-aski-aziz-pinar-1rq4l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş dağlara vurunca

Zirvede karlar eriyor

Aydınlığına bakınca

Ruhuma sevdan akıyor.

Pırıldıyor tüm kayalar

Işık ışığa yağıyor

Yeşile dönüyor çamlar

Bahar saçını öpüyor...', 'Güneş dağlara vurunca Zirvede karlar eriyor Aydınlığına bakınca Ruhuma sevdan akıyor. Pırıldıyor tüm kayalar Işık ışığa yağıyor Yeşile dönüy...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahar-aski-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki Dedim; Kendimim', 'i-yi-ki-dedim-kendimim-bekir-mutlu-gokcesu-k4moa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Masmavi ve  bembeyazdı gökyüzü

Düşüyordum boşluğa yüreğim ağzımda

Oysa şehir ne kadar da küçüktü aşağıda 

Tarifsiz bir duygu; korku ve heyecan

Oysa minik bir kuş olsaydım o anda

Hiç öleceğim gelir miydi aklıma

Avuçlarında olmak istedim

Sıkı, sıkı tutmanı, sarılmanı

Oysa minik bir kuş olsaydım avuçlarında

Aynı böyle çarpacaktı yüreğim

Neyse ki o koca boşluğun ortasında

Fırlayıverdim yataktan

Nasılda geçmiş içim şurada

İyi ki dedim, minik bir kuş değilim

Ne o sonsuz boşlukta

Ne de avuçlarında', 'Masmavi ve  bembeyazdı gökyüzü Düşüyordum boşluğa yüreğim ağzımda Oysa şehir ne kadar da küçüktü aşağıda  Tarifsiz bir duygu; korku ve heyec...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iyi-ki-dedim-kendimim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cünkü sensizim', 'cunku-sensizim-diyarbakirli-mehmet-wv42v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gencligim bir avuc toprak gibi 

Ellerinde sanki 

Acsan avucunu savuracak

Esen su deli rüzgar beni 

Hayallerim depremden kalma yikintilarla dolu

Ümitlerim altinda sikismis

Imkansiz kurtulusu

Eger bu gün ayaktaysam bilki

Sevdanin sayesinde 

O beni avuttu 

Sevmek yasama sevincim benim 

Gülmek ise imkansizim 

Yalnizlik yazilmis olan kaderim 

Sen ise inan bana benim her seyim 

Ama ben bir hicim 

Cünkü simdi sensizim 

Dermansiz 

Caresiz yetim 

Öksüz kimsesizim 

Hicim ben bir hicim 

Cünkü sensizim', 'Gencligim bir avuc toprak gibi  Ellerinde sanki  Acsan avucunu savuracak Esen su deli rüzgar beni  Hayallerim depremden kalma yikintilarla d...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakirli Mehmet']::text[], 8.5, '{"poet":"Diyarbakirli Mehmet","poet_slug":"diyarbakirli-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cunku-sensizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin Yaşı Yoktur', 'siirin-yasi-yoktur-bulent-ozcan-p3a6p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiirin yaşı yoktur

Sevda bir ok(u)  yan-us-tur yüreğinde insanın

Şiirin yaşı yoktur

Hayat bir türküdür dilinde rüzgârın

Şiirin yaşı yoktur

Sözcükler ışığıdır evrende yıldızların

Şiirin yaşı yoktur

Zaman bir gül dalıdır elinde Tanrıların

20 Kasım 2001, Londra, İngiltere

Şafak Dergisi, Mayıs 2003, Sayı: 135, Yunanistan

www.bulentozcan.com', 'Şiirin yaşı yoktur Sevda bir ok(u)  yan-us-tur yüreğinde insanın Şiirin yaşı yoktur Hayat bir türküdür dilinde rüzgârın Şiirin yaşı yoktur S...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/siirin-yasi-yoktur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda yüklü gemim', 'sevda-yuklu-gemim-diyarbakirli-mehmet-x7w1l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu hayat denizinde 

Benim bir gemim vardi 

Ici sevda yüklü 

Kaptani sana asikti 

Dalgalara aldirmaz 

Notasini sasirmaz

Tam istikamet senin alanindi 

O denizin ortasinda 

Kimsesiz tek basina 

Yüregindeki sevdayla

Yanip tutusan bir asikti

Her seyíni o gemiye adamis 

Güzel seyleri geride birakmis 

Senin yolunu secip 

Kendini sana adamisti 

Ama yanildi 

Bunu cok gec anladi 

Cünkü yari yolu asmisti

Bir gece yarisi

Kör karanliginda 

Cikan o büyük firtinada 

Gemi arizalandi

Durdu motoru 

Yelkenlerini indirdi 

Kaptan yaralandi 

Sizlayan yürek agrisina dayanamadi 

Oturdu bir kösesine geminin 

Caresiz kaldi 

Gemide büyük bir delik acildi 

Gemiyi denizin dibine batirdi 

Onun yanan sevda atesini 

Denizin sulari söndürdü

Onuda bogup vahsice öldürdü! ! ! ! !', 'Bu hayat denizinde  Benim bir gemim vardi  Ici sevda yüklü  Kaptani sana asikti  Dalgalara aldirmaz  Notasini sasirmaz Tam istikamet senin a...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakirli Mehmet']::text[], 8.5, '{"poet":"Diyarbakirli Mehmet","poet_slug":"diyarbakirli-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sevda-yuklu-gemim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar 14', 'yar-14-refik-yildiz-oqlcs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçime akıttım yaşı kimseler görmesin diye

Tebessüm astım çehreme insanlar kansın diye

Yine yıktı ayrılık kor kaldı ateşinden

Seller gelse söndürmez bekler gözyaşı gelsin diye

Madde sanma sen bunu o duygu hamalıdır

Biliriz menbaası gönüldür onun diye

Dostlar bırakıp gitti, güzelliği sendendi

Sevdim onları kalpten, senin remzin var diye

Bu firaklar vesile, ötesinde sen varsın

Yansa gönül acımam, sivaya kandı diye

Hep isyan doluyum, isyanım var zamana

Dünyamı dünyandan ayırıyor diye

Ayrılığın öldürdü, feryadımı duy benim

Başka kime gideyim visal burdadır diye

Ya tut ellerimden asrına götür orada kalayım

Ya ayrılma hiç, bırakma nefsime kurbanın olayım', 'İçime akıttım yaşı kimseler görmesin diye Tebessüm astım çehreme insanlar kansın diye Yine yıktı ayrılık kor kaldı ateşinden Seller gelse sö...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yar-14-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaymaklı Vatandaşlar', 'kaymakli-vatandaslar-caglar-akarsu-2856e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaymaklı Vatandaşlar

..

Severdik, sütü kaynatırken

Yağlı ve beyaz köpüklü, 

Sıvanır, kabın her köşesine, 

Biz ise, hazır ve nazır, 

Yutmak için hep bekledik, 

Birleri, bir başları tutmuşlar, 

Düşünmezler, dönüp geri bakmayı, 

Nice-nice günler geçip de giderken, 

Yollar, uzak diyarlara çıkar, 

Mısır tarlaları çok bereketli miş

Çoluk ve çocuk “ ramsey”  kanatlı, 

Kaymaklı dondurmaları yalarken, 

Ağızlarını bozmak, istemezler.

...

 Ne  kaymakmış böyle bitmeyen, 

Doymayan  kişiler, arsız olursa

Elde uzun bir kepçe sallanır, 

Kazan delik, üstünden koyulur

Altından kaymak   ve bal tutanlar, 

Şapırdamış hırsları dolu dizgin, 

İradesizce kendini bilmeden, 

Bu nice yaşamaktır, kaymaklı.

Aç kalmış  vatandaşlar biçare

Lokmaları mideye götürenler, 

Yedikçe, yemişler bu illerde, 

Ak kaymaklı   vatandaş, ah! ! 

....

12/ ekim/2003

çağlar akarsu', 'Kaymaklı Vatandaşlar .. Severdik, sütü kaynatırken Yağlı ve beyaz köpüklü,  Sıvanır, kabın her köşesine,  Biz ise, hazır ve nazır,  Yutmak i...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kaymakli-vatandaslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönsende ne fayda artik', 'donsende-ne-fayda-artik-diyarbakirli-mehmet-9gyx6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gittigin günün aksami bir rüya gördüm

Inanki bu ömrümde ilkti gördügüm 

Giderken ansizin arkani döndün 

Ve bana bakip güldün

Gülüslerin bir silahin namlusuydu

Bakislarin ise icindeki kör kursun 

Beni tam kalbimden vurdun 

Sustun bende sustum 

Yoluna devam ettin beni unuttun 

Takat kalmadi dizlerimde cöktüm 

Yaramdan sen akiyordun 

Icim sen doluydun 

Durmak bilmiyordun 

Dinmiyordun 

Aktin aktin kayboldun 

Bende bittin o an artik kalmadin 

Sana sensiz yasayamam dedim 

Sen bana inanmadin

Son nefesimi aliyordum 

Sen buna bile aldirmadin 

Sensiz bir gün bile dayanamadim öldüm

Son yolculuguma hazirladilar beni 

Ellerdeydi tabutum

Siyahlar giyinmislerdi sevenlerim agliyordu

Ama sen gülüyordun 

Gözünden akan bir damla yas kadar degerim yoktu 

Helal olsun dedim gülüm

Sana helal olsun 

Sana verdigim emekler 

Aka cevirdigim o kömür karasi saclar 

KomsunuN bahcesinden yürüttügüm güller

Helal olsun gülüm helal olsun 

BIR TELAS ICINDE UYANDIM 

Bir sey ariyormus gibi etrafima bakindim 

Her zamanki seyleri gördüm 

Rüya oldugunu anladim 

Masamdaki sigara paketimi alip

Bir sigara cikardim 

Yaktim 

Yatagima uzandim 

Düsündüm 

Basladim agladim 

Buna dayanamadim 

Adini mirildadim bir iki kere 

Sonrada sesimin ciktigi yere kadar bagirdim 

Cagirdim gelmedin

Beni duymadin 

Caresiz kaldim agladim 

Telefon numarani cevirdim

ama yapamadim yarida biraktim 

Aramadim arayamadim

Bekledim seni o aksam sabaha kadar 

Uyku girmedi gözlerime uyuyamadim 

Sigara üstüne sigara ictim 

Bir bilsen kac kere numarani cevirdim 

Ama her seferinde yarida biraktim 

Ne bileyim iste gururmuydu ne benimkisi

Bir türlü yapamadim 

Sabah oldu sen gelmedin 

Bende kararimi verdim

Seni unutacagim 

Zor olsada bu belki

Bunu basaracagim 

Dönsende ne fayda artik canim 

Anladim mecburum buna 

ve bunu basaracagim......! ! ! ! ! ! ! !', 'Gittigin günün aksami bir rüya gördüm Inanki bu ömrümde ilkti gördügüm  Giderken ansizin arkani döndün  Ve bana bakip güldün Gülüslerin bir ...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakirli Mehmet']::text[], 8.5, '{"poet":"Diyarbakirli Mehmet","poet_slug":"diyarbakirli-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/donsende-ne-fayda-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteme Seni Benden', 'i-steme-seni-benden-derin-oger-efoxh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstersen seni benden

Şuramda bir ağrı duyarım

Veremem bendeki seni sana

Bak duruşun nasılda yakışmış içime dışıma

Seni seviyorum ufuklar ardınca yollar boyunca

Varlığına yokluğuna aşığım sana

Yüklenmişim sevdanı  tonlarca

Sığdırmışım kalbimin bir göz odasına

Anlatamam bu aşkı başka dillerde sana

Yemin ederim üstüne mukaddes bildiğim ne varsa

Seni seveceğim günlerin akında karasında yıllar boyunca

Bilki her yeni günle yeniden aşığım sana.............', 'İstersen seni benden Şuramda bir ağrı duyarım Veremem bendeki seni sana Bak duruşun nasılda yakışmış içime dışıma Seni seviyorum ufuklar ard...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isteme-seni-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karmaşık denklem midir hayat?', 'karmasik-denklem-midir-hayat-arzu-dincer-zlnde', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karmaşık denklem midir hayat? 

Aklın erdiği mertebe, 

Karmaşık bir denklem gibi, 

Bilinmeyenleri bulmak 

Çözümü müdür yaşamın?', 'Karmaşık denklem midir hayat?  Aklın erdiği mertebe,  Karmaşık bir denklem gibi,  Bilinmeyenleri bulmak  Çözümü müdür yaşamın?...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/karmasik-denklem-midir-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedim ki', 'dedim-ki-oguzkan-bolukbasi-5qyw9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dediler ki

“Yaşamla uğraşma yaşamaya uğraş”

Dedim ki

Anlamadan yaşamak  sadece varolmaktır

Sadece varolmak, baş, gövde, kollar ve bacaklardır

Aslan, kaplan, yılan, tilki, köpek yaşamaya uğraşır

İnsan biraz yaşamla da savaşır

Mesela parlak ışıkta gözün kamaşır

Bilmek istersin niye kamaşır

Mesela aşk acıdır

Can yakıcıdır

Bilmek istemez misin nedendir

Acıyı çeken ruhundur

Çöküp giden bedendir

Mesela yumurta mı tavuktan

Tavuk mu yumurtadan

Diyelim ki ilgilenmezsin

Sadece yumurtayı yersin

Aslan, kaplan, yılan, tilki, köpek bağrışır o zaman 

“bendensin bendensin, yada bizdensin bizdensin”

Dediler ki 

“Karışma Yaratanın işine O her şeyi bilendir”

Dedim ki

Yaratan niye akıl versin öyleyse

De bizleri denesin

O aklı verendir

Ve düşün diyendir

Hayvan bilmez sebebini çiçeğin

Gökte güneş niye var

Niye döner dünya

Niye her şey döner

Evren niye büyür de

Yer çekimi nedendir

Parmak izin senindir

Özetle dostum 

Yaşamı anlamadan yaşamak benim korkum', 'Dediler ki “Yaşamla uğraşma yaşamaya uğraş” Dedim ki Anlamadan yaşamak  sadece varolmaktır Sadece varolmak, baş, gövde, kollar ve bacaklardı...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dedim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''da Bir Kızın Mavi Gözleri', 'i-stanbul-da-bir-kizin-mavi-gozleri-bekir-gedikoglu-62p4h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul’da  bir kızın mavi gözlerini

Yürek teknemde yoğurdum

Paramparça kalbimi

Baştan başa yeni kurdum

Ahh İstanbul ahh

Az kalsın beni yakacaktın! 

Değirmen taşları gibi öğütüp

Herhangi bir çöplüğe atıp

...ve memleketime bir mektup yazıp

Ağıtlar yaktıracaktın değil mi? 

...sonunda

İstanbul’da bir kızın mavi gözlerini

Yürek teknemde yoğurdum

Paramparça kalbimi

Baştan başa yeni kurdum

Ahh İstanbul ahh

Ben seni zaptetmeyi bildim! 

Yoksa

Beni bir canavar gibi yiyecektin

İstanbul boğazının tüm sularını içtim ki

Sevgilimin gözleri

Gözleri mavileşti

Sonra

Emirgan, yıldız parkına ve hatta boğazın üstüne

Yemyeşil bir halı serdim

Üzerinde sere serpe yatan yarimin yanından

İstanbul’un yedi tepesine selam verdim

İşte bu vadide

Yosmam başını göğsüme yasladı

Gözlerini gözlerime dayadı

Sanki tarifsiz bir saldırının başlangıcıydı bu

Lav gibi arzu dolu bakışlar beni bombalıyordu

Her gelen kor parçası 

Yüreğimde cız ediyordu

O iki mavi denizin derinliklerinden

Bir türlü gözlerimi alamıyordum

Ben büyülenmiş miydim? 

Ey benim Yüce Allahım

Şahlanan bu yüreğimle

Anadolu hisarından Rumeli hisarına atlayabilirdim

Yarimin üzerine bindiği bir Anka kuşuna dönüşüp

Boğazın engin suları üstünde uçabilirdim

Seni sokak sokak, 

Ev ev dolaşabilirdim', 'İstanbul’da  bir kızın mavi gözlerini Yürek teknemde yoğurdum Paramparça kalbimi Baştan başa yeni kurdum Ahh İstanbul ahh Az kalsın beni yak...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/istanbul-da-bir-kizin-mavi-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar Düşüncesi', 'i-ntihar-dusuncesi-hakki-hakan-kaya-p3ij8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ezilmez bir yürekle dağlarken yaşamı, 

Nasıl kapanır ardından insanın tüm kapıları, 

Desteksiz ve yalnız yürürken boşlukta, 

Böyle mi oluyormuş insanın hayata intikamı.

Hangi deli cesaret sarmaladı bedenini de, 

Hangi çıkmaz yolların kaldırımına savruldun, 

Fırtınalarla dans eden köpüklü dalgalarken, 

Nasıl bitti heyecanında böylesine duruldun.

Bir kaçış zannettin yada karanlıktan bir çıkış, 

İlaç gibi geldi sana tüm acını dindirecek, 

Kalk şimdi ayağa sevdiklerine dostlarına sarıl, 

Seni bu sevgi yaşatıp hayata döndürecek.', 'Ezilmez bir yürekle dağlarken yaşamı,  Nasıl kapanır ardından insanın tüm kapıları,  Desteksiz ve yalnız yürürken boşlukta,  Böyle mi oluyor...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/intihar-dusuncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sevdanın Harcı Eksik', 'bu-sevdanin-harci-eksik-murat-demir-2w63k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sevdanın harcı eksi tutmuyor

Bağ bozulmuş, bülbülleri ötmüyor

Ay karanlık, Güneş batmış çıkmıyor

Sen hayattan neyi beklersin gönül

Sen yandıkça kader güldü elllere

Neye yarar saçlar inse bellere

Teleklerin tek tek düşmüş yerlere 

Sen kanattan neyi beklersin gönül

Tren gitmiş son durakta kalmışsın

Hazan vurmuş gazelinle yanmışsın

Kurşun yemiş kaderine saymışsın

Sen Murattan neyi beklersin gönül

			Murat Demir', 'Bu sevdanın harcı eksi tutmuyor Bağ bozulmuş, bülbülleri ötmüyor Ay karanlık, Güneş batmış çıkmıyor Sen hayattan neyi beklersin gönül Sen ya...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-sevdanin-harci-eksik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Adam Olmayacak', 'senden-adam-olmayacak-murat-demir-p1j1t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen başıma bir belasın

Yüreğimde tek yarasın

Yalan ise kanım aksın

Senden adam olmayacak

Gül bilirdim diken çıktın

Hanemi yerinden yıktın

Başka nehirlere aktın

Senden adam olmayacak

Aratmadın buz dağını

Harap ettin gül bağımı

Vurdun döktün yaprağımı

Senden adam olmayacak

Sevgin sevdan yanlış yalan

Sen oldun aşkıma kıyan

Bağrımda beslenen yılan

Senden adam olmayacak

İster sürün ister dilen

Sensin bana el güldüren

Beni yaşarken öldüren

Senden adam olmayacak

Saçlarıma aklar düştü

Bak gençliğim elden uçtu

Beni yaktın puştun puştu

Senden adam olmayacak

Tövbe edip gelsen bile

Önümde diz çöksen bile

Benden sana güle güle

Senden adam olmayacak

		Murat Demir', 'Sen başıma bir belasın Yüreğimde tek yarasın Yalan ise kanım aksın Senden adam olmayacak Gül bilirdim diken çıktın Hanemi yerinden yıktın Ba...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/senden-adam-olmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirleniyoruz..', 'kirleniyoruz-ceylan-yarar-8lvsh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nedir kirleten bizleri

Nedir yok eden? 

Oysa tertemiz doğuyoruz

Dünya mı kirli yoksa insanlar mı...

Anne baba istemezki

Kirlensin evlatları

Büyüdükçe bebekler

Ayak uydurmak için...

Dönen kötülük çarklarının

Arasında yok olmamanın

Savaşını mı veriyorlar acaba? 

Sevgi tohumu içimizde doğuyoruz

Suyunu verdikçe sevdiklerimiz

Yeşerip büyüyoruz

Essede hırçın rüzgarlar

Kırsada dallarımızı

Sevenlerimiz var oldukça

Dokunamaz kötülük çarkları 

Oynansada bazen bizans oyunları

Dönsede entrika dolapları

Bir anlıkta olsa; 

Tanrı yaşatmasın bu duyguları...', 'Nedir kirleten bizleri Nedir yok eden?  Oysa tertemiz doğuyoruz Dünya mı kirli yoksa insanlar mı... Anne baba istemezki Kirlensin evlatları ...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kirleniyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avunursun Şiirlerle', 'avunursun-siirlerle-ceylan-yarar-rd7rk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birşeyler eksik bende

Yarım sanki herşey

Derin nefes alamamak gibi

Yada çığlık atmak isteyipte

Sesinin çıkmaması gibi

Susarsınya kurumuş toprak misali

Kurumuştur boğazın yutamassınki

Koşmak istersin, yüremek hatta

Ayakların tutmazki

Sevmek, okşamak istersin

Yarin nerede ki

Duygulalın şahlanır bazen

Çoşmak istersin

Alırsın kalemi eline

Yürekten dökülen dizelerle

Doldurursun sayfaları

Yinede eksiksindir

Kalbin dolanadek

Avunursun şiirlerle...', 'Birşeyler eksik bende Yarım sanki herşey Derin nefes alamamak gibi Yada çığlık atmak isteyipte Sesinin çıkmaması gibi Susarsınya kurumuş top...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/avunursun-siirlerle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-ceylan-yarar-zhjkf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Usulca yaklaştı pencerenin önüne

Kollarıyla kendi bedenini sardı

Yalnızdı üşüyordu

Gözlerini bir bir evlere çevirdi

Ne hayatlar yaşanıyor diye düşündü

Tv seyrediyordu yaşlı adam

Hanımı örgüsünü almış kimbilir neleri sorguluyordu

Ders çalışan delikanlı

Dans eden gençkıza baktı

Bir masabaşında toplanmış aile vardı

Ve bir şey farketmişti

Aslında hepsi yanlızdı

Birden sokak lanbasının oraya odaklandı gözleri

Yeni park etmiş arabanın

Daha soğumamış motorunda ısınan kediciği

Koşarak gidip aldı kediciği

Karnını doyurdu kuruladı

Adınıda dost koydu

Yanlız değildi artık üşümüyordu 

Yüreğini ısıtan bir dostu vardı..', 'Usulca yaklaştı pencerenin önüne Kollarıyla kendi bedenini sardı Yalnızdı üşüyordu Gözlerini bir bir evlere çevirdi Ne hayatlar yaşanıyor di...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dost-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miras', 'miras-ceylan-yarar-skigl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güvenme yüz güzelliğine

Önce yüreğin güzel olsun

Güvenme zenginliğine

Varsın gönlün zengin olsun

Gençim deyip geçme sakın

Her yaşta beynin genç kalsın

Yaşlıyken titreyen ellerin değil

Hala titreyen kalbin olsun

Yatırımların yanlız maddi değil

Dostluğa sevgiye olsun

Bırakacağın miras

Yanlız ellerde değil

Ebediyen gönüllerde kalsın', 'Güvenme yüz güzelliğine Önce yüreğin güzel olsun Güvenme zenginliğine Varsın gönlün zengin olsun Gençim deyip geçme sakın Her yaşta beynin g...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/miras-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaos', 'kaos-yildiz-yildiz-ejbkm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Attım bir kazana tüm renkleri

Karıştırdım karıştırdım

Siyahı buldum

Tattım gece renginin 

Derin sakinliğini

Yele verdim sonra bütün renkleri

Beyazın hiçliğinde gezdirdim gönlümü

Ruhum dokundu renklere bir bir

Tanıdı kaosun dinginliğini', 'Attım bir kazana tüm renkleri Karıştırdım karıştırdım Siyahı buldum Tattım gece renginin  Derin sakinliğini Yele verdim sonra bütün renkleri...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kaos-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Cadının Saçı Çekiliyor', 'i-cimdeki-cadinin-saci-cekiliyor-mine-ozdemirtas-0m4bn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biri, 

İçimdeki Cadı''nın saçını çekiyor

Kasıtlı.

Korkuyorum ki; 

Uykudaki Cadı... uyanacak.

En azından o birinin; 

Burnunu ısırıp koparacağım.

Bu kesin.

Acıdan iki büklüm, 

Gözlerinden yaş gelecek.

Boşnak damarıma; 

Basıp duruyor ya..............

Vampirliğim kaşınıyor gün boyu.

Sabrım taştı, taşacak.

Ben; 

Bir şey kazanmayacağım ama, 

O  ''Şah Damarı''ndan olacak.

Ve o gün; 

Bir de resim çizeceğim

Sayfalara Anonim.

O resmi çizdiğimde şairliğim; 

Çırılçıplak; 

Satırlara sere serpe uzanacak.

13/10/2003... kartal', 'Biri,  İçimdeki Cadı''nın saçını çekiyor Kasıtlı. Korkuyorum ki;  Uykudaki Cadı... uyanacak. En azından o birinin;  Burnunu ısırıp koparacağı...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/icimdeki-cadinin-saci-cekiliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim', 'giderim-ozgur-sirius-1qpbc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana yazdığım mektubu

Belki yırtar giderim

Böyle azalmaz yara bu

Hergün artar giderim

İnanmasanda sözüme

Aşkı yakar giderim

Kanım dolarda gözüme

Bazen akar giderim

Ağla yüreğim derinden

Kalan varsa gerinden

Kalbin açtığı yerinden

Bir gün çıkar giderim

Asla güvenmem yüreğe

Seni yazan bileğe

Fazla direnmem gerçeğe

Yalan olur giderim', 'Sana yazdığım mektubu Belki yırtar giderim Böyle azalmaz yara bu Hergün artar giderim İnanmasanda sözüme Aşkı yakar giderim Kanım dolarda gö...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/giderim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümün Pınarları', 'koyumun-pinarlari-necmettin-karaman-pb1bf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hereke’den çıktım yola sabah erken

Cıvıl cıvıl kuş sesleri öterken

Kız Pınarı’na doğru  patika, keçi yolu

Yolumun üzerinde

Papatyalar sarmıştı çimenlerin üstünü

Kıyamadan koparıp topladım bir ikisini

Bilirmisiniz Papatya bir başka alem

Dedi bana

Muhakkak bir sevgilin olmalı

Seviyor-sevmiyor diyerek tek tek

Koparacaksın

İnce beyaz yapraklarımı

Yaptım merakla dediğini

Seviyor, sevmiyor diyerek tek tek

Kopardım yaprakları istemiyerek

Ne oldu biliyormusunuz

Seviyor dedi bana işte en son kopardığım yaprak...

On dakika sonra Kız Pınarındayım

Vardım çeşme başına

Hafif hafif ter akmaya başladı

Yüzüme ve kaşıma

Oh negüzel akıyor Pınarım şırıl şırıl

Yıkadım elimi hem yüzümü harıl harıl

Kuruladım mendilime

Eğilip o güzel sudan içtim kana kana

Bundan güzeli mümkün değil olamaz

Şükürler Olsun Yârab Yârab sana...

15 Temmuz 2003

İstanbul', 'Hereke’den çıktım yola sabah erken Cıvıl cıvıl kuş sesleri öterken Kız Pınarı’na doğru  patika, keçi yolu Yolumun üzerinde Papatyalar sarmış...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Karaman']::text[], 8.5, '{"poet":"Necmettin Karaman","poet_slug":"necmettin-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/koyumun-pinarlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Yeli Duy Beni.', 'seher-yeli-duy-beni-ensar-cevval-59w2a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seher yeli gel de yüzümü okşa! 

geceden kalma emanet karanlığı al

çölde kutsanmış sular öpsün yüzümü

ve her zerremi imanın aydınlığı...

Ellerimin arasındaki sadece bir baş mı? 

sanmam; 

bir dünya, ağırlaştıkça ağırlaşan

öyle fırtınalar, gelgitler varki

yüreğimin kıyıları harman olmuş

gözbebeklerimde güneş kırıkları, 

koca bir sahil burası

yalnız kalabalıklar

hangi yüze baksan iki insan

dudağın bir yanı tebessüm

öbür yanı hüzün

otuzüç gece gördüm

otuzüç gündüz

demek ki altmışaltı zaman

yüreğime bir kor düştü sabah yeli! 

üçyüzaltmışbeş kez alev oldum

üçyüzaltmışbeş kez su

yaşamdan alacağım var artık

hakkımı helal etmem suya

mutluluğuma tuz aktı

belki hissetmedi gözlerim; amma

yüreğime çarpınca gözümü kör etti.

13,10,2003 Sirkeci-İstanbul', 'Seher yeli gel de yüzümü okşa!  geceden kalma emanet karanlığı al çölde kutsanmış sular öpsün yüzümü ve her zerremi imanın aydınlığı... Elle...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seher-yeli-duy-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen!', 'sen-murat-sahan-8d8v2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nevin Şahan''a

Kimse anlamaz ki onlara seni anlatayım, seni ne çok sevdiğimi... 

Elini tutunca bir olmayı, gözüne bakınca yok olmayı, 

Damarlarında kan, dudağında su olmayı....

Aydınlıkta gözüm, karanlıkta elimsin; 

İçtiğim su, yediğim ekmek gibisin. 

Yerde toprağım, gökte güneşimsin; 

Yaşarken can yoldaşım, ahirette kefenimsin.

Elimde kalem, aklımda fikirsin; 

Dilimde duam, kalbimde zikirsin; 

Allah’tan her gün dilediğimsin; 

Sen benim sultanım, sen sevdiğimsin! 

Sen benim kalemsin, sığındığım en son limanım; aşkım, arkadaşım, dostum, sırdaşım! 

Sen benim kalbimdeki ormanları ateşe veren peri, 

Sen benim yüce sevdamın alın teri! 

Sen benim emeğim, göz nurum, 

Sen benim her şeyim! 

Sen, sevgilim! ..

								31.12.1998', 'Nevin Şahan''a Kimse anlamaz ki onlara seni anlatayım, seni ne çok sevdiğimi...  Elini tutunca bir olmayı, gözüne bakınca yok olmayı,  Damarl...', ARRAY['Türk Edebiyatı','Şiir','Murat Şahan']::text[], 8.5, '{"poet":"Murat Şahan","poet_slug":"murat-sahan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-296-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '... Aşkınla Kelebek Gibi...', 'askinla-kelebek-gibi-suleyman-saylan-53qjf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '... AŞKINLA KELEBEK GİBİ...

Baharı beklerken vurgunu yedim; 

Karşıma çıktın sen, bir melek gibi.

Çılgınca tutulan bu yorgun kalbim; 

Uçuyor aşkınla kelebek gibi...

Gönlüm bu sevgiyle sel gibi aktı, 

Tanrıya yalvarıp bir dilek kaptı, 

Sevinç yumağından kanatlar taktı, 

Uçuyor aşkınla kelebek gibi...

Kanım dondu sanki, damla akmıyor, 

Ateşinle yanarken acı çekmiyor, 

Dünya güzeline dönüp bakmıyor.

Uçuyor aşkınla kelebek gibi...

Süleyman SAYLAN

(Ankara,09.05.1993, Saat: 22.00) 

Şarkı sözü olarak yazılmıştır.', '... AŞKINLA KELEBEK GİBİ... Baharı beklerken vurgunu yedim;  Karşıma çıktın sen, bir melek gibi. Çılgınca tutulan bu yorgun kalbim;  Uçuyor ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askinla-kelebek-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumun Efendisi', 'ruhumun-efendisi-meral-balci-tanis-szkg6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Korkundur, 

Korkumun peşi sıra sürüklenen.

Yüreğindir, 

Ömrünün en parlak seherin de, 

Beni yitireceğinden korkan. 

Allah seveni korur.

Seven sevdiğinin olur.

Ve bu denklem sürdükçe, 

Dünya yerinde durur.

Soyum seninle yürür.

Bensiz kalmaman için

Dua edişimin sebebi, 

Sensiz kalmamak için(se)

Ruhumun efendisisin. 

Beyhudedir endişelenişin.

13/10/2003', 'Korkundur,  Korkumun peşi sıra sürüklenen. Yüreğindir,  Ömrünün en parlak seherin de,  Beni yitireceğinden korkan.  Allah seveni korur. Seve...', ARRAY['Türk Edebiyatı','Şiir','Meral Balcı Tanış']::text[], 8.5, '{"poet":"Meral Balcı Tanış","poet_slug":"meral-balci-tanis","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruhumun-efendisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabesk Fantezi', 'arabesk-fantezi-oguzkan-bolukbasi-4g1wq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.........................''bu şiir hayatının güzellikleri acı olan arkadaşıma armağandır''

Tesellisi yok aşkımın, geceler kapkara

Yağmurlar değil göz yaşlarım düşüyor sokaklara

Ellerimi geceye sürüyorum ellerim yanıyor

Gözlerim nemli ellerim cerahat ellerim yara

Şarkılar söylensin hepsi yakamozlara

Şiirler yazılsın dizeler martılara

Canımı jiletlere kurban ediyorum

Gömleğim kan oldu ellerim cerahat ellerim yara

Gelme kanamam sana yalnızlığım ilacım

Doymak yaramaz bana acının lezzetine açım

Çöllerde mekanım kadehlerde sabahlarım

Bak ağarıyor başımda tel tel saçım

Adını ağaçlara kazıyorum ormanlar yakıyorum

Şimşek olamıyorum kibritler çakıyorum

Çiçekler açıyor bahçelerde baharlar kokuyor

Seviyorum diyorsun ben sevgiden kaçıyorum

“Ben acıların çocuğuyum”', '.........................''bu şiir hayatının güzellikleri acı olan arkadaşıma armağandır'' Tesellisi yok aşkımın, geceler kapkara Yağmurlar de...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/arabesk-fantezi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Timsah Gözyaşları', 'timsah-gozyaslari-aysel-coban-4hca7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hissedilen en güzel duygular

Dağlardaki yaban çileği tadında.

Yaşadıkça içinde mayhoşumsu bir tat

En güzeli tattıkça, 

İçini ferahlatan serinlik.

Her şeye rağmen belli belirsiz korkular derinlerde

Anlatılmaz duygular fırtınası o an.

Estikçe savrulan, 

Çiçek tozları yığını düşünceler.

Bir bir konar sevgi yağmuruyla yıkanmış gönlüne

Uzun gecelerde, 

Gizemli sabahlara yol alırken korkular.

Hangi limana sığınıp, demir atacak yalnızlığa

O yalnızlık oturur içine bir kor gibi.

Paylaşılmaz, yaşanır biçare

Dayanılır gibi değil yaşananlar.

Düşündükçe çoğalır sorular, 

Nedensiz olmaz ya hüsranlar

Sebeplidir elbet, 

Verilen cevaplarla birlikte, 

Bir de timsah gözyaşları, gözlerinde 

O, tırpan misali söküp almıştır umutları

sürgün tarlasındaki cellat, 

artık bedel ödeme zamanı

İhanet SİLGİDİR.

Affetmez.', 'Hissedilen en güzel duygular Dağlardaki yaban çileği tadında. Yaşadıkça içinde mayhoşumsu bir tat En güzeli tattıkça,  İçini ferahlatan seri...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/timsah-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan', 'hazan-aysel-coban-vyqqg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baharın serzenişiyle uyandım

Kapıldım mis kokan, aşk çiçeklerine

Kelebek misali, uçup sana kondum

Belki severim diye

Yanılmışım.

Sonra aşkın meyvesini yedik seninle

Dolu dizgin duyguların esiriydik.

Paylaşılan her şey sahteymiş

Oysa ki, kapılan bendim yalanlara

Hissedemedim.

İçimdeki serseri ruhla

Rüzgarın estiği yere savruldum

O an hazan mevsimiydi

Kırılıp, kahrolan bendim

Anlamadın.

İşte o hazan mevsiminde

Asıl hazan yaprakları

Ruhumdaki aldanmış duygulardı

Sızıyordu birer birer 

Bu son hazanda 

Engel olamadım.', 'Baharın serzenişiyle uyandım Kapıldım mis kokan, aşk çiçeklerine Kelebek misali, uçup sana kondum Belki severim diye Yanılmışım. Sonra aşkın...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hazan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hançer', 'hancer-aysel-coban-v9hgs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hak etmediğin acılarla beraber

Delik deşik edilmiş yüreğinde bir hançer...

Sen de varsın üstelik bunlara tuz biber olan

Göz bebeklerimde çektiğim acı zonklar

Ağlamak istersin ya, gözyaşın kurumuşsa

Yutkununca hıçkırığın tıkanmışsa boğazında

Söyleyemem o an hissettiklerimi çaresiz

Her şeyin bir bedeli var demiştin

Buraya kadar deyip pes ettim.

Değdi mi bunca yıllara boşa heder oldum.

Geçmiş içinde kara saplı bir hançer

Öyle saplanmış ki ta...derinlere nüfuzeder.

Sökmek istersin, 

Çektiğinde daha da kanar

Ya öyle kalacak, 

Öyle yaşayacaksın.

Yada söküp alıp, 

Kanayan her katrede yok olacaksın.', 'Hak etmediğin acılarla beraber Delik deşik edilmiş yüreğinde bir hançer... Sen de varsın üstelik bunlara tuz biber olan Göz bebeklerimde çek...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hancer-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Var Ya Sen, İşte Öylesin..!', 'sen-var-ya-sen-i-ste-oylesin-aysel-coban-w4n32', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen doğruluktan ayrılmayan güzel

El değmemiş bakir ormanlar kadar saf

Üstüne varılınca, 

Ehlileşmemiş bir yaban kısrağı gibi hırçın

Nerede bir güzellik görsen

Hep açarsın Yediverenler gibi, 

Dokunmasın kimse iffetine

Dişi aslan gibi yırtıcısın

Söz söylenmesin onuruna

Öyle ki; 

Mağrur kardelenler kadar erişilmezsin.', 'Sen doğruluktan ayrılmayan güzel El değmemiş bakir ormanlar kadar saf Üstüne varılınca,  Ehlileşmemiş bir yaban kısrağı gibi hırçın Nerede b...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-var-ya-sen-iste-oylesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Biter mi?', 'umut-biter-mi-bekir-mutlu-gokcesu-sta9m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçim sıkılınca

Sarıveriyorum kendimi

Sıkı sıkıya umutlarıma

Umutlar pembemsi, şekerli

Yumuşacık pamuk helva gibi

Her şekle giriyor avuçlarımda

Çocuk gibi oluyorum

Tadı kalıyor damağımda

Eriyip gitse de

Sapı da kalsa eninde sonunda

Olsun ne çıkar

Umut biter mi? 

Bizim köşe başında

Horoz şeker, elma şeker

Paşa gönlüm ne çeker

Kağıt helva, pamuk helva

Gidiyorum hemen almaya', 'İçim sıkılınca Sarıveriyorum kendimi Sıkı sıkıya umutlarıma Umutlar pembemsi, şekerli Yumuşacık pamuk helva gibi Her şekle giriyor avuçlarım...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/umut-biter-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyhude', 'beyhude-aysel-coban-xod4p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bil ki sevdiğim her şey yalan

Senin aklını başından alan

Ah gözüm görmez aklın talan

Sen sevda yollarında kalan

Ben umutsuz sende korkusuz

Yollarında ayrılmış sorgusuz

Olunmaz artık canım kaygısız

Yılların hasreti de sonsuz', 'Bil ki sevdiğim her şey yalan Senin aklını başından alan Ah gözüm görmez aklın talan Sen sevda yollarında kalan Ben umutsuz sende korkusuz Y...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beyhude-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mümkün mü?', 'mumkun-mu-aysel-coban-paij8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gizemli siyahın süslü ışıklarında

Mavi siyahın üstüne düşen ışıltılarda

Parlak yolun, bitiştiği kumsalda

Yakamozu oluşturan ay ışığında

Seninle yaşadığım anları

Hatırlamamak  mümkün mü?', 'Gizemli siyahın süslü ışıklarında Mavi siyahın üstüne düşen ışıltılarda Parlak yolun, bitiştiği kumsalda Yakamozu oluşturan ay ışığında Seni...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mumkun-mu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahika', 'sahika-aysel-coban-z0939', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şaha kalkmış tüm duygularım

Adını bilmediğim belirsizlik içinde

Hümanist bir yaşam derdinde

İnanmak zor kalpsizlik selinde

Kabullenmek yalnızlığı, hasretim dorukta

Arzular sel olmuş çağlıyor bedenimde', 'Şaha kalkmış tüm duygularım Adını bilmediğim belirsizlik içinde Hümanist bir yaşam derdinde İnanmak zor kalpsizlik selinde Kabullenmek yalnı...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sahika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimlerden kış', 'mevsimlerden-kis-aysel-coban-dkb1l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevsimlerden kış

Ve o soğuk kış geceleri

İnsanın dışarıda iken kanının donduğu saatler

Biran önce eve gitmek için

Acele ettiğin uzun titrek dakikalar

Sıcacık sobanın hararetini düşlediğin anlar

Eziyettir insana

Eve gelindiğinde tüm vücudunun donduğu anladığında

O zaman yoksul ve aç olan insanları düşünürsün

Soğuk yorgan altında yaşamlar sürer

Ya ben de dışarıda kalsaydım

Şanslıyım bir evim var dersin.

Vakit kaybetmeden sıcak bir şeyler içersin

Gözlerin ansızın, 

Sobanın kenarında kıvrılıp uyuyan kediye takılacak

Gidip bir güzel mıncıklayacaksın

Dışarıda lapa lapa kar yağıyor

Pencereden karın yağışını izlerken

Bu manzaranın yanda mısır patlağı yenir

Ve elindekilerle dalıp gidersin uzaklara

Az sonra gözlerde bir mahmurluk

Sıcak yatak hayaliyle farkında olmadan uyuklarsın', 'Mevsimlerden kış Ve o soğuk kış geceleri İnsanın dışarıda iken kanının donduğu saatler Biran önce eve gitmek için Acele ettiğin uzun titrek ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mevsimlerden-kis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşma Vakti', 'kavusma-vakti-i-brahim-bayraktar-tojid', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dönüşü olmayan meşakkatli bir yolculuktur, 

Yolcu yoldan habersiz; yol, yolcudan, 

Gözyaşı gibi süzülür yamaçlardan, 

Her taşa, her kayaya kokusunu bırakarak.

Yalar gider toprağı, izi kalır yarınlara.

Tepeler aşar, vadiler dolaşır, 

Çağıl çağıl akan derelere karışır, 

Dereler, nehir olur yatağına ulaşır.

Kimi yerde köpük köpük köpürür, 

Kimi yerde çağlayan, kimi yerde nehir, 

Bazen iplik iplik akar, bazen kudurur, 

Bazen canlar alır, acılara boğar, 

Rahmet olur çise çise yağar, 

Zemzem olur son nefeste, 

Gönüllere akar aheste aheste.

Yeşile renktir, doğaya bereket, 

Bir damlası hayat olur tohuma, 

Bazen ırmak olur çağlar, 

Bazen gözlerde yaş...

Geçit vermez, yollar keser, 

Yolcuya yaren olur günlerce, 

Bazen kurnası kırık bir pınar, 

Bazen eşme...

Mahşeri bir kalabalık bekler, 

Gelin alayını karşılar gibi coşkulu, 

Kucak açmış mavi deniz, 

Dört gözle bekler yeni misafirini.

Mahmur çiçeği gibi avuçlarıma dol, 

Bayram etsin gün yanığı ellerim, 

“Başın pınar olsun ayağın göl”.

Duamız varlığına; “Su gibi aziz ol”.

13.10.2003', 'Dönüşü olmayan meşakkatli bir yolculuktur,  Yolcu yoldan habersiz; yol, yolcudan,  Gözyaşı gibi süzülür yamaçlardan,  Her taşa, her kayaya k...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kavusma-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladıkça Kaybettik', 'anladikca-kaybettik-fahrettin-tatlici-098r9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlayacak ne kaldıki

konuşacak birşey olsun.

Korkusuz sevmeler, 

erken küsmeler geçti ömrümüzden.

Gözlerimiz çocuktu, 

yaşlarımız acemi

döküldük ömre hesapsız.

Utangaç sevmeyide kaybettik, 

çekingen gülmeyide.

Nevardı

bukadar unutkan olmasak

şimdi gözümüzde bizdeydi

gönlümüzde.

Kaptırmayacaktık ikisinide; 

Ergenliğimizde çocuk kalacaktık, 

gençliğimizde tilki olsaydık....', 'Ağlayacak ne kaldıki konuşacak birşey olsun. Korkusuz sevmeler,  erken küsmeler geçti ömrümüzden. Gözlerimiz çocuktu,  yaşlarımız acemi dökü...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Tatlıcı']::text[], 8.5, '{"poet":"Fahrettin Tatlıcı","poet_slug":"fahrettin-tatlici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anladikca-kaybettik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-aysel-coban-m4dvk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin gizemli sabahlara tesliminde

Ben yatağımda, 

Kapanmış göz kapaklarım, 

Yorgun ve hasret sana

Seni aramakta göz bebeklerim 

Sevgili bahçesinde kayboluyorum.

Karşımda sen ve sana benzeyen

Çıplak aşk tohumları

O an hoyratça seni seçiyorum.

Çılgınca duygular kaplıyor beynimi

Arzular şeytanına uyup, 

Uzanıp sana dokunuyor, 

Günahların ateşlerinde kavruluyorum.

Duyguların susamışlığında

Sana hasret seni kucaklıyorum.

İşte o zaman

Olanca arzular selinde çağlıyor kalbim

Ansızın müthiş göz alıcı bir ışık demetiyle

Kopuyorum senden 

Boncuk boncuk günahların kaydığı terlerle

Açıyorum gözlerimi

Hain sabahın ışıklarıyla

Kaybetmiştim seni.', 'Gecenin gizemli sabahlara tesliminde Ben yatağımda,  Kapanmış göz kapaklarım,  Yorgun ve hasret sana Seni aramakta göz bebeklerim  Sevgili b...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ruya-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-aysel-coban-it5gm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzayan gecede dekolte giymiş hüsranlar

Karanlık yüzün, ışıltılı görünüşü var.

Dokunsan bir anda dağılan parlak ışık

Kaybolup gidiş, içinde hırçın sesi uyandırırdı

Bir çiğ tanesi kadar umutları tutan gözler

Vakti gelince gül yaprağında kayan saniyeler

Oysa ki neleri vaat etmiş görünürdü

Bir bekleyişti, bir umuttu zaman

Genç kızın mahmurlu gözlerinde puslu sabahlar

Açılınca gözleri, üşüşür kipriklerine bir bir yansır

Zaman akrebin peşinde yelkovan neyin derdinde

Yetişmek için, acelen ne güzelim, vaktin kısa

Yaşam kum saatinde hapistir o an

Çıkar tadını her anın, zaman akıp gitmeden

Kum tanelerinde gizli yaşadıkların, gün gün

Yakalamak imkansız onları, geri döndüremezsin

Geride kalanlarla yetinecek, güleceksin her zaman

Kızıl akşamlar yaşanırken bile bile

Beklersin gidişi, istemeden izin verirsin

Bilirsin ki aynı şeyler yaşanır bu bir döngüdür

Zaman  dalga geçiyor sanırsın yüzünde gülücüklerle', 'Uzayan gecede dekolte giymiş hüsranlar Karanlık yüzün, ışıltılı görünüşü var. Dokunsan bir anda dağılan parlak ışık Kaybolup gidiş, içinde h...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zaman-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem ve Arayış', 'ozlem-ve-arayis-aysel-coban-npvwh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yakaladığım dediğin an uzaklaşırsa

O meçhul diyar.

Dokundukça eline sinen

Gül kokusu misali.

Başını döndüren iç çekmeler

Olsun, 

Geldi gelecek derken geçecek zaman

Süre dolunca açılır kapılar, 

Mis kokan bahçelere

Gezinirken adım adım, 

Unutulan ne varsa  çıkar karşına

Kaybedilenler bitiverir başucuna

Özlenilen bir el gibi

Başının okşanmasını bekler

Neredesin ey zaman, 

Acımasız ey adem derken

Seni bekledim.

Al götür beni buralardan

Bilir ki bu bir rüyadır bitecek elbet

Uyandığında gerçekler

Bir tokat gibi vurmadan gecelere

Ne yapsan kardır düşüncesiyle

Yaşananlar kalsın dimağında

Soğuk siyahın kızıl aydınlığa tesliminde

Teninde kalan sıcaklığı hissetmek için

Denemeye değdi demekle, kalmaya değer

Mahmur göz kapaklarında

Uyku denen illet bittiğinde', 'Yakaladığım dediğin an uzaklaşırsa O meçhul diyar. Dokundukça eline sinen Gül kokusu misali. Başını döndüren iç çekmeler Olsun,  Geldi gelec...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ozlem-ve-arayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesi derin', 'oylesi-derin-aysel-coban-y7h8n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Açığa çıkmayan duygularda, 

Derinlerde bir yer var.

Olmayacak şeyler için

Düşünülen istemler günah

Sorgusuz ve acımasız

Derin, öylesi derin işler içine hesapsız

O derinlerde içindeki sesler tehlikeli

Düşünceler ise kaçık, 

Arzular bile uçuk

Ta derinlerden gelen, 

İçindekileri yansıtan aldatıcı bir yüz

Günün birinde senden istenilen şeyler

Derinden derine kaplar içini

Beynindeki doğrular karmaşık

Beklenmeyen olgularda şaşkın

İsyan eder durur ve suskun

Karşı çıkmalı o zaman

Elde edilemeyen düşünceler karşısında kızgınlık

Kızgınlığın içinde küstahlık

Gözleri sis perdesinde

Gizemli bakışlarında kuyruklu yalan

Ve olanca yüzsüzlükle

Kılı kırk yaran sözler

Üstün çıkmak için yapılan asabi hareketler

Bu ne cürret böyle? 

Öylesi cesur, 

Öylesi hoyratça, 

Öylesi küstahça, 

Üzgün olmanın pençesinde düşünürsün

Ve boşa harcanan zaman', 'Açığa çıkmayan duygularda,  Derinlerde bir yer var. Olmayacak şeyler için Düşünülen istemler günah Sorgusuz ve acımasız Derin, öylesi derin ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/oylesi-derin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim', 'memleketim-aysel-coban-cxgyz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Of ta of, of anam of

Yine hüzünlendim.

Yine özlem sardı her yanımı

Şimdi anam olsaydı, kollarında uyusaydım.

Yaptığı ekmeğin kokusunu özledim.

Kaşarını, lorunu, sütünü, kaymağını

Yayık yaydığı günleri özledim.

Nerede bir ot görsem

Ekin tarlalarını hatırlarım.

Babamın tırpanla başakları biçişini özledim.

Tepelerde gezmelerim, 

Gelincikler arasında yuvarlanışım, 

Kardeşlerimi kandırışım, 

O şımarık günlerimi unutamıyorum

Herkes gözümde tütüyor

Mehmet emmiyi, Hatçe nineyi, 

Nafiye bacıyı, Osman kardaşı

Köyümdeki insanları özledim.

Ya karabaşım nerededir şimdi

Hangi tavuğun, hangi kazların peşinde, 

Hangi ine kaçmıştır.

Yine dağıtmıştır ortalığı, anam arka sıra dolanır

Dayanmaz gelir öper onu, hem de kemik elinde

Gürül gürül akan dereleri

Mis kokan çam ormanları 

Balık tutmaya çalışırken ıslanışımı

Çıplak ayakla kaçışımı özledim.

Ormanda kozalak toplamayı

Sırtında çalı çırpı taşımayı

Temiz havasını, soğuk sularını

Çılgınca yağan yağmurunu özledim.

Karlı günlerde kızak kayıp, 

kartopu oynayışımı 

her şeyi ama her şeyi memleketimi özledim.', 'Of ta of, of anam of Yine hüzünlendim. Yine özlem sardı her yanımı Şimdi anam olsaydı, kollarında uyusaydım. Yaptığı ekmeğin kokusunu özledi...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/memleketim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi Derdimiz', 'neydi-derdimiz-aysel-coban-4ewfe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neydi paylaşamadığımız şeyler

Niye kör kuyu olmuş hayatımız

Neden öfkeye mahkum yüreklerimiz

Yaptıklarımızın sonunu düşünmeyip

Yaşadığımız  anın kıymetini bilmeyiz

Yüreğimizin derinlerine gömdüğümüz

Unuttuğumuz değerleri görmeyiz

Her gün doğan güneşi göremeyebiliriz

Son kez soluyup son kez uyuyabiliriz

Sevdiğimizin yüzüne bir daha bakamayabiliriz

Kırılan kalpleri onaramayabiliriz

Neydi paylaşamadığımız hayatta

Niye körelmiş sevgi için çarpan kalpler

Neden sevmek yerine nefretle yaşarız

Zaman bize düşman anlamayız

Geçmişi, geleceğe kovalıyor, farketmeyiz

Yaşanılan arbedelerle uğraşırken

Kaybettiklerimizi geri döndüremeyiz

Kırışık zamanın izi belirdiğinde

Yalnız uyuyanlar arasına katıldığımız an

Baş ucumuza kısa not yazılan 

Ebedi hayatımıza yönelirken ah ederiz

İşte o an sorarız

Neydi bizim derdimiz.', 'Neydi paylaşamadığımız şeyler Niye kör kuyu olmuş hayatımız Neden öfkeye mahkum yüreklerimiz Yaptıklarımızın sonunu düşünmeyip Yaşadığımız  ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/neydi-derdimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Bakışı', 'mutluluk-bakisi-goktu-kara-a103w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gökyüzüne bakarken rastladım sana

ya sen bulutlara benziyordun ya da

bulutlar sana

bir mutluluk bakışı içindeydim

düşünceler içine daldım

hep seni uzakta mı arayacaktım

geçende bir öykü okudum

seni anımsadım hemen

kitabı elimden bıraktım

sana koşacaktım

vazgeçtim sonra

beni alıkoyan senden

bakışlarındı bana mutlu mutlu bakan', 'gökyüzüne bakarken rastladım sana ya sen bulutlara benziyordun ya da bulutlar sana bir mutluluk bakışı içindeydim düşünceler içine daldım he...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mutluluk-bakisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bulamadigim', 'bulamadigim-aysel-coban-fphb8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin sessizliğinde, 

Rüzgarın eşliğinde

Yalnızlığıyla dans eden ben.

Etrafım kalabalıkken, bir o kadar ıssızım

Karşımda bir dost eli, 

Yüzünde sıcak bir gülüş

Bir sevecen söz

İçimde, şimdi bir şeyler eksik

Olmuyor, 

Yalnızlığın içinde kapana kısılmışım.

Kalabalığın ıssızlığı boğuyor.

Arayıp bulamadığım, 

Çözüp anlayamadığım, 

Kadehlerin tanıklığında

Bu akşam, 

Neydi bu masada bulamadığım.', 'Gecenin sessizliğinde,  Rüzgarın eşliğinde Yalnızlığıyla dans eden ben. Etrafım kalabalıkken, bir o kadar ıssızım Karşımda bir dost eli,  Yü...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bulamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz', 'caresiz-yavuz-turhan-gtqga', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güllerin solduğu saatte

                                      yapayalnızım...

Şehrin ışıkları bir bir damlıyor

                                       caddelere.

Sezsizliğe gömülüyor zamanlar

                                        ezan sesleriyle, 

Kaldırımlar, çöp ve tükürük yığını; 

                    herkes kinini kusmuşçasına...

Gölgeler, sahiplerine yabancıymış gibi, 

                    önde ve hızlı gidiyorlar.

Ciğerlerimdeki avaz, patlama noktasında.

                    boğazımdakihıçkırıklar yolvermiyor.

Elektrik direklerini sayıyorum bir bir, 

                    gözlerim su birikintilerinde.

  -Yüzün yansıyor-

Düşlerime bile sığdıramıyorum sevgini...

Ellerimde kalemimin dil bilmez çaresizliği...', 'Güllerin solduğu saatte                                       yapayalnızım... Şehrin ışıkları bir bir damlıyor                              ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/caresiz-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başım Dönüyor..', 'basim-donuyor-suleyman-saylan-qicyj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BAŞIM  DÖNÜYOR..

Yıllarca küllenen sevda derdimden

Üfürüp külleri közler örüyor, 

Bir duygu dalgası coştu kalbimden

Sevgi ipliğiyle bir aşk örüyür

Ben aşk sarhoşuyum başım dönüyor.

Kıvılcım çakıyor damarlarımda, 

Yanıyor yüreğim senin aşkınla, 

Sen de değilsin belki farkında...

Bakışın yakarak bir aşk örüyür, 

Ben aşk sarhoşuyum başım dönüyor.

İnan ki suçsuzum seni severken, 

Farkında olmadan kapılmışım ben, 

Aşk aydınlığından zindana düşen...

Hasret çeksem bile bu aşk büyüyor, 

Ben aşk sarhoşuyum başım dönüyor.

Süleyman  SAYLAN

(Ankara,01.07.1993, Saat: 15.15)', 'BAŞIM  DÖNÜYOR.. Yıllarca küllenen sevda derdimden Üfürüp külleri közler örüyor,  Bir duygu dalgası coştu kalbimden Sevgi ipliğiyle bir aşk ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/basim-donuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-yavuz-mehmet-erturk-i7le5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen yanar ya zaman

Geçmez olur durur öylece

Hani sıcak bir şey gönle sızan

Kurur uzakta durur öylece

Susar ya rüzgarın ve ahengin

Eski mabetler gibi kalırsın yalnız

Okyanuslardan bile daha engin

Sadece kendin olursun yalnız

İşler bedenine hasretin sancısı

Gözlerin hırpalanır kalırsın garip

Dostlar olur umudun yalancısı

Sen de unutulmuş olursun garip

	(11 Temmuz 99 gece İstanbul)', 'Bazen yanar ya zaman Geçmez olur durur öylece Hani sıcak bir şey gönle sızan Kurur uzakta durur öylece Susar ya rüzgarın ve ahengin Eski mab...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Mehmet Ertürk']::text[], 8.5, '{"poet":"Yavuz Mehmet Ertürk","poet_slug":"yavuz-mehmet-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/garip-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Şiir Dostuyum', 'ben-bir-siir-dostuyum-yavuz-mehmet-erturk-zgwtg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bir şiir dostuyum…

Yani, mısralarla bir yakınlığım vardır.

Bir tanıdıklık, 

Bir his birliği işte.

Gülümserim onları görünce, 

Ellerinden sıkar, 

Hoş geldiniz der, 

Sonra buyur ederim, 

En güzel defterlerimin en beyaz sayfalarına.

Ben bir şiir dostuyum…

Yani, şairlerle bir yakınlığım vardır.

İçimdeki çocuğu kırmam.

Eline kalemi verir, 

Gözlerimi kapar, 

Onunla yaşarım bir zaman.

O yazar, ben dinlerim, 

O okur, ben hüzünlenirim.

İçimdeki şairi severim.

Yani üstadım, 

Ben bir şiir dostuyum.

Şiir kadar nazik, 

Şair kadar derbederim.', 'Ben bir şiir dostuyum… Yani, mısralarla bir yakınlığım vardır. Bir tanıdıklık,  Bir his birliği işte. Gülümserim onları görünce,  Ellerinden...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Mehmet Ertürk']::text[], 8.5, '{"poet":"Yavuz Mehmet Ertürk","poet_slug":"yavuz-mehmet-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-bir-siir-dostuyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-yavuz-mehmet-erturk-vquzv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün benim olursan sen

Ilık bir rüzgarla söndür ateşimi

Bir gün benim olursan sen

Yalvarırım ne olur bırakma peşimi', 'Bir gün benim olursan sen Ilık bir rüzgarla söndür ateşimi Bir gün benim olursan sen Yalvarırım ne olur bırakma peşimi...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Mehmet Ertürk']::text[], 8.5, '{"poet":"Yavuz Mehmet Ertürk","poet_slug":"yavuz-mehmet-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/eger-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Segâh Peşrev', 'seg-h-pesrev-hakan-kose-lyq7j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çalınız canım efendim Segâh''tan çalınız

Nerede elleri nazenin Mesut Cemil Bey

Nicedir Andon udundan dışarı çıkmıyor

Yıldızlara söyledim geç kalmayacaklar

Yaklaşın artık gözlerim beni sevmiyor

Boğaza nâzır idi seslerimizde leylaklar

Çalınız canım efendim Segâh''tan çalınız

Hayat ne kadar Mâhur idi bir zamanlar

Heybeli''de bitti yazık mehtâba çıkmalar

Ben ki Küçükköy''lü Dilrûba Nûr Sultan

Yürüyünce ardım sıra revân Dersaadet

Katibim Aziz Efendi derdimden perişan

Hatırlar mısınız gecelerden bir gece

Aşkını ilân etmişti Miralay Mustafa Bey

Sizler yine, Kürdîlihicazkâr çalmıştınız

Şimdi ne yâd eden var ne kapımı çalan

Ben ki Küçükköy''lü Dilrûba Nûr Sultan

Çalınız canım efendim Segâh''tan çalınız

Akşam olmakta şimdi koyu kızıl Segâh', 'Çalınız canım efendim Segâh''tan çalınız Nerede elleri nazenin Mesut Cemil Bey Nicedir Andon udundan dışarı çıkmıyor Yıldızlara söyledim geç ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Köse']::text[], 8.5, '{"poet":"Hakan Köse","poet_slug":"hakan-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/segah-pesrev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Üçbuçuğu Olduğunu Düşün', 'gecenin-ucbucugu-oldugunu-dusun-turgay-kaygi-4eajn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gecenin üçbuçuğu olduğunu düşün; 

sert bir poyrazın

masum meşe ağaçlarının kederli dallarını

durmadan silkeleyerek

kopardığı yaprakları

lambaların zar zor aydınlattığı caddeye

önce buruşturup attığını

ardından da

düşüncesizce 

dört bir yana dağıttığını düşün...

ağlayan sokak kedilerini düşün

park etmiş arabaların altında

sonra

bir elinde sigara

diğerinde dibi yaklaşmış bir

bira şişesi

çoktan kapanmış

bir taksi durağının pencere pervazına oturmuş

seni düşünerek azalmakta olan

beni düşün...

ve sonra

git; 

nereye ve

kime istersen....

(inegöl,  08.10.2003)', 'gecenin üçbuçuğu olduğunu düşün;  sert bir poyrazın masum meşe ağaçlarının kederli dallarını durmadan silkeleyerek kopardığı yaprakları lamb...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gecenin-ucbucugu-oldugunu-dusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senli Sensizlik', 'senli-sensizlik-gulay-yildiz-rbst3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidişinin acısı belkide içimi yakan

Biliyorum olsanda yanacak kalbim, yanlızım

Bak, geceden düştü bu yıldız, can çekiyor bahçemde

Almayacağım içeri yansın ve sönsün tıpkı kalbim gibi

Güneş doğacak, alacakaranlık bitmek üzere

Kapatacak güneş tüm karanlıkları ve hatta daha sönük ışıkları

O zaman gidecek bu yıldız göz ufkumdan

Garip mutluluklar yaratıyorsun içimde, olmayacaksın hiç

Gidişine sürgün kalacak kalbim

Gelişini bekleyecek ellerim ve gözlerim

Sevgini hisset diye söylemeden susuyorum

Kalbimde yangını bilecek kadar keskin, 

Anlamamış gibi dalacak kadar kurşuni bakışların

Ve sabredecek kadar olgun, 

Ezilmeyecek kadar haşmetli kalbim...', 'Gidişinin acısı belkide içimi yakan Biliyorum olsanda yanacak kalbim, yanlızım Bak, geceden düştü bu yıldız, can çekiyor bahçemde Almayacağı...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/senli-sensizlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmamış', 'yasanmamis-yildiz-yildiz-but66', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimse

Hiç kimse acıtamaz

Kendisi kadar insanı

Zorlamak, kırmak kolay

Yeter ki kendimiz 

Koymamış olalım sınırları

Yaşanmış gibi çok olmaz, 

İçeri, derine akar çünkü

Yaşanmamışın kanı.', 'Kimse Hiç kimse acıtamaz Kendisi kadar insanı Zorlamak, kırmak kolay Yeter ki kendimiz  Koymamış olalım sınırları Yaşanmış gibi çok olmaz,  ...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasanmamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksan', 'sen-yoksan-fatih-konuk-7hj3p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen yoksan

istemem güneş doğmasın dünyama

istemem kader gülmesin yüzüme

sen yoksan güneşin dünyama doğmasını, 

kaderin yüzüme gülmesini istemem

sen yoksan

isterim kıyametler kopsun içimde

isterim cehennem ateşleri yansın bağrımda

sen yoksan kıyametlerin içimde kopmasını, 

cehennem ateşlerinin içimde yanmasını isterim

sen yoksan 

dilerim ölümüm gelsin gidişinle

dilerim hayatım son bulsun ardından

sen yoksan gidişinle ölümümün gelmesini, 

ardından hayatımın son bulmasını dilerim', 'sen yoksan istemem güneş doğmasın dünyama istemem kader gülmesin yüzüme sen yoksan güneşin dünyama doğmasını,  kaderin yüzüme gülmesini iste...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-yoksan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gül Sana', 'bu-gul-sana-fatih-konuk-lbf7r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu gülü sana vermek istiyorum

biliyorum çok geç ama

yine de bu gülü almanı istiyorum

yıllar önce sana vermek istedim

ama o yıllarda gerek duymadım vermeye

şimdi ise öyle gerek duyuyorum ki

bu gülü almazsan gurur meselesi yaparım

kendi kendime bir yare bir gül veremedin diye

kendi kendimi suçlar dururum

bu gül benim için çok önemli

bu gülü benden, elimden al ne olursun

sakın bu gülü vermekten bir anlam çıkarma

beni bağışlaman, beni affetmen için vermiyorum

zaten istesemde olmaz ki sen başkasınınsın artık

bu gülü al istersen bir ömür boyu sakla, 

istersen de arkamı döndüğümde at

benim için bir anlam taşımaz saklaman, atman', 'bu gülü sana vermek istiyorum biliyorum çok geç ama yine de bu gülü almanı istiyorum yıllar önce sana vermek istedim ama o yıllarda gerek du...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-gul-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-emin-baydil-fphud', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çıkmaz sokakta bitince yollar

Gönül vadisine kahır döküldü.

Karanlığa nispet sarınca kollar

Zaman, damla damla zehir döküldü.

Her ânı gönüle tokmak saatler

Görmedi hiçbir şey, bak bak saatler.

Binince setlerin üstüne setler

Sandı ki kıyamet, mahşer döküldü.

Nereydi kaçışan, ne idi uçan? 

Neydi o su gibi, kimdi o içen? 

Yetti be gâfil! Çaldı, çaldı çan

Kimdi o peşinde şehir döküldü? ..

Söndü avuçlarda okunan dua, 

Nerede, bu çölde yok mu hiç vaha? 

Çok şükür sonsuza, lâ''net günaha, 

Dağı delen gözden nehir döküldü.

Yumağın ellere gelince ucu

Zamanı sır gibi verdi sunucu.

''Dök! '' diye denizi getiren sucu

Kırınca küpünden sihir döküldü.

Bulutlar savuştu, gözyaşım dindi

Sulara güneşin gölgesi indi.

Mevsim sonbahar, vakit ikindi

Dilden ''şükür Allah, şükür'' döküldü.', 'Bir çıkmaz sokakta bitince yollar Gönül vadisine kahır döküldü. Karanlığa nispet sarınca kollar Zaman, damla damla zehir döküldü. Her ânı gö...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/arayis-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Dilenci Değilim', 'ben-dilenci-degilim-emin-baydil-f7w8e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kızılay Meydanı''nda her akşam insan seli

Akarmış bir aşağı, bir yukarı ezeli.

Boş gezenler, gâripler, hoş vakit geçirirmiş

Âşıklar bir köşede beklerlermiş güzeli.

Bir gün, benim de yolum, düştü bu başşehire

Mahşerde sandım bir an, kendimi birdenbire.

Gördüm ki; nice insan, çalışmakta işinde

Kimisi de bin türlü günahların peşinde.

Dalmışım bu kaynayan insanların haline

Bıraktığım yılların yaşanmış hayaline.

Değişmiş değil insan, aynı kem göz bakmakta

Bencilliğe işaret, at gözlüğü takmakta.

Olan-biten ortada, tınmıyor hiçbirisi, 

İnsanların benziyor ölüye ekserisi...

Binlerce arasında, karar yoktu gülene

Bakınca bir ahûya rastladım gökdelene.

Gözlerimi yummuşum, kamaşınca maniden

Soğuk gülen bu beton yığınından aniden.

Bir ses beni o anda, uyandırdı ağlayan

Sandım, yanıbaşımda bir şelâle, çağlayan:

İmsakiye! 

İmsakiyem var benim.

Al, al! .. Sen de al haydi! 

İmsakiye! ..

''İmsakiyem var benim'' diyen o ses, kimdi kim! 

Baktım ki, bu bir mazlum, inildeyen bir isim.

Ayakları kesilmiş, gözleri kör bir kambur

Sermayesi aldığı kırık-dökük bir tambur...

Vurmakta, 

Vurmakta tellerine hayata kahrederek

Arasıra gözyaşı, dökmekte ''ahhh! '' ederek.

Çökmüş gibi görünen o cüsseden bir ara

Feryada benzer bir ses, dedi ki insanlara:

Varsın eğlensin beyler, hayır! Kinci değilim

Verin hakkımı benim, ben dilenci değilim...

İmsakiye almadan uzaklaşan birinin

Arkasından haykırıp fırlattı parasını.

İnsanlığın kaldı mı, nerede haysiyeti? 

Diyerek cemiyetin, attı yüzkarasını...

''Kaderim bu! ..'' der gibi, gözlerinden damla yaş

Çizerek geniş bir yay, dağıldı yavaş yavaş.

Anladım kı; yaşanan hayatın ta kendisi, 

Eziliyor toplumun, haklısı, efendisi.

Geçen yine uğradım, elinde tamburuyla

Biri ölmüş dediler, sırtında kamburuyla.

''Nasıl olmuş, bir anlat! '' dedimse de birine

Bana mânalı bakıp, yaklaştı diğerine.

Dedi; görülmüş değil, adamcağız ölünce

Şu yazılsın istemiş, taşına gömülünce:

Varsın, eğlensin beyler, hayır, kinci değilim

Verin hakkımı benim, ben, dilenci değilim.', 'Kızılay Meydanı''nda her akşam insan seli Akarmış bir aşağı, bir yukarı ezeli. Boş gezenler, gâripler, hoş vakit geçirirmiş Âşıklar bir köşed...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/ben-dilenci-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Cesaretten Açılmışken,', 'soz-cesaretten-acilmisken-mine-ozdemirtas-1p02k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buralarda biri, 

Cesaretten mi söz etti kızlar? 

Yani, 

Konumuz “Cesur bir adam”

Öyle mi? 

Ben böyle birini tanıyorum.

O çok cesur bir adam.

O; 

Aynı anda bütün hikayelerin

Kahramanı olmaya soyunan, 

O; rüzgarın oğlu olan.

Ama....yaya kalan

Hiç risk almadan

Üstelik; hiç durmadan

Rus ruleti oynayan

Plastik tabancalı adam.

Aslında; 

Onu, sizde tanıyorsunuz. Kızlar.

Hani o; ” tepeden , tepeden” bakar........

Hem önünüzde hem arkanızdadır aslında.

Sağınızda, solunuzda duran.

Hani canım şu...

Burnundan kıl aldırmayan

Kendini beğenmiş adam.

Hani neyi  diyemediği anlaşılmasın diye

Homurdanan.

Hani canım şu her yerde rastlanan

Hani kendisi küçük... gölgesi kocaman

Anlayın kızlar yaaaaaaaaa

Şu daima farklı olan, 

Yani; sıradan /sürüden olan.

Anladınız değil mi? İşte o; 

Çok cesur adam..

Söz cesaretten açıldı madem

İtiraf edeyim ki; Korkakları severim ben.

Bu yüzden; 

Cesur adamların hepsini

Size bırakıyorum kızlar.

İnanın hakkımdan vazgeçiyorum.

Pay edecekleriniz arasında, 

Benim payıma düşen “ cesur adam” da var

Gözüm yok helali hoş olsun.

Bana yeter....bende kalan.

Vallahi; tüm iyileri size verdim.

Sadece; 

Şu korkak olandır alıp gittiğim.

Hani şu; 

Şair bile olamadan; şiir yazan.

Hiç allayıp pullamadan

Dümdüz sevip, aşık kalan.

Yüreklice sevdim deyip, 

Ayrılıktan ödü kopan.

Yani; 

Azat ettiklerim kadar

Cesur olmayan adam.

İşte o; benimle geliyor.

Yokluğumda; 

Kendinize iyi bakın kızlar.

İzdihama hiç gerek yok.

Nasılsa; “cesur adam” lardan

Milyonlarca var.

Ben sadece; 

“Ben de kalamamaktan, ”Ve 

“Beni; kendinde tutamamaktan”  korkmayı bileni; 

Alıp gidiyorum.............  İşte o kadar.

Bundan sonrası  ise; 

Henüz yazılmamış satırlar.', 'Buralarda biri,  Cesaretten mi söz etti kızlar?  Yani,  Konumuz “Cesur bir adam” Öyle mi?  Ben böyle birini tanıyorum. O çok cesur bir adam....', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/soz-cesaretten-acilmisken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Hastalıgı', 'yalnizlik-hastaligi-andrei-shopovski-ty51o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kadar zor gün bugün

Yattım, uyudum durdum

Rahatsızım 

Geçen cuma soguk aldım

Üstüne iki gün yattım

Geçmedi körolası

Duvarlar yosun tutmuş

Yerler ıslak

Yokki bir sıcak çorba yapacak

Çorba olmasa da

Bir güzel  söz

Gözlerdeki ışık

Hiçbişey yok

Yalnızlık çok zor

Diyorum ki

Acaba giyinip dışarı mı çıkmalı

Ne bitiriyor beni? 

Ya yalnızlık 

Ya hastalık

Nem duvarı yıkar

Beni ise yıkan yalnızlık

Belki 

Belki bir tanıdık vardır

En azından mutlu insanlar

Mutlu insanlar yeter bana

Kalktım

Çıktım dışarı

Şansıma güneş de açtı

Üç güne varmadı iyileştim.

En kısa zamanda 

Güçlenmeli

Sonra da sevmeli

Belki de 

Belki de evlenmeli..', 'Ne kadar zor gün bugün Yattım, uyudum durdum Rahatsızım  Geçen cuma soguk aldım Üstüne iki gün yattım Geçmedi körolası Duvarlar yosun tutmuş...', ARRAY['Türk Edebiyatı','Şiir','Andrei Shopovski']::text[], 8.5, '{"poet":"Andrei Shopovski","poet_slug":"andrei-shopovski","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yalnizlik-hastaligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Kadın', 'i-cimdeki-kadin-ebru-delice-9zo91', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sönmeyen volkanı dizginlemek, 

Krateri hep kapatmak

Depremler oluyor ruhumda

Basıncım artıyor

Baramotre patlayacak

Arzular ölmedi içimde

Ruh um 70''ine geldi, 

Bedenim  hala canlı

Kalbim  paramparça

Med-cezirler içindeyim

Bitmiyor

Ölmüyor içimdeki kadın

Öldüremiyorum', 'Sönmeyen volkanı dizginlemek,  Krateri hep kapatmak Depremler oluyor ruhumda Basıncım artıyor Baramotre patlayacak Arzular ölmedi içimde Ruh...', ARRAY['Türk Edebiyatı','Şiir','Ebru Delice']::text[], 8.5, '{"poet":"Ebru Delice","poet_slug":"ebru-delice","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icimdeki-kadin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pusula', 'pusula-gurkal-aylan-wb4yc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dileksiz kayan yıldız

Damaklarda tizişen sessiz ses

Unutulmayacak bir dün

Köprüsüz karşıdan karşılar...', 'Dileksiz kayan yıldız Damaklarda tizişen sessiz ses Unutulmayacak bir dün Köprüsüz karşıdan karşılar......', ARRAY['Türk Edebiyatı','Şiir','Gürkal Aylan']::text[], 8.5, '{"poet":"Gürkal Aylan","poet_slug":"gurkal-aylan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pusula-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seni sevmeyi sevdim', 'ben-seni-sevmeyi-sevdim-olcay-kose-tpum4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çocukluğumda 

hep seni sevdiğimi söylerdim 

anneme

kara gözlerinin çıkmazını

o sımsıcak bakışlarını

sevdim

büyüdüm; 

dostlarıma söyledim seni sevdiğimi

bana kurşun yarası dokunuşlarını 

sana her gelişimde 

kendimden kaçışlarımı sevdim

ben seni sevmeyi sevdim

kalbimin en aydınlık hücresine 

hapsettim seni

ve zincir vurdum kapılarına

sonsuza dek saklayabilmek 

için........', 'çocukluğumda  hep seni sevdiğimi söylerdim  anneme kara gözlerinin çıkmazını o sımsıcak bakışlarını sevdim büyüdüm;  dostlarıma söyledim sen...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-seni-sevmeyi-sevdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya..', 'ruya-ebru-delice-i40st', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Etraf zifiri karanlık

Gözlerim alışıyor karanlığa

usul, usul aydınlanıyor oda

Beyazlaştı, her taraf beyaz

Oratada tüm çıplaklığıyla bir insan

Koşuyor duvardan duvara

Çıkışı olmalı mutlaka

Gece karanlık

Yumuşacık bulutun üsünde biiri

Bakıyor hayata..

Mehtap ve yıldızın aydınlığında

Kent ışıl ışıl

hayat cıvıl, cıvıl aşağıda

Meltem esiyor tüm yumusşaklığıyla

Bir pelikan sırtında uçuyorum

Açık denizlerde

Bir nokta gittikçe büyüyor

yeşil, yemyeşil ağaçlar

Sımsıcak kumsal, 

Dingin turkuaz bir deniz

Denizde bembeyaz bir ''yunus''

Yunusta ''ben''', 'Etraf zifiri karanlık Gözlerim alışıyor karanlığa usul, usul aydınlanıyor oda Beyazlaştı, her taraf beyaz Oratada tüm çıplaklığıyla bir insa...', ARRAY['Türk Edebiyatı','Şiir','Ebru Delice']::text[], 8.5, '{"poet":"Ebru Delice","poet_slug":"ebru-delice","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ruya-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halkalı Köle', 'halkali-kole-ebru-delice-zw54w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adliye koridorlarında, 

Kara cüppeli, çantalı 

Telaşlı bir sürü insan

Uğultu...

Mübaşirin sesi...

Davacı...! 

           Davalı....! 

İçeriden hakimin sesi

Yaz kızım karar! 

Şahitlerin dinlenmesine....

Davanın ''Fİ'' tarihe ertelenmesine! 

Çıt yok salonda

Bağırıyorum tüm gücümle, 

       Prangalar çürüdü, 

        Neden ben hala

          Halkalı Köle ''

Duyulmuyor sesim......

Sadece klavyenin sesi.....', 'Adliye koridorlarında,  Kara cüppeli, çantalı  Telaşlı bir sürü insan Uğultu... Mübaşirin sesi... Davacı...!             Davalı....!  İçerid...', ARRAY['Türk Edebiyatı','Şiir','Ebru Delice']::text[], 8.5, '{"poet":"Ebru Delice","poet_slug":"ebru-delice","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/halkali-kole-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun Sona Erdi', 'oyun-sona-erdi-i-lyas-sahin-i06in', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O gün ne kadarda güzel bir başlangıçtı

Yeni bir doğuşun habercisi gibiydi.

Gözlerini oğuşturması bile gerekmiyordu, çapaksızdı.

Gerinmesine bile gerek yoktu, yay gibiydi.

Bileğini kontrol etti, zihnini ve yüreğini, her şey tastamamdı işte

İlle de bir eksik bulması gerekli gibi bakındı durdu.

Yok, yok bugün o gündü işte, içinde beklediği anın saklı olunduğu gün

Hissediyordu, ta derinliklerinde.Yanılmıyordu işte yanılmamakta ısrarcıydı.

Çayını yudumlarken son çayını içtiğini biliyordu, oldukça keyifliydi.

Son kez yatağını topladı.sevgili menekşesine bakmak istemiyordu

ama arkasından hıçkırdığını duydu, kaçtı.

Kontak anahtarı da ne kadar kolay dönüverdi, 

bugün her şey rast gidiyordu, çünkü o gün bu gündü.

Alnındaki ışıltı ne kadarda farklı ama farkında değildi

Beklediği an onu bekliyordu

Kafasını kaldırdı göğe ve onu gördü.sağa baktı sola baktı hep o vardı

Gözlerini kapattı bir daha açmamacasına, o ordaydı

O gün güneş farklı bir batışla batmıştı

ve menekşe hala ağlıyordu.

10/2003', 'O gün ne kadarda güzel bir başlangıçtı Yeni bir doğuşun habercisi gibiydi. Gözlerini oğuşturması bile gerekmiyordu, çapaksızdı. Gerinmesine ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Şahin']::text[], 8.5, '{"poet":"İlyas Şahin","poet_slug":"i-lyas-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oyun-sona-erdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünbaz', 'huzunbaz-ahmet-aksoy-m268n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırık döküktü her yerin

Çıkık içindeydi bedenin

Ve sen, bir doktor yerine

Bana geldin

Niyetin geçirmekti acılarını

Alelacele, üstün körü

Aslında için için mutluydun

Üzgün olduğunu söylerken bile

Bense, bir doktordan çok

Bir çıkıkçı hüneriyle

Seni iyileştirmeye yeltendim

Yetmeyeceğini bile bile! 

Ki asla iyileşmedin

Hep sızladı uzuvların

Ve acıyordu her yerin bana bakıp

Beni sevdiğini söylerken bile...', 'Kırık döküktü her yerin Çıkık içindeydi bedenin Ve sen, bir doktor yerine Bana geldin Niyetin geçirmekti acılarını Alelacele, üstün körü Asl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huzunbaz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Malül', 'malul-ahmet-aksoy-3wskl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelecek baharlar daha gelmeden

Sen yine geri gel.

Bilirim; kendine hastır gidişin

Dönüşünse mecburi.

Kara bir kış gibi, 

Kalkarsın yüreğimin üstünden

Ki bir arbede, ki bir karambol

Hakim kalır hükümsüzlüğünle

Sen benim yaşama amacım

Sanki bir tulumbasındır 

Yüreğimin orta yerinde, işte bu yüzden 

Kanım pıhtılaşır gittiğinde

Ateşten de olsa tutacın

Alevden nehirler dolaşsa da bedenimde

Sen benim yaşama amacım; 

Ölüm dolaşmadan ovalarımı

“Geri gel sen yine”', 'Gelecek baharlar daha gelmeden Sen yine geri gel. Bilirim; kendine hastır gidişin Dönüşünse mecburi. Kara bir kış gibi,  Kalkarsın yüreğimin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/malul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı', 'aci-mustafa-sureyya-sezgin-blz1q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dalgın ve sakin

Yürüyorken yolumda

Bir çiçek kokusu soludum

Geliverdin aklıma.

Uzaklarda şekillendi bedenin

Ve cıvıltılı o sesin.

Bir kırgınlık  duygusu eklendi

Kimsesizliğime.

Zorluyor  gönlümün dizginleri

Özlüyorum! ..

İsyanlarda yüreğim

Sana atılmak istiyor

Engelliyorum! ..

Kaderimin üstünde

Bir karabulut gibisin

Tüm duygularım; “haydi ona koş” diyor.

Oysa seni görmek bile

Bana acı veriyor...

İstanbul,08.10.2003', 'Dalgın ve sakin Yürüyorken yolumda Bir çiçek kokusu soludum Geliverdin aklıma. Uzaklarda şekillendi bedenin Ve cıvıltılı o sesin. Bir kırgın...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aci-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Felsefeleri 4', 'hayat-felsefeleri-4-hakki-hakan-kaya-hncur', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zayıflık değildir ki acizlik, 

İhtiras ve şehvetin kaymağıdır, 

İçinde bir çığ gibi büyüyen, 

Tutku ve hırsın kaynağıdır.', 'Zayıflık değildir ki acizlik,  İhtiras ve şehvetin kaymağıdır,  İçinde bir çığ gibi büyüyen,  Tutku ve hırsın kaynağıdır....', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayat-felsefeleri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-murat-kilic-8se5h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölüp kalacak mıyım yoksa, ismini diye diye, Gün boyunca bekledim telefon çalsın diye, Ama sen aramadın ayrılalım diye... Bahtsız benim adım, ayrılık ise soyadım, Her geçen gün yaklaştım ayrılığa adım adım, Herşeyden ayrılırım ama ayrılıktan asla, Yoktur benim yarim ayrılıktan başka... İşte bir şiir daha, yine bir acı, Yarab dinmeyecek mi, bende ki bu sancı? O tatlı gülüşün artık benim kaderim, Gülüyor kaderim, bitmiyor kederim...', 'Ölüp kalacak mıyım yoksa, ismini diye diye, Gün boyunca bekledim telefon çalsın diye, Ama sen aramadın ayrılalım diye... Bahtsız benim adım,...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç']::text[], 8.5, '{"poet":"Murat Kılıç","poet_slug":"murat-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/ayrilik-123-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekar Odam', 'bekar-odam-murat-kilic-4a3ob', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazende bir sigara yetişir imdadıma, Şu bekar odam var ya, Şahit herşeyiyle sana olan aşkıma, Ne olursun bir soruver duvarlara, Neler dinlediler neler senin adına, Masamı bir görsen her tarafı çizilmiş, Sabahlara kadar beni dinlediler, üzülmüşmü üzülmüş, Eğer birgün gelirsen odama, kapım açılır kendiliğinden sana, Ümit kapısı oldu adı yıllarca, Her parçası senden iyi bilir seni, İnsan yalnız kalıncada mı anlatamaz sevdiğini? Benden daha çok özlediler ellerini, Ümit verde müjdeleyeyim geleceğini...', 'Bazende bir sigara yetişir imdadıma, Şu bekar odam var ya, Şahit herşeyiyle sana olan aşkıma, Ne olursun bir soruver duvarlara, Neler dinled...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç']::text[], 8.5, '{"poet":"Murat Kılıç","poet_slug":"murat-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/bekar-odam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul -2', 'i-stanbul-2-sirma-mersin-1j8ey', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adına sevdalar yaşanan,  İstanbul

Arnavut kaldırımlı sokakları, 

Beyoğlunun moziği ile; 

Çeşit çeşit insanları bir araya getiren...

Boğazın incisi herbiri; 

Bebeği ile, Çınarlatı, Emirganı ile

Bir tatlı huzurun olduğu, o yer Kalamış

Yeditepe üzerine kurulu; 

Anadolu insanın hayali olan İstanbul! 

Birbirinden güzel semtleri, 

Genci ile yaşlısının arasında, köprü olan

Bambaşka kuşakları bir araya toplayan...

Her mevsimi bir başka güzel olan, 

Zengini ile yoksulunu bir araya getiren, 

Gece ile gündüzü gibi başka bir dünya, 

Alımlı bir kadındır, İstanbul! 

8.10.02', 'Adına sevdalar yaşanan,  İstanbul Arnavut kaldırımlı sokakları,  Beyoğlunun moziği ile;  Çeşit çeşit insanları bir araya getiren... Boğazın ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istanbul-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki -1', 'belki-1-sirma-mersin-bozxu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belki! gecelerinde yaşayan bir hayal

Belki! mutluluğun için dua eden bir melek

Belki içinde sakladığın bir sır

belki gözlerinden yüreğine akan bi damla

Belki sevgiyi bulduğun bir kadın

Benliğinin içinde belkilerde  toplanmış her anlam...

1.09.02', 'Belki! gecelerinde yaşayan bir hayal Belki! mutluluğun için dua eden bir melek Belki içinde sakladığın bir sır belki gözlerinden yüreğine ak...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/belki-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mana', 'mana-aysel-coban-z1d9w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çift gören mavi boncuk

Anlam yüklü derinlere indikçe

Her nesne isim buluyor ışığında

Kararlığı aydınlatan ışık gibi

Üç boyutta canlanan her şey

Düşünmeye sevk ediyor

Zaman “mefhumuyla” birleşince zaman

Başka boyutta ben bir nokta

Varlığı sorgularken, yaşamı anlamak

Her nesnede ben varsam, bende var.', 'Bir çift gören mavi boncuk Anlam yüklü derinlere indikçe Her nesne isim buluyor ışığında Kararlığı aydınlatan ışık gibi Üç boyutta canlanan ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercin Kanadı', 'guvercin-kanadi-aysel-coban-4jxsj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gri bulanık bir gökyüzü dışarıda

Sünger gibi çekmiş ümitleri hayat

Alıcı kuşlar olsa da hayat denen o ucubede

Ne zaman istesek yağacak üstümüze

Bir güvercin kanadında haber yollasak yeter

Zamanında görülmezse ümit yüklü bulurlar

Sezdirmeden kayıp gidecek üstümüzden

Bir dağın doruğunda buluşmayı bekler

Ruhumuz özgür o zaman birleşmeyi özler', 'Gri bulanık bir gökyüzü dışarıda Sünger gibi çekmiş ümitleri hayat Alıcı kuşlar olsa da hayat denen o ucubede Ne zaman istesek yağacak üstüm...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/guvercin-kanadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elma Kurdu', 'elma-kurdu-aysel-coban-h6wbz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pencereme vuran sabah güneşi

Bu sabah, 

Yüreğimde elma kurdu olmuş hüzünleri ısıt

Gir içeri, 

Daha da ısıt, aydınlat yüreğimi

Erit ümitsiz gözlerimi

Al götür, 

Sevenlerin gönlüne akın edeyim.

Bırak beni yalnız akan dere kenarına

Issızlık içinde akıp giden derede yüzüm

Bir engel bulunca takılsın gönlüm

Sımsıcak bir gülüşle buhar olsun

Gözlerimde aç kalmış sevgi tohumları

Nereye serpsem onları, 

Yeşerse ansızın

Uzak şehirlerin kaldırımlarında 

Bir kadının elinde sevgiliye ulaşsa

Yeniden gözlerinde büyüse

Narçiçeği dudaklarda sevinç

Aç kollarını anladığın an

Tut ellerimi, 

Tut ki kenetlensin özlem dolu yüreğim.', 'Pencereme vuran sabah güneşi Bu sabah,  Yüreğimde elma kurdu olmuş hüzünleri ısıt Gir içeri,  Daha da ısıt, aydınlat yüreğimi Erit ümitsiz g...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/elma-kurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmayı Unutmak', 'unutmayi-unutmak-aysel-coban-dqh91', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayaklarım terk edilmiş bu masaya getirdi beni

Karşımda duran sandalye sahipsiz

Sahipsiz görünse de sahiplenen çok

Gel otur der’cesine sitemkar

Kalabalığa sinmiş nereden geldiği anlaşılmayan ten kokusu

O koku içimde yarım kalan gün ışığı

Gün ışığı aydınlattıkça göz bebeklerimi

Gözlerimde okyanusun haşin dalgaları yayılıyor.

Dışa vurum duygular hatırlanmak istiyor

Neydi unuttuğum, yada unuttuklarım

Kendim miydi unutulan, unuttuğum

Unutulmuşların yeri nereye aitti

Geri dönüşler olsa, çağrılsa gelir mi

Ya beni unutan bu şehir, bu şehre ne demeli

Boğuluyorum yokluğun içinde, yok oluyorum

Kaçışım matadorun rüyasından daha kabus

Bu masa kilit noktası sanki

Bir şeyler, buralarda kalmıştı o akşam

Kalabalığın yalnızlık sisiyle çevrili masada

O gün bir kuş gagasında bir kırıntı

Asıl olan unutulanın kırgınlığı kanat sesinde

Yüzümde siyahın en masum hali

Gözlerinde parlayan kinle kalmak

Artık eski gülüşler, camgöbeği gözler solgun

Masum dokunuşlar, fısıltılarda kalan sözler

Bir masalın anlatılışı kadar yalan

Bir yaşam kadar gerçek bitenler

Ruhumdaki yorgunluk hüsran yumağı

Çözdükçe körelir

Anlıyorum şimdi çektiğim isimsizliği

Unutmayı, unutulmayı, ne fark eder

Artık unutulmayı unutmak istiyorum.', 'Ayaklarım terk edilmiş bu masaya getirdi beni Karşımda duran sandalye sahipsiz Sahipsiz görünse de sahiplenen çok Gel otur der’cesine sitemk...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/unutmayi-unutmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardahan (Kars)', 'ardahan-kars-aysel-coban-qyuq9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir zemheri ayında doğdum yer Ardahan

Özüm sen de kaldı, bende de senden izler var

Çıldır gölünde balık solungacında oksijenim

Ani harabelerinde tarihten fırlamış canlı tanık gibiyim

Tarihin öyle eski, nice milletler geldi geçti

Olup bitenleri en kuytu yerlerden izleyen çakıl taşıyım.

Uğruna Sarıkamış’ta ölen doksan bir askerden her biriyim

Tarlaları yeşile boyayan Kura Nehrinin kollarındanım

Yaylalarda rengarenk çiçeklere konan arılardan biriyim

Sevdiğine en güzel balları sunan o beşlik güzelim

Dağ çiçeği kokan yamaçlarda dolaşan çobanlardanım

Kavalımla yanık türküleri dile getiren benim

Çam ağaçlarında birer kozalak

Kozalaklarla oynayan yaramaz sincabım ben

Yayla evlerinde, güneş ışığı sızan duvarlarında bir toz parçasıyım

O duvarları oluşturan, çok şeye tanık olmuş her taştan biriyim

Eski kaşar peyniri gibi kıymetli

Örgü peynirinde tel telim ben

Atını tımar eden her seyisten biriyim

Ketesinde, Hengelinde, el emeğinde damak tadıyım

Kadınların yüreğinde, geçmişim yükünde bir çizgi

Tülbentlerinde mavi boncuklu oyayım ben

Bir bardak çayında kıtlamalık şekerim

Tarlalarda yetişmeye atılmış buğday tanesiyim

Nice aşıklar çıktı bağrından

Seni anlatmak için yazarlar yetişti peşi sıra

Dağlarını karış karış tanıyan dağcılar büyüttün

Seni anlamak için senin yaşamak gerek

Özüm sende kaldı ARDAHAN', 'Bir zemheri ayında doğdum yer Ardahan Özüm sen de kaldı, bende de senden izler var Çıldır gölünde balık solungacında oksijenim Ani harabeler...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ardahan-kars-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Sevdam', 'mavi-sevdam-sema-aka-cu8ay', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimdeki derin sevda benim mavi sevdam

Sürüklüyor beni ardı sıra

Kanım mavi akıyor, kalbim mavi çarpıyor

Sen yanımdayken saatler mavide kalıyor

Mavi umutlar sundun bana

Ve yine mavi mutluluklar

Seninle sevdim tüm renkleri

Ama gözlerinde ki maviyi bir başka

Söylenen şarkı mavi, okunan şiir mavi

Mavi sevda sardı tüm benliğimi

Ellerin, gözlerin, sözlerin

Mavi düşlere sürüklüyor sevgimi

Maviler kervanına katıldım gidiyorum

Okyanus mavisinden koyu bir sevda

Gelip geçici bir mavilik değil yaşanan

Ölümüne sürecek bir mavilik benim ki

Gökyüzünün gri mavisi

Yıldızlarla çiziyor bana hayalini

Kayan her yıldızla mavi bir dilek

Elbet bu mavilik seni bana getirecek

Ve sonrasındaki mavi sensizlik, sessizlik

İçimi yakıyor zindan karası mavi geceler

Mavi hayallerle dalmak derin uykulara

Mavi umutlarla uyanmak yeni bir sabaha

14.10.2003', 'İçimdeki derin sevda benim mavi sevdam Sürüklüyor beni ardı sıra Kanım mavi akıyor, kalbim mavi çarpıyor Sen yanımdayken saatler mavide kalı...', ARRAY['Türk Edebiyatı','Şiir','Sema Aka']::text[], 8.5, '{"poet":"Sema Aka","poet_slug":"sema-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mavi-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazan Kimdi?', 'yazan-kimdi-cigdem-yorgancioglu-8pzqj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dudaklarım kurumuştu

Baktım ağzından bal akıyor 

Dudaklarına dokundum 

Bal tutan parmağını yalarmış 

Dudaklarım ıslandı. 

Şiiri söyleyen dudaklarimdi 

Yazan ise bal tutan parmaklarimdi 

(H.Çiğdem Yorgancıoğlu 

Istanbul, Sonbahar sonu 2003)', 'Dudaklarım kurumuştu Baktım ağzından bal akıyor  Dudaklarına dokundum  Bal tutan parmağını yalarmış  Dudaklarım ıslandı.  Şiiri söyleyen dud...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Yorgancıoğlu']::text[], 8.5, '{"poet":"Çiğdem Yorgancıoğlu","poet_slug":"cigdem-yorgancioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yazan-kimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boğaziçi Bahar Peyzajı', 'bogazici-bahar-peyzaji-cigdem-yorgancioglu-prrvp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bütün mevsimler bahar gibi yaşanır 

Boğaziçi''nde.

Bir sabah uyandım, baktım bahar 

takıp şapkamı, vurup sırtıma çantamı 

Bir balıkçı kasabasına gider gibi 

O anda çiziverdim yolumu 

istikamet yüksek öğrenim kurumu 

Uzanıverdim Boğaziçi Üniversitesine 

Yürüyordum belki 

Bahara yada nostalji penceresine 

Yıldızların konumu uygun 

Susarak mümkün mü yaşadıklarımın 

yüreğime ulaşmak için, size uğramadan 

Boğazımdan geçmesine.. 

Bahar kompozisyonu var bazı mekanların 

Görmesini yaşamasını bilene. 

Bütün mevsimler bahar gibi yaşanır 

Boğaziçi''nde.

Görmeden daha dekoratif sesleri 

Ve duymadan sanki bahara iltifat için 

en güzel sesleri ile öten 

Kuş seslerini, 

Girer girmez Güney kampüsün

Hisar kapısından içeri, 

Mezun ve şapkalı kadının biri, 

Vizörden izler iken, zihnindeki görüntüleri 

Aldı kalemi eline, düzyazıdan çıkarıp baharı 

seçiyor dizeleri.

Kelimelerle kıpırdatmak an''ı, medâr-ı iftiharı. 

Bahar gelmiş gelmesine.. gelmiş te 

Bütün mevsimler bahar gibi yaşanır 

Boğaziçi''nde.

Bahar dile aktarılmak istediğindendir belkide 

Ondandır..kesin.. bu göz ve söz oyunları.

Objektif -odak uzaklığı çoktan ayarlanmış 

İstiyorki sözlerde baştan çıkarsın baharı 

Peteğin önünden geçiyordum az önce 

Burnuna konmuşken kelebek, vızıldarken arı.

Steplerin önünden geçen adımlarım için 

Geri kaçmak ne mümkün, adımlar hep ileri 

Terakki bana babamın ve okullarımın yadigarı 

Üstelik zaman girince araya, artıyor değeri 

Nasıldı kırmıızı salon önünde kayıt kuyrukları 

Görüyorum orta sahada koşan topu ve oyuncuları 

Konuşuluyordu bir ara orta kantindeki 

Sinop’lu Kazım’ın ıspanaklı tostu ve kaşarı 

Vakit akşam üzeri 

Hormonları değişmiş baharın 

Değişim ise her şeyin mimarı 

Erguvan ağaçları ve pembe çiçekleri 

Baharın giydiği en güzel elbiseleri 

Örtülüyor ağacın bütün basenleri 

Görünce görkemli kompozisyonu 

Bir kedi, tiki varmış gibi gözkırpıyor 

Sanki deklanşöre basıyor.

An''ı durdurunca başlıyor gösteri 

Belki de bir şair arıyor sözcükleri 

Sesleri ve anlamdaki değeri 

Bütün mevsimler bahar gibi yaşanır 

Boğaziçi''nde 

Ne yaşarsanız parlak kalır zihninizde 

Güneşe dönüktür aşıkların yüzleri 

Aşklar da, baharlarda şiir gibidir. 

Bütün mevsimler bahar gibi yaşanır 

Boğaziçi''nde 

Zihnim zamana, bedenim çimene yayılır 

Bir belgesel çeker gibi anılara kurulup 

Sincaplar finallere hazırlananları, 

Gözlerim ise sincapları seyreder 

Bütün mevsimler bahar gibi yaşanır 

Boğaziçi''nde 

Gelen yeni çifte yer verir içimdeki centilmen 

Körpeliklerine rağmen 

Orası onlara aittir, tıpkı benim orayı 

mekanım yapıp yağlı boya tablolarımı yaydığım

zamanlar sahiplendiğim gibi 

Bakıyorum aşkları biraz grekoromen 

Ayağı kalkınca baktım 

Topuklarıma yapışmış çimen 

Bütün mevsimler bahar gibi yaşanır 

Boğaziçi''nde 

Anımsıyorum yıldızlı bahar gecelerinde 

Kenedy partilerini ve tatlı dokunuşları 

Anımsıyorum 90 larda Kablo estetiği diye

kazılıp köstebek yoluna çevirilen 

Albert Long Hall ile Hamlin Hall un önünü.

Üzerinden hiç inmek istemediğim 

ağacın önünden geçiyorum 

Daha da kalınlaşmış beli. 

Manzaraya yaklaşınca göruyorum 

Banka oturmus genclerin arkasındaki 

Fatih''in imzasını attığı surları 

Çalkalanan Marmara denizi 

Buhar olup gökyüzüne asılmış, 

Anımsıyorum 

Buluta takılmış anıları ve sorulmamış soruları 

Ve nereye dökulecekti, icimdeki yagmurun suları 

Dürbünle bakınca görüyorum boğazdaki yalıları 

Bütün mevsimler bahar gibi yaşanır 

Boğaziçi''nde 

Hatırlıyorum....... 

Fatih koprusunun açılışında temelinin atıldığı günleri 

Bu ne muhteşem bir alan derinliği 

Görüyorum bu derinliğe 

ayın ondordü gibi kurulmuş okulumu 

Öğretmenlerinin ve Öğrencilerinin 

Eğitim görürken bir doğa yürüyüşü ifadesi var 

Sanki yüzlerinde 

Ne yaparsanız yapın 

Hiç bir şeyi kadrajın dışında bırakamazsınız 

Buradan uzaklaşırken.. 

Kıpırdatırken rüzgar ince dalları 

Uzaklaşmıyor çiğdem çiçeğine bal yapmadan 

Az önce etrafımda vızıldanan arı 

Steplerin önünden geçiyorum yine 

Mezuniyet törenimin yapıldığı, 

Spor bayramı kapanışlarında heyecanlandığım 

sevgilinizi öptüğünüzde marjinal fayda artar diyen 

sevgili hocamız Dimitriyadis''i bir bahar günü 

acı bir nisan şakası ile son yolculuğuna uğurladığım 

Steplerin önünden geçiyorum. 

Ne bilsin di Demir Hoca yokluğuna dayanamayıp 

Doğu Almanya ve Batı Almanya birleştiği sıralarda 

Karısının da 9 kattan atlayıp 2 sene sonra 

Yanına geleceğini... 

Bahar geldi önce gözlerim 

Sonra ağzım sulandı.gözüm çilekte 

Sözcüklerim anılara izdüşmekte 

Bütün mevsimler bahar gibi yaşanır 

Boğaziçi''nde 

Parmağımı deklanşörden artık çekiyorum 

İlk fotoğraf nasıl çıkacak merak ediyorum. 

Buradan uzaklaşırken.. 

Kıpırdatırken rüzgar ince dalları 

Tası tarağı toplayıp gitsenizde 

Kürkçü dükkanına arasıra tilki olup dönsenizde 

Şehrimin pastoral bir köşesinde 

Bütün mevsimler bahar gibi yaşanır 

Boğaziçi''nde 

Tripod''ua arıyor gözlerim 

Eskiye dair ne varsa özlerim 

Kelimeler birbirinin içinde 

Nakaratların hepsi birbirinin peşinde 

Bütün mevsimler bahar gibi yaşanır 

Boğaziçi''nde 

(H.Çiğdem YORGANCIOGLU

Boğaziçi Güney Kampüs

Bahar 2003)', 'Bütün mevsimler bahar gibi yaşanır  Boğaziçi''nde. Bir sabah uyandım, baktım bahar  takıp şapkamı, vurup sırtıma çantamı  Bir balıkçı kasabas...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Yorgancıoğlu']::text[], 8.5, '{"poet":"Çiğdem Yorgancıoğlu","poet_slug":"cigdem-yorgancioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":148,"source_url":"https://www.antoloji.com/bogazici-bahar-peyzaji-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Frida''ya ''Abrakadabra ''', 'frida-ya-abrakadabra-cigdem-yorgancioglu-k4o6v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendi gölgesini karaladığı bir anda

Hayatta insanin başina iki kaza gelebilir 

Bir otobüs bir de Rivera 

Biraz gerçek birz sanat biraz palavra 

Geriye en sonunda kalacak olan 

Eserler, söylentiler ve bir de kadavra, 

Diken üzerinde otururken yada ayakta 

Yaratan yasayan ve hisseden 

Sirtini hiç duvara dayamamis bir kadina 

Gerisi palavra 

Nasıl olsa yasami bir mucize 

yada ABRAKADABRA 

10.04.2003-Istanbul Kozyatağı gece', 'Kendi gölgesini karaladığı bir anda Hayatta insanin başina iki kaza gelebilir  Bir otobüs bir de Rivera  Biraz gerçek birz sanat biraz palav...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Yorgancıoğlu']::text[], 8.5, '{"poet":"Çiğdem Yorgancıoğlu","poet_slug":"cigdem-yorgancioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/frida-ya-abrakadabra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle', 'gule-gule-esma-ozdemir-8hnaz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kucak gülle

En sıcak günde

Tatlı bir dille

Girdin gönlüme.

Bir gülüşünle

Bir sevişinle

Bir bakışınla

Doldun kalbime.

Koynumda saklı

Bir kucak gülle

Bir buselik yola

Gel, sağlık ile de

Git, güle güle!', 'Bir kucak gülle En sıcak günde Tatlı bir dille Girdin gönlüme. Bir gülüşünle Bir sevişinle Bir bakışınla Doldun kalbime. Koynumda saklı Bir ...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gule-gule-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta''ya... Çırakça', 'usta-ya-cirakca-hatice-ari-0rz0m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Usta''dan sonra ilkmişim, 

Öyle diyorlar; hangi vakitte? 

Kalemin sakınmadan yazdığı, 

Kağıdın çekinmeden düzdüğü, 

Ayıklamalı  kurtları, döküntüleri, 

Alın teri damlatmak içine,

Galeyana getirmek için akıntıları.

Zor olan, dağları aşmak değildir ey kitle; 

Geçmektir düzlüğü, 

Sonunun kuru bir serap olduğunu bile bile..

Zaman eskitir ya onları; 

Ayakta tutmak zordur yıkıntıları, 

Benim içimde parça parça sevda ekintileri, 

Sızlar inceden, ikindileri

Ve gönül Tanrısına der ki:

Bilseydim, bu koca yürek, 

Ne akıntılarla durulur, 

Ne kırıntılarla avunur, 

Ne de şöyle usul usul dalında durur; 

Kuş gibi, serçe bakışlı, 

Söyle diyorum, 

Hangi ahitte

Şeytan da yücedir melekler gibi? 

Şüphe yok, 

Daha iyi anlardın o vakitte, 

Sen de benim gibi sevebilseydin 

Ey Tanrı; 

Sen de benim gibi yüce..

Saç diplerindeki ağartı, 

Sol böğründeki o sancı

Ve inancı, 

Sonsuz inancı

Bitene dek; 

Rüzgarda ses gibi, 

Derinden bir nefes gibi, 

Ah, hiç bitmeyen bir es gibi; 

O vakit anlardın halden elbet..

Usta''dan sonra ilkmişim; 

Kalemin, kağıdın ve sözün, 

Alemin, ağıdın ve özün

Soylu sahipleri! 

Zaman ve mekanla sınırlı değiliz, 

Ustam ve biz; 

Ne gerçekler yoğurduk yufka hayalden, 

Halkalanmaz o ipler boğazımıza; 

İpler, sahipler

Köleliği simgeler; 

Kula köleliği.

Yaşatmayız itleri, bitleri.

Sütü bozuk tipleri! 

Benim içimdeki çocuk, 

Gece demez, gündüz demez

Hep düş kurar; 

Bir kuş, konar yüreğimin tırabzanına

Kuş durmadan şarkı söyler, 

Naralar atar:

''''Katar var gök yüzünde katar, 

Katara, katar katacağız; 

Katarın rengi dönsün

Maviye, yeşile, ala; 

Siyahı atacağız, atacağız! ''''', 'Usta''dan sonra ilkmişim,  Öyle diyorlar; hangi vakitte?  Kalemin sakınmadan yazdığı,  Kağıdın çekinmeden düzdüğü,  Ayıklamalı  kurtları, dök...', ARRAY['Türk Edebiyatı','Şiir','Hatice Arı']::text[], 8.5, '{"poet":"Hatice Arı","poet_slug":"hatice-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/usta-ya-cirakca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiromansi (1)', 'siromansi-1-cigdem-yorgancioglu-30a9p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aynı fallardaki gibi yüreğimi hoplattım, 

El falı deyip, ellerine bakmayasın diye

Meyveli ellerimi yıkayıp, sana elimi açtım

Sonra, taşlarımı avuçlarından aldım

Gene kelimelerimle bir geceyi abarttım

Gecenin yakasına bir çiçek taktım, 

Sözcüklerde gurur ile kibiri kabarttım

Sen eski resimlere, ben senin ayaklarına baktım

Gizlenerek ve bilmeden ben o gece sana aktım

Seni ilk bildiğim gün olduğu için

Işığın etrafındaki pervaneyi sana ve bana hatırlattım

Sana Velasquez’in La Meninas tablosunu anlattım

Sen gidince kapıyı arkandan sıkıca kapattım

Ellerimi kendime uzattım ve açtım

Avuucumdaki çizgilere bir daha baktım.

Ardından da kendimi başka bir şehre attım.

Doludizgin gidiverdim

Ben sanki, 

Babanın ormanlarından kaçan bir attım.

Ceylan ise pınara çoktan inmişti

25-26/07/2003', 'Aynı fallardaki gibi yüreğimi hoplattım,  El falı deyip, ellerine bakmayasın diye Meyveli ellerimi yıkayıp, sana elimi açtım Sonra, taşlarım...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Yorgancıoğlu']::text[], 8.5, '{"poet":"Çiğdem Yorgancıoğlu","poet_slug":"cigdem-yorgancioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/siromansi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Bir Hal', 'siyah-bir-hal-naime-erlacin-hxtvp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çöl bir yalnızlık

buz bir duygu 

çarpıştılar

devasa bir girdap doğdu

kainatı içine düşürdüm

kayboldu

ben yokum! 

yaşamayı yadsımak bu

simsiyah bir hal

tuhaf bir vazgeçmişlik

bilerek bırakmak kirlenmiş dünyayı 

tutunulan son dalı 

sonuncu uykuya doğru

benimle gel hüznüm

çıkalım yola bitsin artık

yokum ben

savaşmayı yadsımak bu! 

(14 Ekim 2003)', 'çöl bir yalnızlık buz bir duygu  çarpıştılar devasa bir girdap doğdu kainatı içine düşürdüm kayboldu ben yokum!  yaşamayı yadsımak bu simsiy...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/siyah-bir-hal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Esmere Kul Oldum', 'bir-esmere-kul-oldum-bekir-gedikoglu-wbhk0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir esmere kul oldum

Kapısından kovuldum

Ben ne umut beklerken

Deryalarda boğuldum

Ben bu aşkın yüzünden 

Düştüm gurbet  ellere

Yandım Allahım yandım

Gönlümdeki ateşe

Sevdalık çeke çeke

Eriyip gideceğim

O yari alamasam

Öldüm Allahım öldüm

Düştüm  sevda  çölüne

Mecnun  gibi  yanarım

Cehennem  ateşi  ne  ki

Gelip  beni  kurtarın

Aşk divanı toplandı

Kararını verecek

Allah  yazdıysa  bana

O yar  bana  gelecek', 'Bir esmere kul oldum Kapısından kovuldum Ben ne umut beklerken Deryalarda boğuldum Ben bu aşkın yüzünden  Düştüm gurbet  ellere Yandım Allah...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-esmere-kul-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-sema-aka-hz0bq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne göklere çıkacak kadar masum

Ne yaşadıklarımdan pişman

Ne de mutluyum

Sırlar içinde bir dünyam var

Bir sen varsın içimde

Ne seni kaybedecek kadar cesur

Ne de kazanacak kadar güçlüyüm

Kazandıklarımla yetinmeyi bilen ben

Kaybettikçe değer kazanan sen

Seni tam bulduğumda ise

Kaçıp giden oldun hep sen...

14.10.2003', 'Ne göklere çıkacak kadar masum Ne yaşadıklarımdan pişman Ne de mutluyum Sırlar içinde bir dünyam var Bir sen varsın içimde Ne seni kaybedece...', ARRAY['Türk Edebiyatı','Şiir','Sema Aka']::text[], 8.5, '{"poet":"Sema Aka","poet_slug":"sema-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sitem-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkıntı', 'yikinti-sema-aka-242gb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her yere baktığımda sen

Gözlerimi kapattığımda, yok olup giden 

Uyandığımda bir rüyaymış dedirten sen

Neden girdin hayatıma böyle derinden

Çık git artık yüreğimden

Sana yer yok artık bu mahallede

Çünkü artık bu mahalle

Yerle bir oldu o depremde

Sen gittin ya…

Artık gözyaşlarım akmayacak

Güneş bir başka parlayacak

Sana inat gün yeniden doğacak

14.10.2003', 'Her yere baktığımda sen Gözlerimi kapattığımda, yok olup giden  Uyandığımda bir rüyaymış dedirten sen Neden girdin hayatıma böyle derinden Ç...', ARRAY['Türk Edebiyatı','Şiir','Sema Aka']::text[], 8.5, '{"poet":"Sema Aka","poet_slug":"sema-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yikinti-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşarsam Onun İçin', 'yasarsam-onun-i-cin-murat-demir-l3f1u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ona yan bakan gözler

Beni hiç unutmasın

Ondan uzak olsamda

Öldüğümü sanmasın 

Benim ilk göz ağrımı

Başkaları alamaz

Ölümüne sevmişim

Onu kimse saramaz

Eyer onu kaybetsem

Başka kimim kalırki

Acıma can dayanmaz

Öyle bir yanarımki

O yanımda oldukça

Hiç taşımam aynayı

Alev topu ederim

Onun için dünyayı

Cümle için iyisi

Devi uyandırmayın

Yaraya tuz basıpta 

Yerinden kaldırmayın

Sizin olsun bu alem

Bana hiç aldırmayın

Ben seven bir garibim

Yeterki saldırmayın

Dünya sizin o benim

Başka bir şey istemem

Yaşarsam onun için

Kimseye sensin demem

		Murat Demir', 'Ona yan bakan gözler Beni hiç unutmasın Ondan uzak olsamda Öldüğümü sanmasın  Benim ilk göz ağrımı Başkaları alamaz Ölümüne sevmişim Onu kim...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yasarsam-onun-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istiyorum', 'istiyorum-sair-ozlem-qir9t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir seyler yapmak istiyorum bugün.

Ayaklarimi yerden kesecek, beni benden alip bambaska yerlere götürecek bir seyler...

Dokunmak istiyorum bugün yildizlara, takilmak istiyorum kuslarin kanatlarina, 

Söyle bir uzanip rahatlamak bulutlarin üzerinde.

Günes''i, Ay''i kucaklamak, 

Masmavi, dupduru denizleri, okyanuslari içmek bir nefeste

Solumak su havayi öylesine derinden

Çiçeklerin bütün renklerini

Yesilin bütün tonlarini görmek bir anda

Haykirmak istiyorum tüm acilara

Meydan okumak istiyorum kanayan yaralarima

Söyle bir omuz atmak istiyorum esmek isteyen det rüzgarlarima.

Bugün bir seyler yapmak istiyorum...

Sevdiklerim yanimda olsun istiyorum bugün.

Güzelliklerin tümünü yasamak istiyorum.

Okumak istiyorum her kelimesini, her hecesini gözlerin.

Anlamak beyinlerdeki firtinalari

Yasamak beraberce mutlulugu ve hüznü.

Dalarken gözlerim ufuklara

Yasarken huzurun doruklar&yacute; nda

Gezerken adim adim  her köseyi, her caddeyi

Hissetmek istiyorum en güzeli, en safi...

Gecenin karanligini, gündüzün aydinligini seviyorum.

Seviyorum akasya kokusunu

Seviyorum yesili, maviyi, pembeyi...

Bülbülün ötüsünü, 

Insanlarin gülümseyisini seviyorum.

Bir seyler yapmak istiyorum bugün 

Bugün Mutlu Olmuk Istiyorum... 

          

(Erzincan 14 Ekim 2003)', 'Bir seyler yapmak istiyorum bugün. Ayaklarimi yerden kesecek, beni benden alip bambaska yerlere götürecek bir seyler... Dokunmak istiyorum b...', ARRAY['Türk Edebiyatı','Şiir','Şair Özlem']::text[], 8.5, '{"poet":"Şair Özlem","poet_slug":"sair-ozlem","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/istiyorum-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam ağlıyor', 'sevdam-agliyor-hicabi-ceylan-28rih', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakmayın ağaran saçlarıma

Yüzümdeki derin çizgilere

ve de gözümdeki yaşlara

Onlar, 

Senelerin yorgunluğunu taşıyor

Zannetmeyinki ağlıyorum

Ben değil içimdeki sevdam ağlıyor

Senelerce herkesten gizlemişim

Nasılda kalbimde saklamışım

Öyle büyükki benim sevdam

Onlar, 

Yılların hatıralarını taşıyor

Zannetmeyinki ağlıyorum

Ben değil içimdeki sevdam ağlıyor

Güneş dağların arkasına gizlerken kendini

Geceler debreştirir azdırır dertlerimi

İşte o zaman yorgun hissederim bedenimi

Onlar, 

Geçmişin izlerini taşıyor

Zannetmeyinki ağlıyorum

Ben değil içimdeki sevdam ağlıyor

Hicabi Ceylan', 'Bakmayın ağaran saçlarıma Yüzümdeki derin çizgilere ve de gözümdeki yaşlara Onlar,  Senelerin yorgunluğunu taşıyor Zannetmeyinki ağlıyorum B...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevdam-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Dipnotları', 'yalnizligin-dipnotlari-bulent-ahmet-alp-z53dh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün anladım...

İki kişilik değil tek kişilik yaşadığımı...

Kalabalıklardan kaçıp, kimsesizliğe sığındığımı...

Tek kişilik yaşamaya alıştım.

Yaşadığımı kimse bilmesin istiyorum...

Kalabalıklarda insanları seyrediyorum

Ve her an bozulmaya hazır psikolojim 

Kırılıyor inceldiği yerden...

Kimsesiz yerlerde kimse yok çünkü.

Kalabalıklarda yek başına olmak, 

Oturmak biryerlerde...nasıl birşeydir 

çok iyi biliyorum...

Maalesef buraya da insanlar gelmeye başladı...

Kaçıp gitmek istiyorum sessizliklere...

Bugün anladım...

Uzun zamandır yazdıklarımda ''SEN'' kelimesini kullanmadığımı...

Sevmekten, sevilmekten, sensizlikten bahsetmiyorum...

Sessizlikten bahsediyorum...', 'Bugün anladım... İki kişilik değil tek kişilik yaşadığımı... Kalabalıklardan kaçıp, kimsesizliğe sığındığımı... Tek kişilik yaşamaya alıştım...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ahmet Alp']::text[], 8.5, '{"poet":"Bülent Ahmet Alp","poet_slug":"bulent-ahmet-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yalnizligin-dipnotlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanamazmıyım', 'dayanamazmiyim-hicabi-ceylan-t0rcs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey içimdeki sevdam

Seni terkedecek kadar korkakmıyım ben

Dayanamazmıyım sanıyorsun

Çekemezmiyim bu acıyı

Hayır bırakmam seni

Asıl ben sensizliğe dayanamam

Çok yalnız hissederim kendimi

Dünya başıma yıkılsa

İçimde depremler olsa

Yine terketmem seni

Seni terk edecek kadar korkakmıyım ben

Sen olmasan yaşayamam

Kurur göz pınarlarım ağlayamam

Dayanamazmıyım sanıyorsun

Merak etme sen

Her acıya olduğu gibi

Bu acıyada dayanırım ben

Hicabi Ceylan', 'Ey içimdeki sevdam Seni terkedecek kadar korkakmıyım ben Dayanamazmıyım sanıyorsun Çekemezmiyim bu acıyı Hayır bırakmam seni Asıl ben sensiz...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dayanamazmiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salıncak', 'salincak-abdulkadir-karaman-jslxd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bindirdiler, elimden tutup bir salıncağa

Zannettim ki, kavuştum; şefkatli bir kucağa! 

Çocuklar gibi zevkle dolu sallanıyorum…

Bakışlar çevrilince, mahcup, utanıyorum! 

Kapatıp gözlerimi hayallere girdikçe

Uçuyor sanıyorum başımda birkaç serçe.

Kim bilir, belki başım değiyor bulutlara? 

Bahar gibi coşkulu içimdeki manzara.

Zincirlerden boşalmış gibi hoş duygularım

Dağıldıkça içimden, çökelmiş kaygılarım.

Yalnız gülmek, oynamak geçiyor hep içimden

Heyecanla dopdolu, korkmadan hiç kimseden! 

Doğrusu tatmak gerek yoğrulduğum bu hissi

Kelimeler yetersiz, yaşamak en iyisi.

Fevkalade, kapılmak bâzen bu duygulara

Vermek her türlü derde, sıkıntılara ara.

Filimmiş gibi hayat, hatırat renkten renge

Kaptırmalı kendini insan bu hoş âhenge.

Uçar gibi git, git gel, târif edilmez âhenk

Görülmemiş böyle zevk, sevinç bahçelerine denk! 

Gönül dolusu sevinç, göz dolusu hayaller

El ele tutmak için sevgi dağıtan eller.

Her şeyi ile yoksa, ruhumda çocukluğum

Aramayın, sormayın; o zaman ben de yoğum! 

Eğer olsaydı hayat, küçücük bir salıncak

Ondan yalnız binenler zevk alırlardı ancak! 

Oysa hayat ayrılmaz, parçalanamaz bir bütün

Anlıyor insan, bâzı şeyleri kaybettiği gün! 

Gülmek-ağlamak; sevmek-nefret, hep iç içe

Mutluluk, katlanmakla mümkün gözükür, hiçe.

Arayan, mutluluğa er geç erişecek yol; 

Yokluğa kavuşmayı cesurca dene bol bol! 

Yüceliği kendinden bilme Yaratan’dan bil! 

Gayriye rağbet etme; yalnız, tek O’na eğil! 

Ruhum bugün gezindi hayli hayallerinde

Uyanınca hiçbir şey bulamadı elinde.

1994 Kastamonu', 'Bindirdiler, elimden tutup bir salıncağa Zannettim ki, kavuştum; şefkatli bir kucağa!  Çocuklar gibi zevkle dolu sallanıyorum… Bakışlar çevr...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/salincak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-tuncay-emrem-qketm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yağmurları beklemişim, yağmamış..

bulutlardan bıkmışım.

çiçekleri özlemişim, açmamış..

bahçelerden bıkmışım.

bana gülen bir aşina çehre yok! 

aynalardan bıkmışım..

günler var ki, bekliyorum yolunu..

takvimlerden bıkmışım.

yıllar yılı kaçıyorum kendimden..

ve gölgemden bıkmışım..', 'yağmurları beklemişim, yağmamış.. bulutlardan bıkmışım. çiçekleri özlemişim, açmamış.. bahçelerden bıkmışım. bana gülen bir aşina çehre yok!...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bekleyis-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Köyüne.', 'don-koyune-suleyman-saylan-23h0k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'DÖN  KÖYÜNE.

Sana ne be birader, 

Üstüne farz mı senin? 

Kirletmişlerse doğayı...

En küçük bir acı, 

Burukluk kırıntısı duymuyorsa kirletenler, 

Sorun etmiyorsa, 

Sorumsuzluklarının utancını taşımıyorsa; 

Sana ne oluyor, 

Sen kim oluyorsun da

Acıyorsun doğaya? 

Sana ne oğlum; 

Boşanmışsa kocalar, 

Boşanmışsa kadınlar, 

Esrarcı, 

Tinerci, 

Dengesiz, 

Hatta satanist olmuşsa çocuklar...

Her gün artıyorsa; 

Sorunlarından kaçıp, 

Unuturum sanan, 

Meyhane kapatan zavallılar...

Bunlara acımak, 

Olanlara üzülmek hakkını kim verdi sana? 

Bırak enayilik etmeyi; 

“Bal tutan parmağını yalasın”, 

Ya da

Götürsün balın tamamını, 

Birileri bir gecede yesin

Birilerinin yıllık nafakasını, 

Birileri çok sevsin kumarı

Bir gecede kaybetsin milyonlarca doları, 

Trafik düzeni dayanmasın aşklarına, 

Biri çıkmadan biri girsin koyunlarına,,,    

Bırak; “bal alan pekmez satsın”, 

Bırak; “iki karısı olan yalnız yatsın”, 

Bırak; isteyen kumarda batsın, 

İsteyen dört kadın alsın.

Boşver aptallık etmeyi de

Bak gününe, 

Hiçbir şey bilmiyorsan

Kur sen de bir tarikat; 

Götür paraları, karıları, 

Farketmesin Leyla, Süheyla, Fadime, 

Sıkışırsan “imam nikahı kıydım.” de.

Sen misin dünyanın delisi, 

Enayisi, 

Kerizi? 

Yok; Cansu’nun oğlu askerlik yapmamış, 

Yok; Bakırel’in yeğeni hayali ihracat yapmış, 

Yok; milletin parası hortuma tutulup

Bankerlerde, bankalarda batmış, 

Yok; hükümetler memuruna kazık atmış...

Almış – satmış, 

Vermiş – almış, 

Yatmış – kalkmış, 

Yemiş – içmiş, 

Çalmış – çırpmış...

İşin mi yok senin yahu? 

Sana ne “elalemin üç oğlak, beş keçisinden”? 

Muhtar mısın be kardeşim? 

Ahmet yirmi yıldır çalışırmış, 

İki fakülte bitirmiş, 

Deneyimliymiş, 

İşi iyi bilirmiş

Ama, 

Bir bok bile olamamış...    

Salaklık etme, 

Partisi yoksa olmaz tabii, 

Üstelik de erkek...

Takma kafanı Serap’a, 

İş o kadar ucuz değil; 

Serap’ın partisi var, 

Fındığı, fıstığı, cevizi var...

Hak etmedi deme, 

Fazlasıyla hak etti, 

Deneyimsiz deme, 

Nasıl olsa öğrenir deneye deneye.

Lise mezunu deme, 

Şükret

Ortaokul mezunu olmadığına (!) 

Karışma başkalarının işine, 

Uy sen de bu gündelikçilere, 

Bak düzenine..

Akıllı mısın, deli mi? 

Şaban mısın, Veli mi? 

Bu kafayla bir yere varamadın

Dünyaya geldiğinden beri, 

Böyle gidersen eğer; 

Senden bir “bok” olmaz ezeli...

Ağlamak boşuna, 

Üzülmek nafile, 

Bizden bu kadar.

Beğenmiyorsan

Dön köyüne.

Süleyman SAYLAN

(Ankara,28 – 29.01.2002, Saat: 11.50 – 00.25) 

(Süleyman Saylan imzalı bütün şiirlerin tüm hakları 

kendisine ve varislerine aittir.)', 'DÖN  KÖYÜNE. Sana ne be birader,  Üstüne farz mı senin?  Kirletmişlerse doğayı... En küçük bir acı,  Burukluk kırıntısı duymuyorsa kirletenl...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/don-koyune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalandan Gerçeğe', 'yalandan-gercege-meral-balci-tanis-uqy0x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle öpüşmek vardı

Elele, yürek yüreğe, 

Seninle yürümek vardı, 

Enginlerden derinler; 

Ve, 

Bir kuşun kanadında, 

Dudaktan kalbe.

Yaprak kadar yeşil, 

Çiğ tanesi kadar sıcak; 

Ve, 

Öpüşmek vardı

Sen kadar yalan, 

Ben kadar gerçek. 

Sonra bir yolculuk başlardı, 

Yalandan gerçeğe uzanan.

Sahi, 

Yalan olan mıydı geride kalan

Yoksa giden miydi gerçek olan.

Ekim 2003', 'Seninle öpüşmek vardı Elele, yürek yüreğe,  Seninle yürümek vardı,  Enginlerden derinler;  Ve,  Bir kuşun kanadında,  Dudaktan kalbe. Yaprak...', ARRAY['Türk Edebiyatı','Şiir','Meral Balcı Tanış']::text[], 8.5, '{"poet":"Meral Balcı Tanış","poet_slug":"meral-balci-tanis","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yalandan-gercege-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığınma', 'siginma-ali-dikili-8eymf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I.

Şehir

biriktirir biriktirir de

çiğner çiğner de

salar salar

kusmuğunu üzerime, 

hak edecek çok şey yaptım:

en posası çıkmış 

sövgüleri...

yergileri...

II.

İşte ben bir adamım 

kendi hapishanesini kuran

aşk kapanmışlığınca

boyası akan

resimlerden hüznüne kaçan.

Bakışlarım

acılarımın yazgıma

teğet geçeceği günlere ayarlı

ki yazgım

başka mazilerden çalınmamıştır.

III.

Modern gülüşler kalbimde iğreti bir tat bırakırken, 

acılarım uçuran gözlerine yenik düşerken, 

uçurum gözlerin beni hiçlikten tutarken, 

yazgımla neden saklambaç oynarım? 

Sürsün bir süre sürgünler, 

sürünedursun gülüşlerden süzülen hüzün, 

sensizlik en iflah etmez zulümdür, 

sürsün bir süre sürgünler.

IV.

Yaşamak ağrısı devam ediyor, 

yok hayata iman etmeyeceğim işte.

Ve

mısralarımı kuşandım

sığındım ürkerek sevdana, 

şimdi sen

tutkularımı kuşanıp

en zırhlı cibinliğim olacaksın.

ikibinüçyılınınekimayınınüçüncügünücumaonüçakrepdörtyelkovan, antalya', 'I. Şehir biriktirir biriktirir de çiğner çiğner de salar salar kusmuğunu üzerime,  hak edecek çok şey yaptım: en posası çıkmış  sövgüleri......', ARRAY['Türk Edebiyatı','Şiir','Ali Dikili']::text[], 8.5, '{"poet":"Ali Dikili","poet_slug":"ali-dikili","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/siginma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulur', 'unutulur-erkan-uyar-g1cb1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutulur ne varsa aşka dair

Beni yakan o gözler unutulur

Ne aşık kalır dünyada ne şair

Çok yeminler çok sözler unutulur

Sen değilsin giden düştür engine

Davul bile vurur dengi dengine

Aldanma talihin pembe rengine

Nice dilberler yüzler unutulur

Bir gün gelir dilimden düşer ismin

Yığınların altında kalır cismin

Albüme hatıra olur her resmin

Senden geriye izler unutulur', 'Unutulur ne varsa aşka dair Beni yakan o gözler unutulur Ne aşık kalır dünyada ne şair Çok yeminler çok sözler unutulur Sen değilsin giden d...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uyar']::text[], 8.5, '{"poet":"Erkan Uyar","poet_slug":"erkan-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutulur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prizma Lütfen', 'prizma-lutfen-halim-yazici-a3s6r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'adam meyhanedeydi

garsonu çağırdı

- yakamoz lütfen

suya koydu adam kalbini sonra

uçurumun kenarında iki prizma

garson geldi

-saat bin çeşit ışık yılı -

- yakamoz kalmadı

   prizma vereyim

garsonun elleri allegro

garson elleriyle yaşama sevinci

koyar tepsiye

adam bir dikişte içer

dışarda olağan ayyaş bir sabahı yaşayan İstanbul

nedir anlamı 

bir şehir terkedilirken 

bir insanın terkedilmesi

diye düşündü adam

bir anlam veremedi 

elleri allegro garson

bir anlam veremedi 

neredeyse kayıp giden 

yaşama sevincine adamın ellerinden

adam meyhanedeydi Denizli''de

kadınsa yedi memeli şehirde

tekrar fısıldadı adam

eğilerek kulağına garsonun

- prizma lütfen.', 'adam meyhanedeydi garsonu çağırdı - yakamoz lütfen suya koydu adam kalbini sonra uçurumun kenarında iki prizma garson geldi -saat bin çeşit ...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/prizma-lutfen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yola Çıkıyorum Anne', 'yola-cikiyorum-anne-halim-yazici-0tvrx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yola çıkıyorum anne

heybem ne güzel

içinde sonsuz katık

-kalbi sevgilimin-

heybem Yağcıbedir

yola çıkıyorum anne

değneğim zeytin dalı

-martının kanadındaki zeytin dalı-

sat sabahın beşi

-serçeler bu saatte çıldırırlar-

hani omzunda nazlı bir gül döner ya insanın

dönüyor çığlıkları kalbimizde serçelerin

dönüyor ''büyük saat''

dönüyor çoğalarak damıttığı

bütün güzel ayrıntıları hayatın

yola çıkıyorum anne

bulutları aralamış gözleri onların

öpüyorum gözlerinden

Nurhan''ın, Mustafa''nın.', 'yola çıkıyorum anne heybem ne güzel içinde sonsuz katık -kalbi sevgilimin- heybem Yağcıbedir yola çıkıyorum anne değneğim zeytin dalı -martı...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yola-cikiyorum-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Dileği', 'ask-dilegi-turgay-kadiroglu-w651t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşk, her can için bir dilek tutar, 

kimse bilmez, tuttuğunu yarına saklar, 

kocaman bir mapustur dünya semahı durmayan

ve içinde aşksız, gönülsüz, 

dileğinden bihaber tutsaklar.', 'aşk, her can için bir dilek tutar,  kimse bilmez, tuttuğunu yarına saklar,  kocaman bir mapustur dünya semahı durmayan ve içinde aşksız, gön...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-dilegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrım Siyah Beyaz Aşıkhava Sineması', 'tanrim-siyah-beyaz-asikhava-sinemasi-halim-yazici-ukhj2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1. izmir vapurunun bacakları kızılten beyaz

    tülden akar üstüne dumanı ölü karanfillerin

    uslu bir çocuk omzu okşar saçlarını körfezin

2. ışıkları sarı gri bir yelkovan kızını kışkırtan zaman

    beyaz yüzlü aydın

    bu yüzden yalnız akşamları açar akşamsefaları

3. akşamüstü kelebek gelecek

    beyaz gazoz ve çekirdek getirecek

    tanrım siyah beyaz aşıkhava sineması.', '1. izmir vapurunun bacakları kızılten beyaz     tülden akar üstüne dumanı ölü karanfillerin     uslu bir çocuk omzu okşar saçlarını körfezin...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tanrim-siyah-beyaz-asikhava-sinemasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlana', 'mevlana-halim-yazici-05rxo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dön ateş yalazında

kendini yak

görmüyor musun

her yer aşk.', 'dön ateş yalazında kendini yak görmüyor musun her yer aşk....', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mevlana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Oku Bana', 'siir-oku-bana-halim-yazici-sme3r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şiir oku bana

uzaktan

kanat sesleri

titretsin kalbimi

şiir oku bana

yürürken

parkta

otobüste

sevişirken

iki kedi

bir bulut

bir çocuğun gözlerinden

geçerken

gözlerinden

şiir oku bana

doğarken

direnirken

kanatları

kanatırken

aydınlığını

kalbimin yalan

şiir oku bana

kitaplarım

deniz kabuklarım

üşürken

düşünürken

ölürken

beyaz bulut

dönüşürken eski

kalbim

üşürken

düşünürken

üşürken

çoğulken

ölürken

yalnızken

evim

yürürken

öz suyu

kalbimin

dağlara

şiir oku

bana.', 'şiir oku bana uzaktan kanat sesleri titretsin kalbimi şiir oku bana yürürken parkta otobüste sevişirken iki kedi bir bulut bir çocuğun gözle...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/siir-oku-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Gözbebeği Kedinin', 'mavi-gozbebegi-kedinin-halim-yazici-s2h5g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eğer bir kuş uçarsa

gece yarısı uçurumlara

          uçurumlardan aşklara

mavi gözbebeği kedinin

dönüşürse birden yalnızlıklara

          yalnızlıklardan aşklara

yağlıboya resimli ellerin

sarsılırsa ihanetlerle kristallerle

          kristallerden aşklara

ve bunları yaşarken kalbim

tutmazsan ellerimi kar damlalarıyla

          kar damlalarıyla aşklara

işte o zaman kırılır incelikler

o zaman kırılır inceliklerden

          uçsuz bucaksız yalnızlıklara.', 'eğer bir kuş uçarsa gece yarısı uçurumlara           uçurumlardan aşklara mavi gözbebeği kedinin dönüşürse birden yalnızlıklara           ya...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mavi-gozbebegi-kedinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Işıkkırıcıyım', 'ben-bir-isikkiriciyim-halim-yazici-sym0d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben bir ışıkkırıcıyım

küçük öykülerim var cebimde

derdim işim budur benim

kanadı kırık hercai menekşe

kekik toplarım kır çiçekleriyle

kağıt helva kar eşliğinde

beyazları toplarım

çocukların ve gözlerinden devlerin

gülümsemem bu yüzden ölürken

serçe parmağına tutunmam

mor tonlarına uçurtmalarımın.', 'ben bir ışıkkırıcıyım küçük öykülerim var cebimde derdim işim budur benim kanadı kırık hercai menekşe kekik toplarım kır çiçekleriyle kağıt ...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ben-bir-isikkiriciyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cancazım', 'cancazim-meral-balci-tanis-9m6w3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Böyle geldik gülüm

Ne yaparsın! ..

Kesiyorlar bizi öyle de, böyle de.

Bu cümle seni de, beni de tanımlar.

Haksızlığı aldık mı? 

Haksızlığa geldik galiba.

Dar bir yola girdik! ..

Tam zamanıydı sanki

Olsun, 

Ölüm yok ya ucunda.

Biz ne badireler atlattık seninle.

Evelallah, 

Bunları da atlatırız, 

Sen varken dünyam da.

Aslında silip süpüreceksin, 

Önünde ne varsa.

Sonrada, 

Çekil köşene.

Seyret olanları.

Dünya değil, 

Cehennem gözüyle.

Ama yapamayız.

Ne sen, ne ben.

Neymiş efendim doğruluk + dürüstlük.

İki ucu kaka değnek.

Kim almış nasibini ki biz alalım.

Sadece yatırım yapıyoruz

Çok uzaklara.

Kestirmeden gidelim dedik, 

Yemedi uzakların sahibi.

''Hak etmediniz bazı şeyleri'' demiştir herhalde.

''Sıranız gelmedi. Sıranızı bekleyin'' demiştir illaki.

İnşallah son sözleri de bunlardır. 

Daha söyleyeceği birşey varsa, kesiliyoruz işte demektir.

Ne o, ne ben, 

Fazla uzatmadan, 

Güzel günlerin şerefine kaldır hayalinde kadehleri; 

Ve de ki; 

Böyle geldik gülüm

Ama; 

Böyle gitmez.

Sonun da bizde güleceğiz, 

En azından sıradaymışız.

Bunada şükür! ..

1999', 'Böyle geldik gülüm Ne yaparsın! .. Kesiyorlar bizi öyle de, böyle de. Bu cümle seni de, beni de tanımlar. Haksızlığı aldık mı?  Haksızlığa g...', ARRAY['Türk Edebiyatı','Şiir','Meral Balcı Tanış']::text[], 8.5, '{"poet":"Meral Balcı Tanış","poet_slug":"meral-balci-tanis","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/cancazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncecik Ay', 'i-ncecik-ay-halim-yazici-pdu5f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'incecik ay, incecik ay

dün akşam sana baktım ağladım

incecik ay, hey incecik ay.', 'incecik ay, incecik ay dün akşam sana baktım ağladım incecik ay, hey incecik ay....', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/incecik-ay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dal Verdi', 'dal-verdi-emin-baydil-mdke0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Barış Manço''ya''

Sormaya gerek yok; hana, hancıya

Aşk kervanı, çoktaaan menzile vardı.

Artık büklüm büklüm değil yollarımız / Dosdoğru, 

Sevgililer buluştu; dağlar, bel verdi.

Dereleri gürül gürül çağladı; bir sen, bir ben

Bu ellerin yazı bitti, kışı geldi erkenden.

Pembe güllerin mahzûn, al güllerin başbaşta, 

Çiçeklerin rengârenk açmış bahçende, işte! 

Çayanlarda bir sükût, çiyanların bin pişman

Cumartesi barıştı, şehit cuma el verdi.

El salladın, eyvallah! 

Hani nerde, bir elveda, eyvallah? 

Sanki dünyam yıkıldı, bir yıldız kaydı eyvah! ..

Gözlerimiz, bir barışa sel verdi, 

Bir ağaçtı; herkese, zeytin dal verdi...', '''Barış Manço''ya'' Sormaya gerek yok; hana, hancıya Aşk kervanı, çoktaaan menzile vardı. Artık büklüm büklüm değil yollarımız / Dosdoğru,  Sev...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dal-verdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal Vapur', 'hoscakal-vapur-halim-yazici-8xj57', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-beyaz bir martı süzülür

               ve günışığı usulcacık dokunur

               teleğine denizin-

kadın arabalı vapurda

gözlerinde köpükleri ihanetin

çaycı çocuk tepside

taşımakta kılcal damarlarını yeni aşkların

...

hoşçakal vapur.', '-beyaz bir martı süzülür                ve günışığı usulcacık dokunur                teleğine denizin- kadın arabalı vapurda gözlerinde köpü...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hoscakal-vapur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karganın gözyaşları', 'karganin-gozyaslari-hanife-efendioglu-ptu9e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kargayı alıp içimden, 

Serbest bıraktım.

