INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin Üstünde Dursun Diye', 'kalbimin-ustunde-dursun-diye-ahmet-ozturk-3tfvi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkı koynuma sakladım

Kimseler görmesin

Kalbimin üstünde dursun diye

