INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şifre', 'sifre-gaffar-karadogan-o0pr7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kınından çıkmamış

Sözlerim var

Çift sarmal DNA yapısında

Çekerim sözlerimi kınından

Orta yerde

Yalnız

Pürin pirimidin ayırımı yapabilenler

Okuyabilir düşüncelerimi', 'Kınından çıkmamış Sözlerim var Çift sarmal DNA yapısında Çekerim sözlerimi kınından Orta yerde Yalnız Pürin pirimidin ayırımı yapabilenler O...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sifre-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hemianopsi', 'hemianopsi-gaffar-karadogan-woga0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Homonim hemianopsinin

Bitemporal olanından olmuşuz

Yaşıyoruz sağlık merkezinde

Görebildik mi? 

Duvardaki Picaso’yu

Picaso’da düşünen adamı

Ne düşünüyor acaba

Kendini mi? 

Yoksa kendinden çok sevdiği

Eşini ve çocuğunu mu? 

Görebildik mi? 

Ali Cengiz oyunlarını

Görebildik mi? 

Sırtında ayak izleri olanları 

Korkarım, gözlerimiz gibi

Düşüncelerimiz de 

Yarım yamalak olacak', 'Homonim hemianopsinin Bitemporal olanından olmuşuz Yaşıyoruz sağlık merkezinde Görebildik mi?  Duvardaki Picaso’yu Picaso’da düşünen adamı N...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hemianopsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Protein', 'protein-gaffar-karadogan-ziblp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün düşüncelerim

Düşlerim ve özlemlerim

Protein yapısında

Bir nöron gövdesinde 

Hepsi bende saklı', 'Bütün düşüncelerim Düşlerim ve özlemlerim Protein yapısında Bir nöron gövdesinde  Hepsi bende saklı...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/protein-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tabaka', 'tabaka-gaffar-karadogan-ciu8n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üç tabakasın sen

Bir endoderm 

Bir mezoderm

Bir ektoderm

Endoderm; miden, bağırsağın

Mezoderm; kemiğin, kasın, vücut örtülerin

Ektoderm; gözün, kulağın, beynin

Endoderm ile yedin, içtin

Mezoderm ile yürüdün, koştun

Ektoderm ile düşündün, sevdin

Adam oldun be 

Gün geldi 

Üç tabakan bir araya geldi

Adam bile olamadın be', 'Üç tabakasın sen Bir endoderm  Bir mezoderm Bir ektoderm Endoderm; miden, bağırsağın Mezoderm; kemiğin, kasın, vücut örtülerin Ektoderm; göz...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tabaka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Remisyon', 'remisyon-gaffar-karadogan-j6taf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Remisyon dedikleri

Fırtına öncesi sessizlik

Başka bir şey değil aslında', 'Remisyon dedikleri Fırtına öncesi sessizlik Başka bir şey değil aslında...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/remisyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lökoz', 'lokoz-gaffar-karadogan-bkumt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Koşun arkadaşlar

Tek tip hücre infiltrasyonu var

Kemik iliğinde

Tek tip demek

Tehlike var demek

Tek tip demek

Yaşam tehlikede demek', 'Koşun arkadaşlar Tek tip hücre infiltrasyonu var Kemik iliğinde Tek tip demek Tehlike var demek Tek tip demek Yaşam tehlikede demek...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/lokoz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizgi', 'cizgi-gaffar-karadogan-iuq5d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlık ile hayvanlık arasında 

İnce bir çizgi var

Dikkat! Yan basmayalım beyler', 'İnsanlık ile hayvanlık arasında  İnce bir çizgi var Dikkat! Yan basmayalım beyler...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/cizgi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiftler', 'ciftler-gaffar-karadogan-0mzxk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani o beynimizin

Her bir yanından çıkan

Kafa çiftleri var ya

Beynimizin püskülleri

Tam oniki çift

Farklı uzunlukta

Çok kafa çiftler', 'Hani o beynimizin Her bir yanından çıkan Kafa çiftleri var ya Beynimizin püskülleri Tam oniki çift Farklı uzunlukta Çok kafa çiftler...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ciftler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kastırma', 'kastirma-gaffar-karadogan-010mz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kastırıyorlar hastaları acil serviste

Başka kliniklere

Kastırmak demek

Hastane lügatında

Hastayı tedavi olamayacağı yere yatırmak demek

Acil kartına türlü sözler yazarlarken 

Gördüm zavallı doktorcukları

‘Yattığı klinikte takip edilecektir’ 

Cümlesinin en popüler olduğu dönemde

Kastırmacılar! 

‘Yattığı Klinik’ diye bir klinik açarsa Cem Çekiç 

İşte o zaman

Yiyeceksiniz naneyi', 'Kastırıyorlar hastaları acil serviste Başka kliniklere Kastırmak demek Hastane lügatında Hastayı tedavi olamayacağı yere yatırmak demek Acil...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kastirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burkitt lenfoma', 'burkitt-lenfoma-gaffar-karadogan-olk2k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir patoloji kesitinde

Çıkarsa karşına

Yıldızlı gök manzarası

Arkadaş! sakın sevinme', 'Bir patoloji kesitinde Çıkarsa karşına Yıldızlı gök manzarası Arkadaş! sakın sevinme...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/burkitt-lenfoma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aforizma', 'aforizma-gaffar-karadogan-h3vb0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Moral agresif insanlar dolaşır olmuş

Hastane koridorlarında

Bilim adamı değil film adamı bunlar

Senaryo, akademik kariyer uğruna

Bir katta sosyal adaletsizlik

Bir başka katta sosyal adalet özlemi

Ve değişen bir aforizma

‘Hastalık yoktur parası olan hastalar vardır’', 'Moral agresif insanlar dolaşır olmuş Hastane koridorlarında Bilim adamı değil film adamı bunlar Senaryo, akademik kariyer uğruna Bir katta s...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aforizma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Astım', 'astim-gaffar-karadogan-h2kua', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey! Yunan şairi Homeros

Soluksuzluğumuzun tarifçisi

Çok şeyler söylediler astım için

Yüzyıllardan beri 

Astım hala eskisi gibi

İçimizi daraltıyor

Yüreğimize yakın bir yerleri

     

Astım kronikmiş Homeros

Kitaplardan bilirim

Bir de gördüğüm hastalardan

Hep sorarlar

Niye daralıyoruz? 

Bu nöbetler neden? 

Sabaha karşı uyanmalar neden? 

     

Dilim döndüğünce cevap veririm

İşte iltihabi hücreler

Ve zehir zemberek salgıları

İşte atopik bünye

İşte tetikçiler

Elleriyle sıkarlar bronş ağacını

Artık bronşlar dardır

Vakitler dar

Dar vakitler yaşarsın 

Sonunda anlarsın

Dolu bir nefesin tadını', 'Hey! Yunan şairi Homeros Soluksuzluğumuzun tarifçisi Çok şeyler söylediler astım için Yüzyıllardan beri  Astım hala eskisi gibi İçimizi dara...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/astim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hız', 'hiz-gaffar-karadogan-tnz82', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gördünüz işte

En agresif tümör bile yetişemedi

Embriyonun bölünme hızına', 'Gördünüz işte En agresif tümör bile yetişemedi Embriyonun bölünme hızına...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/hiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birinci sınıf', 'birinci-sinif-gaffar-karadogan-yeiy2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özel oda isterler

Birinci sınıf hastalar

Özel muamele isterler 

Birinci sınıf hastalar

Üstü kapalı tehdit ederler 

Birinci sınıf hastalar

İnandırıcı bulunur

Birinci sınıf hastalar', 'Özel oda isterler Birinci sınıf hastalar Özel muamele isterler  Birinci sınıf hastalar Üstü kapalı tehdit ederler  Birinci sınıf hastalar İn...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/birinci-sinif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-gaffar-karadogan-ak51y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir arkadaşlık başlamış 

Intrauterin dönemde

Dokunmuşlar birbirlerine

Fetus ile anne 

Kanın en sıcak eliyle

Bir bedende iki can 

Biri birine o kadar bağımlı ki

Göbek bağından da öte

Bir o kadar bağımsız ki

Nasıl anlatsam bilmem

Uteroplasental  ünite kurulmuş aralarında

Sınır kapısında pazar yeri adeta

Ahenk içinde bir alışveriş

Kontrollü bir karmaşa

Pazarın orta yerinde

Plasental trofoblastlar

Haykırıyor biz yabancı değiliz diye

Gebede nedir ki immünite

Yüreğine taş basıp 

Susmaktan öte

İlk trimesterde başlamıştı hikaye

Anne toleranslıydı

Gebelik bitti

Çocukluk

Bazen de ömür bitti

He şey aynıydı

Bi kez daha anladım 

Anneydi o

Çocuğa en toleranslı olan', 'Bir arkadaşlık başlamış  Intrauterin dönemde Dokunmuşlar birbirlerine Fetus ile anne  Kanın en sıcak eliyle Bir bedende iki can  Biri birine...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/arkadas-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bronkoskopi', 'bronkoskopi-gaffar-karadogan-a129y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ses telleri arasından

Zarif bir hareketle geçtik

Teller bize saygılı

Usulca çekildiler iki yana

Karşımızda karina

Amma da keskin

Kılıçla kıyaslamadan

Geçiyoruz sağ ana bronşa

Mukoza ödemli

Ulaştık orta lob bronşuna

Bir de ne görelim

Dışardan baskı altında

Bronş mukazası ile yakın temastayız

İğneledik, fırçaladık

Hep yaptığımız şey

Patoloji ile diyaloğa geçecek 

Materyallerimiz var artık

Kara haber tez gelir patolojiden

Küçük hücreli akciğer CA

Halkın diliyle

Akciğer kanseri

Sınırlı hastalık, operabıl

Laflar dolanıyor ortalıkta

Haydi operasyona

‘Hocam biz ameliyat istemiyoruz’

Diye dikilirlerse karşına 

Sakın şaşırma

Nedenmiş? 

‘Akciğere bıçak değerse iflah olunmazmış’

Kim demiş? 

‘Çaycı Halil Efendi, Boyacı Rıza Usta’

Ah be üstad

Yine kalkıştık

Atomu parçalamaya', 'Ses telleri arasından Zarif bir hareketle geçtik Teller bize saygılı Usulca çekildiler iki yana Karşımızda karina Amma da keskin Kılıçla kıy...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bronkoskopi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyyah', 'seyyah-hakan-ak-ip38s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ayrılık karıştı akşamlara

yağmur damlası işte

hüzünler avuçlarımda

ertelediklerimden vazgeçtim

dün yine

yine yeni

önce vurgun

sonra seyyah.

merak etmişin işte yazdım._00-10-2003

içimden geldiği gibi 

sevgiler bıraktım

sevgiliden 

elinden

dudaklarından geçtim

kalbin sandım

aktım, aktım...

yağmıyor ki yağmur

kapkaranlık 

öylesine bir gece

vuruldum 

ay görmedi

yıldızlar yoktu

sustum

ağlamıycam işte

istesem içerdim de

senden de 

aşkındanda

kalbindende geçerdim

ben gözlerine tutundum

yolumu bulurdum da

inadına kayboldum

iş bulamadım hala 

aramadım aslında

senin gibi herşey

yorgunum biliyonmu

ama yine aşık oldum

en azından öyle sandım

sonrası malum

yine ayrıldım

senin gibi herşey

dün yine

yine yeni

önce vurgun

sonra seyyah oldum.', 'ayrılık karıştı akşamlara yağmur damlası işte hüzünler avuçlarımda ertelediklerimden vazgeçtim dün yine yine yeni önce vurgun sonra seyyah. ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ak']::text[], 8.5, '{"poet":"Hakan Ak","poet_slug":"hakan-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/seyyah-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sella', 'sella-gaffar-karadogan-5zqsq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sella Tursika

Türk eğeri beyin tabanında

Oturmuş üzerine hipofiz diye bir bez

Yaklaşık altı gram ağırlığında

Tavanında diafragma sella

Hipofiz, yapışık ikizler gibi

Ön tarafı  rathke cebinden

Arka taraf üçüncü ventrikül tabanından 

Hücre çeşnisi ön hipofizde

Beş farklı hücre

Hedefleri başka başka

Hipofiz ile hipotalamus arasında

Bir ilişki var

Herkesin bilmediği

Portal sistem kanalıyla

Laktotroflardan söz etmeden geçemem

Sürekli dopaminin baskısı altında

Dizginleri koparınca prolaktinoma

Bize dopamin agonisti gerek 

Agonist demek 

Takviye kuvvet demek', 'Sella Tursika Türk eğeri beyin tabanında Oturmuş üzerine hipofiz diye bir bez Yaklaşık altı gram ağırlığında Tavanında diafragma sella Hipof...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sella-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaman', 'saman-gaffar-karadogan-ay3n8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acı çekildiğinde hatırlanan           

Acı çekildiğinde önemsenen biriyim

Doktorum ben

İsa’dan çok yıllar önce

Doğa üstü güçler vardı 

Hastalık yapan

O zamanlar şamandı benim adım

Antik dönemde

Kos adasında

Çınar ağacı gölgesinde

Hippokrat

Şamanı doktor yaptı

Binlerce yıl geçti aradan

Dönüp geriye baktım

Çok yol almışız

Daha sağlıklı

Daha uzun 

Yaşamak için

Farkında olmadan belki

Ölümsüzlüğü aramışız', 'Acı çekildiğinde hatırlanan            Acı çekildiğinde önemsenen biriyim Doktorum ben İsa’dan çok yıllar önce Doğa üstü güçler vardı  Hasta...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/saman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-gaffar-karadogan-oddo1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir de bakarsınız

Evlilik denen bahçenin kapısındayız

Uzatırsınız ellerinizi

İki kişilik tek bir irade olmaya

Serap ve Gaffar

Gelmişler bahçe kapısına

Biliyorlar gülün ve dikenin tarihini

İlk adımı atarken

Sade yaşamaya

Ve gülleri dalında sevmeye

Söz verecekler

Dostlar

Tanık olmak için

Zamanı bir de sizi 

Davet ediyoruz', 'Bir de bakarsınız Evlilik denen bahçenin kapısındayız Uzatırsınız ellerinizi İki kişilik tek bir irade olmaya Serap ve Gaffar Gelmişler bahç...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/davet-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyet', 'diyet-gaffar-karadogan-h09b2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birinci dekatta başlıyormuş

Atherosklerotik süreç

Halkın diliyle

Damar sertliği

İnsanın kendine zarar veren sertliği

                 

Endotel üzerine kurulmuş

Dev bir köpük hücresi

Beslenip katmerleşiyor

En alçak kolesterol tipi ile

                  

Peki ne zaman başlamalı diyete 

Daha onlu yaşlardayken mi? 

Hadi be ordan

Kim uzak durabilir on altısındayken

Kuzu tandırdan, kavurmadan

                  

Hem kim demiş

Yediklerimiz neden olur

Aterom plağına

Ya yiyemediklerimizden dolayı

Bozuluyorsa endotel? 

Ekmek aslanın ağzında değil 

Ekmek aslanın karaciğerinde glikojen

Zamanında yaşarken

Diyetisyenler! 

Verin en katı diyetleri hak edene

Versinler diyetlerini hak edenler', 'Birinci dekatta başlıyormuş Atherosklerotik süreç Halkın diliyle Damar sertliği İnsanın kendine zarar veren sertliği                   Endot...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/diyet-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çivi', 'civi-gaffar-karadogan-t0lpy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Memleketin şaftında koca bir kırık

Ortasına bir çivi

Çak ortopedist arkadaş çak

Memleketin çivisi çıkmış

Çak o zaman çak çak', 'Memleketin şaftında koca bir kırık Ortasına bir çivi Çak ortopedist arkadaş çak Memleketin çivisi çıkmış Çak o zaman çak çak...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/civi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Donör', 'donor-gaffar-karadogan-ncwkl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Donör oldum 

Makinaya bağlandım

Otuz bin trombositi

Paket yaptırdım

Tek, tek sayamasakta

Beş bin eksik, beş bin fazla

Vasati otuz bin

Damarda durduğu gibi 

Durmuyor kan pulcukları

Sallamak gerekiyor yavaşça

Ne kadar sallarsan salla

Üç günden sonra 

Uyuyup kalıyorlar

İşe yaramaz oluyor pulcuklar

Sarının farklı tonlarında

Tenimizin rengi gibi

Farklıydı trombositlerin rengi

Tenimizin görevi gibi

Aynıydı trombositlerin görevi

Transfüzyon sonrasında

Görev adamı oldular şimdi

Farklı dünyalarda 

Farklı insanların kanında', 'Donör oldum  Makinaya bağlandım Otuz bin trombositi Paket yaptırdım Tek, tek sayamasakta Beş bin eksik, beş bin fazla Vasati otuz bin Damard...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/donor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke Ben, Hiç Ben Olmasam', 'keske-ben-hic-ben-olmasam-nurhan-gokturk-xvus7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Katar katar isli bir tren olsam

Derin koyaklardan, 

Duru sulardan, 

Yılan gibi sessizce kıvrılsam, 

Gün olup doruklardan, 

Yıldızlara dokunsam.

Gün olup eteklerden saçılsam.

Şeftali çiçeklerini koklasam, 

Kardelenler misali kristalleri delip, 

Göklere ersem.

Ağıtlarla karanlığa karışsam, 

Türkülerle asker uğurlasam, 

Alem olup yükseklerden selam dursam.

Sınır boylarında umut yolcusu olup, 

Vurulup kalsam.

Biten umutları yüklensem, 

Gidip te gelmesem.

Eşkıya olup dağları inletsem, 

Sevgili diye tüfeğimle sevişsem.

Bir kaçak gibi saklanmaktan, 

Bıktım! ! ! 

Çıkmaz bir sokakta ele geçsem, 

Tüm gerçekliğe karşın, 

Bir yalan olsam, 

Keşke ben, hiç ben olmasam.

Nurhan Göktürk

(17 Ekim 2003 Antalya)', 'Katar katar isli bir tren olsam Derin koyaklardan,  Duru sulardan,  Yılan gibi sessizce kıvrılsam,  Gün olup doruklardan,  Yıldızlara dokuns...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/keske-ben-hic-ben-olmasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oksidatif yol', 'oksidatif-yol-gaffar-karadogan-k7jiu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir seversin ki

Sanırsın yeniden doğmuşsun

Soluğu ciğerinin en uç alveolüne çekersin

Oksijeni beyninin en uç hücresine

Bir glukozdan otuzsekiz ATP üretilirken

Araştırıcıların bilmediği

Aşkın oksidatif yolundan

Binlerce ATP üretirsin

Dağları delecek kadar güçlü

Bulutların üzerinde uçacak kadar hafifsin

İşte aşkın esrarlı  periyodu

Tüm bunlar

Ne kadar sürer bilinmez

Belki bir gün 

Belki de bir ömür', 'Bir seversin ki Sanırsın yeniden doğmuşsun Soluğu ciğerinin en uç alveolüne çekersin Oksijeni beyninin en uç hücresine Bir glukozdan otuzsek...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oksidatif-yol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antidot', 'antidot-gaffar-karadogan-8uww7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Evvel zaman içinde

Zehir okun ucunda

Kaybedilen bir insan

Geldik uzay çağına

Zehir füzenin ucunda

Kaybedilen binlerce insan

Gaz maskeleri taktırırlar 

Döneriz, başını kuma sokan devekuşuna

Türlü yöntemler ve antidotlarla

Kurtardık birkaç devekuşunu 

Doktor olarak yaptığımız 

Devede ribozom sadece

Aramak lazım artık

Zehirin değil 

Savaşın antidotunu', 'Evvel zaman içinde Zehir okun ucunda Kaybedilen bir insan Geldik uzay çağına Zehir füzenin ucunda Kaybedilen binlerce insan Gaz maskeleri ta...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/antidot-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çevre', 'cevre-gaffar-karadogan-rd2w0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dolaştınızmı 

Kemik iliğindeki mikro çevreyi

Gördünüz mü ahengi

Matriks ile stroma arasındaki

Nasılda olgunlaştırdılar

Küçülterek stoplazma ve çekirdeği

Çevirdiler

Çok potansiyelli kök hücreyi

Çok özellikli hücreye

Ve yazdılar

Kemik iliğinin kuralını

Hücre olgunlaştıkça küçülür', 'Dolaştınızmı  Kemik iliğindeki mikro çevreyi Gördünüz mü ahengi Matriks ile stroma arasındaki Nasılda olgunlaştırdılar Küçülterek stoplazma ...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cevre-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca ağaç', 'koca-agac-gaffar-karadogan-jyt9z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz koca bir ağacız

Meyve veren bir ağaç

Zaman, zaman taşlansak da

Meyva veriyoruz işte

Yemesini bilene

Her birimiz bu ağacın

Ya yaprağıyız

Ya dalıyız yada meyvesi

Dört mevsim yaşasak da

İçimizde bayram tadında 

Bir bahar besliyoruz 

Yaşamasını bilene', 'Biz koca bir ağacız Meyve veren bir ağaç Zaman, zaman taşlansak da Meyva veriyoruz işte Yemesini bilene Her birimiz bu ağacın Ya yaprağıyız ...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/koca-agac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-gaffar-karadogan-2ghn0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık

Çökmez üzerimize

Karanlık 

Usulca yayılır 

Bir yarım küreye

Üstümüzde başımızda

Sade yıldızlı bir gök

Bakıyorum bir yarı küreye

Sınır tanımadan

Tanıyamıyorum olmayan sınırları

Geçiyorum ırmaklar gibi

Su uyurmuş

Yalan

Düşman uyumazmış 

Yalan

Kalkın dostlar

Görün manzarayı da

Basalım kahkahayı', 'Karanlık Çökmez üzerimize Karanlık  Usulca yayılır  Bir yarım küreye Üstümüzde başımızda Sade yıldızlı bir gök Bakıyorum bir yarı küreye Sın...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yalan-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan gölü', 'kan-golu-gaffar-karadogan-97rcp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimden geçen 

Düşüncelerime

Hançer saplanmış

Kanıyor ömrüm

Kan gölü 

Gönül bahçem

Kan güllere hasret', 'Yüreğimden geçen  Düşüncelerime Hançer saplanmış Kanıyor ömrüm Kan gölü  Gönül bahçem Kan güllere hasret...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kan-golu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Can Yitirdim', 'uc-can-yitirdim-nurhan-gokturk-3lsr6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sızıyor aman sızıyor! 

Yüreğimden kan, 

Sobadan gaz

Üç can yitirdim....

Zeliş''im, Aliş''im, Salih''im...

Olmamış armutlarım.

Sarı saçlarını öpüp, okşayamadıklarım, 

Çakır gözlerine bakmaya, doyamadıklarım.

Anam dediklerini duyamadım.! 

Üç can yitirdim....

Tutulsun bu dilim.

Adlarını anamazsam, 

Bırakın tutuşsun bu yüreğim, 

Üç can yitirdim....

Aliş''im, pek küçük anasız duramaz, 

Oralar dardır, Salih''im sığamaz, 

Zeliş''im, körpe çiçek karanlıkta yol bulamaz

Yarılsın bu toprak! 

Beni de al haramdır yaşamak.

Üç can yitirdim....

Sisli gecelerin korku dolu

Gizem odalarında, 

Kan kırmızı güllerim, 

Bir kıvılcımla düştü..

Kara topraklara.

Nurhan Göktürk

(31 Ocak 2003 Antalya)', 'Sızıyor aman sızıyor!  Yüreğimden kan,  Sobadan gaz Üç can yitirdim.... Zeliş''im, Aliş''im, Salih''im... Olmamış armutlarım. Sarı saçlarını öp...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/uc-can-yitirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kültür', 'kultur-gaffar-karadogan-wj60h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mustafa bir de Elif

Çalışıyorlar didiniyorlar

Mikrobiyoloji laboratuarında

Kanımızdaki

Tüm vücudumuzdaki

Mikropları açığa çıkarmak için

Bilelim içimizdeki canavarları

Tanıyalımda

Yok edebilelim onları

Kan bedenden çekilmeden

Bu iş için üretilir

Besi ortamları

Agarların en kanlısı en çikolatalısı

Yiyip beslendikçe

Açığa çıkıyorlar

Mikroplar kolonilerce

Yüzbinlerce milyonlarca

Canavarlar

Bir kültürün sonuçları

Asistanlar vardı

Kültür peşinde koşan

İnsanlar vardı 

Kültürlerden habersiz', 'Mustafa bir de Elif Çalışıyorlar didiniyorlar Mikrobiyoloji laboratuarında Kanımızdaki Tüm vücudumuzdaki Mikropları açığa çıkarmak için Bile...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kultur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamze; Doru, Dilay', 'gamze-doru-dilay-nurhan-gokturk-umu9o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Atlar boşaldı ağıllardan.

Arkalarında kaldı toz duman, 

Atlar şaha kalktı dört bir yandan.

Yabana erdikçe, yaban oldular.

Çekip attılar gemlerini ağızlarından, 

Gözleri küçüldü, soludukça özgürlüğü.

Gamze, Doru, Dilay''dılar, 

Unuttular adlarını.

Yılların özlemini, bir kurşunda buldular, 

Gözlerinde kaldı dağlar.

Nurhan Göktürk

(18 Kasım 1987/Niğde)', 'Atlar boşaldı ağıllardan. Arkalarında kaldı toz duman,  Atlar şaha kalktı dört bir yandan. Yabana erdikçe, yaban oldular. Çekip attılar geml...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gamze-doru-dilay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanık', 'tanik-gaffar-karadogan-vnmk7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Filozofik bir iş değil 

Bizim yaptığımız

Namus işçiliği ise 

Üstad Ahmed Ariften kaldı

Bir tür hayata tanıklıktır

Bizim yaptığımız

Yaşamı kayıtlara geçiyoruz

Kayda değdiği kadarıyla', 'Filozofik bir iş değil  Bizim yaptığımız Namus işçiliği ise  Üstad Ahmed Ariften kaldı Bir tür hayata tanıklıktır Bizim yaptığımız Yaşamı ka...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tanik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstler', 'ustler-gaffar-karadogan-g31cu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tedavülden kalkmış

Bir para ise para üstü

Üstü kalsın demek 

Ne kadar boş

Üstler tedavülde olsalarda

İstemiyoruz artık

Kalsınlar bozukluklar

Bozukluk olarak', 'Tedavülden kalkmış Bir para ise para üstü Üstü kalsın demek  Ne kadar boş Üstler tedavülde olsalarda İstemiyoruz artık Kalsınlar bozukluklar...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ustler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devinim', 'devinim-gaffar-karadogan-5m3z6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir süper egom vardı

Babamdan kaldı

Bir egom vardı

Yaşarken oldu

Bir id’im vardı

Doymadı

Süper ego, babama kaldı

Yerini vicdan aldı

Ego, devindi durdu

İd, ne hali varsa gördü', 'Bir süper egom vardı Babamdan kaldı Bir egom vardı Yaşarken oldu Bir id’im vardı Doymadı Süper ego, babama kaldı Yerini vicdan aldı Ego, dev...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/devinim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fibroblast', 'fibroblast-gaffar-karadogan-1hs4h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ölüm marşının

En dokunaklı notaları olsa da hayat

Fibroblastlar dokuyacaklar

Kollajen iplerini

Bir uçtan bir uca', 'Bir ölüm marşının En dokunaklı notaları olsa da hayat Fibroblastlar dokuyacaklar Kollajen iplerini Bir uçtan bir uca...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/fibroblast-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yayma', 'yayma-gaffar-karadogan-k21aj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Genç nötrofiller 

Gülümseyerek 

Bana bakıyorlar

Yüzlük büyütmede 

Mikroskop altında

Neden hep sola kayıyor yaymalarımız

Ateş bastığında', 'Genç nötrofiller  Gülümseyerek  Bana bakıyorlar Yüzlük büyütmede  Mikroskop altında Neden hep sola kayıyor yaymalarımız Ateş bastığında...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yayma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komik', 'komik-gaffar-karadogan-iskek', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yayılmış sere serpe

Kemik iliği

Hakim olacakmış makrofajlar

Tüm seriye

Ha ha ha! gülesim gelir

Yok olacakmış eozinofiller

Ha ha ha! gülesim gelir', 'Yayılmış sere serpe Kemik iliği Hakim olacakmış makrofajlar Tüm seriye Ha ha ha! gülesim gelir Yok olacakmış eozinofiller Ha ha ha! gülesim ...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/komik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aks', 'aks-gaffar-karadogan-iqu6c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Renin, anjiotensin, aldesteron

Kime ait bu sistem

Fizyologlara mı? 

Kardiyologlara mı? 

Nefrologlara mı? 

Hayır hiçbirine

Herkesin aksı kendine', 'Renin, anjiotensin, aldesteron Kime ait bu sistem Fizyologlara mı?  Kardiyologlara mı?  Nefrologlara mı?  Hayır hiçbirine Herkesin aksı kend...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aks-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ar damarı', 'ar-damari-gaffar-karadogan-k5a59', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ar damarı varmış gördüm

Çatlakmış

Ar damarı varmış gördüm

Çatlamdan durmazmış

Ar damarı varmış gördüm

Beynin tam ortasındaymış', 'Ar damarı varmış gördüm Çatlakmış Ar damarı varmış gördüm Çatlamdan durmazmış Ar damarı varmış gördüm Beynin tam ortasındaymış...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ar-damari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başı Boydak', 'basi-boydak-nurhan-gokturk-29ha4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O yaz günleriydi.

Kayıtsızlığın timsali, 

Başı boydaklığın, 

Su misali akıcılığın.

Burnumun ucunda tüten, 

Baygın  hanımelinin kokusuydu.

Açık penceremden gönlüme dolan.

Havada bir hafiflik, 

Bende başı boydaklık.

Oradan oraya yalpa vuran, 

Seviyor mu? sevmiyor mu? diye, 

Papatyaları ayırırken yaprak yaprak, 

Bakmazdım  hiç yüzüne.

Yüzü ne hal alır, nasıl titrer yüreği

Ne olacak korkak! ! diye

Haykırırdı ateşböcekleri, 

Bende kayıtsızlığın kol gezdiği

O yaz geceleri.

Bir sonbahardı zannedersem, 

Yüreğim kuş misali, 

Kaçmaya çalışırken kafesten.

Ağlara takıldım kaldım.

Gülmez artık gözlerim, 

Ellerim seni okşamazsa

Kızma sevgilim...

Yok artık yazdan kalan kayıtsızlığım, 

Kara saplandım kaldım.

Nurhan Göktürk

(26 Eylül 1993/ Bismil)', 'O yaz günleriydi. Kayıtsızlığın timsali,  Başı boydaklığın,  Su misali akıcılığın. Burnumun ucunda tüten,  Baygın  hanımelinin kokusuydu. Aç...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/basi-boydak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerbet', 'serbet-gaffar-karadogan-gl42s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şerbet var şerbet

Nabıza göre şerbet

Her damara ayrı şerbet

Verenler var

Tek şerbetim var benim

Veriyorum her damara 

Aynı hızda', 'Şerbet var şerbet Nabıza göre şerbet Her damara ayrı şerbet Verenler var Tek şerbetim var benim Veriyorum her damara  Aynı hızda...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/serbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reseptör', 'reseptor-gaffar-karadogan-rd3we', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir reseptör varmış

Duyarlıymış

Karbondioksidi görmüş

Solunum uyarılmış

Hadi bakalım karbondioksid

Akciğerden dışarı

Bir reseptör varmış

Duyarsızmış

Karbondioksidi görmüş

Tanıyamamış

Vücut hipoksik kalmış', 'Bir reseptör varmış Duyarlıymış Karbondioksidi görmüş Solunum uyarılmış Hadi bakalım karbondioksid Akciğerden dışarı Bir reseptör varmış Duy...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/reseptor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinüzit', 'sinuzit-gaffar-karadogan-b8grm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mahallede dolanıyor

Sümüklü çocuklar

Üç beş yaşlarında

Sokak ortasında

Hiçbiri sümüklü değil

Hepsi akut sinüzit aslında', 'Mahallede dolanıyor Sümüklü çocuklar Üç beş yaşlarında Sokak ortasında Hiçbiri sümüklü değil Hepsi akut sinüzit aslında...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sinuzit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya ajans', 'ruya-ajans-gaffar-karadogan-27v5f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece yine komadayım

Çevremden habersiz

Derin bir uykudayım

Kovalarken birbirini

REM non-REM dönemleri

Kısa metrajlı filimler izlerdik

Hepsi yerli yapım 

Hepsi rüya ajans', 'Bu gece yine komadayım Çevremden habersiz Derin bir uykudayım Kovalarken birbirini REM non-REM dönemleri Kısa metrajlı filimler izlerdik Hep...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruya-ajans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaş dolaş', 'sarmas-dolas-gaffar-karadogan-wuxen', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yirmiüç çift kromozomumuz var

Sarmaş dolaş

Yirmiüçü anneden 

Yirmiüçü babadan

Eşitlik ilkesinden

Bazıları çekin(gen)  arka planda

Bazıları baskın(gen)  ön planda

Eşitsizlik ilkesinden

İdare edin artık

Nasıl olsa hepsi sarmaş dolaş', 'Yirmiüç çift kromozomumuz var Sarmaş dolaş Yirmiüçü anneden  Yirmiüçü babadan Eşitlik ilkesinden Bazıları çekin(gen)  arka planda Bazıları b...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sarmas-dolas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otonom', 'otonom-gaffar-karadogan-5qh3z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani sinir sisteminin

Kendi başına buyruk olanı varya

Adı otonom olan

Biz uyurken bile uyanık

Başına buyruk olsa da

Her şey yine de bizim için', 'Hani sinir sisteminin Kendi başına buyruk olanı varya Adı otonom olan Biz uyurken bile uyanık Başına buyruk olsa da Her şey yine de bizim iç...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otonom-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Henle kulpu', 'henle-kulpu-gaffar-karadogan-mv860', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karışmayın henle kulpuna

Uzanmış medullanın derinliklerine

Çevresinde medüller hipertonisite

O şimdi

İdrarı konsantre ediyor

Distal tübüle inat

ADH’ya bağımlı olmadan', 'Karışmayın henle kulpuna Uzanmış medullanın derinliklerine Çevresinde medüller hipertonisite O şimdi İdrarı konsantre ediyor Distal tübüle i...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/henle-kulpu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durmaksızın dönen kör kurşunlar', 'durmaksizin-donen-kor-kursunlar-i-lyas-sahin-624rr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küre 

yerçekimi

meridyen 

dönen kör bin kurşun

Yüreğimin orta yerinden saplandı ve çıktı orta yerinden

Habille başladı isabet

Kavuk zırhını deldi ve Zekeriyya

Kerbela yolunun üstü ve Huseyn

Kudüs

Durmaksızın dönen kör bin kurşun

Dağlar ve kardeşlerim

Zindan ve kardeşlerim

Issızlık, sessizlik ve gerçek dost

Coğrafyam ve kardeşlerim

Yüreğimde kapanmayan bin yara', 'Küre  yerçekimi meridyen  dönen kör bin kurşun Yüreğimin orta yerinden saplandı ve çıktı orta yerinden Habille başladı isabet Kavuk zırhını ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Şahin']::text[], 8.5, '{"poet":"İlyas Şahin","poet_slug":"i-lyas-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/durmaksizin-donen-kor-kursunlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kodon', 'kodon-gaffar-karadogan-q916t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yetti artık

Bu düzen(bazlık)

Bize yenilik gerek

Hücre düzeyinde

İşe başlıyoruz

Çözün ko(donları) 

Delesyon yapılacak', 'Yetti artık Bu düzen(bazlık) Bize yenilik gerek Hücre düzeyinde İşe başlıyoruz Çözün ko(donları)  Delesyon yapılacak...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kodon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyabet', 'diyabet-gaffar-karadogan-vw9sc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğru bilgiler yığınak yapmış

Diyabet konusunda

Bilgiyi öğrenmekle kalmayıp

Uygularsan yaşamına

Gör nasıl sağlıklı yaşarsın

Yaşam kaliten zirvelerde

Diyabetin kendi gider 

Sade adı kalır sende', 'Doğru bilgiler yığınak yapmış Diyabet konusunda Bilgiyi öğrenmekle kalmayıp Uygularsan yaşamına Gör nasıl sağlıklı yaşarsın Yaşam kaliten zi...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/diyabet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tırşık', 'tirsik-gaffar-karadogan-vvi83', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Armut’un iyisini yiyenler

Umurumda mı? 

Ayvayı yiyenler

Yorumsuz kalsın

Tek öğün kapuska

Ve tırşık yiyenler

Umurumda

Bir deri bir de kemikler

Erimediği kadarıyla kas

Olabildiğince kas

Sanmayın yağ dokuları yok

Beyinleri var

Erimeyen yağ dokusu

Erimeyen düşünceleri var', 'Armut’un iyisini yiyenler Umurumda mı?  Ayvayı yiyenler Yorumsuz kalsın Tek öğün kapuska Ve tırşık yiyenler Umurumda Bir deri bir de kemikle...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tirsik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geriye Dönmek', 'geriye-donmek-ali-osman-yilmaz-trb6j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geriye dönmek

Her şeyi ortada öylece bırakıp, 

Sevdayı, umudu, 

Bırakıp gidebiliyorsan

Sevdim diyemezsin ki! 

Sevmekten pişman olmak? 

Bunu anlamadım hiçbir zaman, 

Geriye dönüp, yaşama

Yeniden başlamayı düşlemek, 

Mümkün değildir güzelim! 

Sevda ateşinde yanmış gibi sıcaktan 

Ve susuzluktan kavrulmuş, 

Toprakta, ne ekilebilir? ne biçilebilir ki? 

Yaşam yoktur orada, 

Yaşamın olmadığı yerde, 

Sevgi de yoktur, aşk da! 

Sevginin olmadığı yerde, 

Ne sen varsın güzelim, 

Ne ben? 

Hele insan arama hiç, 

Yoktur, bulamazsın, 

İnsanın olmadığı yerde, 

Keşkeler, belkiler, 

Yeşerecek yeni ümitler

Yoktur! 

Keşkenin kucağında da olsan, 

Ya varsın; Ya varsın, 

Aynada gördüğün, 

Ben değilsem? 

Yoksun.

Bursa...25..Ekim..2003..10.30 (pm)', 'Geriye dönmek Her şeyi ortada öylece bırakıp,  Sevdayı, umudu,  Bırakıp gidebiliyorsan Sevdim diyemezsin ki!  Sevmekten pişman olmak?  Bunu ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/geriye-donmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küreselleşme', 'kuresellesme-gaffar-karadogan-kx82x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsanları üçe ayırasım geldi

Tam karşısındayken 

Televizyon kutucuğunun

İlla ki küreselleşeceğiz diyenler

Küreselleşme karşıtları

Bir de küreselleşme izleyicileri

Toplanıveriyorlar arada bir

Küreselleşelim diyenler

Karşıtları ise onların çocukları

Küreselleşmişler zaten

Biliyorlarmış olacakları

Aynı kürede yaşarken

Kendi kürelerine katacaklar

İkinci dünya ülkelerini

Üçüncü dünya ülkelerini

Ve sıralamaya giremeyen ülkeleri

Sıvağı mı olacağız acep

Isınma trendindeki

Çatlayan kürelerinin', 'İnsanları üçe ayırasım geldi Tam karşısındayken  Televizyon kutucuğunun İlla ki küreselleşeceğiz diyenler Küreselleşme karşıtları Bir de kür...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kuresellesme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gram hesabı', 'gram-hesabi-gaffar-karadogan-p4ycs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaratılırken 

Sıra geldi insana

Birazda beyin koyun

Kilogram başına yirmi gram', 'Yaratılırken  Sıra geldi insana Birazda beyin koyun Kilogram başına yirmi gram...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gram-hesabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Patlama', 'patlama-gaffar-karadogan-3vjz1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün olmuş

Devran dönmüş

Develüasyon olmuş memleketimde

Çıkmış karşımıza 

Düze çıkmaz bir memleket

Köşe kapmaca oynayan yazarlar

Sihirli küreleri olmasa da ortada

Bir patlama lafı dolamışlar dillerine 

Adı sosyal patlama

Traş oldum

Gittim sağlık merkezine

Sağlık sistemimin içine...

Daha yeni başlıyorduk ki güne

Otopark görevlisi 

Kartını göstermeyen sürücüye patladı

Sıra  bekleyen hastalar 

Birbirine patladı

Tahliller fazla gelince

Laboratuarcı patladı

Hoca assistana

Asistan çömezine patladı

Hemşire personele

Personel ziyaretçiye patladı

Ziyaretçi 

Kendi kendine patladı

İsterimki bu patlamalar 

Bilincin simgesi olsun

Patlasın bizi uyutanların

Yüzünde ve beyninde', 'Gün olmuş Devran dönmüş Develüasyon olmuş memleketimde Çıkmış karşımıza  Düze çıkmaz bir memleket Köşe kapmaca oynayan yazarlar Sihirli küre...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/patlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bos', 'bos-gaffar-karadogan-mxv47', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beynim sulanacak biliyorum

Belli bir yaştan sonra

Beyin suyu dediğimiz

Beyin omurilik sıvısı

Epandim hücreleri üretiyor

Beyinin kendi ürünü işte

Size ne

Hem biraz da sulu olanı 

Daha makbul

Bizim köyde', 'Beynim sulanacak biliyorum Belli bir yaştan sonra Beyin suyu dediğimiz Beyin omurilik sıvısı Epandim hücreleri üretiyor Beyinin kendi ürünü ...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bos-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sap', 'sap-gaffar-karadogan-osnpf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beyin bu işte

Tabanı, tavanı var

Sapı da', 'Beyin bu işte Tabanı, tavanı var Sapı da...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınlık çağ', 'aydinlik-cag-gaffar-karadogan-kd6rm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En aydınlık çağda

Adölesan çağda yaşarken

Kılıç savuracak kadar güçlü iken

Kılıçlar kalemleri sivriltip

Kalemler aşk şiirleri yazsın diye

Şiirler yazıyorken....

Göz bebeklerinden geçer

Beynine saplanır bir silüet

Tenine değer bir ten

Bir haller olur sana

Ateşin düşmez 37’den aşağı

Dünyalar bir yana

Sen bir yana dedirten bir ateş

Isıtır seni, bulutlar üzerinde uçarsın

İşte aşk ateşidir bu

Etiyolojiye ben koydum

Sınırsız bir düş gücüdür

Ateşi ortaya çıkaran

Cevap vermez kimselere

Ve prostoglandinle uğraşan aspirine

Duydum Lokman Hekim bile

Düşürememiş bu ateşi

Sebebi ortadan kaldırmalı

Lafları dolanıyor orta yerde

Size sesleniyorum 

Yapıcı bir ateş bu

Kim çıkardıysa 

Sakın söndürmesin o ateşi', 'En aydınlık çağda Adölesan çağda yaşarken Kılıç savuracak kadar güçlü iken Kılıçlar kalemleri sivriltip Kalemler aşk şiirleri yazsın diye Şi...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aydinlik-cag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gılgameş', 'gilgames-gaffar-karadogan-yb1pg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bilinmezlik çölünde

Kalmış bir başına

Uruk arslanı

Gılgameş

Çölün ortasında

Yüreği derya

Cenneti anlatmışlar ona

Fırat kıyılarından daha zengin

Ve daha bir suna

Koşuyor

Sarı çölden

Yeşil vahaya

Toplanmışlar 

Güneş tanrısı Şamaş, 

Savaş tanrısı Bel, 

Ateş tanrısı Gibil, 

Ay tanrısı Nannar, 

Ve diğer tanrılar.

Bir denge kurmuş sanki

İlahi kalabalık

Gılgameşin etrafında

Uruk

Sümer ülkesinin başkenti

Tanrılar tarafından

Ilıman bir iklimle korunan

Bu şehir

Civar köyleri

Yağmacılardan korurdu

Uruk kentinde yaşam 

Üç boyutlu

Bir boyutta Uruk halkı

Birinde tapınak hizmetçileri

Diğer boyut yedi bilge dünyası

İşte şehrin tapınakları

Anu, İştar, Eanna

İhtişamlı, eşsiz ve yüksek

Tanrılarla konuşmak için

Yaşlı kadın Ninsun

Ulu bilge

Rüzgar gibi sesi

Doğruyu ve düşünmeyi aşıladı

Sesiyle Gılgameş’e

İşte ilk öğreti

Korkuyu yenen cesaret

Sevincin bir parçası

Sevinç, cesaretten daha kudretli

Gılgameş

Gözlerinde kırmızı aslan gülüşü

Yüreğinde sevincin bir parçası cesaret

Gılgameş’in gözünde

Yaşam basit ve sade

Görev, yükümlülük ve maceradan ibaret

Zor olanlar ise insanlardı

Yedi bilge mağarasıyla

Tapınaklar arasında

Bir elçiydi Gılgameş

Bilgeler ihtiyar

Öğretileri

Yılların tecrübesi

Kral Dimuzi ölünce

Tanrılardan güç alan 

Lider arandı

İhtiyar bilge

Davudi bir sesle

Kraliyet asasını 

Gılgameş’e uzattı

‘Büyük tufandan sonraki 

Yirmi sekizinci kral’ diyerek

Yeminlerin en berrak ve sadesi

Gılgameşin dilinde

‘Hizmet eder gibi hükmedeceğim

Hükmeder gibi hizmet edeceğim’

Sade giysiler içinde

Gılgameş

Tacın, asanın, mantonun değeri yok

Halktan biri kadar yalın

Kral kadar mağrur

Geniş bir ülkenin kalbi

Sanat, zanaat, din, politika

Ve ticaret merkezi Uruk

Gılgameş’in emrinde

Dünyada eşi olmayan

Surlarla çevrilecekti

Topladılar

Taş ustalarını, duvarcıları

Eli kalem tutanları

Ve düşünebilen tüm insanları

Çöle ve düşmana karşı

Uruk korunacaktı

Gılgameş

Üçte ikisi tanrı

Üçte biri insan

Azim ve inanç

En tanrısal yanı

Tamamladı şehri kuşatan surları

Uruk eşsiz bir çiçek gibi açtı

Bolluk ve bereket 

Fırat kıyısındaydı

Gök tanrıçası Ma

Topraktan biraz kil aldı

Gılgameş’e denk birini yarattı

İçine yaşam üfleyince

Güçlü Enkidu bozkır ortasındaydı

Enkidu

İri yarı, vahşi ve güçlü

Gökyüzü sakinlerinden biri kadar

Perçemleri ve sakalları uzun 

Gözleri parlak yıldız misali

Göbeği olmayan göksel çocuk

Gılgameş’in beklenen dostu

Bilge ana Ninsu

Devam ediyordu öğretiye

Rüzgar gibi sesiyle

Aynı varlığın sağ ve sol parçası

Gılgameş ve Enkidu’ya

Öğütlerde bulundu

‘Tehlikelerden sakının

Tanrılara karşı günah işlemeyin

Kudreti sizden az olanları koruyun’

Uzaklarda kuzeybatıda

Lübnan diye bir ülke

Lübnan’da Hermon dağı

Sedir ağaçları ile süslenmiş

Ormanı koruyan

Gulyabani Humbaba

Kötülükleri toplamış

Geçit vermez orman içine

Kartalların uçmaya cesareti yok

Hermon dağında

Humbaba

Tarif edilmez dehşetin ta kendisi

Gılgameş kararlı

Hermon dağının kalbinden

Sedir ağaçlarını sökecek

Enkidu

Humbaba’ya bulaşmama yanlısı

Gılgameş ikna eder Enkidu’yu

Bilgelerle konuşulur

Yolun haritası

Tavsiyeler alınır

Yaşlı ana Ninsun

Kehanette bulundu

Tanrılardan güç ve merhamet istedi

Savaştan galip gelmek için

Yalnız değil atrık Gılgameş

Kuşandılar

Altın kabzalı kılıçları

Üç talent ağırlığındaki baltaları

Ve zırhlı giysileri

Elli gözü pek asker yanlarında

Fırat kıyılarında

Çıktılar Lübnan yolculuğuna

Birçok gün

Birçok gece

Fırat nehrinde yol aldılar

Ulaştılar düğüm noktası kıyı şehrine

Mari

Büyük tufandan sonra kurulmuş

Onuncu şehir

Mari’de geçen iki gün

Sonrasında kızgın çöl

Haritadaki  yerleşim birimleri

Aşılıyordu sırayla

Palmarya vahası

Orontes vadisi

Bukea ovası geçildi

Ulaşıldı koyu yeşil göle

Ardından Kadeş

Kayalıkların geçit vermez kalesi

Sonrasında beklenen orman 

Orman sessiz ve karanlık

Askerlerin duyduğu

Katırların kalp sesleriydi sadece

Kuş ve böcek sesleri

Terk etmişti ormanı

Ürperten suskunluk

Korkuyu getiriyordu

Korku suskunluğu

Enkidu ve Gılgameş

İçlerinde korku ile cesaret

Karmaşayla ilerliyorlardı

Ormanın kapısında

Hayalet Adad

İlk karşılaşılan

Korkunç ve devasa

Adad’ı alt etmek için

Eski Uruk kralı

Lugalbanda’nın ruhu

Yetişti Gılgameş’in imdadına

Çetin bir çarpışma sonrası

Adad’ın kafası 

Patladı  Enkidu’ nun kılıç darbesiyle

Humbaba küçümsedi

Gılgameş ve Enkidu’yu

Göklere alevler püskürterek

Hava tanrısı Wer 

Gökyüzünün efendisi Şamaş’tan

Emirler aldı

On üç farklı rüzgarı

Kükreyerek Humbaba’ya yolladı

On üç rüzgar

Ve Enkidu’nun oku

Hermon dağını Humbabaya mezar yaptı

Barış gelmişti artık

Hermon dağına

Ve Lübnan topraklarına

Ormanda kuş sesleri

Bir baştan bir başa

Sürekli güneşe yürüdü

Enkidu rüyasında

Bozkırlarda sekerek

Dicle ırmağına ulaştı

Ardından Kerha ırmağı

Irmaklar sonrası

Başı dumanlı bir dağ

Dağın zirvesine tırmandı

Zirvede ilahi bir ateş

Çevresinde tanrılar

İki insanın kaderini konuşuyorlar

Enkidu  dinlemeye başladı

Tanrı Enlil’in gözünde

Günahkardır Gılgameş ve Enkidu

Hermon dağından sedirleri keserek

En büyük günahı işlediler

Tanrı Anu

Gılgameş’ten yana

Şamaş ise kaderden

Anu tekrar söze başladı

Ormanın kapısını açan

Humbaba’yı öldüren

Sedirler kesilsin diye ısrar eden

Enkidu 

Hak edendir ölümü

Konuşmalar tamamlandı

Enkidu ölmeli diye yazdı

İlahi kader

Amansız bir hastalığın pençesinde

Enkidu

Ormanın kapısını açarken

Koluna ilişen illet

Tüm vücudunu sarmıştı

Enkidu’nun ruhu güvercin kadar hafif

Bedeni cansız ve ağır

Ruh ve beden

Ayrı yönlerde artık

Ağıtlar yakıldı

İnsanlar siyaha büründü

Uruk şehrinde

Dicle, Kerha, Ulai ırmakları

Ardından gözyaşı döktü

Susa

Elam ülkesinin başkenti

Kerha ırmağının kıyısında

Dicle’nin doğusunda

Susa’lı akıllı adam

Sutruknahunda

Yaşlı gezgin

Kültürlerin bilgesi

Tanımak arzusunda

Tüm kültürleri

Uruk’u ve Gılgameş’i

Sutruknahunda

Uruk’a ulaşınca

Gördüklerine şaşmadı

Herşey anlatıldığı kadar harika

Gılgameş ile bilge

Yaşamı tartıyorlar

Ölüm konuşmanın bir kefesinde

‘Ölüm bize ne kadar yakın

Biz kabullenmekten o kadar uzak’

Dedi yaşlı bilge

Kimdir boşa yaşamayan? 

Ölümün olduğunu bilip

İyilik ve güzellik bırakan

Mutlu insan

Devam etti anlatmaya 

Ölümsüzlük otunu

Mutlular adası Tilmun’u anlattı

Tilmun nerede? 

Kimse bilmiyor

Ölümsüzlük 

Gılgameş’in özleminde

Kuşanarak çıktı yola

Hangi yöne? 

İçinden gelen sesle

İlerliyor sarı çölde

Ölümsüzlük yolunda

Maşu dağı

Işığın zerresi yok içinde

Akrep insanlar dağın çevresinde

Cehennem misali

Çift zirveli bir dağ

Diğer adı İkiz Dağ

Hayvan eğeri gibi

İkiz dağın kapısında

İki korkunç nöbetçi

Cehennem bekleyenleri

Gılgameş

Duygulu sözler söyledi

Gerçeği, cesareti

Aradığı sonsuz yaşamı anlattı

Nöbetçiler duygulandı izin verdi  Gılgameş’e

Maşu dağında karanlığın en tarifsizi

Ne  bir ışık, ne de bir ses 

Var olan tek şey

Diri, diri gömülme hissi

Karanlık dağı aşmak

Cesaret ve içsel aydınlık işi

Karanlıkta umutla ilerledi

On ikinci çift saatin sonunda

Güneş ışıkları

Gılgameş’i selamladı

Eşsiz elmas bahçesi karşısındaydı

Açlığı ve susuzluğu

Hissetti elmas bahçesinde

Açlık ve susuzluk

Elmaslardan  değerli

Kuşlar vardı Gılgameş’in tepesinde

‘Elmasları kopar’ diye bağıran

Kopardığı elmas

Akkor oldu tenini yaktı

Değerli taştan bir canavar

Gılgameş’e saldırdı

Kaçıyordu

Yakut canavardan

Elmas bahçesinden

Yaşamak isteğiyle 

Sonunda

Yıldızlara ve kumsala ulaştı

Gılgameş

İnsan sesine hasret

Yürüdü kıyı boyunca

Sazdan bir kulübe gördü

Kulübede hancı kadın

Siduri Sabitu Gılgameşe seslendi

‘Ölüm insanlara

Ölümsüzlük tanrılara verildi

Ölümsüzlüğü aramak

Maceradan ibaretti’

Gılgameş kararlı

Gidecek mutluluk adası Tilmun’a

Ölümsüzlüğü bulmaya

Hancı kadın Siduri

Tek gidiş yolunu

Ormandaki Urşanabi’yi anlattı

Urşanabi

Ölüm suyundan geçebilen tek adam

Tilmun’a tek gidiş yolu

Fırtınalı bir yolculuk

Sonunda Tilmun kıyısı

Kıyıda ölü deniz

Ölü denizin ölüm suyu

Bir damlasına dokunmadan

Adaya çıkılmalı

Başardılar zoru

Zor olan adaya çıkışı

Ölümsüz iki ada sakini

Ziusudra ve Utnasudra

Büyük tufanın kurtarıcıları

Ölümsüzlüğün armağan edildiği

İki kişi

Mistik bilginin kaynağı Ziusudra

Anlatmaya başladı

‘Gökyüzündekileri

Yeryüzündeki tanrıları

İnsanın yaradılışını

Tanrılar arasındaki kargaşayı

Büyük tufanı

Büyük tufanı haber veren

Gören gözlerin efendisi Ea’yı

Canlıları kurtarmak için

Ea’nın gemi planını

Tufandan sonraki yaşamı

Ziusudra ve Utnasudra’ya

Tanrıların ölümsüzlük armağanını

Mutlular adası ve Tilmun’u

Nasıl sunduklarını

Tanrılarla birlik içindeki

Yaşamlarını anlattı

Ölümsüzlük için

Tüm tanrılar toplanmalı

Gılgameş’in etrafına

Herşey küçük bir sınavla başladı

Altı gün yedi gece

Uyumayacaktı

Yolculuğun ağır yorgunluğu

Çöktü Gılgameş’in gözlerine

Altı gün yedi gece uyudu

Bir ölümlü gibi

Kader kitabında yazılan

Yaşam için

Gılgameş geri dönüyordu

Bilgi ve tecrübeyle

Bir de küçük bir armağanla

Ziusudra tarif etti

Adada gizlenen

Gençlik otunun yerini

Bir tutam ot yiyince

Gılgameş’in gençliği

Geri gelecek

Yaşlılığı gecikecekti

Tekne yolculuğuyla

Ulaştılar gençlik otuna

Bir öbek ot  Gılgameş’in çıkınında

İlk dinlendikleri ada

Gılgameş kuyuda

Su aramakta

Çıkını kuyunun yanıbaşında

Bir yılan ulaştı gençlik otuna

Gılgameş yetişemedi

Yılan gençleşerek kabuğunu değiştirdi

Gılgameş ağlıyordu

Bir acı duydu yüreğinde

Felaketti bu

Herşey bir öğreti

Uruk’tan Tilmun’a kadar

Yaşanan herşey

Gılgameş karar verdi

Dönecekti Uruk’a

Küçük yelkenli

Bir de Urşanabi

Çıkmışlar yola

Dalgalar, gök gürültüsü

Büyük tufan misali

Bir kıyamet

Parçaladı yelkenliyi

Urşanabi kayboldu

Gılgameş 

Bir tahta parçasının sırtında

Gençlik otunu da yese

Ne fayda

Ölüm işte şuracıkta

Herşey süt liman olunca

Gılgameş minnet duydu

Tahta parçasına

Bir kayıkçının  eliydi

Gılgameş’i sudan çıkaran

Ve getiren şehri Uruk’a

Yaşam olgunlaştırmış Gılgameş’i

Maceraperest, gözükara adam

Yok ortada

Sabır ve tecrübe abidesi

Gılgameş

Sinnunni

Uruk şehrinin şairi

Oturdu Gılgameş’in yanıbaşına

Dinledi kralın tüm macerasını

Düşüncelerini de katarak

Yazdı Gılgameş Destanı’nı

Gılgameş’in sonsuz yaşam arayışını', 'Bir bilinmezlik çölünde Kalmış bir başına Uruk arslanı Gılgameş Çölün ortasında Yüreği derya Cenneti anlatmışlar ona Fırat kıyılarından daha...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":450,"source_url":"https://www.antoloji.com/gilgames-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Robot resim', 'robot-resim-gaffar-karadogan-344bs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Robot resmimi yaptırdım

Robotluk ilkesine bağlı kalarak

Birkaç görgü tanığı

Bir de çizer gerekti

Sesli düşünürken görüldüm

Robot resmimi yaptırdım

Bir kenarda hazır dursun

Belki aranırım

Belki yaşama kaydolurken kullanırım', 'Robot resmimi yaptırdım Robotluk ilkesine bağlı kalarak Birkaç görgü tanığı Bir de çizer gerekti Sesli düşünürken görüldüm Robot resmimi yap...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/robot-resim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Ne garip', 'sevmek-ne-garip-ahmet-aksoy-fkcb6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek ne garip

Her şeyini kabul edip

Birini istemek

Ölesiye istemek

Sanki birlikte olunca

Bu birliktelik

Sonuna kadar devam edebilecekmiş gibi

Son derken ölümden sonraki yaşam da dahil

Ve kaybetmek ne garip

Sonuna kadar istediğin birini

Ve katlanabilmek onsuzluğa

Sanki onsuzluk yerine 

Ölmeyi yeğlemez  gibi.', 'Sevmek ne garip Her şeyini kabul edip Birini istemek Ölesiye istemek Sanki birlikte olunca Bu birliktelik Sonuna kadar devam edebilecekmiş g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevmek-ne-garip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler Konuşmaz', 'oluler-konusmaz-ahmet-aksoy-cafj5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her haykırışın

Dipsiz kuyuya düşen taş oldu

Düşüşü sonsuz yankısı kendi olan

Beklediğin yıllar oldu

Sonsuzluğa denk

Duyulmayan feryatların oldu

Acı dolu, çaresiz

Sevdiğine, cevapsız soruların oldu

Birbiri ardına hiç bitmeyen

Unuttuğunsa bu oldu

Ölüler konuşmaz.', 'Her haykırışın Dipsiz kuyuya düşen taş oldu Düşüşü sonsuz yankısı kendi olan Beklediğin yıllar oldu Sonsuzluğa denk Duyulmayan feryatların o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/oluler-konusmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buzdan', 'buzdan-ahmet-aksoy-4zmgs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buzdan bir sütundu aşkımız

Saf ve pürüzsüz

Ay kadar güzel

Görkemi namından öte

Güneş kadar ihtişamlı

Her göz kıskanırdı

Yoktu bir göz kıskanmayacak

Göze geldi eridi

Sıcağa değil kendine yenildi

Şimdiyse beş paralık.', 'Buzdan bir sütundu aşkımız Saf ve pürüzsüz Ay kadar güzel Görkemi namından öte Güneş kadar ihtişamlı Her göz kıskanırdı Yoktu bir göz kıskan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/buzdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Bir Sevda Takılsa Aklıma', 'ne-zaman-bir-sevda-takilsa-aklima-oguzkan-bolukbasi-npqha', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir sevda takılsa aklıma

Yorgun odalarda asılı gönüller salınırlar 

Asma yaprakları hışırdar üzüm üzüm ağustos akşamlarında

Omuzuna konmuş bir el gibidir gözbebeklerin sıcacık

Tüter durur burnumda deniz kenarları

Şehrin limana yanaşmış hali 

Dalgaları kımıldatır usulcacık

Sevda yanaklarımda gezinir yumuşacık

Şiire dönüşür yıldızlar

Kayarken berrak akşamlarda

Her köşesine bir kafiye yerleşir

Dileklerin rüzgarındadır rotaları

Başımı başına dayamışımdır mutlaka

Elim omuzunda

Ceketim sendedir

Sen kokar akşamın sonrasında yakası

Koklarım yeniden sevdalanırım

Ne zaman bir sevda takılsa aklıma

Seni düşünürken suçüstü yakalanırım', 'Ne zaman bir sevda takılsa aklıma Yorgun odalarda asılı gönüller salınırlar  Asma yaprakları hışırdar üzüm üzüm ağustos akşamlarında Omuzuna...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ne-zaman-bir-sevda-takilsa-aklima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maddeden Maneviyata', 'maddeden-maneviyata-hicabi-ceylan-2j36g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gitmek bu kadar kolaymı

Çek git gidebilirsen

Bırakırmıyım sanıyorsun

Sen gönlümün sultanı

Sevgi bahçemin dikenli gülü

Seni ben maddeden ayırdım

Hadi git bakalım gidebilirsen

Çatma kaşlarını öyle melun, melun

Ateş olup düştün yüreğime

Deryalara kapılmışım bakarken gözlerine

Seni ben maddeden ayırdım 

Hadi git bakalım gidebilirsen

Biliyormusun artık kurtuldum bedeninin esaretinden

Ardına bile bakmadın gittiğini zannederken

Gün gelecek sende anlayacaksın

Gitmek bu kadar kolaymı

Seni ben maddeden ayırdım 

Hadi git bakalım gidebilirsen

Hicabi Ceylan', 'Gitmek bu kadar kolaymı Çek git gidebilirsen Bırakırmıyım sanıyorsun Sen gönlümün sultanı Sevgi bahçemin dikenli gülü Seni ben maddeden ayır...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/maddeden-maneviyata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Al Beni', 'gel-al-beni-murat-cobanoglu-kelebekci-cw34q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Altıncı katın terasında

Çiçekleri sulamıyorum artık.

En çok nar taneleri dökülüyor, 

Beraber kuruyoruz gibi, 

Yana yana, döne döne..

Senin için istanbul''da, 

Güneşli bir kuzey rüzgarında, 

Gel al beni.

gidelim, 

Neresi olursa, 

Nereye diye

Sormadan..', 'Altıncı katın terasında Çiçekleri sulamıyorum artık. En çok nar taneleri dökülüyor,  Beraber kuruyoruz gibi,  Yana yana, döne döne.. Senin i...', ARRAY['Türk Edebiyatı','Şiir','Murat Çobanoğlu Kelebekçi']::text[], 8.5, '{"poet":"Murat Çobanoğlu Kelebekçi","poet_slug":"murat-cobanoglu-kelebekci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-al-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Murat', 'adi-murat-bekir-mutlu-gokcesu-5w67t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceye bir düş lazım,

düşe bir kuş.

Alsın uçursun onu.

Kuşa bir sabah,

sabaha bir doğuş lazım.

Doğuşa bir gülüş,

gülüşe bir koşuş,

koşuşa bir at,

ata bir ad.

Adı Murat...', 'Geceye bir düş lazım, düşe bir kuş. Alsın uçursun onu. Kuşa bir sabah, sabaha bir doğuş lazım. Doğuşa bir gülüş, gülüşe bir koşuş, koşuşa bi...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/adi-murat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güne günaydın canlı', 'gune-gunaydin-canli-ahmet-kose-6a6ea', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamın sabah programını dinliyorum

Karmen ile birlikte

o yalanıp duruyor

şapur şupur

cırcır böcekleri bir kişi bırakmış nöbetçi

aralarından.

Hava bugünkü ilk serinliğini açtı

yaprakları hafiften dansa başladı ağaçların

değişik tınılar ufaktan ufaktan

kimi taksim

kimi kendi yöresinden

kimi akor basıyor arkadan

kimi aryalar okuyor

telefon telinde sallanarak

kuşlar korosu

yedisinde başlıyorlar canlı yayınlarına 

sabahın ekranına.

Servis elemanı gibi sincaplar

bir o ağaçta bir öbür

bir  o dalında portakalın

bir gövdesine sarılmış çamların.

Zeytin geldi şimdi

sol ayağıma sürtünerek

gitti yattı karşısına doğal düşmanının.

Ekran bugün parçalı bulutlu

zor kalkar artık güneş efendi yatağından.

Sonbaharın hüznü

bir yaylı tambur taksimi andırırken

çöküyor üstüne

aşk programımın.

24/10/03/bitez', 'Yaşamın sabah programını dinliyorum Karmen ile birlikte o yalanıp duruyor şapur şupur cırcır böcekleri bir kişi bırakmış nöbetçi aralarından...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gune-gunaydin-canli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlaşan Yüreklere', 'taslasan-yureklere-ali-osman-yilmaz-mc66e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir köy çeşmesine bakıp, 

 ''''Bu çeşme ne güzelmiş, 

  Su içecek tası yok, 

  Kırma İnsan kalbini, 

  Yapacak ustası yok’’

Diyebilen gönül, 

Yaşama sevgi katar ancak, 

Ve bir insanı kıran, bir güzelde olsa! 

Çatar kaşların, yüzün öylece bakar.

Güzellikler içinde açmaz mı? 

O güzelim sevgi çiçekleri, 

Renklerinde Hal olmaz mı? 

Sevda ateşin de pişmez mi? 

Aşklar ve aşıklar.

Sevdası için gönül, Olmaz mı? 

Hayyam’da şarap destisi, 

Neyzenin ney’inden dökülmez mi? 

Nefes, nefes, 

Veysel’in sazından bir ezgi, hepimize ders, 

Karacoğlandan kara göze yergi, 

Leylasının ardından, 

Koyun olup yayılmaz mı? Mısır’a

Taşlaşmış yüreklerde ancak, 

Sevgi gelmez hiç hatıra.

Bursa..  26.Ekim.2003  00.30 (am)', 'Bir köy çeşmesine bakıp,   ''''Bu çeşme ne güzelmiş,    Su içecek tası yok,    Kırma İnsan kalbini,    Yapacak ustası yok’’ Diyebilen gönül,  ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/taslasan-yureklere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeye Vaktim Olmadıydı', 'sevmeye-vaktim-olmadiydi-ali-osman-yilmaz-zgvha', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki ayda beni

Şair yaptınız kızlar.

Aşka aşık olmayı, 

Sizlerden birine sevdalanmayı, 

Delicesine sevmeyi, 

Siz öğrettiniz.

Bilmezdim önceleri, 

Aşk nedir, sevda nedir? 

Kavga etmekten, yaşamla, 

İnsanları ezen, köle eden

Bu düzenle.

Vaktim olmadıydı, 

Sevdayı tanımayı, 

Aşkı kana kana içmeyi, 

Sevdiğine ağıt ağıt

Aşk şarkıları yakmayı

İki ayda siz öğrettiniz kızlar

Bazen GÜL olarak, 

Bazen halay çektiren bir şarkı, 

Bazen IŞIL dayarak çıktınız karşıma, 

Hele o GRİ_MAVİ gözleriyle

Rumelinden bir güzel, 

Bir çarptı ki, sormayın, 

Felek bile döndürememişti, 

Beni böyle şaşkına.

Bursa..26.ekim..2003    03.00', 'İki ayda beni Şair yaptınız kızlar. Aşka aşık olmayı,  Sizlerden birine sevdalanmayı,  Delicesine sevmeyi,  Siz öğrettiniz. Bilmezdim öncele...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevmeye-vaktim-olmadiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Çocukları', 'gecenin-cocuklari-oguzkan-bolukbasi-mpopd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece, her sabah bir çocuk doğurur adı gündüz

Kırmızı bir acıyla ufuktan

Başını uzatır

Bence küçücük bir kızdır

Öğlene kadar büyür serpilir

Akşam olurken ölür

Doğumu gibi kırmızı bir ölümdür

Ufka gömülür

Üçyüzaltmışbeş çocuk doğurur gece

En uzun ömürlüsü haziranda

Gecenin gebe olduğunu farkeder miydiniz

Gündüze', 'Gece, her sabah bir çocuk doğurur adı gündüz Kırmızı bir acıyla ufuktan Başını uzatır Bence küçücük bir kızdır Öğlene kadar büyür serpilir A...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecenin-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Delik', 'kara-delik-turgay-kadiroglu-9ocmt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kara delikler! 

ey göğün dipsiz kuyuları! 

efkarımı de sindirebilir misiniz yorgun gözlerimden, 

evren yutan ihtişamlı kaleler! 

içimin başsız askerleriyle de savaşabilir misiniz, 

sığındığım dilekleri, 

bozduğum niyetleri, 

aşk olsun diye ödediğim diyetleri, 

görebilir misiniz siyahi gözlerinizle.

nicedir azık çantamdan bölük bölük hüzün çıkar

soframa ortak dost bulunmaz, 

azığım beni doyurmaz

ve nasılsa öldürmez...', 'kara delikler!  ey göğün dipsiz kuyuları!  efkarımı de sindirebilir misiniz yorgun gözlerimden,  evren yutan ihtişamlı kaleler!  içimin başs...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kara-delik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanal Sevgiliye', 'sanal-sevgiliye-ali-osman-yilmaz-4ipqs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rengarenk çiçekler kaplamış her yanı, 

Çevrelenmiş yeşil çimenlerle,sanki bir halı, 

İçinde kaybolmak isteyeceğimiz bir deniz yanı 

Tanrım cennetin de böylemi, güzelmi yani? 

Ortada kurulmuş mükellef bir sofra, 

Hizmetkarlar fır döner, atarlar sanki takla, 

Yeterki memnun olsun, bu cennete gelenler, 

Her şey güzel gibi, sofrada gülmekte yüzler, 

Anlatın bana, cennetiniz de böyle güzelmi erenler? 

Giyinmiş en güzel esvapları, dizi dizi laciler 

Hanımlarda en son moda eseri, abiye tuvaletler, 

karınlar doymuş tıka basa, karnını tutar gülerken eller, 

Ey  dünya malına kavuk sallıyan hanımlar beyler, 

Aynada bir bakın, doymuşmu içinizdeki  aç gönüller? 

Hanibir şarkı vardı, ağıt yakar sevdiğine, 

Bende erdim artık o boşnak güzeline, 

Kader buysa, yuh olsun, ben diyeyim bin kez 

siz deyin vallahi yetmez  yuh deyin milyar kez, 

Geç buldum çabuk kaybettim, hicran oldu hayat bana, 

vallahi tam böyle oldu, yakalandı o lanet hastalık illetine. 

kimse şaşrımasın, gül yüzünü görmedim daha, 

Ne elinden tuttum, ne saçlarını taramadım ama, 

Gönül bu, çamurların ortasında bulduğum bir pırlanta, 

Sözü söz, özü boşnak, yüzünde gri-mavi bir çift göz, 

Boy desen kleopatrayı bile çıldırtacak görse o an, 

Hani tarihler yazarya, tam bir Hürrem sultan. 

Peki görmeden nasıl edersin böyle tarif,? 

Be ahmak, seven gönüle hangi heykeltraş olur arif, 

Aslında o güzelin insan yanını etmeliyim tarif, 

Surete aşık olursan, yazarlar benide kitaba bir son 

Okuyanlar derin bir ah çeker, beklerler onlar da bir mecnun 

sonunda Erecek o zamana, tüm güzeller halinden memnun 

Son sözüm itirafımdır, dinleyin bu ahmağı, 

Görmediği güzele aşık, yandığı yer sevda ocağı, 

Her gece, her gün öper, bilmez onu dilberin dudağı, 

Türkü türkü dua eder, namaz bile kılar bu ateist, 

Duymaz kimse, anlayamaz, bu sevda ateşinde yanan ahmağı, 

sevdiceğim için yanacağım, olsun destan, vallahi değer, 

Lütfen dostlar, okuyun hani, böyle aşka ne desen değer. 

Bursa...22 ekim 2003.', 'Rengarenk çiçekler kaplamış her yanı,  Çevrelenmiş yeşil çimenlerle,sanki bir halı,  İçinde kaybolmak isteyeceğimiz bir deniz yanı  Tanrım c...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sanal-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şakaklarına Düşmüşüm!', 'sakaklarina-dusmusum-t-l-n-ayse-kayi-0qono', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şakaklarına düşmüşüm yine.

Ne kadar inkar etsen de aklındayım.

Koca şehirde 

Hep bizim sokakta yakalanmaktasın

Şakaklarına düşmüşüm yine.

Eski defterleri toplayıp getirmişsin; 

Bakmamışım.

Çileden çıkarmışım sabrımla.

Galata da aramışsın

Kağıthane’de...

Çıkmaz sokaklarda düşmüşüm aklına.

Kuşlarla haber salmışın, 

Böceklere yazıp vermişsin, 

Komşulara çalım atmışsın; 

‘Gelsin! ’ diye.

Şakaklarına düşmüşüm yine.

Öğlen paydosunda zil çalmışım, 

Tren istasyonunda bilet satmış, 

Ödünü patlatmışım korku filmlerin de...

Diş fırçanın kılları olup, batmışım.

Şeker olup, 

Erimişim bir güzel çayında.

Şakaklarına düşmüşüm yine.

Ayakkabı bağın, 

Kravatın, 

Potinlerin olmuşum...

Kuş tutmuşum ağzımla; 

Nafile! 

Şarap şişesinde balık olmuşum, 

Boğulmuşum.

Tırnaklarına bulaşmışım, 

Diline düşmüşüm...

Şehvetmişim, 

Öfkeymişim, 

Suçmuşum...

Şakaklarına düşmüşüm yine!', 'Şakaklarına düşmüşüm yine. Ne kadar inkar etsen de aklındayım. Koca şehirde  Hep bizim sokakta yakalanmaktasın Şakaklarına düşmüşüm yine. Es...', ARRAY['Türk Edebiyatı','Şiir','Tâlân Ayşe Kayı']::text[], 8.5, '{"poet":"Tâlân Ayşe Kayı","poet_slug":"t-l-n-ayse-kayi","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sakaklarina-dusmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün Kutlu Olsun Anne', 'dogum-gunun-kutlu-olsun-anne-nevin-kalafatoglu-hitw6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen  ne kadar guzel bir kadındın...

bakardım uzun uzun sana minnacıktım... 

gozumu guzelliğin bürürdü...

o kosturman o telasın o sevgin...

sevilendin...

bazen acı olurdu sozlerin... gerçektiler cunki...

uyutulmus beyinler anlamazdı seni...

yorardın kendini... üzülürdün benim gibi...

okulun meleği derlerdi oğrencilerin.... 

babamın bakıslarını yakalardım bazen sana...

içim dolardı... sevinçle...

oylesine ask dolu laciverte yakın mavı gozleri vardı...

sen her zamanki asaletinle... soyle bir gözünü süzerdin...

bir naz bakışı yakalardım... bal rengi gözlerinde...

dudaklarına bazen kırmizi bir ruj surerdin...

bir film artıstı kadar gorkemli olurdun... 

guzelliğin çikardı hafif dekoltelerinden...

uç çocuk doğuran muhtesem kadın...

bize ne fedakar anaydın... 

sen ornek olurdun  anadoluya...

kadınlar dolusurdu hep etrafına  anlatırdın..

hayatın gerçeklerini onlara.. kurallarla...

çeyizler yapardınız mutluluklara...

gelinlikler dikilirdi atölyelerde...

sen benim canım annem... sen olmasaydın ben

yaşarmıydım diye sarıldım sana bu sabah

gri beyaz olmus saçlarını sevdim.. sen hala cok guzelsin.. 

bugun optum optum kokladım... seni...üç kisilik

iki damla goz yaşı döktük birlikte..bu sabah

yaşadıklarımıza... direncimize...  sevgimize...

Beydağlar''ına karşı ağladık......iyi doğdun anneciğim...

Doğum Günün Kutlu Olsun... 

ya sen olmasaydın... bana veremeseydin gönlündeki aşkı...

ben bu  şiiri  mümkün değil.... yazamazdım...

26.10.2003

Sevgili annem Mübeccel Kalafatoğlu''na', 'sen  ne kadar guzel bir kadındın... bakardım uzun uzun sana minnacıktım...  gozumu guzelliğin bürürdü... o kosturman o telasın o sevgin... s...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dogum-gunun-kutlu-olsun-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadi Ceylan', 'olmadi-ceylan-huseyin-poyraz-apwnj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her yolu denedik gulelim diye

Annen istemedi olmadi Ceylan

Bir soysuz elinde donduk kediye

Bi turlu cilemiz dolmadi Ceylan...

Gencligim boguldu bir kasik suda

Sirtim hancer yedi tatli uykuda

Felek yatagina iti koydu da

Bizi kapisina almadi Ceylan...

Kader de bezmedi beni ezmekten! 

Sansim usanmadi dudak buzmekten! 

Hayalinle diyar diyar gezmekten

Bu can bir kez olsun yilmadi Ceylan...

.....kizima', 'Her yolu denedik gulelim diye Annen istemedi olmadi Ceylan Bir soysuz elinde donduk kediye Bi turlu cilemiz dolmadi Ceylan... Gencligim bogu...', ARRAY['Türk Edebiyatı','Şiir','Huseyin Poyraz']::text[], 8.5, '{"poet":"Huseyin Poyraz","poet_slug":"huseyin-poyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olmadi-ceylan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Strana Bajarê Bê Hîs', 'strana-bajar-b-h-s-r-nas-jiyan-yvtc7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“Şev bû...

                      bajarekî bêdeng û dev bû

                      canê te bi girî re li hev bû”

                                     Ehmed Huseynî

1.

wexta te 

lê dixist

û diçûyî

min dixwest

ji kûrkûra dengê giriyê xwe

stranekê ji te re çêkim

û ji kûrkûra temama giriyê bajêr jî koroyekê

çi bikim

ez ne mûzikjenekî binamûs bûm

ew bajarê tu jê direviya jî

ji xwe ji koroyeke kezebşewat pêk nedihat

nizanîbûn reşêşkên rondikan bibarandana

di nav wan de

min girêk li giriyê xwe xistibû

kanî strana te jî ji melodiyên giriyan çêdibû

bi ser neketim, bibore, çênebû

çavên min birijin

bê stran bimînim

ku min tu bê stran şandî

2.

wê wextê

bi xezeb

li vî bajarî

ez bi efara evîna te ketim

çiqas ken û maçên te hebûn

min zû zû civandin ji bajêr

nebêje çima

çavên min bar nebû

ku ji wan re bihêlim

lê dîsa jî

min hinek dil

kirin sedeqa evîna xwe û te

û min li bajêr belav kirin

tu zanî pê

bê çi bû

bajar dîn bû

û bi çolê ket

çû û çû....', '“Şev bû...                       bajarekî bêdeng û dev bû                       canê te bi girî re li hev bû”                               ...', ARRAY['Türk Edebiyatı','Şiir','Rênas Jiyan']::text[], 8.5, '{"poet":"Rênas Jiyan","poet_slug":"r-nas-jiyan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/strana-bajare-be-his-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Haldeyim ki', 'oyle-bir-haldeyim-ki-ali-osman-yilmaz-p7o6r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle bir haldeyim ki, 

Yüklü canım kendi olgun meyvasıyla, 

Yüklü canım meyvasıyla.

Kim şimdi  gelecek ve yiyecek ve doyacak? 

Canım kendi şarabını taşıyor.

Kim şimdi döküp içecek ve çöl ateşini serinletecek? 

Bir ağaç olaydım çiçeksiz ve meyvasız

Çünkü bereketin ağrısı daha keskin çoraklıktan, 

Ve hiç kimsenin almayacağı zenginin acısı

Büyük kimsenin vermediği dilencinin kederinden.

Bir kuyu olaydım kuru ve kavruk

                                           İnsanların içini taşladığı

Çünkü böylesine dayanmak daha iyi ve kolay

                                           Yaşayan bir su kaynağı olmaktan

Gelip geçecek ve içmeyecekse insanlar, 

Ayaklar altında çiğnenmiş bir saz olaydım keşke, 

Çünkü daha iyidir gümüş telli bir lir olmaktan 

Ev sahibi parmaksız, 

Ve çocukları sağır bir evde, 

Sevgiliye ulaşamayacaksam, 

Niye yol olayım gidemeyeceksem, 

Derin bir yar olaydım deniz kıyısında, 

Sevgilisine ağıt yakanların 

Sevda Şarkıları söylediği, 

Kulakları duymayan, gözleri görmeyen

Dilleri suskun bir koca adam olaydım, 

Sevdiğine ulaşamayacak olacağıma.

Bursa...20  Ekim..2003', 'Öyle bir haldeyim ki,  Yüklü canım kendi olgun meyvasıyla,  Yüklü canım meyvasıyla. Kim şimdi  gelecek ve yiyecek ve doyacak?  Canım kendi ş...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/oyle-bir-haldeyim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ömür Böyle Geçti', 'bir-omur-boyle-gecti-ozcan-nevres-1xm1t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir Ömür Geçti Gitti

Bir ömür geçti gitti 

Maslağın suyu gibi boşuna 

Dönüpte geriye ne kaldı diye baktım da 

Hüzün elem ve yitilmişlik 

Hepsi de orada 

Mutluluğu aradım 

Göremedim aralarında 

Sorguladım geçmişimi 

Hiç mi mutlu olmadım diye 

Geçmişim yanıtladı 

Mutluluk senin neyine 

Sen acıların insanıydın 

Her olumsuzluğa yanan 

Sen acı duyardın 

Yoksulluğu yaşayanlardan 

Ve hastanelerden kovulan zavallılardan 

Hep koştun olumsuzlukların kapılarını kırmak için 

Bir, bir 

Kıramadıklarınla kırıldın, 

Umarsızlığına ağladın 

Yoksulluğu yaşadın, yoksullardan beter 

Şiirler yazdın yokluklar ve yolsuzluklar üstüne 

Anlayan çıkmadı, 

Bir de deli dediler üstüne 

Mutluluğu kendin yok ettin 

Yıkma benim üstüme 

Doğruyu söyler geçmişim, 

Alınmam niye 

Bankalar hortumlanmış, 

Yatağan dumandan boğuluyor 

Bergama’da siyanür kavgası 

Silivri’de beş yıldızlı cezaevi yüzünden 

Bin dönüm arazi elden çıkacakmış 

Sana ne 

Hava alanlarında yok edilmiş en verimli topraklar 

Arsa diye betonlaşan bahçeler kan ağlar 

Dersin ki gelecektekiler bizi 

Lanetleyerek anacaklar 

Sen değilsin bunca olumsuzlukların sorumlusu 

Hani başka isyan edenler nerede 

Boşuna dememişler 

Bu dünya iki kulplu bir kazan 

Tut bir sapından ki sen de kazan 

Tutan tutmuş, kazanan kazanmış 

Sen ve senin gibiler yaya kalmış 

Hani derler ya sen bu kafayla gidersen askere 

Nah! ! ! ! Alırsın teskere 

Varsıllar sömürmüş ülkeyi 

Hani yoksulların isyanı nerede 

Kader demişler yoksulluğa 

Yoksulunki kaderse 

Varsılınki ne 

Yorma kafanı bu düzen böyle kurulmuş 

Böyle gider 

Çırpınma boşuna 

Günü gelip son nefesini verdiğinde 

Tüm çileler biter iz bile kalmaz geride 

Bu dünya düzensizlikler 

Ve düzeysizlikler üstüne kurulmuşsa 

Sana ne be adam, hadi söyle sana ne 

Doğruydu geçmişimin tüm söyledikleri 

Yanlışmış tuttuğum yol bilemedim 

Doğruları defterimden silemedim 

Defterim doğrularla dolmuş, 

Yanlışa yer veremedim 

Böyle gelmiş bu dünya, 

Böyle gidermiş bilemedim 

Özcan Nevres 10 - 07 - 2001 

Özcan Nevres', 'bir Ömür Geçti Gitti Bir ömür geçti gitti  Maslağın suyu gibi boşuna  Dönüpte geriye ne kaldı diye baktım da  Hüzün elem ve yitilmişlik  Hep...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/bir-omur-boyle-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-i-srafil-yildizkan-tvoxu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Az önce yağdı yağmur.

Çamura bulandı toprak.

Küçücük bir beden, 

  Yağmurun altında.

-Ayaklar yalın

-Saçlar darmadağın.

Bir elinde; 

Kuru bir dilim ekmek.

Diğerinde; 

Çamura dönüşmüş toprak.

Anıtlaşmış, köyün ortasında.

Güneş yansır, yağmurun ardı sıra.

Aydınlatır ak yüzünü, 

Belirir yüzündeki hüznü.

Bedenine yayılır; 

Çamurun soğuğu, 

Güneşin ısısı.

Bir damla yaş oluverir gözlerinde

Damlar…

Yağmurdan kalan son damla

Gözleinden toprağa; 

Çamur ile bütünleşir

Göz yaşları, yalın ayakları

Ve bir dilim kuru ekmeği…', 'Az önce yağdı yağmur. Çamura bulandı toprak. Küçücük bir beden,    Yağmurun altında. -Ayaklar yalın -Saçlar darmadağın. Bir elinde;  Kuru bi...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Yıldızkan']::text[], 8.5, '{"poet":"İsrafil Yıldızkan","poet_slug":"i-srafil-yildizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yagmur-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirler Beyinin Susturuculu Aşkı', 'siirler-beyinin-susturuculu-aski-goktu-kara-5oze0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kış geliyor artık  uyanma zamanı şiirler beyinin

yaz boyunca elinde tuttuğu gül solmuştur

gereksinimi vardır taze bir güle

ama kim verecek ona bu gülü 

Süreyya mı

susmuş kış rüzgarları

Süreyya ağlamış

dinmek bilmeyen gözyaşları şirler beyinin kapısının önüne gelmiş

şiirler beyi yataktan kalkmış

elindeki gülü ufalamış gözyaşı ırmağına

takip etmiş gül tozlarını

görmüş kırmızılar içinde Süreyya''yı

tutmuş ellerini

bir daha da hiç bırakmamış', 'kış geliyor artık  uyanma zamanı şiirler beyinin yaz boyunca elinde tuttuğu gül solmuştur gereksinimi vardır taze bir güle ama kim verecek o...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/siirler-beyinin-susturuculu-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaşa Karşı Savaş', 'savasa-karsi-savas-ali-ziya-camur-byhek', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeni bir savsöz

Dillerde bayrak açıyor:

Açlığa karşı savaş! 

Ölüme karşı savaş! 

Savaşa karşı savaş! 

Payanda olmak yok

Artık düşsel öykülere, 

Aşılmalı bu duvar.

Gerekirse

Zulamızda ölmek var, 

Yıkana dek

Doların ve yuronun saltanatını.

Savaşın kararttığı coğrafyada

Sabrın yakıldığı fenerler, 

Muştu yeni zaferlere.

Gözlerin inanç yüklü izlerinde, 

Soluklar, 

Hazırlanıyor yeni türkülere; 

Gizlerinde

Yeni tırmanışlara gebe doruklar.

Sapanların bağrına

Kendini çeken canlar, 

Çektikçe pimini öfkenin, 

Birer birer de olsa dökülüyor

Beş köşeli, altı köşeli 

Köşeleri hançerli kara yıldızlar.

Ey 

Sabrın yatağında demlenen umut! 

Çıkar bağrından artık

Kasırgaları.

Yakarak  mistisizmin yapraklarını, 

Tutuştur küllerinden

Yeni şahlanışların 

Zafer şafaklarını! ...', 'Yeni bir savsöz Dillerde bayrak açıyor: Açlığa karşı savaş!  Ölüme karşı savaş!  Savaşa karşı savaş!  Payanda olmak yok Artık düşsel öyküler...', ARRAY['Türk Edebiyatı','Şiir','Ali Ziya Çamur']::text[], 8.5, '{"poet":"Ali Ziya Çamur","poet_slug":"ali-ziya-camur","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/savasa-karsi-savas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benimsin', 'sen-benimsin-muammer-celik-g7e2d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim sabahımda okşadığım tan yerim 

Sen benim gecemde beklediğim seher yelim 

Siirim, duygum, kuzey yıldızımsın, yol gösteren 

Sen benim gündüzümde dolaştığım şehrim 

Sen benim gecemde sayıkladığım yavuklum 

Düşüm, rüyam, hayalimsin geleceğime yön veren 

Sen benim gündüzümde gezdiğim gönülbahçem 

Sen benim gecemde topladığım şebnem damlam 

Arım, balım, peteğim, kanımsın bana CAN veren 

Sen benim gündüzümde özümsediğim sevdam 

Sen benim gecemde yattığım döşeğim, yatağım 

Yastığım, yorganım, çarşafımsın üstümü örten 

Sen benim gündüzümde aşk yaşadığım gecem 

Sen benim gecelerimin karanlığında mehtabım 

Güneşim, yıldızım, nur’um, ışığımsın içimi aydınlatan 

BirDeli

02.04.2003', 'Sen benim sabahımda okşadığım tan yerim  Sen benim gecemde beklediğim seher yelim  Siirim, duygum, kuzey yıldızımsın, yol gösteren  Sen beni...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-benimsin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat Ne Zaman', 'vuslat-ne-zaman-muammer-celik-q9of8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çatlıyor uçuklamış dudaklarım 

Parlıyor sevdalanmış gözlerim 

Sevgine, sıcaklığına hasretim 

terine, tenine vuslat ne zaman..? 

Şaşıyor delirmiş, çılgın aklım 

Terliyor yüzüm ve gözlerim 

Ruhuna, yüreğine hasretim 

Nemli bedenine vuslat ne zaman..? 

BirDeli

yaz-2002', 'Çatlıyor uçuklamış dudaklarım  Parlıyor sevdalanmış gözlerim  Sevgine, sıcaklığına hasretim  terine, tenine vuslat ne zaman..?  Şaşıyor deli...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vuslat-ne-zaman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm ve Aşk', 'olum-ve-ask-mustafa-tanrikulu-e4439', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar dokundu son kez saçına

Yüzünden çekildi kan yavaş yavaş.

Kim derdi gurbette ve bir başına 

Verir Azrail''e can yavaş yavaş.

Gurbet ehli uzak gitme beri gel...

Garibleri kapar ateşten bir sel

Ger iterse seni ateşe bir el

Çıkma o ateşten yan yavaş yavaş.', 'Bir rüzgar dokundu son kez saçına Yüzünden çekildi kan yavaş yavaş. Kim derdi gurbette ve bir başına  Verir Azrail''e can yavaş yavaş. Gurbet...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olum-ve-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk Kuyu', 'kirk-kuyu-mustafa-tanrikulu-4yer6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derince kırk kuyum var kırkının acı suyu 

Kırk damlada bir yılan çıkarır budur huyu

Beni ağularlar her yudumda bir tat da alamam

Yere batsın fayda vermeyen kırk tane kuyu.', 'Derince kırk kuyum var kırkının acı suyu  Kırk damlada bir yılan çıkarır budur huyu Beni ağularlar her yudumda bir tat da alamam Yere batsın...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kirk-kuyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah', 'allah-mustafa-tanrikulu-4ka6t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalem bîçare, lisan bîdevran ve akıl sakin

Anlatılmazsın yarabbim...

Ne ilmelyakin ne aynelyakin

Ancak kendini sen anlatırsın kuluna

Yoksa ilmi yetişemez  buna...

Kulun cahildir...', 'Kalem bîçare, lisan bîdevran ve akıl sakin Anlatılmazsın yarabbim... Ne ilmelyakin ne aynelyakin Ancak kendini sen anlatırsın kuluna Yoksa i...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/allah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-mustafa-tanrikulu-ny41b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kahrın da güzel ama 

Rahmetin daha güzel

Rahmeyle sen bana da

Bana Rahman-ı ezel

güzelse sen demişsin

çirkinse sensin diyen

olur muydu güzellik

güzel olmasaydın sen

güzelsin ki yarattın

yaratığını güzel

sen Halık-ı mahlukat

sensin tek büyük güzel', 'Kahrın da güzel ama  Rahmetin daha güzel Rahmeyle sen bana da Bana Rahman-ı ezel güzelse sen demişsin çirkinse sensin diyen olur muydu güzel...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzel-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamıyorum Köyümü', 'unutamiyorum-koyumu-muammer-celik-p3qxh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Köyümdeki otlaklar

otlattığım kuzular, oğlaklar 

ve topladığım kirçiçekleri 

tütüyor burnumda çocukluk aşkım 

Ayse’mi unutamıyorum...

Ahhh…  Ayşe ah... 

Tarla lalerinin içinde 

kanat geren kolların 

uçuyor adeta örüklü sacların 

uçurtma kuyrugu gibi arkanda 

hiç gitmiyor gözlerimin önünden

yamaçlardaki koyun sürüsü 

ovadaki sığırlar tütüyor burnumda... 

Oynaşan çocuklar arasında yokum 

ufuklarda kalırdı hep gözüm 

verdiğin bir salkım üzüm

unutamıyorum seni halen, dostum…

Untamıyorum bembeyaz bulutları 

güneş parlıyorken yağan yagmurları 

tüm gövdemizi saran toprak ve çamurları 

bereketli pekmez ile yediğimiz karları 

elinde tırpanla gelişini babamın 

testilerle edalı yürümesini anamın 

unutamıyorum, unutamıyorum, unutamıyorum hala..! 

Bağlı kaldığım yataktan o köyün görünüşünü 

sığırtmacın torbasında sakladığı azığını 

çobanın heybesinde getirdiği körpe kuzuyu 

özlüyorum, burnumda tütüyor belek belek saçların 

Çiğdem çiçeklerinin kar altından gösterdiği başların''... 

Çelik çomak oynayan çocugun; 

”yandım anam gözüme geldi” diye çığlığını 

yaz gününde yorgan altından bakışlarımı 

yeşil gözlerimden cisil cisil akan yaşlarımı 

önümde oynaşan çocuklara saldığımı 

hayalimdeki çocukluk aşkım Ayşe''mi 

gözümde bebeğim, 

hayalimde kadınım 

burnumda tütüyor tezek kokan ellerin…

”Amanıııın, yetişin dostlar, komşular, 

kızımı kaçırıyorlar, dürzüler, deyyuslar”

diye bağıran, çığlıklar atan kadını 

silahını kapmasıyla koşan orta yaşlı kocasını 

bastonu ile merkebe vuran ak sakallı dedeyi

nakış nakış, renk renk yün çorap ören nineyi

manda kaymağında yüzen yaramaz oğlanı 

birde ayaklarım yoktu, yürümeyi özlediğim günleri 

kirçiçeklerini, kardelenleri, otlaktaki kuzuları 

yamaçtaki sürüyü, tarladaki laleleri, oğlakları 

gönlümdeki Ayse''yi unutamıyorum, 

ve hiç bir zaman unutmayacağım Arkadaşım...! 

BirDeli

2/11/2000', 'Köyümdeki otlaklar otlattığım kuzular, oğlaklar  ve topladığım kirçiçekleri  tütüyor burnumda çocukluk aşkım  Ayse’mi unutamıyorum... Ahhh… ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/unutamiyorum-koyumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-sair-i-stambul-drxd7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana geldim içim ümitlerle dolu, 

Beni sarhoş etme istanbul neolur, 

Bir gun bende eririm caddelerinde, 

Çürür kemiklerim adım unutulur, 

Yine sen kalırsın, dipdiri sımsıcak, 

Göğün, bulutların, denizlerin kalır, 

Oynama istanbul benimle oynama, 

Bir gün öldürür beni bu dert bu kahır, 

Ezilmiş ellerimin arasında başım, 

Bu yer yüzünde başka çarem kalmamış, 

İşte gelip kapılarına dayanmışım, 

Karşında yıkılmış bir duvar gibiyim, 

Beni sarhoş etme başım dölnüyor, 

Üstüme varma istanbul kederliyim.', 'Sana geldim içim ümitlerle dolu,  Beni sarhoş etme istanbul neolur,  Bir gun bende eririm caddelerinde,  Çürür kemiklerim adım unutulur,  Yi...', ARRAY['Türk Edebiyatı','Şiir','Şair İstambul']::text[], 8.5, '{"poet":"Şair İstambul","poet_slug":"sair-i-stambul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istanbul-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fatihadan İlhamla Münacaat', 'fatihadan-i-lhamla-munacaat-mustafa-tanrikulu-6rivc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ya rabbim

senin isminle başlarım duama

sen ki rahimsin

kullarını nar-ı azimden kurtaransın

rasulünün eliyle şefaati sunansın

günahlarla kapına dayandığımız gün

bizi sonsuz merhametinle bağışlayansın

sana şirk koşmazsak  eğer

bizi cennette sonsuzlaştıransın

sen rahimsin

senin isminle başlarım duama

sen ki rahmansın

affedersin bizi dünya yüzünde

biz doğru dürüst yürümesek de

resulünün izinde

sen tekrar tekrar  lütfedersin rahmeti

bizden almış hazinene kaldırmışsın zahmeti

esman rahmle tecelli eder tekrar tekrar

hem vermişsin bize bir hayat, 

hem hayatın sonunda yine bir sonsuzluk var...

sen  rahmansın

ve hamd sanadır, hamd senin elindedir

alemlerin terbiyesi, 

“olmak” ya da “olmamak” senin dilindedir

ağaçlar emrinle nakışlanır

nurunla aydınlanır yıldızlar

mü''minler seni tanır

mahlukat  seni bilir sana yalvarır

sen hamidsin

ve sen rahman ve rahimsin...

gün gelir yıldızlar dökülür

ve yürütülür dağlar.

Ne yavru ana için

ne ana yavru için ağlar

güneşin ışığı söner..., , , 

işte  o gün

işte o muhteşem gün

her şey aslına döner...

ve sen o günün de sahibisin

biz seni  ma''bud bildik...

sana açılmıştır ellerimiz.

Bizden daha iyi bilirsin ki

Biz ancak sana ibadet ediciyiz.

Sen ki Muin-ı hakikisin

Biz de nusretine muhtacız

Yardımı da ancak senden isteriz...

Ya rabbim

Bizi dünya yüzünde

Dosdoğru bir yol üstünde yürüt.

Öyle bir yol ki

Üstünden daha önce bütün resuller ve nebiler geçmiş olsun

Öyle bir yol ki

Bütün  velilerin ayakları bu yolda toprağa değmiş olsun.

Öyle bir yol ki

Salih  kişiler bu yolda sevmiş ve sevilmiş olsun

Ve öyle bir yol ki

Aşkınla yananlar bu yolda delirmiş olsun.

Bize nebilerin velilerin salihlerin ve aşıkların yolunu nasip et

Sen onlara nimetini verdin

Bize de ver

Ve bize o yolu verme ki

O yol cehenneme gidiyor.

O yol ki

Musa''ya hain olanların yoludur.

Gazabınla doludur.

O yol ki

İsa''nın yolundan sapanlarındır.

Hatem-i mürselini kabul etmeyenlerindir..

Onlar sapıklıktadır.

bize o yolu verme Ya rabbim', 'ya rabbim senin isminle başlarım duama sen ki rahimsin kullarını nar-ı azimden kurtaransın rasulünün eliyle şefaati sunansın günahlarla kapı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/fatihadan-ilhamla-munacaat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Götür', 'gotur-mustafa-tanrikulu-yc8vs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bad -ı saba  bu şerbeti

Dallardan meyvaya  götür.

Zor geliyor yar hasreti

Mecnun’u leyla’ya götür

Ben ki  nehirde bir sazdım

Ney oldum  inledim  azdım

Uzunca bir name yazdım

Uçur da sılaya götür...

Bad-ı saba bil  sen   seni

Pek erklisin  bilsen seni

Tut kolumdan fırlat beni

Beladan belaya götür.

Göğe çıktı feryadımız

Kul Mustafa''dır   adımız

Allah bizim maksadımız

Kaldır da mevlaya  götür', 'Bad -ı saba  bu şerbeti Dallardan meyvaya  götür. Zor geliyor yar hasreti Mecnun’u leyla’ya götür Ben ki  nehirde bir sazdım Ney oldum  inle...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gotur-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyor Seni', 'seviyor-seni-mustafa-tanrikulu-c4lwx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu şehrin en filinta delikanlısı

Elinde Zülfikar-vari bir kılıç

Kalbinin kapısında bekliyor

Çekmiş kılıcını  kalbine yaklaşanların

İndirmek için kafalarını omuzlarından...

Seviyor bir de seni mecnunane

İsmini söyleyemiyor  bir de...

Yalnızca  seviyor yalnızca  seviyor

İçinde  bir ukde olmuş sevdan..

Mes’ut değil, mahzun değil...sadece seviyor.

Kaldırıp da  başını bakamıyorsa da gözlerine

Aşkını söyleyemiyorsa da seni seviyor

Lambaların sönmesini bekliyor

Bakmak için elifî  endamına

İkliminde bu belalı şehrin...

Nasıl söyleyeceğini bilmiyorsa da

İki  büklüm oluyorsa da kalbi

“Niçin”e cevap veremiyorsa da

Seviyor seni  ezilircesine

Ellerinden tutmak değil arzusu

Vallahi öpmektir ellerini

Güzellik gibi güzelsin

İspat edilmiştir güzelliği kalbinin

Lalede gülde bir de nun’da vav’da re’de

İşte bunun için seviyor seni', 'Bu şehrin en filinta delikanlısı Elinde Zülfikar-vari bir kılıç Kalbinin kapısında bekliyor Çekmiş kılıcını  kalbine yaklaşanların İndirmek ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seviyor-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözmek', 'cozmek-ali-ziya-camur-5yfp5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir avuçluk nefesin parmaktaki izini görmek, 

Örmek gümüşlü sabahlara gecede yamalı ışıltıları.

Kıvılcım suretinde gülde tutkuyu sezmek.

Ateşin azarında suyu yangına çekmek, 

Dökmek fenersiz gecelere devingen okyanusları.

Aymazın tespihine direnci dizmek.

Gül zamana asılan sabrın kilidini kırmak, 

Haykırmak en yeğin bulutlara çelikten istemleri.

Acıdan ve karadan fona top top karanfil çizmek.

Zulmün kara kaftanını yedi yerinden yarmak, 

Sarmak gökkuşağına en renkli umutları.

Ağıt torbasının ağzını büzmek.

Nara vuran sancıyı güz aynasında duymak, 

Yaymak gökyüzü sofrasına nakışlı ezgileri.

Ölümün köpüklü pıhtısından yaşamı süzmek.', 'Bir avuçluk nefesin parmaktaki izini görmek,  Örmek gümüşlü sabahlara gecede yamalı ışıltıları. Kıvılcım suretinde gülde tutkuyu sezmek. Ate...', ARRAY['Türk Edebiyatı','Şiir','Ali Ziya Çamur']::text[], 8.5, '{"poet":"Ali Ziya Çamur","poet_slug":"ali-ziya-camur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cozmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hükümlü-Hükümsüz', 'hukumlu-hukumsuz-ahmet-aksoy-9goem', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman ağartırken 

Eski günahları

Binlerce ölü mahkum

Hüzünlenir

Ve tükürürler

Yanlış zaman

Yanlış yer denklemlerine

Ki onlar

Giydikleri hüküm

Henüz eskimeden üstlerinde

Apar topar yollanmışlardır

Bir ipin ya da bir baltanın ucundan

Başka bir hükme...', 'Zaman ağartırken  Eski günahları Binlerce ölü mahkum Hüzünlenir Ve tükürürler Yanlış zaman Yanlış yer denklemlerine Ki onlar Giydikleri hükü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hukumlu-hukumsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürükleniş', 'suruklenis-ahmet-aksoy-ox2dm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çengelli bir iğneye takılmış

Herhangi bir ip gibi takipteyim

Ve dikiş tutmuyor zemin

Bu yüzden sürüncemede akıbetim

Ki mesele değerinden yoksun

Benim için, yılmak ya da yılmamak

Çengelli bir iğne geçmiş etime

Sürüklüyor beni ritminde

Kurtuluş belirtiden uzak, belirsiz

Bir ip gibiyim bir ucum çengelde

Diğer ucumsa zaman tarafından

Tutuşturulmuş, bu yüzden tükeniyorum

Ve bekliyorum; tükenmeden ömrüm

Tutunmayı herhangi bir zeminde

Yoksa geçirdiğim işkence

Daha bir ağır daha bir beyhude.', 'Çengelli bir iğneye takılmış Herhangi bir ip gibi takipteyim Ve dikiş tutmuyor zemin Bu yüzden sürüncemede akıbetim Ki mesele değerinden yok...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/suruklenis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Doğuş', 'yeniden-dogus-osman-velioglu-oncs5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben; bir aşk-ı memnu, bir yasak vuslat, 

Bir nisyan-ı mutlak noktasındayım... 

Sen ağla yüreğim, maziyi ıslat. 

Seyyare-i efkâr ukdesindeyim.... 

Ruhumun en asi, yoz tarafından 

Beynimin içinde arzı sallarım. 

İndirip ömrümü altın rafından 

Günleri, ayları çöpe yollarım... 

Sevdamı sevginle yargılayarak, 

Gönlümü müebbed mahkumu kıldım. 

Unutturdum, içim kan ağlayarak; 

Farzet ki dünyaya ben yeni geldim....', 'Ben; bir aşk-ı memnu, bir yasak vuslat,  Bir nisyan-ı mutlak noktasındayım...  Sen ağla yüreğim, maziyi ıslat.  Seyyare-i efkâr ukdesindeyim...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeniden-dogus-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğacak Çocuğuma Şiir', 'dogacak-cocuguma-siir-zeki-ergin-itqfs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'türkülerle

ağıtların 

birbirine karıştığı bir zamanda

bir çığlık atacaksın dünyaya

toprakta patlayan tohumun

sevincini yaşayacaksın

ve ben seni

yeni açan bir çiçek gibi karşılayacağım

ve de okşayacağım birkaç saçını

yüreğimde dereler çağlarken

gül kokan dudaklarından

ananın ak sütü dökülürken

anlayacaksın

başlamıştır kavgan

ve yılmadan yürüyeceksin yolunu

ine çıka

düşe kalka

yüreğinde sönmeyen

umutla

_üsküdar 1977

_numune sayı: 3 may03 

_sevgiliye isyan yt:haz04', 'türkülerle ağıtların  birbirine karıştığı bir zamanda bir çığlık atacaksın dünyaya toprakta patlayan tohumun sevincini yaşayacaksın ve ben s...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dogacak-cocuguma-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gören Körler', 'goren-korler-muammer-celik-9mrhc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kör talihe

Kör bir kurşun sıktım

Geldi vurdu beni alnımdan…

İnsan yapılı kör Şeytan

Geldi boğazıma oturdu Hafakan…! 

Kör kurşun arkasında iki göz

Üstünde bir arpacık birde gez

Tetikteki parmak insafsız

”ÇEK” diyen düsünceyedir

tüm itirazımla tüm isyanım…! 

BirDeli

26.10.2003', 'Kör talihe Kör bir kurşun sıktım Geldi vurdu beni alnımdan… İnsan yapılı kör Şeytan Geldi boğazıma oturdu Hafakan…!  Kör kurşun arkasında ik...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/goren-korler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pastırma Sıcakları', 'pastirma-sicaklari-cem-ucar-6qw28', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pastırma sıcakları zamanı şehrimde... turşusunu yapamayanlara son elveda vakti; yemiş daha pahalanmadı. Bi de yazdan nasibini alamayan aşıklar için turfan mevsimi. Geç kalmışlara atfedilen güneş; saçlarını dağıtan hatunun yapay buklelerine zorla da olsa bir tutam hareket veriyor. Çok şükür diyoruz... Bunun da yokluğunu bilenlerdeniz.  Ama öyle uzaktan, sanki nispet yapar gibi, hem de başkalarının yanında olmuyor ki.

Bu sıcaklar her sene olur şehrimde... Ama aynı nehir de iki kere yıkanamıyoruz ya; işte belki bu yüzden, belki de elimizde olmayan sebeplerden dolayı bu sene daha bir pastırma sıcaklığı var şehrimde. Biraz daha yorucu, biraz daha her kelimemin arasına virgül koyuyor. O lodoslu ünlemlerimi yitiriyorken ve saçlarımdaki dökülmenin logaritmik olarak arttığı bu sene, sıcaklar içime içime esiyor şehri kuru havasını. Rüzgarı olup da, yelken bulamayan modellerden de değiliz ama dedik ya virgüllerle olmuyor ki. Nasıl bir doğumu, bir doğum çıkışını bekleyeni, bir bayrağın dalgalanışını, yada bir kurtuluş savaşını ünlemler olmadan anlatamazsak, bu sene sıcakları anlatmak o kadar olanaksız. 

Tabii ki söylenebilir; telaffuz edilebilir. Ama sevda dedikten sonra; virgül koyarsan o sevda olmaz ki! Bırak virgülü boşluk bile bırakmadan devam edecesin haykırmaya. Güzel Türkçe’nin yapım eklerinden ekleyeceksin sonuna. Sevdam, sevdalım diyeceksin. Hatta haykıracaksın. Ama fark ediyorum ki; saçların azalması ses tonuna da etkiyor. Ama problem bu değil. Yürek sevdam diye haykırırken, azın bunu sadece konuşuyorsa. O zaman gırtlağın parçalanmaya mahkumdur. Ama öyle ki gırtlak da parçalanmaya çoktan razı.

Bütün bunlara ek; dünyada kurulabilecek en acımasız, en küstah cümleyi, en tek kelimelik ve en mahcup cümleyi kuracaksın. Sevdalımsın. İşte o zaman etrafında kimsenin kanı damarlarına sığamayacak. Karşında ki yüzüne bakamayacak, eve gitmek hiç bu kadar zor olmayacak, ayakların seni onun evine götürürken, sen kalkıp sonra tekrar oturacaksın. Ve bi daha bekli de; yüzüne bakamayacaksın. Bir daha olursa tabi, sen de onu yüzüne bakamayacaksın.

O zaman sevda girmesin kapımdan içeri. Diyebilir misin? Bırak kapını; ciğerlerinden içeri girer. Öyle yüzsüzdür ki. Davet edildiği yere gitmez, davet edilmeği kapıdan da dışarı çıkmaz. Bi de ukalaları duyarsın, aşk dediğin nedir ki? Derler. Arkanı dönüp lafla peynir gemisi yürüseydi Macellan ömründen ömür yemezdi, Piri Reis o haritaları alafranga tuvalette şamdan okurken de çizebilirdi demene gerek yok. 

Sonra sabah olacak, kalbim vücudunu yadırgayacak. Evden kalbimi eline alıpta çıkacaksın. Karşısına gideceksin ve tek Al! diye, ünlemi ağır bir cümle kuracakken, hoca koridorun ortasına gelmiş olacak ve sen elinde bir poşet dosyanın içine konulmuş bir ödevle sınıfa gireceksin. Oda senin defterinin arasına koyduğun notu senin gözlerinin önünde  yırtacak ve çöpe atacak. Ve sonra yanında oturak elemanı akşam yemeğe çağıracak. Dışarı çıkınca bi çilim sigara için elini cebine attığında sigaranın bittiğini fark edeceksin, rakı şişesinin dizaynı konusunda bir arge çalışması için de yeterli öz kaynak olmadığını fark edince yürüye yürüye eve gideceksin.

O yüzden sevdalan ma... Sakın ha!', 'Pastırma sıcakları zamanı şehrimde... turşusunu yapamayanlara son elveda vakti; yemiş daha pahalanmadı. Bi de yazdan nasibini alamayan aşıkl...', ARRAY['Türk Edebiyatı','Şiir','Cem Uçar']::text[], 8.5, '{"poet":"Cem Uçar","poet_slug":"cem-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/pastirma-sicaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yama Tutmaz Yangın Yüreklim', 'sevgi-yama-tutmaz-yangin-yureklim-kamil-aydemir-2k1a0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'nasıl güler memleket kokan sürgünler

hüzünlü açıyor dalında güller

hayat okyanusunda döküntü taka gibi ilerliyor

ve kanlı kapatıyor perdesini günler

yürek parçalıyor ezilenler

sevebilir mi ölüler

bizim gibi nice aşıklar üzgünler

yangın yüreklim yama tutmaz sevgiler

hayatı mayınlayanların karşısında isyanım

tanımasaydım seni eksik kalırdı bir yanım

ben seni insanlığınla sevdim

özlemler rıhtımı yüreğimi önüne serdim

sevgi yama tutmaz yangın yüreklim

ve külde açmaz çiçekler

içindeki yangınları söndürmeye geldim

yangın yüreklim sevgi tutmaz yama

güzel günlerimi sakladım çocukluğuma

gençliğimi sorma

kanatları yaralı güvercindir gençliğim

kendimi unutarak memleketimin dertlerini yüklendim sırtıma

ortaokullu yıllarda yitti gamzelerim

artvin kadar çektim

kara eylüllü memleketimde ölümü yırttım ama

an oldu utandım yaşamama

insanın dayanma gücüne şaşıyorum

dönüp bakımca arkama

buzdan bir adam dolanır ortalıkta

bakışların sıcaklığı düşmese damarlarıma

her yanından hüzün damlayan

budaklı bir ağacım sanki

benim neyime uğrasın arılar

yürekde ağrılar

yakamı bırakmıyor serseli mayın gibi acılar

umutlarımı çaldılar insana yabancılar

mutluluğun izini yakalamaya çalışıyorum

ve geç kalmamak için zamanla yarışıyorum

aşk yatağında sana karışıyorum

yaraları bitürlü iyileşmeyen dünyada

ağlarken bir yanım diğer yanımın gülmesine alışıyorum

acılarından da uzat bana gönüllü paylaşıyorum

yangın yüreklim fırtınalar bile engelliyemiyor

aşkada uğruyor yollar

sevgiye kanat vuruyorsa sol göğsündeki güvercin

ve senden göç etmiyorsa kırlangıçlar

yatağından taşan ırmak gibi akar yıllar

geceden yıldızlar kaydıkça ben düşüyorum

kendine sığmayan çocuk gibi giyinip sevinçlerimi

bayram yeri gözlerine koşuyorum

kirpiklerini çek aradan sokulayım gözlerine

ellerin sarmayınca dipsiz yalnızlığımda üşüyorum

korkma yangın yüreklim

insandan yana dövüşüyorum

ve biliyorum

engelliyemiyor fırtınalar bile

aşkada uğruyor yollar

sevgi demim 

yanımdaki özlemim

aşk en iyi ilacıdır ömrün

onca acılara

ve her şeye rağmen yaşıyorum

ölüme komşu yollardan çok çektim

yangın yeri yüreğine sevgimi

sesimi dağlara ektim

ateşböceğine özenmek suçum

karlı günlerde karnı sırtına yapışmış 

                     sokak kedisi gibi açım

yangın yüreklim beni mutluluğa doyur

dağlarda sesim büyür

yası uzun olur asi dağın

uyuduğu görülmüş müdür cemre düşmüş toprağın

bedeli olsa da nice sevdanın

bana dünüm kadar uzak olma sakın

hep aşkım ol

hep yarınım

yarınım dünden yakın

unutma sakın

bir bebeğin gülüşünden daha naziktir sevgi

örselenmeye bile gelmez

yangın yüreklim sevgi yama tutmaz', 'nasıl güler memleket kokan sürgünler hüzünlü açıyor dalında güller hayat okyanusunda döküntü taka gibi ilerliyor ve kanlı kapatıyor perdesin...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/sevgi-yama-tutmaz-yangin-yureklim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birimizin Yarasında İkimiz Kanadık', 'birimizin-yarasinda-i-kimiz-kanadik-kamil-aydemir-8x56t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aşkımızın uçnoktalarında dolaştım

bütün kapıları mutluluğa açtim

merhaba

         merhaba aşkım

yaşamın bayırında kıraçtım

zorları aştın bana ulaştın

sevginle suladın

mutluluk çiçekleri açtım

umudu insanda aradık

nice güzellikleri ıskaladık

darağaçlı şafaklarda ağladık

untup odunsuzluğumuzu

karakışın ayazında sokak çocuklarına

ve kuşların çaresizliklerine yandık

birimizin yarasında ikimiz kanadık

aynı yatakta birbirimize karıştık

seninle yüreklerimizi paylaştık

                 sevdiğim yüreklerimizi

ayrılık rüzgârina harcatmam insanca sevgimizi

derman olacağım acında

yeter ki sevgin olsun yanında

güzellikler de büyür yaşamın yamacında

çekip gitsende

   ben araya ayrılığı sokmayacağım

   sensizde seninle yaşıyacağım

ve tek başıma kalsamda bu soylu sevdayı taşıyacağım

benden hoşça kal sözcüğünü duyamayacaksın

bu aşka sende kıyamayacaksın

hep merhaba

       merhaba sevdiğim diyeceğim

biliyorum ki ben sensizde seni seveceğim

sevgin benim şahdamarım', 'aşkımızın uçnoktalarında dolaştım bütün kapıları mutluluğa açtim merhaba          merhaba aşkım yaşamın bayırında kıraçtım zorları aştın ban...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/birimizin-yarasinda-ikimiz-kanadik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım', 'anladim-emin-baydil-q4p8y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Galiba erken gelmişim ben bu dünyaya

Bozkır sessiz, gökler açık ve mevsim yazmış.

Meğer ilkbaharı şaşırmış yıllar, 

Hayatımı günbegün sonbahar yazmış...

Ben, bu dünyaya erken gelmişim belli, 

Parmak hesabıyla yaptığım, yaşımdan anladım bunu.

Evet, tamı tamına elli yıl, 

Demek ki, yarım asırdır dünya, 

Beni de taşımış kambur sırtında.

Olmadığım aynalarda

Acılarla doğranmış insanlar orda, 

Beni de gösterdiler: ''Aha işte! '' Oracıkta anladım...

Tül perdeler, çekilsin tül perdeler! 

Bulutlar gibi gönlüm ararken bir sevgili, 

Semâda yana yana tutuşsun istemişim.

Şu köhnemiş, kokmuş dünyadan yana

Daha neler ummuşum, kim bilir! ..

Bir anda sevinmiş, üzülmüşüm

Bir başka görünmüşüm, albümdeki resimlerde:

El sallayan ya da gülen pozlarda.

Bilinsin diye mi ne, 

Yazılmış inceden inceden

Arkasında bir tarih, gün ve üstünde adım.

Artık sararmış, tarihten bile eski, şu koca çınar resmini

''İşte bir zamanlar böyleydim'' demek için sakladım, aldanmışım...

Tamı tamına elli yıl, dile kolay.

Saymakla bitmiyor: Bir iki üç ve...

Babamdan genç, benden yaşlı bir köstekli saatle

Her anı demirden, çelikten tokmak, 

Bir eli yılı geride bırakarak...

Her biri üçyüzaltmışbeş gün altı saat, 

Tükenmiyor bir türlü: Anlat, anlat! ..

Öyle ya; 

Acıktığım, sılâdan uzak, kimsesiz yaşadığım

Ve belki de âşık olduğum günler olmuş.

Rengârenk çiçeklerle; bezediğim güzel, tatlı sözlerle; 

Mektup yazdığım ve aldığım günler olmuş, anladım.

Anladım; 

Urfa''nın yaz gecelerinde

Kesme taş döşeli eyvanımda; 

Bir elinde bir havlu, 

Diğer elinde ibrikle yâr, bekler yanımda.

İşte, o günden ve o andan beri

Anadolu''dan derdiğim güzelleri

Çiçekler kadar sevmişim bir, bir.

Kiminin endâmına, 

Belki de edâsına, nazına vurulmuşum.

Şiirlerim olmasaydı, neler çekerdi kalbim, Tanrı bilir...

Gökkubeden dökülen yıldızlarla birlikte

Dolunayı koynuma almış,  öylece uyumuşum.

Göz bebeklerimi öpünce Güneş, 

Belki de sabah simitçileri

Geçerlerken Urfa''nın o daracık sokaklarından, 

Uyanmışım, usulca...

...............

Tam elli yıl yürüdüğüm

Sayarak adım adım, 

Bir rüyaymış gördüğüm

Eyvah, şimdi anladım! ..

Eyvah! 

''Eyvah da, artık çok geç! ..''

Ne kadarsa günahım

Affet! Affet Allah''ım! ..', 'Galiba erken gelmişim ben bu dünyaya Bozkır sessiz, gökler açık ve mevsim yazmış. Meğer ilkbaharı şaşırmış yıllar,  Hayatımı günbegün sonbah...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/anladim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşksın sen-', 'asksin-sen-kibar-tavasav-xcgg0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kıyıları yalayıp ta 

kum tanelerini içine alıp kaçan denizin dalgası gibi 

öptün dudağımdan kaçtın yağmur ıslaklığında 

alıp götürdün dudağımdan sarkan sevdamı, 

bir düş değil 

bin düş parçaladı içimi 

bir göz değil 

bin gözün değdi gözüme 

bir tel değil 

bin tel saçın sarmaladı vücudumu, 

ben kurtulamadım 

hangi dağa baksam adın yazıyor 

hangi ağaca tutunsam 

sevdan haykırıyor parmaklarımın ucundan içime 

kollarım yanıyor, 

ya yüreğime ne demeli 

bir bilsen kendime dokunuşlarım bile sen kokuyor 

yıkayamıyorum ellerimi 

kokun beni asla terk etmiyor 

çıkmıyor içimden 

nedir bu? 

işte adını koyuyorum 

aşksın sen! 

dinlenmiş vücudum bile yorgun düşüyor senin koynunda 

uykusuz sabahlardan çıkıp uyku tutmuyor 

seninle uyumuş kabul ediyor beynim, kalbim kendini 

nedir bu? 

işte adını koyuyorum 

aşksın sen! 

saçların süpürge olup süpürüyor toz konmuş kalbimi 

ellerin sabun olup 

gözlerin iğne oluyor 

biri yıkıyor, öbürü batıyor 

zaman geçiyor 

ama hep kalbim acıyor, 

kanıyor 

bir türlü tutunamıyorum rüyalara 

ya bir sinek uyandırıyor 

yada arap kedim miyavlıyor 

sen kaçıyorsun, 

ne olurdu rüya görürken Kibar hiç uyanmasa 

hatta sonsuzmuş gibi uykunun kudretli kollarında 

senin sıcacık nefesini duyup 

seninle bir sahil kasabasında geçen renkli bir rüyada 

aşk ve romantizm kokan bir filmi 

bin bir yıl başından sonuna tekrar  tekrar izleyerek yaşasa 

nedir bu? 

işte adını koyuyorum 

aşksın sen 

aşk!', 'kıyıları yalayıp ta  kum tanelerini içine alıp kaçan denizin dalgası gibi  öptün dudağımdan kaçtın yağmur ıslaklığında  alıp götürdün dudağı...', ARRAY['Türk Edebiyatı','Şiir','Kibar Tavasav']::text[], 8.5, '{"poet":"Kibar Tavasav","poet_slug":"kibar-tavasav","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/asksin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet Destanı', 'cumhuriyet-destani-ali-hallac-gksru', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cumhuriyet bir devrimdir çocuklar

Kulluğa, köleliğe, bendeliğe karşı

Cumhuriyet bir devrimdir çocuklar

Yobazlığa, geriliğe karşı..

Cumhuriyet bir devrimdir çocuklar

Türk Devrimi''dir, Atatürk Devrimi''dir.

Cumhuriyet bir devrimdir çocuklar

Aynı zamanda bir yaşam biçimidir.

Cumhuriyet bir devrimdir çocuklar

Osmanlılığı bitirip Türk''lüğü başlatan.

Cumhuriyet bir devrimdir çocuklar

Gericiliği bitirip, çağdaşlığı başlatan.

Cumhuriyet bir devrimdir çocuklar

Esarete karşı çıkıp, özgürlüğü getiren

Cumhuriyet bir devrimdir çocuklar

Egemenliği Ulus''a teslim eden.

Cumhuriyet bir devrimdir çocuklar

Bizi kendi dilimize kavuşturan.

Cumhuriyet bir devrimdir çocuklar

Demokratik yapıyı oluşturan.

Cumhuriyet bir devrimdir çocuklar

Şeyhliği, müritliği, ağalığı kaldıran.

Cumhuriyet bir devrimdir çocuklar

Türk Vatandaşlığı kavramını oluşturan.

Cumhuriyet bir devrimdir çocuklar

İnsanca yaşamayı amaçlayan

Cumhuriyet bir devrimdir çocuklar

Kimsesizlerin kimsesi olan.

Cumhuriyet bir devrimdir çocuklar

Bir devrim ki süregelen ve yaşayan..

İnanın ki suçu hatası yok bu devrimin

Hatalı uygulanmasıdır aksayan.

Cumhuriyet bir devrimdir çocuklar

Ata''mızın en önemli emaneti

Cumhuriyet bir devrimdir çocuklar

Affedilmez asla hıyaneti.

Türk  Ulusu, Türk Ülkesi, Türk Vatanı

Cumhuriyet var oldukça yaşar

Cumhuriyet bir devrimdir çocuklar.', 'Cumhuriyet bir devrimdir çocuklar Kulluğa, köleliğe, bendeliğe karşı Cumhuriyet bir devrimdir çocuklar Yobazlığa, geriliğe karşı.. Cumhuriye...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/cumhuriyet-destani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Gündüz', 'gece-gunduz-ahmet-aksoy-7l7x2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kan çanağı gözlerim

Bakıyor donuk resmine

Vakit ne olmuş

Saat kaçı gösteriyor

Yıllardan hangi yıldayız

Kan olmuş gözlerim

Yüreğimdeki kan 

Gözlerime vurmuş

Kızıl görüyor her yanı.

Gece, karanlık değil kıpkızıl olmuş

Her gece devralıyor kızıl sakallı, 

Gardiyan gibi nöbeti

Senden sonra hiç göremediğim günden

Gece gündüz, başıma asker olmuş 

Beni bekliyorlar

Sana bakarken kan çanağı gözlerimle.', 'Kan çanağı gözlerim Bakıyor donuk resmine Vakit ne olmuş Saat kaçı gösteriyor Yıllardan hangi yıldayız Kan olmuş gözlerim Yüreğimdeki kan  G...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-gunduz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyüş', 'yuruyus-ahmet-aksoy-xdkfa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çelik bir tel gibi 

Gergin zaman

Çelik bir tel gibi 

Gergin iki uçta

Ve insan cambaz 

Gibi yürümekte

Tek kişilik 

Bir gösteride

İşte bu yüzden

Tüm mesele

İpten düşmek

Ya da düşmemekte

Lakin tel uzun

Bir ucu başlangıç

Bir ucu son

Uçsuz zaman

Çelik bir tel

Gibi gergin

Çelik bir tel gibi

Gergin iki uçta

Ve insan yürümekte

Fakat uçsuz zaman

Düşüşü ertelemek

Ve direnmek beyhude

İşte bu sebeple

Yürüyüş düzgün

Yürüyüş doğru

Yürüyüş olmalı etkin.', 'Çelik bir tel gibi  Gergin zaman Çelik bir tel gibi  Gergin iki uçta Ve insan cambaz  Gibi yürümekte Tek kişilik  Bir gösteride İşte bu yüzd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yuruyus-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet Masalı', 'cumhuriyet-masali-ali-hallac-d91z8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Taa ilk mektepten beri

Cumhuriyet masalı okurlar bize

Okulda öğretmenler, kürsüde siyasetçiler..

Taa 11 Kasım 1938''den beri

Cumhuriyet masalı okurlar bize

Karşı devrimciler, ikinci Cumhuriyetçiler..

Taa 80 yıldan beri

Cumhuriyet masalı okurlar bize

Halktan kopuk bürokratlar...

Cumhuriyet Cumhuriyet diye diye

Kemalizm''den adım adım uzaklaştılar

Cumhuriyet maskesi altında

Köşe dönme, köşe kapma uğraşındalar.

Oysa 80 yılda iyi olan ne varsa O''nun eseri

Sivillik, demokratikleşme, çağdaşlaşma...

Batı uygarlığını ve aydınlanmayı

Hedef gösteren hep O''nun ilkeleri.

Bitsin artık bu Cumhuriyet masalı

Ulus Cumhuriyeti tam yaşamalı

Tarihsel gerçekler çarpıtılmamalı

Atatürkçülük dos doğru anlatılmalı.

Senin bir kimliğin var başka kimlik arama

Yitirme kimliğini ve kimselere aldanma! 

Cumhuriyetin baş yapıtı NUTUK''tur

Benim karnım tok başka başka masala.', 'Taa ilk mektepten beri Cumhuriyet masalı okurlar bize Okulda öğretmenler, kürsüde siyasetçiler.. Taa 11 Kasım 1938''den beri Cumhuriyet masal...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cumhuriyet-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısır Döngü', 'kisir-dongu-caglar-akdeniz-zbcs8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eşanlamlı insanlar, 

Karşılıksız kelimeler.

Bir kısır döngü, 

Yaşamın içinden gelip, kopan dürtüler.

Türbülans etkisi yaratıyor belleklerde.

Kayıp kümeler, kesişen hayatlar.

Yarım kalmış sevgiler ve orgazmlar.

Hatıralarda iz bırakan, 

Oyunlar.

Mastürbasyon etkisi yaratıyor belleklerde.

18.07.2002', 'Eşanlamlı insanlar,  Karşılıksız kelimeler. Bir kısır döngü,  Yaşamın içinden gelip, kopan dürtüler. Türbülans etkisi yaratıyor belleklerde....', ARRAY['Türk Edebiyatı','Şiir','Çağlar Akdeniz']::text[], 8.5, '{"poet":"Çağlar Akdeniz","poet_slug":"caglar-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kisir-dongu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmi Dört Saat', 'yirmi-dort-saat-orhun-basat-0qwg1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne sevmekten vazgeç, ne sevilmekten, 

Soğuk uzun gecelerde, sarıl bana sıcacık.

Gecenin üstünü örten, bu koyu renkten

Beyaz düşler topla, ikimize, birazcık..

Gözlerimde sis içinde anılar, 

El yordamı yürüyorum, cümle yollar daracık.

Var mı, yok mu belli değil yarınlar, 

Gelirsin diye, yüreğim, yirmi dört saat açık..', 'Ne sevmekten vazgeç, ne sevilmekten,  Soğuk uzun gecelerde, sarıl bana sıcacık. Gecenin üstünü örten, bu koyu renkten Beyaz düşler topla, ik...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yirmi-dort-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-olcay-kose-b59fo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bugün

bir orospu kadar gamsızım

devrik cümle gibi anlamsız...', 'bugün bir orospu kadar gamsızım devrik cümle gibi anlamsız......', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bugun-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Göz Aynı Bakışla', 'ayni-goz-ayni-bakisla-derin-oger-m9fhn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakışlarım gözyaşı taşımış ağırlığınca

Gözlerine ağlıyamamış gözlerim doya doya

De ki gözlerinde birikmiş gözyaşlarım

De ki gözyaşlarım ulaşmış rüyalarına

Gri bir bulut yağmur olmuş yanaklarında

Yağmış deli dolu düşlerimin pembe damlaları

Süzülmüş ıslak bir gömlek gibi sarmış tenini

Sen ve ben olmuşuz tek vucud gün ışığına

Yaprağın yeşiline denizin mavisine güneşin turuncusuna

De ki uyanmışız her rüyadan aynı göz aynı bakışla

Pırıltılı bir mutluluğa.....................', 'Bakışlarım gözyaşı taşımış ağırlığınca Gözlerine ağlıyamamış gözlerim doya doya De ki gözlerinde birikmiş gözyaşlarım De ki gözyaşlarım ulaş...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayni-goz-ayni-bakisla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-hayri-aydin-ckuug', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkım, bu gece ve her gece

Yıldızlar senin için parlıyor

Gökyüzünün en parlak yıldızı

Yüreğinde tatlı bir ışıltı, mutluluk olsun

26 Ekim 2003, Istanbul', 'Aşkım, bu gece ve her gece Yıldızlar senin için parlıyor Gökyüzünün en parlak yıldızı Yüreğinde tatlı bir ışıltı, mutluluk olsun 26 Ekim 200...', ARRAY['Türk Edebiyatı','Şiir','Hayri Aydın']::text[], 8.5, '{"poet":"Hayri Aydın","poet_slug":"hayri-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gece-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlara', 'dostlara-bekir-mutlu-gokcesu-kwk43', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Görmedim yüzünü

Hiç bilmem gülüşünü

Ne önemi var

Seni seviyorum

Bunu hissediyorum

Dudağımda dua, şiir

Gönlümde güzelden yana

Ne varsa dosta dair

Sana vermek isterim

Birkaç dizecik işte

Dökülüverdi dilimden

Mutluluklar dileğim sana

Ta yüreğimden', 'Görmedim yüzünü Hiç bilmem gülüşünü Ne önemi var Seni seviyorum Bunu hissediyorum Dudağımda dua, şiir Gönlümde güzelden yana Ne varsa dosta ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dostlara-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakarış', 'yakaris-emin-baydil-duwms', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman, zamana tutsak

Toprağa hasret tenim.

Her ânı vûslat için yaşarım

Her nefesi, bitmek için bedenim.

Kurulmuş bir zemberek gibiyim:

Tik-tak, tik-tak...

Boşanırsa bir gün, zamanı bırakarak

Biliyorum, duracak kalbim.

Dalınca sade bir, sabaha ruhum

Dua mı etsem kurtulurum, 

Diz çöksem mi, Yarabbim! ..

Gözlerim mi kör, 

Kulaklarım mı sağır! ..

Doğrulup kalksam diyorum

Yüklenerek hayatı, 

Doğrulup da bir kalksam diyorum

Yerimden ağııır ağır...

Bu benim, 

Şu da, benim günahım! 

Onu ben yaptım, ben! 

Ben yaptım, onu da...

Bir ömürlük saltanatın sonunda

Hepsine şahid kalbim.

Bir değil, bin günahım.

Beni affet! 

Beni affet Allah''ım! ..', 'Zaman, zamana tutsak Toprağa hasret tenim. Her ânı vûslat için yaşarım Her nefesi, bitmek için bedenim. Kurulmuş bir zemberek gibiyim: Tik-t...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yakaris-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kupa Kızına Mesaj', 'kupa-kizina-mesaj-ali-osman-yilmaz-qmome', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutlu sonla biten filmler

Hep şaşırtmıştır beni, 

Nasıl mutlu sonla biter

Anlayamadım hiç.

İnsanlık tarihi boyunca

Mutlu sonla biten bir hikaye 

Duydunuz mu siz? 

Yüz yıl savaşları yapılmış, 

Nice aşklar için, 

Yine gelmiş ayrılık.

Nice aşk masalları dinlemedik mi? 

Dedelerimizden, ninelerimizden, 

Kim kavuşmuş sevgilisine söylermisiniz? 

Ne Leyla’sına sarılmış Mecnun! 

Ne Ferhat dağları delsede

Şirin’ine kavuşmuş, 

Bazende aşk bahçelerinin güllerine

Gelmiş dolanmış kalleş hastalık, 

Ölüm ayırmış  aşıkları bu kez, 

Sevmek, kavuşmak ne mümkün? 

Varsın yolunda gitsin her kes.

Benimde bir sözüm var! 

Darbı mesel olarak bilsin herkes, 

‘’Sevginin dışında, 

   İnsanın kendisinden başka

   Değerli değildir hiçbir şey’’

Derim kupa kızına etme artık naz, 

Seni görmekten başka bir şey istemedi, 

Ömrünün yazını yaşamakta olan 

 Ve seni seven; ahmak kupa papaz', 'Mutlu sonla biten filmler Hep şaşırtmıştır beni,  Nasıl mutlu sonla biter Anlayamadım hiç. İnsanlık tarihi boyunca Mutlu sonla biten bir hik...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kupa-kizina-mesaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-turgut-cakar-2wyol', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölüm gibi belirsiz

Dipsiz kuyular kadar sessiz.

Ben, 

Tepeden tırnağa sensiz

Sen, 

Tüm bunlardan habersiz.

Yaşamak denirse buna

Yaşıyoruz işte...

Anladım ki:

Ayrı doğrultularda

Aynı doğrularız biz...', 'Ölüm gibi belirsiz Dipsiz kuyular kadar sessiz. Ben,  Tepeden tırnağa sensiz Sen,  Tüm bunlardan habersiz. Yaşamak denirse buna Yaşıyoruz iş...', ARRAY['Türk Edebiyatı','Şiir','Turgut Çakar']::text[], 8.5, '{"poet":"Turgut Çakar","poet_slug":"turgut-cakar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/biz-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para', 'para-emin-baydil-5lqx7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey vicdansız serseri, şu kanı bozuk para

En cahil insanı da getirir iktidara.

Hem cahil, zır cahil ol, ister isen eşek ol

Önünde secde edip, açılır yüzlerce yol.

Varlığın şımarıkça, yokluğun değer cana

Nice insan bilirim, öyle ki tapar sana.

Ne dost olduğun belli, ne de düşman olduğun

Yalnız bir şey öğrettin, o da pişman olduğum.

Sensin tahta oturan, köşede oturan da

Tıpkı bir şaşkın gibi, ağlayan da gülen de.

Sensin yük altındaki inleyen bahtı kara

Sensin yine seyreden yüksekten insanlara.', 'Ey vicdansız serseri, şu kanı bozuk para En cahil insanı da getirir iktidara. Hem cahil, zır cahil ol, ister isen eşek ol Önünde secde edip,...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/para-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şakacıktan Deli Kız', 'sakaciktan-deli-kiz-emin-baydil-61zdu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine eski bir tarak

Kırık-dökük bir ayna.

Bir de cımbız elinde

Yolda sallanır boyna.

Ah gözleri sürmeli, 

Elleri al kınalı, şakacıktan deli kız! 

Deli, 

     deli, 

          deli kız! 

Kastamonu içinde, Çoyboyu güzeli kız...

Bilmez misin adın var

İpekten kanadın var.

Kelebekler misâli

Söyle! Ne maksadın var? ..

''Kambur Köprü'' üstünde

Bir sağına, soluna

Bakınırsın dönerek

Söyle, kimin yoluna! ..

Durma git, yürü haydi! 

Köprünün ayağı var...

Bilirsin: İyi-kötü

Yolların ayağı var.

Bak! İşte, dedikodu! 

Diller, 

    diller, 

        ne diller! ..

Mehtabı kucaklayan durgun suda kandiller, 

Hep seni, 

Hep seni konuşuyor, şakacıktan deli kız! 

Adım adım uzayan, yolların bedeli kız! ..', 'Yine eski bir tarak Kırık-dökük bir ayna. Bir de cımbız elinde Yolda sallanır boyna. Ah gözleri sürmeli,  Elleri al kınalı, şakacıktan deli ...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sakaciktan-deli-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişti', 'degisti-emin-baydil-vs1pg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül tutardı eskiden

Şimdi, eller değişti.

Buram buram kokardı

İnan, güller değişti.

Ağaçlar gitti kökten

Kuşlar uçmaz yüksekten.

Artık, izinsiz gökten

Akan seller değişti.

Hayat güzel, en güzel

En doğru giden güzel.

Tatlı söz eden güzel

Belki diller değişti.

Essin rüzgâr, halınca

Arı çiçek dalınca

''Kötü'', insan olunca

Bahaneler değişti.', 'Gül tutardı eskiden Şimdi, eller değişti. Buram buram kokardı İnan, güller değişti. Ağaçlar gitti kökten Kuşlar uçmaz yüksekten. Artık, izin...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/degisti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-halil-baba-takkabulan-49v5h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gelişinle

Dudaklarımda bir gülümseme bırakmıştın, 

Gidişinle 

Gönlümde bir hüzün.

Hem öyle bir hüzün ki; Ey yar! 

Sen gittin gideli, ben rüyalarıma

Misafir kabul etmedim hiç bir gün....

(20.10.2001 Adana)', 'Sen gelişinle Dudaklarımda bir gülümseme bırakmıştın,  Gidişinle  Gönlümde bir hüzün. Hem öyle bir hüzün ki; Ey yar!  Sen gittin gideli, ben...', ARRAY['Türk Edebiyatı','Şiir','Halil Baba Takkabulan']::text[], 8.5, '{"poet":"Halil Baba Takkabulan","poet_slug":"halil-baba-takkabulan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-301-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hiç Olmak', 'bir-hic-olmak-halil-baba-takkabulan-my3ol', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Devri kadar deli olmak...

Anlaşılmayacak kadar gizemli, 

Doğa kadar saf, 

Yağmur kadar berrak, 

Kıtmir kadar vefalı, 

Güneş gibi sıcak...

Belki hiçbir şey kadar büyük, 

Belki herşey kadar küçük olmak...

(30.10.2002 Adana)', 'Devri kadar deli olmak... Anlaşılmayacak kadar gizemli,  Doğa kadar saf,  Yağmur kadar berrak,  Kıtmir kadar vefalı,  Güneş gibi sıcak... Be...', ARRAY['Türk Edebiyatı','Şiir','Halil Baba Takkabulan']::text[], 8.5, '{"poet":"Halil Baba Takkabulan","poet_slug":"halil-baba-takkabulan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-hic-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hava Durumu', 'hava-durumu-isik-sevinc-vyp12', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anneciğim, 

Bak yağmurlar yağıyor 

gözlerimde ağlarken

Parlak  bir güneş açılıyor 

yüzümde, gülerken

Tıpkı  bu şehir gibi 

değil mi annem..., 

                    2001/', 'Anneciğim,  Bak yağmurlar yağıyor  gözlerimde ağlarken Parlak  bir güneş açılıyor  yüzümde, gülerken Tıpkı  bu şehir gibi  değil mi annem......', ARRAY['Türk Edebiyatı','Şiir','Işık Sevinç']::text[], 8.5, '{"poet":"Işık Sevinç","poet_slug":"isik-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hava-durumu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkbahar', 'i-lkbahar-isik-sevinc-6ilbe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağaçlar parıldıyor 

Güneş  ışığıyla.

Denizler pırıl pırıl 

Balıklar  koynunda.

Kuşlar uçuyor 

Sevinçle havada.

Çocuklar koşuyor 

Mutlu mutlu okula

         9-Mart-2002', 'Ağaçlar parıldıyor  Güneş  ışığıyla. Denizler pırıl pırıl  Balıklar  koynunda. Kuşlar uçuyor  Sevinçle havada. Çocuklar koşuyor  Mutlu mutlu...', ARRAY['Türk Edebiyatı','Şiir','Işık Sevinç']::text[], 8.5, '{"poet":"Işık Sevinç","poet_slug":"isik-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ilkbahar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldin Yeni Yıl', 'hos-geldin-yeni-yil-isik-sevinc-v7gtf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeni    yıl    geldi.

Yaşasın    çok     mutluyum.

Babam     bana     çam   ağacı, 

Annem     de     hediye      aldı.

Ağacı     diktim, hediyemi açtım.

Bir     baktım     barbie    evimin   içi

Mutluluk   dolu.

Yaşa,  yaşa  çok  yaşa, yılbaşı.', 'Yeni    yıl    geldi. Yaşasın    çok     mutluyum. Babam     bana     çam   ağacı,  Annem     de     hediye      aldı. Ağacı     diktim, hed...', ARRAY['Türk Edebiyatı','Şiir','Işık Sevinç']::text[], 8.5, '{"poet":"Işık Sevinç","poet_slug":"isik-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hos-geldin-yeni-yil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-isik-sevinc-y4irr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonbahar  geldi.

