INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ezgi', 'bir-ezgi-tahir-bingol-pmc3w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onun elleri vardır.

Anadolu kokar buram buram

Kardelen gibi beyazı sever gözleri.

Ezgisinde can dostları vardır.

Nelere tanıklığı vardır. 

Nelere acıları.....

En iyi bahar ezgilerini

Ve güneşe bükük boynunda hüznünü

Çakar bir başına bin başına 			

Çakmak taşına körpecik gencecik			

Ele avuca sığmaz nazlı gelinciği vardır.			

Bebeğin ay mavisi gözleri vardır.			

Bir aşk şiir''idir			

Tüm evrene, 			

Bir türküdür ıssız gecelere			

Ve ilk ninnilerinde çocuğun tebesümüdür.			

Bir han yolcusudur bir başına bin başına..			

Ayaklarında asırların yorgunluğu			

Haykırır korkusuzca ve gebe kalmadan 			

Namusuza...			

Bebeğin  gök kuşağı renginde kanı vardır.			

Sıcacık tüm evreni sararcasına 

Ve dostçasına....

31.10.2003', 'Onun elleri vardır. Anadolu kokar buram buram Kardelen gibi beyazı sever gözleri. Ezgisinde can dostları vardır. Nelere tanıklığı vardır.  N...', ARRAY['Türk Edebiyatı','Şiir','Tahir Bingöl']::text[], 8.5, '{"poet":"Tahir Bingöl","poet_slug":"tahir-bingol","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-ezgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-rahmi-nalbantoglu-aoqi4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anne

Önce HAKKA, sonra sana, tapardım, 

Sevginle ömrümü, çürüttün ANNE.

Sen dünya hırsıyla, bencillikteyken, 

Beni sokaklarda, büyüttün ANNE.

Sen gelmeden, işten kokun, gelirdi, 

Hasretinle küçük kalbim, ölürdü.

Ne zaman anneli, çocuklar görsem, 

Ruhumun isyanı, kabarır ANNE.

Anladım kalbinde, bana yer yokmuş, 

Bir gözden, var imiş, gayrısı boşmuş.

ANA gibi ANA, olmadın ANNE.

Bir ömür ağladım, gülmedim ANNE.

Her zaman gönlümde, taht kurdun inan, 

Ben sevgi isterim, gerisi yalan.

Ne zaman, ben seni, yanımda bulsam, 

Sırtımda bir hançer, oluyor ANNE

Seni düşünmekten, inan yoruldum, 

Senin için, bin kez, kula kul oldum.

Ömrümü uğrunda, harcadım durdum, 

Beni kapı kapı, satma be ANNE.

Riyakarlık etme, doğruyu söyle, 

Varlığım sizlere, ağırmı böyle.

Ellerle birlikte, güle, eğlene,.

Beni hep sırtımdan, vurdunuz ANNE.

Sevgiye kalbiniz, kapalı imiş, 

Bu yalan dünya, kime yar olmuş.

Yüz yıl yaşasakta, sonu ölümmüş, 

Mahşerde, sen bana, ne dersin ANNE.

Beni kula kul etmek, muradınmıdır? , 

Kalbimde tahtını, görmedin ANNE.

Yürekten yüzüme, bir kez gülmedin, 

Ne zaman dizinde, Ağladım ANNE? .

Hiç derdim eksilmez, artarda artar, 

Ben düşsem, elimden hep eller, tutar.

Sana hasret olmak, ölümden beter, 

Derdimi hep eller, soruyor ANNE.

Gün olur hayalim, gerçek olursa, 

Gönlünde bir zerre, yerim var ise.

Bir günde derdimi, sorsana ANNE, 

Benliğim kölendir, bilsene ANNE.

Rahmi NALBANTOĞLU', 'Anne Önce HAKKA, sonra sana, tapardım,  Sevginle ömrümü, çürüttün ANNE. Sen dünya hırsıyla, bencillikteyken,  Beni sokaklarda, büyüttün ANNE...', ARRAY['Türk Edebiyatı','Şiir','Rahmi Nalbantoğlu']::text[], 8.5, '{"poet":"Rahmi Nalbantoğlu","poet_slug":"rahmi-nalbantoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/anne-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek ve Sera*', 'cicek-ve-sera-bayram-tunca-z1bzq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönderilmişim gaipten, şu çiçek serasına 

Hangisi derman olursa, kalbimin yarasına 

Yerleştiririm onu, yüreğimin tam ortasına 

Var gücümle çalışırım onun muhafazasına 

24.10.2003-10.24', 'Gönderilmişim gaipten, şu çiçek serasına  Hangisi derman olursa, kalbimin yarasına  Yerleştiririm onu, yüreğimin tam ortasına  Var gücümle ç...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cicek-ve-sera-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GökKuşağım', 'gokkusagim-tevfik-mengulluoglu-dnvvk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdayı kuşanıp çıkıyorum yollara, mevsimlerden sonbahar adını Bilmediğim ağaçların ıslak yola savrulmuş narım tırak yapraklarının üzerinden yürüyorum, nereden geldiğimi ve nereye gideceğimi bilmiyorum; bilmekte istemiyorum aslında.Tereddütlü bir güneşin gölgesinde Silueti’ni görüyorum gözlerimi yumduğumda, kocaman yağmur tanelerini yanaklarımda hissetmeye başlıyorum ve anlıyorum ki sen birazdan en sevdiğim renklerle inadına göklerde tuhaf şekiller yapmaya başlayacaksın sonrada muhtemelen adına gök kuşağı dersin.Hep bir buz dağının etrafına çizmek isterdin aslında, Kabullenmek istemezdin bir türlü doğanın kaygılarını.Gözlerimi açar açmaz Ürperiyorum ve ayaklarım birbirine dolaşıyor ama senin bundan haberin yok kurnazca seviniyorum, yolumu değiştiriyorum ne yana dönsem senin o farkında bakışlarınla karşılaşıyorum, ne yana dönsem sen; damla olup denizlere karışasım gelirdi bilmeseydim renklerinden  vazgeçmenin bu kadar zor olduğunu! Zamanı parçalayan saatime bakıyorum  belleğimde boşluklar oluşuyor anlıyorum ki yaşamım şimdiye kadar gitmek istediğim ama gitmekten korktuğum anlarla  geçmiş, nereden bilirdim gitmek istediğim ama ulaşamadığım yerde senin olabileceğini.Hafiften üşüyorum oysa güneş kararsızlığından sıyrılıp tüm çıplaklığıyla vuruyor kendini yamaçlara, sonra anlıyorum ki benim baktığım her yerde sen varsın, olduğum her yerde sen, yağan her damlada senin bir parçan var, sende bu evrenin bir parçası isen!  Bende bir parçasıyım! işte ben buna sevda derim gök kuşağım...', 'Sevdayı kuşanıp çıkıyorum yollara, mevsimlerden sonbahar adını Bilmediğim ağaçların ıslak yola savrulmuş narım tırak yapraklarının üzerinden...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/gokkusagim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Yoktu', 'i-stanbul-yoktu-nilay-aksu-s9930', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen yoktun ya 

istanbul vardı hani 

hey gözünü sevdiğim ışıklar şehri 

varlığın göz alıcı sureti 

iç geçirten kasveti yoksunluğun

sen yoktun ya 

istanbul vardı hani 

aşk yoktu ne gökte ne yerde 

takma kirpikli çorabı kaçık bir fahişeydi şehir 

dudaklarını doyasıya öpemediğin

ve sevmeleri yalan bir şehirdi İstanbul 

seni sevmek yaz ortası hazanları gibi 

kış ortasında bahara göz kırpmak gibi 

seni sevmek yokluğunla yaşamaya alışmak gibi 

yorganın soğuğuna sarılmak gibi 

ölümü apansız çağırmak gibi 

sen yoktun ya 

istanbul vardı hani 

hani öpemediğim dudaklarını 

hani ölüme uzanır gibi 

dingin hesapsız yatamadığım kollarında 

sen yoktun ya 

otuz yaşım vardı başımda 

hesapsız sevmelerin yaşı geçmisti 

hani ''aşk'' deyince 

sarı bir hasret oturur ya bakışlarına 

„boşveer çivi çiviyi söker“ derken 

titrer ya ellerin saklasan da 

seni sevmek bir çocuk şarkısı gibi 

gözleri gülen bir umuda sarılmak gibi 

imkansız masallara inanmak gibi 

gecenin bir yarısı tanrıya yakarmak gibi 

seni sevmek bir ağacı kollarınla sarmak gibi 

sen yoktun ya 

istanbul ağlamıştı hani 

takma kirpiklerini sarı peruğunu önüne koyup 

dolu bir kadehi diklemişti ya 

hani “aşk da yok aslında” deyip 

omzumda ağlamıştı ya 

sen yoktun ya 

istanbul yoktu orda 

gözlerimle gördüm 

bir gece kendini sulara attı 

bütün ışıklarıyla!', 'sen yoktun ya  istanbul vardı hani  hey gözünü sevdiğim ışıklar şehri  varlığın göz alıcı sureti  iç geçirten kasveti yoksunluğun sen yoktun...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/istanbul-yoktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hele Dur', 'hele-dur-ahmet-kurt-fmkha', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nazlı canan bakışında sırları, 

Çöze çöze geliyorum hele dur.

Aramızda yükseltilen surları, 

Eze eze geliyorum hele dur.

Kaşınla kirpiğin, ne güzel uymuş, 

Yüreğim ses vermiş, kanımsa duymuş, 

Saçların başına tahtını kurmuş, 

Yaza yaza geliyorum hele dur.

İmbikten süzülür sanki göz yaşın, 

Çeyrek asra varmış, ne ola yaşın, 

Sözünden mi döndün nedir telaşın, 

Seze seze geliyorum hele dur.

Ahvalim karışık, zihnim karışık, 

Yollar geçit vermez, izler dolaşık, 

Dünyaya küsmüşüm, kulla barışık, 

Geze geze geliyorum hele dur.

Durulur bu kabus, duygular diner, 

Çarptıkça göğsümde ateşin söner, 

Sözlerin geceden mehtaba döner, 

Süze süze geliyorum hele dur.

Hayallar silinir, gerçek bulunur, 

Leklaklar yeşermiş kokusu vurur, 

Aşıklar feyz almış ürüne durur, 

Dize dize geliyorum hele dur.

Kurdoğlu rüyadan uyanır bir gün, 

Gerçekle örtüşmez, düşde gördüğün, 

Yıllar öncesinden bana sorduğun, 

Çize çize geliyorum hele dur.', 'Nazlı canan bakışında sırları,  Çöze çöze geliyorum hele dur. Aramızda yükseltilen surları,  Eze eze geliyorum hele dur. Kaşınla kirpiğin, n...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hele-dur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duydum ki+', 'duydum-ki-bayram-tunca-plcdr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duydum ki

Duydum ki hasretimden ağlıyormuşsun

Gelip geçenlerden beni soruyormuşsun

Ah gülüm ah, bu haberle kül ettin beni

Muradım odur ki, ivedili kavuşmak seni

Ah ağlattın beni yine be gülüm ağlattın

Hasretinle ciğerlerimi akkorla dağlattın

Her akla gelişinde, basiretimi bağlattın

Mecnun gibi kendini çöllerde arattırdın

Vuslatımız için her daim beni yalvarttın

01.11.2003-11:01

Aşk Ateşten Gömlek''', 'Duydum ki Duydum ki hasretimden ağlıyormuşsun Gelip geçenlerden beni soruyormuşsun Ah gülüm ah, bu haberle kül ettin beni Muradım odur ki, i...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duydum-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar ŞAİR, Neye Yarar ŞİİR', 'neye-yarar-sai-r-neye-yarar-si-i-r-naime-erlacin-mc01v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-beyaz zambaktan kor karanfile umutla çiçek açan 

bütün küskün şehirleri ve kırgın gönülleri 

ruhuyla okşayarak inatla sevdi ŞAİR! 

yol kazarak köklerine toprakta

lanetledi bozkır yüreklileri 

ölümsüz tutkulu yeşildi 

çınar dalında

nar ağacında özgür bir çiçek

fesleğenle kekik taşıdı dağlarından

bulutla zifaftayken kent semalarında mahcup 

aşık bir konuktu gül fidanında

bülbülün sevdası çile

şair’in deryası acı

vahşi bir ölümce içini yırtarak geçen rüzgar

her yeni mısrada taze bir intihar

hazırdır bahane oysa: adı aşk! 

yırtılmış saatlerde aranır yarınlar

-dokunmasaydı yüreği yasemin sarayların fildişi duvarlarına

eriyip akmasaydı ruhu unutulmuş son yağmur damlasında

buzdan sebeplenen kardelenle gizlice fısıldaşmasa

yeniden doğmayı bilmese çiy tanesinin buğusunda

neye yarardı ŞAİR! 

delmeli oysa dağları şiirle Ferhat’a inat

titreşirken güvercinler narin yüreğinde

çözülmeli hayata dair ruhun ehramına gizlenen sırlar

kaderi görmeli 

kan kırmızı şahin ve yırtıcı atmaca gözlerinde

tek silah var: adı “sözcük” 

böyle kuşanılır dil kalemden tırnağa

biraz yabansı biraz delice

çılgın cesareti ister çünkü er meydanı! 

neye yarar şair 

Şehrazat gibi büyüleyici, esrarlı

kalkışmış bir yılan kadar ağu dilli olmasa

kainatı çalıp gönlünde saklamasa 

bezgin şarkılarla hırsız zamanların uslanmaz cenkçisi

kan öğütürken sürgün kalbinde 

kutsanmamış yalnızlığın yorgun süvarisi şair 

neye yarar şiir olmasa

ŞİİR neye yarar 

acılar olmasa

aşklar olmasa! 

(01 Kasım 2003)', '-beyaz zambaktan kor karanfile umutla çiçek açan  bütün küskün şehirleri ve kırgın gönülleri  ruhuyla okşayarak inatla sevdi ŞAİR!  yol kaza...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/neye-yarar-sair-neye-yarar-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlik Parkı', 'genclik-parki-burhan-gumus-tkqpy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gençlik Parkı

Sen benim. 

Zira senin saçların simsiyah

yüzünde karanlık çizgiler yok

Omuzların dik

Gözlerinde hançer bakışlı.

Sen benim.

Bankta oturuyorsun

bende oturuyorum.

Yanında biri var. Duyuyorum adı Hülya’mı  ney.

Hafif bir rüzgar esiyor saçlarını yalıyor.

Benimde hayalim var

Farketmiyeseniz diye çaktırmadan düşen yaprakları sayıyorum.

Kalkıyorsunuz 

Bende kalkıyorum, dayanarak.

Elleriniz birbirine prangalı 

başınız yerde suskun suskun

yürüyorsunuz.

Bende yürüyorum.

Belliydi ipil  ipil kar yağıyor üşüyorum.

Köprüden geçiyorsunuz 

bende geçiyorum, nefesim daralıyor.

Lüna  parkın ışıkları da cıvıl cıvıl

Aile bahçesine giriyorsunuz

bende giriyorum.

Orkestra nirengi noktasında 

çılgınca bir müzik

“Taksimde bir durak

Durakta bir kadirlak

Kadirlakta bir manyak

Twist yap abi dalgana bak

Twistegey

Abidik gubidik twist twist

Lap lap lubalaba twist twist 

Twistegey”

eşliğinde dans ediyorsunuz

neşeyle çıkıyorsunuz

bende çıkıyorum, hicranla.

Az ötede canlı bir ses 

Zeki Müren havuzbaşında 

“İnleyen nağmeler ruhumu sardı

Bir rüya ki orda hep şarkılar vardı.”

Birden koşuyorsunuz, gülerek

bende koşuyorum, burnumum üstüne

Kalkamıyorum.

Bir telaş sarıyor beni

Hey durun! . Diyorum. Siz bensiniz

bensiz nereye gidiyorsunuz.

Gençlik parkı gözlerimde buğulanıyor.', 'Gençlik Parkı Sen benim.  Zira senin saçların simsiyah yüzünde karanlık çizgiler yok Omuzların dik Gözlerinde hançer bakışlı. Sen benim. Ban...', ARRAY['Türk Edebiyatı','Şiir','Burhan Gümüş']::text[], 8.5, '{"poet":"Burhan Gümüş","poet_slug":"burhan-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/genclik-parki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbül ve Gül', 'bulbul-ve-gul-ali-osman-yilmaz-5nsdd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilirmisiniz dostlar? 

Özgürlük yalnızlık demektir

Özgür kuşlar gibi uçmak isteriz, 

Gideceğimiz yer neresidir? 

Kendi yalnızlığımızın cennetidir.

Bülbül kafeste yaşamaz, 

Yalnız söyler şarkılarını gül’e, 

Aşkını getirir her şafakta dile, 

Dinler doğa ana şarkısını bülbülün, 

Sağır sultan bile uyanır uykusundan, 

Şafak vakti dillenir söyler şarkılarını, 

Yapraklarını hışırdatarak ağaçlar bile, 

Hangi şarkıyı söylerse söylesin bülbül, 

Kulakları yok ki duymaz onu gül, 

Her şafak yeniden gelir gül’e bülbül, 

Kırmızı gülden yanıt gelmez amma

Onun adına utancından morarır sümbül, 

Uçar özgürlüğe doğru, üzgün olarak bülbül, 

Bir tek aşkına esir olmaya razıdır, o da gül, 

Bilirmisiniz ey aşıklar, sevdanın ak kuşları, 

Yavruları aşkdan başka kimseye köle olmasın diye

Yuvasını altından da  olsa kafese yapmaz bülbül

1.Kasım.2003  Bülbülden Gülüne 12,00', 'Bilirmisiniz dostlar?  Özgürlük yalnızlık demektir Özgür kuşlar gibi uçmak isteriz,  Gideceğimiz yer neresidir?  Kendi yalnızlığımızın cenne...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bulbul-ve-gul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-i-brahim-bayraktar-haadb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sayılı gün çabuk geçermiş, 

Haydi be oradan! 

Zaman, aman mı veriyor sanki? 

Her gün bir gün daha artıyor yarınlar. 

Her şeyin ilacı olsaydı zaman; 

Katlanarak büyür müydü sorunlar? 

01.11.2003', 'Sayılı gün çabuk geçermiş,  Haydi be oradan!  Zaman, aman mı veriyor sanki?  Her gün bir gün daha artıyor yarınlar.  Her şeyin ilacı olsaydı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zaman-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elden ayrıksı', 'elden-ayriksi-i-brahim-atilmis-sbm7i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kendimden müstakil dünyamın penceresinden

uzatıp başımı 

baktığımda dışardaki dünyaya

her seferinde

yıldızlar bir başka parıldamakta gök yüzünde

her biri ayrı ayrı değme dansözlere taş çıkartırcasına

raksetmekte

ve gülmekte her biri ayrı ayrı 

her biri ayrı ayrı kendinden müstakil dünyalara.

elbette herkes elden ayrıksı(farklı)  sanar kendini

ayrıksıdır da zaten bir ötekine göre

oysa hepimiz aynı gezegenin ayrı dünyaları değilmiyiz gerçekte?', 'kendimden müstakil dünyamın penceresinden uzatıp başımı  baktığımda dışardaki dünyaya her seferinde yıldızlar bir başka parıldamakta gök yüz...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/elden-ayriksi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Halimi Her Gece', 'ay-halimi-her-gece-halim-yazici-ee7x2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sesler geçiyor gözlerimden akşam vakti

ne desem dinlemiyor bu saatte kimse ay halimi

bıraktım ben de yelesini taylarımın soğuk iklimlere

alnından öptüm bütün sularını dünyanın sessizce

babam da annesini öpmüştü alnından o gece

büyürken ıssız iklimler halinde ay kendi halinde

bu yüzden hâlâ sesler geçiyor alnımdan her gece.', 'sesler geçiyor gözlerimden akşam vakti ne desem dinlemiyor bu saatte kimse ay halimi bıraktım ben de yelesini taylarımın soğuk iklimlere aln...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ay-halimi-her-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaçlar Büyüdü', 'agaclar-buyudu-zeki-ergin-fcy7m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'etrafıma bir bakıyorum

çocuklar büyümüş

ağaçlar büyümüş

çocukların çocukları olmuş

ağaçların meyveleri

unutmak mümkün mü geçmişi

o günleri

sanki dün gibi

bahçeme diktiğim çam ağacı

üç yıldır fıstık veriyor 

dört yılda bir oy verdiklerim

düşündüm de ne veriyor

_erenköy 1kas03

_numune sayı:5 ara03 

_sevgiliye isyan yt:haz04', 'etrafıma bir bakıyorum çocuklar büyümüş ağaçlar büyümüş çocukların çocukları olmuş ağaçların meyveleri unutmak mümkün mü geçmişi o günleri s...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/agaclar-buyudu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Uğruna', 'ask-ugruna-suskun-resital-zfo22', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün ölüm günümdür, 

Seni gördüğüm, son gündür.

Umutlarımı, az önce gömdüm, 

Şimdi sıra bedenimindir...

En güzel yarınlar, senin olsun, 

En güzel umutlar, senin olsun, 

Dilerim Allah''tan senin de bir gün

Yürekten sevdiğin biri olsun

                     

Şimdi yürüyorum ağır adımlarla, 

Kendi elimle yaptığım darağacına.

Gidiyorum ama mutluyum! ...

Aşk uğruna ölenlerin yanına...', 'Bugün ölüm günümdür,  Seni gördüğüm, son gündür. Umutlarımı, az önce gömdüm,  Şimdi sıra bedenimindir... En güzel yarınlar, senin olsun,  En...', ARRAY['Türk Edebiyatı','Şiir','Suskun Resital']::text[], 8.5, '{"poet":"Suskun Resital","poet_slug":"suskun-resital","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-ugruna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağzına Biber Sürülen Çocuklar', 'agzina-biber-surulen-cocuklar-oguzkan-bolukbasi-xx33z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Türümün yalnızlığıdır aşk

Biz 

Ağzına biber sürülen çocuklardık küfür edince

O nedenledir ki aşkı tek başına yaşadık

İki kişi olamadık

O nedenledir ki anlaşılmaz cümleler kurarız

Anlaşılmaz ifadeler

Biz bile bakakalırız yazdıklarımızın ardından

Anlamayız

Çünkü yalnız

Kalmış bir kalbin kendini ifadesi çok zordur

Ağzına biber sürülen çocuklardan değilseniz

Siz

Bilemezsiniz bu yalnızlığın ne demek olduğunu

Canınızın yangını biribirine karışmamıştır

Diliniz mi

Yüreğiniz mi yanıyor bilirsiniz

Kelimeleriniz 

Anlaşılarak gezer 

Ama bizimkiler

Bizi kurşuna dizer

Türümün yalnızlığıdır aşk

Yine ardından bakakalacağım', 'Türümün yalnızlığıdır aşk Biz  Ağzına biber sürülen çocuklardık küfür edince O nedenledir ki aşkı tek başına yaşadık İki kişi olamadık O ned...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/agzina-biber-surulen-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetin Çatısına Kiremit Çektim', 'cennetin-catisina-kiremit-cektim-i-brahim-bayraktar-a4gqe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ilgıt ılgıt yüreğime esen yeller, 

Kalbimin kuytularında barınsın, 

Elinde sevgi meşalesi, kapımı çalan...

Ilık ılık akan sularımda arınsın.

Esmeye devam et, ey aşk rüzgârı! 

Peşinden ayrılmasa da sevgi seli,

Korkma! Ben bağrımı açmışım, 

Canının istediğince es deli deli.

Sevgi ektim Cennetin bahçelerine, 

Yaz gelince mahmur çiçekleri açsın, 

Sevenler okşasın, öpsün, sevsinler, 

Kucak kucak mutlulukla dönsünler.

Ne han isterim, ne hamam, ne saray, 

Şu dört duvar, işte benim cennetim, 

İçinde ben varım, sevgi var, sevgim var, 

Sevgi ekilen bacadan, nefret tüter mi? 

Sevgisiz köprüye korkuluk neyler, 

Tam orta yerinde gelir hey heyler, 

Sevelim, sevilelim hanımlar, beyler, 

Şiddeti ancak; sevgi, hoşgörü eyler.

Cennetin çatısına kiremit çektim, 

Kucaklaşın sevenler, sevmeyenler, 

Yeter ki sevginin ışığı sönmesin, 

Cehennem ayazı vız gelir bize.

01.11.2003', 'Ilgıt ılgıt yüreğime esen yeller,  Kalbimin kuytularında barınsın,  Elinde sevgi meşalesi, kapımı çalan... Ilık ılık akan sularımda arınsın....', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cennetin-catisina-kiremit-cektim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunsan', 'dokunsan-omer-serdar-go3sx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne bir eksik ne bir fazlayım

loş odaların halvetinden

aktı akacak dokunsan

camlara biriken bir damlayım ben

dokunamazsın

görüş alanını kapsamışım

ne facia ki

toplanmışım kâselerden

dokunsan ah! dokunsan

azalıp çoğalıp

seni akarım gözlerimden

bilemezsin

ozan biriktiren kristallere

kırk köşeli kesitlerini elmasın

buğulaşan direnmelerime

dokunsan ah! dokunsan

seni akar gözlerim

ha bir eksik ha bir fazla

ne çıkar

o ateş o har yandıkça 

camlara kanasam ben', 'ne bir eksik ne bir fazlayım loş odaların halvetinden aktı akacak dokunsan camlara biriken bir damlayım ben dokunamazsın görüş alanını kapsa...', ARRAY['Türk Edebiyatı','Şiir','Ömer Serdar']::text[], 8.5, '{"poet":"Ömer Serdar","poet_slug":"omer-serdar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dokunsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Sevdalı', 'sana-sevdali-nilay-aksu-8et1m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küçük bir kız oluyorum 

Ellerinde 

Şaşkın, utangaç, sevdalı 

Kendime söylemediklerimden 

Tutuyorsun beni 

Sırrı dökülüyor içimdeki aynanın 

Senin gözlerinde ben 

Sana hırçın 

Sana korkulu 

Çılgın bir aşık oluyorum 

Ellerinde 

Gözü kara, inatçı, sevdalı 

İmkansızlıkların gülüyorum gözlerine 

Uzaklar çözülüyor ellerimde 

Uçurum bir bakıştan 

Tutuyorsun beni 

Senin yanında ben 

Sana vurgun 

Sana tutkulu 

Ateşten bir kadın oluyorum 

Ellerinde 

Arzulu, yangın yeri, sevdalı 

Tenimin çığlığından 

Tutuyorsun beni 

Darmaduman kaçışıyor içimin olmazları 

Senin koynunda ben 

Sana teslim 

Sana yangınlı 

Çaresiz bir aşık oluyorum 

Ellerinde 

Hasretli, elleri bağlı, sevdalı 

Kimseleri koyamıyorum yerine ah 

Dillenmemiş sızılarımdan 

Tutuyorsun beni 

Senin yüreğinde ben 

Sana yenik 

Sana sevdalı', 'Küçük bir kız oluyorum  Ellerinde  Şaşkın, utangaç, sevdalı  Kendime söylemediklerimden  Tutuyorsun beni  Sırrı dökülüyor içimdeki aynanın  ...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sana-sevdali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-esma-ozdemir-g9re2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak, sönüyor ateş

Geliyor rüzgârlar üstüme üstüme...

Hışım gibi yağıyor yine yağmur

Tozumu dumanımı kattılar birbirine!

Bu son çağrıdır yeşillim, uyan! 

Bak, düşüyor ağaçtan yapraklar

Bak, yeniliyorum mevsimine!', 'Bak, sönüyor ateş Geliyor rüzgârlar üstüme üstüme... Hışım gibi yağıyor yine yağmur Tozumu dumanımı kattılar birbirine! Bu son çağrıdır yeşi...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cagri-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahkar', 'gunahkar-muhammed-cankaya-zzc3d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ardına kadar kapatmışım kapıyı

İlk kez içmişim, bulmuşum kafayı

Unutmak için seni 

Silmek için hatıraları

Senin yüzünden oldum günahkar

Bana yaptıkların kalsın yanına kar

Bilsen sensizlik o kadar zor ki

Senin taş kalbini bile yakar

Demek artık yoksun

Bende yokum bundan sonra

Madem ki bana çoksun 

Sevgimi veririm toprağa

Artık rahat uyu

Sen yazdın bu aşkın sonunu

İstememişsin zaten hiç beni

Bundan sonra bari

Ellerinle öldürdüğün sevgimin

Çiçekleriyle doldur kabrini...', 'Ardına kadar kapatmışım kapıyı İlk kez içmişim, bulmuşum kafayı Unutmak için seni  Silmek için hatıraları Senin yüzünden oldum günahkar Bana...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Çankaya']::text[], 8.5, '{"poet":"Muhammed Çankaya","poet_slug":"muhammed-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gunahkar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak', 'toprak-muhammed-cankaya-itfsn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçenlerde bilmiyorsun ne yaptığımı

Önce gizlice seni izledim 

Geçtiğin yolları ezberledim

Sensiz kaldığım bir gün

Belki kokun sinmiştir diye 

O yollardan geçtim

Fakat yağmur izlerini silmiş 

Yere toprak kokusu vermiş

Sen sanıp içime çektim

Ve o gün oradan öylece gittim

Kaç gün oldu gelmedin

Meğer, zaten toprağın altına girmişsin

Boşuna hissetmemişim

Bundan sonra bende bitmişim

Çok yakında sana yetişirim', 'Geçenlerde bilmiyorsun ne yaptığımı Önce gizlice seni izledim  Geçtiğin yolları ezberledim Sensiz kaldığım bir gün Belki kokun sinmiştir diy...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Çankaya']::text[], 8.5, '{"poet":"Muhammed Çankaya","poet_slug":"muhammed-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/toprak-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştüğüm Yere Bakar', 'dustugum-yere-bakar-esma-ozdemir-iwwfh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düştüğüm yere bakarmış yâr

Düştüğüm yerde bekler gözleri!

Dost başa düşman ayağa misali...

Yükseklerde bırakmıştım oysa

Düşlerimdeki sevgiliyi...', 'Düştüğüm yere bakarmış yâr Düştüğüm yerde bekler gözleri! Dost başa düşman ayağa misali... Yükseklerde bırakmıştım oysa Düşlerimdeki sevgili...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dustugum-yere-bakar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslinda,', 'aslinda-serife-goksel-glivw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yine yanliz, 

yari karanlik, 

køhne odasinda, 

masasinda dalgin defteri, 

o kirgin kirik kalemi, 

basladi yazmalarina, 

yanlizliktan hic korkmadan, 

ictigi kavhe sogumus, 

yine bardagi yarim, 

sebebi düsleri, 

belkide yikilisi bir seylerin, 

hep yanliz, 

yari karanlik, 

kalabalik dünyasinda, 

üzerinde siyah ceketi, 

avucunda acinin isareti, 

keskin bakislarinda hala onun hasreti, 

yürüyor yorulmadan, 

ve yanlizliktan hic korkmadan, 

aklindan gecenleri okuyordum, 

duyuyordum, , 

sesindeki aciyi, 

dudaklarinin arasindan, 

sinirleniyordu yine, 

gøruyordum, 

saclarina degen rüzgardan, 

duruyordu, 

bir sigara yakiyordu, 

yapayanliz, , 

bir aksam ayazinda, 

ve øylece daliyordu gøzleri, 

sokak lambasinin, 

yere vuran, 

sari siyah  aglayisina, 

elleri üsüyordu, 

yine gøzleri doluyordu, 

yasamin tam ortasinda, 

hayatinin anlamsiz kalabaliginda, , 

dønüp gidiyordu, 

o bildigi, 

o soguk, 

o karanlik sokaklarina, 

yürüyordu durmadan, 

ve yanlizliktan hic korkmadan, 

buz gibi anahtarini aliyordu, 

sicacik elleriyle cebinden, 

agir agir cikiyordu merdivenlerden, 

daliyordu hüzün kokan, 

huzurlu odasina, 

yanlizdi, 

üsüyordu, 

yari aydinlik odasinda, 

sigarasini yakiyordu, 

bakiyordu akvaryumdaki baliklara, 

gørmüyordu gøzleri oysa, 

onu düsünüyordu, 

icinde kipirdaniyordu, 

ona dair hersey, 

titriyordu bakislari, 

elleri, gøz yaslari, 

saskin, 

caresiz, 

ürkerek, 

dudaklarindan siziyordu, 

onun sevdigi türkü, 

gøzleri geliyordu, 

karsisina, 

ici daliyordu bir an, 

yine, 

yanlizdi, 

hayatin tam ortasinda, 

aksamin yari karanliginda, 

agliyordu durmadan, 

ve ølümden bile hic korkmadan, 

aslinda, 

korkuyordu yanlizliktan,', 'yine yanliz,  yari karanlik,  køhne odasinda,  masasinda dalgin defteri,  o kirgin kirik kalemi,  basladi yazmalarina,  yanlizliktan hic kor...', ARRAY['Türk Edebiyatı','Şiir','Şerife Göksel']::text[], 8.5, '{"poet":"Şerife Göksel","poet_slug":"serife-goksel","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/aslinda-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denge', 'denge-ahmet-aksoy-k1g5v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kırmızı dut boyarken kırmızıya, 

siyah dut boyar siyaha, 

iş böyle işler düzen, 

kırmızı kırmızıya siyah siyaha, 

lakin elbet, bir ademoğlu, 

düzeni bozmak için, çıkacaktır 

bir gün, bayrak açarak, soracaktır 

kırmızı neden, siyaha boyamaz diye 

ki sorunun cevapsız olduğunu bildiğinden, 

gittikçe daha fazla çığırıcaktır, 

düzeni bozmayı umarak, 

denge buna, pabuç bırakmayacaktır fakat.', 'kırmızı dut boyarken kırmızıya,  siyah dut boyar siyaha,  iş böyle işler düzen,  kırmızı kırmızıya siyah siyaha,  lakin elbet, bir ademoğlu,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/denge-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ev li', 'ev-li-serife-goksel-6b5bs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ev uyandi serince, 

suya degdi bembeyaz yüzü, 

kirpikleri islak islak, 

bakislarinda gøkyüzü, 

bakindi aynalara, 

zaman geciyordu usul usul, 

ev kalkti, 

gezindi odalarda, 

küpelerini takti, 

geceye az kalmisti, 

gace yakardi piril piril, 

küpeleri degerdi bembeyaz boynuna, 

degerdi sehrin isiklari, 

o güzel saclarina, 

yagmurlar gelirdi sIk sIk, 

evle aglasir giderlerdi, 

hüznü cøkerdi saclarina  sislerin, 

gizlice bakardi ay gøzlerine, 

ev susardi, 

ay''in suskunluguna, 

ev siirler okurdu 

her gece, 

yildizlara, 

sayfalarca, 

defalarca, 

yildizlar dinlerdi, 

evin gøzlerinde erirdi yildizlar, 

hayat dalardi kalabaliga, 

ev søzlerini cizerken, 

bembeyaz duvarlarina, 

sIkIsIrdI ruhu, 

daracik bedenine, 

diyemezdi kimseye, 

evi severdi cicekler, 

gülüp dururlardi gøzlerine, 

kuslar konardi saclarina, 

cirpinirlardi heyecanla, 

karanfiller eteklerinde, 

ve tüm yollar acilirdi ønünde, 

ev, 

mutluydu kendi kendine oysa, , 

o amansiz gün günes dogmasaydi

yüregini ezenler olmasaydi, 

üzenler olmasaydi,', 'ev uyandi serince,  suya degdi bembeyaz yüzü,  kirpikleri islak islak,  bakislarinda gøkyüzü,  bakindi aynalara,  zaman geciyordu usul usul,...', ARRAY['Türk Edebiyatı','Şiir','Şerife Göksel']::text[], 8.5, '{"poet":"Şerife Göksel","poet_slug":"serife-goksel","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ev-li-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarem', 'carem-tuncay-kiziltoprak-s4btt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dalmışken sonsuz düşüncelere

Ne düşündüğünü bilmeden

Öylesine garip öylesine mahsun 

Kaybetmişken kendimi.

Senin sonsuzluğunda

Çare araken ölesiye

Bulamadım senden

Sonsuzluklarda bir cevap

Sen şimdi ellerdesin

Kimbilir kimlerlesin

Bense sensiz, 

Ne hallerdeyim? 

Bir tohum ektin sonu

Nedir? Diye düşünmeden

Suladın filizlendirdin

Kurumaya bıraktın sonrada

Kopardın kendi ellerinle

Kaldırdın atın bir kenara

Tuncay  KIZILTOPRAK', 'Dalmışken sonsuz düşüncelere Ne düşündüğünü bilmeden Öylesine garip öylesine mahsun  Kaybetmişken kendimi. Senin sonsuzluğunda Çare araken ö...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Kızıltoprak']::text[], 8.5, '{"poet":"Tuncay Kızıltoprak","poet_slug":"tuncay-kiziltoprak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/carem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arama Yokum Ben', 'arama-yokum-ben-osman-velioglu-mo1ti', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün çözülecek katı yüreğin, 

İçinde bir avuç kül bulacaksın. 

Özlemim kalacak ölene değin, 

Aynada kendini el bulacaksın. 

. 

Beni göreceksin baktığın yerde, 

O küller soracak: Ateşim nerde? 

Sanma güzelliğin deva her derde, 

Saksıda, kurumuş dal bulacaksın. 

. 

Yalnızlık dört yandan seni saracak, 

İncinen gururlar hesap soracak, 

Kaybolan umutlar kalem kıracak, 

İnleyen onlarca yıl bulacaksın. 

. 

Çizgiler düşünce yanaklarına, 

Sözlerim çarpacak kulaklarına, 

Adım yapışacak dudaklarına 

İsmimi zikreden dil bulacaksın. 

. 

Bir engin yüreği sunmuştum sana, 

Al dedim. Bu sevda, iç kana kana, 

Seni yaşamayı çok gördün bana 

Geriye dönsen de çöl bulacaksın. 

. 

Bülbüldün, sesine doyamıyordum. 

Senden başkasını duyamıyordum. 

Sözünü kesmeye kıyamıyordum. 

O bağda bir solmuş gül bulacaksın. 

. 

Tatlıydın, iyiydin, güzeldin, hoştun. 

Bende gördün seni, coştukça coştun. 

Kendine vuruldun, kendine koştun. 

Bundan böyle, ıssız yol bulacaksın 

. 

Sen bu şiiri okuduğunda, 

Ruhum izleyecek seni, sağında, 

Gözlerin gözümü aradığında, 

Görebilsen, yalnız sel bulacaksın', 'Birgün çözülecek katı yüreğin,  İçinde bir avuç kül bulacaksın.  Özlemim kalacak ölene değin,  Aynada kendini el bulacaksın.  .  Beni görece...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/arama-yokum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev beni', 'sev-beni-tuncay-akdeniz-hkx7k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sev beni

Aşkın gözü kördür görmez önünü

Gören gözle göreceksen sev beni

Esen yeller değiştirir yönünü

Doğru yöne eseceksen sev beni

Seven razı olmaz ayrı düşmeye

Aşk dediğin benzer akan çeşmeye

Her ummanda geçit olmaz geçmeye

Deryalardan geçeceksen sev beni

Aşkın günahı yok  olmaz tövbekâr

Dört mevsim içinde ikisi bahar

Bülbül gülü için eder ahuzar

Her mevsimde açacaksan sev beni

Yaratanın tutmak haktır emrini

Yürekte saklarsan aşkın yerini

Bu gün değil yarın için ömrünü

Aşk uğruna vereceksen sev beni

Değeri çok bize o giden dünün

Dünyayı kaplasa servetin ünün

Aşk üstüne eğer içmişsen yemin

Sevdasını çekeceksen sev beni

İhanettir aşkın belini büken

Gülünü sevene batarmı diken

Tuncay diyor bize ölüm var iken

Ömür boyu seveceksen sev beni

                                                 10.01.2003', 'Sev beni Aşkın gözü kördür görmez önünü Gören gözle göreceksen sev beni Esen yeller değiştirir yönünü Doğru yöne eseceksen sev beni Seven ra...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sev-beni-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek İbadet', 'sevmek-i-badet-muammer-celik-x0mko', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevmek ibadetse eğer 

gönlündeki mabetten çıkmam asla 

Seninle sevişmek günahsa eger

içindeki aşkı ateşınden çıkmam asla 

BirDeli 

Güz-2001', 'Seni sevmek ibadetse eğer  gönlündeki mabetten çıkmam asla  Seninle sevişmek günahsa eger içindeki aşkı ateşınden çıkmam asla  BirDeli  Güz-...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevmek-ibadet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuva İstiyorum', 'yuva-i-stiyorum-muammer-celik-9m49w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Önce bir selam 

arkasından sade bir dostluk 

daha sonra sırdaşlık, serdaşlık 

birde sevgi ile aşk istiyorum

Gönlündeki bahceye gül saçtım 

yüreğindeki yele yelken açtım 

içindeki denize kulaç attım 

Yüreğinde herkesten büyük yer isterim 

tüm yüreginin gönlünün hepsini 

arkadaş ötesi dostlugunu

sırdastan öte sevgini isterim 

başıma taç, gönlümde sultan KADIN isterim

Bunlarda yetmez elbette

yanında birde meşk isterim 

karışalım sevda kervanına 

biraz kavga, biraz tartışma

tuzumuz, biberimiz, baharatimiz 

saadet ve mutluluk yaşantımız 

paylaşmak ise evimiz olsun isterim… 

BirDeli

15.11.2001', 'Önce bir selam  arkasından sade bir dostluk  daha sonra sırdaşlık, serdaşlık  birde sevgi ile aşk istiyorum Gönlündeki bahceye gül saçtım  y...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yuva-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelir misin..?', 'gelir-misin-umut-gul-btu1n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben mecnunum sevda çöllerinde

Çatlayan dudağıma bir yudum su verir misin? 

Beklesem  seni yıldızlı bir gecede

Mehtabı peşine takıp gelir misin? 

Buz tuttu  yüreğim zemheri ayazında

Gözlerinden bir parça sıcaklık verir misin? 

Sevdanın sıtmasıyla titriyor bedenim

Güneşi ellerine alıp da gelir misin? 

Gözlerini gözlerime, ellerini ellerime

Yüreğini sevdama ödünç verir misin? 

Gel desem bir akşam güneşin battığı yere

Yüreğine kanat takıp ta gelir misin? 

Yüreğindeki sakladığın sevda güllerinden

Umuda bir tomurcuk verir misin? 

Gönlümün  kapısını açsam sevdana

Tacını, tahtını atıp ta gelir misin?', 'Ben mecnunum sevda çöllerinde Çatlayan dudağıma bir yudum su verir misin?  Beklesem  seni yıldızlı bir gecede Mehtabı peşine takıp gelir mis...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelir-misin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Sensizlik', 'sessiz-sensizlik-muammer-celik-njty1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessiz

Suskun 

ve

Soluk bir yüz… 

Yapraklar sarardı 

geldi yine güz... 

Açıyor güzün gülleri 

Sarı 

Kırmızı 

ve 

mos-mor… 

sensiz anlamsız mevsimlerin 

sensiz açan gül ve çiçeklerin

hazanı güç 

hasatı cok zor…

BirDeli

07.10.2002', 'Sessiz Suskun  ve Soluk bir yüz…  Yapraklar sarardı  geldi yine güz...  Açıyor güzün gülleri  Sarı  Kırmızı  ve  mos-mor…  sensiz anlamsız m...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sessiz-sensizlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onsuz onun ikisi', 'onsuz-onun-ikisi-hakan-ak-ezl1u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '...bir zamanlar

söz karışmışken

vakti gelmişken

geç geçebilirsen

birde geç kalmışlığına

gelde seç eskimişliği

nerden nezamana

ne zamnadan yanıma

gelde gel gelebilirsen

zamanı tutursamda 

konuşamıyorum

tutturulmuş tutulmuş

her yanım 

hangi tarihti

bilmem ama

umuttur

unutulmamış 

hiçbir şeyin

10/03/200(hatırlamıyorum) 3', '...bir zamanlar söz karışmışken vakti gelmişken geç geçebilirsen birde geç kalmışlığına gelde seç eskimişliği nerden nezamana ne zamnadan ya...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ak']::text[], 8.5, '{"poet":"Hakan Ak","poet_slug":"hakan-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/onsuz-onun-ikisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alacalı...', 'alacali-hakan-ak-k9h6k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidemeyişler

ne güzel günlerdi onlar hepsi geçti ve bitti ne geri gelir nede benzerleri yaşanır bundan sonra zamanın kayboluşu hayatın yaşlanışı gençliğin sararışı ne dersen de artık hiçbirşey eskisi gibi olmayacak... şimdi bundan sonra ilelebet yaşlanacağız yaşarırken gözlerimiz hüzünlenirken cümlerimiz kırık bir aşkın anlatılamayışınıyaşamaklı iken sever iken geceleri sahile çarpan dalgaların sesini izlerken mecnun ile leylanın hikayesini ve sessiz', 'Gidemeyişler ne güzel günlerdi onlar hepsi geçti ve bitti ne geri gelir nede benzerleri yaşanır bundan sonra zamanın kayboluşu hayatın yaşla...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ak']::text[], 8.5, '{"poet":"Hakan Ak","poet_slug":"hakan-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/alacali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lazım', 'lazim-hakan-ak-wedwy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herşeyin sonrasında 

bitip tükenmeyen yol

karanlık gözleri ile

zamana meydan okuyan

kararsız bir gürültü

ortasında yanlızlık

süslü parmakları ile

hayatsız kalmış yaşam

vEseN_ 

Dönüşü olmayan yol

içinden gelene çıkmaz

katlanmış yıl

eskimiş aşık

sonrası karmaşık

yolcu kimisine

kalıcı uzaklık

tek sevdalık

suskun kimisine

buruşuk tutsaklık

kuruşsuz zenginlik

deli kimisine

küskün birisine

ölesiye 

kıpırdamaya mecali olan fazlası kalan bir kaç kelam.. onlarda dökülmekte bir yanda gece olmuşluğu bir yanım uykularında... sabahın en geç gelişinde bir yanımda bir yanında anlamsız kalakalmışlığında 

...sonrasında düşünülen başka başka şeylere hakedercine hakettiği kadara ve değercesine yaşamak yaşyıp ölürcesine', 'Herşeyin sonrasında  bitip tükenmeyen yol karanlık gözleri ile zamana meydan okuyan kararsız bir gürültü ortasında yanlızlık süslü parmaklar...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ak']::text[], 8.5, '{"poet":"Hakan Ak","poet_slug":"hakan-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/lazim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakınımda Uzaklarda Olan Yar', 'yakinimda-uzaklarda-olan-yar-sinan-potur-yj0mg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu kahırdır senden bana 

ilmek ilmek  yolladıgın 

bogazıma  dügümledigin

işte bir kahırdır senden gelen

yoruldum artık  senden gelenlerden 

yoklugunda varlıgından 

neredesin sen 

yakınımda uzaklarda olan yar

kaçıyorum artık her halimden

yoklugundan varlıgından 

yorulmaktan  kaçıyorum

yakınımda uzakta olan yar

gölgelerden bana bakan suratlardan 

durmadan yılmadan 

bana yolladıgın sonsuz kahırlardan 

kaçıyorum sorumsuzca bilmeden sendende 

bu bir kahırdır senden bana

yollamaktan bıkmadıgın, 

alıp başımı gitmeden sonkez 

söylemeliyim seni sevdigimi 

yakınımda uzakta olan yar', 'bu kahırdır senden bana  ilmek ilmek  yolladıgın  bogazıma  dügümledigin işte bir kahırdır senden gelen yoruldum artık  senden gelenlerden  ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Potur']::text[], 8.5, '{"poet":"Sinan Potur","poet_slug":"sinan-potur","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yakinimda-uzaklarda-olan-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rastgele Yaşayana 1', 'rastgele-yasayana-1-okan-savci-jy8cd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ayrılamıyorsan; 

ayrılmış gibi 

seviyorsan; 

sevmemiş gibi yapacaksın...

ve gitmeyi de öğreneceksin, 

ardına bakmadan.

masumiyeti yitirdin çünkü.

konuşacak çok şeyin olsa da, 

buna bir dakikan bile yok...

zamanı tükettin sen 

ne yüzün ilk günkü yüz

ne de sesin... 

aslını da kaybettin sen. 

dağıttığın yerlerden kendini

şimdi git de topla, 

toplayabilirsen...', 'ayrılamıyorsan;  ayrılmış gibi  seviyorsan;  sevmemiş gibi yapacaksın... ve gitmeyi de öğreneceksin,  ardına bakmadan. masumiyeti yitirdin ç...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/rasgele-yasayana-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rastgele Yaşayana 2', 'rastgele-yasayana-2-okan-savci-6tke7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öğrenmiş olmalısın, 

kendini özlediğin şu günlerde; 

“bütün” kalmanın

ne kadar anlamlı olduğunu... 

ki sen bölünmüşsün insanlara

her parçan ayrı yerde...

ne çok sevinirdin değil mi

sil baştan 

yaşama şansı verseler? 

senin için ne iyi olurdu.....

uyanmak istemezdin bazı sabahlara, 

bazı gecelere dur derdin.

inanmak istemesen de biliyorsun, 

zamanın geç olduğunu.

mutsuzluğun bundandır senin....', 'Öğrenmiş olmalısın,  kendini özlediğin şu günlerde;  “bütün” kalmanın ne kadar anlamlı olduğunu...  ki sen bölünmüşsün insanlara her parçan ...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/rasgele-yasayana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rastgele Yaşayana 3', 'rastgele-yasayana-3-okan-savci-u0h91', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'varlığından çok daha samimi

yokluğun inan.

sessizliğin, 

sesinden daha sıcak

özün bende çünkü.

böyle olunca bir sebep yok, 

senden kaçacak.

Şimdi kendine soruyorsun

“ben neredeyim” 

arama nafile

çaldım seni belli etmeden, 

sakladım özünü içimde

görmeyeyim yeter ki

yoksa büyü bozulacak. 

sevmek; 

bazen de böyle.....', 'varlığından çok daha samimi yokluğun inan. sessizliğin,  sesinden daha sıcak özün bende çünkü. böyle olunca bir sebep yok,  senden kaçacak. ...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/rasgele-yasayana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rastgele Yaşayana 4', 'rastgele-yasayana-4-okan-savci-9zw5s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gülmek, yüzünün yalanı

sevmek dilinin.

O bakışlar gözlerinin yalanı, 

Bütün yalanlar sendeyse; 

Seni karşıma çıkaran hayatın, 

Yalanısın sen de...

Anlamadın değil mi? 

Öyleyse zorlama

Hayat zaten bir tekerleme...

Olur da söylemek istersen 

Tekleme! 

Ve her söyleyişte zorlaşır 

Deneme! 

Bana gelince? 

Ben hala ilk satırdayım 

Yüzünde mahsur kaldım

Sen bu şiirden 

Bir şey anlamadın bence', 'gülmek, yüzünün yalanı sevmek dilinin. O bakışlar gözlerinin yalanı,  Bütün yalanlar sendeyse;  Seni karşıma çıkaran hayatın,  Yalanısın sen...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/rasgele-yasayana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karışıyor Sakallarıma Sigara Dumanı', 'karisiyor-sakallarima-sigara-dumani-okan-savci-6z3w6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen sakallarıma karışmış, 

Sigara dumanı kadar yakındın bana 

Bazen en derin uçurumların dibinde, 

Ulaşılması zor bir kadındın...

Gitmeseydin ne iyi olurdu, 

  seninle birkaç yıl yaşlanmak...

Yokluğunda bile dilime takılıyor adın.

Tam da yakalamışken hayatı ucundan 

Tam da alışmışken elinin sıcaklığına

Süzülüp gittin avuçlarımdan.

Ne çok inanmıştım sana, bilsen...

Sanki hiç gitmeyecek gibiydin

Gafil avladı ayrılığın

Girdiğim hangi günahın bedelisin sen...

Olsun be ne olacak? 

Varsın ellerinin yerine kadehler doldursun, 

     avuç içimi...

Varsın buz gibi şişeler soğutsun

     bıraktığın sıcaklığı...

Ben alışığım bu hasrete

Alışığım her öleni

Şiirlerde diriltmeye

Odamda bir efkar, 

Sorma gitsin...

Artık uçurumun dibindeki, 

o kadın değilsin...

yanımda biri, yüreği sitem dolu 

vurdukça vuruyor sazına

Ve yine bir sigara dumanı, 

Karışıyor sakallarıma...', 'Bazen sakallarıma karışmış,  Sigara dumanı kadar yakındın bana  Bazen en derin uçurumların dibinde,  Ulaşılması zor bir kadındın... Gitmesey...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/karisiyor-sakallarima-sigara-dumani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenlere', 'gidenlere-derin-oger-vy0pq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göz görmez gönüldür beklemede

Aşk kapısı bir gün duvar olur önünde

Sevendir yüreğini serer aşkın merdivenlerine

Yatak  yorgan yastık halı yerine

Donuk gülüşüyle koyar sevdasını orta yere

Zulüm üşüşür yaş çiseler gözlerinde

Kıyamaz umuduna elele tutuşur yüreğiyle

O yüreğe ulaşmaz koparılıp atılmalar

Yeniden çiçek açar bağ bahçe yar yeşiline

Yazık ki yazık çiğneyipte gidenlere.......', 'Göz görmez gönüldür beklemede Aşk kapısı bir gün duvar olur önünde Sevendir yüreğini serer aşkın merdivenlerine Yatak  yorgan yastık halı ye...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gidenlere-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar 1-Efendimize Şiirler-', 'yar-1-efendimize-siirler-refik-yildiz-gbp37', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu hal

Sende var

Dünya gelse

Gelmez yar...! 

Öyleyse ne var

Yoksa

Dünya senin olsa

Etmez yar...! 

Yar diyorum yar

Gayri ne var

Başım eşiğinde

Bin yıl kalsın yar...! 

Ey varlığın sebebi

Nazdar yar

Fatımanın babası

Müşfik yar! ...

Biliyorum ancak sen

Sen kabul edersin yar

Kirlerimi yusun tevbe

Kucak açarsın yar! ...

Gedalık bana

Sultanlık sanadır yar

Başımı kaldıramam

Hicap ederim yar

Gözyaşı temizlesin

Ruhumu yar

Kabul eyle gedanı

Lutfeyle Efendim

Lutfeyle yar...!', 'Bu hal Sende var Dünya gelse Gelmez yar...!  Öyleyse ne var Yoksa Dünya senin olsa Etmez yar...!  Yar diyorum yar Gayri ne var Başım eşiğind...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yar-1-efendimize-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar 2', 'yar-2-refik-yildiz-g7vjm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zümrüt altına dönmüştü o vadide

Sararıp dökülen yapraklar

Sarının her tonundan halı dokurlar

Hafif bir rüzigar esiverince

Ürkek kelebekler gibi uçuşuverirler

Yamaçları sis doludur yüce dağların

Zirveleri kar doludur kar

Fasıla vermeden pınar sunarlar

Ağaçlar irkilir de tesbih çekerken

Saçlarıma tutam tutam çiğ serperler

Ağaca düştü mü çiğ, kışı getirir

Tıpkı saçlarıma düşen çiğler gibi

Yaprakların üstüne bir gecede doluşuverirler

Kar yağdı mı, susar ormendeki kuşlar

Ve bahara kadar uyurlar

Ya insanoğlu? 

Yaz günleri tükenmez gibidir

Kış günleri sonsuz uzakta

Lakin bir gece ve sessizce

Ömrün sobaharı geliverir

Düşünüp dolaşırken bir güz sabahında

Düşen her yaprakla kırıldı gönlüm

Hüzün, bir buğu gibi dolanır gözde

İmdat isterim maziden yara getirir

Bilirim bu son bahar kışı getirir

Kalbim güz rüzigarlarıyla kırıldı

Düşen her yaprağı yağmur yıkıyor

Rüzigarlar taşıyıp mezar kazıyor

Tıpkı insanoğlu gibi onlar da ölür

Lakin onların gassalıdır yağmurlar

Bu son kıştır söyle

Ümidin, heyecanın, korkuların nerede? 

Kin biter, öfke ölür bu mevsimde

Ve bir baharı bekler ümitle

Yere düşen tohum gibi insanoğlu da

Elde ne var? 

Ötede yar

Çağırmazsa seni

Çağırır yar

Çare yok, dönülmez mezardan

Öyleyse gel

Sende gel

Maksudun olsun yar

Tutuversin de elinden

Doğumun olsun bahar', 'Zümrüt altına dönmüştü o vadide Sararıp dökülen yapraklar Sarının her tonundan halı dokurlar Hafif bir rüzigar esiverince Ürkek kelebekler g...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yar-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaller ve gerçek', 'hayaller-ve-gercek-erdem-ozarslan-9c73v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beyaz düşlerinle geldin zamana

Ellerini hep uzattın dostluğa

Dalıp giderken yarınlara

İlerledin hayatta; içinde sadece senin bildiğin acılarla

Şaşırdın bazen insanlara, yaşananlara, ama anladınki hayattı bu aslında...', 'Beyaz düşlerinle geldin zamana Ellerini hep uzattın dostluğa Dalıp giderken yarınlara İlerledin hayatta; içinde sadece senin bildiğin acılar...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özarslan']::text[], 8.5, '{"poet":"Erdem Özarslan","poet_slug":"erdem-ozarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hayaller-ve-gercek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlarım Aldırma', 'daglarim-aldirma-sule-aydemir-1ujni', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'beni benden aldın 

içime hüzünden yangın saldın

kim söyle kim bilebilirdi 

en saklı sandukalarımı

çeyizimdi tüm sevgi çeşitleri

kullanmadan naftalin kokularında 

takıldı kaldı 

mutluluğu bilmezdim

ağlatırdın ya sevdamı

saklardım bir kese içinde

acılarımı göz bebeklerimde

gözlerimin içi 

ve sen derya 

hiç görmediğin eladan rengi

ben gün ışığında

iyi bir gündüzüm

kimse bilmez gecelerimi

ipek gergef yoldum

içimden geçtin gittin

dağlarım ben aldırma

kanayan bekçimi', 'beni benden aldın  içime hüzünden yangın saldın kim söyle kim bilebilirdi  en saklı sandukalarımı çeyizimdi tüm sevgi çeşitleri kullanmadan ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/daglarim-aldirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Elveda', 'son-elveda-muammer-celik-e8cvy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her elveda deyişinde

”KAL” der gibisin

her kal deyişinde

”GİT” der gibisin... 

Bir karar ver 

eyy sevgili.. 

Ya git de, KALAYIM

ya kal de, GİDEYİM

Belki de; 

Bu kaçıncı elveda deyişin dir

Bu kaçıncı son yazılan şiirin dir

Kim bilir…? 

BirDeli

02.11.2003', 'Her elveda deyişinde ”KAL” der gibisin her kal deyişinde ”GİT” der gibisin...  Bir karar ver  eyy sevgili..  Ya git de, KALAYIM ya kal de, G...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/son-elveda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedinci Suvari', 'yedinci-suvari-muammer-celik-a7qcc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yedinci atlı

sonuncu süvari

atının nal sesleri geliyor...! 

Mahşerin habercisi 

SÛR üfleyecek sanırım

Kanı Deli

kendi zır Deli

hepsi Birdeli...! 

Erkekliğin kitabı ne ise, bilmem 

Kadınlık kitabı yazan da olmalı 

bence 

en önemlisi İNSAN olmalı

önce…! 

BirDeli

02.11.2003

(M.S. VAROL’un güzeller güzeli bir şiirine esinti)', 'Yedinci atlı sonuncu süvari atının nal sesleri geliyor...!  Mahşerin habercisi  SÛR üfleyecek sanırım Kanı Deli kendi zır Deli hepsi Birdeli...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yedinci-suvari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açık Bilet', 'acik-bilet-burcu-karakaya-qnt4o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elinde bir cigaralık, 

Nereleri gezersin babalık, 

Belki çocukluk benimkisi, 

Tabii marifet seninkisi, 

Saklamaya çalışma, 

Yaşama bağlılık bende senden çok, 

Uzun yaşarım sanma, 

Ahiretine henüz ''açık bilet''  yok...

....Bitik insanlığa kısa bir sitem....

C.Burcu Karakaya

02/11/2003

Antalya', 'Elinde bir cigaralık,  Nereleri gezersin babalık,  Belki çocukluk benimkisi,  Tabii marifet seninkisi,  Saklamaya çalışma,  Yaşama bağlılık ...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/acik-bilet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Fazla Yalnızlık Bu', 'cok-fazla-yalnizlik-bu-oguzkan-bolukbasi-sski8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok fazla yalnızlık bu

Dağınıklığını içime sindiremediğim

Göz bebeklerin beni tanır

Yüreğin benimle ısınır sanırdım

Yanıldım inançlarımı senin avuçlarına bıraktığım şehirde

Daha neler bırakmışım şaşırdım

Bu yalnızlık bu şehire sığmıyor

Ya şehri boşaltın yada beni dağlara kaldırın ki gökyüzüne yakın olayım

En sağdan birmilyonuncu sıradaki yıldızlara söyleyeceklerim var

Gecenin olmasını bekliyorum

Ki onlar  sokağa çıkacaklar

Kuş olup belki de omuzuma konacaklar

Hayaliydi ışığa karşı yakınlığım

Göz kamaşıklığıma da dayanırdım

Aydınlığın üzerimden yayılmasını seyrederken

Şehir  güne hazırlanıyor

Ben saklanacak yer bulamıyorum

Yalnızlık bu 

Kalabalıktan hoşlanmaz

Ama bir bilse kalabalık kendisini görmüyor

Gözleri biribirine değmeyenlerin kentinde yaşıyoruz

Açığa çıksam ne olacak

Sokaklarda dolaşan kör görünmezliğinde 

Seni tutuklayacak bir çift bakış mı yakalayabilirsin

Çok fazla yalnızlık bu

………………………….çok fazla.', 'Çok fazla yalnızlık bu Dağınıklığını içime sindiremediğim Göz bebeklerin beni tanır Yüreğin benimle ısınır sanırdım Yanıldım inançlarımı sen...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cok-fazla-yalnizlik-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit ve Endişe+', 'umit-ve-endise-bayram-tunca-n3wuz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gün geleceğini öyle ümit ederim ki 

Güneşin her sabah doğacağı katiyetinde

Gidişine her seferinde öyle üzülürüm ki

Şemsin ya doğmazsa kaygısı nispetinde

01.11.2003-11:01

Aşk Ateşten Gömlek', 'Her gün geleceğini öyle ümit ederim ki  Güneşin her sabah doğacağı katiyetinde Gidişine her seferinde öyle üzülürüm ki Şemsin ya doğmazsa ka...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/umit-ve-endise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilgaz', 'ilgaz-emin-baydil-9f9n5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ilgaz heyy! Yine geldim, baksana Urfa nere

Kastamonu-Çankırı, memlekete taç Ilgaz.

Nice hana uğradım, aç-susuz neler gördüm

Gâriplere sor beni, kollarını aç Ilgaz.

Senin, benim gözyaşım birbirine karışır

Sende naz, bende inat usanmadan yarışır.

Bilirsin, yarın bayram düşman olsa barışır

Anladım ki büyüksün, bende hata, suç Ilgaz.

Senden geçen yaşlanır, şu var ki çeyrek asır

Sanki bağdaş kurmuşum, hem de bağrına hasır.

Kağnıların can taşır, akşamdan sabaha sır

Ankara''dan şu kara, denize kulaş Ilgaz.

Dört bir yanda söylenen, efesi namlı senin

Anlat, neler yaşadın, hem dertli, gamlı senin.

Çomağın, suyun kara, ormanın çamlı senin

Dökülse de başından, aklarını saç Ilgaz.

Beğdili''ye sözün var, unuttun mu be Ilgaz? ! 

Büklüm büklüm yollara, yolcuya gebe Ilgaz.

Sana uymak mı hâşa! ..Bir daha tövbe Ilgaz

Yeter ki sen yolum ol, derdime ilaç Ilgaz.', 'Ilgaz heyy! Yine geldim, baksana Urfa nere Kastamonu-Çankırı, memlekete taç Ilgaz. Nice hana uğradım, aç-susuz neler gördüm Gâriplere sor be...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ilgaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi öğrenmeden yaşadım.', 'sevmeyi-ogrenmeden-yasadim-ali-osman-yilmaz-ql11d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Varlık içinde yokluğu yaşamak, 

Ne demektir bilirmisiniz? 

Anneniz vardır ama; yokturda, 

Sarılmak istersiniz, olmaz hiç yanınızda, 

Babanızı ararsınız ananın yokluğunda, 

Uludağın tepesinde yatar, senatoryumda, 

Camdan uludağa bakıp iç çekersiniz, 

Camın kenarında siz ve ağabeyiniz, 

Fabrikada çalışır canım annem benim, 

Evini geçindirmekle yükümlü sayar kendini, 

Göçmenliğin acısını derinden yaşamakta, 

Gençtir güzeldir, kadınlığını bile yaşayamamakta, 

Evde çocuklarına anne, kocasına olacak eş, 

Aynı zamanda kocasına bir hasta bakıcı, 

Yaşayacak insanlığını bilmeden, hayat bu, 

İnsanlar  böyle yaşamak zorunda, ne acı.

Bazen sabah erkenden, bazen gece yarısı, 

Fabrikaya gidecek, çalışıp eve para getirecek, 

Ev işlerini yapıp, yorgun bedeni, evlatların sevecek, 

Arada kocasıyla yatakta kadınlığını giderecek, 

Kader bu, ne yapsın, öyle yazmış yaradan, 

Hiç şikayet etmeden, kaderini kabul edecek, 

Böyle bir ortamda yetiştik biz üç kardeş, 

En büyüğümüz, hem haylaz, hem kalleş, 

En küçüğü ise, el bebek kıyılmaz ona, 

Bakın neler çekmekte anneyle birlikte, ortanca, 

Her sabah kimi amele, kimi işçi çimentoda, 

Aşk nedir, sevda nedir bilmeden yaşamış, 

Aferin çeker çevredekiler o ortanca oğlana.

Bayramları sevmedi hiç ortanca oğul, 

Bayram kaç gün ki, bitecek haydi işe koyul, 

Doyamadan bir sofrada anneyle babaya, 

Saatin geldi, haydi koş çimentoda çalışmaya, 

Bekleyecek bir yıl daha, gelsin diye bayram, 

Kardeş, ana baba oturmak için hasretle sofraya.

Böyle yaşarken başladım üniversiteye, 

Doğu illerinden birinde, hemde mühendisliğe, 

68 kuşağı imanıyla çıkarmak için ülkeyi esenliğe

Bilirsiniz izin vermez düzenden sebeplenenler, 

Ellerinde yasalardan bir balyoz, devam halkı ezmeye, 

Değiştirmek istediğimiz için yatırdılar bizi işkenceye, 

Düzeni düzeltmek için çabalamaktan bulamadık vakit, 

Gönül bahçemizde açacak, gençliğimizi kanatlandıracak, 

Bir güzelin gamzesinde kırmızı gül olup açacak, 

Sevgi bahçesinde sevda çiçeklerine türkü yakacak, 

Elele tutuşucak, göz göze bakışıp, aşk harında yanacak, 

Karar vermişler beyler, bu kuşak böyle haracanacak.

Bu hal ve şeriat içinde yetiştim, sevdayı bilmeden, 

Bir güzele tutulmayı öğrenemedim, sormadım neden? 

Sevmek benimde hakkım değilmi? insan gibi sevmeden, 

Yaşamaya kim mahkum etti beni? bilmedim neden, 

Öğrendim sevmeyi, aşık olmayı, ömrümün yazında, 

Okursunuz, şarkı, şiir, yazarım o güzelin hakkında, 

Kader bu, kötü yazılmış, kavuşmayacağım bilirim, 

Ah çeke çeke öleceğim, Mutlu ol yeter sen sevdiğim.

02.Kasım.2003', 'Varlık içinde yokluğu yaşamak,  Ne demektir bilirmisiniz?  Anneniz vardır ama; yokturda,  Sarılmak istersiniz, olmaz hiç yanınızda,  Babanız...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sevmeyi-ogrenmeden-yasadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Türlü', 'bir-turlu-emin-baydil-xg7x9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başına geleni bilirim elbet, 

Söylemeye, dilim varmaz bir türlü.

Korkarım ki, yaran deşilir hepten

Sonra da şu dilim, durmaz bir türlü.

Mevlâ''nın kuluyum, canım adarım, 

Elbette fanîyim, ben de giderim.

Dostuma her işim, ters gitti derim

Balıklar oltaya vurmaz bir türlü.

Koyunla kuzuyu ayırmış kader, 

Burda; güller mahzun, bülbül derbeder.

Eskiden her mevsim, baharmış meğer, 

Çiçeği, şu gönül, dermez bir türlü.

Sanki, Dicle''yim ben: sen, Fırat gibi, 

Yolumuz Basra''dır, hüsn-ü hat gibi.

Müebbed mahkûmla beraat gibi, 

Kolkola gezer de sormaz bir türlü.

Kapalı Çarşı''da sarraf olaydım

Tartılıp ben dahi, bir af olaydım.

Biraz da sılâdın taraf olaydım

Ilgaz bu! ..Yolları, vermez bir türlü.', 'Başına geleni bilirim elbet,  Söylemeye, dilim varmaz bir türlü. Korkarım ki, yaran deşilir hepten Sonra da şu dilim, durmaz bir türlü. Mevl...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-turlu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anasam''a Gel', 'anasam-a-gel-ali-bas-tnhyh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anasam ilim ve meslek birliği, 

Gayesi şairin düzen dirliği, 

Başlatmış sanatsal seferberliği, 

Dostum Anasam''ı yaşatalım gel, 

Bütün gönülleri kuşatalım gel.

Onlarca eseri basılmış bakın, 

Başarıya ermiş mazisi yakın.

Bilmeyeni hakir görmeyin sakın, 

Dostum Anasam''ı yaşatalım gel, 

Bütün gönülleri kuşatalım gel. 

Birlik beraberlik tohumu ekip, 

Sanat bahçesine fidanlar dikip, 

Sen-ben davasını çöplüğe atıp, 

Dostum Anasam''ı yaşatalım gel, 

Bütün gönülleri kuşatalım gel.

Açıktır kapanmaz gönül kapısı, 

Başkanı Sabit bey İNCE yapısı, 

Kayseri ilim ve kültür tapısı, 

Dostum Anasam''ı yaşatalım gel, 

Bütün gönülleri kuşatalım gel.

Aşık Seziniyem sezdiğim budur, 

Gönülden görüp de dizdiğim budur.

ANASAM hakkında yazdığım budur, 

Dostum Anasam''ı yaşatalım gel, 

Bütün gönülleri kuşatalım gel.

1.4.2000 kayseri', 'Anasam ilim ve meslek birliği,  Gayesi şairin düzen dirliği,  Başlatmış sanatsal seferberliği,  Dostum Anasam''ı yaşatalım gel,  Bütün gönüll...', ARRAY['Türk Edebiyatı','Şiir','Ali Baş']::text[], 8.5, '{"poet":"Ali Baş","poet_slug":"ali-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/anasam-a-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı', 'sarki-mustafa-tanrikulu-fa0t1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tak boynuma sevdâ gibi esved saçını yâr

Â sevgili küfrün kulunu eyleme azad.

Saçlar kara gözler kara û sahib-ihtiyâr

Â sevgili küfrün kulunu eyleme azad.

Sevmek seni kalbime vermekte zîyan

Etmem, edemem yine feryâd u figan

Ah sevgili tak boynuma zülfünden urgan

Â sevgili küfrün kulunu eyleme azad.', 'Tak boynuma sevdâ gibi esved saçını yâr Â sevgili küfrün kulunu eyleme azad. Saçlar kara gözler kara û sahib-ihtiyâr Â sevgili küfrün kulunu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sarki-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekirge Azlediliyor! ... (Hoca ile Çekirge 4 - Yamuk Yazı)  *', 'cekirge-azlediliyor-hoca-ile-cekirge-4-yamuk-yazi-naime-erlacin-50cn5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Hoca ile Çekirge – 4.Bölüm)   

-ÇEKİRGEEEEE! ! !

-Emret hocam! 

-Ne haltlar karıştırdın yine sen? 

-Af buyurunuz. Anlayamadım üstad? 

-Anlamayacak ne var? O şiirleri ben yazmadım herhalde. Anarşi-manarşi demişsin hani…

-Tabii ki ben yazdım ve ayrıca her dizenin altına dönüp bir daha imzamı atarım. Hem ne varmış benim şiirlerimde? 

-Daha ne olsun? Baştan aşağı küfür dolu.

-Estağfurullah Hocam, olur mu öyle şey? Gerçek dışı tek satır yazmam ben.

-Senden şair filan olmaz! Yazıklar olsun verdiğim bunca emeğe! Tez azlediyorum seni çıraklıktan….

-Paşa gönlün bilir hocam. Ben “şair” olduğumu söylemedim ki hiç. Onu diyen de, demeyen de başkaları...

-AZLEDİLDİN! ! !

(Hayırdır inşallah. Durduk yerde yeni bir YÖK krizi demektir bu. Olsun varsın. Milletçe alışkınız biz kriz çıkartmaya. Kriz yoksa eğer, yaratıveririz bir tane. Tansiyonumuzu yükseltmeden yaşayamıyoruz ki! RTÜK’e çatarız; bir davetiye meselesi atarız ortaya; bağımsız kurumları lağvetmeye kalkışır ve böylece borsayı sallar; bono, mevduat faizleri ve döviz kurunu yükseltiriz. Hiç olmadı savaşa girmeye karar veririz. Sonra da gelsin işyeri kapatmaları; sanayide kapasite kaybı, işsizlik oranında rekor yükseliş, vs., vs… Daha olmazsa, birkaç banka batırır veya Anayasa’yı delmeye çalışırız. Onu da beceremiyorsak eğer, bilir bilmez şiir eleştiririz, olur biter!

Krizden bol ne var memlekette? Hem böylece yazarlara da iş çıkıyor, fena mı? Profesyoneller, aldıkları astronomik ücretleri başka türlü nasıl hak edecekler? Üstelik pek çoğu, ne kadar şanslı olduğunun farkında bile değil. Mizah ve güncel yazı üretenler için bundan daha verimli bir coğrafya bulunur mu hiç?

“GÜNCEL HAZİNEDİR”. 

(Çalışma masalarının arkasına çerçeveletip asmak lazım bunu! En iyisi branş değiştirmek galiba….)   

-Çekirgeeee! Sesini duymuyorum. Yine ne şeytanlık peşindesin? 

-Azledildim ya hocam. Kendime yeni bir uğraş arıyorum.

-Buldun mu bari? 

-Tabii ki buldum… Rusya’da son günlerde patlak veren Yukos krizine yoğunlaşacağım. Ucu, nasıl olsa bize de dokunacak. (Dokunmayanın canı acıyor zaten!)   

Kısa vadede mali piyasaları olumlu yönde etkileyebilirler ancak seçim sonrasında sular durulduğunda piyasadan yabancı çıkışları başlayabilir pekâlâ. Başımıza bir dolu dert açıyor bu komşu. Ekonomileri bir sallandı; biz çöktük. Vallahi ne Arjantin, ne Uzak Doğu bu denli kuvvetli vurmamıştı. Adamların petrol ve doğalgaz geliri bol. Bellerini doğrulttular ama biz halen debeleniyoruz…

-Delirdin mi sen Çekirge? Bu gidişle Putin’den bile hesap sorarsın sen.

-Sorarım tabii. Adamın adına takmış durumdayım zaten. Rusya’nın başına ne geldiyse bu Putin’lerden geldi. Rasputin yetmemişti, bir de bu çıktı başımıza. Üstelik doğalgaz fiyatlarını da indirmiyorlar. İran’la gizli ittifak mı kurdular, nedir? Bu demek ki, gariban vatandaş yeryüzünün en pahalı enerjisini tüketmeye devam edecek. Yakıt fiyatlarının yanına yanaşılmıyor. Ya açlıktan öleceksin ya da soğuktan donarak. Üretim ise hak getire! 

Neyse ben yazayım biraz….

                                 ………………..

-Okudum yazını Çekirge. Evlere şenlik! Vallahi numuneliksin. Uğraşmadığın bir şey yok mu senin? Geçen gün de boyalardaki kimyasal maddelere takmıştın.

-Neden takmayacakmışım? Belirli renklerin içine katılan kurşun oranı çok yüksek. Sonuçta metabolizmayı olumsuz yönde etkiliyor. Bu yüzden, ressamların çoğu kanserden gidiyor. Yazık değil mi adamlara? Bebek karyolalarına vurulan boyanın zehir oranıyla ilgileniyoruz da, yetişkinlere gelince boş veriyoruz. Ne yani, onca emek verip büyüteceksin; sonra da zehre teslim edeceksin insanları. Antioksidan filan da kâr etmiyor bu tip zehirlenmelerde. Özellikle kurşun zehirlenmesinde.

-Bana kalırsa, senin içindeki kurşun oranı had derecede yüksek. Sağlığımı tehdit ediyorsun artık! 

-Boşversene Hoca. Oto-sansürümü bir kaldırsam var ya, “küt” diye gidersin vallahi! 

-Yıkıl karşımdan. Belâ mısın nesin? 

-Aynen öyleyim Hocam. Adımı boşuna “belâ okur” koymadılar. Düşler dünyasına gelmeden önce yorum yazardım, hatırlasana. Okur okur, eleştirirdim. Şimdi de “belâ yazar” olmuşum, çok mu? 

-Bana diyorsun ama asıl kimlik bunalımı yaşayan sensin. Şimdi anladım işte. Çok yönlü olmaya karar vermişsin ancak yönünü kaybetmişsin bana kalırsa.

-Karanlıkta bile yolumu bulurum ben. Sen hiç merak etme Hocam. Ayrıca çok yönlü olmanın ne zararı var, anlamadım doğrusu. “Post-Modern Diletant” olmak  diyorum ben buna. Beyin kapasitemizin yüzde onunu bile kullanmadığımızı biliyoruz. Beyin tembeliyiz yani. Bazıları ise ancak yüzde üçünü kullanabiliyor sanırım! Yani ben öyle anlıyorum. Kullanım alanını hiç değilse ekonomik ve ergonomik olarak değerlendirelim, değil mi? 

-Haydi bas git! ...Ben de kafamı toplayayım biraz. Serseme çeviriyorsun adamı. Akıllı uslu şiir yazacak birini bulurum nasıl olsa…

-Tabii hocam, yolun açık olsun.

- Aklıma mukayyet ol Yarabbi! Ben gidiyorum. Tamam, ne halin varsa gör...

-Göreceğimden hiç kuşkun olmasın Hocam. Çekirgeler başka ne işe yarar ki? “Kuğu Gölü”nde prima dansçı olacak halim yok ya! Ulusal kanalların birinde ıtırı-vıttırı içerikli(!)  bir show programına çıkıp malı götürecek de değilim. (Her ne kadar, çokbilmişler öylesini yakıştırmışlarsa da!)   

İçinde, “Çekirgeler Ölmez” sahnesi olan bir eser yazarlarsa eğer, bil ki orada baş roldeyim! ! ! 

Sağlıcakla kal Hocam :))))   

         

                                    …………….

(*)      DİKKAT! ...Bu bir mizahi eleştiri yazısıdır. Vatandaşın ruh sağlığı açısından, fazla ciddiye alınmaması özellikle rica olunur! ...

(02 Kasım 2003)', '(Hoca ile Çekirge – 4.Bölüm)    -ÇEKİRGEEEEE! ! ! -Emret hocam!  -Ne haltlar karıştırdın yine sen?  -Af buyurunuz. Anlayamadım üstad?  -Anla...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/cekirge-azlediliyor-hoca-ile-cekirge-4-yamuk-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Düşüm Dön', 'don-dusum-don-halim-yazici-3mvzl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dün bir düş gördüm

düşüm elimde mürdüm eriği

hâyâl aldım semender sattım

kırmızı iki gün gördüm

kadınlarım kuş ölüleri

yastık altında sesler gördüm

gördüğüme inanamadım

kuşun göğsü gül ölüsü.', 'dün bir düş gördüm düşüm elimde mürdüm eriği hâyâl aldım semender sattım kırmızı iki gün gördüm kadınlarım kuş ölüleri yastık altında sesler...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/don-dusum-don-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farklı Olmalıydım', 'farkli-olmaliydim-yusuf-pangal-ljjic', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Farklı olmalıydım herkesten

Mavi olmamalıydı papuçlarım

..................................../bebekliğimde

Simsiyah kara dumanlara çalmalıydı rengi

Gömlek giymemeliydim

......................................../yaz sıcağında

...........-kazaklara bürünmeliydim-

Kaşkolumu belime dolamalıydım

......................................../kemer yerine

Sevmeliydim ama herkesten farklı

...................................-olabildiğince deli-

Olabildiğince serseri olmalıydı aşkım

Romanlara konu olmasa da

....................../ırmakları ters aktırmalıydı

Fırtınaları kendi içinde daraltıp

..................../gökyüzünü alaşağı etmeliydi

Çığlık çığlığa yarışmalıydım

............................................../kırlangıçlarla

sarp kayalıklarda bölüşmeliydim

......................................................./sevgimi

ekmeğimi,/şarabımı,/herşeyimi

Buz gibi duvarlara spreylerle yazı yazarken

.........................................................../başlamalıydı 

Polis sirenlerinden kaçarken sevişmeliydik

Saklanmalıydık

............................../surların soğukluğunda

Şiir biriktirirken

..........................''dudaklarımızın kıvılcımları''

Patlatmalıydı

........................../barut fıçısı bedenimizi

Yağmur olup yağmalıydık sonra

......................./yemyeşil mutluluk ovasına

Farklı olmalıydı herşey

Büyürken yanlış yetişmişim ben

Berduş yüreğimi saklamışım hep

İçimde çığ gibi büyüyen çılgınlığımı

..............................gizlemişler benden

...........................................yasaklamışlar

Hayâllerimi susturmuşlar

.......................................-sakıncalı- deyip

Yalnız bırakmışlar

................................../gündüzün ortasında

Öcülerden korktuğum kadar

....................................../korktuğum güneşle

Arkadaş yapmak istemişler

Okula göndermişler

............./bembeyaz sıraların üzerinde oturmaya

Konuşmaktan korktuğumu bilmeden

Efendi demişler ne kadar sessiz

....................................-ne kadar suskun-

Oysa akşamları yaşamak isterdim 

Doyasıya karanlıkla sevişmek

Doyasıya yalnız kalmak

.................../ve birde sevmek isterdim

Duvarları beraber karalayacağım birini

Düzene beraber sövüp

............................/argo ağızla

..............................''köpek öldüren'' içeceğim

Sabahlara kadar nara atıp

....................../çocukluğuna gizleneceğim birini

Yalnız kalmayı da isterdim

............................................./geceler boyu

Hiç konuşmadan

............................/yanımda sadece o

Farklı bir sevdayı yaşamak

Kara değil

...................../kapkara cinsinden olanını

Baharı değil

................./sonbaharı yaşamak isterdim

Yağmurda sırılsıklam ıslanıp 

......................-onun sıcaklığına sarılmayı-

Farklı yaşlanmalıydım 

....................-yaşlandıkça çocuklaşmalıydım-

Kırmızı fularımı boynuma dolayıp

................................./devrim türküleri söylerken

Parklarda sallanmalı

.........................yaşıtlarımla

........................../oyuncak arabalarımı yarıştırmalıydım

Bir günüm serseri

................bir günüm kırmızı ve mavili zamanların

......................................................./büyüsünde olmalıydı

Belki o zaman

...................../şiirlerim de daha güzel olurdu

Kesik kesik kalmazdı böyle

Kâfiyeleri daha düzgün

............................/mısraları daha anlaşılır

.................................../duyguları daha çekici olurdu

Ve ben

................./daha da -ben- olurdum', 'Farklı olmalıydım herkesten Mavi olmamalıydı papuçlarım ..................................../bebekliğimde Simsiyah kara dumanlara çalmalıydı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/farkli-olmaliydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
